USE JAMAJO_DDBB;


UPDATE Contenido SET id_tmdb = 653, descripcion = 'Año 1838. En la ciudad de Wisborg viven felices el joven Hutter y su mujer Ellen, hasta que el oscuro agente inmobiliario Knock decide enviar a Hutter a Transilvania para cerrar un negocio con el conde Orlok. Se trata de la venta de una finca de Wisborg, que linda con la casa de Hutter. Durante el largo viaje Hutter pernocta en una posada, donde hojea un viejo tratado sobre vampiros que encuentra en su habitación. Una vez en el castillo, es recibido por el siniestro conde. Al día siguiente, Hutter amanece con dos pequeñas marcas en el cuello, que interpreta como picaduras de mosquito. Una vez firmado el contrato, descubre que el conde es, en realidad, un vampiro. Al verle partir hacia su nuevo hogar, Hutter teme por Ellen.', trailer_url = 'https://www.youtube.com/watch?v=e_xpuux5nO0' WHERE id_api = 'tt0013442';

UPDATE Contenido SET id_tmdb = 643, descripcion = 'Basada en hechos reales ocurridos en 1905, narra como la tripulación del acorazado Príncipe Potemkin de Táurida se cansan del tratamiento vejatorio e injusto de los oficiales. El detonante de la situación es la carne podrida que éstos quieren que los marineros se coman. Con este motín comienza el reguero revolucionario por Odesa y toda Rusia.', trailer_url = 'https://www.youtube.com/watch?v=19Jh9PVIRP4' WHERE id_api = 'tt0015648';

UPDATE Contenido SET id_tmdb = 992, descripcion = 'Película sobre el mundo del cine, Keaton es un proyeccionista que sueña con ser un detective cuando, milagrosamente, se encuentra dentro de la película que está proyectando. Allí intentará salvar a su amada de las garras del villano. Una de las más aclamadas cintas de cine mudo llena de gags visuales y con un portentoso Buster Keaton.', trailer_url = 'https://www.youtube.com/watch?v=JSEK1NUPrGA' WHERE id_api = 'tt0015324';

UPDATE Contenido SET id_tmdb = 10098, descripcion = 'Una mujer londinense, sumamente pobre, se ve en la necesidad de abandonar a su hijo en una casa de millonarios, aunque por una serie de circustancias el niño terminará siendo cuidado por un vagabundo que se convierte así en su padre. Cinco años después, y con la madre convertida en una popular cantante, el destino tratará de separarlos...', trailer_url = 'https://www.youtube.com/watch?v=O5WXokyub-4' WHERE id_api = 'tt0012349';

UPDATE Contenido SET id_tmdb = 234, descripcion = 'Sentado en un banco de un parque, Francis anima a su compañero Alan para que vayan a Holstenwall, una ciudad del norte de Alemania, a ver el espectáculo ambulante del doctor Caligari. Un empleado municipal que le niega al doctor el permiso para actuar, aparece asesinado al día siguiente. Francis y Alan acuden a ver al doctor Caligari y a Cesare, su ayudante sonámbulo, que le anuncia a Alan su porvenir: vivirá hasta el amanecer.', trailer_url = 'https://www.youtube.com/watch?v=6_uvMK0dbMY' WHERE id_api = 'tt0010323';

UPDATE Contenido SET id_tmdb = 962, descripcion = 'Aventuras de un solitario buscador de oro en Alaska, donde se topa con varios personajes rudos, y se enamora de la hermosa Georgia, a la que trata de conquistar.', trailer_url = 'https://www.youtube.com/watch?v=wXrGsMrDEzA' WHERE id_api = 'tt0015864';

UPDATE Contenido SET id_tmdb = 19, descripcion = 'En una megalópolis del año 2000, los obreros están condenados a vivir recluidos en un gueto subterráneo, donde se encuentra el corazón industrial de la ciudad. Sin embargo, incitados por un robot, se rebelan contra la clase dominante y amenazan con destruir la ciudad exterior. Freder (Gustav Frölich), el hijo del soberano de Metrópolis, y María, una muchacha de origen humilde, intentarán evitar la destrucción apelando a los sentimientos y al amor.', trailer_url = 'https://www.youtube.com/watch?v=YEotzg8Q9DA' WHERE id_api = 'tt0017136';

UPDATE Contenido SET id_tmdb = 631, descripcion = 'Un granjero convive felizmente en el campo con su esposa. Pero la aparición de una seductora mujer de la ciudad hace que comience a enamorarse de ésta, y a pensar que su mujer es un estorbo que se interpone en la felicidad entre él y su nueva y sofisticada amante.', trailer_url = 'https://www.youtube.com/watch?v=PCgbFay53BA' WHERE id_api = 'tt0018455';

UPDATE Contenido SET id_tmdb = 961, descripcion = 'A pesar de querer alistarse, durante la Guerra de Secesión Johnny Gray (Buster Keaton) es destinado a la retaguardia. Todo cambia cuando un comando enemigo le roba las dos cosas que más ama: Anabelle Lee y "La General", una locomotora.', trailer_url = 'https://www.youtube.com/watch?v=eEVWb9NcSuY' WHERE id_api = 'tt0017925';

UPDATE Contenido SET id_tmdb = 780, descripcion = 'Guerra de los Cien Años (siglos XIV y XV). En 1431, Juana de Arco, después de haber conducido a las tropas francesas a la victoria, es arrestada y acusada de brujería. Ella declara haber recibido de Dios la misión de salvar a Francia, pero es procesada y condenada a morir en la hoguera.', trailer_url = 'https://www.youtube.com/watch?v=Iz3XmfNzrNs' WHERE id_api = 'tt0019254';

UPDATE Contenido SET id_tmdb = 143, descripcion = 'Mítica película antibélica que plasma los sentimientos, sensaciones y desilusiones de un grupo de jóvenes estudiantes que son enviados al frente en la Primera Guerra Mundial (1914-1918). Es una adaptación de la novela homónima del escritor alemán Erich María Remarque. Su estreno provocó enfrentamientos entre nazis y comunistas.', trailer_url = 'https://www.youtube.com/watch?v=Qeh3DlBEjAc' WHERE id_api = 'tt0020629';

UPDATE Contenido SET id_tmdb = 138, descripcion = 'El conde Drácula abandona los Cárpatos y se traslada a Londres, llevándose como sirviente a un contable. Una vez instalado, se enamora de una joven que ya está prometida. Empieza a a visitarla por las noches y va bebiendo su sangre poco a poco para convertirla así en su esposa. Pero el malestar que sufre la joven alerta a su familia, que busca la ayuda del doctor Van Helsing.', trailer_url = 'https://www.youtube.com/watch?v=M5zL-jCgvUA' WHERE id_api = 'tt0021814';

UPDATE Contenido SET id_tmdb = 901, descripcion = 'Un pobre vagabundo (Charles Chaplin) pasa mil y un avatares para conseguir dinero y ayudar a una pobre chica ciega (Virginia Cherill) de la que se ha enamorado.', trailer_url = 'https://www.youtube.com/watch?v=7vl7F8S4cpQ' WHERE id_api = 'tt0021749';

UPDATE Contenido SET id_tmdb = 3035, descripcion = 'El doctor Henry Von Frankenstein acomete un experimento tenebroso: construir, a partir de fragmentos de cadáveres, un nuevo ser humano. Con la ayuda de su criado Fritz, se adentra durante la noche en los cementerios de la localidad para arrancar a los cadáveres las partes que necesita. Lo que ignora es que el cerebro que ha utilizado en su experimento había pertenecido a un criminal.', trailer_url = 'https://www.youtube.com/watch?v=EEH5MZCewPQ' WHERE id_api = 'tt0021884';

UPDATE Contenido SET id_tmdb = 832, descripcion = 'Un asesino de niñas tiene atemorizada a toda la ciudad. La policía lo busca frenética y desesperadamente, deteniendo a cualquier persona mínimamente sospechosa. Por su parte, los jefes del hampa, furiosos por las redadas que están sufriendo por culpa del asesino, deciden buscarlo ellos mismos.', trailer_url = 'https://www.youtube.com/watch?v=nsVproWjN6c' WHERE id_api = 'tt0022100';

UPDATE Contenido SET id_tmdb = 136, descripcion = 'En un circo lleno de seres deformes, tullidos y personas con diversas amputaciones, Hans, uno de los enanos, hereda una fortuna. A partir de ese momento, Cleopatra, una bella contorsionista, intentará seducirlo para hacerse con su dinero. Para lograr su objetivo, traza un plan contando con la complicidad de Hércules, el forzudo del circo...', trailer_url = 'https://www.youtube.com/watch?v=GjzvvYX8hmk' WHERE id_api = 'tt0022913';

UPDATE Contenido SET id_tmdb = 244, descripcion = 'Un equipo de cine va a rodar una película a la misteriosa isla de Teschio, al este de Sumatra. Allí descubren la existencia de una civilización prehistórica y de una tribu ancestral que secuestra a la atractiva Ann, la actriz protagonista, para ofrecerla en sacrificio ritual a King, un gigantesco gorila.', trailer_url = 'https://www.youtube.com/watch?v=I8P7RzqOU_M' WHERE id_api = 'tt0024216';

UPDATE Contenido SET id_tmdb = 3078, descripcion = 'Peter Warren, es un periodista desempleado que se topa con Ellie, la hija de un millonario que huyó del barco de Alexander Andrews, su padre, porque no acepta al hombre con el que ella se quiere casar. Peter ve la oportunidad de conseguir una buena historia, pero varios hechos acaban por crear un vínculo entre ellos.', trailer_url = 'https://www.youtube.com/watch?v=FUAxNS_31So' WHERE id_api = 'tt0025316';

UPDATE Contenido SET id_tmdb = 260, descripcion = 'Richard Hannay está en un music-hall londinense. De repente, suena un disparo y comienza una pelea. En medio del tumulto, una chica asustada le pregunta si puede ir con él. Richard accede y la lleva a su apartamento...', trailer_url = 'https://www.youtube.com/watch?v=EjPwRiJ1Yxw' WHERE id_api = 'tt0026029';

UPDATE Contenido SET id_tmdb = 3082, descripcion = 'Extenuado por el frenético ritmo de la cadena de montaje, un obrero metalúrgico acaba perdiendo la razón. Después de recuperarse en un hospital, sale y es encarcelado por participar en una manifestación en la que se encontraba por casualidad. En la cárcel, también sin pretenderlo, ayuda a controlar un motín, gracias a lo cual queda en libertad. Una vez fuera, reemprende la lucha por la supervivencia en compañía de una joven huérfana a la que conoce en la calle.', trailer_url = 'https://www.youtube.com/watch?v=NNznUyDmSFc' WHERE id_api = 'tt0027977';

UPDATE Contenido SET id_tmdb = 900, descripcion = 'David Huxley (Cary Grant) es un paleontólogo tímido y despistado que está a punto de acabar la laboriosa reconstrucción del esqueleto de un brontosaurio, al que sólo le falta una clavícula intercostal. También está a punto de casarse con su anodina secretaria. En un partido de golf con el abogado de una solterona millonaria, potencial mecenas del museo para el que trabaja, Huxley conoce a Susan Vance (Katharine Hepburn), una joven adinerada y caprichosa que hará lo posible para que no culmine ninguno de sus dos proyectos: se dedicará a manipular a Huxley para seducirlo con un estilo muy peculiar: le abolla el coche, le desgarra el smoking, esconde su ropa, le rompe las gafas y por si fuera poco, lo embauca para que cuide a un joven leopardo llamado "Baby".', trailer_url = 'https://www.youtube.com/watch?v=efY5UmQfzyA' WHERE id_api = 'tt0029947';

UPDATE Contenido SET id_tmdb = 229, descripcion = 'Después de la huida del monstruo creado por el doctor Frankenstein, el siniestro Dr. Praetorius propone al científico la creación de una compañera para el monstruo.', trailer_url = 'https://www.youtube.com/watch?v=gJoE3AIHTjU' WHERE id_api = 'tt0026138';

UPDATE Contenido SET id_tmdb = 10907, descripcion = 'Robin de Locksey regresa a Inglaterra tras combatir contra los infieles en las Cruzadas, pero Juan sin Tierra, el hermano del Rey Ricardo I, ha usurpado el trono y gobierna como un tirano, por lo que el noble sajón decide refugiarse en el bosque de Sherwood y luchar contra él para devolverle la corona a Ricardo.', trailer_url = 'https://www.youtube.com/watch?v=bU6rh7nRDgY' WHERE id_api = 'tt0029843';

UPDATE Contenido SET id_tmdb = 940, descripcion = 'En un país centroeuropeo, el tren Transcontinental Express sufre un gran retraso a causa del mal tiempo. Los pasajeros pernoctan en un pequeño hotel, donde Iris Henderson entabla conversación con una vieja institutriz inglesa, la señora Froy. Poco después de reanudar el viaje, Iris se da cuenta de la desaparición de la anciana, pero los demás pasajeros afirman que su amiga no existe y que ella ha sufrido una alucinación.', trailer_url = 'https://www.youtube.com/watch?v=YihbNGUNQmU' WHERE id_api = 'tt0030341';

UPDATE Contenido SET id_tmdb = 3083, descripcion = 'Jefferson Smith, un joven ingenuo e idealista, que parece fácilmente manipulable, es nombrado senador. Ignora que en Washington tendrá que vérselas con políticos y empresarios sin escrúpulos que le harán perder la fe. Sin embargo, gracias a su secretaria, una joven que conoce muy bien los entresijos de la política, protagoniza en el Senado una espectacular y maratoniana intervención en la que, además de defender apasionadamente la democracia, pone en evidencia una importante trama de corrupción.', trailer_url = 'https://www.youtube.com/watch?v=bXoF7w6IWAc' WHERE id_api = 'tt0031679';

UPDATE Contenido SET id_tmdb = 995, descripcion = 'Personajes muy variopintos emprenden un largo, duro y peligroso viaje en diligencia. Entre ellos, un fuera de la ley en busca de venganza, una prostituta a la que han echado del pueblo, un jugador, un médico, la mujer embarazada de un militar y un sheriff. Las relaciones entre ellos serán difíciles y tensas. Además, durante el viaje, tendrán que afrontar el ataque de una partida de indios apaches.', trailer_url = 'https://www.youtube.com/watch?v=OE-VWDsdkwM' WHERE id_api = 'tt0031971';

UPDATE Contenido SET id_tmdb = 3085, descripcion = 'Hildy Johnson, la mejor reportera del periódico Morning Post, anuncia que va a dejar el periodismo para casarse y dedicarse a su familia y a las labores del hogar. Pero Walter Burns, el editor del periódico y ex-marido de Hildy, no puede aceptarlo, por lo que se sirve de toda clase de tretas para retenerla en el periódico y, de paso, intentar reconquistarla.', trailer_url = 'https://www.youtube.com/watch?v=yRMDR2KKugo' WHERE id_api = 'tt0032599';

UPDATE Contenido SET id_tmdb = 630, descripcion = 'La huérfana Dorothy Gale vive una vida sencilla en Kansas con su tía Emma Clara Blandick, su tío Henry y tres pintorescos peones: Hunk, Zeke y Hickory. Un día la severa vecina Miss Gulch es mordida por el perro de Dorothy, Toto. Miss Gulch se lo lleva, por orden del sheriff, a pesar de las apasionadas protestas de tía Emma y el tío Henry. Toto escapa y regresa junto a Dorothy, la cual se alegra momentáneamente, pero pronto se da cuenta de que Miss Gulch regresará. Decide llevarse a Toto y fugarse en busca de una vida mejor ''en algún lugar sobre el arco iris''.', trailer_url = 'https://www.youtube.com/watch?v=b_A2twyZevo' WHERE id_api = 'tt0032138';

UPDATE Contenido SET id_tmdb = 756, descripcion = 'Una colección de interpretaciones animadas de grandes obras de música clásica. En ''El Aprendiz de Brujo'' (P. Dukas), Mickey Mouse, discípulo de un mago, se mete en un gran embrollo, pues sus conocimientos de magia son muy limitados. ''La Consagración de la Primavera'' (Stravinsky) cuenta la historia de la evolución, desde los seres unicelulares hasta la extinción de los dinosaurios. ''La Danza de las Horas'' (Ponchielli) es un fragmento de un ballet cómico interpretado por elefantes, hipopótamos, cocodrilos y avestruces. ''Una Noche en el Monte Pelado'' de Mussorgsky y el ''Ave Maria'' de Schubert describen el enfrentamiento entre la oscuridad y la luz.', trailer_url = 'https://www.youtube.com/watch?v=eD8U083gQmY' WHERE id_api = 'tt0032455';

UPDATE Contenido SET id_tmdb = 981, descripcion = 'Historias de Filadelfia es una comedia protagonizada por Cary Grant, Katherine Hepburn y James Stewart. Tracy Lord (Katherine Hepburn) es idolatrada por todo el mundo y debe mantener a su siniestro ex-marido, un periodista alcohólico, y su futuro marido contentos.', trailer_url = 'https://www.youtube.com/watch?v=4f2jCffBrck' WHERE id_api = 'tt0032904';

UPDATE Contenido SET id_tmdb = 11360, descripcion = 'Las cigüeñas llegan, como todos los años, hasta un pintoresco circo para repartir los bebés a sus respectivas mamás. La señora Dumbo, una elefanta, descubre que su bebé tiene unas orejas enormes; todas sus compañeras se ríen de él, pero la señora Dumbo lo defiende siempre, hasta el punto de ser encerrada por enfrentarse a todo aquel que se mofe de su retoño. El pequeño Dumbo, maltratado y ridiculizado por todos sus compañeros, sólo cuenta con la ayuda de un minúsculo ratoncito llamado Timothy, que decide hacer de él una estrella del circo.', trailer_url = 'https://www.youtube.com/watch?v=sie0ataCDHg' WHERE id_api = 'tt0033563';

UPDATE Contenido SET id_tmdb = 10895, descripcion = 'Un anciano llamado Geppetto fabrica una marioneta de madera a la que llama Pinocho, con la esperanza de que se convierta en un niño de verdad. El Hada Azul hace realidad su deseo y da vida a Pinocho, pero conserva su cuerpo de madera. Pepito Grillo, la conciencia de Pinocho, tendrá que aconsejarlo para que se aleje de las situaciones difíciles o peligrosas hasta conseguir que el muñeco se convierta en un niño de carne y hueso.', trailer_url = 'https://www.youtube.com/watch?v=_xHYzf_rdGU' WHERE id_api = 'tt0032910';

UPDATE Contenido SET id_tmdb = 15, descripcion = 'Un importante financiero estadounidense, Charles Foster Kane, dueño de una importante cadena de periódicos, de una red de emisoras, de dos sindicatos y de una inimaginable colección de obras de arte, muere en su fabuloso castillo de estilo oriental, Xanadú. La última palabra que pronuncia al expirar es Rosebud. El país entero y la prensa en general quedan intrigados por saber el significado de esta palabra. Para descubrirlo, un grupo de periodistas se pone a investigar.', trailer_url = 'https://www.youtube.com/watch?v=fAcLNMkzfTE' WHERE id_api = 'tt0033467';

UPDATE Contenido SET id_tmdb = 963, descripcion = 'Un detective privado es abordado por una misteriosa mujer, que dice estar amenazada. Pero tanto el perseguidor como el hombre encargado de su protección aparecen muertos. Todo parece girar alrededor de una estatua de un halcón de valor incalculable.', trailer_url = 'https://www.youtube.com/watch?v=Yv-BPuqhW9U' WHERE id_api = 'tt0033870';

UPDATE Contenido SET id_tmdb = 11462, descripcion = 'Un atractivo vividor coincide en el tren con una joven ingenua que acabará teniendo que pagarle el billete. Más adelante, vuelven a encontrarse en una fiesta y, tras un breve romance, ella decide casarse con él, a pesar de la oposición de su padre. Considerada por todos, incluida su familia, una solterona, está empeñada en demostrarles que alguien la puede amar.', trailer_url = 'https://www.youtube.com/watch?v=gHpCbrRcBhk' WHERE id_api = 'tt0034248';

UPDATE Contenido SET id_tmdb = 3170, descripcion = 'Con los primeros rayos del sol iluminando la pradera, un nuevo príncipe ha nacido en el bosque. Tan pronto como Bambi aprende a dar sus primeros pasos, comienza a jugar con sus nuevos amigos, Tambor, el conejo juguetón, y Flor, la tímida y adorable mofeta. Pero la diversión de patinar sobre el lago helado, de mordisquear las florecillas y de juguetear entre los árboles del bosque será sólo el principio de un largo aprendizaje.', trailer_url = 'https://www.youtube.com/watch?v=-jXX-EYTAis' WHERE id_api = 'tt0034492';

