UPDATE Contenido SET id_tmdb = 1939, descripcion = 'El detective Mark McPherson investiga el asesinato de Laura, una elegante y seductora mujer que aparece muerta en su apartamento. McPherson elabora un retrato mental de la joven a partir de las declaraciones de sus allegados. El sugestivo retrato de Laura, que cuelga de la pared de su apartamento, también le ayuda en esta tarea.', trailer_url = 'https://www.youtube.com/watch?v=KgGtRJY516E' WHERE id_api = 'tt0037008';

