UPDATE Contenido SET id_tmdb = 303, descripcion = 'Tras la Segunda Guerra Mundial (1939-1945), el padre de Alicia Huberman, un espía nazi, es condenado por traición contra los Estados Unidos. Después del juicio, Alicia da una fiesta en la que aparece un apuesto desconocido llamado Devlin. Se trata de un agente de los servicios de Inteligencia que reclama su colaboración para atrapar a Alexander Sebastian, el cerebro de los nazis en Brasil. Al principio se muestra reacia, pero finalmente accede, sobre todo, porque se ha enamorado del atractivo agente americano. Una vez en Brasil, Alicia se gana la simpatía de Sebastian y se va a vivir a su casa. Pero su implicación en el asunto acaba poniendo en peligro su vida.', trailer_url = 'https://www.youtube.com/watch?v=H8f4UOtLf5Q' WHERE id_api = 'tt0038787';

