UPDATE Contenido SET id_tmdb = 5156, descripcion = 'En la Roma de la posguerra, un obrero sin empleo consigue un sencillo trabajo pegando carteles a condición de que posea una bicicleta. Obra maestra del neorrealismo italiano que forma junto con "Umberto D." y "Miracolo a Milano" la famosa trilogía de De Sica.', trailer_url = 'https://www.youtube.com/watch?v=1gngh-jQRpU' WHERE id_api = 'tt0040522';

UPDATE Contenido SET id_tmdb = 11016, descripcion = 'Frank McCloud (Humphrey Bogart) es un veterano de guerra que viaja a Cayo Largo, en Florida, para visitar al padre (Lionel Barrymore) y a la viuda (Lauren Bacall) de un compañero muerto en combate. Pero su estancia se complica, ya que en su hotel se aloja también una banda de gángsters que, aprovechando una fuerte tormenta, los toman como rehenes.', trailer_url = 'https://www.youtube.com/watch?v=oIi_ipWRxXo' WHERE id_api = 'tt0040506';

UPDATE Contenido SET id_tmdb = 1092, descripcion = 'Orson Welles es Harry Lime y Joseph Cotten actúa como su amigo de la infancia, Holly Martins, en este clásico thriller de Graham Greene, dirigido por Carol Reed. Martins busca a Lime en la caótica postguerra de Viena, y se encuentra así mismo metido en un entorno de amores, decepción y asesinatos.', trailer_url = 'https://www.youtube.com/watch?v=Y7nwySBGqCo' WHERE id_api = 'tt0041959';

UPDATE Contenido SET id_tmdb = 705, descripcion = 'Una joven que aspira a convertirse en actriz y triunfar en los escenarios se las ingenia para introducirse en un grupo de actores de teatro y hacerse amiga y confidente de una famosa y veterana actriz. El deseo de actuar y los celos la consumen hasta el punto de traicionar a sus compañeros en su escalada hacia el éxito. Ella halaga, atrae, seduce, pero también pisotea a todo el que se cruza en su camino: escritores, directores, productores. Sólo un inteligente crítico teatral adivina lo que se esconde tras su dulce apariencia, sólo él es capaz de ver a Eva al desnudo.', trailer_url = 'https://www.youtube.com/watch?v=MILphnfj2mo' WHERE id_api = 'tt0042192';

UPDATE Contenido SET id_tmdb = 11787, descripcion = 'Elwood P. Dowd (James Stewart) es un hombre afable, cariñoso y siempre dispuesto a ayudar a los demás. Su único problema es que va a todas partes acompañado por un imaginario conejo gigante al que llama Harvey. La familia de Elwood no sabe qué hacer y opta por llevarlo a un psiquiátrico.', trailer_url = 'https://www.youtube.com/watch?v=FJLsnPndIEc' WHERE id_api = 'tt0042546';

UPDATE Contenido SET id_tmdb = 548, descripcion = 'Japón, siglo XII. En Kioto, bajo las puertas del derruido templo de Rashomon, se guarecen de la torrencial lluvia un leñador, un sacerdote budista y un peregrino. Los tres discuten sobre el juicio a un bandido, acusado de haber dado muerte a un señor feudal y violado a su esposa. Los detalles del crimen son narrados desde el punto de vista del bandido, de la mujer, del señor feudal -con la ayuda de un médium- y del leñador, único testigo de los hechos.', trailer_url = 'https://www.youtube.com/watch?v=L2E_DfExUmU' WHERE id_api = 'tt0042876';

UPDATE Contenido SET id_tmdb = 488, descripcion = 'Durante la Primera Guerra Mundial, un capitán de barco con tendencia a la bebida y una estirada misionera huyen de las tropas alemanas en una ruinosa embarcación y se ven obligados a remontar un peligroso río. Son, a primera vista, dos seres antagónicos, incompatibles, pero la convivencia y, sobre todo, las penalidades que tendrán que afrontar juntos para sobrevivir harán cambiar radicalmente su relación.', trailer_url = 'https://www.youtube.com/watch?v=sFVu74-A6kI' WHERE id_api = 'tt0043265';

UPDATE Contenido SET id_tmdb = 12092, descripcion = 'Historia de magia y fantasía en el que la joven Alicia se sumerge en el sorprendente País de las Maravillas y conoce a extraordinarios personajes como Tweedledee y Tweedledum, el Sombrerero Loco, La Reina de Corazones y el frenético Conejo Blanco.', trailer_url = 'https://www.youtube.com/watch?v=JY2rHymtNvc' WHERE id_api = 'tt0043274';

UPDATE Contenido SET id_tmdb = 828, descripcion = 'El mundo entero queda conmocionado el día en que, sin previo aviso, un O.V.N.I. aterriza en Washington y de él sale Klaatu, un alienígena de aspecto humano, acompañado de Gort, un androide. Klaatu pide reunirse simultáneamente con todos los gobernantes de la Tierra, para entregarles un mensaje muy importante, pero su petición es rechazada. Klaatu se da cuenta de que necesita comprender mejor cómo viven los humanos y, para ello, se hospeda en la casa de una mujer, madre de un chico, con el que Klaatu traba amistad.', trailer_url = 'https://www.youtube.com/watch?v=sU_wBld7FPo' WHERE id_api = 'tt0043456';

UPDATE Contenido SET id_tmdb = 702, descripcion = 'Blanche, que pertenece a una rancia pero arruinada familia sureña, es una mujer madura y decadente que vive anclada en el pasado. Ciertas circunstancias la obligan a ir a vivir a Nueva Orleáns con su hermana Stella y su cuñado Stanley (Marlon Brando), un hombre rudo y violento. A pesar de su actitud remilgada y arrogante, Blanche oculta un escabroso pasado que la ha conducido al desequilibrio mental. Su inestable conducta provoca conflictos que alteran la vida de la joven pareja.', trailer_url = 'https://www.youtube.com/watch?v=U3CXLHLFvyM' WHERE id_api = 'tt0044081';

UPDATE Contenido SET id_tmdb = 3782, descripcion = 'Kanji Watanabe es un viejo funcionario público que arrastra una vida monótona y gris; sin embargo, no es consciente del vacío de su existencia hasta que le diagnostican un cáncer incurable. Con la certeza de que el fin de sus días se acerca, surge en él la necesidad de buscarle un sentido a la vida. Y cuando lo consigue se produce un cambio radical en su actitud respecto a los demás.', trailer_url = 'https://www.youtube.com/watch?v=qAPSdf8NmBQ' WHERE id_api = 'tt0044741';

UPDATE Contenido SET id_tmdb = 288, descripcion = 'Will Kane, el sheriff del pequeño pueblo de Hadleyville, acaba de contraer matrimonio con Amy. Los recién casados proyectan trasladarse a la ciudad y abrir un pequeño negocio; pero, de repente, empieza a correr por el pueblo la noticia de que Frank Miller, un criminal que Kane había atrapado y llevado ante la justicia, ha salido de la cárcel y llegará al pueblo en el tren del mediodía para vengarse de Kane. El tiempo va pasando lentamente, pero nadie en el pueblo está dispuesto a ayudar al sheriff.', trailer_url = 'https://www.youtube.com/watch?v=vFRm6xPDLFc' WHERE id_api = 'tt0044706';

