UPDATE Contenido SET id_tmdb = 632, descripcion = 'Durante la Segunda Guerra Mundial, en un campo de prisioneros alemán, unos seiscientos sargentos americanos comparten el barracón 17. En Nochebuena, dos de ellos se disponen a fugarse, pero son descubiertos y ejecutados por soldados alemanes que estaban al acecho. Los prisioneros empiezan a sospechar que en el barracón hay un traidor que informa a los nazis y llegan a la conclusión de que ese traidor es el sargento Sefton, un hombre más bien cínico y flemático, que vive bastante bien a base de canjear provisiones con los soldados alemanes', trailer_url = 'https://www.youtube.com/watch?v=nPT7bzA5Nis' WHERE id_api = 'tt0046359';

UPDATE Contenido SET id_tmdb = 18148, descripcion = 'Una pareja de ancianos viaja a Tokio para visitar a sus hijos, pero ninguno de ellos tiene tiempo para atenderlos, por lo que deciden enviarlos a un balneario. Cuando regresan, la madre pasa una noche en la casa de una nuera, viuda de uno de sus hijos. A diferencia de sus cuñados, Noriko muestra afecto por sus suegros y conforta a la anciana.', trailer_url = 'https://www.youtube.com/watch?v=xqO0d3328Do' WHERE id_api = 'tt0046438';

