UPDATE Contenido SET id_tmdb = 654, descripcion = 'El exboxeador Terry Malloy podría haber sido un serio aspirante al título, pero se ve obligado a ganarse la vida trabajando para Johnny Friendly, el jefe de la conflictiva banda de gánsteres de la ciudad. Cuando dos de los matones de Friendly asesinan brutalmente a un hombre, Terry comienza a sentirse culpable con la vida que lleva, iniciando una peligrosa lucha para derrocar el imperio del hampa', trailer_url = 'https://www.youtube.com/watch?v=boekTHsOIY8' WHERE id_api = 'tt0047296';

