UPDATE Contenido SET id_tmdb = 346, descripcion = 'Una banda de forajidos atemorizan a los habitantes de un pequeño pueblo, saqueándolos periódicamente sin piedad. Para repeler estos ataques, los aldeanos deciden contratar a mercenarios. Finalmente, consiguen los servicios de 7 guerreros, 7 samurais dispuestos a defenderlos a cambio, tan solo, de cobijo y comida.', trailer_url = 'https://www.youtube.com/watch?v=RsRN65PlaIM' WHERE id_api = 'tt0047478';

UPDATE Contenido SET id_tmdb = 10653, descripcion = 'Como miles de neoyorkinos, Richard Sherman se ha quedado trabajando en agosto mientras su mujer e hijos disfrutan de unas gratas vacaciones en la playa. Siguiendo las recomendaciones de su esposa, está dispuesto a dejar de fumar, de beber, a acostarse pronto y sobre todo a no echar una cana al aire. Pero la tentación aparece cuando conoce a una despampanante vecina, tan sexy como ingenua.', trailer_url = 'https://www.youtube.com/watch?v=1xeS5W-3n1o' WHERE id_api = 'tt0048605';

UPDATE Contenido SET id_tmdb = 13368, descripcion = 'Bob y Phil son dos tipos que acaban de volver de la Segunda Guerra Mundial. Consumados cantantes y bailarines, deciden ganarse la vida haciendo números musicales. Así conocen a una pareja de hermanas dedicadas a lo mismo. Siguiéndolas, van a parar a Vermont, a un hotel que tiene graves problemas financieros. El administrador del hotel resulta ser el antiguo jefe de los muchachos en el ejército y sus líos económicos son urgentes. Tanto como para que Bob y Phil decidan ayudarlo como mejor saben.', trailer_url = 'https://www.youtube.com/watch?v=3n3-UtakD3I' WHERE id_api = 'tt0047673';

UPDATE Contenido SET id_tmdb = 220, descripcion = 'Un granjero californiano tiene dos hijos, Cal y Aron, de caracteres muy diferentes, pero ambos compiten por el cariño de su padre. La situación de Cal se complica cuando averigua que, en realidad, su madre no sólo no está muerta, sino que además regenta un local de alterne.', trailer_url = 'https://www.youtube.com/watch?v=Yi_wwgJOEwk' WHERE id_api = 'tt0048028';

UPDATE Contenido SET id_tmdb = 10340, descripcion = 'Reina es una preciosa perrita de pura raza que vive feliz en su hogar. Jaimito y Linda, la miman mucho y ella corresponde feliz a sus cuidados. Sin embargo, el día en que sus dueños deciden hacer un viaje, la vida de Reina se ve alterada; la llegada de la tía Sara con sus gatos no provoca más que sobresaltos. Menos mal que conoce a Golfo, un perro vagabundo muy simpático', trailer_url = 'https://www.youtube.com/watch?v=SAoLpLXvGN0' WHERE id_api = 'tt0048280';

UPDATE Contenido SET id_tmdb = 381, descripcion = 'A pesar de que John Robie ''El Gato'' es un ladrón de joyas reformado, se convierte en el principal sospechoso de una serie de robos de piedras preciosas en los más lujosos hoteles de la Riviera francesa, así que no tendrá más remedio que demostrar su inocencia. Cuando conoce a la caprichosa heredera Frances, ve la oportunidad de desenmascarar al misterioso ladrón utilizando como señuelo las fabulosas joyas de la madre de la joven.', trailer_url = 'https://www.youtube.com/watch?v=YIc5SDKEC6g' WHERE id_api = 'tt0048728';

UPDATE Contenido SET id_tmdb = 830, descripcion = 'Reconocido como uno de los clásicos de la ciencia-ficcion adulta, Forbidden Planet es una de las grandes películas realizadas durante la década de los cincuenta, junto con otras como La invasión de los ladrones de cuerpos (Invasion of the body snatchers, 1956), El increíble hombre menguante (The incredible shrinking man, 1957), y Ultimátum a la Tierra (The day the earth stood still, 1951). Pero su importancia va mas allá, pues Planeta Prohibido también representa un germen sobre el cual mucha de la ciencia-ficción para la pantalla grande y pequeña se iba a desarrollar a partir de la década de los sesenta. No es difícil ver en los tripulantes de la nave espacial los futuros antecesores de los tripulantes del Enterprise en Star Trek y en el robot a un ancestro de C3PO. También fue innovadora en su banda sonora, ya que fue la primera película con banda sonora totalmente electrónica, sintetizada con circuitos electrónicos creados ex-profeso, aunque es música ambiental y no sinfónica.', trailer_url = 'https://www.youtube.com/watch?v=dU8g84K2M3Q' WHERE id_api = 'tt0049223';

UPDATE Contenido SET id_tmdb = 11549, descripcion = 'En una pequeña ciudad de California empiezan a suceder cosas muy extrañas: el comportamiento de algunas personas cambia de tal manera que causa estupor e incluso miedo entre sus parientes y amigos.', trailer_url = 'https://www.youtube.com/watch?v=9SqN8wHry2M' WHERE id_api = 'tt0049366';

UPDATE Contenido SET id_tmdb = 247, descripcion = 'Después de pasar por la cárcel, Johnny Clay ha decidido dar el último golpe de su vida, el que le permita retirarse junto a su amada Fay. El plan es llevarse la recaudación de las carreras de caballos de un hipódromo. Después de una meticulosa selección de colaboradores, planea la estrategia del asalto con una precisión insospechada. Tratará de provocar un altercado en la sala de apuestas y matar al caballo favorito de la séptima carrera. Clay cuenta con la ayuda de Randy, un policía sobornado, George, el cajero de las apuestas, y Mike, barman del hipódromo. El atraco se desarrolla según lo previsto, pero los problemas se presentan con el reparto del botín.', trailer_url = 'https://www.youtube.com/watch?v=c0Odg-GY40w' WHERE id_api = 'tt0049406';

UPDATE Contenido SET id_tmdb = 574, descripcion = 'Una familia americana, compuesta por el doctor Ben MacKenna, su mujer y su hijo Hank, está pasando unas vacaciones en Marruecos. Tras la muerte de un espía en brazos de Ben, mientras visitaban el mercado de Marrakech, el matrimonio descubre que su hijo ha sido secuestrado. Sin saber en quién confiar, los MacKenna se ven envueltos en una angustiosa pesadilla que tiene que ver con una operación de espionaje internacional.', trailer_url = 'https://www.youtube.com/watch?v=YP8brOVQnKA' WHERE id_api = 'tt0049470';

