UPDATE Contenido SET id_tmdb = 3777, descripcion = 'Japón feudal, siglo XVI. Adaptación del "Macbeth" de William Shakespeare. Cuando los generales Taketori Washizu y Yoshaki Miki regresan de una victoriosa batalla, se encuentran en el camino con una extraña anciana, que profetiza que Washizu llegará a ser el señor del Castillo del Norte. A partir de ese momento, su esposa lo instigará hasta convencerlo de que debe cumplir su destino.', trailer_url = 'https://www.youtube.com/watch?v=oa0CcrHB4rc' WHERE id_api = 'tt0050613';

UPDATE Contenido SET id_tmdb = 19426, descripcion = 'Cabiria es una prostituta que ejerce como tal en uno de los barrios más pobres de Roma. Sueña, sin embargo, con encontrar el amor verdadero, un hombre que la aparte de la calle y a quien pueda entregarse en cuerpo y alma. Su bondad y su ingenuidad la convierten en víctima propicia de sucesivos vividores que se aprovechan de ella, le roban y la golpean. A pesar de sus fracasos, recobra la esperanza una y otra vez. Todo parece cambiar cuando abre su corazón a un tímido contable que le propone matrimonio.', trailer_url = 'https://www.youtube.com/watch?v=nG91owD7UjM' WHERE id_api = 'tt0050783';

UPDATE Contenido SET id_tmdb = 975, descripcion = 'Primera Guerra Mundial (1914-1918). En 1916, en Francia, el general Boulard ordena la conquista de una inexpugnable posición alemana y encarga esa misión al ambicioso general Mireau. El encargado de dirigir el ataque será el coronel Dax. La toma de la colina resulta un infierno, y el regimiento emprende la retirada hacia las trincheras. El alto mando militar, irritado por la derrota, decide imponer al regimiento un terrible castigo que sirva de ejemplo a los demás soldados.', trailer_url = 'https://www.youtube.com/watch?v=FESvZ0HG2p4' WHERE id_api = 'tt0050825';

UPDATE Contenido SET id_tmdb = 614, descripcion = 'El profesor Borg, un eminente físico, debe ir a Estocolmo para recibir un homenaje de su universidad. Sobrecogido, tras un sueño en el que contempla su propio cadáver, decide emprender el viaje en coche con su nuera, que acaba de abandonar su casa, tras una discusión con su marido, que se niega a tener hijos. Durante el viaje se detiene en la casa donde pasaba las vacaciones cuando era niño, un lugar donde crecen las fresas salvajes y donde vivió su primer amor.', trailer_url = 'https://www.youtube.com/watch?v=EwMgTyVbCS0' WHERE id_api = 'tt0050986';

UPDATE Contenido SET id_tmdb = 261, descripcion = 'La inminente muerte del anciano patriarca de una acomodada familia del Sur desencadena terribles tensiones entre sus herederos. Uno de sus hijos, Brick, indeciso y apático, se refugia en el alcohol y se muestra completamente indiferente ante la situación, pero Maggie, su mujer, no está dispuesta a contemplar impasible su destrucción. El otro, Gooper, al igual que su esposa, es ambicioso y oportunista.', trailer_url = 'https://www.youtube.com/watch?v=SGvJZLJi9sU' WHERE id_api = 'tt0051459';

