UPDATE Contenido SET id_tmdb = 11901, descripcion = 'En 1870 un Forastero pasa a caballo ante la tumba de un antiguo Sheriff, Jim Duncan, en la ciudad fronteriza de Lago en el Sudoeste de Estados Unidos. Los propietarios de la compañía minera de Lago, Dave Drake y Morgan Allen obtienen el apoyo de los vecinos de la pequeña ciudad para contratar al Forastero. Debe proteger a la comunidad contra tres pistoleros, cuya llegada se hace inminente al haber sido liberados tras cumplir condena por acusaciones falsas de la compañía minera Drake-Allen. El Forastero acepta el contrato a condición de llevarlo a cabo con los tres forajidos y, entre otras cosas, pide que pinten el pueblo entero de color rojo vivo y que le cambien el nombre y pasa a llamarse "Infierno".', trailer_url = 'https://www.youtube.com/watch?v=be2mIVxDrr8' WHERE id_api = 'tt0068699';

