UPDATE Contenido SET id_tmdb = 12101, descripcion = 'En el año 2022, la población de Nueva York, unos cuarenta millones de habitantes, vive en condiciones miserables. Para combatir el hambre se crea un alimento sintético, el soylent green, pero el policía Thorn y el viejo Roth, un superviviente de otra época, sospechan que detrás del nuevo alimento hay algo inquietante.', trailer_url = 'https://www.youtube.com/watch?v=N_jGOKYHxaQ' WHERE id_api = 'tt0070723';

UPDATE Contenido SET id_tmdb = 2362, descripcion = 'En un futuro próximo existe un gigantesco parque de vacaciones dividido en tres zonas: la Roma Imperial, el Oeste americano y la Europa Medieval. Cada una de ellas reproduce con total fidelidad las características de cada época. Existe, además, la posibilidad de que quien pueda permitírse el lujo viva sus propias aventuras en la época elegida. Al parque han ido de vacaciones un par de amigos, Peter Martin (Richard Benjamin) y John Blane (James Brolin). Todo está perfectamente controlado hasta que los robots que hacen de figurantes empiezan a fallar, en concreto un implacable pistolero (Yul Brynner) diseñado para perseguir sin descanso a sus víctimas.', trailer_url = 'https://www.youtube.com/watch?v=_vezkZIMm74' WHERE id_api = 'tt0070909';

UPDATE Contenido SET id_tmdb = 16307, descripcion = 'Una carta que hace sospechar que una joven desaparecida ha sido asesinada lleva al sargento Howie de Scotland Yard hasta Summerisle, una isla en la costa de Inglaterra. Allí el inspector se entera de que hay una especie de culto pagano, y conoce a Lord Summerisle, el líder religioso de la isla.', trailer_url = 'https://www.youtube.com/watch?v=MXq-NuS24fg' WHERE id_api = 'tt0070917';

UPDATE Contenido SET id_tmdb = 7857, descripcion = 'Historia de un hombre que un día se da cuenta de que apenas reconoce a las personas con las que ha vivido durante años, hasta el punto de que su propia esposa e hijos le parecen extraños y todo lo que lo rodea le resulta opaco e indiferente. Se lanza entonces a la búsqueda desesperada de algún punto de referencia para recuperar su identidad y no hundirse en el caos. Emprende así, a través de las ilimitadas regiones de la memoria, un viaje que lo conduce a la infancia, a la época en que era un niño que vivía en un pequeño pueblo costero; a la Italia de los años treinta, cuando el fascismo había alcanzado el punto culminante de su apogeo.', trailer_url = 'https://www.youtube.com/watch?v=BtG9ZM-ZHnY' WHERE id_api = 'tt0071129';

UPDATE Contenido SET id_tmdb = 592, descripcion = 'Harry Paul, un detective cuyo prestigio como especialista en vigilancia y en sistemas de seguridad es reconocido por sus colegas en todo el país, recibe el encargo por parte de un magnate de investigar a su joven esposa. Deberá escuchar sus conversaciones con un empleado del marido, del que ella parece estar enamorada. La misión, para un experto de su categoría, resulta a primera vista inexplicable, ya que la pareja no ofrece ningún interés fuera de lo corriente. Sin embargo, cuando Harry da por finalizado su trabajo, advierte que algo extraño se oculta tras la banalidad que ha estado investigando, ya que su cliente se niega a identificarse, utilizando siempre intermediarios.', trailer_url = 'https://www.youtube.com/watch?v=9XGovTqAF60' WHERE id_api = 'tt0071360';

