UPDATE Contenido SET id_tmdb = 1396, descripcion = 'Un hombre, Alekséi, habla con su esposa sobre su situación actual y los motivos por los que se han distanciado. La película es una evocación continua de recuerdos y sentimientos que viajan en diferentes tiempos sin orden aparente: la relación con su madre, su infancia,...que se mezclan con material fílmico de noticiario sobre la Guerra civil española, la Segunda guerra mundial y el enfrentamiento entre la URSS y China por la isla Damanski. En la película suenan poemas escritos y recitados por Arseni Tarkovski, padre del director. Retrata un pasado que es el suyo, pero también el de un país y el del acontecer mundial.', trailer_url = 'https://www.youtube.com/watch?v=S2U9TXmYJ94' WHERE id_api = 'tt0072443';

UPDATE Contenido SET id_tmdb = 578, descripcion = 'En la costa de un pequeño pueblo del Este de Estados Unidos, un enorme tiburón ataca a varias personas. Temiendo las fatales consecuencias que esto puede provocar en el negocio turístico, el alcalde se niega a cerrar las playas y a difundir la noticia. Pero un nuevo ataque del tiburón, en la propia playa, termina con la vida de otro bañista. El terror se ha hecho público, así que un veterano cazador de tiburones, un científico y el jefe de la policía local se unen para dar caza al temible escualo...', trailer_url = 'https://www.youtube.com/watch?v=IBgwS4JedEw' WHERE id_api = 'tt0073195';

