UPDATE Contenido SET id_tmdb = 2207, descripcion = 'Serie de TV (1975 y 1979). 12 episodios. Los Fawlty son un matrimonio  que regenta un pequeño hotel en la costa de Inglaterra. Él es maniático y  deslenguado; ella exigente, mandona y con un irónico sentido del humor.  En el servicio nos encontramos con Manuel, un camarero español  (italiano en la versión doblada en España) que no sabe hablar inglés y  con Polly, la asistenta que siempre está sacando al jefe de apuros. Ante  semejante elenco, los clientes del hotel lo tendrán complicado para  pasar unas buenas vacaciones.', trailer_url = 'https://www.youtube.com/watch?v=KluNYgZsDLo' WHERE id_api = 'tt0072500';

