UPDATE Contenido SET id_tmdb = 6037, descripcion = 'El excéntrico multimillonario Lionel Twain invita a cenar a su castillo a los cinco detectives más importantes de la historia: el chino Sidney Wang, el neoyorquino Dick Charleston, la inglesa Jessica Marbles, el belga Milo Perrier y Sam Diamond, residente en San Francisco. Después de ser recibidos por un mayordomo ciego, Twain les explica durante la cena el motivo de la reunión: a medianoche se producirá un asesinato y el que sea capaz de resolverlo se llevará un millón de dólares.', trailer_url = 'https://www.youtube.com/watch?v=zKdmSdUrsCg' WHERE id_api = 'tt0074937';

UPDATE Contenido SET id_tmdb = 26842, descripcion = 'Siglo VII. Férreamente determinado a acabar con las injusticias de los líderes de la Meca, Mohammad, que afirma haber tenido una visión del ángel Gabriel, les persuade para que abandonen la adoración de los 300 ídolos de Kaaba en favor de uno sólo. Además de desoir sus ruegos, las reuniones de Mohammad y sus partidarios son respondidos con persecuciones y crueles torturas. Su expulsión de la Meca desencadena la sed de justicia de éstos hasta que Mohammad accede a tomar las armas y luchar para instaurar el monoteísmo.', trailer_url = 'https://www.youtube.com/watch?v=gCyWycOx3nI' WHERE id_api = 'tt0074896';

UPDATE Contenido SET id_tmdb = 10774, descripcion = 'Tras 25 años trabajando en una cadena, el veterano presentador Howard Beale debe abandonar su puesto por el bajo nivel de audiencia. Su jefe y mejor amigo, Max Schumacher, le da dos semanas para despedirse de los espectadores. Beale, viudo y alcohólico, queda trastocado y decide anunciar durante una emisión que se suicidará en su último programa ante las cámaras. El hecho sin precedentes provoca una gran expectación y los propios compañeros tratarán de convertir la destrucción de este hombre en un negocio rentable.', trailer_url = 'https://www.youtube.com/watch?v=T-PyQ1gMT6o' WHERE id_api = 'tt0074958';

UPDATE Contenido SET id_tmdb = 10747, descripcion = 'A punto de finalizar la Guerra de Secesión, un grupo de unionistas, liderados por el sádico capitán Terrill, asesina a la familia de un granjero llamado Joseph Wales. Movido por el odio y el deseo de venganza, se une a un grupo de rebeldes. Poco después, finaliza la contienda, el ejército de la Unión ofrece la amnistía a todas las guerrillas y sus compañeros aceptan. La rabia y el dolor siguen vivos dentro de Wales, y no se rendirá tan fácilmente.', trailer_url = 'https://www.youtube.com/watch?v=YvXl6Ij-LhQ' WHERE id_api = 'tt0075029';

UPDATE Contenido SET id_tmdb = 1366, descripcion = 'Rocky Balboa es un desconocido boxeador a quien se le ofrece la posibilidad de pelear por el título mundial de los pesos pesados. Con mucha fuerza de voluntad, Rocky se preparará concienzudamente para este combate, y también para los cambios que producirá en su vida.', trailer_url = 'https://www.youtube.com/watch?v=yTqsJT1mFng' WHERE id_api = 'tt0075148';

UPDATE Contenido SET id_tmdb = 103, descripcion = 'Para sobrellevar el insomnio crónico que sufre después de su regreso de Vietnam, Travis decide trabajar como taxista nocturno. Como individuo tiene poco contacto con la gente, pero observa la violencia y desolación en la que se hunde la ciudad de Nueva York. Travis anota en su diario todas sus impresiones, hasta que un día decide pasar a la acción.', trailer_url = 'https://www.youtube.com/watch?v=XQljOh9p6P8' WHERE id_api = 'tt0075314';

UPDATE Contenido SET id_tmdb = 11009, descripcion = 'En Nueva York, después de trabajar toda la semana en una tienda de pinturas de Brooklyn, Tony Manero (John Travolta) se prepara esmeradamente para disfrutar de la noche del sábado: se empapa en colonia Brut, se pone una camisa de flores ajustada, pantalones de tela de gabardina y zapatos de plataforma. En la discoteca de moda, Tony deslumbrará a todos con lo que mejor sabe hacer: bailar.', trailer_url = 'https://www.youtube.com/watch?v=Ze5KdovxqUQ' WHERE id_api = 'tt0076666';

UPDATE Contenido SET id_tmdb = 840, descripcion = 'Una noche, cerca de su casa, en Indiana, Roy Neary (Richard Dreyfuss) observa en el cielo unos misteriosos objetos voladores. Obsesionado por comprender lo que ha visto, se distancia de su esposa (Teri Garr). Neary encuentra apoyo en Jillian Guiler (Melinda Dillon), que también fue testigo de esas visiones nocturnas. Juntos buscan una respuesta a ese misterio que ha alterado sus vidas. Al mismo tiempo, un nutrido grupo de científicos internacionales, bajo la dirección de Claude Lacombe (François Truffaut), empieza a investigar las apariciones de OVNIS y otros extraños fenómenos.', trailer_url = 'https://www.youtube.com/watch?v=dSpQ3G08k48' WHERE id_api = 'tt0075860';

UPDATE Contenido SET id_tmdb = 11319, descripcion = 'Una niña huérfana que ha sido secuestrada envía una nota dentro de una botella pidiendo ayuda. Bernardo y Bianca, dos valientes ratones, miembros de la Sociedad Internacional de Rescate, reciben el mensaje que los llevará al peligroso "Pantano del Diablo". Allí, ayudados por la libélula Evinrude y los habitantes del pantano, vivirán un sinfín de emocionantes aventuras luchando contra la malvada Madame Medusa', trailer_url = 'https://www.youtube.com/watch?v=bz4vILhWO18' WHERE id_api = 'tt0076618';

UPDATE Contenido SET id_tmdb = 11590, descripcion = 'Un veterano jugador que entrena a un equipo de hockey sobre hielo (Newman) ve cómo las derrotas se suceden hasta que decide aplicar la más brutal de las tácticas: aconseja a sus jugadores que jueguen como verdaderos animales durante los partidos, sin importar si la violencia que emplean es o no legal. Divertida y muy bien interpretada, fue duramente criticada en su estreno por su violento -y extremadamente liberal- mensaje.', trailer_url = 'https://www.youtube.com/watch?v=vW67agGgWAM' WHERE id_api = 'tt0076723';

