UPDATE Contenido SET id_tmdb = 11006, descripcion = 'Bandit, el camionero rey de la carretera, se enfrenta a todo un reto, recoger un camión de cerveza en Texarkana, el lugar más cercano donde se puede vender legalmente esa bebida, y conducirlo a través del país hasta Atlanta en solo 48 horas. ¿La recompensa? ¡80.000 dólares! ¿El resultado? La persecución y los accidentes de coches más salvajes jamás vistos. ¿El motivo? Un sheriff de Texas, Buford T. Justice alias "Smokey", obsesionado con capturar al escurridizo Bandit, desde que la novia de su hijo lo abandonara por el rey de la carretera.', trailer_url = 'https://www.youtube.com/watch?v=3U7j296Nxcs' WHERE id_api = 'tt0076729';

UPDATE Contenido SET id_tmdb = 11906, descripcion = 'Una joven (Jessica Harper) ingresa en una exclusiva academia de baile la misma noche en que asesinan a una de las alumnas. La subdirectora del centro es la amable Madame Blank, que brinda a la nueva alumna las comodidades y facilidades necesarias para su aprendizaje. Pero, poco a poco, una atmósfera malsana se va apoderando del lugar, y la estancia de la joven se va convirtiendo en una verdadera pesadilla.', trailer_url = 'https://www.youtube.com/watch?v=x_FfT98QJks' WHERE id_api = 'tt0076786';

UPDATE Contenido SET id_tmdb = 16642, descripcion = 'Bill y Abby, una joven pareja, deciden abandonar la pobreza y la dura vida que llevan en el Chicago de 1916. Los dos y Linda, la hermana de Bill, viajan hacia las grandes campos de trigo de Texas, donde encuentran trabajo como braceros en una granja. Recogida la cosecha, el joven y apuesto patrón, al que hacen creer que los tres son hermanos, les pide que se queden porque se ha enamorado de Abby.', trailer_url = 'https://www.youtube.com/watch?v=7LAqRFoT97o' WHERE id_api = 'tt0077405';

UPDATE Contenido SET id_tmdb = 621, descripcion = 'Sandy y Danny han pasado un romántico y maravilloso verano juntos, pero las vacaciones se acabaron y sus caminos se separaron. Al regresar al instituto Rydell, ambos vuelven a encontrarse de manera sorpresiva, pero el problema es que la imagen y actitud de Danny no es la misma que durante el verano: ya no es el encantador y atento chico que encandiló a Sandy, sino alguien engreído e insensible que sólo quiere presumir de duro delante de sus amigos.', trailer_url = 'https://www.youtube.com/watch?v=THd96gHV7Tg' WHERE id_api = 'tt0077631';

UPDATE Contenido SET id_tmdb = 948, descripcion = 'Durante la noche de Halloween, Michael, un niño de seis años, asesina a su familia con un cuchillo de cocina. Es internado en un psiquiátrico del que huye quince años más tarde, precisamente la víspera de Halloween. El psicópata vuelve a su pueblo y comete una serie de asesinatos. Mientras, uno de los médicos del psiquiátrico le sigue la pista.', trailer_url = 'https://www.youtube.com/watch?v=NT0loXUv-ks' WHERE id_api = 'tt0077651';

UPDATE Contenido SET id_tmdb = 11850, descripcion = 'Hace unos días que Elizabeth Driscoll (Brooke Adams) nota algo raro en el comportamiento de su novio, el doctor Geoffrey Howell (Art Hindle). La chica lo comenta con algunos de sus compañeros de trabajo pero no le hacen mucho caso, hasta que descubren a un clon del doctor Howell vagando por el hospital. De inmediato intentan avisar a Elizabeth, pero ya es demasiado tarde: la invasión de los ultracuerpos ha comenzado y ella encuentra una réplica de sí misma en su propio apartamento.', trailer_url = 'https://www.youtube.com/watch?v=e_brmjvATLc' WHERE id_api = 'tt0077745';

UPDATE Contenido SET id_tmdb = 579, descripcion = 'Han pasado cuatro años desde que aquel gran tiburón blanco aterrorizara al pequeño pueblo costero de Amity. El jefe de policía Brody sigue preocupado, a pesar de que hay en marcha varios proyectos para reavivar el interés turístico de las playas. El alcalde Larry Vaughn da la bienvenida al inversor Len Peterson y su equipo al pueblo. Dos submarinistas exploran la zona donde apareció el peligroso escualo en el pasado, y son devorados por otro enorme tiburón no sin antes obtener uno de ellos una foto del ojo del monstruo. La desaparición de los dos buceadores alerta a Brody, ya que es verano y los turistas llegan por centenares hasta Amity. Mientras tanto, un grupo de adolescentes entre los que se encuentra Mike y Sean, los hijos del policía, hacen una excursión hasta una península cercana...', trailer_url = 'https://www.youtube.com/watch?v=2-KIByGsyaI' WHERE id_api = 'tt0077766';

UPDATE Contenido SET id_tmdb = 1924, descripcion = 'Desde una galaxia remota, un recién nacido es enviado por sus padres al espacio debido a la inminente destrucción del planeta donde viven. La nave aterriza en la Tierra, y el niño es adoptado por unos granjeros que le inculcan los mejores valores humanos. Con los años el joven se irá a Metrópolis y allí usará sus poderes sobrenaturales para luchar contra el mal.', trailer_url = 'https://www.youtube.com/watch?v=vfC6XFYFbyA' WHERE id_api = 'tt0078346';

UPDATE Contenido SET id_tmdb = 8469, descripcion = 'El Faber College es una Universidad privada de EE.UU, fundada a finales del siglo pasado por Emil Faber. Sin embargo, posee algunas características que la hacen diferente del resto, por su carácter especialmente clasista. Existen en su organización dos partes: la Casa Omega está integrada por estudiantes serios y estirados; los de la Casa Delta son todo lo contrario... Comedia que obtuvo un enorme éxito de taquilla en Estados Unidos; de hecho se mantuvo durante décadas como una de las películas más taquilleras.', trailer_url = 'https://www.youtube.com/watch?v=-mSQag4Re4Y' WHERE id_api = 'tt0077975';

UPDATE Contenido SET id_tmdb = 28, descripcion = 'Durante la guerra de Vietnam, al joven Capitán Willard, un oficial de los servicios de inteligencia del ejército estadounidense, se le ha encomendado entrar en Camboya con la peligrosa misión de eliminar a Kurtz, un coronel renegado que se ha vuelto loco. El capitán deberá ir navegar por el río hasta el corazón de la selva, donde parece ser que Kurtz reina como un buda despótico sobre los miembros de la tribu Montagnard, que le adoran como a un dios.', trailer_url = 'https://www.youtube.com/watch?v=h5iZf5kv354' WHERE id_api = 'tt0078788';

UPDATE Contenido SET id_tmdb = 17443, descripcion = 'Un abogado debe defender a un juez corrupto acusado de violación. Se trata de un magistrado con el que tuvo serios problemas profesionales, pues en una ocasión se negó a admitir, por pequeñas formalidades, pruebas irrefutables que demostraban la inocencia de uno de sus clientes.', trailer_url = 'https://www.youtube.com/watch?v=m6-tlGGKYcI' WHERE id_api = 'tt0078718';

