UPDATE Contenido SET id_tmdb = 10322, descripcion = 'Chance es un hombre peculiar. Su vida se reduce a cuidar el jardín de la mansión de un hombre adinerado y a ver la televisión el resto del día. Pero, cuando el dueño de la casa muere y Chance es despedido, no está preparado para hacer frente al mundo exterior. Tiene, sin embargo, la suerte de conocer a Eve, una buena mujer que lo acoge en su casa. Lo paradójico es que, poco a poco, este hombre analfabeto conseguirá engañar a muchos haciéndoles creer que es un gran político.', trailer_url = 'https://www.youtube.com/watch?v=oOOghKacg40' WHERE id_api = 'tt0078841';

