UPDATE Contenido SET id_tmdb = 15764, descripcion = 'Verano de 1947. Stingo, un joven aspirante a escritor, se instala en El Palacio Rosa, una pensión familiar de Brooklyn, con la intención de escribir una novela. Sin embargo, su tranquilidad se verá pronto turbada por la terrible discusión de una pareja que vive en el piso de arriba. Cuando conoce a los amantes queda cautivado por su encanto y simpatía. Ella, Sophie Zawistowska, es una hermosa emigrante polaca y católica. Él, Nathan Landau, es un brillante, encantador y desequilibrado científico judío. Poco a poco, Stingo se convierte en su mejor amigo. Sophie, hija de un ilustre profesor polaco, sobrevivió al campo de exterminio de Auschwitz, pero vive atormentada por su pasado.', trailer_url = 'https://www.youtube.com/watch?v=STPJVf6wqCk' WHERE id_api = 'tt0084707';

UPDATE Contenido SET id_tmdb = 1091, descripcion = 'En una estación experimental de la Antártida, un equipo de investigadores descubre a un ente extraño venido del espacio, que según todos los indicios ha permanecido enterrado en la nieve durante más de 100.000 años. Al descongelarse, experimenta una metamorfosis sorprendente...', trailer_url = 'https://www.youtube.com/watch?v=ySvzHdtCiWE' WHERE id_api = 'tt0084787';

UPDATE Contenido SET id_tmdb = 9576, descripcion = 'Michael Dorsey es un actor neoyorkino sin éxito. Además, en los círculos artísticos tiene fama de conflictivo. Como su mala racha no se acaba, un día toma una importante decisión: hacerse pasar por una mujer para encontrar trabajo. Consigue un papel, pero su nueva identidad le traerá no pocas complicaciones en su vida diaria.', trailer_url = 'https://www.youtube.com/watch?v=IS-rkKwfuJU' WHERE id_api = 'tt0084805';

UPDATE Contenido SET id_tmdb = 24226, descripcion = 'Un abogado que ha tenido una carrera profesional llena de fracasos contempla la posibilidad de rehabilitarse mediante un fácil caso de éxito. Se trata de un juicio promovido por la familia de una mujer que ha sido sometida a una intervención quirúrgica sin aparente peligro en un famoso hospital. El resultado de la operación ha sido que ella está clínicamente muerta.  De cualquier forma, el caso no es tan fácil como en un principio parece, ya que la clínica ha contratado a los abogados de mayor prestigio dentro del ámbito judicial.', trailer_url = 'https://www.youtube.com/watch?v=wwqUtCeODOk' WHERE id_api = 'tt0084855';

UPDATE Contenido SET id_tmdb = 12560, descripcion = 'Ocho viejos amigos, compañeros de universidad en la década de los sesenta, vuelven a reunirse un fin de semana con motivo del entierro de uno de los miembros del grupo. El fallecido era un médico brillante que rehusó integrarse en el sistema y que, tras quince años de vagabundeo, acabó por suicidarse en la elegante mansión de uno de sus amigos.', trailer_url = 'https://www.youtube.com/watch?v=hHUwAZdQFBg' WHERE id_api = 'tt0085244';

UPDATE Contenido SET id_tmdb = 10489, descripcion = 'En una pequeña población norteamericana, un murciélago muerde a un entrañable perro San Bernardo y le contagia la rabia. A medida que avanza la enfermedad, el perro se vuelve más agresivo hasta llegar a aterrorizar a todo el vecindario.', trailer_url = 'https://www.youtube.com/watch?v=vFUD8b-BZCc' WHERE id_api = 'tt0085382';

UPDATE Contenido SET id_tmdb = 11336, descripcion = 'Adaptación de la novela escrita por Stephen King.  Un joven profesor sufre un accidente que le hará permanecer cinco años en coma. Al despertar, descubre que posee poderes extrasensoriales y que es capaz de adivinar el futuro. La policía pedirá su colaboración para resolver un asesinato...', trailer_url = 'https://www.youtube.com/watch?v=qxJp_VQ5VUk' WHERE id_api = 'tt0085407';

UPDATE Contenido SET id_tmdb = 535, descripcion = 'Alex Owens es una joven huérfana que sueña con llegar a ser bailarina. Para poder vivir y, además, pagar sus clases de baile, durante el día trabaja como soldadora y de noche bailando en un club nocturno.', trailer_url = 'https://www.youtube.com/watch?v=NV6IbcZVjuk' WHERE id_api = 'tt0085549';

UPDATE Contenido SET id_tmdb = 10676, descripcion = 'Las pesadillas se vuelven realidad cuando un maníaco y propietario de una tienda de juguetes, Conal Cochran, empieza a fabricar unas máscaras que convierten las almas y los cuerpos de los niños en seres diabólicos.', trailer_url = 'https://www.youtube.com/watch?v=kk8QJdD5ExE' WHERE id_api = 'tt0085636';

UPDATE Contenido SET id_tmdb = 1516, descripcion = 'En 1972, cuatro de los mejores hombres del ejército americano, que formaban un comando, fueron encarcelados por un delito que no habían cometido. No tardaron en fugarse de la prisión en la que se encontraban recluidos. Hoy, buscados todavía por el gobierno, sobreviven como soldados de fortuna. Si tiene usted algún problema y si los encuentra, quizás pueda contratarlos.', trailer_url = NULL WHERE id_api = 'tt0084967';

Esta mujer está muy preocupada porque su hermano ha desaparecido. Además, en el encuentro aparece también una antigua novia de Fénix que hace todo lo posible por entregarle a las autoridades y así cobrar la recompensa.', 49, '1986-03-04');

UPDATE Contenido SET id_tmdb = 262, descripcion = 'Amarga comedia que narra la historia de Rupert Pupkin, un cómico obsesionado con convertirse en el mejor en su campo. Un día Rupert conoce a su ídolo, Jerry Langford, y le suplica la oportunidad de aparecer en su show, pero éste se la niega. Sin embargo no cejará en su empeño, acechando a Jerry hasta que consiga lo que quiere. Finalmente y con la ayuda de su amiga Masha secuestrarán a Langford para poder conseguir sus propósitos.', trailer_url = 'https://www.youtube.com/watch?v=0wVhCCo02P4' WHERE id_api = 'tt0085794';

UPDATE Contenido SET id_tmdb = 4543, descripcion = 'Conjunto de episodios que muestran de forma disparatada los momentos más importantes del ciclo de la vida. Desde el nacimiento a la muerte, pasando por asuntos como la filosofía, la historia o la medicina, todo tratado con el inconfundible humor de los populares cómicos ingleses.', trailer_url = 'https://www.youtube.com/watch?v=wMJ24QwHdCY' WHERE id_api = 'tt0085959';

UPDATE Contenido SET id_tmdb = 11153, descripcion = 'Un típico matrimonio americano, que tiene dos hijos, prepara minuciosamente unas vacaciones en el parque temático de Wally World (California), tratando de evitar así cualquier contratiempo. Sin embargo, nada más llegar a su destino empiezan a sucederse toda clase de problemas, de modo que las soñadas vacaciones se convierten en una auténtica pesadilla.', trailer_url = 'https://www.youtube.com/watch?v=LGJplbPcJFA' WHERE id_api = 'tt0085995';

UPDATE Contenido SET id_tmdb = 227, descripcion = 'Dos bandas de adolescentes rivales. Algunos todavía van al colegio asidos a un futuro con esperanza. Otros son jóvenes marginados (o desplazados: "outsiders") acicalados de gomina. Casi todos a la búsqueda de un sitio en una sociedad en la que no se ven reflejados, y en la que el camino más recto conlleva una fácil tentación por la violencia... Apenas unos meses antes, el propio Coppola había estrenado otra historia de pandillas juveniles con "La ley de la calle" (Rumble Fish, 1983), un hipnótico relato poco convencional en su formato que incluía incluso toques oníricos.', trailer_url = 'https://www.youtube.com/watch?v=3ud6PLVjY5Y' WHERE id_api = 'tt0086066';

UPDATE Contenido SET id_tmdb = 1892, descripcion = 'Luke Skywalker y la princesa Leia deben viajar a Tatooine para liberar a Han Solo. Para conseguirlo, deben infiltrarse en la peligrosa guarida de Jabba the Hutt, el gángster más temido de la galaxia. Una vez reunidos, el equipo recluta a tribus de Ewoks para combatir a las fuerzas imperiales en los bosques de la luna de Endor. Mientras tanto, el Emperador y Darth Vader conspiran para convertir a Luke al lado oscuro, pero el joven Skywalker, por su parte, está decidido a reavivar el espíritu del Jedi en su padre. La guerra civil galáctica culmina en un último enfrentamiento entre las fuerzas rebeldes unificadas y una segunda Estrella de la Muerte, indefensa e incompleta, en una batalla que decidirá el destino de la galaxia.', trailer_url = 'https://www.youtube.com/watch?v=yhuKapE-Bio' WHERE id_api = 'tt0086190';

UPDATE Contenido SET id_tmdb = 111, descripcion = 'Un emigrante cubano frío y sanguinario, Tony Montana, llega de Cuba para instalarse en Miami, donde se propone hacerse con un nombre dentro del crimen organizado de Florida. Junto a su amigo, Manny Rivera, inicia una ascendente carrera delictiva.', trailer_url = 'https://www.youtube.com/watch?v=vSp_kLkNdnE' WHERE id_api = 'tt0086250';

UPDATE Contenido SET id_tmdb = 9549, descripcion = 'El libro de Tom Wolfe sobre la historia del programa espacial de los Estados Unidos, se lee como si fuera una novela, y la película mantiene esa misma emocionante apariencia de ficción. Hace un recorrido desde la rotura de la barrera del sonido por Chuck Yeager en la base de la Fuerza Aérea de Edwards hasta los 7 astronautas seleccionados para el programa Mercurio, el primer proyecto de los Estados Unidos para enviar personas al espacio. Muestra que nadie tenía ni idea de cómo desarrollar un programa espacial o cual era la forma de seleccionar a las personas que debían participar en ella. Emocionante, divertido y encantador, todo a la vez.', trailer_url = 'https://www.youtube.com/watch?v=G6dFmkvEKGE' WHERE id_api = 'tt0086197';

UPDATE Contenido SET id_tmdb = 9531, descripcion = 'Superman se tiene que enfrentar con una máquina creada por un genio de los ordenadores llamado Gus Gorman, contra un magnate megalómano que pretende transformar la Tierra y lo que es mucho peor contra un desdoblamiento de personalidad. Pero también habrá tiempo para que Clark Kent vuelva a Smallville, donde se encontrará con Lana Lang, su novia de la adolescencia.', trailer_url = 'https://www.youtube.com/watch?v=nchUXJ6upXo' WHERE id_api = 'tt0086393';

UPDATE Contenido SET id_tmdb = 10650, descripcion = 'Callahan es un experimentado detective de policía del departamento de homicidios de San Francisco, famoso por sus drásticos métodos, que provocan fuertes enfrentamientos con sus superiores. Tiene que desplazarse a San Paulo, pequeño pueblo situado al norte de California, donde sigue la pista del autor de la muerte de unos hombres, a los que han encontrado con unos disparos en la frente y en los genitales. Allí conoce a una solitaria artista llamada Jennifer Spencer.', trailer_url = 'https://www.youtube.com/watch?v=8AnAgwxJk0Y' WHERE id_api = 'tt0086383';

UPDATE Contenido SET id_tmdb = 11050, descripcion = 'Aurora y Emma son madre e hija que marchan a diferentes ritmos. Comenzando con el matrimonio de Emma, Aurora muestra lo difícil y amorosa que puede ser. La película abarca varios años de su vida y como cada uno encuentra diferentes razones para seguir viviendo y encontrar la alegría. Interludios de Aurora con Garrett Breedlove, el astronauta retirado y vecino de al lado son bastante sorprendentes.', trailer_url = 'https://www.youtube.com/watch?v=7BToOAoehA0' WHERE id_api = 'tt0086425';

UPDATE Contenido SET id_tmdb = 860, descripcion = 'A David Lughtman, estudiante de diecisiete años, le han suspendido varias asignaturas. Pero haciendo uso de su gran habilidad con las computadoras, logra cambiar las notas y aprobar el curso. Un día, jugando con su máquina, David entra en contacto con "Joshua", la computadora del Departamento de Defensa de los Estados Unidos, y decide "jugar a la guerra". El muchacho cree que es un juego más pero, sin darse cuenta, desafía a "Joshua" a un escalofriante juego de guerra termonuclear mundial. Entre las dos máquinas planean desplegar todas las estrategias y opciones para una Tercera Guerra Mundial.', trailer_url = 'https://www.youtube.com/watch?v=-OyoNR4kiJ0' WHERE id_api = 'tt0086567';

UPDATE Contenido SET id_tmdb = 11030, descripcion = 'Falso documental sobre Leonard Zelig, un hombre que asombró a los Estados Unidos de los años 20 con su increíble capacidad para adaptarse a la gente que le rodea.', trailer_url = 'https://www.youtube.com/watch?v=-ih7lQxrtds' WHERE id_api = 'tt0086637';

UPDATE Contenido SET id_tmdb = 279, descripcion = 'Antonio Salieri es el músico más destacado de la corte del Emperador José II de Austria. Entregado completamente a la música, le promete a Dios humildad y castidad si, a cambio, conserva sus extraordinarias dotes musicales. Pero, después de la llegada a la corte de un joven llamado Wolfang Amadeus Mozart, Salieri queda relegado a un segundo plano. Irritado por la pérdida de protagonismo, hará todo lo posible para arruinar la carrera del joven músico. Mientras tanto, Mozart, ajeno a las maquinaciones de Salieri, sorprende a todos con su genialidad como músico, pero también con sus excentricidades.', trailer_url = 'https://www.youtube.com/watch?v=yE9X2RC0Vj0' WHERE id_api = 'tt0086879';

UPDATE Contenido SET id_tmdb = 4437, descripcion = 'Nueve años después de que la USS Discovery se perdiese en el espacio, una expedición conjunta de los Estados Unidos y la Unión Soviética es enviada a Júpiter para reactivar el ordenador Hal 9000, que dirigía la nave accidentada, y descubrir el problema que frustró la expedición del Discovery misión así como el significado de las últimas transmisiones de uno de los tripulantes. El doctor Floyd, jefe de la expedición, a su llegada a Júpiter se encuentra con el gran monolito negro que la primera misión pretendía investigar.', trailer_url = 'https://www.youtube.com/watch?v=rqvdHik5bog' WHERE id_api = 'tt0086837';

UPDATE Contenido SET id_tmdb = 9610, descripcion = 'La poderosa Reina Taramis promete a Conan hacer volver a su amada del reino de la muerte, pero le impone una condición: debe traerle un legendario cuerno incrustado de piedras preciosas y una bella y joven princesa. Lo que Conan ignora es que la Reina quiere utilizar el cuerno para despertar al durmiente dios Dagoth y sacrificarle a la joven princesa. Enfrentado con enemigos mortales y sobrenaturales, Conan debe convocar a las fuerzas del Bien para derrotar a Taramis e incluso al mismísimo dios Dagoth.', trailer_url = 'https://www.youtube.com/watch?v=QmKCtpK-6iY' WHERE id_api = 'tt0087078';

UPDATE Contenido SET id_tmdb = 11368, descripcion = 'Texas. Una joven casada y muy seductora cae en brazos de Ray, uno de los empleados de su marido. Enterado por un detective privado de la infidelidad de su mujer y obsesionado por la traición, Julián se decide a preparar el asesinato de ambos.', trailer_url = 'https://www.youtube.com/watch?v=TFzPVLdGtAg' WHERE id_api = 'tt0086979';

UPDATE Contenido SET id_tmdb = 841, descripcion = 'Por orden imperial la familia Atreides deberá hacerse cargo de la explotación del desértico planeta de Arrakis, conocido también como Dune, el único planeta donde se encuentra ''la especia'', una potente droga que, además, es necesaria para los vuelos espaciales.', trailer_url = 'https://www.youtube.com/watch?v=mtLd5CWuwbo' WHERE id_api = 'tt0087182';

UPDATE Contenido SET id_tmdb = 9730, descripcion = 'Jason, el más impopular de los habitantes de Cristal Lake, regresa para causar mayores estragos en esta parte. Tras su resurgimiento en el depósito de cadáveres de un hospital, el asesino enmascarado centra su venganza en la familia Jarvis y en un grupo de despreocupados adolescentes. El joven Tommy Jarvis es un gran aficionado al cine de terror con un talento especial para las máscaras y el maquillaje. ¿Ha encontrado el diabólico Jasón finalmente la horma de su zapato?', trailer_url = 'https://www.youtube.com/watch?v=8zcPf9fuDPg' WHERE id_api = 'tt0087298';

UPDATE Contenido SET id_tmdb = 927, descripcion = 'Rand es un viajante que un día regala a su hijo Billy una tierna y extraña criatura, un mogwai. El inocente regalo, sin embargo, será el origen de toda una ola de gamberradas y fechorías en un pequeño pueblo de Estados Unidos. Todo empieza cuando son infringidas, una tras otra, las tres reglas básicas que deben seguirse para cuidar a un mogwai: no darle de comer después de medianoche, no mojarlo y evitar que le dé la luz del Sol.', trailer_url = 'https://www.youtube.com/watch?v=XXxC0Geijzs' WHERE id_api = 'tt0087363';

UPDATE Contenido SET id_tmdb = 620, descripcion = 'Los Drs. Venkman, Stantz y Epengler, son tres doctores en parapsicología que se quedan sin empleo tras quedar excluidos de una beca universitaria de investigación. Entonces deciden formar la empresa "Los Cazafantasmas", dedicada a limpiar Nueva York de ectoplasmas. El aumento repentino de apariciones espectrales en la Gran Manzana será el presagio de la llegada de un peligroso y poderoso demonio.', trailer_url = 'https://www.youtube.com/watch?v=msq0hZSgZdM' WHERE id_api = 'tt0087332';

UPDATE Contenido SET id_tmdb = 87, descripcion = '1935. Shanghai. El intrépido arqueólogo Indiana Jones, tras meterse en jaleos en un local nocturno, consigue escapar junto a una bella cantante y su joven acompañante. Tras un accidentado vuelo, los tres acaban en la India, donde intentarán ayudar a los habitantes de un pequeño poblado, cuyos niños han sido raptados.', trailer_url = 'https://www.youtube.com/watch?v=EdRx5HPYnlQ' WHERE id_api = 'tt0087469';

UPDATE Contenido SET id_tmdb = 81, descripcion = 'En un futuro lejano, en un mundo post-apocalíptico, la Tierra está cubierta por unos bosques llenos de hongos venenosos e insectos gigantescos. Los humanos han quedado reducidos a unos pocos pueblos aislados que intentan sobrevivir a la plaga mientras luchan entre ellos. En medio de todo esto la princesa Nausicaä, del Valle del Viento, quien ama a los insectos, buscará comprender el origen del problema y conseguir la paz entre los hombres, y sobre todo entre éstos y el bosque.', trailer_url = 'https://www.youtube.com/watch?v=zaskbIZtfxQ' WHERE id_api = 'tt0087544';

UPDATE Contenido SET id_tmdb = 9314, descripcion = 'El futuro, año 1984. Winston Smith (John Hurt) soporta una abyecta existencia bajo la continua vigilancia de las autoridades en la Oceanía totalitaria. No obstante, su vida se convierte en una pesadilla cuando prueba el amor prohibido y comete el crimen de pensar libremente.', trailer_url = 'https://www.youtube.com/watch?v=1yj_Ww6jRkc' WHERE id_api = 'tt0087803';

UPDATE Contenido SET id_tmdb = 11884, descripcion = 'Alex es un adolescente que escapa de su monótona rutina jugando con un vídeo juego llamado Starfighter. Su habilidad y tenacidad atraen a un amable extranjero Centauri, que resultará ser un alienígena. Alex recibe una sacudida y es transportado hasta un lugar lejano de la galaxia, donde descubrirá que su juego preferido es una realidad. Ahora tendrá que demostrar si es tan bueno como parece...', trailer_url = 'https://www.youtube.com/watch?v=4R2UFlSc4mI' WHERE id_api = 'tt0087597';

UPDATE Contenido SET id_tmdb = 11393, descripcion = 'Nada iba a impedir que Roy Hobbs cumpliese su sueño de ser una estrella del beisbol. Robert Redford protagoniza esta inspiradora historia que empieza cuando Hobbs, con 14 años, hace un bate muy potente de la madera de un roble caído. Muy pronto impresiona a los cazatalentos de las ligas profesionales con su habilidad y queda grabado en la retina del periodista deportivo Max Mercy, el cual acabará siendo clave en la carrera de Hobbs. Sin embargo, un encuentro con una mujer misteriosa da al traste con su sueño. Pasan los años y un Hobbs más mayor reaparece como un novato en los New York Knights. Superando el dolor físico y desafiando a aquellos que les interesa ver perder a los Knights, Hobbs, con su bate de la infancia, tiene la oportunidad de hacer ganar la liga a los Knights y por fin cumplir su sueño.', trailer_url = 'https://www.youtube.com/watch?v=ihRtZcxghIE' WHERE id_api = 'tt0087781';

UPDATE Contenido SET id_tmdb = 311, descripcion = 'David Aaronson "Noodles", un pobre joven judío, conoce en los suburbios de principios del siglo XX de Manhattan, Nueva York, a Maximilian Bercovicz "Max", otro joven de origen hebreo dispuesto a llegar lejos por cualquier método. Entablan una gran amistad y forman, con los 3 colegas de "Noodles", Patrick Goldberg "Patsy", Philip Stein "Cockeye", y Dominic una banda que prospera rápidamente. Desgraciadamente, son perseguidos por Bugsy, el tipo para el que Noodles y sus amigos trabajaban anteriormente, y en uno de sus asaltos, mata a Dominic. Rápidamente Noodles se tira encima suyo y le mata, por lo que pasará 12 años en prisión. Cuando Noodles sale de prisión le recibe Max, que sigue con su banda junto a los otros 2 amigos, Patsy y Cockeye. Rápidamente, entre los 4, llegan a convertirse, en tiempos de la prohibición, en unos de los mayores gánsteres de todo el país.', trailer_url = 'https://www.youtube.com/watch?v=5vrbUpDihxs' WHERE id_api = 'tt0087843';

UPDATE Contenido SET id_tmdb = 9336, descripcion = 'En la academia de policía están a punto de finalizar sus pruebas preparatorias para el cuerpo un numeroso grupo de veteranos. Durante un tiempo, coinciden con los novatos de nuevo ingreso, que serán el centro de un montón de bromas que muchas veces se lo harán pasar muy mal.', trailer_url = 'https://www.youtube.com/watch?v=725QU19eHWI' WHERE id_api = 'tt0087928';

UPDATE Contenido SET id_tmdb = 1880, descripcion = 'Un ejército formado por tropas soviéticas y cubanas invade y destruye una pequeña localidad de Colorado, provocando la III Guerra Mundial. Un grupo de jóvenes con un alto espíritu patriótico consigue huir y preparar un rápido contraataque.', trailer_url = 'https://www.youtube.com/watch?v=cMYIe9sxLVU' WHERE id_api = 'tt0087985';

