UPDATE Contenido SET id_tmdb = 9326, descripcion = 'Joan Wilder, una escritora de novelas románticas, debe viajar a Colombia con un misterioso paquete para que su hermana sea liberada por unos traficantes de droga que la han secuestrado. Cuando llega al país sudamericano, alguien está a punto de asesinarla, y es salvada por Jack Colton, un aventurero buscavidas que se parece demasiado al héroe protagonista de sus novelas', trailer_url = 'https://www.youtube.com/watch?v=DL40GuLfxA8' WHERE id_api = 'tt0088011';

