UPDATE Contenido SET id_tmdb = 2619, descripcion = 'Allen Bauer es un neoyorquino que se salvó de morir ahogado cuando era un niño gracias a una joven sirena. 20 años después vuelve al mismo lugar y de nuevo cae al mar para ser rescatado otra vez por la misma sirena. Confuso sobre lo sucedido, Allen vuelve a Nueva York, pero la sirena decide buscarle. Ambos consiguen encontrarse y se enamoran, aunque él desconoce su secreto.', trailer_url = 'https://www.youtube.com/watch?v=uv_77am0ec8' WHERE id_api = 'tt0088161';

UPDATE Contenido SET id_tmdb = 8764, descripcion = 'El jóven ídolo del rock estadounidense Nick Rivers viaja a Alemania Oriental para participar en un prestigioso festival cultural. Pero lo que parece ser una simple gira musical pronto se convierte en un enredo internacional cuando un plan militar secreto amenaza con destrozar el orden geopolítico. Rivers se ve arrastrado a una aventura llena de conspiraciones, persecuciones y alianzas inesperadas.', trailer_url = 'https://www.youtube.com/watch?v=dG6P8W6Cw9U' WHERE id_api = 'tt0088286';

