UPDATE Contenido SET id_tmdb = 10843, descripcion = 'Al finalizar su jornada laboral, un solitario empleado de una compañía de informática (Griffin Dunne) se ve envuelto en una serie de extrañas circunstancias que le llevan a uno de los peores barrios de Nueva York. Allí, vivirá una interminable y alocada noche...', trailer_url = 'https://www.youtube.com/watch?v=jcxyqHpRR8c' WHERE id_api = 'tt0088680';

UPDATE Contenido SET id_tmdb = 12609, descripcion = 'Narra la historia de Goku, un excepcional niño que llegó a la Tierra en una cápsula durante una noche tormentosa. Sin saber nada de su pasado, un anciano lo cuidó como su nieto hasta los ocho años. Después de morir su abuelo, Goku accede a la Kame House, lugar donde un estrambótico anciano le convertirá en un campeón de artes marciales. Conocerá por el camino a Bulma, una muchacha obsesionada con algo denominado las Bolas de Dragón, y Krilin, su compañero de aventuras, entre otros.', trailer_url = 'https://www.youtube.com/watch?v=gqIEgmqljM8' WHERE id_api = 'tt0088509';

UPDATE Contenido SET id_tmdb = 13667, descripcion = 'Una vez que su novia le abandona por un esquiador palurdo, Lane decide que el suicidio es su única salida. Pero sus intentonas serán cada vez más fallidas, trayéndole sólo más angustia y desconcierto', trailer_url = 'https://www.youtube.com/watch?v=NdSavg_i_lw' WHERE id_api = 'tt0088794';

UPDATE Contenido SET id_tmdb = 68, descripcion = 'En un extraño y deprimente universo futurista donde reinan las máquinas, una mosca cae dentro de un ordenador y cambia el apellido del guerrillero Harry Tuttle por el del tranquilo padre de familia Harry Buttle, que es detenido y asesinado por el aparato represor del Estado. El tranquilo burócrata Sam Lowry es el encargado de devolver un talón a la familia de la víctima, circunstancia que le permite conocer a Jill Layton, la mujer de sus sueños. Y, mientras la persigue, hace amistad con Harry Tuttle y se convierte en su cómplice.', trailer_url = 'https://www.youtube.com/watch?v=SRYdjfC7D28' WHERE id_api = 'tt0088846';

UPDATE Contenido SET id_tmdb = 11064, descripcion = 'Brewster es un jugador de las ligas menores de béisbol. Aunque no lo conocía, un rico pariente suyo acaba de fallecer y, para probar que Brewster comprende el valor del dinero, le impone en su testamento la prueba de derrochar 30 millones de dólares en cosas inútiles en un mes, sin poder poseer al final de ese tiempo absolutamenta nada de lo que haya gastado. Si tiene éxito, heredará otros 300 millones de dólares.', trailer_url = 'https://www.youtube.com/watch?v=V7g0tqdNy7M' WHERE id_api = 'tt0088850';

UPDATE Contenido SET id_tmdb = 15196, descripcion = 'En una gran y apartada mansión victoriana se reúnen varios personajes pintorescos para cenar ante una misteriosa invitación de un anfitrión desconocido. Todos ellos tienen secretos que ocultar, por los que son vilmente chantajeados desde hace años. Cuando la casa se queda a oscuras por culpa de un momentáneo apagón de luz, el chantajista aparece asesinado en el salón. Ahora deben averiguar quién de ellos ha sido el culpable, una tarea muy complicada teniendo en cuenta que todos ellos tenían motivos de peso para cometer el crimen.', trailer_url = 'https://www.youtube.com/watch?v=KEXdWfsKZ1k' WHERE id_api = 'tt0088930';

UPDATE Contenido SET id_tmdb = 1678, descripcion = 'Las chicas de oro es una comedia de enredo americana, creada por Susan Harris, que se emitió originalmente en NBC del 14 de septiembre de 1985, al 9 de mayo de 1992. Con Bea Arthur, Betty White, Rue McClanahan y Estelle Getty, el show se centra en cuatro mujeres mayores compartiendo una casa en Miami, Florida.', trailer_url = 'https://www.youtube.com/watch?v=FKRob6YlGIA' WHERE id_api = 'tt0088526';

UPDATE Contenido SET id_tmdb = 873, descripcion = 'Principios del siglo XX. Narra la historia de Celie, una adolescente negra de catorce años que está embarazada de su propio padre, un hombre despótico y cruel. A partir de entonces su vida estará llena de dolor y humillaciones.', trailer_url = 'https://www.youtube.com/watch?v=_h-efLS7VV4' WHERE id_api = 'tt0088939';

UPDATE Contenido SET id_tmdb = 2875, descripcion = 'La serie gira en torno a las misiones que realiza el personaje principal Angus MacGyver para distintas instituciones, sobre todo para la Fundación Phoenix. En la serie, MacGyver resuelve todos los problemas que se le plantean haciendo uso de su gran inteligencia, su conocimiento académico en ciencias e ingeniería y su habilidad para la construcción de herramientas con elementos cotidianos de su entorno.', trailer_url = 'https://www.youtube.com/watch?v=dVVN4eqVB5U' WHERE id_api = 'tt0088559';

UPDATE Contenido SET id_tmdb = 10999, descripcion = 'El coronel John Matrix, experto en artes marciales, es un comando sin igual; sin embargo, debido al número de operaciones especiales en las que ha intervenido, ha sido ''jubilado'' para protegerlo de quienes desearían vengarse de él. Pero un dictador sudamericano despiadado y vengativo ha logrado localizarle y secuestrar a su hija. Para recuperarla, Matrix deberá volver a Sudamérica con una última misión: acabar con el presidente Velásquez.', trailer_url = 'https://www.youtube.com/watch?v=mh-QUh69MCg' WHERE id_api = 'tt0088944';

UPDATE Contenido SET id_tmdb = 10328, descripcion = 'Un grupo de ancianos que viven en una residencia descubren la fuente de la eterna juventud. El único problema es que el lugar mágico pertenece a un grupo de extraterrestres, y desconocen si sus intenciones son amigables. Un espléndido reparto y acertadas dosis de sentimentalismo hicieron de este drama fantástico un gran éxito de taquilla.', trailer_url = 'https://www.youtube.com/watch?v=h77perEoYNY' WHERE id_api = 'tt0088933';

UPDATE Contenido SET id_tmdb = 9749, descripcion = 'Hasta la semana pasada, Fletch era tan sólo uno de esos reporteros amables que luchaba por la verdad, la justicia y un despacho con ventana. Pero las cosas cambian cuando se hace pasar por drogadicto para seguir la pista a unos traficantes. Es entonces cuando conoce a Stanwyk, que tiene cáncer de huesos y le pide que le mate para que su esposa pueda cobrar el seguro. Stanwyk ha organizado el crimen perfecto: un robo fingido, un Jaguar para escapar y un billete de primera a Río... Pero hay algo que le huele a chamusquina. Mientras intenta descubrir la verdad disfrazado de mil maneras, Fletch se ve víctimas de amenazas, disparos, acusaciones y un arresto. ¡Y eso que sólo quería ayudar!', trailer_url = 'https://www.youtube.com/watch?v=VYsRIZsd2xI' WHERE id_api = 'tt0089155';

UPDATE Contenido SET id_tmdb = 9731, descripcion = 'Jason ha regresado, con su máscara de hockey y dispuesto a poner de nuevo en práctica todas sus viejas costumbres y trucos en esta nueva entrega. Esta vez parece que ha puesto sus ojos en los jóvenes residentes de una retirada mansión, a medio camino del pueblo. Algunos de estos adolescentes acabarán en mitades, cuartos... Jason es capaz de convertir en realidad los peores sueños.', trailer_url = 'https://www.youtube.com/watch?v=cZ5cMK-3Z_I' WHERE id_api = 'tt0089173';

UPDATE Contenido SET id_tmdb = 9340, descripcion = 'Mikey, un muchacho de trece años, que junto con su hermano mayor y sus amigos se hacen llamar ''Los Goonies'', decide subir a jugar al desván de su casa, donde su padre guarda antigüedades. Allí, el grupo encuentra el mapa de un tesoro.', trailer_url = 'https://www.youtube.com/watch?v=3IKAk4DhTWE' WHERE id_api = 'tt0089218';

UPDATE Contenido SET id_tmdb = 11797, descripcion = 'Charley Brewster, un estudiante de secundaria, descubre accidentalmente la verdadera y espeluznante naturaleza de Jerry Dandrige, su elegante y enigmático nuevo vecino; pero nadie parece dispuesto a creerle.', trailer_url = 'https://www.youtube.com/watch?v=PMRH0RIEjnc' WHERE id_api = 'tt0089175';

UPDATE Contenido SET id_tmdb = 9056, descripcion = 'Kevin es un policía de Hong Kong que se enfrenta a una difícil misión: debe atrapar al capo de la droga del país. Pero para condenar al criminal solo hay una testigo que puede incriminarle y Kevin es el único que puede protegerla. Evidentemente todos los criminales a las órdenes del capo intentarán matar a la testigo y a su guardaespaldas', trailer_url = 'https://www.youtube.com/watch?v=ccRgWRcKb9w' WHERE id_api = 'tt0089374';

UPDATE Contenido SET id_tmdb = 10014, descripcion = 'Una nueva familia se ha trasladado a Elm Street, a una casa que llevaba un buen tiempo deshabitada. Pasado poco tiempo allí, los jóvenes comienzan a tener extrañas pesadillas, tal y como ocurriese años atrás. Uno de ellos consigue darse cuenta de que Freddy intenta poseerle desde el mundo de los sueños, para pasar su obra al mundo real. Aunque intenta resistirse, no puede evitar que el asesino le obligue a realizar terribles acciones. Sólo la novia del joven puede hacer algo por salvar a su compañero, y acabar con Krueger.', trailer_url = 'https://www.youtube.com/watch?v=DHjt3H43dNI' WHERE id_api = 'tt0089686';

UPDATE Contenido SET id_tmdb = 526, descripcion = 'En una época de magia y aventuras, una leyenda heroica y sobrenatural relata la diabólica venganza del Obispo de Aquila que a consecuencia de una traición, jura impedir el amor de Navarre e Isabel. Apoderándose de las fuerzas del mal, lanza sobre la pareja un terrible hechizo: ella se convertirá en halcón durante el día y él en un acechante lobo gris por la noche... Eternamente unidos y separados, encontrarán un aliado en la persona de Philippe que les ayudará a conjurar la maldición del obispo.', trailer_url = 'https://www.youtube.com/watch?v=iGs4o_5jyhw' WHERE id_api = 'tt0089457';

UPDATE Contenido SET id_tmdb = 11976, descripcion = 'Lili es una bella princesa a la que le gusta pasear por el bosque encantado. Ella dice que va a ver a unos parientes, pero en realidad va a encontrarse con Jack, un extraño personaje verde. Mientras, una personificación del diablo intentará extender la noche eterna asesinando al unicornio de esas tierras. Aunque no parece que haya salvación, Jack y sus amigos se enfrentarán a él para salvar al mundo y a la princesa.', trailer_url = 'https://www.youtube.com/watch?v=ybnoJErfDas' WHERE id_api = 'tt0089469';

UPDATE Contenido SET id_tmdb = 606, descripcion = 'A principios del siglo XX Karen Blixen (Streep), una mujer europea de gran coraje, llega a Kenia para dirigir una plantación de café junto a su marido (Brandauer), un mujeriego incorregible con el que no se ha casado por amor. Para su sorpresa, Karen se da cuenta de que poco a poco se está enamorando de la tierra, de sus gentes... y de Denys Finch-Hatton (Redford), un enigmático cazador aventurero.', trailer_url = 'https://www.youtube.com/watch?v=5RrEv9-ks2Y' WHERE id_api = 'tt0089755';

UPDATE Contenido SET id_tmdb = 8879, descripcion = 'Un grupo de colonos buscadores de oro se establece en un lugar de California, pero sufren el acoso de los hombres de Lahood, el propietario del resto de las explotaciones mineras. Pero un día al poblado llega un misterioso y frío predicador que se pone de parte de los colonos, y comienza a enfrentarse al temido cacique local.', trailer_url = 'https://www.youtube.com/watch?v=lCVgv2Gsc9E' WHERE id_api = 'tt0089767';

UPDATE Contenido SET id_tmdb = 1369, descripcion = 'Rambo es excarcelado y enviado de vuelta al Vietnam con una nueva misión: averiguar el paradero de unos soldados norteamericanos desaparecidos. Tras saltar en paracaídas en la jungla, portando únicamente un cuchillo y un arco con flechas, se le dice que no ataque al enemigo y que sólo haga fotografías de reconocimiento. Pero el plan no saldrá como estaba previsto.', trailer_url = 'https://www.youtube.com/watch?v=q5w0-Kq9dP8' WHERE id_api = 'tt0089880';

UPDATE Contenido SET id_tmdb = 5683, descripcion = 'Pee-Wee tiene una flamante bicicleta roja y blanca que es la envidia de los niños del barrio, pero, mientras compra una bocina nueva, alguien se la roba. Empezará entonces a buscarla incansablemente, pero sin éxito; por ello decide visitar a una vidente para que le diga su paradero, pero la mujer se equivoca. Cuando Pee-Wee reanuda la búsqueda vivirá innumerables aventuras: subirá al coche de un preso fugado, viajará con una camionera fantasma, muerta hace un año, montará un toro salvaje...', trailer_url = 'https://www.youtube.com/watch?v=1UWsZ9k3Rds' WHERE id_api = 'tt0089791';

UPDATE Contenido SET id_tmdb = 10849, descripcion = 'EE.UU., Gran Depresión. Mientras Cecilia trabaja como camarera en Nueva Jersey, su marido se dedica a hacer el vago. Su única vía de escape es el cine, al que acude una y otra vez para evadirse de la realidad y soñar con un mundo de champagne, trajes de noche y fiestas elegantes. Una noche, el protagonista de su película favorita, "La rosa púrpura de El Cairo", se fija en ella y atraviesa la pantalla para conocerla.', trailer_url = 'https://www.youtube.com/watch?v=u9qate1rGAg' WHERE id_api = 'tt0089853';

UPDATE Contenido SET id_tmdb = 10925, descripcion = 'Frank y su aprendiz Freddy terminan su turno en un almacén de productos sanitarios. Charlando, Frank cuenta al joven que los hechos narrados en lapelícula la Noche de los Muertos Vivientes fueron reales, pero han sido ocultados por las autoridades. Para convencer al chico de queno miente, le lleva al sótano, donde le enseña un barril que contiene a uno de los zombies, y el gas que en su momento le devolvió la vida. Accidentalmente abren el barril, liberando tanto al muerto viviente como el gas, que alcanza un cementerio cercano. Sin saberlo, un grupo de jóvenes que han ido a pasar la noche al cementerio serán testigos del despertar de los muertos.', trailer_url = 'https://www.youtube.com/watch?v=gyeLuN1dBro' WHERE id_api = 'tt0089907';

UPDATE Contenido SET id_tmdb = 11645, descripcion = 'En el Japón medieval, el poderoso señor Hidetora decide abdicar y repartir sus dominios entre sus tres hijos. El menor considera que la idea es absurda y sólo servirá para causar problemas. Su padre, enfurecido, lo deshereda. Muy pronto descubrirá su error: la ambición hará que sus hijos mayores se enfrenten por el poder en una cruenta guerra. Se inspira en el drama de Shakespeare "El rey Lear".', trailer_url = 'https://www.youtube.com/watch?v=29ukiH4_GvQ' WHERE id_api = 'tt0089881';

