UPDATE Contenido SET id_tmdb = 9080, descripcion = 'Chevy Chase y Dan Aykroyd son dos ingenuos funcionarios de los servicios de espionaje norteamericanos que son utilizados como anzuelo para despistar a los agentes rusos, mientras los americanos tratan de llevar a cabo una astuta operación', trailer_url = 'https://www.youtube.com/watch?v=ECCIymg1kD4' WHERE id_api = 'tt0090056';

UPDATE Contenido SET id_tmdb = 11509, descripcion = 'Silverado es una vieja ciudad fronteriza del Oeste. En 1880, cuatro vaqueros cabalgan por el polvoriento camino de la ciudad: los hermanos Emmett, el aventurero Paden y un duro vaquero de raza negra. Al llegar encuentran un ambiente hostil que les obliga a tomar decisiones con las que no todos están de acuerdo. Su principal enemigo es el comisario, que se dice salvaguarda de la ley, aunque muy a su manera. Para empezar, regenta una cantina.', trailer_url = 'https://www.youtube.com/watch?v=oPLSventoUI' WHERE id_api = 'tt0090022';

