UPDATE Contenido SET id_tmdb = 9671, descripcion = 'Michael Dundee es un amigable y rudo cazador de cocodrilos en el salvaje outback australiano que, por su original filosofía de la vida, es considerado como un héroe entre los suyos. Su fama llega a oídos de Sue Charlton, una reportera de Nueva York que decide ir a Australia para visitarle y, una vez allí, le convence para que le acompañe en su viaje de regreso a América.', trailer_url = 'https://www.youtube.com/watch?v=aHVco-yGNlM' WHERE id_api = 'tt0090555';

UPDATE Contenido SET id_tmdb = 4978, descripcion = 'Viajando en barco desde Rusia hasta la soñada América, Fievel se pierde en el mar durante una feroz tormenta. Viviendo después en los suburbios de Nueva York, se enfrentará a los peligros y maravillas de este extraño lugar en una apasionante búsqueda de su familia.', trailer_url = 'https://www.youtube.com/watch?v=1XC0REIj_F0' WHERE id_api = 'tt0090633';

UPDATE Contenido SET id_tmdb = 9874, descripcion = 'Cuando el crimen se extiende como una plaga, el teniente de policía Marion Cobretti "Cobra" es el único remedio para combatirlo. La misión de Cobra consiste, por una parte, en detener a los seguidores de una secta de asesinos y, por otra en proteger a Ingrid, la testigo de un asesinato cometido por la banda. Con lo que no cuenta es con la existencia de un "topo" en el departamento de policía, que se encargará de informar del escondite de la chica.', trailer_url = 'https://www.youtube.com/watch?v=n_8F9HaVWXg' WHERE id_api = 'tt0090859';

UPDATE Contenido SET id_tmdb = 679, descripcion = 'Alien es un organismo perfecto, una máquina de matar cuya superioridad física sólo puede competir con su agresividad. La oficial Ripley y la tripulación de la nave «Nostromo» se habían enfrentado, en el pasado, a esa monstruosa criatura. Y sólo Ripley sobrevivió a la masacre. Después de vagar por el espacio durante varios años, Ripley fue rescatada. Durante ese tiempo, el planeta de Alien ha sido colonizado. Pero, de repente, se pierde la comunicación con la colonia y, para investigar los motivos, se envía una expedición de marines espaciales, capitaneados por Ripley. Allí les esperan miles de espeluznantes criaturas. Alien se ha reproducido y esta vez la lucha es por la supervivencia de la Humanidad.', trailer_url = 'https://www.youtube.com/watch?v=Rgjo6j5eNGk' WHERE id_api = 'tt0090605';

UPDATE Contenido SET id_tmdb = 6978, descripcion = 'Jack Burton es un camionero que, en una de sus paradas en el barrio de Chinatown, en San Francisco, le gana una gran cantidad de dinero a Wang Chi. Este le convence para que le lleve al aeropuerto a recoger a su prometida Miao Yin, tras lo cual le entregará el dinero que le debe. Cuando Miao Yin es secuestrada por unos gángsters chinos, Jack se verá envuelto en una gran aventura para rescatarla, entrando en un tenebroso mundo gobernado por Lo Pan, un mago de 2.000 años que gobierna sin piedad el mundo de los espíritus. Esquivando demonios y haciendo frente a temores incomprensibles, Jack lucha a su manera en los oscuros dominios de Lo Pan en una loca carrera para salvar a la chica.', trailer_url = 'https://www.youtube.com/watch?v=QDjf9qjqPhA' WHERE id_api = 'tt0090728';

UPDATE Contenido SET id_tmdb = 11873, descripcion = 'Eddie Felson, antiguo campeón de billar retirado, vive de su negocio de licores. Un día, en una sala de juego, conoce a Vincent, un joven jugador de billar, que aún no ha encontrado un oponente de su talla, y que siempre va acompañado de su novia, que es la que se encarga de las apuestas que se hacen a favor de Vincent.', trailer_url = 'https://www.youtube.com/watch?v=HgLvznCiNUo' WHERE id_api = 'tt0090863';

UPDATE Contenido SET id_tmdb = 9377, descripcion = 'Un joven de 17 años decide disfrutar de unas vacaciones anticipadas aprovechando la ausencia de sus padres. Prepara minuciosamente un día dedicado enteramente a hacer todo lo que normalmente no puede hacer. Para ello contará, por supuesto, con la compañía de su mejor amigo y de su novia.', trailer_url = 'https://www.youtube.com/watch?v=tx9micq-Ge0' WHERE id_api = 'tt0091042';

UPDATE Contenido SET id_tmdb = 1554, descripcion = 'Tres hombres muy diferentes se conocen al compartir celda en una cárcel de Louisiana. Zack es un DJ; Jack, un chulo de poca monta y Roberto, un turista italiano.', trailer_url = 'https://www.youtube.com/watch?v=IeFU1PJ-APQ' WHERE id_api = 'tt0090967';

UPDATE Contenido SET id_tmdb = 9994, descripcion = 'A finales del siglo XIX, Basil, el Sherlock Holmes del mundo de los ratones tiene que enfrentarse a su eterno enemigo: el profesor Ratigan. La aventura comienza cuando una jovencita es raptada por el villano Ratigan. Entonces Basil y sus inseparables amigos, el Dr. Dawson y Tobi, se embarcarán en una apasionante misión de rescate.', trailer_url = 'https://www.youtube.com/watch?v=s-v9FiDKyaA' WHERE id_api = 'tt0091149';

UPDATE Contenido SET id_tmdb = 10122, descripcion = 'En 1978, una oscura noche, el pequeño David, un niño de 12 años que juega cerca de su casa buscando a su hermano Jeff, se da un golpe y queda inconsciente. Ocho años, o apenas un instante después, David despierta, vuelve a su casa y se da cuenta de que su familia se ha mudado, y que él ha sido dado por desaparecido.. o por muerto. Más tarde David empieza a ser perseguido por la NASA, que dice que ha sido abduccido.', trailer_url = 'https://www.youtube.com/watch?v=gVebPEYiq2o' WHERE id_api = 'tt0091059';

UPDATE Contenido SET id_tmdb = 9426, descripcion = 'Seth Brundle, un excéntrico y solitario científico que crea uno de los inventos más revolucionarios de la historia: la cabina de teletransportación. En un intento por ponerla a prueba a la vez que ignora todo atisbo de prudencia, decide usarse a sí mismo como cobaya en la primera teletransportación aplicada a un humano, con la mala suerte de que una mosca se introduce junto con él en el artefacto. A partir de allí comenzará para Brundle una gradual pero definitiva transformación, una inquietante metamorfosis que le consumirá poco a poco, poniéndole en peligro a él y a los que le rodean.', trailer_url = 'https://www.youtube.com/watch?v=jak8opma0SM' WHERE id_api = 'tt0091064';

UPDATE Contenido SET id_tmdb = 10225, descripcion = 'De pequeño logró hacer algo que supuso el fin de cuantos lo intentaron: mató a Jason Vorhees, el terrible criminal que aterrorizó a los habitantes de Cristal Lake. Y ahora, años más tarde, Tommy se siente atormentado por el miedo de que no esté realmente muerto. Así que Tommy y un amigo van al cementerio y excavan la tumba de Jason. Desgraciadamente para Tommy (y más aún para su amigo), en lugar de encontrar un cadáver descomponiéndose, descubren que Jason se ha conservado a la perfección', trailer_url = 'https://www.youtube.com/watch?v=4ETsQHtUqcs' WHERE id_api = 'tt0091080';

UPDATE Contenido SET id_tmdb = 10136, descripcion = 'Chandler Jarrell es un detective especializado en buscar niños perdidos. Se le encomienda la misión de encontrar y proteger a un niño budista que posee poderes mágicos llamado el Chico de Oro, que ha sido raptado según sus tutores por un maligno hechicero. Jarrell es escéptico respecto a la magia y a los poderes sobrenaturales, pero a medida que avanza en el caso, descubre evidencias suficientes para empezar a dudar.', trailer_url = 'https://www.youtube.com/watch?v=S7d9PyMIFFY' WHERE id_api = 'tt0091129';

UPDATE Contenido SET id_tmdb = 10015, descripcion = 'El sargento Tom Highway, conocido como `Gunny´, es un perdedor en el plano personal, aficionado al alcohol, que sacrificó a su mujer, a su familia, a sus amigos y su reputación, por llegar a lo más alto en la carrera militar. Veterano de guerra en Vietnam y Corea, vuelve a los Estados Unidos para llevar a cabo su última misión: instruir a un grupo de novatos para convertirlos en auténticos marines.', trailer_url = 'https://www.youtube.com/watch?v=vsVKs0mN0lk' WHERE id_api = 'tt0091187';

UPDATE Contenido SET id_tmdb = 9542, descripcion = 'Una noche de tormenta, el joven Jim, que transporta un coche de lujo desde Chicago a California para entregárselo a su dueño, sintiéndose cansado y somnoliento, recoge a un misterioso autoestopista aparecido de la nada, pensando que una buena conversación le ayudará a no quedarse dormido. Jim tendrá tiempo suficiente para lamentar profundamente haber tomado una decisión tan precipitada.', trailer_url = 'https://www.youtube.com/watch?v=dTs-9jKh5_U' WHERE id_api = 'tt0091209';

UPDATE Contenido SET id_tmdb = 5143, descripcion = 'La hija mayor de una pareja de artistas, Hannah, es una esposa devota, madre cariñosa y actriz de éxito. Defensora leal de sus dos hermanas, Lee y Holly, es también la columna vertebral de una familia que parece casi tan resentida de su estabilidad como depende de ella. Pero cuando la rivalidad fraternal sabotea silenciosamente el mundo perfecto de Hannah, finalmente se da cuenta de que está tan perdida como todos los demás, y para ser capaz de encontrarse tendrá que elegir entre la independencia y... la familia sin la cual no puede vivir.', trailer_url = 'https://www.youtube.com/watch?v=8YPsjtK60ds' WHERE id_api = 'tt0091167';

UPDATE Contenido SET id_tmdb = 8009, descripcion = 'Son Inmortales, destinados a vivir eternamente. Deben retarse a duelos a través de los tiempos hasta que sólo quede uno. Sólo decapitados por la hoja de una espada pueden liberarse de su eterna lucha y conseguir el Premio: un poder inimaginable. Desde las tierras altas de Escocia del siglo XVI hasta el Nueva York de nuestros días, los Inmortales luchan por su recompensa, mientras el destino de los mortales se sostiene en un frágil equilibrio.', trailer_url = 'https://www.youtube.com/watch?v=vT13a8KzBRM' WHERE id_api = 'tt0091203';

UPDATE Contenido SET id_tmdb = 25237, descripcion = 'Tras encontrar un viejo rifle, un joven se une a las fuerzas de la resistencia soviética, que lucha por expulsar a las fuerzas nazis del frente oriental. Allí, será testigo de algunos los mayores horrores cometidos en la Segunda Guerra Mundial.', trailer_url = 'https://www.youtube.com/watch?v=38jQFZ00Cwo' WHERE id_api = 'tt0091251';

UPDATE Contenido SET id_tmdb = 5693, descripcion = 'Después de un accidentado pasado, Norman Dale es contratado para entrenar a un equipo de baloncesto. A pesar del rechazo que sufre por parte de los jugadores, de un antipático profesor y de unos vecinos que intentan echarle, Dale, que es un hombre lleno de energía y de una pasión inquebrantable por el juego, no se rinde. Pero ganarse al equipo es sólo la mitad de la batalla en un mundo en el que los equipos débiles pueden acabar jugando contra rivales de primera, pero un forastero tenaz puede levantar el orgullo de todo un condado.', trailer_url = 'https://www.youtube.com/watch?v=12h5KGHU8Mg' WHERE id_api = 'tt0091217';

UPDATE Contenido SET id_tmdb = 10658, descripcion = 'Desde un lejano planeta, y debido a un error de un laboratorio espacial, llega a La Tierra teletransportado un extraño personaje, un pato que dice llamarse Howard. Es acogido en casa de Beberly, una joven que es vocal de un grupo de rock. Cuando el doctor Jenin intenta devolverle a su planeta, la energia diabólica del experimento le atrapa, transformandole en el terrible Señor de las Tinieblas y Howard tendrá que enfrentarse a él.', trailer_url = 'https://www.youtube.com/watch?v=yeU4UlDWfKI' WHERE id_api = 'tt0091225';

UPDATE Contenido SET id_tmdb = 8856, descripcion = 'Daniel y el señor Miyagi viajan a Okinawa, a la pequeña aldea en la que el anciano nació y de la que tuvo que marcharse por un asunto de honor. Su padre está gravemente enfermo y quiere verlo, pero también le espera su antiguo amor de juventud. La llegada del señor MIyagi reabre unas heridas que el tiempo y la distancia parecían haber borrado.', trailer_url = 'https://www.youtube.com/watch?v=siRMz-PyjZI' WHERE id_api = 'tt0091326';

UPDATE Contenido SET id_tmdb = 13597, descripcion = 'Sarah debe atravesar un laberinto para rescatar a su hermano pequeño, que ha sido secuestrado por los duendes y está en manos del poderoso rey Jareth. La niña descubre que ha llegado a un lugar donde las cosas no son siempre lo que parecen.', trailer_url = 'https://www.youtube.com/watch?v=8bJy0GF2RZ0' WHERE id_api = 'tt0091369';

UPDATE Contenido SET id_tmdb = 10776, descripcion = 'Seymour, un joven dependiente de una floristería, está enamorado de su compañera Audrie, pero ella sale con un sádico dentista. Un día, justo después de un extraño eclipse, compra una pequeña planta, a la que bautiza como Audrie II. La planta comenzará a moverse e incluso a hablar con Seymour, de forma que se convierte en una atracción para la ciudad. Poco pueden imaginar todos que realmente es un ser abominable, que Seymour casualmente ha descubierto que se alimenta de sangre humana.', trailer_url = 'https://www.youtube.com/watch?v=HqX9g3Qwb5A' WHERE id_api = 'tt0091419';

UPDATE Contenido SET id_tmdb = 11454, descripcion = 'Will Graham (William Petersen) regresa a la policía persuadido por un compañero. Encargado de la difícil tarea de dar caza a un escurridizo asesino que ataca sólo los días de luna llena, Graham decide emplear métodos poco convencionales. De este modo, recurre al doctor Hannibal Lecter (Brian Cox), otro asesino en serie, para entrar en la mente del asesino, pero esto le llevará a estar expuesto a la inteligencia de un genio poniendo en peligro su salud mental.', trailer_url = 'https://www.youtube.com/watch?v=zrwMd5snOk8' WHERE id_api = 'tt0091474';

UPDATE Contenido SET id_tmdb = 11416, descripcion = 'Siglo XVIII. Los grandes imperios colonialistas, España y Portugal, se disputan el dominio de Ámerica del Sur. El padre Gabriel dirige una misión en lo alto de las montañas de Brasil, donde los nativos son evangelizados y llevan una vida pacífica. Hasta allí llega Mendoza, un mercader arrepentido, en busca de redención que, fascinado por la labor del padre Gabriel, se ordena sacerdote. La presión llevada a cabo por Portugal obliga a la Iglesia a ceder las tierras en las que se haya la misión. El padre Gabriel y Mendoza, aunque por caminos muy diferentes, harán lo imposible por defender la obra y evitar que los nativos sean esclavizados.', trailer_url = 'https://www.youtube.com/watch?v=HU14R9hbUFc' WHERE id_api = 'tt0091530';

UPDATE Contenido SET id_tmdb = 792, descripcion = 'Chris Taylor es un ingenuo joven estadounidense que, a su llegada a Vietnam, descubre que no sólo debe combatir contra los soldados vietnamitas sino también contra el miedo que le atormenta, el cansancio y la rabia que le invade. Mientras sus dos oficiales al mando libran su propia batalla personal, el conflicto, el caos y el odio hacen mella en Taylor, confundiendo su realidad e insensibilizándole ante el valor más preciado del ser humano... la vida.', trailer_url = 'https://www.youtube.com/watch?v=R8weLPF4qBQ' WHERE id_api = 'tt0091763';

UPDATE Contenido SET id_tmdb = 10466, descripcion = 'Anna es una joven y atractiva violinista que, con su novio Walter, vive provisionalmente en el apartamento de su ex-marido, un famoso director de orquesta. De repente, éste aparece en la casa y la pareja tiene que buscar otra residencia. Walter recurre a su amigo Jack, agente de la propiedad, que le proporciona una auténtica ganga en las afueras de la ciudad.', trailer_url = 'https://www.youtube.com/watch?v=ZO8svUiRDNE' WHERE id_api = 'tt0091541';

UPDATE Contenido SET id_tmdb = 192, descripcion = 'Siglo XIV. Todo comienza una hermosa mañana de finales de noviembre de 1327, cuando un monje franciscano y antiguo inquisidor, acompañado de su novicio discípulo –quien relata la historia– acuden a una abadía benedictina situada en el norte de Italia para intentar resolver un crimen. Durante su estancia van desapareciendo misteriosamente más religiosos, a quienes después hallan muertos. Poco a poco, gracias a la información aportada por algunos monjes, Guillermo va esclareciendo los hechos. El móvil de los crímenes parecen ser unos antiguos tratados que se custodian en la biblioteca del complejo, de la cual se dice que es la mayor del mundo cristiano. ¿Quién es el asesino? ¿Qué motivó la muerte de sus víctimas? Nadie lo sabe…', trailer_url = 'https://www.youtube.com/watch?v=BX2u0cxj-KU' WHERE id_api = 'tt0091605';

UPDATE Contenido SET id_tmdb = 10068, descripcion = 'Elizabeth, una bella marchante de arte, entabla relación con John, un broker de Wall Street. Tras unos inicios apasionados, la pareja se embarcará, por deseo de él, en una serie de juegos eróticos cada vez más extraños que confundirán a Elizabeth, pues ella le ama pero desconoce los verdaderos sentimientos de John.', trailer_url = 'https://www.youtube.com/watch?v=bRIsOxLzLLM' WHERE id_api = 'tt0091635';

UPDATE Contenido SET id_tmdb = 12118, descripcion = 'La academia está a punto de desaparecer. Para evitarlo, la única solución es luchar por su supervivencia contra su competidora, la academia del comandante Mauser.', trailer_url = 'https://www.youtube.com/watch?v=oodRggGr_l0' WHERE id_api = 'tt0091777';

UPDATE Contenido SET id_tmdb = 235, descripcion = 'En un pequeño pueblo de Oregon, cuatro jóvenes amigos salen de la ciudad en busca de un chico desaparecido: el sentimental Geordie, el rudo Chris, el extravagante Teddy y el miedoso Vern. Deseando ser vistos como héroes ante ellos mismos y ante los ojos del pueblo, emprenden una inolvidable excursión de dos días que se convierte en una aventura increíble. Fuman a escondidas, cuentan historias, sueltan tacos porque les gusta y hacen causa común cuando las cosas se ponen difíciles. Cuando se encuentran con los matones del pueblo, que armados de cuchillos también buscan el cuerpo, los chicos descubren una fuerza que nunca supieron que tenían.', trailer_url = 'https://www.youtube.com/watch?v=2rBenGsz23E' WHERE id_api = 'tt0092005';

UPDATE Contenido SET id_tmdb = 2605, descripcion = 'Una fábrica de robots construye con fines pacíficos un sofisticado modelo, pero sus responsables deciden que puede servir también para la guerra. Durante la presentación del invento, un rayo afecta al número 5 que, a partir de ese momento, deja de ser una máquina militar. El robot se escapa y, en su huida, se encuentra con una chica que, tomándolo por un extraterrestre, se lo lleva a su casa.', trailer_url = 'https://www.youtube.com/watch?v=_nwjjuP50Ow' WHERE id_api = 'tt0091949';

