UPDATE Contenido SET id_tmdb = 8388, descripcion = 'Tres actores de cine mudo y sin empleo, Dusty Bottoms (Chevy Chase), Lucky Day (Steve Martin) y Ned Nederlander (Martin Short), llegan por accidente a un pueblo mexicano que está siendo asolado por una banda de forajidos dirigida por "El Guapo" (Alfonso Arau). Pensando haber sido contratados para una actuación, los habitantes del pueblo creen que serán sus salvadores frente a los peligrosos delincuentes.', trailer_url = 'https://www.youtube.com/watch?v=xgOcejbMuq0' WHERE id_api = 'tt0092086';

UPDATE Contenido SET id_tmdb = 11257, descripcion = 'Lucy Honey Church una joven inglesa de buena familia, se encuentra de viaje en Florencia, acompañada por su prima y dama de compañía Charlotte Bartlett. En la pensión donde se hospedan conocen al excéntrico señor Emerson y a su hijo George, que, amablemente, les ceden sus habitaciones para que las damas disfruten de una ventana con vistas a la ciudad.', trailer_url = 'https://www.youtube.com/watch?v=PW6W3EsfZaE' WHERE id_api = 'tt0091867';

UPDATE Contenido SET id_tmdb = 168, descripcion = 'En el siglo XXIII, un misterioso poder alienígena amenaza la Tierra, evaporando los océanos y destruyendo la atmósfera. En un frenético intento para salvar a la humanidad, el Capitán Kirk y su tripulación viajan en el tiempo y regresan al San Francisco de 1986, encontrándose con un mundo de punks, pizza y autobuses de cambio exacto, que les resultan tan alienígenas como todo lo que han encontrado en los lugares más recónditos de la galaxia.', trailer_url = 'https://www.youtube.com/watch?v=4IJVV2sjPT8' WHERE id_api = 'tt0092007';

UPDATE Contenido SET id_tmdb = 10515, descripcion = 'La huérfana Sheeta ha heredado un misterioso cristal que la une al mítico reino de las nubes de Laputa. Con la ayuda del  ingenioso Pazu y una graciosa banda de piratas del cielo, dirige su camino hacia las ruinas de la que fué, una gran civilización. Sheeta y Pazu deben ser más listos que el malvado Muska, quien planea usar la tecnología de Laputa para dominar el mundo.', trailer_url = 'https://www.youtube.com/watch?v=5lMRfLJGXSM' WHERE id_api = 'tt0092067';

UPDATE Contenido SET id_tmdb = 744, descripcion = 'La Marina de los Estados Unidos ha creado una escuela de élite para pilotos con el fin de sacar una promoción de expertos en técnicas de combate. En la academia, más conocida como Top Gun, a los mejores se les entrena para ser intrépidos y fríos al mismo tiempo, capaces de no perder los nervios en situaciones extremas y de no inmutarse al romper la barrera del sonido a los mandos de un F-14. A la escuela llega el joven Maverick, famoso por su temeraria aunque brillante forma de pilotar.', trailer_url = 'https://www.youtube.com/watch?v=Klc__shdj88' WHERE id_api = 'tt0092099';

UPDATE Contenido SET id_tmdb = 9396, descripcion = 'Mick Dundee vive con la periodista Sue Charlton en su lujoso apartamento de Nueva York. Pero, tras el asesinato de Bob, el ex-marido de Sue, a manos de unos traficantes de drogas colombianos, Nick decide llevársela a Australia para poder protegerla mejor.', trailer_url = 'https://www.youtube.com/watch?v=ITeB21KyX3Q' WHERE id_api = 'tt0092493';

UPDATE Contenido SET id_tmdb = 14367, descripcion = 'Comedia de enredos y aventuras juveniles que cuenta la historia de Chris Parker (Elisabeth Shue), una chica que planeaba pasar una velada especial cuando su novio la cancela. Entonces accede a hacer de niñera de dos hermanos, un adolescente y una niña. Está convencida de que va a pasar una noche sosegada cuando recibe la llamada de Brenda (Penelope Ann Miller), una amiga que se acaba de escapar de casa. Todos viajarán al centro de la ciudad.', trailer_url = 'https://www.youtube.com/watch?v=cQzDui1QeKg' WHERE id_api = 'tt0092513';

UPDATE Contenido SET id_tmdb = 635, descripcion = 'A Harry Angel, detective privado en horas bajas de la ciudad de Nueva Orleans, lo contrata en Nueva York un misterioso personaje llamado Louis Cyphre para que encuentre a un hombre desaparecido. Conforme avanza la investigación y conoce a Epiphany Proudfoot, hija de un sacerdote vudú, se suceden extrañas muertes, que parecen estar relacionadas con la magia negra y el vudú, y que implican a Harry de una manera cada vez más personal.', trailer_url = 'https://www.youtube.com/watch?v=oLNHY7x055E' WHERE id_api = 'tt0092563';

UPDATE Contenido SET id_tmdb = 655, descripcion = 'Star Trek: La nueva generación o Viaje a las estrellas: La nueva generación en Uruguay (Star Trek: The Next Generation) (algunas veces abreviada ST:TNG o TNG) es una serie de ciencia ficción estadounidense dentro del universo de Star Trek. Situada en el siglo XXIV, 21 años después de Star Trek: la serie original, el programa cuenta con una nueva tripulación y una nueva nave Enterprise. Su estreno fue el 28 de septiembre de 1987, contando con más de 27 millones de televidentes el episodio piloto "Encuentro en Farpoint". Con un total de 178 episodios (el mayor número de episodios que haya tenido alguna serie de Star Trek) y siete temporadas, llegó a su fin el 23 de mayo de 1994, con el episodio "Todas las cosas buenas".

Los episodios siguen las aventuras de la tripulación del USS Enterprise (NCC-1701-D), una nave clase Galaxia. Como nave insignia de la Federación Unida de Planetas, la Enterprise está diseñada para la exploración y la diplomacia, pero preparada para la batalla si fuera necesario. Su capitán es el conocido y carismático Jean-Luc Picard, mucho más intelectual y filosófico que el típico protagonista de una serie de ciencia ficción.', trailer_url = 'https://www.youtube.com/watch?v=HnDtvZXYHgE' WHERE id_api = 'tt0092455';

Picard con los viajes en el tiempo entiende que está en sus manos algo mucho más importante que su propia vida. Las decisiones que tome tanto en el pasado, en el presente y en el futuro determinarán la supervivencia de la humanidad.', 92, '1994-05-23');

UPDATE Contenido SET id_tmdb = 9964, descripcion = 'Una pequeña ciudad de la costa está más tranquila que nunca. Todos sus habitantes han desaparecido. Su destino ha sido decidido por un grupo de aliens en busca de carne humana para las hamburgesas de un fast-food intergaláctico. Un cuerpo especial se enfrentará a los extraterrestres.', trailer_url = 'https://www.youtube.com/watch?v=7IHwKJOZZ6U' WHERE id_api = 'tt0092610';

UPDATE Contenido SET id_tmdb = 96, descripcion = 'El detective de Detroit Axel Foley se entera por las noticias de la tele de que su amigo Andrew Bogomil, capitán de la policía de Beverly Hills, ha sido tiroteado por una mujer. Cuando va a visitarlo al hospital, conoce a su hija Jan. Con la ayuda de dos agentes amigos suyos intenta localizar a la culpable, a pesar de que el jefe de policía Harold Lutz ha intentado encontrar alguna razón para despedir a los dos agentes. Axel y sus amigos descubren que los "atracos del alfabeto", que han tenido lugar en la zona, son obra del traficante de armas Maxwell Dent, que ha enviado a su prometida Karla Fry a matar a Bogomil porque éste le iba siguiendo los pasos.', trailer_url = 'https://www.youtube.com/watch?v=soQDJ2NA8dw' WHERE id_api = 'tt0092644';

UPDATE Contenido SET id_tmdb = 4313, descripcion = 'Tras la muerte de su esposa en un accidente de coche, Danny Tanner, un periodista de San Francisco, tiene que sacar adelante a sus tres hijas pequeñas: D.J., Stephanie y Michelle. Su cuñado Jesse y su mejor amigo, Joey, le ayudarán en la diaria y difícil tarea de criar, cuidar y educar a las niñas.', trailer_url = 'https://www.youtube.com/watch?v=SDP7__2F1YE' WHERE id_api = 'tt0092359';

', 25, '1987-09-25');

Mientras tanto, Danny se retira de su trabajo como comentarista deportivo en la estación de TV, ya que la estación ha creado un nuevo programa matutino titulado "Despierta, San Francisco", y necesitan dos personas para presentar el nuevo espectáculo. Danny es nombrado el nuevo presentador.

', 24, '1988-10-21');

Stephanie y D.J. se pelean porque Stephanie siempre anda enredando en las cosas de D.J. y como venganza, D.J. le ata todos los zapatos del armario uno junto al otro.', 24, '1988-11-11');

Durante la cena se descubre que Denise es una chica con la que Jesse ya había salido antes, lo que le hace a Danny preguntarse si habrá alguna chica en San Francisco con la que Jesse no haya salido aún. A Zoey no le gustan las bromas de Joey, pero él parece que se lleva bien con Cheryl. Danny está triste porque parece que Denise aún está colgada de Jesse y no se lo puede quitar de la cabeza porque cree que aún tienen una oportunidad de volver a estar juntos. Mientras, en el piso de arriba Stephanie provoca que D.J. arroje accidentalmente por el lavabo el anillo de bodas de su padre. Ellas intentarán sacarlo por su cuenta pero al final necesitarán la ayuda de la familia para conseguirlo.', 24, '1988-12-09');

Mientras el Señor Malatesta le ofrece a Michelle un anuncio publicitario en el que Jesse y Joey deben trabajar.', 24, '1989-03-10');

Mientras Stephanie pierde un diente y el hada de los dientes le deja un billete de 20 dolares. Además, Danny y los chicos tratan de enseñarle a Michelle a compartir.', 23, '1989-10-06');

Mientras D.J. tiene que seguir a una persona durante un día y hacer un trabajo para el colegio sobre esa persona. Elige a Michelle y se pasa el día detrás de ella. Por otro lado, Becky está fuera de la ciudad por unos días, y en Despierta San Francisco ponen como compañero de Danny a Joey.', 23, '1989-10-13');

Mientras, Comet, que es muy juguetón, coge la costumbre de destrozar las cosas que ve por el suelo. Una de sus víctimas es el Señor Oso, el juguete favorito de Stephanie.', 23, '1989-12-15');

En este capítulo aparece Jaleel White en su papel de Steve Urkel.', 23, '1991-01-25');

Mientras Jesse y Becky se quedan en casa discutiendo sobre la mejor manera de educar a sus hijos.', 23, '1992-03-03');

UPDATE Contenido SET id_tmdb = 88, descripcion = 'Johnny Castle es un experto profesor de baile y un amante consumado. Por su parte, Baby Houseman es una aburrida e inocente adolescente de 17 años. Durante el transcurso de un verano, en un balneario para clases acomodadas, el encuentro entre ambos causará más de un recelo, a causa de sus distintos orígenes sociales. Entre ambos media un abismo pero, cuando la música suena, sus cuerpos se abrazan al ritmo del dirty dancing y todos esos detalles desaparecen de repente...', trailer_url = 'https://www.youtube.com/watch?v=cFwFE_Rs_8I' WHERE id_api = 'tt0092890';

UPDATE Contenido SET id_tmdb = 11690, descripcion = 'Cada cinco años se celebra el "Kumite", un torneo secreto de artes marciales en el que se enfrentan, a vida o muerte, los mejores luchadores del mundo. Frank Dux, que trabaja eventualmente para la CIA, se convertirá en el primer occidental que participa en este torneo. Pero, para ganar, deberá derrotar al despiadado Chong Li, el vigente campeón.', trailer_url = 'https://www.youtube.com/watch?v=bCZ1CIQ64YQ' WHERE id_api = 'tt0092675';

UPDATE Contenido SET id_tmdb = 12919, descripcion = 'Ronny Miller, un chico cualquiera, está enamorado en secreto de Cindy Mancini, la chica más guapa y popular del campus. Cuando Cindy se ve envuelta en un tremendo apuro, Ronny aparece y arregla el embrollo, pero todo tiene un precio: Cindy tiene que hacerse pasar por su novia, esperando que así la popularidad de ella "se le pegue". Pero el camino para conseguirla toma un giro inesperado cuando Ronny pasa a ser tan "guay" que sus amigos se escandalizan. Cindy pasa a un segundo plano y Ronny descubre que el dinero puede comprar la popularidad, pero ¡no puede comprar el amor!', trailer_url = 'https://www.youtube.com/watch?v=hiS42RHaKyg' WHERE id_api = 'tt0092718';

UPDATE Contenido SET id_tmdb = 10110, descripcion = 'Cuando, en diciembre de 1941, el ejército japonés ocupa Shanghai, la privilegiada vida de James Graham, un niño inglés de clase alta, toca a su fin. Es separado de sus padres y confinado en un campo de concentración próximo a un aeropuerto militar chino. En un ambiente dominado por la tristeza y la miseria se verá obligado a madurar prematuramente, y eso condicionará su visión del mundo.', trailer_url = 'https://www.youtube.com/watch?v=NsU11wxFMbY' WHERE id_api = 'tt0092965';

UPDATE Contenido SET id_tmdb = 765, descripcion = 'El bueno de Ash se dispone a pasar un fin de semana en el bosque con su novia. Pero todo se va al traste cuando repoducen una cinta en la que un profesor había grabado varios pasajes del Necronomicom, el Libro de los Muertos. El hechizo convoca a una fuerza demoniaca que convierte a la compañera de Ash en un monstruo ávido de carne. Ahora él y varios compañeros se disponen a pasar una noche en una cabaña en medio del bosque, con un demonio en casa.', trailer_url = 'https://www.youtube.com/watch?v=s7WNgzilRBw' WHERE id_api = 'tt0092991';

UPDATE Contenido SET id_tmdb = 10998, descripcion = 'Mientras su mujer y su hija pasan el fin de semana fuera de casa, Dan tiene una aventura con Alex, una compañera de trabajo. Pero lo que para él no es más que una excitante pasatiempo, para ella es mucho más. Por eso, cuando Dan le comunica que quiere dejar de verla, enloquece.', trailer_url = 'https://www.youtube.com/watch?v=HXQhUukZqkA' WHERE id_api = 'tt0093010';

UPDATE Contenido SET id_tmdb = 4239, descripcion = 'En "Matrimonio con hijos" se parodiaba la familia norteamericana de los años 80: un marido al que poco le importaba su familia; la señora, una impulsiva compradora; la hija, que era el estereotipo de "rubia sexy y tonta"; y el hijo, un perdedor que busca ser atractivo. Posteriormente se unirían a la familia Seven, un hijo adoptado. Los Bundy viven en Chicago y, aunque no podría afirmarse que se aprecien particularmente, siempre se mantienen juntos. Tal y como el mismo Al Bundy explica: "Amor, odio... mira, somos una familia, ¿cuál es la diferencia?". Su convivencia, y la relación con sus vecinos, una pareja de recién casados idealistas y poco conscientes de la realidad del matrimonio, fue el punto de partida para una de las series más sarcásticas, desvergonzadas y cáusticas de la historia de la televisión norteamericana.', trailer_url = NULL WHERE id_api = 'tt0092400';

UPDATE Contenido SET id_tmdb = 144, descripcion = 'Dos ángeles sobrevuelan Berlín, ciudad dividida por el "muro de la vergüenza". Sólo son visibles para los niños y los hombres de corazón puro. Testigos impotentes que no pueden cambiar el curso de los acontecimientos, sienten una gran compasión por los seres humanos. Uno de ellos, decidido a conocer los sentimientos de los mortales, se enamora de una joven trapecista.', trailer_url = 'https://www.youtube.com/watch?v=0iAzYofuItM' WHERE id_api = 'tt0093191';

UPDATE Contenido SET id_tmdb = 600, descripcion = 'Un grupo de reclutas se prepara en Parish Island, centro de entrenamiento de la marina Norteamericana. Allí está el sargento Hartmann, duro e implacable, cuya única misión en la vida es endurecer el cuerpo y el alma de los novatos, para que puedan defenderse del enemigo. Pero no todos los jóvenes soportan igual sus métodos...', trailer_url = 'https://www.youtube.com/watch?v=7115nOKRFD8' WHERE id_api = 'tt0093058';

UPDATE Contenido SET id_tmdb = 2614, descripcion = 'El temperamental piloto Tuck Pendelton se presta voluntario para un experimento que consiste en miniaturizarle en el interior de una cápsula que debe ser introducida en un conejo. Pero unos delincuentes intentan apropiarse del invento, y Pendelton acaba por casualidad en el interior de Jack Putter, un ser humano hipocondríaco. A partir de ahí, ambos se verán obligados a colaborar para conseguir que Tuck pueda salir del cuerpo de Jack.', trailer_url = 'https://www.youtube.com/watch?v=-VvhMcQFY38' WHERE id_api = 'tt0093260';

UPDATE Contenido SET id_tmdb = 801, descripcion = 'Vietnam. 1965. Un pinchadiscos de la radio, Adrian Cronauer, es enviado a Saigón para trabajar en la emisora del ejército norteamericano. En contraste con sus aburridos antecesores, Cronauer es pura dinamita, sus comentarios irreverentes, sus tacos e improperios y sus críticas al vicepresidente, le hacen ganarse el aprecio de las tropas. Sin embargo su superior el teniente Hauk no es de la misma opinión.', trailer_url = 'https://www.youtube.com/watch?v=JnBXv3W0arQ' WHERE id_api = 'tt0093105';

UPDATE Contenido SET id_tmdb = 9003, descripcion = 'Frank Cotton tiene en su poder un enigmático cubo dotado de poderes extraordinarios. Según antiguas leyendas, es una especie de puerta a seres de otra dimensión que pueden proporcionar placeres sensuales inimaginables. Cotton convoca a estas criaturas, pero sólo le inflingirán tormentos y dolor hasta acabar con él. 20 años después, dos nuevos inquilinos se instalan en la antigua casa de Frank: su hermano y su esposa. La aparición del espíritu de Frank es el principio de una vorágine de horror en estado puro.', trailer_url = 'https://www.youtube.com/watch?v=tOcth6-HjPg' WHERE id_api = 'tt0093177';

UPDATE Contenido SET id_tmdb = 580, descripcion = 'Ellen Brody aún vive en el pueblecito isleño de Amity, pero sus hijos Sean y Michael ya no trabajan en el Sea World y hace tiempo que su marido Martin falleció de un ataque al corazón debido a su miedo a los escualos. Sean es ahora policía del pueblo. Una noche de Navidad tiene que acudir a una llamada para desenredar un tronco de una boya y es devorado por un gran tiburón blanco. Su madre piensa que fue una venganza personal contra su familia, por lo que su hijo Michael decide llevársela con su mujer y su hija lejos de Amity.', trailer_url = 'https://www.youtube.com/watch?v=PMXarjDD86E' WHERE id_api = 'tt0093300';

UPDATE Contenido SET id_tmdb = 941, descripcion = 'Antiguos soldados de la guerra del Vietnam han creado una poderosa red de tráfico de droga. Dos policias reciben el encargo de esclarecer un asesinato en el que esa peligrosa organización se halla implicada.', trailer_url = 'https://www.youtube.com/watch?v=kulyIwXNznU' WHERE id_api = 'tt0093409';

UPDATE Contenido SET id_tmdb = 746, descripcion = 'Pekín, 1908. China se encuentra en plena decadencia. Puyi, un niño de tres años, es arrancado de los brazos de su madre. En medio de la noche es conducido hasta la Ciudad Prohibida, donde es coronado emperador, aunque tendrá que vivir recluido dentro de ese recinto inaccesible.', trailer_url = 'https://www.youtube.com/watch?v=uJilPHcnnjw' WHERE id_api = 'tt0093389';

UPDATE Contenido SET id_tmdb = 708, descripcion = 'El agente 007 se enfrenta a una nueva misión en Bratislava: ha sido designado expresamente por el general Koskov para que lo proteja al desertar de la KGB. Tras escapar hacia Austria, Koskov se reúne con la organización de Bond en Londres para ponerlos al corriente de los planes de general Puskin, que tiene la intención de asesinar a una serie de agentes británicos. Bond no cree la historia de Koskov, más aún cuando éste es capturado de nuevo por la KGB. Para dar con el paradero de Koskov, Bond regresa a Bratislav, donde encuentra a la novia del general, que también corre peligro. La ayuda a escapar, y descubre que Koskov se halla en Tanger junto al general Whitaker, traficante de armas.', trailer_url = 'https://www.youtube.com/watch?v=fQdNvTgKHng' WHERE id_api = 'tt0093428';

UPDATE Contenido SET id_tmdb = 1547, descripcion = 'Sam y su hermano mayor Michael son los típicos jóvenes americanos con intereses normales. Pero nada más instalarse en la tranquila ciudad de Santa Carla, California, las cosas misteriosamente empiezan a cambiar. La personalidad de Michael se transforma. Y a su madre no le gustaría ver en lo que se está convirtiendo.', trailer_url = 'https://www.youtube.com/watch?v=Q786UsnOcsY' WHERE id_api = 'tt0093437';

UPDATE Contenido SET id_tmdb = 10072, descripcion = 'Años después de los incidentes, Nancy se ha convertido en una psiquiatra especializado en terapia del sueño, pero Freddy también sigue en activo, y comienza a parecerse en los sueños de varios de los pacientes. Nancy los reúne a todos en busca de una forma de parar al monstruo.', trailer_url = 'https://www.youtube.com/watch?v=POfLbCv-co8' WHERE id_api = 'tt0093629';

UPDATE Contenido SET id_tmdb = 11649, descripcion = 'Basada en la famosa serie animada. He-man y sus amigos deben viajar a la Tierra del siglo XX para rescatar una llave cósmica que les permita derrotar a Skeletor, que se ha apoderado del castillo de Grayskull y que mantiene prisionera a Sorceress. Los inconvenientes son que Skeletor posee otra llave y que la original está en manos de unos jóvenes terrícolas, que creen que es un instrumento musical.', trailer_url = 'https://www.youtube.com/watch?v=vLq_LYUkZG0' WHERE id_api = 'tt0093507';

UPDATE Contenido SET id_tmdb = 10780, descripcion = 'Joanna Stayton, una rica y presuntuosa heredera, contrata al carpintero Dean Proffitt porque necesita en su yate un armario para guardar su lujoso vestuario. Cuando Dean fracasa en su encargo, ella lo despide sin pagarle. Poco después, al caerse por la borda, Joanna recibe un golpe que le provoca amnesia. Enterado del hecho por la tele, Dean se inventa una historia para hacerse pasar por su marido.', trailer_url = 'https://www.youtube.com/watch?v=tHsO4OUYyXs' WHERE id_api = 'tt0093693';

UPDATE Contenido SET id_tmdb = 2039, descripcion = 'Loretta, una viuda de origen italiano que vive en Nueva York, decide contraer matrimonio con Johnny, un solterón de carácter débil al que maneja a su antojo. De repente, Johnny tiene que ir a Sicilia para visitar a su madre enferma; entonces le pide a Loretta que se encargue de invitar a la boda a su hermano Ronnie, del que está distanciado desde hace tiempo.', trailer_url = 'https://www.youtube.com/watch?v=MN3sPq9RJKM' WHERE id_api = 'tt0093565';

UPDATE Contenido SET id_tmdb = 11879, descripcion = 'Un joven cowboy, seducido por una chica nueva en la ciudad, descubre que ha sido mordido por un vampiro. Lentamente se convierte en una criatura de la noche, una raza compuesta por hombres y mujeres que vagan sin rumbo, alimentándose con la sangre de sus víctimas. Frente a estos zombis vampiros, sólo queda una cosa: "rezar para que salga la luz del día"', trailer_url = 'https://www.youtube.com/watch?v=XBDhZrzqcPY' WHERE id_api = 'tt0093605';

UPDATE Contenido SET id_tmdb = 10083, descripcion = 'El Secretario de Defensa David Brice (Gene Hackman) mata a su amante en un arrebato de furia. Para encubrir el escándalo, su fiel ayudante (Will Patton) hace que las sospechas recaigan sobre un espía ruso, y para encontrarlo recluta al comandante de marina Tom Farrell (Kevin Costner). A medida que la investigación avanza, Farrell descubre horrorizado que todas las pistas lo inculpan directamente a él y que su vida corre peligro.', trailer_url = 'https://www.youtube.com/watch?v=-NaBMu3pooM' WHERE id_api = 'tt0093640';

UPDATE Contenido SET id_tmdb = 1825, descripcion = 'Lincoln Hawk es un camionero que no deja de pensar en su hijo, al que no ha visto desde su nacimiento. Ahora, Lincoln debe recogerlo en la academia militar de Virginia para llevarlo a Denver, donde su madre -de la que Lincoln está divorciado- agoniza. Pero el suegro de Lincoln no quiere que llegue. Ésta es la historia de un padre que conquista el amor de su hijo, pese a que todo está contra él, un hombre con la ambición de ganar el concurso mundial de pulsos, contra todo pronóstico, y compartir sus sueños con su hijo.', trailer_url = 'https://www.youtube.com/watch?v=EaqL6BPp--A' WHERE id_api = 'tt0093692';

UPDATE Contenido SET id_tmdb = 2493, descripcion = 'Después de buscar fortuna durante cinco años, Westley retorna a su tierra para casarse con su amada, la bella Buttercup, a la que había jurado amor eterno. Sin embargo, para recuperarla habrá de enfrentarse a Vizzini y sus esbirros. Una vez derrotados éstos, tendrá que superar el peor de los obstáculos: el príncipe Humperdinck pretende desposar a la desdichada Buttercup, pese a que ella no lo ama, ya que sigue enamorada de Westley.', trailer_url = 'https://www.youtube.com/watch?v=HFv8r4CKwTM' WHERE id_api = 'tt0093779';

UPDATE Contenido SET id_tmdb = 2609, descripcion = 'Un vendedor de cortinas de ducha y un estirado agente de publicidad tienen asientos contiguos en el vuelo que les lleva a casa para celebrar el Día de Acción de Gracias. Pero el avión, luego el tren y posteriormente el automóvil en el que viajan sufrirán muchos percances y los dos personajes, que mantienen una tensa relación, tendrán que colaborar juntos para poder llegar a casa a tiempo.', trailer_url = 'https://www.youtube.com/watch?v=vHhG2MsGxGI' WHERE id_api = 'tt0093748';

UPDATE Contenido SET id_tmdb = 106, descripcion = 'Un comando de mercenarios es contratados por la CIA para rescatar a unos pilotos apresados por las guerrillas en la selva Centroamericana. La misión resulta satisfactoria, pero durante su viaje de regreso se dan cuenta de que algo está dándoles caza uno a uno, ese algo resulta ser un cazador alienígena que se queda con las calaveras de sus víctimas como trofeos', trailer_url = 'https://www.youtube.com/watch?v=RinHCS85Wt8' WHERE id_api = 'tt0093773';

UPDATE Contenido SET id_tmdb = 10587, descripcion = 'Reclutado por el comandante Lassard, un grupo de voluntarios llega a la Academia para ser formados en un programa de patrullas civiles.', trailer_url = 'https://www.youtube.com/watch?v=VMc2efsEFgQ' WHERE id_api = 'tt0093756';

UPDATE Contenido SET id_tmdb = 865, descripcion = 'En el año 2017, el mundo se ha colapsado por culpa de una grave crisis económica. La primera potencia del planeta, los Estados Unidos de América, se hallan inmersos en el caos y el desconcierto. Para salir del atolladero, el gobierno inventa un videojuego que se emite por televisión y que logra altas cotas de audiencia. Consiste en soltar a varios convictos para que corran hacia la libertad mientras son perseguidos por auténticas máquinas de matar. Entre los participantes se encuentra Ben Richards (Arnold Schwarzenneger), dispuesto a aprovechar la oportunidad que le han ofrecido.', trailer_url = 'https://www.youtube.com/watch?v=i2FMhBg0h_8' WHERE id_api = 'tt0093894';

UPDATE Contenido SET id_tmdb = 8852, descripcion = 'Un sacerdote cree haber descubierto el lugar de descanso de Satán, príncipe de las tinieblas, en una nueva entrega de terror del habitual del género John Carpenter. Una cinta que obtuvo malas críticas pero defendida por los seguidores del realizador, que aquí firmó el guión con seudónimo.', trailer_url = 'https://www.youtube.com/watch?v=GMJ5a08G0CM' WHERE id_api = 'tt0093777';

UPDATE Contenido SET id_tmdb = 378, descripcion = 'H.I. McDonnough y Edwina, un exconvicto y una expolicía, son una pareja que ven sus planes de futuro frustrados al no poder tener hijos, pero están dispuestos a intentar recuperarlos secuestrando al bebé de una familia que acaba de tener quintillizos.', trailer_url = 'https://www.youtube.com/watch?v=9ZS8BMKw-JY' WHERE id_api = 'tt0093822';

UPDATE Contenido SET id_tmdb = 5548, descripcion = 'Parte del cuerpo de un policía asesinado, es utilizado para crear un «superpolicía» con cuerpo mecánico y cerebro humano. Aunque los científicos aseguran que el robot no tendrá remordimientos, éstos acabarán apareciendo en la memoria del humanoide.', trailer_url = 'https://www.youtube.com/watch?v=avjhBziqypU' WHERE id_api = 'tt0093870';

UPDATE Contenido SET id_tmdb = 11584, descripcion = 'Adaptación moderna del clásico de Edmond Rostand, Cyrano de Bergerac. C.D. Bales, jefe de bomberos de una pequeña población, es un poeta frustrado que no ha tenido suerte ni con la literatura ni con las mujeres. En el caso de las mujeres, el problema es su enorme nariz. A pesar de ello, no tiene complejos y trata de conquistar a Roxanne, una estudiante de astronomía que prepara su tesis. Pero ella se siente atraída por otro bombero, Chris McDonell, tan guapo como torpe con las palabras.', trailer_url = 'https://www.youtube.com/watch?v=BTZImXfnrXM' WHERE id_api = 'tt0093886';

UPDATE Contenido SET id_tmdb = 957, descripcion = 'La princesa Vespa (Daphne Zuniga) decide huir justo antes de su boda con el príncipe Valium (JM J. Bullock), para ello se lleva a su robot Dot Matrix (Lorene Yarnell) y una pequeña nave espacial. Ante esto su padre, el rey Roland de Druidia (Dick Van Patten) ofrece una recompensa a quien encuentre a su hija. La recompensa interesa mucho a Lone Starr (Bill Pullman) y a su ayudante Vomito Barf (John Candy) que deben mucho dinero a un delincuente llamado Pizza el Hutt (Dom DeLuise). En su huida la princesa Vespa es interceptada por la nave del malvado Lord Casco Oscuro (Rick Moranis) que trabaja para el presidente del planeta Spaceballs (Mel Brooks), que ansía el aire puro del planeta Druidia. Lone Starr, con la ayuda del maestro Yogurt (Mel Brooks), que le enseña a usar la suerte, debe rescatar a la princesa y acabar con los Spaceball', trailer_url = 'https://www.youtube.com/watch?v=mN09YLA1_-I' WHERE id_api = 'tt0094012';

UPDATE Contenido SET id_tmdb = 117, descripcion = 'El joven agente del tesoro Elliot Ness llega a Chicago con la determinación de detener a Al Capone. No va a ser tarea fácil, puesto que Capone tiene a la policía en el bolsillo. Ness conoce a Jimmy Malone, un guardia veterano y probablemente el más honrado de todo el cuerpo, al que Ness pide ayuda en su cruzada contra Capone.', trailer_url = 'https://www.youtube.com/watch?v=TsWXoKO5Svw' WHERE id_api = 'tt0094226';

UPDATE Contenido SET id_tmdb = 11411, descripcion = 'Poco despues de que la cumbre USA-URSS para el desarme nuclear fracase, el mundo se ve al borde de la III guerra mundial. Superman recibe la carta del niño Jeremy, quien le pide que salve el mundo de la inminente guerra atómica. Desafiando al espíritu de los sabios de Krypton, el Hombre de Acero anuncia a la ONU que destruirá todas las armas nucleares, tanto del Este como del Oeste. Sin embargo, esto es aprovechado por el genio criminal Lex Luthor, recién fugado de prisión, quien se alía con los militaristas americanos y soviéticos para crear a Nuclear Man, un supermonstruo que aniquilará al Ultimo Hijo de Krypton.', trailer_url = 'https://www.youtube.com/watch?v=J3IFSj4ebwU' WHERE id_api = 'tt0094074';

UPDATE Contenido SET id_tmdb = 12154, descripcion = 'Cuando tres solteros, el arquitecto Peter, el artista Michael y el actor Jack, se encuentran en la puerta de su casa un pequeño bebé del que no saben nada, se ven obligados a hacer de padres. Hasta entonces disfrutaban de una libertad total que dedicaban a la diversión, a las mujeres y al trabajo. A partir de ese momento tendrán que aprender a poner pañales, dar biberones...', trailer_url = 'https://www.youtube.com/watch?v=ki1tNXq9vIU' WHERE id_api = 'tt0094137';

UPDATE Contenido SET id_tmdb = 10673, descripcion = 'Bud Fox es un joven y ambicioso corredor de bolsa que logró finalizar sus estudios universitarios gracias a su esfuerzo y al de su padre, mecánico y jefe de sindicato. Su mayor deseo es trabajar con el hombre al que admira, Gordon Gekko, un individuo sin escrúpulos hecho a sí mismo que, en poco tiempo, ha conseguido amasar una gran fortuna en el mundo de la bolsa. Gracias a su insistencia, Bud consigue introducirse en el círculo privado del todopoderoso Gekko y comienza a colaborar con él en sus negocios e inversiones.', trailer_url = 'https://www.youtube.com/watch?v=LO3aipUvfK8' WHERE id_api = 'tt0094291';

UPDATE Contenido SET id_tmdb = 149, descripcion = 'Corre el año 2019. Un estado policial, políticos tramposos, sectas religiosas, revolucionarios y un proyecto científico secreto se combinan para causar una atmósfera explosiva en Neo-Tokyo. Todos los grupos rivales quieren controlar a Akira, un chico con extraños poderes psíquicos que ha sido mantenido bajo custodia criogénica por más de 30 años. En medio de esta tensa atmósfera, un joven psíquico llamado Tetsuo libera a Akira.', trailer_url = 'https://www.youtube.com/watch?v=SQ_hhKhrABs' WHERE id_api = 'tt0094625';

UPDATE Contenido SET id_tmdb = 6069, descripcion = 'En la pequeña y tranquila población de Eastwick, Nueva Inglaterra, viven Jane (Sarandon), Sukie (Pfeiffer) y Alexandra (Cher), tres modernas y aburridas mujeres. Hartas de esperar al hombre capaz de satisfacerlas, una noche de lluvia se reúnen, e inocentemente, invocan al hombre perfecto. Pronto las tres mujeres descubren sus extraordinarios poderes cuando llega a la ciudad el misterioso Daryl Van Horne (Nicholson), un personaje tan diabólico como seductor.', trailer_url = 'https://www.youtube.com/watch?v=mLs1y_KSTKk' WHERE id_api = 'tt0094332';

UPDATE Contenido SET id_tmdb = 13446, descripcion = 'Dos jóvenes actores, Withnail y Marwood, comparten un miserable apartamento en Londres y buscan trabajo en vano, con poca suerte. Withnail convence a su rico y excéntrico tío Monty para que les preste su casa de campo durante unas semanas; pero encuentran el campo tan frío y antipático como la ciudad. Entonces el tío Monty se une a ellos y se propone inmediatamente seducir a Marwood. Withnail admite que le dijo a su tío que Marwood era gay (no lo es) porque de lo contrario no habrían tenido oportunidad de quedarse con la casa.', trailer_url = 'https://www.youtube.com/watch?v=PCJ2gzSeTdE' WHERE id_api = 'tt0094336';

UPDATE Contenido SET id_tmdb = 4011, descripcion = '¿Qué debería hacer una pareja de fantasmas si su estrafalario hogar de Nueva Inglaterra se llenara de elegantes visitantes neoyorquinos? Pedir ayuda a un exorcista para aterrorizar a los intrusos con el fin de que abandonen la casa. Bitelchús es una criatura de ultratumba repugnante y terrorífica, un fenómeno asustando y bromeando que se gira y se transforma en grotescas formas, traga insectos y no puede dejar a las mujeres (vivas o muertas) en paz.', trailer_url = 'https://www.youtube.com/watch?v=po1HJbmow0g' WHERE id_api = 'tt0094721';

UPDATE Contenido SET id_tmdb = 2280, descripcion = 'Josh Baskin tiene trece años pero, cansado de que las chicas no le hagan caso y de que sus padres le traten como a un niño, desea ser mayor. Una noche, encuentra, en una feria, una vieja máquina que concede un deseo a cambio de una moneda. Josh, sin dudarlo un instante, pide hacerse mayor. A la mañana siguiente, descubre en el espejo un cuerpo de adulto. La otra cara de la moneda serán los problemas y responsabilidades que debe asumir sin ninguna experiencia previa.', trailer_url = 'https://www.youtube.com/watch?v=YM8zgY7sG_g' WHERE id_api = 'tt0094737';

UPDATE Contenido SET id_tmdb = 9599, descripcion = 'Una malévola forma de vida viscosa irrumpe en un tranquilo pueblo de Arborville. No tiene problemas de conciencia ni inteligencia alguna, y sólo sabe hacer una cosa, pero es todo un experto en ello: comerse todo lo que se mueve, hombres, mujeres o niños.', trailer_url = 'https://www.youtube.com/watch?v=vq0our4mceQ' WHERE id_api = 'tt0094761';

UPDATE Contenido SET id_tmdb = 9602, descripcion = 'El principe Akeen del africano reino de Zamunda cumple veintiún años. Su futura esposa ya ha sido elegida por el rey y es presentada en la corte. Akeen decide ir a Norteamérica para buscar novia de su gusto. Un barrio marginal de Nueva York será su morada.', trailer_url = 'https://www.youtube.com/watch?v=ZDme5Y5E-bI' WHERE id_api = 'tt0094898';

UPDATE Contenido SET id_tmdb = 10585, descripcion = 'El vudú y el terror se apoderan de un muñeco de aspecto inocente habitado por el alma de un asesino en serie. Cuando Andy Barclay, un niño de seis años de edad, asegura que “Chucky”, su nuevo muñeco, ha arrojado violentamente por la ventana a su niñera, nadie le cree. Pero una larga serie de horribles asesinatos conduce al detective que se ocupa del caso hasta el muñeco y, entonces, descubre que el auténtico terror no ha hecho más que empezar. El malvado muñeco pretende transferir su diabólico espíritu a un ser humano, y el pequeño Andy parece ser el candidato perfecto.', trailer_url = 'https://www.youtube.com/watch?v=6YYCNn3tyMQ' WHERE id_api = 'tt0094862';

UPDATE Contenido SET id_tmdb = 287, descripcion = 'Un novato (Robbins) y una vieja gloria del béisbol (Costner) se disputarán el amor de una madura y atractiva animadora del equipo (Sarandon). Cada primavera, Annie, forofa del equipo de béisbol "Los Búfalos" de Durham, elige a un jugador para "educarle" en la cama y en el campo de juego. Esta temporada tiene dos candidatos: el veterano y el novato. Ambos tienen cualidades pero, como suele suceder, ellas siempre deciden... (FILMAFFINITY)', trailer_url = 'https://www.youtube.com/watch?v=qnWSvSrb1-I' WHERE id_api = 'tt0094812';

UPDATE Contenido SET id_tmdb = 7520, descripcion = 'Brian Flanagan (Tom Cruise), un joven ambicioso recién licenciado del ejército, trabaja como camarero en un local de copas de Nueva York para costearse los estudios. Gracias a los consejos de su jefe Douglas Coughlin (Brian Brown), se convierte en la atracción del local. Pero él aspira a abrir su propio local con el nombre de "Coktails y Sueños". Para conseguir el dinero necesario se va a Jamaica a trabajar de camarero. Allí conoce a Jordan Mooney (Elisabeth Shue), una ingenua joven que está de vacaciones en la isla.', trailer_url = 'https://www.youtube.com/watch?v=Tyd6Dh_6v74' WHERE id_api = 'tt0094889';

UPDATE Contenido SET id_tmdb = 859, descripcion = 'Francia, siglo XVIII. La perversa y fascinante Marquesa de Merteuil planea vengarse de su último amante con la ayuda de su viejo amigo el Vizconde de Valmont, un seductor tan amoral y depravado como ella. Una virtuosa mujer casada, Madame de Tourvel, de la que Valmont se enamora, se verá involucrada en las insidiosas maquinaciones de la marquesa.', trailer_url = 'https://www.youtube.com/watch?v=i_odB2FsJ4w' WHERE id_api = 'tt0094947';

UPDATE Contenido SET id_tmdb = 2706, descripcion = 'La serie se centraba en la vida de la familia Conner, una familia de clase baja trabajadora estadounidense, que vivía en la ficticia ciudad de Lanford, Illinois, con serias dificultades para llegar a fin de mes con los escasos sueldos de ambos progenitores, Roseanne y Dan. El hecho de representar en una serie por primera vez en Estados Unidos a una familia de clase baja en la que ambos padres trabajaban fuera de casa hizo que destacara entre público y crítica.3​4​ La serie plasmaba con realismo muchos problemas sociales que no se habían mostrado en las comedias familiares anteriores, tocando temas tabú hasta entonces en otras series de máxima audiencia, ya que trataba y bromeaba sobre la pobreza, el alcoholismo, el consumo de drogas, el sexo, la menstruación, los anticonceptivos, el embarazo de los adolescentes, la masturbación, la obesidad, el aborto, los problemas raciales, las clases sociales, la violencia doméstica o la homosexualidad.', trailer_url = NULL WHERE id_api = 'tt0094540';

UPDATE Contenido SET id_tmdb = 10651, descripcion = 'Quinta y última entrega de la saga policiaca que nace con ''Harry, el sucio'', protagonizada por el controvertido inspector de la policía de Los Ángeles, Harry Callahan. Una lista de ocho personas célebres circula por San Francisco y se están haciendo macabras apuestas, que consisten en adivinar quién de esas personas morirá primero. Uno de los nombres es el del famoso inspector Callahan, que investiga el caso.', trailer_url = 'https://www.youtube.com/watch?v=n41u5nOsuBM' WHERE id_api = 'tt0094963';

UPDATE Contenido SET id_tmdb = 790, descripcion = 'Desde Inglaterra hasta Egipto, acompañado por sus elegantes colaboradores de confianza, el inteligente y excéntricamente refinado detective belga Hércules Poirot se enfrenta a una serie de engaños de primera clase.', trailer_url = 'https://www.youtube.com/watch?v=_4ypEmJlfn8' WHERE id_api = 'tt0094525';

Al final, este caso puede tener que ser puesto como el que se escapó.', 51, '1991-02-10');

UPDATE Contenido SET id_tmdb = 9540, descripcion = 'Historia de dos gemelos idénticos, el encantador Elliot y el introvertido Beverly. Son las caras opuestas de una misma personalidad: comparten las mismas costumbres, el mismo apartamento y la misma mujer. Pero, cuando entra en sus vidas una mujer especial, el vínculo que une a los gemelos, se ve, por primera vez, amenazado. Y esta amenaza se traduce en el descenso a un abismo de perversión, drogas y locura.', trailer_url = 'https://www.youtube.com/watch?v=-ZHbu3msmes' WHERE id_api = 'tt0094964';

UPDATE Contenido SET id_tmdb = 562, descripcion = 'John McClane, un duro policía neoyorquino, acude a Los Angeles para pasar unos días de vacaciones con sus hijos y su esposa Holly. En el transcurso de la fiesta navideña que la empresa de Holly da en el moderno edificio Nakatoni, éste es asaltado por un supuesto grupo terrorista liderado por un megalómano llamado Hans Gruber.', trailer_url = 'https://www.youtube.com/watch?v=4Wi28Vsi_ZU' WHERE id_api = 'tt0095016';

UPDATE Contenido SET id_tmdb = 10141, descripcion = 'Lawrence Jamieson (Caine), seductor profesional que opera en la Riviera francesa, donde estafa a mujeres ricas, observa con desagrado cómo lo imita Freddy Benson (Martin), un advenedizo que pone en peligro su agradable y fácil modo de ganarse la vida. La competencia entre ambos dará lugar a las más disparatadas aventuras. Divertido filme de timadores.', trailer_url = 'https://www.youtube.com/watch?v=jb8ialk-J4c' WHERE id_api = 'tt0095031';

UPDATE Contenido SET id_tmdb = 623, descripcion = 'Un grupo de delincuentes organizan un plan para robar una valiosa colección de diamantes en la joyería Hatton Gardens de Londres. Entre ellas se encuentra la encantadora Wanda, que va a intentar un doble juego para quedarse ella con el botín. Lo malo es que sólo George, el jefe de la banda, sabe dónde están escondidas las joyas, pero ha sido encarcelado.', trailer_url = 'https://www.youtube.com/watch?v=0WTwVpEEMps' WHERE id_api = 'tt0095159';

UPDATE Contenido SET id_tmdb = 10675, descripcion = 'La asistencia a una conferencia en París le brinda al doctor Richard Walken y a su esposa la oportunidad de revivir su luna de miel. Pero, nada más instalarse en la habitación del hotel, su mujer desaparece misteriosamente. Completamente solo, en un país desconocido cuyo idioma ignora, Walken la buscará desesperadamente. La única pista que tiene es un número de teléfono apuntado en una caja de cerillas, pero, a partir de ahí, la trama se irá complicando hasta convertirse en una auténtica pesadilla.', trailer_url = 'https://www.youtube.com/watch?v=lZ397XS9r1c' WHERE id_api = 'tt0095174';

UPDATE Contenido SET id_tmdb = 175, descripcion = 'Jacques Mayol es un joven francés con un talento especial para el buceo, y ayuda al profesor Lawrence en sus experimentos marinos. Cuando era niño y vivía en una pequeña población griega junto a su gran amigo Enzo Molinari, ahora campeón de buceo en apnea, Jacques perdió a su padre, que trabajaba como buzo, pero a pesar de ello ama al mar por encima de todo. Nada de lo que tiene o consigue en la vida le llena tanto como estar bajo el agua.', trailer_url = 'https://www.youtube.com/watch?v=LSsByl32CRc' WHERE id_api = 'tt0095250';

UPDATE Contenido SET id_tmdb = 10281, descripcion = 'Desde que el maníaco homicida Jason Voorhees quedó atrapado en unas cadenas al fondo del lago Crystal, el campamento de verano más cercano no ha sufrido ningún altercado... ni asesinatos. Pero una de las campistas, Tina Shepherd, puede ver el futuro y hacer levitar objetos. Su médico conoce los peligros de la telequinesia, pero tiene más interés en aprovecharse de ella que en ayudarla. Y ahora es demasiado tarde. Sin querer, Tina ha liberado a Jason de su tumba acuosa, y el baño de sangre está a punto de empezar', trailer_url = 'https://www.youtube.com/watch?v=7AyRUWJriuY' WHERE id_api = 'tt0095179';

UPDATE Contenido SET id_tmdb = 12144, descripcion = 'Aclamada película de animación que narra las aventuras de unos pequeños dinosaurios en su viaje por alcanzar el Gran Valle, el único sitio de la tierra que todavía no ha sido alcanzado por una plaga devastadora', trailer_url = 'https://www.youtube.com/watch?v=4BInhb4GkG8' WHERE id_api = 'tt0095489';

UPDATE Contenido SET id_tmdb = 2617, descripcion = 'Dos familias de carácter muy distinto van a pasar una semana de descanso en medio de la Naturaleza, pero lo que parecía que iban a ser unas apacibles vacaciones se convierte en un cúmulo de conflictos que desembocan en las situaciones más cómicas.', trailer_url = 'https://www.youtube.com/watch?v=gpP_l-atlT4' WHERE id_api = 'tt0095253';

UPDATE Contenido SET id_tmdb = 11357, descripcion = 'Michael Myers, un psicópata que mató a dieciséis personas, acabó siendo capturado por su propio médico, el doctor Lomis. Tras pasar diez años encarcelado en una prisión de máxima seguridad, Myers es trasladado, en estado catatónico, al Instituto Mental de Richmond. Pero inexplicablemente se vuelve a escapar con el fin de asesinar a su único familiar vivo, su sobrina Jamie Lloyd. De nuevo el doctor Lomis intentará atraparlo.', trailer_url = 'https://www.youtube.com/watch?v=27PbiWvVyUA' WHERE id_api = 'tt0095271';

UPDATE Contenido SET id_tmdb = 9064, descripcion = 'Kirsty Cotton acaba recluida en un sanatorio donde intenta olvidar la pesadilla vivida con la muerte de sus padres. Sin embargo, allí coincide con el siniestro Doctor Channard, quien encuentra en la joven la pieza que necesita para llegar al éxito en sus intentos de encontrar la puerta a una dimensión oculta.', trailer_url = 'https://www.youtube.com/watch?v=WdiWUPOYL-k' WHERE id_api = 'tt0095294';

UPDATE Contenido SET id_tmdb = 1632, descripcion = 'En 1964, en un pueblo sureño, donde el racismo está profundamente arraigado y el Ku Klux Klan sigue celebrando sus ritos y reuniones, tres activistas defensores de los derechos humanos desaparecen sin dejar rastro. Dos agentes del FBI, de caracteres muy diferentes, se harán cargo de la investigación. Allí chocarán con un comisario racista.', trailer_url = 'https://www.youtube.com/watch?v=0nxToB95XJg' WHERE id_api = 'tt0095647';

UPDATE Contenido SET id_tmdb = 12477, descripcion = 'Verano de 1945. La aviación estadounidense somete las ciudades japonesas a continuos ataques aéreos. En uno de ellos, una incursión con bombas incendiarias convierte la ciudad de Kōbe en un infierno humeante, para los dos protagonistas (Seita, de 14 años, y su hermanita Setsuko, de 5). El joven Seita y su pequeña hermana Setsuko son hijos de un oficial de la marina japonesa. Durante la Segunda Guerra Mundial, ambos viven con su madre, pero un día, tras un bombardeo, ellos se retrasan y no consiguen llegar al búnker donde ella los espera.', trailer_url = 'https://www.youtube.com/watch?v=3YeP-UMHVaE' WHERE id_api = 'tt0095327';

UPDATE Contenido SET id_tmdb = 16296, descripcion = 'Deb y Mike ven caer un meteorito en el bosque. Cuando se acercan a investigar descubren que se trata de una carpa de circo llena de payasos asesinos. Después de huir de ellos por los pelos, acuden a la comisaría donde chocan con la incredulidad de Kirk, un viejo policía antipático. Sin embargo, ante su insistencia, consiguen la ayuda de Dave, un amigo de la infancia de Deb, que les ayuda en este surrealista caso. Mientras, la población sufre los hilarantes ataques de los payasos...', trailer_url = 'https://www.youtube.com/watch?v=ETiSMS4i1as' WHERE id_api = 'tt0095444';

UPDATE Contenido SET id_tmdb = 11051, descripcion = 'Jesús, un carpintero de Nazaret, decide atender la constante llamada de Dios. Pero cuando está a punto de completar su misión, debe hacer frente a la mayor de las tentaciones y realizar un sacrificio para salvar a todos los hombres.', trailer_url = 'https://www.youtube.com/watch?v=DCqn0gkwLEM' WHERE id_api = 'tt0095497';

UPDATE Contenido SET id_tmdb = 11216, descripcion = 'En un pequeño pueblo siciliano durante los años previos a la llegada de la televisión (justo al finalizar la Segunda Guerra Mundial) el joven Toto vivía fascinado por el cine. Toto trata de entablar amistad con Alfredo, el proyeccionista del cine local, una persona muy irritable pero con un gran corazón. Todos estos hechos se presentan en forma de nostálgicos recuerdos de Toto que ha crecido hasta convertirse en un cineasta de éxito, y que revive a su infancia cuando recibe la noticia de que Alfredo ha muerto.', trailer_url = 'https://www.youtube.com/watch?v=JMyVSD6OvO8' WHERE id_api = 'tt0095765';

UPDATE Contenido SET id_tmdb = 9013, descripcion = 'Un ex-policía de Chicago, que se dedica a capturar forajidos, recibe una oferta de cien mil dólares a cambio de encontrar a un contable que se ha fugado con dinero de la mafia. A primera vista, parece un trabajo sencillo, pero resulta que hay otro cazador de recompensas que busca al mismo individuo.', trailer_url = 'https://www.youtube.com/watch?v=Geo_tNuNgD8' WHERE id_api = 'tt0095631';

UPDATE Contenido SET id_tmdb = 380, descripcion = 'Charlie Babbitt, un joven sin corazón, espera recibir una considerable herencia tras la muerte de su padre, del que estaba distanciado. Sin embargo, alguien a quien Charlie no ha tenido en absoluto en cuenta, su hermano mayor Raymond, recluido en una institución medica, recibe toda la fortuna del testamento. Raymond es un autista con capacidad mental limitada en algunos aspectos, pero con dotes de genio en otros.', trailer_url = 'https://www.youtube.com/watch?v=wwmctS4nldM' WHERE id_api = 'tt0095953';

UPDATE Contenido SET id_tmdb = 4203, descripcion = 'Pepa e Iván son actores de doblaje. Él es un mujeriego empedernido y, después de una larga relación, rompe con Pepa: le deja un mensaje en el contestador pidiéndole que le prepare una maleta con sus cosas. Al quedarse sola, Pepa no soporta vivir en una casa llena de recuerdos y decide alquilarla. Mientras espera que Iván vaya a recoger la maleta, la casa se le va llenando de gente extravagante de la que aprenderá muchas cosas sobre la soledad y la locura.', trailer_url = 'https://www.youtube.com/watch?v=phcJmTvhzus' WHERE id_api = 'tt0095675';

UPDATE Contenido SET id_tmdb = 10131, descripcion = 'Freddy Krueger vuelve a la vida después de su aparente muerte en la entrega anterior y comienza a matar a los chicos que viven en Elm Street. Pero, Kristen, capaz de atraer a los demás dentro de sus sueños, le concede este poder especial a su amiga Alice. Sin embargo, ésta se da cuenta de que Freddy está sacando partido a este extraño poder.', trailer_url = 'https://www.youtube.com/watch?v=8MAAASH1n9M' WHERE id_api = 'tt0095742';

UPDATE Contenido SET id_tmdb = 37136, descripcion = 'Después de que su compañero Nordberg fuera tiroteado por una banda de narcotraficantes, el incompetente teniente Frank Drebin busca al jefe de la organización para vengarse. Sospecha del magnate naviero Vincent Ludwig, pero no tiene pruebas para inculparlo. Tendrá incluso que enfrentarse a una alcaldesa, que trata de obstaculizar su investigación. Sin embargo, Drebin consigue la inesperada ayuda de Jane Spencer, una antigua novia de Ludwig.', trailer_url = 'https://www.youtube.com/watch?v=PACTQutbow4' WHERE id_api = 'tt0095705';

UPDATE Contenido SET id_tmdb = 12233, descripcion = 'Un gatito huérfano llamado Oliver se une a Fagin y a su banda de ladronzuelos con Dodger, un maestro moviéndose por la ciudad, y el simpático chihuahua Tito. Un buen día, el pequeño Oliver deja las calles al ser adoptado por Jenny, una niña rica que se lo lleva a su casa, donde vivirá con todas las comodidades. Pero cuando Jenny es secuestrada por el malvado jefe de Fagin y su terrorífico doberman, Oliver comprobará el valor de la verdadera amistad al ver cómo toda la banda se pone en marcha para rescatarla. Adaptación animada y muy libre de "Oliver Twist", de Charles Dickens.', trailer_url = 'https://www.youtube.com/watch?v=np9kVcBLV18' WHERE id_api = 'tt0095776';

UPDATE Contenido SET id_tmdb = 1370, descripcion = 'Cuando descubre que el coronel Trautman ha caído en manos soviéticas en Afganistán, Rambo regresa al servicio para intentar liberar a su amigo. Después de contactar a la resistencia afgana, entra en la zona sitiada por las tropas enemigas.', trailer_url = 'https://www.youtube.com/watch?v=6NsyftiMwO4' WHERE id_api = 'tt0095956';

UPDATE Contenido SET id_tmdb = 8740, descripcion = 'Rex y Saskia son una pareja de holandeses de vacaciones en Francia. En una gasolinera, Saskia desaparece sin dejar rastro. Rex dedica tres años de su vida a intentar encontrar a su novia sin éxito. Un día empieza a recibir postales de alguien que promete revelarle qué le pasó a Saskia. El supuesto secuestrador, un tipo llamado Raymond Lemorne, es un personaje escalofriante a quien Rex sigue la corriente en su obsesión de conocer la verdad sobre la desaparición de su amada. Y la verdad, quizá, sea más siniestra de lo que él nunca se atrevió a imaginar...', trailer_url = 'https://www.youtube.com/watch?v=KlO2oIieI44' WHERE id_api = 'tt0096163';

UPDATE Contenido SET id_tmdb = 9604, descripcion = 'Danko, un duro policía soviético, recibe la orden de viajar a los Estados Unidos en busca de unos delincuentes de su país que están introduciendo droga en la URSS. Cuando llega a Chicago descubre que debe trabajar junto a un agente americano de la brigada de narcóticos.', trailer_url = 'https://www.youtube.com/watch?v=qIzVcJXnrQM' WHERE id_api = 'tt0095963';

