UPDATE Contenido SET id_tmdb = 8392, descripcion = 'Dos chicas jóvenes, Mei y Satsuki, se mudan a una nueva casa cerca del hospital en el que se encuentra su madre. En el patio junto a la casa, existe un gran árbol que es el hogar de tres Totoros, dioses de la selva. Poco después, reciben noticias desde el hospital de que su madre no puede venir a casa como había prometido, por lo que Mei (la más joven) se escapa para ir a visitarla. Satsuki tiene que recurrir a un Totoro para ayudar a encontrarla.', trailer_url = 'https://www.youtube.com/watch?v=BjeBG8Xrci8' WHERE id_api = 'tt0096283';

UPDATE Contenido SET id_tmdb = 9647, descripcion = 'La desbordante alegría de las fiestas de Nochebuena va a hacer que Frank Cross sufra unas visiones fantasmagóricas en esta divertida sátira de “Un Cuento de Navidad” de Charles Dickens. Cross, que ha hecho una carrera meteórica desde lo más recóndito del departamento de envíos de una cadena de TV hasta la presidencia, es tacaño, desagradable, ingrato, implacable y con un cruel sentido del humor, cualidades idóneas para un miserable de hoy en día. Antes de que la noche termine, será visitado por un desconcertante taxista neoyorquino del pasado, un hada del presente un tanto estrafalaria y, finalmente, un sádico, enorme y descabezado mensajero del futuro.', trailer_url = 'https://www.youtube.com/watch?v=3YjrsSEEreY' WHERE id_api = 'tt0096061';

UPDATE Contenido SET id_tmdb = 8337, descripcion = 'Un trabajador encuentra ocasionalmente unas gafas que permiten ver a las personas en su aspecto auténtico, así descubrirá que importantes personajes de la política y social son en realidad extraterrestres. Durante su particular cruzada podrá observar como esta raza alienígena ha llenado el mundo de mensajes subliminales que pretenden convertir a los humanos en una especie esclava.', trailer_url = 'https://www.youtube.com/watch?v=vSVQ975eTBI' WHERE id_api = 'tt0096256';

UPDATE Contenido SET id_tmdb = 9493, descripcion = 'Dos gemelos que vinieron al mundo por un experimento de carácter científico se encuentran al cabo de los años, tras haber pasado la mayor parte de sus vidas separados. Una vez juntos tratan de encontrar a su madre que según parece reside cerca de la frontera de México. El viaje hasta allí será aprovechado por uno de ellos para entregar una valiosa mercancía.', trailer_url = 'https://www.youtube.com/watch?v=2J6-luztpxY' WHERE id_api = 'tt0096320';

UPDATE Contenido SET id_tmdb = 856, descripcion = 'Hollywood, 1947. Eddie Valiant, un detective de poca monta, ha sido contratado para encontrar pruebas que demuestren que Marvin Acme, magnate del negocio de los artículos de broma y dueño de Toontown, está rondando a Jessica Rabbit, mujer fatal y esposa de la superestrella del Marron Cartoon, Roger Rabbit. Cuando Acme aparece asesinado, todas las pruebas apuntan a Roger, y el siniestro y ambicioso Juez Doom está decidido a condenarlo como sea. Roger suplica a Valiant que le ayude a encontrar al verdadero culpable, pero el asunto se irá complicando a medida que Eddie va descubriendo, escándalo tras escándalo, que la propia existencia de Toontown corre peligro.', trailer_url = 'https://www.youtube.com/watch?v=XEIJpS26aAw' WHERE id_api = 'tt0096438';

UPDATE Contenido SET id_tmdb = 847, descripcion = 'Cuento medieval con brujas, enanos y poderes mágicos. En las mazmorras del castillo de la malvada reina hechicera Bavmorda, una prisionera da a luz una niña que, de acuerdo a una antigua profecía, pondrá fin al reinado de la hechicera. La comadrona salva a la niña de la ira de Bavmorda, pero se ve obligada a arrojar su cuna al río cuando es alcanzada por sus perros de presa. La corriente le hace alcanzar un pueblo de enanos en donde es adoptada por el valiente Willow.', trailer_url = 'https://www.youtube.com/watch?v=9KhFp9fqrHc' WHERE id_api = 'tt0096446';

UPDATE Contenido SET id_tmdb = 11967, descripcion = 'En una zona fronteriza con México, Tunstall contrata coo ayudantes para su granja a jóvenes, huidos o vagabundos, a quienes enseña y educa. Entre ellos hay uno con una gran puntería. Tunstall cuenta en el pueblo con competidores codiciosos que ponen trabas a sus negocios y matan por la espalda sin ningún temor a las consecuencias.', trailer_url = 'https://www.youtube.com/watch?v=2OAF9_lUryk' WHERE id_api = 'tt0096487';

UPDATE Contenido SET id_tmdb = 11974, descripcion = 'En un típico vecindario norteamericano de los suburbios llegan unos vecinos nuevos a instalarse al lado de la casa de Ray Peterson. Pero estos nuevos vecinos son realmente extraños: nadie los ha visto y por la noche se pueden escuchar extraños sonidos provenientes del sótano. Lo único que conocen es su apellido: los Klopeks. Un día Walter, un anciano del vecindario, desaparece y todos comienzan a sospechar de ellos.', trailer_url = 'https://www.youtube.com/watch?v=cJ7bZpwzNfg' WHERE id_api = 'tt0096734';

UPDATE Contenido SET id_tmdb = 4327, descripcion = 'Serie que a través de numerosos sketches narra las desventuras de un peculiar y humorístico personaje, Mr. Bean, un adulto de mente profundamente simple al que cualquier tarea, por sencilla que sea, le supone una extraordinaria labor que siempre se le complica hasta extremos insospechadamente divertidos.', trailer_url = 'https://www.youtube.com/watch?v=1a7CzFpZtUo' WHERE id_api = 'tt0096657';

UPDATE Contenido SET id_tmdb = 165, descripcion = 'Aunque a Marty McFly todavía le falta tiempo para asimilar el hecho de estar viviendo dentro de la familia perfecta gracias a su anterior viaje en el tiempo, no le queda ni espacio para respirar cuando su amigo Doc aparece de improviso con la máquina del tiempo (mucho más modernizada), e insta a que le acompañen él y su novia a viajar al futuro para solucionar un problema con la ley que tendrá uno de sus futuros hijos. En la tremenda vorágine futurista, con todo lo que ello conlleva, del Hill Valley de 2015, la presencia de tales viajeros temporales causará un efecto mayor que el que iban a arreglar. Un almanaque deportivo y la posesión del secreto de la existencia de la máquina del tiempo por parte del siempre villano Biff Tannen, serán los ingredientes que conjugarán una causa-efecto en el pasado, en el presente y en el propio futuro, que hará que Marty y Doc se tengan que emplear a fondo para poner fin a la catástrofe a la que les lleva el destino.', trailer_url = 'https://www.youtube.com/watch?v=F4TJ5-YVRdY' WHERE id_api = 'tt0096874';

UPDATE Contenido SET id_tmdb = 2756, descripcion = 'Un equipo de científicos de una instalación petrolífera es contratado por la marina norteamericana para llevar a cabo la operación de rescate de un submarino nuclear atrapado, en extrañas circunstancias, en el fondo del mar, justamente al borde de una grieta abisal de varios kilómetros de profundidad. Un grupo de las fuerzas especiales del ejército acompañará a los científicos. Muy pronto estos últimos empiezan a sospechar que lo que está sucediendo en las profundidades abisales es algo tan extraño que, en principio, escapa a su comprensión.', trailer_url = 'https://www.youtube.com/watch?v=7cCVYAcIIAo' WHERE id_api = 'tt0096754';

UPDATE Contenido SET id_tmdb = 14506, descripcion = '¿Quién es el Barón Munchausen?¿Un mentiroso?¿Un bribón?¿Un loco?¿O el más grande superhéroe que luchó y venció en los más disparatados combates?¿Será cierto que cabalgó por el aire en una bala de cañón, que acabó con un dragón de tres cabezas, que viajó a la luna y todo ello antes de desayunar...?', trailer_url = 'https://www.youtube.com/watch?v=ahKu6zCk73U' WHERE id_api = 'tt0096764';

UPDATE Contenido SET id_tmdb = 268, descripcion = 'Atormentado por haber visto morir a sus padres delante suyo, Bruce Wayne se enfunda cada noche en el traje de Batman, adopta la terrorífica forma de un murciélago y surca los tejados de Gotham City combatiendo el crimen y manteniendo a raya la corrupción de su ciudad. Pero esta vez Batman tendrá que enfrentarse a su más terrible enemigo, El Joker, que pretende someter a toda la ciudad bajo los deseos de su mente perturbada.', trailer_url = 'https://www.youtube.com/watch?v=EtI74GCT3IU' WHERE id_api = 'tt0096895';

UPDATE Contenido SET id_tmdb = 11497, descripcion = 'Todos los perros van al cielo... o al menos hasta ahora. A las puertas del cielo es donde se encuentra Charlie, un pastor alemán granuja y estafador, asesinado por su antiguo socio, el malvado Carafea, para hacerse con el control del negocio de apuestas ilegales más importante de Nueva Orleans. Con la inestimable ayuda de su fiel amigo Richie y de María, una niña huérfana que puede hablar con los animales, Charlie tendrá una oportunidad para demostrar que merece su entrada en el cielo.', trailer_url = 'https://www.youtube.com/watch?v=fhRvSKLbM-0' WHERE id_api = 'tt0096787';

UPDATE Contenido SET id_tmdb = 1648, descripcion = 'Bill y Ted, de diecisiete años, amigos inseparables y miembros de una banda de rock, sienten más interés por la música que por sus estudios. El día de su graduación está cerca y deben aprobar como sea el examen de Historia. Las cosas están difíciles para los chicos, sin embargo, la aparición de un personaje inesperado va a serles de crucial ayuda. Se trata de Rufus, un emisario del futuro, que les ofrece un alucinante viaje en el tiempo para conocer a algunos de los más importantes personajes de la historia.', trailer_url = 'https://www.youtube.com/watch?v=gxFxklxvE_w' WHERE id_api = 'tt0096928';

UPDATE Contenido SET id_tmdb = 11562, descripcion = 'Un médico neoyorquino decide tomar medidas desesperadas cuando su amante le amenaza con sacar a la luz su aventura si no se casa con ella. Cuando su hermano se ofrece para eliminar el problema, se enfrenta a un dilema moral. Paralelamente, a Clifford Stern le encargan hacer un documental sobre su cuñado Lester, un famoso productor de televisión que personaliza todo lo que Clifford desprecia.', trailer_url = 'https://www.youtube.com/watch?v=JBzlQ7bUtKk' WHERE id_api = 'tt0097123';

UPDATE Contenido SET id_tmdb = 207, descripcion = 'En un elitista y estricto colegio privado de Nueva Inglaterra, un grupo de alumnos descubrirá la poesía, el significado de "Carpe Diem" -aprovechar el momento- y la importancia de perseguir los sueños, gracias a un excéntrico profesor que despierta sus mentes por medio de métodos poco convencionales.', trailer_url = 'https://www.youtube.com/watch?v=S52E2aje2l0' WHERE id_api = 'tt0097165';

UPDATE Contenido SET id_tmdb = 4105, descripcion = 'Una pareja de policías de Nueva York viaja a Japón para entregar a un mafioso a la policía nipona, pero éste logra escapar. De modo obsesivo decide quedarse en Japón para capturarle, pero choca con las tradiciones del país.', trailer_url = 'https://www.youtube.com/watch?v=RBP-zNZyewo' WHERE id_api = 'tt0096933';

UPDATE Contenido SET id_tmdb = 2604, descripcion = 'Inspirada en la autobiografía de Ron Kovic. Segunda parte de la trilogía sobre Vietnam: muestra la historia de un joven que se alista como voluntario para ir a la guerra, convencido de que defender a su país es la mejor manera de demostrarle su amor. Pero sus convicciones cambiarán radicalmente cuando regrese como veterano de guerra, postrado en una silla de ruedas y atendido en un cochambroso hospital.', trailer_url = 'https://www.youtube.com/watch?v=75sZjnTWur0' WHERE id_api = 'tt0096969';

UPDATE Contenido SET id_tmdb = 925, descripcion = 'En uno de los barrios más humildes de Brooklyn, Bedford Stuyvesant, conviven atropelladamente varias familias de raza negra, algunos hispanos, una pareja de comerciantes vietnamitas y una familia de italoamericanos que tienen una pizzeria. Mookie, un chico que trabaja de repartidor de pizzas, es un testigo privilegiado de los personajes y de los hechos cotidianos que tienen lugar en el barrio, así como de las tensiones y las actitudes racistas de algunos de sus habitantes', trailer_url = 'https://www.youtube.com/watch?v=yVAD4fYRcvA' WHERE id_api = 'tt0097216';

UPDATE Contenido SET id_tmdb = 10142, descripcion = 'Durante la guerra de Vietnam, unos soldados americanos secuestran, violan y asesinan a una joven campesina inocente. El único soldado del pelotón que no ha participado en los hechos se siente, sin embargo, cómplice del crimen, y amenaza con denunciarlo a sus superiores. Por eso se convierte en el objetivo de sus propios compañeros, liderados por un psicopático sargento.  Basada en una historia real, aparecida en un periódico americano, la película reflexiona sobre el horror de la guerra y la vida de los combatientes, así como también de la propia naturaleza humana ante situaciones límite. La cinta se beneficia, además, de un inesperado duelo interpretativo entre el siempre espléndido Sean Penn y Michael J. Fox, en uno de los papeles más dramáticos de su carrera.', trailer_url = 'https://www.youtube.com/watch?v=2S5uKG0uCLo' WHERE id_api = 'tt0097027';

UPDATE Contenido SET id_tmdb = 10493, descripcion = 'John y Rae deciden hacer un viaje en su pequeño yate de vela para intentar olvidar la muerte de su hijo en un accidente. Pero la travesía se ve interrumpida cuando divisan un bote neumático que escapa de una goleta. El único ocupante del bote, un asustado joven, les explica que es el único superviviente de una intoxicación alimentaria que ha acabado con toda la tripulación.', trailer_url = 'https://www.youtube.com/watch?v=SkqZd3h3f2U' WHERE id_api = 'tt0097162';

UPDATE Contenido SET id_tmdb = 10835, descripcion = 'Sin abandonar su particular estilo que combina el melodrama al más puro estilo Douglas Sirk con la violencia de Peckinpah, el director asiático John Woo consigue su obra maestra dentro del género de acción "made in Hong Kong": una violencia desatada irrumpe tras momentos de calma.', trailer_url = 'https://www.youtube.com/watch?v=bdLwJ2-zxDA' WHERE id_api = 'tt0097202';

UPDATE Contenido SET id_tmdb = 9665, descripcion = 'A principios de la Guerra de Secesión, el ejército del norte se mostraba reticente a dar armas a los negros. El heroico comportamiento del regimiento de Massachusetts, formado por soldados afroamericanos y oficiales blancos, resultó decisivo para que la Unión abriera las puertas a 180.000 soldados negros.', trailer_url = 'https://www.youtube.com/watch?v=-OS-OE1EcHI' WHERE id_api = 'tt0097441';

UPDATE Contenido SET id_tmdb = 403, descripcion = 'Miss Daisy (Jessica Tandy), una antipática profesora jubilada de 72 años, decide comprarse un coche. Su hijo, temiendo un posible caos circulatorio o, peor aún, un accidente, contrata a un chófer negro para que conduzca el vehículo. Al principio, la anciana y el tranquilo conductor no se llevan demasiado bien.', trailer_url = 'https://www.youtube.com/watch?v=p_gi28yWLtM' WHERE id_api = 'tt0097239';

UPDATE Contenido SET id_tmdb = 2323, descripcion = 'Un granjero de Iowa (Kevin Costner), casado y con una hija, tiene un día una experiencia sobrenatural: una misteriosa voz le ordena construir en sus tierras de cultivo un campo de béisbol para que las viejas glorias de ese deporte bajen del cielo y vuelvan a jugar...', trailer_url = 'https://www.youtube.com/watch?v=-jUOGhUqGdk' WHERE id_api = 'tt0097351';

UPDATE Contenido SET id_tmdb = 11361, descripcion = 'Michael Myers, el psicópata asesino ha vuelto a sobrevivir a las heridas de bala después de la persecución policial y, obsesionado por la venganza, continua buscando a su pequeña sobrina para asesinarla. Jamie ha sido hospitalizada y debido a un shock traumático ha perdido la capacidad del habla. Sin embargo ha desarrollado un vínculo telepático con su tío Michael y sabe que sigue vivo y que la está buscando para vengarse.', trailer_url = 'https://www.youtube.com/watch?v=ilHM_qpy-zM' WHERE id_api = 'tt0097474';

UPDATE Contenido SET id_tmdb = 89, descripcion = 'En 1938, dos años después de encontrar el Arca de la Alianza, Indiana Jones es convencido por un millonario para que lo ayude a encontrar el Santo Grial antes de que caiga en manos del ejército nazi. Sin embargo, el verdadero motivo para involucrarse es encontrar a su padre, el doctor Henry Jones, con quien ha mantenido una fría relación desde su juventud y que ha desaparecido mientras seguía la pista del tesoro bíblico.', trailer_url = 'https://www.youtube.com/watch?v=5YbMpOOonJs' WHERE id_api = 'tt0097576';

UPDATE Contenido SET id_tmdb = 10283, descripcion = 'Jason ha escogido como víctimas a un grupo de escolares que se encuentra en Crystal Lake. Tras una primera masacre, decide ir a Manhattan para acabar con los supervivientes de su primera embestida', trailer_url = 'https://www.youtube.com/watch?v=PkC417SQKao' WHERE id_api = 'tt0097388';

UPDATE Contenido SET id_tmdb = 10495, descripcion = 'El joven karateka Daniel Larusso libra su batalla mas difícil cuando el malvado Kreese le arrastra a una complicada situacion, al obligarle a defender su título de campeón del torneo del Valley. Su maestro Miyagi no está de acuerdo y el joven rompe con él. Daniel tendra un nuevo profesor, que más que como karateka realmente le entrena como si fuera un asesino. Cuando Daniel comprende que el kárate sólo debe usarse para defender el honor y la vida, regresa a las enseñanzas de su viejo maestro.', trailer_url = 'https://www.youtube.com/watch?v=RjKac-JPchs' WHERE id_api = 'tt0097647';

UPDATE Contenido SET id_tmdb = 2978, descripcion = 'Han pasado cinco años desde que los Cazafantasmas entraron por última vez en acción. El doctor Peter Venkman, notable parapsicólogo de persuasivos encantos, ha quedado relegado a maestro de ceremonias de un programa de televisión donde se discuten fenómenos psíquicos. Ray Stantz y su colega Winston Zeddemore se ganan la vida entreteniendo a niños en fiestas infantiles, y el mago tecnológico Egon Spengler continúa sus investigaciones sobre los efectos de las emociones humanas en el campo de energía psicomagnética. La relación de Dana Barrett con Venkman se disolvió; ella se casó con otro hombre y tuvo un hijo, pero el matrimonio fracasó. Ahora Dana vive sola en Nueva York, criando a Oscar, su bebé de ocho meses, y trabajando como restauradora de cuadros en el Museo de arte de Manhattan, junto a un excéntrico experto en pinturas del periodo romántico, Janosz Poha. Todo parece normal hasta que el cochecito de Oscar rueda por sí solo y se mete entre el peligroso tráfico de la ciudad.', trailer_url = 'https://www.youtube.com/watch?v=NOuJIkbvfvA' WHERE id_api = 'tt0097428';

UPDATE Contenido SET id_tmdb = 9354, descripcion = 'Wayne Szalinski es un científico e inventor que desarrolla una máquina que permite encoger el tamaño de los objetos. Una pelota de béisbol activa accidentalmente la máquina sobre sus hijos, que vivirán una auténtica aventura intentando atravesar el césped del jardín hasta la casa, convertido ahora en una auténtica "jungla" para ellos.', trailer_url = 'https://www.youtube.com/watch?v=cN19AazIWLk' WHERE id_api = 'tt0097523';

UPDATE Contenido SET id_tmdb = 2640, descripcion = 'Un grupo de cuatro estudiantes, consideradas como las chicas más populares de su escuela secundaria, cometen todo tipo de crueldades con sus compañeras y compañeros. Una de estas chicas, Verónica Sawyer (Winona Ryder), empieza a darse cuenta de que lo que hacen no es bueno, pero le resulta difícil salir del grupo. Aliada con un nuevo chico que ha llegado a la escuela, logran matar a tres alumnos molestos, aunque en todos los casos aparecen como suicidas. Pronto, Verónica comprobará que su amigo es un psicópata.', trailer_url = 'https://www.youtube.com/watch?v=WE3_uwJC4NQ' WHERE id_api = 'tt0097493';

UPDATE Contenido SET id_tmdb = 10144, descripcion = 'Ariel es una sirena adolescente, hija de Tritón, el rey del mar. Desobedeciendo a su padre, visita la superficie y se enamora del príncipe Eric. Con la esperanza de encontrar a su amado, la sirenita cae inocentemente bajo los encantos de Úrsula, la bruja del mar, que la transforma en un ser humano. Pero la bruja tiene planes terribles para Ariel y su padre.', trailer_url = 'https://www.youtube.com/watch?v=ZGZX5-PAwR8' WHERE id_api = 'tt0097757';

UPDATE Contenido SET id_tmdb = 10222, descripcion = 'Cuando Tong Po, el sanguinario campeón de Kickboxing, deja paralítico a su hermano, Eric jura vengarse del hombre a quienes todos consideran invencible, aunque le cueste la vida.', trailer_url = 'https://www.youtube.com/watch?v=qTw0qobi58Q' WHERE id_api = 'tt0097659';

UPDATE Contenido SET id_tmdb = 9494, descripcion = 'Mollie (Kirstie Alley) se ha quedado embarazada de un hombre casado. Entonces decide criar sola a su hijo y buscar para él un padre perfecto. Pero el niño tiene sus propias opiniones al respecto, y no se priva de hacer todo tipo de comentarios sobre los posibles candidatos. Él quiere como padre al taxista (John Travolta) que le ayudó al nacer.', trailer_url = NULL WHERE id_api = 'tt0097778';

UPDATE Contenido SET id_tmdb = 709, descripcion = 'El agente 007 a la caza y captura de un peligroso narcotraficante latinoamericano, con implicaciones personales de por medio: el capo de la droga mató a un amigo suyo, y Bond desea vengarse.', trailer_url = 'https://www.youtube.com/watch?v=6gxc1RA4H04' WHERE id_api = 'tt0097742';

UPDATE Contenido SET id_tmdb = 942, descripcion = 'Una pareja de policías tiene como misión proteger a un individuo que va a testificar en contra de una organización de traficantes de droga. Las cosas se complican cuando uno de ellos decide iniciar la investigación por su cuenta sin comunicarlo a la comisaría.', trailer_url = 'https://www.youtube.com/watch?v=xGcCI8JWCic' WHERE id_api = 'tt0097733';

UPDATE Contenido SET id_tmdb = 9972, descripcion = 'Frank Leone está a punto de cumplir su condena de reclusión por un delito menor. Sin embargo a punto de ser liberado, Warden Drumgoole se hace cargo de la prisión. Drumgoole fue reasignado a tan infernal presidio después de que su administración fuera públicamente puesta en entredicho por Leone, y ahora él se encargará de que nunca vuelva a ver la luz del día.', trailer_url = 'https://www.youtube.com/watch?v=57VxLjrShUI' WHERE id_api = 'tt0097770';

UPDATE Contenido SET id_tmdb = 10161, descripcion = 'Christy Brown es un enfermo de parálisis cerebral, nacido en el seno de una numerosa y mísera familia irlandesa. Su madre es la única que lo ve como un chico con talento y sensibilidad. Con el tiempo, Christy se revela como un irascible pero talentoso escritor y pintor, que utiliza su pie izquierdo -la única parte de su cuerpo que tiene motricidad- como instrumento.', trailer_url = 'https://www.youtube.com/watch?v=ckxjGhC90V0' WHERE id_api = 'tt0097937';

UPDATE Contenido SET id_tmdb = 16859, descripcion = 'Nicky no es una niña como otra cualquiera porque es aprendiz de bruja. Con solo 13 años y por tradición del oficio que está aprendiendo, la niña tiene que abandonar la casa de sus padres y buscar algún sitio donde sean necesarios sus servicios de bruja. Para emprender el viaje, Nicky se acompaña de su amigo Jiji y también de su gato; juntos, y sobre una escoba voladora, los amigos se instalan en un pueblecito que da al mar, donde la niña empezará a conocerse verdaderamente a sí misma.', trailer_url = 'https://www.youtube.com/watch?v=nu4OX6RKeLY' WHERE id_api = 'tt0097814';

UPDATE Contenido SET id_tmdb = 9942, descripcion = 'Los Indians de Cleveland son el peor equipo de béisbol de la liga nacional. Su nueva propietaria, una antigua show girl, quiere que acaben los últimos de la liga para poder trasladarse a Miami, pero ahora el equipo empieza a ganar.', trailer_url = 'https://www.youtube.com/watch?v=E7ESB7xkJYU' WHERE id_api = 'tt0097815';

UPDATE Contenido SET id_tmdb = 5825, descripcion = 'Clark Griswold, movido por un generoso y sentimental espíritu navideño, quiere sorprender a toda su familia con una gran fiesta. La suerte no suele acompañarlo y esta vez no va a ser diferente... Una sucesión de disparatados desastres convertirán la esperadísima sorpresa de Clark en un verdadero caos.', trailer_url = 'https://www.youtube.com/watch?v=tLVd4ipC5Lc' WHERE id_api = 'tt0097958';

