UPDATE Contenido SET id_tmdb = 8913, descripcion = 'Louis Creed, su esposa y sus dos niños se instalan en una vivienda próxima a una carretera con mucho tráfico. Cerca de la casa hay un sendero que lleva a un cementerio de animales y también a un antiguo cementerio indio; según la leyenda, los que sean enterrados allí volverán a la vida. Cuando uno de los niños muere atropellado por un camión, Louis ldecide enterrarlo en el cementerio indio.', trailer_url = 'https://www.youtube.com/watch?v=jpjpUOXQZac' WHERE id_api = 'tt0098084';

UPDATE Contenido SET id_tmdb = 10135, descripcion = 'Dalton tiene un doctorado en Filosofía, pero ha optado por ganarse la vida como vigilante de locales de alterne, una profesión bastante bien remunerada. Contratado para mantener el orden en el Double Duce en Jasper, Missouri, resulta herido en su primera noche en el local y es atendido por "Doc" Clay, una bella doctora de la localidad. Enseguida se enamora de ella, pero hay otro hombre que se interpone entre ambos: Brad Wesley, un extorsionista y capo mafioso.', trailer_url = 'https://www.youtube.com/watch?v=xbN9m-1vIZc' WHERE id_api = 'tt0098206';

UPDATE Contenido SET id_tmdb = 2028, descripcion = 'Lloyd Dobler, un eterno optimista, busca conseguir el corazón de Diane Court, una inalcanzable belleza del instituto, además de una intachable estudiante. Todo el mundo se sorprende, incluido Lloyd, cuando ella demuestra que el sentimiento es recíproco. Pero el posesivo padre divorciado de Diane no aprueba esa relación, y hará falta algo más que el poder del amor para que consigan seguir juntos.', trailer_url = 'https://www.youtube.com/watch?v=Se_eSeEAoX0' WHERE id_api = 'tt0098258';

UPDATE Contenido SET id_tmdb = 456, descripcion = 'El día a día de una peculiar familia formada por Homer, Marge, Bart, Maggie y Lisa Simpson y otros divertidos personajes de la localidad norteamericana de Springfield. Homer, el padre, es un desastroso inspector de seguridad de una central nuclear. Marge, la madre, es un ama de casa acostumbrada a soportar a su peculiar familia. Bart, de diez años, intenta divertirse con travesuras de todo tipo. Lisa es la más inteligente de la familia, y Maggie, la más pequeña, es un bebé que todavía no habla, pero que juega un importante papel.', trailer_url = 'https://www.youtube.com/watch?v=jt14g4XydyY' WHERE id_api = 'tt0096697';

