UPDATE Contenido SET id_tmdb = 1412, descripcion = 'John, un abogado yuppie, con pocos escrúpulos, está casado con Ann, una mujer seria e introvertida. Ella, aunque muestra poco interés por el sexo, se siente segura de su matrimonio. John, en cambio, es un adicto al sexo y tiene una aventura con Cinthia, la extrovertida y desenfadada hermana de Ann. La llegada del enigmático Graham, un antiguo compañero de John en la universidad, alterará la vida de Ann', trailer_url = 'https://www.youtube.com/watch?v=6BMZrfINaUk' WHERE id_api = 'tt0098724';

UPDATE Contenido SET id_tmdb = 1920, descripcion = 'El excéntrico agente del FBI Dale Cooper llega a Twin Peaks, una pequeña población montañosa, para investigar el brutal asesinato de la joven y bella Laura Palmer, la chica más popular del instituto de la localidad. Con la ayuda del sheriff del pueblo, el amable Harry S. Truman, el agente Cooper comienza a interrogar a los habitantes del pueblo y va descubriendo poco a poco que muchos de ellos esconden oscuros y misteriosos secretos.', trailer_url = 'https://www.youtube.com/watch?v=rFuKtJjhBCQ' WHERE id_api = 'tt0098936';

