UPDATE Contenido SET id_tmdb = 6488, descripcion = 'Una pequeña población es atacada por una extraña variedad de araña extremadamente venenosa que ha sido transportada desde la selva amazónica hasta Estados Unidos. La araña se refugia en el granero de un joven médico que acaba de instalarse en el pueblo con su familia. El arácnido se reproduce y pronto comienza a morir gente en el pueblo. El médico decide investigar por su cuenta las causas de tan raras muertes.', trailer_url = 'https://www.youtube.com/watch?v=v7ZXhQIJFdc' WHERE id_api = 'tt0099052';

UPDATE Contenido SET id_tmdb = 11595, descripcion = 'Jack Cates vuelve a contar con la ayuda del exconvicto Reggie Hammond, esta vez para acabar con El Témpano, un despiadado capo de la droga que opera en la zona de la bahía de San Francisco.', trailer_url = 'https://www.youtube.com/watch?v=iKMpn9mTV_w' WHERE id_api = 'tt0099044';

UPDATE Contenido SET id_tmdb = 1400, descripcion = 'El cómico Jerry Seinfeld y sus excéntricos amigos (Constanza, Kramer y Elaine) viven en Nueva York y les pasan innumerables peripecias en esta genial comedia de situación donde la menor excusa sirve para regalarnos un delirante episodio. Batió todos los récords de audiencia que se pusieron por delante, y aún hoy en día sus reposiciones siguen contando con innumerables seguidores, no en vano "Seinfeld" es una verdadera leyenda de la televisión americana. "Media hora acerca de nada", así definió Jerry Seinfeld su teleserie cuando la presentó a los ejecutivos de la NBC, a comienzos de 1990. Contra todo pronóstico, ellos aceptaron. No en vano Seinfeld era ya por entonces uno de los cómicos más populares de Estados Unidos. ¿Su secreto? Sacar punta a las rutinas de cada día hasta convertirlas en reflexiones filosóficas dignas de figurar en un tratado sobre las grandezas y las miserias humanas.', trailer_url = 'https://www.youtube.com/watch?v=hQXKyIG_NS4' WHERE id_api = 'tt0098904';

