UPDATE Contenido SET id_tmdb = 11005, descripcion = 'A finales de los años sesenta, el doctor Malcolm Sayer, un neurólogo neoyorquino, decide utilizar un medicamento nuevo para tratar a sus pacientes de encefalitis letárgica, enfermedad que priva de las facultades motoras a las personas que la padecen hasta reducirlas a un estado vegetativo. Poco a poco empezará a manifestarse cierta mejoría en los pacientes, especialmente en Leonard Lowe.', trailer_url = 'https://www.youtube.com/watch?v=7exeVt7CaE4' WHERE id_api = 'tt0099077';

UPDATE Contenido SET id_tmdb = 196, descripcion = 'Marty McFly sigue en 1955 y su amigo Doc ha retrocedido al año 1885, la época del salvaje oeste. Éste le envía una carta donde comenta que la máquina del tiempo está averiada, y que es imposible repararla. Sin embargo no le preocupa estar atrapado en el pasado, pues allí es muy feliz trabajando de herrero aunque convive con malhechores. Pero Marty descubre una vieja tumba en la que lee que Doc murió en 1885 y, sin pensárselo dos veces, irá a rescatar a su amigo.', trailer_url = 'https://www.youtube.com/watch?v=ksIOV1xr9xI' WHERE id_api = 'tt0099088';

UPDATE Contenido SET id_tmdb = 11186, descripcion = 'Chucky ha vuelto. El famoso muñeco asesino de sonrisa satánica resucita en este nuevo episodio. A pesar de que en su última escapada quedó totalmente achicharrado, Chucky resurge de sus cenizas cuando una fábrica de juguetes decide reconstruirlo para acabar con la mala publicidad que la rodea. Chucky vuelve a estar entero y sigue la pista de su presa hasta una familia de acogida..', trailer_url = 'https://www.youtube.com/watch?v=YC93-07FYBc' WHERE id_api = 'tt0099253';

UPDATE Contenido SET id_tmdb = 1727, descripcion = 'Un hombre que vive con una nueva identidad acogido al sistema de protección de testigos es descubierto por su ex-novia, justo en el mismo momento en el que un criminal que acaba de salir de la cárcel trata de vengarse de él...', trailer_url = 'https://www.youtube.com/watch?v=CJmVVz8sT5U' WHERE id_api = 'tt0099141';

UPDATE Contenido SET id_tmdb = 581, descripcion = 'En torno a 1860, en vísperas de la Guerra de Secesión y a punto de terminar el periodo de colonización del Oeste (1785-1890), el teniente John J. Dunbar se dirige a un lejano puesto fronterizo que ha sido abandonado por los soldados. Su soledad lo impulsa a entrar en contacto con los indios sioux y, gracias a ello, conoce a ''En pie con el puño en alto'', una mujer blanca que fue adoptada por la tribu cuando era niña. Poco a poco, entre Dunbar y los sioux se establece una relación de respeto y admiración mutuos.', trailer_url = 'https://www.youtube.com/watch?v=g2P5QuLP7GE' WHERE id_api = 'tt0099348';

UPDATE Contenido SET id_tmdb = 9768, descripcion = 'Años cincuenta. Eisenhower es el Presidente de los Estados Unidos. En el ambiente musical domina el Rock. Wade "El lágrima" Walker, el chico más malo del instituto, es un joven irresistible cuya habilidad para llorar una sola lágrima vuelve locas a las chicas. Especialmente a Allison Vernon-Williams, una rica y bella jovencita que se siente irracionalmente atraída por este delincuente juvenil y su mundo de rock, coches rápidos y mujeres aún más rápidas.', trailer_url = 'https://www.youtube.com/watch?v=wkk5_7OH0kE' WHERE id_api = 'tt0099329';

UPDATE Contenido SET id_tmdb = 2119, descripcion = 'Cole Trickle es un joven temerario que busca en la emoción de pilotar un bólido la audacia que le haga perder todos los miedos. Trickle entra con buen pie en el complicado mundo de las carreras. Se sabe rodear de un buen equipo y cuenta además con la ayuda inestimable de Harry, un verdadero amigo que sabe estimular a la joven promesa hasta hacerle alcanzar la gloria.', trailer_url = 'https://www.youtube.com/watch?v=GcNRp8Tsg6I' WHERE id_api = 'tt0099371';

UPDATE Contenido SET id_tmdb = 9556, descripcion = 'Un joven y prometedor científico es víctima de un accidente en su laboratorio cuando unos delincuentes lo destruyen. Está al borde de la muerte, pero consigue sobrevivir a pesar de que queda en un estado lamentable. Utiliza sus descubrimientos sobre piel sintética en sí mismo y prepara su venganza contra los que le atacaron.', trailer_url = 'https://www.youtube.com/watch?v=W8oGHvO2RgU' WHERE id_api = 'tt0099365';

UPDATE Contenido SET id_tmdb = 1573, descripcion = 'Es Navidad. El policía del departamento de Los Angeles, teniente John McLane, espera en el aeropuerto de Dulles de Washington a que aterrice el avión en el que viaja su esposa. Mientras tanto, el coronel del ejército Stuart, un militar bien entrando, expulsado del congreso, junto con otros mercenarios profesionales, montan una base de operaciones cerca de dicho aeropuerto, con el objetivo de liberar a un dictador sudamericano derrocado, considerado el mayor traficante del mundo, y que dentro de 58 minutos aterrizará en Dulles en calidad de prisionero político. Stuart anula todos los sistemas que permiten aterrizar a los demás aviones, condenados a permanecer en el aire con el riesgo de agotárseles el combustible. Exige, además, que un Boeing 747 esté a su disposición para huir con el dictador una vez liberado, pero McClane intentará que no prospere...', trailer_url = 'https://www.youtube.com/watch?v=lBNPy3AOJrs' WHERE id_api = 'tt0099423';

UPDATE Contenido SET id_tmdb = 8592, descripcion = 'El mafioso Big Boy Caprice asesina a su rival Labios Manlis para hacerse con el control de la ciudad y quedarse con su chica, la cantante Suspiros Mahoney. El detective Dick Tracy se encargará de impedir que consiga sus propósitos. En esta guerra aparecerá un tercer personaje misterioso conocido como The Blank.', trailer_url = 'https://www.youtube.com/watch?v=-4rzqSsqaqA' WHERE id_api = 'tt0099422';

UPDATE Contenido SET id_tmdb = 162, descripcion = 'Érase una vez... un castillo donde vivía un inventor que dedicó parte de su vida a crear una criatura perfecta a la que llamó Edward. Pero el inventor murió de repente y dejó incompleta su creación, ya que en vez de dedos tenía unas horribles manos con hojas de tijera. El pobre Edward vivía sólo en el castillo hasta que una encantadora joven, que trabajaba para la firma Avon, lo llevó a su casa junto con su familia. Pero una criatura tan especial como Edward no estaba preparada para vivir en una ciudad tan extravagante y falsa como Suburbia.', trailer_url = 'https://www.youtube.com/watch?v=nfJPYIfT2-U' WHERE id_api = 'tt0099487';

UPDATE Contenido SET id_tmdb = 1551, descripcion = 'Cinco estudiantes de medicina deciden experimentar en ellos mismos lo que se esconde más allá de la muerte. Para ello fuerzan la paralización del corazón y el cerebro de cada uno hasta que los monitores que indican los signos vitales no muestren más que una línea horizontal. Tras esto, uno de los miembros procede a reavivar el cuerpo inerte. Tras el éxito de la primera de las experiencias se animan a permanecer cada vez más tiempo "muertos".', trailer_url = 'https://www.youtube.com/watch?v=7FlbnHrrLd8' WHERE id_api = 'tt0099582';

UPDATE Contenido SET id_tmdb = 242, descripcion = 'Michael Corleone, heredero del imperio de don Vito Corleone, intenta rehabilitarse socialmente y legitimar todas las posesiones de la familia negociando con el Vaticano. Después de luchar toda su vida se encuentra cansado y centra todas sus esperanzas en encontrar un sucesor que se haga cargo de los negocios. Vincent, el hijo ilegítimo de su hermano Sonny, parece ser el elegido.', trailer_url = 'https://www.youtube.com/watch?v=05bJF54X5-0' WHERE id_api = 'tt0099674';

UPDATE Contenido SET id_tmdb = 769, descripcion = 'Henry, un niño de trece años de Brooklyn, vive fascinado con el mundo de los gángsters. Su sueño se hace realidad cuando entra a formar parte de la familia Pauline, dueña absoluta de la zona, que lo educan como un miembro más de la banda convirtiéndole en un destacado mafioso.', trailer_url = 'https://www.youtube.com/watch?v=Shj-QWYDn_M' WHERE id_api = 'tt0099685';

UPDATE Contenido SET id_tmdb = 251, descripcion = 'Una pareja de enamorados ve truncada su felicidad cuando él es asesinado por un ladrón. La necesidad de salvar la vida a la chica hace que él permanezca en la Tierra en forma de fantasma, e intente advertirla del peligro que corre. Su único medio de comunicación es una alocada vidente.', trailer_url = 'https://www.youtube.com/watch?v=jWvUTmvaOyU' WHERE id_api = 'tt0099653';

UPDATE Contenido SET id_tmdb = 928, descripcion = 'Tras la muerte de su cuidador, un simpático Gremlin es llevado a un laboratorio donde se encuentra con su antiguo dueño. Debido a un despiste, el animalillo se moja, multiplicándose en temibles duendecillos que se apoderarán del rascacielos más moderno de Nueva York.', trailer_url = 'https://www.youtube.com/watch?v=oD8zcT4-TsY' WHERE id_api = 'tt0099700';

UPDATE Contenido SET id_tmdb = 771, descripcion = 'Kevin McAllister es un niño de ocho años, miembro de una familia numerosa, que accidentalmente se queda abandonado en su casa cuando toda la familia se marcha a pasar las vacaciones a Francia. Kevin aprende a valerse por sí mismo e incluso a protegerse de Harry y Marv, dos bribones que se proponen asaltar todas las casas cerradas de su vecindario. Cuando su madre Kate lo hecha en falta, realiza un pintoresco viaje de vuelta contra reloj a Chicago para recuperar a su hijo.', trailer_url = 'https://www.youtube.com/watch?v=dzdpqRGA1qc' WHERE id_api = 'tt0099785';

UPDATE Contenido SET id_tmdb = 1669, descripcion = 'Un submarino nuclear, bajo el mando de un prestigioso general de la Unión soviética, se interna en el Océano Atlántico con rumbo a los Estados Unidos. La CIA, que ignora si pretende atacarles o desertar de su país, encarga al agente Jack Ryan que se ponga en contacto con él para saber sus verdaderas intenciones. Entretenida cinta de suspense y acción. Fue la primera entrega de una saga sobre las aventuras de Jack Ryan, el brillante analista y agente de la inteligencia americana creado por Tom Clancy.', trailer_url = 'https://www.youtube.com/watch?v=kxL8uBmdulY' WHERE id_api = 'tt0099810';

