UPDATE Contenido SET id_tmdb = 7442, descripcion = 'Laura y Martin estuvieron casados durante cuatro años y parecían una pareja perfecta. Sin embargo, la realidad era muy distinta: Martin resultó ser un marido obsesivo y brutal que la maltrataba continuamente. La situación llegó a ser tan insostenible que Laura decidió simular su muerte para librarse de él y empezar una nueva vida con una nueva identidad. Sin embargo, cuando él se da cuenta del engaño, decide perseguirla para vengarse.', trailer_url = 'https://www.youtube.com/watch?v=c70tmkjg-TU' WHERE id_api = 'tt0102945';

UPDATE Contenido SET id_tmdb = 1541, descripcion = 'Thelma Dickinson, un ama de casa de vida vacía y anodina, está casada con un cretino detestable que la trata como a una niña. Por su parte, Louise Sawyer trabaja como camarera en una cafetería y sueña con que su novio Jimmy, que es músico, se case con ella. Un fin de semana deciden hacer un viaje juntas en el coche de Louise para alejarse de la mortal rutina de sus vidas y de todas sus frustraciones. Sin embargo, su escapada, que prometía ser divertida y, sobre todo, liberadora, acaba siendo una experiencia llena de episodios dramáticos.', trailer_url = 'https://www.youtube.com/watch?v=dZWffRsh_WI' WHERE id_api = 'tt0103074';

UPDATE Contenido SET id_tmdb = 1497, descripcion = 'El malvado Shredder tiene un único y perverso plan: acabar con los cuatro superhéroes Tortugas Ninja Mutantes, Raphael, Leonardo, Michelangelo y Donatello. Para ello, secuestra al profesor Jordan Perry, creador del "moco verde" que hace posible la mutación de las Tortugas. Poco después, Shredder aplica la preciada sustancia a dos criaturas que acaba de reclutar, convirtiéndolos en terribles e imponentes guerreros ninja que lucharán e intentarán terminar con los superhéroes. Sin embargo, éstos logran hacen frente al peligroso criminal, con la ayuda de su maestro Splinter, la elegante periodista April y el repartidor de pizzas Keno.', trailer_url = 'https://www.youtube.com/watch?v=bxn1dVeDFxQ' WHERE id_api = 'tt0103060';

UPDATE Contenido SET id_tmdb = 280, descripcion = 'Ha pasado once años desde que Sarah Connor fue marcada como objetivo para ser eliminada por un cyborg del futuro. Ahora su hijo John, el futuro líder de la resistencia, es el objetivo de un Terminator más moderno, más mortífero. Una vez más, la resistencia se las ha ingeniado para enviar un protector de vuelta al pasado para intentar salvar a John y a su madre Sarah.', trailer_url = 'https://www.youtube.com/watch?v=VQd38bFMoIg' WHERE id_api = 'tt0103064';

