UPDATE Contenido SET id_tmdb = 10276, descripcion = 'Bob Wiley (Bill Murray), un neurótico lleno de manías y fobias, frecuenta la consulta del psiquiatra Leo Marvin (Richard Dreyfuss). Harto de sus problemas, el médico se marcha de vacaciones con su familia a su chalet de verano a orillas de un lago. Pero, de manera inesperada, Bob se presenta allí. La situación llega a ser tan desesperante que Leo, completamente desquiciado, trama un plan para deshacerse de él.', trailer_url = 'https://www.youtube.com/watch?v=ptmP1lziJw4' WHERE id_api = 'tt0103241';

