UPDATE Contenido SET id_tmdb = 2098, descripcion = 'Bruce Wayne de día, Batman de noche. Junto a su inseparable aprendiz, Robin, Batman luchará por la estabilidad y bienestar de los habitantes de Gotham; protegiendo a la ciudad de villanos como Dos Caras, Joker, Harley Quinn y Pingüino.', trailer_url = 'https://www.youtube.com/watch?v=rrmUk2YUm14' WHERE id_api = 'tt0103359';

UPDATE Contenido SET id_tmdb = 4574, descripcion = 'Primera serie de animación basada en los cómics de Marvel, X-Men. La serie comienza con Júbilo, una adolescente que de pronto descubre tener poderes mutantes. Fue atacada por Centinelas y rescatada por los X-Men, y luego de conocerlos dejó a sus padres adoptivos y se fue con ellos, para aprender a controlar sus poderes y estar a salvo de los ataques de los Centinelas u otras organizaciones extremistas anti-mutantes.  La serie se enfoca también en el triángulo amoroso entre Cíclope, Jean y Wolverine, y la complicada relación entre Gambito y Rogue. Había una enorme cantidad de personajes invitados a lo largo de la serie provenientes de todo el Universo Marvel, pero sólo los mutantes se pueden considerar como tales. A excepción de Miss Marvel y el Capitán América en uno de los episodios finales, y Juggernaut dado su naturaleza mágica, todos los personajes no-mutantes que aparecían lo hacían sólo como cameos de breves segundos. En 2000, se estrenó una segunda serie animada llamada "X-Men Evolution", aunque no fue tan bien recibida como ésta, Spiderman: La serie animada o Batman: La serie animada. ', trailer_url = 'https://www.youtube.com/watch?v=gh0KJImjkqc' WHERE id_api = 'tt0103584';

Aparecen las lápidas de las tumbas de Cyclops (2032), Rogue (2033), Storm (2021) y Jubilee (2010).', 21, '1993-03-13');

