UPDATE Contenido SET id_tmdb = 763, descripcion = 'Un científico descubre en Skull Island un ejemplar muy extraño de mono rata al que acompaña una terrible maldición, según los nativos. El ejemplar es trasladado a Nueva Zelanda para su estudio. Por otra parte, Lionel es un joven que vive con su insoportable madre, que no aprueba la relación que acaba de comenzar con Paquita, la hija del tendero. Cuando los dos enamorados realizan una visita al zoológico, ella les vigila en secreto, y será mordida por el animal encontrado en la isla. Poco a poco, la madre de Lionel se va convirtiendo en una especie de zombie, sedienta de carne, y que convierte en zombie a todo el que ataca.', trailer_url = 'https://www.youtube.com/watch?v=Ytg1JFrI2AA' WHERE id_api = 'tt0103873';

UPDATE Contenido SET id_tmdb = 6114, descripcion = 'Antes de convertirse en vampiro, el conde Drácula era el príncipe Vlad, quien tras conocer la muerte de su prometida, vendió su alma al diablo. Cuatro siglos después, en Londres, encuentra a Mina, reencarnación de su amor perdido.', trailer_url = 'https://www.youtube.com/watch?v=cFSb5sQ0RTY' WHERE id_api = 'tt0103874';

UPDATE Contenido SET id_tmdb = 10206, descripcion = 'Buffy (Kristy Swanson) es una popular animadora del equipo de fútbol americano del Hemery High School en Los Angeles cuando es abordada por un hombre llamado Merrick Jamison-Smythe (Donald Sutherland), que la informa de que ella es la Cazadora, una joven elegida para tener habilidades especiales y destinada a luchar contra los vampiros. Ella admite que ha tenido sueños sobre Cazadoras anteriores y finalmente acepta lo que es. Junto a Pike (Luke Perry), un perdedor que se convierte en la "Dama en apuros", siendo rescatado por Buffy numerosas veces, y sobre el que siente cierta atracción sexual. Después de un corto entrenamiento, entra en conflicto con un Rey Vampiro local llamado Lothos (Rutger Hauer), quien ha asesinado a numerosas Cazadoras anteriores, y que poco después mata a Merrick.', trailer_url = 'https://www.youtube.com/watch?v=pnZkV_aR_9w' WHERE id_api = 'tt0103893';

UPDATE Contenido SET id_tmdb = 10086, descripcion = 'Un asesino en serie y ladrón es seguido a todas horas por un equipo de televisión que registra todas sus reflexiones para mostrarlas en un documental, al tiempo que el psicópata prosigue con sus criminales actividades.', trailer_url = 'https://www.youtube.com/watch?v=3HFuTY3HpV8' WHERE id_api = 'tt0103905';

UPDATE Contenido SET id_tmdb = 9529, descripcion = 'En la Universidad de Chicago la estudiante graduada Helen Lyle se da cuenta de la superstición prevaleciente que rodea la leyenda de Candyman (un fantasma con un gancho en vez de mano que aparecerá si su nombre se dice cinco veces en un espejo) entre los arrendatarios del Cabrini del proyecto Verde de Chicago. El profesor, oyendo hablar de la investigación de Helen, explica la base histórica para la leyenda y detalla cómo se cree que Candyman es el espíritu vengativo de un esclavo que fue mutilado por una chusma enloquecida cuando se lo acusó de violar a una mujer blanca. Cuando Helen prueba su confianza intelectual recitando el nombre de Candyman cinco veces, ella pone en movimiento una serie inevitable de eventos sobrenaturales, culminando en una serie de matanzas espantosas en las que Helen sostiene el arma del asesinato. Aunque ella es capturada por la policía, se pone en evidencia para Helen que Candyman está guiando su destino.', trailer_url = 'https://www.youtube.com/watch?v=CeLZMhkFTuU' WHERE id_api = 'tt0103919';

UPDATE Contenido SET id_tmdb = 11187, descripcion = 'Ocho años después del día en que creyó haber destruido al muñeco asesino, Andy Barclay cumple los dieciséis y entra en una academia militar. Mientras, el codicioso presidente de la empresa de juguetes Play Pals decide resucitar la popular línea de muñecos Good Guys. Cuando la cadena de montaje recrea el primer muñeco a partir de una masa de plástico derretido, el espíritu de Chucky regresa con renovadas intenciones de alcanzar su objetivo y vengarse de Andy.', trailer_url = 'https://www.youtube.com/watch?v=AHY0IfcRXHE' WHERE id_api = 'tt0103956';

UPDATE Contenido SET id_tmdb = 10435, descripcion = 'Biografía de Charles Chaplin. Chaplin pertenecía a una familia numerosa que se ganaba la vida en los teatros de mala muerte de Londres. Cuando su padre murió alcoholizado, su madre, enferma, tuvo que trabajar duramente para sacar adelante a la familia hasta que fue ingresada en un psiquiátrico. Chaplin entró entonces a trabajar en una compañía musical que hizo una gira por los Estados Unidos. Allí conoció al productor de cine Mack Sennett con el que firmó un contrato que le permitió demostrar su gran habilidad como cómico. Además de actuar, empezó a dirigir los filmes que protagonizaba y su personaje de entrañable vagabundo dio la vuelta al mundo.', trailer_url = 'https://www.youtube.com/watch?v=7tXo1S8c0hc' WHERE id_api = 'tt0103939';

UPDATE Contenido SET id_tmdb = 881, descripcion = 'El teniente Daniel Kaffee es un joven y prometedor abogado de la Marina que tiene una excelente reputación. Sus superiores le confían la defensa de dos marines acusados de asesinato. A primera vista, el caso no parece complicado. Pero cuando tenga que vérselas con el Coronel Nathan R. Jessup, comandante en jefe de la base de Guantánamo, saldrán a la luz nuevas pistas que harán que el caso adquiera dimensiones insospechadas.', trailer_url = 'https://www.youtube.com/watch?v=oYd-IIWFEL4' WHERE id_api = 'tt0104257';

UPDATE Contenido SET id_tmdb = 11386, descripcion = 'La organización terrorista IRA secuestra a un soldado británico. Durante su confinamiento, el prisionero entabla amistad con Fergus, uno de los terroristas, y le pide que, si lo matan, vaya a ver a su novia. Más tarde, Fergus, huyendo de sus compañeros, acude al pub donde trabaja Dil, la novia del soldado británico.', trailer_url = 'https://www.youtube.com/watch?v=FRxmK7Q3yF4' WHERE id_api = 'tt0104036';

UPDATE Contenido SET id_tmdb = 9374, descripcion = 'Madeline Ashton es una prestigiosa actriz cuya fama empieza a declinar a causa de la edad. Está casada con Ernest, un maquillador de cadáveres alcohólico al que Madeline ha arruinado la vida. Madeline se casó con Ernest tras robárselo a Helen Sharp, una antigua compañera de colegio que se ha convertido en una mujer obesa que vive con la fantasía de eliminar a Madeline y recuperar a su antiguo novio. Helen pronto se da cuenta de que la única manera de conseguir recuperar a Ernest es llegar a ser una guapa y exitosa escritora. Para ello entrará en contacto con Lisle von Rhuman, una bruja que le subministra la pócima de la eterna juventud.', trailer_url = 'https://www.youtube.com/watch?v=0jPuZLUY4II' WHERE id_api = 'tt0104070';

UPDATE Contenido SET id_tmdb = 10406, descripcion = 'Dave Morgan y Stoney Brown son dos estudiantes que, excavando en el jardín, descubren enterrado a un hombre de las cavernas. En seguida piensan que su hallazgo supondrá todo un éxito en el instituto, pero ocurre exactamente lo contrario: su descubrimiento convertirá sus vidas en un auténtico desastre.', trailer_url = 'https://www.youtube.com/watch?v=1xkTN1Z1rTQ' WHERE id_api = 'tt0104187';

UPDATE Contenido SET id_tmdb = 11259, descripcion = 'A comienzos del siglo XX, Joseph y sus dos hermanos malviven del cultivo de unas tierras que son propiedad, como toda la comarca, del poderoso señor Christie. Cuando el padre de Joseph muere en un accidente provocado por los hombres de Christie, el joven decide vengarse, pero no lo consigue. Poco después, para evitar un duelo, emigra a América, y en el barco coincide con Shannon, la bella hija de Christie. Nada más llegar a los Estados Unidos, a Shannon le roban todo su dinero; entonces Joseph decide protegerla haciéndola pasar por su hermana.', trailer_url = 'https://www.youtube.com/watch?v=kgpwDLMowBM' WHERE id_api = 'tt0104231';

UPDATE Contenido SET id_tmdb = 11158, descripcion = 'Una vez devuelto el tamaño normal a sus hijos, el despistado científico Wayne Szalinski (Rick Moranis) reanuda sus investigaciones, pero en el sentido inverso: experimenta con un rayo capaz de aumentar el tamaño de las moléculas. Pero, de nuevo el pequeño Adam, un niño que tan sólo pretende jugar, interfiere catastróficamente en su trabajo.', trailer_url = 'https://www.youtube.com/watch?v=1uNS2JKhr9U' WHERE id_api = 'tt0104437';

UPDATE Contenido SET id_tmdb = 10326, descripcion = 'Año 1939. Daniel McCormick (Mel Gibson), piloto de pruebas, es un hombre al que todo le va bien en la vida. Todo cambia una mañana en la que su novia, Helen, tiene un desgraciado accidente. Desolado, se ofrece voluntario para un experimento secreto: El cuerpo de Daniel queda congelado en una cápsula experimental. En 1992, más de cincuenta años después, dos niños descubren la cápsula y descongelan el cuerpo, llevando a Daniel a casa de uno de ellos, que vive con su madre Claire (Jamie Lee Curtis).', trailer_url = 'https://www.youtube.com/watch?v=HIEHuEFDgac' WHERE id_api = 'tt0104291';

UPDATE Contenido SET id_tmdb = 9504, descripcion = 'En una empresa inmobiliaria, de la ciudad de Chicago y en plena, depresión económica, Blake (Alec Baldwin) en vista que sus nuevas técnicas comerciales, no son bien acogidas, entre sus comerciales, les lanza un reto a todos sus empleados, el mejor vendedor será recompensado con un ''Cadillac'', al segundo con un ''juego de cuchillos'' y el último simplemente será ''despedido''. Desde entonces se irá abriendo una brecha entre ellos, cada uno reacciona de distinta forma a este reto, todos empiezan a tenderse trampas y en pensar la manera, de vender o no ser, el peor vendedor, incluyendo, el robo de las "fichas" o "tarjetas de presentación" de los clientes, para conseguir el éxito.', trailer_url = 'https://www.youtube.com/watch?v=_VrekKSuFto' WHERE id_api = 'tt0104348';

