UPDATE Contenido SET id_tmdb = 11782, descripcion = 'El inspector Tequila Yuen (Chow Yun-Fat) es un duro policía encargado de detener una operación de contrabando de armas y de encontrar al asesino de su compañero. John Woo continúa con su personal estilo de violencia casi poética y tiroteos con ritmo en un thriller que cuenta con numerosos seguidores, toda una cinta de culto dentro del cine de acción. En España se estrenó en el año 1995, resultando un fracaso en taquilla.', trailer_url = 'https://www.youtube.com/watch?v=qJlUXv3owaY' WHERE id_api = 'tt0104684';

UPDATE Contenido SET id_tmdb = 9361, descripcion = 'En 1757, a orillas del río Hudson, tropas francesas e inglesas luchan por el dominio de la región. Los ingleses reclutan a los granjeros asentados en esas tierras para formar un ejército capaz de enfrentarse a las tropas franco-indias. Hawkeye -Ojo de halcón- (Daniel Day-Lewis) es un hombre blanco adoptado por los indios mohicanos que vive con su padre (Russell Means) y su hermano Uncas (Eric Schweig). Tras rescatar de una emboscada de los hurones a Cora Munro (Madeleine Stowe) y a su hermana pequeña Alice (Jodhi May), hijas de un oficial británico, los tres deciden acompañarlas al fuerte inglés William Henry, que está siendo asediado por franceses y hurones. Allí les obligan a quedarse con un grupo de británicos que acaban de llegar de las colonias...', trailer_url = 'https://www.youtube.com/watch?v=IHVnrh1y2Aw' WHERE id_api = 'tt0104691';

UPDATE Contenido SET id_tmdb = 11287, descripcion = 'En 1943, mientras los hombres estaban en la guerra, el béisbol estuvo a punto de desaparecer. Se formó entonces una liga femenina que intentaba captar la atención del público. Dottie y Mae formaban parte de uno de esos equipos femeninos que debían demostrar que eran capaces de competir y luchar como hombres. Lo peor era que tenían que soportar a Jimmy, un sarcástico y alcohólico entrenador.', trailer_url = 'https://www.youtube.com/watch?v=0A-O1MJAl9E' WHERE id_api = 'tt0104694';

UPDATE Contenido SET id_tmdb = 943, descripcion = 'Riggs y Roger son una pareja de policías de Los Ángeles que se enfrentan a un difícil caso. Armas confiscadas y a punto de ser destruidas han desaparecido de las dependencias oficiales y están llegando a los delincuentes más peligrosos de la ciudad. El responsable resulta ser Travis, antiguo teniente expulsado del cuerpo por corrupción.', trailer_url = 'https://www.youtube.com/watch?v=qGqEpNGwanc' WHERE id_api = 'tt0104714';

UPDATE Contenido SET id_tmdb = 10414, descripcion = 'Gordon Bombay (Emilio Estevez) es un ambicioso abogado que participa con intensidad del mundo competitivo y despiadado en el que debe desenvolverse. Pero sus valores se tambalean por completo cuando un juez decide condenarle a realizar un trabajo de rehabilitación social. La tarea que se le encomienda, y de la que no puede escapar, es entrenar a un equipo infantil de hockey. Sin embargo, el abogado termina por encontrar en la condena un nuevo sentido a su vida.', trailer_url = 'https://www.youtube.com/watch?v=Um_JU7HpSYQ' WHERE id_api = 'tt0104868';

UPDATE Contenido SET id_tmdb = 10497, descripcion = 'Nigel y Fiona (Hugh Grant y Kristin Scott-Thomas) hacen un crucero para celebrar su séptimo aniversario de boda. A bordo conocen a la hermosa y atractiva Mimi (Emmanuelle Seigner) y a su marido Oscar (Peter Coyote), que está inválido en una silla de ruedas. Nigel empieza a sentirse atraído por Mimi, y Oscar, que se da cuenta, le propone que intente seducirla, pero antes le cuenta cómo eran las experiencias sexuales con su mujer antes de sufrir el accidente que lo dejó paralítico.', trailer_url = 'https://www.youtube.com/watch?v=R3EMSHqkbfI' WHERE id_api = 'tt0104779';

UPDATE Contenido SET id_tmdb = 1883, descripcion = 'Malcolm Little (1925–1965) nació en Omaha (Nebraska). Su padre, ministro baptista, murió siendo él niño, y su madre acabó en un psiquiátrico cuando el Ku Klux Klan incendió su casa. Después de ser rechazado por el ejército, cayó en la delincuencia y fue a parar a la cárcel. Allí se convirtió al Islam y cambió radicalmente su vida, convirtiéndose pronto en un carismático líder del movimiento de liberación de la comunidad negra norteamericana.', trailer_url = 'https://www.youtube.com/watch?v=0hMpERkER6s' WHERE id_api = 'tt0104797';

UPDATE Contenido SET id_tmdb = 9367, descripcion = 'Un joven mariachi que se gana la vida actuando en diferentes lugares llega a un pueblo de la frontera mexicana al mismo tiempo que un peligroso matón, cuya misión es asesinar al amo del lugar.', trailer_url = 'https://www.youtube.com/watch?v=QtNJsvpHye0' WHERE id_api = 'tt0104815';

UPDATE Contenido SET id_tmdb = 10437, descripcion = 'El clásico ''Cuento de Navidad'' de Charles Dickens brilla con humor y fantasía en las manos de los siempre divertidos Teleñecos. Michael Caine da vida al avaro Mr. Scrooge, en una excelente interpretación que sin embargo no se caracteriza por su buen humor. La noche de navidad los fantasmas visitan a Scrooge y lo transportan a su pasado, presente y futuro, ofreciéndole un panorama muy poco alentador...', trailer_url = 'https://www.youtube.com/watch?v=JXaVI60BFJM' WHERE id_api = 'tt0104940';

UPDATE Contenido SET id_tmdb = 10377, descripcion = 'Debido a una serie de fatales coincidencias, dos jóvenes neoyorkinos, que viajaban al sur del país, son tomados por asesinos. Como no pueden pagar los honorarios de un buen abogado, deciden llamar al primo de uno de ellos, que es un abogado sin experiencia. En estas circunstancias, se prevé que el resultado del juicio puede ser verdaderamente desastroso.', trailer_url = 'https://www.youtube.com/watch?v=hITJLnyH9Fc' WHERE id_api = 'tt0104952';

UPDATE Contenido SET id_tmdb = 9869, descripcion = 'Jack Ryan es un ex agente de la CIA. Salir de aquel mundillo, tan peculiar, donde el peligro y la acción forman parte del día a día, no ha sido una decisión fácil. Pero no se arrepiente porque ahora, por primera vez, tiene una vida familiar. Durante unas vacaciones en Londres, por casualidad, mientras pasean por la ciudad, son testigos de un atentado contra Lord Holmes, un distinguido miembro de la Familia Real Británica. En medio de la confusión, los gritos y las llamas, su entrenamiento en la CIA hace reaccionar a Ryan automáticamente. Sale a defender a Lord Holmes y al hacerlo, le salva la vida, aunque para ello tiene que matar a uno de los terroristas. El atentado es atribuido al I.R.A.', trailer_url = 'https://www.youtube.com/watch?v=lctC_4kQwtw' WHERE id_api = 'tt0105112';

UPDATE Contenido SET id_tmdb = 10403, descripcion = 'Griffin Mill, productor cinematográfico de Hollywood, recibe amenazas escritas de un guionista al que rechazó un proyecto. Intentan llegar a un acuerdo, pero tras una terrible discusión, Griffin lo mata. Dada la crisis económica por la que atraviesan los estudios, estos harán todo lo posible para que eluda la responsabilidad de los hechos.', trailer_url = 'https://www.youtube.com/watch?v=HpDDTS08wPs' WHERE id_api = 'tt0105151';

UPDATE Contenido SET id_tmdb = 500, descripcion = 'Una banda organizada formada por seis individuos es contratada para dar un golpe. Anteriormente varios de los miembros no se conocían entre sí, por lo que entre ellos usan nombres en clave. El objetivo: atracar una empresa para llevarse unos diamantes. Pero, antes de que suene la alarma, la policía ya está allí. Algunos mueren en el atraco, y el resto se reúne en el lugar convenido.', trailer_url = 'https://www.youtube.com/watch?v=KlDJKZ8kJ-A' WHERE id_api = 'tt0105236';

UPDATE Contenido SET id_tmdb = 9609, descripcion = 'Dos grandes amigos, Lennie (John Malkovich) y George (Gary Sinise) se encuentran en paro, en plena era de la depresión norteamericana, y con pocas posibilidades de conseguir trabajo debido al retraso mental de Lennie. Cuando son contratados en el Rancho Tyler ven como su vida progresa a pesar de la estricta supervisión de Curley (Casey Siemaszko), el desagradable hijo del jefe. Pero su mundo se tambalea cuando la insatisfecha esposa de Curley (Sherilyn Fenn) se convierte en víctima inocente de la compasión de Lennie, forzando a George a decidir entre su amistad o él mismo.', trailer_url = 'https://www.youtube.com/watch?v=pWanzPwjwCA' WHERE id_api = 'tt0105046';

UPDATE Contenido SET id_tmdb = 293, descripcion = 'Aunque Norman y Paul Mclean, hijos de un pastor protestante, recibieron una rígida educación, tambien disfrutaron de libertad. Norman, un joven juicioso y reservado, es profesor y está enamorado. Paul, en cambio, es extrovertido, se dedica al periodismo y lleva una vida desordenada. A pesar de todo, hay algo que siempre los mantendrá unidos: el río salvaje que atraviesa Montana, donde aprendieron a pescar.', trailer_url = 'https://www.youtube.com/watch?v=F63Ae88_XKk' WHERE id_api = 'tt0105265';

UPDATE Contenido SET id_tmdb = 9475, descripcion = 'Frank Slade es un malhumorado Coronel en la reserva del ejército norteamericano, retirado pues sufre de ceguera. Durante el fin de semana de Acción de Gracias el joven estudiante Charlie Simms, contratado por la familia de Slade, se queda en su casa para servirle de lazarillo y procurar que no beba mucho. Pero Frank tiene otros planes: irse a la gran ciudad de Nueva York... Remake de la película italiana de 1974 "Profumo di donna" (Perfume de mujer).', trailer_url = 'https://www.youtube.com/watch?v=3GUvsJc3vvE' WHERE id_api = 'tt0105323';

UPDATE Contenido SET id_tmdb = 10538, descripcion = 'Charles Rane está considerado uno de los más peligrosos terroristas del mundo. Custodiado por agentes federales, Rane es trasladado a Los Angeles en avión para ser juzgado por los crímenes cometidos. A pesar de las medidas de seguridad, Rane consigue liberarse y se hace con el mando del avión, pero no cuenta con que en el mismo vuelo, sentado en el asiento número 57, viaja John Cutter, un especialista en lucha antiterrorista.', trailer_url = 'https://www.youtube.com/watch?v=cqftFJdAvtQ' WHERE id_api = 'tt0105104';

UPDATE Contenido SET id_tmdb = 9605, descripcion = 'Tras echar a su infiel novio de casa, Alison Jones, una ejecutiva de Nueva York, pone un anuncio en el periódico, buscando a alguien para compartir piso. Hedra Carlson, tímida y poco atractiva, pero muy inteligente, responde al anuncio. Pronto se crea una relación especial entre ellas y se hacen inseparables. Sin embargo, la dependencia de Hedra respecto a Alison va convirtiéndose en algo enfermizo; así, cuando ésta se reconcilia con su novio, unos celos patológicos se apoderan de Hedra, y empieza a ejercer sobre ellos un terrible acoso.', trailer_url = 'https://www.youtube.com/watch?v=ROg4MoaAXvY' WHERE id_api = 'tt0105414';

UPDATE Contenido SET id_tmdb = 8845, descripcion = 'Un gran acorazado norteamericano realiza su última travesía antes de ser retirado del servicio con una reducida tripulación. Uno de los miembros de ésta es el cocinero, hombre taciturno del que únicamente el capitán sabe que es un brillante oficial, condecorado en Vietnam, Oriente Medio y Panamá.', trailer_url = 'https://www.youtube.com/watch?v=DypYXFr51B8' WHERE id_api = 'tt0105690';

UPDATE Contenido SET id_tmdb = 33, descripcion = 'William Munny es un pistolero retirado, viudo y padre de familia, que tiene dificultades económicas para sacar adelante a su hijos. Su única salida es hacer un último trabajo. En compañía de un viejo colega y de un joven inexperto, Munny tendrá que matar a dos hombres que cortaron la cara a una prostituta.', trailer_url = 'https://www.youtube.com/watch?v=Ex_VDI8RJH0' WHERE id_api = 'tt0105695';

UPDATE Contenido SET id_tmdb = 2005, descripcion = 'Deloris Van Cartier es una mediocre cantante de cabaret. Su amante Vince ha cometido un crimen, y ella decide acogerse al programa policial de protección de testigos. Así, Deloris consigue una nueva identidad como monja en un convento que, tan sólo con su presencia, perderá su habitual tranquilidad.', trailer_url = 'https://www.youtube.com/watch?v=lCBjHkCK1Vw' WHERE id_api = 'tt0105417';

UPDATE Contenido SET id_tmdb = 2322, descripcion = 'Martin Bishop, un genio de los ordenadores, es el líder de un grupo de expertos especializados en comprobar los sistemas de seguridad de grandes empresas. Un día es obligado a trabajar para una agencia secreta con el fin de robar una caja negra secreta. Tras conseguirla, descubren que dicha caja tiene la capacidad de decodificar todos los sistemas de encriptación existentes en el mundo, y que los agentes para los que trabajan no son exactamente del gobierno', trailer_url = 'https://www.youtube.com/watch?v=VNy4zC-wy_M' WHERE id_api = 'tt0105435';

UPDATE Contenido SET id_tmdb = 9876, descripcion = 'Tutti Bomoski, una encantadora y simpática mujer de New Jersey, está convencida de saber qué es lo mejor para su único hijo, tanto a nivel personal como profesional. Su hijo es el sargento de policía de Los Ángeles Joe Bomowski, un solterón acomodado a su estilo de vida independiente y algo descuidado, a tres mil millas de su madre. Cuando Tutti, durante una inoportuna visita, se convierte en testigo de un crimen, se verá involucrada también en una peligrosa investigación policial... y Joe, de mala gana, tendrá una nueva "compañera."', trailer_url = 'https://www.youtube.com/watch?v=e1VnUF8mIWA' WHERE id_api = 'tt0105477';

UPDATE Contenido SET id_tmdb = 1923, descripcion = 'Precuela de la famosa serie televisiva. La fuente de los impulsos autodestructivos de Laura Palmer está en los abusos que sufre por parte de alguien muy cercano, quien sufre la posesión del diabólico BOB. Cuando Laura se da cuenta de que su mejor amiga, Donna Hayward, se encamina a su mismo sendero autodestructivo, tiene un ataque de lucidez que le permite prevenírselo.', trailer_url = 'https://www.youtube.com/watch?v=wtM53AvjgYA' WHERE id_api = 'tt0105665';

UPDATE Contenido SET id_tmdb = 9349, descripcion = 'Siguiendo un programa altamente secreto, el ejército está trabajando con cadáveres a los que transforma en soldados invencibles. Una pareja de reporteros se aproxima a la base en la que se realiza el experimento y toma fotografías del lugar.', trailer_url = 'https://www.youtube.com/watch?v=EhXJHHzphdM' WHERE id_api = 'tt0105698';

UPDATE Contenido SET id_tmdb = 8872, descripcion = 'Cuando un importante ejecutivo de la televisión ofrece a los alocados y poco convencionales Wayne y a Garth un jugoso contrato para hacer en su cadena su peculiar show nocturno, ambos no pueden dar crédito a su suerte. Pero el camino hacia el éxito es muy tortuoso, está lleno de peligros, tentaciones y fiestas salvajes. ¿Podrá Wayne ganar el cariño de la diosa del rock Cassandra? ¿Será Garth capaz de “mojar” con la chica de sus sueños en la tienda de donuts?', trailer_url = 'https://www.youtube.com/watch?v=eBzr2UDK4DM' WHERE id_api = 'tt0105793';

UPDATE Contenido SET id_tmdb = 10158, descripcion = 'Billy y Sidney son dos amigos, uno blanco y otro negro, que se dedican a practicar el baloncesto callejero contra todo aquel que desee medir sus fuerzas con ellos. Como los dos se creen los mejores jugadores del mundo, su excesivo ego hace que se peleen entre ellos, con los contrarios y con todo aquel que no comparta su filosofía del juego.', trailer_url = 'https://www.youtube.com/watch?v=NHRvNAENaxk' WHERE id_api = 'tt0105812';

UPDATE Contenido SET id_tmdb = 10436, descripcion = 'Nueva York, año 1870. Newland Archer, un caballero de la alta sociedad neoyorquina, está prometido con May Welland, una joven de su misma clase social. Pero sus sentimientos cambian cuando conoce a la poco convencional prima de May, la condesa Olenska. Desde el principio, defenderá la difícil posición de la condesa, cuya separación de un marido autoritario la ha convertido en una especie de proscrita dentro de su propia clase social.', trailer_url = 'https://www.youtube.com/watch?v=I3Mx8OSlNYM' WHERE id_api = 'tt0106226';

UPDATE Contenido SET id_tmdb = 1777, descripcion = 'Es una comedia de situación estadounidense protagonizada por Ben Savage. Fue estrenada el 24 de septiembre de 1993 en la cadena ABC y finalizó el 5 de mayo de 2000. En total cuenta con 158 episodios repartidos en siete temporadas.', trailer_url = 'https://www.youtube.com/watch?v=wntEBGSNWVI' WHERE id_api = 'tt0105958';

UPDATE Contenido SET id_tmdb = 11044, descripcion = 'En un extraño y desolador paraje del desierto americano, un vendedor de coches convence a su sobrino para que trabaje con él. Allí conocerá a una mujer que le traerá serios problemas.', trailer_url = 'https://www.youtube.com/watch?v=xR4Aq-p8thE' WHERE id_api = 'tt0106307';

UPDATE Contenido SET id_tmdb = 2352, descripcion = 'Fran Fine (Fran Drescher), una joven judía del barrio de Queens de Nueva York, al ser despedida de la tienda donde trabajaba junto a su ex novio, encuentra un empleo como canguro en casa de Maxwell Sheffield (Charles Shaughnessy), un millonario productor de Broadway que vive solo con sus tres hijos. Fran vive una vida llena de sorpresas en la que trata de enamorar al padre de los niños que cuida.', trailer_url = 'https://www.youtube.com/watch?v=OHK-1WTRQAM' WHERE id_api = 'tt0106080';

UPDATE Contenido SET id_tmdb = 2758, descripcion = 'Fue amor al primer susto cuando Gomez y Morticia acogieron a un nuevo miembro en el grupo familiar -Pubert, su delicado, blandito y bigotudo niño. Fue entonces cuando Fétido se enamoró de la voluptuosa niñera. Pero tras algunas investigaciones, Miércoles y Pugsley descubren que la inocente niñera es en realidad una viuda negra asesina que planea añadir a Fétido a su colección de maridos muertos.', trailer_url = 'https://www.youtube.com/watch?v=oaURSnE6qKc' WHERE id_api = 'tt0106220';

UPDATE Contenido SET id_tmdb = 580, descripcion = 'Star Trek: Espacio profundo nueve (Star Trek: Deep Space Nine) (algunas veces abreviada ST:DS9 o DS9) es una serie de ciencia ficción estadounidense estrenada en 1993, que se extendió a lo largo de siete temporadas. Se ubica dentro del universo ficticio de Star Trek de Gene Roddenberry, creada por Rick Berman y Michael Piller a petición de Brandon Tartikoff, y fue producida por CBS Paramount Television. Los escritores principales, además de Rick Berman y Michael Piller, fueron Ira Steven Behr, Robert Hewitt Wolfe, Ronald D. Moore, Peter Allan Fields, Bradley Thompson, David Weddle, y René Echevarria.

Como una spin-off de Star Trek: La nueva generación, DS9 comenzó mientras su predecesora aún estaba al aire, lo cual llevó a varios episodios entrelazados entre ambas series. Además, dos miembros de TNG, Miles O''Brien y Worf, se convirtieron en miembros regulares de DS9.

A diferencia de otros programas de Star Trek, DS9 tuvo lugar en una estación espacial en vez de una nave estelar, para no tener dos series con naves al mismo tiempo (más adelante sería agregada la nave estelar USS Defiant). Esto hizo posible realizar arcos históricos y la aparición de personajes recurrentes con mayor frecuencia. La serie se centró más en temáticas oscuras, menos exploración espacial, y puso énfasis (en las últimas temporadas) en muchos aspectos de guerra.', trailer_url = 'https://www.youtube.com/watch?v=cwNFUgYWGG4' WHERE id_api = 'tt0106145';

Descubren un agujero de gusano cerca de la estación y mueven la estación espacial hasta allí. El comandante Benjamin Sisko y Jadzia Dax, una trill, van por el agujero de gusano. Allí encuentran a unos seres incorpóreos que los bajoranos llaman profetas, y se comunican con Sisko y envían a la teniente Dax de regreso a EP9.', 90, '1993-01-03');

