UPDATE Contenido SET id_tmdb = 3452, descripcion = 'El doctor Frasier Crane es un estirado psiquiatra que, tras su divorcio, se traslada de Boston a Seattle para llevar un programa-consultorio de radio. Nada más llegar, se entera de que tiene que vivir con su padre, un gruñón expolicía lisiado en acto de servicio. Frasier queda con frecuencia con su hermano (también psiquiatra, y todavía mucho más snob), con el que tiene conversaciones muy peculiares sobre arte, mujeres y la vida en general. En la vida de Frasier sólo hay dos mujeres estables: su asistenta, una inglesa muy deseada su hermano; y la directora de su programa, una soltera desesperada por tener novio.', trailer_url = 'https://www.youtube.com/watch?v=d6rIzxICCio' WHERE id_api = 'tt0106004';

UPDATE Contenido SET id_tmdb = 7305, descripcion = 'Basada en una historia real, "Alive" narra la terrible experiencia de un grupo de jugadores del equipo nacional de rugby de Uruguay cuyo avión se estrelló en medio de los Andes en octubre de 1972. Aislados completamente, los días pasaban sin que nadie viniera a rescatarles, por lo que se vieron obligados a recurrir al canibalismo, comiéndose la carne de los compañeros fallecidos, mientras los más fuertes preparaban un viaje desesperado a través de las montañas.', trailer_url = 'https://www.youtube.com/watch?v=C2lFPEp7dbI' WHERE id_api = 'tt0106246';

UPDATE Contenido SET id_tmdb = 766, descripcion = 'Inglaterra, siglo XIII. Las fuerzas del mal ejercen su reinado en la Edad Media. Valerosos caballeros se disponen a entrar en desigual batalla, mientras que los atemorizados campesinos se refugian tras los muros del castillo. Todo cambia con la inesperada llegada de un nuevo héroe, provisto de sofisticadas armas, que dice provenir del siglo XX.', trailer_url = 'https://www.youtube.com/watch?v=UHZQEtG8xYo' WHERE id_api = 'tt0106308';

UPDATE Contenido SET id_tmdb = 14919, descripcion = 'Una enigmática figura fantasmal hace su aparición, cumpliendo las ejecuciones de determinadas figuras importantes del hampa. Simultáneamente regresa a Gotham una muchacha con la cual Bruce Wayne mantuvo un idilio; éste rememorará su relación con la chica y, de paso, su propio «nacimiento» como Batman.', trailer_url = 'https://www.youtube.com/watch?v=imtYrQEZ4H8' WHERE id_api = 'tt0106364';

UPDATE Contenido SET id_tmdb = 1607, descripcion = 'Años 60. El gángster Sonny es el rey del barrio del Bronx, donde vive el pequeño Calogero. Un tiroteo, presenciado por el niño, es el punto de partida de una duradera relación entre el gángster y el pequeño. Lorenzo Anello, padre del chico y un honrado conductor de autobuses, desaprueba esta relación. A pesar de ello, el muchacho crece bajo la protección de los dos hombres, dividido entre su honradez natural y su fascinación por Sonny. Sin embargo, llegará un momento en el que Calogero (Lillo Brancato) no tendrá más remedio que tomar una decisión sobre el camino que debe seguir.', trailer_url = 'https://www.youtube.com/watch?v=wnakCrX0NNM' WHERE id_api = 'tt0106489';

UPDATE Contenido SET id_tmdb = 4104, descripcion = 'Tras la muerte de sus padres, Joon (Masterson), una chica sensible y delicada, se ha convertido en una persona mentalmente desequilibrada, que vive bajo la estricta tutela y protección de su hermano Benny (Quinn). Como consecuencia de una disparatada apuesta en una partida de póker, Benny tiene que aceptar que Sam (Depp), un muchacho extravagante y solitario que tiene un don especial para la pantomima (homenaje al cine mudo), se vaya a vivir con ellos. Joon y Sam simpatizan enseguida y acaban enamorándose.', trailer_url = 'https://www.youtube.com/watch?v=oPjBb1qeiK4' WHERE id_api = 'tt0106387';

UPDATE Contenido SET id_tmdb = 9350, descripcion = 'Gabe Walker, un alpinista dedicado al rescate de alta montaña, todavía no ha superado la muerte de su compañera en una caída al vacío un año atrás. Ahora le piden que vuelva a la misma montaña de la tragedia para rescatar a un grupo de personas extraviadas. Lo que Gabe desconoce es que se trata de peligrosos delincuentes que acaban de perpetrar un asalto a un avión para hacerse con un botín de cien millones de dólares.', trailer_url = 'https://www.youtube.com/watch?v=FMSxpwJ_q-Y' WHERE id_api = 'tt0106582';

UPDATE Contenido SET id_tmdb = 6075, descripcion = 'Carlitos Brigante, un antiguo traficante de heroína de origen portorriqueño, sale de la cárcel después de cinco años de reclusión, dispuesto a dejar el tráfico de drogas. Con la ayuda de un abogado cocainómano consigue hacerse socio de un club nocturno e intenta reanudar la relación con su ex-novia, pero no es fácil seguir el buen camino dentro del mundo del crimen.', trailer_url = 'https://www.youtube.com/watch?v=nYBHVf108J0' WHERE id_api = 'tt0106519';

UPDATE Contenido SET id_tmdb = 864, descripcion = 'Derice, Sanka, Junio Bevil y Yul son cuatro atletas jamaicanos, sin apenas recursos y sin tener conocimiento o adaptación a la nieve, pero dispuestos a alcanzar una difícil meta: ganar la medalla de oro nada menos que en los Juegos Olímpicos de invierno de Calgary, Canadá. Para ello reclutan como entrenador a un ex-campeón norteamericano (John Candy), quien aceptará la imposible tarea debido a su precaria situación económica.', trailer_url = 'https://www.youtube.com/watch?v=wLlmymHRNZg' WHERE id_api = 'tt0106611';

UPDATE Contenido SET id_tmdb = 4087, descripcion = 'Expediente X es una serie de televisión estadounidense de ciencia ficción y misterio, que emitió la cadena FOX y fue creada por Chris Carter, centrada en los casos que investigan dos agentes del FBI, clasificados como "Expedientes X": fenómenos paranormales, avistamiento de ovnis, criaturas extrañas, etc.

La serie ha sido uno de los mayores éxitos de la cadena FOX. Sus personajes y frases se han convertido en iconos de la cultura popular al explotar e inspirar una gran cantidad de teorías sobre conspiraciones y existencia de vida extraterrestre.', trailer_url = 'https://www.youtube.com/watch?v=_HTByz4RlqI' WHERE id_api = 'tt0106179';

Por otro lado, está Dana Scully, joven agente con una prometedora carrera. Es doctora forense y descarta el carácter paranormal de los Expedientes X. Es una científica y por tal condición trata de encontrar a todo, una explicación válida. Si bien puede resultar extraño que la Dra. Scully trabaje en expedientes de estas características, el hecho es que es asignada por sus superiores del FBI al departamento con el pretexto de aportar validez científica a los casos investigados por Mulder; pero el objetivo oculto es desacreditar el trabajo realizado en los Expedientes X.

Scully comienza a trabajar con Mulder en 1993. Por aquel tiempo, éste entra en contacto con un curioso informante: garganta profunda. Gracias a él, Mulder confirma sus sospechas de que existe una conspiración del Gobierno para ocultar evidencia de vida extraterrestre a la opinión pública. Los dos agentes comienzan a desatar el ovillo, a la par que se topan con casos que involucran a criaturas mutantes y actividad paranormal. Resolviendo estos casos, Dana y Fox van ganando confianza hasta llegar a tener una relación sentimental, aunque por la naturaleza de la serie se trata de un sutil amor platónico.36​ Ella empieza a creer un poco en lo inexplicable y a él no le sienta mal confrontar sus obsesiones con la dosis de ciencia de su compañera. Al poco tiempo forman ya un gran equipo.');

Sin embargo, no será él quien tenga más posibilidades de conseguir el tan ansiado encuentro con lo paranormal...');

', 46, '1994-09-23');

Lejos ya de su versión escéptica, la forense es la única que parece creer en encontrar al desaparecido doctor y, junto a él, retomar una búsqueda que contará con la ayuda del informante X y que, para Scully, es ya un asunto personal.');

El doctor comienza a replantearse la búsqueda de lo oculto por primera vez en su vida mientras, Scully, que ha tenido contacto directo con lo extrasensorial, sufre un efecto secundario inesperado.');

Llegando a crear una identidad falsa, Mulder está dispuesto a hacer lo necesario para salvar la vida de su amiga en un viaje que le dará más detalles sobre la relación entre el FBI y el Sindicato; y que, de nuevo, probará su fe inquebrantable en lo paranormal.');

Las vidas de Scully y Mulder cambiarán cuando, de pronto, una amenaza surja sobre el planeta y tan solo ellos dos sean los únicos que puedan afrontarla.');

Scully debe darse prisa, pues los símbolos contienen la clave para solucionar el problema que Mulder padece y son la única forma de salvar al mismo. En esta temporada, los investigadores deberán luchar a contrarreloj contra un fenómeno que, cada vez, es más real.');

', 45, '1999-11-07');

Le acompañarán el líder de una fuerza especial del FBI, John Doggett, y la especialista en rituales criminales, Mónica Reyes. Scully deberá lidiar frente a todas estas complicaciones con los añadidos del inminente nacimiento de su bebé y una amenaza oculta que espera su momento para atacar.');

Los encargados ahora de los Expedientes X son el agente John Doggett y su compañera, Mónica Reyes. Con la ayuda de Mulder, los agentes prosiguen con el legado marcado por el propio Fox y Scully mientras lo oculto y el propio FBI planean impedirlo.');

Los dos agentes, junto a Walter Skinner y varios viejos conocidos, abrirán de nuevo los expedientes referidos al mundo paranormal para afrontar esta renovada amenaza.');

Comienza así una búsqueda contrarreloj en la que el destino de William; el de los investigadores, y el del mundo entero están en juego.');

UPDATE Contenido SET id_tmdb = 9612, descripcion = 'Belder y Prymaat son emisarios de Remulack, planeta a 26 años-luz de la Tierra. Pertenecen a una civilización que intenta extender su imperio... esclavizando a pueblos de otros mundos. Su misión: conquistar nuestro planeta. Pero un accidente les obliga a aterrizar en la Tierra antes de tiempo, tratando de pasar desapercibidos y evitando a los agentes que les acosan. Así, encuentran cierta seguridad en Paramus, New Jersey, donde se convierten en la típica familia trabajadora con una hija.', trailer_url = 'https://www.youtube.com/watch?v=_Q8CpaejCk8' WHERE id_api = 'tt0106598';

UPDATE Contenido SET id_tmdb = 11566, descripcion = 'Dave Kovic (Kevin Kline) es un sencillo ciudadano que guarda un extraordinario parecido con el presidente de los Estados Unidos Bill Mitchell. Cuando un repentino ataque incapacita al presidente, sus asesores políticos deciden que Dave lo suplante, dando por supuesto que será un hombre fácil de manipular. Por otra parte, la esposa del presidente (Sigourney Weaver), que ignora la situación, encuentra tan anómala la conducta de su supuesto marido que empieza a sospechar.', trailer_url = 'https://www.youtube.com/watch?v=ynC1hITFIzQ' WHERE id_api = 'tt0106673';

UPDATE Contenido SET id_tmdb = 37233, descripcion = 'Mitch McDeere, un joven y brillante abogado recién salido de la facultad de Harvard, se deja seducir por las promesas y regalos de un prestigioso bufete de abogados de Memphis. Sin embargo, muy pronto tendrá razones para empezar a sospechar que algo extraño está sucediendo en la poderosa empresa.', trailer_url = 'https://www.youtube.com/watch?v=Auxb3l4Y8j0' WHERE id_api = 'tt0106918';

UPDATE Contenido SET id_tmdb = 9739, descripcion = 'En el año 1996 un edificio estalla con 30 rehenes dentro, tras una brutal lucha entre Simon Phoenix, un criminal psicópata y John Spartan, un policía conocido como Demolition Man. Ambos son condenados a ser congelados hasta 2032, año en el que se vuelven a encontrar.', trailer_url = 'https://www.youtube.com/watch?v=7UVS1GV8wtY' WHERE id_api = 'tt0106697';

UPDATE Contenido SET id_tmdb = 9571, descripcion = 'Al igual que hiciera George Lucas en "American Graffiti" veinte años antes, Linklater retrata el último día de clase de unos estudiantes de un instituto, en 1976. Una fiesta a base de cerveza, marihuana y novatadas en un día único tanto para los chicos que se van para siempre como para los novatos que acaban de llegar.', trailer_url = 'https://www.youtube.com/watch?v=uzDPw5N8d_0' WHERE id_api = 'tt0106677';

UPDATE Contenido SET id_tmdb = 12139, descripcion = 'Daniel es un chiquillo inquieto que inunda la vecindad con ruidosos juegos. Un fin de semana que debe quedarse con sus vecinos, los Wilson, provoca un incidente que acaba con la paciencia del Sr. Wilson y le convierte en héroe involuntario al capturar a un ladrón de poca monta.', trailer_url = 'https://www.youtube.com/watch?v=63XgkkkEPMo' WHERE id_api = 'tt0106701';

UPDATE Contenido SET id_tmdb = 37094, descripcion = 'En Los Ángeles, durante una jornada especialmente agobiante a causa del calor y del colapso del tráfico, de repente, un ciudadano normal se rebela de manera violenta y destructiva contra todo lo que lo rodea. Bill Foster (Michael Douglas) no es más que un hombre corriente que supera como puede las frustraciones de cada día y que lo único que quiere es regresar a casa. Un oficial del departamento de policía (Robert Duvall) intentará poner fin a su violencia y agresividad.', trailer_url = 'https://www.youtube.com/watch?v=BD5ofrSNDFA' WHERE id_api = 'tt0106856';

UPDATE Contenido SET id_tmdb = 1634, descripcion = 'Willy es una impresionante orca confinada en un pequeño parque acuático en el Pacífico Norte, lejos de su hábitat natural y separada de toda su familia y hogar. Nadie en el parque entiende el comportamiento y los sentimentos de Willy, excepto un muchacho de 12 años, quien al igual que Willy sabe muy bien lo que significa estar lejos de su familia.', trailer_url = 'https://www.youtube.com/watch?v=PQZES1EtZ2w' WHERE id_api = 'tt0106965';

UPDATE Contenido SET id_tmdb = 5503, descripcion = 'El doctor Richard Kimble es un prestigioso cirujano de Chicago con una vida prácticamente perfecta: una bella esposa, una casa de lujo en un elegante barrio de Chicago... Su vida se desmorona el día que su mujer es brutalmente asesinada en manos de un misterioso hombre manco. Kimble es acusado del crimen y, aunque él es inocente, es sentenciado con la pena de muerte. Camino de la cárcel, el autobús donde es transportado Kimble sufre un accidente de tráfico. Varios prisioneros consiguen escapar, entre ellos el propio Kimble. El detective Samuel Gerard es el encargado de realizar la investigación. Todos los fugados son atrapados, excepto el esquivo Kimble, que se le escapa de las manos por unos segundos. Ahora que está en libertad, Kimble sabe que solamente tiene una manera de probar su inocencia: encontrar al verdadero asesino. Perseguido por Gerard, inicia la búsqueda del manco.', trailer_url = 'https://www.youtube.com/watch?v=e6rHvHfrGDw' WHERE id_api = 'tt0106977';

UPDATE Contenido SET id_tmdb = 10439, descripcion = 'Tres brujas del siglo XII son invocadas durante la noche de Halloween en la ciudad de Salem, Massachusetts, de manera accidental por unos niños. Desterradas hace 300 años por sus prácticas de brujería, este trío prometió volver algún día para sembrar el caos. Ahora aprovecharán la ocasión para cumplir su promesa.  Una comedia realizada por la factoría Disney con vistas a su exhibición en la fiesta de Halloween.', trailer_url = 'https://www.youtube.com/watch?v=Qh5DXOj5g8g' WHERE id_api = 'tt0107120';

UPDATE Contenido SET id_tmdb = 137, descripcion = 'Phil, hombre del tiempo de una cadena de televisión, es enviado un año más a Punxstawnwey, a cubrir la información del festival de El día de la marmota. En el viaje de regreso, Phil y su equipo se ven sorprendidos por una tormenta que les obliga a regresar a la pequeña ciudad. A la mañana siguiente, al levantarse, Phil escucha en el radiodespertador el mismo programa que la mañana anterior.', trailer_url = 'https://www.youtube.com/watch?v=UFPjz8l2U8k' WHERE id_api = 'tt0107048';

UPDATE Contenido SET id_tmdb = 9272, descripcion = 'Henry Evans es un niño tan modélico que sus padres tienen razones de sobra para sentirse orgullosos de él. Sin embargo, bajo su apariencia cariñosa y apacible se esconde una mente retorcida y poblada de ideas malignas. Sólo otro niño podría darse cuenta de ello; y eso es lo que ocurre cuando su primo Mark, tras la muerte de su madre, se traslada a vivir con los Evans.', trailer_url = 'https://www.youtube.com/watch?v=_gHxeAadqOs' WHERE id_api = 'tt0107034';

UPDATE Contenido SET id_tmdb = 11520, descripcion = 'Son gruñones y viejos, llevan 56 años enfadados. Y odiarse mutuamente se ha convertido en su mayor placer. Idear nuevas maneras de ridiculizarse o ponerse en apuros es la clave de su relación y la salsa de sus vidas. Ni siquiera sus propios hijos conocen la razón. Ahora, van a tener un nuevo aliciente y un motivo de disputa: una atractiva viuda.', trailer_url = 'https://www.youtube.com/watch?v=64MH2i5gr_I' WHERE id_api = 'tt0107050';

UPDATE Contenido SET id_tmdb = 4478, descripcion = 'David (Harrelson), arquitecto, y Diona Murphy (Moore), agente inmobiliario, son un matrimonio felizmente casado y bien avenido que, por culpa de un traspié económico, ve peligrar su nivel de vida. En Las Vegas, donde buscan un golpe de suerte en el juego que les traiga algo de dinero, un maduro y apuesto multimillonario (Redford) ofrece a David un millón de dólares a cambio de pasar una noche con su mujer. A pesar de las dudas iniciales, ambos acaban aceptando la propuesta...', trailer_url = 'https://www.youtube.com/watch?v=u3SyUC7GPV0' WHERE id_api = 'tt0107211';

UPDATE Contenido SET id_tmdb = 2019, descripcion = 'Dos hombres despiadados, Fouchon y Van Cleaf, han convertido Nueva Orleans en su particular coto de caza, donde organizan siniestros torneos que enfrentan a sus asesinos con veteranos de guerra, a quienes prometen 10.000 dólares si logran sobrevivir. Desde luego, ninguno de los infortunados que se atreve a probar suerte en tan sanguriento juego llega a cobrar el premio. Las cosas cambiarán el día en que Chance Boudreaux (Jean Claude Van Damme) decide participar en el juego... Chance, sin embargo, no es un héroe noble y altruista, sino un solitario "cajun" que solamente quiere cobrar los 217 dólares que necesita para saldar sus deudas con el sindicato de marineros mercantes.', trailer_url = 'https://www.youtube.com/watch?v=-pzx4IeYYFg' WHERE id_api = 'tt0107076';

UPDATE Contenido SET id_tmdb = 6878, descripcion = 'Tres sorprendentes amigos, un perro perdiguero, un cachorro de Bulldog y una gata del Himalaya, se ven separados de la familia con la que viven. Habiéndose quedado al cuidado de una amiga de la familia, los tres compañeros, ahora desamparados, emprenden un increíble viaje de vuelta a casa a través de la naturaleza virgen. Los tres amigos han de reunir todo su valor y confiar plenamente en sus compañeros con el fin de sobrevivir a feroces animales y la dureza del entorno.', trailer_url = 'https://www.youtube.com/watch?v=xAH5q1VRdzU' WHERE id_api = 'tt0107131';

UPDATE Contenido SET id_tmdb = 329, descripcion = 'El multimillonario John Hammond tiene una idea para un espectacular parque temático: una isla retirada donde los visitantes puedan observar dinosaurios reales. Con la última tecnología en el desarrollo de ADN, los científicos pueden clonar braquiosaurios, triceratops, velociraptors y un tiranosaurio rex, utilizando para ello la sangre fosilizada en ámbar contenida en insectos que los mordieron hace millones de años. Los paleontólogos Alan Grant, Ellie Sattler y Ian Malcolm visitan el parque y quedan muy sorprendidos con los resultados obtenidos. Pero cuando un problemático empleado manipula el sofisticado sistema de seguridad los dinosaurios escapan, obligando a los visitantes a luchar por su supervivencia.', trailer_url = 'https://www.youtube.com/watch?v=Rz_FvTXa_qY' WHERE id_api = 'tt0107290';

UPDATE Contenido SET id_tmdb = 7984, descripcion = 'Belfast, años 70. Gerry es un gamberro que sólo sabe beber e ir de juerga, para disgusto de su padre Giuseppe, un hombre tranquilo y educado. Cuando Gerry se enfrenta al IRA, su padre lo manda a Inglaterra. Una vez allí, por caprichos del azar, es acusado de participar en un atentado terrorista y condenado a cadena perpetua junto con los "cuatro de Guildford". También su padre es arrestado y encarcelado. En la cárcel Gerry descubre que la aparente fragilidad de su padre esconde en realidad una gran fuerza interior. Con la ayuda de una abogada entregada a la causa, Gerry se propone demostrar su inocencia, limpiar el nombre de su padre y hacer pública la verdad sobre uno de los más lamentables errores legales de la historia reciente de Irlanda.', trailer_url = 'https://www.youtube.com/watch?v=b1VcwIncgYs' WHERE id_api = 'tt0107207';

UPDATE Contenido SET id_tmdb = 9255, descripcion = 'Topper Harley es hallado trabajando de chapuzas en un monasterio budista. La CIA le necesita para encabezar una misión de rescate en Irak: rescatar a la misión de rescate que tenía que rescatar a unos cautivos de la operación tormenta del desierto. Tug Benson, el presidente de los Estados Unidos, tendrá un importante papel en todo el asunto.', trailer_url = 'https://www.youtube.com/watch?v=Rida8js49Uo' WHERE id_api = 'tt0107144';

UPDATE Contenido SET id_tmdb = 9386, descripcion = 'Frank Horrigan es un veterano escolta, que conoció tiempos mejores cuando llegó a ser guardaespaldas del Presidente Kennedy. Muchos años después, a punto de retirarse, está atravesando una crisis profesional y personal, pero decide volver al servicio de la Casa Blanca cuando en una investigación rutinaria descubre que un psicópata llamado Mitch Leary está amenazando de muerte al Presidente de los Estados Unidos. El presidente recibe unas 1400 amenazas cada año, pero estas parecen creíbles y provenientes de un tipo peligroso.', trailer_url = 'https://www.youtube.com/watch?v=Oc-4t7LI68M' WHERE id_api = 'tt0107206';

UPDATE Contenido SET id_tmdb = 9593, descripcion = 'Danny Madigan es un fantasioso chico, ferviente admirador de Jack Slater, el mayor héroe del cine de acción. Nunca se pierde ninguna de sus películas, así que, ante el estreno de su última superproducción, el viejo acomodador del cine le regala al joven fan una entrada para que la vea en primicia. Gracias a esa entrada, que resulta tener poderes mágicos, Danny consigue introducirse en la pantalla y vivir trepidantes aventuras con Jack.', trailer_url = 'https://www.youtube.com/watch?v=IeHRd-cLa24' WHERE id_api = 'tt0107362';

UPDATE Contenido SET id_tmdb = 10909, descripcion = 'Brian Kessler es un periodista que prepara un libro sobre los asesinos en serie más famosos de los Estados Unidos. Para ello decide emprender un viaje junto a su novia Karrie, para conocer los lugares donde los criminales vivieron y mataron. Para compensar los altos costes del viaje, ponen un anuncio solicitando compañeros con los que compartir los gastos de gasolina.', trailer_url = 'https://www.youtube.com/watch?v=2ut7heVeMnM' WHERE id_api = 'tt0107302';

UPDATE Contenido SET id_tmdb = 21450, descripcion = 'Después de un encuentro sexual con una mujer casada en un callejón en Mánchester que se convierte en una violación, Johnny Fletcher (David Thewlis) roba un coche y huye de su ciudad natal a Londres para buscar refugio en la casa de su ex novia, Louise (Lesley Sharp). Johnny es un hombre inteligente, educado y elocuente, pero con una profunda amargura y un pesimismo vital que siempre le mantiene al límite de una conducta sádica. En Londres seduce a la compañera de piso de Louise, Sophie (Katrin Cartlidge), antes de embarcarse en una odisea en la que compartirá sus días entre indigentes y personajes desesperados de los bajos fondos de la capital del Reino Unido.', trailer_url = 'https://www.youtube.com/watch?v=TdKPbyvS0qc' WHERE id_api = 'tt0107653';

UPDATE Contenido SET id_tmdb = 10440, descripcion = 'Carol Lipton (Diane Keaton), una aburrida ama de casa de Manhattan, empieza a sospechar que su vecino Paul House (Jerry Adler), un hombre de avanzada edad, ha asesinado a su mujer, aunque, aparentemente, haya muerto a causa de un infarto. Su marido (Woody Allen) la tacha de paranoica y trata de quitarle de la cabeza esa descabellada idea; pero Carol se empeña en investigar a su vecino y empienza a seguirlo con la ayuda de su amigo Ted (Alan Alda), que siempre se ha sentido atraído por ella. Larry, espoleado por los celos y por una seductora escritora (Anjelica Huston), también interesada en el caso, se une de mala gana a la investigación.', trailer_url = 'https://www.youtube.com/watch?v=kOQuEcmYoZI' WHERE id_api = 'tt0107507';

UPDATE Contenido SET id_tmdb = 9516, descripcion = 'Caine, un joven afroamericano del barrio angelino de Watts, cuyo padre era traficante y su madre drogadicta, vive con sus abuelos maternos que intentan inculcarle los buenos valores que sus padres no pudieron darle. Pero sigue en el ghetto, lo cual hace que se junte con otros jóvenes, entre ellos una malísima influencia como lo es su mejor amigo, O-Dog. La violencia le rodea y tendrá que tomar una motivación existencial para poder escapar de ese "infierno", la chica que le gusta era la novia de su modelo paternal (condenado a cadena perpetua) y puede ser su chispa potenciadora para escapar y empezar de cero...', trailer_url = 'https://www.youtube.com/watch?v=woJQ9XPpVVY' WHERE id_api = 'tt0107554';

UPDATE Contenido SET id_tmdb = 788, descripcion = 'Willams es padre y esposo. Sus hijos lo consideran un padre maravilloso, pero su mujer está cansada de que se comporte como si también él fuera un niño. Tras un accidentado divorcio, aunque lucha con todas sus fuerzas para conseguir la custodia de los niños, el juez no se la concede. Decide entonces hacerse pasar por una señora mayor para poder ser, al menos, la canguro de sus hijos.', trailer_url = 'https://www.youtube.com/watch?v=23KfhRrtni8' WHERE id_api = 'tt0107614';

UPDATE Contenido SET id_tmdb = 9944, descripcion = 'Darby Shaw, una estudiante de Derecho, escribe un informe en el que analiza las posibles razones del reciente asesinato de dos jueces del Tribunal Supremo. Su informe, en principio descabellado, parece que toca material "sensible", pues pronto será objeto de una implacable persecución, de la que saldrá con vida gracias a la ayuda de un periodista que también quiere descubrir quiénes están detrás de esos asesinatos.', trailer_url = 'https://www.youtube.com/watch?v=MgmItLPfdO4' WHERE id_api = 'tt0107798';

UPDATE Contenido SET id_tmdb = 9800, descripcion = 'Andrew Beckett, un joven y prometedor abogado de Philadelphia, es despedido del prestigioso bufete en el que trabaja cuando sus jefes se enteran de que ha contraído el sida. Decide entonces demandar a la empresa por despido improcedente, pero en un principio ningún abogado acepta defender su caso.', trailer_url = 'https://www.youtube.com/watch?v=qf49UApA88s' WHERE id_api = 'tt0107818';

UPDATE Contenido SET id_tmdb = 11971, descripcion = 'El Príncipe Don Pedro de Aragón (Denzel Washington) regresa victorioso de una batalla acompañado de su hermano bastardo Don Juan (Keanu Reeves), de Benedicto (Kenneth Branagh) y de Claudio (Robert Sean Leonard), un joven florentino que ha sido colmado de honores por el gran valor mostrado en el campo de batalla. Son recibidos con gran regocijo por el caballero Leonato, que vive con su hija Hero (Beckinsale) y su sobrina Beatriz (Emma Thompson) en una paradisíaca villa de la campiña siciliana (Mesina). En el siglo XV, Sicilia formaba parte de los dominios de la Corona de Aragón, lo que explica el nombre de alguno de los personajes.', trailer_url = 'https://www.youtube.com/watch?v=rbSN4Lv_N4g' WHERE id_api = 'tt0107616';

UPDATE Contenido SET id_tmdb = 713, descripcion = 'Año 1851. Ada, que es muda desde niña, acaba de enviudar. Un matrimonio concertado la obliga a dejar su Escocia natal y viajar a Nueva Zelanda, acompañada de su hija y de su piano. Allí conoce a su futuro marido, un próspero granjero que se niega a llevar a casa el piano. Abandonado en la playa, el instrumento será rescatado por un vecino que establece un extraño pacto con Ada: él la dejará usar su piano a cambio de que ella se deje tocar.', trailer_url = 'https://www.youtube.com/watch?v=61ooIf1QDZo' WHERE id_api = 'tt0107822';

UPDATE Contenido SET id_tmdb = 9644, descripcion = 'Un inconformista policía de Los Ángeles recibe como compañero a un veterano a punto de jubilarse. Ambos investigarán el asesinato de una compañera. Parodia del cine de acción, en concreto de las "buddy movies": películas alrededor de una pareja de policías con diferentes personalidades.', trailer_url = 'https://www.youtube.com/watch?v=Xtz0Zw0eSkA' WHERE id_api = 'tt0107659';

UPDATE Contenido SET id_tmdb = 9479, descripcion = 'Cuando Jack Skellington, el Señor de Halloween, descubre la Navidad, se queda fascinado y decide mejorarla. Sin embargo, su visión de la festividad es totalmente contraria al espíritu navideño. Sus planes incluyen el secuestro de Santa Claus y la introducción de cambios bastante macabros. Sólo su novia Sally es consciente del error que está cometiendo.', trailer_url = 'https://www.youtube.com/watch?v=IoYahD_xNR0' WHERE id_api = 'tt0107688';

UPDATE Contenido SET id_tmdb = 9559, descripcion = 'Un niño secuestrado entabla amistad con su captor: un convicto fugitivo que huye de la ley, perseguido por un honorable mariscal de EE.UU.', trailer_url = 'https://www.youtube.com/watch?v=5MXFbseYt6E' WHERE id_api = 'tt0107808';

UPDATE Contenido SET id_tmdb = 1245, descripcion = 'Stevens es el perfecto mayordomo inglés, un ideal que lleva hasta el extremo al servicio de su señor, Lord Darlington. Como muchos otros miembros de la aristocracia británica en los años 30, Darlington es captado por los nazis para intentar establecer una vía de comunicación con el gobierno del Reino Unido. La señorita Kenton es el ama de llaves de la mansión, una mujer joven y llena de vida que contempla horrorizada lo que sucede escaleras arriba. A pesar de sus temores, ella y Stevens se van enamorando poco a poco, aunque ninguno de ellos quiera reconocerlo.', trailer_url = 'https://www.youtube.com/watch?v=jALmEb72beg' WHERE id_api = 'tt0107943';

UPDATE Contenido SET id_tmdb = 7007, descripcion = 'Una joven y bella modelo muere asesinada durante una recepción organizada en Los Ángeles por la corporación japonesa Nakamoto. Le encargan el caso al teniente Smith, un rudo policía del departamento de homicidios al que ayuda en las pesquisas el capitán John Connor, un agente retirado con un profundo conocimiento de la cultura nipona.  Adaptación al cine de una controvertida novela de Michael Crichton que, bajo la apariencia de un thriller, esconde una crítica a la cada vez mayor influencia japonesa en la economía estadounidense y a las prácticas agresivas y racistas de las grandes empresas niponas.', trailer_url = 'https://www.youtube.com/watch?v=4gPr_qix-po' WHERE id_api = 'tt0107969';

UPDATE Contenido SET id_tmdb = 11528, descripcion = 'Durante un verano de amistad y aventura, un chico entra a formar parte de la banda, nueve chavales se convierten en un equipo y su líder es leyenda ya que se enfrenta al temido misterio tras el muro del campo de la derecha.', trailer_url = 'https://www.youtube.com/watch?v=52yV9dSzV1E' WHERE id_api = 'tt0108037';

UPDATE Contenido SET id_tmdb = 8005, descripcion = 'Robin de Loxley es un valiente arquero de la Edad Media que regresa a Inglaterra. El reino está bajo el poder del avaricioso rey Juan, que no hacer más que subir los impuestos a los empodrecidos habitantes.Robin robará a los ricos para dárselo a los pobres, a la ves que vive numerosas aventuras.', trailer_url = 'https://www.youtube.com/watch?v=rL_aElj93ws' WHERE id_api = 'tt0107977';

UPDATE Contenido SET id_tmdb = 5550, descripcion = 'La ciudad de Detroit está dominada por bandas de mafiosos que no pueden ser controlados por la policía, pero sí por los poderosos dirigentes de la multinacional OCP, los cuales quieren destruir un barrio de inmigrantes y, en su lugar, construir un complejo residencial de lujo. Para lograrlo, sobornan a los políticos y controlan a casi toda la policía, pero no consiguen controlar a Robocop, que protegerá a los inocentes. Cuando todo parece perdido para los oprimidos, unos pocos policías tienen un arranque de honestidad y se unen a Robocop para restablecer el orden y la justicia.', trailer_url = 'https://www.youtube.com/watch?v=VWBo9-YtSQs' WHERE id_api = 'tt0107978';

UPDATE Contenido SET id_tmdb = 424, descripcion = 'Oskar Schindler, un hombre de enorme astucia y talento para las relaciones públicas, organiza un ambicioso plan para ganarse la simpatía de los nazis. Después de la invasión de Polonia por los alemanes, consigue, gracias a sus relaciones con los nazis, la propiedad de una fábrica de Cracovia. Allí emplea a cientos de operarios judíos, cuya explotación le hace prosperar rápidamente. Su gerente, también judío, es el verdadero director en la sombra, pues Schindler no tiene el menor conocimiento industrial.', trailer_url = 'https://www.youtube.com/watch?v=0Z9cLiliBh0' WHERE id_api = 'tt0108052';

UPDATE Contenido SET id_tmdb = 14534, descripcion = 'A Daniel E. Ruettiger todo el mundo le decía que era imposible que pudiera triunfar. Su padre, sus profesores, entrenadores y amigos estaban convencidos de que Rudy nunca podría ser admitido en la Universidad de Nôtre Dame y menos aún entrar en el más prestigioso programa de fútbol americano de la nación. Así las cosas, Daniel se va hundiendo cada vez más.', trailer_url = 'https://www.youtube.com/watch?v=7YKYFz-0a1E' WHERE id_api = 'tt0108002';

UPDATE Contenido SET id_tmdb = 695, descripcion = 'Adaptación de varios relatos del escritor norteamericano Raymond Carver (1939-1988). Retrato de la vida cotidiana de un grupo muy heterogéneo de personas que viven en Los Ángeles e intentan afrontar como pueden las dificultades de su vida laboral y personal, gentes que se cruzan indiferentes ignorando los dramas ajenos. Sin embargo, en medio de tanta cotidianeidad, late la presencia del terror.', trailer_url = 'https://www.youtube.com/watch?v=ePyhGz9_RCI' WHERE id_api = 'tt0108122';

UPDATE Contenido SET id_tmdb = 11236, descripcion = 'Tras la muerte de sus padres, Mary, una niña británica nacida en la India, es enviada a Inglaterra a vivir con un tío suyo. Se trata de un personaje huraño y distante que vive en una gran mansión gótica, gobernada por una estricta ama de llaves, la señora Medlock. Mary descubre un gran jardín, cerrado y abandonado durante años, que se convertirá en un mágico refugio para ella y sus dos nuevos amigos: Colin, un inválido caprichoso, y Dickon, ingenuo y lleno de bondad. Mientras disfrutan del jardín, se establece entre ellos una sólida y especial relación que cambiará su destino para siempre.', trailer_url = 'https://www.youtube.com/watch?v=13czbJPP9ZQ' WHERE id_api = 'tt0108071';

UPDATE Contenido SET id_tmdb = 14291, descripcion = 'El pequeño Josh Waitzkin tiene verdadera pasión por el ajedrez y quiere convertirse en un nuevo Bobby Fischer, su ídolo. Sus padres, por supuesto, le ayudarán en todo lo posible, pues ven el crío un futuro maestro.', trailer_url = 'https://www.youtube.com/watch?v=hOTc4D0uQNk' WHERE id_api = 'tt0108065';

UPDATE Contenido SET id_tmdb = 6279, descripcion = 'Dolores vuelve a colocarse los hábitos de la hermana Mary Clarence. Sus compañeras monjas necesitan ayuda para evitar el cierre de la escuela parroquial de Saint Francis. Con su colaboración y la del resto de las divertidas monjas, se prepara la participación del colegio en un concurso de coros escolares.', trailer_url = 'https://www.youtube.com/watch?v=_QcgjGyRnuw' WHERE id_api = 'tt0108147';

UPDATE Contenido SET id_tmdb = 858, descripcion = 'Tras la muerte de su esposa, el arquitecto Sam Baldwin se encuentra muy abatido. Jonah, su hijo de ocho años, cree que su padre necesita una mujer que le devuelva la alegría de vivir; así que el dia de Navidad decide llamar a un programa de radio para contar su historia. Miles de mujeres le escuchan: una de ellas es Annie Reed, que está a punto de contraer matrimonio. Pero Annie comienza a obsesionarse con la idea de que debe conocer a Sam antes de casarse con su novio.', trailer_url = 'https://www.youtube.com/watch?v=2bnxHgO59A4' WHERE id_api = 'tt0108160';

UPDATE Contenido SET id_tmdb = 9607, descripcion = 'Basada en el famoso videojuego de la compañía Nintendo. Dos fontaneros de Brooklyn, Mario y Luigi, viajan a otra dimensión para rescatar a una princesa del malvado dictador Rey koopa y evitar que se apodere del mundo.', trailer_url = 'https://www.youtube.com/watch?v=GE7zdN-Qzvw' WHERE id_api = 'tt0108255';

UPDATE Contenido SET id_tmdb = 11969, descripcion = 'En 1879 y tras la sangrienta Guerra Civil norteamericana, mucha gente emigró hacia el oeste del país en busca de prosperidad y fortuna. entre ellos, Wyatt Earp, un hombre de la ley que había abandonado la placa y la pistola para formar una familia, o John "Doc"Hollyday, un ex caballero del sur reconvertido en pistolero y jugador.', trailer_url = 'https://www.youtube.com/watch?v=XTWYKf5hXIg' WHERE id_api = 'tt0108358';

