UPDATE Contenido SET id_tmdb = 11074, descripcion = 'El detective Tom Hardy es de una familia de origen irlandés afincada en Pittsburgh y que desde hace cinco generaciones forma parte de la policía de esa ciudad. Por su parte, la rama italiana de la familia, encabezada por su tío Nick De Tillo, se dedica tradicionalmente a diversas actividades delictivas. Tom, con ayuda de Vince, su padre, sigue la pista de un peligroso psicópata, pero en el transcurso de la persecución sufren un accidente del que Vince resulta muerto. Jimmy De Tillo, primo de Tom, es detenido como principal sospechoso.', trailer_url = 'https://www.youtube.com/watch?v=doagfMS5fdA' WHERE id_api = 'tt0108238';

