UPDATE Contenido SET id_tmdb = 10057, descripcion = 'Un habilidoso espadachín de provincias, D´Artagnan, viaja a París con la intención de cumplir su sueño de seguir los pasos de su padre: unirse al cuerpo de mosqueteros de la guardia del Rey. Entretanto el diabólico consejero real, el Cardenal Richelieu, con la ayuda del Capitán Rochefort, ha desmantelado la guardia del Rey en un intento de facilitar sus aspiraciones de usurpar su poder y gobernar Francia.', trailer_url = 'https://www.youtube.com/watch?v=FMy1TFRF8Lk' WHERE id_api = 'tt0108333';

UPDATE Contenido SET id_tmdb = 319, descripcion = 'El joven y solitario Clarence está celebrando su cumpleaños como siempre lo hace, viendo películas de Kun-fú en un destartalado cine de Detroit, cunado una rubia explosiva, Alabama, hace su entrada en la sala derramando palomitas sobre él. De este incidente surgirá una loca aventura de amor que llevará a los dos jóvenes a vivir una verdadera noche de pasión. Alabama es en realidad una prostituta alquilada por el mejor amigo de Clarence como regalo de cumpleaños. Los dos jóvenes se enamoran y contraen matrimonio. Clarence intenta alejar a su mujer de la prostitución y se enfrenta con su chulo al ir a recoger las pertenencias de Alabama, pero al abrir la maleta se encuentran con una considerable cantidad de cocaína que utilizarán como esperanza para realizar todos lo sueños que han deseador.', trailer_url = 'https://www.youtube.com/watch?v=TUq0PgnHve0' WHERE id_api = 'tt0108399';

UPDATE Contenido SET id_tmdb = 108, descripcion = 'En un accidente de coche, Julie pierde a su esposo Patrice, un prestigioso compositor, y a la hija de ambos, Anna. Al recuperarse de sus lesiones, Julie decide comenzar una nueva vida, independiente, solitaria y anónima, alejada de los privilegios que antes disfrutaba. En su propósito se cruza Sandrine, una periodista especializada en música que la persigue intentando probar que era Julie quien componía las piezas que hicieron famoso a su marido. También pretenderá entrar en su vida Olivier, el ayudante de Patrice, enamorado de Julie desde muchos años atrás, que la convence para terminar el «Concierto para Europa», una ambiciosa obra inacabada del músico.', trailer_url = 'https://www.youtube.com/watch?v=ZZcRioiaZAU' WHERE id_api = 'tt0108394';

UPDATE Contenido SET id_tmdb = 1587, descripcion = 'Gilbert es un chico del pequeño pueblo de Endora atrapado allí por las obligaciones familiares. Tras el suicidio de su padre, debe hacerse cargo de su hermano menor, que es deficiente, de sus dos hermanas y de una madre obesa que pesa más de 200 kilos. Su aburrida vida transcurre entre el colmado donde trabaja, su familia y la relación que mantiene con una mujer casada. La llegada al pueblo de una joven optimista llamada Becky cambiará su rutina.', trailer_url = 'https://www.youtube.com/watch?v=QvwV4GT-av8' WHERE id_api = 'tt0108550';

