UPDATE Contenido SET id_tmdb = 13595, descripcion = 'Los Lone Rangers son una banda de Rock de Los Ángeles que lucha por abrirse camino y que lo tiene todo: el sonido, el look y la actitud. Seguros de su talento, lo único que necesitan es alguien que les escuche y por eso secuestran una emisora de radio.', trailer_url = 'https://www.youtube.com/watch?v=FD9a_EVDk-s' WHERE id_api = 'tt0109068';

UPDATE Contenido SET id_tmdb = 2759, descripcion = 'Tres artistas de cabaret que viven en Sidney son contratadas para actuar durante cuatro semanas en un hotel de Alice Springs, en medio del desierto rojo de Australia. Les espera una gran aventura, pero una cosa es atravesar el país en autobús, dejando atrás todos sus problemas, y otra llegar a su destino sanas y salvas. Sobre todo si Felicia y Mitzi son reinas del drag y Benardette transexual. Inician así un periplo de dos semanas, con música sonando a toda pastilla y el autocar repleto de un llamativo vestuario y zapatos de plataforma.', trailer_url = 'https://www.youtube.com/watch?v=VFmwVI-5lfU' WHERE id_api = 'tt0109045';

UPDATE Contenido SET id_tmdb = 58128, descripcion = 'Dos jóvenes sin blanca ni planes de futuro descubren que cerca de ellos vive una atractiva heredera, así que cada uno tratará de engatusarla para casarse con ella.', trailer_url = NULL WHERE id_api = 'tt0109117';

UPDATE Contenido SET id_tmdb = 11212, descripcion = 'En una bonita mañana de verano, en un privilegiado suburbio de una gran ciudad, Baby Bink se dispone a comenzar su mañana como siempre suele hacer: su desayuno, un relajado baño y su libro de cuentos favoritos: "El bebé va de paseo". Pero la tranquila vida de Baby Bink se ve amenazada cuando es secuestrado por una banda de inteligentes ladrones que se hacen pasar por fotógrafos de niños. Los secuestradores pronto se darán cuenta de lo difícil que resulta cuidar de un bebé y, aunque no intencionadamente, Baby Bink se dispone a explorar la ciudad y esos sitios que tan bien conoce de su libro de cuentos. Los secuestradores pasarán por toda clase de aventuras y situaciones límites tratando de localizar al bebé que, inteligentemente, ha tomado un día libre.', trailer_url = 'https://www.youtube.com/watch?v=JNhjv-7IGrE' WHERE id_api = 'tt0109190';

UPDATE Contenido SET id_tmdb = 306, descripcion = 'El detective de Detroit Axel Foley emplea todo su coraje para perseguir a unos despiadados asesinos con la ayuda de sus viejos compañeros Serge y Billy Rosewood. Las investigaciones lo conducen al popular parque temático de Los Ángeles WonderWorld. Allí, repentinamente, Axel se convierte en la nueva atracción del lugar, bien sea quedándose colgado de una araña gigante para rescatar a un niño o disfrazándose de Okey Dokey, un enorme elefante azul.', trailer_url = 'https://www.youtube.com/watch?v=GAygpaSniHM' WHERE id_api = 'tt0109254';

UPDATE Contenido SET id_tmdb = 1668, descripcion = 'Las aventuras de seis jóvenes neoyorquinos unidos por una divertida amistad. Entre el amor, el trabajo y la familia, comparten sus alegrías y preocupaciones en el Central Perk, su café favorito.', trailer_url = 'https://www.youtube.com/watch?v=ki6Mbtnl_9I' WHERE id_api = 'tt0108778';

Phoebe intenta advertirles a sus amigos que Rachel va en camino a Londres. Después de emborracharse, Chandler y Monica tienen relaciones sexuales.', 46, '1998-05-07');

