UPDATE Contenido SET id_tmdb = 8467, descripcion = 'La vida de Lloyd y Harry, dos amigos de una estupidez supina, es un auténtico desastre. El primero trabaja como chófer de una limousina, y el segundo se dedica a transportar perros. Cuando Lloyd se enamora de una chica de buena posición, que deja olvidado un maletín en el coche, los dos amigos emprenden un viaje por todo el país para devolvérselo.', trailer_url = 'https://www.youtube.com/watch?v=wWBsRJguJqg' WHERE id_api = 'tt0109686';

UPDATE Contenido SET id_tmdb = 8984, descripcion = 'Tom Sanders es un maduro y atractivo ejecutivo que trabaja en una empresa de alta tecnología y que está a punto de ser ascendido. Sin embargo, en una semana crucial para su vida, verá sus aspiraciones rotas cuando, en lugar de él, es nombrada para el puesto Meredith Jonson, una antigua novia suya que ahora es una ambiciosa ejecutiva.', trailer_url = 'https://www.youtube.com/watch?v=_UtApAxpjJ0' WHERE id_api = 'tt0109635';

UPDATE Contenido SET id_tmdb = 11929, descripcion = 'Dolores Claiborne es acusada del asesinato de Vera Donovan, la dueña de la casa en la que trabaja como asistenta desde hace más de veinte años. Selena, la hija de Dolores, vuelve a su pueblo natal para intentar probar la inocencia de su madre, pero allí ambas se tendrán que enfrentar a un implacable detective y a un sórdido pasado.', trailer_url = 'https://www.youtube.com/watch?v=AqPvXzess2I' WHERE id_api = 'tt0109642';

UPDATE Contenido SET id_tmdb = 11934, descripcion = 'Cuando el director de una importante empresa se suicida, todos los accionistas se ponen de acuerdo y elaboran un plan para obtener los mayores beneficios posibles: se trata de poner al frente del consejo de dirección a alguien fácilmente manipulable. Todo parece sencillo hasta que entra en escena Amy Archer.', trailer_url = 'https://www.youtube.com/watch?v=2o5yi6hFg4Q' WHERE id_api = 'tt0110074';

UPDATE Contenido SET id_tmdb = 712, descripcion = 'Charles y sus amigos, todos ellos solteros y sin compromiso, han llegado a una edad en la que casi todos sus conocidos se han casado. En una de las bodas, a la que el grupo ha sido invitado, Charles conoce a Carrie, una americana de la que se enamora a primera vista. Esa noche la pasan juntos, pero no vuelven a verse. Tendrán que esperar a la siguiente boda, en la que Carrie le presenta a su prometido.', trailer_url = 'https://www.youtube.com/watch?v=tvdlnbfaJ3E' WHERE id_api = 'tt0109831';

UPDATE Contenido SET id_tmdb = 3036, descripcion = 'La prematura muerte de su madre durante un parto, arranca violentamente a Víctor Frankenstein de su idílica vida en Ginebra. Desde ese día, la posibilidad de vencer a la muerte será su obsesión y, por ello, decide estudiar medicina en Inglostadt. Allí conoce al siniestro profesor Waldman, de quien se rumorea que pasó su juventud estudiando la posibilidad de crear un ser humano. Víctor no sólo se interesa por sus experimentos, sino que está dispuesto a llegar hasta el fondo de la cuestión cueste lo que cueste.', trailer_url = 'https://www.youtube.com/watch?v=ZkZAPkKDd9I' WHERE id_api = 'tt0109836';

UPDATE Contenido SET id_tmdb = 1024, descripcion = 'Nueva Zelanda, mediados del siglo XX. La amistad entre dos compañeras de colegio adolescentes es tan intensa y estrecha que despierta el recelo de los padres de una de ellas. Las chicas crean un mundo imaginario y lleno de fantasía en el que se refugian para vivir de espaldas al resto del mundo. Basada en hechos reales.', trailer_url = 'https://www.youtube.com/watch?v=_bIUDcnHDlg' WHERE id_api = 'tt0110005';

UPDATE Contenido SET id_tmdb = 628, descripcion = 'En "Entrevista con el Vampiro" somos testigos de cómo el vampiro llamado Louis revela a un periodista su condición sobrenatural y su extensa "vida" a través de los últimos dos siglos. Una historia que comienza en la vieja Nueva Orleans del siglo dieciocho, cuando franceses y españoles habitaban las costas del Mississipi. Lestat, un vampiro pomposo y arrogante, acento francés, arrebata la vida humana de Louis de Pointe du Lac, joven criollo y terrateniente signado por desgracias familiares, para otorgarle el don oscuro: lo convierte en uno de los de su clase. A partir de ese momento los une no sólo su condición vampírica sino un afecto-odio que los llevará al principio por caminos similares y luego a la más trágica separación. Conforme pasan las décadas, estos personajes inmortales crean a una niña vampira de nombre Claudia, la cual influirá indefectiblemente en su separación.', trailer_url = 'https://www.youtube.com/watch?v=qmFYu8x46VY' WHERE id_api = 'tt0110148';

UPDATE Contenido SET id_tmdb = 10660, descripcion = 'Charlie Lang es un buen policía que está casado con Muriel, una mujer muy ambiciosa que sólo sueña con tener mucho dinero y abandonar el humilde barrio de Queens. Un día entra con su compañero Bo en una pequeña cafetería y, como no tiene dinero para dejar propina, le hace a la camarera Yvonne una promesa: si gana en el próximo sorteo de la loto, compartirá el premio con ella. Inesperadamente, el billete resulta premiado con cuatro millones de dólares. Para desesperación de Muriel, Charlie mantiene su promesa y entrega la mitad a Yvonne. La prensa y la televisión se harán eco inmediatamente del insólito caso.', trailer_url = 'https://www.youtube.com/watch?v=hpIeqy8VRJU' WHERE id_api = 'tt0110167';

UPDATE Contenido SET id_tmdb = 10897, descripcion = 'Spanky y los miembros del "Club de machotes odia-mujeres" se reúnen. Alfalfa se ha enamorado de Darla, amenazando la existencia del gran club “solo para chicos”. Futuros problemas se avecinarán cuando destruyen su centro de operaciones, y los matones del barrio roban su coche, "The Blur". ¿Cómo podrán ganar la carrera y el gran trofeo? Además de esta serie de infortunios aparece un nuevo chico en el barrio, Waldo, que es un refinado niño rico, interesado también en Darla. A través de las travesuras y el jaleo, trucos e ingenuidad, los pillos aprenderán el valor de la verdadera amistad… e incluso el gusto por las chicas.', trailer_url = 'https://www.youtube.com/watch?v=FgyCE8VsGKM' WHERE id_api = 'tt0110366';

UPDATE Contenido SET id_tmdb = 6280, descripcion = 'El doctor Alex Hesse (Arnold Schwarzenegger), un científico serio y disciplinado, ha inventado una droga llamada Esperana que facilita el embarazo. Con Alex trabaja Larry Arbogast (Danny DeVito), que, por más que lo intenta, no puede lograr que su mujer Angela (Pamela Reed) quede embarazada. Alex y Larry son trasladados al laboratorio de la doctora Diana Reddin (Emma Thompson), especialista en la congelación de óvulos fecundados. Como Alex y Larry no quieren perder sus hallazgos científicos, roban un óvulo y lo implantan donde a nadie se le ocurriría buscarlo: en el cuerpo de Alex que, sorprendentemente, queda embarazado. Alex se enamora de Diana, pero le oculta su embarazo. Por lo demás, a medida que la gestación avanza, su carácter se vuelve más tierno y menos tímido. (FILMAFFINITY)', trailer_url = 'https://www.youtube.com/watch?v=vvFBLJ7C1eo' WHERE id_api = 'tt0110216';

UPDATE Contenido SET id_tmdb = 4476, descripcion = 'William Ludlow es un coronel separado de su mujer que vive con sus tres hijos en un gran rancho de Montana, en las colinas de las Montañas Rocosas. La Primera Guerra Mundial y una bella mujer cambiarán el destino de cada uno de ellos para siempre. Sus hijos son el indómito Tristan, el sensato Alfred y el menor Samuel, que acaba de traer al rancho a su bella prometida, Susannah.', trailer_url = 'https://www.youtube.com/watch?v=JnJoaUzvXc4' WHERE id_api = 'tt0110322';

UPDATE Contenido SET id_tmdb = 9587, descripcion = 'Con su marido en la guerra civil americana, Marmee se queda sola con sus cuatro hijas; sus “mujercitas”: Jo, un torbellino de energía; Meg, más formal; la frágil Beth y la romántica Amy. A medida que pasan los años, las hermanas comparten algunos de sus recuerdos más queridos y dolorosos, mientras Marmee y la tía March les orientan sobre cuestiones como la independencia, el amor y la importancia de la familia.', trailer_url = 'https://www.youtube.com/watch?v=sET83nlk1NU' WHERE id_api = 'tt0110367';

UPDATE Contenido SET id_tmdb = 8587, descripcion = 'La sabana africana es el escenario en el que tienen lugar las aventuras de Simba, un pequeño león que es el heredero del trono. Sin embargo, se ve forzado a exiliarse al ser injustamente acusado de la muerte de su padre. Durante su destierro, hará buenas amistades y, finalmente, regresará para recuperar lo que legítimamente le corresponde.', trailer_url = 'https://www.youtube.com/watch?v=bjJvvrKl83M' WHERE id_api = 'tt0110357';

UPDATE Contenido SET id_tmdb = 101, descripcion = 'Stan es un corrupto agente de la DEA cuya codicia le lleva a cometer asesinatos en las calles de Nueva York. El mortal juego del gato y el ratón empieza cuando se cruza en su camino un solitario hombre, llamado León. León es asesino a sueldo, un personaje indestructible e indocumentado, que sólo bebe leche y se ocupa de sus plantas. En medio se encuentra una huerfanita de 12 años, que no puede olvidar al hombre que asesinó a su familia.', trailer_url = 'https://www.youtube.com/watch?v=AjGr4tjEa5M' WHERE id_api = 'tt0110413';

UPDATE Contenido SET id_tmdb = 236, descripcion = 'Muriel es una chica con sobrepeso que vive en un mundo de fantasía, canciones de ABBA y catálogos nupciales. Sueña con un príncipe azul que algún día la liberará de su odiosa familia y de sus burlonas amigas. Cansada de esperar su llegada, decide irse a la ciudad y buscarlo. Uno de los mayores éxitos del cine australiano de los noventa.', trailer_url = 'https://www.youtube.com/watch?v=JJVWXHRDqec' WHERE id_api = 'tt0110598';

UPDATE Contenido SET id_tmdb = 680, descripcion = 'Jules y Vincent, dos asesinos a sueldo con muy pocas luces, trabajan para Marsellus Wallace. Vincent le confiesa a Jules que Marsellus le ha pedido que cuide de Mia, su mujer. Jules le recomienda prudencia porque es muy peligroso sobrepasarse con la novia del jefe. Cuando llega la hora de trabajar, ambos deben ponerse manos a la obra. Su misión: recuperar un misterioso maletín.', trailer_url = 'https://www.youtube.com/watch?v=Yydi7TMo5n0' WHERE id_api = 'tt0110912';

UPDATE Contenido SET id_tmdb = 854, descripcion = 'Stanley es un ingenuo empleado de banca incapaz de enterarse de cuándo se aprovechan de él, al que su jefe mangonea, al que su casera humilla, y al que solamente su perro parece ser capaz de aguantar. Su amigo Charlie le invita a ir al cabaret Coco Bongo para intentar estimularle y conseguir que espabile, pero antes de que eso ocurra, aparece la bella Tina Carlyle, que entra en el banco para hablar con Stanley y de paso fotografiar la caja fuerte con una mini cámara. Es entonces cuando Stanley encuentra una máscara que le da grandes poderes y que también le quita todos sus miedos: ahora es libre de actuar como quiera.', trailer_url = 'https://www.youtube.com/watch?v=uPrUiKgQVQk' WHERE id_api = 'tt0110475';

UPDATE Contenido SET id_tmdb = 36593, descripcion = 'La noche de los Oscar, ¿quién ganará?, ¿quién perderá?, y por favor, ¿puede alguien quitar a ese imbécil del escenario? ¡Esperen! No se trata de un imbécil normal y corriente. Es el teniente Frank Drebin, destrozando la ceremonia para detener un plan terrorista que podría ser su final… Y va a convertirse en el principio de toda una locura.', trailer_url = 'https://www.youtube.com/watch?v=WQ3p19A1mbw' WHERE id_api = 'tt0110622';

UPDATE Contenido SET id_tmdb = 2788, descripcion = 'Lelaina Pierce (Winona Ryder), ayudante de producción en un programa matinal de televisión, sueña con ser directora de cine. Mientras llega su gran oportunidad rueda un vídeo de sus amigos en los que estos hablan de su realidad cotidiana, sus ambiciones y su falta de expectativas. Entre tanto, debe elegir entre dos amores, un yuppie y su leal amigo Troy. Drama generacional de joven y conocido reparto que se promocionó como la película de la "generación X".', trailer_url = 'https://www.youtube.com/watch?v=xDYGo0UgIVM' WHERE id_api = 'tt0110950';

UPDATE Contenido SET id_tmdb = 241, descripcion = 'Micky y Mallory son una poco convencional pareja de jovenes amantes que sienten que han nacido para matar: son dos despiadados criminales que tienen atemorizada a la población. Un presentador de un programa sensacionalista se aprovecha de la fascinación que su personalidad ejerce sobre el público y convierte a los asesinos en héroes televisivos.', trailer_url = 'https://www.youtube.com/watch?v=vv7-39m08u0' WHERE id_api = 'tt0110632';

UPDATE Contenido SET id_tmdb = 9359, descripcion = 'Bret Maverick es un atractivo timador con una extraordinaria facilidad para escabullirse de los enredos que él mismo provoca. Sólo una persona es capaz de perturbarle: Annabelle, una habilidosa jugadora de póquer que se cruza en su camino.', trailer_url = 'https://www.youtube.com/watch?v=mQ69CVbCiow' WHERE id_api = 'tt0110478';

UPDATE Contenido SET id_tmdb = 10510, descripcion = 'Durante un desfile navideño organizado por los grandes almacenes Macy, el hombre que encarna a Santa Claus es sustituido por indisposición. Un anciano llamado Kris se ofrece a la señora Walker, responsable del desfile, para encarnar a Santa Claus. Después del desfile es contratado por dar a la perfección el tipo de personaje, pero todo se complica cuando él asegura que es el auténtico Santa Claus. Remake del film de la Fox "De ilusión también se vive" (Miracle on 34th Street) de 1947.', trailer_url = 'https://www.youtube.com/watch?v=yiypbCFV7Ao' WHERE id_api = 'tt0110527';

UPDATE Contenido SET id_tmdb = 11450, descripcion = 'Entre 1956 y 1959, Charles Van Doren, perteneciente a una prestigiosa familia de intelectuales y profesor de inglés de la universidad de Columbia, se convirtió en uno de los personajes más populares de Estados Unidos gracias a su participación en el concurso de televisión ”Twenty One”. Durante tres años contestó siempre las más variadas y difíciles preguntas. Pero, cuando su popularidad había llegado a todos los rincones del país, estalló el escándalo: uno de los concursantes eliminados denunció que el concurso estaba amañado.', trailer_url = 'https://www.youtube.com/watch?v=bj-m3Ddmn0E' WHERE id_api = 'tt0110932';

UPDATE Contenido SET id_tmdb = 278, descripcion = 'Acusado del asesinato de su mujer, Andrew Dufresne, tras ser condenado a cadena perpetua, es enviado a la prisión de Shawshank. Con el paso de los años conseguirá ganarse la confianza del director del centro y el respeto de sus compañeros presidiarios, especialmente de Red, el jefe de la mafia de los sobornos.', trailer_url = 'https://www.youtube.com/watch?v=4u87tmlj4oE' WHERE id_api = 'tt0111161';

UPDATE Contenido SET id_tmdb = 11395, descripcion = 'Scott Calvin es el padre divorciado de Charlie. La relación entre ellos se ha vuelto insoportable, pero en Nochebuena Santa Claus muere al caer del techo de su casa. Con la ayuda de Charlie, Scott será capaz de reemplazarle temporalmente.', trailer_url = 'https://www.youtube.com/watch?v=9-d6L6u5594' WHERE id_api = 'tt0111070';

UPDATE Contenido SET id_tmdb = 11011, descripcion = 'Ricky Ricón es el niño más rico del mundo; tiene su propio parque de atracciones, un Burguer en su casa y su profesora de gimnasia es la mismísima Claudia Schiffer. Richie tiene además el amor de sus padres, pero no es feliz; echa de menos jugar al béisbol en la calle con los chicos del barrio. Cuando sus padres desaparecen en el Triángulo de las Bermudas, el muchacho sospecha que detrás de la desaparición se encuentra Laurence Van Dogh, un ejecutivo de Industrias Richie que pretende hacerse con la compañía asesinando a sus padres. Sin embargo, Richie y su nueva pandilla de chiflados amiguetes no están dispuestos a rendirse a la primera... son capaces de cualquier travesura y la fuerza de la amistad es muy poderosa. Con su ayuda intentará liberar a sus padres y salvar la compañía', trailer_url = 'https://www.youtube.com/watch?v=Yddr5thpDTE' WHERE id_api = 'tt0110989';

UPDATE Contenido SET id_tmdb = 8987, descripcion = 'Con motivo del cumpleaños de su hijo Roarke (Joseph Mazello), sus padres Gail (Streep) y Tom (Strathairn), cuyo matrimonio no pasa por un buen momento, deciden organizar una excursión familiar a las montañas, lejos de la civilización. El plan incluye un emocionante descenso de rafting por un río.', trailer_url = 'https://www.youtube.com/watch?v=WbGD81wUgC0' WHERE id_api = 'tt0110997';

UPDATE Contenido SET id_tmdb = 9905, descripcion = 'Tres compañeros de piso encuentran una maleta llena de dinero en la habitación de un nuevo y misterioso inquilino, que acaba de morir por sobredosis. En vez de llamar a la policía, deciden quedarse con el dinero, una decisión que implica no sólo deshacerse del cadáver, sino también que cada uno de ellos confíe en los otros dos.', trailer_url = 'https://www.youtube.com/watch?v=xKrfUAho5as' WHERE id_api = 'tt0111149';

UPDATE Contenido SET id_tmdb = 11667, descripcion = 'En una inexpugnable fortaleza un renegado señor de la guerra, M. Bison, mantiene a 63 rehenes, a los que matará si no recibe un desorbitado rescate de 20.000 millones de dólares. El coronel Guile y más de una docena de hombres -héroes multiétnicos- tratarán de localizar y liberar a los secuestrados.', trailer_url = 'https://www.youtube.com/watch?v=HsTKoGcFS78' WHERE id_api = 'tt0111301';

UPDATE Contenido SET id_tmdb = 2636, descripcion = 'Un experto en explosivos, antiguo miembro de la CIA, es contratado por una hermosa y misteriosa mujer con objeto de acabar con un grupo de mafiosos que asesinaron a sus padres cuando ella era una niña.', trailer_url = 'https://www.youtube.com/watch?v=SS75LoRrmMg' WHERE id_api = 'tt0111255';

UPDATE Contenido SET id_tmdb = 1637, descripcion = 'Jack Traven es un intrépido policía de Los Angeles. La supervivencia en esta ciudad para un agente de la ley no es tarea fácil, pero Jack, además de disfrutar de una proverbial buena suerte, conoce perfectamente los trucos para sortear el peligro. Sin embargo, tendrá que afrontar una dura prueba cuando queda atrapado en un autobús urbano que lleva instalada una bomba programada para explotar si el vehículo disminuye su velocidad a menos de 50 millas por hora (80km/h). Empieza así una loca carrera por la ciudad.', trailer_url = 'https://www.youtube.com/watch?v=3q_4xiR3VJQ' WHERE id_api = 'tt0111257';

UPDATE Contenido SET id_tmdb = 193, descripcion = 'James T. Kirk, Montgomery Scott y Pavel Chekov asisten al viaje inaugural del USS Enterprise-B, que es requerido para ayudar a un convoy de naves que se hallan atrapadas en un cinturón de energía. Debido a la inexperiencia del capitán, Kirk decide ayudar pero cuando la cubierta donde se hallaba es destruida por una ráfaga de energía, es dado por muerto.', trailer_url = 'https://www.youtube.com/watch?v=MUieGh1fHSI' WHERE id_api = 'tt0111280';

UPDATE Contenido SET id_tmdb = 2164, descripcion = 'Un coronel y un científico, movidos por distintos intereses, investigan el misterioso hallazgo en unas excavaciones de un extraño artefacto al que llaman "Puerta de las Estrellas". Acompañados de un equipo de reconocimiento, atraviesan la Puerta y son transportados a un lejano planeta.', trailer_url = 'https://www.youtube.com/watch?v=c3sgzrgpn8s' WHERE id_api = 'tt0111282';

UPDATE Contenido SET id_tmdb = 8831, descripcion = 'En un futuro donde es posible viajar al pasado, se ha creado la Comisión de Control del Tiempo, que realiza diversas misiones encaminadas a impedir la alteración de hechos que cambiarían el curso de la historia. Uno de los agentes de policía, Walker, que diez años antrás perdió a su mujer en un ataque criminal, regresa al pasado para rescatarla y acabar con el ambicioso senador McComb.', trailer_url = 'https://www.youtube.com/watch?v=7OPLHgw54h4' WHERE id_api = 'tt0111438';

UPDATE Contenido SET id_tmdb = 110, descripcion = 'Valentina, joven modelo que comienza a ser conocida, ha atropellado con su coche a Rita, una perra que esperaba cachorros. Después de curarla, intenta devolverla a su dueño. Asi conocerá a un hombre mayor, juez jubilado, que rechaza al animal. Valentina descubre que está obsesionado por una enfermiza afición: espiar a todo el mundo.', trailer_url = 'https://www.youtube.com/watch?v=BMm0goTX2qo' WHERE id_api = 'tt0111495';

UPDATE Contenido SET id_tmdb = 36955, descripcion = 'El agente especial Harry Tasker mantiene una doble vida. Harry habla seis idiomas, conoce y domina todas las formas de contraespionaje y trabaja como espía internacional para Omega, una agencia gubernamental ultrasecreta encargada de la neutralización del terrorismo nuclear. Por razones de seguridad nacional, Harry oculta su verdadera profesión a su mujer Helen, que empieza a aburrirse del hombre gris y rutinario que, según ella cree, se dedica a vender ordenadores. Harry, que tiene recursos y valor para salvar a su país, quizá no sea capaz de salvar su matrimonio. Pero, cuando Helen descubre la verdadera profesión de su marido, excitada por la novedad, decide ayudarle a acabar con un comando integrista que planea un sangriento atentado.', trailer_url = 'https://www.youtube.com/watch?v=hxd0bD6cKBc' WHERE id_api = 'tt0111503';

UPDATE Contenido SET id_tmdb = 109, descripcion = 'Karol ama profundamente a Dominique, pero el problema de impotencia sexual que sufre provoca el divorcio. Una serie de penurias se sucederán en la vida de Karol, que se verá obligado a volver a su Polonia natal y a intentar ganarse la vida como pueda.', trailer_url = 'https://www.youtube.com/watch?v=MTt8KGGZcaI' WHERE id_api = 'tt0111507';

UPDATE Contenido SET id_tmdb = 10395, descripcion = 'Un hombre que conduce de noche atropella a un animal. Cuando sale del vehículo, observa con admiración que se trata de un lobo por el que es mordido en un descuido. Una vez incorporado a su vida cotidiana comienza a notar una serie de extraños síntomas.', trailer_url = NULL WHERE id_api = 'tt0111742';

UPDATE Contenido SET id_tmdb = 12207, descripcion = 'Cuando el gobierno británico es descubierto traficando con obras de arte chinas fuera del país, el héroe Wong Fei Hung (Chan) utiliza sus extravagantes artes marciales para luchar contra los conspiradores y salvar las obras, antes de que sea demasiado tarde. Cuanto más bebe Hung, más ágil se vuelve, siendo capaz de defenderse de numerosos ataques, con increíbles movimientos. Hung consigue, de esta manera, afrontar todo tipo de desafíos.', trailer_url = 'https://www.youtube.com/watch?v=p4X2naY_2-k' WHERE id_api = 'tt0111512';

UPDATE Contenido SET id_tmdb = 11596, descripcion = 'La actriz que protagonizó la primera «Pesadilla en Elm Street» se empieza a obsesionar con su personaje y con la presencia de Freddy Kruger. A la vez, recibe una oferta para hacer una nueva secuela de la serie, escrita por el propio Craven, que se inspira en los sueños de la chica.', trailer_url = 'https://www.youtube.com/watch?v=GRlKEpNCiF0' WHERE id_api = 'tt0111686';

UPDATE Contenido SET id_tmdb = 12160, descripcion = 'Wyatt Earp es miembro de un familia de granjeros de Iowa que, al no prosperar su negocio, deciden participar en la Conquista del Oeste. En los nuevos estados que ya forman parte de los Estados Unidos reina la anarquía, por lo que Wyatt Earp decide hacerse agente de la ley, con todos los riesgos que comporta. Pronto hará amistad con Doc Holliday, un personaje mítico con un pasado que le precede y que le ayudará en unos momentos muy especiales.', trailer_url = 'https://www.youtube.com/watch?v=3deAQVbaqlY' WHERE id_api = 'tt0111756';

UPDATE Contenido SET id_tmdb = 9273, descripcion = 'Intentando superar el trauma que le ha dejado el fracaso de su última misión, donde no pudo evitar que muriera la mofeta que tenía que rescatar, el inefable detective Ace Ventura es requerido en su retiro en un monasterio de monjes budistas por un extraño personaje que le ofrece una fuerte suma de dinero para que trate de encontrar el animal sagrado de una tribu.', trailer_url = 'https://www.youtube.com/watch?v=DfqPjRMsRP0' WHERE id_api = 'tt0112281';

UPDATE Contenido SET id_tmdb = 568, descripcion = 'El Apolo 13 inicia su viaje a la luna en abril de 1970. Cuando la tripulación está a punto de llegar a su destino, una explosión en el espacio les hace perder oxígeno, energía y el curso de la nave... Todo se convierte en una situación desesperada para los tres hombres tripulantes, especialmente cuando el oxígeno amenaza con agotarse. Mientras, el mundo entero, que apenas un año antes conoció la gloria de la aventura espacial cuando el hombre pisó la luna, contiene la respiración a la espera de ver cómo acaba tan angustiosa espera.', trailer_url = 'https://www.youtube.com/watch?v=TS-xd9ecgKM' WHERE id_api = 'tt0112384';

UPDATE Contenido SET id_tmdb = 1457, descripcion = 'Miniserie de TV de 6 episodios. Adaptación en formato miniserie de la famosa novela de Jane Austen ambientada a comienzos del siglo XIX, en la que los prejuicios y las diferencias sociales constituyen un obstáculo casi insalvable en las relaciones amorosas.', trailer_url = 'https://www.youtube.com/watch?v=NZKmzkdXPoo' WHERE id_api = 'tt0112130';

UPDATE Contenido SET id_tmdb = 890, descripcion = 'En 2015, tras el catastrófico "Segundo Impacto" que devastó la Tierra, los "Ángeles" regresan para atacar. La organización NERV crea los Evas, robots bio-mecánicos pilotados por jóvenes como Shinji, Rei y Asuka, los únicos capaces de enfrentarlos. Mientras luchan, descubren oscuros secretos sobre la humanidad y su destino.', trailer_url = 'https://www.youtube.com/watch?v=Ni8kEQi1BwA' WHERE id_api = 'tt0112159';

UPDATE Contenido SET id_tmdb = 1813, descripcion = 'A crazy comedy about three rather strange parish priests exiled to Craggy Island, a remote island off the Irish west coast.', trailer_url = 'https://www.youtube.com/watch?v=ZvsmGfVXCOM' WHERE id_api = 'tt0111958';

UPDATE Contenido SET id_tmdb = 21032, descripcion = 'Balto, un perro lobo siberiani, mezcla de husky y lobo, se siente confundido en cuanto a sus orígenes y está marginado en Alaska, excepto por sus verdaderos amigos. Un día, de repente, se extiende una epidemia de difteria entre los niños de Nome, pero una violenta tormenta de nieve bloquea todas las rutas de transporte y la obtención de las medicinas necesarias se hace imposible... a menos que un grupo de perros pueda cruzar mil kilómetros tirando de un trineo a través de la atroz tormenta ártica y volver con la antitoxina. Y sólo Balto puede rescatar a los perros y salvar a los niños.', trailer_url = 'https://www.youtube.com/watch?v=Qrk3sqy1wjo' WHERE id_api = 'tt0112453';

UPDATE Contenido SET id_tmdb = 9737, descripcion = 'Un alijo de heroína valorada en unos 100 millones de dólares es robado del mismísimo depósito de la policía. El caso le será asignado a los agentes Burnett y Lowery, una pareja muy peculiar por los métodos que utilizan. La única pista que tienen para comenzar es la de un testigo que les ayudará a identificar a los atracadores y a la que tendrán que proteger.', trailer_url = 'https://www.youtube.com/watch?v=OLYENHi4IIc' WHERE id_api = 'tt0112442';

UPDATE Contenido SET id_tmdb = 9087, descripcion = 'Andrew Shepherd, el presidente de los Estados Unidos, acaba de enviudar. Sin embargo, inicia un inesperado romance con Sydney Wade, miembro de una importante organización ecologista. En plena campaña electoral, su rival, el republicano Bob Rumson, aprovechará esa relación para desacreditarlo.', trailer_url = 'https://www.youtube.com/watch?v=5E3VG3LL1Mo' WHERE id_api = 'tt0112346';

UPDATE Contenido SET id_tmdb = 9691, descripcion = 'Robert Rath es un combatiente en un campo de batalla que la mayoría de la gente ni tan siquiera sabe que existe, allí es donde practica un juego mortal en el que los jugadores están sentenciados y la única salida es una bala. Reclutado inicialmente por la urgente causa de la Guerra Fría, Rath llevó a cabo trabajos para los que pocos hombres estaban preparados y ahora quiere dejarlo. Después de haber sido el indiscutilble número uno, alguien llamado Miguel Bain comienza a acosar ese liderazgo. Apasionado y ambicioso, este estudiante de Historia disfruta con la emoción de matar y sabe que su momento ha llegado y que sólo Rath le impide realizar su destino. en el camino de ambos se cruzará Electra, una experta en vigilancia y astuta ladrona en el mundo de la información que comparte con Rath el deseo de salirse de un mundo que le ha absorbido durante años y le hace llevar una vida nómada.', trailer_url = 'https://www.youtube.com/watch?v=XCuD8Q_Y10Q' WHERE id_api = 'tt0112401';

UPDATE Contenido SET id_tmdb = 9598, descripcion = 'En la granja Hogget vive toda clase de animales. Cada animal atiene un trabajo que sabe como hacer y cada uno intenta hacerlo bien, porque sabe cual es su sitio. A la granja llega Babe, un cerdito que el granjero ha ganado en un concurso. Hogget siente que hay algo especial en Babe y decide enseñarle el oficio de perro pastor y de esta forma tan peculiar, Babe evita ser la cena de Navidad.', trailer_url = 'https://www.youtube.com/watch?v=XTXupTzPOKU' WHERE id_api = 'tt0112431';

UPDATE Contenido SET id_tmdb = 10474, descripcion = 'Crónica autobiográfica de un grupo de adolescentes, entre los que se encuentra el escritor Jim Carroll, a los que sus travesuras están a punto de llevarlos por oscuros caminos de la desesperación, ya que sus actividades fuera de clase amenazan con destruirlos. Esnifando productos de limpieza, riéndose con fotografías pornográficas, participando en pequeños hurtos, estos cinco amigos apenas mantienen la cabeza a flote al perder el control de sí mismos.', trailer_url = 'https://www.youtube.com/watch?v=MpjAZAn35jY' WHERE id_api = 'tt0112461';

UPDATE Contenido SET id_tmdb = 4616, descripcion = 'Xena (Lucy Lawless) es una bella guerrera cuyos orígenes se remontan a la antigua Grecia. Siempre acompañada de su fiel amiga Gabrielle (Renée O''Connor) y de su poderoso disco mágico, protagoniza numerosas aventuras que la llevan a recorrer distintas regiones en su eterna lucha contra el mal.', trailer_url = 'https://www.youtube.com/watch?v=aYEl6JUfOWQ' WHERE id_api = 'tt0112230';

pasado.', 44, '2001-02-12');

UPDATE Contenido SET id_tmdb = 414, descripcion = 'La ciudad de Gotham está amenazada de nuevo. Esta vez, se trata de una maligna pareja compuesta por Dos Caras y Enigma, que procurarán alterar la paz de sus conciudadanos y del mundo entero para siempre. Por este motivo, Bruce Wayne deberá enfundarse otra vez el traje de Batman y luchar contra ellos; pero esta vez no estará solo, ya que será acompañado por el joven Robin.', trailer_url = 'https://www.youtube.com/watch?v=4gHqW1oPIkA' WHERE id_api = 'tt0112462';

UPDATE Contenido SET id_tmdb = 1855, descripcion = 'Star Trek: Voyager (algunas veces abreviada ST:VOY, ST:VGR, ST:V) es una serie de televisión de ciencia ficción estadounidense, dentro del universo de Star Trek. Esta serie fue creada por Rick Berman, Michael Piller y Jeri Taylor, y es la cuarta serie televisiva de Star Trek, que comenzó en los años 1960 con Star Trek: La Serie Original, creada por Gene Roddenberry. Star Trek Voyager fue producida durante siete temporadas, entre 1995 y 2001, y es la única serie de T.V. de Star Trek en tener una mujer como capitán (Kathryn Janeway).

Esta serie sigue las aventuras de la nave estelar USS Voyager, atrapada en el Cuadrante Delta a 75 mil años luz de la Tierra, mientras perseguía una nave de renegados Maquis. Ambas tripulaciones se unirán para emprender el camino de regreso a casa.', trailer_url = 'https://www.youtube.com/watch?v=b1PX9E2RsgU' WHERE id_api = 'tt0112178';

