UPDATE Contenido SET id_tmdb = 7095, descripcion = 'A causa de un trastorno de envejecimiento inusual que le ha envejecido cuatro veces más rápido que un ser humano normal, un niño entra en el quinto grado por primera vez con el aspecto de un hombre de 40 años de edad.', trailer_url = 'https://www.youtube.com/watch?v=R2tCAybRzpY' WHERE id_api = 'tt0116669';

UPDATE Contenido SET id_tmdb = 10586, descripcion = 'Hacia finales de 1890, la llegada del ingeniero John Patterson (Val Kilmer) a tierras africanas acelera la construcción del ferrocaril. Además, los trabajadores africanos le consideran un héroe, desde que Patterson cazara a un león de un solo disparo, algo que sólo es capaz de hacer el legendario cazador Charles Remington (Michael Douglas). Cuando parece que las obras van viento en popa, se presentan Fantasma y Oscuridad, dos leones devoradores de hombres. Entonces Patterson y Remington deberán unirse para poder acabar con ellos.', trailer_url = 'https://www.youtube.com/watch?v=jGsiY-2CkPU' WHERE id_api = 'tt0116409';

UPDATE Contenido SET id_tmdb = 10545, descripcion = 'Oculto a las miradas de todos los ciudadanos de París, en lo alto del campanario de la catedral de Notre Dame, vive Quasimodo. Su tutor, el juez Frollo, no le permite bajar nunca del Campanario. En compañía de tres simpáticas gárgolas de piedra, Victor, Hugo y Laverne, Quasimodo pasa las horas observando el bullicioso ir y venir de la gente. Hasta que un día, decide bajar a escondidas y conoce a la bella Esmeralda, con la que vivirá su mayor aventura.', trailer_url = 'https://www.youtube.com/watch?v=rJHkp8ZG_xA' WHERE id_api = 'tt0116583';

