UPDATE Contenido SET id_tmdb = 199, descripcion = 'El Capitán del Enterprise encuentra de nuevo a sus adversarios, los Borg, a quienes intenta impedir modificar la historia y conquistar la Tierra en el siglo XXI, por medio de un viaje en el tiempo, que impediría el primer vuelo warp de la raza humana y el consiguiente primer contacto con una raza extraterrestre: los vulcanos.', trailer_url = 'https://www.youtube.com/watch?v=YQ1eiEvefKI' WHERE id_api = 'tt0117731';

UPDATE Contenido SET id_tmdb = 9299, descripcion = 'Ángela, licenciada en ciencias de la información, prepara su tesis sobre la violencia audiovisual. Su director, Figueroa, se compromete a buscarle películas, mientras que un amigo, Chema, la invita a su casa a una sesión de cine gore y pornográfico. Figueroa descubre en la videoteca de la Facultad unas galerías con cientos de videocintas. Poco después muere en extrañas circunstancias. Ángela descubre el cadáver y se da cuenta de que ha sufrido un infarto mientras veía una cinta de vídeo. Ángela se hace con la cinta y hace un terrible descubrimiento: se trata de una snuff movie, una película ilegal en la que se filma al asesinato real de gente inocente. La joven comienza a sospechar que en la Facultad existe una red de tráfico de este tipo de películas. Pero, ¿quién es el responsable de ella?', trailer_url = 'https://www.youtube.com/watch?v=6-RsSaBjpaI' WHERE id_api = 'tt0117883';

UPDATE Contenido SET id_tmdb = 9879, descripcion = 'Cuando Erin Grant pierde su trabajo y la custodia de su hija, se hace bailarina de striptease en un sórdido local de Miami. El propósito de Erin es reunir la gran suma de dinero que necesita para apelar la sentencia que le ha arrebatado a la niña de su lado. El potencial erótico y la sensualidad de Erin atraen la atención de un pervertido miembro del Congreso, que no se detendrá ante nada ni nadie para conseguirla.', trailer_url = 'https://www.youtube.com/watch?v=ujvOdC3-JGw' WHERE id_api = 'tt0117765';

UPDATE Contenido SET id_tmdb = 10218, descripcion = 'Mike (Jon Favreau) es un actor sin suerte que dejó a su amor en el Este para triunfar en Hollywood. Ahora, nueve meses después, Mike todavía pierde el tiempo escuchando a su contestador automático, reviviendo el pasado y esperando la llamada de su novia.', trailer_url = 'https://www.youtube.com/watch?v=SoNOlh_zCf8' WHERE id_api = 'tt0117802';

UPDATE Contenido SET id_tmdb = 664, descripcion = 'Dos grupos de científicos persiguen a las tormentas en busca de conseguir estudiar los comportamientos de los tornados. Ambos compiten por ser los primeros en analizar estos peculiares fenómenos meteorológicos desde dentro de un tornado. Su objetivo es analizar en profundidad la mayor tormenta que caerá sobre Oklahoma en el último medio siglo. En uno de los grupos está Jo Harding, una mujer que, con escasos medios y a punto de divorciarse, tendrá que pedir ayuda a su todavía marido Bill. Este se la da, pero se presenta acompañado de su nueva novia.', trailer_url = 'https://www.youtube.com/watch?v=beHzfQPaTaw' WHERE id_api = 'tt0117998';

UPDATE Contenido SET id_tmdb = 9591, descripcion = 'Guy Patterson trabaja en la tienda de electrodomésticos de su padre, pero su sueño es tocar la batería. Por casualidad se presenta a un concurso cuando un grupo de su barrio se queda sin batería. Guy imprime un nuevo ritmo a las canciones que les hace triunfar y subir a los primeros puestos de ventas con "Los Wonders".', trailer_url = 'https://www.youtube.com/watch?v=fBSrLcksj8c' WHERE id_api = 'tt0117887';

UPDATE Contenido SET id_tmdb = 1645, descripcion = 'En una tranquila localidad sureña de Mississippi dos jóvenes borrachos violan salvajemente a una niña negra de diez años. La mayoría blanca de la ciudad se muestra horrorizada ante tan atroz crimen. Carl Lee, el padre de la niña, armado con un rifle de asalto, decide tomarse la justicia por su mano y mata a los violadores de su hija. Mientras la tensión va creciendo y reaparecen en las calles las cruces ardiendo del Ku Klux Klan, Jake Brigance, un joven abogado blanco, hará todo lo posible por salvar la vida de Carl Lee y proteger la suya.', trailer_url = 'https://www.youtube.com/watch?v=Zy9VWEZOGKU' WHERE id_api = 'tt0117913';

UPDATE Contenido SET id_tmdb = 10478, descripcion = 'Roy McAvoy (Kevin Costner), una antigua gloria del golf que sobrevive en una caravana bebiendo cerveza y dando clases de golf, recibe en poco tiempo dos propuestas: enseñar a jugar a una atractiva mujer, Molly Griswold (Rene Russo), y ganar algo de dinero como caddy de su novio David Simms (Don Johnson), un famoso golfista con el que rivalizó en el pasado.', trailer_url = 'https://www.youtube.com/watch?v=cG-XrSUg1fw' WHERE id_api = 'tt0117918';

UPDATE Contenido SET id_tmdb = 627, descripcion = 'Mark Renton es un joven escocés adicto a la heroína, al igual que el resto de sus amigos Todos ellos viven en un mundo aparte, al margen de la realidad. Dentro del grupo hay un violento y alcohólico psicópata, un drogadicto desesperado, un mujeriego con un conocimiento enciclopédico de Sean Connery y un entusiasta de las caminatas y de Iggy Pop.', trailer_url = 'https://www.youtube.com/watch?v=bKrbNruyFVE' WHERE id_api = 'tt0117951';

UPDATE Contenido SET id_tmdb = 95, descripcion = 'Buffy y su madre se mudan desde Los Ángeles a Sunnydale. En el subsuelo del pueblo habita el Maestro, el más antiguo y poderoso vampiro que existe. El Maestro está atrapado en el punto místico llamado La Boca del Infierno, que él trato de abrir cuando, por causa de un terremoto, quedó atrapado, hace décadas. En Sunnydale, Buffy conoce a Willow y Xander, que se convierten en sus amigos y que, sin querer, la tendrán que ayudar en su lucha contra el Maestro. Además esta Giles, el bibliotecario de la escuela, que es un Vigilante u Observador, que desde siempre se han dedicado a entrenar y guiar a las Cazadoras, pero sin intervenir directamente en la lucha contra los vampiros. Además Buffy conoce un misterioso aliado, de nombre Angel, del que se enamora. Pero es un amor imposible, pues Angel es un vampiro, aunque por una maldición gitana recobró su alma y ahora lucha contra ellos.', trailer_url = 'https://www.youtube.com/watch?v=yGVOs7-ZVKY' WHERE id_api = 'tt0118276';

