UPDATE Contenido SET id_tmdb = 2327, descripcion = 'Ambientada en la ficticia ciudad de Capeside, "Dawson''s Creek" narra el paso de la adolescencia a la madurez de varios jóvenes del pueblo. Dawson, Joey y Pacey eran muy amigos desde la infancia, pero todo cambió cuando empezaron el instituto. Al pueblo llegó una joven, Jen, que al ser vecina de Dawson se les unió al grupo. Así, sus vidas iban a sufrir constantes cambios, propios de la juventud, siempre entre estudios, amoríos, inquietudes sbre sus relaciones cruzadas, sus aficiones, su búsqueda del lugar en el mundo en el mundo de cada uno y su preocupación sobre su futuro.', trailer_url = 'https://www.youtube.com/watch?v=ntxG68WJzuA' WHERE id_api = 'tt0118300';

UPDATE Contenido SET id_tmdb = 9360, descripcion = 'En Anaconda, un equipo de cine documental dirigido por el antropólogo Steven Cale (Eric Stoltz) y la directora Terri Flores (Jennifer Lopez) entra en el misterioso mundo del Amazonas para buscar a los legendarios indios shirishama. El cámara Danny (Ice Cube) se huele el peligro cuando el equipo recoge a un sospechoso pasajero: Paul Sarone (Jon Voight), un "hombre del río" carismático y solitario cuyos supuestos conocimientos sobre los shirishama atraen al equipo. Pero el motivo de Sarone para llevar al equipo a las profundidades del río es su oscura búsqueda de una letal anaconda de 12 metros, y lo sacrificará todo y a todos para encontrar a su rival. La expedición se convierte en una pesadilla en la jungla cuando Sarone lleva al equipo directamente a las fauces de la serpiente asesina y deben recurrir a sus recursos más primarios para sobrevivir.', trailer_url = 'https://www.youtube.com/watch?v=ZkjWyIdIBJo' WHERE id_api = 'tt0118615';

UPDATE Contenido SET id_tmdb = 3322, descripcion = 'En el estado de Nueva York se encuentra la Penitenciaría Oswald, a la que casi todo el mundo conoce como Oz. No es una cárcel cualquiera, sino una prisión de máxima seguridad en la que existe una unidad experimental, la Ciudad Esmeralda, con la que se pretende conseguir la rehabilitación de los presos. Limpia, pulcra, moderna y hasta hermosa, la Ciudad Esmeralda no deja de ser, sin embargo, una prisión y, como todas, peligrosa. A pesar de las modernas instalaciones y del énfasis en la recompensa de la rehabilitación, la prioridad allí sigue siendo la supervivencia... y el miedo es el compañero constante.', trailer_url = 'https://www.youtube.com/watch?v=fxGJyYb9_po' WHERE id_api = 'tt0118421';

UPDATE Contenido SET id_tmdb = 9444, descripcion = 'Cuando la sombra de la revolución se cierne sobre Rusia, Anastasia, la hija más joven de la familia real, apenas consigue escapar con vida. Años despúes conoce al joven Dimitri. Cuando se dirigen a París para reclamar los derechos del legado de Anastasia, se verán envueltos en una cruenta lucha contra el malvado monje Rasputín y su sicario, el murciélago Bartok.', trailer_url = 'https://www.youtube.com/watch?v=NFVpoI_Qjq8' WHERE id_api = 'tt0118617';

UPDATE Contenido SET id_tmdb = 4629, descripcion = 'Stargate SG-1 es una serie televisiva estadounidense derivada del largometraje de ciencia ficción ''Stargate: Puerta a las Estrellas'' (1994). Producida por los estudios Metro Goldwyn Mayer. Esta serie se centra en las vivencias y aventuras de un equipo de militares y científicos miembros de un proyecto ultra-secreto de las Fuerzas Aéreas de los Estados Unidos, que utiliza un ingenio extraterrestre (Stargate) para desplazarse a otros planetas de manera casi instantánea.', trailer_url = 'https://www.youtube.com/watch?v=wSRS7c_UqaM' WHERE id_api = 'tt0118480';

