UPDATE Contenido SET id_tmdb = 8078, descripcion = 'Más de doscientos años después de su muerte, Ellen Ripley vuelve a la vida gracias al empleo de técnicas avanzadas de clonación. Pero, durante el proceso, el ADN de Ripley se ha mezclado con el de la Reina Alien, por lo que Ripley empieza a desarrollar ciertas características de la peligrosa alienígena.', trailer_url = 'https://www.youtube.com/watch?v=LyONzb1dBbk' WHERE id_api = 'tt0118583';

UPDATE Contenido SET id_tmdb = 11831, descripcion = 'Una noche del verano de 1839, cincuenta y tres esclavos negros que viajaban a bordo del navío “La Amistad” se amotinaron y tomaron el control del barco frente a las costas de Cuba. Fracasado su intento de regresar a África, fueron detenidos por tropas americanas y se encontraron en un país extraño y a merced de un sistema judicial que les era ajeno.', trailer_url = 'https://www.youtube.com/watch?v=pMNArpFZXk0' WHERE id_api = 'tt0118607';

UPDATE Contenido SET id_tmdb = 415, descripcion = 'Unos experimentos de criogenia han convertido al Dr. Victor Fries en el malvado Mr. Freeze, un villano que necesita mantener su cuerpo a temperaturas gélidas y que, por ello, intentará congelar a todos los habitantes de la ciudad de Gotham. Por otro lado, la tímida botánica Pamela Isley se transformará en el transcurso de un experimento en la terrible Hiedra Venenosa, que querrá asesinar a todos los seres humanos de la tierra, para que las plantas recuperen su hegemonía sobre el planeta. Por este motivo, Batman y Robin deberán enfrentarse a ellos y detener sus siniestros planes.', trailer_url = 'https://www.youtube.com/watch?v=oWsY1dqih6Y' WHERE id_api = 'tt0118688';

UPDATE Contenido SET id_tmdb = 816, descripcion = 'Fotógrafo por el día y superagente británico por la noche, Austin Powers es el espía más irreverente de los años 60. ¿Podrá detener al megalómano Doctor Villano antes de que se congele a sí mismo para revivir en los 90? Con la ayuda de su atractiva compinche Vanessa Kensington, se supone que sí.', trailer_url = 'https://www.youtube.com/watch?v=9HGy-c4_xFg' WHERE id_api = 'tt0118655';

UPDATE Contenido SET id_tmdb = 9320, descripcion = 'El apuesto John Steed (Ralph Fiennes) y la sofisticada y astuta Emma Peel (Uma Thurman) son dos agentes secretos que despliegan estilo y elegancia en su lucha contra el crimen. Sir August de Wynter (Sean connery), un antiguo miembro del Ministerio del Interior, es un hombre muy rico e inteligente que planea controlar el mundo por medio de una modernísima máquina del tiempo que representa una grave amenaza para la humanidad, que se verá expuesta a imprevisibles y violentas tormentas de hielo o a temperaturas abrasadoras. Pero nuestros héroes no pierden la calma ni siquiera en situaciones tan aparentemente irresolubles.', trailer_url = 'https://www.youtube.com/watch?v=-NfKTtTozWg' WHERE id_api = 'tt0118661';

UPDATE Contenido SET id_tmdb = 1281, descripcion = 'Mr. Bean trabaja como vigilante del prestigioso Royal National Gallery. Sus jefes están hartos de él y quieren despedirlo a causa de sus continuas meteduras de pata, pero no pueden hacerlo porque cuenta con la recomendación del director del museo. Para asegurarse de que su incompetencia quede de manifiesto ingenian un plan para enviarle a los EE.UU. como un experto en arte con el fin de adquirir el cuadro más valioso del mundo.', trailer_url = 'https://www.youtube.com/watch?v=roUoaJnqIhQ' WHERE id_api = 'tt0118689';

UPDATE Contenido SET id_tmdb = 2122, descripcion = 'King of the Hill (El rey de la colina en España y Los reyes de la colina en Hispanoamérica) fue una sitcom costumbrista/satírica animada de televisión que se emite en Estados Unidos. Representa a la "típica" familia tejana, los Hills (Reyes en Hispanoamérica) compuesta por Hank (Hector en Latinoamérica), el personaje central de la comedia. Se trata de un hombre trabajador, fiel, orgulloso de ser tejano y con el sentido común necesario para sobrevivir en el mundo en el que vive. Está casado con Peggy, una ingenua profesora sustituta de español, y tienen un hijo de 12 años, Bobby (Beto en Hispanoamérica), que es la alegría y el orgullo de sus padres. Son en general una familia conservadora, temerosa de Dios y orgullosa de su herencia texana.

Los Hills viven en la ciudad ficticia Arlen, una zona residencial, y a menudo se relacionan con sus vecinos, con quien Hank pasa gran parte del tiempo bebiendo cerveza. Dale Gribble (Diego) es uno de sus mejores amigos. Está casado con Nancy y tienen un hijo, Joseph. Boomhauer (Benavides) es el personaje más curioso de la serie y solo sabe pronunciar su nombre. Bill (Blas), el cuarto del grupo, es el más inteligente de todos y es amigo de Hank desde que iban al instituto.', trailer_url = 'https://www.youtube.com/watch?v=-Jv_cYh2MGE' WHERE id_api = 'tt0118375';

UPDATE Contenido SET id_tmdb = 843, descripcion = 'Hong Kong, 1962. Chow, redactor jefe de un diario local, se muda con su mujer a un edificio habitado principalmente por gentes de Shanghai. Allí conoce a Li-zhen, una joven que acaba de instalarse en el mismo edificio con su esposo. Ella es secretaria de una empresa de exportación y su marido está continuamente de viaje de negocios. Como la mujer de Chow también está casi siempre fuera de casa, Li-zhen y Chow pasan cada vez más tiempo juntos y se hacen muy amigos. Un día, ambos descubrirán que sus respectivos cónyuges los están traicionando.', trailer_url = 'https://www.youtube.com/watch?v=f3dBlMEsF9I' WHERE id_api = 'tt0118694';

UPDATE Contenido SET id_tmdb = 9622, descripcion = 'Un Ninja sin demasiado talento está decidido a salvar a una misteriosa dama en apuros. Chris Farley en Haru, un niño huérfano que llega a Japón y es confundido con el legendario Gran Ninja Blanco. Criado con un grupo de ninjas de élite, debido a su gran tamaño se convierte en la vergüenza de su clan. Pero cuando una bella rubia le pide ayuda para resolver una peligrosa misión en Beverly Hills, Haru tiene una oportunidad de oro, aunque sea arriesgando su vida, para demostrar de lo que es capaz.', trailer_url = 'https://www.youtube.com/watch?v=XSwpv54VgK8' WHERE id_api = 'tt0118708';

UPDATE Contenido SET id_tmdb = 115, descripcion = 'El Nota es un hombre fracasado y en paro que un día es confundido con otra persona con su mismo nombre. Dos matones irrumpen en su apartamento y destrozan su alfombra creyendo que están ante Jeff Lebowski un millonario de Pasadena. El primer error de El Nota es visitar a su opulento tocayo con la esperanza de que le reponga su vieja alfombra.Sin embargo, nuestro reticente héroe y su compinche Water se ven atrapados en un thriller con toques humorísticos muy al estilo de los hermanos Coen donde se mezclan la extorsión, la traición, la decepción, el chantaje, el sexo y las drogas.', trailer_url = 'https://www.youtube.com/watch?v=GiwMMziJdqg' WHERE id_api = 'tt0118715';

