UPDATE Contenido SET id_tmdb = 9464, descripcion = 'Es invierno en Buffalo, Nueva York. Billy Brown acaba de salir de la cárcel después de cinco años tras una apuesta poco acertada que no pudo pagar. Sin embargo, ha engañado a sus padres diciéndoles que trabaja para el Gobierno en un importante proyecto y que está casado con una preciosa joven. Desesperado por impresionar a sus padres, y sin esposa o novia de ninguna clase, Billy rapta impulsivamente a Layla y la obliga a representar el papel ante sus extravagantes progenitores.', trailer_url = 'https://www.youtube.com/watch?v=r7JXNyiPBIQ' WHERE id_api = 'tt0118789';

UPDATE Contenido SET id_tmdb = 2255, descripcion = 'Holden McNell y su mejor amigo, Banky Edwards, disfrutan del éxito de su más reciente creación, el cómic de culto ”Bluntman and Chronic”. Cuando conocen a la también creadora de cómics Alyssa Jones, Holden se siente inmediatamente atraído por ella. Las inclinaciones sentimentales de Alyssa, no obstante, apuntan a otra dirección, por lo que prefiere que Holden y ella sean simplemente amigos. Este se plantea un dilema: sintiendo lo que siente por ella, ¿pueden ser tan sólo amigos? Banky, que la conoce, tiene la respuesta: de ninguna manera.', trailer_url = 'https://www.youtube.com/watch?v=2PwIAmcrr3E' WHERE id_api = 'tt0118842';

