UPDATE Contenido SET id_tmdb = 1701, descripcion = 'Un grupo de presos considerados muy peligrosos son trasladados a un nuevo centro penitenciario. En el avión viaja también Cameron Poe, que acaba de conseguir la libertad condicional y cuyo único deseo es reunirse de nuevo con su esposa y su hija. Sin embargo, durante el trayecto, Poe se ve envuelto en un secuestro aéreo urdido meticulosamente por Cyrus Grissom. Mientras que Cameron intenta evitar que Cyrus y sus secuaces masacren a toda la tripulacion y que el avión se estrelle contra la ciudad de Las Vegas, Vince Larkin, de la policia judicial, tiene que convencer a sus superiores para que no hagan explotar al avion con todos sus pasajeros.', trailer_url = 'https://www.youtube.com/watch?v=H8GfCfpUnQ0' WHERE id_api = 'tt0118880';

UPDATE Contenido SET id_tmdb = 1813, descripcion = 'Kevin Lomax (Keanu Reeves) es un joven y brillante abogado que nunca ha perdido un caso. Vive en Florida y parece feliz con su esposa, Mary Ann (Charlize Theron). Un día, recibe la visita de un abogado de Nueva York, que representa a un poderoso bufete que tiene la intención de contratarlo. Al frente de la prestigiosa empresa se encuentra John Milton (Al Pacino), un hombre mundano, brillante y carismático, que alberga planes muy oscuros con respecto a Lomax.', trailer_url = 'https://www.youtube.com/watch?v=qpl8UrgXZig' WHERE id_api = 'tt0118971';

UPDATE Contenido SET id_tmdb = 686, descripcion = 'Eleanor Arroway perdió la fe en Dios tras la muerte de sus padres en su niñez. Sin embargo, Ellie ha desarrollado una clase distinta de fe en lo desconocido: trabaja con un grupo de científicos escrutando ondas de radio procedentes del espacio exterior en busca de señales de inteligencias extraterrestres. Su trabajo se verá recompensado cuando detecte una señal desconocida que supuestamente porta las instrucciones de fabricación de una máquina para reunirse con los creadores del mensaje.', trailer_url = 'https://www.youtube.com/watch?v=Qt9zT9viZAw' WHERE id_api = 'tt0118884';

UPDATE Contenido SET id_tmdb = 8834, descripcion = 'Jerry Fletcher es un excéntrico taxista de Nueva York. Según él, el mundo se rige por conspiraciones a gran escala de las que todos somos víctimas, y ése es el principal tema de conversación con sus clientes, a quienes pone al corriente de todo tipo de tramas que dominan el mundo. Todos creen que está loco. Veterano del Vietnam, Jerry jura a todo el que se arriesga a escucharlo que la NASA está provocando terremotos y, en el próximo, asesinará al Presidente aprovechando que estará en Turquía. No cesa de acosar a Alice (Julia Roberts), joven ayudante del Fiscal que no sabe como quitárselo de encima. Pero, de pronto, los acontecimientos parecen darle la razón: unos hombres con todo el aspecto de agentes del Gobierno, lo secuestran y torturan. Tras conseguir escapar, Alice comienza a pensar que, tal vez, Jerry no esté tan loco como todos suponen.', trailer_url = 'https://www.youtube.com/watch?v=gOoEZT_C7gA' WHERE id_api = 'tt0118883';

UPDATE Contenido SET id_tmdb = 9619, descripcion = 'Un vulcanólogo prevé una erupción en las cercanías de Dante''s Peak. A pesar de las investigaciones, nadie da crédito a los avisos del experto hasta que ya es demasiado tarde. En medio del pánico general, el volcán entra en erupción y la huida se hace desesperada.', trailer_url = 'https://www.youtube.com/watch?v=Qq06-T0hnLM' WHERE id_api = 'tt0118928';

UPDATE Contenido SET id_tmdb = 2666, descripcion = 'Al despertar solo en un extraño hotel y habiendo perdido la memoria, John Murdoch se ve envuelto en una peligrosa búsqueda de su identidad en una ciudad donde la noche parece nunca terminar, mientras es perseguido por las autoridades como el autor de una serie de sádicos y brutales asesinatos.', trailer_url = 'https://www.youtube.com/watch?v=30mmoegSQCs' WHERE id_api = 'tt0118929';

UPDATE Contenido SET id_tmdb = 2639, descripcion = 'Harry Block, un escritor de mediana edad y con un cierto éxito, se ha servido con frecuencia de sus experiencias sentimentales y familiares para escribir sus obras, razón por la cual la mayor parte de sus amigos, parientes y ex-mujeres lo odian. En tales circunstancias, le resulta muy difícil encontrar a alguien que quiera acompañarlo en un viaje a su vieja universidad para recibir un homenaje.', trailer_url = 'https://www.youtube.com/watch?v=WwXOol3hRUg' WHERE id_api = 'tt0118954';

