UPDATE Contenido SET id_tmdb = 3050, descripcion = 'Un cirujano que posee la facultad de entender el lenguaje de los animales intentará solucionar sus problemas personales y los de los más diversos animales que acuden a su consulta.', trailer_url = 'https://www.youtube.com/watch?v=LWbtxG-jXMY' WHERE id_api = 'tt0118998';

UPDATE Contenido SET id_tmdb = 9366, descripcion = 'Basada en hechos reales, narra la historia del agente del FBI, Joe Pistone, que abandona temporalmente a su familia y se hace pasar por gángster, el joyero Donnie Brasco, y que para ser aceptado por los mafiosos debe probar su lealtad y su disposición para cometer crímenes. Para acceder al corazón de las actividades del clan de los Bonnano, Donnie se gana la confianza de Lefty Ruggiero, un cínico pistolero en decadencia que nunca consiguió entrar en las altas esferas del poder.', trailer_url = 'https://www.youtube.com/watch?v=TDWkpydv51k' WHERE id_api = 'tt0119008';

UPDATE Contenido SET id_tmdb = 9433, descripcion = 'Tras un accidente de avión en las boscosas, frías y hostiles tierras de Alaska, el multimillonario e intelectual Charles Morse, acompañado de su escultural y joven esposa Mickey, y el cotizado fotógrafo de moda Bob Green, se ven envueltos en una desesperada lucha por la supervivencia en medio de las montañas. Pronto descubrirán que el mayor peligro no proviene de la Naturaleza, sino del miedo y de la traición de los hombres.', trailer_url = 'https://www.youtube.com/watch?v=iqkcX_I5MMU' WHERE id_api = 'tt0119051';

UPDATE Contenido SET id_tmdb = 9421, descripcion = 'Para Pierre Brochant y sus amigos el miércoles es el día de los idiotas. La idea es simple: cada uno debe llevar consigo un idiota. El que consiga llevar a la cena el idiota más espectacular de todos es el ganador. Esa noche, Brochant está pletóric: ha encontrado una auténtica joya. Un idiota redomado. François Pignon, un chupatintas del Ministerio de Finanzas, es un hombre apasionado por sus construcciones hechas a base de cerillas. Lo que Brochant ignora es que Pignon es un auténtico gafe, un maestro en el arte de provocar catástrofes.', trailer_url = 'https://www.youtube.com/watch?v=4FANGIUNbiA' WHERE id_api = 'tt0119038';

UPDATE Contenido SET id_tmdb = 9574, descripcion = 'Un simpático y despistado científico que trabaja en una universidad que está a punto de cerrar por falta de dinero hace un sorprendente descubrimiento que puede evitar el cierre del centro: Flubber, una sustancia voladora que produce energía y que se mueve a velocidades supersónicas.', trailer_url = 'https://www.youtube.com/watch?v=oFh76uz-mPU' WHERE id_api = 'tt0119137';

UPDATE Contenido SET id_tmdb = 9411, descripcion = 'El detective John Hobbes está convencido de que tras la ejecución del asesino en serie Edgar Reese se han acabado los problemas. Pero cuando la gente que conoce comienza a cantar la misma canción que Reese cantó durante su ejecución, Hobbes se da cuenta que quizá tras los crímenes se encuentre el ángel caído Azazel, que fue condenado a vagar informe por la Tierra y toma los cuerpos de otras personas.', trailer_url = 'https://www.youtube.com/watch?v=eSCMzZoKkyg' WHERE id_api = 'tt0119099';

UPDATE Contenido SET id_tmdb = 8413, descripcion = 'En el año 2047 una nave de rescate, la "Lewis & Clark", es enviada a investigar la misteriosa reaparición en la órbita de Neptuno de una nave experimental, la "Horizonte Final", desaparecida años antes junto a toda su tripulación. En el año 2040 la nave "Horizonte Final" fue lanzada al espacio para investigar los confines del universo, pero desapareció sin dejar rastro. Sucesos extraños comienzan a ocurrir a bordo mientras la misión de rescate intenta averiguar cuál ha sido el destino de los desaparecidos...', trailer_url = 'https://www.youtube.com/watch?v=Ix9CHnOo94k' WHERE id_api = 'tt0119081';

UPDATE Contenido SET id_tmdb = 754, descripcion = 'Para vengar la muerte de su hijo, el Agente del FBI San Archer se hace una peligrosa operación consistente en cambiar su cara por la del terrorista Castor Troy, que está en estado de coma. Peor cuando Castor despierta y toma la identidad de Sean, comienza para éste su peor pesadilla, teniendo que luchar no sólo por salvar su vida sino la de su mujer e hija.', trailer_url = 'https://www.youtube.com/watch?v=i4Vi61_Laxc' WHERE id_api = 'tt0119094';

UPDATE Contenido SET id_tmdb = 9427, descripcion = 'El cierre de la fábrica de acero de Yorkshire deja sin trabajo a casi toda la población masculina. Gaz, uno de los obreros afectados, perderá el derecho de ver a su hijo si no consigue dinero para pagar la pensión de manutención familiar a su mujer. En medio de la desesperación, se le ocurre una idea, a primera vista disparatada, y se la plantea a los amigos que están en la misma situación: organizar un espectáculo de strip-tease.', trailer_url = 'https://www.youtube.com/watch?v=tHrBCGJmNbo' WHERE id_api = 'tt0119164';

UPDATE Contenido SET id_tmdb = 2649, descripcion = 'Nicholas Van Orton es un perspicaz e influyente hombre de negocios acostumbrado a controlar absolutamente todas las facetas de su existencia. Sin embargo, su perfecta vida sufre un dramático cambio cuando su hermano Conrad le hace un original regalo de cumpleaños que pronto tendrá consecuencias devastadoras. Se trata del acceso a una misteriosa y nueva forma de entretenimiento en la que todo puede perderse, y con una sola regla: no hay reglas.', trailer_url = 'https://www.youtube.com/watch?v=9KXxG-KjfUc' WHERE id_api = 'tt0119174';

UPDATE Contenido SET id_tmdb = 18, descripcion = 'Cada 5.000 años se abre una puerta entre las dimensiones. En una dimensión existe el Universo y la vida. En la otra dimensión existe un elemento que no está hecho ni de tierra, ni de fuego, ni de aire, ni de agua, sino que es una anti-energía, la anti-vida: es el quinto elemento.', trailer_url = 'https://www.youtube.com/watch?v=5Sg2RkdkSvk' WHERE id_api = 'tt0119116';

UPDATE Contenido SET id_tmdb = 10234, descripcion = 'Anna, Georg y su hijo Georgie van a pasar las vacaciones a su bonita casa a orillas de un lago. Sus vecinos Fred y Eva han llegado antes que ellos. Las dos parejas quedan para jugar al golf al día siguiente. Mientras padre e hijo preparan el velero, Anna prepara la cena. De repente, Peter, un joven muy educado que se aloja en casa de los vecinos, se presenta para pedir que le presten algunos huevos porque a Eva no le queda ninguno. De repente, Anna se pregunta cómo ha podido entrar en la casa. El joven le explica que Fred le ha enseñado un agujero que hay en la cerca.', trailer_url = 'https://www.youtube.com/watch?v=hgczUZXVKWA' WHERE id_api = 'tt0119167';

UPDATE Contenido SET id_tmdb = 782, descripcion = 'En un futuro cercano, en La Tierra la perfección genética impera. Los seres inferiores, como Vincent Freeman, cuyo ADN es fruto de una relación natural y no de laboratorio, están condenados al fracaso. Pero Vincent quiere triunfar, y conseguirá esconder su verdadera condición para conseguir su objetivo más ansiado: ser piloto espacial.', trailer_url = 'https://www.youtube.com/watch?v=mV01h6HoglM' WHERE id_api = 'tt0119177';

UPDATE Contenido SET id_tmdb = 4421, descripcion = 'Las presiones de una senadora del Congreso de los EE.UU. convierten a la teniente Jordan O ́Neil en la primera mujer de una unidad de élite del ejército estadounidense. En el fondo, nadie espera que supere un régimen de entrenamiento severísimo que el sesenta por ciento de los reclutas masculinos no consiguen terminar. Sin embargo O ́Neil está dispuesta a demostrar que todo el mundo se equivoca.', trailer_url = 'https://www.youtube.com/watch?v=FDrXl6WOPZA' WHERE id_api = 'tt0119173';

UPDATE Contenido SET id_tmdb = 10603, descripcion = 'En lo más profundo de la jungla africana los gorilas han criado a un bebé, George. Crecerá para ser el más valiente rey de la jungla. George va de un árbol a otro llevándose por delante todo lo que está en su camino. Pero cuando una bella mujer llamada Úrsula, procedente de la civilización, irrumpe en el mundo de George, éste perderá definitivamente el control. Dejando atrás la jungla y todos sus salvajes amigos, incluidos Mono, un gorila que habla, y Shep, un elefante que aspira a ser un perro, George aterrizará en la ciudad de San Francisco.', trailer_url = 'https://www.youtube.com/watch?v=PP9VGoP8xnI' WHERE id_api = 'tt0119190';

UPDATE Contenido SET id_tmdb = 489, descripcion = 'Will es un joven rebelde con una inteligencia asombrosa, especialmente con las matemáticas. El descubrimiento de su talento por parte de los académicos le obligará a elegir entre seguir con su vida de siempre -un trabajo fácil, buenos amigos, muchas cervezas y alguna bronca- o aprovechar sus grandes cualidades intelectuales en alguna universidad. Sólo los consejos de un solitario y bohemio profesor le ayudará a decidirse.', trailer_url = 'https://www.youtube.com/watch?v=ReIJ1lbL-Q8' WHERE id_api = 'tt0119217';

UPDATE Contenido SET id_tmdb = 9410, descripcion = 'Adaptación actualizada de la famosa novela de Dickens, que ya había sido llevada al cine por David Lean. Gracias al dinero de un benefactor desconocido, Finn (Hawke), un joven pobre, llega a Nueva York para dedicarse a la pintura. Desde que era niño Finn vive obsesionado por la bella Estella (Gwyneth Paltrow), que se convierte en la musa que inspira sus cuadros.', trailer_url = 'https://www.youtube.com/watch?v=Sy0hc1_4yiI' WHERE id_api = 'tt0119223';

UPDATE Contenido SET id_tmdb = 9434, descripcion = 'Martin Blank es un asesino a sueldo. Enviado para un trabajo a un suburbio de Detroit, casualmente la reunión de antiguos alumnos de su instituto tendrá lugar allí. Tras su pista están un par de agentes federales, otro matón a sueldo que quiere liquidarlo y Grocer, un compañero de profesión que quiere que se una a su equipo y que no aceptará un no por respuesta. Martin, que últimamente anda decaído, decide acudir a la reunión de su antiguo colegio, y allí se reencuentra con su antiguo amor juvenil... (FILMAFFINITY)', trailer_url = 'https://www.youtube.com/watch?v=RL1oWnFyyZ8' WHERE id_api = 'tt0119229';

UPDATE Contenido SET id_tmdb = 8052, descripcion = 'John es un hombre sin recursos que vive en Reno. Un día, Sydney, un misterioso individuo, lo invita a desayunar y le ofrece la oportunidad de ganar dinero acompañándolo por los casinos. Todo les va muy bien, pero John se enamora de una camarera, que está dispuesta a hacer lo que sea por conseguir dinero.', trailer_url = 'https://www.youtube.com/watch?v=AwLWHNuJ-2M' WHERE id_api = 'tt0119256';

UPDATE Contenido SET id_tmdb = 9714, descripcion = 'Cuatro espías de alta tecnología industrial roban un microchip ultrasecreto y confiadamente lo ocultan en un coche de juguete de control remoto. Por causa de una confusión de equipajes en el aeropuerto, la anciana señora Hess recoge el juguete y se lo regala a su vecino de ocho años Alex. Los espías desearán recuperar el valioso chip a toda costa, pero Alex está preparado para darles una cálida bienvenida.', trailer_url = 'https://www.youtube.com/watch?v=VetFOEcscnM' WHERE id_api = 'tt0119303';

UPDATE Contenido SET id_tmdb = 11970, descripcion = 'Hércules, el hijo de Hera y el dios Zeus, es robado del Olimpo por los secuaces de Hades, que tienen la misión de despojarle de su inmortalidad. Hércules crecerá en un mundo de mortales hasta que le llegue la hora de regresar al Olimpo.', trailer_url = 'https://www.youtube.com/watch?v=mXRDoJqg5Oo' WHERE id_api = 'tt0119282';

UPDATE Contenido SET id_tmdb = 547, descripcion = 'Grace y su amiga Judith salen a dar un paseo a caballo y sufren un terrible accidente al ser atropelladas por un tráiler. Judith y su caballo mueren, mientras que Grace y el suyo (Pilgrim) resultan gravemente heridos. En un intento desesperado por recuperar a Pilgrim que, desde el accidente, se ha convertido en un caballo salvaje, Anie, la madre de Grace, decide ir a Montana a ver a Tom Booker, un vaquero que posee una facultad especial para hablar y curar a los caballos.', trailer_url = 'https://www.youtube.com/watch?v=W_1dKoCQlxY' WHERE id_api = 'tt0119314';

