UPDATE Contenido SET id_tmdb = 3597, descripcion = 'Una noche de verano, cuando volvían de una fiesta, dos jóvenes parejas en estado de embriaguez atropellan a un hombre en una carretera desierta. Confundidos y asustados, deciden tirar el cadáver al mar. Un año después, una de las chicas, Julie, recibe un mensaje en el que alguien dice saber qué pasó el verano anterior. A partir de ese momento, un hombre con gabán de marino y un garfio se dedica a matar a los adolescentes.', trailer_url = 'https://www.youtube.com/watch?v=rEnCEM48QaY' WHERE id_api = 'tt0119345';

UPDATE Contenido SET id_tmdb = 68924, descripcion = 'Noviembre de 1973, New Cannan, Connecticut. La liberación sexual tan de moda ha llegado a los suburbios y ha salpicado a las acomodadas y tradicionales familias americanas, que, de pronto, se aficionan al intercambio de parejas. Esta situación afecta a la familia Hood. Ben Hood pretende acostarse con la vecina de enfrente, pero su esposa empieza a estar harta de las mentiras de su marido. En la noche de Acción de Gracias, una serie de acontecimientos lleva a los Hood a replantearse su vida.', trailer_url = 'https://www.youtube.com/watch?v=GALtpiBSG3I' WHERE id_api = 'tt0119349';

UPDATE Contenido SET id_tmdb = 184, descripcion = 'Jackie Brown es una azafata de vuelo que necesita dinero y hace de correo para Robbie, un mafioso buscado por la policía. Todo parece ir bien hasta que un día es sorprendida en la aduana y acusada de tráfico de drogas y evasión de capital. Sólo podrá evitar su ingreso en prisión, si acepta una propuesta de la policía: ayudarles a llegar hasta Robbie.', trailer_url = 'https://www.youtube.com/watch?v=3rBm88bsRIc' WHERE id_api = 'tt0119396';

UPDATE Contenido SET id_tmdb = 4824, descripcion = 'Un asesino sin escrúpulos, al que sólo se le conoce por el pseudónimo de Chacal, es contratado por un jefe de la mafia rusa para eliminar a un alto mandatario de gobierno de los Estados Unidos como represalia por la muerte de su hermano. El director del FBI, Preston se enfrenta al reto más grande de su carrera: con la ayuda de Valentina Koslova, una oficial de la inteligencia rusa, tendrá que desenmascarar al Chacal, descubrir quién es su objetivo y evitar el fatal desenlace. La única forma de conseguirlo es encontrar a alguien que piense como él: Declan, un antiguo activista del IRA.', trailer_url = 'https://www.youtube.com/watch?v=PbbFOgNtfKo' WHERE id_api = 'tt0119395';

UPDATE Contenido SET id_tmdb = 1624, descripcion = 'Fletcher Reed es un servidor de la justicia que se atiene a un sólo código ético: la verdad es negociable. Sin permitir que los hechos interfieran con un buen argumento, no tiene rival en cuanto a exagerar y distorsionar la verdad. Él es una persona muy convincente y un mentiroso empedernido que se está labrando una prometedora carrera legal, representando a los personajes más inmorales de la sociedad, clientes que otros abogados no representan por pura ética. Pero lo que hace de Fletcher un buen abogado es también lo que le convierte en un padre irresponsable. Un día, su hijo Max lo transforma en una persona honrada y Fletcher descubre que su más preciado tesoro, su boca, de repente se ha convertido en su más grave debilidad.', trailer_url = 'https://www.youtube.com/watch?v=uWp-TiBZZ7A' WHERE id_api = 'tt0119528';

UPDATE Contenido SET id_tmdb = 607, descripcion = 'Un agente de policía se une a una organización secreta que controla y monitoriza la actividad extraterrestre en la Tierra.', trailer_url = 'https://www.youtube.com/watch?v=j9ReysSdQzc' WHERE id_api = 'tt0119654';

UPDATE Contenido SET id_tmdb = 9437, descripcion = 'El Dr. Alex Cross es detective, psicólogo forense y escritor de éxito de novelas criminales. Cuando su sobrina Naomí desaparece, inicia su propia investigación. Siete chicas han desaparecido y se han encontrado dos cadáveres. Al lado del último de ellos ha aparecido una nota firmada ''Casanova''. Cross recibe la ayuda de Kate McTiernan, una joven doctora que ha conseguido escapar del secuestrador y puede ser la única persona capaz de identificarlo. A pesar de la reticencia inicial del detective, juntos emprenden una carrera contrarreloj para encontrar a la sobrina de Cross y descubrir la estremecedora verdad que se oculta tras su desaparición.', trailer_url = 'https://www.youtube.com/watch?v=X9oG87OLjyw' WHERE id_api = 'tt0119468';

UPDATE Contenido SET id_tmdb = 2118, descripcion = 'Los Ángeles, años 50. El departamento de policía vive tiempos agitados en una ciudad revuelta y sacudida continuamente por escándalos que destapa la prensa sensacionalista, y donde todo el mundo busca la fama, drogas, alcohol, sexo o dinero. Dos agentes de caracteres opuestos, en cambio, guian sus acciones por nobles sentimientos: Bud White (Russell Crowe) se mete en todo tipo de líos pero no soporta que maltraten a una mujer. Mientras, Ed Exley (Guy Pearce) es un novato que quiere "limpiar" el cuerpo de policía de la corrupción imparable que invade todo el escalafón policial, aunque le cueste el desprecio de sus compañeros. Cada uno tiene sus tareas y sus problemas, hasta que una noche aparecen muertos varios agentes en un local nocturno.', trailer_url = 'https://www.youtube.com/watch?v=QeIoelqDzsA' WHERE id_api = 'tt0119488';

UPDATE Contenido SET id_tmdb = 9769, descripcion = 'Humbert es un europeo culto, brillante y atractivo que se instala en una ciudad de Nueva Inglaterra como profesor. Una vez allí, se hospeda en casa de Charlotte, una voluptuosa viuda, que ve en Humbert la encarnación de sus fantasías provincianas. Pero Humbert oculta una herida envenenada: el recuerdo de un frustrado amor de adolescencia. Por eso, Lolita, la hija de Charlotte, se le aparece a Humbert como la materialización de sus sueños.', trailer_url = 'https://www.youtube.com/watch?v=vaO_L0n0zhc' WHERE id_api = 'tt0119558';

