UPDATE Contenido SET id_tmdb = 297, descripcion = 'William Parrish es un poderoso y meticuloso magnate cuya vida se ve alterada por la llegada de un enigmático joven llamado Joe Black que se enamora de su hija. Se trata, en realidad, de la personificación de la muerte, con una misión que cumplir en dicho hogar. Versión del filme de 1934 "La muerte de vacaciones".', trailer_url = 'https://www.youtube.com/watch?v=_zIOjl93WrU' WHERE id_api = 'tt0119643';

UPDATE Contenido SET id_tmdb = 9823, descripcion = 'Estamos en el universo del Emperador Shao-Khan, donde las reglas no existen y la vida es una continua batalla. Los esbirros del maquiavélico Khan han sido adiestrados para matar y están dispuestos a cumplir las órdenes de su amo, conseguir el control de la Tierra para iniciar su aniquilación total. Un héroe, llamado Liu Kang, les hará frente.', trailer_url = 'https://www.youtube.com/watch?v=dimVCTUBJEA' WHERE id_api = 'tt0119707';

UPDATE Contenido SET id_tmdb = 8874, descripcion = 'Julianne Potter es una crítica gastronómica que se da cuenta de que está enamorada de su mejor amigo el mismo día que él la llama para anunciarle su inminente matrimonio con una chica de la alta sociedad. Sólo dispone de tres días para urdir un plan que le permita impedir la boda.', trailer_url = 'https://www.youtube.com/watch?v=7gRQFgdtAXs' WHERE id_api = 'tt0119738';

UPDATE Contenido SET id_tmdb = 4961, descripcion = 'En Nueva York, una epidemia provocada por cucarachas provoca una terrible enfermedad que afecta a los niños. Cuando una entomóloga consigue crear un insecto modificado genéticamente, la terrible plaga desaparece. Sin embargo, tres años después...', trailer_url = 'https://www.youtube.com/watch?v=1RVTNsEBRd8' WHERE id_api = 'tt0119675';

UPDATE Contenido SET id_tmdb = 4415, descripcion = 'Francia, a principios del siglo XIX. De forma cruel e injusta, Jean Valjean es condenado y llevado a prisión por robar una barra de pan. Pero el convicto logra escapar de la cárcel y se refugia en la pobre villa de Vigau, de la que con el tiempo llegará a ser alcalde y a la que convertirá en una próspera ciudad. Mientras, para el policía Javert, encontrarle se ha convertido en una obsesión y le perseguirá de forma implacable durante toda su vida.', trailer_url = 'https://www.youtube.com/watch?v=JhhsylxYafE' WHERE id_api = 'tt0119683';

UPDATE Contenido SET id_tmdb = 128, descripcion = 'Tras sufrir el ataque de un monstruoso jabalí maldito, el joven Ashitaka emprende el camino en busca de la cura que detenga la infección. Mientras, los humanos están acabando con los bosques y los dioses convertidos en temibles bestias hacen todo lo posible por protegerlo encabezados por Mononoke, una princesa guerrera. Ashikata deberá escoger bando y decidir si ayudar a los hombres o las deidades intentando detener la maldición de su herida que se extiende por su cuerpo sin cuartel.', trailer_url = 'https://www.youtube.com/watch?v=NixsPRMfqV0' WHERE id_api = 'tt0119698';

UPDATE Contenido SET id_tmdb = 2898, descripcion = 'Melvin Udall, un escritor obsesivo y maniático, es uno de los seres más desagradables y desagradecidos que uno pueda tener como vecino. Pero, un buen día, tiene que hacerse cargo de un perro al que odia a muerte. La presencia en su vida del animal ablandará su corazón.', trailer_url = 'https://www.youtube.com/watch?v=ssMbPxpSoiw' WHERE id_api = 'tt0119822';

UPDATE Contenido SET id_tmdb = 6283, descripcion = 'Dos hermanos heredan de su padre una mansión en la cual vive un ratón que intentará evitar por mil y un medios que los nuevos propietarios se deshagan de la casa.', trailer_url = 'https://www.youtube.com/watch?v=zgjUMHGjO0k' WHERE id_api = 'tt0119715';

UPDATE Contenido SET id_tmdb = 11676, descripcion = 'La vida de Nick Beam no podría resultar peor. Descubre que ha estado viviendo una mentira y se encuentra al borde de un ataque de nervios. Así que cuando T. Paul, un ratero, intenta robarle, resulta ser la gota que colma el vaso. Sin nada que perder, lo secuestra para darle una lección.', trailer_url = 'https://www.youtube.com/watch?v=D81vrzAu9Ck' WHERE id_api = 'tt0119807';

UPDATE Contenido SET id_tmdb = 6623, descripcion = 'Un tren que transporta cabezas nucleares sufre un accidente en los Urales (Unión Soviética) y provoca una explosión nuclear. La Dra. Julia Kelly, una funcionaria del gobierno americano experta en contrabando nuclear, descubre que el accidente forma parte de una trama relacionada con el tráfico de arsenal nuclear, una tapadera para ocultar el robo de material militar por parte de una organización mafiosa con destino a la venta a organizaciones terroristas. El coronel Thomas Devoe y ella reciben el encargo de capturar a los culpables e impedir la venta del material en la frontera iraní', trailer_url = 'https://www.youtube.com/watch?v=QG8O3Cr9kEs' WHERE id_api = 'tt0119874';

UPDATE Contenido SET id_tmdb = 9922, descripcion = 'En el año 2013, los Estados Unidos son un lugar sin autopistas, leyes, ni esperanza en el futuro. Tras una guerra apocalíptica que casi ha destruido la civilización, los supervivientes intentan reagruparse en poblados, llevando una vida tranquila aunque muy primitiva. A este mundo atroz llega un enigmático personaje que viaja sin rumbo fijo y que tiene un don especial para interpretar a Shakespeare; pero posee algo mucho más importante: la capacidad de renovar las esperanzas perdidas.', trailer_url = 'https://www.youtube.com/watch?v=V43K5yFn5GM' WHERE id_api = 'tt0119925';

UPDATE Contenido SET id_tmdb = 978, descripcion = 'Heinrich Harrer fue un famoso alpinista austríaco, que intentó la ascensión al Nanga Parbat; pero, desgraciadamente, su aventura se vio bruscamente interrumpida por el estallido de la Segunda Guerra Mundial (1939-1945). Tanto él como su compañero Peter Ausehnaiter fueron recluidos en un campo de concentración, del que lograron escapar a través de las montañas.', trailer_url = 'https://www.youtube.com/watch?v=m9a_7WFcPlI' WHERE id_api = 'tt0120102';

UPDATE Contenido SET id_tmdb = 11975, descripcion = 'Un joven abogado, recién licenciado e idealista, afronta su primer caso importante con casi todo en contra. Su primer trabajo a las órdenes de un letrado muy poco escrupuloso le lleva a desenmascarar un negocio de seguros, tan sucio como multimillonario,cuya trama puede sacudir los cimientos de una justicia corrupta. El mítico director Francis Ford Coppola denuncia en este film, basado en el libro del considerado rey del best seller John Grisham, el poder que las grandes empresas poseen en los Estados Unidos.', trailer_url = 'https://www.youtube.com/watch?v=Odb3LrbvS_0' WHERE id_api = 'tt0119978';

UPDATE Contenido SET id_tmdb = 9611, descripcion = 'Romy (Mira Sorvino) y Michelle (Lisa Kudrow) son amigas desde la época del instituto. Cuando reciben una invitación para asistir a una fiesta de antiguos alumnos, se sienten avergonzadas porque son muy conscientes de lo grises y anódinas que son sus vidas. Sin embargo, en lugar de quedarse en casa, deciden inventarse una vida apasionante y acudir a la reunión. (FILMAFFINITY)', trailer_url = 'https://www.youtube.com/watch?v=SBsOzaI0NSM' WHERE id_api = 'tt0120032';

UPDATE Contenido SET id_tmdb = 4233, descripcion = 'La universidad de Windsor ofrece una variada opción de materias para sus estudiantes, justo lo que Sidney Prescott necesita. Es primavera, dos años después de los asesinatos en Woodsboro, California, y el año escolar está llegando a su fin. Sid tiene una compañera de habitación, un novio y es la elegida para encabezar el reparto de la obra que se representa en la universidad este curso. Randy, otro de los supervivientes de los asesinatos de Woodsboro, estudia cine en Windsor. También es feliz, como Sid. Pero el pasado nunca queda atrás. De hecho, vuelve y alguien es asesinado mientras ve la película "Stab" (Puñalada) en el cine del campus, el día del estreno nacional. Stab, basada en la novela superventas escrita por la periodista Gale Weathers, describe los asesinatos de Woodsboro. El libro no sólo se vendió como rosquillas, además ayudó a salir de la prisión a Cotton Weary, el hombre acusado por Sidney de la muerte de su madre.', trailer_url = 'https://www.youtube.com/watch?v=owI_iq20w9U' WHERE id_api = 'tt0120082';

UPDATE Contenido SET id_tmdb = 10003, descripcion = 'Simon se educó en un durísimo orfanato y allí tuvo que aprender muchos trucos. Años después, era el más famoso ladrón del mundo, a punto de completar cincuenta millones de dólares en su cuenta. Los mismos empresarios rusos a los que robó un valioso microchip, le contratan para una difícil misión: arrebatar a una bella científica el secreto de la fusión nuclear.', trailer_url = 'https://www.youtube.com/watch?v=qkscr4gDcP8' WHERE id_api = 'tt0120053';

UPDATE Contenido SET id_tmdb = 10215, descripcion = 'Una joven (Paltrow), el mismo día que pierde su trabajo, descubre la infidelidad de su novio. La posibilidad de que una circunstancia nimia - perder el metro- le depare un destino completamente diferente origina esta curiosa historia sobre el azar y la fuerza del destino.', trailer_url = 'https://www.youtube.com/watch?v=Da-Mizk86AE' WHERE id_api = 'tt0120148';

UPDATE Contenido SET id_tmdb = 9425, descripcion = 'Todd O-POS 3465 es un soldado del futuro, entrenado para el combate desde que nació. Él y su equipo son los mejores, hasta que el Coronel Mekum decide crear una raza de guerreros perfectos a través de la manipulación genética. Al ser considerado obsoleto, Todd es abandonado en un planeta utilizado como vertedero, en el que habita un grupo de colonos olvidados. Allí, rodeado de gente sencilla, empieza a descubrir los valores de la amistad y el amor. Pero su destino le perseguirá, y tendrá que volver a enfrentarse al Coronel Mekum y sus soldados para defender a esas personas y su estilo de vida.', trailer_url = 'https://www.youtube.com/watch?v=tuER-MHKbQ4' WHERE id_api = 'tt0120157';

UPDATE Contenido SET id_tmdb = 10336, descripcion = 'Un mercenario llamado Al Simmons es traicionado y asesinado por su diabólico jefe. Cuando baja a los infiernos hace un pacto con el diablo para volver a la tierra bajo la figura de Spawn, y así poder volver a ver a su mujer.', trailer_url = 'https://www.youtube.com/watch?v=Yh8Eg0icV6U' WHERE id_api = 'tt0120177';

UPDATE Contenido SET id_tmdb = 597, descripcion = 'Jack, un joven artista, gana en una partida de cartas un pasaje para viajar a América en el Titanic, el transatlántico más grande y seguro jamás construido. A bordo conoce a Rose, una joven de una buena familia venida a menos que va a contraer un matrimonio de conveniencia con Cal, un millonario engreído a quien sólo interesa el prestigioso apellido de su prometida. Jack y Rose se enamoran, pero el prometido y la madre de ella ponen todo tipo de trabas a su relación. Mientras, el gigantesco y lujoso transatlántico se aproxima hacia un inmenso iceberg.', trailer_url = 'https://www.youtube.com/watch?v=6FKmt1RcLug' WHERE id_api = 'tt0120338';

UPDATE Contenido SET id_tmdb = 1639, descripcion = 'Una joven sueña con disfrutar de unas maravillosas vacaciones por el Caribe, en compañía de su novio, a bordo del transatlántico más lujoso del mundo. Su viaje al paraíso se convierte en un viaje al mismísimo infierno, cuando un lunático genio de la informática se hace con el mando del crucero, poniéndolo rumbo a un desastre seguro.', trailer_url = 'https://www.youtube.com/watch?v=tRAxg_8HAsc' WHERE id_api = 'tt0120179';

UPDATE Contenido SET id_tmdb = 10153, descripcion = 'Un equipo de científicos es enviado a investigar una extraña esfera situada en una nave sumergida en el océano. Pero una terrible tormenta les sorprende.', trailer_url = 'https://www.youtube.com/watch?v=Ng8eBKHJmDc' WHERE id_api = 'tt0120184';

UPDATE Contenido SET id_tmdb = 6415, descripcion = 'En marzo de 1991, el capitán Archie Gates, los sargentos Troy Barlow y Chief Elgin, y el soldado Conrad Vig matan el tiempo en el desierto iraquí mientras aguardan el fin de la guerra y la vuelta a la aburrida y desesperanzada vida civil que les espera en casa. Cuando descubren un mapa que indica la ubicación de una reserva de oro Kuwatí robado por los iraquíes, los cuatro hombres deciden iniciar su propia guerra para llegar hasta el oro. Por el camino irán descubriendo las verdaderas condiciones de vida del pueblo iraquí, convirtiendo su misión en una historia de redención que cambiará todos sus puntos de vista y pondrá a prueba su humanidad.', trailer_url = 'https://www.youtube.com/watch?v=Bdal5c1TfmE' WHERE id_api = 'tt0120188';

UPDATE Contenido SET id_tmdb = 563, descripcion = 'Johnny, Carmen, Dizzy y Ace son cuatro jóvenes amigos que finalizan el instituto y hacen planes para el futuro. En él domina el espacio como el lugar más apetecible para aprender un oficio y trabajar. La Tierra se halla en guerra con una raza de insectos alienígenas gigantes, y los cuatro amigos estudiarán disciplinas para destruirlos. Pero cada uno irá a una unidad diferente, según sus capacidades. Johnny se ve separado de su novia, Carmen, ya que él tiene que ir a infantería. El día que Johnny decide marcharse del ejército, los insectos arrasan su ciudad natal. Es la guerra.', trailer_url = 'https://www.youtube.com/watch?v=zPYuV_jGk7M' WHERE id_api = 'tt0120201';

UPDATE Contenido SET id_tmdb = 37165, descripcion = 'Truman Burbank es un hombre corriente y algo ingenuo que ha vivido toda su vida en uno de esos pueblos donde nunca pasa nada. Sin embargo, de repente, unos extraños sucesos le hacen sospechar que algo anormal está ocurriendo. Todos sus amigos son actores, toda su ciudad es un plató, toda su vida está siendo filmada y emitida como el reality más ambicioso de la historia.', trailer_url = 'https://www.youtube.com/watch?v=c3gI9ms8Fdc' WHERE id_api = 'tt0120382';

UPDATE Contenido SET id_tmdb = 10223, descripcion = 'Hank, su hermano y un amigo encuentran 4.500.000 dólares en una avioneta que ha sufrido un accidente. Enfrentados al dilema de quedarse o no con el dinero, adoptan una solución intermedia: como Hank es el único que tiene un empleo estable y, por tanto, es el menos sospechoso, guardará el dinero durante una temporada. Si, al final, nadie lo reclama, se lo repartirán a partes iguales.', trailer_url = 'https://www.youtube.com/watch?v=VgHoQ1bw050' WHERE id_api = 'tt0120324';

UPDATE Contenido SET id_tmdb = 714, descripcion = 'El gran magnate de los medios de comunicación Elliot Carver tan sólo precisa hacerse con los derechos de emisión en China para completar su emporio global. Para conseguirlo desarrolla un maquiavélico plan para hacer estallar una guerra entre Gran Bretaña y China, mediante el hundimiento de un buque de guerra inglés. James Bond se embarcará en una misión contrareloj para descubrir quién está detrás del peligroso incidente.', trailer_url = 'https://www.youtube.com/watch?v=8iZopKz75i0' WHERE id_api = 'tt0120347';

UPDATE Contenido SET id_tmdb = 863, descripcion = 'Cuando Andy se va de campamento dejando solos a los juguetes, Al McWhiggin, un compulsivo coleccionista de juguetes valiosos, secuestra a Woody. Buzz Lightyear y el resto de los juguetes de Andy deberán actuar con rapidez para rescatarlo, poniéndose al frente de una operación de rescate durante la cual se enfrentarán a múltiples peligros y divertidas situaciones.', trailer_url = 'https://www.youtube.com/watch?v=qHo5y0FFBuE' WHERE id_api = 'tt0120363';

UPDATE Contenido SET id_tmdb = 10155, descripcion = 'Después de un accidente de coche en el desierto de Arizona, Bobby Cooper consigue llegar a un pequeño pueblo habitado por gentes muy extrañas. Allí conoce a una pareja formada por un hombre maduro y una atractiva joven. Pronto, el marido le propondrá matar a su esposa. Poco después, ella le propondrá matar a su marido.', trailer_url = 'https://www.youtube.com/watch?v=uidcyKDkFWU' WHERE id_api = 'tt0120399';

UPDATE Contenido SET id_tmdb = 11419, descripcion = 'Nadie planea unas vaciones mejor que Clark Griswold, un fiel marido y generoso padre de familia. En esta ocasión ha elegido un destino perfecto, Las Vegas, capital del juego donde los Griswold podrán disfrutar de unos días en familia. Pero cuando Clark pone empeño en algo, todo se estropea.', trailer_url = 'https://www.youtube.com/watch?v=U5jQU0gsuaE' WHERE id_api = 'tt0120434';

UPDATE Contenido SET id_tmdb = 10357, descripcion = 'Un desastre de inimaginables proporciones amenaza la ciudad de Los Ángeles: un terremoto y el intenso calor que emana del subsuelo anuncian, sin lugar a dudas, la erupción de un volcán, lo que causaría una situación de caos sin precedentes en la ciudad. Mike Roark, director de la oficina de gestión de emergencias, con la ayuda de una sismóloga, la doctora Amy Barnes, intentará controlar la situación para evitar que el pánico se extienda.', trailer_url = 'https://www.youtube.com/watch?v=M320q7FEjQY' WHERE id_api = 'tt0120461';

UPDATE Contenido SET id_tmdb = 10663, descripcion = 'Un joven de 31 años, Bobby Boucher, es continuamente atormentado por los jugadores del equipo universitario para el que trabaja como aguador, debido a su carácter extraño (causado por la sobreprotección de su madre), y ante la indiferencia del entrenador. Cuando llega al equipo un nuevo míster, éste le convence para que juegue como defensa y dé rienda suelta a toda la rabia contenida que lleva dentro.', trailer_url = 'https://www.youtube.com/watch?v=vVLvkqfTRVQ' WHERE id_api = 'tt0120484';

UPDATE Contenido SET id_tmdb = 73, descripcion = 'Derek (Edward Norton) es un joven californiano que se convierte en el líder de una banda de neonazis tras el asesinato de su padre. Su hermano pequeño, Danny, le admira y sigue sus pasos de odio y violencia. Cuando Derek mata a dos ladrones negros, es condenado a tres años de cárcel, donde cambia su forma de pensar al conocer a otros presos. Al salir, intenta alejar a Danny del racismo y la delincuencia, pero se encuentra con la resistencia de sus antiguos compañeros y las consecuencias de su pasado.', trailer_url = 'https://www.youtube.com/watch?v=oi7bhRmJzec' WHERE id_api = 'tt0120586';

UPDATE Contenido SET id_tmdb = 8916, descripcion = 'Z-4196 es tan sólo una neurótica hormiga obrera macho, una más entre sus millones de hermanas. Después de bailar con la princesa Bala, se enamora de ella, pero se trata de un amor imposible. Convence, sin embargo, a un amigo para que le ceda su puesto en un desfile militar para poder estar cerca de la princesa. La excavación de un nuevo túnel es supervisada por el general Mandible, una hormiga ambiciosa que convence a la reina de la necesidad de enviar al batallón del hormiguero a la guerra contra las termitas. Y en ese batallón se encuentra el asustadizo y cobarde Z...', trailer_url = 'https://www.youtube.com/watch?v=04pwLsCeFlM' WHERE id_api = 'tt0120587';

UPDATE Contenido SET id_tmdb = 564, descripcion = 'El legionario Rick O''Connell y su socio descubren durante una batalla en Egipto las ruinas de Hamunaptra, la ciudad de los muertos. Pasado un tiempo, este descubrimiento le permitirá salvar su vida y volver al lugar con una egiptóloga y su hermano, donde coinciden con un grupo de americanos. Todos ellos, seducidos por la aventura, provocarán la resurrección de la momia de un diabólico sacerdote egipcio que intenta desesperadamente recuperar a su amada.', trailer_url = 'https://www.youtube.com/watch?v=qscGRbdMSaM' WHERE id_api = 'tt0120616';

UPDATE Contenido SET id_tmdb = 95, descripcion = 'Un asteroide del tamaño del estado de Texas apunta directamente hacia la Tierra. En la NASA, tan sólo encuentran una posible solución: enviar a un equipo de astronautas al espacio para que destruya el meteorito antes de que colisione con nuestro planeta. Para ello recurren a Harry S. Stamper, el mayor experto en perforaciones petrolíferas, y a su cualificado equipo de perforadores, para que aterricen en la superficie del asteroide, lo perforen e introduzcan un dispositivo nuclear que al estallar consiga desviar su trayectoria y poder salvar el planeta, evitando así el armagedón.', trailer_url = 'https://www.youtube.com/watch?v=5oZVjG2gT90' WHERE id_api = 'tt0120591';

UPDATE Contenido SET id_tmdb = 492, descripcion = 'La vida de Craig Schwartz está llegando al final de un ciclo. Craig es un marionetista callejero con un gran talento, pero él tiene la impresión de que su vida carece de sentido. Nueva York ha cambiado mucho y la gente no le presta mucha atención. Lleva diez años casado con Lotte, que trabaja en una tienda de animales y está obsesionada con su trabajo. Él consigue encontrar trabajo en la planta 7''5 del edificio Mertin-Flemmer de Manhattan, donde encuentra una pequeña puerta que le permite el acceso a un pasillo secreto que le aspira y que le permite acceder al cerebro de John Malkovich.', trailer_url = 'https://www.youtube.com/watch?v=sfVor5JLBM4' WHERE id_api = 'tt0120601';

UPDATE Contenido SET id_tmdb = 9454, descripcion = 'Durante la Edad Media, la pequeña Danielle, huérfana de madre, ha encontrado en los libros y en el amor de su padre el refugio ideal, pero tras su trágica muerte se convierte siendo una niña en la criada de su nueva madrastra. Por si fuera poco, sus dos hermanastras son realmente crueles con ella. Con el tiempo Danielle crece y se convierte en una damisela cuyo destino se cruzará fortuitamente con el príncipe Henry.', trailer_url = 'https://www.youtube.com/watch?v=szP9U0uLl5U' WHERE id_api = 'tt0120631';

UPDATE Contenido SET id_tmdb = 36647, descripcion = 'En un mundo cohabitado en guerra por hombres y vampiros Blade es un vampiro que, al contrario que el resto, no se alimenta de humanos, y que pretende acabar con la raza de "seres superiores" que mordieron a su madre cuando estaba embarazada.', trailer_url = 'https://www.youtube.com/watch?v=0tbO6WbIE-I' WHERE id_api = 'tt0120611';

UPDATE Contenido SET id_tmdb = 9487, descripcion = 'Un grupo de saltamontes liderados por el malvado Hopper y su estúpido hermano Molt asedian la colonia de hormigas todos los veranos para hacerse con la comida almacenada para pasar el invierno. Flik, una hormiga cansada de seguir las reglas del grupo, decide abandonar la colonia en busca de un grupo de mercenarios que los defiendan. Por equivocación, Flik reclutará a una pandilla de artistas de circo.', trailer_url = 'https://www.youtube.com/watch?v=NH-iK91kKEw' WHERE id_api = 'tt0120623';

