UPDATE Contenido SET id_tmdb = 8656, descripcion = 'El descubrimiento de un meteorito que viene en dirección a la Tierra a gran velocidad pone a toda la Humanidad en estado de alerta. Las naciones de todo el mundo preparan planes para tratar de salvar al mayor numero de personas y de especies animales posibles.', trailer_url = 'https://www.youtube.com/watch?v=9cqDWRIv7Mg' WHERE id_api = 'tt0120647';

UPDATE Contenido SET id_tmdb = 1832, descripcion = 'Dos ángeles caídos, condenados a un exilio perpetuo en Wisconsin, han encontrado la manera de regresar al paraíso, aunque ello suponga la destrucción del universo. Bethany, una trabajadora de una clínica abortista con una seria crisis de fe, será la encargada de impedírselo.', trailer_url = 'https://www.youtube.com/watch?v=m5XqG2tS1XE' WHERE id_api = 'tt0120655';

UPDATE Contenido SET id_tmdb = 1911, descripcion = 'Siglo X. Ahmed Ibn Fahdlan (Banderas) es un noble árabe que es expulsado de sus tierras por cortejar a una mujer. Acompañado de su mentor (Sharif), emprende un viaje al Norte, donde entrará en contacto con un grupo de guerreros vikingos que tienen que enfrentarse con una horda de salvajes que atacan sus poblados y devoran a sus gentes. La profecía de una bruja, anunciando el triunfo de los vikingos gracias a la intervención de un extranjero, anima a Ahmed a ayudarles en la lucha...', trailer_url = 'https://www.youtube.com/watch?v=RikXt796p2o' WHERE id_api = 'tt0120657';

UPDATE Contenido SET id_tmdb = 9798, descripcion = 'La vida de Robert Clayton Dean va a cambiar. Una casualidad pondrá en peligro su feliz hogar y su brillante carrera como abogado cuando hasta sus manos llega una cinta de video con las imágenes del asesinato de un miembro del Congreso de los Estados Unidos, en la que aparecen involucrados agentes del gobierno.', trailer_url = 'https://www.youtube.com/watch?v=a3mrRv-1khI' WHERE id_api = 'tt0120660';

UPDATE Contenido SET id_tmdb = 345, descripcion = 'William Harford es un respetable médico neoyorquino cuya vida parece ir muy bien: está casado con una preciosa mujer, tiene una hija y tiene un trabajo que le gusta. Pero, al día siguiente de asistir a una fiesta, su esposa Alice le habla de unas fantasías eróticas y de cómo estuvo a punto de romper su matrimonio por un desconocido. Abrumado por esta confesión, acaba entrando en un local, donde un antiguo compañero le habla de una congregación secreta dedicada al hedonismo y al placer sin límites. A partir de entonces un mundo dominado por el sexo y el erotismo se abre ante él.', trailer_url = 'https://www.youtube.com/watch?v=VSS47StLOhk' WHERE id_api = 'tt0120663';

UPDATE Contenido SET id_tmdb = 9738, descripcion = 'El ambicioso Von Doom patrocina un viaje de exploración científica  del espacio, en el que participan él mismo y cuatro tripulantes. Todo discurre sin incidentes, hasta que detectan un error de cálculo en la velocidad con la que se les acerca una tormenta. En unos minutos, el umbral de este fenómeno atmosférico está sobre ellos. La estación espacial se ve engullida por turbulentas nubes de radiación cósmica que cambian el genoma de la tripulación. Su ADN se ve irrevocablemente alterado.... y ése va a ser su futuro. De regreso a la Tierra, los efectos de la exposición muestran rápidamente sus primeros síntomas brindando a cada uno de ellos poderes sobrenaturales, convirtiéndose en Los Cuatro Fantásticos: Míster Fantástico, La Chica Invisible, La Antorcha Humana y La Cosa.', trailer_url = 'https://www.youtube.com/watch?v=QIx2jkXYu34' WHERE id_api = 'tt0120667';

UPDATE Contenido SET id_tmdb = 1878, descripcion = 'El periodista deportivo Raoul Duke y su abogado el doctor Gonzo van a Las Vegas para hacer un reportaje sobre una carrera de motos. Su descapotable rojo está equipado con todo tipo de fármacos estimulantes y un arsenal de hierbas dopantes. Esto les permitirá hacer un alucinado viaje, físico y mental, por la decadente América de los setenta.', trailer_url = 'https://www.youtube.com/watch?v=Rx-EsbhLZLQ' WHERE id_api = 'tt0120669';

UPDATE Contenido SET id_tmdb = 497, descripcion = 'En el sur de los Estados Unidos, en plena Depresión, Paul Edgecomb es un vigilante penitenciario a cargo de la Milla Verde, un pasillo que separa las celdas de los reclusos condenados a la silla eléctrica. Esperando su ejecución está John Coffey, un gigantesco negro acusado de asesinar brutalmente a dos hermanas de nueve años. Tras una personalidad ingenua, Coffey esconde un don sobrenatural prodigioso. A medida que transcurre la historia, Paul Edgecomb aprende que los milagros ocurren... incluso en los lugares más insospechados.', trailer_url = 'https://www.youtube.com/watch?v=hBtSF4-cnzk' WHERE id_api = 'tt0120689';

UPDATE Contenido SET id_tmdb = 1360, descripcion = 'Biopic sobre la famosa pintora mexicana Frida Kahlo, centrada en su tormentosa relación con Diego Rivera; desde su larga y complicada relación con su mentor y marido, hasta su controvertido e ilícito affaire con Leon Trotsky, pasando por sus provocativas aventuras amorosas con mujeres, Frida Kahlo vivió una vida atrevida y absoluta como revolucionaria política, artística y sexual.', trailer_url = 'https://www.youtube.com/watch?v=-CTM7FcY1LE' WHERE id_api = 'tt0120679';

UPDATE Contenido SET id_tmdb = 768, descripcion = 'Basada en la historia de Jack el Destripador y el cómic de Alan Moore. Amanece en Whitechapel, el barrio más sórdido de Londres, donde las drogas, la enfermedad y la miseria campan a sus anchas. Cinco chicas dedicadas a la prostitución se encuentran amenazadas por un terrible monstruo que podría robarles su única posesión: la vida. El único que se toma la molestia por protegerlas es el Inspector Fred Abberline que con la ayuda de su amigo el sargento Godley, trata de desentrañar una espeluznante conspiración. A medida que los salvajes asesinatos se suceden, los dos hombres ven obstaculizado su trabajo por unos superiores más interesados en esconder los crímenes bajo la alfombra que en encontrar al verdadero asesino, un sádico loco destinado a pasar a la historia.', trailer_url = 'https://www.youtube.com/watch?v=7gJQRKQjvrU' WHERE id_api = 'tt0120681';

UPDATE Contenido SET id_tmdb = 120, descripcion = 'En la Tierra Media, el Señor Oscuro Saurón creó los Grandes Anillos de Poder, forjados por los herreros Elfos. Tres para los reyes Elfos, siete para los Señores Enanos, y nueve para los Hombres Mortales. Secretamente, Saurón también forjó un anillo maestro, el Anillo Único, que contiene en sí el poder para esclavizar a toda la Tierra Media. Con la ayuda de un grupo de amigos y de valientes aliados, Frodo emprende un peligroso viaje con la misión de destruir el Anillo Único. Pero el Señor Oscuro Sauron, quien creara el Anillo, envía a sus servidores para perseguir al grupo. Si Sauron lograra recuperar el Anillo, sería el final de la Tierra Media.', trailer_url = 'https://www.youtube.com/watch?v=3GJp6p_mgPo' WHERE id_api = 'tt0120737';

UPDATE Contenido SET id_tmdb = 929, descripcion = 'Las pruebas nucleares realizadas por los franceses en el Pacífico originan la aparición en el océano de un reptil mutante, de enormes dimensiones, localizado tras el ataque a un barco pescador japonés. Sin embargo, la criatura no se va a limitar a vivir en el agua: Godzilla se dirige con rumbo fijo a Nueva York, en cuyas calles causará el pánico.', trailer_url = 'https://www.youtube.com/watch?v=VvB2r7v6vpU' WHERE id_api = 'tt0120685';

UPDATE Contenido SET id_tmdb = 9441, descripcion = 'Isabel es una fotógrafa que se enamora de un hombre divorciado con dos hijos. Ganarse el amor de los niños le resultará difícil, ya que la madre, Jackie, no está dispuesta a facilitárselo.', trailer_url = 'https://www.youtube.com/watch?v=QNUu1d7i26g' WHERE id_api = 'tt0120686';

UPDATE Contenido SET id_tmdb = 9490, descripcion = 'Historia de cuatro amigos muy peculiares que cuando están en casa se pasan todo el tiempo flipados. Un día, uno de los colegas es arrestado por provocar la muerte, sin querer, de un caballo de la policía de Nueva York al que ha alimentado con toda clase de comida basura y que resultó ser diabético. Los tres amigos restantes intentarán conseguir el dinero preciso para pagar la fianza y sacar a su colega de la cárcel. El único medio que se les ocurre es vender marihuana robada en el laboratorio farmacéutico en el que trabaja uno de ellos. Es un plan arriesgado, pero son chicos hechos y derechos que harían todo lo posible para ayudar a un amigo que los necesita.', trailer_url = 'https://www.youtube.com/watch?v=0v3Azrz5bJs' WHERE id_api = 'tt0120693';

UPDATE Contenido SET id_tmdb = 11675, descripcion = 'Veinte años después de ser acosada por un psicópata, Laurie Strode vive apartada en una pequeña ciudad con el recuerdo permanente de aquella pesadilla. Tiene un hijo de 17 años, trabaja como jefa de estudios en una escuela privada y la fiesta de Halloween está a punto de celebrarse una vez más.', trailer_url = 'https://www.youtube.com/watch?v=xMpeZ1BXEO4' WHERE id_api = 'tt0120694';

UPDATE Contenido SET id_tmdb = 2157, descripcion = 'El profesor John Robinson se embarca junto a su familia en la nave Júpiter II para realizar una misión. Pero en la nave también navega el Dr. Smith, enviado por fuerzas enemigas para sabotear la misión, que provocará un incidente a partir del cual la nave deambulará sin rumbo fijo por las galaxias.', trailer_url = 'https://www.youtube.com/watch?v=IYoX0i7Nsxs' WHERE id_api = 'tt0120738';

UPDATE Contenido SET id_tmdb = 10376, descripcion = 'Historia de un niño que fue abandonado sobre el piano del Virginia, un enorme trasatlántico. El niño es adoptado por un maquinista y le pone por nombre "Novecento", ya que lo encuentra justo en el cambio de siglo. Novecento se convertirá en un fabuloso pianista y amenizará las noches del Virginia. Pero nunca pisará tierra firme, ni tan sólo tras las súplicas de su amigo Max.', trailer_url = 'https://www.youtube.com/watch?v=jqhbOiF9-8g' WHERE id_api = 'tt0120731';

UPDATE Contenido SET id_tmdb = 100, descripcion = 'Eddie convence a tres amigos para jugarse sus ahorros en una partida de cartas contra Harry el Hacha, un mafioso del barrio. La partida está amañada, y Eddie no sólo pierde todo el dinero sino que contrae una deuda de medio millón de libras, que debe pagar en el plazo de una semana. El mafioso pretende quedarse con el local de su padre para resarcirse de la deuda, pero los cuatro amigos planean saldarla de una forma mucho más arriesgada.', trailer_url = 'https://www.youtube.com/watch?v=HY7mRdQuUSw' WHERE id_api = 'tt0120735';

UPDATE Contenido SET id_tmdb = 10674, descripcion = 'Mulán, una joven china hija única de la familia Fa, en lugar de buscar novio, como sus amigas, trata por todos los medios de alistarse en el ejército imperial para evitar que su anciano padre sea llamado a filas para defender al Emperador del acoso de los Hunos. Cuando el emisario imperial lleva a cabo la orden de reclutar a los varones de todas las familias, Mulán se hará pasar por soldado y se someterá a un duro entrenamiento hasta hacerse merecedora de la estima y de la confianza del resto de su escuadrón.', trailer_url = 'https://www.youtube.com/watch?v=FNZLizaAfno' WHERE id_api = 'tt0120762';

UPDATE Contenido SET id_tmdb = 9313, descripcion = 'Francia se muere de hambre, mientras el Rey Luis XIV mantiene un reinado de terror. Sólo "los tres mosqueteros" podrán salir al rescate. Su misión: liberar a un misterioso prisionero en La Bastilla, en cuya identidad radica el secreto que podrá salvar a la nación...', trailer_url = 'https://www.youtube.com/watch?v=gnNt7l2nA_o' WHERE id_api = 'tt0120744';

UPDATE Contenido SET id_tmdb = 9342, descripcion = 'México, 1821. Un enmascarado y romántico héroe popular, conocido como El Zorro, lucha valientemente contra el dominio colonial español en la Alta California. Sin embargo, la víspera de la liberación de México, el despótico gobernador don Rafael Montero descubre que el Zorro es don Diego de la Vega. Un ataque contra la casa del rebelde, se salda con su captura, la muerte de su mujer, el secuestro de su única hija Elena y la destrucción de sus propiedades. Veinte años después, Montero regresa del exilio con Elena, que ignora la identidad de su padre, y se propone comprar California al Presidente de México, el General Santa Anna.', trailer_url = 'https://www.youtube.com/watch?v=abwtRFZx8Rs' WHERE id_api = 'tt0120746';

UPDATE Contenido SET id_tmdb = 8838, descripcion = 'Art Jeffries, un renegado agente del FBI, se enfrenta a despiadados agentes federales con el fin de proteger a Simon, un niño autista de nueve años que ha descifrado el nuevo código, en principio indescifrable, del gobierno. Él lee Iee Mercury, el código cifrado más avanzado, con la misma facilidad que los otros chicos leen su propio idioma.', trailer_url = 'https://www.youtube.com/watch?v=jkAGQJZFEmg' WHERE id_api = 'tt0120749';

UPDATE Contenido SET id_tmdb = 955, descripcion = 'El agente especial Ethan Hunt tiene una nueva misión: evitar que un despiadado ex-agente y ahora terrorista internacional se haga con un virus mortal que podría soltar sobre Australia causando millones de víctimas. Para evitarlo, contará otra vez con la inestimable ayuda del genio informático Luther Stickell, del experto conductor Billy Baird y de la presencia de la sensual y exótica ladrona internacional Nhye, que en el pasado mantuvo una relación sentimental con el criminal y que ahora se siente atraída por Hunt.', trailer_url = 'https://www.youtube.com/watch?v=hSPtsCQq52k' WHERE id_api = 'tt0120755';

UPDATE Contenido SET id_tmdb = 9820, descripcion = 'Hallie y Annie, dos gemelas que se parecen como dos gotas de agua, fueron separadas poco después de nacer, a causa del divorcio de sus padres. Hallie vive en Napa Valley con su padre, que es viticultor. Por su parte, Annie vive en Londres con su madre, una famosa diseñadora de trajes de novia. Ninguna de las dos conoce la existencia de la otra, pero el destino hace que se encuentren por casualidad en Maine, en un campamento de verano. Antes de volver a casa, las niñas urden un plan para conseguir reunir a sus padres, pero hay un inconveniente con el que no contaban: su padre proyecta casarse con otra mujer.', trailer_url = 'https://www.youtube.com/watch?v=vvO-fV76Vjg' WHERE id_api = 'tt0120783';

UPDATE Contenido SET id_tmdb = 2112, descripcion = 'Porter (Mel Gibson), su mujer (Deborah Kara Unger) y su amigo Val (Gregg Henry) han cometido un atraco con gran facilidad y se han apoderado de ciento cuarenta mil dólares, aunque lo complicado va a ser repartir el botín. Y es que Val lo quiere todo para él, el dinero y a la mujer de Porter, y decide acabar con su compinche. Aparentemente consigue su propósito, pero Porter no ha muerto.Tiempo después, ya recuperado de las heridas que le hizo su ¿buen amigo¿, reaparece endurecido, arruinado e implacable dispuesto a vengarse a cualquier precio y de cualquier manera posible por el robo del dinero y de su mujer. Pero Porter se va a llevar una gran sorpresa cuando descubra que Val era miembro de una poderosa organización a la que ahora deberá enfrentarse.', trailer_url = 'https://www.youtube.com/watch?v=n_aXrHNqQro' WHERE id_api = 'tt0120784';

UPDATE Contenido SET id_tmdb = 9631, descripcion = 'Víctima de una compleja conspiración, Danny Roman, un experto negociador de la policía especializado en secuestros, se ve obligado a tomar rehenes con el fin de probar su inocencia. Además, con la ayuda de un prestigioso colega, intentará descubrir quién está detrás de la trampa que le han tendido.', trailer_url = 'https://www.youtube.com/watch?v=6YfNLyBaP8E' WHERE id_api = 'tt0120768';

UPDATE Contenido SET id_tmdb = 9429, descripcion = 'Los hermanos Butabi, Steve y Doug, quieren triunfar en la movida nocturna de Los Ángeles para llegar a convertirse en personas importantes y así tener su propio club. Pero parece que no lo conseguirán jamás, pues el primer paso es formar parte de la lista de invitados del club más selecto, elitista y ultramoderno, el Roxbury. Aunque un accidente con el actor Richard Grieco va a hacer que las puertas del Roxbury, con todo su lujo y decenas de famosos, se les abran de par en par.', trailer_url = 'https://www.youtube.com/watch?v=Xvl3qJe9L9g' WHERE id_api = 'tt0120770';

UPDATE Contenido SET id_tmdb = 6435, descripcion = 'Dos hermanas huérfanas son criadas por sus tías de una forma atípica: sin reglas ni obligaciones y con muchos libros de hechizos a su alrededor. Ambas saben que tienen poderes extraordinarios pero eso tiene un precio: todos los hombres que se enamoren de ellas están destinados a morir prematuramente.', trailer_url = 'https://www.youtube.com/watch?v=R7uixLkpjPs' WHERE id_api = 'tt0120791';

UPDATE Contenido SET id_tmdb = 1389, descripcion = 'Jack Foley, un elegante atracador de bancos, es detenido tras un atraco fallido e ingresa en prisión. Estando en la cárcel Jack planea un plan de fuga en el que contará con la ayuda de su socio Buddy Bragg. Pero durante la huida se ven obligados a tomar como rehén a Karen Sisco, una agente federal muy propensa a las atracciones fatales por los criminales que debe capturar.', trailer_url = 'https://www.youtube.com/watch?v=WE49DjCAZCc' WHERE id_api = 'tt0120780';

UPDATE Contenido SET id_tmdb = 9837, descripcion = 'En el antiguo Egipto, hace miles de años, el faraón Seti ordena la muerte de todos los recién nacidos judíos. Una madre, desesperada, coloca a su hijo en una cesta y la deposita en el Nilo. Las aguas la conducen río abajo hasta la orilla donde la hallará la reina. El niño era Moisés y fue educado como hermano de Ramsés, el heredero del trono. Sin embargo, cuando, años después, se descubra el origen hebreo de Moisés, los hermanos se distanciarán.', trailer_url = 'https://www.youtube.com/watch?v=zmBDY-fSlIs' WHERE id_api = 'tt0120794';

UPDATE Contenido SET id_tmdb = 857, descripcion = 'Segunda Guerra Mundial, 1944. Tras el desembarco de los Aliados en Normandía, a un grupo de soldados americanos se le encomienda una peligrosa misión: poner a salvo al soldado James Ryan. Los hombres de la patrulla del capitán John Miller deben arriesgar sus vidas para encontrar a este soldado, cuyos tres hermanos han muerto en la guerra. Lo único que se sabe del soldado Ryan es que se lanzó con su escuadrón de paracaidistas detrás de las líneas enemigas.', trailer_url = 'https://www.youtube.com/watch?v=RYExstiQlLc' WHERE id_api = 'tt0120815';

UPDATE Contenido SET id_tmdb = 1576, descripcion = 'En un centro clandestino de investigación genética -con fines militares- de una poderosa multinacional se produce un brote vírico que contamina todo el edificio. Para contener la fuga el ordenador que controla el centro sella toda la instalación y, en un principio se cree que mueren todos los empleados, pero en realidad se han convertido en feroces zombis...', trailer_url = 'https://www.youtube.com/watch?v=B8Htt3yx-fo' WHERE id_api = 'tt0120804';

UPDATE Contenido SET id_tmdb = 1965, descripcion = 'Steven Taylor, un industrial millonario que atraviesa un mal momento financiero, está casado con Emily, una joven adinerada de familia rica que mantiene un pasional romance con David, un artista bohemio. Tras conocer la infidelidad de su esposa, Steve averigua también el turbio pasado del amante, un estafador que seduce a mujeres ricas, y entonces le encarga que asesine a su esposa... Remake del clásico de Hitchcok "Crimen perfecto" (Dial M for Murder, 1954).', trailer_url = 'https://www.youtube.com/watch?v=aaQ8YI-rX2s' WHERE id_api = 'tt0120787';

UPDATE Contenido SET id_tmdb = 2657, descripcion = 'David y su hermana Jennifer son teletransportados mágicamente al mundo ficticio de una serie clásica de la televisión en blanco y negro. Allí conviven con los vecinos de un pueblo apacible y conservador, llegando a ejercer sobre ellos una gran influencia: los sacan de su marasmo y les ayudan a descubrir las principales emociones y pasiones de la vida.', trailer_url = 'https://www.youtube.com/watch?v=Q-4pnXcqyt0' WHERE id_api = 'tt0120789';

UPDATE Contenido SET id_tmdb = 2109, descripcion = 'Dos detectives diferentes son asignados en un mismo caso. Ambos tendrán que adaptarse a las costumbres del otro para poder concluir su trabajo con éxito, pero no va a ser una tarea fácil. El detective inspector Lee es el rey de las artes marciales y pertenece a la Royal Hong Kong Police. Su pupila preferida es la hija de once años del Cónsul chino, de la cual el inspector Lee es su guardaespaldas y su mejor amigo. Esta muchacha es capturada y llevada a los Estados Unidos por un peligroso grupo criminal. Hasta allí tendrá que viajar el inspector y, donde se unirá a la investigación con un departamento del FBI y, concretamente, al detective James Carter, un arrogante e impulsivo agente de policía. La explosiva pareja tendrá que enfrentarse a una banda de criminales muy peligrosa, y contarán con la ayuda de Tania Johnson, una experta en artefactos explosivos.', trailer_url = 'https://www.youtube.com/watch?v=hgrQLDbs1qU' WHERE id_api = 'tt0120812';

UPDATE Contenido SET id_tmdb = 6068, descripcion = 'Robin Monroe, editora de una revista, está de vacaciones con su novio en una isla tropical. Por motivos de trabajo, se ve obligada a contratar el avión de Quinn Harris, pero en el vuelo sufren un accidente y se ven obligados a llevar a cabo un aterrizaje de emergencia.', trailer_url = 'https://www.youtube.com/watch?v=P_cWHAPogMo' WHERE id_api = 'tt0120828';

UPDATE Contenido SET id_tmdb = 8688, descripcion = 'Ricky Santoro es un turbio agente de policía de Atlantic City que, en la noche en que se disputa el combate de boxeo por el campeonato del mundo de los pesos pesados, debe evitar el asesinato del Secretario de Defensa de los Estados Unidos. Tiene la misión de ayudar a su amigo Kevin Dunne, comandante de la Marina. Pronto descubrirá una conspiración en la que está implicada una extraña mujer de traje blanco.', trailer_url = 'https://www.youtube.com/watch?v=LwNgUdp2otk' WHERE id_api = 'tt0120832';

UPDATE Contenido SET id_tmdb = 200, descripcion = 'Jean-Luc Picard, capitán del USS Enterprise, recibe un mensaje de la flota. Al parecer, el comandante Data, que se encontraba estudiando una sociedad primitiva, ha sufrido un cortocircuito y ha revelado la existencia del equipo de investigación a los habitantes del planeta Ba''Ku. Pronto descubrirá que intentaba defender a ésta sociedad inocente de las aspiraciones de los Son''a.', trailer_url = 'https://www.youtube.com/watch?v=gm2M8oUrEyg' WHERE id_api = 'tt0120844';

UPDATE Contenido SET id_tmdb = 586, descripcion = 'Tras ser pillado in fraganti en una situación escandalosa unos días antes de su reelección, el presidente de los Estados Unidos decide inventarse un conflicto que desvíe la atención de la prensa de su affaire. Uno de sus consejeros se pone en contacto con un productor de Hollywood para crear una cortina de humo: una guerra en Albania a la que el presidente pueda poner fin heroicamente ante las cámaras de televisión.', trailer_url = 'https://www.youtube.com/watch?v=steA_PZPkc8' WHERE id_api = 'tt0120885';

UPDATE Contenido SET id_tmdb = 37135, descripcion = 'Cuando Kala, una gorila hembra, encuentra un niño huérfano en la jungla, decide adoptarlo como su propio hijo a pesar de la oposición de Kerchak, el jefe de la manada. Junto a Terk, un gracioso mono, y Tantor, un elefante algo neurótico, Tazán crecerá en la jungla desarrollando los instintos de los animales y aprendiendo a deslizarse entre los árboles a velocidad de vértigo. Pero cuando una expedición se adentra en la jungla y Tarzán conoce a Jane, descubrirá quién es realmente y cuál es el mundo al que pertenece...', trailer_url = 'https://www.youtube.com/watch?v=JYOMf4SS2oA' WHERE id_api = 'tt0120855';

UPDATE Contenido SET id_tmdb = 8741, descripcion = 'Segunda Guerra Mundial, isla de Guadalcanal, 1942. Un grupo de hombres pertenecientes a la compañía de fusileros del ejército ''C de Charlie'' combate contra el ejército japonés por la conquista de una estratégica colina. Allí, los hombres sufren grandes cambios, padecen y, en última instancia, descubren aspectos fundamentales de sí mismos. Los soldados forman parte del envío de nuevas unidades del ejército para proceder al relevo de las unidades de infantería de marina agotadas por el combate.', trailer_url = 'https://www.youtube.com/watch?v=ejm0XvT3rB8' WHERE id_api = 'tt0120863';

UPDATE Contenido SET id_tmdb = 11808, descripcion = 'Mark Sheridan, acusado del asesinato de dos agentes secretos, es arrestado y trasladado en avión a una penitenciaría. Durante el viaje, debido a una revuelta, el avión sufre un accidente que le permite escapar. Comienza entonces una implacable persecución por parte del agente federal Sam Gerard, que hace años vivió una experiencia similar persiguiendo al doctor Kimble, el famoso fugitivo.', trailer_url = 'https://www.youtube.com/watch?v=aV9MiAQ_EDA' WHERE id_api = 'tt0120873';

UPDATE Contenido SET id_tmdb = 9945, descripcion = 'Jack Crow es el jefe de una banda de mercenarios cuyo objetivo es liquidar a todos los vampiros de la Tierra, de la cual se están haciendo dueños, y en especial de Jan Valek, un vampiro que lleva más de 660 años haciendo el mal allí donde está. La película nos situa en un desierto de Nuevo México, donde Crow y los suyos se disponen a acabar con un nido de vampiros donde se sospecha que se puede encontrar Valek. Acaban con todos ellos, pero Valek no está allí', trailer_url = 'https://www.youtube.com/watch?v=hSfGOdPSvPQ' WHERE id_api = 'tt0120877';

UPDATE Contenido SET id_tmdb = 11003, descripcion = 'Robbie trabaja como cantante en banquetes de boda, y está a punto de casarse. Ese día tiene que trabajar como camarera Julia, una joven que también está a punto de casarse y en cuya boda actuará Robbie. Pero a Robbie le dejará plantado su novia en el altar, y Julia dejará a su novio tras descubrir su verdadera personalidad, lo que provocará que ambos se conozcan e inicien una relación.', trailer_url = 'https://www.youtube.com/watch?v=8yjOXMTa6vA' WHERE id_api = 'tt0120888';

UPDATE Contenido SET id_tmdb = 36657, descripcion = 'En un futuro cercano, la humanidad comienza a ver aparecer una nueva raza; los mutantes. Dotados de extraños y variados poderes, están agrupados en dos bandos: los que abogan por la integración y el entendimiento con la humanidad, encabezados por el doctor Charles Xavier, y los que buscan el enfrentamiento con una raza que consideran inferior y que les odia, dirigidos por Magnus, alias Magneto, un peligroso mutante con extraordinarios poderes.', trailer_url = 'https://www.youtube.com/watch?v=s4Wqw8tqgdM' WHERE id_api = 'tt0120903';

UPDATE Contenido SET id_tmdb = 12159, descripcion = 'Tras la muerte de sus dos hijos, el doctor Chris Nielson y su esposa Annie intentan con dificultades continuar con sus vidas. Pero Chris también muere en un accidente de coche, y cuando llega al cielo conocerá a Albert, que le desvela que aquello es más maravilloso de lo que podía esperar. Sin embargo la soledad sume a Annie en una locura que le alejará todavía más de la vida y de su esposo.', trailer_url = 'https://www.youtube.com/watch?v=ahduR16B7K0' WHERE id_api = 'tt0120889';

UPDATE Contenido SET id_tmdb = 617, descripcion = 'Sam Lombardo, un atractivo consejero de un instituto, es acusado de violación por una sexy y seductora alumna, hija de una importante mujer de la alta sociedad de Blue Bay, Florida. Cuando el sargento de la policía Ray Duquette comienza a investigar el caso, descubre que otra alumna también declara haber sido violada por el mismo hombre.', trailer_url = 'https://www.youtube.com/watch?v=RbnGi43LqI4' WHERE id_api = 'tt0120890';

UPDATE Contenido SET id_tmdb = 8487, descripcion = 'Jim West es un viejo héroe de la guerra de Secesión (1861-1865). Artemus Gordon es un imaginativo shériff que lo supera en el arte del disfraz. Cuando los Estados Unidos se ven amenazados por Arliss Loveless, un lunático confederado, el presidente Ulysses Grant encarga a esta excéntrica pareja que se ocupe de él. En un movido viaje desde Washington a Utah, nuestros héroes deberán enfrentarse a los diabólicos artilugios de Loveless.', trailer_url = 'https://www.youtube.com/watch?v=wSRtRrPBTT8' WHERE id_api = 'tt0120891';

UPDATE Contenido SET id_tmdb = 846, descripcion = 'En el norte de Texas, un joven cae en una grieta del suelo mientras juega con sus amigos y éstos contemplan cómo es atacado por un cáncer negro que también infecta a dos bomberos que intentaban rescatarle. Mientras tanto los agentes del FBI Fox Mulder (David Duchovny) y Dana Scully (Gillian Anderson), apartados de los expedientes-x, inspeccionan un edificio federal de Dallas cuando algo inesperado sucede.', trailer_url = 'https://www.youtube.com/watch?v=NmVHEEogDII' WHERE id_api = 'tt0120902';

