UPDATE Contenido SET id_tmdb = 1946, descripcion = 'Refleja una sociedad en la que los diseñadores de juegos son venerados como ídolos y los jugadores pueden entrar orgánicamente en los juegos. Alegra Geller es la autora eXistenZ, el juego más original, que impide a los usuarios distinguir los límites entre la realidad y la fantasía.', trailer_url = 'https://www.youtube.com/watch?v=DZZJrQc-wtw' WHERE id_api = 'tt0120907';

UPDATE Contenido SET id_tmdb = 1893, descripcion = 'La Federación de Comercio ha bloqueado el pequeño planeta de Naboo, gobernado por la joven Reina Amidala, como parte de un plan ideado por Sith Darth Sidious, que manteniéndose en el anonimato dirige a los neimoidianos, que están al mando de la Federación. Amidala es convencida por los Jedis Qui-Gon Jinn y su aprendiz, o padawan, Obi-Wan Kenobi a viajar hasta Coruscant, capital de la República y sede del Consejo Jedi para intentar mediar esta amenaza. Pero esquivando el bloqueo, la nave real resulta dañada, obligando a la tripulación a aterrizar en el desértico y remoto planeta de Tatooine...', trailer_url = 'https://www.youtube.com/watch?v=n1CUHjrc9Sc' WHERE id_api = 'tt0120915';

UPDATE Contenido SET id_tmdb = 11688, descripcion = 'El arrogante y egoísta emperador Cuzco es traicionado y convertido en llama por la ambiciosa Yzma y su guardaespaldas Kronk. El emperador, que una vez lo tuvo todo, se verá abocado a confiar en un llano y simpático campesino llamado Pacha, para encontrarse a sí mismo.', trailer_url = 'https://www.youtube.com/watch?v=ZrCWAQaMNdQ' WHERE id_api = 'tt0120917';

UPDATE Contenido SET id_tmdb = 7450, descripcion = 'Año 3208. La Tierra está siendo atacada por los malvados alienígenas Drej, una raza altamente evolucionada hecha de energía pura. En medio del caos, miles de naves han de despegar de la superficie de la Tierra; el científico Sam Tucker llama a su hijo, Cale, un niño de cinco años, y le manda lejos de la Tierra en una nave espacial para que esté a salvo. Tucker se marcha en la nave espacial Titan -la astronave mejor dotada de la galaxia- porque es el único rayo de esperanza ante el desastre que se presagia. De repente, una ráfaga de la nave nodriza de los Drej envía a la Tierra fuera de control.', trailer_url = 'https://www.youtube.com/watch?v=mK7huyUD3i8' WHERE id_api = 'tt0120913';

UPDATE Contenido SET id_tmdb = 3933, descripcion = 'Ambientada en un pueblecito europeo en el siglo XIX, esta película de animación fotograma a fotograma cuenta la historia de Victor, un joven que es llevado de repente al infierno, donde se casa con una misteriosa Novia Cadáver, mientras que su verdadera novia, Victoria espera en el mundo de los vivos. A pesar de que la tierra de los muertos resulta ser más colorista que su estricta educación victoriana, Victor aprende que no hay nada en este mundo, ni en el siguiente, que pueda separarle de su único y verdadero amor.', trailer_url = 'https://www.youtube.com/watch?v=6wcj_aJ15gI' WHERE id_api = 'tt0121164';

UPDATE Contenido SET id_tmdb = 1894, descripcion = 'Corren tenebrosos tiempos para la República. Ésta continúa envuelta en luchas y sumida en el caos. Un movimiento separatista, formado por centenares de planetas y poderosas alianzas y y lideradas por el misterioso conde Dooku, abre nuevas amenazas para la galaxia, a la que ni siquiera los Jedi parecen poder poner freno. Estas maniobras, planeadas hace mucho por una poderosa fuerza, conducen al estallido de las guerras clones y al principio del fin de la República. Para allanar el camino, los separatistas intentan asesinar a la senadora Padme Amidala. Para evitar futuros atentados, su seguridad es encomendada a dos caballeros Jedi...', trailer_url = 'https://www.youtube.com/watch?v=DywnxIuPtUs' WHERE id_api = 'tt0121765';

UPDATE Contenido SET id_tmdb = 1895, descripcion = 'Último capítulo de la saga de Star Wars, en el que Anakin Skywalker definitivamente se pasa al lado oscuro. En el Episodio III aparecerá el General Grievous, un ser implacable mitad-alien mitad-robot, el líder del ejército separatista Droid. Los Sith son los amos del lado oscuro de la Fuerza y los enemigos de los Jedi. Ellos fueron prácticamente exterminados por los Jedi hace mil años, pero la orden del mal sobrevivió en la clandestinidad.', trailer_url = 'https://www.youtube.com/watch?v=kqkfjBKmWc4' WHERE id_api = 'tt0121766';

UPDATE Contenido SET id_tmdb = 8195, descripcion = 'Cuando un equipo internacional de ex-agentes de inteligencia y ex-guerreros de la guerra fría se reunen en una bodega, su aventura de amor, amistad y traición apenas comienza. Al igual que el honorable e independiente samurai de hace cientos de años, estos ronin modernos se embarcan en su más peligrosa misión secreta: recobrar una misteriosa maleta y entregársela a su desconocido jefe y a la vez conservar sus vidas. Un criminal que se vende al mejor postor lidera un grupo de profesionales del crimen que busca un misterioso maletín, cuyo contenido es desconocido incluso para el espectador.', trailer_url = 'https://www.youtube.com/watch?v=FHrhOuz_QEk' WHERE id_api = 'tt0122690';

UPDATE Contenido SET id_tmdb = 11551, descripcion = 'El Comando Elite está formado por una patrulla de muñecos militares muy arrogantes y agresivos que han cobrado vida y escapado de sus cajas para acabar con los gorgonitas, unos muñecos de aspecto extraño pero absolutamente pacíficos que sólo sueñan con encontrar la isla de Gorgon. El adolescente Alan Abernathy se verá envuelto en esta contienda y tomará posiciones a favor de los Gorgonitas, lo que le llevará a él y a toda su familia a convertirse en el nuevo objetivo del Comando Elite, capaces de crear el caos en toda la ciudad.', trailer_url = 'https://www.youtube.com/watch?v=bS9f0L5J634' WHERE id_api = 'tt0122718';

UPDATE Contenido SET id_tmdb = 944, descripcion = 'La pareja de policías formada por Martin Riggs y Roger Murtaugh vuelve a la carga para enfrentarse a un capo de la mafia asiática que ha extendido sus actividades a Los Angeles. En la investigación les ayudará un joven policía responsable de los quebraderos de cabeza familiares de Murtaugh, ya que ha dejado embarazada a su hija. En casa de Riggs, las cosas también se complican cuando su compañera espera un hijo y amenaza con hacerle pasar por el altar.', trailer_url = 'https://www.youtube.com/watch?v=pi2cGmz9Q2A' WHERE id_api = 'tt0122151';

UPDATE Contenido SET id_tmdb = 9535, descripcion = 'Paul Vitti (De Niro), uno de los capos de la mafia más poderosos de la ciudad sufre de inseguridad, y como se acerca una reunión de todos los capos donde se debe decidir quien será el nuevo jefe de todos los jefes, debe encontrar una solución para que no piensen que es un cobarde. Y como cualquier hijo de vecino, lo más lógico es que vaya a un psiquiatra. Por casualidad uno de sus secuaces choca con Ben Sobol (Crystal), un "comecocos" divorciado que está a punto de casarse, y Vitti empieza a recibir terapia. El único problema es que Sobol debe estar disponible las 24 horas del día, si no quiere acabar en el río, y no precisamente para remojarse. Pero con el paso del tiempo se irán conociendo mejor, llegando incluso a involucrarse demasiado en los negocios no demasiado turbios del jefe mafioso.', trailer_url = 'https://www.youtube.com/watch?v=ZJyv0AYmy4c' WHERE id_api = 'tt0122933';

UPDATE Contenido SET id_tmdb = 431, descripcion = 'Seis personas, desconocidas entre sí, despiertan un día y se encuentran atrapadas en una prisión extraña y surrealista, en un laberinto con un sin fin de habitaciones cúbicas dotadas de trampas mortales. Entre ellos hay un policía, un ladrón profesional, un prodigioso estudiante de matemáticas y un joven autista. Esta mezcla caprichosa de personalidades no está exenta de perversión. Ninguno de ellos sabe porqué o cómo ha llegado hasta allí, porqué está preso, pero enseguida surgirá la obsesión en este grupo por huir, por planificar una salida de tan horrible cárcel. Mientras tanto, varias preguntas sin respuestas: ¿quién ha podido crear este diabólico laberinto y por qué? ¿quién les ha encerrado en él y con qué objetivo?.', trailer_url = 'https://www.youtube.com/watch?v=HYoTGYT0-I4' WHERE id_api = 'tt0123755';

UPDATE Contenido SET id_tmdb = 12971, descripcion = 'La historia de Dragon Ball Z se divide en cuatro ramas centrales, repartidas en un total de 291 episodios. La primera abarca desde que Son Gohan, hijo de Goku, es raptado por el saiyan Raditz. La etapa de Freezer lleva a Goku, Krillin, Vegeta y Bulma al planeta Namek. Después viene la Saga de los Androides, que da comienzo cuando tres androides (A16, A17, A18) comienzan a aterrorizar la tierra, hasta la llegada de Cell. La última etapa de Z la cubre la Saga de Bu. Comienza cuando Babidi, un brujo bastante ambicioso, comienza un plan para resucitar al poderoso Majin Bu, un ente capaz de poner la tierra a su favor en un par de movimientos.', trailer_url = 'https://www.youtube.com/watch?v=cie7scVUdQE' WHERE id_api = 'tt0121220';

UPDATE Contenido SET id_tmdb = 6522, descripcion = 'Nueva York, 1932. Ray Gibson es un delincuente de poca monta que acaba de colarse en el club Spanky y detecta enseguida a su primera víctima de la noche. El ingenuo Claude Banks, aspirante a contable, ha salido con su novia esa noche y poco sospecha que se ha convertido en el blanco de Ray. La cartera de Claude pasa a manos de Ray, quien cree haber conseguido así el dinero para pagar la deuda de juego que tiene con Spanky. Pero Ray se lleva un chasco porque Claude, que también tiene el vicio del juego, está tan arruinado como él. (FILMAFFINITY)', trailer_url = 'https://www.youtube.com/watch?v=crXNoJ-tMpQ' WHERE id_api = 'tt0123964';

UPDATE Contenido SET id_tmdb = 10833, descripcion = 'Max y su hija Page son dos timadoras profesionales que utilizan sus dotes de seducción para estafar a millonarios. Pero, en una ocasión, mientras Max intenta embaucar a un excéntrico magnate del tabaco, Page conoce a un simpático chico y se enamora de él. Entonces empieza a cuestionar su vida pasada y a plantearse problemas de conciencia. La situación se complica todavía más porque un ex-marido furioso sigue los pasos de las dos mujeres.', trailer_url = 'https://www.youtube.com/watch?v=xE4N6-pjl7I' WHERE id_api = 'tt0125022';

UPDATE Contenido SET id_tmdb = 10029, descripcion = 'Fisher está apunto de casarse con la mujer de sus sueños. Sus amigos deciden montarle en Las Vegas una despedida de soltero que no pueda olvidar jamás. Y, efectivamente, ninguno de ellos la olvidará jamás...', trailer_url = 'https://www.youtube.com/watch?v=WUIO3LKZcdI' WHERE id_api = 'tt0124198';

UPDATE Contenido SET id_tmdb = 11622, descripcion = 'En 1962, Calvin Webber (Christopher Walken), un brillante aunque algo paranoico científico, vivía con su esposa Helen (Sissy Spacek) en Los Ángeles. En plena crisis de los misiles de Cuba, un avión sufre un accidente cerca de la casa de los Webber, que, convencidos de que ha estallado una guerra nuclear, se guarecen en un refugio construido por Calvin. 35 años después su hijo Adam (Brendan Fraser), nacido en esa especie de cápsula temporal, sale a la superficie para comprobar si la Tierra sigue siendo apta para la vida humana.', trailer_url = 'https://www.youtube.com/watch?v=hDNR4CxYtls' WHERE id_api = 'tt0124298';

UPDATE Contenido SET id_tmdb = 509, descripcion = 'La historia se centra en William, propietario de una tienda de libros en el popular barrio londinense de Notting Hill, y Anna Scott, la estrella más rutilante del firmamento cinematográfico. Desde el momento en que la actriz entra en la tienda, William se embarca en un cortejo complicado, para el cual cuenta con la inestimable ayuda de sus inseparables amigos, entre los que destaca su compañero de piso el singular Spike, que observa con asombro e incredulidad cómo el bueno de William tiene un romance con una mujer inalcanzable para cualquier otro ser humano.', trailer_url = 'https://www.youtube.com/watch?v=sn-m50RUf_Q' WHERE id_api = 'tt0125439';

UPDATE Contenido SET id_tmdb = 1715, descripcion = 'Un joven abandona al doctor que lo crió como a su propio hijo, para saber qué hay más allá de los confines del orfanato.', trailer_url = 'https://www.youtube.com/watch?v=pGdZBESUSfk' WHERE id_api = 'tt0124315';

UPDATE Contenido SET id_tmdb = 9469, descripcion = 'Jake es un preso al que el gobernador del estado le ofrece un trato: reducir su estancia en la cárcel si logra convencer a su hijo Jesús, el mejor jugador de baloncesto de todos los institutos del país, para que fiche por el equipo local. Huérfano de madre y con su padre en prisión, Jesús es un joven que se ha hecho a sí mismo y que ha criado a su hermana pequeña sin ninguna ayuda. Ahora debe resolver en una semana un difícil dilema: aceptar una beca deportiva universitaria o entrar en la NBA. La repentina reaparición de Jake plantea el problema de la reconciliación entre padre e hijo e influye en la resolución del dilema.', trailer_url = 'https://www.youtube.com/watch?v=qLCh8teN0qo' WHERE id_api = 'tt0124718';

UPDATE Contenido SET id_tmdb = 808, descripcion = 'Hace mucho, mucho tiempo, en una lejanísima ciénaga vivía un intratable ogro llamado Shrek. Pero de repente, un día, su absoluta soledad se ve interrumpida por una invasión de sorprendentes personajes de cuento. Hay ratoncitos ciegos en su comida, un enorme y malísimo lobo en su cama, tres cerditos sin hogar y otros muchos seres increíbles que han sido deportados de su reino por el malvado Lord Farquaad. Para conseguir salvar su terreno, y de paso a sí mismo, Shrek hace un pacto con Farquaad y emprende viaje para conseguir que la preciosa princesa Fiona sea la novia del Lord. En tan importante misión le acompañan un burro chistoso, dispuesto a hacer cualquier cosa por Shrek. Todo, menos estarse calladito. Rescatar a la princesa de una dragona enamoradiza que suelta fuego al respirar va a resultar una tontería comparado con lo que ocurre cuando el oscuro secreto que la joven guardaba es revelado.', trailer_url = 'https://www.youtube.com/watch?v=B88JfTyJ1Fw' WHERE id_api = 'tt0126029';

UPDATE Contenido SET id_tmdb = 4518, descripcion = 'Inglaterra 1554. Tras la muerte de la reina María Tudor, que ha dejado al país sumido en un estado de inestabilidad financiera y crisis religiosa, sube al trono Isabel I (Cate Blanchett). Popularmente se la conoce como "La Reina Virgen", aunque por su participación en el reparto del botín obtenido tras los ataques de Drake a las costas españolas, tanto peninsulares como coloniales, es también conocida como "La Reina Pirata".', trailer_url = 'https://www.youtube.com/watch?v=EnkaUTvEy1E' WHERE id_api = 'tt0127536';

UPDATE Contenido SET id_tmdb = 1902, descripcion = 'César es un atractivo y apuesto joven que ha heredado una gran fortuna de sus padres. Vive en una espléndida casa de su propiedad en la que organiza lujosas fiestas. Cuando una noche su amigo Pelayo le presenta a la hermosa Sofía, Nuria, que fue amante de César, se muere de celos y, al día siguiente, yendo en coche con César, intenta suicidarse. Cuando éste se despierta en el hospital, su rostro se encuentra horriblemente desfigurado.', trailer_url = 'https://www.youtube.com/watch?v=1zX8gwWvke8' WHERE id_api = 'tt0125659';

UPDATE Contenido SET id_tmdb = 1850, descripcion = 'Cuando Andy Kaufman era un niño ya le gustaba organizar espectáculos de variedades, aunque no tuviera público. De adulto empieza a destacar como humorista y es descubierto por el cazatalentos George Shapiro, que le consigue un papel en "Taxi", una famosa serie de televisión, en la que, gracias a sus dotes cómicas, alcanza una gran popularidad. A pesar de ello, se plantea nuevos retos: con su colega Bob Zmuda crea el personaje de Tony Clifton, su "alter ego"; además, organiza espectáculos de lucha libre entre mujeres que le ocasionan numerosos problemas.', trailer_url = 'https://www.youtube.com/watch?v=cvaHj0np8GM' WHERE id_api = 'tt0125664';

UPDATE Contenido SET id_tmdb = 11545, descripcion = 'Max Fisher (Jason Schwartzman), un estudiante de Rushmore, una de las escuelas más prestigiosas del país, es el editor del periódico escolar y el capitán y presidente de numerosos clubs y sociedades; pero también es un pésimo estudiante; por eso, no deja de pensar que algún día lo expulsarán del colegio. Max se enamora de la elegante profesora Miss Cross (Olivia Williams), pero su cortejo fracasa cuando se entera de que el señor Blume (Bill Murray), el padre de dos compañeros de clase, también intenta conquistar el amor de la profesora.', trailer_url = 'https://www.youtube.com/watch?v=846UzdeHI1g' WHERE id_api = 'tt0128445';

UPDATE Contenido SET id_tmdb = 9451, descripcion = 'Por motivos que ni él mismo entiende, el profesor de un instituto estadounidense decide impedir que su mejor estudiante consiga el anhelado cargo de delegada de los alumnos.  Una comedia aparentemente simple, pero que pronto se revela como una compleja y mordaz moraleja sobre la ambición, la corrupción y el deseo en sus niveles más descarnados y mezquinos. Cada escena es una mezcla de humor y amargura que dejan al espectador a medio camino entre la sorpresa y la empatía. No es extraño, pues, que recibiera una candidatura al Óscar al mejor guion original del 2000.', trailer_url = 'https://www.youtube.com/watch?v=XaQvqhtCYW0' WHERE id_api = 'tt0126886';

UPDATE Contenido SET id_tmdb = 8697, descripcion = 'Jackie es reclutado por la CIA para formar parte de un comando de élite, que recibe la orden de asaltar un laboratorio secreto de armamento tecnológico en la jungla africana. Traicionados por su jefe, todo el equipo muere excepto Jackie, que es abandonado inconsciente en la jungla. Una tribu le recoge y le cura, aunque sufre de amnesia que le impide saber quién es y cómo llegó hasta allí. Su lucha por descubrir su verdadera identidad le hará sufrir la persecución de sus antiguos enemigos, y no podrá confiar en nadie nunca más. (FILMAFFINITY)', trailer_url = 'https://www.youtube.com/watch?v=iLo5g4HHyBE' WHERE id_api = 'tt0127357';

UPDATE Contenido SET id_tmdb = 544, descripcion = 'Ted Strohehmann ha vivido angustiado durante 14 años de su vida, la razón de su desgracia no es otra que la famosa Mary Jensen, la chica que todos desean y con la que por fin, consigue tener una cita en la fiesta de fin de curso.', trailer_url = 'https://www.youtube.com/watch?v=3CHwXQjDM4Q' WHERE id_api = 'tt0129387';

UPDATE Contenido SET id_tmdb = 15037, descripcion = 'El joven aspirante a escritor Preston (Ethan Embry) esta enamorado de Amanda (Jennifer Love Hewitt) desde la primera vez que la vió, y su amor se ha hecho más intenso durante el curso. Preston acude a la gran fiesta con la idea de declararse a Amanda, ahora que ha sido abandonada por su novio.', trailer_url = 'https://www.youtube.com/watch?v=qukvN6ieeMY' WHERE id_api = 'tt0127723';

UPDATE Contenido SET id_tmdb = 10220, descripcion = 'Mike McDermott, además de estar estudiando derecho, es un rounder, es decir, un jugador de cartas de los que nunca pierden. Cuando su mejor amigo, Les "Gusano" Murphy, sale de la cárcel y descubre que sigue debiendo una importante cantidad de dinero a un peligroso delincuente, decide volver a jugar, a pesar de las advertencias de su novia y de su mentor en la Universidad. La partida de póker en la que se propone participar para ayudar a su amigo se disputará con algunos de los jugadores más siniestros de la ciudad, entre los que se encuentra el pérfido Teddy KGB.', trailer_url = 'https://www.youtube.com/watch?v=cjUgHE3hxyg' WHERE id_api = 'tt0128442';

UPDATE Contenido SET id_tmdb = 9489, descripcion = 'Kathleen Kelly es la propietaria de una librería infantil, un verdadero tesoro cultural de uno de los barrios más esclusivos de Nueva York, y pasa largas noches aburridas junto a su novio Frank , un escritor frustrado que escribe columnas en el periódico. Lo único que apasiona a Kathleen es intercambiar mensajes de correo electrónico con un hombre del que sólo conoce su seudónimo.', trailer_url = 'https://www.youtube.com/watch?v=AKlhYZ-HqKs' WHERE id_api = 'tt0128853';

UPDATE Contenido SET id_tmdb = 10386, descripcion = 'En 1957, en la pequeña localidad de Rockwell, alguien ha visto cómo un enorme hombre metálico caía al mar. Un imaginativo niño descubre que se trata de un robot gigante, cuyo apetito de metal es insaciable. Entre ambos nace una fuerte amistad, pero el gobierno envía a un agente para investigar los hechos. El niño esconde a su nuevo compañero en la chatarrería de un amigo. Pero los habitantes del pueblo comienzan a sentirse aterrados porque creen que es una nueva amenaza en plena Guerra Fría.', trailer_url = 'https://www.youtube.com/watch?v=2izFEWmzPdk' WHERE id_api = 'tt0129167';

UPDATE Contenido SET id_tmdb = 10312, descripcion = 'Basada en una historia real, la película es la biografía del médico Patch Adams, que revolucionó a la comunidad médica oficial aplicando singulares terapias consistentes en hacer reír y proporcionar afecto a los pacientes enfermos de cáncer.', trailer_url = 'https://www.youtube.com/watch?v=lZqGA1ldvYE' WHERE id_api = 'tt0129290';

UPDATE Contenido SET id_tmdb = 10212, descripcion = 'En 1847, el capitán John Boyd, que ha cometido una falta grave durante la guerra entre Méjico y EE.UU., es enviado a un remoto fuerte de Sierra Nevada. Un día, Colqhoun, un extraño personaje, sostiene que él y otros colonos, después de ser sorprendidos por una avalancha, quedaron encerrados durante largo tiempo en una cueva, logrando sobrevivir gracias a la práctica del canibalismo. Pero la verdadera historia aún está por descubrir.', trailer_url = 'https://www.youtube.com/watch?v=l7BDiNktrLU' WHERE id_api = 'tt0129332';

UPDATE Contenido SET id_tmdb = 3600, descripcion = 'Un año después de ser acosada por Ben Willis, la víctima mortal de un accidente en el que ella estuvo implicada junto a sus amigos, Julie ha dejado su ciudad natal para ir a la Universidad. Una extraña llamada le anuncia que es la ganadora de un fin de semana en una isla paradisíaca, lugar en el que la pesadilla vuelve a repetirse.', trailer_url = 'https://www.youtube.com/watch?v=xx_j5SL93Xs' WHERE id_api = 'tt0130018';

UPDATE Contenido SET id_tmdb = 10567, descripcion = 'Prehistoria, hace 65 millones de años, al final del periodo cretáceo. Un iguanodonte de tres toneladas llamado Aladar se cría separado de los de su especie y crece en una isla paradisiaca al amparo de un clan de lémures. Cuando una devastadora lluvia de meteoritos provoca el caos en su pacífico mundo, Aladar pone rumbo a tierra firme y se une a un grupo de dinosaurios que buscan desesperadamente un lugar donde anidar en paz. Pero el agua y la comida empiezan a escasear, y los carnotaurios, sedientos de sangre fresca, representan un peligro constante. Es entonces cuando Aladar se ve obligado a desafiar el "orden establecido" y demuestra que saber adaptarse a cualquier situación es la mejor manera de sobrevivir.', trailer_url = 'https://www.youtube.com/watch?v=ewi_p9sNQoc' WHERE id_api = 'tt0130623';

UPDATE Contenido SET id_tmdb = 104, descripcion = 'Manni es un ladrón de poca monta que acepta participar en un gran golpe: vender unos diamantes robados por cien mil marcos que debe entregar a mediodía a un traficante. Pero pierde la bolsa que contiene el dinero en el metro de Berlín. Como último recurso, llama a su novia, Lola (de veinte años, cabellos rojos, frágil pero decidida), y le explica la situación. Son las once y cuarenta minutos; si en veinte minutos Manni no ha recuperado el dinero, es hombre muerto. Desesperada, la joven se precipita hacia la capital. Tiene veinte minutos para encontrar cien mil marcos, reunirse con Manni y salvar al hombre de su vida.', trailer_url = 'https://www.youtube.com/watch?v=ZCYnsUdO6H0' WHERE id_api = 'tt0130827';

UPDATE Contenido SET id_tmdb = 11353, descripcion = 'Bobby Bowfinger, un director fracasado de Hollywood, se dispone a producir el guión que ha escrito un amigo. Está tan convencido de su calidad que alberga la esperanza de recuperar así la fama perdida. Sin embargo, venderlo no resultará nada fácil. Por fin, un famoso productor lo acepta pero con una condición: Kit Ramsey, la estrella de moda, tiene que participar en la película.', trailer_url = 'https://www.youtube.com/watch?v=vQArw5Lu418' WHERE id_api = 'tt0131325';

UPDATE Contenido SET id_tmdb = 2190, descripcion = 'South Park es una serie de televisión estadounidense de animación, creada por Trey Parker y Matt Stone para el canal Comedy Central. Está dirigida al público adulto y se caracteriza por satirizar con humor negro la sociedad, actualidad y cultura estadounidense a través de las historias y situaciones surrealistas que les suceden a sus protagonistas, cuatro niños (Stan, Kyle, Cartman y Kenny) residentes en un pueblo ficticio de Colorado que se llama South Park.', trailer_url = 'https://www.youtube.com/watch?v=oUIK01ek-Ko' WHERE id_api = 'tt0121955';

