UPDATE Contenido SET id_tmdb = 603, descripcion = 'Thomas Anderson lleva una doble vida: por el día es programador en una importante empresa de software, y por la noche un hacker informático llamado Neo. Su vida no volverá a ser igual cuando unos misteriosos personajes le inviten a descubrir la respuesta a la pregunta que no le deja dormir: ¿qué es Matrix?', trailer_url = 'https://www.youtube.com/watch?v=Zd8Jw1Z_j4w' WHERE id_api = 'tt0133093';

UPDATE Contenido SET id_tmdb = 11374, descripcion = 'Debido a los bajos índices de audiencia del canal de televisión True TV, a la directora de programación se le ocurre la idea de seguir con una cámara a un ciudadano cualquiera las veinticuatro horas del día. El elegido es un joven sin futuro llamado Ed que vive con su familia en un barrio pobre de San Francisco. El éxito del programa es inmediato pero, con el paso del tiempo, el precio que Ed deberá pagar por la fama será demasiado alto.', trailer_url = 'https://www.youtube.com/watch?v=V5ZJtWn8zBY' WHERE id_api = 'tt0131369';

UPDATE Contenido SET id_tmdb = 10477, descripcion = 'Trepidante drama de acción ambientado en el peligroso y emocionante mundo de las carreras de coches. El genial pero impetuoso principiante Jimmy Bly pierde posiciones en el ránking al no poder soportar la presión a la que lo somete su ambicioso hermano y promotor. Pero hay otro asunto que le impide concentrarse: quiere conquistar a Sophia, la novia de su máximo rival. Así las cosas, el dueño de la escudería pide ayuda a Joe Tanto, una estrella del automovilismo cuya espléndida carrera se vio truncada por un trágico accidente. Pero para conseguir que Bly llegue a la cima, Joe tendrá que resolver antes no pocos problemas personales. (FILMAFFINITY)', trailer_url = 'https://www.youtube.com/watch?v=Hx5mVrXOddw' WHERE id_api = 'tt0132245';

UPDATE Contenido SET id_tmdb = 14013, descripcion = 'Comedia protagonizada por los creadores de "South Park". Un buen día, Coop (Trey Parker) y Remer (Matt Stone), dos amigos sin trabajo, deciden crear un nuevo deporte "puro e inocente": el Baseketball, una mezcla de béisbol y baloncesto en el que puede jugar cualquiera, y en el que la mejor defensa es hacer que el lanzador pierda "las pelotas". El genial invento se convierte rápidamente en el fenomeno nacional y, de la noche a la mañana, los grandes clubes montan incluso una gran liga profesional.', trailer_url = 'https://www.youtube.com/watch?v=UtxFvx3GE7c' WHERE id_api = 'tt0131857';

UPDATE Contenido SET id_tmdb = 9824, descripcion = 'La bulliciosa metrópoli de Champion City es una próspera comunidad de ciudadanos decentes y trabajadores, donde el hombre común puede aún albergar la fantasía de convertirse en un superhéroe. Roy tiene un empleo sin futuro en una chatarrería, Jeffrey vive en casa de su madre y se pasa el día encerrado en su cuarto, Eddie anhela el apoyo de su familia, pero sus hijos se burlan de él y su mujer le regaña. De día todo parece normal, pero de noche Roy, Jeffrey y Eddie se convierten en Mister Furioso, El Rajá Azul y El Zapador, héroes que peinan las calles en busca de villanos.', trailer_url = 'https://www.youtube.com/watch?v=pPkXTEZupEo' WHERE id_api = 'tt0132347';

UPDATE Contenido SET id_tmdb = 13466, descripcion = 'En 1957 en la pequeña ciudad minera de Coalwood, Homer Hickam sabe, como todos los chicos, que de mayores terminarán trabajando en las minas de carbón. Como no tiene el talento de su hermano para el fútbol americano, Homer intuye que no escapará de este estilo de vida. Pero el satélite soviético Sputnik atraviesa el cielo de octubre y todo cambiará. Homer decide fabricar un cohete junto con sus amigos y, a pesar de los fracasos iniciales logrará convencer a todos de que incluso en Coalwood se puede soñar con las estrellas.', trailer_url = 'https://www.youtube.com/watch?v=4cmMukCFyd8' WHERE id_api = 'tt0132477';

UPDATE Contenido SET id_tmdb = 869, descripcion = 'Año 2029. En una misión rutinaria, el astronauta Leo Davidson pierde el control de su nave y aterriza en un extraño planeta, habitado por una raza de simios de inteligencia similar a la de los humanos y que tratan a éstos como a animales. Con la ayuda de una chimpancé llamada Ari y de una pequeña banda de humanos rebeldes, Leo encabeza el enfrentamineto contra el terrible ejército dirigido por el general Thade y su hombre de confianza, el guerrero Attar. La clave es llegar a un templo sagrado que se encuentra en la zona prohibida del planeta.', trailer_url = 'https://www.youtube.com/watch?v=h2yzzzfLSeE' WHERE id_api = 'tt0133152';

UPDATE Contenido SET id_tmdb = 9016, descripcion = 'Jim, un surfista solar, se enfrenta a una cacería intergaláctica de tesoros cuando cae en sus manos un legendario mapa que le llevará a buscar la fortuna más grande del Universo. A bordo de un espectacular ''galeón solar'', Jim se convierte en el ayudante del cocinero del barco, John Silver -mitad hombre, mitad máquina-, que le enseña a ser un buen explorador del espacio.', trailer_url = 'https://www.youtube.com/watch?v=G4uMQMMdFeg' WHERE id_api = 'tt0133240';

UPDATE Contenido SET id_tmdb = 9564, descripcion = 'La pequeña villa de Astérix y Obelix es el último lugar que queda fuera del control de Roma. Cuando el recaudador de impuestos Claudius Incorruptus no consigue el dinero de sus habitantes, el propio Julio César se acerca al lugar para ver qué hay de especial en ellos. El secreto es una poción mágica preparada por su druida Panoramix les da a todos una fuerza sobrehumana cuando la beben.', trailer_url = 'https://www.youtube.com/watch?v=ZZtqOvEWxYM' WHERE id_api = 'tt0133385';

UPDATE Contenido SET id_tmdb = 9276, descripcion = 'El instituto Herrington es un sitio de mugrientas paredes, anticuados libros de texto y profesores quemados. No hay dinero para excursiones ni para ordenadores nuevos ni para el departamento de Música. Los alumnos son de lo más heterogéneo: solitarios, líderes, pandilleros y cerebritos. Como todos los adolescentes del mundo, han de vérselas con unos padres que no los entienden, con unos profesores que los subestiman y, además, con sus activas hormonas. Lo que ignoran es que están a punto de enfrentarse con algo que nunca podrían haber imaginado.', trailer_url = 'https://www.youtube.com/watch?v=coWVuhk0K-Y' WHERE id_api = 'tt0133751';

UPDATE Contenido SET id_tmdb = 4234, descripcion = 'Después de los terroríficos acontecimientos que tuvieron lugar en la localidad de Woodsboro, Sidney vive alejada del mundo en una casita de las montañas, intentando olvidar el pasado. Se dedica a proporcionar apoyo moral a mujeres con problemas a través del teléfono; pero, un día, alguien la llama para informarla de los asesinatos que se están produciendo durante el rodaje de "Puñaladas 3", película basada en los hechos de los que ella fue protagonista.', trailer_url = 'https://www.youtube.com/watch?v=uJmT7c7rbwQ' WHERE id_api = 'tt0134084';

UPDATE Contenido SET id_tmdb = 9882, descripcion = 'Tras el secuestro de un líder religioso musulmán por tropas norteamericanas, Nueva York se convierte en el objetivo de una serie de atentados terroristas. Anthony Hubbard, el director del equipo antiterrorista del FBI, y la agente de la CIA Elise Kraft serán los encargados de acabar con la organización criminal. Mientras tanto, el gobierno decide declarar la ley marcial en la Gran Manzana.', trailer_url = 'https://www.youtube.com/watch?v=87Rai0X97Fc' WHERE id_api = 'tt0133952';

UPDATE Contenido SET id_tmdb = 8224, descripcion = 'Un detective privado consigue mantener dignamente a su familia ocupándose de resolver casos sencillos e irrelevantes. Pero, de repente, su vida cambia radicalmente cuando, durante la investigación de un caso, queda atrapado dentro de un sórdido mundo de espeluznantes snuff-movies.', trailer_url = 'https://www.youtube.com/watch?v=Qzgz7fn90cs' WHERE id_api = 'tt0134273';

UPDATE Contenido SET id_tmdb = 1213, descripcion = 'Ser joven y despreocupado en medio de un paisaje idílico de la Italia bañada por el sol de finales de los 50: esa es la dolce vita que Tom Ripley (Matt Damon) anhela, y que Dickie Greeleaf (Jude Law) disfruta. Cuando el padre de Dickie, un adinerado constructor de barcos, pide a Tom que traiga de vuelta a casa, a América, a su hijo, éste y su bella y expatriada compañera, Marge Sherwood (Gwyneth Paltrow), nunca hubieran sospechado a qué peligrosos extremos llegaría Ripley con tal de convertir el estilo de vida de la pareja en el suyo propio. Al fin y al cabo, es mejor ser una falsa persona importante que un don nadie auténtico.', trailer_url = 'https://www.youtube.com/watch?v=Ylc5ToQoLg0' WHERE id_api = 'tt0134119';

UPDATE Contenido SET id_tmdb = 2787, descripcion = 'Durante un viaje interestelar, un carguero espacial sufre una avería a causa de una tormenta de asteroides, viéndose obligado a efectuar un aterrizaje de emergencia en el que muere parte del pasaje. Un asesino muy peligroso, Riddick, que formaba parte de la carga, huye del lugar dejando a los supervivientes con dos preocupaciones, él y unas peligrosas criaturas nocturnas que salen a la superficie cuando los tres soles del planeta se oscurecen a causa de un eclipse.', trailer_url = 'https://www.youtube.com/watch?v=eLM4VtLC4CE' WHERE id_api = 'tt0134847';

UPDATE Contenido SET id_tmdb = 1073, descripcion = 'Atormentados por la muerte de su esposa, Michael y su hijo Grant entablan una gran amistad con sus nuevos vecinos, los Hunts. Pero, a medida que las dos familias se encuentran más unidas, Michael empieza a sospechar que sus vecinos no son quienes dicen ser, que algo tienen que esconder, e incluso llegará a pensar que ellos tienen algo que ver con la muerte de su esposa...', trailer_url = 'https://www.youtube.com/watch?v=tzzT_Iaw0t8' WHERE id_api = 'tt0137363';

UPDATE Contenido SET id_tmdb = 550, descripcion = 'Un hombre consumido por el insomnio y una vida sin sentido conoce a Tyler Durden, un carismático anarquista que lo arrastra a un club secreto donde el dolor despierta algo dormido. Lo que comienza como liberación pronto se convierte en una guerra contra el sistema…', trailer_url = 'https://www.youtube.com/watch?v=aIo4Adm96EA' WHERE id_api = 'tt0137523';

UPDATE Contenido SET id_tmdb = 1934, descripcion = 'Londres, 1593, reinado de Isabel I Tudor. William Shakespeare, joven dramaturgo de gran talento, necesita urgentemente poner fin a la mala racha por la que está pasando su carrera. Por mucho que lo intenta, y a pesar de la presión de los productores y de los dueños de salas de teatro, no consigue concentrarse en su nueva obra: "Romeo y Ethel, la hija del pirata". Lo que Will necesita es una musa y la encontrará en la bella Lady Viola, con la que mantiene un romance secreto. Ahora bien, Lady Viola guarda dos secretos que él debe descubrir.', trailer_url = 'https://www.youtube.com/watch?v=P_rHx-Yv7zQ' WHERE id_api = 'tt0138097';

UPDATE Contenido SET id_tmdb = 1844, descripcion = 'Siguiendo la pista de una valiosa pieza de arte robada, la agente de seguros Gin Baker convence a su compañía para que le permitan llevar a cabo un golpe en colaboración con un prestigioso y veterano ladrón, Robert "Mac" MacDouglas. Pero Mac la someterá a una serie de duros entrenamientos y pruebas antes de confiar en ella.', trailer_url = 'https://www.youtube.com/watch?v=LFSpRNtxd8I' WHERE id_api = 'tt0137494';

UPDATE Contenido SET id_tmdb = 2900, descripcion = 'Una pareja de astronautas regresa de un viaje espacial donde algo extraño ha sucedido. Spencer Armacost y Alex Streck estaban en una en misión espacial cuando, durante una salida de la nave, pierden el contacto con la base de control durante algunos minutos. Luego todo vuelve a la normalidad y ellos regresan a la Tierra. Pero, tras el regreso, muchas cosas extrañas comienzan a suceder en la vida de los astronautas.', trailer_url = 'https://www.youtube.com/watch?v=pu_TmXgGEG8' WHERE id_api = 'tt0138304';

UPDATE Contenido SET id_tmdb = 6552, descripcion = 'Anton es un joven que la mañana siguiente a Halloween descubre los cadáveres decapitados de sus padres. Los crímenes se suman a una serie de muertes violentas que han ocurrido en el vecindario y de las que el muchacho no se había enterado. Ahora, atando cabos, empieza a ser consciente de que en realidad tiene mucho que ver con dichas muertes, y es que su mano derecha parece ser que actúa por su propia cuenta.', trailer_url = 'https://www.youtube.com/watch?v=Gl8-Z3rVvTs' WHERE id_api = 'tt0138510';

UPDATE Contenido SET id_tmdb = 11775, descripcion = 'Miles Massey es un famoso abogado de Los Ángeles especializado en casos de divorcio. Su hastío a causa del éxito termina cuando conoce a Marylin Rexroth, la esposa de un rico constructor cliente de Miles, al que tiene atrapado por una infidelidad gracias a las pesquisas de un detective. Sin embargo la habilidad de Miles en su oficio hace que Marylin no reciba ni un sólo dolar. Pero Marylin, lejos de desanimarse, decide pagarle con la misma moneda: planea casarse con el multimillonario petrolero Howard Doyle.', trailer_url = 'https://www.youtube.com/watch?v=6h4RZ1Jtw5I' WHERE id_api = 'tt0138524';

UPDATE Contenido SET id_tmdb = 10501, descripcion = 'Siglo XVI. Dos jóvenes estafadores ganan en un juego de dados un mapa a El Dorado pero son descubiertos y perseguidos por los guardias. Logran escapar pero terminan por meterse en el barco del mismisimo Hernán Cortés. Escapan en un bote del barco y llegan a tierra arrastrados por el mar. Allí deciden emprender la búsqueda de la ciudad de oro al reconocer indicios que aparecían en el mapa, pero su aventura no terminará como ellos lo esperan.', trailer_url = 'https://www.youtube.com/watch?v=ErD6OTyvB1A' WHERE id_api = 'tt0138749';

UPDATE Contenido SET id_tmdb = 473, descripcion = 'Max es un brillante matemático que está a punto de dar con el descubrimiento más importante de su vida: la decodificación del sistema numérico que rige el aparente caos del mercado bursátil. Pero primero ha de encontrar el valor del número PI. Mientras se acerca a la verdad, y afectado periódicamente por unas brutales jaquecas, Max es acosado por una agresiva firma de Wall Street y una secta judía que pretende descifrar los secretos ocultos tras los textos sagrados. Todos ansían apropiarse del inminente hallazgo de Max', trailer_url = 'https://www.youtube.com/watch?v=yRjkQT9xLZs' WHERE id_api = 'tt0138704';

UPDATE Contenido SET id_tmdb = 796, descripcion = 'Kathryn y Sebastian son dos hermanastros que viven Manhattan, estudiantes de bachillerato en un elitista instituto de Nueva York. Cada uno es más manipulador y más perverso que el otro, así que harán una singular apuesta. Sebastian debe cortejar a una chica virgen que ha encandilado al novio de Kathryn. Si Sebastian pierde, Kathryn se quedará con su Jaguar, pero si gana... la tendrá a ella.', trailer_url = 'https://www.youtube.com/watch?v=UzlKsS-IhEo' WHERE id_api = 'tt0139134';

UPDATE Contenido SET id_tmdb = 1090, descripcion = 'Hannon Fuller, un magnate de los negocios y empresario emprendedor, muere en extrañas circunstancias. Su amigo y mano derecha, Douglas Hall, se ve lanzado a un mundo de crímenes y decepciones, llegando a descubrir que Fuller llevaba una peligrosa doble vida que se movía entre dos mundos paralelos: uno en 1937 y otro en el presente.', trailer_url = 'https://www.youtube.com/watch?v=CMSxmp-LRvw' WHERE id_api = 'tt0139809';

UPDATE Contenido SET id_tmdb = 9430, descripcion = 'Ronna (Sarah Polley) necesita dinero, Simon (Desmond Askew) quiere pasar el fin de semana en Las Vegas. Por su parte, Adam (Scott Wolf) y Zack (Jay Mohr), aunque no quieren meterse en líos están a punto de embarcarse en una aventura que no acabará hasta que amanezca.', trailer_url = 'https://www.youtube.com/watch?v=0KTWEFpDOis' WHERE id_api = 'tt0139239';

UPDATE Contenido SET id_tmdb = 9825, descripcion = 'Cuando un hombre es comido vivo por una criatura desconocida, el guardián local se une con una paleontóloga de Nueva York para encontrar a la bestia.  Añade a la mezcla un filántropo excéntrico con una inclinación por los cocodrilos y...ya lo tenemos!.  Este lago remoto y tranquilo es de repente el foco de una intensa búsqueda de un cocodrilo con un gusto por los animales vivos....y las personas!', trailer_url = 'https://www.youtube.com/watch?v=I9VhNITGtLI' WHERE id_api = 'tt0139414';

UPDATE Contenido SET id_tmdb = 2034, descripcion = 'Todos los días, en las calles de las zonas urbanas deprimidas de los Estados Unidos se libra una guerra; una guerra entre residentes, traficantes de droga y los que han jurado proteger a unos de los otros. Esta guerra tiene sus víctimas y sus verdugos, y una de sus figuras más importantes es el sargento Alonzo Harris, un agente de narcóticos con 13 años de experiencia cuyos discutibles métodos hacen difusa la línea entre la legalidad y la corrupción. Jake Hoyt, un joven policía recién asignado a narcóticos, comienza sus rondas a las órdenes de Alonzo para aprender de él.', trailer_url = 'https://www.youtube.com/watch?v=VQ-SCoyUwfg' WHERE id_api = 'tt0139654';

UPDATE Contenido SET id_tmdb = 14709, descripcion = 'Los West Canaan Coyotes están muy cerca de lograr su 23º título de liga. De la mano de su entrenador, el mítico Bud Kilmer, el equipo ha alcanzado la cima del fútbol americano juvenil en Texas, un estado en el que la afición por este deporte es prácticamente una forma de vida. Sus grandes logros han convertido a Kilmer en un mito para los habitantes de l pequeña ciudad en la que juega el equipo y nadie, ni padres ni jugadores, se han atrevido nunca a cuestionar las técnicas más que dudosas que el popular entrenador ha venido utilizando para encumbrar a sus jóvenes deportistas a lo más alto.', trailer_url = 'https://www.youtube.com/watch?v=eSnkWiacUW4' WHERE id_api = 'tt0139699';

UPDATE Contenido SET id_tmdb = 9008, descripcion = 'Jeffrey Wigand, científico y directivo de la famosa tabacalera norteamericana Brown & Williamson, descubre el secreto celosamente guardado por la industria tabacalera sobre las sustancias que crean adicción en los fumadores. El productor del programa 60 minutes, Lowell Bergman, arriesga su carrera para poner frente a las cámaras a Wigand, que ve como su vida entera se viene abajo al revelar la verdad a la opinión pública. Nadie saldrá indemne de esta batalla contra la industria del tabaco. Nada volverá a ser como antes.', trailer_url = 'https://www.youtube.com/watch?v=P-_ZdJxgwcU' WHERE id_api = 'tt0140352';

UPDATE Contenido SET id_tmdb = 666, descripcion = 'En los asfixiantes pasillos de la Estación Central, en Río de Janeiro, una antigua maestra se gana la vida escribiendo las cartas que le dictan los analfabetos. Endurecida por la soledad y por la adversidad, Dora ha ido cayendo en una estoica indiferencia. Sin embargo, cuando una de sus clientes muere atropellada a la salida de la estación, decide hacerse cargo de su hijo y llevarlo a casa de su padre en una remota zona del nordeste de Brasil.', trailer_url = 'https://www.youtube.com/watch?v=qCoqppCsEa8' WHERE id_api = 'tt0140888';

UPDATE Contenido SET id_tmdb = 332, descripcion = 'John Brown es un inocente guardia de seguridad que sueña con ser el mejor agente de policía del mundo. Cuando accidentalmente su camino se cruce con el malvado Sanford Scolex será dado por muerto. En el hospital, Brenda Bradford le implantará en el cuerpo 14.000 dispositivos fáciles de utilizar. Cuando Brown despierte, se habrá transformado en el Inspector Gadget, una máquina perfectamente preparada para luchar contra el crimen. Basada en la serie de dibujos animados de TV de los años ochenta. Efectos especiales de Stan Winston.', trailer_url = 'https://www.youtube.com/watch?v=x48CNwTvrPU' WHERE id_api = 'tt0141369';

UPDATE Contenido SET id_tmdb = 622, descripcion = 'Dean Corso (Johnny Depp) trabaja de forma confidencial, con sumo cuidado, dotado de una sólida cultura, nervios de acero y pocos escrúpulos. Su reputación le ha servido para recibir la llamada de Boris Balkan (Frank Langella), un apasionado de los textos demoníacos que quiere encontrar los dos últimos libros del legendario manual de invocación satánica De umbrarum regni novem portis: Las nueve puertas del Reino de las Sombras. De Nueva York a Toledo y de París a Sintra, Corso se verá inmerso en un laberinto lleno de peligro, tentaciones, aterradoras sorpresas, violencia y muertes inesperadas.', trailer_url = 'https://www.youtube.com/watch?v=6QdBiSIgtg4' WHERE id_api = 'tt0142688';

UPDATE Contenido SET id_tmdb = 3536, descripcion = 'En 1942, en plena Segunda Guerra Mundial, la flota alemana está ganando la partida a la armada aliada causándoles gran número de bajas. Cientos de barcos están siendo hundidos por los submarinos de Hitler gracias a un sistema de comunicaciones llamado "enigma", que posiciona con increíble exactitud los objetivos a los que deben atacar. Pero ahora, un capitán norteamericano ha detectado las señales de "enigma". Se encuentran a bordo de un submarino alemán averiado, el U-571, en mitad del Atlántico Norte. Rápidamente, un grupo de oficiales aliados, haciéndose pasar por miembros de la armada alemana a bordo del S-33, son enviados para reducir a la tripulación del U-571 y capturar el codificador "enigma", con el que las comunicaciones alemanas podrán ser interceptadas.', trailer_url = 'https://www.youtube.com/watch?v=LvcbGleQjJ4' WHERE id_api = 'tt0141926';

UPDATE Contenido SET id_tmdb = 36643, descripcion = 'Tras la muerte del magnate británico del petróleo Sir Robert King en un atentado en el cuartel general del MI6, su hija Elektra hereda su billonaria fortuna en yacimientos petrolíferos en el mar Caspio. El agente 007, sintiéndose culpable de la muerte de su padre, se convierte en su guardaespaldas. Su fortuna atraerá la atención de la prensa internacional y también de su asesino, Renard, un hombre con una bala alojada en el cerebro que le impide sentir dolor físico y cuya única obsesión es la venganza.', trailer_url = 'https://www.youtube.com/watch?v=NglfF8zHMzM' WHERE id_api = 'tt0143145';

UPDATE Contenido SET id_tmdb = 9032, descripcion = 'Sonny Koufax es un abogado treintañero al que nunca le ha gustado asumir las responsabilidades de su condición de adulto. Sin embargo, a medida que sus antiguos compañeros se van casando, Sonny se da cuenta de que si no hace algo pronto podría quedarse solo para el resto de su vida. Después de que su última novia le abandone por su inmadurez, decide hacer algo drástico que cambie su vida: adoptar a Julian, un niño de 5 años.', trailer_url = 'https://www.youtube.com/watch?v=J_l5fMb1oxg' WHERE id_api = 'tt0142342';

UPDATE Contenido SET id_tmdb = 1398, descripcion = 'Los Soprano (The Sopranos) es una serie de televisión estadounidense creada y producida por David Chase. La serie se estrenó en Estados Unidos el 10 de enero de 1999 por el canal de televisión por cable HBO, que la emitió ininterrumpidamente hasta su desenlace, el 10 de junio de 2007. La trama de la serie gira en torno al mafioso de Nueva Jersey Tony Soprano (James Gandolfini) y las dificultades que enfrenta tanto en su hogar como en la organización criminal que dirige. A su vez, la serie también se centra en la historia de los personajes cercanos a Tony, especialmente su esposa Carmela (Edie Falco) y su sobrino y protegido Christopher Moltisanti (Michael Imperioli).', trailer_url = 'https://www.youtube.com/watch?v=Q8cBFvpqmH0' WHERE id_api = 'tt0141842';

UPDATE Contenido SET id_tmdb = 557, descripcion = 'Peter Parker es un joven y tímido estudiante que vive con su tía May y su tío Ben desde la muerte de sus padres. Un día es mordido por una araña que ha sido modificada genéticamente, descubriendo al día siguiente que posee unos poderes poco habituales: tiene la fuerza y agilidad de una araña.', trailer_url = 'https://www.youtube.com/watch?v=zWT32yFM8bU' WHERE id_api = 'tt0145487';

UPDATE Contenido SET id_tmdb = 1359, descripcion = 'En un mundo moralmente plano en el que la ropa tiene más sentido que la piel, Patrick Bateman es un espécimen soberbiamente elaborado que cumple todos los requisitos de Master del Universo, desde el diseño de su vestuario hasta el de sus productos químicos. Es prácticamente perfecto, como casi todos en su mundo e intenta desesperadamente encajar en él. Cuando más intenta ser como cualquier otro hombre adinerado de Wall Street, más anónimo se vuelve y menos control tiene sobre sus terribles instintos y su insaciable sed de sangre, que lo arrastra a una vorágine en la que los objetos valen más que el cuerpo y el alma de una persona.', trailer_url = 'https://www.youtube.com/watch?v=81mibtQWWBg' WHERE id_api = 'tt0144084';

UPDATE Contenido SET id_tmdb = 8374, descripcion = 'Dos hermanos católicos irlandeses se convierten en justicieros y deciden acabar con el inframundo criminal de Boston en nombre de Dios.', trailer_url = 'https://www.youtube.com/watch?v=IMs4ESRJuCU' WHERE id_api = 'tt0144117';

UPDATE Contenido SET id_tmdb = 817, descripcion = 'Austin Powers es un agente secreto de los años 60 que, tras ser congelado, vuelve a la vida en los años 90. En esta nueva entrega de sus aventuras, Austin Powers se enfrentará con nuevos villanos, pero deberá volver a luchar con el Doctor Maligno, su máximo enemigo. El malvado doctor tiene un siniestro plan: ha inventado una máquina del tiempo que le permitirá volver a los años 60 y destruir a su archienemigo, que deberá unir sus fuerzas a una bella agente para derrotarle.', trailer_url = 'https://www.youtube.com/watch?v=Cfh5HliruZw' WHERE id_api = 'tt0145660';

UPDATE Contenido SET id_tmdb = 11932, descripcion = 'Chucky, el implacable muñeco asesino, vuelve a la vida. Tiffany, se ha encargado de resucitarlo. Pero su amado no reacciona como ella esperaba. Chucky, que echa de menos la compañía de alguién como él, consigue traspasar el alma de Tiffany a una muñeca. Con su ayuda, Chucky aspira a recuperar su forma humana. Mientras llega el momento, deja a su paso un reguero de muerte y destrucción.', trailer_url = 'https://www.youtube.com/watch?v=VNpqr8GfNRg' WHERE id_api = 'tt0144120';

UPDATE Contenido SET id_tmdb = 11973, descripcion = 'En plena guerra fría, la Administración Kenney se enfrenta a la ofensiva soviética de los misiles en Cuba, capaces de alcanzar en cuestión de minutos diversas ciudades americanas de la Costa Este.Un pulso a vida o muerte entre los Estados Unidos y Rusia, y JFK y sus principales consejeros batallando con el Pentágono y la CIA sobre la conveniencia de un asalto militar en Cuba.Un conflicto nuclear de dimensión internacional está a punto de estallar, y el destino del mundo está en manos de un solo hombre.', trailer_url = 'https://www.youtube.com/watch?v=PqM102xIbIs' WHERE id_api = 'tt0146309';

UPDATE Contenido SET id_tmdb = 10307, descripcion = 'Una joven norteamericana, Frankie Paige (Patricia Arquette), comienza a mostrar misteriosos estigmas tras recibir de Brasil un paquete de su madre con un crucifijo y posteriormente sufrir un accidente en la bañera. Para investigar su caso, enviado por el Vaticano, llega desde Roma el padre Andrew Kiernan (Gabriel Byrne), un sacerdote encargado de descifrar milagros y que anteriormente había estado de un pequeño pueblo del Brasil donde brotan lágrimas de sangre de la estatua de una iglesia.', trailer_url = 'https://www.youtube.com/watch?v=vrAfiEM30nk' WHERE id_api = 'tt0145531';

UPDATE Contenido SET id_tmdb = 9481, descripcion = 'Lincoln Rhyme es un policía que está en silla de ruedas desde que le cayó una viga encima durante una investigación y lo dejó tetrapléjico. Un asesino en serie deja pistas que sólo Lincoln puede descrifrar, y éste contará con la ayuda de Amelia Donaghy para resolver el misterio creado por el asesino.', trailer_url = 'https://www.youtube.com/watch?v=uVTbS1wg_wQ' WHERE id_api = 'tt0145681';

UPDATE Contenido SET id_tmdb = 2275, descripcion = 'Un tenaz y astuto oficial de élite de la división de Investigación Criminal del ejército estadounidense recibe una nueva misión: encontrar, junto con una colega, al asesino de la hija de un famoso general, que tenía cargo de capitán. Podrá arrestar a cualquier miembro del Ejército sobre el que recaigan sus sospechas, pero el asunto se complica cuando van descubriendo que la vida privada de la muerta hace sospechosos a todos los residentes de Fort MacCullam: desde el propio padre, pasando por su fiel ayudante y amigo, hasta el oficial de mando.', trailer_url = 'https://www.youtube.com/watch?v=k1MQqkCA484' WHERE id_api = 'tt0144214';

UPDATE Contenido SET id_tmdb = 12107, descripcion = 'El profesor Sherman Klump está a punto de casarse y toda la familia Klump no podría estar más feliz. Pero su alter-ego Buddy Love volverá para intentar hacer de las suyas. Utilizando una muestra de ADN obtenida del laboratorio de Denise, la prometida de Sherman, intentará independizarse de él creando un clon suyo.', trailer_url = 'https://www.youtube.com/watch?v=X5BnhugnRR8' WHERE id_api = 'tt0144528';

UPDATE Contenido SET id_tmdb = 1995, descripcion = 'Explorar imperios perdidos, descubrir tesoros de incalculable valor, castigar a los malvados en combates a vida o muerte… todo forma parte de un día de trabajo para la aventurera Lara Croft. Pero un secreto del pasado de su padre va a llevar a Lara a su desafío más grande: el Triángulo de la Luz, un legendario artefacto con el poder de alterar el espacio y el tiempo. Lara ha de encontrar el Triángulo antes de que caiga en poder de los Illuminati, una sociedad secreta dispuesta a dominar el mundo. Para detener a los Illumitati, Lara ha de sobrevivir a una auténtica cacería a través del planeta, repleta de inimaginables peligros.', trailer_url = 'https://www.youtube.com/watch?v=-0enc2VSiKE' WHERE id_api = 'tt0146316';

UPDATE Contenido SET id_tmdb = 9877, descripcion = 'Hay un asesino suelto por el campus que está convirtiendo en realidad leyendas urbanas, como la de que comer poprocks (peta-zetas) y beber cocacola a la vez hará explotar tu estómago o la del psicópata con un hacha que entra, cuando no miras, en el asiento trasero de tu coche al repostar en una gasolinera.', trailer_url = 'https://www.youtube.com/watch?v=R4d1_D90BwU' WHERE id_api = 'tt0146336';

UPDATE Contenido SET id_tmdb = 9946, descripcion = 'Nueva York, 1979. En un hospital de Manhattan acaba de nacer Christine, una niña preciosa. Ese mismo día, en el Vaticano, un joven sacerdote informa al Papa del nacimiento de la niña, que lleva la marca del Anticristo. En 1999, Jericho Cane, un ex-policía amargado, salva a una joven del asalto de unos ladrones: es Christine. Desde entonces Cane será víctima de la persecución de terribles fuerzas sobrenaturales.', trailer_url = 'https://www.youtube.com/watch?v=3qO3R8OlwYs' WHERE id_api = 'tt0146675';

UPDATE Contenido SET id_tmdb = 4951, descripcion = 'Las hermanas Stratford son muy distintas. La guapa y popular Bianca nunca ha salido con un chico, y Kat, su hermana mayor, es una bruja con muy mal genio, y algo arisca, que se ha propuesto rechazar a cualquier chico que demuestre el más mínimo interés por ella. Desgraciadamente, el estricto reglamento que rige el hogar de los Stratford prohibe a Blanca tener novio hasta que su insoportable hermana tenga uno; situación que parece más que improbable teniendo en cuenta que Kat lleva una vida social desastrosa. Blanca está desesperada por ir al baile de fin de curso. Pero su pretendiente, Cameron, guarda una sorpresa...', trailer_url = 'https://www.youtube.com/watch?v=GbWQ_VXek6A' WHERE id_api = 'tt0147800';

UPDATE Contenido SET id_tmdb = 9563, descripcion = 'Cuatro años antes, los Tiburones de Miami, dirigidos por el entrenador D''Amato, habían ganado dos campeonatos consecutivos, pero ahora sólo consiguen acumular derrotas. Además, el público escasea y los antiguos ídolos están en el ocaso de sus carreras, particularmente Jack "Cap" Rooney, que a sus 39 años se aferra desesperadamente a lo poco que le queda como jugador profesional. Por otra parte, son frecuentes los conflictos con Christina Pagniacci, la joven presidenta y propietaria del equipo.', trailer_url = 'https://www.youtube.com/watch?v=cC2rkQThgX0' WHERE id_api = 'tt0146838';

UPDATE Contenido SET id_tmdb = 8914, descripcion = 'Utilizando tiburones Mako, una de las máquinas de matar más rápidas y perfectas de la naturaleza, la doctora McAlester espera encontrar la clave de la regeneración de los tejidos del cerebro humano. Pero para alcanzar su meta ha violado los códigos éticos, modificando el ADN de los tiburones, haciendo que sean más inteligentes y más rápidos, convirtiéndolos de depredadores peligrosos en monstruos depredadores que pondrán en peligro a todo el equipo de trabajo...', trailer_url = 'https://www.youtube.com/watch?v=l2C07HRRd5g' WHERE id_api = 'tt0149261';

UPDATE Contenido SET id_tmdb = 243, descripcion = 'En esta comedia romántica y mordaz, Rob Gordon es el dueño de una tienda de discos de Chicago, cuya peculiaridad es que vende, sobre todo, discos de vinilo. Rob dice ser un verdadero fanático de la música, y se pasa todo el tiempo en el Championship Vinyl con sus dos empleados, Dick y Barry, dos tipos de lo más peculiar. Aunque los tres conocen a fondo el mundo de la música popular, y les encantan los conciertos y la idea de hacer listas de las cinco mejores canciones de todos los tiempos por categorías específicas, Rob está pasando por un mal momento: su relación con Laura, su actual novia, se rompe. Y a partir de ese momento Rob empieza a reflexionar sobre sus desengaños amorosos, lo que él llama "las cinco principales", es decir, las chicas que han dejado huella en su vida. Eso sí, sin dejar de lado la música, la auténtica pasión de su vida, junto a las mujeres.', trailer_url = 'https://www.youtube.com/watch?v=6P4dXJ_Tvns' WHERE id_api = 'tt0146882';

UPDATE Contenido SET id_tmdb = 4958, descripcion = 'Tras su heroico comportamiento en la Primera Guerra Mundial (1914-1918), Rannulph Junuh (Matt Damon) se hace muy popular. En 1931, lo invitan a enfrentarse a dos famosos jugadores en un torneo de golf, cuyo fin es inaugurar un nuevo campo y atraer la atención del público gracias a su presencia. Pero como Junuh no está al nivel de sus adversarios, decide contratar a un caddie muy especial, Bagger Vance (Will Smith), un misterioso joven negro que parece esconder más de un as en la manga.', trailer_url = 'https://www.youtube.com/watch?v=lpsF4MfeGlQ' WHERE id_api = 'tt0146984';

UPDATE Contenido SET id_tmdb = 10683, descripcion = 'Happiness es un agudo retrato de varias personas conectadas por lazos familiares o sociales, viviendo en estado de desesperación o de simple depresión, y forzadas a tomar actitudes delictivas o inmorales. Verdadera, trágica y divertida, es una película de culto en el cine americano de los años 90.', trailer_url = 'https://www.youtube.com/watch?v=1eOzYczx-Xk' WHERE id_api = 'tt0147612';

UPDATE Contenido SET id_tmdb = 10398, descripcion = 'Nick Parsons y su esposa Libby viven aparentemente una vida idílica junto a su hijo Matty. Pero una noche navegando Nick desaparece, y Libby es acusada de su asesinato y enviada a prisión. Allí se entera de que su marido sigue vivo, y también de que una vez juzgada y sentenciada por un crimen, una persona no puede volver a ser juzgada por el mismo delito....', trailer_url = 'https://www.youtube.com/watch?v=y0cRIxT5IkQ' WHERE id_api = 'tt0150377';

UPDATE Contenido SET id_tmdb = 2330, descripcion = 'Daniel, un joven repartidor de pizzas, consigue hacer realidad uno de sus sueños: obtener la licencia de taxi. Pero un encuentro fortuito con Emilien le pone en un aprieto: para conservar su licencia de taxi, han de detener a una banda que está desmantelando los bancos del país.', trailer_url = 'https://www.youtube.com/watch?v=qYBNjVnbtFg' WHERE id_api = 'tt0152930';

UPDATE Contenido SET id_tmdb = 11634, descripcion = 'La película relata la historia de Agnes Ahlberg y Elin Olsson, alumnas de secundario en el "insignificante" pueblo de Åmål. Elin es extrovertida, popular y ha estado con innumerables chicos, pero encuentra su vida exasperantemente aburrida. Agnes, por el contrario, es tímida y no ha conseguido hacer amigos desde que se mudó con su familia a Åmål hace un año.', trailer_url = 'https://www.youtube.com/watch?v=pJTa4EYcdy4' WHERE id_api = 'tt0150662';

UPDATE Contenido SET id_tmdb = 10047, descripcion = 'En 1412, nace en Domrémy (Francia) la Doncella de Orleáns. La guerra de los Cien Años contra Inglaterra dura ya casi un siglo y ha devastado Francia. Juana es una muchacha profundamente religiosa. Después de tener su primera visión, vuelve a su hogar y se encuentra con que los ingleses han matado a su familia. Algunos años después, completamente convencida de que Dios le ha encomendado la misión de expulsar a los ingleses de Francia, va a ver al Delfín, el futuro Carlos VII, que le proporciona tropas para levantar el cerco de Orleáns.', trailer_url = 'https://www.youtube.com/watch?v=aCbMOQIs45s' WHERE id_api = 'tt0151137';

UPDATE Contenido SET id_tmdb = 11355, descripcion = 'Josie Geller trabaja como correctora en un importante periódico, aunque lo que realmente desea es convertirse en periodista. De pronto se le presenta la oportunidad que tanto había estado esperando: su primer trabajo como reportera, en el que deberá infiltrarse en un instituto. Allí revivirá su frustrada adolescencia, pero también conocerá a un profesor que la ayudará a integrarse.', trailer_url = 'https://www.youtube.com/watch?v=xPyMf4ROt3Q' WHERE id_api = 'tt0151738';

UPDATE Contenido SET id_tmdb = 1542, descripcion = 'Harto de su trabajo como programador informático y de su jefe, Peter Gibbons se propone que le despidan para cobrar una buena indemnización y dedicarse a la buena vida junto a una joven camarera llamada Joanna, que es en realidad la que le anima a seguir por ese camino. Pero sus múltiples acciones para conseguir el despido, entre las que figuran llegar tarde o no presentarse al trabajo, son consideradas como una nueva y revolucionaria manera de trabajar, lo que, contra todo pronóstico, le suponen un aumento de sueldo y un ascenso.', trailer_url = 'https://www.youtube.com/watch?v=3_fG_zLbBeU' WHERE id_api = 'tt0151804';

UPDATE Contenido SET id_tmdb = 309, descripcion = 'Los Klingenfeldt, una familia de la alta burguesía danesa, se disponen a celebrar el sesenta cumpleaños del patriarca, un hombre de trayectoria y reputación intachable. Sin embargo, sus tres hijos, aunque muy diferentes entre sí, están dispuestos a aprovechar la ocasión para sacar a relucir los trapos sucios de la familia.', trailer_url = 'https://www.youtube.com/watch?v=XCqc_JTiNxg' WHERE id_api = 'tt0154420';

UPDATE Contenido SET id_tmdb = 11660, descripcion = 'Bill, un aspirante a escritor ocioso y desempleado, deambula por las atestadas calles de Londres siguiendo a personas desconocidas elegidas al azar, un entretenimiento aparentemente inocente que se vuelve peligroso cuando su camino se cruza con el de un misterioso  individuo.', trailer_url = 'https://www.youtube.com/watch?v=62TTN6gD2So' WHERE id_api = 'tt0154506';

UPDATE Contenido SET id_tmdb = 913, descripcion = 'A los cuarenta años, al multimillonario y distinguido Thomas Crown no le queda nada que demostrar: es un triunfador nato. Pero no se siente satisfecho, así que planea robar un Monet del Museo de Nueva York. La policía nunca sospecharía de él, pero sí lo hace una experta y bella detective privada que trabaja para la agencia de seguros del museo. Por esta razón empieza a tantear a Crown por medio de un peligroso juego de inteligencia y seducción.', trailer_url = 'https://www.youtube.com/watch?v=XSGTgwGsP1U' WHERE id_api = 'tt0155267';

UPDATE Contenido SET id_tmdb = 615, descripcion = 'Serie de animación creada por Matt Groening (creador también de Los Simpson) y David X. Cohen (guionista también de Los Simpson). Ambientada en la ciudad de "Nueva Nueva York" en el año 3000, la serie comienza con Philip J. Fry, un joven repartidor de pizza neoyorquino fracasado y desmotivado que es criogénicamente congelado por accidente la Nochevieja de 1999. Mil años después es descongelado, encontrándose en Nueva Nueva York el 31 de diciembre de 2999. El intento de Fry por escapar de la entonces obligatoria asignación laboral como repartidor termina cuando es contratado en Planet Express, una pequeña compañía de mensajería intergaláctica propiedad de su sobrino lejano, como repartidor. La serie trata sobre las aventuras de Fry y sus colegas cuando viajan por el universo haciendo repartos para Planet Express.', trailer_url = 'https://www.youtube.com/watch?v=dUHzt5md1x0' WHERE id_api = 'tt0149460';

