UPDATE Contenido SET id_tmdb = 10490, descripcion = 'En un pequeño pueblo de Norte América se ha convocado una nueva edición del concurso anual de belleza “Joven Princesa Americana”. Dos son las concursantes con mayores posibilidades: la malcriada y rica heredera de un gran imperio de muebles y la modesta maquilladora de la funeraria local...', trailer_url = 'https://www.youtube.com/watch?v=M26Llut3FEM' WHERE id_api = 'tt0157503';

UPDATE Contenido SET id_tmdb = 11252, descripcion = 'Huyendo de la justicia, Marion Crane se refugia en el motel de Norman Bates, un hombre oscuro cuyas víctimas van cayendo en las misteriosas redes de su madre. Marion será la próxima. Su desaparición hará que su hermana y un detective privado emprendan su búsqueda. Remake del clásico de Hitchcock.', trailer_url = 'https://www.youtube.com/watch?v=p0QkvHCfg7w' WHERE id_api = 'tt0155975';

UPDATE Contenido SET id_tmdb = 1443, descripcion = 'A mediados de los 70, en un barrio residencial de una ciudad americana vive en perfecta armonía la familia Lisbon. Todos los chicos suspiran por las cinco hermosas hermanas Lisbon. Sin embargo, ese paraíso se desmorona cuando Cecilia, la menor, se suicida a los doce años. ¿Cómo puede convivir la belleza más pura con una macabra historia adolescente? Ésta es la pregunta que persigue a uno de aquellos adolescentes que, ya en su madurez, aún no ha podido olvidar los sucesos ocurridos veinte años antes.', trailer_url = 'https://www.youtube.com/watch?v=8kDcCGlaBwY' WHERE id_api = 'tt0159097';

UPDATE Contenido SET id_tmdb = 10494, descripcion = 'Tras años siendo una ídolo juvenil que forma parte del exitoso trío musical CHAM!, Mima Kirigoe decide abandonar el grupo para perseguir su sueño de convertirse en actriz. Alentada por su entorno, decide romper con su imagen de niña buena y acepta un papel en una serie policíaca subida de tono, lo que provoca la ira de muchos de sus fans. Pronto descubre que alguien está escribiendo un blog en internet en el que explica detalles íntimos sobre su vida y además su misterioso acosador pasa a la acción amenazando a sus seres queridos. Mientras los cadáveres comienzan a acumularse a su alrededor, la realidad y las alucinaciones se mezclan en un mundo terrorífico en el que no hay lugar para la inocencia y los sueños se convierten en pesadillas.', trailer_url = 'https://www.youtube.com/watch?v=RS3fB6KLz8A' WHERE id_api = 'tt0156887';

UPDATE Contenido SET id_tmdb = 2289, descripcion = 'Adaptación de una novela de Charles Frazier. A punto de terminar la Guerra Civil americana (1861-1865), Inman (Jude Law), un soldado confederado herido, vive una auténtica odisea para regresar a su casa en Cold Mountain (Carolina del Norte) y reunirse con su prometida Ada (Nicole Kidman), que lleva años esperándolo. En su ausencia, Ada tiene que afrontar enormes dificultades para sobrevivir, pero consigue sacar adelante la granja de su padre con la ayuda de Ruby (Zellwegger), una intrépida y voluntariosa joven.', trailer_url = 'https://www.youtube.com/watch?v=Rq7ecfLUtZI' WHERE id_api = 'tt0159365';

UPDATE Contenido SET id_tmdb = 9473, descripcion = 'Cuando los estudiantes de la escuela primaria de South Park, Stan, Kyle, Cartman y Kenny, deciden entrar a escondidas a ver una película canadiense no apta para menores, su vocabulario sufre un cambio brutal. La indignación de los padres, tras el devastador impacto que sufren sus inocentes y jóvenes mentes al ver la película, da lugar a una incondicional guerra entre Estados Unidos y Canadá. Inesperadamente, los chicos se ven inmersos en una crisis debiendo arriesgar sus vidas en nombre de la libertad de expresión.', trailer_url = 'https://www.youtube.com/watch?v=Tq-C9-QJV30' WHERE id_api = 'tt0158983';

UPDATE Contenido SET id_tmdb = 10479, descripcion = 'El coronel Terry Childer (Jackson), un condecorado oficial veterano de Vietnam y Líbano, es acusado de asesinato por el ejército. Como abogado defensor elige al Coronel Hays Hodges (Tommy Lee Jones), un camarada que le debe la vida.', trailer_url = 'https://www.youtube.com/watch?v=usKVcBTxkfk' WHERE id_api = 'tt0160797';

UPDATE Contenido SET id_tmdb = 8007, descripcion = 'Se supone que la guerra en los Balcanes ha terminado, pero la batalla por la supervivencia apenas ha comenzado. Tras ser tiroteado durante una misión de reconocimiento en Bosnia, el piloto americano Chris Burnett (Owen Wilson) tendrá que luchar por sobrevivir y escapar de las tropas serbias. Con el tiempo en su contra, el jefe de Burnett (Gene Hackman) prepara una arriesgada misión de rescate -en contra de las directivas de la OTAN- para salvarlo.', trailer_url = 'https://www.youtube.com/watch?v=PUeWBp_kmuo' WHERE id_api = 'tt0159273';

UPDATE Contenido SET id_tmdb = 8358, descripcion = 'Chuck Noland, un ejecutivo de la empresa multinacional de mensajería FedEx, se ve apartado de su cómoda vida y de su prometida a causa de un accidente de avión por el que queda aislado de la civilización en una remota isla tropical. Único superviviente y solo en la isla, tras cuatro años de subsistencia Chuck aprende todas las técnicas de supervivencia mientras sufre la tortura de la soledad. La solución: arriesgar la vida adentrándose mar adentro.', trailer_url = 'https://www.youtube.com/watch?v=4tVklCz2jcI' WHERE id_api = 'tt0162222';

UPDATE Contenido SET id_tmdb = 4454, descripcion = 'Narra las aventuras y desventuras sentimentales y profesionales de una pareja de treintañeros que comparte un apartamento en Nueva York: él es un gay llamado Will Truman y ella una encantadora diseñadora llamada Grace Adler. Ella está enamorada del atractivo Will, pero con el tiempo acaba por aceptar su condición de homosexual; así es como comienza una inquebrantable amistad llena de complicidad y ternura.', trailer_url = 'https://www.youtube.com/watch?v=PbmZ39kEwGM' WHERE id_api = 'tt0157246';

UPDATE Contenido SET id_tmdb = 1981, descripcion = 'Tras la muerte de su abuela, las hermanas Halliwell descubren que son brujas. Desde ese momento deben aprender a manejarse con sus nuevos poderes y combatir con los demonios que tratan de asesinarlas.', trailer_url = NULL WHERE id_api = 'tt0158552';

UPDATE Contenido SET id_tmdb = 4327, descripcion = 'Una peculiar agencia de detectives dirigida por el multimillonario Charlie tiene en sus filas a Natalie (Cameron Diaz), Dylan (Drew Barrymore) y Alex (Lucy Liu), tres expertas en artes marciales, en disfraces y en la más avanzada tecnología. Juntas tendrán que ocuparse de un caso muy importante: el secuestro del genio de la informática Eric Knox (Sam Rockwell) por su rival Roger Corwin (Tim Curry). Si no consiguen liberarlo, quedaría destruida la intimidad de todo el mundo, incluido Charlie, su misterioso jefe.', trailer_url = 'https://www.youtube.com/watch?v=GtB603KpU9g' WHERE id_api = 'tt0160127';

UPDATE Contenido SET id_tmdb = 10314, descripcion = 'Zack , el chico más popular del instituto, ha sido abandonado por su novia, una joven siempre dispuesta a trepar socialmente. Tras la afrenta, intenta impedir por todos los medios que ella sea elegida la reina anual del instituto y, para ello, apadrina a otra candidata, a la vez que apuesta con un amigo que una chica anónima puede convertirse en la reina de la fiesta de graduación con el adecuado cambio de imagen. La elegida es la tímida Laney. Mientras se esmera en la mejora del aspecto físico de su pupila, el amor se apodera de él.', trailer_url = 'https://www.youtube.com/watch?v=kI9fYsgduGE' WHERE id_api = 'tt0160862';

