UPDATE Contenido SET id_tmdb = 2655, descripcion = 'Norman y Claire parecen ser una pareja muy normal; él es profesor de genética y ella ama de casa. El vacío que deja en Claire la marcha de su hija a la universidad se va convirtiendo en un asunto secundario para ésta, cuando misteriosamente comienzan a ocurrir extraños eventos en la casa. Objetos que se caen, puertas que se abren solas, radios que se encienden sin que nadie las toque..... Claire piensa que la casa está encantada por un espíritu, y decide profundizar en este extraño suceso.', trailer_url = 'https://www.youtube.com/watch?v=s6nTJMdrGVU' WHERE id_api = 'tt0161081';

UPDATE Contenido SET id_tmdb = 479, descripcion = 'Cuando el joven Walter Wade mata a un estudiante negro, John Shaft le detiene. Violando la libertad condicional, el acusado abandona el país. Sin embargo, después de una espera de dos años, Shaft le acaba echando el guante a su anónimo regreso a los Estados Unidos. Cuando el millonario padre de Walter paga su fianza de nuevo, Walter queda libre y desea ver a Shaft muerto. No es el único. El mismo destino quieren para él dos de sus corruptos colegas: Jack Roselli y Jimmy Grovitch, así como un traficante de drogas dominicano, Peoples Hernández, que espera vengarse de Shaft por haberle humillado en el barrio que controla.', trailer_url = 'https://www.youtube.com/watch?v=Mnu70RPh20E' WHERE id_api = 'tt0162650';

UPDATE Contenido SET id_tmdb = 1548, descripcion = 'Enid y Rebecca, dos rebeldes adolescentes amigas desde hace años, no saben cómo pasar el rato ahora que ya han acabado los estudios de secundaria. Pese a sus tímidos esfuerzos por encontrar trabajo, a menudo acaban deambulando por las calles, escrutando el comportamiento de la gente que les rodea. Atraídas por los personajes excéntricos, suelen mirar los anuncios personales del periódico local. Enid llama al autor del anuncio más lamentable, un hombre solitario de cuarenta años, coleccionista de discos, y le invita a una cita a ciegas. Ambas acudirán al restaurante convenido para espiarle y saber cómo es su vida...', trailer_url = 'https://www.youtube.com/watch?v=PXD5GtKF2Dc' WHERE id_api = 'tt0162346';

UPDATE Contenido SET id_tmdb = 2668, descripcion = 'Durante la Guerra de Secesión Americana, un policía de Nueva York que utiliza avanzados métodos de investigación es enviado al pueblo de Sleepy Hollow para descubrir qué hay de verdad en la leyenda de un jinete sin cabeza que aterroriza a los habitantes del lugar. Una vez allí adopta la identidad de un profesor de escuela y se enamora de Katrina, que mantiene relaciones con uno de los hombres más conocidos del pueblo. Realidad y ficción se darán la mano en el momento menos pensado.', trailer_url = 'https://www.youtube.com/watch?v=xC7H4ox8Siw' WHERE id_api = 'tt0162661';

UPDATE Contenido SET id_tmdb = 2105, descripcion = 'Una legión de jóvenes inexpertos están intentando apuntarse un tanto con el sexo opuesto. Jim es como cualquier otro chico de su edad, un joven sano y vigoroso que también resulta ser virgen, el principal motivo de su galopante desesperación. Desde que sus padres le sorprendieron viendo películas pornográficas, las cosas han ido a peor. En casa, su bienintencionado padre extiende un celo mortificador en todo lo referente a la educación sexual de su hijo; en el colegio, las cosas no van mucho mejor: sus experiencias con una belleza perteneciente a un programa de intercambio tienen toda la pinta de fracasar. Así que su último recurso se llama Michelle, una integrante de la banda de música que resulta ser todo un prodigio.', trailer_url = 'https://www.youtube.com/watch?v=_ULIV2sRSvk' WHERE id_api = 'tt0163651';

UPDATE Contenido SET id_tmdb = 331, descripcion = 'El doctor Alan Grant, ansioso por conseguir fondos que financien su estudio sobre la inteligencia del velociraptor, acepta la oferta de pareja de millonarios, Paul y Amanda Kirby, para sobrevolar la Isla Sorna, en Puerto Rico, poblada por dinosaurios creados genéticamente para un parque recreativo. Tras producirse un aterrizaje forzoso en la isla, Alan descubre que los Kirby estaban buscando a su hijo adolescente, perdido en la isla tras un accidente de parapente.', trailer_url = 'https://www.youtube.com/watch?v=FBRWNdXpG1g' WHERE id_api = 'tt0163025';

UPDATE Contenido SET id_tmdb = 4806, descripcion = 'Ike Graham, redactor de un periódico de Nueva York, abrumado por diversos problemas, decide aislarse en su refugio favorito a fin de encontrar ideas para escribir. Allí se entera del caso de Maggie, una joven que vive en una zona rural del estado de Maryland, a la que le encantan los compromisos matrimoniales, pero le horroriza el matrimonio. Intrigado, Ike escribe una columna sobre el caso de la joven, sin prever el enfado de Maggie y la cadena de enredos que acabará desatando.', trailer_url = 'https://www.youtube.com/watch?v=nlOLJ_H0zcA' WHERE id_api = 'tt0163187';

UPDATE Contenido SET id_tmdb = 11601, descripcion = 'Tom Witzky es un hombre normal que vive con su mujer y su hijo de siete años. A pesar de su escepticismo respecto a los fenómenos paranormales, accede a ser hipnotizado durante una fiesta en casa de unos vecinos. A partir de ese momento su vida se ve perturbada por extrañas voces y visiones inexplicables que parecen fragmentos de un rompecabezas que podrían servir para resolver un crimen.', trailer_url = 'https://www.youtube.com/watch?v=Daa5VOnUWsA' WHERE id_api = 'tt0164181';

UPDATE Contenido SET id_tmdb = 2426, descripcion = 'Ángel es una serie de televisión estadounidense, serie secuela de Buffy, la cazavampiros. Ambas comparten a su creador Joss Whedon en colaboración con David Greenwalt y se estrenó en los Estados Unidos el 5 de octubre de 1999 en conjunto con la cuarta temporada de su predecesora.  La trama central de la serie sigue a Ángel, el primer vampiro con alma humana, que en su búsqueda por la redención decide pelear del lado del bien y se muda a Los Ángeles. Con ayuda de antiguos compañeros de Sunnydale como Cordelia Chase y Wesley, así como de aliados nuevos como Charles Gunn y Winifred, Ángel funda una compañía de servicios especializados en resolver los casos sobrenaturales de la ciudad y restaurar la fe y las almas de los que han perdido el camino. Siendo su enemigo más frecuente la firma de abogados demoníaca Wolfram &amp; Hart.', trailer_url = 'https://www.youtube.com/watch?v=rwgxne3tzZw' WHERE id_api = 'tt0162065';

Entonces conocerá a Doyle, un ser mitad demonio mitad humano, y junto a él y Cordelia (que intenta trabajar como actriz) forman Angel Investigations: un servicio de ayuda a gente con problemas.

Crossover: Angel telefonea a Buffy pero no habla. Buffy coge esta misteriosa llamada durante el capítulo "Alumnos de nuevo ingreso", emitido justo antes.', 45, '1999-10-05');

Pronto descubrirán que estan buscando a un demonio asesino en serie que va de cuerpo en cuerpo buscando uno en el que por fin se encuentre a gusto. Angel colaborará con Kate, una policia con la que además conecta.', 45, '1999-10-12');

Desgraciadamente, Spike está ansioso por conseguir el anillo y va a Los Angeles en busca de él. Doyle y Cordelia tendrán que salvar a Angel, que está en apuros. 

Crossover: Este episodio continua la historia del episodio de Buffy "La Áspera luz del día", emitido justo antes.', 43, '1999-10-19');

Los miembros del cuerpo de policía son incapaces de contener sus emociones, lo que puede traer graves problemas.

Doyle es perseguido por un demonio.', 43, '1999-11-09');

Doyle aceptará pero en la despedida de soltero descubrirá que la familia del novio tiene unas inusuales costumbres en lo que al exmaridos se refiere.

Crossover: Al final del episodio Doyle tiene una visión de Buffy en peligro, por lo que Angel decide ir a Sunnydale, apareciendo en el capítulo "Remordimientos".', 45, '1999-11-16');

Al terminar una agotadora caza, y el demonio muerto, algo ocurre en Ángel. La sangre de ese demonio ha provocado un cambio en el. Ángel se empieza a encontrar cansado, con hambre y nota como el corazón le empieza a later.

Ángel se ha convertido en humano, algo que siempre ha querido, y decide volver a retomar la relación con Buffy, pero ¿es todo tan bueno como parece? Ha dejado de ser alguien especial, sin poderes, sin poder proteger a la gente.

Crossover: Este capítulo continua los acontecimientos ocurridos durante el capítulo "Remordimientos".', 45, '1999-11-23');

Para eso Doyle tendrá que superar sus miedos he integrarse con los suyos para que ninguno salga herido. La organización Scourge no tendrá piedad en destruir a todos los mestizos.', 44, '1999-11-30');

Llega a la ciudad un cazademonios que va tras un demonio al que Ángel aparentemente tiene que defender, se trata de un demonio empatico, y al parecer el cazademonios va tras el para arrebatarle su don.', 43, '1999-12-14');

Empieza a creer que el es el causante de dichas muertes, ¿tal vez Ángelus vuelve cuando el esta dormido?.', 43, '2000-01-18');

Ángel y Wesley empiezan a investigar cuando de repente descubren que Cordelia esta embarazada de un demonio y no es la única en la ciudad con los mismo síntomas.', 41, '2000-01-25');

Por supuesto los hombres de esta dimensión intentaran capturarlas, para ello Ángel intenta ayudarlas, aunque ellas crean no necesitar su ayuda.', 42, '2000-02-08');

Desde ese momento, y con la investigación de Wesley, demuestran que alguien de la familia esta poseído por un demonio, ahora tendrán que averiguar quien es y solucionarlo, antes de que demonio se deshaga del anfitrión humano.', 42, '2000-02-15');

Por la situación de padre e hija, Ángel empieza a recordar su relación con sus padres y la manera en la que los mato.', 39, '2000-02-22');

Los hermanos le han engañado y ahora si quiere volver a ser libre tendrá que ganar y matar a los demonios contrincantes.', 41, '2000-02-29');

Una noche Ángel salva la vida de Rebbeca de ser atropellada. Rebecca descubre el pequeño secreto de Ángel, ser vampiro, y en vez de asustarse y huir, le pide ser joven eternamente. Ante la negativa de Ángel, ella intenta convencerle dándole polvos de la eterna alegría, pero lo que ella no se espera es el cambio de personalidad de Ángel, a Ángelus.', 42, '2000-04-04');

En vez de enfrentarse a Ángel directamente, primero ataca a Wesley torturándole hasta casi matarlo, en ese momento una terrible lucha entre ella y Ángel sucede, hasta que Faith pide que la mate a Ángel.

Crossover: Faith fue vista por última vez huyendo de Sunnydale en el capítulo "¿Quién eres tú?"', 41, '2000-04-25');

Buffy llega a L.A. para avisar a Ángel de la escapada de Faith, pero para su sorpresa se encuentra a Ángel abrazando a Faith, en ese momento tras una discusión Ángel pega a Buffy. Faith vuelve a escaparse y Ángel es detenido por Kate por ocultar a una criminal.

El consejo vuelve para detener a la cazadora, y le ofrecen a Wesley un puesto si consigue detener a Faith.

Crossover: Después de este capítulo, Angel visita Sunnydale durante "El Factor Yoko"', 40, '2000-05-02');

Gracias a Lindsey, Ángel se entera que tres niños van a ser asesinados por la chica y para detenerla deben entrar en los archivos de Wolfram & Hart.

Crossover: Cordelia llama a Willow para pedirle ayuda en la decodificación del disco, poco después de los acontecimientos del robo. "Primigenio".', 42, '2000-05-16');

Wolfarm & Hart esta detrás de esto, e intenta por todos los medios mantener a Ángel ocupado hasta que acaben con la invocación. Destruyen las oficinas de Ángel y Wesley queda malherido. Ángel no sabe que hacer y se intenta comunicar con los oráculos pero estos han muerto misteriosamente.

Finalmente Ángel descubre los oscuros secretos del buffet de abogados pero ya es tarde para acabar con lo que se empezó, aunque logra salvar a sus amigos. Pero alguien nuevo ha vuelto de entre los muertos.', 41, '2000-05-23');

Crossover: Este espisodio consiste en gran parte en flashbacks. Algunos de los eventos son contados desde otro punto de vista durante el capítulo "Ansias de amor".', 43, '2000-11-14');

Crossover: Después de este episodio, Drusilla visita Sunnydale durante "Spike Enamorado".', 41, '2001-01-16');

Crossover: Después de este episodio, Angel visita momentaneamente Sunnydale durante "Para siempre" por el funeral de Joyce Summers', 43, '2001-02-27');

Crossover: Harmony dejó Sunnydale después de "Spike Enamorado". Durante este capítulo, Cordelia llama a Willow para obtener información sobre Harmony.', 42, '2001-04-17');

Crossover: Al final del episodio Willow telefonea para comunicar a los chicos que Buffy ha resucitado.', 40, '2001-10-15');

Crossover: Angel menciona a Cordelia que antes ya estuvo poseído por espíritus de antiguos amantes, esto ocurrió en el Buffy capítulo 2x19 I only have eyes for you cuando era Angelus y estaba atormentando a Buffy, los poseyó una pareja de antiguos amantes trágicos', 43, '2002-02-04');

Crossover:Angel menciona que nunca nieva en baja california, Cordelia le dice que "lo hizo una vez" en referencia a la vez que nevó y se salvó la vida de Angel en el capítulo Enmiendas.', 41, '2002-04-29');

UPDATE Contenido SET id_tmdb = 1907, descripcion = 'Richard es un joven mochilero que llega a Tailandia en busca de experiencias. Allí conoce a una pareja francesa y a Daffy, un trotamundos colgado por años de viajes y drogas que le habla de un paraíso escondido: una playa no tocada todavía por el turismo. Una noche, Richard encuentra en la puerta de su habitación un mapa para llegar a ese paraíso .Richard emprende el camino acompañado de sus amigos franceses y a pesar de los peligros consigue llegar.', trailer_url = 'https://www.youtube.com/watch?v=fngZ6_fT61A' WHERE id_api = 'tt0163978';

UPDATE Contenido SET id_tmdb = 8649, descripcion = 'Frank Pierce es un paramédico que trabaja en el turno de noche en Nueva York. Frank está al borde del colapso, debido al estrés, la falta de sueño y la culpa por no poder salvar a sus pacientes. Frank tiene que lidiar con compañeros excéntricos, enfermeras hostiles, drogadictos, pandilleros y fantasmas de los muertos que le atormentan. Su única esperanza es Mary Burke , la hija de un hombre al que intentó reanimar. Frank se siente atraído por ella y trata de ayudarla a superar su adicción. Frank tendrá que enfrentarse a sus propios demonios y encontrar un sentido a su vida.', trailer_url = 'https://www.youtube.com/watch?v=IgKYObChgfI' WHERE id_api = 'tt0163988';

UPDATE Contenido SET id_tmdb = 9383, descripcion = 'El descubrimiento de un brillante científico lo hace invisible, pero lo transforma en un omnipotente y peligroso megalómano.', trailer_url = 'https://www.youtube.com/watch?v=PksGHTBW1uE' WHERE id_api = 'tt0164052';

UPDATE Contenido SET id_tmdb = 4614, descripcion = 'En 1973, el ejército de Israel perdió un caza con un misil nuclear, abatido por fuerzas enemigas. No se volvió a saber del misil. 29 años después, un viejo árabe lo encuentra semienterrado y abandonado en el Golán, y se lo vende a un mercenario con conexiones con unos potentados neonazis. Al mismo tiempo, en Rusia, se produce un nuevo cambio de presidente, y el nuevo mandatario, apenas conocido, no despierta plena confianza para la CIA... Nueva y trepidante aventura del agente de la CIA Jack Ryan (interpretado ahora por Ben Affleck y al que anteriormente habían dado vida Alec Baldwin y Harrison Ford). La película tuvo su polémica al tratar el tema del terrorismo de forma apocalíptica cuando todavía estaba reciente el recuerdo del 11-S. Además, en la novela de Tom Clancy los terroristas eran fanáticos musulmanes, pero los productores decidieron "sustituirlos" por terroristas neonazis en la adaptación cinematográfica.', trailer_url = 'https://www.youtube.com/watch?v=52zGYHEpHns' WHERE id_api = 'tt0164184';

UPDATE Contenido SET id_tmdb = 2043, descripcion = 'Morgan Freeman vuelve a interpretar el personaje de Alex Cross, que ya había recreado en ''El coleccionista de amantes'', un detective de policía, psicólogo y novelista de éxito del distrito central de Washington que ha renunciado a seguir practicando juegos mentales con los criminales... hasta que un metódico depredador, Gary Soneji, comete un atrevido secuestro y provoca que Cross se involucre dejando una prueba del caso en su buzón de correo. Soneji no busca ningún tipo de rescate, sino algo mucho más importante: un lugar en los libros de historia, quiere que Cross escriba sobre él después de haber cometido el crimen del siglo. Soneji planifica cada uno de sus movimientos como una araña que tiende su red. Y tanto Cross como la agente del servicio secreto Jezzie Flannigan emprenden una carrera contrarreloj para tratar de detenerle.', trailer_url = 'https://www.youtube.com/watch?v=kswRbwYqn3k' WHERE id_api = 'tt0164334';

UPDATE Contenido SET id_tmdb = 2085, descripcion = 'Dos bandas (Asiática y afroamericana) enzarzadas en una "guerra de mafias" están disputándose el control de los muelles. La situación se vuelve aún más peligrosa cuando el hijo del capo asiático es asesinado; es entonces cuando su hermano Han, ex policía encarcelado en Hong Kong, escapa de la cárcel para vengar su muerte, convirtiéndose él en objetivo de las bandas, lo que le lleva a declarar la guerra por su cuenta.', trailer_url = 'https://www.youtube.com/watch?v=4R7O2A8R63A' WHERE id_api = 'tt0165929';

UPDATE Contenido SET id_tmdb = 10137, descripcion = 'Un día la familia Little adopta a Stuart, un pequeño ratón al que tratan como si fuera un hijo. Los Little están encantados con la manera de ser de Stuart, pero George, su hijo mayor, no sabe qué hacer con su "nuevo hermano". Por su parte, Snowbell, el gato de la familia, urde un plan para echar a Stuart de casa para siempre.', trailer_url = 'https://www.youtube.com/watch?v=Wlo-sYrADlw' WHERE id_api = 'tt0164912';

UPDATE Contenido SET id_tmdb = 4816, descripcion = '"Ghost Dog" (Whitaker) es un asesino a sueldo de Nueva York, un hombre de actitud tranquila en su vida diaria que se rige bajo el código de honor de los antiguos samuráis.', trailer_url = 'https://www.youtube.com/watch?v=tYVQHKsCY3c' WHERE id_api = 'tt0165798';

UPDATE Contenido SET id_tmdb = 61018, descripcion = 'The show where everything''s made up and the points don''t matter. Not a talk show, not a sitcom, not a game show, Whose Line Is It Anyway? is a completely unique concept to network television. Four talented actors perform completely unrehearsed skits and games in front of a studio audience. Host Drew Carey sets the scene, with contributions from the audience, but the actors rely completely on their quick wit and improvisational skills. It''s genuinely improvised, so anything can happen - and often does.', trailer_url = NULL WHERE id_api = 'tt0163507';

UPDATE Contenido SET id_tmdb = 404, descripcion = 'Alvin Straight (Richard Farnsworth) es un achacoso anciano que vive en Iowa con una hija discapacitada (Sissy Spacek). Además de sufrir un enfisema y pérdida de visión, tiene graves problemas de cadera que casi le impiden permanecer de pie. Cuando recibe la noticia de que su hermano Lyle (Stanton), con el que está enemistado desde hace diez años, ha sufrido un infarto, a pesar de su precario estado de salud, decide ir a verlo a Wisconsin. Para ello tendrá que recorrer unos 500 kilometros, y lo hace en el único medio de transporte del que dispone: una máquina cortacésped.', trailer_url = 'https://www.youtube.com/watch?v=XVUoVTbfJj8' WHERE id_api = 'tt0166896';

UPDATE Contenido SET id_tmdb = 4238, descripcion = 'Ambientada en un barrio residencial de clase obrera en Queens, Nueva York, esta serie nos muestra la vida de Doug Heffernan, un amable repartidor, y su esposa, la temperamental secretaria Carrie Heffernan, y como afrontan los retos que cada día le supone a ambos su amor, su familia y sobre todo su matrimonio.', trailer_url = 'https://www.youtube.com/watch?v=kDfhZTKu5XE' WHERE id_api = 'tt0165581';

UPDATE Contenido SET id_tmdb = 14411, descripcion = 'Simbad, el aventurero más osado y famoso que cruzó los siete mares, tiene que afrontar el peligro más grande de su vida. Acusado de robar el Libro de la Paz, uno de los tesoros más valiosos del mundo, tendría que encontrarlo para salvar a Proteus, su mejor amigo. Será Marina, la prometida de Proteus, quien convenza a Simbad de que tiene el deber de cumplir esa misión. Eris, la diosa del caos, trata de impedírselo arrojando contra él la furia de los elementos y una legión de criaturas monstruosas. (FILMAFFINITY)', trailer_url = 'https://www.youtube.com/watch?v=bRsdyOck9IY' WHERE id_api = 'tt0165982';

UPDATE Contenido SET id_tmdb = 9023, descripcion = 'Sigue las aventuras de un corcel mustang salvaje e ingobernable que recorre la indómita frontera norteamericana. Cuando encuentra a un hombre por primera vez, un joven de la tribu de los Lakota llamado Little Creek, Spirit se niega a dejarse domar por él pero sí se hace amigo suyo. El valiente corcel también encuentra el amor con una hermosa yegua llamada Rain. Spirit se conviertirá en uno de los grandes héroes anónimos del Viejo Oeste.', trailer_url = 'https://www.youtube.com/watch?v=RPJ4EQ2Eh9I' WHERE id_api = 'tt0166813';

UPDATE Contenido SET id_tmdb = 1018, descripcion = 'Betty, una joven aspirante a actriz, llega a Los Ángeles para convertirse en estrella de cine y se aloja en el apartamento de su tía. Allí conoce a Rita, una mujer que padece amnesia a causa de un accidente en Mulholland Drive. Las dos juntas deciden investigar quién es Rita y cómo llegó hasta allí.', trailer_url = 'https://www.youtube.com/watch?v=iDSsG6bephI' WHERE id_api = 'tt0166924';

UPDATE Contenido SET id_tmdb = 16, descripcion = 'La película se desarrolla en Estados Unidos en el año 1964. Selma (Björk) es una inmigrante checa que se muda a aquel país con su hijo Gene. Además padece una enfermedad hereditaria degenerativa que le está ocasionando una rápida ceguera progresiva. Por este motivo Selma ahorra centavo a centavo en una lata que guarda en su cocina para pagar una operación que evite que su hijo sufra el mismo destino.', trailer_url = 'https://www.youtube.com/watch?v=RhSjevRpWLo' WHERE id_api = 'tt0168629';

UPDATE Contenido SET id_tmdb = 122, descripcion = 'Las fuerzas de Saruman han sido destruidas, y su fortaleza sitiada. Ha llegado el momento de que se decida el destino de la Tierra Media, y por primera vez en mucho tiempo, parece que hay una pequeña esperanza. La atención del señor oscuro Sauron se centra ahora en Gondor, el último reducto de los hombres, y del cual Aragorn tendrá que reclamar el trono para ocupar su puesto de rey. Pero las fuerzas de Sauron ya se preparan para lanzar el último y definitivo ataque contra el reino de Gondor, la batalla que decidirá el destino de todos. Mientras tanto, Frodo y Sam continuan su camino hacia Mordor, a la espera de que Sauron no repare en que dos pequeños Hobbits se acercan cada día más al final de su camino, el Monte del Destino.', trailer_url = 'https://www.youtube.com/watch?v=h-9RYiqyqjk' WHERE id_api = 'tt0167260';

UPDATE Contenido SET id_tmdb = 1487, descripcion = 'Nacido de las llamas del infierno hace sesenta años durante la Segunda Guerra Mundial, Hellboy (Ron Perlman) fue enviado a la Tierra por el loco diabólico Grigori Rasputín (Karel Roden) para hacer el mal. Destinado a ser un presagio del Apocalipsis, Hellboy fue rescatado por las Fuerzas Aliadas lideradas por el profesor Broom (John Hurt), fundador del clandestino I.I.P.D. (Instituto para la Investigación Paranormal y de Defensa), que lo crió como un hijo y desarrolló sus extraordinarios poderes paranormales. A pesar de sus oscuros orígenes, Hellboy se convierte en un extraño héroe del bien, que lucha contra las fuerzas del mal que amenazan nuestro mundo.', trailer_url = 'https://www.youtube.com/watch?v=qc4-3QmiFak' WHERE id_api = 'tt0167190';

UPDATE Contenido SET id_tmdb = 52, descripcion = '¿Qué es lo más interesante de vivir el día a día? Para Eric Forman, su novia Donna y sus amigos Jackie, Kelso, Hyde y Fez, todo es importante. Este grupo de chicos que vive en los años 70 tienen una rutina muy divertida: escuchar y bailar música disco, vestirse con jeans de bota campana y ropa muy colorida, además de tener sexo “sin culpa” y pasar tiempo en el sótano de Eric fumando marihuana, con grandes dosis de humor, sarcasmo y acidez.', trailer_url = 'https://www.youtube.com/watch?v=b1za7d3KvHw' WHERE id_api = 'tt0165598';

UPDATE Contenido SET id_tmdb = 121, descripcion = 'La Compañía del Anillo se ha disuelto. El portador del anillo Frodo y su fiel amigo Sam se dirigen hacia Mordor para destruir el Anillo Único y acabar con el poder de Sauron. Mientras, y tras la dura batalla contra los orcos donde cayó Boromir, el hombre Aragorn, el elfo Legolas y el enano Gimli intentan rescatar a los medianos Merry y Pipin, secuestrados por los ogros de Mordor. Por su parte, Saurón y el traidor Sarumán continúan con sus planes en Mordor, en espera de la guerra contra las razas libres de la Tierra Media.', trailer_url = 'https://www.youtube.com/watch?v=h-9RYiqyqjk' WHERE id_api = 'tt0167261';

UPDATE Contenido SET id_tmdb = 8871, descripcion = 'Cada año, en Navidad, los lugareños perturban su pacífica soledad con celebraciones cada vez más desmesuradas, luminosas y ruidosas. Cuando los Quién declaran que ese año van a preparar una Navidad el triple de grande, el Grinch se da cuenta de que solo hay un modo de recuperar algo de paz y silencio: robar la Navidad. Para ello, decide hacerse pasar por Santa Claus en Nochebuena, haciéndose con un reno muy peculiar para tirar de su trineo. Mientras tanto, en Villa Quién, una dulce niña llamada Cindy-Lou, desbordante de espíritu navideño, planea con sus amigos atrapar a Papá Noel durante su visita en Nochebuena para darle las gracias por ayudar a su trabajadora madre. Sin embargo, a medida que se acerca la noche mágica, sus buenas intenciones amenazan con chocar con las del Grinch, mucho más perversas.', trailer_url = 'https://www.youtube.com/watch?v=SL0YugjtkiI' WHERE id_api = 'tt0170016';

UPDATE Contenido SET id_tmdb = 18491, descripcion = 'Seele ordena un ataque sin cuartel contra NERV con el objetivo de destruir los Evas antes de que Gendo pueda provocar el Tercer Impacto y la unión de las almas humanas.', trailer_url = 'https://www.youtube.com/watch?v=v1pWyWIu8x4' WHERE id_api = 'tt0169858';

UPDATE Contenido SET id_tmdb = 745, descripcion = 'El Dr. Malcom Crowe es un conocido psicólogo infantil obsesionado con el doloroso recuerdo de un joven paciente desequilibrado al que fue incapaz de ayudar. Cole Sear es un aterrorizado y confuso niño de ocho años que necesita tratamiento, y Crowe ve la oportunidad de redimirse haciendo todo lo posible por ayudarle. Sin embargo, el psicólogo infantil no está preparado para conocer la terrible verdad acerca del don sobrenatural de su paciente: recibe visitas no deseadas de espíritus atormentados.', trailer_url = 'https://www.youtube.com/watch?v=HXG4HTIlc1U' WHERE id_api = 'tt0167404';

UPDATE Contenido SET id_tmdb = 14, descripcion = 'Divertida, inquietante y sorprendente incursión en la América suburbana a través de las vidas de Lester y Carolyn, una pareja perteneciente a la clase medio-alta cuyo matrimonio -y cuyas vidas- lentamente se deshacen. Carolyn odia a su marido, su hija lo desprecia y su jefe está a punto de despedirlo. Así que Lester decide cambiar algunas cosas en su vida; a medida que va siendo más libre, consigue ser más feliz, lo que enfurece más a su esposa y a su hija.', trailer_url = 'https://www.youtube.com/watch?v=CQH51MGFwpY' WHERE id_api = 'tt0169547';

UPDATE Contenido SET id_tmdb = 19666, descripcion = 'Durante la ocupación inglesa de la India, los habitantes de una pequeña aldea se resisten a pagar el impuesto que los oficiales británicos han doblado. Ante las protestas deciden resolver el conflicto jugando un partido de cricket: si ganan los campesinos, se les exonerará de las tasas.', trailer_url = 'https://www.youtube.com/watch?v=rZPbpymefuE' WHERE id_api = 'tt0169102';

UPDATE Contenido SET id_tmdb = 11618, descripcion = 'Desde que fuera construida hace 130 años, la Casa de La Colina, un edificio tan gótico como tenebroso, se levanta solitaria y rodeada de múltiples leyendas y rumores que hablan sobre muertes trágicas. Intrigado por el pasado de la mansión el Dr. David Marlow forma un equipo con otras tres personas: Theo, una exuberante bisexual, Nell, mujer sensible que acaba de escapar del control familiar, y Luke Sannerson, el cínico del grupo, para ir a la deshabitada casa y realizar un estudio sobre la naturaleza del miedo. Y la casa se encargará de despertar el miedo de sus inquilinos.', trailer_url = 'https://www.youtube.com/watch?v=dt3NUUcsUnQ' WHERE id_api = 'tt0171363';

UPDATE Contenido SET id_tmdb = 10687, descripcion = '1971. Estados Unidos. El país permanece dividido por la escalada de la guerra en Vietnam. Miles de jóvenes norteamericanos yacen muertos en suelo extranjero. Y en Fort Polk, Luisiana, miles más se preparan para correr su misma suerte. La sombra del combate pende sobre los hombres de la Compañía A, Segundo Pelotón en la medida que encaran la recta final de su período de entrenamiento en la infantería. Van a ser enviados a la guerra. Pero cada uno de ellos afronta su inminente destino de una manera distinta.', trailer_url = 'https://www.youtube.com/watch?v=LABt1rwmIgg' WHERE id_api = 'tt0170691';

UPDATE Contenido SET id_tmdb = 4967, descripcion = 'Grandes amigos desde niños, el rabino Jacob Schram  y el padre Brian Finn  son hombres dinámicos y populares que viven y trabajan en la zona Oeste de Nueva York. Cuando Anna Reilly , una vieja amiga de la infancia, regresa a la ciudad convertida en una bella ejecutiva, saltan chispas y comienza un triángulo inusual y complicado.', trailer_url = 'https://www.youtube.com/watch?v=wORkOt7MOHM' WHERE id_api = 'tt0171433';

UPDATE Contenido SET id_tmdb = 226, descripcion = 'Teena Brandon siempre ha deseado ser un chico. Así que un día decide cortarse el pelo, ocultar sus pechos bajo un vendaje apretado, y cambiar el orden de su nombre, pasándose a llamar Brandon Teena. (FILMAFFINITY)', trailer_url = 'https://www.youtube.com/watch?v=uxWt9rxNzjg' WHERE id_api = 'tt0171804';

UPDATE Contenido SET id_tmdb = 3558, descripcion = 'Año 1967. Susanna Kaysen, de 17 años, es como la mayoría de las chicas americanas de su edad: está confusa, se siente insegura y lucha por entender el mundo que la rodea. Su psiquiatra decide ingresarla en el Hospital Claymoore, diagnosticándole un trastorno de la personalidad, que se manifiesta a través de una gran inseguridad respecto a la propia imagen, a los objetivos a largo plazo y a los amigos. En el centro Susanna conoce a Lisa, Georgina, Polly y Janet, un grupo de chicas inadaptadas con las que entabla una estrecha amistad y que, además, le muestran el camino para encontrarse a sí misma.', trailer_url = 'https://www.youtube.com/watch?v=Km2ucMbVyX8' WHERE id_api = 'tt0172493';

UPDATE Contenido SET id_tmdb = 8961, descripcion = 'Los detectives de narcóticos Mike Lowrey y Marcus Burnett han sido asignados a un nuevo caso en Miami, donde un astuto narcotraficante ha iniciado una sangrienta guerra. Además la amistad de los dos agentes se complica cuando Mike empieza a sentir algo por la hermana de Marcus...', trailer_url = 'https://www.youtube.com/watch?v=MsGSpfK6H4A' WHERE id_api = 'tt0172156';

UPDATE Contenido SET id_tmdb = 98, descripcion = 'En el año 180, el Imperio Romano domina todo el mundo conocido. Tras una gran victoria sobre los bárbaros del norte, el anciano emperador Marco Aurelio decide transferir el poder a Máximo, bravo general de sus ejércitos y hombre de inquebrantable lealtad al imperio. Pero su hijo Cómodo, que aspiraba al trono, no lo acepta y trata de asesinar a Máximo.', trailer_url = 'https://www.youtube.com/watch?v=W3xjHIdaGww' WHERE id_api = 'tt0172495';

UPDATE Contenido SET id_tmdb = 2114, descripcion = 'Corre el año 2070 y la tierra ha sido devastada por una invasión alienígena. En los ojos de una joven se refleja tristeza y desolación, mientras mira fijamente a la desértica tierra a su alrededor, y la luz del sol, demasiado brillante, le dificulta la visión. Está sola, entre nubes de polvo, en un amenazador mundo de extraterrestres y sus ojos revelan un conflicto interno. Times Square se desmorona en la oscuridad, quemado casi hasta desaparecer, pero en alguna parte grandes ejércitos retienen al ejército extraterrestre. Mientras la muerte acecha entre las sombras, ella busca el milagro, creyendo en que los valores humanos como el valor, la dedicación y el amor podrán finalmente salvar al planeta Tierra...', trailer_url = 'https://www.youtube.com/watch?v=X4GcSEbC4F0' WHERE id_api = 'tt0173840';

UPDATE Contenido SET id_tmdb = 11854, descripcion = 'Rahul y Anjali son los mejores amigos hasta que se encuentran en un triángulo romántico, una vez llega Tina. Rahul y Tina se casan y tienen una hija, que Tina nombra Anjalí, pero Tina muere en el parto. Anjalí, la hija de Rahul, recibe una serie de cartas escritas por su madre antes de su muerte y la última letra describe su nombre. La pequeña Anjalí intentará volver a unir a su padre de vuelta con su antigua mejor amiga de la universidad, Anjalí.', trailer_url = 'https://www.youtube.com/watch?v=IR5ReWgs-iQ' WHERE id_api = 'tt0172684';

UPDATE Contenido SET id_tmdb = 10400, descripcion = 'Basada en hechos reales. Rubin "Huracán" Carter era un boxeador negro que se sobrepuso a su problemática juventud y se convirtió en aspirante al título de los pesos medios. Sin embargo, sus sueños se vinieron abajo cuando, en junio de 1966, fue injustamente acusado de un triple asesinato ocurrido en un bar de Nueva Jersey. Condenado en un juicio lleno de errores, Carter fue condenado a tres cadenas perpetuas.', trailer_url = 'https://www.youtube.com/watch?v=GxtcUmaTHMY' WHERE id_api = 'tt0174856';

UPDATE Contenido SET id_tmdb = 4247, descripcion = 'Tras el asesinato de una bella estudiante, un grupo de adolescentes descubren que hay un asesino entre ellas. La heroína, Cindy, y su grupo de desconcertantes amigos, serán aterrorizados por un singular psicópata enmascarado que pretende vengarse de ellos por haberlo atropellado el pasado Halloween.', trailer_url = 'https://www.youtube.com/watch?v=3iy0pE1FBkc' WHERE id_api = 'tt0175142';

UPDATE Contenido SET id_tmdb = 334, descripcion = 'La película consta de nueve tramas paralelas que tienen lugar en el Valle de San Fernando, en Los Angeles: un niño prodigio, el presentador de un concurso de televisión, un ex-niño prodigio, un moribundo, su hijo perdido, la mujer y el enfermero del moribundo. Son historias aparentemente independientes, pero que guardan entre sí una extraña relación. Magnolia es el retrato de la vida americana visto a través de una serie de viñetas cómicas y conmovedoras.', trailer_url = 'https://www.youtube.com/watch?v=cxcegktcxSM' WHERE id_api = 'tt0175880';

UPDATE Contenido SET id_tmdb = 926, descripcion = 'Galaxy Quest es el título de una serie de televisión que se ha emitido con gran éxito durante treinta años. Una vez que deja de emitirse, sus protagonistas se dedican a pasear sus antiguos uniformes por convenciones y programas especiales. Lo que no saben es que una raza alienígena del espacio exterior, los Thermians, captaban la serie creyendo que se trataba de un documento histórico. En su lucha contra el perverso Roth''h''ar Sarris, deciden secuestrar a los protagonistas para que les ayuden a combatirlo.', trailer_url = 'https://www.youtube.com/watch?v=Szmskr-DLFM' WHERE id_api = 'tt0177789';

UPDATE Contenido SET id_tmdb = 607, descripcion = 'El profesor Utonium es un ingeniero genético que siempre está experimentando. Una noche decide hacer realidad su sueño más anhelado: crear una niña perfecta. El resultado es espectacular: en vez de una niña ha creado a tres superheroínas.', trailer_url = 'https://www.youtube.com/watch?v=dBJWgpsLHCo' WHERE id_api = 'tt0175058';

UPDATE Contenido SET id_tmdb = 2133, descripcion = 'Gloucester (Massachussetts), octubre de 1991. El Andrea Gail es un barco de pesca capitaneado por Billy Tyne, un veterano pescador cuyas últimas salidas se han saldado con paupérrimas capturas. Buscando un golpe de suerte que haga cambiar esta mala racha, se interna en el Flemish Cap, un lugar más allá de las zonas frecuentadas por los pescadores. Lo que ignora es que, a la zona donde faena, se está aproximando la tormenta más aterradora, violenta y destructiva que se pueda concebir.', trailer_url = 'https://www.youtube.com/watch?v=sK5ejT_V9to' WHERE id_api = 'tt0177971';

UPDATE Contenido SET id_tmdb = 2671, descripcion = 'En una pequeña y apacible localidad japonesa, entre los estudiantes circula una leyenda en torno a unos videos malditos cuya visión provoca la muerte. Tras la muerte de su sobrina, una periodista investigará el origen de dichos videos.', trailer_url = 'https://www.youtube.com/watch?v=RHEoAPrnt2g' WHERE id_api = 'tt0178868';

UPDATE Contenido SET id_tmdb = 641, descripcion = 'Harry (Jared Leto) vive con su atormentada madre Sara (Ellen Burstyn), y mientras él sueña con una vida mejor, ella está permanentemente a dieta para el día que pueda cumplir su mayor ilusión; aparecer en su concurso televisivo preferido. La ambición de Harry y su novia Marion (Jennifer Connelly) es hacerse ricos vendiendo droga con su amigo Tyrone (Marlon Wayans), y utilizar las ganancias para abrir un negocio propio, pero nunca llega el dinero suficiente para iniciar su plan. A pesas de todo, Harry y Marion no se resignan a vivir una existencia que consideran despreciable, por lo que harán lo impensable para conseguir la vida que anhelan.', trailer_url = 'https://www.youtube.com/watch?v=NEKjZSTo0Uk' WHERE id_api = 'tt0180093';

UPDATE Contenido SET id_tmdb = 20770, descripcion = 'Megan Bloomfield es animadora en su colegio, tiene amigas animadoras y es novia del capitán del equipo de fútbol. Es vegetariana, no le gustan los besos de su novio y abraza cuando puede a sus amigas. Un día sus amigos/as, su novio y sus padres le tienen una trampa para enviarla a un campamento en el que curan la homosexualidad. Megan tiene que pasar varias pruebas, incluyendo la primera que es darse cuenta de que es lesbiana.', trailer_url = 'https://www.youtube.com/watch?v=HnUvneNxoz8' WHERE id_api = 'tt0179116';

UPDATE Contenido SET id_tmdb = 2749, descripcion = 'Oleg y Emil, dos criminales europeos, llegan a Nueva York para hacer fortuna. El detective de homicidios Flemming y el bombero Warsaw intentarán pararles los pies, pero se toparán con unos medios de comunicación que han hecho de los delincuentes héroes populares....', trailer_url = 'https://www.youtube.com/watch?v=nWdh_-ZItS4' WHERE id_api = 'tt0179626';

UPDATE Contenido SET id_tmdb = 10876, descripcion = 'Francia siglo XVIII. El Marqués de Sade pasa los diez últimos años de su vida en el asilo Charenton. Allí entabla amistad con el abate Coulmier, con el que comparte el afecto de Madeleine, la lavandera del asilo. Cuando Napoleón envía a un médico para que cure su presunta locura, el temperamento rebelde del marqués se agudiza todavía más. Obtuvo tres nominaciones a los Oscar, incluyendo el de mejor actor (Geoffrey Rush).', trailer_url = 'https://www.youtube.com/watch?v=u--PYnIYewE' WHERE id_api = 'tt0180073';

UPDATE Contenido SET id_tmdb = 180, descripcion = 'Washington DC, año 2054. La policía utiliza tecnología psíquica para arrestar y enjuiciar a los asesinos antes de que cometan un crimen. El futuro se puede predecir y los culpables son detenidos por la unidad de élite Precrime antes de que puedan delinquir. Las pruebas se basan en los "precogs", tres seres psíquicos cuyas visiones sobre los asesinatos nunca han fallado.', trailer_url = 'https://www.youtube.com/watch?v=3JNsNp2DVSE' WHERE id_api = 'tt0181689';

UPDATE Contenido SET id_tmdb = 11001, descripcion = 'Miles acaba de robar un valioso diamante. Poco antes de ser atrapado por la policía consigue esconder el botín. Tras pasar dos años entre rejas se dispone a recuperar la joya, pero ahora el lugar donde ocultó el diamante se ha convertido en una comisaría de policía. Su plan no podía ser otro que el de hacerse pasar por policía para recuperar tan preciada joya.', trailer_url = 'https://www.youtube.com/watch?v=zxfFGW00EB0' WHERE id_api = 'tt0181316';

UPDATE Contenido SET id_tmdb = 711, descripcion = 'Conocido en su barrio por su condición de huraño solitario,... Forrester es un hombre cuyo misterio y excentricidad son casi míticos. Cuando Jamal, un destacado estudiante negro, logra colarse en su apartamento con una cartera repleta de trabajos literarios, de manera inesperada e insólita, se establece entre ellos una relación altamente provechosa.', trailer_url = 'https://www.youtube.com/watch?v=8QGCBH_2Dck' WHERE id_api = 'tt0181536';

UPDATE Contenido SET id_tmdb = 60572, descripcion = 'La serie narra las aventuras del joven entrenador Pokemon de diez años Ash Ketchum, que decide comenzar su aventura para llegar a convertirse un día en un gran Maestro de Pokemon. Para ello deberá recorrer distintas regiones, capturar cuantos más pokemon pueda, y conseguir las medallas de gimnasio necesarias y así participar en la Liga Pokemon, ganarla y así estar un paso más cerca de convertirse en Maestro Pokemon. Para ello cuenta con la ayuda de Pikachu, su primer pokemon, que obtuvo de manos del Profesor Oak. En su recorrido conocerá y hará nuevos amigos, como Brock o Misty, que le acompañarán y ayudarán para conseguir alcanzar su sueño.', trailer_url = 'https://www.youtube.com/watch?v=kfgfQPA6oPI' WHERE id_api = 'tt0168366';

Luego mientras caminan se percatan de que ninguno sabe en donde esta el laboratorio de la Profesora Ivy, Pikachu observa un Centro Pokémon y todos de dirigen a él. Al entrar una Enfermera Joy los recibe y Brock se enamora de ella, después Ash le pregunta si sabe donde esta el laboratorio de la profesora Ivy.', 23, '1999-02-11');

Él les habla de la noticia sobre un trofeo de la Liga Naranja de hace más de 300 años que unos buzos encontraron en un barco hundido en las costas de la isla y que estaría siendo exhibida en el museo de artes de la Isla Moro, nuestros héroes se emocionan por ir a verlo.', 23, '1999-05-06');

En eso se topan con una tormenta eléctrica e intentan refugiarse en una gran roca y cuando estaban a punto de ser alcanzados por un trueno son protegidos por un grupo de Magnemite que absorben los rayos y un Jolteon.', 23, '1999-06-17');
Ash, Pikachu y sus amigos caen por otro agujero y llegan hasta la alcantarilla de la ciudad. Cuando buscaban la salida Ash oye el sonido de un cascabel y de repente una misteriosa criatura toca a Ash y cuando este saca a Bulbasaur la criatura se lo lleva con ella debajo del agua. En eso aparece la Oficial Jenny que saca a nuestros héroes de la alcantarilla.', 23, '1999-06-24');

Al amanecer, el huevo brilla más y nace un Phanpy.', 23, '2001-12-27');

Cuando los chicos tratan de devolverle a Larvitar, Tyranitar piensa que ellos fueron los que lo robaron, por lo que se pone a usar Hiperrayo.', 23, '2002-09-05');

La Anciana da una cálida bienvenida a Iris y, tras un rápido examen, declara que ha cuidado muy bien de Axew. Otros aldeanos quieren ver el resto de los Pokémon de Iris y ella pide a Dragonite que salga. Todo el mundo lanza exclamaciones ante su impresionante captura, hasta que Dragonite empieza a pelear contra un Haxorus cercano. Pero, para su sorpresa, unas cuantas palabras suaves de la Anciana los calman a los dos.', 23, '2012-10-25');

El Froakie y el Hawlucha de Ash forman equipo, contra los Pokémon de Lem, pero sus estilos de combate son tan distintos que la cosa no funciona. Ash trata de enseñarles a combinar sus ataques en un solo movimiento, al que llama Supercorte Volador, pero, de repente, Ash es arrastrado al interior del bosque por un fantasmal Pokémon llamado Trevenant.  Hawlucha y Froakie forman equipo para rescatar a Ash, quien, una vez que Trevenant le ha soltado, se entera de la razón por la que le ha secuestrado. El Team Rocket ha atrapado a dos Pokémon amigos de Trevenant en una red electrificada y necesita la ayuda de Ash para rescatarlos.', 23, '2014-08-07');

El Team Rocket está acechando cerca, y Jessie decide que tiene que hacerse con Smoochum, que es de Nini, para que la acompañe a ella en el Gran Espectáculo Pokémon. Se disfraza como coreógrafa y encierra a todos los Pokémon danzarines en un espacio pequeño para su actuación. Y, entonces, el globo del Team Rocket despega con ellos. Chespin y Pancham por fin deciden trabajar juntos y descubren que son un equipo bastante bueno, mientras envían a los villanos a despegar de nuevo.', 23, '2014-11-13');

Clem tiene una idea mejor, sugiere que el Hawlucha de Ash le sustituya en el papel del reluciente héroe. Hawlucha tiene algunos problemas con la idea de un combate simulado, pero el espectáculo debe continuar. Cuando se alza el telón, el Team Rocket intenta ser el protagonista, ante lo cual, Hawlucha y Hawlucha Oscuro se unen para hacer que despeguen de nuevo, para más tarde enfrentarse los dos en un reñido combate por Lady Snubbull. La función Supercombate Pokémon resulta ser un enorme éxito.', 23, '2014-11-20');

Mientras Lem y Clem se quedan arriba con Eddy, Ash y Serena se unen a Lindsey en un submarino y bucean hacia el lecho oceánico donde, por supuesto, están los restos de El Titanus y, gracias a unos hábiles Dragalge que han fusionado el barco con Ácido, se ha convertido en un hogar para muchas clases distintas de Pokémon de tipo Agua.', 23, '2014-11-27');

Ash y sus amigos deciden ayudar a Sanpei en su misión, pero, en un momento dado, Ash y Sanpei se separan del resto, justo en el momento en que el ninja enmascarado ataca de nuevo. Froakie y Greninja se unen para contraatacar y, cuando parece que el combate se ha vuelto contra ellos, Froakie evoluciona a Frogadier.', 23, '2014-12-11');

Ash y sus amigos deciden ayudar a Sanpei en su misión, pero, en un momento dado, Ash y Sanpei se separan del resto, justo en el momento en que el ninja enmascarado ataca de nuevo. Froakie y Greninja se unen para contraatacar y, cuando parece que el combate se ha vuelto contra ellos, Froakie evoluciona a Frogadier.', 23, '2014-12-18');

Mientras Jessie, James y Meowth celebran su última captura, los dos Pokémon trabajan juntos, combinando la fuerza de Pikachu y la baba de Goomy, para escapar de la jaula y huir. Cuando se reúnen con Ash y los demás, el Team Rocket les pisa los talones.

Los villanos parecen tener ventaja hasta que Goomy se coloca delante de sus nuevos amigos y usa Venganza, absorbiendo los ataques del Team Rocket y luego haciéndoles despegar gracias a su poder. Ash admira la inesperada fuerza de Goomy, y el pequeño de tipo Dragón se une a él muy contento en el viaje hacia Ciudad Témpera', 23, '2015-01-08');

Dedenne sigue el rastro de babas de Goomy hasta un túnel de rocas y descubre al pequeño de tipo Dragón enfrentado al Team Rocket al otro lado. Dedenne, enseguida, entra en combate protegiendo a Goomy hasta que ya no puede resistir más, y, entonces, Goomy encuentra el coraje y se alza en defensa de Dedenne. Justo cuando parece que los dos pequeños están a punto de caer en manos de los villanos, aparecen nuestros héroes y envían al Team Rocket a despegar de nuevo. La nueva amistad entre Dedenne y Goomy es motivo de celebración, y el viaje continúa.', 23, '2015-01-15');

Resulta que Vanillite tiene amigos poderosos y, cuando Vanillish y Vanilluxe llegan buscando a su compañero perdido, entierran a la ciudad entera bajo una gigantesca tormenta de nieve. Amaro dirige todo un ejército de Sunflora que tiene bajo su cuidado para detener la tormenta y, con su ayuda, nuestros héroes envían al Team Rocket a despegar de nuevo y reúnen a los tres gélidos Pokémon.

La Enfermera Joy agradece su ayuda a Amaro, y Lem por fin se da cuenta de quién es. Este Entrenador que puede dirigir un campo entero de Pokémon de tipo Planta es el próximo oponente de Ash, el Líder de Gimnasio de Ciudad Témpera.', 23, '2015-01-22');

Finalmente, Ash saca a Frogadier, que es de tipo Agua y no parece ser el rival del tipo adecuado. Pero resulta que Ash tiene un plan. Le indica a Frogadier que use sus Frurbujas como una mascarilla protectora para no inhalar el veneno. Weepinbell es derrotado, y Amaro saca a su leal Gogoat, que usa Hoja Afilada como táctica evasiva, algo que Ash jamás había visto. Ash hace que Frogadier use Doble Equipo y luego lanza Hidropulso mientras Gogoat esta distraído. Funciona, ¡y Ash gana la Medalla Hoja!', 23, '2015-01-29');

Justo cuando comienza el festival, el Team Rocket aparece para robar todos los regalos. Nuestros héroes rápidamente unen sus fuerzas para enviar a los villanos a despegar de nuevo y distribuyen los regalos entre sus legítimos receptores. Resulta que lo que hace más feliz a Ash es la comida y ha recolectado una gran cantidad de bayas para todos sus Pokémon. Serena ha decorado unos monísimos accesorios para que Fennekin y Pancham los luzcan en el escenario.', 23, '2015-02-05');

Xana gana con facilidad en su grupo, derrotando a Jessilee, Jessie del Team Rocket disfrazada. En el grupo de Serena, las cosas parecen ir muy bien, hasta que Fennekin tropieza con su lazo mientras caminan por la pasarela. Esto les imposibilita ganar y observan con tristeza desde bambalinas como Xana realiza una impresionante Actuación de Estilo Libre con sus Bulbasaur y Flabébé, ganando el Gran Espectáculo y su primera Llave Princesa.', 23, '2015-02-12');

Ash y Sabino deciden librar su propio combate, mientras Serena y Clem admiran los glamurosos diseños de Valeria, para más tarde ser reclutadas para unirse al desfile de moda como modelos sustitutas. Nuestros héroes pronto descubren que, al final de cada desfile, Valeria elige un aspirante entre el público para presumir de sus creaciones durante el combate. Esta vez le toca a Sabino.', 23, '2015-05-21');

Con la ayuda de la aguda nariz de Slurpuff, Sabino consigue rastrear su preciada posesión, y Ash y él combaten juntos para enviar al Team Rocket a despegar de nuevo. Luego deciden combatir el uno contra el otro. Ash parece estar totalmente al mando, hasta que el Treecko de Sabino evoluciona a Grovyle y presenta a Frogadier un auténtico desafío.', 23, '2015-06-04');

Jessie y Meowth quieren hacer evolucionar a Noibat enseguida a un poderoso Noivern, pero James investiga un poco y descubre que no es tan fácil. Durante su discusión, los dos Pokémon consiguen escapar a una cueva muy oscura, donde rápidamente vencen a los villanos gracias al sónar de Noibat. Una vez todos reunidos, envían al Team Rocket a despegar de nuevo. Nuestros héroes están preparados para partir otra vez hacia Ciudad Fluxus, y Noibat decide unirse a ellos.', 23, '2015-06-11');

Un anciano caballero llamado Orencio ofrece su experiencia en la Carrera de Relevos en el Cielo y Ash resulta que tiene tres Pokémon Voladores, por lo que acuerdan trabajar juntos. Fletchinder sale el primero y toma la delantera. Luego en el segundo tramo, Hawlucha se encuentra con un agresivo Pelipper que insiste en intentar sacarlo de la carrera y resulta que es un robot dirigido por Meowth.', 23, '2015-06-18');

Tras un encontronazo con Jessie que deja un roto notable en el vestido de Serena, le preocupa que este Gran Espectáculo acabe como el último. Pero viajar con Ash le ha enseñado a no rendirse nunca, así que coge su costurero para hacer unos ajustes de último momento... y termina ganando la Actuación de Estilo Libre y su primera Llave Princesa.', 23, '2015-06-25');

El Rotom de Weston sale de su escondite y revela que su Entrenador fue una vez el dueño, pero Macario le desafió a un combate el día de la inauguración del hotel hace diez años. Cuando el inexperto Rotom Salió huyendo, Macario se declaró a sí mismo ganador del combate y del hotel.', 23, '2015-07-02');

Ash y los demás descubren que Abomasnow está protegiendo a un pequeño Snover enfermo y enseguida Lem los pone a todos a buscar plantas medicinales. Con estos ingredientes, prepara un remedio y rápidamente Snover vuelve a sentirse bien. Tras una pequeña trifulca con el Team Rocket, nuestros héroes parten de nuevo y los Mamoswine los transportan hasta el otro lado de la montaña en dirección a Ciudad Fluxus.', 23, '2015-07-23');

Lem necesita un fusible de repuesto, pero no puede abandonar la caja de los fusibles, que aún echa chispas y los demás aún están trabajando. Por lo que envía a Chespin y a Bunnelby al pueblo con una nota para el dependiente. Por el camino, los dos Pokémon se topan con el Team Rocket, pero justo cuando Ash aparece buscando a Chespin y a Bunnelby, ellos solitos envían a los villanos a despegar de nuevo.', 23, '2015-07-30');

La Enfermera Joy sugiere que lleven la rama a un cirujano de árboles, el doctor Troncales, para que la repare. Él quiere primero que Serena y Braixen le demuestren su vínculo, y la mejor manera de hacerlo es con un combate. Braixen, en cierto momento, usa su rama rota para desatar un potente movimiento nuevo: Llamarada. Esto deja la rama sin posible reparación, pero le devuelve la confianza a Braixen y finalmente acepta la nueva rama que Pancham le ofrece.', 23, '2015-08-13');

Resuelta a volver a encontrar a Eevee, Serena decide hacer una actuación, para atraer su atención. Por supuesto, Eevee se asoma a observar, pero entonces el Team Rocket aparece. En el combate que sigue, Eevee usa Protección para mantener a Serena fuera de peligro, y el Rayo de Pikachu envía a los villanos a despegar de nuevo. Serena le pide a Eevee que se una a su equipo para el Gran Espectáculo Pokémon. Tras una pequeña y tímida duda, Eevee acepta, y nuestros héroes parten una vez más con un nuevo miembro en el grupo.', 23, '2015-09-17');

La performance de Jessie incluye una exhibición de fuegos artificiales muy ruidosa que hace que Eevee corra a ocultarse. Serena no puede actuar hasta que encuentre a Eevee, pero el sonido de su voz pronto le hace salir de su escondite. Xana y Serena realizan unas performances extraordinarias y Serena gana su segunda Llave Princesa.

Y pronto, en cuanto termina el Gran Espectáculo, Beni y Xana corren a ayudar a su amigo Trovato. El Combate de Gimnasio de Ash es lo siguiente en el viaje de nuestros héroes.', 23, '2015-10-08');

Astrid tiene una visión del fuerte vínculo entre Ash y Frogadier y un futuro brillante para ambos, pero también ve que el Reloj Solar corre el grave peligro de ser destruido, por nada menos que el Team Rocket. Nuestros héroes unen sus fuerzas con las de Astrid y sus aprendizas para enviar a los villanos a despegar de nuevo. La formidable Astrid acepta el desafío de Ash para un Combate de Gimnasio y aunque sus amigos están un poco nerviosos, Ash está impaciente por la oportunidad de ganar su séptima Medalla de Gimnasio en Kalos.', 23, '2015-10-15');

Estos nuevos villanos son el Team Flare y han identificado a Blandín como uno de los núcleos que necesitan para su misteriosa "Operación Z". Ash y Sabino se unen para deshacerse de ellos, pero ellos se reagrupan para elaborar nuevos planes, mientras el Team Rocket los observa de cerca. Sabino sugiere que el grupo haga una parada en la Cueva Desenlace en su camino hacia Ciudad Fractal, y Blandín aprueba este plan rotundamente, por lo que el siguiente destino de nuestros héroes ya está decidido.', 23, '2015-10-29');

Pancham y Chespin se apresuran a proteger a su amiga, y Quilladin les desafía a un combate en un intento de impresionar a Eevee. Enseguida el combate es interrumpido, y aparece el Team Rocket, que atrapa a Eevee, a Dedenne, a Blandín y a Bunnelby en una red. Quilladin, Pancham y Chespin deciden dejar a un lado sus diferencias y trabajan en equipo para enviar a los villanos a despegar de nuevo. Al poco rato, una Flareon salvaje llama la atención de Quilladin, que muy contento se separa de nuestros héroes.', 23, '2015-11-05');

Todos están decididos a ayudar a que hagan las paces, sobre todo cuando el profesor les dice que para la megaevolución es necesario tener un vínculo fuerte. Al final, trabajan en equipo para curar a un Makuhita herido, y, cuando el Team Rocket ataca, se demuestra su vínculo cuando Audino megaevoluciona y rápidamente los envía a despegar de nuevo.

Tras haber conocido el Profesor Ciprés a Blandín, confiesa que no sabe qué es y decide volver a su laboratorio para investigar sobre él. Se separan, y nuestros héroes siguen su camino a Ciudad Fractal.', 23, '2015-11-12');

El viaje de Litleo se interrumpe cuando el Team Rocket aparece para atrapar a Pyroar, que también ha estado vigilando al pequeño desde una distancia prudente. Pero Litleo está decidido a detenerlos y encuentra el coraje y la fuerza necesarios para enfrentarse a los villanos. Con una pequeña ayuda de nuestros héroes, envía al Team Rocket a despegar de nuevo y libera a Pyroar. Parece que a Litleo le va a ir muy bien solo, por lo que, tras despedirse de su nuevo amigo, nuestros héroes reanudan el camino hacia Ciudad Fractal.', 23, '2015-11-19');

Las cosas se ponen aún más raras cuando Pikachu y Meowth se encuentran con Blandín, que también puede hablar, y que está siendo perseguido por una gigantesca bola de fuego con cara. Salen huyendo del fuego, pero este sigue persiguiéndolos… hasta que suena el reloj despertador que Lem inventó, que acto seguido explota, despertándolos a todos.', 23, '2015-11-26');

Todos quedan impresionados por el avance de Sanpei como ninja y como Entrenador. Nuestros héroes se maravillan ante los sorprendentes Pokémon que hay allí… y el Team Rocket, observando desde arriba, conspira para atraparlos a todos. De repente, varios Skarmory atacan la aldea y un grupo de ninjas enmascarados secuestran al Jefe Hanzo. ¿Quiénes son y cuáles son sus intenciones? Las respuestas llegarán. Y el viaje continúa.', 23, '2015-12-03');

Durante la batalla, el Frogadier de Ash evoluciona a un inmensamente poderoso Greninja. La fuerza ninja es derrotada, Kagetomo admite el error que ha cometido y decide concentrarse en su entrenamiento. Ash y sus amigos se quedan a disfrutar del festival de la aldea, en el que Hanzo nombra al hermano mayor de Sanpei, Ippei, como nuevo jefe. Tras la marcha de nuestros héroes, el hermano mediano, Nihei, les revela a los demás que ha visto algo en el Greninja de Ash que le recuerda al antiguo héroe de la aldea.', 23, '2015-12-10');

Eevee y Serena bailan juntas, mientras Braixen hace girar un anillo de fuego a su alrededor y, en un movimiento final, Eevee salta elegantemente a la llama flameante de Braixen. Sin embargo, cuando el público explosiona en vítores, Eevee se pone nerviosa y pierde el equilibrio. Este tropiezo es suficiente para darle la victoria a Jessilee y, con ella, su primera Llave Princesa.', 23, '2015-12-17');

Cuando el Team Flare ya está cerca, Blandín invoca a un montón de células y se funde con ellas para convertirse en un feroz Pokémon de armas tomar. Golpea al Team Flare con un ataque devastador, y, por si eso no bastara, Ash saca a su Greninja, y los dos combaten como si se trataran de uno solo.

Por fin, el Team Flare se retira, pero Blandín ha desaparecido. Nuestros héroes parten a buscarlo, mientras el Team Flare vigila cada uno de sus movimientos.', 23, '2015-12-24');

Los demás pronto la alcanzan y juntos buscan la Nicera en la cima de una montaña. Mientras, Blandín los observa escondido, impresionado por la determinación de Clem. Bunnelby se recupera pronto y, justo cuando todos están a punto de salir de nuevo para buscar a Blandín, lo encuentran sano y salvo en la bolsa de Clem.', 23, '2016-01-14');

Una ráfaga repentina de viento se lleva a Floette volando y Noibat despega para rescatar a su nueva amiga. Los dos están jugando juntos cuando Breloom se presenta con un ramo de flores para Floette, pero se enfada cuando ve que Floette no está interesada. Noibat se interpone para proteger a Floette de la atención no deseada... y más tarde del Team Rocket.

Pronto, muchas más Floette llegan con el viento, y Noibat tiene que decir adiós mientras su amiga continúa su particular viaje.', 23, '2016-01-21');

Cuando derriban a Eevee, Serena se acerca a darle fuerzas y, gracias al vínculo entre ambas, Eevee evoluciona a Sylveon y gana la batalla. Más tarde, Aria emocionada llama a Palermo, jueza del Gran Espectáculo, para hablarle de la maravillosa actuación de una chica y su Sylveon.', 23, '2016-01-28');

Alain quiere ver qué más puede hacer el Greninja de Ash, por lo que le desafía a un combate  contra su Charizard y, cuando Charizard megaevoluciona y la apariencia de Greninja vuelve a cambiar, el combate se vuelve intenso. Greninja, al final, es derrotado, pero todos están deseando saber más cosas sobre esta misteriosa transformación.

Mientras tanto, los experimentos del Team Flare parecen haber dado un paso adelante.', 23, '2016-02-04');

Z2, claramente tiene ventaja, pero Lysson ha pedido refuerzos. Con la ayuda de Alain y su Mega-Charizard lucha contra Z2 hasta un punto muerto y lo encierra en una jaula. Mientras tanto, en el campamento de nuestros héroes, Clem acaricia a un triste y preocupado Squishy, intentando averiguar qué es lo que va mal.', 23, '2016-02-11');

Lem hace unas reparaciones para volver a poner a Robon en forma y todos los Pokémon trabajan juntos para encontrar una fuente de agua subterránea, pero está bloqueada por una enorme roca. Robon perfora la roca para liberar un impetuoso manantial y mientras nuestros héroes se dirigen hacia Ciudad Fractal, se observan las primeras señales de nuevo crecimiento.', 23, '2016-02-18');

Por accidente, Serena oye a Amelia quejarse ante la jueza del Gran Espectáculo, Palermo, por haber perdido. Más tarde, Palermo le dice a Serena que todavía no tiene lo que hace falta para ser Reina de Kalos. Serena piensa en ello mientras nuestros héroes se dirigen hacia el siguiente Gran Espectáculo Pokémon en Ciudad Gloria, donde competirá en la Clase Maestra.', 23, '2016-02-25');

Ash encuentra al Team Rocket escondido en otra parte de la cueva, y pronto queda claro por qué está tan enfadado Zapdos. Envía a Talonflame y a Hawlucha a distraer a Zapdos para poder escapar y, cuando Zapdos abate a Hawlucha, Noibat evoluciona a Noivern para rescatar a su amigo. Ash entrega la medicina y el festival comienza.', 23, '2016-03-03');

Cuando se declara un incendio en el Centro Pokémon, Lock, el aprendiz de Don Eduardo, se queda atrapado dentro. Don Eduardo va a ayudarle, y los dos cerrajeros y sus amigos Binacle trabajan juntos para abrir la complicada cerradura. Lock confiesa que se ha convertido en el Maestro Abre-Cerraduras para ganarse el respeto de Don Eduardo, y este contesta que ya lo sabía.

Abren la cerradura, y la Agente Mara arresta a Lock, pero luego le deja ir con una advertencia. Don Eduardo, Lock y sus Binacle se reúnen, y todo se resuelve.', 23, '2016-03-10');

Jessie, (disfrazada de Jessilee), gana en el grupo de Nini en la primera ronda, y Serena vence a Miette. Después de perder, las dos niñas están disgustadas, pero felicitan a Serena y le exigen que gane por todas ellas. Serena, Jessie y Xana pasan a competir en las semifinales..., y la ganadora desafiará a Aria por el título de la Reina de Kalos.', 23, '2016-03-17');

Después, Palermo se reúne con Serena, que aún está entusiasmada por convertirse en la Reina de Kalos. Palermo está impresionada con su progreso y se ofrece a ser su mentora. Después de pensarlo un poco, Serena decide continuar su viaje con Ash y los demás por ahora, pero Palermo le dice que la oferta seguirá en pie cuando esté preparada.', 23, '2016-03-24');

Más tarde, en medio de un ataque del Team Rocket, Clem se encuentra en peligro, y Lem corre a rescatarla, sacrificando incluso su valioso Brazo Aipom en el proceso. Lilia decide que no está preparada para casarse después de todo, así que los hermanos se reconcilian y nuestros héroes parten de nuevo hacia Ciudad Fractal.', 23, '2016-04-07');

El combate está yendo bien para Serena, cuando el Team Rocket se hace con los dos Pikachu, pero, tras una rápida recuperación, Ash ayuda a derrotar a los villanos. Jimmy está impresionado con las habilidades de combate de Serena, pero aun así quiere desafiar al verdadero Ash... justo después de almorzar.', 23, '2016-04-14');

Mientras Greninja se está curando, Alain y su Charizard se pasan por el mismo Centro Pokémon y, con mucho entusiasmo, acceden a librar un combate. Durante esta feroz competición, Ash y Greninja se sincronizan, y Greninja se transforma en un espectacular despliegue de poder, pero el combate se interrumpe después de que Ash reacciona de manera intensa y alarmante. Aun así, está decidido a hacerse más fuerte junto a Greninja.', 23, '2016-04-21');

Disfrazados, los villanos alejan a Phantump con la promesa de más amigos nuevos, pero sus verdaderos amigos pronto corren a rescatarlo, mientras aparece el grupo de Phantump del bosque para enviar al Team Rocket a despegar de nuevo.', 23, '2016-04-28');

Comienza una tormenta de nieve, y Ash se refugia en una cueva con algunos Pokémon asustados. Se mete en problemas tratando de ayudar a un Spewpa atrapado, pero Greninja aparece justo a tiempo y se transforma en "Greninja Ash", sin el más mínimo esfuerzo, para rescatar a Spewpa. Cuando nuestros héroes se reúnen, Ash promete no volver a perder los nervios, una promesa que Greninja le va a hacer cumplir, cuando Ash se entera de que la Liga de Kalos se va a celebrar en Ciudad Luminalia.', 23, '2016-05-26');

Al principio, Greninja contra Abomasnow, y luego Greninja Ash contra Mega-Abomasnow, puesto que Édel saca una inesperada Piedra Activadora. A pesar de ser un gran desafío, Greninja Ash se viene arriba, y Ash gana su última Medalla de Gimnasio y se clasifica para la Liga de Kalos.', 23, '2016-06-02');

Sintiéndose mal por los problemas que ha provocado, el travieso Carbink forma equipo con Goodra para liberar a sus amigos y enviar a los villanos a despegar de nuevo. Mientras tanto, Alain ha derrotado a la Líder de Gimnasio Corelia, ganando su octava Medalla de Gimnasio. Y ahora está impaciente por enfrentarse a un oponente en particular, en la Liga de Kalos.', 23, '2016-06-09');

A Ash le detiene un rival tenaz en su camino hacia el campo de batalla y llega justo a tiempo para su enfrentamiento. Su oponente empieza con un impresionante Altaria, pero Greninja Ash consigue una victoria rápida. Mientras tanto, ambos, Sabino y Alain, esperan con paciencia su oportunidad de enfrentarse a Ash.', 23, '2016-06-30');

Luego ocurre algo insólito: un empate, ya que el Noivern de Ash y el Salamence de Sabino se noquean el uno al otro. Y luego vuelve a ocurrir con el Goodra de Ash y el Slurpuff de Sabino. El Sceptile de Sabino derrota a Pikachu y, por fin, Greninja Ash y Mega-Sceptile se enfrentan en un impresionante combate. El combate es rápido y encarnizado, hasta que Greninja Ash emerge victorioso, y Ash pasa a la final para enfrentarse a Alain.', 23, '2016-07-28');

A continuación, el Talonflame de Ash y el Unfezant de Alain se noquean el uno al otro, tras un espectacular combate aéreo,  y empatan tres a tres. Pikachu regresa para enfrentarse al enorme Metagross,  demostrando una determinación asombrosa, y se hace con la victoria. Entonces, Alain saca a su compañero Charizard, y ambos Pokémon se disponen a librar el combate que tienen por delante con confianza y alegría.', 23, '2016-08-11');

Los ataques y estrategias son rápidos y potentes, pero al final Mega Charizard X sale triunfante, y Alain se convierten en el Campeón. Sin embargo, mientras que todos los ojos están concentrados en la Liga de Kalos, Lysson y el Team Flare ponen en marcha su plan, y el pánico se apodera de Ciudad Luminalia, cuando el  Zygarde capturado lanza sus terroríficos poderes contra la Torre Prisma.', 23, '2016-08-18');

Ash y Alain parten a rescatar a Mairin, pero Ash se queda sorprendido al descubrir que Alain ha estado trabajando con Lysson, y el Team Flare encierra a Ash en la cima de la Torre Prisma. Sus amigos tratan de ayudarlo, pero un furioso Zygarde  se interpone en su camino. Pero un segundo Zygarde se enfrenta a él, puesto que Blandín se transforma y revela su verdadera identidad. Se aproxima una gran batalla, de Zygarde contra Zygarde.', 23, '2016-08-25');

Blandín, una vez revelado como el Pokémon legendario Zygarde, sigue tratando de comunicarse con el Zygarde del Team Flare, pero una horrible máquina del Team Flare hace que Blandín quede bajo su control, mientras Clem lo observa todo con desesperación. El destino del mundo está en juego. ¿Quién saldrá victorioso?', 23, '2016-09-01');

Lem entra en la Torre Prisma para derrotar a Xero, y Lembot se conecta al sistema de control con la intención de apagarlo. Al hacerlo, borrará su memoria, pero Lembot insiste en que no tienen elección, y Lem accede a hacerlo con gran tristeza. Al completar la desconexión, la máquina del Team Flare se apaga... de momento.', 23, '2016-09-08');

La situación es desesperada, pero Blandín convence al otro núcleo para que se una a la batalla. Los dos se fusionan para convertirse en el titánico Zygarde Forma Completa, que detiene el plan de Lysson de una vez por todas. Finalmente, es hora de que Blandín y Clem se despidan, pero siempre recordarán su inquebrantable amistad que ha ayudado a salvar al mundo.', 23, '2016-09-15');

El resto de nuestros héroes también han hecho planes. Ash quiere volver a casa para empezar de nuevo. Alain vuelve a trabajar para el Profesor Ciprés. Y Serena recuerda la oferta que Palermo le hizo para estudiar con ella.', 23, '2016-10-06');

Clem le convence para que salga de su escondite, con una charla emotiva sobre perseguir juntos sus sueños, y llega la hora de que Serena coja el avión, y de una emotiva despedida de Ash. A Lem se le ocurre la idea perfecta para pasar el tiempo hasta que Ash tenga que partir. Un combate entre Pikachu y Bunnelby, igual que el día en que se conocieron.', 23, '2016-10-27');

Jan continuó su misión, en busca del Pokémon Creación, Xerneas, para que nutriera la tierra estéril, aunque no pudo recuperar a Aila. Cuando Kalos parecía haber perdido el equilibrio por completo, el Pokémon Equilibrio, Zygarde, apareció para restaurarlo, y Jan permaneció al lado de Aila mientras el ciclo de vida y destrucción continuaba.', 23, '2016-11-03');

De madrugada, como Lylia no puede conciliar el sueño, se pone a hablar con la Profesora Pimpinela, que le da consejos sobre su familia. Al día siguiente, Nebulilla teletransporta inesperadamente a Lylia para hacerle una visita a su hermano, y su compañero, el misterioso Silvally, le da un gran susto, dejándola aterrorizada y de nuevo incapaz de tocar Pokémon.', 23, '2017-11-02');

Kukui pide ayuda a Lario para intercambiarse, y así poder mantener su secreto. Pero James y Fabio, que son dos grandes fans, pillan a Lario "robando" la máscara de Royale y lo atan. Después, Fabio decide ponerse la máscara y subir al cuadrilátero, tras subir Mad Magma en busca de un combate de revancha. Al final, todo sale bien. Lario se desata y ayuda a Kukui a recuperar su máscara. Mad Magma es derrotado, y la identidad secreta de Royale, el Enmascarado, sigue a salvo.', 23, '2018-10-14');

Cuando la niebla se despeja, Lylia y Gladio se preguntan por qué ellos no han podido reencontrarse con su padre desaparecido, y se llevan una gran impresión cuando Hela les dice que su padre podría seguir aún, en alguna parte, en este mundo.', 23, '2019-02-10');

El Golisopod de Guzmán se defiende bien contra Pikachu, pero, cuando, de repente, regresa a su Poké Ball, se acaba el combate, y Guzmán vuelve a la base del Team Skull. ¿Cuál es la relación entre Guzmán y el Profesor Kukui? ¿Y se hará realidad la Liga Pokémon de Alola?', 23, '2019-03-31');

Pero, al levantarse una ráfaga de viento, Shaymin, Meltan y Areni salen volando. Nuestros héroes se disponen a buscarlos, pero hay un trío más que dispuesto a robar Pokémon raros. Son ni más ni menos que el Team Rocket.

Pero, cuando utilizan una trampa de un material supuestamente irrompible, descubren que Meltan come todo tipo de material.

Pero aparece Stufful con una cometa en forma de Bewear de tamaño natural y se lleva al desventurado trío de nuevo. Nuestros héroes se reúnen muy contentos. Ash se entera de que Charlie también es Entrenador en el Gimnasio de Kanto y está deseando hacerle una visita.', 23, '2019-04-14');

Al día siguiente, Ash y Goh le cuentan a Chloe que han conocido a ese joven y a su Psyduck, así que Chloe insiste en salir a buscarlos. La búsqueda es fructífera y Chloe reúne a una Chrysa llena de alegría ¡con el Psyduck que tanto significó para ella!', 23, '2021-02-26');

Luego, Meowth y Wobbuffet se juntan con un Chewtle, que se encuentra con un Turtwig, y ambos Pokémon con caparazón deciden echar una carrera. Se unen más competidores, pero cuando el resto de los Pokémon se van a casa, Chewtle se declara ganador.', 23, '2021-03-05');

Ash desafía a Risto a un combate oficial: una revancha entre Farfetch´d y Gallade. Farfetch´d tiene un comienzo flojo pero Ash le pide que recuerde el entrenamiento que recibieron de Tileo. Tras asumir una nueva estrategia, Farfetch´d evoluciona a Sirfetch´d, derrota a Gallade y la categoría de Ash en la Serie Mundial de Coronación se dispara hasta el 184.', 23, '2021-03-19');

El Líder de Gimnasio Lirio accede a dejarles combatir en el Gimnasio Caolín, y será un enfrentamiento de Dragonite contra Dragonite.

Pero el Dragonite de Iris parece  más fuerte, así que Ash, de momento, retira a su Dragonite y saca a Dracovish. Ni Iris ni Lirio jamás han visto un Dracovish, y el Dragonite de Iris pierde. Iris entonces saca a Haxorus, la forma evolucionada de su compañero Axew. El combate es feroz, pero la singular estrategia de Ash con su Dragonite derrota a Haxorus, convirtiéndole en el ganador y llevándolo hasta la Clase Superior.', 23, '2021-05-07');

La investigación de Ash y Goh demuestra que Darkrai está vagando cerca de un bosque en Sinnoh, mientras que el Team Rocket parte a capturar a Cresselia, localizada  en alguna parte de ese mismo bosque…

Cuando Chloe acampa, aparecen Maya y Piplup. Aunque Chloe nunca ha participado en un Concurso Pokémon, accede a ir con Maya a Ciudad Vetusta. Sin embargo, los planes dan un giro cuando Maya y Chloe descubren a una Cresselia herida.', 23, '2021-07-23');

Ash se maravilla ante la rutina de entrenamiento de Lionel, llena de diversión, juego y tentempiés. Este es el entrenamiento que le gusta a nuestro héroe, y pronto se hace evidente que los dos se parecen como dos juguetonas gotas de agua.', 23, '2022-03-04');

Mientras Goh atrapa a varios Pokémon por el camino, entran en un laberinto de cavernas donde descubren a Articuno. Se produce un feroz combate y los Pokémon de todos ellos combaten valientemente, pero Articuno gana. Al principio, Gary se burla de Goh, a quien no le hace nada de gracia. Pero Gary está intentando impresionarle con la idea de disciplina. Al derretirse la frialdad mutua que ambos sienten, Goh y Gary ahora esperan con ilusión volver a encontrarse.', 23, '2022-03-18');

Mientras tanto, Ash y Goh se retrasan porque el Líder de Gimnasio Plubio insiste en combatir contra Ash. Chloe, Serena y Ariana dan unos fantásticos espectáculos con sus Pokémon, y, mientras Serena se despide de Chloe, llegan por fin Ash y Goh. Aunque su reencuentro es corto, Ash y Serena prometen animarse mutuamente mientras persiguen sus objetivos.', 23, '2022-04-08');

Mientras tanto, Ren y el Profesor Cerezo se han hecho enormes fans del programa sin darse cuenta de las verdaderas identidades de sus carismáticos locutores. El objetivo original del Team Rocket de encontrar nuevos miembros puede haberse desvanecido, pero su programa de radio en la web es un gran éxito.', 23, '2022-04-15');

Gigaesfera Aural. Ash gana el combate, convirtiéndose oficialmente en un miembro de Los Ocho Maestros.', 23, '2022-05-06');

UPDATE Contenido SET id_tmdb = 296, descripcion = 'Ha pasado una década desde que John Connor salvara a la humanidad de la destrucción. En la actualidad John tiene 25 años y vive en la clandestinidad: no hay ninguna prueba documental de su existencia. Así evita ser rastreado por Skynet, la sofisticada corporación de máquinas que una vez intentó acabar con su vida. Pero, ahora, desde el futuro, ha sido enviado el T-X, la máquina destructora cyborg más desarrollada de Skynet. Su misión es completar el trabajo que no pudo terminar su predecesor, el T-1000. El T-X es una máquina tan implacable como bello su aspecto humano. Ahora la única esperanza de sobrevivir para Connnor es Terminator.', trailer_url = 'https://www.youtube.com/watch?v=vphJKzT0IWs' WHERE id_api = 'tt0181852';

UPDATE Contenido SET id_tmdb = 1900, descripcion = 'El juez Robert Wakefield es nombrado por el Presidente de los Estados Unidos para supervisar los grupos de lucha contra la droga y su coordinación con las autoridades de México. Sin embargo su entusiasmo inicial por la posición de prestigio alcanzada se acabará cuando se dé cuenta de que su hija adolescente Caroline, de 16 años, se ha convertido en una drogadicta -hecho que le ocultaba su esposa Barbara-. Mientras tanto, al sur de la frontera, el agente mexicano Javier Rodriguez intenta librar su propia batalla contra la droga.', trailer_url = 'https://www.youtube.com/watch?v=sZnOWu68Vw4' WHERE id_api = 'tt0181865';

UPDATE Contenido SET id_tmdb = 786, descripcion = 'Homenaje al rock de los 70. Gracias a sus buenas críticas musicales, un adolescente que aspira a ser periodista es contratado por la revista "Rolling Stone" para cubrir la gira de una famosa banda. A pesar de su juventud y de la oposición de su madre, el chico vivirá con los músicos y sus fans una aventura inolvidable. Basada en la propia experiencia de Crowe.', trailer_url = 'https://www.youtube.com/watch?v=4U07rtBNa2g' WHERE id_api = 'tt0181875';

UPDATE Contenido SET id_tmdb = 2067, descripcion = 'En el año 2020 el comandante Luke Graham es seleccionado para dirigir la primera misión tripulada de la NASA a Marte. Una vez en el planeta rojo, descubren una antigua estructura con forma de cúpula que parece ser una especie de baliza. La cúpula mata a la tripulación y deja herido a Luke. El coronel Jim McConnell, recientemente enviudado, encabezará la misión de rescate.', trailer_url = 'https://www.youtube.com/watch?v=njIN5HU4UMQ' WHERE id_api = 'tt0183523';

UPDATE Contenido SET id_tmdb = 14181, descripcion = 'Seth ha dejado los estudios y ha montado un casino ilegal en su casa. Su padre, que es juez, no ve demasiado bien esta ocupacion, y esto provoca nuevas tiranteces en su relacion, ya de por si tensa. Todo parece cambiar cuando a Seth un cliente le ofrece trabajar como agente de bolsa. Sin embargo, pronto comprobará que no es oro todo lo que reluce. Es un mundo atractivo en el que la gran parte son jóvenes y ambiciosos. Pero en el negocio de la especulación financiera la lealtad riñe con la ambición...', trailer_url = 'https://www.youtube.com/watch?v=kgCLG4gCAvI' WHERE id_api = 'tt0181984';

UPDATE Contenido SET id_tmdb = 2277, descripcion = 'En la primera década del nuevo milenio, con avances tecnológicos que engullen la soberanía de la compasión humana, Richard Martin compra un regalo, un nuevo robot NDR-114. El hijo más pequeño de la familia le pone de nombre Andrew. Andrew es adquirido como electrodoméstico casero programado para realizar tareas menores. A medida que Andrew empieza a experimentar emociones y pensamiento creativo, la familia Martin descubre pronto que no tienen un robot común y corriente.', trailer_url = 'https://www.youtube.com/watch?v=NRFxf-2J1GM' WHERE id_api = 'tt0182789';

UPDATE Contenido SET id_tmdb = 2123, descripcion = 'Charlie es un inocente y amable policía de Rhode Island que es todo un caballero, además de un abnegado padre soltero de tres hijos de color que su esposa tuvo tras una aventura. Pero un día Charlie, conocido por su buen carácter, no soporta más que le tomen por blando y sufre de repente un trastorno de personalidad, convirtiéndose en alguien completamente distinto, en el que sale a relucir su hiperagresivo álter ego...', trailer_url = 'https://www.youtube.com/watch?v=UBPHrX4x3Ns' WHERE id_api = 'tt0183505';

UPDATE Contenido SET id_tmdb = 1817, descripcion = 'En medio de la calle y a plena luz del día, el joven Stu Shepard, un ambicioso publicista de Nueva York, se encuentra de repente atrapado en una cabina telefónica debido a las amenazas de un francotirador que le está apuntando: si cuelga el teléfono, morirá.', trailer_url = 'https://www.youtube.com/watch?v=ica8jopRX9A' WHERE id_api = 'tt0183649';

UPDATE Contenido SET id_tmdb = 11004, descripcion = 'Grady Tripp, un profesor de literatura de la Universidad de Carnegie Mellon, sufre una crisis que le impide escribir: su tercera esposa lo acaba de abandonar, y su agente literario lo presiona para que termine su segunda novela. Siete años antes, cuando era un joven prodigio, su primera novela tuvo una enorme repercusión. Durante el fin de semana en que se celebra el "Festival de las Palabras", James Leer, uno de sus alumnos, despierta su vena paternal, y ambos se lanzan a la búsqueda de una extraña prenda que perteneció a Marilyn Monroe.', trailer_url = 'https://www.youtube.com/watch?v=VZd2zeiFYl8' WHERE id_api = 'tt0185014';

UPDATE Contenido SET id_tmdb = 9476, descripcion = 'Edad Media, siglo XIV. William es un joven plebeyo extraordinariamente dotado para justas y torneos. Tras la repentina muerte de su maestro, en compañía de sus amigos y escuderos Roland y Wat, se lanza a la aventura y se hace pasar por un noble caballero. Durante sus viajes conocerá a Chaucer, un escritor que falsificará un árbol genealógico que justifique el título nobiliario del que se ha apropiado.', trailer_url = 'https://www.youtube.com/watch?v=PVKVgkm-nkA' WHERE id_api = 'tt0183790';

UPDATE Contenido SET id_tmdb = 2332, descripcion = 'El embajador japonés se encuentra de visita en Marsella para informarse de las técnicas policiales anti-terroristas de la ciudad. Sin embargo, durante la visita es secuestrado por un grupo yakuza junto a Petra, agente policial compañera de Émilien, el cual tendrá que recurrir de nuevo a Daniel y a su peculiar taxi para salvar la situación, restaurar el "honor" del cuerpo de policía e impedir un conflicto internacional.', trailer_url = 'https://www.youtube.com/watch?v=XvGjrOLjG-s' WHERE id_api = 'tt0183869';

UPDATE Contenido SET id_tmdb = 8584, descripcion = 'Corre el año 1881 y Chon Wang (Jackie Chan) es un guardián del emperador chino. Cuando la princesa Pei Pei (Lucy Liu) es secuestrada y retenida en el oeste de Nevada en los Estados Unidos de América, él decide ir en su búsqueda junto con otros guardias imperiales. Una vez allí, se encuentra con una banda de pistoleros liderados por Roy O''Bannon (Owen Wilson), quien se muestra muy interesado por la princesa y en su recompensa, por lo cual decide ayudar a Chon en su ardua tarea de búsqueda.', trailer_url = 'https://www.youtube.com/watch?v=FqHg5fc_0_U' WHERE id_api = 'tt0184894';

UPDATE Contenido SET id_tmdb = 99, descripcion = 'Madrid. Manuela, una madre soltera, ve cómo su hijo muere el día en que cumple 17 años, por correr para conseguir el autógrafo de su actriz favorita. Decide entonces viajar a Barcelona en busca del padre de su hijo, un travestido llamado Lola, que ignoraba que tenía un hijo. Encuentra también a su amigo Agrado, otro travesti, y a través de él conoce a Rosa, una monja española y, por pura casualidad, Manuela termina convirtiéndose en la asistente de Huma Rojo, la actriz que admiraba su hijo.', trailer_url = 'https://www.youtube.com/watch?v=hcVEvcP1iAc' WHERE id_api = 'tt0185125';

UPDATE Contenido SET id_tmdb = 4613, descripcion = 'Miniserie de TV de 10 episodios que se basa en el bestseller de Stephen E. Ambrose "Band Of Brothers". Narra la historia de la Easy Company, un batallón americano del regimiento 506 de paracaidistas que luchó en Europa durante la II Guerra Mundial (1939-1945). Incluye entrevistas a los supervivientes, recuerdos de los periodistas y cartas de los soldados.', trailer_url = 'https://www.youtube.com/watch?v=KKRBAFlN5ww' WHERE id_api = 'tt0185906';

', 59, '2001-10-28');

UPDATE Contenido SET id_tmdb = 11377, descripcion = 'Un excéntrico millonario, especialista en atracciones de terror, organiza en un antiguo psiquiátrico una fiesta en honor de su mujer, con la que no se lleva especialmente bien. El edificio, situado en una remota colina, arrastra la leyenda de que está encantado debido a los horribles sucesos que ocurrieron años atras. Cuando llegan los invitados, los anfitriones descubren la primera sorpresa: no son los esperados, sino un grupo de personas totalmente diferente.', trailer_url = 'https://www.youtube.com/watch?v=DayzGxv9Kf4' WHERE id_api = 'tt0185371';

UPDATE Contenido SET id_tmdb = 5491, descripcion = 'En el año 3000 ya no existen ciudades ni naciones, la Tierra es un yermo desolado y la raza humana está a punto de extinguirse. Desde hace mil años, una malvada raza de alienígenas, los Psychlo, aniquilaron las defensas terrestres y esclavizaron a los hombres. El joven Jonni Goodboy Tyler parece ser la única esperanza de la humanidad.', trailer_url = 'https://www.youtube.com/watch?v=7VbfuehRjpw' WHERE id_api = 'tt0185183';

UPDATE Contenido SET id_tmdb = 9678, descripcion = 'Tras diez mil años de duro trabajo, Satanás está deseando retirarse, pero ninguno de sus hijos es lo bastante malvado para sustituirlo. Los mayores, Cassius y Adrian, cansados de la tiranía de su padre, deciden marcharse a Nueva York para instaurar su propio reino infernal. Nicky, el más pequeño y tonto, conseguirá evitar la sucesión encarnándose en un hombre.', trailer_url = 'https://www.youtube.com/watch?v=yQhuDfZMSgA' WHERE id_api = 'tt0185431';

UPDATE Contenido SET id_tmdb = 2667, descripcion = 'Durante el octubre de 1994, tres estudiantes de cine en el Montgomery College, Heather Donahue, Joshua Leonard y Michael Williams realizaron la propuesta de crear un proyecto para presentarla en la clase de cine, el proyecto llamado por Heather "El Proyecto de la Bruja de Blair" contaba de entrevistas con los residentes del pueblo de Burkittsville, Maryland, sobre la bruja local.', trailer_url = 'https://www.youtube.com/watch?v=AcTh2YItSaM' WHERE id_api = 'tt0185937';

UPDATE Contenido SET id_tmdb = 10559, descripcion = 'John Sullivan vive obsesionado con la muerte de su padre, un bombero que pereció hace 30 años durante un incendio. Un día, un extraño fenómeno meteorológico le permite hablar con él a través de un viejo equipo de radioaficionado con el que se comunica con el pasado: John informa a su padre de los errores cometidos en aquel incendio y así evita su muerte. Sin embargo, de este vuelco del destino se derivarán otros trágicos acontecimientos.', trailer_url = 'https://www.youtube.com/watch?v=jdACpDDpIUs' WHERE id_api = 'tt0186151';

UPDATE Contenido SET id_tmdb = 9679, descripcion = 'Hace ya tiempo que Randall "Memphis" Raines ha dejado atrás su pasado delictivo. Pero cuando se entera de que su hermano está en peligro, para salvarlo se ve obligado a hacer lo que mejor sabe hacer: robar coches: 50 coches y un contrato. Fanático del automovilismo, Memphis es una leyenda en el negocio de robo de coches. No se le resiste ninguna cerradura, ninguna alarma.', trailer_url = 'https://www.youtube.com/watch?v=LDafYNLmNPE' WHERE id_api = 'tt0187078';

UPDATE Contenido SET id_tmdb = 5551, descripcion = 'Cuatro veteranos pilotos del ejército del aire de los EE.UU. ven cumplidos sus deseos de convertirse en astronautas y viajar al espacio aunque sea con cuarenta años de retraso. Su misión es reparar un gran satélite de comunicaciones ruso, que se ha salido de su órbita, para evitar que caiga sobre la Tierra. El satélite en cuestión había sido diseñado por Frank Corvin, el capitán de la expedición. Tras un severo y, a veces, hilarante entrenamiento, estos veteranos astronautas tropezarán en el espacio con problemas más difíciles de lo que esperaban.', trailer_url = 'https://www.youtube.com/watch?v=7PAZBAV43Zw' WHERE id_api = 'tt0186566';

UPDATE Contenido SET id_tmdb = 2024, descripcion = 'Año 1776, Guerra de Independencia entre los colonos de Nueva Inglaterra y las tropas de Jorge III (1760-1820). En Carolina del Sur, el viudo Benjamin Martin (Mel Gibson), heroico soldado en Francia y en la India, renuncia a combatir para cuidar de sus siete hijos. Pero la pacífica vida de la familia Martin se ve alterada cuando Gabriel (Heath Ledger), el hijo mayor, se alista en el ejército; mientras tanto su padre se esfuerza por sacar adelante a la prole. Sin embargo, los británicos, al mando del cruel coronel Tavington (Jason Isaacs), llegarán hasta las puertas de su casa poniendo en peligro a toda la familia...', trailer_url = 'https://www.youtube.com/watch?v=OpKR4qTOVgI' WHERE id_api = 'tt0187393';

UPDATE Contenido SET id_tmdb = 134, descripcion = 'Siempre con algo interesante que ofrecer, los hermanos Coen firman una divertida e inclasificable comedia, con algunos eficaces giros dramáticos, que narra la historia de tres reclusos que, tras escapar de una cárcel sureña, deciden en plena fuga ganarse un dinero grabando una canción que será todo un éxito. A destacar el simpático Clooney, que demuestra su talento tanto para la comedia -se llevó el Globo de Oro al mejor actor- como para la música -la banda sonora de la película también alcanzó gran popularidad-.', trailer_url = 'https://www.youtube.com/watch?v=cWDbEMEkV14' WHERE id_api = 'tt0190590';

UPDATE Contenido SET id_tmdb = 36586, descripcion = 'Una nueva raza de vampiros, los Reapers, surge para atacar tanto a los humanos como a los de su propia raza, causando el terror. El Consejo de la Sombra, un grupo de vampiros que teme por su supervivencia y que tiene su sede en Praga, contacta con Blade para que acabe con ellos.', trailer_url = 'https://www.youtube.com/watch?v=9T8aigHWtxM' WHERE id_api = 'tt0187738';

UPDATE Contenido SET id_tmdb = 1434, descripcion = 'Los Griffin son una mediocre familia compuesta por Peter y Lois; sus hijos, Meg, Chris, y Stewie; y su antropomórfica mascota canina Brian. Está ambientada en la ciudad ficticia de Quahog, Rhode Island, y gran parte de su humor se exhibe en forma de pequeños cortes que frecuentemente se mofan de la cultura americana.', trailer_url = 'https://www.youtube.com/watch?v=J32iwo65RMc' WHERE id_api = 'tt0182576';

Mientras tanto, Peter y Brian compiten como Willy Wonker, pero con cerveza en lugar de chocolate, mientras que Stewie es secuestrado por una banda de mutantes.');

¿Qué novedades hay en la familia Griffin? Es trivial: Brian se ha vuelto adicto a la cocaína, algo poco recomendable para un pointer recién entrenado. Los planes de Stewie de conquistar el planeta se ven frustrados una vez más, mientras que Peter debe recuperarse del shock al descubrir que su hijo adolescente es... ¡Físicamente mucho más talentoso que él!');

No Bones About It: Un genio concede a Peter tres deseos, su último deseo consiste en "no tener huesos" teniendo que vivir como un montón de grasa.

SuperGriffins: Los Griffin son expuestos a residuos tóxicos con los que obtienen poderes, al final acaban aterrorizando a la ciudad.

Li''l Griffins: Versión diminuta de los Griffin y parodia de La pandilla. Peter y Quagmire intentan hacer valer su valentía para impresionar a Lois.', 23, '2002-02-14');

La temporada recibió críticas dispares por parte de la crítica, los cuales citan el abuso que se hace de personajes como el Viejo Herbert o el Sordo Engrasado, y la falta de guiones originales. La PTC, grupo frecuentemente crítico con Padre de familia calificó varios episodios como "el peor programa de prime time para los televidentes". Los críticos, sin embargo, puntúan que la serie "no ofrece signos de debilidad", además de tener "muchos momentos divertidos como jamás se han visto".');

FOX celebró el episodio 100 de la serie con Stewie Kills Lois.2 Blue Harvest se contó como un doble episodio, explicando así las diferencias respecto al episodio 100 de la serie.

Debido a la huelga de guionistas del 2007-2008, la temporada tuvo un número reducido de episodios, de los cuales 3 fueron emitidos sin permiso expreso de Seth MacFarlane (quien apoyaba la huelga y se negó a trabajar en más episodios).');

Stand by Me: Peter, Joe, Quagmire y Cleveland a los 12 años viajan a lo largo de una vía férrea

Misery: Tras sufrir un accidente con el coche, Brian es "auxiliado" por su "fan número uno" Stewie

The Shawshank Redemption: Cleveland y Peter se hacen amigos en una prisión.', 22, '2009-05-10');

Un asesino anda suelto entre los desprevenidos ciudadanos de Quahog, reunidos en la finca de James Wood para una noche de intriga y asesinatos. ¿Resolverá Peter el misterio... o empeorará las cosas, como siempre? ¡Únete a tus personajes favoritos en esta divertidísima aventura y en el resto de la diversión!');

Chap of the Manor: Peter y su familia aparecen representados en una versión británica de la serie.

Fatman and Robin: Tras escuchar un monologo humillante sobre el actor Robin Williams, a Peter le gustaría que todo el mundo fuera como él, sin embargo cuando es alcanzado por un rayo y adquiere la habilidad de transformar a todo aquel que toca en el actor la cosa se le va de las manos

Point of Stew: El episodio está realizado desde el perspectiva de Stewie, desde cuando se levanta hasta cuando se acuesta.', 22, '2012-05-20');

Dale un toque de risa a tu hogar con los nuevos y divertidísimos episodios de Padre de Familia: Peter necesita un riñón nuevo, Lois se convierte en campeona de boxeo, Chris encuentra un nuevo pasatiempo, y Brian y Stewie ponen a prueba la continuidad del espacio y el tiempo para intentar salvar el universo. ¡Viaja a una nueva galaxia de risas con Padre de Familia!');

La serie presenta a la familia Griffin, una familia disfuncional formada por el padre Peter, la madre Lois, la hija Meg, el hijo Chris, el bebé Stewie y el perro de la familia Brian, que residen en su ciudad natal de Quahog.

Los invitados especiales a la temporada incluyen a Conan O''Brien, Jeff Daniels, Michelle Dockery, Tony Sirico, Yvette Nicole Brown, Gary Cole, y Cesar Millan, Ashton Kutcher, Liam Neeson, Jon Cryer, Liam Neeson, Bryan Cranston, Billie Joe Armstrong, Peter Dinklage y Adam Levine.4 5

La temporada finalizó el 18 de mayo de 2014 con el episodio "Chap Stewie".');

La serie sigue a la familia Griffin, una familia disfuncional formada por el padre Peter, la madre Lois, la hija Meg, el hijo Chris, el bebé Stewie y el perro de la familia Brian, que residen en su ciudad natal de Quahog, Rhode Island.

El primer episodio de la temporada cuenta con un crossover con la serie Los Simpsons.');

UPDATE Contenido SET id_tmdb = 745, descripcion = 'Spaced es una serie de humor británica escrita y protagonizada por Simon Pegg y Jessica Hynes, sobre las vidas de un dibujante de cómics y una periodista estancada, cuya cotidianidad y comicidad dan como resultado desde críticos toques de ironía hasta el humor más surrealista, además de continuas referencias a la cultura pop y las relaciones interpersonales.

', trailer_url = 'https://www.youtube.com/watch?v=IXx0pxPD8mY' WHERE id_api = 'tt0187664';

UPDATE Contenido SET id_tmdb = 2069, descripcion = 'Nicholas es un joven dentista que vive una vida tranquila, pero con una mujer insoportable, en su acogedora casa al lado de Montreal. El mundo de Nicholas sufrirá una revolución cuando aparece su nuevo vecino, Jimmy “El Tulipán”, un temido y reputado asesino a sueldo. Después de delatar en prisión a su jefe, el capo mafioso Yanni Gogolack, intenta ahora empezar una nueva y tranquila vida en el Montreal suburbano. Sin embargo, la intrigante esposa de Nicholas acaba de un plumazo con ese sueño cuando obliga a éste a volar hasta Chicago para avisar a la mafia que Jimmy está en Montreal y cobrar así la recompensa del chivato. Nicholas, que haría cualquier cosa por alejarse de su mujer, accede a llevar a cabo el plan, creyendo que quizás así podrá reunir el dinero suficiente para abandonarla y desaparecer', trailer_url = 'https://www.youtube.com/watch?v=efr6Pm8LrSM' WHERE id_api = 'tt0190138';

UPDATE Contenido SET id_tmdb = 10873, descripcion = 'Año 1921. F.W. Murnau está rodando Nosferatu en la Europa del Este. El director está decidido a hacer la película más auténtica jamás vista. Para este fin Murnau ha contratado a un vampiro auténtico, Max Schreck como protagonista. Explica el peculiar comportamiento de Schreck diciendo a su equipo que es el no va más de la nueva generación: el actor con método, formado por el mismísimo Stanislavsky. Si Schreck realiza la actuación que Murnau busca tan desesperadamente y controla hasta el final de la producción sus necesidades más indecorosas, el premio de Schreck será el sabroso cuello de la estrella de la película, Greta.', trailer_url = 'https://www.youtube.com/watch?v=_B15iesNMa8' WHERE id_api = 'tt0189998';

UPDATE Contenido SET id_tmdb = 146, descripcion = 'China del año 43 (1779) y ambientada en la historia de la Dinastía Quing. Li Mu Bai, un virtuoso de las artes marciales, tiene en su poder una espada mágica conocida como "Destino Verde". Éste no quiere seguir siendo un guerrero, por lo que decide darle la espada a su mejor amigo, Sir Te. Antes de que llegue el momento de entregarla, se la confía a su enamorada, la guerrera Yu Shu Lien, quien será la encargada de llevarla a la ciudad de Pekín, donde se encuentra su compañero. Sin embargo, una noche, un enmascarado entra en la casa de Sir Te y roba la espada. Así, Mu Bai y Shu Lien se lanzarán en la búsqueda de "Destino Verde", despertando, con ello, viejos fantasmas del pasado.', trailer_url = 'https://www.youtube.com/watch?v=q-HrIQLdaNE' WHERE id_api = 'tt0190332';

UPDATE Contenido SET id_tmdb = 10228, descripcion = 'Un grupo de científicos ha estado trabajando en un laboratorio secreto, tratando de crear el Pokémon más fuerte que exista. Para ello, han tomado ADN de una muestra de cabello fosilizada del legendario Pokémon Mew, utilizando el código genético de la evasiva criatura para crear a Mewtwo mediante la ingeniería biológica. Ignorantes del poder de su creación, los científicos y sus laboratorios son destruídos por Mewtwo cuando se despierta. Airado con sus creadores, Mewtwo jura vengarse del mundo...', trailer_url = 'https://www.youtube.com/watch?v=NFE-LU2g3ow' WHERE id_api = 'tt0190641';

UPDATE Contenido SET id_tmdb = 11678, descripcion = 'Peter Garret es un joven fotógrafo deportivo que vive atormentado por el recuerdo de su padre, que sacrificó su vida durante una escalada para salvarlo a él y a su hermana Annie. Con los años, Annie se ha convertido en una experta escaladora que forma parte de un equipo de ascensión al K-2. Sin embargo, cuando un error en la previsión meteorológica provoca un grave accidente en el que se ve implicada, Peter decide arriesgar su vida junto a otros voluntarios para rescatarla.', trailer_url = 'https://www.youtube.com/watch?v=pRdFuZSW4-Y' WHERE id_api = 'tt0190865';

UPDATE Contenido SET id_tmdb = 462, descripcion = 'Erin Brockovich es una madre soltera que consigue un puesto de trabajo en un pequeño despacho de abogados. Su personalidad poco convencional hará que sus comienzos no sean demasiado alentadores, pero todo cambiará cuando decida investigar el extraño caso de unos clientes que padecen una sospechosa enfermedad.', trailer_url = 'https://www.youtube.com/watch?v=jjqUUxIy_yk' WHERE id_api = 'tt0195685';

UPDATE Contenido SET id_tmdb = 10393, descripcion = 'Una brutal huelga de la Liga Nacional de Fútbol americano, deja en el aire los anhelados play-off. Los Washington Sentinels tenían al alcance de la mano llegar a la final, pero como no pueden contar con sus estrellas deciden contratar temporalmente a un grupo de aficionados para quienes ésta es la gran oportunidad de sus grises y anodinas vidas.', trailer_url = 'https://www.youtube.com/watch?v=Ivh1DoSVfyo' WHERE id_api = 'tt0191397';

UPDATE Contenido SET id_tmdb = 10468, descripcion = 'Como consecuencia de su adicción al alcohol, la periodista Gwen Cummings tiene un accidente de tráfico. Debido a este hecho se ve obligada a ingresar en una clínica de desintoxicación.', trailer_url = 'https://www.youtube.com/watch?v=-dwp9ea0sSY' WHERE id_api = 'tt0191754';

UPDATE Contenido SET id_tmdb = 2382, descripcion = 'Serie juvenil, ambientada en los años 80, que relata las relaciones de amistad, problemas y situaciones a las que se enfrentan dos grupos de adolescentes en el instituto. Los problemas propios de su edad, sumados a las situaciones personales de cada uno, darán lugar a divertidas tramas donde los jóvenes de hoy en día se podrán ver identificados sin problema.', trailer_url = 'https://www.youtube.com/watch?v=E0oJ-uYWakw' WHERE id_api = 'tt0193676';

UPDATE Contenido SET id_tmdb = 9532, descripcion = 'Al subir a un avión con destino a Paris, junto con sus compañeros de clase, Alex tiene una premonición, por lo que desembarca justo antes de despegar junto a seis de sus amigos y una profesora. Poco después el aparato explota en el aire. El grupo de supervivientes se verá perseguido por la dama de la guadaña, la propia muerte, que no se dará por vencida. Acosado por el FBI que considera a Alex responsable del accidente y perseguido por sus propios miedos, el joven deberá descubrir que las coincidencias y los accidentes no son algo casual.', trailer_url = 'https://www.youtube.com/watch?v=9hvUxRGeBhA' WHERE id_api = 'tt0195714';

UPDATE Contenido SET id_tmdb = 585, descripcion = 'Monsters Inc. es la mayor empresa de miedo del mundo, y James P. Sullivan es uno de sus mejores empleados. Asustar a los niños no es un trabajo fácil, ya que todos creen que los niños son tóxicos y no pueden tener contacto con ellos. Pero un día una niña se cuela sin querer en la empresa, provocando el caos.', trailer_url = 'https://www.youtube.com/watch?v=feRnlEHTCY0' WHERE id_api = 'tt0198781';

UPDATE Contenido SET id_tmdb = 10471, descripcion = 'Secuela de "Friday". Tras la inminente venganza por parte de Deebo tras su fuga carcelaria, Craig decide pasar una temporada mientras se calmen las cosas con su tío y su primo, que viven en Rancho Cucamonga tras haber ganado la lotería.', trailer_url = 'https://www.youtube.com/watch?v=mKepqz19Qb0' WHERE id_api = 'tt0195945';

UPDATE Contenido SET id_tmdb = 9398, descripcion = 'Derek Zoolander (Stiller) ha sido el modelo masculino más cotizado durante los últimos 3 años. La noche de la gala que podría suponer su cuarta corona, el galardón se lo lleva un nuevo modelo llamado Hansel (Wilson). Derek queda en entredicho y como un idiota, y decide retirarse. Sin embargo, un prestigioso diseñador le pide que desfile para él.', trailer_url = 'https://www.youtube.com/watch?v=YtQq0T3ExLs' WHERE id_api = 'tt0196229';

UPDATE Contenido SET id_tmdb = 8870, descripcion = 'La comandante de misión Kate Bowman es la piloto y comandante de la misión más importante del siglo XXI: salvar a la raza humana. Es el año 2050, la Tierra se está muriendo, y colonizar Marte es la única alternativa a la destrucción. Bowman y su tripulación han hecho este viaje para investigar a qué se ha debido el fallo del proyecto Mars Terra-Forming, y repararlo. Pero lo que sucede cuando llegan allí es bastante más aterrador de lo que cualquiera podría haber adivinado: un aterrizaje forzoso los deja sin equipo científico, de comunicación y de salvamento, y hace que su robot de exploración y cartografía militar falle, convirtiéndose en su enemigo. Desafiando las órdenes de Houston, Bowman se niega a abandonar a Gallagher, con el que comparte un intenso lazo afectivo, y al resto del equipo, y trata de guiarles de vuelta a las alturas.', trailer_url = 'https://www.youtube.com/watch?v=GROpZD40mk0' WHERE id_api = 'tt0199753';

UPDATE Contenido SET id_tmdb = 8848, descripcion = 'Inglaterra, 1971. Un grupo de ladrones planea y ejecuta un golpe maestro: un espectacular atraco a un banco. Pero, además del dinero y las joyas, forman parte del botín ciertos documentos que permitirían sacar a la luz un escándalo de corrupción que involucra no sólo a altos funcionarios del gobierno británico, sino también a un miembro de la familia real.', trailer_url = 'https://www.youtube.com/watch?v=tdiWAhlVOBY' WHERE id_api = 'tt0200465';

UPDATE Contenido SET id_tmdb = 12508, descripcion = 'Chris Cole (Mark Wahlberg) es un fanático obsesivo del grupo heavy Steel Dragon. Los admira tanto que con varios amigos ha formado un "grupo tributo", es decir, un grupo de rock especializado en reproducir fielmente las canciones de Steel Dragon. Luego de algunas discusiones internas, Chris es expulsado del grupo que él mismo fundó. Entonces, llega la llamada mágica. Parece que el vocalista real de Steel Dragon va a abandonar la banda y el resto de los integrantes buscan un reemplazo. Por azar vieron en vídeo una presentación del grupo tributo en el que cantaba Chris y quedaron impresionados por su talento, por lo que lo invitan a hacer una audición. Chris y Emily -su novia/manager (Jennifer Aniston)- viajan a Los Angeles y finalmente Chris es seleccionado como reemplazo.', trailer_url = 'https://www.youtube.com/watch?v=ZpSUqTJ7X6g' WHERE id_api = 'tt0202470';

UPDATE Contenido SET id_tmdb = 6282, descripcion = 'A sus 21 años, Violet Sanford llega a Nueva York con la esperanza de convertirse en letrista. Pero sus sueños de dedicarse al mundo de la música quedan aparcados momentáneamente por el éxito que alcanza trabajando como camarera en el bar Coyote. El bar Coyote es un nuevo club nocturno y el punto más caliente de la ciudad. Cuenta con un ambicioso plantel de chicas, todas jóvenes y muy atractivas. Lil es el cerebro y la estricta propietaria del local, que reina con autoridad sobre sus chicas. Entre ellas están la coqueta Cammie, la cabezota y variable Rachel y Zoe, la que más propinas consigue. Las "chicas Coyote", como las llaman cariñosamente, provocan a los clientes y a los medios de comunicación con sus atrevidos atuendos, y convierten el bar Coyote en el punto de atracción de los chicos que merodean por la zona.', trailer_url = 'https://www.youtube.com/watch?v=2lqWOOHOwlE' WHERE id_api = 'tt0200550';

UPDATE Contenido SET id_tmdb = 824, descripcion = 'París, alrededor de 1900. El mundo ha sido conquistado por la revolución de Bohemia. Satine, la estrella más rutilante del Moulin Rouge, encandila a toda la ciudad con sus bailes llenos de sensualidad y su enorme belleza. Atrapada entre el amor de Christian, un joven escritor, y la obsesión del duque, lucha por hacer realidad su sueño de convertirse en actriz. Pero, en un mundo en el que vale todo excepto enamorarse, nada es fácil.', trailer_url = 'https://www.youtube.com/watch?v=2PpgPxjzbkA' WHERE id_api = 'tt0203009';

UPDATE Contenido SET id_tmdb = 1588, descripcion = 'Historia sobre una competición de "cheerleaders". Las animadoras del equipo de los "Toro" tienen una coreografía explosiva para hacerse con el trofeo del campeonato nacional. Pero para la nueva capitana el camino a la victoria se tuerce cuando descubre que esta misma coreografía ha sido robada de las animadoras de los "Clover" por la capitana previa. Mientras que ellas desesperadamente buscan una nueva coreografía, las "Clover", con Isis al mando, tienen sus propios problemas: deben conseguir bastante dinero para cubrir los gastos de desplazamiento al campeonato. La tensión sube, el tiempo se agota y ambas capitanas dejan sus equipos exhaustos. Sólo uno puede llevar el trofeo a casa, que ganen las que mejor se menean.', trailer_url = 'https://www.youtube.com/watch?v=_CCQC8LhLdc' WHERE id_api = 'tt0204946';

UPDATE Contenido SET id_tmdb = 11826, descripcion = 'Tras haber pasado una temporada entre rejas, Gal Dove vive ahora felizmente retirado en un chalet de la Costa del Sol española, junto a su mujer, a quien adora. Sin embargo, su felicidad se empaña con la llegada de Don Logan, un antiguo compinche que intenta convencerle de que vuelva a Londres para un último gran golpe.', trailer_url = 'https://www.youtube.com/watch?v=osexRaPM_Gc' WHERE id_api = 'tt0203119';

UPDATE Contenido SET id_tmdb = 688, descripcion = 'El presidente demócrata Josiah Bartlet lidera una de las naciones más poderosas del mundo con la devoción y la convicción de creer fervientemente en que lo que hace es lo mejor para su país. La serie se desarrolla, fundamentalmente, en los pasillos, despachos y salas de la Casa Blanca, mostrándonos los entresijos del febril trabajo que allí tiene lugar y los problemas diarios a los que se han de enfrentar. Es en esta atmósfera de conflicto donde el equipo de la Casa Blanca va a tener que esforzarse hasta límites insospechados para seguir defendiendo su credibilidad de cara a las reelecciones y a los Estados Unidos de amenazas externas.', trailer_url = 'https://www.youtube.com/watch?v=S1-ip47WYWc' WHERE id_api = 'tt0200276';

Josh despierta después de la operación, que ha sido un éxito.  Capturan a un joven que resulta ser miembro de un grupo racista cuyo objetivo no era el presidente, sino Charlie, por su relación con Zoey.', 40, '2000-10-04');

Charlie se siente responsable del incidente porque él era el objetivo del tiroteo, esto le hace estar irritable y rechazar el consuelo que le ofrece Zoey. Durante una recepción en la Casa Blanca con locutores de radio, el odio de Bartlet por la intolerancia le hace desafiar a un conocido presentador famoso por su fanatismo y sus prejuicios, que expresa libremente utilizando la Biblia como justificación.', 41, '2000-10-18');

La republicana Ainsley Hayes tiene que enfrentarse a un difícil primer día de trabajo en la Casa Blanca, donde está en franca minoría por su inclinación política. Tiene un despacho pequeño y húmedo y debe aguantar, no sólo la desconfianza de sus compañeros, sino también la patente animadversión de su jefe. Sam quiere demandar a un grupo que está presionando a Josh. Y Abby informa a Bartlet de que su recuperación permite que reanuden las relaciones maritales.', 41, '2000-10-25');

Una analista política republicana, y muy atractiva, llamada Ainsley Hayes derrota de forma aplastante a Sam durante un debate televisado. A pesar de sus duras críticas al partido demócrata, Bartlet se queda impresionado por la pasión y el sentido del deber que demuestra Ainsley; y le pide a un desconfiado Leo que le ofrezca un empleo, que desencadena la rabia del resto del equipo.', 41, '2000-11-01');

C.J. se siente decepcionada porque Danny desaprovecha la oportunidad de trabajar con ella fuera de la sala de prensa, lo que les habría dado ocasión de salir juntos guardando las apariencias.', 40, '2000-11-08');

Toby quiere que le den a la problemática hermana de Leo un puesto en educación. C.J. tiene que elegir un pavo y Charlie recibe la misión de encontrar el cuchillo perfecto para trinchar.', 40, '2000-11-22');

Mientras tanto, C.J. ayuda a un turista que se pone muy nervioso después de ver un cuadro que afirma le robó a su familia el gobierno francés durante la ocupación nazi. Charlie debe convencer al presidente de que es imposible que se empeñe en firmar personalmente más de un millón de felicitaciones de Navidad. En este capítulo interviene el violonchelista YO-YO-MA interpretándose a sí mismo.', 41, '2000-12-20');

Mientras tanto, cinco agentes de la lucha anti-droga son secuestrados por un narcotraficante colombiano. Bartlet también tiene que enfrentarse al enfado de su mujer porque, escuchando su discurso, ha tenido la sensación de que Bartlet tiene intención de presentarse para un segundo mandato, cosa que le había prometido no hacer.', 41, '2001-02-07');

Más tarde Bartlet tiene que aceptar con tristeza el plan de Leo para que el gobierno colombiano libere al narcotraficante sin que parezca que los Estados Unidos cedieron a las exigencias de los secuestradores. Los rehenes regresan a casa... y también lo hacen los cuerpos de los agentes asesinados. Abbey le dice a su marido que le preocupa que la esclerosis múltiple le incapacite durante su mandato.', 41, '2001-02-14');

El problema empeora para Bartlet cuando Ellie, su hija mediana, se pone del lado de Griffith, que al mismo tiempo es su madrina. Gracias a la explicación de la doctora, el presidente consigue comprender el comportamiento de su hija y acaba por no aceptar la dimisión de Griffith cuando ésta se la presenta. Por otra parte, Toby le pide a su combativa ex mujer, la congresista Andrea Wyatt, que le ayude a enfrentarse a una influyente comisión. Un director de cine acusa a Bartlet de ser un cobarde.', 41, '2001-02-21');

Toby, que ha participado en multitud de protestas, asiste a una manifestación contra la Organización Mundial del Comercio en la que la muchedumbre se niega a escucharle, hasta que tiene una idea muy persuasiva. C.J. se reúne con un grupo de cartógrafos.', 41, '2001-02-28');

Cuando Donna se entera de que el nieto del senador sufre dicha enfermedad, Josh se pone de su lado para hacer que se añadan los cambios que propone. Toby se pregunta cuáles son los motivos que han llevado al vicepresidente a amonestar a las tabacaleras.', 41, '2001-03-14');

Toby está furioso y no tarda en enfrentarse al presidente. Josh, Donna, Sam y Ainsley intentan escribir algunos chistes para el discurso que Bartlet tiene que pronunciar en una cena.', 41, '2001-04-04');

Además, un incidente en Puerto Príncipe en el que es secuestrado el presidente de Haití plantea la intervención del ejército en el conflicto.', 40, '2001-05-09');

Josh, tenía previsto irse de vacaciones pero surge una crisis en Vieques, Puerto Rico. Se trata de una zona donde Estados Unidos realiza pruebas militares.

Sam tiene que reunirse con Robert Engler, un excéntrico político que cree que la reserva de oro de los Estados Unidos está perdiendo una fortuna en lingotes de oro.', 40, '2002-01-30');

C.J. recibe la noticia de han apresado a un periodista norteamericano en la República Democrática del Congo, así que que inicia las acciones necesarias para negociar un rescate y conseguir su liberación.

Toby ha escrito un discurso en el que se deja ver una ataque demasiado directo a los países árabes proclamando los valores americanos, que hace que su ex mujer, la congresista Andrea "Andy" Wyatt, se ponga furiosa.

Mientras, Sam pide a la abogada republicana Ainsley Hayes que estudie una propuesta de ley por la que se realice el pago de la deuda que Estados Unidos tiene con las Naciones Unidas, a cambio de ciertas peticiones.', 41, '2002-02-06');

Para complicar la situación internacional, Taiwan quiere probar unos misiles que ha comparado a los Estados Unidos. La realización de las pruebas hace que su vecina, China, se ponga en alerta máxima y amenace con hacer lo mismo con sus misiles. El equipo de Bartlet debe desplegar sus dotes diplomáticas para solventar la situación.', 41, '2002-02-27');

Pero cuando acude a la fiesta el embajador británico, se produce un pequeño incidente diplomático, ya que ve entre los invitados a una persona que su gobierno considera un terrorista.

A esto se le añade otra complicación para Abbey, ya que recibe la noticia de que puede ser suspendida durante un año del ejercicio de su profesión. Lejos de deprimirse decide reunirse con C.J., Donna y Amy para conversar y beber juntas.', 39, '2002-03-06');

La Casa Blanca va a dar una cena de gala a una poetisa que acaba de ser laureada, pero surge un problema, la mujer piensa criticar la política del Presidente en su discurso. Tobby tiene que intentar convencerla que no lo haga.', 41, '2002-03-27');

El Gabinete no encuentra ninguna fórmula electoral que permita el relevo del Vicepresidente. Esto preocupa a los asesores de Bartlet, ya que piensan que el actual puede perjudicar las posibilidades del Presidente en la campaña.

Leo acude a las reuniones de alcohólicos anónimos y descubre que también asiste a ellas el Vicepresidente. El asesor del Presidente considera que esa información debe ser conocida por su jefe.', 39, '2002-04-03');

Sam está ultimando los detalles, junto a sus homónimos del Kremlin, para la entrevista que van a tener los dos altos dignatarios en una cumbre en Helsinki.', 41, '2002-05-01');

El servicio secreto ha detectado que están tramando ataques contra distintas bases militares, y que uno de los objetivos puede ser la Casa Blanca.

Debido a las amenazas de muerte que ha recibido C.J., el servicio secreto le ha asignado un equipo de seguridad. A pesar de eso, ella sigue recibiendo amenazas de muerte, que van subiendo de tono. En el último mensaje recibido se muestra que la están siguiendo a todas partes y en que le anuncian que su muerte está próxima.', 40, '2002-05-08');

Donna es enviada a Dakota del Norte, en representación de la Casa Blanca, para tratar de disuadir a sus habitantes de la petición que han hecho de eliminar la palabra “Norte” de su nombre.', 41, '2002-05-15');

Aunque la caída de la bolsa inquieta, los colaboradores creen que cuando abra la bolsa de Japón se recuperarán. CJ pide a Charlie que se ocupe de Anthony, el "hermano" pequeño de Simon, que aún no se ha sobrepuesto de su muerte.', 41, '2002-09-25');

Aunque la caída de la bolsa inquieta, los colaboradores creen que cuando abra la bolsa de Japón se recuperarán. CJ pide a Charlie que se ocupe de Anthony, el "hermano" pequeño de Simon, que aún no se ha sobrepuesto de su muerte.', 40, '2002-09-25');

El equipo del Presidente plantea la campaña y los discursos en los que se deberá abordar la educación. George y Toby coinciden en proponer una desgravación importante en la matrícula universitaria.', 41, '2002-10-02');

Al finalizar uno de los debate de ensayo, Toby se encuentra con su ex mujer, la congresista Andrea Wyatt “Andy” (Katlen York), que ha sido contratada para que asesore en la campaña electoral.

La hora decisiva ha llegado y todas las miradas están puestas en los dos principales candidatos. Sólo uno puede ser el vencedor.

Mientras, Leo y la abogado Jordan Kendall (Joana Geason) están negociando la posibilidad de encontrar una vía de salida al conflicto generado por el asunto de Qumar. Sam intenta persuadir a uno de los miembros de la campaña, Will Beiley (Josh Malina), para que se incluya en la votación para las presidenciales a un miembro que acaba de ser cesado, y podría dar mala imagen a Bartlet.', 41, '2002-10-30');

Toby y su ex mujer, la congresista Andrea "Andy" Wyatt –personaje interpretado por la actriz Kathleen York-, deben plantearse una decisión que afectará a su futuro profesional y personal.

A la oficina de la Casa Blanca llega un nuevo oficial de la Marina, el capitán de fragata Jack Ross –personaje interpretado por Christian Slater-. El joven causa furor entre las féminas y Donna intenta conquistarlo.', 41, '2002-11-13');

Además, empiezan a surgir tensiones entre el Pentágono y el equipo de la Casa Blanca, debido a que se han producido varias filtraciones.', 40, '2003-02-05');

Mientras, las investigaciones que se están realizando sobre las filtraciones, hacen que se sospeche de Donna.', 41, '2003-02-12');

Josh sigue haciendo entrevistas para poder contratar a un nuevo abogado asociado.Para poder bajar la tensión en la que se encuentran, el equipo del presidente decide jugar una partida de cartas. Durante la misma, los compañeros le toman el pelo a C.J, que afirma que durante el equinoccio los huevos de gallina se pueden poner de pie sin que se caigan.', 41, '2003-04-23');

El equipo del Presidente tiene que buscar un sustituto al Vicepresidente, mientras C.J, intenta, por todos los medios, ganar tiempo para que no se publique una información en la que se vincula al Presidente con el asesinato del ministro de defensa de Qumar.

Zoey, la hija de Bartlet, está encantada porque es el día de la fiesta de su graduación. Charlie, que sigue albergando esperanzas, le ha comprado un regalo muy especial, sin saber que la joven corre un gran peligro.', 41, '2003-05-07');

meramente profesional.', 41, '2003-10-08');

Mientras Jai (Tony Lee) está ofreciendo un concierto en la Casa Blanca, el Presidente decide sentarse junto a él para interpretar una pieza. En ese momento el pianista le hace llegar un mensaje en el que le informa su intención de huir de su país. A pesar de la apasionada argumentación que C.J. realiza a favor de la petición de asilo, queda también claro que concederla supondría bloquear las delicadísimas relaciones con Corea del Norte. Mientras, el equipo del Presidente propone como nuevo Vicepresidente al Congresista de Colorado Robert Russell (interpretado por Gary Cole).', 40, '2003-10-22');

Tras ser el centro de los elogios de la prensa, Josh tiene que enfrentarse con un senador demócrata de Idaho. El senador Carric (Tom Skerritt) está empeñado en condicionar su voto a la aprobación de la construcción de un tipo de misil, que resulta muy caro e inservible para el ejército. 

Mientras, el vicepresidente le ofrece a Will el puesto de Director de Comunicaciones. Toby le presiona para que no lo acepte.

Por su parte, el Presidente reprocha a Amy el haberse extralimitado en sus funciones. Leo y C.J. también tienen desavenencias.', 40, '2003-10-29');

Mientras tanto, en la Casa Blanca, Leo (John Spencers) se impacienta por la tardanza del Presidente debido a la cantidad de problemas que reclaman su presencia en Washington.Además, la perdida del voto de un senador demócrata, hace que Donna (Jannel Moloney) esté preocupada porque teme convertirse en el chivo expiatorio.', 40, '2003-11-05');

El equipo de asesores del presidente Bartlet se enfrenta con el nuevo portavoz republicano, Jeff Haffley (Steven Culp) en el complejo tema del presupuesto federal.

Toby cree que ha llegado el momento de sugerir la dimisión al presidente del Tribunal Supremo, quien además de ser un hombre de avanzada edad tiene la salud muy delicada. El designado para insinuarle esta posibilidad es Joe Quincy (Matthew Perry), hombre de confianza del magistrado, al que considera su mentor y maestro. 

Pero surgen tensiones entre el pragmatismo de Toby y las convicciones de Joe. Cuando se acerca la fecha límite de la negociación presupuestaria, Ángela Blake (Michael Hyatt) apuesta con cartas que ponen en juego las promesas electorales de Bartlet.', 40, '2003-11-12');

Bartlet ve como el portavoz republicano ha conseguido bloquear los presupuestos del Gobierno Federal. Esto supone que no hay dinero para poder pagar al personal que trabaja en La Casa Blanca, por lo que Leo, Josh y Toby tienen que empezar a despedir a sus colaboradores más cercanos.

En realidad, es un intento por parte de los republicadnos de poner contra las cuerdas a Bartlet, ya que esa crisis es, a los ojos de la opinión pública, un fracaso de la política de los demócratas.

Ante la insistencia de Bartlet en no ceder, a Leo se le ocurre una solución para romper el bloque: conseguir la colaboración de la Primera Dama.', 40, '2003-11-19');

Bartlet quiere celebrar la Navidad con sus hijas Zoey (Elisabeth Moss), Liz (Annabeth Gish) y Ellie (Nina Siemaszko) pero el ambiente navideño de la Casa Blanca se interrumpe bruscamente cuando notifican al presidente que varios cooperantes han sido encarcelados en Sudán.

Durante la cena Liz y su marido, Doug (Steven Eckholdt) anuncian que éste quiere presentarse a congresista por New Hampshire. Esta noticia sorprende fuertemente a Josh.

Para complicar aún más la cena, informan al equipo del presidente de la retirada de la licencia a un médico en Oregón por ayudar a morir a un paciente con una enfermedad terminal. Esta noticia pone en guardia al director de comunicación, Toby, ya que el incidente podría desencadenar un espinoso debate que pusiera de nuevo sobre la mesa la enfermedad del presidente Bartlet.', 41, '2003-12-03');

Bartlet vuela en el Air Force One para acudir a los funerales de Lassiter, junto a él viajan dos ex Presidentes. Durante el trayecto, el actual y los anteriores mandatarios cambian impresiones sobre algunas de las decisiones que se han tomado en el pasado y que afectan al mandato actual.

Entre estas decisiones, están las que han provocado que se produzcan disturbios en Arabia Saudí, además del secuestro de 200 personas -algunas de ellas norteamericanas- y de poner peligro la reserva del petróleo mundial.

La conclusión que obtiene Bartlet es que “los dogmas del pasado ya no son válidos en el tormentoso presente”.', 41, '2004-01-07');

Abbey está decidida a que su marido indulte al líder de una tribu que ha sido acusado del el asesinato de dos agentes del FBI en Dakota del Norte. Y Toby decide contratar a Rena (Melissa Marsala), como su nueva ayudante.', 40, '2004-01-14');

Estas gestiones requieren que nadie de su equipo sepa nada, por lo que sus compañeros empiezan a encontrarse algo molestos por el secretismo de Toby. Con esta importante y compleja apuesta, Toby se compromete a que dimitir si no logra los apoyos necesarios para conseguir su misión.', 41, '2004-02-04');

La investigación revela que hay un nuevo actor que se ha instalado en el escenario nuclear. 

Josh tiene que lidiar con una comisión de la NASA, que quieren saber cuales son los planes del gabinete con respecto al futuro de la exploración espacial. Al frente de la misma se encuentra Alex Moreau – personaje interpretado por la actriz Christina Chang-, que resulta ser más dura de lo que ha previsto el asesor.

Leo intenta por todos los medios que el Vicepresidente Russell (Gary Cole), se mantenga ocupado y no se inmiscuya en los asuntos que está llevando.', 40, '2004-02-11');

Pero la sospecha que tienen tanto el Presidente como su equipo, es que en realidad se están escribiendo exclusivamente para favorecer las aspiraciones del senador Hoynes, que quiere llegar a ser el nuevo Presidente de los Estados Unidos.

Mientras a C. J. no le queda más remedio que frenar a un entrevistador de televisión que intenta conseguir popularidad a su costa.', 40, '2004-02-25');

Debido a la muerte repentina de un juez del Tribunal Supremo, Josh y Toby pelean duro para encontrar un sustituto conveniente. La sala de espera presidencial se llena de candidatos moderados y de muy diversas tendencias. Los asesores ponderan los pros y contras que implicarían la elección de cualquiera de ellos. En ninguno de los casos la decisión sería descabellada, excepto en el caso de un candidato. O, mejor dicho, una candidata de ideas feministas radicales y brillantes.', 39, '2004-03-24');

Mientras tanto, C.J. (Allison Janney) se siente frustrada con la normativa de la nueva Comisión Federal de Comunicaciones que permite mayor concentración de capital en las cadenas de televisión. Donna (Janel Moloney) le reprocha a Josh no tener mayores oportunidades de progresar en su carrera.', 41, '2004-04-21');

La detección de una sustancia contaminante pone en situación de emergencia a la Casa Blanca.Toda el ala oeste debe ser sometida a un aislamiento hasta que se pueda determinar la naturaleza y el origen de las partículas.

El Presidente Bartlet (Martin Sheen) es llevado al Búnker junto con Charlie (Dulé Hill) y su secretaria personal. Allí es sometido a un reconocimiento médico. Este aislamiento inesperado propicia ciertas confidencias e incluso velados reproches entre Leo (Jon Spencer) y la Primera Dama.

Otros miembros del equipo de asesores que deberan permanecer encerrados en el lugar en el que estaban son Donna (Janel Moloney), que esta con C.J (Allison Janney); Toby (Richard Schiff) con Will (Joshua Malina) y Josh (Bradley Whitford) con Kate.', 41, '2004-04-28');

UPDATE Contenido SET id_tmdb = 11978, descripcion = 'La historia de Carl Brashear, un hombre que combatió el racismo y se convirtió en el primer oficial afroamericano de la armada americana. La acción se desarrolla durante más de 30 años, periodo en el que destaca su relación con Billy Sunday , un oficial rebelde de alta graduación y experto buceador que fue degradado por permitir la graduación de Brashear.', trailer_url = 'https://www.youtube.com/watch?v=iC3pHZwdmGg' WHERE id_api = 'tt0203019';

UPDATE Contenido SET id_tmdb = 10402, descripcion = 'Deuce Bigalow trabaja de limpiador en un acuario hasta que un día pierde su empleo. Más tarde consigue un empleo temporal en la casa de un gigoló, pero cuando accidentalmente la destruye se verá obligado a trabajar como chico de compañía. Tendrá una serie de variopintas clientes, enamorándose de una de ellas', trailer_url = 'https://www.youtube.com/watch?v=vcfyZr5buDA' WHERE id_api = 'tt0205000';

UPDATE Contenido SET id_tmdb = 9816, descripcion = 'Sara Johnson (Julia Stiles) es una chica blanca de clase media de Chicago que arma un pequeño revuelo cuando, a la muerte de su madre, se matricula en un instituto de alumnado mayoritariamente negro. Sara se ha criado en un pequeño pueblo de Illinois, adora el ballet y sueña con ir a Juilliard. Cuando su madre muere en un accidente de coche, olvida sus sueños y se reúne con su padre Roy, del que hacía mucho tiempo que estaba separada, y que ahora trabaja como músico en el South Sidc de Chicago. Cuando empieza el curso, se encuentra con un mundo muy diferente al suyo, tanto racial como culturalmente. Allí conoce a Chenille, una madre soltera negra, cuyo hermano, Derek (Sean Patrick Thomas), es un chico atractivo, con talento y muy popular tanto en el instituto como en un club de hip-hop llamado Stepps. Allí, Derek introduce a Sara en la cultura del hip-hop.', trailer_url = 'https://www.youtube.com/watch?v=gV7MWxwxa1I' WHERE id_api = 'tt0206275';

UPDATE Contenido SET id_tmdb = 9693, descripcion = 'Año 2027: el ser humano está al borde de la extinción: los hombres han perdido la capacidad de procrear y se ignora por qué razon todas las mujeres del planeta se han vuelto estériles. Al mismo tiempo, el mundo se estremece cuando muere un muchacho de 18 años, la persona más joven de la Tierra. Se vive, pues, una situación de caos galopante. En tales circunstancias, Theo (Clive Owen), un desilusionado ex-activista radical de Londres convertido en burócrata, es contratado por Julian (Julianne Moore) para que proteja a una mujer que puede tener el secreto de la salvación de la humanidad, la persona más valiosa de la Tierra...', trailer_url = 'https://www.youtube.com/watch?v=jSJKgHLlRFQ' WHERE id_api = 'tt0206634';

UPDATE Contenido SET id_tmdb = 10866, descripcion = 'Han empezado las vacaciones y Lewis está listo para marcharse en coche con Venna, la chica de sus sueños, que acaba de romper con su novio. Pero sus planes se van al garete cuando tiene que desviarse para recoger a Fuller, su hermano mayor, famoso por meterse en líos, que ha vuelto a hacer de las suyas.', trailer_url = 'https://www.youtube.com/watch?v=udKUOQ2czWg' WHERE id_api = 'tt0206314';

UPDATE Contenido SET id_tmdb = 107, descripcion = 'Franky es una ladrón de diamantes que tiene que entregar una enorme pieza a su jefe Avi, pero en el camino es tentado por Boris para apostar en un combate ilegal de boxeo. En realidad, es una trampa para atracarle por lo que, cuando Avi se entera, contrata a Tony para encontrar a Franky y el diamante. Pronto se descubre el triste destino de Franky, y la caza y captura de la gema desaparecida lleva a todo el mundo a un juego de locos que corre el riesgo de descontrolarse, donde el engaño, el chantaje y el fraude se mezclan de forma sangrienta con perros, diamantes, boxeadores y gran variedad de armas en una caótica merienda de negros.', trailer_url = 'https://www.youtube.com/watch?v=IXYy07RTMnI' WHERE id_api = 'tt0208092';

UPDATE Contenido SET id_tmdb = 77, descripcion = 'Leonard Shelby sigue la pista del hombre que violó y asesinó a su mujer. Sin embargo, la dificultad de localizar al asesino de su esposa se ve agravada por el hecho de que padece una forma rara e intratable de pérdida de memoria a corto plazo. Aunque puede recordar detalles de la vida antes de su accidente, Leonard no puede recordar qué ha pasado hace quince minutos, adónde va o por qué.', trailer_url = 'https://www.youtube.com/watch?v=mV9l1enMqvk' WHERE id_api = 'tt0209144';

UPDATE Contenido SET id_tmdb = 3981, descripcion = 'El ejecutivo de publicidad Nick Marshall es un arrogante machista, pero ¿qué pasa con un hombre machista, cuando de repente escucha lo que piensan las mujeres? Nick no consiguió un ascenso que daba por seguro, porque se lo dieron a una mujer: Darcy. Pero después de un accidente, es capaz de oír los pensamientos de las mujeres, y utiliza este talento para trabajar contra Darcy, su nueva jefa.', trailer_url = 'https://www.youtube.com/watch?v=lx_0DuJn2Zc' WHERE id_api = 'tt0207201';

UPDATE Contenido SET id_tmdb = 9600, descripcion = 'El agente del FBI Malcolm Turner es un hombre duro y astuto, pero sobre todo un consumado maestro del arte del disfraz. Su última misión lo lleva a una pequeña ciudad del sur de los Estados Unidos, donde debe atrapar a un sanguinario ladrón de bancos que se acaba de fugar de prisión. Malcolm monta un puesto de vigilancia en la casa de una arisca matriarca, la Gran Abuela, que está a punto de recibir la visita de su nieta Sherry, ex-novia del presidiario, y de su hijo. Aunque el plan es muy sencillo, surge una dificultad nada desdeñable: la Gran Abuela se ha ido inesperadamente la ciudad, así que Malcolm tendrá que ingeniárselas para hacerse pasar por ella.', trailer_url = 'https://www.youtube.com/watch?v=QPEzzJYsPbY' WHERE id_api = 'tt0208003';

UPDATE Contenido SET id_tmdb = 2018, descripcion = 'Mary Fiore (Jennifer Lopez) es la más prestigiosa organizadora de bodas de San Francisco. Está tan ocupada en hacer realidad los sueños de los demás, que no tiene tiempo para ocuparse de su propia vida. Un día, por casualidad, conoce a un apuesto médico que le salva la vida y del que se queda prendada. Lo malo es que resulta ser su próximo cliente.', trailer_url = 'https://www.youtube.com/watch?v=KAuxlHrDZJ4' WHERE id_api = 'tt0209475';

UPDATE Contenido SET id_tmdb = 1734, descripcion = 'Han pasado diez años, Rick O''Connell se ha casado con Evelyn, y ambos son padres del pequeño Alex, de ocho años. Cuando, tras una serie de acontecimientos, la momia del antiguo sacerdote egipcio Im-Ho-Tep es resucitada por una extraña secta en el British Museum, y la maldición milenaria del Rey Escorpión -que seis mil años atrás traicionó al dios Anubis- lo devuelve a la vida, el choque entre ambas fuerzas malignas desencadenará el caos en el mundo... si Rick y Evelyn no consiguen evitarlo.', trailer_url = 'https://www.youtube.com/watch?v=ptmLrNpmcBo' WHERE id_api = 'tt0209163';

UPDATE Contenido SET id_tmdb = 8843, descripcion = 'Catherine Deane es una psicoterapeuta que forma parte de un revolucionario tratamiento que le permite literalmente introducir su mente en la de sus pacientes. Sus experiencias con este método cobran un giro inesperado cuando un agente del FBI le llega con una petición desesperada: introducirse en la mente de un asesino en serie, Carl Stargher, que se encuentra en coma tras haber secuestrado y atrapado a una mujer cuya vida está en serio peligro si no consiguen descubrir su paradero.', trailer_url = 'https://www.youtube.com/watch?v=44jpefZclO4' WHERE id_api = 'tt0209958';

UPDATE Contenido SET id_tmdb = 13483, descripcion = 'Clay Beresford (Hayden Christensen) es un joven multimillonario que debe someterse a un transplante de corazón. Para ello, deja que su mejor amigo, el doctor Jack Harper (Terrence Howard), sea el encargado de realizar la operación. Durante la intervención, Clay experimenta un extraño fenómeno que le hace estar consciente y completamente paralizado mientras le operan. Mientras tanto, su novia, Sam (Jessica Alba) debe hacer frente a una serie de decisiones que serán determinantes para el futuro de Clay. Según transcurre la acción, todo da un vuelco, haciendo que nada sea lo que en principio parecía.', trailer_url = 'https://www.youtube.com/watch?v=RzR2J7_QBHg' WHERE id_api = 'tt0211933';

UPDATE Contenido SET id_tmdb = 9871, descripcion = 'Brigitte y su hermana Ginger son dos adolescentes muy unidas... y aburridas de su rutinaria vida. Pero cierta noche en que deciden gastar una broma a un chico, Ginger acaba siendo atacada por una extraña criatura. Aunque se recupera milagrosamente de las heridas, Ginger no está bien: comienzan a crecerle pelos en las cicatrices, una cola asoma por la base de su espina dorsal y siente un deseo irrefrenable de sangre humana... se está convirtiendo en una mujer-lobo. Brigitte tiene que ayudar a su hermana y recurre a Sam, un joven enigmático, con fama de chico malo y muy aficionado a la botánica... Y mientras Brigitte lucha por proteger a Ginger, se convierte en cómplice de sus crímenes violentos e incontrolables', trailer_url = 'https://www.youtube.com/watch?v=011YdVip2KM' WHERE id_api = 'tt0210070';

UPDATE Contenido SET id_tmdb = 387, descripcion = 'Cerca del Atolón Bikini, a algunas leguas bajo el mar, en una ciudad submarina llamada Fondo de Bikini, vive Bob Esponja. No tiene un modo lógico de actuar en la vida, todo lo hace de una manera poco convencional. Sus buenas intenciones y sus ansias de hacer el bien suelen crear bastantes problemas. Bob Esponja ha sido producida en los estudios de Burbank, en California. Fue creado por Steve Hillenburg, el guionista de la serie de culto "La vida moderna de Rocko".', trailer_url = 'https://www.youtube.com/watch?v=0lGyuTtYUJo' WHERE id_api = 'tt0206512';

