UPDATE Contenido SET id_tmdb = 10637, descripcion = 'Corre el año 1971, cuando en la ciudad de Alexandria, Virginia, se tomó la polémica decisión de integrar en el Secundario T.C. Williams a los estudiantes de raza negra con los de raza blanca. Los jugadores blancos veían con temor el ingreso de jugadores negros al equipo, llamado "Los Titanes", pues ponía en peligro sus puestos. Su miedo aumentó cuando el hasta entonces entrenador Bill Yoast es reemplazado en su cargo por Herman Boone, de raza afroamericana.', trailer_url = 'https://www.youtube.com/watch?v=nPhu9XsRl4M' WHERE id_api = 'tt0210945';

UPDATE Contenido SET id_tmdb = 11470, descripcion = 'En el año 2445, la Tierra es un lugar contaminado al que regresan de vez en cuando los hombres para recoger residuos de la vieja civilización. Poco se imaginan los jóvenes e intrépidos exploradores que acaban de aterrizar en la Tierra el destino que les aguarda.', trailer_url = 'https://www.youtube.com/watch?v=RDwYC3W-Fmc' WHERE id_api = 'tt0211443';

UPDATE Contenido SET id_tmdb = 194, descripcion = 'Amélie Poulain (Audrey Tautou) es una joven camarera que vive en París y que tiene una imaginación desbordante. Un día, encuentra una caja con objetos antiguos que pertenecían al antiguo inquilino de su apartamento. Amélie decide devolver la caja a su dueño y ver su reacción. Al ver la felicidad que le provoca, Amélie se propone hacer felices a los demás con pequeños gestos. Así, ayuda a sus vecinos, a sus compañeros de trabajo y a su padre, mientras se divierte con sus ocurrencias. Pero en su búsqueda de la felicidad ajena, Amélie se olvida de la suya propia, hasta que conoce a Nino Quincampoix (Mathieu Kassovitz), un joven coleccionista de fotos que le roba el corazón.', trailer_url = 'https://www.youtube.com/watch?v=UQRxJfMqQcE' WHERE id_api = 'tt0211915';

UPDATE Contenido SET id_tmdb = 676, descripcion = 'Rafe y Danny crecieron juntos en una zona rural estadounidense y su amistad se ha prolongado a lo largo de los años hasta las filas del ejercito del aire, donde los dos son pilotos de combate. Rafe encontró en Evelyn, una valiente enfermera, al amor de su vida, pero pronto es llamado a servir en la fuerza aérea británica para combatir a los nazis como representante del ejército estadounidense. Mientras tanto, Danny y Evelyn son enviados a la base aérea de Pearl Harbor en Hawai. Una vez allí, ambos se enamoran mientras Rafe es derribado en combate. Para sorpresa de ambos, Rafe sobrevive y regresa a Pearl Harbor pero todo se complica cuando se produce un mortal bombardeo por parte del ejercito japonés.', trailer_url = 'https://www.youtube.com/watch?v=lSTHpTsO6ts' WHERE id_api = 'tt0213149';

UPDATE Contenido SET id_tmdb = 1597, descripcion = 'Greg Focker es un enfermero algo patoso que, tras anunciar su compromiso con novia Pam, tiene que pasar unos días con los padres de ella, para conocerles. Su encuentro inicial no será muy afortunado, en especial por las suspicacias que Greg levanta en el estricto padre de la novia, un padre protector exagente de la CIA al que es muy difícil impresionar. Desde el principio, Jim rechaza por completo a Greg, pero a medida que lo conoce mejor, su rechazo se convierte en absoluto desprecio, y se encarga de convertirse en la peor pesadilla de este hombre que, a pesar de amar a su novia y querer dar una buena primera impresión, cada vez se hunde más en el lodo de su propia ineptitud, y deberá luchar mucho para poder cambiar la pésima opinión que tienen de él los parientes de su novia.', trailer_url = 'https://www.youtube.com/watch?v=I18TOdCvvdM' WHERE id_api = 'tt0212338';

UPDATE Contenido SET id_tmdb = 1493, descripcion = 'Cuando el objetivo de un asesino en serie es la ganadora del concurso de Miss Estados Unidos, el FBI decide enviar una agente infiltrada a participar en el concurso. La mejor candidata que encuentran para la misión es Gracie Hart, una agente de modales un tanto hoscos y poco femeninos. Aparece como Miss New Jersey, y, ante su total falta de glamur, los organizadores deciden buscarle un representante que le enseñe todos los trucos del mundo de la pasarela.', trailer_url = 'https://www.youtube.com/watch?v=MSXZJDuNwJE' WHERE id_api = 'tt0212346';

UPDATE Contenido SET id_tmdb = 2734, descripcion = '‘Ley y Orden: Unidad de Víctimas Especiales’ es una serie de televisión estadounidense grabada en Nueva York donde es también principalmente producida. Con el estilo de la original ‘Ley y Orden’ los episodios son usualmente "sacados de los titulares" o basados libremente en verdaderos asesinatos que han recibido la atención de los medios.', trailer_url = 'https://www.youtube.com/watch?v=MhGI_1DIhxw' WHERE id_api = 'tt0203259';

