UPDATE Contenido SET id_tmdb = 644, descripcion = 'En un futuro donde los avances científicos hacen posible la existencia, los humanos confían todos los aspectos de sus vidas a sofisticados robots denominados Mecas. La emoción es la última frontera en la evolución de las máquinas. Pero cuando un avanzado niño robótico llamado David es programado para amar, los humanos no están preparados para las consecuencias.', trailer_url = 'https://www.youtube.com/watch?v=4DUVcNPCNvo' WHERE id_api = 'tt0212720';

UPDATE Contenido SET id_tmdb = 2004, descripcion = 'Sitcom familiar que aborda los divertidos problemas y situaciones de una familia americana de clase media en la que el hijo Malcolm parece ser el único sensato... o al menos el único que da señales de cordura. La familia está compuesta por sus neuróticos padres Hal y Lois, el hermano mayor Francis y sus otros dos hermanos, Reese y Dewey.', trailer_url = 'https://www.youtube.com/watch?v=o6gPg-P5FPg' WHERE id_api = 'tt0212671';

UPDATE Contenido SET id_tmdb = 844, descripcion = 'Él era escritor. Creía escribir sobre el futuro, pero en realidad era el pasado. En su novela, un misterioso tren salía de cuando en cuando con dirección al año 2046. Todos los que subían a él lo hacían con el mismo propósito: recobrar los recuerdos perdidos. Se decía que en 2046 nada cambiaba. Nadie sabía a ciencia cierta si eso era verdad, porque ninguno de los que viajaron regresó jamás. Con una excepción. Él estuvo allí. Se marchó voluntariamente.', trailer_url = 'https://www.youtube.com/watch?v=xjmvuBY3560' WHERE id_api = 'tt0212712';

UPDATE Contenido SET id_tmdb = 9740, descripcion = 'Han pasado diez años desde que el doctor Hannibal, después de su entrevista con la agente del FBI Clarice Starling, escapara del hospital de máxima seguridad en el que estaba recluido. Lecter vive ahora en Italia, pero Starling no ha podido olvidar sus encuentros con él: su fría voz sigue resonando en sus sueños. Mason Verger también recuerda a Lecter: fue su sexta víctima y, pese a quedar horriblemente desfigurado, logró sobrevivir. Tras heredar una fortuna, Verger decide emplearla para satisfacer sus deseos de venganza. Pero pronto se da cuenta de que, para sacar a Lecter de su escondrijo, debe ponerle delante un cebo irresistible: Clarice Starling.', trailer_url = 'https://www.youtube.com/watch?v=20rd9VQ1Wx0' WHERE id_api = 'tt0212985';

UPDATE Contenido SET id_tmdb = 853, descripcion = 'Mientras los ejércitos de Alemania y la Unión Soviética luchan encarnizadamente y el mundo espera con ansiedad el desenlace de la batalla de Stalingrado, un francotirador ruso, Vassili Zaitsev, persevera en la empresa de eliminar a sus enemigos uno por uno. Modesto y reservado, Vassili es un hombre corriente que simplemente cumple con su deber con una destreza extraordinaria. Danilov -el oficial encargado de la propaganda soviética- se da cuenta del enorme valor de este antiguo campesino, y convierte al sencillo pastor de los Urales en un héroe nacional', trailer_url = 'https://www.youtube.com/watch?v=IHdtB4xTumQ' WHERE id_api = 'tt0215750';

UPDATE Contenido SET id_tmdb = 10867, descripcion = 'Malena es la belleza más encantadora e irresistible de Castelcuto, un aburrido pueblo de la soleada costa siciliana. Es nueva en la población y estando su marido en la guerra, cada paseo que da por el pueblo se convierte en un espectáculo, acompañado por las lujuriosas miradas de los hombres de la localidad y de los resentidos cotilleos de sus envidiosas esposas. Un ejército de flacos adolescentes en bicicleta la sigue allí donde vaya, con la única intención de observar su exquisita y arquetípica belleza. Entre ellos se encuentra Renato Amoroso, un chico de trece años con mucha imaginación que lleva su deseo a unos límites inesperados de obsesiva fantasía.', trailer_url = 'https://www.youtube.com/watch?v=73FrJrCgJCI' WHERE id_api = 'tt0213847';

UPDATE Contenido SET id_tmdb = 9285, descripcion = 'Cuatro amigos de la universidad se embarcan en un viaje por carretera para recuperar un video ilícito enviado a una amiga por error.', trailer_url = 'https://www.youtube.com/watch?v=NU9NYU9O0Hw' WHERE id_api = 'tt0215129';

UPDATE Contenido SET id_tmdb = 30991, descripcion = 'La tripulación de la nave Bebop solo intenta ganar dinero, y son la pandilla de caza-recompensas más divertida del año 2071.', trailer_url = 'https://www.youtube.com/watch?v=QCaEJZqLeTU' WHERE id_api = 'tt0213338';

UPDATE Contenido SET id_tmdb = 8452, descripcion = 'El piloto de helicóptero Adam Gibson, después de una jornada aparentemente normal, regresa a casa para estar con su familia, y se encuentra que ha sido suplantado por un clon. Cuando los creadores de su réplica descubren que no ha muerto en un accidente, como habían previsto, intentan darle caza.', trailer_url = 'https://www.youtube.com/watch?v=0VP44dGIi9c' WHERE id_api = 'tt0216216';

UPDATE Contenido SET id_tmdb = 9741, descripcion = 'Philadelphia. Año 1961. Un niño negro acaba de nacer en unos grandes almacenes. Un médico acude a ver como se encuentran tanto la madre como el bebé, y horrorizado le pregunta a la mujer si se le ha caído el niño, ya que tiene tanto los brazos como las piernas fracturadas. Philadelphia. Año 2000. Un hombre llamado David Dunn está en el expreso que va de Nueva York a Philadelphia camino de su casa después de una entrevista de trabajo en la ciudad de los rascacielos. En el tren entabla conversación con una atractiva mujer, pero ésta cree que quiere ligar y se cambia de asiento. Un momento después se produce un dramático accidente.', trailer_url = 'https://www.youtube.com/watch?v=AQkjd9wwpmU' WHERE id_api = 'tt0217869';

UPDATE Contenido SET id_tmdb = 3131, descripcion = 'New York City, 1863. Antes de la ciudad que conocemos hoy, llena de riqueza, poder y sueños infinitos, New York era un lugar diferente, una ciudad naciente donde el deseo por una vida mejor enfurecía a su gente y generaba violencia en las calles. Mientras la superviviencia del país se debatía en la Guerra Civil, un vasto y peligroso grupo de personas crecía en el bajo mundo. Pero en la joven y naciente ciudad, llegaba el momento de luchar contra los despiadados, contra la intolerancia y el miedo. Había llegado el momento del extraordinario valor de aquellos que impulsaron al borde de la lucha la libertad de futuras generaciones.', trailer_url = 'https://www.youtube.com/watch?v=1bjh979vVG0' WHERE id_api = 'tt0217505';

UPDATE Contenido SET id_tmdb = 13785, descripcion = 'Los participantes en un concurso de perros ven en su mascota la oportunidad de alcanzar la gloria y el reconocimiento que creen merecer, hasta tal punto que son capaces de cualquier cosa con tal de ahuyentar a sus adversarios. Con sus perros caprichosos y de nombres estrafalarios, los concursantes se desenvuelven en un medio donde la pureza de la raza es el máximo valor que puede tener un animal. Sus perros convenientemente adiestrados se han convertido en máquinas mimadas que saben controlarse para satisfacción de sus dueños.', trailer_url = 'https://www.youtube.com/watch?v=w7H9fsREWdg' WHERE id_api = 'tt0218839';

UPDATE Contenido SET id_tmdb = 2057, descripcion = 'En Cuba, Luis Vargas (Antonio Banderas) sostiene una relación epistolar con Julia Russell (Angelina Jolie), una atractiva americana. En principio ella es todo lo que él necesita para casarse y el hecho de que sea norteamericana, es ideal para proyectar el estatus al que él aspira. Pero un buen día Julia desaparece... con el dinero de Luis. Ahora, Luis sólo piensa en vengarse y emprende un viaje hacia el complicado pasado de Julia. Las consecuencias de esa odisea de mentiras descubiertas y pasiones encontradas son devastadoras tanto para él como para ella', trailer_url = 'https://www.youtube.com/watch?v=HF0eg5YAFIs' WHERE id_api = 'tt0218922';

UPDATE Contenido SET id_tmdb = 5994, descripcion = 'Jack Campbell es un egocéntrico broker de Wall Street cuya única obsesión es el trabajo y una vida llena de lujo. Tras un incidente en una tienda el día de Nochebuena, se despierta viviendo otra vida: es un humilde vendedor de neumáticos de Nueva Jersey, casado con su antigua novia Kate, a la que había abandonado hacía años para que no obstaculizara su carrera en el mundo de las finanzas.', trailer_url = 'https://www.youtube.com/watch?v=Hzw-p2PfBeU' WHERE id_api = 'tt0218967';

UPDATE Contenido SET id_tmdb = 4244, descripcion = 'Willis es un hombre muy ocupado con poco tiempo para los sentimientos que, tras una experiencia sobrenatural, se encuentra con un niño que resulta ser él mismo de chico. Una comedia bondadosa con toques fantásticos para consumo familiar.', trailer_url = 'https://www.youtube.com/watch?v=1KCk3z8kmko' WHERE id_api = 'tt0219854';

UPDATE Contenido SET id_tmdb = 2046, descripcion = 'Desde el cuarto trasero de su pequeña casa en Georgia, Annie Wilson usa sus talentos telepáticos para adivinar la suerte de sus vecinos. Viuda y con tres hijos que mantener, Annie soporta la pesada carga de tener que acarrear con los problemas de todo el pueblo sobre sus hombros mientras lucha con los suyos propios. Unos días más tarde desaparece Jessica, novia de Wayne, el director de la escuela de los hijos de Annie. Habiendo agotado todas las posibilidades e intuyendo que su “don” puede servir de algo, Wayne y el padre de Jessica, acompañados de las autoridades locales, le piden a Annie que les ayude a solucionar el caso. Al principio Annie no puede proporcionar ninguna pista. A medida que pasa el tiempo se ve atormentada por horribles pesadillas y visiones.', trailer_url = 'https://www.youtube.com/watch?v=wz9-H7oTIJ0' WHERE id_api = 'tt0219699';

