UPDATE Contenido SET id_tmdb = 4133, descripcion = 'Basada en hechos reales, cuenta la historia de George Jung, un hombre de familia humilde que consiguió hacerse multimillonario gracias a su propia versión del sueño americano. Durante su estancia en la cárcel se adentra en el mundo del narcotráfico en Colombia, y a través de un ingenioso sistema de importación llega a comerciar la mayor parte de la cocaína que entra en Estados Unidos durante los 70. Acompañado por Mirtha y Delgado, formarán un triángulo que compartirá situaciones límite dominadas por la pasión, el odio, la amistad y una desmedida ambición de poder.', trailer_url = 'https://www.youtube.com/watch?v=otckBy8LdVg' WHERE id_api = 'tt0221027';

UPDATE Contenido SET id_tmdb = 10647, descripcion = 'Un niño imagina un curioso sistema para mejorar el mundo; hacer favores incluso antes de que te los devuelvan. Es decir: no devolver favores, sino pagarlos por adelantado, y no necesariamente a quien te lo hizo a ti. Para sorpresa de todos, la desinteresada propuesta causa furor entre la gente. Entretenida comedia con toques dramáticos y un eficaz reparto. Como anécdota el personaje interpretado por Spacey es, en la novela, de raza negra, lo que provocó polémica en USA entre el colectivo afroamericano.', trailer_url = 'https://www.youtube.com/watch?v=_pCtXRP1edo' WHERE id_api = 'tt0223897';

UPDATE Contenido SET id_tmdb = 11371, descripcion = 'Nick Wells (Robert De Niro), un famoso ladrón de guante blanco, ha decidido dejar para siempre su vida criminal y dedicarse a lo que realmente le interesa: su club de Jazz y su novia Diane (Angela Bassett). Pero Max (Marlon Brando) -su amigo, cómplice y socio- tiene otros planes para él: realizar su último golpe, un golpe maestro... Entrar en el edificio de Aduanas de Montreal y robar una obra de arte valorada en varios millones de dólares. Para ejecutar el plan necesitan la ayuda de Jackie Teller (Edward Norton), un joven y agresivo ladrón de mucho talento, experto en sistemas de alarma.', trailer_url = 'https://www.youtube.com/watch?v=8W1D_D7ZG8o' WHERE id_api = 'tt0227445';

UPDATE Contenido SET id_tmdb = 10054, descripcion = 'Cuando el matrimonio Cortez -aparentes padres de familia normales y corrientes pero que en realidad son superespías internacionales- es secuestrado por el malvado Floop, sus hijos no tendrán más remedio que intentar salvarles en una trepidante aventura llena de acción y peligros', trailer_url = 'https://www.youtube.com/watch?v=GE5aHKJp6HI' WHERE id_api = 'tt0227538';

UPDATE Contenido SET id_tmdb = 2085, descripcion = 'La historia trata sobre un perro llamado Agallas y sus dueños: Muriel, una vieja mujer escocesa, y Eustaquio, un viejo agricultor gruñón. Este perro vive para salvarles la vida de tenebrosos monstruos, extraterrestres y otras criaturas míticas.', trailer_url = 'https://www.youtube.com/watch?v=zxz5_OlpbUI' WHERE id_api = 'tt0220880';

UPDATE Contenido SET id_tmdb = 10016, descripcion = 'Marte, año 2176. Debido a la superpoblación de la Tierra, el Planeta Rojo se ha convertido en una zona habitada, pero sigue siendo un lugar peligroso. Para colmo, durante una exploración se descubre que una civilización marciana que ha permanecido dormida mucho tiempo, ahora está despierta. En tal circunstancia, un pequeño grupo de policías es enviado a una lejana población minera con la misión de escoltar a un peligroso criminal.', trailer_url = 'https://www.youtube.com/watch?v=XbmFwk8n0f0' WHERE id_api = 'tt0228333';

UPDATE Contenido SET id_tmdb = 1613, descripcion = 'Elmo McElroy, un químico estadounidense, viaja a Inglaterra para llevar a cabo su último gran negocio: introducir una nueva droga de diseño en el mercado europeo.', trailer_url = 'https://www.youtube.com/watch?v=CaGy5JkZiis' WHERE id_api = 'tt0227984';

UPDATE Contenido SET id_tmdb = 11983, descripcion = 'Mientras construye una presa en Tecala, en el corazón de los Andes, el ingeniero norteamericano Peter Bowman es capturado por fuerzas antigubernamentales durante una incursión en la capital. Cuando los rebeldes descubren su identidad exigen tres millones de dólares de rescate. El problema es que la empresa de Peter, con sede en Houston, está al borde de la bancarrota y ha cancelado la póliza de seguros contra secuestros, así que no dispone del dinero del rescate. Viéndose abandonada por la compañía, la esposa de Peter contrata los servicios de Terry Thorne, un negociador profesional que en los últimos años ha resuelto numerosos casos de secuestro.', trailer_url = 'https://www.youtube.com/watch?v=btRBnxFQvD0' WHERE id_api = 'tt0228750';

UPDATE Contenido SET id_tmdb = 10865, descripcion = 'Un joven aventurero llamado Milo encuentra un antiguo diario que contiene pistas de cómo llegar a Atlantis, el mítico reino hundido. Junto a otros intrépidos personajes Milo decide embarcarse en el Ulises, un impresionante submarino, en una arriesgada expedición al fondo del mar.', trailer_url = 'https://www.youtube.com/watch?v=r39ys9K3LgA' WHERE id_api = 'tt0230011';

UPDATE Contenido SET id_tmdb = 60670, descripcion = 'El mismo día, en dos lugares separados por 300 kilómetros de distancia, a dos policías les asignan investigaciones muy particulares. Pierre Niemans (Jean Reno), un hombre con experiencia y un instinto infalible para los casos criminales, viaja a Guernon, una ciudad universitaria de los Alpes, donde se ha cometido un violento asesinato. Mientras tanto, el joven y solitario Max Kerkerian (Vincent Cassel), un antiguo ladrón de coches cuyo amor al peligro lo llevó a ingresar en la policía, está investigando en Sarzac la profanación de un cementerio, especialmente la tumba de una niña que murió hace veinte años. Inesperadamente, se establece una conexión entre ambos casos.', trailer_url = 'https://www.youtube.com/watch?v=dzSrbX8u9q0' WHERE id_api = 'tt0228786';

UPDATE Contenido SET id_tmdb = 1636, descripcion = 'Elliot es un asesor informático lleno de buenas intenciones, pero un auténtico desastre a la hora de hacer amigos, que cae perdidamente enamorado de Alison, una compañera de trabajo que ni siquiera sabe que él existe. Desesperado por conquistarla, vende su alma al Diablo a cambio de siete deseos.', trailer_url = 'https://www.youtube.com/watch?v=tjCUxFY01_A' WHERE id_api = 'tt0230030';

UPDATE Contenido SET id_tmdb = 1921, descripcion = 'El ejecutivo de publicidad Nelson Moss es un hombre absorto en sí mismo y emocionalmente aislado, que está centrado en su futuro, huyendo de su pasado y ajeno al presente. Hasta el día que conoce a Sara, una mujer encantadora e intrépida, cuya pasión por la vida trastoca la actitud segura y decidida de Nelson. Sara sabe realmente lo que quiere de la vida y cómo vivirla a tope, y considera fundamental compartir ese conocimiento con otras personas. Intrigados el uno por el otro, pero no lo bastante dispuestos a comprometerse, se deciden por un noviazgo bastante poco convencional: un mes de prueba, tras el cual seguirán caminos diferentes. Sin expectativas, sin presión, sin ataduras, lo que ninguno de los dos espera es enamorarse.', trailer_url = 'https://www.youtube.com/watch?v=MafIG-ilj0Q' WHERE id_api = 'tt0230838';

UPDATE Contenido SET id_tmdb = 1933, descripcion = 'Grace educa sola a sus hijos en un aislado caserón victoriano bajo estrictas normas religiosas. Los tres nuevos sirvientes deben aprender una regla vital, la casa estará siempre en penumbra y nunca se abrirá una puerta si no se ha cerrado la anterior  porque los niños sufren una extraña alergia a la luz del día.', trailer_url = 'https://www.youtube.com/watch?v=GekkoBitLvM' WHERE id_api = 'tt0230600';

