UPDATE Contenido SET id_tmdb = 6073, descripcion = 'Jerry Welbach acaba de recibir dos ultimátum: el primero de su jefe, un mafioso que le encarga viajar a México para recuperar "la Mexicana", una antigua y valiosa pistola, y el segundo de su novia Samantha, que le exige que ponga fin a su relación con la mafia. Jerry piensa que seguir vivo es lo más importante, aunque eso suponga tener problemas con Samantha, así que va a México. Aunque encuentra el arma, llevársela a su jefe es un asunto más complicado. Sobre la pistola pesa una maldición legendaria, ya que fue el regalo de boda que un rico terrateniente hizo a su hija, que murió en trágicas circunstancias. Cuando un asesino a sueldo secuestra a Samantha para hacerse con la pistola, Jerry tendrá motivos para creer en la maldición.', trailer_url = 'https://www.youtube.com/watch?v=LyujCIHTiHc' WHERE id_api = 'tt0236493';

UPDATE Contenido SET id_tmdb = 6312, descripcion = 'Gévaudan, en la Francia del siglo XVIII. Una monstruosa criatura devora salvajemente a los habitantes del lugar. Recién llegado de América, Grégoire de Fronsac recibe el encargo del rey Luis XV de identificar y encontrar a la fiera. Sin embargo Grégorie y su misterioso hermano de sangre, un indio llamado Mani, intentarán descubrir qué hay detrás de estos sucesos...', trailer_url = 'https://www.youtube.com/watch?v=xGINKIKO0nc' WHERE id_api = 'tt0237534';

UPDATE Contenido SET id_tmdb = 15917, descripcion = 'Devdas es enviado lejos por su padre para que pueda mejorar a sí mismo, pero a su regreso su padre todavía no le da la bienvenida. Devdas y Paro están enamorados, pero Paro es de una casta inferior y está lista para casarse con un viudo mayor. Devdas está devastado y se va de casa. Se convierte en un mujeriego alcohólico y se enamora de una cortesana. Paro intenta alejar a Devdas de la bebida antes de que se autodestruya.', trailer_url = 'https://www.youtube.com/watch?v=8tuHQWGMQwY' WHERE id_api = 'tt0238936';

UPDATE Contenido SET id_tmdb = 5955, descripcion = 'En un pequeño pueblo de Nevada, Jerry Black es un solitario detective de homicidios que está a punto de jubilarse. Resignándose a dejar el trabajo, lo único que en realidad da sentido a su vida, decide hacerse cargo de un último caso cuando se descubre en las montañas el cuerpo sin vida de una niña. Tras jurarle a una madre desconsolada que hallará al culpable, comienza una investigación en la que irá más allá de las evidencias y de su horario laboral, volcándose por completo.', trailer_url = 'https://www.youtube.com/watch?v=V-r55UiW7fE' WHERE id_api = 'tt0237572';

UPDATE Contenido SET id_tmdb = 2719, descripcion = 'Aclamada sitcom británica -una especie de "Friends" a la inglesa, mucho más caústica y provocadora- sobre los amores y ligues de tres parejas de amigos treintañeros -Steve, Susan, Patrick, Sally, Oliver y Jane- que viven en Londres. Debido a su gran éxito en Gran Bretaña, la cadena estadounidense NBC compró los derechos para crear una nueva versión en norteamérica, pero finalmente tuvo que ser suspendida por resultar demasiado "atrevida" para la audiencia.', trailer_url = 'https://www.youtube.com/watch?v=hstPHM3R1dY' WHERE id_api = 'tt0237123';

