UPDATE Contenido SET id_tmdb = 8859, descripcion = 'Tras un noche de juerga, dos amigos no recuerdan dónde dejaron aparcado su coche. Su búsqueda significará el comienzo de una serie de sorpresas. Todo empieza cuando los jóvenes Jesse y Chester se despiertan una mañana después de una fiesta muy intensa, pero ninguno de los dos puede recordar qué pasó durante la noche anterior. El coche de Jesse desapareció, y todo parece estar fuera de lugar, así que los dos amigos comienzan la búsqueda del auto y de pistas que les permita reconstruir la noche anterior, aunque a medida que profundizan en los acontecimientos de las últimas veinticuatro horas, la situación se convierte en una salvaje historia que parece extraída de la ciencia-ficción.', trailer_url = 'https://www.youtube.com/watch?v=d1wuijgeaaY' WHERE id_api = 'tt0242423';

UPDATE Contenido SET id_tmdb = 634, descripcion = 'Bridget Jones está decidida a superarse a sí misma al mismo tiempo que busca al amor de su vida dejando constancia de todo ello en su diario personal.', trailer_url = 'https://www.youtube.com/watch?v=821-G2T1bLc' WHERE id_api = 'tt0243155';

UPDATE Contenido SET id_tmdb = 467, descripcion = 'Cuatro jóvenes estudiantes, dos chicas y dos chicos, desaparecen de un exclusivo internado británico. Dos semanas más tarde aparece una de las chicas, Liz, pero está tan traumatizada que no lo logra distinguir lo real de lo imaginario. Lo único que recuerda es que para librarse de una excursión, se encerró con sus compañeros en un bunker subterráneo. Junto con la doctora Horwood, psicóloga de la policía, intentará descubrir qué pasó en el bunker, y qué ha sido de sus amigos.', trailer_url = 'https://www.youtube.com/watch?v=_N50XofqZkY' WHERE id_api = 'tt0242527';

UPDATE Contenido SET id_tmdb = 9081, descripcion = 'Un anónimo protagonista mantiene diversas conversaciones con personas distintas que parecen entrar y salir de su vida sin motivo alguno. Pero paulatinamente se atisba un propósito detrás de las crípticas y profundas charlas. Una frase, "dream is destiny" (el sueño es el destino), expresa la idea básica de la película: atreverse a entrar en el incontrolable mundo de los sueños, tan apasionante como inquietante y oscuro, y permitirse disfrutar al máximo del instante eterno que dura.', trailer_url = 'https://www.youtube.com/watch?v=edrGozs6W_I' WHERE id_api = 'tt0243017';

UPDATE Contenido SET id_tmdb = 10778, descripcion = 'Verano de 1949. Ed Crane (Billy Bob Thornton), un introvertido barbero de un pueblecito del norte de California, se siente insatisfecho de su rutinaria vida. Las infidelidades de su mujer (Frances McDormand) le brindan la oportunidad de ejercer un chantaje que podría ayudarle a cambiar su apática existencia.', trailer_url = 'https://www.youtube.com/watch?v=vjO8u_9CqXI' WHERE id_api = 'tt0243133';

UPDATE Contenido SET id_tmdb = 10996, descripcion = 'Una nueva aventura del valiente y pequeño héroe Stuart Little. Dos nuevos personajes forman parte de la familia Little: una hermana de nueve meses llamada Martha y un pájaro lleno de vida llamado Margalo.', trailer_url = 'https://www.youtube.com/watch?v=k--OdtbKyqE' WHERE id_api = 'tt0243585';

UPDATE Contenido SET id_tmdb = 2171, descripcion = 'Historia sobre las desventuras de un grupo de personas durante el último día de un campamento de verano en 1981.', trailer_url = 'https://www.youtube.com/watch?v=RByrRpURS5s' WHERE id_api = 'tt0243655';

UPDATE Contenido SET id_tmdb = 129, descripcion = 'Durante el traslado de su familia a los suburbios, una niña de 10 años de edad deambula por un mundo gobernado por dioses, brujas y espíritus, y donde los humanos se convierten en bestias.', trailer_url = 'https://www.youtube.com/watch?v=5Fgq4Osh6XQ' WHERE id_api = 'tt0245429';

UPDATE Contenido SET id_tmdb = 9705, descripcion = 'Stanley Jobson (Hugh Jackman), un experto en informática que acaba de salir de prisión, es requerido por el terrorista Gabriel Shear (John Travolta) para que le ayude a decodificar un complicado código de seguridad de una cuenta secreta. Sólo unos pocos hackers en el mundo son capaces de realizar dicho trabajo, y él es uno de ellos. Pese a que no puede tocar un ordenador, los métodos de Shear obligarán a Jobson a ayudarle en su misión... Un thriller de acción que fue Nº1 de taquilla en USA.', trailer_url = 'https://www.youtube.com/watch?v=BgYPMc070w8' WHERE id_api = 'tt0244244';

UPDATE Contenido SET id_tmdb = 2752, descripcion = 'La última relación de Matt (Josh Hartnett) con su idealizada Nicole (Vinessa Shaw) acabó muy mal, y tras la ruptura se embarcó en una avalancha de citas que tan sólo aumentaron su sensación de vacío. Entonces decide que no quiere saber nada de chicas, por lo que se autoimpone un celibato de 40 días y 40 noches sin tener sexo. De ninguna clase. El problema surge cuando, al tercer día, conoce a Erica (Shannyn Sossamon), la mujer de sus sueños...', trailer_url = 'https://www.youtube.com/watch?v=Asl625hZzoM' WHERE id_api = 'tt0243736';

UPDATE Contenido SET id_tmdb = 12100, descripcion = 'Durante la Segunda Guerra Mundial (1939-1945) el avance de las tropas estadounidenses en la campaña del Pacífico se ve seriamente obstaculizado por la capacidad de los servicios de inteligencia japoneses para descifrar los mensajes militares. A finales de 1942, son entrenados varios centenares de indios navajos para emplear un código secreto basado en su lengua materna, el único que no pudo ser descifrado por los japoneses. Los protagonistas son dos oficiales cuya misión es proteger a dos indios navajos enrolados en la Marina. Basada en hechos reales.', trailer_url = 'https://www.youtube.com/watch?v=0nTY1nz-lpY' WHERE id_api = 'tt0245562';

UPDATE Contenido SET id_tmdb = 1391, descripcion = 'Las vidas de Julio y Tenoch, dos jóvenes mexicanos de 17 años, están regidas por su apetito sexual, su amistad, y por su deseo de alcanzar la madurez. Durante una festiva tarde de boda con sus familias, conocen a Luisa, una española de 28 años.', trailer_url = 'https://www.youtube.com/watch?v=inc0vS58ZKg' WHERE id_api = 'tt0245574';

UPDATE Contenido SET id_tmdb = 9378, descripcion = 'Arthur Kriticos (Tony Shalhoub), un profesor viudo, hereda la majestuosa mansión de su tío Cyrus y se traslada a vivir allí con sus dos hijos, su niñera y un médium. Pronto descubren que la casa está construida con paredes de cristal inscritas con frases en latín que son hechizos de barrera. Encerrados en la casa, se dan cuenta de que contiene a 13 fantasmas capturados por Cyrus, cada uno encerrado por los hechizos. Con la ayuda del médium Dennis Rafkin (Matthew Lillard), intentan sobrevivir y desentrañar el misterio de la mansión antes de que sea demasiado tarde.', trailer_url = 'https://www.youtube.com/watch?v=Xj1LWNgG0Ng' WHERE id_api = 'tt0245674';

UPDATE Contenido SET id_tmdb = 10956, descripcion = 'Joe Dirt es un inocente conserje de extraño peinado y jeans deslavados que aún tiene la esperanza de encontrar a sus padres, a quienes perdió cuando tenía ocho años en una visita al Gran Cañón. Durante su búsqueda, un locutor de radio lo invita a su programa para burlarse de él, sin sospechar que sus ordinarias aventuras serán la delicia de la audiencia', trailer_url = 'https://www.youtube.com/watch?v=l3Ng784FblQ' WHERE id_api = 'tt0245686';

UPDATE Contenido SET id_tmdb = 55, descripcion = 'Ciudad de México: un fatal accidente automovilístico afecta trágicamente a tres personas. Octavio, un joven adolescente, decide fugarse con Susana, la esposa de su hermano; el Cofí, su perro, se convierte en el medio para conseguir el dinero que necesitan para poder escapar juntos. Al mismo tiempo, Daniel, un hombre de 42 años, deja a su esposa y a sus hijos para irse a vivir con Valeria, una hermosa modelo. El mismo día en que ambos festejan su nueva vida, el destino hace que Valeria sea víctima del trágico accidente.', trailer_url = 'https://www.youtube.com/watch?v=_P29GF_NbDc' WHERE id_api = 'tt0245712';

UPDATE Contenido SET id_tmdb = 314, descripcion = 'Star Trek: Enterprise es una serie de ciencia ficción y precuela de la serie original que transcurre 100 años antes. Se estrenó el 26 de Septiembre de 2001 en la red de UPN y el episodio final fue emitido en Mayo de 2005.

La serie transcurre en el siglo 22 abordo de la primera nave terrestre capaz de factor 5, la nave estelar Enterprise NX01, diseñada para la exploración de la galaxia y capitaneada por Jonathan Archer. La designacion NX indica que la nave es un modelo experimental.', trailer_url = 'https://www.youtube.com/watch?v=urYH6xEyXw0' WHERE id_api = 'tt0244365';

