UPDATE Contenido SET id_tmdb = 8835, descripcion = 'Elle Woods es una rubia auténtica, además de muy popular, buena estudiante, presidenta de su hermandad y Miss Junio en el calendario de la Universidad. Ha disfrutado de una vida maravillosa y está enamorada de Warner Huntington III. Pero todo se derrumba cuando su novio decide romper con ella debido a que es demasiado rubia y no lo suficientemente formal para su futura carrera en el mundo de la política. Decidida a salir adelante, Elle se matricula en la Facultad de Derecho de la Universidad de Harvard, asumiendo un reto aún mayor de lo que esperaba.', trailer_url = 'https://www.youtube.com/watch?v=Qf5_SuyCbUM' WHERE id_api = 'tt0250494';

UPDATE Contenido SET id_tmdb = 575, descripcion = 'Llegaron a una cárcel ficticia buscando una forma rápida de ganar dinero fácil. Ahora sólo buscan la manera de sobrevivir. Todo empezó como un experimento científico protagonizado durante dos semanas por veinte hombres que cobrarían por su colaboración 4.000 marcos. El proyecto consistía en estudiar el comportamiento agresivo en un ambiente carcelario simulado. A los participantes se les asigna el papel de guardianes (ocho) o prisioneros (doce). Los prisioneros deben obedecer las órdenes, y los guardias deben mantener el orden. Pero dar a un hombre un poco de poder puede tener consecuencias insospechadas.', trailer_url = 'https://www.youtube.com/watch?v=MG_xQs9_MGQ' WHERE id_api = 'tt0250258';

UPDATE Contenido SET id_tmdb = 9896, descripcion = 'El propietario de un hotel de Las Vegas ha organizado una curiosa apuesta para complacer a unos excéntricos millonarios. Se trata de una alocada carrera humana hasta Silver City, Nuevo México, cuyo premio para el ganador son dos millones de dólares guardados en la consigna de la estación del ferrocarril. Un grupo de personajes elegidos al azar reciben una moneda de oro que les permite participar en la carrera. La frenética competición les llevará a través del desierto hasta la meta, en una competición en la que sólo hay una regla: llegar el primero.', trailer_url = 'https://www.youtube.com/watch?v=OY2S_kY2KWU' WHERE id_api = 'tt0250687';

UPDATE Contenido SET id_tmdb = 9397, descripcion = 'Un meteorito cae en el desierto de California, en principio uno más de los que chocan con nuestro planeta. Pero este meteorito va a provocar el caos al contener vida alienígena, lo cual va a dar un nuevo significado al principio de la ley del más fuerte. Las cosas comienzan a agravarse cuando aparecen toda clase de curiosos bichos circulando por ahí, pero en lo que no han caído los alienígenas es en un equipo formado por Ira, Allison, Harry y Wayne, un grupo de científicos que tratarán de desbaratar un más que probable desastre sin precedentes.', trailer_url = 'https://www.youtube.com/watch?v=vWYNyqqnPfE' WHERE id_api = 'tt0251075';

UPDATE Contenido SET id_tmdb = 2251, descripcion = 'El matrimonio de Edward (Richard Gere) y Connie Sumner (Diane Lane) parece ir bien: tienen dinero, posición, un niño y una bonita casa en un barrio residencial de las afueras de Nueva York. Pero un día, en Manhattan, Connie conoce a Paul (Olivier Martinez), un joven y atractivo coleccionista de libros de origen francés. Ambos comienzan una relación adúltera de insospechadas consecuencias.', trailer_url = 'https://www.youtube.com/watch?v=EfptM8xKyUI' WHERE id_api = 'tt0250797';

UPDATE Contenido SET id_tmdb = 10592, descripcion = 'Durante la Segunda Guerra Mundial, el teniente Thomas Hart, un oficial de buena familia y estudiante de derecho en Yale, es capturado por los alemanes. A los pocos días de ser interrogado, es enviado a un campo de prisioneros. Una vez allí, el coronel estadounidense William McNamara, al mando entre los prisioneros, le pregunta si ha dado información al enemigo. Como Hart lo niega, es expulsado del barracón de los oficiales. Ocurre un crimen, y el oficial nazi a cargo del campo permite a los prisioneros llevar adelante una corte marcial para resolver el caso.', trailer_url = 'https://www.youtube.com/watch?v=TcRuFgqFLrA' WHERE id_api = 'tt0251114';

UPDATE Contenido SET id_tmdb = 9919, descripcion = 'Andie Anderson es una periodista que debe terminar un reportaje poco usual y dispone tan sólo de diez días. Se trata de escribir, basándose en experiencias de primera mano, sobre las cosas que las mujeres hacen sin querer y que provocan el alejamiento de los hombres. Para ello tiene que conseguir que un chico se enamore de ella y luego cometer todos los errores posibles para que la deje. El hombre elegido es el cotizado soltero Benjamin Barry, que precisamente acaba de apostar con el director de la agencia de publicidad en la que trabaja que es capaz de hacer que una mujer se enamore de él en diez días.', trailer_url = 'https://www.youtube.com/watch?v=lxDQW1fkkxc' WHERE id_api = 'tt0251127';

UPDATE Contenido SET id_tmdb = 2662, descripcion = 'Dos parejas de jóvenes se pierden durante la noche y van a dar a una oscura casa habitada por una familia de psicópatas. Asesinatos, canibalismo y ritos satánicos son algunos de los mil horrores que allí les esperan.', trailer_url = 'https://www.youtube.com/watch?v=-ksE8KaNIKo' WHERE id_api = 'tt0251736';

UPDATE Contenido SET id_tmdb = 1431, descripcion = 'CSI: Crime Scene Investigation es una serie de televisión de ficción estadounidense transmitida por primera vez en los Estados Unidos por la cadena CBS. La serie se centra en torno a un grupo de científicos forenses y criminologos que trabajan en la ciudad estadounidense de Las Vegas (Nevada), investigando los crímenes que en ella suceden. La original fórmula de la serie y su éxito suscitó dos secuelas, CSI: Miami (2002-2012) y CSI: Nueva York (2004-2013), en torno a los equipos de científicos forenses de dichas ciudades, pero además influye en varias series posteriores relacionadas con la investigación criminal, como Bones o NCIS entre otras.', trailer_url = 'https://www.youtube.com/watch?v=ApT1EYvrwuk' WHERE id_api = 'tt0247082';

