UPDATE Contenido SET id_tmdb = 2770, descripcion = 'Jim (Jason Biggs) y sus amigos se reúnen en una casa de la playa después de su primer año de universidad. Allí, Jim busca mejorar sus habilidades sexuales con la ayuda de Michelle (Alyson Hannigan), su antigua cita del baile de graduación. Mientras tanto, Kevin (Thomas Ian Nicholas) intenta recuperar a Vicky (Tara Reid), Oz (Chris Klein) mantiene una relación a distancia con Heather (Mena Suvari), Finch (Eddie Kaye Thomas) practica el tantra y Stifler (Seann William Scott) hace de las suyas con sus bromas y su lujuria. Entre risas, líos y situaciones embarazosas, los amigos planean organizar la fiesta más grande de sus vidas.', trailer_url = 'https://www.youtube.com/watch?v=TXQDmsNXLRA' WHERE id_api = 'tt0252866';

