UPDATE Contenido SET id_tmdb = 83651, descripcion = 'Lazy, uneducated students mostly coming from money, share a very close band. They live together in the dormitory of this private highschool, where they daily plan their latest pranks on teachers or the other classes. When a new and obviously strict headmaster arrives, the students naturally try to overthrow him. A comic war of nitwits follows.', trailer_url = 'https://www.youtube.com/watch?v=k6gi9WhpBJ0' WHERE id_api = 'tt0252487';

UPDATE Contenido SET id_tmdb = 423, descripcion = 'Varsovia, 1939. El pianista polaco de origen judío Wladyslaw Szpilman (Adrien Brody) interpreta un tema de Chopin en la radio nacional de Polonia mientras la aviación alemana bombardea la capital. El régimen nazi ha invadido el país, y como hace en otros países invadidos, lleva a cabo la misma política con respecto a los judíos. Así Szpilman y toda su familia -sus padres, su hermano y sus dos hermanas- se ven obligados a dejar su casa y todo lo que les pertenece para trasladarse con miles de personas de origen judío al ghetto de Varsovia. Mientras Wladyslaw trabaja como pianista en un restaurante propiedad de un judío que colabora con los nazis, su hermano Henryk (Ed Stoppard) prefiere luchar contra los nazis. Pero tres años más tarde, los habitantes del ghetto son trasladados en trenes hacia campos de concentración.', trailer_url = 'https://www.youtube.com/watch?v=og9hFxxdSOg' WHERE id_api = 'tt0253474';

UPDATE Contenido SET id_tmdb = 6278, descripcion = 'En el Londres actual, Quinn, un niño de 12 años, despierta por error a un enorme dragón de su letargo de siglos. Veinte años más tarde, pueden apreciarse las devastadoras consecuencias del paso de la bestia y de sus vástagos en la práctica totalidad del planeta. Los dragones son seres extremadamente inteligentes, muy evolucionados… y no tienen ninguna intención de compartir la Tierra con los humanos. Quinn se ha hecho mayor y ahora es Jefe de Bomberos. Su tarea es mantener a las bestias alejadas y defender a una pequeña comunidad que lucha por su supervivencia. En medio de este caos aparece Van Zan, un emprendedor americano que afirma saber cómo acabar con los dragones y salvar a la humanidad; y además con un método que Quinn jamás había visto utilizar antes…', trailer_url = 'https://www.youtube.com/watch?v=NFZoDnP-1eE' WHERE id_api = 'tt0253556';

UPDATE Contenido SET id_tmdb = 201, descripcion = 'La policía romulana obtiene ADN del Capitán Picard y fabrican un clon, llamado Shinzon, con la finalidad de introducirlo en la Federación, pero ese plan queda en nada y envían al clon a las minas de dilitio de Remo, el planeta hermano de Rómulo, la capital del Imperio Romulano. Shinzon organiza un golpe de estado gracias a las fuerzas Remanas y su imbatible nave erigiéndose nuevo Pretor Romulano.', trailer_url = 'https://www.youtube.com/watch?v=Ts8dfaRtlqM' WHERE id_api = 'tt0253754';

UPDATE Contenido SET id_tmdb = 11529, descripcion = 'Melanie es una diseñadora de moda de Nueva York prometida al soltero de oro de la ciudad. Pero la joven esconde un pasado lleno de secretos. Como por ejemplo Jake, un apuesto sureño con el que se casó en el instituto y que se niega a concederle el divorcio. Decidida a terminar con su tormentoso matrimonio de una vez por todas, Melanie regresa a su casa en Alabama para enfrentarse a su pasado. Allí comprende que aunque una chica se marche del Sur, el Sur nunca la abandona.', trailer_url = 'https://www.youtube.com/watch?v=f1LxRJno7N8' WHERE id_api = 'tt0256415';

UPDATE Contenido SET id_tmdb = 4147, descripcion = 'En los oscuros años de la Gran Depresión, Michael Sullivan es un asesino a sueldo que profesa una lealtad inquebrantable a su jefe, el señor Rooney, y, al mismo tiempo, un buen padre de familia. Son tiempos duros en Rock Island, donde domina la mafia irlandesa, la Ley Seca sigue vigente y los gánsteres, especialmente Al Capone en Chicago, están en la cima del poder. Pero un día, inesperadamente, el hijo de doce años de este asesino a sueldo, Michael Jr., decide seguir a su padre para ver en qué consiste exactamente su trabajo.', trailer_url = 'https://www.youtube.com/watch?v=Tpj8mfOWB5M' WHERE id_api = 'tt0257044';

UPDATE Contenido SET id_tmdb = 11812, descripcion = 'La atractiva Christina Walters, inesperadamente y tras años de evitar relaciones serias con los hombres, conoce durante una noche de fiesta al que parece ser su media naranja, Pete. Pero cuando Christina se entera a la mañana siguiente que Pete ha dejado la ciudad, ella y su mejor amiga, Courtney, salen en su búsqueda y se encuentran con una serie de contratiempos durante su viaje.', trailer_url = 'https://www.youtube.com/watch?v=5sA8dpA3gig' WHERE id_api = 'tt0253867';

UPDATE Contenido SET id_tmdb = 1433, descripcion = 'España, 1939. En los últimos días de la guerra civil española, el joven Carlos llega al orfanato de Santa Lucía, donde hará amigos y enemigos mientras sigue los quedos pasos de una misteriosa presencia ávida de venganza…', trailer_url = 'https://www.youtube.com/watch?v=bQIADt2dfTc' WHERE id_api = 'tt0256009';

UPDATE Contenido SET id_tmdb = 11090, descripcion = 'Un policía tiene un accidente de tráfico. Cuando despierta una semana después descubre que un científico ha utilizado órganos de animales para reconstruir su cuerpo destrozado. Con esta mentalidad Marvin se convierte en un héroe hasta que sus instintos animales se apoderan de él en los momentos más inoportunos.', trailer_url = 'https://www.youtube.com/watch?v=pBwcksgKcFs' WHERE id_api = 'tt0255798';

UPDATE Contenido SET id_tmdb = 9889, descripcion = 'Hal Larsen es un muchacho superficial que sólo encuentra bellas a las chicas que parecen supermodelos. Sin embargo, después de ser sometido a una sesión de hipnosis por un conocido gurú, sólo será capaz de ver la belleza interior de las mujeres. Rosemary, una chica obesa y bondadosa, se cruzará en su camino y Hal se enamorará locamente de ella.', trailer_url = 'https://www.youtube.com/watch?v=YGaqlO9bClk' WHERE id_api = 'tt0256380';

UPDATE Contenido SET id_tmdb = 4248, descripcion = 'En esta ocasión los hermanos Wayans empiezan la historia con una satírica parodia de El Exorcista, mostrando a James Woods en el papel de un cura poco convencional, el padre McFelly, ocupado en salvar a una Natasha Lyonne de un espíritu de otro mundo. Entonces, retomando la historia donde la dejaron, los hermanos Wayans se vuelven a reunir de forma cómica con la heroína Cindy Campbell, convertida ahora en una buena estudiante universitaria. Un profesor loco la recluta a ella y a su grupo de compañeros deseosos de vivir aventuras y nuevas experiencias, para una salida de fin de semana bajo el pretexto de realizar un experimento científico. Mientras se desarollan las actividades del fin de semana, las continuas sorpresas mantienen la diversión siempre en marcha.', trailer_url = 'https://www.youtube.com/watch?v=NdnacU5sbcE' WHERE id_api = 'tt0257106';

UPDATE Contenido SET id_tmdb = 9257, descripcion = 'Basada en la popular serie de televisión de los años setenta "Los hombres de Harrelson". En su versión cinematográfica Jim Street (Colin Farrell) es un agente de policía de Los Ángeles que busca desesperadamente una oportunidad para vestir el uniforme del cuerpo de élite S.W.A.T. (Special Weapons and Tacticts Unit). La ocasión llega cuando Hondo (Jackson), el jefe del comando, recibe la orden de reclutar a cinco policías para el cuerpo. Tras semanas de riguroso entrenamiento, el nuevo equipo entra inmediatamente en acción: un notorio capo de la droga (Olivier Martinez) ofrece cien millones de dólares a quien lo libere del control policial. Mientras custodia al detenido, el equipo S.W.A.T. es perseguido por una implacable y bien armada banda de mercenarios.', trailer_url = 'https://www.youtube.com/watch?v=Q-4MvX9zNgU' WHERE id_api = 'tt0257076';

UPDATE Contenido SET id_tmdb = 2501, descripcion = 'Un hombre amnésico es rescatado por la tripulación de un barco pesquero italiano cuando flota a la deriva en el mar. Carece de identidad y de pasado, pero posee unas serie de talentos extraordinarios en artes lingüísticas, marciales y de autodefensa que sugieren una profesión de riesgo. Confuso y desorientado, emprende una frenética búsqueda para descubrir quién es y por qué su vida ha tomado un giro tan peligroso.', trailer_url = 'https://www.youtube.com/watch?v=PGKK5wACwrU' WHERE id_api = 'tt0258463';

UPDATE Contenido SET id_tmdb = 2755, descripcion = 'La odisea personal de Schmidt comienza cuando su esposa muere inesperadamente. Días después, revisando los objetos personales de su mujer, descubre unas cartas que demuestran que hace veinticinco años tuvo una aventura con su mejor amigo. Destrozado, Schmidt decide adelantar su viaje a Denver, donde se casa su hija. Entonces comienza una odisea llena de encuentros, sorpresas, situaciones cómicas y también agridulces. Al igual que su vida, es un viaje lleno de frustraciones, rechazos, humillaciones y fracasos. Schmidt se da cuenta de que nunca ha hecho nada destacado en la vida, ni tampoco ha hecho nada por mejorar la vida de los demás... hasta que recibe una carta del pequeño Ngudu Ubu.', trailer_url = 'https://www.youtube.com/watch?v=G-dafG40eGU' WHERE id_api = 'tt0257360';

UPDATE Contenido SET id_tmdb = 9296, descripcion = 'Abandonado en mitad de una película por la estrella protagonista, sin tiempo para reaccionar y a punto de arruinarse, Victor decide crear a Simone, una actriz virtual generada por ordenador que sustituirá a la protagonista. La película es un gran éxito y Simone se convierte en un auténtico fenómeno mundial, iniciando una espectacular carrera como actriz. Sólo hay un problema: nadie salvo él sabe que Simone no existe, y después de engañar al estudio y a millones de personas ya es demasiado tarde para confesarlo públicamente', trailer_url = 'https://www.youtube.com/watch?v=mbf76viP-Hc' WHERE id_api = 'tt0258153';

UPDATE Contenido SET id_tmdb = 4547, descripcion = 'La recién separada Meg Altman y su hija Sarah se mudan a una lujosa mansión en Nueva York. Pero cuando tres intrusos invaden brutalmente su hogar, las dos se encierran en "la habitación del antipánico", una cámara oculta construida como refugio, con cuatro muros de hormigón, línea de teléfono independiente, un conjunto de monitores que controlan todos los rincones de la casa y una impenetrable puerta de acero.', trailer_url = 'https://www.youtube.com/watch?v=RC5MMetR3LE' WHERE id_api = 'tt0258000';

UPDATE Contenido SET id_tmdb = 11560, descripcion = 'Claire Kubik es una dinámica abogada de éxito, casada con un contratista, Tom Kubik. Ambos viven en la idílica Marin County, y están muy enamorados, tanto que piensa en ampliar la familia. Una noche, unos ladrones entran en su casa, y a partir de ese momento se suceden una serie de extraños hechos que romperán su vida en pedazos. Poco después del robo, les abordan unos agentes del FBI, y arrestan a Tom en plena calle ante la mirada de Claire. Le acusan de haber asesinado a sangre fría, bajo su verdadero nombre, Ronald Chapman, y su verdadera identidad, militar de operaciones especiales, a nueve civiles en El Salvador en el transcurso de una operación.', trailer_url = 'https://www.youtube.com/watch?v=FD51I774-TQ' WHERE id_api = 'tt0257756';

UPDATE Contenido SET id_tmdb = 8346, descripcion = 'Todos los miembros de la familia Portokalos están preocupados por Toula (Nia Vardalos). A sus treinta años sigue soltera y trabaja en el restaurante griego de sus padres. Pero es que Toula aspira a algo más y está dispuesta a conseguirlo; su familia, por desgracia, no. Lo único que necesitaba Toula para cambiar su vida eran unas cuantas clases de informática, un par de lentillas y adoptar otra actitud. Cuando empieza a trabajar en la agencia de viajes de su tía, un apuesto desconocido se siente atraído por ella. Es Ian Miller (John Corbett), un profesor de instituto alto, guapo y sin una gota de sangre griega.', trailer_url = 'https://www.youtube.com/watch?v=nnVMh3uDwwE' WHERE id_api = 'tt0259446';

UPDATE Contenido SET id_tmdb = 1250, descripcion = 'Adaptación del famoso cómic de la Marvel. Hace mucho tiempo, la superestrella de las acrobacias en moto, Johnny Blaze (Nicolas Cage) hizo un trato con el diablo para proteger a los que más quería: su padre y su novia de la juventud, Roxanne (Eva Mendes). Ahora, el diablo ha venido a cobrar su deuda. De día, Johnny es un motero acróbata temerario... pero de noche, en presencia del diablo, se convierte en Ghost Rider, un cazarecompensas de demonios deshonestos. Obligado a hacer la voluntad del diablo, Johnny está decidido a enfrentarse a su destino y utilizar su maldición y sus poderes para defender al inocente...', trailer_url = 'https://www.youtube.com/watch?v=nu6R7ypaz5g' WHERE id_api = 'tt0259324';

UPDATE Contenido SET id_tmdb = 1903, descripcion = 'Re-boot. David Aames lo tiene todo: es apuesto, tiene dinero y una hermosa mujer a su lado. Pero justo cuando ha encontrado el verdadero amor en Sofía, sufre un accidente de automóvil que le deja la cara horriblemente desfigurada y lo pierde todo.', trailer_url = 'https://www.youtube.com/watch?v=rRUnUbVB-eU' WHERE id_api = 'tt0259711';

UPDATE Contenido SET id_tmdb = 12103, descripcion = 'Tres ejes narrativos independientes uno del otro, que con el correr de los minutos empiezan a conectarse, forman la base a través de la cual se desarrolla la trama de la película. El principal de ellos tiene como centro de acción a Nathan Conrad (Michael Douglas), un brillante psiquiatra de New York que, tras atender a una joven y misteriosa paciente, ve como su vida cambia abruptamente una mañana, cuando su pequeña hija es secuestrada sin motivo aparente. El segundo eje muestra al líder (Sean Bean) de una banda de ladrones de joyas en busca de venganza a cualquier costo luego de haber sido traicionado por unos de sus socios. Y el tercero cierra el triángulo con la investigación que la policía interpretada por Jennifer Esposito inicia a raíz de dos violentos asesinatos.', trailer_url = 'https://www.youtube.com/watch?v=aHASWXlET04' WHERE id_api = 'tt0260866';

UPDATE Contenido SET id_tmdb = 2294, descripcion = 'Cuando Jay y el Bob el Silencioso descubren que se está haciendo una película de Bluntman y Chronic, un cómic de superheroes basado en ellos, se enteran de que su amigo Banky Edwards les ha traicionado y no recibirán derechos de imagen por ella. Tras ver como en internet los acusan de vendidos sin haber visto un dólar, deciden viajar a Hollywood y sabotear la película.', trailer_url = 'https://www.youtube.com/watch?v=HjDSFna_LXQ' WHERE id_api = 'tt0261392';

UPDATE Contenido SET id_tmdb = 10972, descripcion = 'Hace quince años que el Hospital Mental de Danvers (Massachussetts), que se levanta amenazador en medio de un bosque, ha sido cerrado, y los vecinos procuran mantenerse alejados del lugar. Gordon Fleming (Peter Mullan), un emigrante escocés que posee y dirige Hazmat Elimination Co., necesita urgentemente conseguir el contrato para retirar los peligrosos residuos de amianto del hospital. Con tal de cerrar el acuerdo, Gordon, imprudentemente, promete al ingeniero local Bill Griggs (Paul Guilfoyle) que el trabajo durará sólo una semana. Una vez firmado el contrato, los hombres de Hazmat se adentran en los vastos y espeluznantes salones y pasillos del hospital. A medida que pasa el tiempo, el equipo se siente cada vez más arrastrado por los misterios que rodean al hospital.', trailer_url = 'https://www.youtube.com/watch?v=4s-5eJq47bY' WHERE id_api = 'tt0261983';

UPDATE Contenido SET id_tmdb = 640, descripcion = 'Frank Abagnale Jr. trabajó como médico, abogado y copiloto de una de las grandes líneas aéreas, todo ello antes de cumplir los dieciocho años. También fue un genial falsificador y sus habilidades le otorgaron una plaza en la historia. A la edad de 17 años, Frank Abagnale Jr. se convirtió en el ladrón de bancos de más éxito en la historia de Estados Unidos. El agente del FBI Carl Hanratty dedicó la mayor parte de su tiempo a perseguir a Frank para llevarle ante la justicia, pero Frank siempre estaba un paso por delante, retándole a continuar la caza.', trailer_url = 'https://www.youtube.com/watch?v=5HKLlbCIKuw' WHERE id_api = 'tt0264464';

UPDATE Contenido SET id_tmdb = 8922, descripcion = 'Trish y su hermano menor Darry cruzan los Estados Unidos en coche, en un viaje largo y aburrido cuya monotonía sólo se rompe por sus continuas discusiones. De pronto, en mitad de ninguna parte, descubren una iglesia abandonada donde un misterioso personaje arroja un cadáver al interior de una gran boca de alcantarillado. A partir de ese momento comienzan una huida aterradora, perseguidos por una de las criaturas más letales que se puedan imaginar.', trailer_url = 'https://www.youtube.com/watch?v=ACMqG1WdPQk' WHERE id_api = 'tt0263488';

UPDATE Contenido SET id_tmdb = 14926, descripcion = 'Molly Gunn -Brittany Murphy- es la despreocupada hija de una vieja leyenda del rock, y una chica siempre presente en la escena social de Manhattan. Pero cuando su abogado huye robándole toda la herencia y dejándola sin dinero, Molly tiene que dedicarse a algo que nunca pensó que tendría que hacer: conseguir un trabajo. Así, Molly se convierte en la niñera de Ray -Dakota Fanning-, una precoz y madura niña de 8 años emocionalmente distanciada de su madre Roma -Heather Locklear-, una ejecutiva muy ocupada. Molly y Ray no tendrán unos inicios muy cordiales, pero juntas aprenderán mucho la una de la otra y descubrirán la amistad que sólo surge entre almas solitarias.', trailer_url = 'https://www.youtube.com/watch?v=ftSY4DW5tEk' WHERE id_api = 'tt0263757';

UPDATE Contenido SET id_tmdb = 903, descripcion = 'Fumar, beber e insultar a la gente, especialmente a los clientes de su librería, son los pasatiempos favoritos de Bernard Black (Dylan Moran), un misántropo cínico, intolerante y sucio que rara vez expresa o muestra algún sentimiento positivo. Por el contrario, su ayudante y compañero de cuarto, Manny Bianco (Bill Bailey), es una persona agradable, amistosa, trabajadora y alegre. Fran (Tamsin Greig), la dueña de un local contiguo a black Books, es la única y vieja amiga de Bernard.', trailer_url = 'https://www.youtube.com/watch?v=3gy3C7cMNeg' WHERE id_api = 'tt0262150';

UPDATE Contenido SET id_tmdb = 12149, descripcion = 'Un hombre (McConaughey) se presenta en la oficina de Wesley Doyle (Powers Boothe), el agente del FBI encargado de la búsqueda del famoso asesino de Texas conocido como "La Mano de Dios", y asegura que conoce la identidad del escurridizo asesino en serie: se trata de su hermano Adam, quien, después de cometer aquellos crímenes, se suicidó. Al mismo tiempo, intenta explicarle a Doyle las razones que impulsaron a su hermano a matar. (FILMAFFINITY)', trailer_url = 'https://www.youtube.com/watch?v=-j863mgjG9c' WHERE id_api = 'tt0264616';

UPDATE Contenido SET id_tmdb = 10782, descripcion = 'Canal de Panama. 1 de Noviembre. 18:00 horas. Un huracán golpea con fuerza una base del ejército norteamericano y alrededores. Un equipo de Rangers, un cuerpo de élite de operaciones encubiertas, a las órdenes del temible sargento Nathan West (Samuel L. Jackson) se despliega en la jungla en lo que parecen unas simples maniobras. 17 horas después, el sargento y varios miembros de su equipo han desaparecido. Dos soldados son rescatados del lugar de los hechos y cada uno tiene una versión distinta de lo sucedido. El ejército convoca al brillante e indisciplinado interrogador Tom Hardy (John Travolta) para descubrir la verdad. Todo parece indicar que no se trataba de una simple misión de entrenamiento...', trailer_url = 'https://www.youtube.com/watch?v=kE7Ue5hjJc0' WHERE id_api = 'tt0264395';

UPDATE Contenido SET id_tmdb = 1537, descripcion = 'En circunstancias normales, un atasco en hora punta en Nueva York no provocaría una reacción en cadena capaz de destrozar la vida de dos personas. Sin embargo, en este día en concreto, un pequeño choque convertirá a dos hombres en enemigos declarados. Gavin Banek (Ben Affleck) es un abogado de altos vuelos que intenta abrirse camino entre los coches para no llegar tarde a un juicio. Doyle Gipson (Samuel L. Jackson), padre de dos niños, que también se dirige al tribunal donde un juez con una larga lista de casos y poco tiempo que perder va a decidir si Doyle tiene derecho a ver a sus hijos. Un accidente sin importancia llevará a estos dos extraños al borde de la autodestrucción y demostrará que la ira nos convierte a todos en iguales.', trailer_url = 'https://www.youtube.com/watch?v=_9K-uuQJKmQ' WHERE id_api = 'tt0264472';

UPDATE Contenido SET id_tmdb = 11457, descripcion = 'George Monroe (Kevin Kline) es un maduro arquitecto que se propone construir la casa de sus sueños. Pero, cuando decide poner en práctica sus deseos se encuentra sólo: su mujer se ha separado de él, su hijo está enganchado a las drogas y a él le han diagnosticado una grave enfermedad. (FILMAFFINITY)', trailer_url = 'https://www.youtube.com/watch?v=QlAXZclowmI' WHERE id_api = 'tt0264796';

UPDATE Contenido SET id_tmdb = 855, descripcion = 'Octubre de 1993. Soldados americanos de élite son enviados a Mogadiscio (Somalia) en una misión de paz de las Naciones Unidas. El fin se supone que es salvar vidas, no segarlas. Pero resulta que el principal objetivo de la misión es capturar al caudillo Aidid y acabar de raíz con la guerra. Al principio, todo parece ir bien, hasta que dos helicópteros Black Hawk, aparentemente invencibles, son derribados. Entonces la misión se convierte en una desesperada carrera para rescatar a la tripulación y a los soldados de tierra que han quedado atrapados o han resultado heridos en el accidente.', trailer_url = 'https://www.youtube.com/watch?v=_vJltamBoy8' WHERE id_api = 'tt0265086';

UPDATE Contenido SET id_tmdb = 11892, descripcion = 'Una pareja de adolescentes -Richard (Ryan Gosling), el más popular de clase, y el tímido Justin (Michael Pitt)-, ambos de buena familia y con una mente fría y siniestra, intentan conseguir el crimen perfecto. Para demostrarlo asesinan a una mujer con el único fin de demostrar que son lo suficientemente inteligentes como para salir impunes de cualquier situación. La detective Cassie Mayweather (Sandra Bullock, también la productora ejecutiva del film) y su compañero Sam (Ben Chaplin) serán los encargados de investigar el caso.', trailer_url = 'https://www.youtube.com/watch?v=RDEAL9vbpM0' WHERE id_api = 'tt0264935';

UPDATE Contenido SET id_tmdb = 11467, descripcion = 'Kiki (Julia Roberts) es hermana y ayudante de una famosa e insoportable estrella de Hollywood (Catherine Zeta-Jones). Para seguir en el candelero no le queda otro remedio que presentar una nueva película con su ex-novio (John Cusack), otro actor famoso, desengañado del mundo del cine, por el que Kiki se siente atraída.', trailer_url = 'https://www.youtube.com/watch?v=nE1ONQjgqqg' WHERE id_api = 'tt0265029';

UPDATE Contenido SET id_tmdb = 10591, descripcion = 'Matthew, un ambicioso joven de un instituto con aspiraciones a ser político en el futuro, se enamora de la chica de sus sueños: la bella y joven vecina de la puerta de al lado. Ambos comienzan un idílico romance, pero un sorprendente descubrimiento pondrá a prueba su relación: ella es un famosa actriz porno.', trailer_url = 'https://www.youtube.com/watch?v=Telaow2niS8' WHERE id_api = 'tt0265208';

UPDATE Contenido SET id_tmdb = 11469, descripcion = 'Jamal se afana infeliz en Medieval World, un parque temático que parece que no ha sido renovado, o ha tenido clientes desde la Época Oscura. Después de caer en el fétido foso del parque, Jamal llega al siglo XIV en Inglaterra, un mundo de caballeros con brillantes armaduras y damiselas afligidas, sin mencionar la higiene cuestionable. Ahora es un extraño en una muy extraña tierra, Jamal conoce a un caballero libertino, una bella mujer con ideas muy modernas y una rebelión en contra del diabólico Rey...', trailer_url = 'https://www.youtube.com/watch?v=lw7dzS8UJ4Q' WHERE id_api = 'tt0265087';

UPDATE Contenido SET id_tmdb = 2637, descripcion = 'Basada en hechos reales, la película examina una serie de acontecimientos inexplicables a través de los ojos –y la mente– de un hombre. Richard Gere, Laura Linney, Will Patton y Debra Messing interpretan este thriller lleno de suspense que cuenta la historia de un hombre que llega al extremo de investigar las misteriosas circunstancias que rodearon la muerte de su esposa y cómo éstas podrían estar conectadas con los extraños fenómenos que ocurren en un pueblo situado a cuatrocientas millas.', trailer_url = 'https://www.youtube.com/watch?v=Yt42df3AscE' WHERE id_api = 'tt0265349';

UPDATE Contenido SET id_tmdb = 9357, descripcion = 'Sy Parrish es un hombre anodino y tímido que dirige desde hace años el laboratorio fotográfico de los grandes almacenes “SavMart”. Vive solo, adora su trabajo y es un auténtico perfeccionista a la hora de revelar los negativos. Cientos de fotos, en las que aparece la familia Yorkin, tapizan las paredes de su vivienda. Desde hace años, los Yorkin llevan sus fotos a revelar a SavMart. Son una perfecta familia de los suburbios y Sy no puede resistirse a seguir sus vidas a través de las copias de sus fotos. Pero un día, el director de los grandes almacenes, Bill Owens, lo despide. Sy consigue hacerse con una serie de fotografías donde aparece Will Yorkin en pleno adulterio y, consternado por el comportamiento del padre de esta familia “perfecta”, Sy decide hacer algo al respecto.', trailer_url = 'https://www.youtube.com/watch?v=eWzILZ6wE9Y' WHERE id_api = 'tt0265459';

UPDATE Contenido SET id_tmdb = 3176, descripcion = 'En el amanecer de un nuevo milenio, el país está al borde del colapso. Millones de personas vagan sin empleo. La violencia en la escuela está descontrolada y adolescentes rebeldes protagonizan boicots masivos. El gobierno contrataca con “Battle Royale”. Cada año, una clase es escogida al azar para que se enfrente, en una isla abandonada, a un cruel juego de supervivencia.', trailer_url = 'https://www.youtube.com/watch?v=hCoPbkvyWEI' WHERE id_api = 'tt0266308';

UPDATE Contenido SET id_tmdb = 9428, descripcion = 'Royal Tenenbaum y su mujer Etheline, después de tener tres hijos, Chas, Richie y Margot, se han separado. Chas, que trabaja en el sector inmobiliario, parecía tener un don innato para las finanzas internacionales. Margot fue dramaturga y obtuvo una beca Braverman de 50.000 dólares cuando aún estaba en el instituto. Richie fue campeón junior de tenis y ganó los campeonatos de Estados Unidos tres años consecutivos. Pero todos los brillantes recuerdos de los jóvenes Tenenbaums quedan repentinamente borrados por dos décadas de traiciones, fracasos y decepciones de las que consideran que su padre es el principal responsable.', trailer_url = 'https://www.youtube.com/watch?v=-DNAI9bhBFU' WHERE id_api = 'tt0265666';

UPDATE Contenido SET id_tmdb = 4546, descripcion = 'Hay personas que parecen haber sido maldecidas con la ley de Murphy: si algo tiene la posibilidad de salir mal, saldrá mal. Larry David se considera una de ellas. El creador y productor de Seinfield, una de los programas más laureados de la historia de la televisión, se interpreta a sí mismo en esta rompedora serie donde, en un ambiguo punto entre la realidad y la ficción, seguimos su día a día que se desarrolla entre celebridades y gente de la calle que nunca sabemos si están o no interpretando un guión. Somos así testigos de su peculiar y ácida visión de todo lo que le rodea y de su don para convertir situaciones cotidianas como ir al cine o atender una llamada telefónica en verdaderos despropósitos.', trailer_url = 'https://www.youtube.com/watch?v=ltY335eAbOA' WHERE id_api = 'tt0264235';

UPDATE Contenido SET id_tmdb = 8409, descripcion = 'Sean Vetter es un agente de aduanas especializado en la lucha contra el tráfico de drogas en el sur de California. Allí trabaja duramente para dar caza al mayor capo de la zona, Memo Gamboa. Todo cambia cuando asesinan a su mujer. Convencido de que Gamboa es el responsable del crimen, decide tomarse la justicia por su mano. Pero pronto descubre que el capo es solo una marioneta: por encima hay alguien que mueve los hilos. Responde al nombre de Diablo.', trailer_url = 'https://www.youtube.com/watch?v=Nxv0VLPy2_o' WHERE id_api = 'tt0266465';

UPDATE Contenido SET id_tmdb = 12, descripcion = 'Nemo, un pececillo, hijo único muy querido y protegido por su padre, ha sido capturado en un arrecife australiano y ahora vive en una pecera en la oficina de un dentista de Sidney. El tímido padre de Nemo se embarcará en una peligrosa aventura para rescatar a su hijo. Pero Nemo y sus nuevos amigos tienen también un astuto plan para escapar de la pecera y volver al mar.', trailer_url = 'https://www.youtube.com/watch?v=ABDiB48VPJc' WHERE id_api = 'tt0266543';

UPDATE Contenido SET id_tmdb = 24, descripcion = 'Uma Thurman es una asesina que, el día de su boda, es atacada por los miembros de la banda de su jefe, Bill (David Carradine). Logra sobrevivir al ataque, aunque queda en coma. Cinco años después despierta con un trozo de metal en la cabeza y un gran deseo de venganza en su corazón.', trailer_url = 'https://www.youtube.com/watch?v=wskEQT7sOxo' WHERE id_api = 'tt0266697';

UPDATE Contenido SET id_tmdb = 7288, descripcion = 'Alex y Nancy forman una joven y dinámica pareja de Nueva York con un brillante futuro por delante. Sólo les falta una cosa: una casa propia. El problema surge cuando su nueva casa viene con "algo" con lo que no contaban: la Sra. Connelly, la arrendataria del piso de arriba, que es mucho menos cordial y delicada de lo que Alex y Nancy pensaron en un principio.', trailer_url = 'https://www.youtube.com/watch?v=_7hzLSja8sg' WHERE id_api = 'tt0266489';

UPDATE Contenido SET id_tmdb = 1535, descripcion = 'Corre el año 1991, y al veterano agente de la CIA Nathan Muir tan sólo le queda un día para retirarse, cuando recibe la noticia de que aquel que fuera su discípulo, Tom Bishop, está en un buen lío. Hecho preso en una cárcel extranjera bajo la acusación de espionaje, Bishop ha sido hallado culpable y se prevé ejecutarlo en 24 horas. Temiendo un incidente de alcance internacional, la CIA decide que es muy arriesgado tratar de salvarlo. Así las cosas, todo depende de Muir. Habiendo toda una nueva generación al cargo de la Agencia, Muir, partidario de los antiguos métodos, está a punto de dejar de pertenecer a la organización a la que ha servido durante tantos años, y deberá hallar el modo de burlarla mientras batalla por conseguir más detalles acerca de la situación de Bishop.', trailer_url = 'https://www.youtube.com/watch?v=VbOTZMNOECo' WHERE id_api = 'tt0266987';

UPDATE Contenido SET id_tmdb = 5175, descripcion = 'El detective James Carter se encuentra de vacaciones en Hong Kong con su buen amigo el detective Lee. Mientras Carter está ansioso por dedicarse a la juerga y las mujeres, Lee tiene que enfrentarse con un jefe de las Tríadas, responsable del asesinato de dos funcionarios de la embajada norteamericana. Conforme avancen en la investigación, descubrirán una trama de distribución de billetes falsos.', trailer_url = 'https://www.youtube.com/watch?v=SCTzYY95Aw4' WHERE id_api = 'tt0266915';

UPDATE Contenido SET id_tmdb = 9637, descripcion = 'Basada en los personajes de la serie Scooby-Doo, creados por Hanna Barbera.  Dos años después de que un choque de egos obligase a Mystery Inc. a cerrar sus puertas, Scooby-Doo y sus avispados amigos son llamados individualmente a Spooky Island para investigar una serie de incidentes paranormales en el parque de atracciones. El propietario de Spooky Island, Emile Mondavarious trata de volver a unir a los jóvenes para que resuelvan el misterio antes de que su secreto sobrenatural ahuyente a la multitud de universitarios que lo frecuentan.', trailer_url = 'https://www.youtube.com/watch?v=2GV_eLwNAjc' WHERE id_api = 'tt0267913';

UPDATE Contenido SET id_tmdb = 8665, descripcion = 'Querido y de confianza para sus hombres, respetado como el capitán de submarinos con mayor experiencia de la Marina soviética, el Capitán Mikhail Polenin (Liam Neeson) es destituido del mando del K-19 cuando el liderazgo soviético decide que no está preparando su submarino insignia lo suficientemente rápido para su primera travesía. En su lugar, el Capitán Alexei Vostrikov (Harrison Ford), un oficial estrictamente "orientado a la misión" y con una voluntad de hierro, consigue sacar el K-19 al mar exactamente a la hora programada 16:00 horas del día 18 de Junio de 1961.', trailer_url = 'https://www.youtube.com/watch?v=BvHWH8xg0Rw' WHERE id_api = 'tt0267626';

UPDATE Contenido SET id_tmdb = 10796, descripcion = 'En un mundo futuro se ha descubierto que existen vidas alternas en universos alternos, un hecho que los agentes del Departamento Multiverse defienden, excepto el investigador Yulaw. Yulaw ha atravesado 123 universos persiguiendo y destruyendo sus vidas alternas. A medida que las mata, absorbe la fuerza de esas vidas alternas, ganando habilidades sobrehumanas. La magnitud de tal fenómeno puede desequilibrar el delicado equilibrio de todos los universos, sobre todo cuando a Yulaw ya sólo le queda eliminar a la última de sus vidas alternas. Ese personaje, Gabriel Yulaw, es agente de policía honesto y buen marido, y su vida se ve alterada cuando el otro Yulaw entra en su universo. Para salvarse a sí mismo, la única alternativa que le queda es la de matar a su yo malvado del otro universo.', trailer_url = 'https://www.youtube.com/watch?v=LfeIezSuRj4' WHERE id_api = 'tt0267804';

UPDATE Contenido SET id_tmdb = 425, descripcion = 'Hace muchos, muchos años, tantos como 20.000, una pequeña ardirata de nombre Scrat quería esconder una bellota en el hielo. Pero lo que hace es provocar una semicatástrofe que provoca que todos los animales migren hacia el sur, hacia tierras más cálidas. Bueno, lo que se dice todos, todos, no. Porque hay uno que lleva la contraria: se trata del mamut Manfred, un auténtico lobo solitario vagabundo y soberbio que va hacia el norte sólo porque los demás están yendo hacia el sur.', trailer_url = 'https://www.youtube.com/watch?v=QbLTkAI-0B0' WHERE id_api = 'tt0268380';

UPDATE Contenido SET id_tmdb = 2135, descripcion = 'El científico e inventor Alexander Hartdegen ha tomado la decisión de probar que los viajes a través del tiempo son posibles. Una tragedia personal que lo ha sumido en la desesperación es la razón de su deseo de volver al pasado. Pero la máquina de su invención, en contra de sus deseos, lo lleva al futuro (800.000 después), donde descubre que la humanidad se ha dividido en dos bandos: perseguidores y perseguidos.', trailer_url = 'https://www.youtube.com/watch?v=TgQSRR2yxR0' WHERE id_api = 'tt0268695';

UPDATE Contenido SET id_tmdb = 2757, descripcion = 'Charlie Kaufman, un guionista de Los Ángeles, vive un periodo de crisis creativa, todo lo contrario que su hermano gemelo Donald. Charlie escribe tal como vive: con gran dificultad y lleno de inseguridades, mientras que Donald vive tal como escribe: con dejadez. Por su parte, Susan escribe sobre la vida, pero es incapaz de vivirla. Por el contrario, la intensa y aventurera vida de John es digna de una novela.', trailer_url = 'https://www.youtube.com/watch?v=pK5jYt9QNIY' WHERE id_api = 'tt0268126';

UPDATE Contenido SET id_tmdb = 4912, descripcion = 'Historia de un famoso empresario del mundo del espectáculo de doble vida -productor de televisión de día, asesino de la CIA por la noche-. En lo más alto de su carrera, Chuck Barris fue reclutado por la agencia gubernamental americana para convertirse en uno de sus agentes. Escrita por Charlie Kaufman -"Being John Malkovich", según la famosa autobiografía no autorizada del propio Chuck Barris. En Estados Unidos obtuvo bastante buenas críticas.', trailer_url = 'https://www.youtube.com/watch?v=mWyLE7kjGrw' WHERE id_api = 'tt0270288';

UPDATE Contenido SET id_tmdb = 2140, descripcion = 'Liu Jian (Jet Li) es un experto agente del gobierno chino que llega a París desde Shanghai para desarrollar una delicada y ultrasecreta misión. Liu va a París para ayudar a Richard (Tchéky Karyo), un poco ortodoxo oficial de policía con un pequeño ejército a sus órdenes. La misión es un completo desastre, pues el hombre al que Liu ha de ayudar le traiciona. Liu se ve atrapado en una vasta y mortal conspiración: acusado de un asesinato que no ha cometido y perseguido en una ciudad que no conoce. Sin ningún lugar a dónde dirigirse, Liu se une a una chica americana llamada Jessica (Bridget Fonda), a quien Richard ha obligado a ejercer la prostitución. Mientras Jessica y Liu conspiran contra su taimado y cruel adversario que ha puesto ya en marcha sus respectivas trampas, Liu hace a Jessica una promesa que podría poner en peligro su carrera e incluso su vida.', trailer_url = 'https://www.youtube.com/watch?v=pZUCr_vlO8Q' WHERE id_api = 'tt0271027';

UPDATE Contenido SET id_tmdb = 453, descripcion = 'Obsesionado con la búsqueda de una idea matemática original, el brillante estudiante John Forbes Nash llega a Princeton para realizar sus estudios de postgrado. Es un muchacho extraño y solitario, al que sólo comprende su compañero de cuarto. Por fin, Nash esboza una revolucionaria teoría y consigue una plaza de profesor en el MIT. Alicia Lardé, una de sus alumnas, lo deja fascinado al mostrarle que las leyes del amor están por encima de las de las matemáticas. Gracias a su prodigiosa habilidad para descifrar códigos es reclutado por Parcher William, del departamento de Defensa, para ayudar a los Estados Unidos en la Guerra Fría contra la Unión Soviética.', trailer_url = 'https://www.youtube.com/watch?v=bsz0Ptx1htE' WHERE id_api = 'tt0268978';

UPDATE Contenido SET id_tmdb = 11086, descripcion = 'El guionista Peter Appleton se ve obligado a huir de Hollywood a causa de la caza de brujas emprendida por el senador McCarthy en la década de 1950. Tras sufrir un accidente de coche que le provoca amnesia, es rescatado por los habitantes de un pueblo.', trailer_url = 'https://www.youtube.com/watch?v=zbI-IVRinK4' WHERE id_api = 'tt0268995';

UPDATE Contenido SET id_tmdb = 10632, descripcion = 'El FBI investiga una serie de asesinatos cometidos en un bosque. Un agente especializado en rastreos (Jones) captura al asesino (Del Toro), que resulta ser un soldado que había estado a sus órdenes en misiones peligrosas, pero que, tras una experiencia traumática en Kosovo, se dedica a la caza de seres humanos. Cuando el detenido escapa, empieza una nueva partida de caza.', trailer_url = 'https://www.youtube.com/watch?v=53AH-k3go7U' WHERE id_api = 'tt0269347';

UPDATE Contenido SET id_tmdb = 8869, descripcion = 'Un accidente provoca que un barril de residuos tóxicos caiga en un lago cerca de un pueblo minero de Arizona. El veneno afecta a las arañas exóticas que un entomólogo tiene en su museo y las hace crecer hasta proporciones gigantescas. Chris (David Arquette), el dueño de las minas, se une a la sheriff Sam (Kari Wuhrer) y a su hijo Mike (Scott Terra), un experto en arácnidos, para detener a las monstruosas criaturas que amenazan con devorar a los habitantes del pueblo. Con la ayuda de otros personajes pintorescos, tendrán que enfrentarse a las hambrientas arañas y evitar que se extiendan por el mundo.', trailer_url = 'https://www.youtube.com/watch?v=3NLara5CJ3I' WHERE id_api = 'tt0271367';

UPDATE Contenido SET id_tmdb = 11078, descripcion = 'Earl Montgomery (Lawrence) es un engreído e hiperactivo cadete de la Policía de Los Ángeles que, a causa de su mala actitud, es expulsado de la academia. Tras ser arrestado en un incidente con su vehículo por el policía Hank Rafferty (Zahn), Earl lo acusa de acoso y, como consecuencia, el agente ingresa en prisión durante seis meses. En ese tiempo, Earl acepta un humilde puesto de trabajo como guardia de seguridad en Seguridad Nacional, el mismo empleo que consigue Hank tras abandonar la cárcel. Es entonces cuando Earl descubre una sofisticada operación de contrabando que ya le costó la vida a su compañero meses atrás y en la que podría estar implicado el propio Departamento de Policía.', trailer_url = 'https://www.youtube.com/watch?v=pra0Mwr0ao8' WHERE id_api = 'tt0271668';

UPDATE Contenido SET id_tmdb = 2100, descripcion = 'Acusado de un acto de desobediencia que tuvo fatales consecuencias, el venerado general Irwin, un héroe de guerra, es sometido a un consejo de guerra, degradado y encerrado en una prisión militar conocida como ''La fortaleza''. Allí pronto se convierte en el punto de mira del alcaide, el coronel Winter, un hombre de carácter autoritario que comienza a sentirse acomplejado ante el carisma de Irwin con los reclusos.', trailer_url = 'https://www.youtube.com/watch?v=THWd2Qtp_mo' WHERE id_api = 'tt0272020';

UPDATE Contenido SET id_tmdb = 167, descripcion = 'El estado emocional del Dr. Powell está siendo desafiado por uno de sus pacientes en el pabellón de psiquiatría; Prot, quien reclama ser de otro planeta, ha anunciado su partida de la tierra, y el resto de los pacientes se apuntan también para ir con él. Esta situación deja al Dr. Powell preguntándose acerca de sus propias habilidades para distinguir la realidad de la fantasía.', trailer_url = 'https://www.youtube.com/watch?v=3x2yapXgZLc' WHERE id_api = 'tt0272152';

UPDATE Contenido SET id_tmdb = 11022, descripcion = 'Un agente secreto se ve obligado a colaborar en el caso del asesinato de un policía, al desvanecerse el rastro que seguían en la investigación.', trailer_url = 'https://www.youtube.com/watch?v=f3sk4PIBfbk' WHERE id_api = 'tt0272207';

UPDATE Contenido SET id_tmdb = 8051, descripcion = 'Barry (Adam Sandler) es un tipo solitario y poco sociable que fue educado entre siete hermanas. La sobreprotección que se le dispensó desde niño le ha impedido enamorarse. Un día descubre un fallo en un concurso y gana miles de millas en billetes de avión. Viajando, conoce a una misteriosa mujer (Emily Watson) con la que inicia una romántica aventura. (FILMAFFINITY)', trailer_url = 'https://www.youtube.com/watch?v=9pG2nfxoUcs' WHERE id_api = 'tt0272338';

UPDATE Contenido SET id_tmdb = 11857, descripcion = 'Colin Hanks, un brillante joven del condado de Orange, desea ingresar en la universidad de Stanford y convertirse en escritor; pero, por desgracia, su solicitud de ingreso cae en manos de un despistado tutor que la extravía. El joven no se rinde y con la ayuda de su novia y de su hermano llegará a conseguir su propósito.', trailer_url = 'https://www.youtube.com/watch?v=DigaxGStjC8' WHERE id_api = 'tt0273923';

UPDATE Contenido SET id_tmdb = 9486, descripcion = 'Las joyas de la Corona de su Majestad han desaparecido. Detrás de ello se esconde Pascal Sauvage (John Malkovich), que también conspira para hacerse con el trono de la reina. La misión es asignada a Johnny English (Rowan Atkinson), un agente tan entregado al trabajo como inexperto. Desde ese momento la información confidencial, los coches de lujo y la tecnología más sofisticada forman parte de su rutina diaria. Johnny English aún no se lo acaba de creer. Quizás todo esto le venga algo grande, pero su empeño con la misión y dedicación para llegar hasta el final es incuestionable, especialmente después de conocer a la agente doble Lorna Campbell (Natalie Imbruglia). Parece ser que lo de estar enamorado aún hará más emocionante esto de salvar al país...', trailer_url = 'https://www.youtube.com/watch?v=7VlpHnog6rw' WHERE id_api = 'tt0274166';

UPDATE Contenido SET id_tmdb = 590, descripcion = 'Las Horas es una tragedia melancólica, basada en el libro de Virginia Woolf "Mrs. Dalloway", sobre tres mujeres condenadas a la depresión. Stephaen Daldry, el director, presenta  la vida y los cambios psicóticos de la excepcional autora inglesa interpretada por Nicole Kidman, que ganó el Oscar a la mejor actriz.', trailer_url = 'https://www.youtube.com/watch?v=CkPWXUxIiXs' WHERE id_api = 'tt0274558';

UPDATE Contenido SET id_tmdb = 11013, descripcion = 'Lee Holloway  tiene el peor de los currículum cuando decide solicitar un empleo de secretaria en el bufete de abogados de E. Edward Grey. Basta con decir que acaba de salir de una institución psiquiátrica y que, tan sólo un día después de volver a estar con su disfuncional familia de barrio periférico, ha recaído ya en su hábito secreto e inconfesable. Pese a que nunca en su vida ha tenido trabajo, Lee resulta finalmente contratada por el Sr. Grey, un misterioso abogado. Al principio el trabajo parece normal: mecanografiar cartas, archivar documentos y hacer el café; pero Lee y el Sr. Grey no tardan en embarcarse en una relación mucho más estrecha e íntima; una relación que haría sonrojar a cualquier jefe de personal.', trailer_url = 'https://www.youtube.com/watch?v=00zGV6p-dKc' WHERE id_api = 'tt0274812';

UPDATE Contenido SET id_tmdb = 11544, descripcion = 'Lilo es una niña hawaiana que se siente sola y decide adoptar un "perro" muy feo al que llama Stitch. Stitch sería la mascota perfecta... si no fuera en realidad un experimento genético que ha escapado de un planeta alienígena y que ha aterrizado por casualidad en la tierra.', trailer_url = 'https://www.youtube.com/watch?v=wAtaSKQ4-T0' WHERE id_api = 'tt0275847';

UPDATE Contenido SET id_tmdb = 17130, descripcion = 'La historia de tres amigas de la infancia, Lucy, Kit y Mimi, quienes después de ocho años deciden redescubrir su amistad y realizan un viaje con el apuesto y misterioso amigo de Mimi, Ben. Su aventura será una lección que cambiará sus vidas para siempre.', trailer_url = 'https://www.youtube.com/watch?v=7bdelecH5cw' WHERE id_api = 'tt0275022';

UPDATE Contenido SET id_tmdb = 11299, descripcion = 'Marte, año 2071, poco antes del día de Halloween. Un camión cisterna lleno de productos químicos hace explosión en una de las calles más importantes de la ciudad, liberando un nuevo virus letal que acaba con la vida de cientos de personas. Las autoridades, temiendo un nuevo ataque aún más destructivo, fijan una recompensa millonaria para quien capture a los responsables. Mientras tanto, en la nave "Bebop", Spike y su banda de cazadores de recompensas están aburridos y sin dinero, hasta que conocen la noticia de la recompensa...', trailer_url = 'https://www.youtube.com/watch?v=c8GpwQz_eH8' WHERE id_api = 'tt0275277';

UPDATE Contenido SET id_tmdb = 10950, descripcion = 'Sam Dawson (Sean Penn) es un deficiente mental que deberá luchar por conservar la custodia de su pequeña hija, ya que el Estado considera que no está capacitado para hacerse cargo de su educación. De su defensa se encargará una prestigiosa abogada, Rita Harrison (Michelle Pfeiffer), cuyo desinterés y frialdad inicial cambiarán tras conocer a Sam, descubrir el amor que siente por su hija y comprobar su determinación por defender sus derechos como padre.', trailer_url = 'https://www.youtube.com/watch?v=D4qRwmaYN7g' WHERE id_api = 'tt0277027';

UPDATE Contenido SET id_tmdb = 1618, descripcion = 'Durante una reunión de las Naciones Unidas se llega a un acuerdo mundial de desarme, confiando la protección del mundo a Superman. Pero poco después del desarme, una raza de poderosos alienígenas atacan la Tierra desde Marte, con aparatos similares a los descriptos en la novela La guerra de los mundos. Durante el combate, Superman recibe un llamado de un marciano mantenido cautivo en una instalación gubernamental, el último sobreviviente de su raza, atacada por los mismos seres que atacan la Tierra. Pronto se arma un equipo entre 7 super héroes: Superman, Batman, Flash, el mencionado marciano (llamado J''onn), los héroes galácticos Linterna Verde y Chica Halcón y la Mujer Maravilla que abandonó su isla (Temiscira, protegida por los dioses) para salvar el mundo de los hombres. Así nació la liga de la justicia...', trailer_url = 'https://www.youtube.com/watch?v=MXph0arElKs' WHERE id_api = 'tt0275137';

UPDATE Contenido SET id_tmdb = 140, descripcion = 'En esta película, Pedro Almodóvar explora el abuso sexual en la Iglesia Católica española durante la década de 1960. La película trata sobre dos niños que son maltratados en una escuela católica y de las luchas a las que se tienen que enfrentar más tarde con su identidad sexual y el odio hacia los sacerdotes.', trailer_url = 'https://www.youtube.com/watch?v=sXgAL_vfzqE' WHERE id_api = 'tt0275491';

UPDATE Contenido SET id_tmdb = 245, descripcion = 'Will Lightman (Hugh Grant) es un soltero de 38 años que vive de los derechos de autor de una canción compuesta hace años por su padre. Su miedo al compromiso es tal que sólo se relaciona con madres solteras, porque piensa que es más fácil romper con ellas. Sin embargo, sus convicciones se tambalean cuando se convierte en el mejor amigo de Marcus, un niño de 12 años al que conoce en una de sus citas.', trailer_url = 'https://www.youtube.com/watch?v=qEks0V9OFbE' WHERE id_api = 'tt0276751';

UPDATE Contenido SET id_tmdb = 9334, descripcion = 'La historia se sitúa hace 5000 años en la célebre ciudad de Gomorrah, en la cual un malvado gobernador decide arrasar con todas las tribus nómadas del desierto. Las pocas tribús que sobreviven, que por naturaleza nunca han sido aliadas, deben unirse o morir. Sabiendo que su enemigo confía en las predicciones de un brujo, contratan a un afamado asesino, Mathayus, para que liquide al vidente. Tras infiltrarse en el campamento enemigo, Mathayus descubre que el brujo es una bella mujer. En lugar de asesinarla la conduce a los páramos del desierto profundo, sabiendo que los hombres del gobernador harán cualquier cosa con tal de rescatarla y llevarla de nuevo a su campamento. Gravemente herido tras la batalla, Mathayus debe encontrar la fuerza para llevar a sus exhautos aliados de vuelta a Gomorrah para luchar en la batalla final.', trailer_url = 'https://www.youtube.com/watch?v=BDWrB-VteOg' WHERE id_api = 'tt0277296';

UPDATE Contenido SET id_tmdb = 10590, descripcion = 'En plena guerra del Vietnam, el coronel Hal Moore y sus soldados (unos 400 hombres) aterrizaron en noviembre de 1965 en una región conocida como "El valle de la muerte". Allí fueron recibidos por más de 2.000 soldados del Vietcong, desencadenándose una de las batallas más feroces de la guerra.', trailer_url = 'https://www.youtube.com/watch?v=lLIZNfdIuhk' WHERE id_api = 'tt0277434';

UPDATE Contenido SET id_tmdb = 553, descripcion = 'Grace llega a la remota localidad de Dogville huyendo de una banda de «gangsters». Persuadidos por las palabras de Tom, que se ha erigido en portavoz de la pequeña comunidad, sus integrantes se avienen a ocultarla. Grace, en justa correspondencia, acepta trabajar para ellos. Sin embargo, cuando Dogville sea sometido a una intensa vigilancia policial para dar con la fugitiva, sus habitantes exigirán un acuerdo más favorable, que les compense del peligro que corren al darle cobijo. Grace aprenderá, de un modo brutal, que en este lugar la bondad es algo muy relativo. Pero ella guarda un secreto que no quiere desvelar.', trailer_url = 'https://www.youtube.com/watch?v=J5-LqwUHTaM' WHERE id_api = 'tt0276919';

UPDATE Contenido SET id_tmdb = 11397, descripcion = 'En el instituto John Hughes los chicos son como cualquier adolescente en cualquier otra peli de adolescentes. El chico deportista y popular apuesta con Austin, el rubito guapo, a que es capaz de transformar a Janey, la fea del colegio, en la reina del baile de fin de curso. Pero dos maquiavélicas compañeras intentarán que Jake pierda la apuesta: su hermana Catherine y Priscilla, la jefa de las animadoras. El resto de la pandilla tampoco es muy distinta a la de cualquier otra película de adolescentes americana. Y claro; los alumnos del instituto viven un curso lleno de fiestas, diversión, alcohol y sexo.', trailer_url = 'https://www.youtube.com/watch?v=f1sbQf58B50' WHERE id_api = 'tt0277371';

UPDATE Contenido SET id_tmdb = 1957, descripcion = 'Slim es una vulgar camarera que cree que su vida ha cambiado cuando se casa con Mitch, un rico contratista al que considera el hombre de su vida. Comienzan una idílica vida juntos en una zona residencial a las afueras de la ciudad y viven como una pareja normal. Hasta que nace su hija Grace.', trailer_url = 'https://www.youtube.com/watch?v=0tahxDOAzT4' WHERE id_api = 'tt0278435';

UPDATE Contenido SET id_tmdb = 8386, descripcion = 'Dos tipos consiguen una hierba que les convierte en tremendamente listos. Consiguen así ser aceptados en Harvard, pero, una vez en la universidad, sus existencias de la hierba se acaban, y tendrán que desenvolverse por sí mismos.', trailer_url = 'https://www.youtube.com/watch?v=B5h2xRYmANk' WHERE id_api = 'tt0278488';

UPDATE Contenido SET id_tmdb = 320, descripcion = 'Will Dormer, un veterano detective de Los Ángeles, viaja a un pequeño pueblo de Alaska con su compañero Hap para investigar el asesinato de una chica de 17 años. En Los Ángeles queda pendiente un oscuro asunto que les incumbe a los dos. Una vez en Alaska, entran en contacto con el principal sospechoso, Walter Finch, un novelista ermitaño.', trailer_url = 'https://www.youtube.com/watch?v=Eby9E9TBYOc' WHERE id_api = 'tt0278504';

