UPDATE Contenido SET id_tmdb = 2723, descripcion = 'Samurai Jack cuenta la historia de un joven príncipe cuyo imperio ha sido destruido por un demonio caído de los cielos llamado Aku. Jack consigue huir de la destrucción y dedica el resto de su vida a entrenarse para poder recuperar su reino y derrotar Aku, vengando así la muerte de todo su pueblo.', trailer_url = 'https://www.youtube.com/watch?v=VSrv_n4tw7w' WHERE id_api = 'tt0278238';

UPDATE Contenido SET id_tmdb = 9962, descripcion = 'Justine ya no es una niña. Ha crecido, se ha casado y está dispuesta a formar una familia. Sin duda su marido Phil la quiere, pero ya hace tiempo que intenta sin éxito tener un niño. Justine se pregunta si la marihuana que fuma su marido con su mejor amigo Bubba podría ser la causa. Un día en el trabajo, Justine descubre una especie de alma gemela en un compañero del trabajo, Holden, un joven creativo y apasionado que representa una oportunidad para Justine de escapar hacia un nuevo mundo de despertar emocional y sexual.', trailer_url = 'https://www.youtube.com/watch?v=55u2eXwbkM4' WHERE id_api = 'tt0279113';

UPDATE Contenido SET id_tmdb = 3132, descripcion = 'Oakes, un veterano agente de la CIA, debe convertir a Jake Hayes, un buscavidas callejero, en un espía astuto y sofisticado para que sustituya a su hermano gemelo que ha sido asesinado. Oakes, que ni siquiera sabía que tuviera un hermano, debe cumplir esta misión antes de que se celebre una negociación para alcanzar un acuerdo sobre armas nucleares, de modo que dispone tan sólo de nueve días.', trailer_url = 'https://www.youtube.com/watch?v=HddSL5meQ6k' WHERE id_api = 'tt0280486';

UPDATE Contenido SET id_tmdb = 11880, descripcion = 'Una escuadrón de soldados británicos, de entrenamiento por los remotos páramos escoceses, encuentar a un capitán de las fuerzas especiales herido, y los restos de su equipo... Parece ser que unos sanguinarios hombres lobos merodean por esa región, y esa noche es luna llena.', trailer_url = 'https://www.youtube.com/watch?v=Zw2-Pl61tp8' WHERE id_api = 'tt0280609';

UPDATE Contenido SET id_tmdb = 2022, descripcion = 'Deeds (Adam Sandler) es un ingenuo provinciano que vive en un pueblo de New Hampshire. Como propietario de "Deeds’ Pizza", la única pizzeria del pueblo, se ha hecho muy popular por su particular manera de entretener a los clientes recitándoles sus insólitos poemas. La vida transcurre plácidamente hasta que recibe la noticia de que un pariente lejano le ha dejado una herencia de cuarenta billones de dólares, una cadena de medios de comunicación, un equipo de fútbol, un equipo de baloncesto y un helicóptero privado.', trailer_url = 'https://www.youtube.com/watch?v=ASw47FiEhes' WHERE id_api = 'tt0280590';

UPDATE Contenido SET id_tmdb = 10229, descripcion = 'Jamie era la última persona de la que se enamoraría Landon. Demasiado seria y conservadora para su gusto. Hija de un pastor de la iglesia baptista, Jamie no tenía miedo de manifestar que la fe era lo más importante en su vida, aunque ello le costara las críticas de sus compañeros. Landon y su pandilla mandaban en la escuela, pero su reinado terminaría en cuanto salieran del instituto y tuvieran que afrontar las responsabilidades de la vida.', trailer_url = 'https://www.youtube.com/watch?v=JxPI047J7Wc' WHERE id_api = 'tt0281358';

UPDATE Contenido SET id_tmdb = 5279, descripcion = 'Noviembre de 1932. Godsford Park es la magnífica mansión campestre a la que Sir William McCordle y su esposa Lady Sylvia invitan a familiares y amigos para una partida de caza. Los invitados son muy dispares: una condesa, un héroe de la Primera guerra mundial, el ídolo de masas Ivor Novello, y un productor de cine norteamericano. Mientras los invitados ocupan las lujosas habitaciones de arriba, sus criados conviven abajo con la servidumbre de los anfitriones. Sin embargo, no todo es lo que parece, ni entre los huéspedes ni entre los criados que se afanan por el bienestar de sus amos.', trailer_url = 'https://www.youtube.com/watch?v=o0m00hg1PKY' WHERE id_api = 'tt0280707';

UPDATE Contenido SET id_tmdb = 2110, descripcion = 'Hubert Fiorentini es un inspector de policía con unos métodos un poco ortodoxos, pero con un tierno corazón, al que obligatoriamente le darán unas vacaciones forzadas, ya que acaba de pelearse con el hijo del jefe de policía. Dos días después recibe la llamada de un abogado desde Tokyo, informándole que Miko, la mujer de su vida, que había desaparecido hacía 20 años, había muerto. Y lo que le había dejado en el testamento, no era ni dinero, ni presentes, ni nada material; le había dejado a su propia hija, Yumi, una extravagante adolescente, adicta a ir de compras, y con doscientos millones de dólares en su cuenta.', trailer_url = 'https://www.youtube.com/watch?v=l0BtQUa4EYI' WHERE id_api = 'tt0281364';

UPDATE Contenido SET id_tmdb = 9707, descripcion = 'Elvis Presley vive y reside en una vieja residencia al este de Texas. Años antes de su "muerte", Elvis cambió su identidad por un Elvis desconocido, pero perdió la oportunidad de dar marcha atrás al cambio. Elvis forma equipo con Jack, un compañero de la residencia que dice ser el presidente John F. Kennedy, y los dos valientes héroes lucharán contra una maligna entidad egipcia.', trailer_url = 'https://www.youtube.com/watch?v=_AquaumGgzc' WHERE id_api = 'tt0281686';

UPDATE Contenido SET id_tmdb = 11452, descripcion = 'Después de siete años perdiendo el tiempo en la universidad, Van Wilder no tiene la menor intención de graduarse. Sin embargo, para su desgracia, su padre, Vance Wilder, tampoco tiene la menor intención de seguir pagando sus estudios. Pero Van tiene una idea: organizar fiestas para recaudar el dinero necesario para continuar con su vida de estudiante. Gwen Pearson es una estudiante a la que le han encargado escribir un artículo, en contra de sus deseos, sobre el "Rey de la universidad". A medida que Gwen conoce el mundo de Van, descubre la verdad sobre el hombre que hay detrás del mito.', trailer_url = 'https://www.youtube.com/watch?v=qShNioFXXwM' WHERE id_api = 'tt0283111';

UPDATE Contenido SET id_tmdb = 8342, descripcion = 'Guerra de Bosnia, 1993. Dos soldados de bandos distintos, un bosnio y un serbio, se encuentran atrapados entre las líneas enemigas, en tierra de nadie. Un sargento de los cascos azules de las Naciones Unidas se dispone a ayudarlos, contraviniendo las órdenes de sus superiores. Los medios de comunicación no tardan en convertir el asunto en un show mediático de carácter internacional. Mientras la tensión bélica crece y la prensa espera pacientemente nuevas noticias, los dos soldados intentarán por todos los medios salir con vida de tal situación.', trailer_url = 'https://www.youtube.com/watch?v=Ypsnv50Af_I' WHERE id_api = 'tt0283509';

UPDATE Contenido SET id_tmdb = 9298, descripcion = 'El Centro de Ocio John Nike en West Staines va a cerrar por falta de fondos. A Ali G le preocupa el destino del club alternativo de boy scouts que ha estado dirigiendo hasta ese momento. Decidido a salvar el centro se encadena a una estación de autobuses de Staines. Así­ consigue llamar la atención del primer ministro, que andaba buscando a un joven intelectual que le ayudase a ganar las elecciones en Staines, y que cree haber encontrado en él al hombre que necesitaba. El político convence a Ali de que la mejor forma de salvar el centro es presentarse a las elecciones para el Gobierno, y Ali le toma la palabra.', trailer_url = 'https://www.youtube.com/watch?v=Ze635GS0Q3k' WHERE id_api = 'tt0284837';

UPDATE Contenido SET id_tmdb = 4604, descripcion = 'Serie que narra los inicios de Superman -Clark Kent- en su pueblo natal, Smallville. Allí vivía con sus padres, estudiaba en el instituto local y conoció a su primera novia, Lana Lang, y a su futuro rival, Lex Luthor.', trailer_url = 'https://www.youtube.com/watch?v=70Y32si4yb8' WHERE id_api = 'tt0279600';

