UPDATE Contenido SET id_tmdb = 11093, descripcion = 'Dos personas entran en conflicto a causa de la propiedad de una casa en el norte de California. Para Kathy Nicolo, es no sólo la casa de su infancia, sino también la última esperanza que le queda para reintegrarse a una vida que casi pierde por su adicción a las drogas. Cuando recibe una orden de desahucio por impago de impuestos, se queda en la calle y no puede impedir que la casa sea vendida a un precio irrisorio. Para el nuevo propietario, Massoud Amir Behrani, la casa es la plasmación del sueño americano que lleva persiguiendo desde que salió de Irán con toda su familia. Antiguo coronel de las Fuerzas Aéreas iraníes, Behrani se ha visto obligado a trabajar en empleos muy modestos para poder mantener las apariencias. Ahora ha invertido hasta el último céntimo en la compra de la casa que, por fin, devolverá a su familia su antigua prosperidad.', trailer_url = 'https://www.youtube.com/watch?v=8Y-0cSERrvE' WHERE id_api = 'tt0315983';

UPDATE Contenido SET id_tmdb = 10601, descripcion = 'Adaptación de la historia de J. M. Barrie acerca de un niño que nunca creció. Los tres niños de la familia Darling reciben una visita de Peter Pan, quien los lleva a la Tierra de Nunca Jamás, donde una guerra continua entre la pandilla de Peter y los Niños Perdidos y el malvado pirata Capitán Garfio está teniendo lugar.', trailer_url = 'https://www.youtube.com/watch?v=yIhQZJFRp-A' WHERE id_api = 'tt0316396';

UPDATE Contenido SET id_tmdb = 2055, descripcion = 'Intentando huir de su pasado, Charley Waite, Boss Spearman "Button" y Mose Harrison conducen ganado por las grandes praderas. Sus ideales son la justicia y la lealtad y procuran por todos los medios evitar la violencia. Pero su visita a Harmonville, una ciudad fronteriza dominada por un poderoso y despótico ranchero a cuyo servicio trabaja el corrupto sheriff local, cambiará sus vidas y los obligará a utilizar las armas en una desigual batalla.', trailer_url = 'https://www.youtube.com/watch?v=Rd1tXbsOGxs' WHERE id_api = 'tt0316356';

UPDATE Contenido SET id_tmdb = 13920, descripcion = '"Radio" es el apodo de un chico solitario y un poco retrasado al que conocen en su pueblo por su amor a la radio y a la música. No habla con nadie, pero un día Harold Jones, el entrenador del equipo de fútbol del instituto y el hombre más respetado del pueblo, se hace amigo suyo y se gana su confianza. A partir de entonces ante el chico se abre un nuevo mundo: ayuda a Jones en los entrenamientos y en los partidos e incluso asiste a sus clases en la escuela. Relato basado en hechos reales.', trailer_url = 'https://www.youtube.com/watch?v=bcfvpJvbYyU' WHERE id_api = 'tt0316465';

UPDATE Contenido SET id_tmdb = 558, descripcion = 'Han pasado dos años desde que el tranquilo Peter Parker dejó a Mary Jane Watson, su gran amor, y decidió seguir asumiendo sus responsabilidades como Spider-Man. Peter debe afrontar nuevos desafíos mientras lucha contra el don y la maldición de sus poderes equilibrando sus dos identidades: el escurridizo superhéroe Spider-Man y el estudiante universitario. Las relaciones con las personas que más aprecia están ahora en peligro de ser descubiertas con la aparición del poderoso villano de múltiples tentáculos Doctor Octopus, "Doc Ock".', trailer_url = 'https://www.youtube.com/watch?v=0EhKGAfNBBw' WHERE id_api = 'tt0316654';

UPDATE Contenido SET id_tmdb = 598, descripcion = 'Basada en hechos reales, cuenta la historia del crecimiento del crimen organizado en los suburbios de la ciudad de Río de Janeiro, desde finales de los años sesenta hasta el comienzo de los ochenta, cuando el tráfico de drogas y la violencia impusieron su ley entre la miseria de las favelas.“Buscapé” tiene 11 años y es sólo un niño más en Cidade de Deus, un suburbio de Río de Janeiro. Tímido y delicado, observa a los niños duros de su barrio, sus robos, sus peleas, sus enfrentamientos diarios con la policía. Ya sabe lo que quiere ser si consigue sobrevivir: fotógrafo. “Dadinho”, un niño de su misma edad, se traslada al barrio. Sueña con ser el criminal más peligroso de Río de Janeiro y empieza su aprendizaje haciendo recados para los delincuentes locales. Dos vidas paralelas en Cidade de Deus.', trailer_url = 'https://www.youtube.com/watch?v=63kaF1n5sz0' WHERE id_api = 'tt0317248';

UPDATE Contenido SET id_tmdb = 2023, descripcion = 'Año 1890. A Frank T. Hopkins (Viggo Mortensen), un legendario soldado de caballería, se le considera el mejor jinete del Far West, a pesar de lo cual se ve obligado a trabajar en el circo de Buffalo Bill. Un día recibe una oferta de un jeque árabe (Omar Sharif), propietario de caballos de pura raza, que puede ayudarle a recuperar su dignidad y prestigio: Frank y su caballo Hidalgo son invitados a participar en una carrera conocida como el Océano de Fuego, una prueba de supervivencia de 3.000 millas a través del desierto de Arabia. Basada en un hecho real.', trailer_url = 'https://www.youtube.com/watch?v=fiTD6o8Jz8A' WHERE id_api = 'tt0317648';

UPDATE Contenido SET id_tmdb = 11045, descripcion = 'Belle (Queen Latifah) es un diablo de la velocidad. Yendo a toda pastilla por las calles de Nueva York en su taxi "tuneado", se ha ganado la reputación de ser la taxista más rápida de la ciudad. Su sueño de ser campeona de coches de carreras se ve en peligro cuando se cruza en su camino un espídico policía, Andy (Jimmy Fallon), cuyas habilidades secretas sólo tiene parangón con su total ineptitud detrás del volante. Remake del exitoso film francés de mismo título de Luc Besson.', trailer_url = 'https://www.youtube.com/watch?v=oCjiNBiEUaQ' WHERE id_api = 'tt0316732';

UPDATE Contenido SET id_tmdb = 9801, descripcion = 'Bridget Jones ya es feliz: vive con el apuesto Mark Darcy y ha dejado al cretino de su ex-jefe Daniel. Lo malo es que Rebeca, estropea su relación con Mark. Tampoco le van bien las cosas en el trabajo, pero lo peor de todo es lo que le ocurre durante un viaje a Tailandia. No obstante, como siempre, sigue contando con el apoyo de sus amigos que la animan a conocer gente nueva. Pero, ¿quién sabe si Bridget no estará pensando en volver con Daniel?', trailer_url = 'https://www.youtube.com/watch?v=4Lx3K1wF3U4' WHERE id_api = 'tt0317198';

UPDATE Contenido SET id_tmdb = 9806, descripcion = 'Como Mr. Increíble y Elastigirl, Bob y su esposa Helen estaban entre los mejores luchadores contra el crimen. Por fin pueden volver a la acción cuando una misteriosa llamada cita a Bob en una isla remota.', trailer_url = 'https://www.youtube.com/watch?v=eMzejXYKT_Y' WHERE id_api = 'tt0317705';

UPDATE Contenido SET id_tmdb = 920, descripcion = 'El aspirante a campeón de carreras Rayo McQueen parece que está a punto de conseguir el éxito, la fama y todo lo que había soñado, hasta que por error toma un desvío inesperado en la polvorienta y solitaria Ruta 66. Su actitud arrogante se desvanece cuando llega a una pequeña comunidad olvidada que le enseña las cosas importantes de la vida que había olvidado.', trailer_url = 'https://www.youtube.com/watch?v=8ZMklX5BzTo' WHERE id_api = 'tt0317219';

UPDATE Contenido SET id_tmdb = 9654, descripcion = 'El plan era impecable, se ejecutó a la perfección y tenían libre la vía de escape. El único factor de riesgo que la mente maestra del crimen Charlie Croker no pudo prevenir, procedía de uno de los miembros de la banda. Después de dar un asombroso golpe millonario en un ''palazzo'' veneciano fuertemente custodiado, Charlie y la banda se quedan asombrados al descubrir que uno de ellos les ha traicionado. Ahora la cosa ya no tiene que ver con el botín sino con la venganza. Entonces entra en escena la bella Stella, una experta reventadora de cajas fuertes que se une a Charlie y a la banda cuando regresan a California en busca del traidor.', trailer_url = 'https://www.youtube.com/watch?v=-AvP5pua8Ko' WHERE id_api = 'tt0317740';

UPDATE Contenido SET id_tmdb = 956, descripcion = 'Tras haber llevado a cabo diversas misiones, el agente especial Ethan Hunt se ha retirado del servicio activo y se ha prometido con su amada Julia. Pero, cuando es secuestrado uno de los agentes entrenados por él, volverá de nuevo a la acción. También tendrá que enfrentarse a Owen Davian, un individuo sin escrúpulos que trafica con armas y con información.', trailer_url = 'https://www.youtube.com/watch?v=7O8XMYWMOa4' WHERE id_api = 'tt0317919';

UPDATE Contenido SET id_tmdb = 10708, descripcion = 'Tras no obtener los resultados esperados en una campaña publicitaria sobre cereales vegetales, Charlie y Phil (Eddie Murphy & Jeff Garlin) son despedidos de sus trabajos. Después de fracasar en la búsqueda de un empleo, y quedarse al mando de sus casas y de sus hijos pequeños, Charlie tiene una idea: ¿Si Phil y él pueden arreglárselas para cuidar de 2 niños, porqué no cuidar a 10? Golosinas, superhéroes y destrozar todo lo que haya a la vista son los hobbies de los traviesos residentes de "Papá Canguro", la loca pero divertida guardería montada en su propia casa, para el cuidado de niños durante el día... para irritación de su principal competidora, la estricta Srta. Gwyneth Harridan (Anjelica Huston).', trailer_url = 'https://www.youtube.com/watch?v=hx0_F3I10ws' WHERE id_api = 'tt0317303';

UPDATE Contenido SET id_tmdb = 1653, descripcion = 'En 1952, siendo el "Che" Guevara estudiante de medicina, recorrió América del Sur, con su amigo Alberto Granado, en una destartalada moto. Ernesto es un joven estudiante de medicina de 23 años de edad, especializado en lepra. Alberto es un bioquímico de 29 años. Ambos jóvenes emprenden un viaje de descubrimiento de la rica y compleja topografía humana y social del continente hispanoamericano. Los dos dejaron atrás el familiar entorno de Buenos Aires en una desvencijada motocicleta Norton de 500 cc, imbuidos de un romántico espíritu aventurero.', trailer_url = 'https://www.youtube.com/watch?v=z82avke1Z_E' WHERE id_api = 'tt0318462';

UPDATE Contenido SET id_tmdb = 1577, descripcion = 'Un virus mortal ha sido liberado sobre la población de Raccoon City. Alice (Milla Jovovich), una de las supervivientes del desastre bioquímico, se encuentra en el corazón de esta devastada ciudad. Sometida a experimentos que han alterado su genética, ahora posee fuerza, sentidos y destreza sobrehumana. Estas habilidades, y más, serán las que deba utilizar quien quiera sobrevivir en esta nueva aventura. Junto con otros supervivientes deberá escapar de la cada vez más peligrosa Raccoon City. Para alcanzar su meta necesitarán luchar contra las fuerzas de la Umbrella Corporation, las violentas criaturas de bioingeniería creadas en sus laboratorios, los zombies que plagan la ciudad y, finalmente, enfrentarse a la más colosal y mortal de estas creaciones: Nemesis.', trailer_url = 'https://www.youtube.com/watch?v=PkutbYENBis' WHERE id_api = 'tt0318627';

UPDATE Contenido SET id_tmdb = 7364, descripcion = 'El gran explorador y aventurero Dirk Pitt (McConaughey), que trabaja para una agencia del gobierno que protege los fondos marinos, emprende la gran aventura de su vida recorriendo las regiones más peligrosas del oeste de África en busca de un tesoro llamado "El barco de la muerte". Cuando él y su ayudante (Steve Zahn) se dan cuenta de que el barco puede estar relacionado con unas misteriosas muertes, tendrán que usar toda su inteligencia y habilidades para ayudar a la Doctora Eva Rojas (Penélope Cruz), también involucrada en el caso. Ella está investigando la expansión de un virus que puede afectar no sólo al continente africano, sino a todo el mundo.', trailer_url = 'https://www.youtube.com/watch?v=VvA4Tbjk8tk' WHERE id_api = 'tt0318649';

UPDATE Contenido SET id_tmdb = 435, descripcion = 'Las investigaciones del climatólogo Jack Hall indican que el calentamiento global podría desencadenar un repentino y catastrófico cambio climático de la Tierra. Hall advierte a los dirigentes políticos de la necesidad de adoptar inmediatamente medidas para evitarlo, pero sus advertencias llegan demasiado tarde: una serie de anómalos fenómenos climáticos empiezan a producirse en distintas partes del globo. El calentamiento global ha puesto el planeta al borde de una nueva era glacial. Mientras Jack advierte a la Casa Blanca del inminente cambio climático, su hijo Sam y sus amigos se encuentran atrapados en Nueva York, a donde han ido para participar en un concurso académico entre institutos.', trailer_url = 'https://www.youtube.com/watch?v=pmvxNS5Juo8' WHERE id_api = 'tt0319262';

UPDATE Contenido SET id_tmdb = 587, descripcion = '"Big Fish" cuenta la historia entre un padre moribundo, Edward Bloom (Albert Finney), y su hijo Will (Ewan McGregor), quien trata de aprender más acerca de su progenitor, reuniendo las distintas historias que este le ha contado. Así, Will recrea su vida en una serie de leyendas y mitos inspirados por los pocos hechos que conoce. Pero a partir del deseo de su madre Sandy, por reunir al padre con su hijo, este comienza a comprender la debacle de su padre. En sus relatos hay viajes alrededor del mundo, y delirios que incluyen gigantes, tornados y brujas.', trailer_url = 'https://www.youtube.com/watch?v=T6M-jwyz28U' WHERE id_api = 'tt0319061';

UPDATE Contenido SET id_tmdb = 35935, descripcion = 'Durante más de 100 años, los magníficos ejércitos de Chuder y los de la región central han luchado en sangrientas batallas. Tan sólo la impenetrable fortaleza Doldery mantiene al Imperio de Chuder a salvo de todas las guerras que les rodean. La banda de los Halcones han tomado posiciones en la gran ofensiva. En esta batalla, las tropas de la región central podrán llegar hasta las puertas de la legendaria fortaleza de Chuder y desafiar al ejército invencible del General Boscongn.', trailer_url = 'https://www.youtube.com/watch?v=odIwkGztmcc' WHERE id_api = 'tt0318871';

UPDATE Contenido SET id_tmdb = 1495, descripcion = 'Balián de Ibelín viaja a Jerusalén durante las cruzadas del siglo XII, donde será el defensor de su pueblo.', trailer_url = 'https://www.youtube.com/watch?v=6Z2wGCZ2fSM' WHERE id_api = 'tt0320661';

UPDATE Contenido SET id_tmdb = 277, descripcion = 'Durante siglos, dos razas han ido evolucionando en las profundidades de la Tierra: los aristocráticos y sofisticados vampiros y los brutales hombres-lobo (Lycans), cuya existencia siempre había formado parte del mundo de los mitos y las leyendas. Estas razas nocturnas son enemigas mortales y están condenadas a vivir en perpetua guerra hasta que sólo una de ellas sobreviva. En medio de este conflicto ancestral, una Guerrera Vampiro, Selene, descubre una conspiración de los Lycan para secuestrar a Michael, un joven médico. Después de seguirlo por toda la ciudad, Selene entabla una insólita relación con él, y cuando los Lycans se deciden a atacar, se interpone entre ellos y el médico. Mientras intenta salvar a Michael, descubre un plan de los Lycans para crear nuevas criaturas que combinen los poderes de ambas razas y carezcan de sus debilidades. Este proyecto, de hacerse realidad, favorecería a los Hombres-lobo.', trailer_url = 'https://www.youtube.com/watch?v=Komxc6yFhv8' WHERE id_api = 'tt0320691';

UPDATE Contenido SET id_tmdb = 10719, descripcion = 'Una Nochebuena, en un orfanato, un bebé gatea dentro del saco de regalos de Santa Claus y acaba en el taller de éste en el Polo Norte. Aunque allí es adoptado y educado como un elfo, al crecer, se hace tres veces más grande que los habitantes de la región. Parece claro que nunca encajará en el mundo de los elfos; lo que necesita es encontrar a su verdadera familia. Con esta intención viaja a Nueva York, donde descubrirá que la vida no consiste sólo en patinar y comer dulces; así que vuelve a sentirse otra vez fuera lugar. Consigue, no obstante, encontrar a su padre, Walter, un editor de libros infantiles adicto al trabajo y al dinero que figura en la lista negra de Santa Claus. Buddy también encuentra a una nueva madre y descubre que su hermanastro de diez años no cree en los elfos ni en Santa Claus ni en las Navidades. En realidad todo el mundo parece haber olvidado el verdadero significado de la Navidad.', trailer_url = 'https://www.youtube.com/watch?v=14o38xfHlXc' WHERE id_api = 'tt0319343';

UPDATE Contenido SET id_tmdb = 584, descripcion = 'El agente del FBI Brian O''Conner cayó en desgracia al ver su lealtad puesta a prueba en su anterior trabajo en el mundo de las carreras ilegales de Los Angeles. La decisión de O’Conner le permitió conservar su honor, pero le hizo perder su insignia. Ahora ha pasado el tiempo, está en otra ciudad y tiene una última oportunidad. A los federales de Miami les está costando mucho detener a Carter Verone, un empresario que utiliza su negocio como tapadera para un cartel internacional de blanqueo de dinero. Aduanas sabe de su relación con las carreras callejeras ilegales, así que deciden llamar a O’Conner para vuelva a infiltrarse. Pero antes pone algunas condiciones para aceptar la misión. La primera: trabajar con su amigo de infancia y antiguo delincuente Roman Pearce, otro adicto a la velocidad.', trailer_url = 'https://www.youtube.com/watch?v=RFee3iNoTQ4' WHERE id_api = 'tt0322259';

UPDATE Contenido SET id_tmdb = 10330, descripcion = 'La doctora Tess Coleman y Anna, su hija de quince años, tienen gustos muy distintos. Mientras que Anna no entiende por qué su madre no apoya sus aspiraciones musicales, Tess, una viuda a punto de casarse de nuevo, se pregunta por qué su hija no es más amable con su prometido. Un día, dos galletitas chinas de la Fortuna provocan un gran cambio en sus vidas. A la mañana siguiente, Tess y Anna se encuentran con sus cuerpos intercambiados. Poco a poco, cada una empieza a comprender el punto de vista de la otra, pero tienen que encontrar la manera más rápida de recuperar su ser porque la boda de Tess se celebra al día siguiente.', trailer_url = 'https://www.youtube.com/watch?v=yRpzGYICTRU' WHERE id_api = 'tt0322330';

UPDATE Contenido SET id_tmdb = 185, descripcion = 'En el sur de los Estados Unidos, en el año 1934, en plena Gran Depresión tras el crack bursátil que condenó a la pobreza a millones de norteameriacanos, un joven huérfano de 18 años, Ben Hawkins, se une a un circo mezcla de feria, freaks, prostitución y vaudeville que le acogerán como uno más. Ben tiene sueños que le inquietan y poderes curativos que le asustan, los mismos sueños que tiene en un mundo opuesto. Donde había pobreza hay bienestar; es el mundo del pastor metodista Padre Justin, el malo de "los inmortales", vive con su hermana Iris en un mundo protegido en California, hasta que comienzan sus visiones. Desde ese momento todo parece indicar que los caminos de ambos protagonistas tendrán que cruzarse de forma inexorable.', trailer_url = 'https://www.youtube.com/watch?v=Io3qEXfuc2s' WHERE id_api = 'tt0319969';

UPDATE Contenido SET id_tmdb = 9012, descripcion = 'Johnny Knoxville y el resto del reparto de la serie de televisión "Jackass" realizan las hazañas más escandalosas y divertidas en Japón, donde se disfrazan de pandas y atacan un campo de golf mas intensas que en la TV.', trailer_url = 'https://www.youtube.com/watch?v=GKuUHOqhKGM' WHERE id_api = 'tt0322802';

UPDATE Contenido SET id_tmdb = 10028, descripcion = 'Honey Daniels es una joven que lleva toda la vida queriendo mostrarle al mundo su talento para la danza. Ambiciosa y trabajadora, siempre ha aspirado a convertirse en coreógrafa, pero nunca lo ha tenido demasiado fácil, porque incluso su familia nunca ha creído que pueda llegar a lo más alto. Decidió mudarse al corazón de la ciudad, dejando una vida que podría haber sido mucho más fácil. Y todo para conseguir hacer realidad sus sueños.', trailer_url = 'https://www.youtube.com/watch?v=9gPkNpqP-2k' WHERE id_api = 'tt0322589';

UPDATE Contenido SET id_tmdb = 1996, descripcion = 'Enfrentándose a nuevos y mayores peligros y desafíos, Lara Croft muestra sus poderes físicos en otra trepidante aventura. La intrépida heroína viajará a un templo sumergido bajo el agua en busca de la legendaria "Caja de Pandora", pero antes de que llegue, un banda de criminales chinos, liderados por Chen Lo, consigue apoderarse del preciado objeto. Lara tendrá que detenerlos antes de que lo usen con fines maléficos.', trailer_url = 'https://www.youtube.com/watch?v=q5VugO68swI' WHERE id_api = 'tt0325703';

UPDATE Contenido SET id_tmdb = 302, descripcion = 'Sarah Morton, una escritora británica autora de libros de misterio y novelas policiacas, viaja de Londres al sur de Francia, para pasar unos días en casa de su editor, con la intención de descansar y encontrar inspiración para su nueva novela. Allí conoce a la hija adolescente de su anfitrión, la atractiva y poco convencional Julie.', trailer_url = 'https://www.youtube.com/watch?v=Nyp8W-wdxpY' WHERE id_api = 'tt0324133';

UPDATE Contenido SET id_tmdb = 9373, descripcion = 'Durante un viaje de Texas a México, un grupo de jóvenes recoge a una autoestopista ensangrentada que asegura que es la única superviviente de una masacre ocurrida la noche anterior en una casa cercana. Remake del clásico homónimo de Tobe Hooper (1974).', trailer_url = 'https://www.youtube.com/watch?v=N0Korn6jzxs' WHERE id_api = 'tt0324216';

UPDATE Contenido SET id_tmdb = 22, descripcion = 'El aventurero capitán Jack Sparrow recorre las aguas caribeñas. Pero su andanzas terminan cuando su enemigo, el capitán Barbossa le roba su barco, la Perla Negra, y ataca la ciudad de Port Royal, secuestrando a Elizabeth Swann, hija del gobernador. Will Turner, el amigo de la infancia de Elizabeth, se une a Jack para rescatarla y recuperar la Perla Negra. Pero el prometido de Elizabeth, comodoro Norrington, les persigue a bordo del HMS Impávido. Además, Barbossa y su tripulación son víctimas de un conjuro por el que están condenados a vivir eternamente, y a transformarse cada noche en esqueletos vivientes, en fantasmas guerreros.', trailer_url = 'https://www.youtube.com/watch?v=5Itr2jHuJaw' WHERE id_api = 'tt0325980';

UPDATE Contenido SET id_tmdb = 616, descripcion = '1870. El capitán Nathan Algren es un hombre a la deriva. Las batallas que libró en otro tiempo parecen ahora lejanas e inútiles. Una vez arriesgó su vida por el honor y por la patria, pero, en los años transcurridos desde la Guerra de Secesión estadounidense, el mundo ha cambiado. El pragmatismo ha reemplazado al valor, el interés personal ha ocupado el lugar del sacrificio y el honor no se encuentra en ninguna parte, especialmente en el Oeste, donde su papel en las campañas contra los indios acabó en desilusión y tristeza. En algún lugar de las implacables llanuras junto a la ribera del río Washita, Algren perdió su alma. En un mundo completamente distinto, otro soldado ve como su modo de vida está a punto de desintegrarse.', trailer_url = 'https://www.youtube.com/watch?v=DGUqfDjqc4w' WHERE id_api = 'tt0325710';

UPDATE Contenido SET id_tmdb = 11208, descripcion = 'Desde el momento en que Matthew ve a Lisa por primera vez, se convierte en su obsesión. Ella pasa delante del escaparate de la tienda en la que él trabaja en el barrio de Wicker Park de Chicago, y queda prendado; le sigue, se conocen, y en seguida se enamoran. Todo en su relación parece perfecto hasta que un día ella desaparece sin dejar rastro.', trailer_url = 'https://www.youtube.com/watch?v=vFo0u-nXbGk' WHERE id_api = 'tt0324554';

UPDATE Contenido SET id_tmdb = 322, descripcion = 'Cuando Jimmy Markum, Dave Boyle y Sean Devine eran unos niños que crecían juntos en un peligroso barrio obrero de Boston, pasaban los días jugando al hockey en la calle. Pero, un día, a Dave le ocurrió algo que marcó para siempre su vida y las de sus amigos. Veinticinco años más tarde, otra tragedia los vuelve a unir: el asesinato de Katie, la hija de 19 años de Jimmy. A Sean, que es policía, le asignan el caso; pero también tiene que estar muy pendiente de Jimmy porque, en su desesperación, está intentando tomarse la justicia por su mano.', trailer_url = 'https://www.youtube.com/watch?v=iCYoGicgruU' WHERE id_api = 'tt0327056';

UPDATE Contenido SET id_tmdb = 7270, descripcion = 'Roy y Frank son dos estafadores de poca monta.La vida privada de Roy es más bien problemática: padece agorafobia, es un maniático compulsivo, un fumador empedernido y no tiene ningún tipo de relación personal; a veces, cuando sus manías empiezan a poner en peligro su rendimiento y su cordura, se ve obligado a visitar a un psicoanalista para seguir funcionando. Gracias a la terapia que le prescribe su médico, llega a saber que tiene una hija adolescente, cosa que sospechaba, pero que nunca se había atrevido a confirmar. Y lo que es más preocupante, Angela quiere conocer al padre al que nunca ha visto. Al principio, la aparición de Angela perturba la ordenada rutina de su neurótico padre. Sin embargo, a pesar de su peculiar manera de asumir la paternidad, Roy comienza a disfrutar de una relación que nunca había soñado tener.', trailer_url = 'https://www.youtube.com/watch?v=zDoOdd00nHM' WHERE id_api = 'tt0325805';

UPDATE Contenido SET id_tmdb = 7518, descripcion = 'Cuando R.J. (un travieso mapache estafador), Verne (una tímida tortuga), y sus amigos del bosque descubren que alguien ha construido unas casas en su territorio, la primera reacción de la tortuga es meterse en su caparazón y retroceder, pero el mapache oportunista se da cuenta de las posibilidades que ofrecen sus nuevos e ingenuos vecinos. Verne y R.J. formarán una inesperada asociación mientras aprenden a coexistir con este extraño mundo llamado “urbanización”, e incluso a explotarlo.', trailer_url = 'https://www.youtube.com/watch?v=ix_bxyRimos' WHERE id_api = 'tt0327084';

UPDATE Contenido SET id_tmdb = 14836, descripcion = 'Película de animación en la que se nos cuenta la historia de Coraline, una jovencita que descubre en su nueva casa una puerta secreta y decide abrirla. Al hacerlo, descubre una segunda versión de su vida, una vida paralela a la que ella tiene. A primera vista, la realidad paralela es curiosamente parecida a su vida de verdad, aunque mucho mejor. Pero cuando su increíble y maravillosa aventura empieza a tomar un cariz peligroso, su otra madre intenta mantenerla a su lado para siempre. Coraline deberá recurrir a su determinación y coraje, a la ayuda de los vecinos y a un gato negro con el don del habla para salvar a sus auténticos padres, a unos niños fantasmas y regresar a casa.', trailer_url = 'https://www.youtube.com/watch?v=ksOiRS2YO1U' WHERE id_api = 'tt0327597';

UPDATE Contenido SET id_tmdb = 13156, descripcion = 'Cuenta las cómicas aventuras de un chico introvertido obligado a pasar el verano en una rancho de Texas con sus excéntricos tíos, dos señores mayores a los que apenas conoce, la idea no le hace ninguna gracia. Y la verdad es que a los dos hombres tampoco les excita mucho la idea de cuidar del chaval, pero éste descubre que sus tíos viven una vida nada convencional, incluso peligrosa, y sus historias despiertan la imaginación y las ganas de aventuras del tímido joven.', trailer_url = 'https://www.youtube.com/watch?v=Ebkrm7u44UI' WHERE id_api = 'tt0327137';

UPDATE Contenido SET id_tmdb = 9890, descripcion = 'Joanna Eberhart (Kidman) y su marido (Broderick), buscando una vida perfecta, se mudan al acomodado barrio de Stepford (Connecticut). A Joanna le intriga tanto que todas las esposas sean tan complacientes con sus maridos que, con la ayuda de una vecina bastante anticonvencional (Bette Midler), empezará a hacer indagaciones.', trailer_url = 'https://www.youtube.com/watch?v=Mu3c8kB9Mg8' WHERE id_api = 'tt0327162';

UPDATE Contenido SET id_tmdb = 2122, descripcion = 'Cuando la mujer de Oz es secuestrada, a éste no le queda otro remedio que recurrir a su viejo conocido Jimmy "el Tulipán", un antiguo asesino a sueldo, que ahora lleva una vida tranquila y anónima.', trailer_url = 'https://www.youtube.com/watch?v=efr6Pm8LrSM' WHERE id_api = 'tt0327247';

UPDATE Contenido SET id_tmdb = 10204, descripcion = 'Phileas Fogg, un excéntrico inventor londinense, acaba de descubrir los secretos del vuelo aéreo, la electricidad, y hasta los patines en línea, pero la sociedad victoriana le toma por demente. Desesperado por ser tomado en serio, Fogg reta a Lord Kelvin, cabeza visible de la Real Academia de las Ciencias, mediante una increíble apuesta: afirma que será capaz de circunnavegar el globo terráqueo en menos de 80 días. Acompañado de su ayuda de cámara Passepartout y Monique, la artista francesa en busca de aventuras, Fogg se embarca en una trepidante y frenética carrera alrededor del mundo que les llevará por tierra, mar y aire hasta los lugares más exóticos del planeta.', trailer_url = 'https://www.youtube.com/watch?v=XVGx5BLmBzQ' WHERE id_api = 'tt0327437';

UPDATE Contenido SET id_tmdb = 14442, descripcion = 'Ella es una joven que vive en un mundo mágico y de fantasía en el que a todos los niños al nacer se les concede un don por parte de una hada superiora. El don de Ella, más que don una maldición, es la obediencia. Como consecuencia de esta circunstancia, Ella no puede negarse a ninguna orden, lo que le traerá más de un problema. En un intento por recuperar el control de su vida, la joven tratará de librarse de la maldición que pesa sobre ella, entrando en un reino lleno de ogros, gigantes y malvadas hermanastras.', trailer_url = 'https://www.youtube.com/watch?v=YQFCpr0iVBE' WHERE id_api = 'tt0327679';

UPDATE Contenido SET id_tmdb = 314, descripcion = 'Patience Philips (Halle Berry) es una mujer sumisa y siempre dispuesta a agradar a la gente, que trabaja como diseñadora gráfica para el gigantesco laboratorio de cosméticos Hedare Beauty, dirigido por el despótico George Hedare (Lambert Wilson) y su esposa, la supermodelo Laurel (Sharon Stone). La tímida Patience se entera por casualidad de un siniestro secreto sobre un revolucionario producto antienvejecimiento de la compañía que pronto va a salir a la venta y se ve envuelta en una conspiración. Justo entonces es salvada de la muerte al renacer con la fuerza, la velocidad, la agilidad y los agudísimos sentidos de un gato. En su nueva vida de venganzas como Catwoman la guiará una misteriosa mujer llamada Ophelia Powers (Frances Conroy).', trailer_url = 'https://www.youtube.com/watch?v=Fp7MeqkCUfc' WHERE id_api = 'tt0327554';

UPDATE Contenido SET id_tmdb = 9509, descripcion = 'México D.F. Un agente del gobierno decepcionado con su vida, acepta a regañadientes un trabajo que consiste en proteger a una niña cuyos padres han recibido amenazas de secuestro. La relación con su pequeña protegida irá creciendo hasta despertar en él un espíritu perdido. Pero cuando la niña es secuestrada, su rabia se desatará contra los responsables.', trailer_url = 'https://www.youtube.com/watch?v=SA3WH0tJPVA' WHERE id_api = 'tt0328107';

UPDATE Contenido SET id_tmdb = 10159, descripcion = 'Para pagar una deuda, un cazador de recompensas (The Rock) viaja a Helldorado, una ciudad en lo profundo de la jungla del Amazonas, para capturar a un convicto (Scott). Pero cuando llega, descubre que a quien tiene que detener es sólo un muchacho ávido de emociones que busca riqueza, y ambos formarán equipo para intentar encontrar una mina llena de oro.', trailer_url = 'https://www.youtube.com/watch?v=BehhBCBSplY' WHERE id_api = 'tt0327850';

UPDATE Contenido SET id_tmdb = 10009, descripcion = 'En los bosques del noroeste americano vive un niño indio llamado Kenai, cuya vida sufre un giro inesperado cuando los Grandes Espíritus lo transforman en un oso, el animal que más odia. Kenai se hace amigo de un osezno llamado Koda y se propone recuperar su forma humana. Mientras, su hermano (que no sabe que Kenai es ahora un oso) lo persigue para cumplir una misión de venganza en la que está en juego el honor familiar.', trailer_url = 'https://www.youtube.com/watch?v=HgGMeCaMtq8' WHERE id_api = 'tt0328880';

UPDATE Contenido SET id_tmdb = 674, descripcion = 'En el cuarto año en Hogwarts, Harry se enfrenta al mayor de los desafíos y peligros de la saga. Cuando es elegido bajo misteriosas circunstancias como el competidor que representará a Hogwarts en el Torneo Triwizard, Harry deberá competir contra los mejores jóvenes magos de toda Europa. Pero mientras se prepara, aparecen pruebas que manifiestan que Lord Voldemort ha regresado. Antes de darse cuenta, Harry no solo estará luchando por el campeonato sino también por su vida', trailer_url = 'https://www.youtube.com/watch?v=CKt0PQFECfs' WHERE id_api = 'tt0330373';

UPDATE Contenido SET id_tmdb = 11023, descripcion = 'Tracy, una joven de 13 años de Los Ángeles, queda fascinada por Evie, la chica más popular del instituto. Tras hacerse muy amigas, y debido a la peligrosa influencia de la "cool" Evie, la antes inocente Tracy se verá poco a poco atrapada en un trepidante ritmo de vida que nada tenía que ver con su anterior vida sedentaria. Tracy se embarca en un mundo salvaje sobre el que no tiene control. Mientras, Mel, la madre de Tracy, trata desesperadamente de comprender la radical transformación que está sufriendo su hija.', trailer_url = 'https://www.youtube.com/watch?v=a_OlFt2XgmE' WHERE id_api = 'tt0328538';

UPDATE Contenido SET id_tmdb = 8273, descripcion = 'Jim (Jason Biggs) le pide matrimonio a su novia Michelle (Alyson Hannigan) después de un incidente vergonzoso en un restaurante. Ella acepta, pero los problemas no terminan ahí para Jim. Ahora tiene que planear la boda con la ayuda de sus amigos Kevin y Finch, y evitar que Stifler, su grosero compañero de escuela, arruine la fiesta. Jim también se preocupa por caerle bien a los padres de Michelle y por aprender a bailar antes del gran día. Entre bromas pesadas, situaciones cómicas y momentos emotivos, Jim y Michelle intentan llegar al altar sanos y salvos.', trailer_url = 'https://www.youtube.com/watch?v=jSxD-QAhJPs' WHERE id_api = 'tt0328828';

UPDATE Contenido SET id_tmdb = 10934, descripcion = 'Frances Mayes (Diane Lane) es una escritora americana de 35 años que vive en San Francisco y cuya perfecta vida acaba de dar un giro de 180 grados. Su reciente divorcio le ha causado una profunda depresión y un bloqueo creativo. Patti (Sandra Oh), su mejor amiga, empieza a preocuparse y decide regalarle una estancia de diez días en la Toscana (Italia). Una vez allí, Frances se encapricha de una villa llamada "Bramasole" (“que anhela el sol”) y decide comprarla. La casa necesita muchas reformas pero Frances está dispuesta a acometerlas. A medida que se va adaptando a su nuevo estilo de vida hará amistades entre sus vecinos.', trailer_url = 'https://www.youtube.com/watch?v=aURoPYu_29w' WHERE id_api = 'tt0328589';

UPDATE Contenido SET id_tmdb = 6466, descripcion = 'Freddy Krueger necesita el miedo de la gente para regresar, por lo que decide resucitar al temible Jason. Pero el protagonista de "Viernes 13" no está dispuesto a dejarle el camino libre.  Este formato que enfrenta a dos personajes míticos del celuloide no es nada nuevo en el cine: Frankenstein ya se encaró al hombre lobo en 1943 y 28 años más tarde resucitó para luchar contra Drácula. También, a lo largo del siglo XX, llegó el gigantesco Godzilla dispuesto a terminar con King Kong y una serie de mutantes que iban sembrando el pánico por Japón. En esta ocasión, fueron dos de los asesinos estrella de las películas de la década de 1980 los que se unieron. El resultado, el esperado: muertes, descuartizamientos y chicas ligeras de ropa.', trailer_url = 'https://www.youtube.com/watch?v=Z3_UqWIAJck' WHERE id_api = 'tt0329101';

UPDATE Contenido SET id_tmdb = 4464, descripcion = 'Nos encontramos en la Gran Depresión estadounidense, a finales de la década de los años treinta. La economía ha sufrido un golpe catastrófico y millones de personas han perdido su trabajo y su hogar. Poco lugar queda para la esperanza y el optimismo. Es un momento de devastación, Estados Unidos se encuentra sumido en una bache del que parece imposible salir.', trailer_url = 'https://www.youtube.com/watch?v=j4UwbKm9rNU' WHERE id_api = 'tt0329575';

UPDATE Contenido SET id_tmdb = 11679, descripcion = 'Augustus Gibbons es un miembro de la Agencia de Seguridad Nacional norteamericana. Tras librarse de un ataque mortal protagonizado por unos desconocidos, Gibbons sospecha que los asesinos han sido enviados por una facción secreta y radical que actúa desde dentro de la Casa Blanca. Busca entonces a un militar experto y bien entrenado que le ayude a desenmascarar al grupo radical que se esconde tras el Gobierno. Desgraciadamente, Darius Stone, el hombre más idóneo para este trabajo, está en prisión. Sin embargo, Gibbons le ayuda a fugarse y lo convence para que colabore con él como el agente XXX.', trailer_url = 'https://www.youtube.com/watch?v=TS8Pl4tsJGQ' WHERE id_api = 'tt0329774';

UPDATE Contenido SET id_tmdb = 11036, descripcion = 'En una residencia de ancianos, un hombre mayor lee a una mujer una historia de amor escrita en su viejo libro de notas. El libro cuenta la vida en los años 40 de Noah Calhoun y Allie Nelson, dos jóvenes adolescentes de Carolina del Norte que, a pesar de vivir en dos ambientes sociales muy diferentes, pasaron un verano idílico juntos y profundamente enamorados, antes de ser separados, primero por sus padres, y más tarde por la Segunda Guerra Mundial.', trailer_url = 'https://www.youtube.com/watch?v=FC6biTjEyZw' WHERE id_api = 'tt0332280';

UPDATE Contenido SET id_tmdb = 11024, descripcion = 'Continuación de las aventuras de Scooby y su pandilla de amigos, que en esta ocasión se enfrentan a un anónimo enmascarado con malvados planes para aterrorizar a la ciudad de Coolsville.', trailer_url = 'https://www.youtube.com/watch?v=jF3PfPD8t50' WHERE id_api = 'tt0331632';

UPDATE Contenido SET id_tmdb = 7220, descripcion = 'Frank Castle (Thomas Jane) es un agente secreto del FBI que hasta el momento ha logrado una carrera intachable. Frank también es un ex operativo de las Fuerzas Especiales. Finalmente sale del campo de batalla para trabajar en una oficina y así poder tener una vida normal con su esposa e hijo. Será entonces cuando el mundo de Frank se viene abajo por el peor temor que siempre tuvo: Su familia es ejecutada como repercusión de su último trabajo. Ahora Castle busca castigar a los asesinos, para encontrar al final lo que menos esperaba: La redención.', trailer_url = 'https://www.youtube.com/watch?v=TqVSFchQEyM' WHERE id_api = 'tt0330793';

UPDATE Contenido SET id_tmdb = 1584, descripcion = 'Dewey Finn es un guitarrista con delirios de grandeza que es expulsado de su banda. Desesperado por encontrar un trabajo ante su falta de dinero, suplanta la identidad de un profesor sustituto para dar clase en una escuela privada a los pequeños alumnos pre-adolescentes de 5o grado a los que intentará enseñarles el "rock and roll de alto voltaje". Además entre sus alumnos está Yuki, un guitarrista prodigio de 9 años que puede ayudar a Dewey a ganar la competición de bandas de música... y de paso solucionar sus problemas económicos.', trailer_url = 'https://www.youtube.com/watch?v=KdzWQT0wLCY' WHERE id_api = 'tt0332379';

UPDATE Contenido SET id_tmdb = 652, descripcion = 'A lo largo de los tiempos, los hombres han hecho la guerra. Unos por poder, otros por gloria o por honor, y algunos por amor. En la antigua Grecia, la pasión de dos de los amantes más legendarios de la historia, Paris, príncipe de Troya y Helena, reina de Esparta, desencadena una guerra que asolará una civilización. El rapto de Helena por Paris, separándola de su esposo, el rey Menelao, es un insulto que El orgullo familiar establece que una afrenta a Menelao es una afrenta a su hermano Agamenón, el poderoso rey de Micenas, que no tarda en reunir a todas las grandes tribus de Grecia para recuperar a Helena de manos de los troyanos y defender el honor de su hermano. La verdad es que la lucha por el honor por parte de Agamenón está corrompida por su incontenible codicia ya que necesita conquistar Troya para asumir el control del mar Egeo.', trailer_url = 'https://www.youtube.com/watch?v=ORKSndBYAPk' WHERE id_api = 'tt0332452';

UPDATE Contenido SET id_tmdb = 9282, descripcion = 'Es una noche tranquila en Middleton, un barrio de clase media. Pero a medida que la noche se aproxima a la fatídica hora de las 11:14 p.m., una serie de sucesos empezarán a ocurrir, con letales consecuencias. En la autopista, Jack, un conductor borracho atropella a un joven con su coche... Un tiroteo en una tienda de conveniencia deja herida a la dependienta, Buzzy. Pero más tarde será arrestada por estar involucrada en el crimen... En el cementerio local, Frank, un padre muy protector, intenta hacerse pasar por culpable de un crimen que no cometió... En los alrededores, tres adolescentes aburridos conducen una camioneta de forma imprudente, haciendo tonterías y lanzando objetos contra otros vehículos. Pero antes de que acabe la noche, habrán aprendido que el gamberrismo ciego también puede tener consecuencias dolorosas, y hasta mortales...', trailer_url = 'https://www.youtube.com/watch?v=XS8gh5qMlFw' WHERE id_api = 'tt0331811';

UPDATE Contenido SET id_tmdb = 11431, descripcion = 'El profesor de instituto Ben Wrightman (Jimmy Fallon) es un buen partido. Es encantador, divertido y fantástico con los niños. Cuando conoce a Lindsey Meeks (Drew Barrymore), una ambiciosa asesora comercial cuyo espíritu refulge tanto como su belleza, la atracción que sienten el uno por el otro es inmediata. Por supuesto, tienen sus diferencias. Ella es una adicta al trabajo, él adora sus vacaciones de verano. Él vive y respira por los Red Sox; ella no distingue a Carl Yastrzemski de Johnny Damon. Pero el verdadero amor vence cualquier obstáculo… al menos hasta que empiezan los entrenamientos de primavera de los Red Sox. Cuando los adorados Boston Red Sox llevan a cabo una de las temporadas más increíbles de la historia del béisbol, Ben y Lindsey deben decidir si, como pareja, rompen o luchan por mantener vivo su amor con entradas extras.', trailer_url = 'https://www.youtube.com/watch?v=uKaldffU02c' WHERE id_api = 'tt0332047';

UPDATE Contenido SET id_tmdb = 13193, descripcion = 'Mary (Jean Malone) quiere hacer un acto de buena voluntad "divina", como "curar" a su novio gay... mediante el sexo. Pero el resultado tiene poco de celestial, y de ser popular en el instituto ultrareligioso donde estudia Mary pasa a pertenecer al grupo de "desplazados".', trailer_url = 'https://www.youtube.com/watch?v=cgWdUumlgUo' WHERE id_api = 'tt0332375';

UPDATE Contenido SET id_tmdb = 615, descripcion = 'Año 33 de nuestra era. En la provincia romana de Judea, un misterioso carpintero llamado Jesús de Nazareth comienza a anunciar la llegada del "reino de Dios" y se rodea de un grupo de humildes pescadores: los Apóstoles. Durante siglos, el pueblo judío había esperado la llegada del Mesías - personaje providencial que liberaría su sagrada patria e instauraría un nuevo orden basado en la justicia-. Las enseñanzas de Jesús atraen a una gran multitud de seguidores que lo reconocen como el Mesías. Alarmado por la situación, el Sanedrín, con la ayuda de Judas Iscariote, uno de los doce Apóstoles, arresta a Jesús. Acusado de traición a Roma, Cristo es entregado a Poncio Pilato, quien, para evitar un motín, lo condena a a morir en la cruz como un vulgar criminal.', trailer_url = 'https://www.youtube.com/watch?v=XdQ4XnShG_o' WHERE id_api = 'tt0335345';

UPDATE Contenido SET id_tmdb = 401, descripcion = 'Andrew Largeman (Braff) vuelve a su casa natal, en Nueva Jersey, después de diez años de ausencia para asistir al funeral de su madre. Allí rememora su pasado y conoce a una chica, Samantha (Portman), que quizá pueda cambiar su vida. Largeman, que acaba de dejar los antidepresivos que ha estado tomando durante años, comienza a redescubrirse a sí mismo, lo que incluye enfrentarse a su padre, psicólogo, y ayudar a Samantha a superar sus propios problemas pisicológicos.', trailer_url = 'https://www.youtube.com/watch?v=u82n0e1mgmQ' WHERE id_api = 'tt0333766';

UPDATE Contenido SET id_tmdb = 3635, descripcion = 'Delft, Holanda, 1665. La joven Griet entra a servir en casa de Johannes Vermeer que, consciente de la intuición de la joven para la luz y el color, irá introduciéndola poco a poco en el misterioso mundo de su pintura. Por otro lado, Maria Thins, la suegra de Vermeer, al ver que Griet se ha convertido en la musa del pintor, decide no inmiscuirse en su relación con la esperanza de que su yerno pinte más cuadros. Griet se enamora cada vez más de Vermeer, aunque no está segura de cuáles son los sentimientos del pintor hacia ella. Finalmente, el maquiavélico Van Ruijven, consciente del grado de intimidad de la pareja, se las ingenia para que Vermeer reciba el encargo de pintar a Griet sola. El resultado será una magnífica obra de arte, pero, ¿qué precio deberá pagar Griet?', trailer_url = 'https://www.youtube.com/watch?v=1R2X-lJFkng' WHERE id_api = 'tt0335119';

UPDATE Contenido SET id_tmdb = 10327, descripcion = 'Elle Woods está de vuelta como la enérgica, optimista y megapija joven abogada de la facultad de Harvard. En esta ocasión, Elle irá a Washington a defender los derechos de los animales.', trailer_url = 'https://www.youtube.com/watch?v=I25jkF0bdJk' WHERE id_api = 'tt0333780';

UPDATE Contenido SET id_tmdb = 5516, descripcion = 'Un refinado profesor sureño reúne a una banda de ladrones con la intención de atracar un casino flotante. Para preparar el plan alquilan una habitación a una anciana negra, pero ésta descubre sus intenciones; decidirán entonces eliminarla, pero no será tarea fácil. Remake de un film británico del mismo título (en español "El quinteto de la muerte"), dirigido en el año 1955 por Alexander MacKendrick y protagonizado por Alec Guiness y Peter Sellers.', trailer_url = 'https://www.youtube.com/watch?v=BVL6AjybCZ0' WHERE id_api = 'tt0335245';

UPDATE Contenido SET id_tmdb = 10096, descripcion = 'Lo único que desea Jenna Rink en su décimotercer cumpleaños es ser guapa y popular. Tras una experiencia humillante delante del chico más guay de la escuela, Jenna desea fervientemente tener una nueva vida. Milagrosamente su deseo se hace realidad: de la noche a la mañana pasan 17 años y ella despierta convertida en una mujer de treinta.', trailer_url = 'https://www.youtube.com/watch?v=JbXKQSZFu1M' WHERE id_api = 'tt0337563';

UPDATE Contenido SET id_tmdb = 153, descripcion = 'Bob Harris y Charlotte son dos norteamericanos que se encuentran en Tokio. Bob es una estrella de cine de mediana edad que ha venido a rodar un anuncio. Charlotte es una mujer joven que acompaña a todas partes a su marido, un fanático del trabajo. Incapaces de dormir, los caminos de Bob y Charlotte se cruzan por casualidad y no tardará en nacer entre ellos una sorprendente amistad. Se aventuran juntos en la vida nocturna de Tokio, comparten inolvidables experiencias con los habitantes de la ciudad y terminan descubriendo una nueva manera de ver la vida.', trailer_url = 'https://www.youtube.com/watch?v=1s4YQqnbnM8' WHERE id_api = 'tt0335266';

UPDATE Contenido SET id_tmdb = 6964, descripcion = 'Harry Sanborn es un solterón recalcitrante que sólo sale con mujeres mucho más jóvenes que él. Él y Marin, su última conquista, han planeado un romántico fin de semana en la casa de la playa de la madre de ella. Cuando Harry sufre un infarto, la madre de Marin, Erica Barrry, una famosa escritora divorciada, acepta a regañadientes cuidarlo hasta que se reponga. La sorpresa de Harry es grande cuando se da cuenta de que se siente atraído por ella, que, a su vez, gracias a Harry, descubre de nuevo el amor. Pero a Erica también la corteja un joven y encantador médico. Una vez recuperado, Harry vuelve a su casa y a sus viejos hábitos. Sin embargo, la relación con Erica ha alterado su vida y sus sentimientos.', trailer_url = 'https://www.youtube.com/watch?v=DKeYq0JeBcI' WHERE id_api = 'tt0337741';

UPDATE Contenido SET id_tmdb = 9384, descripcion = 'Adaptación cinematográfica, en clave de humor, de la popular serie de televisión de los años setenta "Starsky & Hutch". Dave Starsky (Ben Stiller) y Ken “Hutch” Hutchinson (Owen Wilson) son dos detectives secretos de Bay City, California, unidos para realizar su primera misión. Starsky & Hutch contarán con la valiosa ayuda del astuto y genial Huggy Bear (Snoop Dogg) y de tres espectaculares animadoras (Carmen Electra, Amy Smart y Brande Roderick) para enfrentarse a un caso sumamente delicado y peligroso.', trailer_url = 'https://www.youtube.com/watch?v=o0NsujlK0FY' WHERE id_api = 'tt0335438';

UPDATE Contenido SET id_tmdb = 38, descripcion = 'Una mujer usa los servicios de una empresa para borrar de su memoria todo recuerdo de su ex pareja. Ofendido, el hombre intenta hacer lo mismo que ella, pero el proceso no sucede según lo esperado y el protagonista debe atravesar la gigantesca marea de recuerdos de su propio cerebro para recomponer las cosas.', trailer_url = 'https://www.youtube.com/watch?v=O6p-kwixXFg' WHERE id_api = 'tt0338013';

UPDATE Contenido SET id_tmdb = 9759, descripcion = 'Un joven recibe la llamada de una mujer que le dice que ha sido secuestrada y que la van a asesinar muy pronto. Además, sus captores buscan también a su marido y a su hijo. Ella necesita ayuda, pero no sabe dónde está y la batería del móvil comienza a agotarse.', trailer_url = 'https://www.youtube.com/watch?v=GAhDD5uKPfY' WHERE id_api = 'tt0337921';

UPDATE Contenido SET id_tmdb = 10226, descripcion = 'Marie, una joven de 20 años, es invitada a pasar unos días en la casa de los padres de su mejor amiga. Allí, en una granja aislada, rodeada de campos de maiz, Marie y su amiga piensan encontrar la tranquilidad necesaria para estudiar. Pero no será más que una ilusión; la primera noche llega a la casa una furgoneta conducida por un implacable asesino que masacra uno por uno a los miembros de la familia. Marie decide actuar para salvar a su amiga. Empieza un trepidante duelo entre ella y el asesino.', trailer_url = 'https://www.youtube.com/watch?v=fQdNvTgKHng' WHERE id_api = 'tt0338095';

UPDATE Contenido SET id_tmdb = 9620, descripcion = 'Michael Jennings es un brillante ingeniero que trabaja en proyectos especializados para una compañía de alta tecnología. Cada vez que completa un trabajo, éste es borrado de su memoria para que no pueda divulgar ningún secreto de la corporación. Muy bien pagado, Jennings espera ganar 90 millones de dólares por su último proyecto, en él ha estado trabajando tres años. Pero una vez finalizado, en vez del cheque, se le dice que él mismo accedió a perder el derecho a su pago. Con la memoria borrada como en los trabajos anteriores, Jennings, con la ayuda de su compañera y amante Rachel, tratará de averiguar qué sucedió en todo ese tiempo, del que no recuerda nada.', trailer_url = 'https://www.youtube.com/watch?v=CeakTMS_J9w' WHERE id_api = 'tt0338337';

UPDATE Contenido SET id_tmdb = 1571, descripcion = 'En Estados Unidos, la infraestructura de ordenadores que controla todo tipo de comunicaciones, transportes y energías sufre un devastador parón por parte de un grupo terrorista. El cerebro que se esconde tras esta trama ha tenido en cuenta hasta el más mínimo detalle de este devastador plan. Con lo que no había contado era con John McClane (Bruce Willis), un policía de la vieja escuela que conoce una o dos cosas acerca de cómo frustrar amenazas terroristas, el hombre adecuado para este tipo de trabajos...', trailer_url = 'https://www.youtube.com/watch?v=svIjk-nlh_c' WHERE id_api = 'tt0337978';

UPDATE Contenido SET id_tmdb = 10756, descripcion = 'Jim Evers (Eddie Murphy) está a punto de salir de viaje con su familia, pero una repentina llamada ahogará sus planes. Jim es agente inmobiliario y le acaban de informar de que van a poner en venta la mansión Gracey, un caramelo para cualquiera que se dedique a la venta de inmuebles. Su adicción al trabajo supera cualquier plan de ocio, aunque este fuera con su familia, y decide aplazar las vacaciones para pasar antes por la mansión, junto a su esposa (Marsha Tho-mason), que también es socia suya, y sus hijos. Una vez allí, la situación que se encuentran es bastante más tétrica de lo que esperaban.', trailer_url = 'https://www.youtube.com/watch?v=IAJBBmMhC9U' WHERE id_api = 'tt0338094';

UPDATE Contenido SET id_tmdb = 5255, descripcion = 'Esta es la historia de un jovencito en la víspera de Navidad quien aborda un poderoso y mágico tren que se dirige al hogar de Papá Noel, en el Polo Norte. Lo que se desarrolla es una aventura que sigue al dubitativo niño, quien toma un tren extraordinario al Polo Norte; durante este viaje, se embarca en una experiencia de autodescubrimiento que le muestra que las maravillas de la vida nunca se desvanecen para quienes creen.', trailer_url = 'https://www.youtube.com/watch?v=4XkHPphBN_Q' WHERE id_api = 'tt0338348';

UPDATE Contenido SET id_tmdb = 7131, descripcion = 'Siglo XIX. En medio de los montes de los Cárpatos está la misteriosa y mítica Transilvania, donde el mal siempre está presente, el peligro aparece cuando el sol se pone... y donde toman forma los monstruos que habitan las pesadillas de los hombres.', trailer_url = 'https://www.youtube.com/watch?v=HvFQv-0p0B0' WHERE id_api = 'tt0338526';

UPDATE Contenido SET id_tmdb = 12279, descripcion = 'La tecnología HD/3-D entra en escena cuando los jóvenes agentes Juni y Carmen Cortez emprenden la misión más emocionante de sus vidas: un viaje al interior de la realidad virtual de un videojuego en 3D que ha sido especialmente diseñado para acabar con ellos. Un videojuego en el que cobran vida los gráficos y criaturas más sorprendentes que puedan imaginarse. Los Spy Kids tendrán que plantar cara a unos niveles del juego cada vez más difíciles con el humor, los dispositivos especiales, la valentía, el espíritu familiar y sus rápidos reflejos como armas. Entre los muchos desafíos a los que deberán enfrentarse se incluyen, por ejemplo, una carrera contra los guerreros de la carretera o practicar surf sobre lava candente, todo para salvar al mundo de un villano sediento de poder: El Fabricante de Juguetes.', trailer_url = 'https://www.youtube.com/watch?v=mx0lo-xCljA' WHERE id_api = 'tt0338459';

UPDATE Contenido SET id_tmdb = 1792, descripcion = 'Los hermanos siameses Bo y Walt, unos extraordinarios deportistas, se sienten también orgullosos de su restaurante de comida rápida. Cuando Walt, que quiere ser actor, decide cumplir su sueño, convence a Bob para que lo acompañe a Los Ángeles. Allí entablan amistad con una sensual vecina que ayuda a Walt a conseguir un agente; lo malo es que éste sólo le ofrece un trabajo en una película pornográfica. Las cosas cambian cuando conocen a la mítica diva Cher. Ésta, descontenta con su nueva serie de televisión, intenta sabotearla y para ello contrata a Walt como coprotagonista. Sorprendentemente, el programa lejos de fracasar se hace muy popular.', trailer_url = 'https://www.youtube.com/watch?v=ZaZtut5al68' WHERE id_api = 'tt0338466';

UPDATE Contenido SET id_tmdb = 2567, descripcion = 'Biografía del polifacético Howard Hughes, que heredó un poco de dinero de la compañía de su padre para trasladarse a Hollywood donde amasó un gran fortuna. Fue uno de los productores más destacados del cine americano durante la década de los treinta y cuarenta, lanzando carreras como la de Jean Harlow y llegando a ser dueño de la RKO Radio Pictures. Pero Hughes, además de productor, fue un reconocido industrial y comerciante que también tuvo su importancia en el mundo de la aviación.', trailer_url = 'https://www.youtube.com/watch?v=dkwypzOQf8o' WHERE id_api = 'tt0338751';

UPDATE Contenido SET id_tmdb = 10775, descripcion = 'Ming es un topo infiltrado en el departamento de policía. Se hizo policía a los 18 años siguiendo las órdenes del jefe de una sociedad secreta de carácter criminal. Por su parte, Yan es un topo de la policía infiltrado en la banda desde hace ya diez años. Ambos se sienten cada vez más atrapados en esos mundos a los que no pertenecen.', trailer_url = 'https://www.youtube.com/watch?v=g_RyXAywKIw' WHERE id_api = 'tt0338564';

UPDATE Contenido SET id_tmdb = 11774, descripcion = 'Lemony Snicket cuenta la historia de los Bauedelaire, tres jóvenes huérfanos, Violet, Klaus y Sunny, quienes mientras buscan un nuevo hogar son tomados por un grupo de raros parientes y otra gente, incluyendo Lemony Snicket, quien narra la historia, y comenzando con el astuto y cobarde Conde Olaf que desea arrebatarles la herencia. Violet es la mayor, con 14 años y es la más valiente de los tres. El niño del medio, es el único varón, de 12 años, que es sumamente inteligente y obsesionado con las palabras, y Sunny, la más pequeña, habla un lenguaje que solo sus hermanos pueden entender y tiene tendencia a morder.', trailer_url = 'https://www.youtube.com/watch?v=h4nOqtgSJ4Y' WHERE id_api = 'tt0339291';

UPDATE Contenido SET id_tmdb = 2026, descripcion = 'Devastado por un fallo en una operación, el negociador de rehenes de la Policía de Los Ángeles Jeff Talley (Bruce Willis) se marcha de la ciudad y se va a vivir con su mujer e hija a una pequeña población en el tranquilo condado de Ventura. Un año después, se deberá volver a enfrentar a otro difícil caso de secuestro con rehenes...', trailer_url = 'https://www.youtube.com/watch?v=nmO-GZCakMc' WHERE id_api = 'tt0340163';

UPDATE Contenido SET id_tmdb = 10027, descripcion = 'Arrancado de los brazos de su madre por Bart, Danny sólo conoce el mundo que éste le ha mostrado: la habitación en la que vive y los actos de violencia que se ve obligado a cometer cuando las personas a las que Bart presta dinero se retrasan en el pago. Danny es, pues, un hombre adiestrado como un perro para obedecer las órdenes de su amo sin rechistar. Pero, un día, Bart cae en la emboscada que le tiende un deudor vengativo.', trailer_url = 'https://www.youtube.com/watch?v=AoBkHA7-I84' WHERE id_api = 'tt0342258';

UPDATE Contenido SET id_tmdb = 2056, descripcion = 'Finbar McBride odia ser el centro de atención de los demás, pero pasar inadvertido midiendo menos de uno treinta y cinco es poco menos que imposible. Finbar, que nació aquejado de raquitismo, desearía llevar una vida de aislamiento, disfrutando de su única pasión: los trenes. Por ello, se instala en una estación de tren abandonada de New Jersey, pero poco a poco, y sin quererlo, se va relacionando con sus escasos vecinos. Olivia Harris es una artista que lucha por superar la reciente muerte de su hijo y la ruptura de su matrimonio. El cercano puesto de perritos calientes lo lleva Joe Oramas, que tiene talento para la cocina y unas ganas insaciables de conversar. Inesperados lazos de afecto y entrega van uniendo a estos tres marginados, quedando de manifiesto que incluso el aislamiento es mejor cuando se comparte.', trailer_url = 'https://www.youtube.com/watch?v=l5i_1apppZ0' WHERE id_api = 'tt0340377';

UPDATE Contenido SET id_tmdb = 504, descripcion = 'Basada en hechos reales. Aileen Wuornos es una prostituta que fue ejecutada en 2002 en el estado de Florida, tras confesarse autora de seis asesinatos, incluido un policía. Aileen declaró que había matado en defensa propia, como reacción a los violentos ataques que sufria mientras ejercía su oficio. Al borde de la desesperación y del suicidio, conoce un día en un bar a Selby Wall, una joven lesbiana, que ha sido enviada por sus padres a vivir con su tía para "curar su homosexualidad". Wuornos, víctima de una trágica infancia llena de abusos, rápidamente se enamora de Selby, encontrando en ella una razón para vivir. Incapaz de encontrar un trabajo digno, Wuornos sigue ejerciendo la prostitución. Cuando uno de sus clientes la maltrata, ella lo mata en defensa propia, comenzando así una trágica cadena de asesinatos. Esta es la historia de una asesina, pero también una historia de amor entre dos inadaptadas.', trailer_url = 'https://www.youtube.com/watch?v=vq70brIQP40' WHERE id_api = 'tt0340855';

UPDATE Contenido SET id_tmdb = 2048, descripcion = 'En el año 2035, los robots son unos dispositivos que usamos todos los días y en quienes confiamos, excepto un detective paranoico, investigando lo que solo él cree que es un crimen perpetrado por un robot. El caso lo lleva a descubrir algo aún peor que amenaza la raza humana.', trailer_url = 'https://www.youtube.com/watch?v=xR3TT0nSORc' WHERE id_api = 'tt0343818';

UPDATE Contenido SET id_tmdb = 5966, descripcion = 'Reuben Feffer le tiene aversión al riesgo, pero su ordenada y planificada vida se complica cuando, durante su luna de miel, su mujer se interesa por un musculoso instructor cubano de submarinismo. Al mismo tiempo, entra en escena Polly, una amiga suya de la infancia, que lo introduce en los deportes de riesgo, la comida picante y el baile de la salsa. En definitiva, le enseña a vivir despreocupadamente y a disfrutar de cada momento.', trailer_url = 'https://www.youtube.com/watch?v=BTXS-5D_U8k' WHERE id_api = 'tt0343135';

UPDATE Contenido SET id_tmdb = 1824, descripcion = 'Henry Roth (Adam Sandler) es un veterinario marino que vive en Hawái y sale con muchas mujeres. Un día conoce a Lucy Whitmore (Drew Barrymore), una artista que tiene amnesia y no recuerda nada al día siguiente. Henry se enamora de ella y trata de hacer que se enamore de él cada día, inventando nuevas formas de llamar su atención. Pero tendrá que enfrentarse a varios obstáculos, como el ex novio de Lucy, el padre de ella y el olvido de la chica.', trailer_url = 'https://www.youtube.com/watch?v=17KJk3ErIx0' WHERE id_api = 'tt0343660';

UPDATE Contenido SET id_tmdb = 1247, descripcion = 'Biografía de James Wilson, entre 1930 y 1960. Graduado en la Universidad de Yale, acabó siendo uno de los fundadores de la CIA. Se supone que el personaje se basa en el legendario y astuto jefe de inteligencia James Jesús Angleton.', trailer_url = 'https://www.youtube.com/watch?v=MKStOxOrxiE' WHERE id_api = 'tt0343737';

UPDATE Contenido SET id_tmdb = 2841, descripcion = 'Cuando la I Guerra Mundial (1914-1918) se acerca a su fin, para una joven francesa está a punto de comenzar la más cruel de las batallas. Mathilde ha recibido la noticia de que su prometido Manech es uno de los cinco soldados heridos que, tras haber sido sometidos a un consejo de guerra, han sido enviados a la tierra de nadie que hay entre el ejército francés y el alemán, lo cual supone una muerte casi segura. Mathilde, que se niega a aceptar esa situación, emprende un extraordinario viaje para conocer el destino de su prometido. Las noticias que va recibiendo sobre Manech son desalentadoras. Aún así, animada por una fe y una esperanza inquebrantables y también por un gran optimismo, sigue su investigación hasta el final. A medida que se acerca a la verdad sobre los desafortunados soldados y su brutal castigo, se ve más envuelta en los horrores de la guerra y en las marcas indelebles que deja en quienes la han vivido.', trailer_url = 'https://www.youtube.com/watch?v=BNx2iuOGVVI' WHERE id_api = 'tt0344510';

UPDATE Contenido SET id_tmdb = 15370, descripcion = 'Esta es la historia de Haru, una joven cuya suerte cambiará un día al volver del instituto, cuando salvará a un gato de ser atropellado por un camión. Pero no es un gato común, es Lune, el Príncipe del Reino de los Gatos. En recompensa por su acción, Haru será invitada a pasar un tiempo en el Reino de los Gatos, aunque no es lo que ella esperaba....', trailer_url = 'https://www.youtube.com/watch?v=YgACXczvMPw' WHERE id_api = 'tt0347618';

UPDATE Contenido SET id_tmdb = 5137, descripcion = 'Famosos científicos de todo el mundo están desapareciendo misteriosamente, y la reportera del Chronicle, Polly Perkins y el hábil aviador Sky Captain lo están investigando. Arriesgando sus vidas viajan a lugares exóticos, pero, ¿podrá este dúo detener al Dr. Totenkopf, el malvado personaje que está detrás de este plan para destruir la tierra? Ayudados por Franky Cook, comandante de un escuadrón femenino, y un genio de la tecnología llamado Dex, Polly y Sky Captain parecen ser la única esperanza del planeta.', trailer_url = 'https://www.youtube.com/watch?v=PAyP5E5rPNU' WHERE id_api = 'tt0346156';

