UPDATE Contenido SET id_tmdb = 11836, descripcion = 'Hay problemas en Bikini Bottom: la corona del Rey Neptuno ha desaparecido y las sospechas recaen en el Sr. Krabs. Junto a Patrick, su mejor amigo, Bob Esponja marcha a la peligrosa Ciudad de Shell para rescatar la corona de Neptuno y salvar al Sr. Krabs.', trailer_url = 'https://www.youtube.com/watch?v=Tv8xk7BKaNM' WHERE id_api = 'tt0345950';

UPDATE Contenido SET id_tmdb = 1966, descripcion = 'Fue muchas cosas para muchas personas: un apuesto rey guerrero lleno de la ambición, el coraje y la arrogancia de la juventud, encabezando a su pequeño ejército contra las gigantescas fuerzas persas… un hijo que buscaba desesperadamente la aprobación de su severo padre, endurecido por las batallas, y que se debatía entre su lealtad a éste y su amor por su madre… un conquistador despiadado que nunca perdió una batalla y empujó a sus soldados a los confines del mundo conocido… un visionario cuyos sueños, hazañas y destino dejaron huella a lo largo de la historia, ayudando a dar forma a nuestro mundo actual. Fue todo eso y más. Fue Alejandro Magno.', trailer_url = 'https://www.youtube.com/watch?v=ZPfYZg1-jh8' WHERE id_api = 'tt0346491';

UPDATE Contenido SET id_tmdb = 363, descripcion = 'Después de haber intentado suicidarse, Cahit, un turco-alemán de cuarenta años, alcohólico y toxicómano, ha sido ingresado en la planta de psiquiatría, pero no consigue acostumbrarse a dormir sin drogas ni alcohol. A Sibel, una guapa chica turca de 20 años que ha nacido en Hamburgo, le gusta demasiado la vida para ser una buena musulmana. También ella intentó suicidarse para huir de la cárcel de rejas humanas que su familia, muy creyente y respetuosa de las tradiciones, había levantado a su alrededor. Una vez frustrado su suicidio, sólo ve una posibilidad para liberarse de su familia: casarse con Cahit.', trailer_url = 'https://www.youtube.com/watch?v=zRioyPHCSVo' WHERE id_api = 'tt0347048';

