UPDATE Contenido SET id_tmdb = 1452, descripcion = 'Tras varios años de misteriosa ausencia, Supermán regresa a la Tierra, pero un viejo enemigo intenta arrebatarle sus poderes. Tratando de proteger al mundo de una destrucción masiva, Supermán emprende una aventura épica de redención que lo lleva desde las profundidades del océano a las regiones más remotas del espacio.', trailer_url = 'https://www.youtube.com/watch?v=gKrGjD7ItsQ' WHERE id_api = 'tt0348150';

UPDATE Contenido SET id_tmdb = 7553, descripcion = 'Monty (Ryan Reynolds) lleva años trabajando como camarero en un restaurante; el futuro no le preocupa lo más mínimo. No es el mismo caso el de su compañero Dean (Justin Long), que empieza a cuestionarse su trabajo como camarero como un callejón sin salida. La ex-novia de Monty, Serena (Anna Faris), trabaja también con ellos en esa cocina de locos. Y junto a sus chiflados compañeros pasan los días entre platos, pedidos y comida, tratando de pasárselo lo mejor posible.', trailer_url = 'https://www.youtube.com/watch?v=HJEsNjH3JT8' WHERE id_api = 'tt0348333';

UPDATE Contenido SET id_tmdb = 4970, descripcion = 'La doctora Miranda Grey, una dedicada y exitosa psicóloga criminal, se despierta un día para encontrase que es una paciente en la propia institución mental donde trabaja, sin ningún recuerdo del asesinato que aparentemente ella ha cometido. Pronto descubre que su marido fue brutalmente asesinado 3 días atrás, y las pruebas de sangre... la incriminan a ella.', trailer_url = 'https://www.youtube.com/watch?v=STxbF5tl5T0' WHERE id_api = 'tt0348836';

UPDATE Contenido SET id_tmdb = 11128, descripcion = 'Brigada 49 se centra en la vida del bombero Jack Morrison (Joaquin Phoenix) mientras ésta pende de un hilo. En su celo por ayudar a rescatar a un ciudadano atrapado, Jack es arrojado a una parte muy profunda de un almacén ahora transformado en una caldera de llamas crujientes, impenetrable humo negro y escombros desplomándose. Aislado de toda ayuda, Jack lucha por sobrevivir, mientras que afuera su mentor y Jefe de Bomberos, Mike Kennedy (John Travolta), lucha por sacar con vida a su mejor amigo. Mientras que los dos hombres hacen una última y desesperada maniobra, Jack pasa revista a su vida desde el comienzo hasta este terrible momento final.', trailer_url = 'https://www.youtube.com/watch?v=h99fvKAYviM' WHERE id_api = 'tt0349710';

UPDATE Contenido SET id_tmdb = 163, descripcion = 'Han pasado tres años desde que Danny Ocean (George Clooney) y su equipo –liderado por el detallista Rusty Ryan (Brad Pitt), el prometedor carterista Linus Caldwell (Matt Damon), el experto en explosivos Basher Tarr (Don Cheadle) y el desvalijador de cajas fuertes Frank Catton (Bernie Mac)– llevaron a cabo uno de los más audaces y lucrativos atracos de la historia, robando al despiadado empresario Terry Benedict (Andy Garcia) hasta el último centavo que guardaba en su impenetrable cámara acorazada de Las Vegas. Después de repartir los 160 millones de dólares conseguidos, cada uno de los conocidos miembros del equipo de Ocean ha tratado de portarse bien, pasar desapercibido y llevar una vida legal... pero eso ha resultado ser difícil, para disgusto de Tess (Julia Roberts), la esposa de Danny.', trailer_url = 'https://www.youtube.com/watch?v=ATHwwFhB-UQ' WHERE id_api = 'tt0349903';

UPDATE Contenido SET id_tmdb = 1677, descripcion = 'La vida de Ray Charles es una alternancia de triunfos y fracasos personales que se suceden a lo largo de una dilatada y galardonada carrera en el mundo del espectáculo. Pero estamos hablando de un hombre que sintetizó sus luchas, su dolor y su oscuridad personal con la misma efectividad con la que supo fundir en su arte una miríada de estilos musicales: el jazz, el rhythm &amp; blues, el rock &amp; roll, el gospel y el country. Su historia tiene entonces un sentido muy distinto: la cadena de logros se transforma en el vibrante y conmovedor trayecto de un genio único con una visión propia que enseñó al mundo a escuchar música de una forma nueva. RAY es la biografía, nunca contada antes, de esa leyenda de la música americana que es Ray Charles. Se centra en el período más explosivo de la carrera de Charles, que comienza cuando este joven negro ciego se sube solo a un autobús en Florida y cruza el país para refinar su arte en la floreciente escena jazzística de Seattle.', trailer_url = 'https://www.youtube.com/watch?v=jVHCQfcugdw' WHERE id_api = 'tt0350258';

UPDATE Contenido SET id_tmdb = 953, descripcion = 'Cuenta la historia de cuatro divertidos animales del zoo de Central Park, Nueva York, (Alex el león, Marty la cebra, Gloria la hipopótamo y Melman la jirafa). Llevan toda su vida encerrados en cautividad sin poder experiemtnar el sabor de la libertad y se han propuesto idear un plan para salir de allí juntos. Un día, una serie de casualidades les llevan a lograr lo que tanto ansiaban y huyen de aquel lugar. Terminan en plena naturaleza, concretamente en la idílica isla de Madagascar. Allí descubrirán, a base de apasionantes aventuras, que la vida salvaje es muy diferente a lo que ellos pensaban y que vivir en libertad no es tan fácil como imaginaban.', trailer_url = 'https://www.youtube.com/watch?v=RZFaaamXo8A' WHERE id_api = 'tt0351283';

UPDATE Contenido SET id_tmdb = 2566, descripcion = 'George muere aplastada por el retrete de una estación espacial que se le cae encima accidentalmente. Pero su historia no ha hecho más que empezar: después de su terrible muerte, es recogida por un par de aparecidos que le informan de que, a partir de ese momento, va a participar con ellos en la misión de recolectar almas. Tan irónica como cuando estaba viva, pronto descubrirá que en el Más Allá hay unas reglas que dictan el comportamiento de vivos y muertos y tendrá que enfrentarse a situaciones como la de tener que volver a su odiado trabajo, ya que los muertos también tienen que ganarse la vida.', trailer_url = 'https://www.youtube.com/watch?v=cNHDFf1YLlc' WHERE id_api = 'tt0348913';

UPDATE Contenido SET id_tmdb = 1406, descripcion = 'Deadwood recrea la historia de la ciudad homónima del Estado de Montana durante el siglo XIX. El pueblo de Deadwood, existente en la realidad, aún hoy mantiene vivo el recuerdo de sus primeros colonos buscadores de oro. La serie ofrece una buena combinación de personajes reales, tramas noveladas y leyendas que narran las vivencias de una ciudad sin ley en un territorio robado. La serie presenta temas clásicos del género del western: juegos de azar, tiroteos, ahorcamientos, duelos, indios y colonos, nómadas buscadores de o y las chicas del Salloon; sin dejar de lado a los míticos personajes sacados de la vida real como Calamity Jane o Wild Bill.', trailer_url = 'https://www.youtube.com/watch?v=mFIojradr4Y' WHERE id_api = 'tt0348914';

UPDATE Contenido SET id_tmdb = 11007, descripcion = 'Remake de un film del mismo título de 1950, que relata las peripecias de los Baker, un matrimonio con doce hijos. Cuando el padre consigue hacer realidad el sueño de su vida, entrenar a un equipo de fútbol americano, la familia tiene que trasladarse desde un pequeño pueblo de Illinois a una gran ciudad.', trailer_url = 'https://www.youtube.com/watch?v=csiX-mSqkGc' WHERE id_api = 'tt0349205';

UPDATE Contenido SET id_tmdb = 9477, descripcion = 'Arturo está deseando abandonar Bretaña para regresar a la paz y estabilidad de Roma. Pero antes, una última misión le hace comprender tanto a él como a los caballeros de la Mesa Redonda (Lancelot, Galahad, Bors,Tristán y Gawain) que, tras la caída de Roma (476 d.C.), lo que Bretaña necesita es un rey que la defienda de la amenaza de la invasión sajona en un tiempo nuevo. Guiado por Merlín y por la valiente y hermosa Ginebra, Arturo tendrá que encontrar en sí mismo la fuerza necesaria para cambiar el curso de la historia.', trailer_url = 'https://www.youtube.com/watch?v=8Fw_1TwxTRU' WHERE id_api = 'tt0349683';

UPDATE Contenido SET id_tmdb = 14292, descripcion = 'Basada en hechos reales, narra la historia de Herb Brooks (Kurt Russell), el jugador convertido en entrenador que llevó al equipo americano de hockey sobre hielo a enfrentarse en los Juegos Olímpicos de Invierno de 1980 al aparentemente invencible equipo de la Unión Soviética.', trailer_url = 'https://www.youtube.com/watch?v=X7xfRXGMrDM' WHERE id_api = 'tt0349825';

UPDATE Contenido SET id_tmdb = 11358, descripcion = 'Chris Vaughn (The Rock) es un soldado retirado de las fuerzas especiales del ejército americano que vuelve a su hogar natal para volver a empezar de nuevo. Pero mientras él estuvo fuera, su ciudad se convirtió en un sitio peligroso y con mucha criminalidad. Uno de los culpables de ese cambio es el acaudalado Jay Hamilton (Neal McDonough), su rival en el instituto. A Chris, que regresaba con la intención de recuperar sus viejas relaciones y construir una nueva vida, lo que se encuentra no es lo que recordaba y luchará, bate en mano, para poner las cosas en su sitio.', trailer_url = 'https://www.youtube.com/watch?v=ZGn_qOhEYoI' WHERE id_api = 'tt0351977';

UPDATE Contenido SET id_tmdb = 921, descripcion = 'Basada en una historia real. Después de haberse retirado del boxeo, James J. Braddock decidió volver al cuadrilátero durante los años de la Gran Depresión para poder alimentar a su familia. No era un boxeador con talento, pero su coraje, sacrificio y dignidad lo llevaron hasta la cumbre.', trailer_url = 'https://www.youtube.com/watch?v=PpdRWplFjG8' WHERE id_api = 'tt0352248';

UPDATE Contenido SET id_tmdb = 4442, descripcion = 'Alemania, siglo XIX. Jake y Will Grimm son dos hermanos que se dedican a recorrer los pueblos embaucando a los pobres lugareños: primero les cuentan historias de maldiciones, espíritus y fantasmas que los acechan y después fingen salvarlos por medio de exorcismos y rituales varios. Pero, un día, llegan a un pueblo sobre el que pesa una maldición real, un pueblo situado cerca de un bosque encantado en el que recientemente han desaparecido varias niñas. Los Grimm tendrán entonces que demostrar su valentía y coraje para salvar al pueblo de una amenaza terrorífica.', trailer_url = 'https://www.youtube.com/watch?v=jGU11iEIeCQ' WHERE id_api = 'tt0355295';

UPDATE Contenido SET id_tmdb = 11423, descripcion = 'Corea del Sur, 1986. Una joven aparece brutalmente violada y asesinada. Dos meses después, se producen una serie de violaciones y asesinatos en circunstancias similares. Para buscar al asesino, se organiza un destacamento especial, encabezado por un detective de la policía local (Park Doo-man) y un detective de la policía de Seúl (Seo Tae-yoon), que ha solicitado ser asignado al caso.', trailer_url = 'https://www.youtube.com/watch?v=0n_HQwQU8ls' WHERE id_api = 'tt0353969';

UPDATE Contenido SET id_tmdb = 300, descripcion = 'Stephane (García Bernal), un joven diseñador mexicano tímido e introvertido, es cautivo de sus propios sueños, y siempre trata de despertarse para controlar su imaginación, que amenaza con suplantar el mundo real. En su vida se presenta una oportunidad de cambio cuando su madre, francesa, lo convence para que vuelva a su casa natal en París, prometiéndole un trabajo. Su decepción es grande cuando comprueba que se trata de un rutinario trabajo en una pequeña oficina que comparte con tres singulares compañeros, en especial el excéntrico Guy (Alain Chabat). Sin embargo, la decepción desaparece cuando conoce a su vecina Stephanie (Charlotte Gainsbourg) y a su amiga Zoe (Emma de Caunes).', trailer_url = 'https://www.youtube.com/watch?v=dHtE0szIip0' WHERE id_api = 'tt0354899';

UPDATE Contenido SET id_tmdb = 9787, descripcion = 'Años 70. Narra la historia de los legendarios Z-Boys, un grupo de jóvenes surferos y skaters del barrio de Dogtown, en Los Ángeles, que practicaban el surf en la playa de Venice. Cuando los Z-Boys difundieron este deporte, se hicieron enormemente populares en California.', trailer_url = 'https://www.youtube.com/watch?v=KHwimJTfvxE' WHERE id_api = 'tt0355702';

UPDATE Contenido SET id_tmdb = 9352, descripcion = 'Cuando la berlinense Mieke se declara, vía e-mail, al norteamericano Scott, éste la rechaza creyendo que es un hombre. Cuando descubre su error intenta ponerse en contacto con ella, pero resulta imposible. La única forma de conquistarla parece viajar hasta Berlín (Alemania) y para ello, en su viaje le acompañarán su amigo Cooper y los gemelos Jenny y Jamie.', trailer_url = 'https://www.youtube.com/watch?v=Vo7-Vb_NijY' WHERE id_api = 'tt0356150';

UPDATE Contenido SET id_tmdb = 713, descripcion = 'Dave Chappelle''s singular point of view is unleashed through a combination of laidback stand-up and street-smart sketches.', trailer_url = NULL WHERE id_api = 'tt0353049';

UPDATE Contenido SET id_tmdb = 787, descripcion = 'Jane y John Smith forman una pareja de vida acomodada dentro de un ordinario y monótono matrimonio suburbano. Además ambos ocultan algo por lo que su pareja mataría por saber: los dos son agentes secretos, asesinos increíblemente eficientes que trabajan para organizaciones que compiten entre sí. Además, un día el Sr. y la Sra. Smith descubren una nueva fuente de emoción en su matrimonio cuando se les contrata para asesinarse mutuamente, pues será entonces cuando comienza la verdadera diversión...', trailer_url = 'https://www.youtube.com/watch?v=KYizf53DqZw' WHERE id_api = 'tt0356910';

UPDATE Contenido SET id_tmdb = 11247, descripcion = 'Adaptación moderna del famoso cuento de "Cenicienta". La adolescente Sam Montgomery vive a disposición de su egocéntrica madrastra Fiona y de sus odiosas hermanastras, quienes la tratan más como una sirvienta que como un miembro de la familia. Sam sueña con ingresar en Princeton, pero de pronto su vida social se complica cuando conoce a su Príncipe Azul en Internet. Pero cuando su amigo de la red termina siendo el chico más popular de la escuela, Austin Ames, Sam despierta a la realidad olvidando su móvil cuando suena la medianoche. Temiendo ser rechazada si él supiera quien es ella en realidad, Sam hace todo lo posible para que Austin no descubra quién es su princesa. Aunque Austin tiene un plan para encontrarla...', trailer_url = 'https://www.youtube.com/watch?v=B_VFs9j95gc' WHERE id_api = 'tt0356470';

UPDATE Contenido SET id_tmdb = 10145, descripcion = 'Telly Paretta se encuentra atormentada por el recuerdo de su hijo de ocho años, Sam, fallecido hace 14 meses en un accidente aéreo. Mientras intenta superar la pena y el consiguiente alejamiento de su marido Jim, su psiquiatra, el Dr. Munce, le informa de que está sufriendo alucinaciones, que su hijo nunca existió y que ella misma está creando sus memorias. Confusa, intenta encontrar evidencias de la existencia de Sam, fotos, vídeos, libros de recuerdos. Pero todo ha desaparecido. Telly está convencida de que se está volviendo loca hasta que conoce a Ash Correll, el padre de una de las otras víctimas del accidente de aviación. Juntos, se embarcan en una búsqueda para probar la existencia de sus hijos y demostrar su salud mental.', trailer_url = 'https://www.youtube.com/watch?v=wET_ZdzwqbE' WHERE id_api = 'tt0356618';

UPDATE Contenido SET id_tmdb = 8920, descripcion = 'La vida no podría ser más dulce para Garfield, el gato al que todos adoran. Apalancado es un confortable sofá delante de la televisión, zampándose un buen trozo de lasaña (su comida favorita) y lanzando pullas a su angustiado dueño, Jon, Garfield se siente el dueño de su mundo. Cuando Jon lleva a Garfield a la consulta de la guapa veterinaria Liz Wilson, ésta le endosa a Jon una entusiasta y jadeante criatura que menea animosamente la cola, y representa todo lo que Garfield odia en la vida. Garfield conoce así a Odie, un perro adorable y no demasiado inteligente.', trailer_url = 'https://www.youtube.com/watch?v=UlvKV6K5Pz4' WHERE id_api = 'tt0356634';

UPDATE Contenido SET id_tmdb = 1599, descripcion = 'Convencido de que las coincidencias no existen, sino que guardan alguna relación con los principales enigmas de la vida, Albert Markovski trata de descubrir el significado de esas coincidencias. Para ello entra en contacto con Bernard y Vivian Jaffe, un matrimonio de Detectives Existenciales o metafísicos, que investigan los misterios más íntimos de sus clientes a base de seguirlos de cerca, observar sus actividades diarias e interrogar a sus amigos y compañeros de trabajo.', trailer_url = 'https://www.youtube.com/watch?v=LJl1VJWgmEs' WHERE id_api = 'tt0356721';

UPDATE Contenido SET id_tmdb = 9043, descripcion = 'Los Stone, una familia de Nueva Inglaterra, se reúne en vacaciones. El hijo mayor lleva a casa a su novia para que conozca a sus padres, a sus hermanos y hermanas. Los bohemios Stone reciben a su visitante (una ambiciosa y controladora neoyorquina) con una mezcla de aturdimiento, confusión y hostilidad. Antes de que terminen las vacaciones, hay relaciones que se rompen y otras que se crean, se revelan secretos y la familia Stone va a seguir unida por su extraordinaria capacidad de amar. Sybil Stone es la matriarca y base de la familia Stone, una extrovertida mujer de rompe y rasga que sólo quiere lo mejor para sus cinco hijos. Increíblemente guapa, su cara refleja ahora una reciente nota de fragilidad o de fatiga, lo cual sugiere que quizás Sybil esconda un secreto.', trailer_url = 'https://www.youtube.com/watch?v=ps8DhuMfScQ' WHERE id_api = 'tt0356680';

UPDATE Contenido SET id_tmdb = 9947, descripcion = 'Elektra (Jennifer Garner), tras recuperarse de las mortales heridas sufridas en "Daredevil", se convierte en la más peligrosa asesina del mundo. Una vez asignada su última misión, Elektra tomará una decisión que llevará su vida en una nueva dirección... o la destruirá para siempre.', trailer_url = 'https://www.youtube.com/watch?v=n348Czg5t3s' WHERE id_api = 'tt0357277';

UPDATE Contenido SET id_tmdb = 8699, descripcion = 'Ron Burgundy es el presentador de noticias más famoso de San Diego en los años setenta. Cuando se entera de que Veronica Corningstone, una reportera feminista y ambiciosa, va a trabajar con él, Ron está de acuerdo mientras la nueva se ocupe de las exposiciones de gatos, cocina y otras especialidades "femeninas". Pero Veronica no está dispuesta a ser un florero: quiere sentarse detrás de la mesa del presentador. A partir de ese momento, ya no se trata de un enfrentamiento, sino de una guerra abierta entre los dos.', trailer_url = 'https://www.youtube.com/watch?v=-T3wnP91OnI' WHERE id_api = 'tt0357413';

UPDATE Contenido SET id_tmdb = 9928, descripcion = 'Rodney Hojalata es un joven y genial inventor que sueña con hacer del mundo un lugar mejor. Cappy es una atractiva ejecutiva robot de la que Rodney se queda prendado al instante. Ratchet es el tirano corporativo; y luego está el Gran Soldador, un magistral inventor que ha perdido el norte … hasta que tropieza con el irreprimible soñador de Rodney. Además está un grupo de robots inadaptados conocidos como los Oxidados liderados por Manivela.', trailer_url = 'https://www.youtube.com/watch?v=HWz297wjsjU' WHERE id_api = 'tt0358082';

UPDATE Contenido SET id_tmdb = 116745, descripcion = 'Remake de "La vida secreta de Walter Mitty", película estrenada en 1947 y que fue dirigida por Norman Z. McLeod. La historia se basaba en un relato de James Thurber que giraba en torno al tímido empleado de una editorial que consigue evadirse de su gris existencia imaginando que es el héroe de grandes aventuras; un día, su sueño se hace realidad cuando conoce a una misteriosa mujer que le implica en una peligrosa misión.', trailer_url = 'https://www.youtube.com/watch?v=Bp_cxxqOaPM' WHERE id_api = 'tt0359950';

UPDATE Contenido SET id_tmdb = 69, descripcion = 'Biopic del gran cantante de música country Johnny Cash. La historia comienza en Arkansas, en la época de la Gran Depresión. John R. Cash es el hijo de un aparcero, pero no tardará en iniciar salvajes giras con los pioneros del rock and roll: Elvis Presley, Carl Perkins, Roy Orbison, Jerry Lee Lewis y Waylon Jennings, giras que culminan con su inolvidable concierto de 1968 en la Prisión de Folsom. Cash se convirtió en el artista más en boga del momento, vendiendo incluso más que los Beatles.', trailer_url = 'https://www.youtube.com/watch?v=rYs6To-vjmQ' WHERE id_api = 'tt0358273';

UPDATE Contenido SET id_tmdb = 4380, descripcion = 'John Clark es un adicto al trabajo que siente estar atrapado en una aburrida existencia de emociones. Pero una noche, toda su vida cambia cuando la visión de una hermosa instructora de baile lo inspira a romper su rutina e inscribirse a clases de baile de salón. Ahora, deberá escoger sus pasos con cuidado, y mover muy bien sus pies, para poder mantener su nueva y emocionante pasión oculta de su familia y sus amigos.', trailer_url = 'https://www.youtube.com/watch?v=UGtS3CL-zpo' WHERE id_api = 'tt0358135';

UPDATE Contenido SET id_tmdb = 36648, descripcion = 'Durante años, Blade ha luchado contra los vampiros sin que el mundo supiera lo que sucedía en los bajos fondos. Pero ahora, tras caer en las redes del FBI, se ve forzado a salir a la luz del día para unir sus fuerzas con un clan de humanos cazadores de vampiros que nunca supo que existían, los Nightstalkers. Junto a Abigail y Hannibal, Blade sigue la pista de una Antigua criatura que lo está acechando el vampiro original: Drácula.', trailer_url = 'https://www.youtube.com/watch?v=Ug3vkBoUKrs' WHERE id_api = 'tt0359013';

UPDATE Contenido SET id_tmdb = 16869, descripcion = 'Segunda Guerra Mundial. Durante la ocupación de Francia por los alemanes, Shosanna Dreyfus presencia la ejecución de su familia por orden del coronel nazi Hans Landa. Ella consigue huir a París, donde adopta una nueva identidad como propietaria de un cine. En otro lugar de Europa, el teniente Aldo Raine adiestra a un grupo de soldados judíos "Los bastardos" para atacar objetivos concretos. Los hombres de Raine y una actriz alemana, que trabaja para los aliados, deben llevar a cabo una misión que hará caer a los jefes del Tercer Reich. El destino quiere que todos se encuentren bajo la marquesina de un cine donde Shosanna espera para vengarse.', trailer_url = 'https://www.youtube.com/watch?v=wlIeworVv2A' WHERE id_api = 'tt0361748';

UPDATE Contenido SET id_tmdb = 11823, descripcion = 'Peter (Paul Bettany), un tenista que ocupa un lugar muy bajo en el ranking internacional, decide participar en el torneo de Wimbledon, aunque sus posibilidades de éxito son prácticamente nulas. Durante el torneo, conoce a la tenista americana Lizzie (Kirsten Dunst) y se enamora de ella. Entonces, su afán de superación unido a su destreza y a una racha de buena suerte lo catapultan de una ronda a la siguiente, teniendo al alcance de su mano el viejo sueño de ganar uno de los títulos del Gran Slam.', trailer_url = 'https://www.youtube.com/watch?v=aLPVMMWtyA4' WHERE id_api = 'tt0360201';

UPDATE Contenido SET id_tmdb = 254, descripcion = 'La suerte de Ann Darrow cambia cuando conoce a Carl Denham, un empresario que lucha para abrirse camino en el mundo del espectáculo. A ellos se une Jack Driscoll, un autor de teatro neoyorquino. Los tres emprenden un viaje que los llevará hasta una remota isla, donde Denham tiene previsto dirigir una película. Allí descubren un ser increíble, un gorila gigante, King Kong, que habita en una frondosa selva, donde criaturas prehistóricas han vivido ocultas durante millones de años. Denham, con un apetito insaciable de grandeza, enseguida ve la fama que puede reportarle la captura del gorila y su exhibición en Nueva York.', trailer_url = 'https://www.youtube.com/watch?v=9extfjDZCts' WHERE id_api = 'tt0360717';

UPDATE Contenido SET id_tmdb = 561, descripcion = 'John Constantine ha estado en el infierno y ha vuelto. Nació con un don que no deseaba, la capacidad de reconocer claramente a los ángeles y a los demonios que andan por la tierra bajo un aspecto humano, Constantine se vio empujado al suicido para escapar de la atormentadora claridad de su visión. Pero fracasó. Ahora, marcado por su intento de suicidio, patrulla la frontera terrenal entre el cielo y el infierno, esperando en vano ganarse el camino a la salvación enviando a los esbirros de Luciffer de vuelta al averno. Cuando una desesperada pero escéptica detective de policía consigue su ayuda para resolver la misteriosa muerte de su querida hermana gemela, su investigación les lleva a través del mundo de demonios y ángeles que subyace justo bajo el paisaje de la actual ciudad de Los Angeles. Atrapados en una catastrófica serie de acontecimientos sobrenaturales, los dos se encuentran inextricablemente involucrados y tratan de encontrar su propia paz a cualquier precio.', trailer_url = 'https://www.youtube.com/watch?v=YOQ3TWUAeJY' WHERE id_api = 'tt0360486';

UPDATE Contenido SET id_tmdb = 1777, descripcion = 'Michael Moore indaga cómo la administración de Bush utilizó el trágico ataque a las Torres Gemelas para su propio beneficio político. Moore nos muestra la controvertida elección de George W. Bush en el año 2000 para seguir su ascenso de mediocre petrolero texano a presidente de Estados Unidos. Tras más de un año de investigación, Michael Moore descubre las oscuras relaciones de negocio entre el padre del Presidente y la familia de Osama Bin Laden, poniendo de relieve que el poder y la riqueza del enemigo número uno de los estadounidenses ha aumentado gracias a este vínculo.', trailer_url = 'https://www.youtube.com/watch?v=ubX6CJ4rowo' WHERE id_api = 'tt0361596';

UPDATE Contenido SET id_tmdb = 594, descripcion = 'Viktor Navorski es un inmigrante balcánico que, al estallar la guerra en su país y quedar anulado su pasaporte, se encuentra involuntariamente exiliado en un aeropuerto de los Estados Unidos.', trailer_url = 'https://www.youtube.com/watch?v=dgXyQUMRpj4' WHERE id_api = 'tt0362227';

UPDATE Contenido SET id_tmdb = 4553, descripcion = 'Trevor Reznik, un empleado de una fábrica, padece desde hace tiempo un grave problema de insomnio, un mal que él esconde y que le provoca serias alucinaciones. Trevor no duerme desde hace un año. La fatiga le ha comportado un horrible deterioro de su condición física y su salud mental. Repelidos por su aspecto físico, sus compañeros de trabajo primero le evitan, y después se volverán contra él cuando uno de ellos pierde un brazo en un incidente en el que Trevor se ve involucrado.', trailer_url = 'https://www.youtube.com/watch?v=AGtIn8tkK2Q' WHERE id_api = 'tt0361862';

UPDATE Contenido SET id_tmdb = 4257, descripcion = 'Una nueva entrega de la franquicia que parodia los últimos títulos del cine americano. Esta vez, la ingenua Cindy Campbell (Anna Faris) intenta hacer carrera en la atención sanitaria a domicilio, y encuentra trabajo con una horripilante anciana que vive en una horripilante casa embrujada por una presencia fantasmal. Si a esto le añades un vecino guapetón y la amenaza de unos alienígenas que quieren dominar la tierra... el pelo rubísimo de Cindy se erizará presa del miedo más electrizante. Nuestra valiente heroína vuelve a sumergirse en la acción más enloquecida en su intento de descifrar los extraños mensajes que le llegan del más allá. Pero eso no le impide seguir buscando el amor en los sitios más inusitados y de salvar el mundo de la destrucción masiva.', trailer_url = 'https://www.youtube.com/watch?v=X2UbAb61zG4' WHERE id_api = 'tt0362120';

UPDATE Contenido SET id_tmdb = 10214, descripcion = 'Diez años después de perturbar la vida de un hombre ingenuo, la famosa máscara de Loki cae en manos de un joven padre: cuando el caricaturista Tim Avery (Jamie Kennedy) supera su temor a la paternidad tras el nacimiento de su primer hijo, descubre que el niño ha nacido con los poderes de la máscara. La situación se complica cuando el celoso perro de la familia se enfrenta al niño por el control de la máscara. Lo que todos ignoran es que Loki (Alan Cumming), el malvado dios escandinavo, busca la máscara y está dispuesto a todo con tal de recuperarla.', trailer_url = 'https://www.youtube.com/watch?v=LPiOevW-Hc4' WHERE id_api = 'tt0362165';

UPDATE Contenido SET id_tmdb = 10795, descripcion = 'Margot, la mujer de Alex, fue brutalmente asesinada por un psicópata. Incapaz de recuperarse de la pérdida, su marido no deja de recordarla ni por un momento. Un día, ocho años después, recibe un email. Lo abre y se encuentra con una imagen en tiempo real, la cara de una mujer entre la multitud: es la de Margot', trailer_url = 'https://www.youtube.com/watch?v=cmQtt8xxK54' WHERE id_api = 'tt0362225';

UPDATE Contenido SET id_tmdb = 11184, descripcion = 'En 1948, la publicación del libro "El comportamiento sexual en el hombre", obra del biólogo Alfred Kinsey, constituyó una auténtica revolución que cambió para siempre la historia de la cultura americana: cientos de personas empezaron a replantearse los aspectos más íntimos de su vida y a cuestionarse los prejuicios y tabúes impuestos por una sociedad excesivamente puritana. Esta obra dio lugar a uno de los debates más intensos del siglo pasado. A Kinsey se le ha considerado el padre de la revolución sexual de los 60.', trailer_url = 'https://www.youtube.com/watch?v=MRfi2jqmjFI' WHERE id_api = 'tt0362269';

UPDATE Contenido SET id_tmdb = 421, descripcion = 'Tras preparar un plan para vengar la muerte de su colega a manos de un mítico tiburón blanco, el oceanógrafo Steve Zissou (Bill Murray) recluta a una tripulación que incluye a su esposa (Anjelica Huston), a una periodista (Cate Blanchett) y a un joven que podría ser su hijo (Owen Wilson).', trailer_url = 'https://www.youtube.com/watch?v=-ncszM2vjb8' WHERE id_api = 'tt0362270';

UPDATE Contenido SET id_tmdb = 22825, descripcion = '¿Qué pasaría si alguien te diera una caja con un botón que, si lo aprietas, haría aparecer un millón de dólares pero, simultáneamente, se llevaría la vida de alguien que no conoces? Estamos en el año 1976. Norma Lewis es profesora en un instituto privado y su marido, Arthur, es ingeniero de la NASA. Son, en todos los aspectos, una pareja normal que lleva una vida normal en las afueras de la ciudad con su hijo joven… hasta que un hombre misterioso con un rostro horrible y desfigurado aparece en su puerta y presenta a Norma su propuesta de vida alternativa: la caja. Norma y Arthur, que sólo tienen 24 horas para decidirse, se enfrentan a un dilema moral imposible. Lo que no saben es que, decidan lo que decidan, ya han empezado a desencadenarse terribles consecuencias. Pronto descubren que no pueden controlar las ramificaciones de su decisión y que éstas se extienden mucho más allá de su destino.', trailer_url = 'https://www.youtube.com/watch?v=4R4ggPKLwRg' WHERE id_api = 'tt0362478';

UPDATE Contenido SET id_tmdb = 613, descripcion = 'Berlín, abril de 1945. En las calles de Berlín se libra una encarnizada batalla. Hitler y sus fieles se han atrincherado en un búnker. Entre ellos se encuentra Traudl Junge, la secretaria personal del Führer. En el exterior, la situación se recrudece. A pesar de que Berlín ya no puede resistir más, Hitler se niega a abandonar la ciudad y, acompañado de Eva Braun, prepara su despedida.', trailer_url = 'https://www.youtube.com/watch?v=Fb0Fb31LECY' WHERE id_api = 'tt0363163';

