UPDATE Contenido SET id_tmdb = 3750, descripcion = 'Sean y Christian son dos prestigiosos cirujanos plásticos que trabajan en la lujosa y glamourosa Miami. El trabajo, las envidias, los problemas personales y amorosos se entrecruzan en afiladas tramas. En 2004 esta popular y cínica teleserie, entonces minoritaria, sorprendió a todos cuando consiguió el Globo de Oro a la mejor serie dramática de televisión, venciendo a "The Sopranos", la gran favorita.', trailer_url = 'https://www.youtube.com/watch?v=v6JdfGMQK98' WHERE id_api = 'tt0361217';

