UPDATE Contenido SET id_tmdb = 924, descripcion = 'Un grupo de supervivientes se refugia en un centro comercial tras una epidemia que ha convertido a la mayoría de la población en zombis. El líder del grupo es el policía Kenneth Hall (Ving Rhames), que junto con otros personajes como la enfermera Ana Clark (Sarah Polley), el vendedor Michael (Jake Weber) o el experto en armas Andy (Bruce Bohne) intenta sobrevivir y escapar de los muertos vivientes. El grupo tendrá que enfrentarse a los zombis, a otros supervivientes hostiles y a sus propios conflictos internos, mientras busca una salida y una esperanza.', trailer_url = 'https://www.youtube.com/watch?v=DV8mJcuYVaA' WHERE id_api = 'tt0363547';

