UPDATE Contenido SET id_tmdb = 411, descripcion = 'La historia narra las aventuras de cuatro hermanos: Lucy, Edmund, Susan y Peter, que durante la Segunda Guerra Mundial descubren el mundo de Narnia, al que acceden a través de un armario mágico mientras juegan al escondite en la casa de campo de un viejo profesor. En Narnia descubrirán un mundo increíble habitado por animales que hablan, duendes, faunos, centauros y gigantes al que la Bruja Blanca- Jadis- ha condenado al invierno eterno. Con la ayuda del león Aslan, el noble soberano, los niños lucharán para vencer el poder que la Bruja Blanca ejerce sobre Narnia en una espectacular batalla y conseguir así liberarle de la maldición del frío.', trailer_url = 'https://www.youtube.com/watch?v=3mKPrxjwF7A' WHERE id_api = 'tt0363771';

UPDATE Contenido SET id_tmdb = 2038, descripcion = 'Sin haber cruzado antes una palabra en el instituto, Drake y Josh se convierten en hermanastros de la noche a la mañana. Drake Parker toca la guitarra en su propia banda, llamada "Drake y sus Notas Rockeras". Es guapo y tiene éxito con las chicas, incluso sale a veces con dos chicas a la vez, y no le importa sacar malas notas, como le sucede a su hermanastro, Josh, un buen estudiante al que no le gustan los deportes, adora los trucos de magia, la cocina y los videojuegos. A Josh no le va bien con las chicas, y es fan de Oprah Winfrey. Viven con la madre de Drake y el padre de Josh y Megan, la hermana de Drake, a quien le gusta hacer bromas pesadas a los chicos. Todos forman una familia, con sus diferencias y sus distintas formas de ser.', trailer_url = 'https://www.youtube.com/watch?v=NEKpuyOj4kI' WHERE id_api = 'tt0363328';

UPDATE Contenido SET id_tmdb = 9472, descripcion = 'Peter LaFleur (Vince Vaughn), es el propietario del gimnasio Average Joe''s, el cual está por quebrar. La clientela del gimnasio es muy escasa, y está compuesta por Steve "el Pirata", un hombre que se cree pirata; Justin Redman, un chico escuálido que sueña con impresionar a una animadora que está a años luz de sus posibilidades; Gordon Pibb, un hombre obeso aficionado a los deportes más raros; Owen, un joven sin muchas luces; y Dwight Baumgarten, un engreído sabiondo que en realidad no tiene ni idea de nada. Al humilde gimnasio de Peter, le echa el ojo White Goodman (Ben Stiller), estrella del mundo de los deportes y egocéntrico propietario del Globo Gym, el resplandeciente templo del fitness.', trailer_url = 'https://www.youtube.com/watch?v=rZfmbdpVLAA' WHERE id_api = 'tt0364725';

