UPDATE Contenido SET id_tmdb = 9515, descripcion = 'Julian Noble (Pierce Brosnan) es un asesino a sueldo que vive una profunda crisis existencial. Estando en Ciudad de México para cumplir un encargo conoce a Danny Wright, que se encuentra allí para resolver un negocio. Danny vive en Denver con su esposa Bean y, aunque tengan algunos problemas económicos, parecen felices después de diez años de matrimonio. Lo que Danny se propone es conseguir un importante contrato: si consigue que acepten su proyecto podrá resolver todos sus problemas financieros, si, por el contrario, lo rechazan se verá condenado a vivir en una situación muy precaria. Julian y Danny caen pronto en la cuenta de que, pese a que no tienen nada en común, se necesitan mutuamente.', trailer_url = 'https://www.youtube.com/watch?v=k3qUl2i9lVA' WHERE id_api = 'tt0365485';

UPDATE Contenido SET id_tmdb = 747, descripcion = 'La vida de Shaun es un callejón sin salida. Se pasa la vida en la taberna local con su amigo íntimo Ed, discute con su madre y descuida a su novia, Liz. Cuando Liz le deja plantado. Shaun decide, finalmente, poner su vida en orden. Tiene que reconquistar el corazón de su novia, enmendar sus relaciones con su madre y enfrentarse a las responsabilidades de un adulto.', trailer_url = 'https://www.youtube.com/watch?v=12Ok6bbV7rQ' WHERE id_api = 'tt0365748';

UPDATE Contenido SET id_tmdb = 2179, descripcion = 'En 1994 tuvieron lugar en Los Ángeles dos acontecimientos que sacudieron la tierra: el terremoto de Northridge y el nacimiento de Tenacious D, la banda liderada por Jack Black y Kyle Gass. Los dos se conocieron cuando eran miembros de la Actor’s Gang, una compañía de teatro de Los Ángeles fundada por Tim Robbins, y allí fue donde ambos descubrieron su amor por el rock and roll. Desde su primera actuación en el Al’s Bar de Los Ángeles, donde interpretaron su única canción, Tribute, hasta su revelación como la autoproclamada Mejor Banda de la Tierra, The D, como los conocen sus seguidores, han encantado a todo el que podido escucharlos. Aunque Black y Gass describen Tenacious D in The Pick of Destiny como una autobiografía, se han tomado ciertas libertades, pero claro, ¿por qué no iban a hacerlo? al fin y al cabo se trata de The D, los trovadores más irreverentes dentro de los reverentes.', trailer_url = 'https://www.youtube.com/watch?v=vz6BkxJFZ5o' WHERE id_api = 'tt0365830';

