UPDATE Contenido SET id_tmdb = 10707, descripcion = 'Park Slope, Brooklyn, 1986. Cuando Walt Berkman, un influenciable chico de 16 años, finge que es suya la canción de Pink Floyd "Hey You" y la canta en un acto del instituto, tenía muy claros sus motivos. "Sentía que podía haberla escrito yo, así que el hecho de que ya estuviera escrita no dejaba de ser un mero tecnicismo." Al mismo tiempo, su hermano Frank, de doce años, bebe cerveza y habla sin pudor de la vida sexual de su madre. Ambos simplemente reaccionan ante la bomba que ha estallado en el seno de su apacible vida familiar: sus padres, Bernard –otrora un prometedor escritor y ahora un profesor de mediana edad- y Joan –una prometedora escritora que va a publicar un libro- anuncian que se separan. Los cimientos familiares se tambalean. Walt y Frank se enfrentan a lo que es repartirse los fines de semana y al desbarajuste de pasar una noche con uno y otra noche con otro.', trailer_url = 'https://www.youtube.com/watch?v=EpbkJaVs3F8' WHERE id_api = 'tt0367089';

UPDATE Contenido SET id_tmdb = 9667, descripcion = 'Tras recuperarse de una herida de bala en la cabeza, el veterano de la Guerra del Golfo Jack Starks regresa a su Vermont natal padeciendo amnesia. Cuando le acusan del asesinato de un policía y le envían a un psiquiátrico, el Dr. Becker le somete a un tratamiento controvertido. Le inyectan drogas experimentales, le colocan una chaqueta de fuerza y le encierran durante horas en un depósito de cadáveres de la morgue. Drogado y desorientado, la mente de Starks le lanza hacia el futuro, donde conoce a Jackie y descubrirán que está destinado a morir en cuatro días. Juntos buscarán la forma de salvarle de su destino.', trailer_url = 'https://www.youtube.com/watch?v=HfKjVvyONoM' WHERE id_api = 'tt0366627';

