UPDATE Contenido SET id_tmdb = 10589, descripcion = 'Max Burdett (Pierce Brosnan) es un ladrón retirado que vive tranquilamente en una isla paradisíaca. Todo cambiará cuando un antiguo agente del FBI conocido suyo, le diga que hay rumores de que va a volver a su antiguo trabajo robando un gran diamante, lo que acabará complicándole su pacífica vida.', trailer_url = 'https://www.youtube.com/watch?v=ZLOwRK2rKJY' WHERE id_api = 'tt0367479';

UPDATE Contenido SET id_tmdb = 118, descripcion = 'Charlie Bucket (Freddie Highmore), un niño muy bueno de una familia muy pobre, gana un concurso, junto a otros cuatro niños de diferentes partes del mundo, para disfrutar de una visita durante todo un día a la gigantesca fábrica de chocolate dirigida por el excéntrico Willy Wonka (Johnny Depp) y su equipo de Oompa-Loompas. La fábrica se parece a un mundo fantástico y mágico lleno de diferentes sabores, todos muy dulces.', trailer_url = 'https://www.youtube.com/watch?v=p6JAQ2aoXm0' WHERE id_api = 'tt0367594';

UPDATE Contenido SET id_tmdb = 11453, descripcion = 'Deuce (Rob Schneider), un limpiador de peceras ingenuo y de buen corazón, creía que su carrera de gigoló había terminado. Pero cuando se veía lejos de todo aquello, es tentado a regresar a su increíble profesión de ''placer pagado''. Hicks (Eddie Griffin), su antiguo proxeneta, se ve implicado en los asesinatos de los gigolós más prestigiosos de Europa. Deuce se ve obligado a regresar como espía de incógnito para limpiar el nombre de su gran amigo. Para conseguir sus propósitos, éste debe competir con la poderosa Unidad Europea de Prostitutos e incluso exponerse a otra serie de estrafalarias clientes. Entre todos estos líos, conoce a la hermosa Eva (Hanna Verboom), que sufre de un desorden crónico obsesivo-compulsivo y a su vez es extremadamente talentosa.', trailer_url = 'https://www.youtube.com/watch?v=NlsISs23Qfs' WHERE id_api = 'tt0367652';

