UPDATE Contenido SET id_tmdb = 6947, descripcion = 'Los vecinos de una pequeña población rural de Pennsylvania viven atemorizados por culpa de unos extraños seres que habitan en los bosques circundantes. Saben perfectamente que para salvarse deben cumplir escrupulosamente ciertas reglas: evitar que vean el color rojo porque los atrae, mantenerse alejados del bosque, donde esperan agazapados la llegada de alguien, y obedecer la campana de alerta, que indica que se acercan a la aldea.', trailer_url = 'https://www.youtube.com/watch?v=TpyU0hOqJUI' WHERE id_api = 'tt0368447';

UPDATE Contenido SET id_tmdb = 9621, descripcion = 'Horas depués de su calamitoso debut como diseñador industrial, Drew Baylor se entera de la repentina muerte de su padre y viaja a Elizabethtown, en Kentucky, para asistir al funeral. Durante el vuelo, conoce a Claire, una azafata que le ayudará a superar los momentos difíciles que le esperan y que le demostrará que las cosas más asombrosas suceden cuando uno menos lo espera.', trailer_url = 'https://www.youtube.com/watch?v=yw9wv7YDd-4' WHERE id_api = 'tt0368709';

UPDATE Contenido SET id_tmdb = 11130, descripcion = 'Mia (Anne Hathaway) ya está preparada para ser princesa de Genovia. Sin embargo, nada más instalarse en el Palacio Real con su bella y sabia abuela, la Reina Clarisse (Julie Andrews), se entera de que tendrá que prepararse inmediatamente para ser reina. Pero, entonces, tendrá que afrontar un peliagudo problema: en Genovia hay una ley que establece que las princesas tienen que casarse antes de ser coronadas; así que Mia tendrá que soportar un desfile de pretendientes cuya única aspiración es ocupar el trono.', trailer_url = 'https://www.youtube.com/watch?v=noajhlyKW8s' WHERE id_api = 'tt0368933';

UPDATE Contenido SET id_tmdb = 2059, descripcion = 'Benjamin Franklin Gates (Nicolas Cage) ha dedicado su vida a buscar el legendario tesoro de los Caballeros Templarios, del que se decía que estaba escondido en algún lugar de Estados Unidos. Durante siete generaciones, la familia Gates, siguiendo las pistas que dejaron los ''Padres Fundadores'' de Estados Unidos, recorrieron el país en busca del tesoro. Cuando, por fin, Ben descubre la pista definitiva: un mapa oculto en el reverso de la Declaración de Independencia, la noticia llega a oídos de su rival Ian Howe (Sean Bean). Para impedir que el documento caiga en manos de alguien tan peligroso, Gates cuenta con la ayuda de su compañero de aventuras Riley (Justin Bartha), un genio de la tecnología, y de Abigail Chase (Diane Kruger), la atractiva conservadora de los Archivos Nacionales.', trailer_url = 'https://www.youtube.com/watch?v=sDrCKTCfEiI' WHERE id_api = 'tt0368891';

UPDATE Contenido SET id_tmdb = 3902, descripcion = 'Retrato del legendario músico Bob Dylan. Seis intérpretes encarnan diferentes momentos de la vida personal y profesional del cantante norteamericano que revolucionó la música popular en los años 60 y 70. Desde entonces, su influencia sobre músicos, escritores, poetas y sobre la cultura en general ha sido permanente. El filme consta de varias historias cuyos protagonistas son de lo más heterogéneo: Woody (Marcus Carl Franklin) es un niño negro de once años que siempre está huyendo. Robbie (Heath Ledger), un artista mujeriego que vive en la carretera. Jude (Cate Blanchett), un joven andrógino, es estrella del rock. John (Christian Bale), un ídolo folk que se convierte en evangelista. Y Billy (Richard Gere) es un famoso fugitivo.', trailer_url = 'https://www.youtube.com/watch?v=abVh39ZmUag' WHERE id_api = 'tt0368794';

UPDATE Contenido SET id_tmdb = 9316, descripcion = 'Ong Bak es una estatua legendaria de Buda que se halla en el templo de Nong Para-du, en la Tailandia rural. Los aldeanos creen que los poderes mágicos de Ong Bak les protegen de todo mal. Un despiadado gánster roba la cabeza del buda dejando al pueblo totalmente desprotegido. Sus habitantes buscarán a un guerrero para recuperar el buda y enfrentarse a la banda de gánsters, encontrando a Ting, un huérfano criado en el templo, y alumno de Pra Kru, un amable monje, experto en el ancestral arte del Muay Thai: “Las Nueve Armas Corporales".', trailer_url = 'https://www.youtube.com/watch?v=b0ce8X8v2ro' WHERE id_api = 'tt0368909';

UPDATE Contenido SET id_tmdb = 269, descripcion = 'Los protagonistas son dos adolescentes con vidas paralelas, aunque muy diferentes, que viven en un pueblo de Carolina del Norte. Los une un oscuro secreto: son hijos del mismo padre. Después de crecer en ambientes muy distintos, de repente, sus vidas se cruzan.', trailer_url = 'https://www.youtube.com/watch?v=GIFbz7uTOKI' WHERE id_api = 'tt0368530';

