UPDATE Contenido SET id_tmdb = 1726, descripcion = 'El multimillonario fabricante de armas Tony Stark debe enfrentarse a su turbio pasado después de sufrir un accidente con una de sus armas. Equipado con una armadura de última generación tecnológica, se convierte en ''El hombre de hierro'' para combatir el mal a escala global.', trailer_url = 'https://www.youtube.com/watch?v=Rxxfxhuob04' WHERE id_api = 'tt0371746';

UPDATE Contenido SET id_tmdb = 11638, descripcion = 'Percy Jones (Bernie Mac) se vanagloria, muy seguro de sí mismo, de que siempre tiene razón, especialmente cuando se trata del bienestar de su familia. Cuando su hija Theresa (Zoe Saldaña) le trae a casa a su nuevo novio, Simon Green (Ashton Kutcher), para que lo conozcan tanto él como su mujer Marilyn (Judith Scott), desconoce que Simon ha pedido a Theresa que se case con ella y planea anunciar el compromiso en la fiesta de celebración de las bodas de plata de Percy y Marilyn. El joven, un exitoso corredor de bolsa, ciertamente parece bueno sobre el papel, y por primera vez, Percy está deseando realmente conocer a uno de los novios de su hija.', trailer_url = 'https://www.youtube.com/watch?v=2Nef33uJ_VA' WHERE id_api = 'tt0372237';

UPDATE Contenido SET id_tmdb = 6961, descripcion = 'Kat Ellis, una soltera de Nueva York, tiene ante sí una celebración poco "agradable" en Londres: la inminente boda de su hermana con su exprometido como padrino de la ceremonia. Temerosa de presentarse sin pareja en el evento, decide contratar los servicios de un apuesto acompañante masculino y presentarle como su novio.', trailer_url = 'https://www.youtube.com/watch?v=DS1bOLtMNfc' WHERE id_api = 'tt0372532';

UPDATE Contenido SET id_tmdb = 3989, descripcion = 'Cuando el gobernante norcoreano Kim Jong-il orquesta un complot terrorista global, le corresponde a la unidad altamente especializada y fuertemente armada del Equipo América detener su cobarde plan. El grupo, que ha reclutado al problemático actor de Broadway Gary Johnston, no sólo tiene que enfrentarse a Jong-il, sino que también debe enfrentarse al Film Actors Guild, un grupo de liberales de Hollywood en desacuerdo con las tácticas de "vigilancia del mundo" del Equipo América. .', trailer_url = 'https://www.youtube.com/watch?v=kMyJWuvW_9k' WHERE id_api = 'tt0372588';

UPDATE Contenido SET id_tmdb = 5528, descripcion = 'En 1948 Clément Mathieu, profesor de música desempleado, acepta un puesto como profesor vigilante en un internado de reeducación de menores. El sistema represivo aplicado por el director conmociona a Mathieu. Enseñándoles música y canto coral a estos niños tan difíciles, Mathieu transformará sus vidas cotidianas.', trailer_url = 'https://www.youtube.com/watch?v=opKz8dXXOV4' WHERE id_api = 'tt0372824';

UPDATE Contenido SET id_tmdb = 272, descripcion = '¿Cómo cambia un hombre el mundo? Es una pregunta que obsesiona a Bruce Wayne al igual que el fantasma de sus padres, muertos a tiros ante sus ojos en las calles de Gotham una noche que cambió su vida para siempre. Atormentado por la culpa y la ira, el desilusionado heredero industrial desaparece de Gotham y viaja en secreto por el mundo, buscando los medios de luchar contra la injusticia y utilizar el miedo contra los que se aprovechan de los que tienen miedo. Con la ayuda de su leal mayordomo Alfred, el detective Jim Gordon - uno de los pocos buenos policías de las fuerzas del orden público de Gotham - y Lucius Fox, su aliado en la división de Ciencias Aplicadas de Wayne Enterprises, Bruce Wayne libera a su imponente alter ego: Batman, un justiciero enmascarado que utiliza la fuerza, la inteligencia y un despliegue de artefactos de alta tecnología para combatir las fuerzas siniestras que amenazan con destruir la ciudad.', trailer_url = 'https://www.youtube.com/watch?v=lirBhHXvDSg' WHERE id_api = 'tt0372784';

UPDATE Contenido SET id_tmdb = 88751, descripcion = 'Durante una expedición científica en Islandia, el visionario científico Trevor Anderson (Brendan Fraser), su sobrino Sean (Josh Hutcherson) y su hermosa guía regional, Hannah (Anita Briem), quedan atrapados en una cueva. La única posibilidad de escapar de allí es adentrándose en las entrañas de la Tierra. Recorriendo mundos jamás vistos, el trío se encuentra cara a cara con criaturas increíbles. Pero la actividad volcánica del lugar es cada vez más intensa, por lo que deberán encontrar urgentemente una manera de poder volver a la superficie antes de que sea demasiado tarde.', trailer_url = 'https://www.youtube.com/watch?v=ytDcArTr0CI' WHERE id_api = 'tt0373051';

UPDATE Contenido SET id_tmdb = 9470, descripcion = 'Ambientada en el caos de la China prerrevolucionaria, un ladrón de poca monta, Sing (Ste-phen Chow), aspira a ser uno de los crueles y sofisticados miembros de la Banda del Hacha cuyas actividades ilegales ensombrecen la ciudad. Sing intenta extorsionar a uno de los habitantes de un complejo de apartamentos llamado ''Pig Sty Alley'', pero los vecinos no son lo que parecen. Sin pretenderlo, los cómicos intentos de intimidación de Sing atraen a la Banda del Hacha, desencadenando una serie de sucesos que enfrentan cara a cara los dos mundos tan diferentes. Mientras los habitantes de Pig Sty luchan por sus vidas, el choque de titanes de kung fu que sigue desentierra algunos maestros legendarios de artes marciales.', trailer_url = 'https://www.youtube.com/watch?v=zHq3Op49ZYI' WHERE id_api = 'tt0373074';

UPDATE Contenido SET id_tmdb = 2082, descripcion = 'Después de estar recluido durante 17 años en una institución mental, Michael Myers, convertido ya en un hombre adulto y muy peligroso, logra escaparse y regresa a Haddonfield para buscar a su hermana. Todo aquel que se cruce en su camino corre un peligro mortal.', trailer_url = 'https://www.youtube.com/watch?v=W0BucFiI5CY' WHERE id_api = 'tt0373883';

UPDATE Contenido SET id_tmdb = 675, descripcion = 'Harry Potter regresa por quinto año a Hogwarts aún sacudido por la tragedia ocurrida en el Torneo de los Tres Magos. Debido a que el Ministro de la Magia niega el regreso de Lord Voldemort, Harry se convierte en el centro de atención de la comunidad mágica. Mientras lucha con sus problemas en el colegio, incluyendo a la nueva profesora Dolores Umbridge, intentará aprender más sobre la misteriosa Orden del Fénix.', trailer_url = 'https://www.youtube.com/watch?v=zqMjQXcpacg' WHERE id_api = 'tt0373889';

UPDATE Contenido SET id_tmdb = 5236, descripcion = 'Harry Lockhart es en esencia un tipo decente. Es cierto que es un ladrón de poca monta, pero quiere hacer lo correcto. La eterna mala suerte de Harry empieza a mejorar cuando él y su socio están haciendo algunas "compras" navideñas fuera de horas en una tienda de juguetes de Nueva York y la alarma de seguridad acaba con la fiesta. En su frenética huída de la policía, Harry se ve metido sin querer en una audición para una película de detectives de Hollywood y, en un abrir y cerrar de ojos, el productor lo lleva en avión a Los Angeles para hacerle una prueba.', trailer_url = 'https://www.youtube.com/watch?v=x7L-kF5Im1Y' WHERE id_api = 'tt0373469';

UPDATE Contenido SET id_tmdb = 83, descripcion = 'Basada en hechos reales, narra una historia ocurrida en Las Bahamas. Una pareja adicta al trabajo había decidido tomarse un tiempo de relax y pasar unos días buceando. La lancha que los lleva, debido a un descuido de la tripulación, los abandona en medio de un mar, a la deriva y lejos de la costa, en unas aguas infestadas de tiburones... Según la crítica americana, la película de terror más impactante exhibida en el Festival de Sundance desde "The Blair Witch Project", en 1999.', trailer_url = 'https://www.youtube.com/watch?v=PKnQHwtB7ZY' WHERE id_api = 'tt0374102';

