UPDATE Contenido SET id_tmdb = 113, descripcion = 'Dos monjes viven en un monasterio aislado. Bajo la atenta mirada del más viejo, el más joven ve pasar las estaciones de la vida. Primavera: un niño monje se ríe de una rana que intenta librarse de una piedra que tiene en la espalda. Verano: un monje adolescente conoce el amor. Otoño: un monje de treinta años intenta hacer algo que va contra su naturaleza. Invierno: el monje está próximo a la vejez y alguien llega al monaterio. Primavera: el viejo monje conversa con la naturaleza; cerca de él juega un niño monje', trailer_url = 'https://www.youtube.com/watch?v=3rIgudJbHek' WHERE id_api = 'tt0374546';

