UPDATE Contenido SET id_tmdb = 23514, descripcion = 'The Rum Diary cuenta la historia cada vez más desquiciada de los viajes del periodista Paul Kemp (Johnny Depp). Cansado del ruido y la locura de Nueva York a finales de la época Eisenhower en los Estados Unidos, Kemp decide viajar a la isla virgen de Puerto Rico para escribir en un periódico local de San Juan. El cual está dirigido por Lotterman, un escritor que hace años también recorrió un camino similar. Adoptando el estilo de vida empapado en ron en la versión de los años cincuenta de Hemingway. Pronto llegará el amor a la vida de Paul, iniciando una relación con una atractiva mujer estadounidense, Chnault (Amber Heard). Aunque ella tiene una relación con un hombre de negocios involucrado en oscuras especulaciones urbanísticas locales.', trailer_url = 'https://www.youtube.com/watch?v=hssJQPZmBJo' WHERE id_api = 'tt0376136';

