UPDATE Contenido SET id_tmdb = 11190, descripcion = 'La vida de dos hermanos sufre un brusco cambio cuando de repente aparece su padre, al que sólo recordaban por una vieja fotografía. ¿Es realmente su padre? ¿Por qué ha vuelto después de tanto tiempo? Los chicos encontrarán la respuesta a sus preguntas en una remota y solitaria isla, después de un emocionante viaje con su padre por los bellos parajes de Siberia. Ópera prima del realizador ruso Andrey Zvyagintsev, nacido en 1964, autor de varios filmes para la televisión rusa. León de Oro en Venecia, donde fue calificada por la crítica como "un film sobre el amor, la pérdida de los afectos y el ingreso en la edad adulta, de irresistible fuerza emocional."', trailer_url = 'https://www.youtube.com/watch?v=kZ0nv2MVoYk' WHERE id_api = 'tt0376968';

UPDATE Contenido SET id_tmdb = 1466, descripcion = '"Joey" es un serie derivada de la mítica serie de televisión "Friends" basado en el personaje de Joey Tribbiani interpretado por Matt LeBlanc. Trata sobre la vida en Los Ángeles de Joey, junto a su sobrino y una de sus hermanas.', trailer_url = 'https://www.youtube.com/watch?v=1IVku9VbHqc' WHERE id_api = 'tt0375355';

UPDATE Contenido SET id_tmdb = 4836, descripcion = 'Elegante y cortés, nuestro anónimo héroe (Daniel Craig) es un traficante respetado, todo un profesional. Trabajando con la cocaína y con el éxtasis con la mayor naturalidad, como si de cualquier otro material se tratase, ha conseguido hacerse con una buena fortuna. Habiendo tomado la decisión de retirarse, su objetivo es salir del mundo del crimen, la droga y la violencia, y llevar una vida sencilla. Pero antes de que esto suceda, el jefe del crimen Jimmy Price (Kenneth Cranham) quiere que le haga dos favores. El primero es que debe encontrar a la hija desaparecida de un poderoso criminal, Eddie Temple (Michael Gambon). En segundo lugar, debe negociar la venta de un importante envío de éxtasis con Duke (Jamie Foreman). Lo que debería ser simple rutina acaba complicándose y nada sale según el plan. En vez de eso, la mentira y las alianzas ocultas se convierten en el orden del día.', trailer_url = 'https://www.youtube.com/watch?v=QtrbWfZtxxM' WHERE id_api = 'tt0375912';

UPDATE Contenido SET id_tmdb = 36668, descripcion = 'En X-Men: La decisión final, el último capítulo de la trilogía cinematográfica de los "X-Men", hay una "cura" para los mutantes que amenaza con alterar el curso de la historia. Por primera vez, los mutantes pueden elegir: seguir con su singularidad, aunque eso les aísle y les separe, o renunciar a sus poderes y convertirse en seres humanos normales. Los opuestos puntos de vista de los líderes mutantes, Charles Xavier, que aboga por la tolerancia, y Magneto, que cree en la supervivencia de los más aptos, se ven sometidos a la prueba definitiva: desencadenar la guerra que pondrá fin a todas las guerras...', trailer_url = 'https://www.youtube.com/watch?v=X8ozc_dQprk' WHERE id_api = 'tt0376994';

UPDATE Contenido SET id_tmdb = 10625, descripcion = 'Una joven adolescente, Cady, acostumbrada a vivir en África con sus padres, zoólogos, se encuentra una nueva jungla cuando se muda a Illinois. Allí acude a la escuela pública, donde se enamorará del ex-novio de la chica más popular del colegio. Las chicas comenzarán a hacer la vida imposible a Cady, y ésta no tendrá otro remedio que usar sus mismas tácticas para mantenerse a flote.', trailer_url = 'https://www.youtube.com/watch?v=i56p4yA70Qs' WHERE id_api = 'tt0377092';

UPDATE Contenido SET id_tmdb = 11866, descripcion = '1 Accidente. 10 Supervivientes. A 3.000 millas de la civilización. Un grupo de supervivientes de un accidente de aviación se encuentra perdido en medio del desierto del Gobi sin ninguna posibilidad de ser rescatados. Su única esperanza es lograr lo "imposible": construir un nuevo aparato con los restos del avión accidentado para salir del desierto. Todo empezéo cuando el piloto del avión de carga Frank Towns y su copiloto AJ son enviados a Tan sag Basin, en Mongolia, para evacuar a la plantilla de una operación de exploración de hidrocarburos que se ha cancelado. Ambos no tienen ni idea de que esta misión rutinaria se va a convertir en una lucha a vida o muerte, haciendo cambiar por completo todos sus planteamientos de vida.', trailer_url = 'https://www.youtube.com/watch?v=bANHr1Qc-7k' WHERE id_api = 'tt0377062';

UPDATE Contenido SET id_tmdb = 9777, descripcion = 'Catherine es una joven que se ha pasado años cuidando a su brillante pero desequilibrado padre, un genio de las matemáticas. La víspera de su cumpleaños no sólo tendrá que soportar la llegada de su hermana Claire, con la que apenas tiene relación, sino que también tendrá que atender a Hal, un antiguo alumno de su padre que espera encontrar datos de gran importancia en los 103 cuadernos del maestro. Al mismo tiempo que va cuajando una relación amistosa con Hal, Catherine tendrá que enfrentarse a los estrictos planes que Claire ha concebido para ella. Pero lo que verdaderamente le preocupa y obsesiona es el temor a heredar la locura – o quizá la genialidad – de su padre.', trailer_url = 'https://www.youtube.com/watch?v=kpOBgoyzLhw' WHERE id_api = 'tt0377107';

UPDATE Contenido SET id_tmdb = 10320, descripcion = 'Seis meses después de los incidentes relacionados con una cinta de vídeo donde se aprecia la muerte de una joven a manos de sus padres, Rachel Keller decide mudarse con su hijo de Seattle a un lugar donde puedan sentirse más seguros y empezar una nueva vida. La cinta de vídeo un tanto siniestra que acabó misteriosamente con la vida de un niño no deja de preocupar a Rachel, que decide emprender una investigación sobre todos aquellos que desaparecieron y saber qué tipo de maldición esconde la cinta.', trailer_url = 'https://www.youtube.com/watch?v=apyfeNwsTu4' WHERE id_api = 'tt0377109';

UPDATE Contenido SET id_tmdb = 4551, descripcion = 'Chili Palmer (John Travolta), un taimado gángster, se dedica al negocio de la música, en el que tiene que vérselas con mafiosos rusos y raperos. Su protegida es Linda Moon, una joven cantante con talento. Desde el estudio de grabación hasta un concierto de Aerosmith, se las arregla para conseguir lo que quiere sirviéndose de su peculiar astucia callejera y habilidad negociadora.', trailer_url = 'https://www.youtube.com/watch?v=Cx4ZswI5Lno' WHERE id_api = 'tt0377471';

UPDATE Contenido SET id_tmdb = 393, descripcion = 'Tras eliminar a algunos de los miembros de la banda que intentó asesinarla el día de su boda, "Mamba Negra" prosigue su venganza e intenta acabar con el resto de la banda, en especial con su antiguo jefe, Bill, que la dio por muerta dejándola en coma.', trailer_url = 'https://www.youtube.com/watch?v=q2h6EFk36kI' WHERE id_api = 'tt0378194';

UPDATE Contenido SET id_tmdb = 45772, descripcion = 'La obra de Shakespeare experimenta una transformación disparatada: la gran historia de amor es protagonizada por enanos de jardín. Gnomeo y Juliet, al igual que sus cuasi homónimos, tienen que superar un sinfín de obstáculos, pero en este caso no se deben al odio que enfrenta a sus familias, sino a una disputa entre vecinos. ¿Podrá este pareja vivir feliz para siempre entre flamencos rosas de plástico y demenciales carreras de cortadoras de césped?. Los dos enanos intentarán que su destino fatal no se cumpla. Lucharán para que su historia de amor tenga un final feliz. Cuenta con canciones clásicas y también originales de Elton John.', trailer_url = 'https://www.youtube.com/watch?v=y85NeNJIva4' WHERE id_api = 'tt0377981';

UPDATE Contenido SET id_tmdb = 6519, descripcion = 'Basada en una popular serie norteamericana de mismo título emitida en los años 1979-1985. La historia relata las aventuras de los primos Bo y Luke Duke, quienes con las ayuda de su prima Daisy y el tío Jesse, intentan salvar la granja familiar de ser destruida por el malvado sheriff Hogg.', trailer_url = 'https://www.youtube.com/watch?v=lJzWkSmeMaY' WHERE id_api = 'tt0377818';

UPDATE Contenido SET id_tmdb = 11968, descripcion = 'Cuando cuatro buceadores descubren lo que podría ser un legendario y valiosísimo pecio, y creen que su sueño de hallar un tesoro escondido se ha hecho realidad. Pero en el fondo del océano, se encuentran con otro misterio más siniestro. Deciden entonces hacer un pacto para mantener en secreto ambos hallazgos.', trailer_url = 'https://www.youtube.com/watch?v=5uMDUHdN24o' WHERE id_api = 'tt0378109';

UPDATE Contenido SET id_tmdb = 7980, descripcion = 'La historia gira en torno a Susie Salmon, que fue asesinada cuando tenía tan sólo 14 años en diciembre de 1973 cuando volvía del colegio a su casa. Tras su muerte, continúa pendiente de su familia terrenal (mientras su asesino sigue sin ser descubierto). Atrapada en un más allá luminoso, Susie descubre que tiene que decidirse entre su deseo de venganza y su anhelo por ver reponerse a los suyos y seguir su camino. Lo que comienza como un asesinato impresionante se transforma en un viaje misterioso y visualmente inventivo a través de los vínculos de la memoria, el amor, la esperanza y la intensa belleza de la vida en sí misma, con destino a un emocionante y sorprendente momento de la verdad.', trailer_url = 'https://www.youtube.com/watch?v=Gs6veqUml6M' WHERE id_api = 'tt0380510';

UPDATE Contenido SET id_tmdb = 883, descripcion = 'En 1993, un corto de Jim Jarmusch titulado "Coffee and Cigarettes" recibió la Palma de Oro del Festival de Cannes. Once años depués Jarmusch rueda "Coffee and Cigarettes", un conjunto de episodios cortos. Cada secuencia muestra a diversos personajes sentados a una mesa, tomando café, fumando cigarrillos y discutiendo sobre temas tan diversos como la preparación del té inglés, las teorías sobre la conspiración contra Elvis Presley, Abbot & Costello, la ficticia banda de rock SQÜRL, París en los años veinte o el uso de la nicotina como insecticida...', trailer_url = 'https://www.youtube.com/watch?v=mM6Mpn0-eyQ' WHERE id_api = 'tt0379217';

UPDATE Contenido SET id_tmdb = 398, descripcion = 'Capote es una película sobre escritor Truman Capote y la investigación que tuvo que realizar para escribir "A sangre fría", un libro basado en hechos reales. Philip Seymour Hoffman ganó un Oscar al mejor actor por su interpretación de Truman Capote.', trailer_url = 'https://www.youtube.com/watch?v=BoRX7e5_nO0' WHERE id_api = 'tt0379725';

UPDATE Contenido SET id_tmdb = 16320, descripcion = 'Siglo XXVI. Tras ganar la guerra Civil Galáctica, las dos grandes potencias mundiales, EE.UU. y China, se unen para formar un gobierno totalitario llamado Alianza Universal. El Capitán Malcolm Reynolds es un curtido veterano de la guerra que se gana la vida alquilando su nave, la Serenity y buscando trabajos al margen de la ley. Su única familia es una pequeña y leal tripulación de disidentes y rebeldes. Cuando Malcom embarca a dos nuevos pasajeros, un médico y su inestable hermana, que está dotada de poderes telepáticos, enseguida descubre que ambos son fugitivos de la Alianza y que ésta no se detendrá hasta dar con la chica. Y, en efecto, la tripulación de la Serenity se verá atrapada entre el poderoso ejército de la Alianza y los Ravers, salvajes bárbaros que vagan por los confines del espacio. Así las cosas, empiezan a darse cuenta de que quizá el mayor peligro se encuentra a bordo de la Serenity.', trailer_url = 'https://www.youtube.com/watch?v=zybHB2V27G8' WHERE id_api = 'tt0379786';

UPDATE Contenido SET id_tmdb = 9763, descripcion = 'Como millones de niños de todo el mundo, Santiago tiene el sueño de ser un jugador de fútbol profesional. Sin embargo, viviendo en una barriada de Los Angeles, piensa que es un sueño difícil de cumplirse. Cuando el pequeño Santiago Munez (Kuno Becker) cruza la frontera de México y se traslada a América con su familia, sólo tiene dos posesiones: su balón de fútbol y una foto de la Copa del Mundo hecha jirones.', trailer_url = 'https://www.youtube.com/watch?v=--qOSiMyD84' WHERE id_api = 'tt0380389';

UPDATE Contenido SET id_tmdb = 36557, descripcion = 'La primera misión del agente británico James Bond como agente 007 lo lleva hasta Le Chiffre, banquero de los terroristas de todo el mundo. Para detenerlo y desmantelar la red terrorista, Bond debe derrotarlo en una arriesgada partida de póquer en el Casino Royale. Al principio a Bond le disgusta Vesper Lynd, la hermosa oficial del Tesoro que debe vigilar el dinero del gobierno. Pero, a medida que Bond y Vesper se ven obligados a defenderse juntos de los mortales ataques de Le Chiffre y sus secuaces, nace entre ellos una atracción mutua.', trailer_url = 'https://www.youtube.com/watch?v=Y6-Jmc4tTk4' WHERE id_api = 'tt0381061';

UPDATE Contenido SET id_tmdb = 80, descripcion = 'Jesse y Celine se conocieron en un tren y pasaron juntos una noche inolvidable paseando por Viena. Aunque prometieron encontrarse de nuevo seis meses más tarde, esa cita nunca llegó a producirse. Diez años después, se vuelven a ver casualmente, pero esta vez en París. Jesse, que está de gira promocionando una novela, la ve entre la gente en una librería. Ella vive desde hace tiempo en París; él, en Nueva York. Jesse inmediatamente decide dejarlo todo para pasar el tiempo con Celine. Así pasan el día en los cafés, en los parques, recordando aquella tarde en la capital austriaca y hablando de sus vidas.', trailer_url = 'https://www.youtube.com/watch?v=X57WUfsRcio' WHERE id_api = 'tt0381681';

UPDATE Contenido SET id_tmdb = 12153, descripcion = 'Dos ambiciosos -pero con poca fortuna- agentes del FBI (Shawn y Marlon Wayans) se hacen pasar por mujeres, novatas en la alta sociedad, en el exclusivo complejo Hamptons para investigar un círculo de secuestros. Pero mientras preparan su actuación en el mayor acontecimiento social del año se encuentran que irrumpir en la alta sociedad es mucho más duro de lo que parecía.', trailer_url = 'https://www.youtube.com/watch?v=UxER50XHW-I' WHERE id_api = 'tt0381707';

UPDATE Contenido SET id_tmdb = 591, descripcion = 'El catedrático y afamado simbologista Robert Langdon se ve obligado a acudir una noche al Museo del Louvre, cuando el asesinato de un restaurador deja tras de sí un misterioso rastro de símbolos y pistas. Con la ayuda de la criptógrafa de la policía Sophie Neveu y poniendo en juego su propia vida, Langdon descubre que la obra de Leonardo Da Vinci esconde una serie de misterios que apuntan a una sociedad secreta encargada de custodiar un antiguo secreto que ha permanecido oculto durante dos mil años...', trailer_url = 'https://www.youtube.com/watch?v=xpBaUqYbEB8' WHERE id_api = 'tt0382625';

UPDATE Contenido SET id_tmdb = 5176, descripcion = 'Remake del film de 1957 "El Tren de las 3:10", de Delmer Daves. Dan Evans es un típico ranchero de un pueblo de Arizona y veterano de la Guerra de Secesión que, para aliviar sus penurias económicas, decide escoltar al peligroso forajido Ben Wade mientras llega el tren que tiene que llevarlo ante la justicia. Pero no todo saldrá bien y la violencia no tardará en aparecer: durante ese tiempo se inicia una dramática lucha psicológica entre ambos hombres mientras las compañeros del forajido intentan liberarle.', trailer_url = 'https://www.youtube.com/watch?v=xwQj6nw6z40' WHERE id_api = 'tt0381849';

UPDATE Contenido SET id_tmdb = 11096, descripcion = 'Para ayudar a su pequeña hija de nueve años (Dakota Fanning) a recuperarse del golpe que significó el suicidio de su madre, un psicoanalista neoyorquino (Robert De Niro) deja la ciudad y se va a con la niña a vivir a una casa en el bosque. Lejos de ayudarla, el entorno parece alterar aún más a la pequeña, cuyas actitudes se vuelven cada vez más inquietantes. Ella comienza a hablar de un peligroso amigo imaginario llamado Charlie, que amenaza y aterroriza. Al principio el padre no se lo toma en serio.', trailer_url = 'https://www.youtube.com/watch?v=mgmjpk-mv2s' WHERE id_api = 'tt0382077';

UPDATE Contenido SET id_tmdb = 2062, descripcion = 'Remy es una simpática rata que sueña con convertirse en un gran chef francés a pesar de la oposición de su familia y del problema evidente que supone ser una rata en una profesión que detesta a los roedores. El destino lleva entonces a Remy a las alcantarillas de París, pero su situación no podría ser mejor, ya que se encuentra justo debajo de un restaurante que se ha hecho famoso gracias a Auguste Gusteau, una estrella de la cuisine. A pesar del peligro que representa ser un visitante poco común (y desde luego nada deseado) en los fogones de un exquisito restaurante francés, la pasión de Remy por la cocina pone patas arriba el mundo culinario parisino en una trepidante y emocionante aventura.', trailer_url = 'https://www.youtube.com/watch?v=b5ZNJoS2RtI' WHERE id_api = 'tt0382932';

UPDATE Contenido SET id_tmdb = 9009, descripcion = 'Dahlia Williams empieza una nueva vida. Acaba de separarse, tiene un nuevo trabajo y un nuevo apartamento y está decidida a pasar página en su matrimonio y dedicarse en cuerpo y alma a su hija Ceci de cinco años. Pero cuando su estresante separación se convierte en una batalla por la custodia de la niña, su ya frágil estado psicológico empieza a desmoronarse. Su nuevo apartamento -desvencijado, abarrotado y destruido- parece tomar vida propia. Ruidos misteriosos emanan del apartamento vacío del piso de arriba y hay una fuga de agua oscura permanente en el techo del dormitorio. Se deja llevar por la imaginación y es incapaz de distinguir entre fantasía y realidad. No tiene fuerzas para averiguar quién está detrás de unos diabólicos juegos mentales.', trailer_url = 'https://www.youtube.com/watch?v=t24DuU9TXRM' WHERE id_api = 'tt0382628';

UPDATE Contenido SET id_tmdb = 10048, descripcion = 'Un escuadrón de pilotos de élite se embarca en una peligrosa misión para intentar neutralizar un prototipo de avión de combate que está fuera de control y que dispone de un sistema de inteligencia artificial cuyas acciones podrían desencadenar una guerra nuclear.', trailer_url = 'https://www.youtube.com/watch?v=dJ8FNgRQFuA' WHERE id_api = 'tt0382992';

UPDATE Contenido SET id_tmdb = 4960, descripcion = 'Un director de teatro pelea con su trabajo y la mujer de su vida, en su intento de crear una réplica a tamaño natural de Nueva York dentro de un almacén como parte de su nueva obra.', trailer_url = 'https://www.youtube.com/watch?v=i2q8F0yRmrs' WHERE id_api = 'tt0383028';

UPDATE Contenido SET id_tmdb = 12096, descripcion = 'Cuando el entrenador de un equipo de fútbol es asesinado en un estadio, su valioso anillo con el diamante Pantera Rosa es robado. El ambicioso Director Dreyfus asignará el caso al torpe Clouseau para que lo resuelva, nombrándole al mismo tiempo inspector. Sin embargo, su verdadera intención es distraer a la prensa mientras trata de resolver el mismo el caso.', trailer_url = 'https://www.youtube.com/watch?v=er7sxi-ur1A' WHERE id_api = 'tt0383216';

UPDATE Contenido SET id_tmdb = 588, descripcion = 'Rose, desesperada por encontrar una cura para la misteriosa enfermedad de su hija Sharon, rehúsa ingresar a la niña en una institución psiquiátrica a pesar de las recomendaciones de los médicos, y decide huir a Silent Hill, un pueblo del que su hija habla constantemente en sueños. A pesar de que su marido Christopher se opone al viaje, Rose está convencida de que la respuesta se encuentra en este misterioso lugar. Al aproximarse al pueblo, una misteriosa figura se alza en medio de la carretera. Rose, para no atropellarla, tiene un accidente. Cuando vuelve en sí, Sharon ha desaparecido. A partir de ese momento, acompañada por una agente de policía, empieza una búsqueda desesperada en Silent Hill para encontrar a su hija. Las dos mujeres no tardan en darse cuenta de que el pueblo, que quedó desierto después de ser devastado por unos terribles incendios, no se parece a ningún otro.', trailer_url = 'https://www.youtube.com/watch?v=hy6nmlTESd8' WHERE id_api = 'tt0384537';

UPDATE Contenido SET id_tmdb = 9788, descripcion = 'Cuando un joven de un instituto descubre que ha sido rechazado por todas las universidades en las que pidió el ingreso, decide crear una universidad ficticia para engañar a sus exigentes padres. Pero cuando centenares de estudiantes empiezan a apuntarse a ésta, deberá poner en marcha el más fabuloso engaño para escolarizar a toda una legión de juerguistas e inadaptados...', trailer_url = 'https://www.youtube.com/watch?v=XOpEUXVGPDc' WHERE id_api = 'tt0384793';

UPDATE Contenido SET id_tmdb = 27275, descripcion = 'Un vendedor de alfombras turco es abducido por unos extraterrestres y transportado al planeta G.O.R.A., donde una especie de meteorito está a punto de destruir el planeta. Allí conocerá a unos extraños personajes, como un robot gay llamado 216 y un admirador de Bob Marley, que se hace llamar Bob Marley Faruk. Juntos intentaran escapar del sitio donde están prisioneros y rescatar a la princesa Ceku de ser casada con el malvado comandante Logar.', trailer_url = 'https://www.youtube.com/watch?v=EmCsr9g9q-o' WHERE id_api = 'tt0384116';

UPDATE Contenido SET id_tmdb = 1891, descripcion = 'Cuatro siglos después de la fundación de la República (509 a.C.), Roma es la ciudad más poderosa del mundo, una metrópoli cosmopolita de un millón de personas, el epicentro de un imperio en expansión. La República se basó en la separación de poderes y creó los mecanismos necesarios para evitar que un solo hombre acumulara demasiado poder. Sin embargo, con el paso del tiempo, la corrupción, el lujo y los excesos fueron carcomiendo esos principios.

La serie es una historia sobre la vida tanto de romanos ilustres como ordinarios, situada en los últimos días de la República Romana.', trailer_url = 'https://www.youtube.com/watch?v=WzoHtuaHshA' WHERE id_api = 'tt0384766';

UPDATE Contenido SET id_tmdb = 58, descripcion = 'Will Turner y Elizabeth Swann se van a casar, pero ambos son hechos prisioneros por Lord Cutler Beckett y acusados de haber liberado al capitán Jack Sparrow. Para salvar su vida, Will tendrá que encontrar a Jack y conseguir su misteriosa brújula. Esta esconde un gran poder, además de la clave de una deuda de sangre del pirata con un temible y siniestro Davy Jones, el legendario capitán del barco fantasma Holandés Errante.', trailer_url = 'https://www.youtube.com/watch?v=2GJh4ElbEjA' WHERE id_api = 'tt0383574';

UPDATE Contenido SET id_tmdb = 10065, descripcion = 'Basada en un suceso real. El 14 de Noviembre de 1974 en Long Island, Nueva York, la policía recibió una escalofriante llamada telefónica que les condujo a una espantosa escena de un crimen en una residencia en Amityville, Long Island. Una familia había sido asesinada en sus propias camas. En los siguientes días, Ronald Defeo confesó que él mismo había disparado a sus padres mientras dormían, culpando a unas voces que le decían que debía matarlos. Un año después, George y Kathy Lutz y sus tres hijos se mudan a la misma casa, creyendo que se trata del hogar de sus sueños. Pero poco después de haberse mudado, extrañas situaciones empiezan a suceder, mientras George comienza a ser atormentado por las voces que existen en la casa...', trailer_url = 'https://www.youtube.com/watch?v=c5Maq9H1lZ8' WHERE id_api = 'tt0384806';

UPDATE Contenido SET id_tmdb = 6963, descripcion = 'El protagonista (Nicolas Cage), un popular hombre del tiempo televisivo al que trasladan de Chicago a Nueva York, ve cómo su vida personal y familiar se desmorona', trailer_url = 'https://www.youtube.com/watch?v=qjweCcEa61o' WHERE id_api = 'tt0384680';

UPDATE Contenido SET id_tmdb = 9550, descripcion = 'Corre el año 859 a.C. y la dinastía Tang, una vez floreciente, ha entrado en decadencia. El malestar se extiende por todo el país, y el corrupto gobierno tiene que enfrentarse en todas partes con ejércitos rebeldes. El más poderoso es el de la "Casa de las Dagas Voladoras", que se está haciendo cada vez más fuerte gracias a un nuevo y misterioso líder. Dos capitanes, Leo y Jin, reciben la orden de capturarlo y para ello elaboran un minucioso plan. El capitán Jin finge ser un guerrero solitario llamado Viento y saca de prisión a la revolucionaria ciega Mei, que lo llevará hasta el cuartel general de la Casa de las Dagas Voladoras, pero durante el viaje, Jin y Mei se enamoran profundamente.', trailer_url = 'https://www.youtube.com/watch?v=PSYtzmbY2Pw' WHERE id_api = 'tt0385004';

UPDATE Contenido SET id_tmdb = 8923, descripcion = 'Después de ser expulsado injustamente de la Universidad de Harvard, el estadounidense Matt Buckner huye a la casa de su hermana en Inglaterra. Una vez allí, se hace amigo del encantador y peligroso cuñado de ella, Pete Dunham, y lo introduce en el inframundo del vandalismo del fútbol británico. Matt aprende a mantenerse firme a través de una amistad que se desarrolla en el contexto de este mundo secreto y, a menudo, violento. ''Green Street Hooligans'' es una historia de lealtad, confianza y las consecuencias a veces brutales de vivir cerca del límite.', trailer_url = 'https://www.youtube.com/watch?v=EAe-1Lv1KYU' WHERE id_api = 'tt0385002';

UPDATE Contenido SET id_tmdb = 1901, descripcion = 'Dan Foreman (Dennis Quaid) es un feliz padre de familia, tiene 51 años y es el Director de Publicidad de la Revista Sports America; la gente que le rodea le quiere y por lo general se puede decir que la vida no le va mal... Todo cambia cuando entra a formar parte de ella Carter Duryea (Topher Grace), un joven de 26 años, inexperto, divorciado y con un prometedor futuro profesional por delante. La tranquila vida de Dan se verá alborotada por Carter, que, de la noche a la mañana, se convertirá en su jefe de inmediato. Pero el destino le tiene preparadas más sorpresas... ¿Cómo afrontará Dan su nueva situación profesional? ¿Cómo sobrellevar que tu jefe no sólo tiene veinte años menos, sino que además tiene un lío con tu hija?', trailer_url = 'https://www.youtube.com/watch?v=8M7z4LoGVEY' WHERE id_api = 'tt0385267';

UPDATE Contenido SET id_tmdb = 10040, descripcion = 'Tras hacerse famosa salvando un concurso de belleza, Gracie Hart pasa más tiempo en la peluquería que en el campo de tiro. Cuando secuestran a sus amigas Cheryl y Emcee en Las Vegas, Gracie vuelve a la acción para salvarlas.', trailer_url = 'https://www.youtube.com/watch?v=iv4SzMPlwp4' WHERE id_api = 'tt0385307';

UPDATE Contenido SET id_tmdb = 9918, descripcion = '"Camino a la gloria" cuenta la historia real del equipo de baloncesto de la Universidad Texas Western que contó con el primer jugador negro de la historia y que revolucionó el país al conquistar el título de la NCAA en 1966. Josh Lucas interpreta a Don Haskins, un apasionado entrenador de baloncesto universitario que cambió la historia de este deporte gracias al triunfo de su equipo en una época en la que todavía imperaba la inocencia y la ingenuidad.', trailer_url = 'https://www.youtube.com/watch?v=6_AnOUp0nVQ' WHERE id_api = 'tt0385726';

UPDATE Contenido SET id_tmdb = 647, descripcion = 'Esta película generada íntegramente por ordenador, es la continuación del videojuego de Square Enix; Final Fantasy VII y forma parte de una estrategía de la propia compañía para completar la historia de la saga. El argumento nos sitúa dos años después de Final Fantasy VII. Cloud Strife, el protagonista, vive solo en la iglesia de Aeris y está afectado por una extraña enfermedad, el GeoStigma, un virus que lo está matando poco a poco dejándole sin energía...', trailer_url = 'https://www.youtube.com/watch?v=FUMxY-767OU' WHERE id_api = 'tt0385700';

UPDATE Contenido SET id_tmdb = 2268, descripcion = 'Historia de una niña de 12 años que hará un largo viaje para intentar salvar a un amigo. En el camino se encontrará con todo tipo de extrañas criaturas, brujas y otros personajes de un universo paralelo... En este singular mundo, donde las almas humanas toman la forma de compañeros del género animal, esta niña se coloca entre el fin de la libre voluntad y el inicio de una nueva era. Lyra Belacqua sólo tiene 12 años, pero incluso ella sabe que hacer lo que te dicen en lugar de hacer lo sientes está bien puede tener resultados muy diferentes. Una huérfana rebelde que vive como una reclusa en Jordan College en la ciudad de Oxford, Lyra pertenece a un mundo que es uno de muchos mundos paralelos: mundos no vistos, dimensiones intangibles donde la humanidad se desarrolla con sutiles diferencias.', trailer_url = 'https://www.youtube.com/watch?v=f2R-m_gwV6A' WHERE id_api = 'tt0385752';

UPDATE Contenido SET id_tmdb = 1428, descripcion = 'Mythbusters (en español Cazadores de mitos) es un programa de televisión estadounidense y australiano de divulgación científica emitido por Discovery Channel. Está protagonizado por los expertos en efectos especiales Adam Savage y Jamie Hyneman ayudados, hasta el final de la temporada de 2014, por Tory Belleci, Grant Imahara y Kari Byron. En el programa, los protagonistas usan sus conocimientos y habilidades para poner a prueba la veracidad de las leyendas urbanas y otras creencias de la cultura popular sometiéndolas al método científico.', trailer_url = 'https://www.youtube.com/watch?v=Hy265SKypYk' WHERE id_api = 'tt0383126';

