UPDATE Contenido SET id_tmdb = 16523, descripcion = 'Una adaptación del cuento clásico infantil de Maurice Sendak, donde Max, un niño desobediente enviado a la cama sin cenar, crea su propio mundo - un bosque habitado por feroces criaturas salvajes que corona a Max como su gobernante.', trailer_url = 'https://www.youtube.com/watch?v=gPkeNzWT6Yo' WHERE id_api = 'tt0386117';

UPDATE Contenido SET id_tmdb = 9297, descripcion = 'D.J. Walters es un chico de doce años al que se le ha metido en la cabeza que en la casa del anciano Nebbercracker, al otro lado de la calle, ocurre algo extraño. La víspera de Halloween, el balón con el que juegan D.J. y su amigo va a parar al jardín del señor Nebbercracker, pero misteriosamente llega al interior de la vivienda. Cuando su amiga Jenny está a punto de ser engullida por la extraña casa, nadie cree a los asustados chicos; así que los tres deciden investigar qué sucede en esa extraña casa.', trailer_url = 'https://www.youtube.com/watch?v=FvJl6wI0QUo' WHERE id_api = 'tt0385880';

UPDATE Contenido SET id_tmdb = 2359, descripcion = 'Michael Moore vuelve a la carga con un documental que denuncia el sistema sanitario norteamericano; un sistema que, al no existir la sanidad universal, excluye a 50 millones de norteamericanos (que, o bien no tienen seguro de salud privado, o no pueden pagárselo) y que se basa en compañías privadas que buscan principalmente beneficios económicos y en aseguradoras que pagan bonos a los empleados que más rentabilidad les proporcionan al denegar prestaciones y reclamaciones a los asegurados.', trailer_url = 'https://www.youtube.com/watch?v=uD9Id4CG_c8' WHERE id_api = 'tt0386032';

UPDATE Contenido SET id_tmdb = 504562, descripcion = 'Nueva York, 1957. Lionel Essrog, un detective privado que convive con el síndrome de Tourette, trata de resolver el asesinato de su mentor y mejor amigo, armado solo con vagas pistas y la fuerza de su mente obsesiva.', trailer_url = 'https://www.youtube.com/watch?v=Fru8IkuDp_k' WHERE id_api = 'tt0385887';

UPDATE Contenido SET id_tmdb = 176, descripcion = 'Dos extraños, que se despiertan en una habitación sin recordar cómo llegaron allí, pronto descubren que son peones en un juego mortal perpetrado por un famoso asesino en serie.', trailer_url = 'https://www.youtube.com/watch?v=roj2cj8veeU' WHERE id_api = 'tt0387564';

UPDATE Contenido SET id_tmdb = 1656, descripcion = 'Tras ayudar con su espada a que California se convierta en el estado número 31 de la Unión, el Zorro debe cumplir la promesa que le hizo a su mujer Elena: abandonar su identidad secreta y llevar una vida normal como Alejandro de la Vega.', trailer_url = 'https://www.youtube.com/watch?v=gs19Vnl8M3E' WHERE id_api = 'tt0386140';

UPDATE Contenido SET id_tmdb = 8488, descripcion = 'Alex "Hitch" Hitchens es conocido en su trabajo como el "Doctor de las Citas": es capaz de conseguir que una mujer se enamore del hombre más mediocre del que nunca imaginó que lo haría en tan solo tres citas. Hitch es un experto en mujeres, puede saber todo sobre ellas, más de lo que suelen imaginar ellas mismas, y se conoce todos los trucos que uno pueda imaginar para conseguir que sus clientes, normalmente personas inseguras y tímidas, acaben teniendo idilios con las mujeres más despampanantes de la ciudad. Cuando Sara Melas, una periodista sensacionalista procedente del mundo de los cotilleos, decide hundirle en los medios creándole una imagen de farsante, surgirá una gran atracción entre los dos, que pondrá a prueba todo lo que Hitch creía conocer sobre las mujeres.', trailer_url = 'https://www.youtube.com/watch?v=QmLclllqSb0' WHERE id_api = 'tt0386588';

UPDATE Contenido SET id_tmdb = 1985, descripcion = 'Basada en el Best Seller de espionaje de John le Carré, cuenta la historia de Justin Quayle (Fiennes) un diplomático británico destinado en Kenya cuya mujer es asesinada junto a un hombre sospechoso de ser su amante, un activista defensor de los derechos humanos de la región. Quayle decide entonces investigar los asesinatos, y comienza a descubrir mucho más de lo que esperaba...', trailer_url = 'https://www.youtube.com/watch?v=9FycLyDTCWQ' WHERE id_api = 'tt0387131';

UPDATE Contenido SET id_tmdb = 11249, descripcion = 'Seed of Chucky presenta a Glen, el hijo huérfano del irresistible Chucky y de su retorcida esposa Tiffany. En Hollywood se prepara una película acerca de la leyenda urbana de sus sanguinarios padres y Glen aprovecha para resucitarlos. Pero las relaciones familiares son todo menos perfectas cuando Glen descubre que Chucky y su deliciosa Tiffany se han lanzado a una carrera tan infernal como criminal. Chucky no acaba de creerse que su retoño no quiera seguir sus sangrientos pasos. Tiffany, totalmente colgada de las estrellas de Hollywood, tampoco acaba de creerse que el director haya escogido a Jennifer Tilly para protagonizar la película. La actriz no tarda en convertirse, muy a pesar suyo, en anfitriona de la temible familia.', trailer_url = 'https://www.youtube.com/watch?v=-g4TZOoXC1E' WHERE id_api = 'tt0387575';

UPDATE Contenido SET id_tmdb = 2316, descripcion = 'Steve Carell protagoniza The Office, un fresco y divertido vistazo, con formato pseudo-documental, al día a día en la vida de unos excéntricos trabajadores de la empresa Dunder Mifflin. El serio pero despistadísimo director Michael Scott se considera un magnífico jefe y mentor, pero realmente inspira más críticas que respeto a sus empleados.', trailer_url = 'https://www.youtube.com/watch?v=dmG9Oc4qYQk' WHERE id_api = 'tt0386676';

