UPDATE Contenido SET id_tmdb = 13673, descripcion = 'Luther Krank y su mujer deciden no celebrar la Navidad. Nada de arbolitos. ¿Lograrán manejar las reacciones que su decisión provoca en familiares y vecinos?', trailer_url = 'https://www.youtube.com/watch?v=nZDRp41I2U0' WHERE id_api = 'tt0388419';

UPDATE Contenido SET id_tmdb = 7512, descripcion = 'Tras un experimento militar fallido, el oficial Joe Bawers y la prostituta Rita despiertan quinientos años adelante en el futuro, en un mundo distópico en el que la selección natural ha favorecido a los más idiotas, debido a que se reproducen más. Esto ha resultado en una humanidad estúpida e ignorante, de modo que Joe descubre que es el hombre más inteligente del planeta. Pronto se convierte en un cercano consejero del Presidente de los Estados Unidos, el excéntrico Camacho.', trailer_url = 'https://www.youtube.com/watch?v=clYwX8Z43zg' WHERE id_api = 'tt0387808';

UPDATE Contenido SET id_tmdb = 445, descripcion = 'Georges es el típico burgués: presenta un programa literario en televisión y lleva una vida acomodada con su mujer y su hijo adolescente. Pero, empieza a recibir unos paquetes anónimos que contienen cintas de vídeo, grabadas desde la calle, y unos dibujos inquietantes cuyo significado es un misterio. No sabe quién los envía; sin embargo, las secuencias que aparecen en las cintas se hacen cada vez más personales, lo que sugiere que el remitente le conoce desde hace algún tiempo. Georges siente que una amenaza se cierne sobre él y su familia, pero, puesto que no hay evidencias de delito alguno, la policía se niega a ayudarlo.', trailer_url = 'https://www.youtube.com/watch?v=pvT_9TqIEtM' WHERE id_api = 'tt0387898';

