UPDATE Contenido SET id_tmdb = 1427, descripcion = 'Francia, siglo XVIII. Adaptación del famoso best-seller de Patrick Süskind. Jean Baptiste Grenouille nació en medio del hedor de los restos de pescado de un mercado y fue abandonado por su madre en la basura. Las autoridades se hicieron cargo de él y lo mandaron a un hospicio. Creció en un ambiente hostil; nadie le quería, porque había en él algo excepcional: carecía por completo de olor. Estaba, sin embargo, dotado de un extraordinario sentido del olfato. A los veinte años, después de trabajar en una curtiduría, consiguió trabajo en casa del perfumista Bandini, que le enseñó a destilar esencias. Pero él vivía obsesionado con la idea de atrapar otros olores: el olor del cristal, del cobre, pero, sobre todo, el olor de algunas mujeres.', trailer_url = 'https://www.youtube.com/watch?v=zutiIw_2e2g' WHERE id_api = 'tt0396171';

