UPDATE Contenido SET id_tmdb = 10066, descripcion = 'Seis amigos que viajan por carretera para asistir al campeonato universitario de fútbol más importante del año, deciden acampar al aire libre la víspera del partido. A la mañana siguiente, se dan cuenta de que su coche ha sido manipulado, así que aceptan la invitación de un conductor que los lleva hasta Ambrose. Al llegar, visitan la principal atracción de la ciudad: la Casa de Cera de Trudy, que está llena de esculturas de cera cuyo parecido con personas reales es asombroso. Cuando descubren, horrorizados, la razón de esta inquietante semejanza, comprenden que o escapan de la ciudad o se convertirán en estatuas del tenebroso museo de cera.', trailer_url = 'https://www.youtube.com/watch?v=kbCfuFJ30t4' WHERE id_api = 'tt0397065';

UPDATE Contenido SET id_tmdb = 2458, descripcion = 'CSI: Nueva York es la tercera franquicia de la serie creada por Anthony Zuiker y producida por Jerry Bruckheimer. Quizás era la más esperada por el atractivo de la ciudad. Casi 19 millones de personas se apoltronaron en Estados Unidos el día del estreno de la primera tanda de este seriado policial que ya es objeto de culto entre los televidentes de todo el mundo. La presencia de Gary Sinise siempre aseguró parte del éxito de la versión neoyorquina de CSI. Este reconocido actor, ganador de premios Emmy y Golden Globe, nominado al Oscar por su desempeño en la célebre Forrest Gump y a quien también hemos visto en Truman y Apollo 13, encarna al detective Mac Taylor, reservado, brillante en su trabajo como jefe del departamento de criminalística. Junto a Sinise, el equipo del detective Taylor se completa con la atractiva, inteligente y medio misteriosa Stella Bonasera (Melina Kanakaredes); Don Flack (Eddie Cahill), el joven detective que parece haber heredado de sus padres la pasión por este riesgoso trabajo y el conocimiento de los rincones más oscuros de la ciudad; Danny Messer (Carmine Giovinazzo), el rubio policía que maneja muy bien los códigos del hampa y siempre parece bordear los límites de lo legal; la entusiasta y justiciera Lindsay Monroe (Anna Belknap); y con el sabelotodo doctor Sheldon Hawkes (Hill Harper), un joven de prodigioso conocimiento enciclopédico que parece saber tanto o más que su vecino de serie, Grissom, y que es capaz de extraer evidencia hasta del diminuto cuerpo de un mosquito.', trailer_url = NULL WHERE id_api = 'tt0395843';

