UPDATE Contenido SET id_tmdb = 10025, descripcion = 'Ashley (Lindsay Lohan) es la chica más afortunada de Nueva York: todo le sale bien. Siempre. El caso es que desde pequeña siempre ha tenido buena suerte, y nunca nada le ha salido mal. Pero un día, en un baile de máscaras, Ashley besa a Jake (Chris Pine), el joven con peor suerte de la ciudad, y sus papeles se intercambian. Ella, que parecía tocada por la buena estrella, comienza a sufrir desgracias.', trailer_url = 'https://www.youtube.com/watch?v=rkJInkePtOY' WHERE id_api = 'tt0397078';

UPDATE Contenido SET id_tmdb = 9913, descripcion = 'Después de abandonar su trabajo de enfermera en una clínica, Caroline (Hudson) es contratada para cuidar de un anciano que ha sufrido una embolia, aunque la esposa de éste (Rowlands) la acoge con bastante recelo. El matrimonio vive en una siniestra mansión sureña en las afueras de Nueva Orleáns, en el delta del Mississippi (Louisiana). Intrigada por las extrañas costumbres de la enigmática pareja, Caroline decide explorar la casa. Armada con una llave maestra, empieza a abrir todas las puertas hasta que descubre un desván secreto que contiene un terrible secreto.', trailer_url = 'https://www.youtube.com/watch?v=Ue86OkmeQxU' WHERE id_api = 'tt0397101';

UPDATE Contenido SET id_tmdb = 9036, descripcion = 'En la Antártida, los miembros de una expedición científica se ven obligados a abandonar a sus queridos perros guía debido a un accidente inesperado y a las terribles condiciones meteorológicas. Los perros tendrán que luchar para sobrevivir en medio del invierno polar hasta que los exploradores puedan enviarles una expedición de rescate.', trailer_url = 'https://www.youtube.com/watch?v=HRQ1JeRieCQ' WHERE id_api = 'tt0397313';

UPDATE Contenido SET id_tmdb = 13053, descripcion = 'Para el super-perro Bolt todos los días están llenos de aventuras, peligros e intriga -al menos hasta que las cámaras dejan de grabar, ya que es el protagonista de un famoso programa de televisión-. Pero cuando la estrella canina del gran éxito televisivo es enviada accidentalmente desde sus estudios de Hollywood a Nueva York, comienza su mayor aventura en un viaje campo a través por el mundo real. Bolt está convencido de que todos sus increíbles poderes y hazañas son reales.', trailer_url = 'https://www.youtube.com/watch?v=ubSLsba9hoU' WHERE id_api = 'tt0397892';

UPDATE Contenido SET id_tmdb = 1904, descripcion = 'Japón, 1929. Chiyo, una niña de nueve años, es vendida por sus padres para trabajar en la casa de Geishas de Nitta Okiya. Su hermana mayor Satsu no es aceptada y es enviada a un prostíbulo. En la casa Chiyo conoce a Pumpkin, otra niña que va a ser instruida para ser geisha, así como a las famosas geishas Hatsumomo y su rival Mameha. Los comienzos de Chiyo son duros, pero un encuentro con el que será el amor de su vida, el Presidente, hará que desde ese momento sólo desee convertirse en una famosa geisha para estar más cerca de él.', trailer_url = 'https://www.youtube.com/watch?v=NwJw70Yufug' WHERE id_api = 'tt0397535';

UPDATE Contenido SET id_tmdb = 8999, descripcion = 'Charles Schine (Clive Owen), un ejecutivo casado, coge el metro-tranvía de todas las mañanas, en el que viaja una atractiva mujer, Lucinda Harris (Jennifer Aniston). Ese día él no tiene dinero para el billete, y ella se ofrece a pagárselo. A partir de este pequeño suceso, su cotidianeidad sufrirá un inesperado giro.', trailer_url = 'https://www.youtube.com/watch?v=P8uXNdX_ccc' WHERE id_api = 'tt0398017';

UPDATE Contenido SET id_tmdb = 38757, descripcion = 'Flynn Rider, el más buscado -y encantador- bandido del reino, se esconde en una misteriosa torre y allí se encuentra con Rapunzel, una bella y avispada adolescente con una cabellera dorada de 21 metros de largo, que vive encerrada allí desde hace años. Ambos sellan un pacto y a partir de ese momento la pareja vivirá emocionantes aventuras en compañía de un caballo superpolicía, un camaleón sobreprotector y una ruda pandilla de matones', trailer_url = 'https://www.youtube.com/watch?v=ee3XOCH-pok' WHERE id_api = 'tt0398286';

