UPDATE Contenido SET id_tmdb = 2800, descripcion = 'Sara Huttinger (Jennifer Aniston), una joven a punto de casarse, regresa a su ciudad natal, en California, para averiguar la verdad sobre un secreto familiar. Al parecer, los personajes femeninos tanto del libro como de la película "El Graduado" están inspirados en su abuela y en su madre. Pero eso no es lo peor: poco a poco Sara se sentirá atraída por el maduro galán (Kevin Costner) que tuvo relaciones con ellas en el pasado.', trailer_url = 'https://www.youtube.com/watch?v=QWYqikq6YuE' WHERE id_api = 'tt0398375';

UPDATE Contenido SET id_tmdb = 1395, descripcion = 'Los niños pijos de un instituto privado de Manhattan se salen siempre con la suya, hasta que una bloguera anónima, llamada la Reina Cotilla, espía sus movimientos.', trailer_url = 'https://www.youtube.com/watch?v=m3Y7JEYrAtg' WHERE id_api = 'tt0397442';

UPDATE Contenido SET id_tmdb = 8978, descripcion = 'Quedan pocas horas para que el año toque a su fin y en la comisaría del distrito 13, sólo queda un puñado de policías encabezado por el sargento Jake Roenick (Ethan Hawke), un buen oficial que no consigue olvidar una operación fallida que tuvo lugar la primavera pasada. Pero es que, además, ese mismo día por la mañana, un policía de paisano había intentado arrestar al mafioso Marion Bishop (Laurence Fishburne), el cual consiguió matar al agente antes de ser capturado por la Unidad contra el Crimen Organizado encabezada por Marcus Duvall (Gabriel Byrne). Bishop es trasladado en autobús a la cárcel, pero la tormenta de nieve arrecia y el autobús, ante la imposibilidad de llegar a la cárcel de máxima seguridad, se dirige provisionalmente a la comisaría del distrito 13.', trailer_url = 'https://www.youtube.com/watch?v=Tcoi_b1hMc0' WHERE id_api = 'tt0398712';

UPDATE Contenido SET id_tmdb = 9053, descripcion = 'Tina Armstrong es una superestrella en el mundo de la lucha femenina. Christie es una bella ladrona y asesina a sueldo. La princesa Kasumi es una guerrera aristócrata asiática que recibió formación de maestros de las artes marciales. Helena Douglas es una atleta de deportes extremos cuyo trágico pasado la obliga a confinarse en un lejano palacio del sureste asiático, que es donde tiene lugar el torneo de Dead Or Alive. A ellas se unirá, en aquel selvático paraje, la flor y nata de los luchadores de élite mundial, todos ellos esforzándose al máximo para conseguir el premio de 10 millones de dólares. Entre los contendientes se encuentra Zack, el luchador callejero, Bayman, poseedor de un récord Guinness y conocido como "el hombre más fuerte de Australia"; y el duro Leon.', trailer_url = 'https://www.youtube.com/watch?v=DHAjxQ3BdI0' WHERE id_api = 'tt0398913';

UPDATE Contenido SET id_tmdb = 1265, descripcion = 'Jess Aarons, un chico que se siente extraño tanto en el colegio como en su propia casa, se ha entrenado durante todo el verano para correr una carrera; pero llega al colegio Leslie Burke y le gana. A pesar de ello, pronto se hacen amigos. Leslie, aficionada a contar fantásticas y mágicas historias, le abre a Jess las puertas de un mundo dominado por la imaginación. A Jess le gusta dibujar, pero nunca había compartido esa afición con nadie. Los dos crean el reino secreto de Terabithia, un lugar mágico cuya entrada sólo ellos conocen. Allí reinan, luchan contra el Maestro Oscuro y sus criaturas y trazan planes para vengarse de los compañeros prepotentes del colegio.', trailer_url = 'https://www.youtube.com/watch?v=VvgS3RcqYLQ' WHERE id_api = 'tt0398808';

UPDATE Contenido SET id_tmdb = 1830, descripcion = 'Basada en una historia real, situada en el mundo internacional de la trata de armas. La película explora una consecuencia poco conocida del final de la Guerra Fría, la enorme cantidad de armas que de repente quedó disponible en los antiguos estados soviéticos para vender a los países en desarrollo (sobre todo de África) y las inmensas sumas de dinero amasadas por los traficantes de armas que las vendieron. Muchos piensan que es el mayor atraco del siglo 20. Sólo en Ucrania, entre 1982 y 1992 se robaron más de treinta y dos mil millones de dólares en armas. Ningún culpable ha sido jamás atrapado ni procesado.', trailer_url = 'https://www.youtube.com/watch?v=w6Zj29q8uC8' WHERE id_api = 'tt0399295';

UPDATE Contenido SET id_tmdb = 1635, descripcion = 'Año 2019. Lincoln Seis-Eco y Jordan Dos-Delta se encuentran entre los cientos de residentes de una especie de campo de concentración. Dentro de ese lugar cuidadosamente vigilado, su vida cotidiana, como la de los demás, está rigurosamente controlada y llena de restricciones. La única salida -y la esperanza que todos comparten- consiste en ser elegidos para ir a "La isla", el único lugar del mundo que no ha sufrido los efectos contaminantes de un desastre ecológico que, al parecer, acabó con todos los humanos excepto los habitantes de esa zona. Lincoln, que vive atormentado por pesadillas inexplicables, se siente cada vez más inquieto, y su creciente curiosidad lo llevará a descubrir un terrible secreto.', trailer_url = 'https://www.youtube.com/watch?v=xb4PR2zYUrk' WHERE id_api = 'tt0399201';

UPDATE Contenido SET id_tmdb = 59, descripcion = 'Tom Stall lleva una vida feliz y tranquila con su mujer –abogada– y sus dos hijos en la pequeña ciudad de Millbrook (Indiana) hasta que una noche su existencia idílica se ve destrozada cuando frustra un violento intento de robo en su restaurante. Tom percibe el peligro y salva a sus clientes y amigos matando en defensa propia a dos criminales buscados por la justicia. Aplaudido como un héroe, la vida de Tom cambia de la noche a la mañana y de repente se encuentra convertido en el centro de atención de todos los medios de comunicación. Incómodo con esta fama no buscada, intenta volver a su vida normal, pero un hombre amenazante y misterioso llega a la ciudad para enfrentarse a él porque cree que Tom es el hombre con quien tiene una cuenta pendiente del pasado.', trailer_url = 'https://www.youtube.com/watch?v=jsEcDGKh56U' WHERE id_api = 'tt0399146';

UPDATE Contenido SET id_tmdb = 11451, descripcion = 'Maggie Peyton (Lindsay Lohan), la nueva propietaria del Número 53, el desenfrenado Herbie (el Volkswagen que piensa por su cuenta), decide competir en la categoría ASCAR. Con los nuevos trucos que esconde Herbie bajo el capó, intentará entrar en el libro de los récords.', trailer_url = 'https://www.youtube.com/watch?v=SlfpQCG4r9U' WHERE id_api = 'tt0400497';

UPDATE Contenido SET id_tmdb = 2013, descripcion = 'Jean-Dominique Bauby, editor de la revista Elle en Francia, sufrió en 1995, a la edad de 43 años, un derrame cerebral que paralizó todo su cuerpo a excepción del ojo izquierdo. Utilizando ese ojo para sacar a la luz sus memorias, Bauby describió elocuentemente los aspectos de su mundo interior, desde el tormento psicológico de estar atrapado dentro de su cuerpo a sus historias imaginadas de tierras que sólo había visitado en su mente.', trailer_url = 'https://www.youtube.com/watch?v=k-9MeE5ZqWY' WHERE id_api = 'tt0401383';

UPDATE Contenido SET id_tmdb = 7484, descripcion = 'Boog, un oso pardo nada habilidoso, vive en un mundo perfecto en el tranquilo pueblo de Timberline hasta que conoce a Elliot, un flacucho, salvaje y parlanchín ciervo. A pesar de su mejor juicio, Boog libera a Elliot del cazador Shaw y Boog es convencido por este ciervo de salir de su cómoda vida para conocer el bosque. Así regresan los dos busca-problemas a la vida salvaje justo 3 días antes de la temporada de caza. Con la temporada de caza y Shaw sobre ellos, Boog y Elliot deberán aprender a trabajar juntos y unir a las criaturas del bosque para librar una ruda batalla y cazar a los cazadores.', trailer_url = 'https://www.youtube.com/watch?v=YHQAL6s3Mk8' WHERE id_api = 'tt0400717';

UPDATE Contenido SET id_tmdb = 9726, descripcion = 'Max Skinner (Russell Crowe), un experto en inversiones viaja desde Londres hasta Provenza para vender un pequeño viñedo que ha heredado de un tío, al que estuvo muy unido en su niñez. Lo que no esperaba en absoluto es que éste fuera el punto de partida de un estimulante capítulo de su vida.', trailer_url = 'https://www.youtube.com/watch?v=bKKrLj5ZHiM' WHERE id_api = 'tt0401445';

UPDATE Contenido SET id_tmdb = 2266, descripcion = 'En París, el amor está por todas partes: en sus bares y cafés, bajo la Torre Eiffel e incluso bajo tierra, en el metro. Algunos de los directores más prestigiosos del mundo fueron invitados a contar una historia ambientada en uno de los barrios de la ciudad. El resultado es un caleidoscopio de imágenes sobre la alegría de vivir, sobre extraños e inesperados encuentros y, especialmente, sobre el amor.', trailer_url = 'https://www.youtube.com/watch?v=yAOQBuPHV3M' WHERE id_api = 'tt0401711';

UPDATE Contenido SET id_tmdb = 49529, descripcion = 'Adaptación de ‘Una princesa de Marte’, la primera novela fantástica de Edgar Rice Burroughs. La película lleva a la gran pantalla una aventura épica que se desarrolla en el devastado planeta Marte, un mundo habitado por tribus guerreras y seres salvajes. John Carter es un veterano de la Guerra Civil norteamericana (1861-1865) que se halla en el planeta Marte, se ve inmerso en una nueva y misteriosa guerra con un extraño ejército de marcianos, entre los que se encuentran Tars Tarkas y la princesa Dejah Thoris.', trailer_url = 'https://www.youtube.com/watch?v=12MKMj86078' WHERE id_api = 'tt0401729';

UPDATE Contenido SET id_tmdb = 187, descripcion = 'Bienvenidos a Sin City, ciudad de policías corruptos, atractivas damas y vigilantes desesperados. Unos buscan venganza, otros redención, y algunos, buscan ambas cosas. Un universo de héroes inverosímiles que intentan hacer lo correcto. Sin City es una ciudad que vive entre la luz y la oscuridad, llena de personajes singulares.', trailer_url = 'https://www.youtube.com/watch?v=-kN3rEbRvGw' WHERE id_api = 'tt0401792';

UPDATE Contenido SET id_tmdb = 834, descripcion = 'La lucha milenaria entre depredadores ha adoptado nuevas dimensiones de violencia. Ha nacido una nueva raza en nada comparable a ninguna otra conocida. Traicionada por los de su propio clan, la guerrera vampiro Selene (Kate Beckinsale), busca venganza. Para ello, decide descubrir la verdad sobre la identidad del primer Inmortal verdadero. No es Marcus, el rey de los vampiros como se creía, sino Alexander Corvinus, padre de Marcus y de su hermano gemelo William. Selene y el híbrido Michael (Scott Speedman), protagonistas de un amor prohibido, lucharán juntos contra el poderoso Marcus, quien está decidido a liberar a su hermano preso y usar la sed de sangre de éste para llegar a dominar el mundo.', trailer_url = 'https://www.youtube.com/watch?v=SWCi9TXC2gI' WHERE id_api = 'tt0401855';

