UPDATE Contenido SET id_tmdb = 4169, descripcion = 'Al aspirante a agente del FBI Eric O''Neill (Phillippe) le asignan como compañero al veterano Robert Hanssen (Cooper). La Agencia tiene evidencias de que está pasando información muy valiosa a los soviéticos. Para no levantar demasiadas sospechas, una de las supervisoras del caso (Linney) le dice a Eric que su misión será vigilar a Hanssen porque es un pervertido sexual. (FILMAFFINITY)', trailer_url = 'https://www.youtube.com/watch?v=XJuLFKeRoJg' WHERE id_api = 'tt0401997';

