UPDATE Contenido SET id_tmdb = 11400, descripcion = 'Ambientada en la América colonial, a principios de siglo XVII, "El nuevo mundo" es una aventura épica sobre el encuentro de las culturas europea y nativa americana durante la creación de la colonia Jamestown en 1607. Inspirada en la leyenda de John Smith y Pocahontas, un ambicioso colonizador y una apasionada nativa de alto linaje que se encuentran divididos entre sus deberes y sus sentimientos.', trailer_url = 'https://www.youtube.com/watch?v=i2LdlqW26zc' WHERE id_api = 'tt0402399';

UPDATE Contenido SET id_tmdb = 5289, descripcion = 'La historia empieza en una tranquila mañana de un día laborable cuando un banco abre sus puertas. Antes de que nadie se dé cuenta de lo que pasa, un grupo de cinco ladrones, encapuchados y vestidos de negro, irrumpen en el banco y toman a todos como rehenes. En breve la policía llega y rodean a los atracadores. El cabecilla de la banda Lorenz (Wesley Snipes) pide un negociador. Exige que sea el detective Quentin Conners (Jason Statham). Conners vuelve a su puesto tras su reciente expulsión causada por un incidente fortuito que terminó con la muerte de un rehén, y la expulsión definitiva del cuerpo de su entonces compañero el detective York.', trailer_url = 'https://www.youtube.com/watch?v=YemdtcnhH14' WHERE id_api = 'tt0402910';

UPDATE Contenido SET id_tmdb = 3040, descripcion = 'Al caer la noche, las fuerzas de la oscuridad combaten a los “Otros”, sobrehumanos, Guardianes de la Noche, cuya misión es patrullar y proteger a la humanidad, manteniendo la calma. Pero existe un temor constante de que una antigüa profecía se convierta en realidad: que un poderoso “Otro” aparecerá, será tentado por uno de los lados e inclinará la balanza, haciendo que se desate una guerra entre la luz y la oscuridad, cuyos resultados pueden ser catastróficos.', trailer_url = 'https://www.youtube.com/watch?v=7zPuFQQfRbE' WHERE id_api = 'tt0403358';

UPDATE Contenido SET id_tmdb = 9681, descripcion = 'Casanova, el seductor más famoso del mundo, el maestro del disfraz y del arte de la seducción, al que ninguna mujer se le resiste, conoce a Francesca, una bella veneciana, que lo rechaza sin contemplaciones. Por medio de una serie de estratagemas y cambios de identidad, consigue finalmente que Francesca se interese por él. Pero, en esta ocasión, no sólo está en juego su vida y su reputación, sino también su única oportunidad de alcanzar el amor.', trailer_url = 'https://www.youtube.com/watch?v=FLbl01QrMzI' WHERE id_api = 'tt0402894';

UPDATE Contenido SET id_tmdb = 9779, descripcion = 'Basada en un best-seller de Ann Brashares, narra la historia de cuatro amigas adolescentes que durante un verano se tendrán que separar por primera vez. A la introspectiva y a veces temperamental Carmen le hace ilusión pasar tiempo con su padre, al que ve muy poco desde que se separó de su madre hace años; la extrovertida atleta Bridget se dirige a un campamento de fútbol en México; la tranquila Lena, una artista tan hermosa como sus dibujos, va a descubrir sus orígenes - y un inesperado amor - en el pueblo de sus abuelos en Grecia; y la rebelde Tibby se quedará contra su voluntad en la ciudad, llenando estanterías en el supermercado local y trabajando en su proyecto personal: un documental que pretende mostrar la banalidad de la vida cotidiana.', trailer_url = 'https://www.youtube.com/watch?v=eV1IkLvTe1I' WHERE id_api = 'tt0403508';

