UPDATE Contenido SET id_tmdb = 7979, descripcion = 'Basado en una novela best-seller, se ha convertido en la película más aclamada del año. Cuando eran pequeños, Amir y Hassan eran dos amigos inseparables hasta que un desafortunado hecho los separa. Años más tarde, Amir comenzará una peligrosa misión para corregir los errores del pasado - y redimirse a sí mismo en formas que nunca imaginó - demostrando además el máximo en valor y en devoción a su amigo. Dirigida por Marc Foster (Descubriendo Nunca Jamás, Bola de Monter), "Cometas en el cielo" nos permite creer que puede haber justicia en el mundo" - Richard Corliss, TIME', trailer_url = 'https://www.youtube.com/watch?v=sLtavGjAOJY' WHERE id_api = 'tt0419887';

UPDATE Contenido SET id_tmdb = 1262, descripcion = 'Una novelista (Emma Thompson) está intentando acabar su última -y posiblemente mejor- obra. Sólo hay un problema: tiene que encontrar un modo de matar al personaje principal (Will Ferrell). ¿Que cuál es el problema? Pues que el personaje principal no es un ente de ficción.', trailer_url = 'https://www.youtube.com/watch?v=PZpg8VII7es' WHERE id_api = 'tt0420223';

UPDATE Contenido SET id_tmdb = 308032, descripcion = 'Esta película está basada en una historia real que tuvo lugar en 1971, cuando el profesor de Stanford Dr. Philip Zimbardo creó lo que se convirtió en uno de los experimentos sociales más impactantes y famosos de todos los tiempos: en unos días fue capaz de convertir a un grupo de ciudadanos de clase media en gente sádica por un lado y víctimas sumisas por otro.', trailer_url = 'https://www.youtube.com/watch?v=7LviGTHud5w' WHERE id_api = 'tt0420293';

UPDATE Contenido SET id_tmdb = 5708, descripcion = 'Película sobre los últimos años de Ian Curtis, el enigmático cantante de la banda Joy Division e icono del post-punk inglés, hasta su trágico suicidio en 1980. Cómo le afectó el dramático conflicto entre el gran amor que sentía por su esposa y la apasionada relación con su amante, sus ataques de epilepsia, su extraordinario talento y sus arrolladoras actuaciones en directo. Mención Especial en la Cámara de Oro, Premio de la Juventud y Premio Label Europa Cinema en el Festival de Cannes.', trailer_url = 'https://www.youtube.com/watch?v=XCbOrTbBr6Y' WHERE id_api = 'tt0421082';

UPDATE Contenido SET id_tmdb = 10781, descripcion = '1969. En Estados Unidos, los efectos de la guerra de Vietnam son catastróficos: las bajas son innumerables, pero el reclutamiento continúa. Dean Hill, que acaba de cumplir 18 años, es llamado a filas. Su hermano Eric, que acaba de regresar de Vietnam, contra los deseos de su novia decide volver a alistarse en la Marina para proteger a su hermano. Pero los planes de Eric no coinciden con los de Dean, que ha planeado huir a México con su novia para evitar la guerra. Pero antes de ejecutar sus planes, las dos parejas deciden ir a Texas para pasar un último fin de semana de diversión.', trailer_url = 'https://www.youtube.com/watch?v=h2ImQed8lvw' WHERE id_api = 'tt0420294';

UPDATE Contenido SET id_tmdb = 4251, descripcion = 'Veer, un piloto de la Armada India, conoce a Zaara, una chica Pakistaní que viaja hacia un pequeño pueblo para enterrar las cenizas de una antigua criada, y decide guiarla. En ese viaje surge el amor, pero Zaara está comprometida.', trailer_url = 'https://www.youtube.com/watch?v=xQ-34j4jKes' WHERE id_api = 'tt0420332';

UPDATE Contenido SET id_tmdb = 1266, descripcion = 'Tom Ludlow es un veterano policía de Los Ángeles que está pasando el peor momento de su vida tras la muerte de su mujer. Cuando unas pruebas le implican en la ejecución de un compañero, Tom se verá forzado a ir contra todo lo que ha conocido en el cuerpo hasta ahora, cuestionándose la lealtad de todos y cada uno de los que le rodean...', trailer_url = 'https://www.youtube.com/watch?v=RqycC_vvxEY' WHERE id_api = 'tt0421073';

UPDATE Contenido SET id_tmdb = 9923, descripcion = 'Domino Harvey, una joven modelo hastiada de la vida de la alta sociedad, decide abandonar su carrera y unirse al equipo de cazarrecompensas de Ed y Choco, esperando que las emociones fuertes le den un sentido a su vida. Contra todo pronóstico, demuestra tener un talento innato para salir de las situaciones arriesgadas. Todo marcha bien hasta que reciben el encargo de recuperar diez millones de dólares que han sido robados. Pero no son los únicos que van detrás de ese dinero...', trailer_url = 'https://www.youtube.com/watch?v=fzP2Pz3ZEfE' WHERE id_api = 'tt0421054';

UPDATE Contenido SET id_tmdb = 4922, descripcion = 'Un hombre nace con ochenta años y va rejuveneciendo a medida que pasa el tiempo, es decir, en lugar de cumplir años los descumple. Ésta es la historia de un hombre extraordinario, de la gentes que va conociendo, de sus amores, pero sobre todo de su relación con Daisy.', trailer_url = 'https://www.youtube.com/watch?v=IwBdnWO2wXQ' WHERE id_api = 'tt0421715';

UPDATE Contenido SET id_tmdb = 37863, descripcion = 'Los hermanos Edward y Alphonse Elric, tras intentar resucitar a su madre usando alquimia, sufren terribles consecuencias: Edward pierde su pierna y Alphonse su cuerpo. Con el alma de su hermano sellada en una armadura, Edward se une a las Fuerzas Armadas en busca de una forma de restaurar sus cuerpos.', trailer_url = 'https://www.youtube.com/watch?v=35cs5zFr2h8' WHERE id_api = 'tt0421357';

Serán estos actos del Señor como dice el Padre Cornello, o estará usando el poder de la Piedra Filosofal? Ed y Al investigan para encontrar la verdad.', 24, '2003-10-04');

UPDATE Contenido SET id_tmdb = 9766, descripcion = 'Unos jóvenes recluidos en un centro de detención para menores, bajo el liderazgo de su consejero, intentan ganar autoestima jugando al fútbol americano.', trailer_url = 'https://www.youtube.com/watch?v=BF25qyiEUpU' WHERE id_api = 'tt0421206';

UPDATE Contenido SET id_tmdb = 16608, descripcion = 'Australia, finales del siglo XIX. El capitán Stanley (Winstone) ha capturado a dos jóvenes de la banda de los hermanos Burns. El trato que Stanley le ofrece al hermano mediano coloca a éste frente a un dramático dilema moral: si decide salvar a su hermano menor de morir en la horca, entonces morirá su hermano mayor.', trailer_url = 'https://www.youtube.com/watch?v=BL9l9W49SRY' WHERE id_api = 'tt0421238';

UPDATE Contenido SET id_tmdb = 11460, descripcion = 'Lisa Reisert vuela a Miami. Poco después del despegue, Jackson, su compañero de asiento, le revela la razón de su presencia a bordo: él es el artífice de un complot para matar al Comisionado de Homeland Security, y Lisa es la clave para llevarlo a cabo. Si ella se niega a cooperar, Jackson ordenará que maten a su padre. Atrapada en el avión, Lisa buscará desesperadamente una forma de eludir a Jackson y evitar un asesinato inminente.', trailer_url = 'https://www.youtube.com/watch?v=Z9M9mkcyO48' WHERE id_api = 'tt0421239';

UPDATE Contenido SET id_tmdb = 11565, descripcion = 'Malcolm Turner, el agente del FBI que maestro en el arte del disfraz, vuelve a tener que transformarse en una señora mayor, amiga de pasarlo bien, conocida como la Gran Abuela. Pero ahora será aún más atrevida, más oronda y estupenda si cabe, para evitar un gran desastre para la seguridad nacional. Aunque salvar a su país va a ser ahora el menor de sus problemas, pues ha de aceptar un último desafío: ser la niñera y ama de llaves de la disfuncional familia del sospechoso.', trailer_url = 'https://www.youtube.com/watch?v=345vOvSvGPw' WHERE id_api = 'tt0421729';

UPDATE Contenido SET id_tmdb = 1887, descripcion = 'Francia, siglo XVIII. El compromiso matrimonial entre el futuro Luis XVI (Schwartzman) y María Antonieta (Dunst) sirve para sellar una alianza entre Francia y Austria. Con sólo catorce años, la ingenua princesa austríaca se ve obligada a abandonar Viena, su familia y sus amigos para instalarse en la opulenta, sofisticada y libertina corte francesa, donde reinan las intrigas y los escándalos. La joven se rebela contra el aislamiento que representa la corte de Versalles y se convierte en la reina más incomprendida de Francia.', trailer_url = 'https://www.youtube.com/watch?v=yBWyKRoh98U' WHERE id_api = 'tt0422720';

UPDATE Contenido SET id_tmdb = 9408, descripcion = 'Los pingüinos, que como todo el mundo sabe inventaron el surf, se enfrentan en una arriesgada y espectacular competición: la "Copa Mundial de Surf de Pingüinos". El adolescente pingüino Rockhopper, Cody Maverick, es un surfero en ciernes que se introduce en su primera competición profesional. Seguido por un equipo de cámara para documentar sus experiencias, Cody deja su familia y su hogar en Shiverpool, la Antártida, para viajar a la isla de Pen Gu para el Campeonato de Surf en Memoria de Big Z. En el camino, Cody conoce al surfero de Sheboygan, Chicken Joe, al famoso promotor de surf Reggie Belafonte, el cazatalentos de surf Mikey Abromowitz, y la enérgica vigilante Lani Aliikai, que reconocen la pasión de Cody por el surf, aunque en ocasiones esté un poco mal encauzado. Cody cree que esa voluntad para ganar le dará la admiración y el respeto que desea, pero cuando inesperadamente se enfrenta con un viejo surfero acabado, Cody empieza a encontrar su propio camino...', trailer_url = 'https://www.youtube.com/watch?v=7mPdQRXFiPA' WHERE id_api = 'tt0423294';

UPDATE Contenido SET id_tmdb = 1280, descripcion = 'Tae-suk es un indigente que lleva una vida espectral. Ocupa temporalmente viviendas cuyos habitantes sabe que están ausentes. No roba ni ocasiona daños en los hogares de sus involuntarios anfitriones. En realidad, es una especie de fantasma que duerme en camas ajenas, come algo de las neveras de esos extraños y retribuye su forzada hospitalidad haciendo la colada o arreglando alguna que otra avería doméstica. Sun-hwa, que en tiempos fue una hermosa modelo, se ha visto convertida en una sombra viviente por un marido que la maltrata, encerrándola en una casa ostentosa. El destino cruza los caminos de Tae-suk y Sun-hwa, aunque sus existencias están abocadas a no dejar huella en el mundo. Se conocen cuando Tae-suk entra en casa de Sun-hwa, y en seguida saben que son almas gemelas. Como si estuvieran unidos por vínculos invisibles, descubren que no pueden separarse y aceptan en silencio su nuevo y extraño destino.', trailer_url = 'https://www.youtube.com/watch?v=S-S5n0JniDw' WHERE id_api = 'tt0423866';

UPDATE Contenido SET id_tmdb = 1063, descripcion = 'Dos guerreros samurai rivales están lejos de ser amigos, pero sus caminos se cruzan cuando se embarcan en una búsqueda con Fuu, una camarera, para encontrar un misterioso samurai.', trailer_url = 'https://www.youtube.com/watch?v=Un7P24YU8OE' WHERE id_api = 'tt0423731';

UPDATE Contenido SET id_tmdb = 11619, descripcion = 'No cabe duda de que Roddy es una «rata de la alta sociedad» que vive como un rey en un piso de Kensington atendido por dos mayordomos, los hámsteres Gilbert y Sullivan. Pero cuando una vulgar rata de alcantarilla llamada Sid aparece por la pila de la cocina y decide que esto es jauja, a Roddy no le queda más remedio que deshacerse del intruso atrayéndole hacia el «remolino».', trailer_url = 'https://www.youtube.com/watch?v=aTKPz4CZOmY' WHERE id_api = 'tt0424095';

UPDATE Contenido SET id_tmdb = 8669, descripcion = 'Un adolescente (Anton Yelchin) de una familia sin problemas económicos entra a estudiar a un instituto público. Incapaz de adaptarse a su nuevo entorno, encontrará, gracias al director del centro (Robert Downey Jr.), la manera de encajar, al ser nombrado el psicólogo de su curso, es decir, la persona para mediar entre estudiantes en conflicto.', trailer_url = 'https://www.youtube.com/watch?v=b_DVwLq0wn0' WHERE id_api = 'tt0423977';

UPDATE Contenido SET id_tmdb = 2652, descripcion = 'Un fotógrafo de 32 años queda con una chica adolescente a la que ha conocido a través de Internet. Después de tomar un café, la lleva a su casa con el propósito de hacerle unas fotos. Sin embargo, la joven no ha quedado con él por casualidad...', trailer_url = 'https://www.youtube.com/watch?v=jsks-8PpOw8' WHERE id_api = 'tt0424136';

UPDATE Contenido SET id_tmdb = 2295, descripcion = 'Dante Hicks y Randal Graves, dependientes de una tienda de barrio de Nueva Jersey y mejores amigos, se ven forzados a buscarse un nuevo empleo en el universo de la comida rápida, siempre acompañados de sus actitudes desafiantes, sus escandalosas vulgaridades y su desenfrenada pasión por tocar las narices a los clientes.', trailer_url = 'https://www.youtube.com/watch?v=qb1aTek0NRE' WHERE id_api = 'tt0424345';

UPDATE Contenido SET id_tmdb = 11665, descripcion = 'Adaptación de la serie de televisión de los años 60 "Superagente 86" interpretada por Don Adams y Barbara Feldon. Steve Carell interpreta al despistado y atolondrado Superagente 86 de la agencia de inteligencia gubernamental CONTROL, que lucha contra las fuerzas del mal encarnadas en KAOS, la agencia rival. Dicho agente siempre va acompañado de su compañera, la agente 99.', trailer_url = 'https://www.youtube.com/watch?v=-fYuByCXniA' WHERE id_api = 'tt0425061';

UPDATE Contenido SET id_tmdb = 14199, descripcion = 'Mientras pasa las vacaciones solo, los héroes imaginarios (amigos con superpoderes) de un chico con mucha imaginación cobran vida y le invitarán a pasar múltiples aventuras.', trailer_url = 'https://www.youtube.com/watch?v=mJP65NQwII8' WHERE id_api = 'tt0424774';

UPDATE Contenido SET id_tmdb = 9750, descripcion = 'Un antiguo campeón de ping pong es reclutado por el gobierno de los EE.UU. para participar en un torneo en China tras el cual se esconde una supuesta red criminal.', trailer_url = 'https://www.youtube.com/watch?v=UAZUiH5wJhI' WHERE id_api = 'tt0424823';

UPDATE Contenido SET id_tmdb = 4441, descripcion = 'Historia de una apasionada, duradera y autodestructiva relación amorosa. Candy es una joven y bella artista cuya ansia de vida la lleva al extremo de la cordura. Dan, es un poeta perdido enamorado de Candy. Ellos encuentran en la heroína un camino de placer ilimitado. Pero cuando la adicción domina ellos pierden lo que habían encontrado. Candy abre la puerta a una visión de ensueño que tendrá significado para aquellos que se han sentido deslumbrados por la belleza del mundo.', trailer_url = 'https://www.youtube.com/watch?v=tdo-bnAM3Po' WHERE id_api = 'tt0424880';

UPDATE Contenido SET id_tmdb = 9794, descripcion = 'Cuando dos trabajadores de unos grandes almacenes se enteran que la dependienta más "cañón" de la tienda tendrá una cita con el que sea nombrado "empleado del mes", ambos se pondrán manos a la obra para conseguir el preciado trofeo. De los productores de "De boda en boda" (Wedding Crashers).', trailer_url = 'https://www.youtube.com/watch?v=uq96WOiaL08' WHERE id_api = 'tt0424993';

UPDATE Contenido SET id_tmdb = 4638, descripcion = 'Nicholas Angel es, sin duda alguna, el mejor policía de Londres. Sus detenciones superan en un 400% al segundo mejor agente del Cuerpo. Es tan bueno que, comparado a él, cualquier poli es malo. Por eso sus superiores deciden trasladarle a un lugar en que su talento no ponga a nadie en evidencia, a Sandford, un aparentemente adormecido y pacífico pueblecito.', trailer_url = 'https://www.youtube.com/watch?v=274AoVIRoPA' WHERE id_api = 'tt0425112';

UPDATE Contenido SET id_tmdb = 9007, descripcion = 'David alquila un pintoresco piso en San Francisco y lo que menos espera -y quiere- es compartirlo. Ya lo tiene casi desordenado a su gusto cuando aparece una bonita chica, aunque bastante mandona, llamada Elizabeth que insiste en que el piso es suyo. David piensa que ha habido un enorme malentendido... hasta que Elizabeth desaparece tan misteriosamente como ha llegado. Nada, ni siquiera cambiar la cerradura, impide que Elizabeth entre y salga a su antojo, principalmente para regañar a David por ensuciar "su" piso.', trailer_url = 'https://www.youtube.com/watch?v=pLp2tgybrKA' WHERE id_api = 'tt0425123';

UPDATE Contenido SET id_tmdb = 186, descripcion = 'A Slevin la vida no le ha ido nada bien. Su casa acaba de ser declarada en ruinas y ha sorprendido a su novia en la cama con otro. En un intento por perder de vista Los Ángeles durante un tiempo, se marcha a vivir a Nueva York al apartamento de su amigo Nick Fisher. Pero dos de los peores gángsteres de la ciudad, El Rabino y El Jefe, antiguos socios y ahora enemigos irreconciliables, se cruzarán en su vida cuando uno de ellos pretenda vengar la muerte de su hijo asesinando al primogénito del otro. La idea para no desencadenar una guerra de bandas: buscar a un jugador que le deba mucho dinero al Jefe y obligarle a matar al hijo del Rabino.', trailer_url = 'https://www.youtube.com/watch?v=oYOiObTFtNk' WHERE id_api = 'tt0425210';

UPDATE Contenido SET id_tmdb = 12289, descripcion = 'En China, hacia el final de la Dinastía Han (208 d.C.) Cao Cao, el temible Primer Ministro (y gobernante de facto) convence al veleidoso Emperador Han de que declare la guerra a los reinos de Xu, al oeste y al este, y al reino de Wu, al sur. Su objetivo, según dice, es la unificar China por el bien del país, pero, en realidad, sus motivos son bastante más egoístas. Tras convencer al Emperador, Cao Cao lleva a su ejército de casi un millón de soldados a la guerra. Su primer objetivo es el Reino de Xu, de reciente creación, gobernado por el benevolente líder Liu Bei. Al llegar al Reino de Xu, las fuerzas de Cao Cao, superiores numéricamente, derrotan fácilmente al ejército de Liu Bei. Los ciudadanos de Xu huyen bajo la protección de las tropas de Liu Bei y de sus dos generales de mayor rango (y hermanos de sangre): Guan Yu y Zhang Fei, que se quedan atrás a riesgo de sus propias vidas para salvar a los campesinos que intentan escapar', trailer_url = 'https://www.youtube.com/watch?v=zqISkKZVZiY' WHERE id_api = 'tt0425637';

UPDATE Contenido SET id_tmdb = 7942, descripcion = 'Dennis es un tío normal. Está un poco gordo y fuma, pero es buena persona, encantador y sencillo. Sin embargo, hace cinco años, Dennis hizo algo que no estuvo bien. El día en que debía casarse con Libby, su novia embarazada, se dio a la fuga. No pudo seguir adelante con la boda. No se sentía merecedor de Libby, entonces decidió que en vez de arruinarle la vida, era mejor arruinarle su gran día. Hoy, cinco años después, Dennis se da cuenta de que ha cometido un gran error. Aún está enamorado de Libby.', trailer_url = 'https://www.youtube.com/watch?v=OnJkCPpIngs' WHERE id_api = 'tt0425413';

UPDATE Contenido SET id_tmdb = 5123, descripcion = 'Un joven guitarrista irlandés (Jonathan Rhys Meyers) y una violonchelista (Keri Russell) pasan una romántica e inolvidable noche de verano en Nueva York, pero el azar los separa. De su breve encuentro nace August (Freddie Highmore), un niño que, por un destino fatal, va a parar a un orfanato, donde pasa una dura infancia. Con sólo once años, se gana la vida como músico callejero, bajo la tutela de un siniestro y extraño personaje (Robin Williams) que trata de explotarlo. El niño pronto se revela como un músico genial, un nuevo Mozart, que se servirá de su talento para encontrar a sus padres.', trailer_url = 'https://www.youtube.com/watch?v=wH7bq_RjJqg' WHERE id_api = 'tt0426931';

UPDATE Contenido SET id_tmdb = 7457, descripcion = 'Johnny es un muchacho de 19 años, de buena familia, que vive pasando droga en Los Angeles. Es el dueño de su propia casa y de varios coches, tiene una vida de lo más acomodada y le encanta irse de juerga. Cuando Jake, uno de sus colegas, no le pague un dinero que le debe, Johnny secuestrará a su hermano de 15 años, Butch y a pesar de que Butch tendrá diversas oportunidades para poder escaparse, decidirá no hacerlo porque se lo está pasando en grande con Johnny… todo parecerá ir dentro de cierto orden, hasta que sucede algo terrible.', trailer_url = 'https://www.youtube.com/watch?v=ox6CYE4o7cg' WHERE id_api = 'tt0426883';

UPDATE Contenido SET id_tmdb = 11918, descripcion = 'Parodia de las películas de superhéroes, desde Spider-Man, hasta Batman Begins o Los 4 Fantásticos, de nuevo a cargo de los creadores de "Scary Movie". En esta ocasion la historia se centra en Rick Riker, un joven agradable pero muy torpe que adquiere superpoderes.', trailer_url = 'https://www.youtube.com/watch?v=9QDtDtj0WcM' WHERE id_api = 'tt0426592';

UPDATE Contenido SET id_tmdb = 38778, descripcion = 'Trata de las peripecias de un grupo de amigos que se reúne semanalmente para cenar. La originalidad de su plan reside en que cada uno debe llevar a la cena al tipo más idiota que haya sido capaz de encontrar y el que lo consiga, será el ganador de la noche... Remake del popular film francés de Francis Veber de 1998.', trailer_url = 'https://www.youtube.com/watch?v=CVY_IRA8NTw' WHERE id_api = 'tt0427152';

UPDATE Contenido SET id_tmdb = 6877, descripcion = 'Tripp (McConaughey) es un atractivo soltero que, a sus 35 años, todavía vive con sus padres (Kathy Bates y Terry Bradshaw). Hartos de la situación, éstos deciden contratar los servicios de una joven motivadora profesional (Sarah Jessica Parker) que debe convencerlo de que ya es hora de que se independice.', trailer_url = 'https://www.youtube.com/watch?v=4KZM3PRV0NM' WHERE id_api = 'tt0427229';

UPDATE Contenido SET id_tmdb = 4858, descripcion = 'Remake de "La invasión de los ladrones de cuerpos". Tras la catástrofe de un transbordador espacial que se estrella contra la Tierra, una misteriosa epidemia comienza a alterar el comportamiento de los seres humanos. Una psiquiatra de Washington descubre junto con varios científicos, que el origen de la epidemia es extraterrestre. Entonces, en una carrera contra reloj para no ser "infectada", deberá luchar para proteger a su hijo, ya que es posible que él sea la clave para detener la creciente invasión.', trailer_url = 'https://www.youtube.com/watch?v=QsFHAg9Ij-0' WHERE id_api = 'tt0427392';

UPDATE Contenido SET id_tmdb = 501, descripcion = 'Entre 1990 y 2003, Timothy Treadwell, camarero, actor ocasional y ex-alcohólico, pasó catorce veranos conviviendo con los osos grizzly. Él mismo grabó con su cámara de vídeo sus estancias en Alaska y su obsesiva relación con los plantígrados (unas cien horas). Werner Herzog usó parte de este material. El último verano, uno de los osos atacó a Timothy y a su novia Annie.', trailer_url = 'https://www.youtube.com/watch?v=2TIhtJysixg' WHERE id_api = 'tt0427312';

UPDATE Contenido SET id_tmdb = 14047, descripcion = 'Drama basado en la historia real de Mel Tolson, un profesor de Historia Afroamericana en el Wiley College de Texas, quien en 1935 inspiró a sus estudiantes a formar el primer equipo de debate del colegio, que luego se enfrentaría en la final a la universidad de Harvard en el campeonato nacional.', trailer_url = 'https://www.youtube.com/watch?v=IN2AGZThL-8' WHERE id_api = 'tt0427309';

UPDATE Contenido SET id_tmdb = 2976, descripcion = 'Tracy Turnblad, una chica cuya única pasión es el baile, sueña con participar en "El Show de Corny Collins", el programa de baile más importante de Baltimore. El único problema de Tracy es que tiene una figura más bien generosa, cosa que le recuerdan siempre su novio y su dominante madre. Pero nada detendrá a Tracy, pues está segura de que ha nacido para bailar... Remake del musical "underground" de John Waters.', trailer_url = 'https://www.youtube.com/watch?v=hsFtWsRn99U' WHERE id_api = 'tt0427327';

UPDATE Contenido SET id_tmdb = 8270, descripcion = 'Chris Pratt (Joseph Gordon-Levitt), una antigua estrella del deporte en el instituto, ve cómo su vida da un trágico giro cuando tiene un grave accidente de coche en el que mueren su mejor amigo y la novia de éste. En el accidente además su novia pierde una pierna, y él sufre una herida en la cabeza que le reduce su coeficiente de inteligencia, le impide recordar cosas y le obliga a anotar las cosas más simples en un cuaderno. Pasado el tiempo Chris consigue un trabajo en un banco como recepcionista, y una banda de criminales le intentará recrutar para que les ayude en un golpe.', trailer_url = 'https://www.youtube.com/watch?v=e9oyHy_ZigY' WHERE id_api = 'tt0427470';

UPDATE Contenido SET id_tmdb = 9388, descripcion = 'Nick Naylor, jefe de prensa de una gran compañía de tabaco, dedica su vida a defender los derechos de los fumadores en medio de la cultura neo-puritana dominante. Enfrentado a grupos de defensa de la salud y a un oportunista senador, Nick pasa a la ofensiva como relaciones públicas del consumo de cigarrillos, pero al mismo tiempo comienza a pensar en la imagen que está dando a su hijo pequeño Joey.', trailer_url = 'https://www.youtube.com/watch?v=Df32RijORLo' WHERE id_api = 'tt0427944';

UPDATE Contenido SET id_tmdb = 34544, descripcion = '"Me encanta que los planes salgan bien" es la frase identificativa del Coronel Hannibal Smith, el líder de "El Equipo A", una unidad especial de veteranos de la guerra de Iraq, antiguos soldados de las Fuerzas Especiales que fueron acusados de un crimen que no cometieron. Ellos son Hannibal, un experto planificador de misiones ingeniosas que requieren una reacción en una fracción de segundo, habilidades especiales y un equipo de soldados competentes... y excéntricos; Templenton ''Fénix'' Peck quien puede conseguir cualquier cosa para las actividades poco ortodoxas y audaces del Equipo; M.A. Barracus, el conductor y músculo del Equipo; y Murdock, un piloto excepcional y loco acreditado. La Capitana Charisa es un antiguo ligue de Fénix que ahora persigue a El Equipo A por un crimen que no cometieron y Lynch es un misterioso agente de la CIA que juega un papel importante en la misión más explosiva del Equipo.', trailer_url = 'https://www.youtube.com/watch?v=YJSL-4OOlDs' WHERE id_api = 'tt0429493';

UPDATE Contenido SET id_tmdb = 1667, descripcion = 'Documental sobre la emigración de los pinguinos en la Antártida. Cada año en la Antártida da comienzo un emocionante y hermoso viaje. Cientos de miles de pingüinos Emperador abandonan la seguridad del océano para adentrarse en la desértica tierra helada. Una región tan dura y extrema que ningún otro ser vivo se atreve a habitar. Toda la comunidad de Pingüinos marchan a través de este difícil paisaje de hielo. Con resolución y valentía conducidos por su necesidad de reproducirse con el fín de la supervivencia de la especie. Esta es la historia de una familia de pingüinos.', trailer_url = 'https://www.youtube.com/watch?v=JZWt5YkhVp8' WHERE id_api = 'tt0428803';

UPDATE Contenido SET id_tmdb = 8292, descripcion = 'Después del asesinato de su madre adoptiva en un atraco, los hermanos Mercer -el impulsivo Bobby (Mark Wahlberg), el seductor Angel (Tyrese Gibson), el padre de familia y hombre de negocios Jeremiah (André Benjamin) y el roquero duro Jack (Garrett Hedlund) - se reúnen de nuevo para aclarar su muerte. Ya en la pista del asesino, no tardan en darse cuenta de que su habitual comportamiento tiene nuevas consecuencias. En este drama de acción basado en la fuerza de los personajes dirigido por John Singleton (Los chicos del barrio, 2 Fast 2 Furious/A todo gas 2) y producido por Lorenzo di Bonaventura (Constantine), cuatro hermanos descubren que les une algo mucho más poderoso que la sangre.', trailer_url = 'https://www.youtube.com/watch?v=kQYR1sIFM48' WHERE id_api = 'tt0430105';

UPDATE Contenido SET id_tmdb = 14191, descripcion = 'Claire y Hailey son dos grandes amigas de 13 años que se embarcan en la aventura de sus vidas cuando, después de una gran tormenta, descubren a una sirena llamada Aquamarine dentro de una piscina. La sirena, de 18 años, guapa y de pelo azul, ha abandonado su hogar justo antes de su matrimonio arreglado en busca del amor verdadero. Si logra demostrar a su padre que ese tipo de amor no es un mito, la dejará cancelar la boda bajo el agua; pero solo le ha dado tres días. Aqua reclama la ayuda de Claire y Hailey, quienes supuestamente son dos grandes expertas en el tema, las cuales se han instruido a través de las páginas de las revistas que leen y citan a diario.', trailer_url = 'https://www.youtube.com/watch?v=UhzXwfatkvk' WHERE id_api = 'tt0429591';

UPDATE Contenido SET id_tmdb = 82, descripcion = 'En Miami, ciudad en la que los barones de la droga procedentes del Tercer Mundo se codean con industrias corporativas de miles de millones de dólares, “Sonny” Crockett y Ricardo Tubbs, se enteran de que un soplo en las altas esferas ha causado la muerte de dos agentes federales y la masacre de una familia. La investigación de los dos detectives no tarda en llevarlos ante la puerta de los brutales asesinos de la Hermandad Aria y de una sofisticada red de traficantes globalizados protegidos internacionalmente.', trailer_url = 'https://www.youtube.com/watch?v=z54CddJ1GSA' WHERE id_api = 'tt0430357';

UPDATE Contenido SET id_tmdb = 9072, descripcion = 'Tras salir de prisión, el enano criminal Calvin Sims se une a su hermano Percy, el imbécil, para robar un enorme y costoso diamante de una joyería para el mafioso Walken. La policía los persigue, y Calvin esconde la piedra en el bolso de la ejecutiva Vanessa Edwards, cuyo esposo, Darryl Edwards, desea tener un hijo. Percy convence a Calvin de que se vista como un bebé y lo dejen frente a la casa de los Edwards para entrar y recuperar el diamante. Darryl y Vanessa se quedan con Calvin durante el fin de semana y deciden adoptarlo, mientras Walken amenaza a Darryl para recuperar la piedra.', trailer_url = 'https://www.youtube.com/watch?v=x9STUnqrE_c' WHERE id_api = 'tt0430304';

