UPDATE Contenido SET id_tmdb = 7873, descripcion = 'Una historia de amistad, lealtad y ambición en las duras calles del South Central de Los Ángeles. Jim Davis (Christian Bale) es un ex-ranger, recientemente licenciado del ejército, cuyas experiencias todavía le provocan pesadillas. Mientras busca un puesto en la policía de Los Ángeles que le permita traerse a su novia mejicana a los Estados Unidos para casarse con ella, pasa el tiempo con su mejor amigo, Mike (Freddy Rodriguez). Por su parte, la novia de Mike, la bella Sylvia (Eva Longoria), intenta que no se desvíe del buen camino.', trailer_url = 'https://www.youtube.com/watch?v=XbS7M4-Y87Y' WHERE id_api = 'tt0433387';

UPDATE Contenido SET id_tmdb = 10033, descripcion = 'Chris (Ryan Reynolds) es un buen chico, divertido... gordo y pardillo. El día de la graduación del Instituto decide armarse de valor y confesarle su amor a Jamie (Amy Smart). Pero Jaime le va a partir el corazón: ella le quiere... sólo como amigo. Diez años más tarde, y a muchos kilómetros de distancia de su pueblo natal, Chris se ha convertido en un atractivo y prometedor productor musical. Su éxito con las mujeres le ha hecho olvidar su fracaso con Jamie. O al menos, eso es lo que él cree. Una tormenta invernal en un viaje de negocios con su nueva estrella musical, la ardiente Samantha James (Anna Faris), le obliga a hacer escala en su antiguo pueblo de New Jersey. Muy a su pesar, va a reencontrarse con su familia, sus amigos... y con Jamie.', trailer_url = 'https://www.youtube.com/watch?v=vIBBVzy5UoQ' WHERE id_api = 'tt0433400';

UPDATE Contenido SET id_tmdb = 578, descripcion = 'Los hermanos Ridley y Tony Scott han creado una serie de detectives, que recurren a las matemáticas para resolver crímenes. ¿Cómo detener a un violador que ha comenzado a asesinar a sus víctimas? ¿Cómo desmantelar una banda de asaltantes de bancos? ¿En qué parte de Los Ángeles se habrá liberado un virus en un ataque terrorista? Ni el FBI ni la CIA tienen la respuesta. La solución está en manos de Charlie, un joven matemático, que con fórmulas y ecuaciones resuelve todos los casos en los que lo inmiscuye Don, su hermano, que sí trabaja para el FBI.', trailer_url = 'https://www.youtube.com/watch?v=ZwURPCvrtks' WHERE id_api = 'tt0433309';

UPDATE Contenido SET id_tmdb = 30984, descripcion = 'La serie narra las aventuras de Ichigo Kurosaki, un adolescente que tiene la facultad de interactuar con los espíritus. Una noche, Ichigo se encuentra con una shinigami —personificación japonesa del Dios de la muerte— llamada Rukia Kuchiki, quien se sorprende que pueda verla. Sin embargo, su conversación es interrumpida por la aparición de un hollow, un espíritu maligno. Después de que Rukia fuera gravemente herida al tratar de proteger a Ichigo, esta intenta traspasarle parte de sus poderes a Ichigo para que pueda enfrentarse al hollow en igualdad de condiciones. No obstante, Ichigo sin darse cuenta los absorbe casi por completo y logra vencer con facilidad al espíritu.', trailer_url = 'https://www.youtube.com/watch?v=mnFXQUq-7ks' WHERE id_api = 'tt0434665';

UPDATE Contenido SET id_tmdb = 10193, descripcion = 'Sabiendo que su dueño Andy, que ya no es un niño, se prepara para ir a la universidad, el vaquero Woody, el astronauta Buzz y el resto de sus amigos juguetes comienzan a preocuparse ante su incierto futuro. Efectivamente todos acaban en una guardería, donde por ejemplo la muñeca Barbie conocerá al guapo Ken. Esta reunión de nuestros amigos con otros nuevos juguetes no será sino el inicio de un montón de trepidantes y divertidas aventuras.', trailer_url = 'https://www.youtube.com/watch?v=xkPhZHt5TKM' WHERE id_api = 'tt0435761';

UPDATE Contenido SET id_tmdb = 9392, descripcion = 'Seis amigas se reúnen en una remota montaña para emprender una expedición espeleológica. Juno, que dirige al grupo es dura, persuasiva y peligrosa. Las demás son las hermanastras Rebecca y Sam, Holly y Beth, una profesora de inglés que va a regañadientes para cuidar de Sarah. Ésta se está recuperando de un colapso mental causado por la muerte de su marido y su hijo un año antes. El grupo queda atrapado en una cueva cuando una roca se desprende y bloquea la salida. Mientras buscan otra salida en medio de un laberinto de túneles, son perseguidas por una raza de hambrientos depredadores.', trailer_url = 'https://www.youtube.com/watch?v=2S0ImYzRxKE' WHERE id_api = 'tt0435625';

UPDATE Contenido SET id_tmdb = 227156, descripcion = 'Jonás es un chico de doce años que vive en una sociedad, basada en la Monotonía y la Igualdad, que ha conseguido eliminar el dolor y los sentimientos. Jonas es seleccionado como "Receptor de la Memoria"; su misión consiste en almacenar todos los recuerdos de la época anterior a la implantación del régimen de la Monotonía. Ese depósito de la memoria podría ser necesario en caso de que los líderes necesitaran tomar decisiones en las que la experiencia fuera un factor decisivo. Muy pronto Jonas se dará cuenta de lo superficial que es la vida en su comunidad.', trailer_url = 'https://www.youtube.com/watch?v=fMUli947oIE' WHERE id_api = 'tt0435651';

UPDATE Contenido SET id_tmdb = 19585, descripcion = 'Mezcla de acción real y efectos CGi -por ordenador-, la historia se centra en un comando de animales ultrainteligentes que trabajan para una agencia del gobierno intentando prevenir que un malvado millonario se apodere del mundo. En versión original contará con la voces, entre otros, de Nicolas Cage, Jon Favreau, Steve Buscemi y Penélope Cruz.', trailer_url = 'https://www.youtube.com/watch?v=x66vnAYCru0' WHERE id_api = 'tt0436339';

UPDATE Contenido SET id_tmdb = 1738, descripcion = 'Cris Johnson es un mago de Las Vegas bendecido con un don que también es una maldición: cuenta con la sobrenatural capacidad de saber qué va a ocurrir a continuación. Johnson puede ver el futuro unos cuantos minutos más allá del momento presente, un talento extrasensorial que, sin duda, le viene muy bien para su trabajo como mago y mentalista en un sórdido club de Las Vegas donde actúa cada noche. Por otra parte, la agente antiterrorista Callie Ferris, quiere sacar partido al talento de Johnson con objeto de impedir el ataque que unos terroristas planean ejecutar contra Los Angeles mediante un arma de destrucción masiva. La cuenta atrás de la bomba prosigue y Johnson sería un elemento clave a la hora de impedir un holocausto nuclear. Si no recurre a sus poderes para canalizar su visión a través de los portales temporales correctos para así poder modificar el presente, su futuro – y el de cientos de miles de personas – podría ser una cosa del pasado.', trailer_url = 'https://www.youtube.com/watch?v=wOLv3cqeolk' WHERE id_api = 'tt0435705';

UPDATE Contenido SET id_tmdb = 1165, descripcion = 'Relato de los sucesos políticos acaecidos tras la muerte de la princesa Diana. Se centra sobre todo en las conversaciones que mantuvieron la Reina Isabel y el Primer Ministro Tony Blair para llegar a un acuerdo sobre la petición popular de que se celebrara un duelo nacional.', trailer_url = 'https://www.youtube.com/watch?v=BIvESE9A_gc' WHERE id_api = 'tt0436697';

UPDATE Contenido SET id_tmdb = 399579, descripcion = 'Ido, un compasivo médico de cíborgs, encuentra a Alita abandonada en el desguace de Iron City. Cuando Alita despierta, no sabe quién es, ni reconoce el mundo en el que se encuentra, todo es nuevo para ella. Ido intentará proteger a Alita de su misterioso pasado, mientras que su nuevo amigo Hugo le ayudará a despertar sus recuerdos. En ese momento, Alita descubre que posee habilidades de combate extraordinarias, que podría usar para salvar a su nueva familia y amigos. Decidida a encontrar la verdad tras sus orígenes, Alita comienza un viaje que le enfrentará a las injusticias de un mundo oscuro y corrupto, descubriendo que sólo ella puede cambiarlo.', trailer_url = 'https://www.youtube.com/watch?v=MjIdm3Qzbc4' WHERE id_api = 'tt0437086';

UPDATE Contenido SET id_tmdb = 9957, descripcion = 'Tres peculiares amigos, que se consideran unos perdedores, intentan resarcirse de las oportunidades perdidas en su infancia, cuando sólo calentaban el banquillo (benchwarmers), fundando un equipo de béisbol. Empezarían por desafiar a un equipo de una escuela primaria, pero, en caso de conseguir la victoria, podrían enfrentarse a los mejores equipos infantiles del estado. Y no sólo eso: se convertirían en un ejemplo para todos los niños frustrados por su condición de "calientabanquillos".', trailer_url = 'https://www.youtube.com/watch?v=TXVboydkkOI' WHERE id_api = 'tt0437863';

