UPDATE Contenido SET id_tmdb = 298618, descripcion = 'Cuando su intento de salvar a su familia altera sin darse cuenta el futuro, Barry Allen queda atrapado en una realidad en la que el General Zod ha regresado y no hay superhéroes a quienes recurrir. Para salvar el mundo en el que se encuentra y regresar al futuro que conoce, la única esperanza de Barry es correr por su vida. Pero, ¿será suficiente hacer el sacrificio máximo para restablecer el universo?', trailer_url = 'https://www.youtube.com/watch?v=mUSFzSvsy8A' WHERE id_api = 'tt0439572';

UPDATE Contenido SET id_tmdb = 534, descripcion = 'Nueva entrega de la saga de Terminator, que transcurre en un post-apocalíptico 2018, tras el día del Juicio Final. John Connor es el hombre destinado a liderar la resistencia de los humanos contra Skynet y su ejército de Terminators. Pero el futuro en el que a Connor le enseñaron a creer se ve alterado en parte por la aparición de Marcus Wright, un extraño cuyo último recuerdo es haber estado en el corredor de la muerte, y que afirma haber estado con Kyle Reese, el padre de John. Connor debe decidir si Marcus ha sido enviado desde el futuro o rescatado del pasado, todo en una carrera contrareloj mientras la Resistencia prepara su ataque final contra el corazón del centro de operaciones de Skynet.', trailer_url = 'https://www.youtube.com/watch?v=DfpWaRfN35w' WHERE id_api = 'tt0438488';

UPDATE Contenido SET id_tmdb = 2503, descripcion = 'Jason Bourne sigue investigando quién es y qué hay realmente detrás del programa secreto de la CIA llamado Treadstone. Ahora un reportero británico de "The Guardian" le pone sobre una nueva pista con el nombre de Blackbriar. Bourne dará con él en Londres, en un intento de encajar las últimas piezas de ese pasado que él aún intenta recuperar.', trailer_url = 'https://www.youtube.com/watch?v=ohkW_xbPl9A' WHERE id_api = 'tt0440963';

UPDATE Contenido SET id_tmdb = 9035, descripcion = 'Wheelsy es un pueblo soñoliento de Estados Unidos, pintoresco y tranquilo. Sus simpáticos habitantes no meten las narices donde no les llaman. Pero por debajo de este bonito barniz se esconde algo sin nombre, malévolo, y ese algo crece. Nadie parece darse cuenta de que cada vez hay más avisos de animales de compañía perdidos ni que Grant Grant , uno de los ciudadanos más prósperos del pueblo, empieza a comportarse de un modo muy raro. Pero cuando el ganado aparece horriblemente mutilado y una joven desaparece, el sheriff Bill Pardy y sus hombres, con la ayuda de la esposa de Grant, Starla descubren la existencia de una fuerza oscura que asedia el pueblo.', trailer_url = 'https://www.youtube.com/watch?v=ETn_HSKRXV4' WHERE id_api = 'tt0439815';

UPDATE Contenido SET id_tmdb = 9502, descripcion = 'El protagonista es un oso panda llamado Po, el más vago de todas las criaturas del Valle de la Paz. Con poderosos enemigos acercándose, la esperanza es depositada en una antigua profecía que dice que un héroe se alzará para salvarles. Voces originales de Jack Black, Angelina Jolie, Dustin Hoffman, Lucy Liu & Jackie Chan.', trailer_url = 'https://www.youtube.com/watch?v=vRhMIpFu-Zw' WHERE id_api = 'tt0441773';

UPDATE Contenido SET id_tmdb = 17111, descripcion = 'Avanzada la noche, en una carretera rural, Tun y Jane atropellan accidentalmente a un misterioso peatón. Huyen de la escena y regresan a su quehacer cotidiano en Bangkok. Sin embargo, algunos fenómenos sin explicación empiezan a convertir su vida en una pesadilla constante. Jane se ve asediada por terribles sueños. Tun, fotógrafo de profesión, percibe extrañas figuras espectrales que empiezan a aparecer en sus fotografías. Cuando deciden regresar al lugar del accidente para investigar, no queda ningún rastro de la víctima ni noticia alguna sobre su desaparición o sobre el descubrimiento del cadáver. Sin embargo, uno a uno, van muriendo los amigos más próximos de Tun. Tanto él como Jane saben muy bien que deben resolver este misterio antes de que sea éste el que destruya sus propias vidas.', trailer_url = 'https://www.youtube.com/watch?v=MLgI_g9tdnQ' WHERE id_api = 'tt0440803';

UPDATE Contenido SET id_tmdb = 709, descripcion = 'Popular serie americana de animación stop-motion, que parodia películas, videojuegos o personalidades de todo el mundo a través de humor mordaz.', trailer_url = 'https://www.youtube.com/watch?v=yD0li2eQbJQ' WHERE id_api = 'tt0437745';

UPDATE Contenido SET id_tmdb = 57243, descripcion = 'Doctor Who es una serie de televisión británica de ciencia ficción producida por la BBC. El programa muestra las aventuras de un Señor del Tiempo conocido como "El Doctor", que explora el universo en su TARDIS, una nave espacial con conciencia propia capaz de viajar a través del tiempo y el espacio. Con la ayuda de distintos acompañantes, el Doctor se enfrenta a una variedad de enemigos mientras salva civilizaciones, visita tanto el pasado como el futuro, ayuda a gente común y corrige injusticias.', trailer_url = 'https://www.youtube.com/watch?v=2V_xYubUJFo' WHERE id_api = 'tt0436992';

Mientras tanto, hay otras preguntas sin responder: ¿Podrá confiarse en que Ambrose mantendrá viva a Alaya? ¿Qué le sucede a la herida de Tony Mack? ¿Son los Silurianos los responsables de las tumbas vacías? ¿Qué le esperará a Mo y a Amy cuando un doctor Siluriano intente ver cómo funcionan sus cuerpos?', 46, '2010-05-29');

Una segunda ola golpea el lugar y los "Gangers" se separan del control de los originales. Estos pueden recordar cada segundo de "sus" vidas y sentir todas las cosas que habían experimentado. ¿Son recuerdos robados o legados? ¿Son los Gangers máquinas defectuosas que deben ser bloqueadas o viven, respiran y son seres conscientes? ¿Convencerá el Doctor a los aterrados humanos para que acepten a estas "casi" personas y evitar una guerra civil sin cuartel?', 44, '2011-05-21');

UPDATE Contenido SET id_tmdb = 219, descripcion = 'El fantasma de la abuela Irene (Carmen Maura) se aparece a sus hijas Raimunda (Penélope Cruz) y Sole (Lola Dueñas), a su nieta Paula (Yohana Cobo), a la tía de las hijas (Chus Lampreave) e incluso a una vecina (Blanca Portillo) en el pueblecito de La Mancha donde viven. La abuela ha vuelto para atar los cabos que le quedaron sueltos en vida.', trailer_url = 'https://www.youtube.com/watch?v=D9u96lQcsHI' WHERE id_api = 'tt0441909';

UPDATE Contenido SET id_tmdb = 2310, descripcion = 'El guerrero Beowulf debe luchar y derrotar al monstruo Grendel, quien está aterrorizando a Dinamarca, y más tarde a la Madre de Grendel, que busca venganza.', trailer_url = 'https://www.youtube.com/watch?v=1m59_fBn6RQ' WHERE id_api = 'tt0442933';

UPDATE Contenido SET id_tmdb = 186, descripcion = 'Ambientada en Agrestic, una ciudad californiana de ficción, la serie narra la historia de Nancy Botwin (Mary-Louise Parker), una madre de familia, cuyo marido Judah (Jeffrey Dean Morgan) ha fallecido reciente y repentinamente, y termina vendiendo marihuana a sus vecinos del barrio residencial donde vive para poder mantener el nivel de vida de clase alta al que está acostumbrada. Su vida gira en torno a sus dos hijos, Shane Botwin (Alexander Gould), un excéntrico y solitario niño de 10 años, y Silas Botwin (Hunter Parrish), un adolescente obsesionado con las relaciones sexuales. Los tres viven en Agrestic, un barrio idílico en apariencia, pero que en realidad oculta oscuros secretos tras las atildadas puertas de sus casas.', trailer_url = 'https://www.youtube.com/watch?v=qZDIH2gbJMM' WHERE id_api = 'tt0439100';

