UPDATE Contenido SET id_tmdb = 72976, descripcion = 'En 1865, mientras la Guerra Civil Americana se acerca a su fin, el presidente Abraham Lincoln propone una enmienda que prohíba la esclavitud en los Estados Unidos. Sin embargo esto plantea un gran dilema: si la paz llega antes de que se apruebe la enmienda, el Sur tendrá poder para rechazarla y mantener la esclavitud; si la paz llega después, decenas de miles de personas seguirán muriendo en el frente. En una carrera contrarreloj para conseguir los votos necesarios, Lincoln se enfrenta a la mayor crisis de conciencia de su vida.', trailer_url = 'https://www.youtube.com/watch?v=dmSZQDTeFTM' WHERE id_api = 'tt0443272';

UPDATE Contenido SET id_tmdb = 496, descripcion = 'Borat, un excéntrico reportero Kazajo, es ordenado por su gobierno a viajar a Estados Unidos para rodar un documental pedagógico, que debe recoger las mejores enseñanzas de los USA para que su país las aproveche. Pero el trabajo no será tan fácil como parece…', trailer_url = 'https://www.youtube.com/watch?v=feU2-Br4cMs' WHERE id_api = 'tt0443453';

UPDATE Contenido SET id_tmdb = 7461, descripcion = 'El presidente de los Estados Unidos viaja a Salamanca para dar una conferencia. En medio del mitin, alguien intenta atentar contra su vida. La historia está contada a través de los ojos de ocho testigos: ocho versiones distintas sobre un único hecho. ¿Qué ocurrió realmente?', trailer_url = 'https://www.youtube.com/watch?v=LGnLCP-lfrA' WHERE id_api = 'tt0443274';

UPDATE Contenido SET id_tmdb = 283350, descripcion = 'Una mujer pierde el tren de la 1:30 de Nueva York a Boston, tras lo cual un músico de la calle pasa la noche tratando de ayudarla a hacer que pueda volver a casa antes de que llegue su marido. A lo largo de la noche aprenden mucho el uno del otro y se enamoran.', trailer_url = 'https://www.youtube.com/watch?v=VrNwcGVGrBw' WHERE id_api = 'tt0443465';

UPDATE Contenido SET id_tmdb = 14636, descripcion = 'Un condenado a muerte es llevado a un reality show en una isla  desierta. Pronto descubrirá que no está solo y que debe luchar a muerte contra otros nueve asesinos. Un violento y sangriento concurso visto en todo el mundo a través de internet. ¡Morir o matar!. Quizás esta pueda ser su única oportunidad de ser libre de nuevo.', trailer_url = 'https://www.youtube.com/watch?v=YZmRuUxRr6M' WHERE id_api = 'tt0443473';

UPDATE Contenido SET id_tmdb = 1125, descripcion = 'Ambientada en los años sesenta y setenta, narra La historia de del ascenso de un trío de mujeres: Effie, Deena y Lorrell, que han formado un grupo prometedor llamado The Dreamettes. El ambicioso agente Curtis Taylor (Jamie Foxx) las descubre durante un concurso musical, y les ofrece la oportunidad de su vida: hacer los coros para el famosísimo James "Thunder" Early (Eddie Murphy). Poco a poco, Curtis empieza a controlar el aspecto físico y la música de las chicas para acabar lanzándolas como The Dreams. Pero los focos no tardan en centrarse en Deena, olvidando e incluso apartando a la menos atractiva Effie. A pesar de que The Dreams se convierten en un auténtico fenómeno de costa a costa, no tardan en darse cuenta de que el precio de la fama y de la fortuna es mucho más elevado de lo que imaginaban...', trailer_url = 'https://www.youtube.com/watch?v=DTgGuFOh2M0' WHERE id_api = 'tt0443489';

UPDATE Contenido SET id_tmdb = 10982, descripcion = 'Todo el mundo conoce el cuento de Caperucita Roja... o eso es lo que se creen. Pero todo está a punto de cambiar pues nadie ha visto hasta ahora el cuento del modo en que aquí se narra. Todo queda patas arriba, reinventado como una comedia disparatada animada por ordenador. Finalmente se desvela, fruto de una profunda investigación, la chocante verdad delictiva que se oculta tras la leyenda. Por fin, conoceremos toda la historia acerca de cómo Caperucita Roja, la Abuelita, el Leñador y el Lobo, acaban siendo sospechosos en un caso que sólo puede resolver el mejor de los detectives.', trailer_url = 'https://www.youtube.com/watch?v=_WGv6Rgp72k' WHERE id_api = 'tt0443536';

UPDATE Contenido SET id_tmdb = 1491, descripcion = 'En la Viena de 1900, el misterioso Eisenheim cautiva al público con sus espectáculos de magia e ilusionismo. Sus poderes sobrenaturales llegan a los oídos del príncipe heredero Leopold, un hombre pragmático que acude a su espectáculo con incredulidad, acompañado de su prometida, la bella y sofisticada Sophie. Sospechando un fraude por parte de Eisenheim, el príncipe encarga al perspicaz inspector de policía Uhl que le vigile de cerca...', trailer_url = 'https://www.youtube.com/watch?v=QngdF-55AGc' WHERE id_api = 'tt0443543';

UPDATE Contenido SET id_tmdb = 4512, descripcion = 'Narra la historia del más famoso forajido del oeste americano, el carismático e impredecible pistolero Jesse James, un bandolero sudista hijo de un predicador. Mientras Jesse planea su próximo gran robo, declara la guerra a sus enemigos, quienes intentan hacerse con la recompensa -y la gloria- que implicaría su captura. Pero la amenaza más importante a su vida puede que venga de aquellos en quienes más confia.', trailer_url = 'https://www.youtube.com/watch?v=SrGmmitc62Q' WHERE id_api = 'tt0443680';

UPDATE Contenido SET id_tmdb = 7840, descripcion = 'Era la época en la que el hombre y la bestia eran salvajes y el gran mamut recorría la Tierra. Una época en la que nacieron las ideas y las creencias que forjaron a la humanidad para siempre. "10.000" narra la historia de un joven cazador (Steven Strait) en su misión de guiar a un ejército a través de un vasto desierto, luchando contra tigres dientes de sable y depredadores prehistóricos, mientras descubre una civilización perdida e intenta rescatar a la mujer que ama.', trailer_url = 'https://www.youtube.com/watch?v=7VpG1ELREOg' WHERE id_api = 'tt0443649';

UPDATE Contenido SET id_tmdb = 8836, descripcion = 'Varias mujeres desaparecen en una población rural de Virginia. Un sacerdote que tiene "visiones" mandará a la policía a un lugar concreto, donde encontrarán una serie de fosas con cuerpos humanos congelados que parece ser un experimento médico secreto y que puede tener relación con las mujeres desaparecidas... Vuelven los agentes del FBI Mulder y Scully, protagonistas de una de las series más populares de la historia de la televisión. Dirigida por el propio creador de la serie, Chris Carter, una nueva adaptación cinematográfica que se puede ver de forma independiente, sin necesidad de estar familiarizado con la popular serie de TV.', trailer_url = 'https://www.youtube.com/watch?v=-mi3O7p_g8k' WHERE id_api = 'tt0443701';

UPDATE Contenido SET id_tmdb = 5820, descripcion = 'Pete Garrison era el agente especial de la Casa Blanca más condecorado de la historia, la última línea de defensa del presidente. Pero, cuando se empieza a sospechar que forma parte de una conspiración para asesinarlo, no tendrá más remedio que servirse de todo su conocimiento y habilidades para probar su inocencia.', trailer_url = 'https://www.youtube.com/watch?v=qacVtga4IYQ' WHERE id_api = 'tt0443632';

UPDATE Contenido SET id_tmdb = 1949, descripcion = 'El Asesino del Zodiaco mató, entre 1966 y 1978, a numerosas personas en San Francisco, al tiempo que enviaba a los medios de comunicación cartas con pistas. La acción se centra en las largas pesquisas de dos detectives que intentaron darle caza y en las investigaciones de dos periodistas que trataron de averiguar su identidad...', trailer_url = 'https://www.youtube.com/watch?v=QI1jajUjzMw' WHERE id_api = 'tt0443706';

UPDATE Contenido SET id_tmdb = 1683, descripcion = 'Después del trágico asesinato de su familia, una misionera cristiana (Hilary Swank) pierde la fe y se convierte en una profesora de teología experta en milagros que investiga el caso de una pequeña ciudad de Louisiana que parece asolada por las diez plagas bíblicas.', trailer_url = 'https://www.youtube.com/watch?v=aWdhBDqLlyo' WHERE id_api = 'tt0444682';

UPDATE Contenido SET id_tmdb = 4688, descripcion = 'Musical romántico ambientado en los años 60 del siglo XX, en la época de las turbulentas protestas contra la guerra, la exploración mental y el rock''n roll. La historia gira en torno a institutos y universidades en Massachusetts, Princeton y Ohio, y se traslada desde los muelles de Liverpool hasta la psicodelia creativa de Greenwich Village en Nueva York; desde las revueltas en las calles de Detroit hasta los campos de muerte de Vietnam.', trailer_url = 'https://www.youtube.com/watch?v=OYa3K2kKfUM' WHERE id_api = 'tt0445922';

UPDATE Contenido SET id_tmdb = 9955, descripcion = 'Expulsados para siempre del patinaje artístico después de pelearse en directo en mitad de los Juegos Olímpicos, dos antiguas estrellas de este deporte encuentran que la única forma de volver a la competición es tener que presentarse en pareja.', trailer_url = 'https://www.youtube.com/watch?v=YFE-6XlAAmE' WHERE id_api = 'tt0445934';

UPDATE Contenido SET id_tmdb = 11652, descripcion = 'Basado en un suceso real ocurrido en 1976. Vince Papale, un hombre de treinta años, barman y profesor a tiempo parcial, era un aficionado de los Philadelphia Eagles que sólo había jugado al fútbol americano un año en el instituto. Un día decidió apuntarse a una prueba abierta de su equipo para encontrar nuevos talentos y consiguió ser admitido, haciendo así realidad el sueño de toda su vida.', trailer_url = 'https://www.youtube.com/watch?v=Aux_hRJYED8' WHERE id_api = 'tt0445990';

UPDATE Contenido SET id_tmdb = 2693, descripcion = 'Telecomedia alrededor de un amargado aspirante a actor que deja su empleo fijo para seguir su sueño de convertirse en un famoso actor de cine; y se encuentra con la triste realidad de no conseguir un papel importante para lograr su objetivo.

Entre las estrellas que han aparecido en la serie, interpretando versiones satíricas y cínicas de sí mismos, están Robert de Niro, Kate Winslet, Samuel L. Jackson, David Bowie, Ian McKellen, Clive Owen, David Tennant, Orlando Bloom, Patrick Stewart, Ben Stiller, Daniel Radcliffe o Vinnie Jones.', trailer_url = 'https://www.youtube.com/watch?v=i8otiYmGJ_Y' WHERE id_api = 'tt0445114';

UPDATE Contenido SET id_tmdb = 1534, descripcion = 'Un joven vikingo fue dejado atrás por su gente tras una incursión en las Costas Orientales. A pesar de su linaje, es joven es criado por los indios que sobrevivieron al ataque. Ante la vuelta de los Vikingos, quienes de nuevo vienen con planes de destruir la aldea, el joven guerrero Nórdico se encuentra en medio de un conflicto en que luchará para impedir que su misma gente traiga la destrucción y la muerte al pueblo donde fue acogido como si fuera uno mas, convirtiéndolo en su familia. Pero en medio de la lucha en contra de su linaje, su verdadero destino le es revelado, y su identidad es reclamada.', trailer_url = 'https://www.youtube.com/watch?v=hxOav6ojI4c' WHERE id_api = 'tt0446013';

UPDATE Contenido SET id_tmdb = 22538, descripcion = 'Scott Pilgrim deberá derrotar a los malévolos siete ex novios de su nueva novia para ganarse su corazón.', trailer_url = 'https://www.youtube.com/watch?v=2jYWFb7NVrI' WHERE id_api = 'tt0446029';

UPDATE Contenido SET id_tmdb = 14202, descripcion = 'Años veinte. Kitty (Naomi Watts) es una joven inglesa de la alta sociedad que, para escapar de su ambiente familiar, se casa con Walter (Edward Norton), un prometedor médico. Ambos se trasladan a Shangai, donde Kitty se enamora de un norteamericano (Liev Schreiber) con el que tiene una aventura. Cuando Walter descubre la infidelidad de su esposa, decide trasladarse con ella a una de las regiones más remotas de China, para intentar luchar contra una mortal epidemia de cólera.', trailer_url = 'https://www.youtube.com/watch?v=YVwYxjmA4dc' WHERE id_api = 'tt0446755';

UPDATE Contenido SET id_tmdb = 7549, descripcion = 'China durante la primera década del siglo XX. El país sufre de corrupción y de la invasión extranjera. Huo Yuanjia es un legendario maestro de artes marciales. Profundamente humillado por la muerte de su padre en un duelo público, el joven Huo decide convertirse en el mejor luchador posible. Pero muy pronto pierde a dos de sus seres más queridos, por culpa de sus increíbles habilidades, cuando matan a su familia por venganza. Loco de dolor y de vergüenza, Huo Yuanjia huye sin importarle la muerte ni la vida...', trailer_url = 'https://www.youtube.com/watch?v=4I3oUkBnFG0' WHERE id_api = 'tt0446059';

UPDATE Contenido SET id_tmdb = 287947, descripcion = 'Todos llevamos un superhéroe dentro, solo se necesita un poco de magia para sacarlo a la luz. Cuando Billy Batson, un niño de acogida de 14 años que ha crecido en las calles, grita la palabra ''SHAZAM!'' se convierte en el Superhéroe adulto Shazam, por cortesía de un antiguo mago. Dentro de un cuerpo musculoso y divino, Shazam esconde un corazón de niño. Pero lo mejor es que en esta versión de adulto consigue realizar todo lo que le gustaría hacer a cualquier adolescente con superpoderes: ¡divertirse con ellos! ¿Volar? ¿Tener visión de rayos X? ¿Disparar un rayo con las manos? ¿Saltarse el examen de sociales? Shazam va a poner a prueba los límites de sus habilidades con la inconsciencia propia de un niño. Pero necesitará dominar rápidamente esos poderes para luchar contra las letales fuerzas del mal que controla el Dr. Thaddeus Sivana.', trailer_url = 'https://www.youtube.com/watch?v=dURE0vS6OJ8' WHERE id_api = 'tt0448115';

UPDATE Contenido SET id_tmdb = 13811, descripcion = 'Durante la inauguración de un nuevo colegio, los estudiantes guardan en una cápsula del tiempo varios objetos. Lucinda, una de las niñas, guarda un papel en el que ha escrito extraños números. Cincuenta años después, la cápsula del tiempo es desenterrada, el hijo de un profesor de astronomía viudo, recibe la misteriosa nota de Lucinda. John descubrirá enseguida que esos números esconden predicciones escalofriantes, algunas de las cuales ya han sucedido mientras que otras aún no.', trailer_url = 'https://www.youtube.com/watch?v=A2oDiEVXuDo' WHERE id_api = 'tt0448011';

UPDATE Contenido SET id_tmdb = 1272, descripcion = 'En el 2057, ante la inminente extinción de la humanidad a causa del envejecimiento del Sol, una nave espacial debe reactivar el astro con un dispositivo nuclear. Pero durante el viaje, la tripulación recibe una señal de socorro de la nave espacial Ícaro I, desaparecida años atrás tras intentar realizar la misma misión.', trailer_url = 'https://www.youtube.com/watch?v=Ig1BU6PUt0A' WHERE id_api = 'tt0448134';

UPDATE Contenido SET id_tmdb = 417859, descripcion = 'Mucho antes de que conociera a Shrek, el conocido espadachín, amante y fuera de la ley Gato con Botas se convierte en un héroe al emprender una aventura junto a la dura y espabilada Kitty Zarpassuaves y el astuto Humpty Dumpty para salvar a su pueblo. Complicándoles las cosas por el camino están los infames forajidos Jack y Jill, que harán cualquier cosa para que Gato y su banda no lo consigan.', trailer_url = 'https://www.youtube.com/watch?v=DziSUWvULh8' WHERE id_api = 'tt0448694';

UPDATE Contenido SET id_tmdb = 8960, descripcion = 'Hancock es un sarcástico e incomprendido superhéroe que ha perdido el cariño de la gente. Cuando Hancock accede a regañadientes a una operación de lavado de imagen por parte del publicista Ray Embrey, su vida y su reputación emergen de las cenizas y todo parece ir bien de nuevo. Hasta que conoce a una preciosa mujer.', trailer_url = 'https://www.youtube.com/watch?v=TxhelzCKFjc' WHERE id_api = 'tt0448157';

UPDATE Contenido SET id_tmdb = 285, descripcion = 'Siguiendo la estela de lo sucedido en “Piratas del caribe: el cofre del hombre muerto”, encontramos a nuestros héroes Will Turner y Elizabeth Swann aliados con el capitán Barbossa, en una búsqueda desesperada para liberar al capitán Jack Sparrow de las manos de Davy Jones. Mientras, el terrorífico barco fantasma, el Holandés Errante, bajo el control de la Compañía de las Indias Orientales, causa estragos a lo largo de los Siete Mares. Will y Elizabeth, navegando en medio de la traición, la felonía y mares salvajes, deben seguir adelante rumbo a Singapur y enfrentarse al astuto pirata chino Sao Feng. Ahora, en los mismísimos confines de la tierra, todos ellos deben elegir un bando en la batalla final, ya que no sólo sus vidas y fortunas, sino también el futuro de la piratería clásica, pende de un hilo...', trailer_url = 'https://www.youtube.com/watch?v=HKSZtp_OGHY' WHERE id_api = 'tt0449088';

UPDATE Contenido SET id_tmdb = 2486, descripcion = 'En el reino legendario de Alagaësia la guerra se está gestando. Los Jinetes protectores de la paz del Imperio y los únicos capaces de controlar a los inteligentes dragones, se han extinguido o han pasado a formar parte de las tropas del malvado rey Galbatorix. Los elfos hace tiempo que se han exiliado a un lugar oculto y los vardenos, un grupo disidente, se ocultan en ciudades protegidas. Cuando Eragon, un joven de 15 años que vive en una pequeña aldea, se encuentra con una piedra preciosa en medio del bosque a donde ha ido a cazar, poco se espera que ese suceso vaya a cambiar su vida y el destino de Alagaësia. Lo único que desea es venderla para así asegurar la subsistencia de su familia durante el duro invierno. Sin embargo, una noche la gema se rompe y lo que sale de ella lo llevará a un viaje que lo convertirá en héroe. ¿Podrá Eragon tomar la responsabilidad de los legendarios jinetes de dragones? La esperanza del Imperio descansa en sus manos...', trailer_url = 'https://www.youtube.com/watch?v=MAqm-1zUyno' WHERE id_api = 'tt0449010';

UPDATE Contenido SET id_tmdb = 773, descripcion = 'Los Hoover son una familia conflictiva: el abuelo esnifa cocaína y suelta palabrotas, el padre da cursos sobre el éxito con estrepitoso fracaso, la madre no da abasto, el tío se recupera de un suicidio frustrado al ser abandonado por su novio, el hijo adolescente lee a Nietzsche y se niega a hablar, y la hija pequeña, Olive, gafotas y ligeramente gordinflona, quiere ser una belleza. Cuando un golpe de suerte lleva a Olive a ser invitada a participar en el muy competitivo concurso de ''Pequeña Miss Sunshine'' en California, toda la familia Hoover se reúne para ir con ella. Se apilan en su oxidada furgoneta Volkswagen y se dirigen hacia el Oeste en un trágicómico periplo de tres días lleno de locas sorpresas que les lleva al gran debut de Olive, el cual cambiará a esta familia de inadaptados de una forma que nunca hubieran imaginado.', trailer_url = 'https://www.youtube.com/watch?v=3XZmXQoatIA' WHERE id_api = 'tt0449059';

UPDATE Contenido SET id_tmdb = 9530, descripcion = 'Agobiado porque el ritmo de la vida moderna apenas le deja disfrutar de su familia, Bob Munro planea unas vacaciones en Hawaii. Pero, desgraciadamente, su jefe lo necesita para una reunión en Colorado. Munro se lo oculta a sus familiares y los convence para que, en lugar de ir a Hawai, alquilen una caravana para ir a las Montañas Rocosas, en Colorado.', trailer_url = 'https://www.youtube.com/watch?v=iG3BmjPjSpY' WHERE id_api = 'tt0449089';

UPDATE Contenido SET id_tmdb = 1164, descripcion = 'Ambientada en Marruecos, Túnez, México y Japón. Armados con un Winchester, dos muchachos marroquíes salen en busca del rebaño de cabras de la familia. En medio del silencio del desierto, deciden probar el rifle, sin conocer el alcance de la bala. En un instante, entran en colisión las vidas de cuatro grupos de personas que viven en tres continentes distintos.', trailer_url = 'https://www.youtube.com/watch?v=P5tSde59HJM' WHERE id_api = 'tt0449467';

UPDATE Contenido SET id_tmdb = 1407, descripcion = 'Biografía de la famosa cantante francesa Edith Piaf (1915-1963): su infancia, su adolescencia y su ascensión a la gloria. De los barrios bajos de París al éxito de Nueva York, la vida de Edith Piaf fue una lucha por sobrevivir y amar. Creció en medio de la pobreza, pero su voz mágica y sus apasionados romances y amistades con las grandes personalidades de la época (Yves Montand, Jean Cocteau, Charles Aznavour, Marlene Dietrich, Marcel Cerdan) hicieron de ella una estrella mundial.', trailer_url = 'https://www.youtube.com/watch?v=M-_7-qgVXE0' WHERE id_api = 'tt0450188';

UPDATE Contenido SET id_tmdb = 1372, descripcion = 'Con el caos y la guerra civil que en los años 90 envolvió Sierra Leona como telón de fondo, "Diamante de sangre" es la historia de Danny Archer, un ex mercenario sudafricano, y Solomon Vandy, un pescador de Mende. Ambos hombres son africanos, pero sus historias y sus circunstancias son completamente diferentes. Sus destinos se unen en la búsqueda conjunta para recuperar un diamante rosa, poco común, que puede transformar sus vidas. Mientras se halla en prisión por contrabando, Archer se entera de que Solomon, quien fue separado de su familia y obligado a trabajar en las minas de diamantes, ha encontrado y escondido la extraordinaria piedra sin pulir. Con la ayuda de Maddy Bowen, una periodista americana cuyo idealismo se ve atenuado por una profunda relación con Archer, los dos hombres emprenden un viaje por territorio rebelde.', trailer_url = 'https://www.youtube.com/watch?v=q8r_IE386DU' WHERE id_api = 'tt0450259';

UPDATE Contenido SET id_tmdb = 2207, descripcion = 'A las 8:02 de la mañana, el detective de la policía de Nueva York Jack Mosley tiene encomendada una misión aparentemente sencilla. El delincuente Eddie Bunker está citado para testificar ante un gran jurado a las 10 en punto, y Mosley debe trasladarlo desde la celda al juzgado, a 16 calles de distancia. Cuando Jack, que tiene serios problemas con el alcohol, mete a Eddie en el asiento trasero de su coche y se dispone a atravesar Nueva York en hora punta de la mañana, no se da cuenta de que los sigue una furgoneta...', trailer_url = 'https://www.youtube.com/watch?v=OgNv-iFYeMA' WHERE id_api = 'tt0450232';

UPDATE Contenido SET id_tmdb = 1690, descripcion = 'Paxton y Josh, dos jóvenes norteamericanos amigos de la universidad, recorren Europa con sus mochilas junto con Oli, un islandés que conocen en el camino. En Eslovaquia conocen a Natalya y Svetlan, dos exóticas bellezas con las que se distraen.... para aparecer atrapados en un siniestro y lúgubre sitio. Su angustiosa situación, como descubrirán más tarde, es tan profunda como el más oscuro y enfermizo recoveco de la propia naturaleza humana... si sobreviven.', trailer_url = 'https://www.youtube.com/watch?v=U8U7qkreU0g' WHERE id_api = 'tt0450278';

UPDATE Contenido SET id_tmdb = 13056, descripcion = 'Película basada en el anti-héroe de Marvel Frank Castle, también conocido como "El castigador". Continuando su cruzada para castigar a criminales violentos en América, el agente del FBI Frank Castle (Ray Stevenson), llega a Nueva York en busca de un jefe que controla los bajos fondos de la ciudad.', trailer_url = 'https://www.youtube.com/watch?v=5R6bFLgQLgY' WHERE id_api = 'tt0450314';

UPDATE Contenido SET id_tmdb = 9708, descripcion = 'Mientras se recupera de un accidente de tráfico, Edward Malus recibe una carta en la que Willow, la novia que lo abandonó hace años sin darle ninguna explicación, le pide ayuda para encontrar a su hija que ha desaparecido misteriosamente. Edward se desplaza hasta la isla privada donde Willow forma parte de una tenebrosa comunidad pagana que realiza extraños ritos.', trailer_url = 'https://www.youtube.com/watch?v=r86OlE7rlFc' WHERE id_api = 'tt0450345';

UPDATE Contenido SET id_tmdb = 3021, descripcion = 'Basada en un relato de Stephen King, cuenta la historia de un novelista de terror que sólo cree en aquello que ven sus ojos. Tras dedicarse a desacreditar fenomenos paranormales ocurridos en supuestas casas fantasmas, él no tiene prueba alguna de la existencia de vida más allá de la muerte. Sin embargo, todo cambiará cuando entre en la habitación 1408 del Hotel Dolphin.', trailer_url = 'https://www.youtube.com/watch?v=hDDKcuQ7zq8' WHERE id_api = 'tt0450385';

UPDATE Contenido SET id_tmdb = 24418, descripcion = 'El joven Darren Shan se parece a la mayoría de los chicos de su barrio residencial. Pasa mucho tiempo con su mejor amigo, Steve, saca buenas notas y no suele meterse en líos. Pero el destino quiere que un circo ambulante se cruce en el camino de Darren y de su amigo, y algo empieza a cambiar en su interior. A partir de ese momento, un vampiro llamado Larten Crepsley (John C. Reilly), ofrece convertirse en su mentor uniéndose al Circo de los Extraños, un espectáculo con criaturas monstruosas como el Chico Serpiente, un Hombre Lobo, la mujer barbuda Madame Truska y un gigantesco presentador llamado Mr. Tall (Sr. Alto). Darren empieza a hacer sus pinitos en este nuevo y oscuro universo, pero no tarda en convertirse en una codiciada presa entre los vampiros y sus letales enemigos, los "vampenezes". En su lucha por la supervivencia, intentará desesperadamente impedir que la inminente guerra acabe por devorar la poca humanidad que le queda', trailer_url = 'https://www.youtube.com/watch?v=VErEjqmfkzY' WHERE id_api = 'tt0450405';

UPDATE Contenido SET id_tmdb = 12222, descripcion = 'Horton no es sólo un bondadoso y torpón elefante, sino tambíen es el único animal capaz de oir a una microscópica comunidad aislada en una mota de polvo, lo que provocará que sus vecinos le tomen por loco e intenten destruir la mota de polvo en la que el pueblo de Villaquien vive en pacífica armonía. Horton está dispuesto a ayudar a los habitantes de Villaquién cuya frágil existencia pende de un hilo.', trailer_url = 'https://www.youtube.com/watch?v=NPREAnDsEVM' WHERE id_api = 'tt0451079';

UPDATE Contenido SET id_tmdb = 4550, descripcion = 'Kum-ja es una joven que ha pasado trece años en prisión acusada del secuestro y el asesinato de un niño de 6 años. Un crimen que conmocionó a la opinión pública, tanto por la brutalidad del mismo como por los veinte años con los que contaba entonces la acusada. Cumplida su pena, Geum-ja sólo tiene una cosa en mente: venganza... Última parte de la trilogía de la venganza de Chan-wook Park, tras "Sympathy For Mr. Vengeance" y "Oldboy".', trailer_url = 'https://www.youtube.com/watch?v=4ELbSqQd3X0' WHERE id_api = 'tt0451094';

UPDATE Contenido SET id_tmdb = 297762, descripcion = 'Diana, princesa de las Amazonas, entrenada para ser una guerrera invencible, fue criada en una isla paradisíaca protegida, hasta que un día, un piloto norteamericano, que tuvo un accidente y acabó en sus costas, le habló de un gran conflicto existente en el mundo, la Primera Guerra Mundial. Diana decidió salir de la isla, convencida de que podía detener la terrible amenaza. Ahora lucha como Wonder Woman, junto a los hombres, en la guerra que acabará con todas las guerras y descubre todos sus poderes y su verdadero destino.', trailer_url = 'https://www.youtube.com/watch?v=WXMwfxYAmiA' WHERE id_api = 'tt0451279';

UPDATE Contenido SET id_tmdb = 10483, descripcion = 'En un futuro próximo. Una penitenciaría atestada de presos inspiró a los carceleros para crear un pasatiempo tan cruel como lucrativo. Presos capaces de todo, un público global hambriento de violencia televisada y un ruedo espectacular se unen en DEATH RACE. El tricampeón de velocidad Jensen Ames (Jason Statham) es todo un experto a la hora de sobrevivir en el desértico paisaje en el que se ha convertido el país. Cree haber cambiado de vida, pero el ex convicto es acusado de un terrible crimen que no ha cometido. La directora de Terminal Island (Joan Allen) le obliga a ponerse la máscara de Frankenstein, un favorito del público al que parece imposible matar, y le da dos opciones: competir o pudrirse en una celda. Con el rostro escondido detrás de la máscara metálica, el preso deberá sobrevivir a los tres días más terribles de su vida, enfrentándose a los peores criminales procedentes de las cárceles más duras del país si quiere salir libre.', trailer_url = 'https://www.youtube.com/watch?v=Gv19dbjcC-k' WHERE id_api = 'tt0452608';

UPDATE Contenido SET id_tmdb = 9767, descripcion = 'Relato sobre las consecuencias de una ruptura sentimental. Gary (Vince Vaughn) y Brooke (Jennifer Aniston), tras dos años de noviazgo, descubren que el amor que se habían profesado ha desaparecido. El detonante es una pequeña discusión doméstica que acaba convirtiéndose en una pelea desaforada. El problema es que ninguno de los dos quiere dejar el apartamento; empieza así una batalla en la que no faltan amigos y parientes que les aconsejan recurrir a la guerra "psicológica" para conseguir que el otro abandone el hogar...', trailer_url = 'https://www.youtube.com/watch?v=SfTaJUh3_J4' WHERE id_api = 'tt0452594';

UPDATE Contenido SET id_tmdb = 9641, descripcion = 'Tom Baker (Steve Martin) y su mujer Kate (Bonnie Hunt), esperando reunir a su familia en unas memorables vacaciones de verano, llevan a sus doce hijos al lago Winnetka, en Wisconsin, que ha sido el lugar en el que siempre han pasado sus vacaciones. Pero su paz y sosiego pronto saltan por los aires cuando han de vérselas en una contienda con los hipercompetitivos miembros de otra gran estirpe de la que Jimmy Murtaugh (Eugene Levy), viejo rival de Tom y padre de ocho hijos, es el cabeza de familia.', trailer_url = 'https://www.youtube.com/watch?v=OnLlLwEflHI' WHERE id_api = 'tt0452598';

UPDATE Contenido SET id_tmdb = 4771, descripcion = 'Basado en un best-seller del autor de "Mystic River", cuenta la historia de dos jóvenes detectives privados, Patrick Kenzie y Angela Gennaro que buscan a una niña de cuatro años, hija de una drogadicta, que ha sido secuestrada en uno de los barrios más sórdidos de Boston.', trailer_url = 'https://www.youtube.com/watch?v=6DNj9zG9UKo' WHERE id_api = 'tt0452623';

UPDATE Contenido SET id_tmdb = 10030, descripcion = 'Charlie (Dane Cook) sufrió cuando era niño una maldición que ahora se ha convertido para algunas en un "don": después de acostarse con una mujer, ésta siempre encuentra a su amor verdadero en el siguiente hombre y se casa con él. Así Charlie, al que llaman "Lucky Chuck", es solicitado por multitud de mujeres solteras. Pero cuando Charlie encuentra a la mujer perfecta (Jessica Alba) tendrá un "pequeño problema": no puede acostarse con ella... porque si lo hace ella encontrará a otro hombre y la perderá para siempre.', trailer_url = 'https://www.youtube.com/watch?v=AG6kMQuTyX0' WHERE id_api = 'tt0452625';

UPDATE Contenido SET id_tmdb = 9697, descripcion = 'Cleveland Heep es el conserje de un edificio de apartamentos que un día rescata del peligro a una misteriosa joven. La chica resulta ser una narf, una ninfa marina que lleva un mensaje de suma importancia para alguien de nuestro mundo. Cleveland intentará ayudarla a encontrar a quien busca y a volver a su mundo antes de que los malvados scrunts la encuentren a ella.', trailer_url = 'https://www.youtube.com/watch?v=j_EfR05ku4Q' WHERE id_api = 'tt0452637';

UPDATE Contenido SET id_tmdb = 24420, descripcion = 'Clare (Rachel McAdams) ha estado siempre enamorada de Henry (Eric Bana), un bibliotecario de Chicago. Está convencida de que están destinados a vivir juntos, aunque no sepa cuándo tendrán que volver a separarse: Henry es un viajero del tiempo, con una rara anomalía genética que lo condena a vivir su vida en una escala de tiempo cambiante, avanzando y retrocediendo a través de los años sin ningún control. A pesar de que los viajes de Henry son tan imprevisibles que Clare nunca sabe cuándo volverán a verse, intenta desesperadamente adaptarse a esa vida, pues lo que sí sabe es que no podría vivir sin Henry.', trailer_url = 'https://www.youtube.com/watch?v=HA9aXkU3uqM' WHERE id_api = 'tt0452694';

UPDATE Contenido SET id_tmdb = 13767, descripcion = 'Santa (Tim Allen), también el hombre corriente Scott Calvin, se enfrenta a una doble tarea: cómo mantener unida y feliz a su nueva familia, y cómo parar a Jack Frost (Martin Short) en su vil intento de destruir la Navidad. Aun a riesgo de revelar la ubicación secreta del Polo Norte, Scott invita a sus suegros (Ann-Margret y Alan Arkin) a compartir las vacaciones navideñas con él y su mujer Carol (Elizabeth Mitchell). A esta aventura se une la extensa familia de Scott: su hijo Charlie (Eric Lloyd), su ex mujer Laura Miller (Wendy Crewson), su marido, Neil Miller (Judge Reinhold) y su hija, Lucy (Liliana Mumy), que junto con el elfo Curtis (Spencer Breslin), tratarán de frustrar los planes de Jack Frost para hacerse con el control del Polo Norte...', trailer_url = 'https://www.youtube.com/watch?v=jpyBrTSUO5k' WHERE id_api = 'tt0452681';

UPDATE Contenido SET id_tmdb = 10294, descripcion = 'David (Wilson) y Amy Fox (Beckinsale), una pareja con problemas tras haber sufrido una tragedia en su matrimono. Se ven obligados a pasar la noche en un aislado hotel tras una avería en su coche. En su habitación descubren unas cámaras de video ocultas, y se dan cuenta de que, a menos que escapen de allá, serán los siguientes en protagonizar una snuff movie...', trailer_url = 'https://www.youtube.com/watch?v=1IYFZYx5u1w' WHERE id_api = 'tt0452702';

UPDATE Contenido SET id_tmdb = 1268, descripcion = 'Nuevas aventuras en la gran pantalla del popular Mr. Bean, esta vez de turismo por el sur de Francia. Su viaje de Londres a la Costa Azul no tardará en convertirse en un auténtico caos, causando auténticos estragos allí por donde pasa.', trailer_url = 'https://www.youtube.com/watch?v=fqx02ecz88Y' WHERE id_api = 'tt0453451';

UPDATE Contenido SET id_tmdb = 9664, descripcion = 'Historia sobre los jóvenes pilotos norteamericanos que conformaron la lengendaria escuadrilla Lafayette (del ejército francés) en la Primera Guerra Mundial. El tejano Blaine Rawlings sufre el desahucio de su rancho familiar de 900 acres y encuentra su nuevo futuro en la noticia de un periódico que informa de la Escuadrilla de héroes. El recluta Higgins, de la Legión Extranjera Francesa, se pasa del cuerpo de conductores de ambulancia al escuadrón de combate. El natural de Nebraska William Jensen, hijo de un oficial de Caballería, se alista para mantener la tradición militar de la familia. Por su parte, Briggs Lowry se une al escuadrón para hacer algo de provecho con su vida, sucumbiendo a las presiones de su rico y poderoso padre.', trailer_url = 'https://www.youtube.com/watch?v=QSP_vl8_Djc' WHERE id_api = 'tt0454824';

UPDATE Contenido SET id_tmdb = 7551, descripcion = 'Tras una terrible explosión de una bomba en un Ferry de Nueva Orleans, el agente Doug Carlin descubre que es obra de un terrorista. Por su perspicacia para analizar y distinguir rápidamente lo relevante de lo secundario en el escenario del crimen, Carlin es asignado a un misterioso nuevo equipo de investigación que utiliza una sofisticada máquina que permite algo extraordinario...', trailer_url = 'https://www.youtube.com/watch?v=VdCRypsfZDE' WHERE id_api = 'tt0453467';

UPDATE Contenido SET id_tmdb = 109410, descripcion = 'Historia de la vida del afroamericano Jackie Robinson, legendario jugador de béisbol que rompió las barreras raciales, tras firmar con los Dodgers de Brooklyn bajo la dirección del ejecutivo Branch Rickey. La participación de Robinson en la gran liga de béisbol supuso el fin de una era de segregación racial en este deporte.', trailer_url = 'https://www.youtube.com/watch?v=I6LsC5xMzyo' WHERE id_api = 'tt0453562';

UPDATE Contenido SET id_tmdb = 9655, descripcion = 'Viola Hastings es una gran futbolista, pero el equipo femenino ha sido cancelado y pide jugar en el masculino. Cuando su solicitud es rechazada de malas formas, decide hacerse pasar por su hermano gemelo, Sebastian, para entrar al equipo masculino de la escuela rival en la que ella solía jugar. Una vez allí, las complicaciones no paran de llegar. Se enamora de su apuesto compañero de cuarto, Duke, que adora a la bella Olivia, que se ha enamorado de Sebastian, el cual es la misma Viola disfrazada de su hermano. Como si eso no fuera suficiente, Sebastian regresa antes de lo previsto, pero no tiene ni idea de que su hermana ya lo ha reemplazado en el campus.', trailer_url = 'https://www.youtube.com/watch?v=QJTDfxZXdNE' WHERE id_api = 'tt0454945';

UPDATE Contenido SET id_tmdb = 1273, descripcion = 'Adaptación de los famosos cómics de Las Tortugas Ninja, que relata cómo cuatro tortugas se convierten en criaturas bípedas. Desde pequeños, fueron entrenados por la rata Ninja, Splinter, y fueron nombrados de acuerdo con los pintores del Renacimiento: Raphael, Michelangelo, Donatello y Leonardo. Cuando terminan su entrenamiento, emergen de las alcantarillas y entran al extraño mundo de los humanos.', trailer_url = 'https://www.youtube.com/watch?v=PXhhPJ1LdoI' WHERE id_api = 'tt0453556';

UPDATE Contenido SET id_tmdb = 9792, descripcion = 'Los Carter, una familia de clase media, ven truncadas sus vacaciones cuando su caravana sufre un extraño accidente en el desierto de Nuevo México. Aislados del mundo, pronto se darán cuenta de que no están solos. En las colinas habita una estirpe de sanguinarios mutantes, fruto de las continuas pruebas nucleares del ejército, y que no dudarán en aniquilar a los Carter de las formas más espeluznantes.', trailer_url = 'https://www.youtube.com/watch?v=K61SoAJ8Uto' WHERE id_api = 'tt0454841';

UPDATE Contenido SET id_tmdb = 388, descripcion = 'Enfrentamiento entre un duro policía y un inteligente atracador durante un tenso secuestro con rehenes en un banco de Manhattan. Según se desarrolla el peligroso juego del gato y el ratón, aparece una tercera persona que ha sido contratada por el influyente propietario del banco. Se trata de Madaline, una poderosa bróker que tiene una agenda secreta.', trailer_url = 'https://www.youtube.com/watch?v=4uc0qJm3iW4' WHERE id_api = 'tt0454848';

UPDATE Contenido SET id_tmdb = 87827, descripcion = 'Pi Patel es un muchacho cuyo padre es el dueño del zoológico de la ciudad de la India en la que viven. Su familia decide marcharse a Canadá, pero una tormenta hace naufragar el barco en el que viajan. Pi consigue salvarse gracias a una barcaza en la que también hay otro "pasajero", un tigre de Bengala al que el joven intentará domar para poder sobrevivir.', trailer_url = 'https://www.youtube.com/watch?v=qcSs_K_G10o' WHERE id_api = 'tt0454876';

UPDATE Contenido SET id_tmdb = 1402, descripcion = 'Chris Gardner es un vendedor brillante y con talento, pero su empleo no le permite cubrir sus necesidades más básicas. Tanto es así que acaban echándolo, junto a su hijo de cinco años, de su piso de San Francisco y no tienen ningún lugar al que ir. Cuando Gardner consigue hacer unas prácticas en una prestigiosa correduría de bolsa, los dos protagonistas tendrán que afrontar muchas adversidades parar hacer realidad su sueño de una vida mejor. Basada en hechos reales.', trailer_url = 'https://www.youtube.com/watch?v=DMOBlEcRuw8' WHERE id_api = 'tt0454921';

UPDATE Contenido SET id_tmdb = 9513, descripcion = 'Continuación de las andanzas del famoso y revoltoso gato Garfield, en esta ocasión de viaje por Londres con su colega canino Odie. Su intención es sorprender a su dueño, Jon Arbuckle, quien está en Londres para proponerle matrimonio a su novia, la veterinaria Liz Wilson.', trailer_url = 'https://www.youtube.com/watch?v=RwPfYvrxy9A' WHERE id_api = 'tt0455499';

UPDATE Contenido SET id_tmdb = 29427, descripcion = 'Una misteriosa toxina en el agua convierte a cualquiera que esté expuesto a ella en un asesino sin escrúpulos. Los residentes de una idílica ciudad empiezan a sucumbir a un desenfreno incontrolable de violencia y la escalofriante masacre acaba en una sanguinaria anarquía. En un intento por controlar la epidemia, el ejército envía una fuerza de élite a bloquear los accesos a la ciudad, aislando a los pocos ciudadanos no infectados que quedan y dejándolos a merced de los despiadados asesinos que acechan en la oscuridad.', trailer_url = 'https://www.youtube.com/watch?v=TfeK0aN9w24' WHERE id_api = 'tt0455407';

UPDATE Contenido SET id_tmdb = 13092, descripcion = 'Basada en la verdadera historia de un verdadero idiota, “Nueva York Para Principiantes” es la crónica del declive de Sidney Young, un prometedor periodista británico que un día tiene la oportunidad de escribir en una de las revistas más prestigiosas de Nueva York, "Sharps". Young, un fracaso total sin vergüenza, sin tacto y sin control, se abrirá camino a través de Manhattan por los motivos más inoportunos, y sus malos modales y sus bromas de mal gusto le llevarán a percances monumentales con divertidas consecuencias... (FILMAFFINITY)', trailer_url = 'https://www.youtube.com/watch?v=GLSeNIAkVx4' WHERE id_api = 'tt0455538';

UPDATE Contenido SET id_tmdb = 4057, descripcion = 'Mentes criminales (Criminal Minds) es una serie de drama criminológico. Se estrenó el 22 de septiembre de 2005 en el canal de televisión estadounidense, CBS. Muestra el trabajo de los miembros del equipo de Unidad de Análisis de Conducta del FBI, un grupo de investigadores de diversas ramas de la criminología que se dedica a hacer análisis psicológicos y criminológicos a criminales para facilitar su captura.', trailer_url = 'https://www.youtube.com/watch?v=NTYxiJBbEZk' WHERE id_api = 'tt0452046';

