UPDATE Contenido SET id_tmdb = 2288, descripcion = 'Michael Scofield (Wentworth Miller) es un hombre desesperado en un situación desesperada. Su hermano Lincoln Burrows (Dominic Purcell), condenado a la pena capital está a la espera de ser ejecutado. A pesar de todas las evidencias, Michael cree en su inocencia, por lo que decide robar un banco para dejarse atrapar y ser encarcelado en la misma prisión que su hermano. Su objetivo: escapar juntos.', trailer_url = 'https://www.youtube.com/watch?v=eYlux4orZSU' WHERE id_api = 'tt0455275';

UPDATE Contenido SET id_tmdb = 14001, descripcion = 'Un joven viudo regresa a su hogar para investigar el asesinato de su mujer. Allí descubre la leyenda de Mary Shaw, una ventrílocua que pidió ser enterrada junto a sus 101 "muñecos". Uno de ellos parece haber vuelto de la tumba, y no precisamente con buenas intenciones... De los creadores de "Saw".', trailer_url = 'https://www.youtube.com/watch?v=H1nFpol67Lk' WHERE id_api = 'tt0455760';

UPDATE Contenido SET id_tmdb = 1523, descripcion = 'Nicholas Garrigan es un joven médico escocés que, buscando nuevas experiencias, se desplaza hacia Uganda en los años setenta para trabajar en la ayuda humanitaria. Nada más llegar debe atender a Idi Amín, el nuevo líder del país, que ha sufrido un aparatoso accidente al chocar su vehículo con una vaca. Este primer encuentro fascina al dirigente y hace que Nicholas se convierta en su médico personal.  El joven se deja seducir por la cautivadora personalidad del gobernador y pronto se convierte en su confidente más íntimo. Pero con el tiempo Nicholas se da cuenta de que, detrás del encanto y generosidad de Idi Amín, se esconde un sanguinario y atroz asesino. Su intención es alejarse cuanto antes del horror que esconde uno de los más terribles regímenes de África. Pero quizás ya es demasiado tarde.', trailer_url = 'https://www.youtube.com/watch?v=R_W7PC6NnN4' WHERE id_api = 'tt0455590';

UPDATE Contenido SET id_tmdb = 6972, descripcion = 'Lady Sarah Ashley (Nicole Kidman), una aristócrata inglesa, se ha pasado la vida persiguiendo la perfección superficial, pero un matrimonio sin amor y sin hijos le ha privado de cualquier cosa importante que no sea su cuadra de caballos. Convencida de que su marido le es infiel, la empecinada Sarah viaja desde Londres hasta el remoto reducto tropical de Darwin (Australia) para enfrentarse a él. Su reacio guía a través del inmenso e inmisericorde terreno del territorio septentrional es Drover (Hugh Jackman), un ganadero tan tosco y basto como refinada es Sarah. Su profunda antipatía mutua se ve aminorada por la tragedia cuando Sarah, de repente, se halla cuidando a un encantador y joven huérfano llamado Nullah (Brandon Walters), un muchacho mestizo a la deriva en una sociedad segregada que le trata como un paria.', trailer_url = 'https://www.youtube.com/watch?v=7uX-d8YeQxA' WHERE id_api = 'tt0455824';

UPDATE Contenido SET id_tmdb = 156022, descripcion = 'Robert McCall, un antiguo agente de la CIA que lleva ahora una vida tranquila, abandona su retiro para ayudar a Teri, que está siendo explotada por la mafia rusa. A pesar de que aseguró no volver a ser violento, contemplar tanta crueldad despertará en Robert un implacable y renovado deseo de justicia.', trailer_url = 'https://www.youtube.com/watch?v=rlMaxFG7blg' WHERE id_api = 'tt0455944';

UPDATE Contenido SET id_tmdb = 10053, descripcion = 'En una remota casa en lo alto de una colina, la estudiante de segunda enseñanza Jill Jonson se prepara para una rutinaria noche de canguro. Con los niños profundamente dormidos y una bonita casa para inspeccionar, cierra la puerta con llave y conecta la alarma. Pero tras una serie de inquietantes llamadas telefónicas en las que un extraño insiste en que “vaya a ver a los niños” Jill empieza a angustiarse. El miedo va en aumento hasta convertirse en terror cuando le informan que las llamadas proceden del interior de la casa. Jill debe reunir todas sus fuerzas si pretende defenderse y lograr salir de la casa con vida.', trailer_url = 'https://www.youtube.com/watch?v=xFxmelljiyg' WHERE id_api = 'tt0455857';

UPDATE Contenido SET id_tmdb = 8398, descripcion = 'Un joven que viaja en su coche a través del estado de Texas recoge a un autoestopista que no tarda en confesarle que es un asesino. El joven asustado consigue deshacerse de él pensando que ha pasado el peligro. Sin embargo, el psicópata continua matando y deja pistas para que la policía inculpe al joven conductor.', trailer_url = NULL WHERE id_api = 'tt0455960';

UPDATE Contenido SET id_tmdb = 9293, descripcion = 'Tres guapas y populares chicas de grupos rivales en el instituto descubren que han estado quedando a la vez con el mismo chico: el guapo y genial capitán del equipo de baloncesto de la escuela, John Tucker (Jesse Metcalfe). Tras comparar sus notas, el furioso trío - la aspirante a reportera, la jefa de animadoras Heather, y la activista vegetariana Beth - conspira para dar a Tucker una lección que nunca olvidará. Deciden contrarrestar su juego y hacer que este chico, que nunca ha estado sin una cita, se quede con un palmo de narices y más solo que la una. Desgraciadamente, cada burdo y extraño plan que traman para abochornar a Tuck les sale del revés y sólo consiguen que éste sea cada vez más popular...', trailer_url = 'https://www.youtube.com/watch?v=hDmtPKruS6s' WHERE id_api = 'tt0455967';

UPDATE Contenido SET id_tmdb = 21461, descripcion = 'Lovable goon Munna falls for a morning radio host by the name of Jahnvi, who also runs an elders'' home which an unscrupulous builder seeks to attain. In order to gain Jahnvi’s attention, he cheats his way to winning a Mahatma Gandhi radio quiz. When Jahnvi consequently expresses interest in Munna, he and his best friend Circuit attempt to keep up the facade.', trailer_url = 'https://www.youtube.com/watch?v=OE6f1oHgeDg' WHERE id_api = 'tt0456144';

UPDATE Contenido SET id_tmdb = 9900, descripcion = 'A sus 35 años, Alex trabaja probando los nuevos juegos de la empresa Brainasium. Es el más veterano entre sus compañeros, pero también es el mejor. Cuando le echan de su apartamento por impago (su compañero se ha gastado el dinero del alquiler en los “masajes terapéuticos” de Madame Wu’s Filipino Palace), Alex intenta instalarse en casa de su “camello”, pero éste se ha comprado un “león guardián” y no puede alojarle. Finalmente no le quedará más remedio que instalarse en casa de su adorable y encantadora abuela y sus octogenarias amigas. A sus compañeros de curro les hace creer que vive con tres jovencitas que están buenísimas para que no descubran la “vergonzosa” verdad. Pero las “abuelitas” son de armas tomar, y acabarán metidas en todas las juergas de Alex, en las que se mezclan alcohol, karaoke, hierba, un hechicero vudú, un mono karateka, tías buenas a porrillo y gamberradas para todos los gustos.', trailer_url = 'https://www.youtube.com/watch?v=sEA_g1UK64k' WHERE id_api = 'tt0456554';

UPDATE Contenido SET id_tmdb = 11344, descripcion = 'Sunwoo (Lee Byung-hun) no es sólo el gerente de un hotel, también es la mano derecha de un mafioso local llamado Kang (Kim Young-chul). El día que éste le ordena que vigile a su prometida, de la que sospecha pueda estar viéndose con otro hombre, su suerte cambiará fatídicamente. Enamorado en secreto de la chica, Sunwoo decide perdonar la vida de su amante aunque eso provocará las iras de su jefe, con consecuencias en extremo dolorosas.', trailer_url = 'https://www.youtube.com/watch?v=q5O2tfiaTxU' WHERE id_api = 'tt0456912';

UPDATE Contenido SET id_tmdb = 18162, descripcion = 'El Dr. Rick Marshall (Will Ferrell) es un científico, venido a menos, al que atrapa un vórtice espacio-temporal, y le lanza a un pasado lejano. Muy lejano, incluso. El científico carece de armas, habilidades e inteligencia para sobrevivir en un universo alternativo plagado de dinosaurios al acecho y fantásticas criaturas de otro mundo.Pero el Dr. Rick Marshall no está solo en esta aventura. Le acompañan la superinteligente investigadora Holly (Anna Friel) y Will (Danny McBride), un forofo de la supervivencia. Perseguidos por T. Rex y acosados por reptiles de una lentitud que exacerbaría a cualquiera, los Sleestaks, los tres dependen de su único aliado, un primate llamado Chaka (Jorma Taccone), para salir de esta dimensión híbrida. Si consiguen escapar, serán héroes. Y si no, eternos refugiados en "Land of the Lost".', trailer_url = 'https://www.youtube.com/watch?v=OF8UT1x9Fcg' WHERE id_api = 'tt0457400';

UPDATE Contenido SET id_tmdb = 2284, descripcion = 'Molly Mahoney es la tímida e insegura gerente de Mr. Magorium''s Wonder Emporium, la más extraña, fantástica y maravillosa tienda de juguetes del mundo. Pero cuando el señor Magorium, el excéntrico dueño de la tienda, que tiene 243 años, decide traspasar el negocio a la joven Molly, la tienda experimenta un oscuro y extraño cambio.', trailer_url = 'https://www.youtube.com/watch?v=m4Mrga2aSL0' WHERE id_api = 'tt0457419';

UPDATE Contenido SET id_tmdb = 1417, descripcion = 'En la España falangista de 1944, una joven aficionada a los libros e hijastra de un sádico oficial del ejército huye a un misterioso pero cautivador mundo de fantasía.', trailer_url = 'https://www.youtube.com/watch?v=NEg7u3boJhU' WHERE id_api = 'tt0457430';

UPDATE Contenido SET id_tmdb = 7183, descripcion = 'Siguiendo las pistas del asesinato sin resolver de uno de sus amigas de la infancia, la periodista Nowena Price, decide investigar por su cuenta. El principal sospechoso es el famoso publicista Harryson Hills. Con la ayuda de su amigo y profesional de la informática, el hacker Miles Haley, y aprovechando el anonimato de Internet, Nowena espera hacer justicia.', trailer_url = 'https://www.youtube.com/watch?v=cL6WWHgp0bo' WHERE id_api = 'tt0457433';

UPDATE Contenido SET id_tmdb = 9353, descripcion = 'Ignacio (Jack Black) es un luchador gordo con un socio de equipo. Su madre era una misionera de Escandinavia y su padre era diácono de México. Murieron cuando Ignacio era pequeño. Creciendo como huérfano en un monasterio mexicano se convirtió en el cocinero del orfanato. Ignacio soñaba con convertirse en un luchador, pero la prohibición de la lucha en el monasterio no se lo permitía. Como en el orfanato la comida era escasa, a Nacho se le ocurrió un plan para conseguir el dinero para los huérfanos, ir a competir en la lucha libre, pero debe tener cuidado con la hermana Encarnación (Ana de la Reguera) con quien tiene mucho en común. Ignacio decide finalmente ser un luchador.', trailer_url = 'https://www.youtube.com/watch?v=m2Vh4tfnvKk' WHERE id_api = 'tt0457510';

UPDATE Contenido SET id_tmdb = 512, descripcion = 'Sondra Pransky (Scarlett Johansson), una estudiante americana de periodismo, se encuentra en Gran Bretaña visitando a unos amigos. Durante su estancia en Londres, acude a un espectáculo de magia, donde un ilusionista (Woody Allen) la invita a subir al escenario para hacerla desaparecer. Mientras espera que el mago ponga en práctica su truco, recibe la visita del fantasma de un prestigioso periodista muerto (Ian McShane), que ha venido desde el más allá para servirle en bandeja la exclusiva del año. El espíritu afirma que Peter Lyman (Hugh Jackman), el rico y atractivo hijo de un conocido aristócrata británico, es en realidad el famoso asesino en serie conocido como "el asesino del tarot".', trailer_url = 'https://www.youtube.com/watch?v=U06CfYfKbxA' WHERE id_api = 'tt0457513';

UPDATE Contenido SET id_tmdb = 1581, descripcion = 'Amanda Woods, una chica americana que posee una próspera agencia de publicidad especializada en trailers de películas, vive en el sur de California y acaba de romper con su novio. Por su parte, Iris Simpkins, redactora de la popular columna de bodas para el London Daily Telegraph, vive en una encantadora casa de campo en Inglaterra y sus relaciones con los hombres tampoco son fáciles. A través de internet llegan a un acuerdo para intercambiarse sus respectivas viviendas durante las Navidades.', trailer_url = 'https://www.youtube.com/watch?v=8j9RVBBMHLU' WHERE id_api = 'tt0457939';

UPDATE Contenido SET id_tmdb = 1771, descripcion = 'Nacido durante la Gran Depresión, Steve Rogers creció como un chico enclenque en una familia pobre. Horrorizado por las noticias que llegaban de Europa sobre los nazis, decidió enrolarse en el ejército; sin embargo, debido a su precaria salud, fue rechazado una y otra vez. Enternecido por sus súplicas, el general Chester Phillips le ofrece la oportunidad de tomar parte en un experimento especial: la Operación Renacimiento. Tras meses de preparación y entrenamiento recibe su primera misión como Capitán América. Armado con un escudo indestructible y su inteligencia para la batalla, el Capitán América emprende la guerra contra el mal, como centinela de la libertad y como líder de los Vengadores.', trailer_url = 'https://www.youtube.com/watch?v=YqEJ0jpFvSU' WHERE id_api = 'tt0458339';

UPDATE Contenido SET id_tmdb = 350, descripcion = 'En el vertiginoso mundo de la moda en Nueva York, la revista ''Runway'' es el Santo Grial. Dirigida con puño de hierro y elegante manicura por Miranda Priestly, trabajar en ella es un temible reto para todo aquel que quiera triunfar en ese mundo. Hacerlo como ayudante de Miranda podría abrirle cualquier puerta a Andy Sachs, recientemente graduada. Pero ella es una chica que destaca por su desaliño dentro del pequeño ejército de guapísimas redactoras de la revista. Andy comprende muy pronto que para triunfar en ese negocio va a necesitar algo más que iniciativa y determinación. Y la prueba definitiva está delante de ella, vestida de Prada de pies a cabeza.', trailer_url = 'https://www.youtube.com/watch?v=bb3NblYZwQU' WHERE id_api = 'tt0458352';

UPDATE Contenido SET id_tmdb = 189, descripcion = 'En las sórdidas calles de Sin City, un hombre busca su venganza. Dwight trata de ajustar cuentas con la misteriosa Ava Lord, la letal mujer que le traicionó. Nancy intenta superar la muerte de Hartigan, y Johny tiene una peligrosa misión: acabar con el mayor villano de Sin City. En su propósito, conocerá a la joven stripper Marcy.', trailer_url = 'https://www.youtube.com/watch?v=GsbVj-yTvQI' WHERE id_api = 'tt0458481';

UPDATE Contenido SET id_tmdb = 2080, descripcion = 'Precuela de la película X-Men. Situada 17 años antes, narra los inicios del arma X y la forma en la que Wolverine se convirtió en mutante. Logan, convertido en un mutante que se hace llamar Wolverine, y que es capaz de sacar unas afiladas garras y de una fuerza y agilidad sobrehumana, ultima su venganza contra Victor Creed, culpable de la muerte de su novia. Mientras tanto, otros mutantes se acogen al programa X para unir sus fuerzas.', trailer_url = 'https://www.youtube.com/watch?v=lAd9dtKN7fk' WHERE id_api = 'tt0458525';

UPDATE Contenido SET id_tmdb = 4194, descripcion = 'La escasa tropa Jedi lucha por mantener la libertad y devolver la paz a la Galaxia frente al aparentemente interminable ejército droide, clones diseñados genéticamente. A través de cientos de planetas, los Caballeros Jedi y los Separatistas combaten por el futuro de la Galaxia, pero el número de planetas que van cayendo en manos del Lado Oscuro cada vez es mayor a causa de los movimientos de los Separatistas. El terrible conflicto se agrava porque nuestros héroes se ven absorbidos por la confusión de guerra, mientras el Conde Dooku, el asesino Asajj Ventress, su maestro Darth Sidious, el General Grievous y una amplia galería de enemigos nunca antes visto también conspiran y se unen para derrotarlos.

La historias de la serie ''Star Wars: The clone wars'' transcurre entre el "Episodio II: El ataque de los clones'' y el "Episodio III: La venganza de los Sith" de la saga Star Wars.', trailer_url = 'https://www.youtube.com/watch?v=ZLW2jkd6E7g' WHERE id_api = 'tt0458290';

