UPDATE Contenido SET id_tmdb = 2317, descripcion = 'La vida de Earl está llena de decisiones erróneas. Cuando, de repente, un pequeño premio de lotería parece anunciar un cambio en su vida, es atropellado por un coche y el billete premiado desaparece volando mientras Earl está inconsciente. En el hospital Carson Daly le enseña que el éxito de una persona depende del bien que haga a los demás. Tras salir del hospital, Earl encuentra el billete y decide empezar a hacer el bien: empieza por elaborar una lista con todas las cosas que ha hecho mal para ir compensándolas con buenas acciones.', trailer_url = 'https://www.youtube.com/watch?v=LyAKsyDN_04' WHERE id_api = 'tt0460091';

