UPDATE Contenido SET id_tmdb = 12225, descripcion = 'Ben Willis, estudiante de Bellas Artes, sufre de insomnio como consecuencia del abandono de su novia, Suzy. Para hacer más llevadera la vigilia, empieza a trabajar en el turno de noche del supermercado del barrio. Aquí conoce a gente de lo más variopinta que ha desarrollado su propia manera de hacer frente al aburrimiento de un turno de ocho horas. Ben se imagina a sí mismo parando el tiempo; de esta manera, es capaz de apreciar la belleza de un mundo congelado con la gente dentro, especialmente con Sharon, la cajera callada que quizás guarde el secreto para resolver el problema del insomnio de Ben.', trailer_url = 'https://www.youtube.com/watch?v=JEBhL6ks7E4' WHERE id_api = 'tt0460740';

