UPDATE Contenido SET id_tmdb = 14784, descripcion = 'Hollywood, años veinte. Tras una desafortunada caída, un especialista en secuencias de acción es ingresado en un hospital. Allí conoce a Alexandria, una niña con un brazo roto a la que hace una promesa: si ella le consigue morfina, él le contará una historia maravillosa. El relato se extiende a todos los rincones del mundo. Remake de la película búlgara "Yo Ho Ho" (1981) de Zako Heskija.', trailer_url = 'https://www.youtube.com/watch?v=th0MkemV-k4' WHERE id_api = 'tt0460791';

UPDATE Contenido SET id_tmdb = 1730, descripcion = 'La percepción de la realidad de una actriz (Laura Dern) se va distorsionando cada vez más. Al mismo tiempo descubre que, quizá, se está enamorando de su partenaire (Justin Theroux) en un remake polaco inconcluso y supuestamente maldito.', trailer_url = 'https://www.youtube.com/watch?v=vEJdmFXZxMI' WHERE id_api = 'tt0460829';

UPDATE Contenido SET id_tmdb = 1116, descripcion = 'Irlanda, 1920. Dos hermanos se alistan en la guerrilla para combatir contra las tropas británicas que intentan impedir la independencia de Irlanda. El amor por su país hace que Damien abandone su prometedora carrera de médico y se una a su hermano Teddy en la lucha por la libertad. Tras sufrir varias derrotas y un escalofriante número de bajas, el Gobierno Británico decide pactar con los rebeldes para poner fin al sangriento enfrentamiento. Pero el acuerdo alcanzado provoca divisiones entre los irlandeses y desemboca en un nuevo y fraticida conflicto armado.', trailer_url = 'https://www.youtube.com/watch?v=6yvHe_ksnDA' WHERE id_api = 'tt0460989';

UPDATE Contenido SET id_tmdb = 254302, descripcion = 'Adaptación de High Rise, novela publicada por J.G. Ballard a mediados de los años ‘70. La historia narra la llegada del doctor Robert Laing a la Torre Elysium, un enorme rascacielos dentro del cual se desarrolla todo un mundo aparte, en el cual parece existir la sociedad ideal. Pero secretamente, el recién llegado se sentirá perturbado ante la posibilidad de que este orden utópico no sea tal. Sospechas que rápidamente serán corroboradas de la forma más siniestra.', trailer_url = 'https://www.youtube.com/watch?v=9LG801J-fnE' WHERE id_api = 'tt0462335';

UPDATE Contenido SET id_tmdb = 4523, descripcion = 'Narra la odisea que debe vivir la bella princesa Giselle, que es transportada por un hechizo de la malvada reina desde su mágico mundo a la moderna y caótica Manhattan actual. Inmersa en un entorno en el que el "fueron felices y comieron perdices" no funciona, deambula por un mundo caótico que necesita urgentemente unos cuantos hechizos. Sin embargo, Giselle se enamora de un abogado divorciado, encantador pero nada perfecto que decide ayudarla. A pesar de que en su mundo está prometida al príncipe de cuento de hadas, la joven princesa se hará la siguiente pregunta: ¿Su visión del amor ideal tiene futuro en el mundo real?', trailer_url = 'https://www.youtube.com/watch?v=rwTNJgffMco' WHERE id_api = 'tt0461770';

UPDATE Contenido SET id_tmdb = 7874, descripcion = 'En un pequeño pueblo de Tennessee, el viejo bluesman Lazarus (Samuel L. Jackson) rescata a la joven Rae (Christina Ricci), que yace medio muerta al borde de la carretera. Rae, víctima de su insaciable apetito sexual, goza de una pésima reputación en todo el pueblo; así que Lazarus decide secuestrarla para apagar sus ansias. Empiezan así una aventura en común que los lleva a enfrentarse a sus demonios, pero la situación se complica cuando reaparece Ronnie (Justin Timberlake), un viejo novio de Rae.', trailer_url = 'https://www.youtube.com/watch?v=VYMqX3SKIGY' WHERE id_api = 'tt0462200';

UPDATE Contenido SET id_tmdb = 285923, descripcion = 'Grindhouse es una película de terror dividida en 2 partes, una dirigida por Tarantino y la otra por Robert Rodríguez, siendo cada una de ellas de algo más de una hora de duración. A su vez ambas están separadas por falsos trailers de películas de terror, creados por los conocidos directores del género Eli Roth, Rob Zombie, Edgar Wright.  "Planet Terror", dirigida por Rodríguez, se trata de una película de zombies. Mientras los afectados por un extraño virus se convierten en un ejército de agresores enloquecidos, Cherry, una bailarina de striptease lisiada, y su ex-novio Wray dirigen un espontáneo equipo de guerreros, adentrándose en la noche hacia un destino que dejará millones de afectados, infinidad de muertos y unos cuantos afortunados supervivientes que lucharán por encontrar el último rincón seguro en el mundo.', trailer_url = 'https://www.youtube.com/watch?v=j1cjXKdox0M' WHERE id_api = 'tt0462322';

UPDATE Contenido SET id_tmdb = 10529, descripcion = 'Vikingos, año 509. Una nave espacial se estrella en la antigua Noruega. De su interior salen un guerrero humanoide llamado Kainan y una sanguinaria criatura conocida como El Moorwen, una bestia salvaje dispuesta a vengar la extinción de su raza a manos del ejército del guerrero. Mientras El Moorwen devasta los territorios vikingos, asesinando a quien se le pone por delante, Kainan, combinando su avanzada tecnología con armas antiguas, se dedica a formar a un grupo de primitivos pero feroces guerreros. El objetivo es claro: acabar con la brutal criatura.', trailer_url = 'https://www.youtube.com/watch?v=5JRjjUTbr94' WHERE id_api = 'tt0462465';

UPDATE Contenido SET id_tmdb = 7555, descripcion = 'John Rambo, el ex-boina verde con una ajetreada vida marcada por la guerra, vive ahora una solitaria y apacible existencia en la jungla del norte de Tailandia, pescando y cazando cobras para luego venderlas. Todo cambia cuando un grupo de misioneros católicos necesita que les guíe hasta la frontera con Birmania para suministrar medicinas y alimentos a unos refugiados asediados por el ejército birmano, que ha hecho de las torturas y los asesinatos algo habitual. Rambo no tendrá más remedio que volver a involucrarse. Se verá obligado a hacer lo que mejor sabe porque, muy a su pesar, lleva la guerra en la sangre.', trailer_url = 'https://www.youtube.com/watch?v=2oVMgRVk4lE' WHERE id_api = 'tt0462499';

UPDATE Contenido SET id_tmdb = 35, descripcion = 'Homer debe salvar al mundo de una catástrofe que él mismo ha provocado. Todo comienza con Homer, su nueva mascota, un cerdo, y un silo lleno de excrementos que tiene una fuga, una combinación que desencadena un desastre distinto a todo lo que Springfield haya experimentado jamás. Mientras Marge está indignada por la monumental metedura de pata de su patán marido, una turba vengativa cae sobre el hogar de los Simpson...', trailer_url = 'https://www.youtube.com/watch?v=tA7sOkuziSc' WHERE id_api = 'tt0462538';

UPDATE Contenido SET id_tmdb = 9952, descripcion = 'Durante la Guerra de Vietman, dos pilotos de las fuerzas americanas son derribados y capturados durante una misión. Ambos intentarán sobrevivir sufriendo las condiciones más extremas.', trailer_url = 'https://www.youtube.com/watch?v=oByaEHTGBUM' WHERE id_api = 'tt0462504';

UPDATE Contenido SET id_tmdb = 1562, descripcion = 'Seis meses después de que la propagación del virus haya aniquilado las Islas Británicas, el ejército de los Estados Unidos declara que ha ganado la guerra contra la infección y que puede comenzar la reconstrucción del país. Con la primera ola de refugiados que vuelve al país, una familia consigue reencontrarse. Pero uno de los miembros guarda un terrible secreto sin ser consciente de ello. El virus aún no ha sido destruido y en esta ocasión, es más peligroso que nunca.', trailer_url = 'https://www.youtube.com/watch?v=gPOt4mAEfBE' WHERE id_api = 'tt0463854';

UPDATE Contenido SET id_tmdb = 9762, descripcion = 'Tyler Gage (Channing Tatum) ha crecido y pasado toda su vida en los barrios más peligrosos de la ciudad de Baltimore y sabe que es poco probable que alguna vez salga de ahí. Un día, tras un roce con la ley, Tyler es sentenciado a realizar un servicio comunitario en la Escuela de Artes de Maryland. Allí conoce a Nora (Jenna Dewan), una atractiva bailarina que está buscando desesperadamente a alguien que sustituya a su compañero, de baja por accidente, antes de la importantísima Exhibición Senior de la escuela.', trailer_url = 'https://www.youtube.com/watch?v=Jxs9s6SXtZQ' WHERE id_api = 'tt0462590';

UPDATE Contenido SET id_tmdb = 9615, descripcion = 'Shaun Boswell es un chico que no acaba de encajar en ningún grupo. Su única conexión con el mundo de indiferencia que le rodea es a través de las carreras ilegales, lo que no le ha convertido en el chico favorito de la policía. Cuando amenazan con encarcelarle, le mandan fuera del país a pasar una temporada con su tío, un militar destinado en Japón. En el país donde nacieron la mayoría de los coches modificados, las simples carreras en la calle principal han sido sustituidas por el último reto automovilístico que desafía la gravedad, las carreras de "drift" (arrastre), una peligrosa mezcla de velocidad en pistas con curvas muy cerradas y en zigzag. En su primera incursión en el salvaje mundo de las carreras de "drift", Shaun acepta ingenuamente conducir un D.K, el Rey del Drift, que pertenece a los Yakuza, la mafia japonesa. Para pagar su deuda, no tiene más remedio que codearse con el hampa de Tokio y jugarse la vida.', trailer_url = 'https://www.youtube.com/watch?v=H6H5ivznn8A' WHERE id_api = 'tt0463985';

UPDATE Contenido SET id_tmdb = 1819, descripcion = 'Los recién casados Carl y Molly Peterson se encuentran con una inesperada visita en su perfectamente construido paraíso conyugal. Se trata de Dupree, un vividor con alma de poeta martirizado por su jefe. Cuando se coge una semana para ir como padrino de boda de Carl y Molly en Hawai, lo despiden de la empresa. Sin trabajo, sin coche, sin casa, Dupree se instala con los Peterson indefinidamente.', trailer_url = 'https://www.youtube.com/watch?v=TluIBiITdkA' WHERE id_api = 'tt0463034';

UPDATE Contenido SET id_tmdb = 1646, descripcion = 'Erin Gruwell es una joven profesora recién licenciada que empieza a trabajar dando clases de lengua en un instituto de Long Beach (California), cuyos alumnos, que viven en barrios marginales, están marcados por la violencia de las bandas. Después de un mal comienzo, descubre cómo ganarse su respeto y confianza y cómo ayudarles a cambiar: les habla de Ana Frank y de otros adolescentes, menos afortunados que ellos, que vivieron grandes tragedias y escribieron sobre ellas.', trailer_url = 'https://www.youtube.com/watch?v=miz1V13QWsU' WHERE id_api = 'tt0463998';

UPDATE Contenido SET id_tmdb = 6537, descripcion = 'Laura regresa con su familia al orfanato en el que creció de niña, con la intenció de abrir una residencia para niños discapacitados. El nuevo entorno despierta la imaginació de su hijo, que comienza a dejarse llevar por juegos de fantasía cada vez más intensos. Éstos van inquietando a Laura cada vez más, hasta el punto en el que llega a pensar que hay algo en la casa que está amenazando a su familia. A ella le ocurre algo extraordinario y, a pesar de que es una mujer con unos principios muy claros, su universo se tambalea poniendo en duda todo aquello en lo que creía...', trailer_url = 'https://www.youtube.com/watch?v=t-OlnNqnddQ' WHERE id_api = 'tt0464141';

UPDATE Contenido SET id_tmdb = 43593, descripcion = 'El lago Victoria (Arizona) es un lugar que se llena de gente joven durante las vacaciones de primavera. De repente, se producen una serie de temblores submarinos que liberan unos peces prehistóricos antropófagos. Todos deberán unir sus fuerzas para sobrevivir a estas criaturas. Remake del clásico de terror dirigido por Joe Dante', trailer_url = 'https://www.youtube.com/watch?v=AImr8U_7CX4' WHERE id_api = 'tt0464154';

UPDATE Contenido SET id_tmdb = 1620, descripcion = 'Basada en el famoso videojuego del mismo nombre. El agente 47 (Olyphant) es contratado por una misteriosa organización conocida como ''La Agencia'' para matar por dinero. El cazador se convertirá en la presa tras un cambio de régimen político. Tanto la Interpol como el ejército ruso perseguirá al asesino por toda Europa del Este, mientras él intenta averiguar quién le tendió la trampa y por qué.', trailer_url = 'https://www.youtube.com/watch?v=n7Q4sIADfZo' WHERE id_api = 'tt0465494';

UPDATE Contenido SET id_tmdb = 6637, descripcion = 'El buscador de tesoros Ben Gates (Cage) se ve de nuevo envuelto en una extraordinaria aventura, en la que se combinan períodos desconocidos de la historia y tesoros ocultos. Cuando una página del diario de John Wilkes Booth, el asesino de Abraham Lincoln, sale a la luz, el tatarabuelo de Ben se ve implicado como el principal instigador del magnicidio. Decidido a probar la inocencia de su antepasado, Ben y su equipo emprenden un viaje que los lleva a descubrir uno de los tesoros más buscados del mundo.', trailer_url = 'https://www.youtube.com/watch?v=INo4JrUl0YY' WHERE id_api = 'tt0465234';

UPDATE Contenido SET id_tmdb = 4566, descripcion = 'Michael Clayton (George Clooney) es un ex fiscal que trabaja para un gran bufete de abogados en Nueva York. Insatisfecho con su trabajo, su divorcio y su fracaso financiero, está involucrado con el caso de una demanda colectiva contra una empresa que fabrica productos que pueden poner en peligro la salud de sus usuarios.', trailer_url = 'https://www.youtube.com/watch?v=oOfhr8EVZIM' WHERE id_api = 'tt0465538';

UPDATE Contenido SET id_tmdb = 13455, descripcion = 'La División, una agencia gubernamental clandestina, tiene un oscuro fin: alterar genéticamente a personas normales para convertirlas en soldados con poderes psíquicos. Aquellos que no quieren participar o que están en contra, son eliminados. Nick Gant lleva escondiéndose de la División desde que, siendo un niño, asesinaron a su padre. Nick ha heredado sus poderes telequinéticos. Oculto en Hong Kong se siente seguro, pero se verá forzado a salir de su escondite cuando se cruce en su camino Cassie, una chica de 13 años que puede ver el futuro. Cassie le pide ayuda para encontrar a Kira, una joven que tiene la más poderosa de las habilidades psíquicas desarrollados por la División: puede implantar pensamientos en las mentes de los demás. Kira tiene la clave para acabar con la División, y Nick y Cassie tienen que encontrarla antes que ellos.', trailer_url = 'https://www.youtube.com/watch?v=e9udEfuWj2k' WHERE id_api = 'tt0465580';

UPDATE Contenido SET id_tmdb = 1259, descripcion = 'Barbara es una despótica y solitaria profesora que gobierna su aula con mano de hierro en una ruinosa escuela pública de secundaria londinense. Vive sola, con su gata Portia, no tiene amigos, pero su vida experimenta un cambio radical cuando conoce a Sheba Hart, la nueva y atractiva profesora de arte de la escuela. Barbara ve en ella al alma gemela y a la leal amiga que siempre ha estado buscando. Pero, cuando descubre que Sheba mantiene una tórrida relación con uno de sus jóvenes alumnos, la incipiente amistad da un ominoso giro, pues Barbara amenaza con contárselo todo al marido de Sheba y al mundo entero.', trailer_url = 'https://www.youtube.com/watch?v=AruRpjQquQQ' WHERE id_api = 'tt0465551';

UPDATE Contenido SET id_tmdb = 4141, descripcion = 'El señor Smith (Clive Owen), un misterioso y solitario pistolero, desbarata involuntariamente un extraño complot, cuando rescata a un bebé de una muerte segura. Para alimentar a su pequeño protegido, contrata a una prostituta (Monica Bellucci). Desde ese momento los dos se convierten en el objetivo de un peligroso mafioso (Paul Giamatti), que enviará a sus sicarios para eliminar al niño.', trailer_url = 'https://www.youtube.com/watch?v=jlx4n_ibNZE' WHERE id_api = 'tt0465602';

UPDATE Contenido SET id_tmdb = 4474, descripcion = 'Un tranquilo joven de Nueva York se enamora de Jenny Johnson, una chica aparentemente normal que resulta ser una superheroína, la chica-G. El problema será romper con una novia celosa y manipuladora… y con superpoderes que no está dispuesta a que la relación se acabe.', trailer_url = 'https://www.youtube.com/watch?v=7FY2efhRS4U' WHERE id_api = 'tt0465624';

UPDATE Contenido SET id_tmdb = 10073, descripcion = 'Nueva comedia de los creadores de "Scary Movie", que en esta ocasión parodian todo tipo de comedias románticas. Julia Jones, una romántica empedernida, conoce por fin al hombre de sus sueños, el muy británico Grant Folloatuhija. Pero antes de que puedan tener su "Gran Boda Griega", tendrá que conocer a "Los padres de ella"; contratar sus "Planes de boda", y pelearse con la amiga de Grant, Andy una espectacular mujer que quiere boicotear "La boda de su mejor amigo".', trailer_url = 'https://www.youtube.com/watch?v=23QoNhfK_qg' WHERE id_api = 'tt0466342';

UPDATE Contenido SET id_tmdb = 13051, descripcion = 'Adaptación de un aclamado videojuego que mezcla el thriller con el cine negro, la historia gira en torno a Max Payne (Wahlberg), un ex-policía de Nueva York que busca a los asesinos de su esposa y su bebé, ambos asesinados bajo los efectos de una fuerte droga sintética.', trailer_url = 'https://www.youtube.com/watch?v=6ZJHFcfiSto' WHERE id_api = 'tt0467197';

