UPDATE Contenido SET id_tmdb = 7326, descripcion = 'Juno Macguff tiene 16 años y es, según los adultos que la rodean, más inteligente de lo que le conviene. Y sí, es cierto, es ingeniosa, culta, rápida en las respuestas, observadora y, sobre todo, sarcástica. Ese sarcasmo es su particular trinchera para esconder sus miedos y las dudas. La relación que mantiene con un compañero de clase, Bleeker, acaba de dejar fruto: está embarazada. A él le interesa poco el asunto, o más bien nada. Juno está sola con su problema pero ya ha tomado una decisión: tendrá el niño y lo dará en adopción. Su padre y su madrastra están de acuerdo. Ahora hay que encontrar padres adoptivos adecuados. Son Mark y Vanessa, y son ideales. Sólo que Mark comparte demasiado con Juno, demasiadas aficiones comunes y un entendimiento a primera vista...', trailer_url = 'https://www.youtube.com/watch?v=Nj0gq4LiSHY' WHERE id_api = 'tt0467406';

UPDATE Contenido SET id_tmdb = 155, descripcion = 'Batman/Bruce Wayne regresa para continuar su guerra contra el crimen. Con la ayuda del teniente Jim Gordon y del Fiscal del Distrito Harvey Dent, Batman se propone destruir el crimen organizado en la ciudad de Gotham. El triunvirato demuestra su eficacia, pero, de repente, aparece Joker, un nuevo criminal que desencadena el caos y tiene aterrados a los ciudadanos.', trailer_url = 'https://www.youtube.com/watch?v=_PZpmTj1Q8Q' WHERE id_api = 'tt0468569';

UPDATE Contenido SET id_tmdb = 12184, descripcion = 'Inglaterra, siglo XVI. Narra la historia de dos hermanas, Ana y María Bolena (Portman &amp; Johansson). El padre y el tío de ambas, movidos por la ambición de mejorar el nivel social y el poder de la familia, convencen a las jóvenes para que conquisten el amor de Enrique VIII, Rey de Inglaterra. Ana y María abandonan su vida en el campo para trasladarse al peligroso y apasionante mundo de la corte. Pero, pronto surge entre ellas una rivalidad sin cuartel para obtener el amor del Rey. Al principio, el Rey escoge como amante a María y tiene con ella un bastardo. Pero Ana, que es muy inteligente y astuta, consigue eclipsar a su hermana e, incluso, que el rey repudie a Catalina de Aragón, su legítima esposa.', trailer_url = 'https://www.youtube.com/watch?v=2YoiWr-yvws' WHERE id_api = 'tt0467200';

UPDATE Contenido SET id_tmdb = 1255, descripcion = 'Los habitantes de Seúl observan sorprendidos un extraño objeto que cuelga de un puente sobre el río Han. El objeto es, en realidad, una monstruosa criatura mutante que al despertar devora a todo aquel que se cruza en su camino. En medio de tanto horror, la criatura mutante rapta a la hija del dueño de un quiosco que vive felizmente a la orilla del río. Mientras el ejército fracasa una y otra vez en sus intentos de destruir al monstruo, este hombrecillo anónimo y su familia intentan recuperar a su hija.', trailer_url = 'https://www.youtube.com/watch?v=jDmbIm3gCUk' WHERE id_api = 'tt0468492';

