UPDATE Contenido SET id_tmdb = 7345, descripcion = 'Texas, principios del siglo XX. Una historia sobre la familia, la avaricia y la religión. Daniel Plainview (Daniel Day-Lewis) se traslada a una miserable ciudad con el propósito de hacer fortuna, pero, a medida que se va enriqueciendo, sus principios y valores desaparecen y acaba dominado por la ambición. Tras encontrar un rico yacimiento de petróleo en 1902, se convierte en un acaudalado magnate. Cuando, años después, intenta apoderarse de un nuevo yacimiento, tiene que enfrentarse al predicador Eli Sunday (Paul Dano). Adaptación de la novela de Upton Sinclair "Petróleo", escrita en 1927.', trailer_url = 'https://www.youtube.com/watch?v=wwlpxn5CF2g' WHERE id_api = 'tt0469494';

UPDATE Contenido SET id_tmdb = 1852, descripcion = 'El 11 de septiembre de 2001, dos aviones de pasajeros se estrellan contra las Torres Gemelas del complejo World Trade Center de Nueva York. Dos policías, el sargento John McLoughlin (Nicolas Cage) y Will Jimeno (Michael Peña), intentarán ayudar a las personas afectadas por la tragedia.', trailer_url = 'https://www.youtube.com/watch?v=QH_9vgtVVvk' WHERE id_api = 'tt0469641';

UPDATE Contenido SET id_tmdb = 59108, descripcion = 'Josh Kovaks lleva diez años como encargado de los pisos más lujosos y más vigilados de todo Nueva York. Nada le pasa desapercibido. Arthur Shaw es un pez gordo de Wall Street que está en arresto domiciliario en el piso más ostentoso del edificio después de ser acusado del robo de dos mil millones de dólares a sus inversores. Y de estos últimos, ¿quién va a sufrir más? El personal de “The Tower”, que le entregó su plan de pensiones. Sólo faltan unos días para que Shaw se salga con la suya. Josh y su gente deciden recurrir a Slide, un delincuente de poca monta, para conseguir lo imposible: robar los 20 millones de dólares que deben estar escondidos en el piso donde Shaw permanece vigilado por un equipo del FBI encabezado por la agente especial Claire Denham.', trailer_url = 'https://www.youtube.com/watch?v=M_lCuLcKf6c' WHERE id_api = 'tt0471042';

UPDATE Contenido SET id_tmdb = 1579, descripcion = 'Historia ambientada en la época del imperio maya. Cuando la idílica existencia de los mayas es brutalmente interrumpida por el ataque de una fuerza invasora, un hombre emprende un arriesgado viaje a un mundo regido por el miedo y la opresión en el que le espera un incierto final. Debido a un giro del destino y espoleado por el amor a su esposa y a su familia, emprenderá el regreso a su hogar en un desesperado esfuerzo por preservar su forma de vida...', trailer_url = 'https://www.youtube.com/watch?v=gSw5l5jMnPM' WHERE id_api = 'tt0472043';

