UPDATE Contenido SET id_tmdb = 14410, descripcion = 'Biopic de la vida del famoso rapero Notorious B.I.G., un voluminoso cantante de rap neoyorquino que irrumpió con fuerza en el mundo de la música del hip hop. Nacido en Brooklyn en 1972 como Christopher George Latore Wallace, tras una ajetreada vida que alternaba números uno en el billboard con arrestos, polémicas y multas, Notorious murió asesinado en un tiroteo en 1997. Tenía 24 años de edad.', trailer_url = 'https://www.youtube.com/watch?v=kDDv6pAbN_U' WHERE id_api = 'tt0472198';

UPDATE Contenido SET id_tmdb = 9543, descripcion = 'Una aventura que tiene lugar en la mítica tierra de Persia. Un príncipe algo granuja (Jake Gyllenhaal) se ve forzado a unirse a una misteriosa princesa (Gemma Arterton) para enfrentarse a fuerzas oscuras con el fin de salvaguardar una antigua daga capaz de liberar las Arenas del Tiempo -un regalo de los dioses que puede volver atrás el tiempo y otorga a su dueño el poder sobre el mundo.', trailer_url = 'https://www.youtube.com/watch?v=9xaKIiZjh8c' WHERE id_api = 'tt0473075';

UPDATE Contenido SET id_tmdb = 10758, descripcion = 'Jenna (Keri Russell), una camarera de un pequeño pueblo norteamericano, se queda embarazada de su abusivo marido Earl (Jeremy Sisto), y expresa sus sentimientos a través de sus creaciones culinarias, como su pastel de ''embarazada-miserable-perdedora-quejica''. En esa difícil situación, conoce a alguien que quizás pueda ayudarla.', trailer_url = 'https://www.youtube.com/watch?v=hvus7pXX2Ew' WHERE id_api = 'tt0473308';

UPDATE Contenido SET id_tmdb = 16995, descripcion = 'Thriller acerca de un congresista y un reportero que se ven envueltos en un caso de brutales asesinatos que, aparentemente, no tienen relación entre sí.  Russell Crowe es Cal McCaffrey, un periodista de Washington D.C., cuyo olfato le lleva a desenmarañar los misteriosos asesinatos de algunas de las figuras más prometedoras de la política y de la gran empresa. El apuesto congresista Stephen Collins representa el futuro de su partido: debido a su honradez, ha sido elegido presidente del comité que supervisa los gastos de defensa. Hasta que alguien asesina brutalmente a su ayudante/amante y los secretos se escapan de su escondite. McCaffrey tiene la dudosa fortuna de ser un viejo amigo de Collins y de que su jefa sea totalmente despiadada y le mande a investigar el caso. Mientras sigue la pista del asesino con la ayuda de su compañera Della, descubre una tapadera que amenaza con hacer temblar las estructuras del poder de la nación.', trailer_url = 'https://www.youtube.com/watch?v=iTzyDVi2JTQ' WHERE id_api = 'tt0473705';

UPDATE Contenido SET id_tmdb = 1494, descripcion = 'China, siglo X, dinastía Tang. En vísperas del Festival Chong Yang, el Palacio Imperial se llena de flores doradas. El regreso inesperado del Emperador, con el príncipe Jai, para celebrar la fiesta con su familia, resulta sospechoso, pues su relación con la Emperatriz es muy fría. Durante muchos años, la Emperatriz y el Príncipe heredero Wan, su hijastro, han mantenido una relación ilícita, pero Wan se siente atrapado y sueña con huir del palacio con Chan, la hija del médico Imperial. Mientras tanto, el Príncipe Jai, el hijo fiel, crece preocupado por la salud de la Emperatriz y su obsesión por los crisantemos dorados.', trailer_url = 'https://www.youtube.com/watch?v=c-W5dl98ZWA' WHERE id_api = 'tt0473444';

UPDATE Contenido SET id_tmdb = 9829, descripcion = 'El 11 de septiembre de 2001 cuatro aviones fueron secuestrados. Tres alcanzaron su objetivo, pero el cuarto no. Relato de la tragedia por medio de una meticulosa recreación de los acontecimientos que rodearon al vuelo 93 de United Airlines con la esperanza de tener una visión más amplia de los hechos. La película, realizada con el apoyo de las familias de los pasajeros que viajaban a bordo del avión, relata en tiempo real la dramática historia de lo que ocurrió en el aire y en tierra, mientras los pasajeros, la tripulación, los controladores aéreos y los centros militares intentaban entender y solucionar una crisis inimaginable.', trailer_url = 'https://www.youtube.com/watch?v=kHdqw6scuIc' WHERE id_api = 'tt0475276';

UPDATE Contenido SET id_tmdb = 7516, descripcion = 'El jefe mafioso Primo Sparazza ofrece una generosa recompensa de 1 millón de dólares a quien liquide a Buddy ''Aces'' Israel (Jeremy Piven), un mago de tres al cuarto que va a testificar contra la mafia de Las Vegas. El FBI ve la oportunidad de usar al embaucador para atrapar a Sparazza, y ofrece protección a Aces, al que custodiarán dos agentes (Ryan Reynolds & Ray Liotta) en su refugio de Lake Tahoe. Cuando la comunidad de malhechores presentes, pasados y futuros, se entera del precio de la cabeza de ''Aces'', una multitud de cazadores de recompensas, matones, bellas y sensuales sirenas traidoras y mafiosos salen de caza. Con Lake Tahoe como objetivo, la colección de chorizos se lanza a una cómica carrera en su intento de matar a ''Aces'' y llevarse el botín...', trailer_url = 'https://www.youtube.com/watch?v=0xXlrhW0ZbE' WHERE id_api = 'tt0475394';

UPDATE Contenido SET id_tmdb = 270487, descripcion = 'En el Hollywood de los años 50, uno de los grandes estudios pretende hacer una gran superproducción de romanos protagonizada por una gran estrella (Clooney), pero el actor es secuestrado durante el rodaje.', trailer_url = 'https://www.youtube.com/watch?v=vMUUKtF_BF0' WHERE id_api = 'tt0475290';

UPDATE Contenido SET id_tmdb = 63247, descripcion = 'Westworld está ambientada en un parque de atracciones futurista dirigido por el Doctor Robert Ford. Las instalaciones cuentan con androides cuya apariencia física es humana, y gracias a ellos los visitantes pueden introducirse en cualquier tipo de fantasía, por muy oscura que sea...', trailer_url = 'https://www.youtube.com/watch?v=sey1O3-PJjY' WHERE id_api = 'tt0475784';

UPDATE Contenido SET id_tmdb = 9954, descripcion = 'Los privilegios y la belleza abundan en la Academia Spenser, un internado de Nueva Inglaterra destinado a la élite dominante de la región. Los Hijos de Ipswich son cuatro de estos jóvenes estudiantes ligados por su ascendencia sagrada. Como descendientes de las primeras familias que se establecieron en la Colonia Ipswich, en la década de 1600, estos cuatro chicos tienen poderes especiales innatos. Cuando, de pronto, un quinto descendiente se traslada a vivir a la ciudad, comienzan a desvelarse ciertos secretos que amenazan con romper el pacto de silencio que ha protegido a sus familias durante años...', trailer_url = 'https://www.youtube.com/watch?v=mNdijA2KlJo' WHERE id_api = 'tt0475944';

UPDATE Contenido SET id_tmdb = 13393, descripcion = 'Sadik es un periodista de izquierdas que vive en el Estambul de los años 70, pese a que su padre hubiese querido que estudiara ingeniería agrícola para poder trabajar las tierras que tienen en su pequeño pueblo en la costa del Mar Egeo. Los problemas políticos (un golpe de Estado el 12 de Septiembre de 1980), le obligarán a volver a su lugar de origen y a enfrentarse a su familia. Pero no irá solo, juntó a él viajará su hijo Deniz, quien conocerá por primera vez a toda su gran familia y a su vez irá creciendo. (FILMAFFINITY)', trailer_url = 'https://www.youtube.com/watch?v=KTmrUXNxwWI' WHERE id_api = 'tt0476735';

UPDATE Contenido SET id_tmdb = 4413, descripcion = 'Erica es una locutora de radio de Nueva York cuya vida da un giro dramático cuando una noche ella y su prometido reciben una brutal paliza en plena calle, y él fallece como consecuencia de las heridas. Incapaz de superar la tragedia, Erica sigue rondando la zona en la que la atacaron, buscando pistas que la lleven a los responsables. Sin embargo, un agente de policía intuye poco a poco sus intenciones y trata de evitar que se tome la justicia por su mano...', trailer_url = 'https://www.youtube.com/watch?v=ypveUYwYEA8' WHERE id_api = 'tt0476964';

UPDATE Contenido SET id_tmdb = 9757, descripcion = 'Norbit (Eddie Murphy) no ha tenido una vida fácil. De pequeño fue abandonado ante la puerta de un restaurante chino, que hacía las veces de orfanato, donde le crió el Sr. Wong (Eddie Murphy). Las cosas se ponen aún peor cuando se ve obligado a casarse con Rasputia (Eddie Murphy), la malvada y tragona reina de la comida basura. Cuando Norbit ya no puede más y está a punto de rendirse, reaparece Kate (Thandie Newton), su gran amor de infancia...', trailer_url = 'https://www.youtube.com/watch?v=HFIdZpc2L6w' WHERE id_api = 'tt0477051';

UPDATE Contenido SET id_tmdb = 9963, descripcion = 'Linda Hanson (Sandra Bullock) tiene una casa preciosa, un marido que la quiere y dos hijas adorables. Su vida es perfecta, hasta que recibe una devastadora noticia: su esposo Jim (Julian McMahon) ha fallecido en un accidente de coche. Al despertarse a la mañana siguiente, Linda descubre que su marido sigue vivo. En un principio, Linda cree que el accidente ha debido de ser una pesadilla... hasta que ocurre de nuevo. Algunos días Jim sigue a su lado cuando se despierta, pero otros debe enfrentarse a la realidad de haberse quedado viuda. Por alguna razón inexplicable, los días están desordenados. La traumática premonición de Linda desencadena una serie de extraños sucesos que alteran el tiempo. En un intento desesperado por salvar a su familia, Linda lucha furiosamente contra el tiempo y el destino para intentar conservar todo lo que ella y Jim han construido juntos.', trailer_url = 'https://www.youtube.com/watch?v=Y0P1eFoln-A' WHERE id_api = 'tt0477071';

UPDATE Contenido SET id_tmdb = 44048, descripcion = 'El destino cruza las vidas de un veterano ingeniero y la de un joven conductor cuando ambos tengan que aunar sus fuerzas para enfrentarse a una peligrosa misión. Un ferrocarril cargado de material altamente toxico ha perdido el control y se encuentra avanzando sin dirección llevándose por delante todo lo que va encontrándose a su paso.Ambos hombres tendrán que hacer que el tren pare antes de descarrilar, evitando así que suceda una tragedia de enormes dimensiones físicas y humanas', trailer_url = 'https://www.youtube.com/watch?v=VHmcxmADgcU' WHERE id_api = 'tt0477080';

UPDATE Contenido SET id_tmdb = 6977, descripcion = 'El veterano de la Guerra de Vietnam ahora cazador Llewellyn Moss descubre por casualidad una sangrienta escena en algún lugar de la frontera entre Texas y México, mientras estaba cazando algunos animales en el árido paisaje. Se trata de un negocio que se cerró mal entre contrabandistas de drogas y algunos hombres locales de la zona, provocando la muerte de varios de ellos. Además de los cuerpos y paquetes de heroína, Llewellyn descubre en una maleta algo más de dos millones de dólares. Cuando Llewellyn toma la maleta con el dinero, provoca una reacción en cadena de catastrófica violencia y una carrera sangrienta de los que quieren darle caza.', trailer_url = 'https://www.youtube.com/watch?v=hgqMFacZQPk' WHERE id_api = 'tt0477348';

UPDATE Contenido SET id_tmdb = 64685, descripcion = 'Oskar Schell, un niño precoz de once años, es inventor, diseñador de joyas, astrofísico y pacifista. Tras la muerte de su padre en los atentados del 11 de septiembre de 2001, Oskar encuentra un misterioso sobre con una llave y se lanza a la búsqueda de la cerradura que esa llave puede abrir.', trailer_url = 'https://www.youtube.com/watch?v=YEDBGPT45Rk' WHERE id_api = 'tt0477302';

UPDATE Contenido SET id_tmdb = 13198, descripcion = 'Los suicidas por amor vagan como almas perdidas por un mundo que no es el cielo ni el infierno. Es el caso de Zia (Patrick Fugit) y de muchos más, desde un ángel caído, a un bombero desesperado o un músico ruso y hasta un turista accidental. Este grupo de ultratumba viajará en busca de respuestas al fallo de sus vidas, en busca de la felicidad y redención que no hallaron en el pasado.', trailer_url = 'https://www.youtube.com/watch?v=H1xRtrKq1kc' WHERE id_api = 'tt0477139';

UPDATE Contenido SET id_tmdb = 8967, descripcion = 'Jack es un niño que vive con sus hermanos y sus padres en la Norteamérica de los años cincuenta. Mientras que su madre encarna el amor y la ternura en el seno familiar, su padre representa la severidad, pues se cree obligado a enseñarle a enfrentarse a un mundo hostil. Así, este viaje que comienza con la pérdida de la inocencia llegará hasta nuestros días, con Jack ya adulto recordando ciertos momentos trascendentes de su infancia, y la influencia de éstos en lo que él es ahora, y en lo que representa en su vida espiritual el recuerdo de su familia.', trailer_url = 'https://www.youtube.com/watch?v=RrAz1YLh8nY' WHERE id_api = 'tt0478304';

UPDATE Contenido SET id_tmdb = 1593, descripcion = 'Un padre divorciado trata de establecerse, impresionar a su hijo y encontrar su destino. Él se presenta para un trabajo como vigilante nocturno en el Museo Americano de Historia Natural de la ciudad de Nueva York y, posteriormente, descubre que los objetos expuestos, animados por un artefacto mágico de Egipto, vuelven a la vida durante la noche. Al principio le va muy mal tratando de mantener el orden y la calma en el museo, pero al final se vuelve muy buen amigo de todos y juntos ayudan a recuperar aquel artefacto mágico egipcio, ya que ha sido robado por los antiguos vigilantes del museo.', trailer_url = 'https://www.youtube.com/watch?v=Ltba1_-tRT4' WHERE id_api = 'tt0477347';

UPDATE Contenido SET id_tmdb = 2710, descripcion = 'Cuatro amigos que regentan un pequeño bar en un barrio del sur de Philadelphia, la ciudad del amor fraternal, intentan mantener el equilibrio entre negocio y amistad, tarea nada fácil, ya que cada uno de ellos suele dejarse llevar únicamente por sus intereses personales, lo que desemboca en situaciones incómodas que amenazan con deteriorar sus relaciones personales.', trailer_url = 'https://www.youtube.com/watch?v=blLAdGYPhiQ' WHERE id_api = 'tt0472954';

