UPDATE Contenido SET id_tmdb = 6973, descripcion = 'Hank Deerfield, un veterano de guerra, investiga la desaparición de su hijo Mike, el cual, tras regresar de Irak, inexplicablemente se ha ausentado de su base sin permiso. Con la ayuda de la detective Sanders, irá reviviendo las experiencias del muchacho en Irak, pero tropieza con enormes dificultades por parte de las autoridades militares.', trailer_url = 'https://www.youtube.com/watch?v=K1jjeuLzF6Y' WHERE id_api = 'tt0478134';

UPDATE Contenido SET id_tmdb = 8065, descripcion = 'Ben Campbell, un tímido y brillante estudiante del Instituto Tecnológico de Massachussets (MIT), recurre a los naipes para poder pagar la matrícula de la universidad. Se le presenta, además, la oportunidad de unirse a un grupo de estudiantes que viajan a Las Vegas para jugar al blackjack. Bajo la dirección del poco ortodoxo profesor de matemáticas y genio de la estadística Micky Rosa, han conseguido descifrar el código del éxito, mediante el conteo de cartas.', trailer_url = 'https://www.youtube.com/watch?v=0DpvqzPdXoc' WHERE id_api = 'tt0478087';

UPDATE Contenido SET id_tmdb = 4964, descripcion = 'Allison Scott es una prometedora periodista de 24 años. Sin embargo, después de una noche de juerga con el vago de Ben Stone, descubre que está embarazada. Ante el dilema de enfrentarse sola a la maternidad o bien conocer mejor al padre, opta por lo segundo. Aunque Ben es una persona inmadura, decide afrontar su responsabilidad. Lo malo es que tanto él como Allison no tardan en darse cuenta de que son incompatibles. Para colmo de males, el único ejemplo de jóvenes padres que conocen son Debbie, la agobiada hermana de Allison, y el calzonazos de Pete. En cualquier caso tienen nueve meses para decidirlo.', trailer_url = 'https://www.youtube.com/watch?v=LYKB0TqHWLU' WHERE id_api = 'tt0478311';

UPDATE Contenido SET id_tmdb = 102899, descripcion = 'Armado con la asombrosa capacidad de reducir su tamaño a la dimensiones de un insecto, el estafador Scott Lang debe sacar a relucir al héroe que lleva dentro y ayudar a su mentor, el doctor Hank Pym, a proteger de una nueva generación de amenazas el secreto que se esconde tras el traje de Ant-Man, con un casco que le permite comunicarse con las hormigas. A pesar de los obstáculos aparentemente insuperables que les acechan, Pym y Lang deben planear y llevar a cabo un atraco para intentar salvar al mundo.', trailer_url = 'https://www.youtube.com/watch?v=gFd4AztySTo' WHERE id_api = 'tt0478970';

UPDATE Contenido SET id_tmdb = 1246, descripcion = 'El mundo del boxeo está tan devaluado que el campeón Mason Dixon no encuentra un rival a su altura. Han pasado 30 años desde que a Rocky Balboa, un hombre sin futuro, se le presentó la oportunidad de boxear y enfrentarse contra el gran campeón Apollo Creed. El coraje y perseverancia de Rocky, tanto en la vida como en el ring, alimentó las esperanzas de millones de personas. Ahora, ya retirado, se pasa las tardes contando viejas historias a los clientes del Adrian''s, el restaurante que lleva el nombre de su esposa, por la que todavía guarda un silencioso luto. Apenas ve a su hijo, que está demasiado centrado en su propia vida. El paso del tiempo y los golpes recibidos lo han hecho más humilde y lo han envejecido, pero en el fondo aún sigue siendo un luchador.', trailer_url = 'https://www.youtube.com/watch?v=uJ6O6jMeOho' WHERE id_api = 'tt0479143';

UPDATE Contenido SET id_tmdb = 10527, descripcion = 'Abandonados en las lejanas costas de Madagascar, los neoyorquinos han ideado un plan tan loco que hasta podría funcionar. Con precisión militar, los pingüinos han reparado un viejo avión estrellado. Una vez a bordo, esta improbable tripulación permanece en el aire el tiempo suficiente para aterrizar en el lugar más salvaje de todos: las vastas llanuras de la propia África, donde la tripulación se encuentra por primera vez con seres de su propia especie.', trailer_url = 'https://www.youtube.com/watch?v=20CzGelkYnM' WHERE id_api = 'tt0479952';

UPDATE Contenido SET id_tmdb = 1948, descripcion = 'Chev Chelios (Jason Statham), un asesino a sueldo de Los Ángeles, ha sido envenenado mientras dormía y que sólo le queda una hora de vida. La única oportunidad que tiene Chev de sobrevivir es mantenerse en movimiento para impedir que el veneno le llegue al corazón. El tiempo pasa y corre enloquecido por las calles de Los Ángeles para salvar a su novia y encontrar un antídoto que le salve la vida.', trailer_url = 'https://www.youtube.com/watch?v=218nsccFpag' WHERE id_api = 'tt0479884';

UPDATE Contenido SET id_tmdb = 23047, descripcion = 'A mediados del siglo XIV, el caballero Lavey (Nicolas Cage) escolta hasta un monasterio a una joven acusada de brujería. Los monjes aseguran que ella es la responsable de que la Peste Negra asole y destruya Europa. Lavey, escéptico, no acepta esta explicación y con un grupo de bravos guerreros emprende un viaje para demostrar la inocencia de la joven, pero el azar los conducirá a un lugar donde les esperan las fuerzas de las oscuridad...', trailer_url = 'https://www.youtube.com/watch?v=nW7OeOd3iRM' WHERE id_api = 'tt0479997';

UPDATE Contenido SET id_tmdb = 11798, descripcion = 'Durante las vacaciones de verano de 1983, Shaun, un niño solitario cuyo padre ha muerto en la guerra de Las Malvinas, es adoptado por un grupo de cabezas rapadas (skinheads). Con sus nuevos amigos, Shaun descubre las fiestas, su primer amor y las botas Dr. Martins. Uno de sus amigos es Combo, un skin racista que acaba de salir de la cárcel.', trailer_url = 'https://www.youtube.com/watch?v=OhhlH44bRew' WHERE id_api = 'tt0480025';

UPDATE Contenido SET id_tmdb = 7211, descripcion = 'Dan (Steve Carrel), columnista en un periódico local, vive con el recuerdo de su esposa fallecida, y dedicado por completo a sus tres hijas. Su vida cambia cuando conoce a Marie (Juliette Binoche), la nueva novia de su hermano menor (Dan Cook).', trailer_url = 'https://www.youtube.com/watch?v=5t2lxao1MvM' WHERE id_api = 'tt0480242';

UPDATE Contenido SET id_tmdb = 48988, descripcion = 'Dos amigos lamentan que el matrimonio les haya arruinado toda posibilidad de diversión, especialmente en lo que al sexo se refiere; sus esposas deciden entonces concederles un fin de semana libre, un paréntesis de libertad, en el que podrán desmadrarse todo lo que quieran, sin remordimientos ni explicaciones', trailer_url = 'https://www.youtube.com/watch?v=5m3sgE67SR0' WHERE id_api = 'tt0480687';

UPDATE Contenido SET id_tmdb = 6479, descripcion = 'Año 2012. Robert Neville es el último hombre vivo que hay sobre la Tierra, pero no está solo. Los demás seres humanos se han convertido en unos mutantes nocturnos llamados "Darkseekers" y todos ansían beber su sangre. Durante el día vive en estado de alerta, como un cazador, y busca a los muertos vivientes mientras duermen; pero durante la noche debe esconderse de ellos y esperar el amanecer. Esta pesadilla empezó hace tres años: Neville era un brillante científico, pero no pudo impedir la expansión de un terrible virus creado por el hombre. Él ha sobrevivido porque es inmune al virus; todos los días envía mensajes por radio con la esperanza de que haya otros supervivientes, pero es inútil. Lo único que puede hacer es buscar una fórmula que le permita utilizar su sangre inmune para devolverles a los hombres su naturaleza. Pero está en inferioridad de condiciones y el tiempo se acaba.', trailer_url = 'https://www.youtube.com/watch?v=F53gHFtGSwQ' WHERE id_api = 'tt0480249';

UPDATE Contenido SET id_tmdb = 14139, descripcion = 'Un hombre descubre a través de sus prismáticos a una preciosa joven e intenta encontrarla en la profundidad del bosque. De repente, un individuo armado con unas tijeras y con la cara cubierta por vendas rosas le ataca por la espalda. Consigue huir y alcanza un complejo científico en mitad del bosque. Allí, una máquina lo transporta al pasado, poco más de una hora. Encontrarse consigo mismo será la primera de una serie de catástrofes de consecuencias imprevisibles.', trailer_url = 'https://www.youtube.com/watch?v=vmi3OY7cQfA' WHERE id_api = 'tt0480669';

UPDATE Contenido SET id_tmdb = 34813, descripcion = 'Una historia de caminos cruzados y venganza, centrada en un grupo de las Fuerzas Especiales, enviado a la jungla boliviana y traicionado por uno los suyos, del que sólo saben su nombre: Max. Dados por muertos, el grupo hace planes para igualar el marcador, cuando se les une la misteriosa Aisha, que tiene sus propios planes. Trabajan juntos en secreto para seguir la pista del bien custodiado Max, quien pretende involucrar al mundo en una guerra global de alta tecnología.', trailer_url = 'https://www.youtube.com/watch?v=OmFTjvdrfyY' WHERE id_api = 'tt0480255';

UPDATE Contenido SET id_tmdb = 49519, descripcion = 'La película está ambientada en la prehistoria, donde Crug lidera a su familia más allá de la comodidad de su hogar después de que este sea destruido por un gran terremoto. Mientras intentan viajar por el desconocido y aterrador mundo, se encuentran con un nómada que cautiva a su clan, en especial a su hermana mayor, con su mente moderna.', trailer_url = 'https://www.youtube.com/watch?v=q6ootctQD_c' WHERE id_api = 'tt0481499';

UPDATE Contenido SET id_tmdb = 3638, descripcion = 'Una chef adicta al trabajo debe ceder parte del control de su restaurante a un despreocupado compañero de trabajo cuando se convierte en la tutora de su sobrina tras la muerte de sus padres.', trailer_url = 'https://www.youtube.com/watch?v=qm68An_PzAs' WHERE id_api = 'tt0481141';

UPDATE Contenido SET id_tmdb = 3594, descripcion = 'Narra la historia de un hombre obsesionado con un libro, cuyo relato parece describir detalles de su vida íntima. El hombre comenzará a sentirse amenazado y desarrolla una paranoia por un número que se repite una y otra vez en todo el libro: el 23.', trailer_url = 'https://www.youtube.com/watch?v=TUTlOC4mVQ8' WHERE id_api = 'tt0481369';

