UPDATE Contenido SET id_tmdb = 13460, descripcion = 'Gran Bretaña, 2007. El letal virus "Reaper" ha aniquilado a cientos de miles de personas. El gobierno británico decide evacuar a los supervivientes sanos y rodear con una muralla el área afectada para evitar la huida de los infectados. Cuando, treinta años después, el virus reaparece, el gobierno envía a la zona un equipo de especialistas de élite, dirigido por el Mayor Eden Sinclair, con la misión de obtener una vacuna a cualquier precio. Aislado del resto del mundo, el equipo deberá trabajar en medio de un paisaje de pesadilla.', trailer_url = 'https://www.youtube.com/watch?v=LZ9VVU11YV4' WHERE id_api = 'tt0483607';

