UPDATE Contenido SET id_tmdb = 6145, descripcion = 'Willy Beachum es un joven y ambicioso fiscal cuya carrera está empezando a despegar. Por otra parte, Ted Crawford es un ingeniero de mediana edad que acaba de disparar a su mujer a sangre fría. El destino querrá que ambos hombres se encuentren cara a cara en un camino de destino inescrutable. Crawford resulta ser tan complejo e impredecible como el crimen que ha cometido y, así, mientras el caso perfecto de Willy comienza a desmoronarse, el futuro del joven fiscal parece destruirse con él.', trailer_url = 'https://www.youtube.com/watch?v=B9jSN5CXO-g' WHERE id_api = 'tt0488120';

UPDATE Contenido SET id_tmdb = 8247, descripcion = 'David Rice ha crecido con el misterioso poder que casi todos sueñan poseer: teletransportarse a cualquier lugar del mundo que imagine. Hasta ahora ha utilizado sus poderes para escapar de su pasado, alimentar su inmensa fortuna y permanecer completamente independiente. Nunca ha conocido límites, fronteras ni consecuencias. Pero cuando David descubre a otro joven igual que él, un exaltado trotamundos rebelde llamado Griffin, la verdad de su existencia se revela. Ya no es un curioso fenómeno singular de la naturaleza, sino parte de una larga línea de anomalías genéticas conocidas como "saltadores", que además nunca están a salvo.', trailer_url = 'https://www.youtube.com/watch?v=ToNzgppC4Nc' WHERE id_api = 'tt0489099';

