UPDATE Contenido SET id_tmdb = 68730, descripcion = 'Dos sacerdotes jesuitas, Sebastião Rodrigues y Francisco Garupe, viajan al Japón del siglo XVII que, bajo el shogunato Tokugawa, prohibió el catolicismo y casi todos los contactos extranjeros. Allí son testigos de la persecución de los cristianos japoneses a manos de su propio gobierno, que desea purgar Japón de toda influencia occidental. Eventualmente los sacerdotes se separan y Rodrigues viaja por el campo, preguntándose por qué Dios permanece en silencio mientras sus hijos sufren.', trailer_url = 'https://www.youtube.com/watch?v=CRyN--J6LuQ' WHERE id_api = 'tt0490215';

UPDATE Contenido SET id_tmdb = 49022, descripcion = 'Rachel es una abogada de talento en un importante bufete de abogados de Nueva York, una amiga fiel y generosa, aunque, por desgracia, continúa soltera... como no pierde ocasión de recordarle su mejor amiga Darcy, ya prometida. Sin embargo, tras la fiesta en la que se celebra que cumple 30 años, Rachel, la eterna chica buena, acaba inesperadamente en brazos del chico del que ha estado colgada desde que no era más que una estudiante de Derecho, Dex... que resulta ser el prometido de Darcy.', trailer_url = 'https://www.youtube.com/watch?v=ZX265xNIuLo' WHERE id_api = 'tt0491152';

UPDATE Contenido SET id_tmdb = 2355, descripcion = 'Charlie Fineman es un dentista de Manhattan que perdió a su familia en el 11-S, y con ella perdió también las ganas de vivir y la capacidad para superar la tragedia. Un buen día, se encuentra con Alan Johnson, un antiguo compañero de la universidad. La recuperación de esa amistad le servirá en parte para aliviar el dolor.', trailer_url = 'https://www.youtube.com/watch?v=yzQYokimcg0' WHERE id_api = 'tt0490204';

UPDATE Contenido SET id_tmdb = 18781, descripcion = 'Tras recibir la noticia de que su hijo adolescente, Matt, tiene cáncer, Sarah y Peter Campbell deciden trasladar a toda la familia cerca de la clínica dónde Matt está siendo tratado. El lugar elegido es una imponente casa de estilo victoriano que oculta un oscuro pasado como antigua funeraria en la que sucedieron terribles acontecimientos. La familia empieza a presenciar violentos y extraños fenómenos que, al principio, asocian con el estrés provocado por la enfermedad. Pronto se darán cuenta de que se enfrentan a oscuras y terroríficas fuerzas de origen sobrenatural.', trailer_url = 'https://www.youtube.com/watch?v=J_DADv1FbXQ' WHERE id_api = 'tt0492044';

UPDATE Contenido SET id_tmdb = 417644, descripcion = 'Baker es un desgastado motociclista profesional que está tratando de reconstruir su vida y su matrimonio. Poncherello es un creído agente federal que está investigando un robo de millones de dólares, que puede resultar siendo un trabajo desde dentro. El inexperto principiante y el endurecido experto se unen como equipo, pero en vez de cooperar, enseguida comienzan a pelear. El comienzo de una cooperación fructuosa resulta ser más difícil de lo pensado, pero con las habilidades de motociclista de Baker, y Ponch que "tiene calle", puede funcionar… si no se vuelven locos uno al otro antes de terminar.', trailer_url = 'https://www.youtube.com/watch?v=FKlbX-t9GLg' WHERE id_api = 'tt0493405';

