UPDATE Contenido SET id_tmdb = 298, descripcion = 'Danny Ocean y su banda sólo tendrían una razón para realizar su golpe más ambicioso y arriesgado: defender a uno de los suyos. Willy Bank, el despiadado propietario de un casino, nunca hubiera imaginado que todo se iba a poner en su contra cuando traicionó a Reuben Tishkoff, amigo y mentor de Danny Ocean. Pero Bank se equivocó… para su desgracia. Quizás pudo derrotar a uno de los miembros originales de la banda, pero dejó a los demás en pie y les dio un propósito compartido: derrotar a Bank en la noche de la gran inauguración de su nuevo casino.', trailer_url = 'https://www.youtube.com/watch?v=sbzwtsMiVQY' WHERE id_api = 'tt0496806';

UPDATE Contenido SET id_tmdb = 8909, descripcion = 'Wesley Gibson (James McAvoy) tiene 25 años y es el zángano más desencantado y aburrido que habita en el planeta. Su jefe se mete con él sin parar, su novia no le hace caso y su vida carece de alicientes. Todos los que le conocen están convencidos de que este vago nato nunca llegará a nada. A Wes sólo le queda esperar que el tiempo pase hasta que muera de forma rutinaria. Pero todo cambia cuando conoce a una mujer llamada Fox (Angelina Jolie). Después del asesinato del padre de Wes, al que veía muy poco, la letal y sexy Fox recluta al joven para la Fraternity (Fraternidad), una sociedad secreta que enseña al joven a desarrollar sus poderes adormecidos para vengar la muerte de su padre.', trailer_url = 'https://www.youtube.com/watch?v=b9YEdjEKme0' WHERE id_api = 'tt0493464';

