UPDATE Contenido SET id_tmdb = 13121, descripcion = 'Una joven adolescente con dificultades para aceptar el sexo, dada su educación, pero cada día reciba más y más provocación de aquellos hombres que la rodean, incluyendo a su medio-hermano, pero ella quiere llegar virgen al matrimonio. Hasta que llega un día en el que es asaltada sexualmente y descubre que su cuerpo tiene "algo" extraño.', trailer_url = 'https://www.youtube.com/watch?v=NV3_O50BJK0' WHERE id_api = 'tt0780622';

UPDATE Contenido SET id_tmdb = 7978, descripcion = 'La infancia de Lawrence Talbot se acabó bruscamente la noche que murió su madre. Se marchó de su pueblo, Blackmoor, y tardó décadas en recuperarse e intentar olvidar. Cuando Gwen Conliffe, la prometida de su hermano, le encuentra y le ruega que la ayude a buscar a su amor, que se encuentra desaparecido, Lawrence Talbot regresa a casa. Entonces se entera de que algo brutal, salvaje, con una sed insaciable de sangre ha matado a muchos campesinos. Empieza a encajar las piezas del sangriento rompecabezas y descubre que existe una antigua maldición que convierte a las víctimas en hombres lobo las noches de luna llena. Para acabar con la carnicería y proteger a la mujer de la que se ha enamorado, Lawrence Talbot debe destruir a la temible criatura que se esconde en los bosques cercanos a Blackmoor. Este hombre sencillo con un pasado doloroso sale en busca de la bestia y descubre que él también tiene un lado primitivo que ni siquiera podía imaginar.', trailer_url = 'https://www.youtube.com/watch?v=GsqeTBewDQY' WHERE id_api = 'tt0780653';

UPDATE Contenido SET id_tmdb = 4347, descripcion = 'En el verano de 1935, Briony Tallis (Saoirse Ronan), una precoz escritora de 13 años, cambia irremediablemente el curso de varias vidas cuando acusa al amante de su hermana Cecilia (Keira Knightley), el joven Robbie Turner (James McAvoy), de haber cometido un crimen. Los productores y el realizador de "Orgullo y prejuicio" vuelven a unirse en este drama.', trailer_url = 'https://www.youtube.com/watch?v=izzipNia4s8' WHERE id_api = 'tt0783233';

UPDATE Contenido SET id_tmdb = 170687, descripcion = 'Cheesebridge (Puentequeso) es una elegante ciudad de la era posvictorinana, obsesionada por el dinero, la clase y el más delicioso de los quesos apestosos. Debajo de sus encantadoras calles adoquinadas viven los Boxtrolls, unos monstruos que salen de las alcantarillas por la noche para hacerse con los bienes más preciados de los habitantes: sus hijos y sus quesos.', trailer_url = 'https://www.youtube.com/watch?v=OxONDGestUk' WHERE id_api = 'tt0787474';

UPDATE Contenido SET id_tmdb = 10074, descripcion = 'Rod Kimble (Andy Samberg), convencido de ser un auténtico especialista en saltos con moto, se prepara para realizar una gran hazaña: saltar con su moto por encima de 15 autobuses. Su objetivo es recaudar dinero para conseguir que su autoritario padre pueda operarse del corazón; pero lo que realmente busca es que la salud de su padre mejore para poder enfrentarse a él.', trailer_url = 'https://www.youtube.com/watch?v=hsgVUofWd3s' WHERE id_api = 'tt0787475';

