UPDATE Contenido SET id_tmdb = 11631, descripcion = 'Versión cinematográfica del popular musical de ABBA. Una joven que ha crecido en una pequeña isla griega, ha sido educada por una madre rebelde y poco convencional, que siempre se ha negado a revelarle la identidad de su padre. Cuando, por fin, parece que la joven está a punto de saberlo, aparecen tres posibles candidatos.', trailer_url = 'https://www.youtube.com/watch?v=R9gH9VJMyIU' WHERE id_api = 'tt0795421';

