UPDATE Contenido SET id_tmdb = 49524, descripcion = 'Aunque Nick es un policía que acaba de morir asesinado, es reclutado para trabajar con Roy, un agente que murió hace cientos de años. Ambos forman parte del “Rest In Peace Department”, que se encarga de perseguir a los demonios que habitan en el mundo de los vivos y de mandarlos al infierno. A Nick le cuesta hacerse a la idea de su condición de muerto, y no acepta estar alejado de su esposa, a la que envía reiteradas señales para que perciba su presencia. Al menos, gracias a su empleo post mortem, el joven agente podrá trabajar en el caso de su propio asesinato.', trailer_url = 'https://www.youtube.com/watch?v=YfTKJ-tm_vE' WHERE id_api = 'tt0790736';

