UPDATE Contenido SET id_tmdb = 1044, descripcion = '''Planeta Tierra'' es una serie de televisión estrenada en 2006 y producida por la Sección de Historia Natural de la BBC. Ganadora de un premio Emmy, esta serie tardó alrededor de cinco años en ser realizada por completo. Fue, además, el documental de naturaleza más caro jamás producido por la BBC, y fue descrito por sus creadores como "la mirada definitiva a la diversidad de nuestro planeta".', trailer_url = 'https://www.youtube.com/watch?v=tiVNk6_0GdY' WHERE id_api = 'tt0795176';

UPDATE Contenido SET id_tmdb = 2196, descripcion = 'Mientras una familia inglesa prepara el funeral del patriarca, la tensión crece a medida que salen a relucir las antiguas rencillas entre los hijos. La aparición de un desconocido que afirma que el difunto ocultaba un oscuro secreto contribuye a empeorar las cosas, lo que obliga a la familia a tomar medidas drásticas para evitar que el funeral se convierta en un desastre total.', trailer_url = 'https://www.youtube.com/watch?v=j9mWAKK-0eE' WHERE id_api = 'tt0795368';

UPDATE Contenido SET id_tmdb = 4258, descripcion = 'Los felizmente casados Dan y Jody empiezan a observar algunos fenómenos extraños en su casa tras volver del hospital con su bebé, Aiden. Pero cuando el caos se apodera del trabajo de Jody como bailarina de ballet y de la carrera de Dan como investigador de monos, la pareja descubre que está siendo acosada por una presencia demoníaca. Juntos, con la ayuda de expertos cualificados y de numerosas cámaras, intentarán deshacerse del maléfico ser antes de que sea demasiado tarde.', trailer_url = 'https://www.youtube.com/watch?v=Vn1uwEiTfMM' WHERE id_api = 'tt0795461';

UPDATE Contenido SET id_tmdb = 13475, descripcion = 'Todo está preparado para el viaje inaugural de la nave más moderna que jamás se haya creado: la USS Enterprise. Su joven tripulación tiene una importante misión: encontrar una manera de detener al malvado Nero que, movido por la venganza, amenaza a toda la humanidad. Pero el destino de la galaxia está en manos de dos jóvenes rivales, que nacieron en mundos diferentes. Uno de ellos, Tiberius James Kirk, humano, busca emociones y es un líder nato. El otro, Spock, medio humano y medio vulcaniano, es menospreciado por los vulcanianos, por sus emociones humanas.', trailer_url = 'https://www.youtube.com/watch?v=xftdFugdA70' WHERE id_api = 'tt0796366';

