UPDATE Contenido SET id_tmdb = 1104, descripcion = 'El drama trata de una de las agencias de publicidad más prestigiosas de Nueva York a principios de los años sesenta, y se enfoca en el misterioso pero talentoso Donald Draper.', trailer_url = 'https://www.youtube.com/watch?v=B8b0B2-hvhc' WHERE id_api = 'tt0804503';

UPDATE Contenido SET id_tmdb = 4626, descripcion = 'Betty Suarez es inteligente, dura y tenaz, pero también sensible y cariñosa. Ella espera que estas habilidades la ayuden a conseguir un trabajo dentro de Meade Publishing Corporation. El hecho de que no sea tradicionalmente atractiva inicialmente evita que la contrate la biblia de la moda, Mode. La revista, sin embargo, está cambiando, con ejecutivos ávidos de poder compitiendo por el dominio. Con la esperanza de controlar la situación, el editor le da a su hijo sin experiencia, Daniel, el puesto de editor en jefe. Contrata a Betty como asistente de Daniel después de encontrarlo en una posición comprometedora con su secretaria en su primer día de trabajo. Después de un comienzo difícil, en el que Daniel intenta obligar a Betty a renunciar tratándola terriblemente, se da cuenta de su valor y los dos forman un equipo eficaz.', trailer_url = 'https://www.youtube.com/watch?v=0IFgj1A6uMU' WHERE id_api = 'tt0805669';

UPDATE Contenido SET id_tmdb = 8461, descripcion = 'Anna, su marido George y su hijo de diez años se van a descansar a su residencia de vacaciones situada al lado de un lago. Nada más llegar, aparecen dos jóvenes aparentemente muy educados que dicen ser amigos de los vecinos y que les piden unos huevos. Remake norteamericano de la película homónima de Haneke, de 1997.', trailer_url = 'https://www.youtube.com/watch?v=XPKloMrHCks' WHERE id_api = 'tt0808279';

UPDATE Contenido SET id_tmdb = 4588, descripcion = 'Shanghai, 1942. La ciudad está ocupada por los japoneses. La señora Mak, una mujer rica y sofisticada, recuerda cómo empezó todo en 1938. Su verdadero nombre no es Mak, sino Wong Chia Chi. Poco antes de estallar la II Guerra Mundial (1939-1945), su padre huyó a Inglaterra y la dejó en China. Era estudiante universitaria y conoció a Kuang Yu Min, que acababa de fundar una compañía de teatro para fomentar el patriotismo. Wong Chia Chi se convirtió en la primera actriz de la compañía. Kuang, por su parte, convenció a un grupo de estudiantes para que asesinaran al señor Yee, un importante colaborador de los japoneses. Wong Chia Chi colaboró en el plan haciéndose pasar por la señora Mak: su cometido era hacerse amiga de la mujer de Yee para ganarse la confianza de éste y seducirlo. Todo iba sucediendo según lo previsto, hasta que se produjo un acontecimiento inesperado.', trailer_url = 'https://www.youtube.com/watch?v=QWKnGqvZKjQ' WHERE id_api = 'tt0808357';

UPDATE Contenido SET id_tmdb = 2011, descripcion = 'Marjane Satrapi (Gabrielle Lopes) es una niña iraní de 8 años que sueña con ser profeta para salvar el mundo. Querida por sus padres y adorada por su abuela, Marjane sigue atenta los acontecimientos que provocan la caída del Shah y de su régimen brutal para dejar paso a una República Islámica que controla la manera de vestir y de actuar de la gente. Ésto provoca que Marjane se vea obligada a llevar velo, lo que la anima a convertirse en una revolucionaria.', trailer_url = 'https://www.youtube.com/watch?v=FGjcfGgVm64' WHERE id_api = 'tt0808417';

UPDATE Contenido SET id_tmdb = 12572, descripcion = 'Película formada por cortometrajes de reconocidos directores y actores, siguiendo la línea de "Paris, je t''aime", narrando historias de amor en la ciudad de Nueva York.', trailer_url = 'https://www.youtube.com/watch?v=VJVtzGhuDf8' WHERE id_api = 'tt0808399';

UPDATE Contenido SET id_tmdb = 23023, descripcion = 'Derek Thompson un popular jugador de Hockey sobre hielo, cuyo apodo es Tooth Fairy porque en los partidos siempre acaba saltándole los dientes a algún oponente. Pero un buen día Derek hace añicos las esperanzas de un niño y por ello es condenado a servir como un hada de verdad, con alas incluidas, durante una semana. Lily, una veterana hada madrina de alto rango quien tendrá la tarea de supervisarlo.', trailer_url = 'https://www.youtube.com/watch?v=7cTilSq6uLg' WHERE id_api = 'tt0808510';

UPDATE Contenido SET id_tmdb = 14069, descripcion = 'Una adolescente sufre un accidente y descubre que desde entonces puede saltar hacia atrás y hacia delante en el tiempo, poder que utilizará para encauzar su caótica vida estudiantil y amorosa en el instituto.', trailer_url = 'https://www.youtube.com/watch?v=boZINHGDxMw' WHERE id_api = 'tt0808506';

UPDATE Contenido SET id_tmdb = 306819, descripcion = 'Drama basado en la verdadera historia de una pareja de artistas daneses, Einar y Gerda Wegener. La vida de este matrimonio dio un giro cuando Einar sustituyó a la modelo femenina que su mujer, Gerda, tenía que pintar. Cuando los retratos resultan ser un éxito, ella anima a su marido a adoptar una apariencia femenina. Lo que comenzó como un juego llevó a Einar a una metamorfosis inesperada.', trailer_url = 'https://www.youtube.com/watch?v=ENiuBpdrnZ8' WHERE id_api = 'tt0810819';

UPDATE Contenido SET id_tmdb = 71880, descripcion = 'Jack (Adam Sandler) es un padre de familia que tiene que afrontar un arduo problema: la llegada por Navidad de su odiada hermana Jill. Por si fuera poco, lo que, en principio, iba a ser una visita de pocos días, se alarga más de lo previsto, lo que obliga a Jack y Jill a intentar limar asperezas.', trailer_url = 'https://www.youtube.com/watch?v=MAiqq6n88QM' WHERE id_api = 'tt0810913';

UPDATE Contenido SET id_tmdb = 50725, descripcion = 'En el verano de 1988, tras licenciarse en la Universidad, tres amigos están a punto de asistir a una fiesta desenfrenada. Uno de ellos, Matt Franklin (Topher Grace) debería trabajar para la compañía Fortune 500, pero, inexplicablemente para su familia y sus amigos, trabaja a tiempo parcial en una tienda de vídeos de una galería comercial. Quizá lo haga para estar cerca de Tori Frederking (Teresa Palmer), su amor platónico del instituto. Cuando ella lo invita a una fiesta, Matt, que cree que por fin ha llegado su oportunidad, acude con su hermana gemela (Anna Faris) y su mejor amigo (Dan Fogler).', trailer_url = 'https://www.youtube.com/watch?v=PPOYww3nuEg' WHERE id_api = 'tt0810922';

UPDATE Contenido SET id_tmdb = 7459, descripcion = 'Sigue las aventuras de Speed Racer, un corredor nato, nacido para pilotar. Es un piloto agresivo y, sobre todo, temerario. Su única competencia es el recuerdo de su hermano, el que fue su ídolo, el legendario Rex Racer, cuya muerte en una carrera ha dejado una meta que Speed siente la necesidad de cumplir. Speed siente una gran lealtad hacia el negocio familiar de las carreras llevado por su padre, Pops Racer (John Goodman), el diseñador del poderoso bólido Mach 5. Cuando Speed rechaza una oferta muy lucrativa y tentadora de las Industrias Royalton, no sólo hace enfurecer al maniático dueño de la empresa (Roger Allam), además, descubre un terrible secreto: algunas de las carreras más importantes están siendo manipuladas por unos desalmados empresarios. Si Speed no pilota para la escudería de Royalton, éste se va a ocupar de que el Mach 5 nunca cruce otra meta. La única manera de que Speed pueda salvar el negocio de la familia y el deporte que ama es ganando a Royalton en su propio', trailer_url = 'https://www.youtube.com/watch?v=YeXDSYF2xDk' WHERE id_api = 'tt0811080';

UPDATE Contenido SET id_tmdb = 12177, descripcion = 'El cómico Mike Myers interpreta a Pitka, un estadounidense que fue educado por gurús fuera de su país y que ahora vuelve con la misión de reunir a un jugador de hockey con su mujer (Meagan Good), que lo ha dejado por un atleta rival, Jacques Grande, a quien interpreta Justin Timberlake.', trailer_url = 'https://www.youtube.com/watch?v=0KUA1d8-6eg' WHERE id_api = 'tt0811138';

UPDATE Contenido SET id_tmdb = 7862, descripcion = 'Berlín, 1936. Sorowitsch (Karl Markovics), el rey de los falsificadores de moneda, es un judío sin escrúpulos que cree que "la manera más rápida de ganar dinero es fabricar dinero". Nada le importa lo que está sucediendo a su alrededor, ni siquiera la situación de los judíos. Sin embargo, cuando estalla la guerra, es arrestado y llevado a un campo de concentración nazi, donde se ve obligado a trabajar con otros falsificadores. Su misión: fabricar libras esterlinas y dólares americanos. A cambio, sus condiciones de vida son mejores que las de los demás prisioneros. Sin embargo, esta situación les plantea a algunos un dilema moral: cooperar con sus verdugos equivale prolongar la guerra y facilitar la victoria de la Alemania nazi.', trailer_url = NULL WHERE id_api = 'tt0813547';

UPDATE Contenido SET id_tmdb = 13184, descripcion = 'Remake de la exitosa película tailandesa "Bangkok Dangerous" de 1999. Joe, un asesino profesional recibe un encargo en Bangkok para acabar con cuatro objetivos, pagado por un gagser local. Para que lo ayude, recluta a Kong, un ladronzuelo al que planea matar al terminar el trabajo, para no dejar ningún rastro. Pero las cosas se complican. Joe se enamora de una joven sordomuda y deja que la simpatía de Kong perfore su coraza. Cuando el hombre que lo contrató se vuelve contra él y captura a su nuevo amigo, Joe reccionará con toda la violencia de la que es capaz.', trailer_url = 'https://www.youtube.com/watch?v=-yoUqQY57Yg' WHERE id_api = 'tt0814022';

UPDATE Contenido SET id_tmdb = 32657, descripcion = 'Adaptación de la novela publicada en España con el título de ''El Ladrón del Rayo. Después de ir a un campamento, Percy, un chico aparentemente normal, (Lerman) descubre que es hijo de Poseidón, el dios de los mares, y que su mejor amigo Grover (Jackson) es un sátiro. A partir de ahí, él y sus dos amigos (dos semidioses y un sátiro) recorrerán el país, que está plagado de monstruos mitológicos, para restaurar el orden cósmico antes de que se ponga el sol en el día más largo del año. Percy busca recuperar la paz, rescatar a su madre, conocer a su padre y comprender quién es él mismo. Todo un reto que debe superar en apenas diez días.', trailer_url = 'https://www.youtube.com/watch?v=_MX7-RKLYFc' WHERE id_api = 'tt0814255';

UPDATE Contenido SET id_tmdb = 2919, descripcion = 'Serie de TV (2007-2013) 111 Episodios. Todo comienza cuando el agente Westen tras una misión en Nigeria sabrá que ha sido apartado del servicio por lo que deberá averiguar quién le ha "traicionado". Para ello contará con la compañía de su ex novia, una ex terrorista del IRA. Por ello trabajará como agente secreto clandestino en casos de poca monta, pero al tiempo investigará por su cuenta porqué ha sido "quemado", argot empleado para designar a los agentes que son cesados de sus funciones...', trailer_url = 'https://www.youtube.com/watch?v=oFtYEe39RUI' WHERE id_api = 'tt0810788';

UPDATE Contenido SET id_tmdb = 11321, descripcion = 'Ben Thomas es un inspector de Hacienda que comienza a contactar con determinadas personas con la aparente intención de ayudarles, a todos de diferentes maneras, sin que sepamos bien ni sus razones ni sus objetivos. Aparentemente Ben tiene un plan, pero cuando conoce a una de esas personas, la atractiva Emily, comienza a sentir algo por ella, complicándose sus misteriosos planes.', trailer_url = 'https://www.youtube.com/watch?v=hvu2F6t26hs' WHERE id_api = 'tt0814314';

UPDATE Contenido SET id_tmdb = 34016, descripcion = 'Kirk (Jay Baruchel, "Tropic Thunder") es un tipo normal y corriente, que no suele tener éxito con las chicas, que se queda sorprendido cuando un día una chica despampanante muestra interés en él. Kirk no puede creer en la suerte que está teniendo. A pesar de que está estancado en un trabajo sin futuro como guardia de seguridad del aeropuerto, contra todo pronóstico, Molly (Alice Eve), una chica con éxito y escandalosamente guapa, se enamora de él. Kirk está aturdido. También lo están sus amigos, su familia y hasta su ex-novia. Ahora tiene que encontrar la manera de hacer que la relación funcione, a pesar de que él es el primero en admitir que ella está totalmente "fuera de su liga".', trailer_url = 'https://www.youtube.com/watch?v=6apjIe7G7BY' WHERE id_api = 'tt0815236';

UPDATE Contenido SET id_tmdb = 1639, descripcion = 'Serie de TV (2006-2010). 4 temporadas. 78 episodios. Algunas personas nacen para ser extraordinarias. Un grupo de personas normales se ve, de la noche a la mañana, dotada de increíbles poderes. Así, mientras en Japón un anónimo oficinista descubre que tiene un don para teletransportarse, en Nueva York un artista se da cuenta de que es capaz de pintar el futuro, o en Los Ángeles un policía puede escuchar los pensamientos ajenos. Estas personas no sólo tendrán que aprender a conocer sus poderes y a dominarlos, sino que además deberán decidir qué destino quieren darles.', trailer_url = 'https://www.youtube.com/watch?v=9AX6aXFdTkc' WHERE id_api = 'tt0813715';

