UPDATE Contenido SET id_tmdb = 13007, descripcion = 'Religulous’ es una palabra que mezcla “religious” y “ridiculous”, “religioso” y “ridículo”. Documental que arremete contra todos los fanatismos, no se centra en una única religión. Describe las ideas y creencias religiosas que son evidentemente absurdas, cómicas o ridículas. Maher viaja por todo el planeta entrevistando a personas acerca de Dios y la religión. Saca la sinceridad que le caracteriza en este viaje espiritual tan inusual.', trailer_url = 'https://www.youtube.com/watch?v=XdkyLrDpaUg' WHERE id_api = 'tt0815241';

UPDATE Contenido SET id_tmdb = 10760, descripcion = 'Adaptación moderna del cuento de Blancanieves. Cuando Sydney es expulsada de la hermandad más popular del campus ya que no es suficientemente "femenina", la acogen siete chicos mal vistos socialmente pero entrañables. Con la ayuda de sus nuevos amigos, Sydney se dedica a defender a los marginados en todos los sitios, y reta a la reina del campus a un duelo de popularidad.', trailer_url = 'https://www.youtube.com/watch?v=N-Hua-wJzVc' WHERE id_api = 'tt0815244';

UPDATE Contenido SET id_tmdb = 14254, descripcion = 'Anna Rydell regresa a casa junto a su hermana -y mejor amiga- Alex, tras su estancia en un hospital mental. Pero su recuperación se pondrá en peligro por culpa de su cruel madrastra, de su padre ausente y de la presencia de un fantasma que habita en la casa... Remake americano de la película surcoreana "Janghwa, hongryeon", dirigida por Ji-woon Kim en 2003 y estrenada posteriormente en España bajo el título de "Dos hermanas".', trailer_url = 'https://www.youtube.com/watch?v=cf66mUsPHH4' WHERE id_api = 'tt0815245';

UPDATE Contenido SET id_tmdb = 203833, descripcion = 'La novela de 550 páginas de la Segunda Guerra Mundial, narrada por la muerte, cuenta la historia de Liesel Memminger desde el momento en que es acogida con nueve años por una familia trabajadora alemana en el barrio obrero justo después de haber robado su primer libro.', trailer_url = 'https://www.youtube.com/watch?v=qrFeM-x2k-s' WHERE id_api = 'tt0816442';

UPDATE Contenido SET id_tmdb = 37430, descripcion = 'Las hazañas de Conan en la Era Hiboria cobran ahora vida como no se habían visto jamás en una colosal película de acción y aventuras. Una búsqueda que comienza como una vendetta personal para el feroz guerrero cimmerio no tardará en convertirse en una épica batalla que lo enfrentará a descomunales rivales y horrendos monstruos. Contra toda esperanza de victoria, Conan se dará cuenta de que es la única posibilidad de salvación de las grandes naciones de Hiboria frente a la invasión de un mal sobrenatural.', trailer_url = 'https://www.youtube.com/watch?v=LslNQbdFgmI' WHERE id_api = 'tt0816462';

UPDATE Contenido SET id_tmdb = 157336, descripcion = 'Un grupo de exploradores hacen uso de un agujero de gusano recientemente descubierto para superar las limitaciones de los viajes espaciales tripulados y vencer las inmensas distancias que tiene un viaje interestelar.', trailer_url = 'https://www.youtube.com/watch?v=UoSSbmD9vqc' WHERE id_api = 'tt0816692';

UPDATE Contenido SET id_tmdb = 72190, descripcion = 'Cuando el mundo comienza a ser invadido por una legión de muertos vivientes, Gerry Lane, un experto investigador de las Naciones Unidas, intentará evitar el fin de la civilización en una carrera contra el tiempo y el destino. La destrucción a la que se ve sometida la raza humana lo lleva a recorrer el mundo entero buscando la solución para frenar esa horrible epidemia.', trailer_url = 'https://www.youtube.com/watch?v=DR_0_v6CB_k' WHERE id_api = 'tt0816711';

UPDATE Contenido SET id_tmdb = 43949, descripcion = 'Corre el año 1957. Juli y Bryce, dos niños de siete años aparentemente muy distintos, son vecinos y compañeros de clase. Juli se enamora de Bryce, pero él no siente lo mismo y durante seis años tratará de evitarla. Cuando, en 1963, siendo ya adolescentes, van a la escuela secundaria, las cosas cambian: Bryce empieza a mirar a Juli con otros ojos.', trailer_url = 'https://www.youtube.com/watch?v=shN4dt583Y0' WHERE id_api = 'tt0817177';

UPDATE Contenido SET id_tmdb = 32856, descripcion = 'El film consta de varias historias que suceden el día de San Valentín: una oficial del ejército que vuela desde Iraq a Los Ángeles, coincide en el avión con alguien que debe resolver algunos asuntos; el dueño de una floristería le propone matrimonio a su novia, aunque, en realidad, está enamorado de una amiga, cuyo novio está casado; una jubilada le confiesa a su marido que mantuvo un largo romance con otra persona; una mujer que trabaja en la agencia de talentos más importante de la ciudad sale con un empleado de Correos. Y, finalmente, una desafortunada publicista resulta que no tiene con quién quedar el día de San Valentín.', trailer_url = 'https://www.youtube.com/watch?v=fXyHuuYtR00' WHERE id_api = 'tt0817230';

UPDATE Contenido SET id_tmdb = 8457, descripcion = 'Durante el primer curso en el instituto, unos chicos deciden contratar a un guardaespaldas de poca monta (Owen Wilson) para que los proteja de unos matones que les están haciendo la vida imposible. Desde el primer día de clase, Ryan, Wade y Emmit se convierten en el blanco de las burlas de Filkins, el "matón" del instituto y un torturador nato. De pronto, lo que habían imaginado que podían ser los mejores años de su vida se convierten en un infierno. Es entonces cuando contratan a Drillbit Taylor (Wilson) como guardaespaldas.', trailer_url = 'https://www.youtube.com/watch?v=j3-_AgJnTyo' WHERE id_api = 'tt0817538';

UPDATE Contenido SET id_tmdb = 12556, descripcion = 'Connor Mead (Matthew McConaughey) es un conocido fotógrafo soltero, amante de la libertad e independencia, que es acosado por el fantasma de una novia del pasado en la boda de un hermano menor suyo.', trailer_url = 'https://www.youtube.com/watch?v=6oSXK43uuCA' WHERE id_api = 'tt0821640';

UPDATE Contenido SET id_tmdb = 17332, descripcion = 'El film narra la historia verídica de Nathaniel Ayers (Jamie Foxx), un prodigioso violonchelista que en su segundo año de conservatorio desarrolló esquizofrenia y acabó viviendo en la calle, en donde fue descubierto por el periodista de Los Angeles Times Steve Lopez (Robert Downey Jr.) en el año 2005. Impresionado por su talento, López, que también pasaba una mala época en su vida, escribió una serie de artículos sobre Nathaniel que lo sacó del anonimato, acercándolo a su sueño de tocar en el Disney Concert Hall.', trailer_url = 'https://www.youtube.com/watch?v=z1YHoyCxdVQ' WHERE id_api = 'tt0821642';

UPDATE Contenido SET id_tmdb = 38321, descripcion = 'En un mundo asolado por siglos de guerra entre el hombre y los vampiros, Paul Bettany es un legendario guerrero que destacó durante la última Guerra del Vampiro, pero ahora es sólo un sacerdote que vive en compañía de otros hombres en las amuralladas ciudades distópicas controladas por la Iglesia. Sin embargo, cuando su joven sobrina es secuestrada por un grupo de vampiros asesinos que viven en los páramos desolados del exterior, el sacerdote rompe sus sagrados votos y emprende su búsqueda decidido a vengarse de los secuestradores, especialmente de su brutal líder. En esta aventura le acompaña Hicks, el novio de la chica, un sheriff y una sacerdotisa, miembro de la legión de asesinos de vampiros y poseedora de habilidades de combate sobrenaturales.', trailer_url = 'https://www.youtube.com/watch?v=2ZLOHj0Wz8Q' WHERE id_api = 'tt0822847';

UPDATE Contenido SET id_tmdb = 14306, descripcion = 'Los recién casados John y Jenny Grogan deciden dejar atrás los duros inviernos de Michigan para instalarse en la soleada West Palm Beach (Florida). Los dos consiguen empleo en dos periódicos rivales, compran su primera casa y afrontan los retos del matrimonio. Cuando John le confiesa a su amigo y colega Sebastian que aún no se siente preparado para ser padre, éste le sugiere que le regale a Jenny un perro. Los Grogan adoptan un bonito cachorro de Labrador que, poco después, se convierte en una mole de 45 kilos que transforma la casa en una verdadera catástrofe.', trailer_url = 'https://www.youtube.com/watch?v=KR5UBtAxseo' WHERE id_api = 'tt0822832';

UPDATE Contenido SET id_tmdb = 7485, descripcion = 'Bob Lee Swagger (Mark Whalberg) es un ex-tirador de élite del ejército de los Estados Unidos que abandona las fuerzas armadas después del fracaso de una misión extraoficial. Cuando le piden que se reincorpore, regresa al servicio a regañadientes, pero vuelven a engañarlo. A pesar de llevar dos balas en el cuerpo y de ser el objetivo de una caza a nivel nacional, Swagger planea su venganza...', trailer_url = 'https://www.youtube.com/watch?v=0cDsb-SsaDY' WHERE id_api = 'tt0822854';

UPDATE Contenido SET id_tmdb = 3580, descripcion = 'Christine Collins es una madre que recupera a su hijo, al que habían secuestrado meses antes. Pero en la locura del muy fotografiado reencuentro, comienza a sospechar que el niño que le han entregado no es su hijo. A pesar de unas fuerzas del orden corruptas y de una opinión pública más que escéptica, intenta dilucidar el misterio cueste lo que cueste. Tachada de loca e incapacitada, por fin encuentra un aliado en el reverendo Briegleb, que la ayudará en su búsqueda.', trailer_url = 'https://www.youtube.com/watch?v=IF5hwg4FNEU' WHERE id_api = 'tt0824747';

UPDATE Contenido SET id_tmdb = 49017, descripcion = 'Los orígenes del mito se revelan en esta película ambientada en los años de reinado de Vlad Tepes, príncipe de Rumania que inspiró la leyenda por sus peculiares métodos para provocar el miedo entre su población y sus enemigos. Una mezcla de mitología e historia para recoger cómo se transformó el sanguinario emperador en el primer vampiro de la historia. Uno de los más terribles y sádicos personajes de Europa que inspiró la clásica obra literaria de Bram Stoker mezclando el terror sobrenatural, las leyendas y pinceladas de amor, para cautivar por completo.', trailer_url = 'https://www.youtube.com/watch?v=AIykNDv88ww' WHERE id_api = 'tt0829150';

UPDATE Contenido SET id_tmdb = 7350, descripcion = 'Dos enfermos terminales escapan del hospital y se hacen un viaje con una lista de deseos que cumplir antes de morir.', trailer_url = 'https://www.youtube.com/watch?v=VUELwMTzsuY' WHERE id_api = 'tt0825232';

UPDATE Contenido SET id_tmdb = 10764, descripcion = 'Traicionado por Vesper, la mujer a la que amaba, 007 se plantea su nueva misión como algo personal. Durante su investigación, Bond y M interrogan a Mr. White, que les revela que la organización que chantajeó a Vesper es mucho más compleja y peligrosa de lo que imaginan. El servicio de inteligencia forense vincula a un traidor del Mi6 con una cuenta bancaria en Haití, donde Bond conoce a la bella pero combativa Camille, una mujer que tiene sus propios motivos para vengarse. Gracias a Camille, Bond descubre la existencia de Dominic Greene, despiadado hombre de negocios y miembro importante de la misteriosa organización.', trailer_url = 'https://www.youtube.com/watch?v=vSYTi0ZdMPs' WHERE id_api = 'tt0830515';

UPDATE Contenido SET id_tmdb = 8363, descripcion = 'En una de sus últimas noches como estudiantes del instituto, los amigos e inadaptados Evan y Seth experimentarán una legendaria odisea durante una tarde en la que intentan comprar bebida para una fiesta en la que estarán las chicas de sus sueños. En su peripecia les acompañará el indescriptible McLovin, otro amigo inadaptado que acaba de comprarse un carnet falso: su pasaporte para comprar el alcohol.', trailer_url = 'https://www.youtube.com/watch?v=LvKvus3vCEY' WHERE id_api = 'tt0829482';

UPDATE Contenido SET id_tmdb = 124905, descripcion = 'Gareth Edwards dirige este "reboot", que se sitúa antes en el tiempo que la película de 1998 dirigida por Roland Emmerich, que nos llevará a conocer los orígenes del famoso monstruo japonés gigante Godzilla.  Protagonizada por Bryan Cranston, ganador del Globo de Oro por Breaking Bad, que da vida a Joe Brody un científico que descubre que algo terrible está a punto de suceder cuando una serie de tsunamis comienzan a llegar a las costas, anticipando la llegada de numerosos monstruos de gran tamaño mientras el ejército intenta defenderse en vano.', trailer_url = 'https://www.youtube.com/watch?v=_MVDpmKxLNg' WHERE id_api = 'tt0831387';

UPDATE Contenido SET id_tmdb = 8285, descripcion = 'The Spirit es la historia de Denny Colt, un policía que fue asesinado y que misteriosamente vuelve a la vida como el enmascarado luchador contra el crimen llamado Spirit. Determinado a mantener a su amada Central City a salvo, Spirit persigue a los villanos de Central City desde las sombras y busca terminar con el peor de todos ellos: el psicótico megalómano conocido como Octopus. A pesar de lo ocupado que lo mantiene esta misión, el deslumbrante guerrero siempre se las arregla para tener tiempo para las bellas mujeres, aunque nunca está seguro de si ellas quieren seducirlo, amarlo o matarlo. Pero hay una dama que nunca lo traicionará y a la que siempre será fiel: Central City, la vieja y orgullosa metrópoli donde nació… dos veces.', trailer_url = 'https://www.youtube.com/watch?v=1CPyav6hQlI' WHERE id_api = 'tt0831887';

UPDATE Contenido SET id_tmdb = 8390, descripcion = 'Will Hayes (Ryan Reynolds) es un papá de treinta y pico años en pleno divorcio. Su hija (Abigail Breslin) de diez años le pregunta por su vida antes de casarse, quiere enterarse de cómo se conocieron sus padres, de cómo se enamoraron. Para contestar a Maya, Will rememora el pasado de un joven idealista que aprende los tejemanejes de la política en una gran ciudad, y le cuenta que conoció a tres mujeres. Desesperado, intenta construir una versión “tolerada” para su hija y cambia los nombres de las protagonistas. Maya tendrá que adivinar con cuál de las tres acabó casándose. ¿Quién es su madre? ¿Emily (Elizabeth Banks), la novia de universidad de Will? ¿O quizá sea su amiga de siempre, su confidente, la apolítica April (Isla Fisher)? Aunque también podría ser una ambiciosa e inconformista periodista llamada Summer (Rachel Weisz). Maya empieza a unir las piezas del rompecabezas romántico de su padre y entiende que el amor no es fácil ni simple.', trailer_url = NULL WHERE id_api = 'tt0832266';

UPDATE Contenido SET id_tmdb = 12437, descripcion = 'Una enemistad a muerte de siglos estalla entre dos tribus inmortales en Underworld: La rebelión de los Licántropos. La tercera película de la saga épica de Underworld retrocede en el tiempo y cuenta el origen del conflicto entre los aristocráticos vampiros, conocidos como los “Death Dealers”, y los salvajes licántropos, una línea de feroces hombres lobos. Tercera entrega de la popular saga Underworld, centrada en el conflicto existente entre los vampiros y los hombres lobo.', trailer_url = 'https://www.youtube.com/watch?v=Jz6MaOr9mmk' WHERE id_api = 'tt0834001';

UPDATE Contenido SET id_tmdb = 76492, descripcion = 'Drácula regenta un hotel en el que se alojan personajes como Frankenstein, la Momia, el Hombre Invisible, hombres-lobo... El problema del conde es que tiene una hija de espíritu aventurero a la que le resulta difícil controlar. El conflicto surge cuando se aloja en el hotel un ser humano que se siente atraído por la hija del dueño.', trailer_url = 'https://www.youtube.com/watch?v=mZ7wb2SmDMI' WHERE id_api = 'tt0837562';

UPDATE Contenido SET id_tmdb = 157433, descripcion = 'El doctor Louis Creed (Clarke) se muda con su mujer Racher (Seimetz) y sus dos hijos pequeños de Boston a un pueblecito de Maine, cerca del nuevo hogar de la familia descubrirá una terreno misterioso escondido entre los árboles. Cuando la tragedia llega, Louis hablará con su nuevo vecino, Jud Crandall (Lithgow), desencadenando una peligrosa reacción en cadena que desatará un mal de horribles consecuencias.', trailer_url = 'https://www.youtube.com/watch?v=XakmsXltPkA' WHERE id_api = 'tt0837563';

UPDATE Contenido SET id_tmdb = 12133, descripcion = 'Aunque Brennan Huff (Will Ferrell) tiene casi cuarenta años, sigue viviendo con su madre Nancy (Mary Steenburgen) y se conforma con conseguir, de vez en cuando, empleos esporádicos. Dale Doback (John C. Reilly), es un parado profesional de cuarenta años que vive con su padre, Robert (Richard Jenkins). Cuando Nancy y Robert se casan, los dos parásitos se ven obligados a compartir casa, pero, debido a su narcisismo y a su agresiva pereza se establece entre ellos una competencia que llega a enturbiar la relación entre sus padres.', trailer_url = 'https://www.youtube.com/watch?v=3NCsx6qFzl0' WHERE id_api = 'tt0838283';

