UPDATE Contenido SET id_tmdb = 4538, descripcion = 'Tres hermanos americanos que llevaban un año sin hablarse, deciden hacer un viaje en tren por la India, con la intención de encontrarse a ellos mismos y conectar con los demás. En resumen, para volver a ser hermanos, como solían serlo. Pero, por varias razones, su aventura espiritual se tuerce rápidamente.', trailer_url = 'https://www.youtube.com/watch?v=aO1bYukdvLI' WHERE id_api = 'tt0838221';

UPDATE Contenido SET id_tmdb = 39781, descripcion = 'Nic (Annette Benning) y Jules (Julianne Moore) son una pareja de lesbianas que viven con sus dos hijos adolescentes: Joni (Mia Wasikowska) y Laser (Josh Hutcherson), ambos fruto de la inseminación artificial. Lo que obsesiona a los dos chicos es conocer a su padre biológico (Mark Ruffalo). Por un capricho del destino lo encuentran y deciden que forme parte de sus vidas, aunque naturalmente tropezarán con la oposición de sus madres. Pero ese no va a ser el único problema', trailer_url = 'https://www.youtube.com/watch?v=RixlpHKfb6M' WHERE id_api = 'tt0842926';

UPDATE Contenido SET id_tmdb = 23168, descripcion = 'En Boston se producen más de 300 robos cada año. Y un barrio llamado Charlestown ha dado más ladrones de vehículos blindados y bancos que ningún otro lugar de EE.UU. Uno de ellos es Doug MacRay, aunque no está hecho de la misma pasta que sus colegas en el crimen. A diferencia de ellos, Doug sí ha tenido una oportunidad de tener éxito, una oportunidad para evitar seguir las huellas criminales de su padre. Pero en lugar de ello, se convirtió en el líder de un grupo de implacables ladrones de bancos que se enorgullecen de coger lo que quieren de forma limpia. La única familia que tiene Doug es la de sus socios criminales. Sin embargo, todo cambia tras el último trabajo de la banda. Doug intentará cambiar de vida y de ciudad, pero no le va a resultar fácil lograrlo.', trailer_url = 'https://www.youtube.com/watch?v=0pWsKuPRf0Q' WHERE id_api = 'tt0840361';

UPDATE Contenido SET id_tmdb = 13260, descripcion = 'Jackie Moon (Will Ferrell) es el propietario, entrenador y jugador de Flint Michigan Tropics, un equipo de baloncesto perteneciente a la American Basketball Association. Sueña con dar el salto a la NBA y pondrá todo el empeño del mundo para conseguirlo.', trailer_url = 'https://www.youtube.com/watch?v=-gv-sxP-4Os' WHERE id_api = 'tt0839980';

UPDATE Contenido SET id_tmdb = 6575, descripcion = 'Comedia musical en forma de parodia que narra el auge y caída del legendario músico y compositor Dewey Cox (John C. Reilly), un personaje ficticio mitad Roy Orbison y mitad Johnny Cash. "Walk Hard: The Dewey Cox Story" es la historia de un músico cuyas canciones cambiaron a una nación con su rock and roll espiral. Este hombre se acostó con 411 mujeres, se casó tres veces, tuvo 22 hijos y acogió a otros 14, triunfó en los programas de televisión de los años 70, se codeaba con gente de la talla de Elvis o los Beatles, era adicto a todo tipo de drogas que un hombre pueda conocer y, a pesar de todo, se convirtió en un icono de su país.', trailer_url = 'https://www.youtube.com/watch?v=-Mv9PMbpkZw' WHERE id_api = 'tt0841046';

UPDATE Contenido SET id_tmdb = 21755, descripcion = 'Los hermanos Bloom han ido perfeccionando progresivamente el arte de estafar grandes fortunas durante muchos años de fraternal trabajo en equipo. Su último y espectacular proyecto consiste en involucrar a una bella y excéntrica heredera en una conspiración que los llevará alrededor del mundo.', trailer_url = 'https://www.youtube.com/watch?v=qIlJbFR27Tk' WHERE id_api = 'tt0844286';

