UPDATE Contenido SET id_tmdb = 22794, descripcion = 'Adaptación del libro homónimo de Judi Barrett, una parodia animada de los films de catástrofes, como Armageddon, Twister o Independence Day. El protagonista es Flint, un joven científico que sueña con inventar algo que le mejore la vida a todos sus vecinos. Tras muchos intentos consigue crear algo que realmente funciona: una máquina que hace caer comida del cielo.', trailer_url = 'https://www.youtube.com/watch?v=k33j4MGrTbg' WHERE id_api = 'tt0844471';

UPDATE Contenido SET id_tmdb = 21407, descripcion = 'Arkin (Josh Stewart) es un ladrón ex-convicto que decide entrar en la casa de campo donde comienza a trabajar, para robar una valiosa joya. La desagradable sorpresa para Arkin llegará en forma de un brutal asesino en serie (familiarizado con las técnicas de tortura de la inquisición española) que se encuentra en el interior de la casa y tiene secuestrada a toda la familia.', trailer_url = 'https://www.youtube.com/watch?v=EE1sL7QWL5c' WHERE id_api = 'tt0844479';

UPDATE Contenido SET id_tmdb = 18405, descripcion = 'Remake de la película "La última casa a la izquierda", dirigida por Wes Craven en 1972. Mari Collingwood llega con sus padres a la casa que tienen junto al lago para pasar unos días. Esa misma tarde, saliendo por la zona con su amiga Paige, ambas son secuestradas por Krug, un psicópata que ha escapado de la cárcel, y sus compañeros, su perturbada novia Sadie, su sádico hermano Francis, y su anulado hijo Justin.', trailer_url = 'https://www.youtube.com/watch?v=Qx2khCbD3h0' WHERE id_api = 'tt0844708';

