UPDATE Contenido SET id_tmdb = 116711, descripcion = 'Historia sobre la interminable batalla entre las fuerzas del bien, encargadas de mantener la vida, y las fuerzas del mal, que pretenden destruirla. Mary Katherine (Amanda Seyfried) es una adolescente que intenta reanudar la relación con su padre el Profesor Bomba (Jason Sudeikis), un científico cuya obsesión es descubrir una diminuta sociedad secreta que habita en el bosque. Esta idea a su hija le parece disparatada hasta que, inesperadamente, es transportada a ese universo secreto, donde se está librando una batalla entre los Hombres Hoja y los Boggans.', trailer_url = 'https://www.youtube.com/watch?v=zpxDLlJCeSM' WHERE id_api = 'tt0848537';

UPDATE Contenido SET id_tmdb = 4977, descripcion = 'El psiquiatra Atsuko Chiba ha desarrollado un método de terapia revolucionario denominado "PT", un prototipo de máquina experimental gracias a la cual es posible introducirse en la mente de los pacientes para tratar sus ansiedades. Pero uno de los modelos de PT es robado del laboratorio del Dr. Atsuko, y comienzan a utilizarlo para invadir las mentes de sus creadores, destruyendo sus personalidades mientras duermen.', trailer_url = 'https://www.youtube.com/watch?v=yn7U1KIGeuQ' WHERE id_api = 'tt0851578';

UPDATE Contenido SET id_tmdb = 13025, descripcion = 'Jason Creed y un pequeño equipo de una escuela de cine se encuentran en los bosques de Pensilvania realizando sin financiación una película de terror. Es entonces cuando se dan cuenta de que la muerte ha empezado a recobrar vida.Conducidos por la novia de Jason, Debra, los aterrados jóvenes realizadores se van a la ciudad de Winnebago para intentar volver al único lugar seguro que conocen: sus hogares.Pero no hay escapatoria para la crisis, ya no queda ningún hogar real para ellos. Todo de lo que dependen, todo lo que quieren, se ha quebrado por una plaga de muertos vivientes que comienza a extenderse.', trailer_url = 'https://www.youtube.com/watch?v=c_8kL7L7arE' WHERE id_api = 'tt0848557';

UPDATE Contenido SET id_tmdb = 10545, descripcion = 'En un pueblo de Lousiana, una serie de brutales asesinatos hace peligrar la convivencia entre vampiros y seres humanos, que hasta entonces había sido pacífica gracias a una bebida japonesa hecha de sangre sintética. Sin embargo, algunos vampiros estaban descontentos porque preferían seguir alimentándose de sangre humana; pero también había hombres que no estaban satisfechos con esta situación. En estas circunstancias nace el polémico romance entre Bill Compton (Stephen Moyer, "Quills"), el primer vampiro que llega al pueblo, y Sookie Stackhouse (Anna Paquin), una camarera clarividente. Nueva serie de la HBO realizada por Alan Ball ("A dos metros bajo tierra"). Basada en la serie de novelas ''Southern vampire'', de la escritora norteamericana Charlaine Harris.', trailer_url = 'https://www.youtube.com/watch?v=3Wk3HSiX-vQ' WHERE id_api = 'tt0844441';

La segunda temporada explora la relación de la telépata Sookie Stackhouse con su amante vampiro, Bill Compton. También introduce a numerosos participantes de la Fraternidad anti-vampiros de la iglesia del Sol y el adoctrinamiento de Jason Stackhouse en la iglesia por sus líderes, Reverendo Steve Newlin y su esposa Sarah. También amplía el papel de Maryann Forrester, una poderosa criatura sobrenatural que controla lentamente al pueblo de Bon Temps. Sookie viaja a Dallas con Bill para ayudar a encontrar al creador de Eric, un vampiro de dos mil años de edad llamado Godric, que ha desaparecido y se cree que ha sido secuestrado por el movimiento del sol.');

