UPDATE Contenido SET id_tmdb = 13312, descripcion = 'Una mujer embarazada y viuda (Alysson Paradis), cuyo novio ha fallecido recientemente, pasa la noche de navidad a solas, completamente afligida por la pérdida del padre de su bebé, cuando una extraña (Béatrice Dalle) se presenta en su casa...', trailer_url = 'https://www.youtube.com/watch?v=0-Aqb1lFNtQ' WHERE id_api = 'tt0856288';

