UPDATE Contenido SET id_tmdb = 433, descripcion = 'Secuela de "Terminator" centrada en el personaje de Sarah Connor (Lena Headey). Después de destruir al T-1000, Sarah y John se convierten en proscritos y descubren nuevos enemigos que combatir tanto del presente como del futuro. Sarah, atormentada por visiones de la próxima guerra nuclear, deja de esconderse y pasa a la ofensiva para destruir la tecnología que trata de eliminarla a ella y al mundo. Su hijo John Connor, futuro líder de la resistencia y última esperanza de la humanidad en la apocalíptica guerra contra las máquinas, aún no está listo para asumir esa responsabilidad. El agente del FBI James Ellison acaba viéndose involucrado en este caso.', trailer_url = 'https://www.youtube.com/watch?v=GVhElUwt4Tw' WHERE id_api = 'tt0851851';

