UPDATE Contenido SET id_tmdb = 8338, descripcion = 'Una misteriosa epidemia de ceguera se propaga en todo un país. Las primeras víctimas son recluidas en un hospital sin recibir explicaciones. Entre ellas está una mujer que conserva la vista, pero lo mantiene en secreto para poder acompañar a su marido, que se ha quedado ciego. Dentro del hospital se impone la ley del más fuerte, lo que dará lugar a todo tipo de atrocidades. Mientras tanto, el caos y el terror dominan las calles. Adaptación de la novela "Ensayo sobre la ceguera", del Premio Nobel portugués José Saramago.', trailer_url = 'https://www.youtube.com/watch?v=CrKGNaeoKo0' WHERE id_api = 'tt0861689';

UPDATE Contenido SET id_tmdb = 1877, descripcion = 'Phineas y Ferb son dos hermanastros que viven en compañía de su hermana y hermanastra Candace y sus padres Lynda y Lawrence en el pequeño pueblo de Danville. Ambos están insatisfechos con estar todo el verano sin hacer nada, por lo que se dedican a buscar una idea novedosa y excitante para disfrutar más las vacaciones. Candace sabe de sus inusuales actividades y constantemente está tratando de llamar la atención de su madre al respecto, para que esta castigue a los niños.  Su ornitorrinco mascota llamado Perry resulta ser en realidad un agente secreto encubierto conocido simplemente como "Agente P". En su constante lucha por detener los malévolos planes del malvado Doctor Doofenshmirtz, toda traza de actividad inusual de los chicos es eliminada por mera coincidencia, antes de que Candace pueda mostrársela a su madre, por lo que siempre queda como un tonta ante ella..', trailer_url = 'https://www.youtube.com/watch?v=th9hxCGH_ms' WHERE id_api = 'tt0852863';

