UPDATE Contenido SET id_tmdb = 37861, descripcion = 'En el siglo X, One-Eye, un enigmático y silencioso guerrero con una fuerza sobrehumana que ha permanecido esclavizado durante años, logra acabar con la vida de su captor, y huir junto a Are, el niño que le ha prestado su ayuda para escapar. En su huida ambos acabarán por enrolarse en un barco tripulado por vikingos, iniciando así un viaje que les transportará a una tierra desconocida, una tierra de autodescubrimiento, pero también de sangre, y dolor.', trailer_url = 'https://www.youtube.com/watch?v=8vf5e3j0vDY' WHERE id_api = 'tt0862467';

UPDATE Contenido SET id_tmdb = 23202, descripcion = 'Filme que intercala cuatro historias en la noche de Halloween. Una de las historias se centra en un director de instituto que se convierte en un vicioso asesino en serie con la luna llena. Otra trata de una virgen en edad universitaria que se reserva para el hombre de su vida, a quien cree que acaba de conocer. La tercera versa sobre una mujer cuyo odio hacia Halloween sólo es superado por el amor que le tiene su marido a esta festividad. Por último, un grupo de adolescentes despiadados llevan a cabo una broma imperdonablemente cruel. Ha sido definida por varios críticos nortamericanos como una versión en carne y hueso de "Pesadilla Antes de Navidad".', trailer_url = 'https://www.youtube.com/watch?v=ukylEvRE76w' WHERE id_api = 'tt0862856';

UPDATE Contenido SET id_tmdb = 2742, descripcion = 'The trials and tribulations of a two man, digi-folk band who have moved from New Zealand to New York City in the hope of forging a successful music career. So far they''ve managed to find a manager (whose "other" job is at the New Zealand Consulate), one fan (a married obsessive) and one friend (who owns the local pawn shop) -- but not much else.', trailer_url = NULL WHERE id_api = 'tt0863046';

UPDATE Contenido SET id_tmdb = 13090, descripcion = 'Rose y Norah Lorkowski son dos hermanas en paro que encuentran una particular forma de ganarse la vida: limpiar las escenas de crimen después de que la policía haya hecho su trabajo. Durante años, Rose (Amy Adams) fue líder de las animadoras y parecía tener un futuro prometedor, pero actualmente tiene poco de lo que presumir. Ahora es una madre soltera que intenta mantener a su hijo y a su desastrosa hermana Norah (Emily Blunt) con un trabajo como limpiadora. Cuando expulsan a su hijo de la escuela, Rose consigue un trabajo como limpiadora de escenas de crimen para intentar pagar así un colegio privado para el niño. Además, convence a Norah para que le ayude en este creciente negocio. A medida que las hermanas trabajan juntas aprenderán a reconciliar sus diferencias y a superar un pasado problemático además de disfrutar de su aventura empresarial.', trailer_url = 'https://www.youtube.com/watch?v=syGGh1rbFCI' WHERE id_api = 'tt0862846';

UPDATE Contenido SET id_tmdb = 12783, descripcion = 'Hermosa, glamurosa y adorada por el pueblo, Georgiana Spencer fue, como su descendiente Diana de Gales, la mujer más fascinante de su época. Pero mientras que su belleza y su carisma le forjó un nombre en la historia, el amor siempre se le escapó. Casada muy joven con uno de los hombres más ricos de Inglaterra, el duque de Devonshire, fue confidente íntima de ministros y de la Casa Real, llegando a ser un icono de la moda, madre adorada e influyente política para el partido liberal. Sin embargo, en el núcleo de su historia está la búsqueda desesperada de afecto y amor. Desde el apasionado pero fatídico romance con Charles Grey hasta el complicado triángulo amoroso con su marido y su mejor amiga lady Foster.', trailer_url = 'https://www.youtube.com/watch?v=FFg-oduezDs' WHERE id_api = 'tt0864761';

UPDATE Contenido SET id_tmdb = 1729, descripcion = 'Un joven (Michael Angarano), que siente una gran pasión por el cine de Kung Fu, visita regularmente una casa de empeños en Chinatown buscando películas. En una de sus visitas descubre un bastón que ha visto en un sueño recientemente, y más tarde se ve envuelto en un atraco en la misma casa de empeños, tras el cual huye con el bastón. En medio de la huida cae desde una azotea y es milagrosamente transportado a la China medieval donde, con la ayuda del luchador borracho (Jackie Chan), el monje silencioso (Jet Li), y el Gorrion Dorado (Yifei Liu), deberá devolver este bastón al mismo Rey Mono, transformado en una estatua de piedra mucho tiempo atras.', trailer_url = 'https://www.youtube.com/watch?v=MuEWMxgKa1E' WHERE id_api = 'tt0865556';

UPDATE Contenido SET id_tmdb = 82703, descripcion = 'Los personajes de la serie animada de los 60 The Rocky &amp; Bullwinkle Show, Mr. Peabody y Sherman, se cuelan en la gran pantalla adquiriendo una nueva dimensión 3D.  En esta ocasión el perro parlante más inteligente del mundo, Mr. Peabody y su mascota Sherman, un enérgico niño bastante ingenuo, se adentrarán en nueva una aventura determinante en el curso de la historia universal. Cuando Sherman desastrosamente avería la máquina del tiempo, la peculiar pareja se ve obligada a recomponer los hechos y arreglar la máquina antes de que sea demasiado tarde y el continuo espacio-tiempo se destruya afectando irreparablemente a nuestra existencia.', trailer_url = 'https://www.youtube.com/watch?v=aMl2tTVwsZA' WHERE id_api = 'tt0864835';

UPDATE Contenido SET id_tmdb = 10761, descripcion = 'Para Tom (Patrick Dempsey) la vida es maravillosa: es un triunfador, tiene éxito con las mujeres y sabe que siempre podrá confiar en su mejor amiga, la encantadora Hannah (Michelle Monaghan). Todo va bien hasta que Hannah se va seis semanas a Escocia por razones de trabajo; entonces Tom se da cuenta de que sin ella su vida está tan vacía que está decidido a pedirle que se case con él en cuanto vuelva. El problema es que cuando Hannah regresa está prometida y le pide a Tom que sea su "dama de honor"...', trailer_url = 'https://www.youtube.com/watch?v=izNkkDFh_ws' WHERE id_api = 'tt0866439';

UPDATE Contenido SET id_tmdb = 451048, descripcion = 'Principios del siglo XX. Frank es el carismático capitán de una peculiar embarcación que recorre la selva amazónica. Allí, a pesar de los peligros que el río Amazonas les tiene preparados, Frank llevará en su barco a la científica Lily Houghton y a su hermano McGregor Houghton. Su misión será encontrar un árbol místico que podría tener poderes curativos. Claro que su objetivo no será fácil, y en su aventura se encontrarán con toda clase de dificultades, además de una expedición alemana que busca también este árbol con propiedades curativas. Esta comedia de acción y aventuras está basada en la atracción Jungle Cruise de los parques de ocio de Disney.', trailer_url = 'https://www.youtube.com/watch?v=mamwmMsJ_lw' WHERE id_api = 'tt0870154';

UPDATE Contenido SET id_tmdb = 17609, descripcion = 'Una pareja sumida en el dolor se retira a una cabaña perdida en medio del bosque, llamada "Edén", con la esperanza de que el contacto con la naturaleza cure sus corazones rotos y su tambaleante matrimonio. Pero la naturaleza sigue su curso y las cosas empiezan a ir de mal en peor.', trailer_url = 'https://www.youtube.com/watch?v=l57hz1Nlr8E' WHERE id_api = 'tt0870984';

UPDATE Contenido SET id_tmdb = 11499, descripcion = 'Richard Nixon (Frank Langella) permaneció en silencio durante tres años tras renunciar a la presidencia de los Estados Unidos. En 1977 accedió a una entrevista con el fin de aclarar algunos puntos oscuros de la época en la que estaba en el gobierno y utilizarla para un posible regreso a la política. El entrevistador fue el joven David Frost (Michael Sheen), al que Nixon creía que iba a doblegar. Pero el resultado fue una gran batalla dialéctica entre los dos, vista por 45 millones de personas en cuatro noches.', trailer_url = 'https://www.youtube.com/watch?v=O9S1RKNgdLw' WHERE id_api = 'tt0870111';

UPDATE Contenido SET id_tmdb = 8780, descripcion = 'Una brillante mujer de negocios sueña con tener un hijo, pero descubre que no es fértil, por lo que decide contratar a una mujer trabajadora como madre de alquiler.', trailer_url = 'https://www.youtube.com/watch?v=stc7RUABPaU' WHERE id_api = 'tt0871426';

UPDATE Contenido SET id_tmdb = 10197, descripcion = 'Adaptación de un musical de Broadway de 1982 que, a su vez, era un remake modernizado del "8 y medio" de Fellini. Narra la crisis personal y profesional de Guido Contini, un conocido director de cine (Daniel Day-Lewis). En la vida de Guido hay demasiadas mujeres: su esposa (Marion Cotillard), su amante (Penélope Cruz), su musa (Nicole Kidman), su confidente y diseñadora de vestuario (Judi Dench), una periodista de moda americana (Kate Hudson), el amor platónico de su juventud (Fergi) y su madre (Sophia Loren).', trailer_url = 'https://www.youtube.com/watch?v=hywycMnDUvA' WHERE id_api = 'tt0875034';

UPDATE Contenido SET id_tmdb = 48572, descripcion = 'Las hormonas pueden ser muy traicioneras. Y si no, que se lo digan a los adolescentes que, atraídos por un anuncio que promete sexo en grupo con una mujer, caen en la trampa de un grupo de fanáticos religiosos dispuestos a erradicar con métodos extremos la libido de la juventud norteamericana. Historia inspirada en la figura real de Fred Phelps, el líder de un grupo religioso extremista que se hacía llamar la Iglesia Bautista Westboro.', trailer_url = 'https://www.youtube.com/watch?v=uJ1v6oFHefc' WHERE id_api = 'tt0873886';

UPDATE Contenido SET id_tmdb = 8624, descripcion = 'Kenny Powers es un famoso jugador de beisbol que por su carácter autodestructivo pierde su puesto en la liga de Beisbol. Ya retirado, tendrá que volver a su ciudad natal en Carolina del Norte, donde será designado como el nuevo entrenador de un equipo de instituto en el que estudió de joven.', trailer_url = 'https://www.youtube.com/watch?v=ADK-g921i0M' WHERE id_api = 'tt0866442';

Causando estragos en la escuela, por la ciudad y en la casa de su hermano Dustin, Kenny se mete en su papel de agitador de la ciudad, poniendo su mirada en recuperar a April, su viejo amor de secundaria, ahora comprometida con el director de la escuela, Terrence Cutler.', 30, '2009-02-15');

UPDATE Contenido SET id_tmdb = 14163, descripcion = 'A team of rag-tag girls with their own agenda form Team India competing for international fame in field hockey. Their coach, the ex-men''s Indian National team captain, returns from a life of shame after being unjustly accused of match fixing in his last match. Can he give the girls the motivation required to win, while dealing with the shadows of his own past?', trailer_url = 'https://www.youtube.com/watch?v=6a0-dSMWm5g' WHERE id_api = 'tt0871510';

UPDATE Contenido SET id_tmdb = 13916, descripcion = 'Light Yagami, un estudiante japonés, encuentra un cuaderno llamado Death Note que permite matar a cualquier persona cuyo nombre se escriba en él. Usando este poder, decide crear un mundo "perfecto" eliminando a los criminales. Sin embargo, su plan empieza a torcerse cuando L, un brillante detective, intenta descifrar el misterio que rodea a todas estas muertes.', trailer_url = 'https://www.youtube.com/watch?v=rZzG1C2hI8M' WHERE id_api = 'tt0877057';

UPDATE Contenido SET id_tmdb = 22881, descripcion = 'Basada en hechos reales, narra la historia de Michael Oher, un joven afroamericano sin hogar que encuentra ayuda y cobijo en una familia blanca, dispuesta a prestarle el apoyo necesario para que pueda desarrollar todo su potencial, tanto para triunfar como jugador de fútbol americano como en la vida. Por su parte Oher también influirá en la vida de los miembros de la familia Touhy, que atravesarán también por experiencias de descubrimiento personal. El cambio de ambiente significa también nuevos desafíos que el joven habrá de vencer, esforzándose por dar lo máximo de sí mismo como deportista y como persona.', trailer_url = 'https://www.youtube.com/watch?v=YcJ4DW4XOEA' WHERE id_api = 'tt0878804';

UPDATE Contenido SET id_tmdb = 12429, descripcion = 'La historia se centra en Sosuke, un niño de 5 años, y su relación con una princesa pez que ansía convertirse en un ser humano. Libre adaptación de "La sirenita" que obtuvo muy buena acogida de la crítica en el Festival de Venecia 2008.', trailer_url = 'https://www.youtube.com/watch?v=89LbtkHG0c4' WHERE id_api = 'tt0876563';

UPDATE Contenido SET id_tmdb = 8090, descripcion = 'El FBI cuenta con un departamento encargado de delitos cibernéticos que se dedica únicamente a investigar y perseguir a los delincuentes que actúan en Internet. En Portland, la agente especial Jennifer Marsh (Diane Lane) tiene que resolver un caso sin precedentes: un depredador cibernético cuelga torturas y asesinatos en una sofisticada página web que, al no dejar rastro, no puede ser desconectada. El destino de sus víctimas depende del público: cuantas más visitas registre la página web, más deprisa morirán. Cuando el juego del gato y el ratón se convierte en algo personal, Jennifer y su equipo deberán lanzarse a una carrera contrarreloj para encontrar al asesino.', trailer_url = 'https://www.youtube.com/watch?v=1Vx3GR_AowA' WHERE id_api = 'tt0880578';

UPDATE Contenido SET id_tmdb = 38167, descripcion = 'Tras varios fracasos sentimentales, una mujer decide encontrarse a sí misma a través de un viaje por Italia, la India, Bali e Indonesia. Liz Gilbert (Julia Roberts) tenía todo lo que una mujer puede soñar, un marido, una casa y una brillante carrera, pero se encontraba perdida, confusa, insatisfecha. Una vez divorciada, y tras un periodo de reflexión, decide abandonar su acomodada vida y lo arriesga todo, emprendiendo un viaje alrededor del mundo. La historia se basa en el best-seller autobiográfico de Elizabeth Gilbert.', trailer_url = 'https://www.youtube.com/watch?v=mjay5vgIwt4' WHERE id_api = 'tt0879870';

UPDATE Contenido SET id_tmdb = 48340, descripcion = 'Un grupo de submarinistas, encabezado por un padre y un hijo, realiza una expedición a la cueva más grande e inaccesible del mundo. A causa de una tormenta tropical, tendrán que enfrentarse a numerosos peligros, mientras buscan una ruta que les permita salir y salvar sus vidas.', trailer_url = 'https://www.youtube.com/watch?v=6LvaIZ0z3aE' WHERE id_api = 'tt0881320';

UPDATE Contenido SET id_tmdb = 134411, descripcion = 'Un padre recibe un duro golpe cuando condenan a su hijo adolescente a a una pena de treinta años de cárcel por un delito relacionado con el narcotráfico. Para conseguir que reduzcan su condena, intenta ponerse en contacto con un importante traficante.', trailer_url = 'https://www.youtube.com/watch?v=arLus-AyVuM' WHERE id_api = 'tt0882977';

UPDATE Contenido SET id_tmdb = 5876, descripcion = 'En un pequeño pueblo de Maine, estalla de repente una violenta tormenta que termina tan bruscamente como comenzó. Entonces surge una espesa niebla que va entrando en casas y supermercados, atrapando y matando a todos los que se ven envueltos por la oscuridad.', trailer_url = 'https://www.youtube.com/watch?v=gaDQR6svjuk' WHERE id_api = 'tt0884328';

UPDATE Contenido SET id_tmdb = 23706, descripcion = 'Para Mary, nada es normal, sobre todo su relación con los demás. Cuando le organizan una cita a ciegas con el apuesto operador de cámara Steve, Mary cree que la química entre ellos es evidente y que Steve es “él”. Steve, por otro lado, piensa que Mary está loca. Mary, absolutamente segura de haber encontrado a su alma gemela, decide hacer lo que haga falta para estar con él. Comienza a perseguirle sin descanso mientras Steve recorre el país cubriendo las noticias de la actualidad.', trailer_url = 'https://www.youtube.com/watch?v=mtJfr-a_oHQ' WHERE id_api = 'tt0881891';

UPDATE Contenido SET id_tmdb = 12162, descripcion = 'En Irak, una unidad de élite de artificieros norteamericanos actúa en una caótica ciudad donde cualquier persona puede ser un enemigo y cualquier objeto, una bomba. El jefe del grupo, el sargento Thompson, muere en el transcurso de una misión y es sustituido por el impredecible y temerario sargento William James. Cuando falta poco para que la brigada sea relevada, el imprudente comportamiento de James hará que dos de sus subordinados, se planteen seriamente el riesgo que corren.', trailer_url = 'https://www.youtube.com/watch?v=MLTteBwHxlY' WHERE id_api = 'tt0887912';

UPDATE Contenido SET id_tmdb = 252838, descripcion = 'A menos de dos semanas de casarse con Gretchen, la chica de sus sueños, Doug Harris no encuentra siquiera a un conocido que pueda hacer de padrino en su boda, por lo que termina contratando a Jimmy Callahan, propietario de una empresa que provee de falsos padrinos a novios solitarios como él.', trailer_url = 'https://www.youtube.com/watch?v=wenJTjqMnMQ' WHERE id_api = 'tt0884732';

UPDATE Contenido SET id_tmdb = 4944, descripcion = 'Ozzie Cox es un agente de la CIA que está escribiendo sus memorias en un CD, pero su mujer se lo roba y va a parar a manos de los empleados de un gimnasio, que no son muy listos, pero que intentan chantajear a Cox. La CIA, naturalmente, interviene en el asunto, que se complica cuando el empleado del gimnasio (Pitt) se encuentra con el amante de la mujer de Cox. Basada en la novela "Burn Before Reading: Presidents, CIA Directors, and Secret Intelligence" del ex jefe de la CIA Stansfield Turner.', trailer_url = 'https://www.youtube.com/watch?v=mSO4EUYNWTs' WHERE id_api = 'tt0887883';

UPDATE Contenido SET id_tmdb = 41210, descripcion = 'Cuando Kassie (Jennifer Aniston) cumple los cuarenta decide no esperar más y recurre a la inseminación artificial para tener un bebé. Siete años más tarde, regresa a Nueva York y se reencuentra con su amigo Wally (Bateman), un hombre neurótico e inseguro, que, de manera inexplicable se siente fuertemente vinculado al hijo de Kassie, el pequeño Sebastian (Thomas Robinson), un niño con el que comparte algo más que sus múltiples manías y excentricidades. Basada en el relato "Baster", del novelista ganador del premio Pulitzer Jeffrey Eugenides, autor de "Las vírgenes suicidas".', trailer_url = 'https://www.youtube.com/watch?v=aomRONeJ3fQ' WHERE id_api = 'tt0889573';

UPDATE Contenido SET id_tmdb = 338947, descripcion = 'Una joven que lucha contra la adicción se apodera de una antigua caja de rompecabezas, sin saber que su propósito es convocar a los Cenobitas, un grupo de sádicos seres sobrenaturales de otra dimensión.', trailer_url = 'https://www.youtube.com/watch?v=oUlgwJNdu2I' WHERE id_api = 'tt0887261';

UPDATE Contenido SET id_tmdb = 18480, descripcion = 'Sacha Baron Cohen interpreta a Brüno, un reportero gay con cierta obsesión por la moda y por el culto al cuerpo. Brüno no sólo sembrará el caos y la controversia en el mundo de la moda para sacar a la luz sus miserias, sino que también ha dirigido sus cáusticos dardos hacia otros aspectos, caso de las estrellas que adoptan niños de otros continentes, los militares o las prácticas sadomaso.', trailer_url = 'https://www.youtube.com/watch?v=79dJSf38D10' WHERE id_api = 'tt0889583';

UPDATE Contenido SET id_tmdb = 10191, descripcion = 'Ambientada en el mítico mundo de los rudos vikingos y los dragones salvajes, y basada en el libro infantil de Cressida Cowell, esta comedia de acción narra la historia de Hipo, un vikingo adolescente que no encaja exactamente en la antiquísima reputación de su tribu como cazadores de dragones. El mundo de Hipo se trastoca al encontrar a un dragón que le desafía a él y a sus compañeros vikingos, a ver el mundo desde un punto de vista totalmente diferente.', trailer_url = 'https://www.youtube.com/watch?v=-k5ve8onP1M' WHERE id_api = 'tt0892769';

UPDATE Contenido SET id_tmdb = 663, descripcion = 'A pesar de la muerte de Jigsaw, y para salvar la vida de dos de sus colegas, el teniente Rigg se ve obligado a participar en un nuevo juego, que promete ponerlo a prueba hasta el límite.', trailer_url = 'https://www.youtube.com/watch?v=0YRCXAPDEQM' WHERE id_api = 'tt0890870';

UPDATE Contenido SET id_tmdb = 4515, descripcion = 'Conmovedora historia de varios individuos capturados en distintos lugares en una terrorífica guerra. Un senador que intenta convencer de una última "estrategia exhaustiva" a una periodista de una televisión. Un catedrático idealista que intenta convecer a uno de sus estudiantes más promotedores de que cambie el rumbo de su vida. Y dos hombres jóvenes, luchando en las nevadas montañas de Afganistán, cuyos deseos de vivir una vida con sentido les conducen a unirse a las tropas americanas y luchar contra el terrorismo global.', trailer_url = 'https://www.youtube.com/watch?v=VvooOSNWrDE' WHERE id_api = 'tt0891527';

UPDATE Contenido SET id_tmdb = 37056, descripcion = 'Sophie Hall (Amanda Seyfried) es una aspirante a escritora de una revista, quien, junto con su novio Víctor (Gael García Bernal), vuela desde Nueva York a Italia para vivir algo del romance que mucha falta le hace a la relación. Mientras Víctor está fuera, ocupándose de unos asuntos de trabajo, Sofía se encuentra en el famoso patio de Verona, donde mujeres de todas partes del mundo le dejan a Julieta cartas de amores perdidos y no correspondidos. Ella descubre una carta escrita 50 años antes a Julieta por Claire Smith (Vanessa Redgrave) buscando a un joven italiano que la cautivó siendo adolescente. Para sorpresa de Sophie, su carta inspira a Claire, ahora abuela, para viajar a Verona en busca de su amor perdido (Franco Nero).', trailer_url = 'https://www.youtube.com/watch?v=RNBBNOH4rjg' WHERE id_api = 'tt0892318';

UPDATE Contenido SET id_tmdb = 8881, descripcion = 'En 1952, el general Fulgencio Batista orquestó un golpe de estado en Cuba, tomó el control del gobierno del país y suspendió las elecciones. Su corrupta dictadura estaba respaldada por un ejército de 40.000 hombres, pero un joven abogado llamado Fidel Castro intentó incitar a la rebelión popular asaltando el cuartel Moncada el 26 de julio de 1953. El ataque no tuvo éxito y Castro pasó dos años en la cárcel antes de ir al exilio en México. Entre tanto, un joven idealista argentino llamado Ernesto Guevara se había involucrado en la actividad política de Guatemala. En 1954, cuando el gobierno legítimo de Jacobo Álvarez fue depuesto por una operación militar organizada por la CIA, Guevara escapó a México. Un conocido de Guatemala le puso en contacto con un grupo de revolucionarios cubanos en el exilio.', trailer_url = 'https://www.youtube.com/watch?v=fqTw2dtVQzw' WHERE id_api = 'tt0892255';

UPDATE Contenido SET id_tmdb = 1087891, descripcion = 'Charlie Heller es un brillante pero introvertido decodificador de la CIA que trabaja en una oficina en el sótano de la sede de Langley. Su vida cambia radicalmente cuando su esposa muere en un ataque terrorista en Londres. Cuando sus supervisores se niegan a tomar cartas en el asunto, él mismo toma las riendas y se embarca en un peligroso viaje por todo el mundo para localizar a los responsables. Su inteligencia puede ser el arma definitiva para llevar a cabo su venganza.', trailer_url = 'https://www.youtube.com/watch?v=8fQ7_9B0OZM' WHERE id_api = 'tt0899043';

UPDATE Contenido SET id_tmdb = 15512, descripcion = 'Cuando la californiana Susan Murphy es golpeada accidentalmente por un meteorito lleno de mugre espacial en el día de su boda, crece misteriosamente hasta alcanzar más de 15 metros de altura. Los militares entran en acción y Susan es capturada y llevada a unas instalaciones gubernamentales secretas. Allí, la rebautizan como Genórmica y la retienen junto a un variopinto grupo de monstruos: el doctor Cucaracha, brillante pero con cabeza de insecto, el bravucón mitad mono mitad pez, el Eslabón Perdido, el gelatinoso e indestructible B.O.B., y la larva de más de 100 metros llamada Insectosaurio. Sin embargo, su confinamiento se acaba cuando un misterioso robot alienígena aterriza y empieza a arrasarlo todo. En un momento de desesperación, al Presidente le convencen de que reclute al abigarrado grupo de monstruos para luchar contra los alienígenas y salvar al mundo de la destrucción inminente.', trailer_url = 'https://www.youtube.com/watch?v=KrGiuIY-gDc' WHERE id_api = 'tt0892782';

UPDATE Contenido SET id_tmdb = 10192, descripcion = 'En lugar de espantar a los aldeanos como él solía hacerlo, un recluido Shrek ahora accede a autografiar horquillas para siembra. Anhelando los días cuando se sentía un "ogro real", Shrek es embaucado al firmar un pacto con el afable negociador Rumpelstiltskin. De pronto Shrek se encuentra en una retorcida versión alterna de Muy Muy Lejano, donde Fiona es un ogro de caza, Rumpelstiltskin es el rey, Burro nunca ha conocido a Shrek, el Gato con Botas es obeso y perezoso, y Shrek y Fiona no se conocían. Ahora, está en las manos de Shrek deshacer todo lo que hizo con la esperanza de salvar a sus amigos, restaurar su mundo y recuperar a su único y verdadero amor.', trailer_url = 'https://www.youtube.com/watch?v=xTAWc9JqgKA' WHERE id_api = 'tt0892791';

UPDATE Contenido SET id_tmdb = 20766, descripcion = 'El planeta ha sido arrasado por un misterioso cataclismo y, en medio de la desolación, un padre y su hijo se dirigen hacia la costa en busca de un lugar seguro donde asentarse. Durante el viaje se cruzarán con otros supervivientes: unos se han vuelto locos, otros se han convertido en caníbales.', trailer_url = 'https://www.youtube.com/watch?v=tloYv8bUAHY' WHERE id_api = 'tt0898367';

UPDATE Contenido SET id_tmdb = 13252, descripcion = 'Tom Cutler es un ex policía que ahora se dedica a limpiar escenas de crímenes una vez que ya han sido investigados. Concienzudo y metódico, no deja jamás rastro alguno que pueda indicar que haya ocurrido una tragedia en ese lugar. Cuando recibe el encargo de limpiar la escena de un brutal asesinato acaecido en un barrio de clase alta, lo encara como un trabajo más… hasta que se da cuenta de que nadie ha comunicado el crimen a la policía y que lo que ha hecho es eliminar toda evidencia del mismo.', trailer_url = 'https://www.youtube.com/watch?v=fdF699_b2wI' WHERE id_api = 'tt0896798';

UPDATE Contenido SET id_tmdb = 10521, descripcion = 'Emma y Liv han sido desde siempre muy buenas amigas (de aquellas que se apoyan en todo, a las buenas y a las malas) y, desde su infancia, han soñado con casarse en junio en el Hotel Plaza de Nueva York. Una ilusión que van a poder compartir y planificar juntas, ya que sus peticiones de mano ocurren con poco tiempo de diferencia y sus bodas van a ser el mismo fin de semana. Un error administrativo, sin embargo, agrieta esta felicidad: las bodas han sido reservadas para el mismo día, y una de las dos va a tener que cambiar la fecha. Sin estar dispuestas a renunciar a su sueño, y utilizando todas las armas que tienen a su alcance, empezará entonces una feroz competición entre Liv y Emma para conseguir la reserva del Hotel Plaza.', trailer_url = 'https://www.youtube.com/watch?v=KBDE4uznmIw' WHERE id_api = 'tt0901476';

UPDATE Contenido SET id_tmdb = 49051, descripcion = 'Precuela de la trilogía "El Señor de los Anillos", obra de J.R.R. Tolkien. En compañía del mago Gandalf y de trece enanos, el hobbit Bilbo Bolsón emprende un viaje a través del país de los elfos y los bosques de los trolls, desde las mazmorras de los orcos hasta la Montaña Solitaria, donde el dragón Smaug esconde el tesoro de los Enanos. Finalmente, en las profundidades de la Tierra, encuentra el Anillo Único, hipnótico objeto que será posteriormente causa de tantas sangrientas batallas en la Tierra Media.', trailer_url = 'https://www.youtube.com/watch?v=Y5wMFIVvnsE' WHERE id_api = 'tt0903624';

UPDATE Contenido SET id_tmdb = 271714, descripcion = 'Biopic sobre el músico y compositor Brian Wilson, fundador de los Beach Boys, sobre su influencia en la música, y sus problemas nerviosos que propiciaron su relación con el controvertido terapeuta Dr. Eugene Landy.', trailer_url = 'https://www.youtube.com/watch?v=Xne-_S34T1c' WHERE id_api = 'tt0903657';

UPDATE Contenido SET id_tmdb = 1396, descripcion = 'Un profesor de química con cáncer terminal se asocia con un exalumno suyo para fabricar y vender metanfetamina a fin de que su familia no pase apuros económicos.', trailer_url = 'https://www.youtube.com/watch?v=V8WQhxHEmMc' WHERE id_api = 'tt0903747';

UPDATE Contenido SET id_tmdb = 60935, descripcion = 'En una remota zona de la Antártida, un descubrimiento de gran relevancia científica se convierte en un problema de supervivencia. La paleontóloga Kate Lloyd (Mary Elizabeth Winstead) llega a esa inhóspita región para colaborar con un equipo científico noruego que ha encontrado una nave extraterrestre enterrada en el hielo, en cuyo interior hay un ser alienígena congelado pero cuyas células están vivas... Precuela de "La Cosa", película dirigida por John Carpenter y protagonizada por Kurt Russell, que se basaba en un clásico de serie B de los años 50.', trailer_url = 'https://www.youtube.com/watch?v=eFSMJIS-aF0' WHERE id_api = 'tt0905372';

UPDATE Contenido SET id_tmdb = 5723, descripcion = 'Glen Hansard es un cantante y compositor que interpreta sus canciones por las calles de Dublín, cuando no está trabajando en la tienda de su padre (Bill Hodnett). Durante el día, para ganar algún dinero extra, interpreta conocidos temas para los transeúntes, pero por las noches, toca sus propios temas en los que habla de cómo le dejó su novia. Su talento no pasa desapercibido a Marketa Irglova, una inmigrante checa que vende flores en la calle. Ella tampoco ha tenido suerte en el amor y, para sentirse un poco mejor, escribe canciones sobre el tema, pero, a diferencia de Glen, nunca las interpreta en público. Glen y Marketa, acaban de improviso haciendo un dueto en una tienda de música, y será entonces cuando descubran que algo les une...', trailer_url = 'https://www.youtube.com/watch?v=uWgwmJ_QvFg' WHERE id_api = 'tt0907657';

UPDATE Contenido SET id_tmdb = 10189, descripcion = 'Un adicto a las drogas (Seth Rogen) es el único testigo de un asesinato cometido por un maléfico capo de la droga (Gary Cole) y una policía corrupta (Rosie Perez). Amenazado de muerte, huye para salvar su vida, arrastrando con él a su camello (James Franco) y su proveedor (Danny McBride), en una divertidísima aventura cubierta de hierba.', trailer_url = 'https://www.youtube.com/watch?v=q2JkfsTEooc' WHERE id_api = 'tt0910936';

UPDATE Contenido SET id_tmdb = 10681, descripcion = 'En el año 2800, en un planeta Tierra devastado y sin vida, tras cientos de solitarios años haciendo aquello para lo que fue construido -limpiar el planeta de basura- el pequeño robot WALL•E descubre una nueva misión en su vida cuando se encuentra con una moderna y lustrosa robot exploradora llamada EVE. Ambos viajarán a lo largo de la galaxia y vivirán una emocionante e inolvidable aventura.', trailer_url = 'https://www.youtube.com/watch?v=4rDD3SccHxQ' WHERE id_api = 'tt0910970';

UPDATE Contenido SET id_tmdb = 38199, descripcion = 'Un thriller psicológico centrado alrededor de un agente del FBI que presiona a un presunto terrorista para que le diga la localización de tres armas nucleares colocadas en los Estados Unidos.', trailer_url = 'https://www.youtube.com/watch?v=U0HtF4_2uyg' WHERE id_api = 'tt0914863';

UPDATE Contenido SET id_tmdb = 14574, descripcion = 'Berlín, 1942. Bruno tiene ocho años y desconoce el significado de la Solución Final y del Holocausto. No es consciente de las pavorosas crueldades que su país, en plena guerra mundial, está infligiendo a los pueblos de Europa. Todo lo que sabe es que su padre -recién nombrado comandante de un campo de concentración- ha ascendido en el escalafón, y que ha pasado de vivir en una confortable casa de Berlín a una zona aislada. Todo cambia cuando conoce a Shamuel, un niño judío que vive una extraña existencia paralela al otro lado de la alambrada.', trailer_url = 'https://www.youtube.com/watch?v=uwysOfnX2Qg' WHERE id_api = 'tt0914798';

UPDATE Contenido SET id_tmdb = 1418, descripcion = 'Leonard y Sheldon son dos físicos superdotados que comparten piso. Ambos son capaces de calcular las probabilidades de existencia de vida en otros planetas, pero son incapaces de relacionarse con los demás y especialmente con las chicas. Penny, su nueva vecina, es el polo opuesto a ellos, por lo que su llegada al edificio alterará la tranquila vida sentimental de Leonard y el desorden obsesivo-compulsivo de Sheldon.', trailer_url = 'https://www.youtube.com/watch?v=I5mUUOZT6b4' WHERE id_api = 'tt0898266';

', 19, '2016-01-14');

UPDATE Contenido SET id_tmdb = 14359, descripcion = 'En 1964, en la parroquia de San Nicolás, en el Bronx, un apasionado y carismático sacerdote, el padre Flynn (Philip Seymour Hoffman) está tratando de cambiar las rígidas normas del colegio, que durante años han sido celosamente salvaguardadas por la hermana Aloysius Beauvier (Meryl Streep), una estricta directora que cree firmemente en el poder de la disciplina. Vientos de cambio político están barriendo la comunidad, y de hecho el colegio ha aceptado a su primer alumno negro, Donald Miller. Pero cuando la hermana James (Amy Adams), inocentemente, le cuenta a la hermana Aloysius sus sospechas de que el padre Flynn presta demasiada atención a Donald, la superiora, sin contar con una sola prueba, comienza una cruzada personal para sacar a la luz la verdad y expulsar a Flynn del colegio por abusar del alumno. Esta batalla amenaza con desgarrar la comunidad de manera irreversible. Basada en una obra ganadora del Premio Pulitzter y de un Premio Toni en su adaptación teatral.', trailer_url = 'https://www.youtube.com/watch?v=f8S0ANEp4vc' WHERE id_api = 'tt0918927';

UPDATE Contenido SET id_tmdb = 1215, descripcion = 'Hank Moody (Duchovny) es un afamado novelista de Nueva York que ha perdido la inspiración tras el éxito de su último libro. Mientras lucha por retomar su carrera, Moody decide mudarse a Los Angeles, donde se reencontrará con Karen (Natascha McElhone), su ex novia, que ahora mantiene una nueva relación, y Becca (Madeleine Martin), la hija adolescente de ambos, una jovencita de doce años bastante poco convencional. Junto a la inseparable compañía de su mejor amigo y también agente, Hank Moody iniciará una nueva vida entregado a los placeres del sexo y coqueteando con las drogas y el alcohol, en una espiral un tanto desenfrenada que él pretende hacer compatible con la educación de su hija y los permanentes intentos de reconquistar a Karen.', trailer_url = 'https://www.youtube.com/watch?v=gQ7yaQhXJAI' WHERE id_api = 'tt0904208';

