UPDATE Contenido SET id_tmdb = 38363, descripcion = 'Narra la historia real de Valerie Plame, una agente de la CIA cuya identidad fue desvelada por miembros de la Casa Blanca, supuestamente para desacreditar a su marido, que en el año 2003 había escrito un polémico artículo en el New York Times. En dicho artículo, el marido de Plame acusaba a la administración Bush de haber manipulado a la Agencia Central de Inteligencia con respecto a la existencia de armas de destrucción masiva por parte del régimen de Sadam Hussein, para poder así justificar la invasión de Irak.', trailer_url = 'https://www.youtube.com/watch?v=MpMGQgXbOgA' WHERE id_api = 'tt0977855';

UPDATE Contenido SET id_tmdb = 24238, descripcion = 'Narra la larga amistad por correspondencia entre un cuarentón judío y obeso de Nueva York, y una niña australiana de 8 años que vive en los suburbios de Melbourne.', trailer_url = 'https://www.youtube.com/watch?v=kGATShQbydk' WHERE id_api = 'tt0978762';

UPDATE Contenido SET id_tmdb = 17578, descripcion = 'Tintín, un joven periodista dotado de una curiosidad insaciable, y su leal perro Milú descubren que la maqueta de un barco contiene un enigmático y secular secreto que deben investigar. A partir de ese momento, Tintín se verá acosado por Ivan Ivanovitch Sakharine, un diabólico villano que cree que el joven ha robado un valioso tesoro vinculado a un cruel pirata llamado Rackham el Rojo. Pero, con la ayuda de Milú, del cascarrabias capitán Haddock y de los torpes detectives Hernández y Fernández, viajará por medio mundo, sirviéndose de su proverbial astucia para burlar a sus perseguidores y encontrar antes que ellos El Unicornio, un navío hundido que puede proporcionar la clave de una fabulosa fortuna y de una antigua maldición.', trailer_url = 'https://www.youtube.com/watch?v=LTnCE_SaU38' WHERE id_api = 'tt0983193';

UPDATE Contenido SET id_tmdb = 23629, descripcion = 'Ambientada en los años 50. Una chica es internada por su padrastro en una institución psiquiátrica para que le practiquen una lobotomía. Mientras espera, su imaginación crea una realidad alternativa que podría salvarla de su dramática situación. A partir de ahí, la joven comienza a preparar su fuga, cuyo éxito depende del robo de cinco objetos.', trailer_url = 'https://www.youtube.com/watch?v=0jEYRg-bnqA' WHERE id_api = 'tt0978764';

UPDATE Contenido SET id_tmdb = 10140, descripcion = 'Tercera entrega de la saga literaria creada por C.S. Lewis. En esta ocasión, los hermanos Edmund y Lucy Pevensie y su primo Eustace embarcan en la nave "El Viajero del Alba" para buscar a los siete caballeros que han sido expulsados del reino por Miraz, el usurpador del trono de Narnia.', trailer_url = 'https://www.youtube.com/watch?v=LuGUVkO0cRM' WHERE id_api = 'tt0980970';

UPDATE Contenido SET id_tmdb = 38142, descripcion = 'Takaki y Akari son dos compañeros de clase en la escuela primaria. Durante su tiempo juntos se volvieron amigos cercanos. Su relación es puesta a prueba cuando Akari se muda a otra ciudad debido al trabajo de sus padres. Ambos sufren dificultades para mantener su amistad viva, mientras el tiempo y la distancia lentamente los separa. Cuando Takaki se entera que se muda a un lugar más lejano, decide visitar a Akari por última vez.', trailer_url = 'https://www.youtube.com/watch?v=M3Io2hVVNwQ' WHERE id_api = 'tt0983213';

UPDATE Contenido SET id_tmdb = 12182, descripcion = 'Nick O''Leary (Michael Cera), que frecuenta los locales de música "indie" de Nueva York con su grupo, acaba de romper con su novia, y ahora apenas es poco más que un joven sensible que toca el bajo y que tiene el corazón roto. Una noche, una chica le pedirá que finja ser su novio durante cinco minutos para esquivar a una antigua pareja. Así conocerá a Norah Silverberg (Kat Dennings), con quien no parece tener nada en común, salvo su gusto por el mismo tipo de música. Juntos se embarcarán en una noche llena de aventuras...', trailer_url = 'https://www.youtube.com/watch?v=0yYcfsYZaWU' WHERE id_api = 'tt0981227';

UPDATE Contenido SET id_tmdb = 539537, descripcion = 'El enigmático Sr. Roarke hace realidad los sueños de los afortunados huéspedes que acuden a su lujoso y remoto resort tropical. Sin embargo, sus fantasías se convertirán en pesadillas, y los invitados deberán resolver el misterio que oculta la isla para poder escapar con vida. Adaptación en clave de terror del famoso programa de televisión de los años 70 ambientado en un resort ubicado en una isla mágica.', trailer_url = 'https://www.youtube.com/watch?v=R6gYEuYhudc' WHERE id_api = 'tt0983946';

UPDATE Contenido SET id_tmdb = 1621, descripcion = 'La Primera Guerra Mundial (1914-1918) ha terminado y Wall Street está a punto de explotar. Es una época de cambios: las mujeres obtienen el derecho al voto, la radio llega a los hogares y los jóvenes gobiernan el mundo. Atlantic City (Nueva Jersey) es un espectacular lugar de vacaciones en el que sólo se respetan las reglas impuestas por Enoch "Nucky" Thompson (Steve Buscemi). Basada en hechos reales, se inspira en la obra homónima de Nelson Johnson.', trailer_url = 'https://www.youtube.com/watch?v=7t2kaj7LY5U' WHERE id_api = 'tt0979432';

