UPDATE Contenido SET id_tmdb = 23631, descripcion = 'Adaptación en forma de largometraje del falso tráiler incluido en Grindhouse. Machete es un ex federal mexicano con habilidades que están más que a la altura de su actitud mortífera. Dado por muerto después de un enfrentamiento con el célebre rey de la droga mexicano Torres, Machete huye a Texas para desaparecer y olvidar su trágico pasado. Pero lo que encuentra es una red de corrupción y engaño que termina con una bala en el cuerpo de un senador y con Machete como uno de los hombres más buscados. Machete se dispone a limpiar su nombre y descubrir la oscura e intricada conspiración, pero en su camino se interpone Booth, un implacable hombre de negocios con una interminable nómina de asesinos a sueldo. Para ayudar a equilibrar la balanza, Machete cuenta con Luz, una sexy vendedora ambulante de tacos con espíritu rebelde y corazón revolucionario, y con Padre, un cura que es bueno con las bendiciones pero mucho mejor con las armas.', trailer_url = 'https://www.youtube.com/watch?v=6UBU1r7VigA' WHERE id_api = 'tt0985694';

UPDATE Contenido SET id_tmdb = 2253, descripcion = 'Cruise interpreta al coronel alemán Claus von Stauffenberg, un aristocrático oficial alemán que lideró el heroico intento de derrocar al régimen nazi y acabar con la guerra colocando una bomba en el bunker de Hitler en 1944. Gravemente herido en combate, el Coronel Claus von Stauffenberg vuelve de África para unirse a la resistencia alemana y ayuda a organizar la Operación Valkiria, el complejo plan para que un gobierno en la sombra reemplazara al de Hitler una vez que éste hubiera muerto. Pero el destino y las circunstancias conspiran para proyectar a Stauffenberg de uno de los muchos implicados en el complot a un papel central de doble filo. No sólo debe liderar el golpe y tomar el control del gobierno de su país... también debe matar al propio Hitler.', trailer_url = 'https://www.youtube.com/watch?v=9eQ49r4d0E0' WHERE id_api = 'tt0985699';

UPDATE Contenido SET id_tmdb = 7508, descripcion = 'Ishaan Awashi es un niño de 8 años cuyo mundo está plagado de maravillas que nadie más parece apreciar: colores, peces, perros y cometas, que simplemente no son importantes en la vida de los adultos, que parecen más interesados en cosas como los deberes, las notas o la limpieza. E Ishaan parece no poder hacer nada bien en clase. Cuando los problemas que ocasiona superan a sus padres, es internado en un colegio para que le disciplinen. Las cosas no mejoran en el nuevo colegio, donde Ishaan tiene además que aceptar estar lejos de sus padres. Hasta que un día, el nuevo profesor de arte, Ram Shankar Nikumbh, entra en escena y se interesa por el pequeño Ishaan.', trailer_url = 'https://www.youtube.com/watch?v=tn_2Ie_jtX8' WHERE id_api = 'tt0986264';

UPDATE Contenido SET id_tmdb = 10360, descripcion = 'Hunger describe la vida en la Maze Prison, una cárcel de máxima seguridad de Irlanda del norte, a través de los emotivos acontecimientos que tuvieron lugar en 1981 con motivo de la huelga de hambre del IRA, liderada por Bobby Sands. Desde un punto de vista épico, la película narra lo que ocurre cuando se obliga al cuerpo y a la mente a actuar por encima del límite. Aclamada ópera prima del director y guionista Steve McQueen. Premio Cámara de Oro de Un Certain Regard en Cannes.', trailer_url = 'https://www.youtube.com/watch?v=K9IiUbBV4zc' WHERE id_api = 'tt0986233';

UPDATE Contenido SET id_tmdb = 19959, descripcion = 'Ambientada en un mundo futurista donde los humanos viven aislados en interacción con robots, un policía (Willis) se verá forzado a abandonar su hogar por primera vez en años para una investigación. Todo comienza cuando dos agentes del FBI (Willis y Radha Mitchell) son asignados para investigar el misterioso asesinato de un estudiante universitario relacionado con el hombre que participó en la creación del fenómeno high-tech de los sustitutos, que permiten a la gente comprar versiones perfectas de sí mismos -en buena forma, guapos, y controlados por control remoto-. Estas máquinas perfectas acaban asumiendo sus roles vitales, de modo que la gente puede experimentar la vida a través de otro cómodamente sentados en el sofá de su casa. El asesinato pone de manifiesto una cuestión: en un mundo de máscaras ¿quién es real y en quién se puede confiar?', trailer_url = 'https://www.youtube.com/watch?v=We3EQLWmmk4' WHERE id_api = 'tt0986263';

