UPDATE Contenido SET id_tmdb = 40805, descripcion = 'De noche, Britt Reid (Seth Rogen), heredero del gran imperio periodístico creado por su padre (Tom Wilkinson), se convierte en un héroe enmascarado que se propone combatir el crimen: es The Green Hornet. Su compañero de aventuras es Jato (Jay Chou), un experto en artes marciales.', trailer_url = 'https://www.youtube.com/watch?v=PMA-taGtfXs' WHERE id_api = 'tt0990407';

UPDATE Contenido SET id_tmdb = 50456, descripcion = 'Hanna tiene 16 años. Es brillante, curiosa y una devota hija. Excepcionalmente, tiene la fuerza y la energía de un soldado; esto se debe a que fue criada por su padre viudo, Erik, un ex hombre de la CIA, en las salvajes tierras del norte de Finlandia. Erik ha enseñado a Hanna a cazar, le ha entrenado con un duro programa de autodefensa y le ha enseñado a leer y escribir con tan solo una enciclopedia y un libro de cuentos de hadas. Hanna ha vivido una vida muy diferente a la de cualquier otra adolescente; toda su educación y entrenamiento se reduce a un objetivo, convertirla en la perfecta asesina. Pero en el mundo real hay una cuenta pendiente con la familia de Hanna, y con una mezcla de orgullo paternal y temor Erik se da cuenta de que ya no puede retener más a su hija. Este momento crucial cambia bruscamente la adolescencia de Hanna y se embarca en la misión para que estaba destinada.', trailer_url = 'https://www.youtube.com/watch?v=jod1UKasuyM' WHERE id_api = 'tt0993842';

UPDATE Contenido SET id_tmdb = 106646, descripcion = 'Película basada en hechos reales del corredor de bolsa neoyorquino Jordan Belfort. A mediados de los años 80, Belfort era un joven honrado que perseguía el sueño americano, pero pronto en la agencia de valores aprendió que lo más importante no era hacer ganar a sus clientes, sino ser ambicioso y ganar una buena comisión. Su enorme éxito y fortuna le valió el mote de "El lobo de Wall Street". Dinero. Poder. Mujeres. Drogas. Las tentaciones abundaban y el temor a la ley era irrelevante. Jordan y su manada de lobos consideraban que la discreción era una cualidad anticuada; nunca se conformaban con lo que tenían.', trailer_url = 'https://www.youtube.com/watch?v=DEMZSa0esCU' WHERE id_api = 'tt0993846';

UPDATE Contenido SET id_tmdb = 12797, descripcion = 'Bertram Pincus (Ricky Gervais), un dentista antipático, muere durante unos instantes durante una intervención médica rutinaria. A partir de ese momento adquiere el don de ver personas muertas que le piden ayuda para ponerse en contacto con los vivos.', trailer_url = 'https://www.youtube.com/watch?v=hWbCr7-oS9I' WHERE id_api = 'tt0995039';

UPDATE Contenido SET id_tmdb = 43549, descripcion = 'Remake de "El experimento", dirigida en 2001 por Oliver Hirschbiegel. Un grupo de 26 hombres son sometidos a una investigación psiquiátrica con roles de prisionero y guardián, pero el estudio finalmente no se desarrollará como pensaban y acabará en el caos.', trailer_url = 'https://www.youtube.com/watch?v=zIVd_pwqYZY' WHERE id_api = 'tt0997152';

UPDATE Contenido SET id_tmdb = 31724, descripcion = 'El 10 de agosto de 2010 a.t.b, el Sacro Imperio de Britannia sobrepasó a las fuerzas japonesas y conquistó el país en menos de un mes, haciendo uso de sus armas robóticas, los Knightmare Frames. Japón perdió su libertad y derechos, y pasó a ser llamada "Area 11 (eleven)". Sus habitantes, ahora llamados "Elevens" fueron obligados a sobrevivir en ghettos. Sin embargo aún persisten grupos que se resisten y luchan contra el Imperio por la independencia de Japón. Después de que su padre, el Emperador de Britannia, no hiciese nada para atrapar a los terroristas que asesinaron a su madre y lisiaron a su hermana, un niño llamado Lelouch juró destruir Britannia. Siete años más tarde en el Área 11 conoce a una misteriosa chica, con la que realiza un contrato a cambio de un poder llamado "Geass". Con él, Lelouch finalmente tiene el poder que necesita para derrotar a Britannia y realizar sus dos deseos: vengar a su madre y construir un mundo en el que su amada hermana pueda vivir feliz.', trailer_url = 'https://www.youtube.com/watch?v=so4b3W5R2Bs' WHERE id_api = 'tt0994314';

