UPDATE Contenido SET id_tmdb = 635910, descripcion = 'Basado en un solo capítulo, el Captain''s Log, de la clásica novela Drácula de 1897 de Bram Stoker, la historia se desarrolla a bordo de la goleta rusa Demeter, que fue fletada para transportar carga privada (veinticuatro cajas de madera sin marcar) desde Carpatia a Londres. La película detallará los extraños eventos que acontecieron a la tripulación condenada mientras intentan sobrevivir al viaje por el océano, acechados cada noche por una aterradora presencia a bordo del barco. Cuando finalmente llegó cerca del puerto de Whitby, estaba totalmente en ruinas. No había rastro de la tripulación.', trailer_url = 'https://www.youtube.com/watch?v=Xq3x3Ntc74w' WHERE id_api = 'tt1001520';

UPDATE Contenido SET id_tmdb = 38055, descripcion = 'Megamind es el supervillano más brillante que el mundo haya conocido. Y el que menos éxito tiene. Durante años, ha estado intentando conquistar Metro City por todos los medios posibles. Cada intento constituye un fracaso, por culpa de Metro Man, un héroe invencible hasta que Megamind consigue matarlo. De repente, la vida de Megamind carece de sentido. ¿Qué puede hacer un supervillano sin un superhéroe con el que enfrentarse?. Crear a Titán, un nuevo héroe más fuerte que Metro Man. Pero Titán empieza a pensar que es mucho más divertido ser malo que ser bueno. Además, Titán no se propone conquistar el mundo, sino destruirlo. ¿Podrá derrotar Megamind a su diabólica criatura?', trailer_url = 'https://www.youtube.com/watch?v=kPVbYBYN--I' WHERE id_api = 'tt1001526';

