UPDATE Contenido SET id_tmdb = 602269, descripcion = 'Joe ''Deke'' Deacon, ayudante de sheriff del condado de Kern, es enviado a Los Angeles para lo que debería ser un caso rápido de recopilación de evidencias. Sin embargo, se ve involucrado en la búsqueda de un asesino en serie que aterroriza a la ciudad. Encabezando la investigación se encuentra el sargento del departamento del sheriff de Los Angeles, Jim Baxter, quien, impresionado por el instinto policial de Deke, le ayuda de manera extraoficial. Pero mientras siguen la pista al asesino, Baxter desconoce que la investigación desentierra partes del pasado de Deke que sacan a la luz secretos más peligrosos que el propio caso.', trailer_url = 'https://www.youtube.com/watch?v=GovsRD2NA0M' WHERE id_api = 'tt10016180';

UPDATE Contenido SET id_tmdb = 599975, descripcion = 'Una enfermera descarga una app que informa al usuario de cuándo morirá. La app le comunica a la joven que fallecerá en tres días y, a partir de ese momento, empieza una carrera frenética por sobrevivir a lo que parece inevitable.', trailer_url = 'https://www.youtube.com/watch?v=k_-0DMlJisI' WHERE id_api = 'tt10039344';

