UPDATE Contenido SET id_tmdb = 625568, descripcion = 'Tom es un hombre cuya vida ha dejado de tener sentido. En pleno colapso mental se cruza en la carretera con Rachel, una joven que llega tarde a trabajar y que, nerviosa, recrimina a Tom con el claxon que no mueva su coche en un semáforo. A partir de entonces dará comienzo un peligroso juego del gato y el ratón en el que el torbellino de esta ira en la carretera traspasará cualquier límite que Rachel jamás haya imaginado.  Salvaje toma como testigo la adrenalina y el pánico de otras películas con psicópatas al volante como El diablo sobre ruedas, Nunca juegues con extraños o Death Proof.', trailer_url = 'https://www.youtube.com/watch?v=eZ-N73KFAy8' WHERE id_api = 'tt10059518';

