UPDATE Contenido SET id_tmdb = 10139, descripcion = 'Harvey Milk fue el primer político abiertamente homosexual elegido para ocupar un cargo público en Estados Unidos y asesinado un año después. A los cuarenta años, cansado de huir de sí mismo, Milk decide salir del armario e irse a vivir a California con Scott Smith. Una vez allí, abre un negocio que no tarda en convertirse en el punto de encuentro de los homosexuales del barrio. Milk se convierte en su portavoz y, para defender sus derechos, no duda en enfrentarse con empresarios, sindicatos y políticos. Su valentía anima a otros a seguir sus pasos. Sin embargo, en su vida privada, mantiene una relación sentimental destructiva con Jack Lira, un joven inestable que se aferra a él para sobrevivir.', trailer_url = 'https://www.youtube.com/watch?v=3uI5o8THOzg' WHERE id_api = 'tt1013753';

UPDATE Contenido SET id_tmdb = 12155, descripcion = 'Alicia, una joven de 19 años, asiste a una fiesta en una mansión victoriana, donde descubre que está a punto de recibir una propuesta de matrimonio frente a un montón de gente estirada de la alta sociedad. Alicia entonces se escapa, corriendo tras un conejo blanco, entra a un agujero tras él... y acaba en el país de las Maravillas, un lugar que visitó hace 10 años, pero el cual no recuerda. El país de las Maravillas era un reino pacífico hasta que la Reina Roja derrocó a su hermana, la Reina Blanca. Las criaturas del país de las maravillas, listos para la revuelta, esperan que Alicia les ayude, y éstas a su vez le ayudarán a recordar su primera visita al mágico reino.', trailer_url = 'https://www.youtube.com/watch?v=mUHSNPfNkIs' WHERE id_api = 'tt1014759';

