UPDATE Contenido SET id_tmdb = 88329, descripcion = 'Después del Lapso en Nueva York, el exvengador Clint Burton (alias Ojo de Halcón) debe cumplir una misión aparentemente sencilla: volver con su familia por Navidad. Pero una amenaza del pasado le obligará a aliarse a regañadientes con Kate Bishop, una hábil arquera de 22 años (y su mayor admiradora), para destapar una conspiración criminal.', trailer_url = 'https://www.youtube.com/watch?v=JTEMQlEI2g0' WHERE id_api = 'tt10160804';

