UPDATE Contenido SET id_tmdb = 791177, descripcion = 'Cuenta la historia del primer amor entre Maren, una joven que está aprendiendo a sobrevivir al margen de la sociedad, y Lee, un vagabundo con ideas muy intensas que vive marginado. Cuando se conocen, se unen en un viaje de mil millas que les lleva por carreteras, pasajes ocultos y caminos alternos en los Estados Unidos de Ronald Reagan. Pero a pesar de sus esfuerzos, todos los caminos conducen a sus aterradores pasados y a una última parada que determinará si su amor puede sobrevivir a su forma de ser.', trailer_url = 'https://www.youtube.com/watch?v=GN2WV5QpuRY' WHERE id_api = 'tt10168670';

