UPDATE Contenido SET id_tmdb = 13510, descripcion = 'Una pareja, Steve y Jenny, se escapa de fin de semana romántico. Sin embargo, su tranquilidad se verá interrumpida cuando una banda de chicos jóvenes aparezca por el lugar. Estos, como acto de rebeldía, robarán las cosas a la pareja y destrozarán su coche. Steve les hará frente pero sufrirá un violento ataque. A partir de ese momento, Jenny tratará de escapar a través del bosque...', trailer_url = 'https://www.youtube.com/watch?v=rJkO9HBXuhc' WHERE id_api = 'tt1020530';

UPDATE Contenido SET id_tmdb = 23759, descripcion = 'Bretaña, año 117 de nuestra era. Un grupo de soldados romanos lucha por salvar sus vidas después de que la legión se vea mermada tras un ataque de la guerrilla local. Los valientes soldados componían nada menos que la 9ª legión, la más legendaria por su dureza, pero las cosas no salieron como planeaban. Ahora tan sólo quedan unos cuantos supervivientes, liderados por Quintus Dias (Michael Fassbender) y su misión es resistir hasta conseguir llegar a la frontera, antes que las hordas guerreras de la fiera y vengativa Etain (Olga Kurylenko) acabe con todos ellos.', trailer_url = 'https://www.youtube.com/watch?v=zxgqJttU3iM' WHERE id_api = 'tt1020558';

UPDATE Contenido SET id_tmdb = 19913, descripcion = 'Tom aún sigue creyendo, incluso en este cínico mundo moderno, en la noción de un amor transformador, predestinado por el cosmos y que golpea como un rayo sólo una vez. Summer no cree lo mismo, para nada. La mecha se enciende desde el primer día, cuando Tom, un arquitecto en ciernes convertido en un sensiblero escritor de tarjetas de felicitación, se encuentra con Summer, la bella y fresca nueva secretaria de su jefe. Aunque aparentemente está fuera de su alcance, Tom pronto descubre que tienen un montón de cosas en común. La historia de Tom y Summer cubre desde el enamoramiento, las citas y el sexo hasta la separación, las recriminaciones y la redención, todo lo cual se suma al caleidoscópico retrato del por qué y el cómo seguimos esforzándonos de modo tan risible y rastrero para encontrar sentido al amor… y esperar convertirlo en realidad.', trailer_url = 'https://www.youtube.com/watch?v=PEdNyYpFprw' WHERE id_api = 'tt1022603';

UPDATE Contenido SET id_tmdb = 8456, descripcion = 'En un intento por encajar en la nueva ciudad, Jack Tyler (Sean Faris) acepta la invitación de su compañera Baja (Amber Heard) para acudir a una fiesta, en la que acaba inmerso en una dura pelea. Después de ser vencido y humillado por Ryan McDonald (Cam Gigandet), un compañero le habla de un deporte conocido como Mixed Martial Arts (MMA) y le presenta a su mentor, Jean Roque (Djimon Hounsou) que lo acoge bajo su tutela. Con Jean aprenderá a ser disciplinado y paciente, claves que quizá le servirán para llegar a lo más alto y definirse a sí mismo.', trailer_url = 'https://www.youtube.com/watch?v=7X8O-OBJY4g' WHERE id_api = 'tt1023111';

UPDATE Contenido SET id_tmdb = 49009, descripcion = 'Adaptación de ''The Long k: The True Story of a Trek to Freedom'' de Slavomir Rawicz. El protagonista narra en primera persona cómo, tras la invasión de Polonia por los alemanes (1939), fue arrestado por el ejército soviético y encarcelado en Siberia; cómo, después, consiguió escapar del gulag (campos de concentración de la Unión Soviética) en compañía de otros presos y, finalmente, cómo huyendo a pie llegaron desde Siberia al Himalaya, al desierto del Gobi y, atravesando el Tibet, acabaron estableciéndose en la India. Recientemente, varios historiadores han puesto en duda la veracidad de esta historia.', trailer_url = 'https://www.youtube.com/watch?v=MsXr25Gv56o' WHERE id_api = 'tt1023114';

UPDATE Contenido SET id_tmdb = 8328, descripcion = 'Cuando Andie, una temperamental bailarina, ingresa en la Maryland School of the Arts, no le resulta fácil integrarse en el grupo sin perder su personalidad. Así que decide unirse a Chase, el bailarin con más carácter de la escuela, para formar un grupo de alumnos marginados que participarán en una competición de baile alternativo de Baltimore.', trailer_url = 'https://www.youtube.com/watch?v=PwDhMUAdlFQ' WHERE id_api = 'tt1023481';

UPDATE Contenido SET id_tmdb = 92749, descripcion = 'Steven Grant, un amable empleado de una tienda de regalos, sufre pérdidas de memoria y experimenta recuerdos de otra vida. Steven descubre que tiene un trastorno de identidad disociativo y que comparte cuerpo con el mercenario Marc Spector. A medida que los enemigos de Steven/Marc van convergiendo, debe lidiar con la complejidad de sus identidades mientras se sumerge en un misterio letal que habita entre los poderosos dioses de Egipto.', trailer_url = 'https://www.youtube.com/watch?v=C9Z75wfjxCU' WHERE id_api = 'tt10234724';

UPDATE Contenido SET id_tmdb = 68734, descripcion = 'Irán, año 1979. Cuando la embajada de los Estados Unidos en Teherán es ocupada por seguidores del Ayatolá Jomeini para pedir la extradición del Sha de Persia, la CIA y el gobierno canadiense organizaron una operación para rescatar a seis diplomáticos estadounidenses que se habían refugiado en la casa del embajador de Canadá. Con este fin se recurrió a un experto en rescatar rehenes y se preparó el escenario para el rodaje de una película de ciencia-ficción, de título "Argo", en la que participaba un equipo de cazatalentos de Hollywood. La misión: ir a Teherán y hacer pasar a los diplomáticos por un equipo de filmación canadiense para traerlos de vuelta a casa.', trailer_url = 'https://www.youtube.com/watch?v=Ou2JnNCys10' WHERE id_api = 'tt1024648';

UPDATE Contenido SET id_tmdb = 88803, descripcion = 'Cuando Thors, un gran guerrero viking muere asesinado en batalla a manos de Askeladd, un mercenario, su hijo, Thorfinn, jura vengarse. Para ello tendrá que demostrar su valía antes de ganarse el derecho a retar a un duelo al asesino de su padre.', trailer_url = 'https://www.youtube.com/watch?v=H3fS-bZ4e2E' WHERE id_api = 'tt10233448';

Thorfinn conoce allí a un joven, Einar, que también era un esclavo como él. El encuentro de Einar llevó a Thorfinn a enfrentarse a los pecados que había cometido y comenzó a encontrar sentido a la vida.

Por otro lado, Canuto, quien se convirtió en Rey de Inglaterra, intentó extender su territorio para el establecimiento de ''la tierra prometida''.

Esta es ''La historia de un verdadero guerrero (Saga)''.

''La historia de Expiación y Salvación (Saga)'' que se encuentra más allá del prólogo.');

UPDATE Contenido SET id_tmdb = 13971, descripcion = 'Poppy Moore, una consentida pija americana de 16 años, es enviada por su padre a un estricto colegio británico para que aprenda disciplina. Allí, la joven se encuentra en un mundo desconocido, de toque de queda y severas guardianas. Bajo la vigilante mirada de la directora y rodeada de nuevas amigas, Poppy deberá reconocer que sus malos modales no llegarán muy lejos en este nuevo ambiente. Aún así, hará todo lo posible por intentar quebrantar las normas del centro.', trailer_url = 'https://www.youtube.com/watch?v=BgIMeJXiPho' WHERE id_api = 'tt1024255';

