UPDATE Contenido SET id_tmdb = 602223, descripcion = 'Para los miembros de un movimiento clandestino, ya no es suficiente una noche anual de anarquía y asesinatos, así que deciden devolver a Estados Unidos el caos y las masacres sin fin, donde nadie volverá a estar a salvo... jamás. Adela (Ana de la Reguera) y su esposo Juan (Tenoch Huerta) viven en Texas, donde él trabaja como peón en un rancho para la adinerada familia Tucker. En la mañana después de la tradicional purga, una banda de asesinos enmascarados ataca violenta e ilegalmente a la familia Tucker, Tras este hecho, la familia texana se ve obligada a unirse con Juan y su esposa para enfrentar un país entero a punto de colapsar, que se hunde en un mar de caos y de sangre. Quinta y última entrega de la saga ''The Purge''.', trailer_url = 'https://www.youtube.com/watch?v=f3XbMyXuEGE' WHERE id_api = 'tt10327252';

