UPDATE Contenido SET id_tmdb = 65057, descripcion = 'Matt King, casado y padre de dos niñas, se ve obligado a replantearse la vida cuando su mujer sufre un terrible accidente que la deja en coma. Intenta torpemente recomponer la relación con sus problemáticas hijas -la precoz Scottie, de 10 años, y la rebelde Alexandra, de 17- al tiempo que se enfrenta a la difícil decisión de vender las propiedades de la familia. Herederos de la realeza hawaiana y de los misioneros, los King poseen en Hawai tierras vírgenes de un valor incalculable.', trailer_url = 'https://www.youtube.com/watch?v=87EwqWSmB7Q' WHERE id_api = 'tt1033575';

UPDATE Contenido SET id_tmdb = 18501, descripcion = 'En el futuro, juego y entretenimiento han evolucionado hacia un híbrido terrorífico: humanos controlan a otros humanos en juegos multi-player online a gran escala. La tecnología para el control de la mente se ha extendido completamente, y en el centro de la controversia está su creador, el multimillonario Ken Castle. Su última invención, Slayers, permite a millones de personas hacer realidad sus más salvajes fantasías online frente a una audiencia global.', trailer_url = 'https://www.youtube.com/watch?v=1MxMp0FDZh8' WHERE id_api = 'tt1034032';

UPDATE Contenido SET id_tmdb = 9029, descripcion = 'Al juerguista Jack Fuller le acaba de despedir de la empresa su propio padre. Por otro lado a la atractiva Joy McNally, su novio le ha dejado plantada. Ambos deciden irse a Las Vegas, y allí se conocen en una equivocación de habitaciones de su hotel. Tras irse de fiesta, a la mañana siguiente se despiertan... y descubren que se han casado tras una noche de locura y descontrol. Justo en su primera discusión, Jack gana un jackpot de 3 millones de dólares en una máquina del casino jugando con una moneda de Joy. Ambos intentarán quedarse con el dinero, aunque el amor quizá aparezca en el camino...', trailer_url = 'https://www.youtube.com/watch?v=UqXBQaKrvPg' WHERE id_api = 'tt1033643';

UPDATE Contenido SET id_tmdb = 602734, descripcion = 'El detective descarado Ezekiel "Zeke" Banks, y su compañero novato, se hacen cargo de una espeluznante investigación sobre varios asesinatos espantosos. Zeke, involuntariamente, se vera atrapado en el  morboso juego del asesino.', trailer_url = 'https://www.youtube.com/watch?v=aOtuYfbqKws' WHERE id_api = 'tt10342730';

UPDATE Contenido SET id_tmdb = 10679, descripcion = 'Cuando las tropas de Hitler estaban a punto de ser vencidas, un programa secreto logró escapar al espacio, refugiándose en la Luna y generando allí una base oculta, que fue preparándose para, de nuevo, intentar conquistar y dominar el mundo. Y ahora es el momento. Han construido toda una flota de platillos volantes con la intención de restaurar el Tercer Reich (ahora el Cuarto), pero ahora a escala más global.  Pero todo el plan se descubrirá antes de tiempo, cuando un astronauta aterrice y se percate de lo que está ocurriendo. Aterrado frente a lo que pueda ocurrirle, se hará pasar por un actor de Hollywood. De todas formas, será el detonante de que los representantes de los nazis viajen a la Tierra para imponer su voluntad. Saben que necesitan la tecnología terrícola para desarrollarse, y su misión será intentar presionar al pueblo norteamericano para que se pliegue a sus intereses. ¿Conseguirán los pérfidos nazis su misión?', trailer_url = 'https://www.youtube.com/watch?v=11-GztyTi9A' WHERE id_api = 'tt1034314';

UPDATE Contenido SET id_tmdb = 13813, descripcion = 'Segunda Guerra Mundial. Corre el año 1941 y los judíos de Europa Oriental están siendo masacrados a millares. En la Bielorrusia ocupada, tres hermanos logran escapar de una muerte segura y se refugian en los densos bosques de alrededor de su casa, que conocen desde su infancia. Allí inician su desesperada lucha contra los nazis. Su lucha se convertirá en algo mucho más importante, una forma de vengar las muertes de sus seres queridos al salvar a miles de personas.', trailer_url = 'https://www.youtube.com/watch?v=7APcuF5nNfQ' WHERE id_api = 'tt1034303';

UPDATE Contenido SET id_tmdb = 13389, descripcion = 'Después de treinta años trabajando juntos, los detectives Turk (Robert De Niro) y Rooster (Al Pacino) están a punto de jubilarse, pero antes les encargan la investigación del asesinato de un conocido proxeneta que estuvo implicado en un caso resuelto por ellos. En el cuerpo de la víctima se ha encontrado un poema de cuatro líneas que pretende justificar el asesinato. Todo parece indicar que se enfrentan a un asesino en serie, cuyo objetivo es eliminar a los criminales que han conseguido burlar la ley.', trailer_url = 'https://www.youtube.com/watch?v=1kRShW-XMRs' WHERE id_api = 'tt1034331';

UPDATE Contenido SET id_tmdb = 49494, descripcion = 'Siglo II d.C. Adaptación de una novela juvenil de Rosemary Sutcliff (1954). Un legionario romano (Channing Tatum) y su esclavo celta Esca (Jamie Bell) emprenden la búsqueda de la Legión Novena, que desapareció veinte años antes en alguna parte del norte de Escocia y a cuyo frente se encontraba un general que resulta ser el padre del legionario en cuestión.', trailer_url = 'https://www.youtube.com/watch?v=SItBFjaLArU' WHERE id_api = 'tt1034389';

UPDATE Contenido SET id_tmdb = 361292, descripcion = 'Susie Bannion (Dakota Johnson) es una joven estadounidense que viaja a Berlín para cursar sus estudios de danza en una de las escuelas más prestigiosas del mundo, dirigida por Madame Blanc (Tilda Swinton). El mismo día en el que ingresa en la escuela, una de las alumnas recientemente expulsada es asesinada. No se trata de un hecho aislado, lo que hace sospechar a la brillante estudiante sobre la implicación de la escuela en los homicidios. Su desconfianza aumenta cuando una compañera le cuenta que antes de que Pat muriera, ésta le confesó que conocía un terrorífico secreto. Remake del clásico giallo dirigido por Dario Argento en 1977, ''Suspiria''.', trailer_url = 'https://www.youtube.com/watch?v=knEhAxNU84E' WHERE id_api = 'tt1034415';

