UPDATE Contenido SET id_tmdb = 604079, descripcion = 'En un futuro distópico, cien adolescentes participan en una brutal competición conocida como "La larga marcha", donde deben caminar sin descanso: si se detienen o reducen la velocidad de la marcha, mueren. Solo uno sobrevivirá. Adaptación cinematográfica de la novela de Stephen King.', trailer_url = 'https://www.youtube.com/watch?v=sw48gC8810I' WHERE id_api = 'tt10374610';

UPDATE Contenido SET id_tmdb = 667216, descripcion = 'Mientras se hospedan en un resort aislado en una isla, James y Em disfrutan de unas vacaciones perfectas en playas vírgenes, un personal excepcional y tomando el sol. Pero guiados por la seductora y misteriosa Gabi, se aventuran fuera de los terrenos del resort y se encuentran en una cultura llena de violencia, hedonismo y horror indescriptible.', trailer_url = 'https://www.youtube.com/watch?v=W5mfHz-5dx8' WHERE id_api = 'tt10365998';

UPDATE Contenido SET id_tmdb = 637920, descripcion = 'Un hombre con discapacidad intelectual es injustamente encarcelado por la muerte de una niña, y debe demostrar su inocencia para poder estar de nuevo con su hija.', trailer_url = 'https://www.youtube.com/watch?v=W2CKOn6UPh8' WHERE id_api = 'tt10431500';

UPDATE Contenido SET id_tmdb = 8329, descripcion = 'Cada noche, Ángela, una joven reportera de una televisión local, sigue con su cámara a un grupo profesional distinto. Esta noche le toca entrevistar a los bomberos y tiene la secreta esperanza de poder asistir en directo a un impactante incendio. Pero la noche transcurre tranquilamente. Y cuando, por fin, reciben la llamada de una anciana que se ha quedado encerrada en su casa, no le queda otro remedio que seguirlos durante la misión de rescate. En el edificio donde vive la anciana, los vecinos están muy asustados. La mujer, encerrada en su piso, lanza unos gritos desgarradores. Los bomberos derriban la puerta y, seguidos por Ángela y el cámara, encuentran a la anciana semiinconsciente, rodeada por decenas de gatos. De pronto, la mujer se lanza sobre un bombero y le muerde salvajemente. Es sólo el comienzo de una larga pesadilla y de un dramático reportaje único.', trailer_url = 'https://www.youtube.com/watch?v=ib5ZSj6ST0U' WHERE id_api = 'tt1038988';

UPDATE Contenido SET id_tmdb = 20504, descripcion = 'En un futuro apocalíptico, 30 años después del "resplandor" que aniquiló la casi totalidad de la sociedad civilizada, unos pocos humanos sobreviven en un ambiente increíblemente hostil y árido. Violaciones, canibalismo y salvajismo imperan en unas derruidas ciudades donde el más fuerte y el que posee el agua impone su ley. Vagando por la carretera, un guerrero solitario (Denzel Washington) se dirige al oeste con una sola misión: proteger un misterioso libro que lleva en su mochila.', trailer_url = 'https://www.youtube.com/watch?v=yAQcwKY0Dik' WHERE id_api = 'tt1037705';

UPDATE Contenido SET id_tmdb = 22894, descripcion = 'Dios ha perdido la fe en el ser humano, así que ha decidido enviar a su legión de ángeles a la Tierra para exterminar a la raza humana por segunda vez en la Historia. La única esperanza para salvar a la humanidad recae sobre un grupo de rebeldes escondidos en mitad del desierto, que recibirán la ayuda del mismísimo arcángel Miguel.', trailer_url = 'https://www.youtube.com/watch?v=P6p01-in6-k' WHERE id_api = 'tt1038686';

UPDATE Contenido SET id_tmdb = 27573, descripcion = 'Milo Boyd es un cazarrecompensas que está pasando por una mala racha y le asignan el encargo de sus sueños: capturar a su exmujer, la periodista Nicole Hurley, quien ha violado su libertad condicional. Milo piensa que será dinero fácil y espera que se trate de un encargo divertido. Pero cuando Nicole se escapa para seguirle la pista a un asesinato encubierto, Milo se da cuenta de que, entre ellos dos, las cosas nunca son tan sencillas. Siempre tratan de ir un paso por delante uno del otro, hasta que de repente, sus vidas empiezan a correr peligro y tienen que salir huyendo. Si pensaban que la promesa de amarse, honrarse, y respetarse era difícil, mantenerse con vida será mucho más complicado.', trailer_url = 'https://www.youtube.com/watch?v=t1EcJJ6XzBc' WHERE id_api = 'tt1038919';

UPDATE Contenido SET id_tmdb = 663712, descripcion = 'Después de ser resucitado por una entidad siniestra, Art the Clown regresa al condado de Miles, donde debe cazar y destruir a una adolescente y a su hermano menor en la noche de Halloween.', trailer_url = 'https://www.youtube.com/watch?v=nhKS2Q9aK8Q' WHERE id_api = 'tt10403420';

UPDATE Contenido SET id_tmdb = 18240, descripcion = 'Margaret es una poderosa y estricta editora de gran éxito de Nueva York que, por un problema con su visado, de repente se enfrenta a ser deportada a Canadá, su país de origen. Para evitarlo y poder mantener su visa en Estados Unidos, la astuta ejecutiva declara que está comprometida con su joven asistente Andrew, al que lleva torturando durante años. Andrew acepta participar en la farsa, pero con algunas condiciones. La "pareja" se dirige entonces a Alaska a conocer la peculiar familia de él, y la ejecutiva de ciudad, acostumbrada a tener todo bajo control, se encuentra inmersa en situaciones surrealistas que escapan a cualquier lógica conocida. Con planes de boda en camino y un agente de inmigración tras sus pasos, Margaret y Andrew se comprometen a seguir con el plan previsto pese a las consecuencias.', trailer_url = 'https://www.youtube.com/watch?v=rCs8skCWF98' WHERE id_api = 'tt1041829';

UPDATE Contenido SET id_tmdb = 775996, descripcion = 'Un piloto de drones se une a un oficial androide para localizar un dispositivo que amenaza con acabar con la vida sobre el planeta. El dispositivo en cuestión se encuentra oculto en una zona altamente militarizada.', trailer_url = 'https://www.youtube.com/watch?v=dZfDLbbpvZs' WHERE id_api = 'tt10451914';

UPDATE Contenido SET id_tmdb = 188207, descripcion = 'La película nos sitúa en la antigua Grecia, en concreto en el año 1200 a.C. Allí, una reina sucumbe a la lujuria de Zeus y tiene un hijo con él. El niño se supone que es el encargado de acabar con el reino tirano del rey y restablecer el orden.  Sin embargo, el príncipe, al que ponen de nombre Hércules (Kellan Lutz, Crepúsculo), no sabe quién es en realidad y solamente desea una cosa: el amor de la princesa de Creta, que se acaba de prometer con su hermano. Pero, cuando se entera de cuál es su destino, debe tomar una difícil decisión. Hércules debe elegir entre huir con su amada o convertirse en el héroe que se supone que debe ser. Su aventura le llevará a conocer lugares y seres tan peligrosos como extraños. Además,  se enfrentará a la envidia de los mortales y a la ira de los dioses.', trailer_url = 'https://www.youtube.com/watch?v=g0GMzQwO2l0' WHERE id_api = 'tt1043726';

UPDATE Contenido SET id_tmdb = 82693, descripcion = 'Tras pasar ocho meses en una institución mental por agredir al amante de su mujer, Pat vuelve con lo puesto a vivir en casa de sus padres. Determinado a tener una actitud positiva y recuperar a su ex-mujer, el mundo de Pat se pone del revés cuando conoce a Tiffany, una chica con ciertos problemas y no muy buena fama en el barrio. A pesar de su mutua desconfianza inicial, entre ellos pronto se desarrollará un vínculo muy especial que les ayudará a encontrar en sus vidas el lado bueno de las cosas.', trailer_url = 'https://www.youtube.com/watch?v=X61g-9ArR7o' WHERE id_api = 'tt1045658';

