UPDATE Contenido SET id_tmdb = 8952, descripcion = 'La historia se centra en Steven Russell, un modélico y convencional padre de familia que tras sufrir un accidente de tráfico decide dejar atrás la farsa que estaba viviendo: es gay y además lo sabe desde niño. Así, Steven comienza una nueva y disipada vida, viéndose obligado a cometer una serie de fraudes para poder costearse sus gastos. Sus acciones lo conducirán a la cárcel, donde se enamora de su compañero de celda, Phillip Morris, con quien inicia una relación. Sin embargo, el sistema penitenciario separará a la pareja, y Russell perpetrará varios intentos de fuga para reunirse de nuevo con su amado.', trailer_url = 'https://www.youtube.com/watch?v=01dljIcgiMw' WHERE id_api = 'tt1045772';

UPDATE Contenido SET id_tmdb = 13596, descripcion = 'Tank (Dane Cook) es un joven especialista en seducir y, sobre todo, en ofender a las mujeres. Y por eso le contratan: los ex novios le pagan para que salga con sus ex chicas y haga que pasen un rato horrible. Después, tras esa cita espantosa, ellas suelen volver encantadas. Todo va bien hasta que el mejor amigo de Tank, Dustin (Jason Biggs), contrata sus servicios para recuperar a su ex, Alexis (Kate Hudson). Pero la presunta horrible cita no lo es tanto y Tank se enamora de Alexis.', trailer_url = 'https://www.youtube.com/watch?v=PsIt1K1C2c4' WHERE id_api = 'tt1046163';

