UPDATE Contenido SET id_tmdb = 14869, descripcion = 'G. I. Joe es el nombre en clave de una fuerza especial altamente entrenada cuya misión fundamental es defender la libertad humana y la paz mundial. Los valerosos Joes son hombres y mujeres de coraje, dueños de una mezcla dinámica de talentos especiales, personalidad e ingenuidad. Dotados de algunas de las armas más sofisticadas que puedan concebirse, estos individuos constituyen la fuerza más formidable de combate del mundo.', trailer_url = 'https://www.youtube.com/watch?v=ccqWxASe9ig' WHERE id_api = 'tt1046173';

