UPDATE Contenido SET id_tmdb = 257445, descripcion = 'El adolescente Zach Cooper se muda sin muchas ganas con su familia desde Nueva York al pequeño pueblo de Greendale. Allí encuentra un resquicio de ilusión cuando conoce a su vecina, la guapa Hannah, y hace un amigo: Champ. También se entera de que el padre de Hannah es RL Stine, autor del Bestseller de la serie "Pesadillas". Pero Zach descubre que Stine tiene un secreto: las criaturas de sus historias son reales, y las mantiene encerradas en sus libros. Así que cuando en un descuido todos los demonios de Stine son liberados involuntariamente de sus libros, Zach, Hannah, Champ y el propio Stine, en una alocada noche llena de aventuras, tendrán que formar equipo y atrapar a todas las criaturas de la imaginación de Stine para devolverlos a los libros donde pertenecen, con el fin de salvar la ciudad.', trailer_url = 'https://www.youtube.com/watch?v=oDSYH5VRmAA' WHERE id_api = 'tt1051904';

UPDATE Contenido SET id_tmdb = 64122, descripcion = 'Todo comienza cuando Ellcrys, un místico árbol élfico enferma y su muerte está cada día más cerca. Este árbol ha sido la única pieza mágica que ha protegido siempre las Cuatro Tierras del mundo maquiavélico de los demonios. Amberle Elessedil es la única que puede salvarlo. Para ello, tendrá que desbloquear la magia de los elfos que lleva miles de años sin utilizarse. Con la ayuda de Wil Ohmsford, viajará por cada rincón para buscar la magia perdida y curar al árbol Ellcrys.', trailer_url = 'https://www.youtube.com/watch?v=VkNTBzyNrCA' WHERE id_api = 'tt1051220';

