UPDATE Contenido SET id_tmdb = 31867, descripcion = 'Los hombres han ampliado y mejorado su esperanza de vida gracias a unos órganos mecánicos muy sofisticados y caros fabricados por la empresa The Union.  Pero este gran avance tecnológico tiene un lado oscuro: si alguien no puede pagar la factura. The Union manda a sus especialistas, los Repo Men, para que recuperen el órgano en cuestión, sin preocuparse del dolor o de la supervivencia del cliente.  Jude Law es Remy, uno de los mejores Repo Men de la empresa. Durante su horario laboral sufre un infarto, pero se despierta con el mejor corazón mecánico del mercado… y de paso, con una deuda sustancial.  Curiosamente, un efecto secundario del trasplante es que ha dejado de interesarle su trabajo. Cuando no puede hacer frente a los pagos, The Union manda a Jake (Forest Whitaker), el durísimo ex compañero de Remy, a por él. El cazador se ha convertido en presa.', trailer_url = 'https://www.youtube.com/watch?v=jl9Nvg4yuus' WHERE id_api = 'tt1053424';

