UPDATE Contenido SET id_tmdb = 695721, descripcion = 'Ambientada en un Panem postapocalíptico, nos traslada varias décadas antes del comienzo de las aventuras de Katniss Everdeen. El joven Coriolanus Snow será el mentor de Lucy Gray Baird, la chica elegida para ser homenajeada del empobrecido Distrito 12. La joven sorprenderá a todos cantando en la ceremonia de apertura de los Décimos Juegos del Hambre en los que Snow intentará aprovecharse de su talento y encanto para sobrevivir.', trailer_url = 'https://www.youtube.com/watch?v=mKlSMLPzn7Q' WHERE id_api = 'tt10545296';

UPDATE Contenido SET id_tmdb = 8054, descripcion = 'Historia de un circo ambulante dirigido por el doctor Parnassus, en el que los trabajadores dan a la audiencia mucho más de lo que podrían esperarse.  Con una extraordinaria habilidad para guiar la imaginación de los demás, el Doctor Parnassus oculta un oscuro secreto. Siglos atrás hizo un trato con el Diablo para ganar inmortalidad, a cambio de entregarle a cualquier hijo que tuviese al cumplir los 16 años. Ahora, deambulando con su humilde teatro ambulante y con una hija a punto de llegar a esa edad, Parnassus está decidido a cambiar el trato. Tras el fallecimiento de Heath Ledger (1979 - 22 enero 2008) durante el rodaje, tres actores finalizaron su trabajo, representando el mismo personaje a través de diferentes realidades: Johnny Depp, Jude Law y Colin Farrell.', trailer_url = 'https://www.youtube.com/watch?v=M1EQYBpKPoI' WHERE id_api = 'tt1054606';

UPDATE Contenido SET id_tmdb = 1100988, descripcion = 'Años transcurridos tras los sucesos de "28 semanas después", el virus de la ira ha regresado y un grupo de supervivientes debe sobrevivir en un mundo asolado por hordas de infectados. Realizada con un iPhone 15 Pro Max y con la ayuda de numerosos accesorios especializados.', trailer_url = 'https://www.youtube.com/watch?v=d-4F7jJUoOE' WHERE id_api = 'tt10548174';

