UPDATE Contenido SET id_tmdb = 38408, descripcion = '“Como la vida misma” es una comedia romántica Holly Berenson (Katherine Heigl) es una organizadora de servicios de banquetes para fiestas y Eric Messer (Josh Duhamel) es el director de una cadena de deportes.Tras su primera cita desastrosa, lo único que tienen en común es su antipatía del uno por el otro y su amor por su ahijada, Sophie.Holly y Messer se ven forzados a dejar de lado las diferencias entre ellos mientras viven bajo el mismo techo.Sin embargo la vida los pondrá a prueba, cuando luego de un terrible accidente se convierten en lo único que Sophie tiene en su vida. Holly y Eric se ven obligados a dejar sus diferencias a un lado y sortear ambiciones y calendarios sociales para encontrar la armonía del nuevo hogar que están destinados a formar.', trailer_url = 'https://www.youtube.com/watch?v=qGdZ3K-Yl9c' WHERE id_api = 'tt1055292';

UPDATE Contenido SET id_tmdb = 8373, descripcion = 'Dos años después de derrotar a los Decepticons, las vidas de Sam y los Autobots han cambiado mucho. Mientras Sam se prepara para ir a la universidad, sus amigos robots se han integrado en una fuerza de élite que captura a enemigos renegados. Pero todo cambia con la llegada de un malvado enemigo que, con un enrevesado plan, planea un nuevo alzamiento de los Decepticons. La humanidad vuelve a estar en peligro, y Sam y los Autobots tendrán que formar una vez más equipo para salvarla.', trailer_url = 'https://www.youtube.com/watch?v=ePRrWxFDcXI' WHERE id_api = 'tt1055369';

UPDATE Contenido SET id_tmdb = 22954, descripcion = 'Película basada en el libro de John Carlin "El factor humano" (Playing the enemy: Nelson Mandela and the Game That Changed the World) y ambientada después de que Nelson Mandela saliera de la cárcel y se convirtiera en presidente de Sudáfrica. Poco después, en 1995, el país celebró el campeonato del mundo de rugby, tras años de ser excluidos de las competiciones debido al apartheid. Evento que Mandela (Morgan Freeman) impulsó y utilizó, con la ayuda de la estrella de rugby Francois Pienaar, como vía para acabar con el odio y la desconfianza existente durante décadas entre la población blanca y negra del país.', trailer_url = 'https://www.youtube.com/watch?v=z4cq9kZPxF0' WHERE id_api = 'tt1057500';

