UPDATE Contenido SET id_tmdb = 23082, descripcion = 'En un mundo donde no existe la mentira, ni siquiera como concepto, donde todos dicen siempre la verdad sin pensar en las consecuencias, Mark Bellison, un perdedor nato, desarrolla inesperadamente la capacidad de mentir y pronto se da cuenta de que la falta de sinceridad tiene grandes ventajas. En ese tipo de sociedad, Mark no tiene problemas para prosperar y hacer fortuna, mediante la invención de historias que todo el mundo cree a pies juntillas.', trailer_url = 'https://www.youtube.com/watch?v=uAKxTieGehk' WHERE id_api = 'tt1058017';

UPDATE Contenido SET id_tmdb = 13027, descripcion = 'Dos desconocidos se encuentran por culpa de una misteriosa llamada de teléfono de una mujer a la que no conocen. Amenazando sus vidas y a sus familias, consigue que Rachel y Jerry se metan en situaciones cada vez más peligrosas, utilizando la tecnología de la vida cotidiana para seguir todos y cada uno de sus movimientos. A medida que las cosas se complican, estas dos personas normales y corrientes se convierten en los fugitivos más buscados de USA, y tienen que colaborar para averiguar qué está pasando en realidad. Luchando por sus vidas, se convierten en marionetas de un enemigo sin rostro que, al parecer, cuenta con ilimitados poderes para manipular todo lo que hacen.', trailer_url = 'https://www.youtube.com/watch?v=lCDA46ELBKs' WHERE id_api = 'tt1059786';

