UPDATE Contenido SET id_tmdb = 616037, descripcion = 'El Dios del Trueno emprende un viaje que no se parece en nada a lo que se ha enfrentado hasta ahora: una búsqueda de la paz interior. Pero el retiro de Thor se ve interrumpido por un asesino galáctico conocido como Gorr el Carnicero de Dioses. Para hacer frente a la amenaza, Thor solicita la ayuda de Valkiria, de Korg y de su ex novia Jane Foster que, para sorpresa de Thor, empuña su martillo mágico, Mjolnir, como la Poderosa Thor. Juntos, se embarcan en una aventura cósmica en la que tendrán que descubrir el misterio de la venganza del Carnicero de Dioses y detenerlo antes de que sea demasiado tarde.', trailer_url = 'https://www.youtube.com/watch?v=9jrffoywRUU' WHERE id_api = 'tt10648342';

UPDATE Contenido SET id_tmdb = 124834, descripcion = 'Dos adolescentes británicos, Nick Nelson y Charlie Spring, estudian en una escuela primaria exclusiva para varones. Charlie, un pensador demasiado nervioso y abiertamente gay, y Nick, un jugador de rugby alegre y de buen corazón, un día se sientan juntos en clase. La amistad florece rápidamente, pero ¿podría haber algo más...? Basada en la novela gráfica de Alice Oseman.', trailer_url = 'https://www.youtube.com/watch?v=xwqVwvCeHeg' WHERE id_api = 'tt10638036';

UPDATE Contenido SET id_tmdb = 615643, descripcion = 'En la década de 1980, durante la presidencia de Reagan, una familia de emigrantes surcoreanos en EE.UU. decide instalarse en Arkansas, tras abandonar California. Trabajan sexando pollos, pero el sueño del padre es instalarse como granjero y cultivar verduras para mercado coreano estadounidense. La madre, sin embargo, preferiría vivir en un ciudad, cerca de un hospital, pues el hijo menor, David, está enfermo del corazón.', trailer_url = 'https://www.youtube.com/watch?v=5GzLZ4ifwoY' WHERE id_api = 'tt10633456';

UPDATE Contenido SET id_tmdb = 7735, descripcion = 'En otoño de 1967 Ron Jones, un profesor de historia de un instituto de Palo Alto en California, no tuvo respuesta para la pregunta de uno de sus alumnos: ¿Cómo es posible que el pueblo alemán alegue ignorancia respecto a la masacre del pueblo judío? En ese momento Jones decidió hacer un experimento con sus alumnos: implantó un régimen de extrema disciplina militar en el aula, restringiéndoles las libertades. Ante el asombro del profesor, los alumnos se entusiamaron hasta tal punto que a los pocos días empezaron a espiarse unos a otros y a acosar a los que no querían unirse al grupo. Al quinto día Ron Jones se vio obligado a acabar con el experimento antes de que las cosas llegaran demasiado lejos. El director alemán Dennis Gansel (Napola) ha trasladado esta experiencia a nuestros días y a su tierra natal: Alemania. Esta vez es el profesor quien hace la pregunta a sus alumnos: ¿Creéis que es imposible que otra dictadura vuelva a implantarse en Alemania? Y comienza el experimento…', trailer_url = 'https://www.youtube.com/watch?v=xawYuNn9V58' WHERE id_api = 'tt1063669';

