UPDATE Contenido SET id_tmdb = 85350, descripcion = 'Es la historia de Mason desde los seis años y durante una década poblada de cambios: mudanzas y controversias, relaciones que se tambalean, bodas, diferentes colegios, primeros amores, también desilusiones, momentos maravillosos, de miedo y de una constante mezcla de desgarro y sorpresa. Un viaje íntimo y épico por la euforia de la niñez, los sísmicos cambios de una familia moderna y el paso del tiempo.', trailer_url = 'https://www.youtube.com/watch?v=khIt84A9zUk' WHERE id_api = 'tt1065073';

