UPDATE Contenido SET id_tmdb = 55787, descripcion = 'En la época de la Gran Depresión, un joven estudiante de veterinaria se ve obligado a dejar sus estudios tras la muerte de sus padres. Empieza entonces a trabajar para el circo de los hermanos Benzini como veterinario y encargado de los animales. El joven se enamora de Marlena, una amazona que está casada con August, el dueño del circo, un hombre tan carismático como retorcido... Adaptación del aclamado best-seller homónimo de Sara Gruen', trailer_url = 'https://www.youtube.com/watch?v=ZFetJtvf1gw' WHERE id_api = 'tt1067583';

