UPDATE Contenido SET id_tmdb = 619730, descripcion = 'Alice y Jack tienen la suerte de vivir en Victoria, la ciudad experimental de la compañía que alberga a los hombres que trabajan para el Proyecto Victoria, de alto secreto, y a sus familias. La vida es perfecta, con todas las necesidades de los residentes cubiertas por la empresa. Todo lo que piden a cambio es un compromiso incondicional con la causa de Victoria. Pero cuando empiezan a aparecer grietas en su idílica vida, exponiendo destellos de algo mucho más siniestro que se esconde bajo la atractiva fachada, Alice no puede evitar cuestionarse qué están haciendo en Victoria y por qué. ¿Cuánto está dispuesta a perder Alice para sacar a la luz lo que realmente ocurre en el paraíso?', trailer_url = 'https://www.youtube.com/watch?v=kMwLgSTNxb8' WHERE id_api = 'tt10731256';

UPDATE Contenido SET id_tmdb = 34480, descripcion = 'Confundida y en estado de shock Sarah Carter emerge de la cueva de la montaña Apalache donde se encontró con algo indescriptible. Incapaz de explicar lo que pasó a las autoridades - o por qué está cubierta de sangre de una de sus amigas - Sara es obligada a volver al sistema subterraneo para ayudar a localizar a sus cinco amigas desaparecidas. Mientras que el equipo de rescate baja a las profundidades de la cueva las visiones de lo que pasó anteriormente allí atormentan a Sarah y comienza a darse cuenta del horror y peligro de la misión. Llevado por la sospecha y la desconfianza del grupo y confrontada de nuevo a las criaturas (Crawlers), Sarah tiene que sacar de su interior toda su fuerza y corage en una lucha desesperada por la liberación y la redención.', trailer_url = 'https://www.youtube.com/watch?v=KXf1BCYtcgI' WHERE id_api = 'tt1073105';

UPDATE Contenido SET id_tmdb = 37724, descripcion = 'En Skyfall, la lealtad de James Bond hacia M será puesta a prueba cuando el pasado de M vuelve para atormentarla. Su vida se verá en peligro, de modo que el agente 007 deberá localizar y eliminar la amenaza, sin importar el precio personal que tendrá que pagar. Tras el fracaso de la última y fatídica misión de Bond y revelarse la identidad de varios agentes secretos en distintos puntos del planeta, la sede del MI6 es atacada, obligando a M a trasladar su agencia. Debido a estos sucesos, su autoridad y posición se verán amenazados por Mallory, el nuevo Presidente del Comité de Inteligencia y Seguridad. Ahora, el MI6 se enfrenta a amenazas tanto externas como internas por lo que M decide acudir al único aliado en quien puede confiar: Bond. El agente 007 desaparece en las sombras con una única aliada: la agente de campo Eve. Juntos le seguirán la pista al misterioso Silva.', trailer_url = 'https://www.youtube.com/watch?v=sgNh7UrbMDY' WHERE id_api = 'tt1074638';

UPDATE Contenido SET id_tmdb = 7278, descripcion = 'Parodia de la exitosa película "300". El heroico Leónidas, sin más armas que la ropa interior de cuero y una capa, lidera un grupo de 13 espartanos en defensa de su patria contra los invasores persas (cuyas filas incluyen a Ghost Rider, Rocky Balboa, los Transformers y a una jorobada Paris Hilton).', trailer_url = 'https://www.youtube.com/watch?v=RY-zJtYYolo' WHERE id_api = 'tt1073498';

UPDATE Contenido SET id_tmdb = 13836, descripcion = 'Remake de "La montaña embrujada"(1975). Durante años han circulado extrañas historias sobre Witch Mountain, un lugar situado en el desierto de Nevada, donde se han producido fenomenos inexplicables. Un taxista de Las Vegas (Dwayne Johnson), que debe llevar a este lugar a dos jóvenes (Anna Sophia Robb, Alexander Ludwig) con poderes sobrenaturales, se verá envuelto en una misteriosa aventura. Al parecer, la unica forma de salvar el mundo radica en descubrir los secretos de Witch Mountain. En el asunto se verán involucrados el Gobierno, la mafia y diversos seres extraterrestres.', trailer_url = 'https://www.youtube.com/watch?v=WKRodkEmbwM' WHERE id_api = 'tt1075417';

UPDATE Contenido SET id_tmdb = 911645, descripcion = 'Alisha Khanna, 30, ambitious, now finds herself at crossroads in life. Her six year long relationship has grown monotonous, her career seems to be going nowhere. But just when she had begun to accept this reality as unchangeable, her life is usurped by the arrival of her cousin, Tia and her fiancé, Zain, with whom she bonds over a troubled past and a common wish to break from its confines.', trailer_url = NULL WHERE id_api = 'tt10733228';

UPDATE Contenido SET id_tmdb = 734265, descripcion = 'Natalie Bauer, una escritora que vive en Los Ángeles, se enamora de Josh Lin por una aplicación de citas y decide viajar a Nueva York para sorprenderlo en Navidad. Sin embargo, al llegar descubre que la han engañado y Josh no es quien decía ser: es un ''nerd'' que ha usado las atractivas fotos de un tal Tag Abbott como cebo. Cuando Natalie descubre que el chico guapo de quien se enamoró, Tag, vive también en Nueva York, Josh se ofrece a prepararle una cita con él si ella finge ser su novia durante las vacaciones de Navidad.', trailer_url = 'https://www.youtube.com/watch?v=3boMRfx6cjE' WHERE id_api = 'tt10752004';

