UPDATE Contenido SET id_tmdb = 20533, descripcion = 'En el salvaje oeste, Jonah Hex (Josh Brolin) es conocido por una cicatriz en la parte derecha del rostro y por vestir un uniforme del ejército confederado. De niño fue vendido a los apaches por su padre y tuvo que hacerse a sí mismo en un mundo tan duro como el Oeste, sobreviviendo unas veces como pistolero y otras como cazador de recompensas. Su único contacto con el mundo es a través de la bella Lilah (Megan Fox).', trailer_url = 'https://www.youtube.com/watch?v=3Ppqbnhp7PI' WHERE id_api = 'tt1075747';

UPDATE Contenido SET id_tmdb = 62213, descripcion = 'En 1752, los Collins y su hijo Bárnabas zarpan de Liverpool con destino a América para librarse de la misteriosa maldición que pesa sobre su familia. Con el paso de los años, Bárnabas (Johnny Depp), un playboy impenitente, se convierte en un hombre rico y poderoso que comete el error de romperle el corazón a Angelique Bouchard (Eva Green). Ella, que es una bruja, lo condena a un destino peor que la muerte: lo convierte en vampiro y lo entierra vivo. Dos siglos después, en 1972, Bárnabas consigue salir de su tumba y se encuentra con un mundo irreconocible. Adaptación de la serie de televisión creada por Dan Curtis en 1966, que tuvo un remake en 1991.', trailer_url = 'https://www.youtube.com/watch?v=UHvaBSsXsCU' WHERE id_api = 'tt1077368';

UPDATE Contenido SET id_tmdb = 10024, descripcion = 'La vida de Sara (Cameron Diaz) y Brian Fitzgerald (Jason Patric) cambia radicalmente cuando a su hija Kate (Vassilieva), de sólo dos años, le diagnostican una leucemia. Inmediatamente, Sara abandona su carrera de abogado para dedicarse por entero al cuidado de su hija. Su única esperanza para salvarla es tener otro hijo. La ingeniería genética es un campo que plantea aún cuestiones morales muy espinosas, pero para los Fitzgerald es la única opción. Así es cómo nace Anne (Breslin), y entre ella y Kate se establece una relación mucho más profunda de lo normal, sobre todo porque ambas tendrán que someterse a diversos tratamientos médicos y compartirán largas estancias en el hospital.', trailer_url = 'https://www.youtube.com/watch?v=hO5KR5-VK9M' WHERE id_api = 'tt1078588';

UPDATE Contenido SET id_tmdb = 18360, descripcion = 'El vigilante jurado Larry Daley (Ben Stiller) se ve obligado a decir adiós a todos sus amigos cuando deciden hacer el Museo de Ciencias Naturales más "interactivo" y sustituyen todas las figuras por hologramas. Sus amigos históricos son empaquetados y enviados a los archivos del famoso Smithsonian, en Washington, DC., el museo más grande del mundo. No han pasado ni 24 horas cuando Larry recibe una llamada de Jedediah, el cowboy en miniatura, y descubre que la tabla de Ahkmenrah ha sido extraviada y esto ha hecho que el Smithsonian cobre vida. Para salvar a sus amigos, Larry tendrá que viajar a Washington, DC y luchar contra Kahmunrah, Al Capone, Iván el Terrible y Napoleón que han planeado un complot para apoderarse de la tabla. En medio del caos, Larry hará nuevos amigos, como Amelia Earhart o Albert Einstein que le ayudarán a detener el complot y salvar el museo.', trailer_url = 'https://www.youtube.com/watch?v=lPLY8O1y0qA' WHERE id_api = 'tt1078912';

