UPDATE Contenido SET id_tmdb = 37821, descripcion = 'Tras sufrir una repentina ruptura de la que intenta recuperarse, Jen Kornfeldt cree que nunca volverá a enamorarse. Sin embargo, cuando accede a regañadientes a acompañar a sus padres a un viaje a la Costa Azul francesa, Jen acaba conociendo al hombre de sus sueños: el atractivo Spencer Aimes. Tres años más tarde, su sueño aparentemente inalcanzable se ha hecho realidad: Spencer y ella son unos recién casados que llevan una vida idílica en un barrio residencial... al menos, hasta la mañana siguiente al cumpleaños de Spencer en la que empiezan a silbar las balas a su alrededor. Literalmente.Resulta que Spencer nunca se había molestado en contar a Jen que había sido un superespía internacional, y ahora el mundo perfecto de Jen se ha venido abajo.', trailer_url = 'https://www.youtube.com/watch?v=GHuZnE99Tgo' WHERE id_api = 'tt1103153';

