UPDATE Contenido SET id_tmdb = 637649, descripcion = 'H (Jason Statham) es el misterioso tipo que acaba de incorporarse como guardia de seguridad en una compañía de furgones blindados. Durante un intento de atraco a su camión, sorprende a sus compañeros mostrando habilidades propias de un soldado profesional, dejando al resto del equipo preguntándose quién es realmente y de dónde viene.', trailer_url = 'https://www.youtube.com/watch?v=CQgBahCGHUk' WHERE id_api = 'tt11083552';

UPDATE Contenido SET id_tmdb = 7482, descripcion = 'Un grupo de criminales y hackers se encargan de cometer robos y estafas a los millonarios o cargos poco transparentes para favorecer a los más necesitados.

El jefe del grupo es Nate Ford, un investigador de seguros con grandes ideales, siempre trata de defender a los más indefensos. Su forma de actuar le ha hecho convertirse en el investigador con el mayor récord de recuperación de artículos robados. Sin embargo, Nate sufre una desilusión y se siente traicionado por la compañía para la que trabaja cuando ésta le niega a pagar el seguro para ayudar a curar a su hijo enfermo. Furioso, Nate deja la compañía y decide convertirse en una especie de "justiciero", velando por los intereses de los más beneficiados.

En su grupo de "justicieros" se encuentra Parker, una experta ladrón; Alec, un hacker informático; Sophie, una estafadora capaz de interpretar cualquier papel con una maestría sorprendente;  y, Eliot Spencer, un especialista en deshacerse de matones y criminales de un plumazo.', trailer_url = 'https://www.youtube.com/watch?v=uqGZwVnyi0g' WHERE id_api = 'tt1103987';

