UPDATE Contenido SET id_tmdb = 116149, descripcion = 'Paddington es un oso que ha crecido en las profundidades de la selva peruana junto a su tía Lucy quien, debido a un encuentro casual con un explorador inglés, ha inculcado en su sobrino el sueño de vivir en Londres. Cuando un terremoto destruye su hogar, la tía Lucy decide ocultar a su joven sobrino en un barco rumbo a Inglaterra en busca de una vida mejor. Cuando el pequeño llega solo a la estación londinense de Paddington, se da cuenta de que la vida de la ciudad no tiene nada que ver con lo que se había imaginado, hasta que conoce a los Brown, una bondadosa familia británica que se lo encuentra con una etiqueta alrededor del cuello en la que se puede leer: ''Por favor, cuidad de este oso. Gracias''. Los Brown le acogen en su casa mientras Paddington busca al famoso explorador que dejó marcada a su tía Lucy muchos años atrás. Sin embargo, poco después, una siniestra y atractiva taxidermista se fija en él, lo que supone una amenaza para su hogar y para su propia vida.', trailer_url = 'https://www.youtube.com/watch?v=Bt4J4MVuHXE' WHERE id_api = 'tt1109624';

