UPDATE Contenido SET id_tmdb = 13012, descripcion = 'Un encantador hombre de familia con un prometedor futuro, Wade Porter de repente lo pierde todo cuando accidentalmente mata a un ladrón que se coló en su casa. Detenido por homicidio involuntario, Wade es condenado a pasar tres años en un centro penitenciario de máxima seguridad en el que las reglas de la sociedad no se aplican. Obligado a compartir celda con un infame asesino y sufriendo las brutales palizas orquestadas por el sádico jefe de los guardias de la prisión, Wade pronto se da cuenta de que su vida está en juego y de que si quiere sobrevivir tendrá que convertirse en el recluso más duro. Porque lo que no te mata te hace más fuerte. Y en una prisión estatal, sólo los más fuertes sobreviven.', trailer_url = 'https://www.youtube.com/watch?v=zq5uhFXNQhg' WHERE id_api = 'tt1117385';

