UPDATE Contenido SET id_tmdb = 316152, descripcion = 'Narra la historia real del granjero sureño New Knight y su extraordinaria revuelta armada contra el Ejército Confederado durante la Guerra de Secesión americana. Harto de luchar por los intereses de los más ricos, Knight desertó, se alió con otros pequeños granjeros y con la ayuda de los esclavos locales, lideró un levantamiento que llevó al Condado de Jones en Mississippi a independizarse creando el Estado Libre de Jones. Su matrimonio con una antigua esclava, Rachel, y su posterior construcción de una comunidad interracial, distinguieron a New Knight como una luchadora y controvertida figura en el contexto de la Guerra Civil americana.', trailer_url = 'https://www.youtube.com/watch?v=3EMkxEKKSQI' WHERE id_api = 'tt1124037';

UPDATE Contenido SET id_tmdb = 626735, descripcion = 'Un guardabosques del ejército y su perro se embarcan en un viaje por carretera a lo largo de la Pacific Coast Highway para asistir al funeral de un amigo.', trailer_url = 'https://www.youtube.com/watch?v=9LKj19zNcUI' WHERE id_api = 'tt11252248';

UPDATE Contenido SET id_tmdb = 12163, descripcion = 'Randy "The Ram" Robinson (Mickey Rourke) es un luchador profesional de wrestling que, tras haber sido una estrella en la década de los ochenta, trata de continuar su carrera en el circuito independiente, combatiendo en cuadriláteros de tercera categoría. Cuando se da cuenta de que los brutales golpes que ha recibido a lo largo de su carrera le empiezan a pasar factura, decide poner un poco de orden en su vida: intenta acercarse a Stephanie, la hija que abandonó (Evan Rachel Wood) y trata de superar la soledad con su amor por Cassidy, una streaper (Marisa Tomei).', trailer_url = 'https://www.youtube.com/watch?v=qjhGZhRJ3j0' WHERE id_api = 'tt1125849';

UPDATE Contenido SET id_tmdb = 87093, descripcion = '''Big Eyes'' está basada en el caso real de Margaret y Walter Keane. La historia gira alrededor del enorme éxito, durante los años 50 y 60 del siglo pasado, de las reproducciones de los cuadros de niños con grandes ojos, creados por ella pero firmados en su momento por su marido, Walter, supuestamente porque él tenía una gran facilidad para el marketing, consiguiendo así ampliar la popularidad de la obra de su esposa.', trailer_url = 'https://www.youtube.com/watch?v=fLR_L21aVxo' WHERE id_api = 'tt1126590';

