UPDATE Contenido SET id_tmdb = 889737, descripcion = 'Tras crear el caos, Arthur Fleck ha sido internado en Arkham a la espera de juicio por sus crímenes como Joker. Mientras lidia con su doble identidad, Arthur no sólo se topa con el amor verdadero, sino que también descubre la música que siempre ha estado dentro de él.', trailer_url = 'https://www.youtube.com/watch?v=QtZPjL_CbQI' WHERE id_api = 'tt11315808';

UPDATE Contenido SET id_tmdb = 19994, descripcion = 'Devil''s Kettle es una pequeña ciudad de los Estados Unidos, donde Jennifer y Needy son amigas desde la infancia y viven juntas. Un día, las chicas van a un bar donde toca un nuevo grupo de rock, y allí se produce un inesperado accidente. Tras provocarse un gran incendio, muchos de los asistentes no consiguen sobrevivir, pero las chicas logran escapar. A partir de entonces, Jennifer será poseída por unas fuerzas malévolas que la impulsarán a cometer asesinatos... principalmente a aquellos que intenten seducirla.', trailer_url = 'https://www.youtube.com/watch?v=BnBMoZ0-zZw' WHERE id_api = 'tt1131734';

UPDATE Contenido SET id_tmdb = 18947, descripcion = 'Inglaterra, años 60. Narra la historia de Radio Rock, una emisora pirata. En 1966, la BBC sólo emitía dos horas de rock and roll a la semana. Pero la Radio Rock, que inundaba el país de rock y pop 24 horas al día, consiguió una audiencia de 25 millones de personas, más de la mitad de la población. Cuando Carl es expulsado del colegio, su madre lo manda a pasar una temporada con su padrino Quentin, que es el jefe de esa emisora pirata que emite desde un barco en el mar del Norte. Entre los extravagantes pinchadiscos destaca "El Conde", un auténtico ídolo de las ondas. Lo secundan Dave, inteligente y sarcástico, Simon, un chico amable que busca el amor verdadero, el enigmático y apuesto Midnight Mark entre otros.', trailer_url = 'https://www.youtube.com/watch?v=hRh1-cyWfGQ' WHERE id_api = 'tt1131729';

