UPDATE Contenido SET id_tmdb = 16558, descripcion = 'Claire Stenwick, exagente de la CIA, y Ray Koval, exagente del MI6, han abandonado el mundo del espionaje para dedicarse a un negocio más lucrativo que los convierte en enemigos: su misión consiste en encontrar la fórmula de un producto que hará ganar una auténtica fortuna a la empresa que la consiga. Sus jefes son el titán de la industria Howard Tully y el desaprensivo consejero delegado Dick Garsik. A pesar de que las tácticas de Claire y Ray son cada vez más sucias, surge entre ellos una creciente atracción.', trailer_url = 'https://www.youtube.com/watch?v=y4qNHjEZjY0' WHERE id_api = 'tt1135487';

UPDATE Contenido SET id_tmdb = 14956, descripcion = '"Eliza Dushku" da vida a lo que en “Dollhouse” se conoce como un activo, una persona a la que han borrado la memoria y ahora es programada para asumir cualquier personalidad, una tarea que se realiza de forma clandestina en “La casa de muñecas”, una empresa al servicio de todo tipo de clientes que buscan seres humanos capaces de meterse en cualquier rol, ya sea el de amante, sicario, asesino, o negociador. Por supuesto, la existencia de esta compañía es secreta y todo va a ir bien, hasta que el personaje de "Echo" empiece a tener recuerdos y a mezclarlos.', trailer_url = 'https://www.youtube.com/watch?v=6cINErID_yk' WHERE id_api = 'tt1135300';

