UPDATE Contenido SET id_tmdb = 24803, descripcion = 'Julie Powell (Amy Adams), decidida a hacer algo creativo para olvidar su rutinario trabajo, se plantea como un reto elaborar las 524 recetas del libro "Dominando el arte de la cocina francesa", un clásico de la gastronomía publicado en 1961 por Julia Child (Meryl Streep). Durante ese año, escribe cada día sus experiencias en un blog que tendrá múltiples seguidores.', trailer_url = 'https://www.youtube.com/watch?v=0NYXKKGJT9U' WHERE id_api = 'tt1135503';

UPDATE Contenido SET id_tmdb = 649609, descripcion = 'En este moderno y monstruoso relato sobre el fiel ayudante de Drácula, Renfield se ve obligado a procurarle víctimas a su amo y hacer todo aquello que este le ordene, por inmoral que sea. Pero ahora, tras siglos de servidumbre, Renfield está listo para descubrir si hay vida lejos de la alargada sombra del Príncipe de las Tinieblas. ¿El problema? Que no sabe cómo romper esa relación de dependencia.', trailer_url = 'https://www.youtube.com/watch?v=8HnpIJ_KNi0' WHERE id_api = 'tt11358390';

UPDATE Contenido SET id_tmdb = 17654, descripcion = 'Tras la llegada de una enorme nave espacial extraterrestre a Johannesburgo (Sudáfrica), a los alienígenas recién llegados a la Tierra se les obligó a vivir en condiciones penosas como "refugiados", en una especie de campo de concentración construido en las afueras la ciudad. Todo empezó unos veinte años atrás, cuando los extraterrestres tomaron el primer contacto con nuestro planeta. Los humanos esperaban un ataque hostil, o un gran avance tecnológico de la raza alienígena. Pero nada de ello sucedió. Los propios extraterrestres eran refugiados de su propio mundo. Sin saber bien que hacer, se confinó a los alienígenas en un campo de refugiados, el "Distrito 9", hasta que las naciones del mundo decidieran qué hacer ante la nueva y extraña situación. Pero el tiempo pasó...', trailer_url = 'https://www.youtube.com/watch?v=Xlh4vQoS2jM' WHERE id_api = 'tt1136608';

UPDATE Contenido SET id_tmdb = 800158, descripcion = 'Después de un fatídico error, un asesino se enfrenta a sus jefes —y a sí mismo— en una persecución internacional de castigo, según él, no es nada personal.', trailer_url = 'https://www.youtube.com/watch?v=iVau-K3q8cM' WHERE id_api = 'tt1136617';

UPDATE Contenido SET id_tmdb = 395990, descripcion = 'Paul Kersey (Bruce Willis) es un famoso cirujano que vive con su familia en Nueva York. Un día, su esposa (Elisabeth Shue) y su hija (Camila Morrone) son brutalmente atacadas en su casa. Paul, que siempre había sido un tipo tranquilo, siente cómo la sed de venganza va apoderándose de él. Con la policía sobrecargada de crímenes, decide tomar la justicia por su mano e ir en busca de los agresores de su familia y de paso enfrentarse a todo tipo de criminales de la Gran Manzana. A medida que las víctimas acaparan la atención de los medios, la ciudad se pregunta si este vengador es un ángel guardián... o un simple justiciero.', trailer_url = 'https://www.youtube.com/watch?v=oESna-93l2A' WHERE id_api = 'tt1137450';

UPDATE Contenido SET id_tmdb = 11439, descripcion = 'Un escritor acepta a regañadientes el encargo de terminar las memorias del antiguo primer ministro británico Adam Lang, después de la muerte en un accidente de la persona que lo estaba haciendo. Para ello, se instala en una isla de la costa este de Estados Unidos. Al día siguiente de su llegada, un antiguo ministro acusa a Lang de autorizar la captura ilegal de presuntos terroristas y su entrega a la CIA, hechos que constituirían un crimen de guerra. El escándalo atrae a periodistas y manifestantes a la mansión de la isla donde se aloja Lang con su mujer y su ayudante personal. ', trailer_url = 'https://www.youtube.com/watch?v=WrvkY6rAgHU' WHERE id_api = 'tt1139328';

UPDATE Contenido SET id_tmdb = 653346, descripcion = 'Ambientada varias generaciones en el futuro tras el reinado de César, en la que los simios son la especie dominante que vive en armonía y los humanos se han visto reducidos a vivir en la sombra. Mientras un nuevo y tiránico líder simio construye su imperio, un joven simio emprende un angustioso viaje que le llevará a cuestionarse todo lo que sabe sobre el pasado y a tomar decisiones que definirán el futuro de simios y humanos por igual.', trailer_url = 'https://www.youtube.com/watch?v=bDc3fchg-vE' WHERE id_api = 'tt11389872';

UPDATE Contenido SET id_tmdb = 13788, descripcion = 'Historia de una joven de 19 años (Odette Yustman) que sufre los ataques de un dybbuk, una alma en pena de una persona muerta que ha sido expulsada del cielo. Este dybbuk en particular tendrá la forma de un joven que falleció en el campo de concentración de Auschwitz. Junto a su novio (Cam Gigandet) y un especialista en temas paranormales (Gary Oldman), todos se unirán para acabar con la maldición que tan malos momentos trae a la joven', trailer_url = 'https://www.youtube.com/watch?v=LNLg86r0UlY' WHERE id_api = 'tt1139668';

UPDATE Contenido SET id_tmdb = 13310, descripcion = 'Oskar, un niño tímido de 12 años, acosado en el colegio por unos compañeros, se hace amigo de Eli, una misteriosa nueva vecina de su edad, cuya llegada coincide con una serie de inexplicables muertes. A pesar de que Oskar piensa que ella es un vampiro, intenta que su amistad esté por encima de su miedo.', trailer_url = 'https://www.youtube.com/watch?v=CJ8AewMYzaY' WHERE id_api = 'tt1139797';

UPDATE Contenido SET id_tmdb = 974931, descripcion = 'Después de que su madre es asesinada en Halloween, una adolescente rebelde viaja en el tiempo a 1987, donde debe detener al joven aspirante a asesino y volver a la línea de tiempo que le corresponde antes de quedar atrapada en el pasado para siempre.', trailer_url = 'https://www.youtube.com/watch?v=51cEc1IlHlE' WHERE id_api = 'tt11426232';

UPDATE Contenido SET id_tmdb = 20943, descripcion = 'Abby Ritcher es una joven productora de un programa matutino de TV de Sacramento que tiene problemas para el amor. Su búsqueda de "el hombre perfecto" la ha dejado soltera y sin esperanzas, y está llegando a pensar que está incapacitada para el romance. A Abby le espera una buena cuando sus jefes deciden que forme equipo con Mike Chadway, un rudo personaje televisivo que promete desvelar la cruda realidad del por qué los hombres y las mujeres son como son. Sorprendentemente, Abby contará con la ayuda de su desagradable presentador, que la asesorará en sus citas haciéndola pasar por una serie de sonrojantes pruebas para demostrar sus teorías sobre las relaciones. Pero las tretas del hombre les conducirán a un resultado inesperado.', trailer_url = 'https://www.youtube.com/watch?v=08G5xB9q5Kg' WHERE id_api = 'tt1142988';

UPDATE Contenido SET id_tmdb = 126027, descripcion = 'Samantha y Jay se olvidan de la precaución cuando convierten su finca recién heredada en un alojamiento y desayuno. Llámalo planes extraviados. El lugar no solo se está desmoronando, sino que también está habitado por espíritus de residentes anteriores, a quienes solo Samantha puede ver y escuchar.', trailer_url = 'https://www.youtube.com/watch?v=fpOjQuFN4z4' WHERE id_api = 'tt11379026';

UPDATE Contenido SET id_tmdb = 19912, descripcion = 'Nick O’Bannon y unos amigos acuden a un circuito de carreras para presenciar una prueba del Nascar. Durante ésta tiene lugar un terrible accidente que conlleva desastrosas consecuencias para el estadio. Pero Nick descubre que se trata de sólo una visión de algo que está a punto de suceder, y junto con otras doce personas consigue salir del recinto y escapar de una tragedia segura. Pensando que han burlado a la muerte, el grupo continúa con su vida, pero desafortunadamente para Nick, Lori y sus amigos sólo es el principio, ya que la muerte no deja cabos sueltos, y regresará para llevarse a los supervivientes de una manera brutal.', trailer_url = 'https://www.youtube.com/watch?v=azQH42WEoTg' WHERE id_api = 'tt1144884';

UPDATE Contenido SET id_tmdb = 62214, descripcion = 'De la mente del director Tim Burton (''Alicia en el país de las maravillas'', ''La leyenda de Sleepy Hollow''), surge ''Frankenweenie'', la tierna historia de un chico y su mascota. Cuando el pequeño perro Sparky fallece, Víctor (su amo y amigo) trata de usar diversas técnicas científicas para intentar revivir al animal, y traerlo de vuelta al mundo de los vivos, todo ello mediante algunos ajustes corporales. Aunque el chico intenta que nadie vea a su "monstruo", el perro Sparky consigue escapar, los amigos del colegio del niño, sus profesores e incluso todos sus vecinos sabrán que construir una nueva vida puede llegar a ser algo terrible y escalofriante.', trailer_url = 'https://www.youtube.com/watch?v=2e1_XxakM-I' WHERE id_api = 'tt1142977';

UPDATE Contenido SET id_tmdb = 656663, descripcion = 'El equipo de Jackass ha vuelto para su cruzada final. Johnny Knoxville, Steve-O y el resto de la pandilla regresan para otra ronda de divertidas, salvajemente absurdas y a menudo, peligrosos retos.', trailer_url = 'https://www.youtube.com/watch?v=apSSJI2DFyo' WHERE id_api = 'tt11466222';

UPDATE Contenido SET id_tmdb = 21208, descripcion = 'Cuando Kate y John Coleman pierden al bebé que estaban esperando, todo se derrumba a su alrededor. Su matrimonio se tambalea y la mente de Kate se llena de pesadillas, miedos y temores. Para intentar recuperar la normalidad, la pareja se dirige a un orfanato local con la intención de adoptar a un niño. Allí se sienten enigmáticamente atraídos por una niña de rostro angelical llamada Esther. Pero las cosas se tuercen tras la llegada de la muchacha a la casa de los Coleman, donde empiezan a ocurrir cosas extrañas. Cuando Kate empieza a darse cuenta de que Esther esconde un terrible secreto, intentará descubrir qué es, pero quizá sea demasiado tarde...', trailer_url = 'https://www.youtube.com/watch?v=F7TfCfebWcc' WHERE id_api = 'tt1148204';

UPDATE Contenido SET id_tmdb = 656690, descripcion = 'A medida que las plataformas digitales se vuelven más importantes para mantenernos conectados, expertos explican cómo esta interacción está reprogramando la civilización, revelando qué se esconde al otro lado de la pantalla', trailer_url = 'https://www.youtube.com/watch?v=uaaC57tcci0' WHERE id_api = 'tt11464826';

UPDATE Contenido SET id_tmdb = 220564, descripcion = 'Amelia está a punto de entrar, por la vía del altar, en una de las familias más ricas de Nantucket, pero aparece un cadáver que arruina la boda y convierte a todos en sospechosos.', trailer_url = 'https://www.youtube.com/watch?v=l1JwxQZ4A48' WHERE id_api = 'tt11514868';

Todo parece ir a la perfección hasta que, en la víspera de la boda, uno de los invitados es encontrado muerto. Este trágico suceso convierte la celebración en una escena del crimen, desencadenando una investigación que saca a la luz los oscuros y complejos secretos de todos los presentes.');

UPDATE Contenido SET id_tmdb = 37903, descripcion = 'En 1913, en vísperas de la Gran Guerra (1914-1918), extraños acontecimientos, que poco a poco toman carácter de castigo ritual, se dan cita en un pequeño pueblo protestante del norte de Alemania. Los niños y adolescentes del coro del colegio y de la iglesia dirigido por el maestro, sus familias, el barón, el encargado, el médico, la comadrona, y los granjeros conforman una historia que reflexiona sobre los orígenes del nazismo en vísperas de la I Guerra Mundial.', trailer_url = 'https://www.youtube.com/watch?v=9JOXs8KEiDY' WHERE id_api = 'tt1149362';

UPDATE Contenido SET id_tmdb = 38117, descripcion = 'Kyle es un joven cuyo atractivo le hace creer que está por encima de los demás. Pero todo cambia cuando una bruja lo transforma en un monstruo para darle una lección. El chico deberá conseguir que alguien se enamore de él en menos de un año, o se quedará con ese aspecto para siempre. Adaptación moderna del cuento clásico "La bella y la bestia", que la escritora francesa Gabrielle-Suzanne Barbot de Villeneuve recogió por primera vez por escrito en el año 1740. A pesar de todo, la cinta no sigue la historia original, sino que se basa en la novela "La bestia", de Alex Flinn, un superventas entre el público adolescente en Estados Unidos.', trailer_url = 'https://www.youtube.com/watch?v=0WAG4A5Wt5c' WHERE id_api = 'tt1152398';

UPDATE Contenido SET id_tmdb = 11322, descripcion = 'Basada en la obra de Brian Burrough "Public Enemies: America''s Greatest Crime Wave and the Birth of the FBI, 1933-43". Narra la historia de Melvin Purvis (Christian Bale), el agente del FBI que en los años treinta dirigió la búsqueda del legendario atracador de bancos John Dillinger (Johnny Depp) y su banda.', trailer_url = 'https://www.youtube.com/watch?v=RstcvQzxy98' WHERE id_api = 'tt1152836';

UPDATE Contenido SET id_tmdb = 649409, descripcion = 'Detroit, año 1954. Unos delincuentes de poca monta son contratados para robar lo que ellos creen que es un simple documento y será un trabajo fácil. Cuando su plan no sale como ellos esperaban, emprenden la búsqueda de quien los contrató y del propósito real para el que fueron contratados.', trailer_url = 'https://www.youtube.com/watch?v=kybqUuHscrM' WHERE id_api = 'tt11525644';

UPDATE Contenido SET id_tmdb = 16538, descripcion = 'Peter Klaven (Paul Rudd) es un joven que vive muy feliz: está de novio con Zooey (Rashida Jones), con quien vive, y es un agente que trabaja en bienes raíces, a pesar de la crisis económica. Su futuro económico depende de la comisión que gane si logra vender una gran mansión del actor Lou Ferrigno. Al momento de casarse, Zooey llama a todas sus amigas para que sean sus damas de honor y Peter a nadie. Así, Peter se da cuenta de que no tiene amigos hombres. Y la boda necesita un padrino. Peter quiere tener suerte con los recomendados de su hermano gay, Robbie (Andy Samberg), con resultados cómicos pero previsibles. Después de fracasar en las citas con los hombres homosexuales, en la casa de Ferrigno conoce a un hombre llamado Sydney Fife (Jason Segel), que no quería comprar la gran mansión, sino que está allí para comer. Peter va rápidamente a proponerle una cita amical a Sydney y poco a poco crece una gran amistad.', trailer_url = 'https://www.youtube.com/watch?v=WQteb-cr4pE' WHERE id_api = 'tt1155056';

UPDATE Contenido SET id_tmdb = 15584, descripcion = 'Poco después de que su amigo Andrew Bagby fuese asesinado por su ex-novia Shirley Turner, el cineasta Kurt Kuenne descubre que Turner está embarazada de Bagby. Kuenne decide crear un documental celebrando la vida de Bagby, con la idea de que sirva para que su hijo pueda conocer quién fué su padre. Viajando a través de los Estados Unidos, Kuenne entrevista a todo aquel que alguna vez conoció a su amigo, antes de que su memoria se desvanezca. Entre tanto, al enterarse de que Turner ha volado a Canadá, los padres de Bagby dejan todo atrás para irse a Canadá a luchar por la custodia de su nieto, Zachary. Sin embargo, durante la producción, el gobierno canadiense decide liberar a Turner, la asesina de Bagby, y darle la custodia de Zachary.', trailer_url = 'https://www.youtube.com/watch?v=l7ughuxTn_Q' WHERE id_api = 'tt1152758';

UPDATE Contenido SET id_tmdb = 38575, descripcion = 'Dre Parker podría haber sido el más popular en Detroit, pero la carrera profesional de su madre los lleva a ambos a China. Allí logra hacer conexión con su compañera de clase Mei Ying y el sentimiento es mutuo, hasta que las diferencias culturales hacen que su amistad sea imposible. Para que la situación empeore, Dre se consigue un enemigo, el peleonero de la clase, Cheng. Dre no tiene amigos a quién acudir, excepto el encargado de mantenimiento, el Sr. Han.', trailer_url = 'https://www.youtube.com/watch?v=vKC4q9Gialo' WHERE id_api = 'tt1155076';

UPDATE Contenido SET id_tmdb = 661539, descripcion = 'Bob Dylan se hizo un nombre en el mundo del folk a muy temprana edad con sus versiones acústicas. Así que cuando en 1965, en el Newport Folk Festival, decidió conectar una guitarra eléctrica y usarla en su concierto, fue un duro golpe para los puristas del folk que veían el futuro del género en el joven. Desde ese momento, la vida de Dylan cambió profundamente. Siendo atacado por un gran grupo de seguidores del folk que lo tachaban de traidor, haciendo que su carrera no volviera a ser la misma. Ese concierto fue clave, se declaró como un músico independiente y fue el comienzo de la voz de una generación.', trailer_url = 'https://www.youtube.com/watch?v=YLYNZ4jDcdk' WHERE id_api = 'tt11563598';

UPDATE Contenido SET id_tmdb = 856437, descripcion = 'Palestina, 1948. Tras la retirada de los ocupantes británicos, aumentan las tensiones entre árabes y judíos. Mientras tanto, Farha, la inteligente hija del alcalde de un pequeño pueblo, ajena a la tragedia que se avecina, sueña con ir a estudiar a la gran ciudad.', trailer_url = 'https://www.youtube.com/watch?v=2UT6Zw4-Yg0' WHERE id_api = 'tt11555492';

UPDATE Contenido SET id_tmdb = 19908, descripcion = 'En un mundo plagado de zombis, Columbus es un gallina, un joven que se encuentra aterrorizado por la situación, pero cuando te juegas el ser comido por los zombies, el miedo puede mantenerte vivo. De hecho su cobardía precisamente le ha permitido que sus sesos aún se mantengan en su cabeza. Entonces un día conoce a Tallahassse, un macarra caza zombies cuya única determinación en su vida es lograr el último Twinkie (dulce americano) en la tierra. Cuando ambos unen fuerzas con Wichita y Little Rock, que también han encontrado una manera original de sobrevivir en ese caos, tendrán que elegir qué es peor: si confiar los unos en los otros para sobrevivir o sucumbir ante los zombies.', trailer_url = 'https://www.youtube.com/watch?v=VBqlyQDvLaM' WHERE id_api = 'tt1156398';

UPDATE Contenido SET id_tmdb = 14048, descripcion = 'Documental sobre la hazaña del funambulista francés Philippe Petit que, el 7 de agosto de 1974, logró de manera ilegal caminar sobre un alambre tendido entre las torres gemelas del World Trade Center de Nueva York. Culminada la proeza, fue arrestado por la policía, pero la exhibición fue considerada por algunos "el crimen artístico del siglo".', trailer_url = 'https://www.youtube.com/watch?v=EIawNRm9NWM' WHERE id_api = 'tt1155592';

UPDATE Contenido SET id_tmdb = 661374, descripcion = 'Cuando el multimillonario Miles Bron invita a algunos de sus allegados a una escapada a su isla griega privada, pronto queda claro que no todo es perfecto en el paraíso. Y cuando alguien aparece muerto, ¿quién mejor que Benoit Blanc para desentrañar todas las capas del misterio?', trailer_url = 'https://www.youtube.com/watch?v=0ExmWjuG1UM' WHERE id_api = 'tt11564570';

UPDATE Contenido SET id_tmdb = 438631, descripcion = 'En un lejano futuro, la galaxia conocida es gobernada mediante un sistema feudal de casas nobles bajo el mandato del Emperador. Las alianzas y la política giran entorno a un pequeño planeta, Dune,  del que extrae la ''especia melange'', la materia prima que permite los viajes espaciales. La Casa Atreides, bajo el mandato del Duque Leto Atreides recibe el encargo de custodiar el planeta, relevando en la encomienda a sus históricos enemigos, los Harkonnen. Paul Atreides, hijo del duque, se verá atrapado en las intrigas políticas mientras descubre el destino que le deparan los desiertos de Dune.', trailer_url = 'https://www.youtube.com/watch?v=kPjOcWHVNGo' WHERE id_api = 'tt1160419';

UPDATE Contenido SET id_tmdb = 48171, descripcion = 'Michael Kovak (Colin O''Donoghue) es un decepcionado seminarista norteamericano que decide asistir a un curso de exorcismos en el Vaticano, lo que hará que su fe se tambalee y tenga que enfrentarse a terribles fuerzas demoniacas. En Roma conocerá al Padre Lucas (Hopkins), un sacerdote poco ortodoxo que le enseñará el lado oscuro de la Fe...', trailer_url = 'https://www.youtube.com/watch?v=8Wjen6Rj4hk' WHERE id_api = 'tt1161864';

UPDATE Contenido SET id_tmdb = 45958, descripcion = 'Retrato de la vida de Uxbal: padre abnegado e hijo desamparado. Intermediario de la sombra. Próximo a los desaparecidos. Atraído por los fantasmas. Sensible a los espíritus. Superviviente en el corazón de una Barcelona invisible. Sintiendo que la muerte le ronda, intenta encontrar la paz, proteger a sus hijos, salvarse a sí mismo. La historia de Uxbal es sencilla y compleja, al igual que nuestras vidas de hoy.', trailer_url = 'https://www.youtube.com/watch?v=WQAfAlZ8TCw' WHERE id_api = 'tt1164999';

UPDATE Contenido SET id_tmdb = 663870, descripcion = 'El militar Markus debe regresar a casa con su hija adolescente, Mathilde, cuando su esposa muere en un trágico accidente de tren. Todo parece ser a causa de la mala suerte, hasta que Otto, experto en matemáticas y también pasajero de tren siniestrado, aparece con sus dos excéntricos colegas, Lennart y Emmenthaler. Otto está convencido de que alguien está detrás de todo esto.', trailer_url = 'https://www.youtube.com/watch?v=RzmPoJznY9Y' WHERE id_api = 'tt11655202';

UPDATE Contenido SET id_tmdb = 178809, descripcion = 'Bajo la superficie helada, los sobrevivientes de la Colonia Siete luchan mientras los suministros de alimentos disminuyen y las temperaturas continúan bajando. Acosados por la enfermedad y los conflictos internos, los colonos sospechan lo peor cuando misteriosamente pierden el contacto con la colonia Cinco, el único otro establecimiento conocido. Sam, un mecánico de carácter fuerte con un pasado trágico, se une a un equipo encabezado por Briggs en una peligrosa expedición para averiguar lo que pasó. Después de un viaje infernal, descubren una amenaza mucho peor de lo imaginado, y ahora la Colonia Siete debe ganar una batalla feroz para preservar el pasado de la humanidad.', trailer_url = 'https://www.youtube.com/watch?v=kRfXdS2q08k' WHERE id_api = 'tt1160996';

