UPDATE Contenido SET id_tmdb = 666243, descripcion = 'El brujo Vesemir mata monstruos por el dinero y la gloria. Hasta que surge una nueva amenaza y debe enfrentarse a los demonios de su mísero pasado.', trailer_url = 'https://www.youtube.com/watch?v=J365hQpaWRw' WHERE id_api = 'tt11657662';

UPDATE Contenido SET id_tmdb = 14070, descripcion = 'Sanjay Singhania, un rico hombre de negocios, dueño de una compañía de teléfonos móviles llamada Air Voice, es herido en la cabeza con una vara de metal. Sanjay sobrevive al golpe, pero adquiere una extraña amnesia debido al trauma de su lesión cerebral. En un momento dado, él no recuerda nada de lo que pasó más de 15 minutos hacia atrás, aunque con frecuencia tiene flashbacks del asesinato de Kalpana, una joven de la que estuvo enamorado. Ahora Sanjay decidirá vengarse, junto con una estudiante universitaria de medicina Sunita. Remake de Bollywood de la película del mismo nombre dirigida por el propio director en 2005, en idioma tamil. Al igual que aquella, se inspira en "Memento", la película de culto dirigida por Christopher Nolan.', trailer_url = 'https://www.youtube.com/watch?v=jEccwrX6AgQ' WHERE id_api = 'tt1166100';

