UPDATE Contenido SET id_tmdb = 113985, descripcion = 'Un ranchero que lucha por su tierra y su familia se topa con un misterio insondable al borde del desierto de Wyoming, lo que lo obliga a enfrentarse con lo Desconocido de manera íntima y cósmica en el indómito oeste americano.', trailer_url = 'https://www.youtube.com/watch?v=8UkDdTMZh14' WHERE id_api = 'tt11685912';

UPDATE Contenido SET id_tmdb = 57158, descripcion = 'Tras sobrevivir al inicio de su inesperado viaje, la Compañía sigue hacia el este y se encuentra por el camino con Beorn, el cambiador de piel, y con un enjambre de Arañas gigantes en el peligroso monte Mirkwood. Tras evitar que los Elfos del Bosque los capturen, los Enanos prosiguen su viaje hacia Ciudad del Lago, y finalmente llegan a la Montaña Solitaria, donde tienen que enfrentarse al mayor de los peligros, una criatura más terrorífica que cualquier otra que pondrá a prueba no solo lo profundo de su valentía sino también los límites de su amistad y la sabiduría del viaje: el dragón Smaug.', trailer_url = 'https://www.youtube.com/watch?v=4SLBizx05Bo' WHERE id_api = 'tt1170358';

