UPDATE Contenido SET id_tmdb = 333371, descripcion = 'Una joven sufre un accidente de coche. Cuando despierta se encuentra encerrada en una celda bajo tierra, secuestrada por un hombre extraño que dice haberla salvado del día del juicio final. El excéntrico captor asegura que el exterior es inhabitable por culpa de un terrible ataque químico, algo que no sabe si creer. Es así como comienza su pesadilla, en una espiral de desconocimiento. La mente del criminal es infranqueable, y ella tendrá que intentar analizar a su enemigo para conseguir sobrevivir.', trailer_url = 'https://www.youtube.com/watch?v=tQWM9Uucfw0' WHERE id_api = 'tt1179933';

UPDATE Contenido SET id_tmdb = 674324, descripcion = 'Pádraic y Colm son dos amigos de toda la vida que se encuentran en un callejón sin salida cuando Colm pone inesperadamente fin a su amistad. Un aturdido Pádraic, ayudado por su hermana Siobhán y el problemático joven isleño Dominic se esfuerza por reparar la relación, negándose a aceptar un no por respuesta. Pero los repetidos esfuerzos de Pádraic no hacen más que reforzar la determinación de su antiguo amigo, y cuando Colm le da un ultimátum desesperado los acontecimientos se intensifican rápidamente, con consecuencias impactantes.', trailer_url = 'https://www.youtube.com/watch?v=_r7j79W4s8o' WHERE id_api = 'tt11813216';

UPDATE Contenido SET id_tmdb = 41215, descripcion = 'A mediados del siglo XIV, Inglaterra se ve asolada por la terrible Peste Negra. En un mundo apocalíptico, dominado por las supersticiones, el joven monje Osmund recibe el encargo de conducir a Ulric, un temible caballero, y a su grupo de mercenarios a un pueblo próximo a un pantano, en el que, según los rumores, los muertos vuelven a la vida.', trailer_url = 'https://www.youtube.com/watch?v=JkOwLCib1Tk' WHERE id_api = 'tt1181791';

UPDATE Contenido SET id_tmdb = 17431, descripcion = 'La película cuenta la historia de Sam Bell, un astronauta que se encuentra cerca de finalizar su contrato con Lunar, empresa para la que ha trabajado durante tres años viviendo en Selene, una base lunar desde la que ha estado extrayendo gas de la mina Helium 3, a causa de la terrible crisis energética que está pasando la Tierra. Dos semanas antes de su regreso a casa con su mujer y su hija, Sam comienza a tener extrañas visiones y a sentirse extraño, pero no será hasta la llegada de sus sustituto cuando Sam vea sus sospechas en cuanto a los verdaderos propósitos de Lunar hechos realidad, pues algo más que su contrato va a expirar en breve.', trailer_url = 'https://www.youtube.com/watch?v=gynaX-yu-xw' WHERE id_api = 'tt1182345';

