UPDATE Contenido SET id_tmdb = 14072, descripcion = 'Surinder (Shahrukh Khan) es un hombre del montón, soso y predecible. Taani (Anushka Sharma) es una joven que rebosa vitalidad y está a punto de casarse cuando su novio muere en un accidente de tráfico. Tras semejante desgracia, acepta casarse con Surinder. En un principio la relación entre ambos es puramente de conveniencia pero Surinder acabará enamorándose de Taani la cual no muestra demasiado interés por él. Cuando Taani se apunta a clases de danza en una Compañía que visita Bombay, Surinder ve la oportunidad de acercarse a ella y se hace pasar por un cachas llamado Raj.', trailer_url = NULL WHERE id_api = 'tt1182937';

UPDATE Contenido SET id_tmdb = 760161, descripcion = 'Tras escapar de un centro psiquiátrico estonio, Leena Klammer viaja a América haciéndose pasar por Esther, la hija desaparecida de una familia adinerada. Pero cuando su máscara empieza a caer, se enfrenta a una madre que protegerá a su familia de la "niña" asesina a cualquier precio.', trailer_url = 'https://www.youtube.com/watch?v=_uX6of3vBu0' WHERE id_api = 'tt11851548';

UPDATE Contenido SET id_tmdb = 13477, descripcion = 'Beth Harper es una neoyorquina harta del amor que aprovecha un viaje a Roma para robar algunas de las monedas que se han lanzado a una fuente que, según cuenta la leyenda, tiene propiedades mágicas. Los enamorados lanzan allí sus monedas para ser correspondidos, por lo que el robo de Bell provoca que un grupo de encolerizados pretendientes la persiga hasta Nueva York, después de haber sabido que robó las monedas que ellos habían tirado a la fuente.', trailer_url = 'https://www.youtube.com/watch?v=hwOeFpjN4ho' WHERE id_api = 'tt1185416';

UPDATE Contenido SET id_tmdb = 8885, descripcion = 'Una noche en un bar, un viejo amigo cuenta al director Ari Folman que tiene una pesadilla recurrente en la que le persiguen 26 perros. Cada noche, el mismo número de animales. Los dos hombres llegan a la conclusión de que hay una conexión entre su sueño y una misión del ejército israelí durante la primera Guerra del Líbano de los años ochenta. Ari se sorprende de no poder recordar nada más de ese periodo de su vida.', trailer_url = 'https://www.youtube.com/watch?v=XN0K1PBq9NU' WHERE id_api = 'tt1185616';

UPDATE Contenido SET id_tmdb = 22832, descripcion = 'Ninja Assassin narra la historia de Raizo (Rain), uno de los mejores asesinos del mundo. Raizo es un niño de la calle transformado en una máquina entrenada por el Clan Ozunu, una sociedad secreta la cual se cree que es un mito. El asesinato de uno de los amigos de Raizo por el mismo Clan hace que él huya y desaparezca. Ahora el espera el momento indicado para la venganza. En Berlin, la agente de Europol Mika Coretti (Naomie Harris) ha chocado con una pista que demuestra que asesinatos políticos tienen vinculación con asesinos del Lejano Oriente. Desafiando las ordenes de su superior, Ryan Maslow (Ben Miles), Mika investiga mas a fondo para saber la verdad detrás de los asesinatos. Este descubrimiento la convierte en un blanco del Clan Ozunu y asesinos son enviados tras ella liderados por el letal Takeshi (Rick Yune), para silenciarla para siempreto. Raizo salva a Mika de sus atacantes, pero ahora el sabe que el Clan no descansará hasta que ambos sean eliminados.', trailer_url = 'https://www.youtube.com/watch?v=grCIfK2ZqH4' WHERE id_api = 'tt1186367';

UPDATE Contenido SET id_tmdb = 12180, descripcion = 'Mientras las Guerras Clon barren la galaxia, Anakin Skywalker y su nueva aprendiz Padawan, Ahsoka Tano, se aventuran en una arriesgada misión para rescatar al hijo secuestrado de Jabba el Hutt, el señor del Crimen. El renegado Conde Dooku y su letal y cruel vasalla Asajj Ventress harán todo lo posible por hacerles fracasar, haciendo que la misión de Anakin Skywalker tenga graves consecuencias.Mientras, en la línea de batalla, Obi-Wan Kenobi y el maestro Yoda lideran el masivo ejército clon en un valiente esfuerzo por derrotar al ejército droide y resistir a las fuerzas del lado oscuro.', trailer_url = 'https://www.youtube.com/watch?v=tRuDieYWAqA' WHERE id_api = 'tt1185834';

UPDATE Contenido SET id_tmdb = 670292, descripcion = 'En medio de una guerra futura entre la raza humana y las fuerzas de la inteligencia artificial, Joshua, un duro ex-agente de las fuerzas especiales que llora la desaparición de su esposa, es reclutado para cazar y matar al Creador, el escurridizo arquitecto de la IA avanzada que ha desarrollado una misteriosa arma con el poder de acabar con la guerra... y con la propia humanidad.', trailer_url = 'https://www.youtube.com/watch?v=Cws_5o2hN-Y' WHERE id_api = 'tt11858890';

UPDATE Contenido SET id_tmdb = 766507, descripcion = 'Ambientada hace 300 años en la Nación Comanche. Naru es una joven guerrera, feroz y altamente hábil, que se crió a la sombra de algunos de los cazadores más legendarios que deambulan por las Grandes Llanuras. Cuando el peligro amenaza su campamento, se dispone a proteger a su gente. La presa a la que acecha y, en última instancia, se enfrenta, resulta ser un depredador alienígena evolucionado con un arsenal técnicamente avanzado, lo que deriva en un enfrentamiento cruel y aterrador entre los dos adversarios.', trailer_url = 'https://www.youtube.com/watch?v=7AWRZuYlEFU' WHERE id_api = 'tt11866324';

UPDATE Contenido SET id_tmdb = 26428, descripcion = 'En el siglo IV, Egipto era una provincia del Imperio Romano. Su ciudad más emblemática, Alejandría, se había convertido en el último baluarte de un mundo en crisis, confuso y violento. En el año 391, las revueltas callejeras alcanzaron una de sus instituciones más legendarias: la biblioteca. Atrapada tras sus muros, la brillante astrónoma Hypatia, filósofa y atea, lucha por salvar la sabiduría del mundo antiguo, sin percibir que su joven esclavo, Davo, se debate entre el amor que le profesa en secreto y la libertad que podría alcanzar uniéndose al imparable ascenso del cristianismo.', trailer_url = 'https://www.youtube.com/watch?v=AnIZieXoUa8' WHERE id_api = 'tt1186830';

UPDATE Contenido SET id_tmdb = 20453, descripcion = 'Cuenta la historia de Rancho. Un chico con una pasión por estudiar y aprender. En la escuela de ingenieros, entablará amistad con Raju y Farham que acabarán por convertirse en sus dos mejores amigos. Pero al graduarse pierden el contacto y sus dos amigos deciden ir en su búsqueda.', trailer_url = 'https://www.youtube.com/watch?v=zIKu9k50SDo' WHERE id_api = 'tt1187043';

UPDATE Contenido SET id_tmdb = 26022, descripcion = 'Rizwan Khan (Tanay Chheda) es un niño musulmán que se crió con su madre (Zarina Wahab) en el Borivali sección de Bombay en la India y que sufre de síndrome de Asperger. Ya como un adulto (Shahrukh Khan), Rizwan se enamora de una hindú madre soltera, Mandira (kajol) que vive en San Francisco. Después de los atentados del 9/11, Rizwan es detenido como sospechoso de terrorismo por la autoridades por la conducta sospechosa que tiene a razon de su discapacidad. Después de su arresto, él se reúne con Radha (Sheetal Menon), un terapeuta que ayuda a superar los traumas vividos. Rizwan entonces comienza un viaje para encontrar y reunirse con el Presidente Barack Obama (Christopher B. Duncan), a fin de limpiar su nombre.', trailer_url = 'https://www.youtube.com/watch?v=nqxgYT3TYzY' WHERE id_api = 'tt1188996';

UPDATE Contenido SET id_tmdb = 26466, descripcion = 'Cuando Jess, de camino al puerto, atropella a una gaviota, no se imagina que se trata de un mal presagio. Cuando llega al yate, donde lo espera un grupo de amigos, nota que algo va mal, pero no acierta a saber por qué. Sus temores se acrecientan cuando se desencadena una tormenta que obliga al grupo a abandonar el yate para subir a otro barco, en el que Jess tiene la sensación de haber estado antes. El barco parece desierto, pero no están solos. Alguien los está cazando uno a uno. Y Jess, sin saberlo, tiene la llave que puede acabar ese horror.', trailer_url = 'https://www.youtube.com/watch?v=RFLvVYetuTE' WHERE id_api = 'tt1187064';

UPDATE Contenido SET id_tmdb = 19898, descripcion = 'Dos miembros de la tripulación de una nave espacial, el Teniente Payton (Dennis Quaid) y el Cabo Bower (Ben Foster), se despiertan en sus cámaras de hibernación sin recordar nada de lo que ha sucedido: ni quiénes son, ni cuál era su misión o por qué, aparentemente, son los únicos supervivientes. Conforme se adentren en las zonas más profundas de la nave, descubrirán que no están solos, y desvelarán el terrible misterio que rodea la desaparición del resto de la tripulación y de los pasajeros. Pronto se darán cuenta de que mantenerse con vida es mucho más importante de lo que puedan imaginarse: es el único modo de evitar la extinción de la raza humana.', trailer_url = 'https://www.youtube.com/watch?v=Vq-R6EXZwHE' WHERE id_api = 'tt1188729';

