UPDATE Contenido SET id_tmdb = 63311, descripcion = 'Desde que su mujer murió quemada en un accidente de coche, el Dr. Ledgard, eminente cirujano plástico, se interesa por la creación de una nueva piel con la que hubiera podido salvarla. Doce años después consigue cultivarla en su laboratorio, aprovechando los avances de la terapia celular. Para ello no dudará en traspasar una puerta hasta ahora terminantemente vedada: la transgénesis con seres humanos. Pero ese no será el único crimen que cometerá...', trailer_url = 'https://www.youtube.com/watch?v=Gm8XTqv_K80' WHERE id_api = 'tt1189073';

UPDATE Contenido SET id_tmdb = 14161, descripcion = 'El geólogo Adrian Helmsley, descubre de que el núcleo de la Tierra se está calentando. Teme que la corteza se vuelva inestable, coincidiendo con las predicciones mayas del fin del mundo. Entre tanto, los líderes del mundo "venden" plazas para escapar del cataclismo. El escritor Curtis Jackson tropieza con esa información... y luchará por salvar a su familia mientras el suelo se hunde bajo sus pies, y los terremotos y las erupciones volcánicas destruyen el mundo tal y como lo conocemos.', trailer_url = 'https://www.youtube.com/watch?v=CcSf1whgEJo' WHERE id_api = 'tt1190080';

