UPDATE Contenido SET id_tmdb = 13855, descripcion = 'Joong-ho, un antiguo detective convertido en proxeneta, tiene problemas financieros, ya que algunas de sus chicas han desaparecido. Al intentar encontrarlas, averigua que han sido reclutadas por un cliente que padece una oscura obsesión. Thriller coreano que se colocó en el Top de las películas más taquilleras de la historia del país. (FILMAFFINITY)', trailer_url = 'https://www.youtube.com/watch?v=akiHkFxV24w' WHERE id_api = 'tt1190539';

UPDATE Contenido SET id_tmdb = 642885, descripcion = 'Han pasado 29 años desde que alguien encendió la Vela de la Llama Negra y resucitó a las hermanas Sanderson del siglo XVII, y ahora buscan venganza. De tres estudiantes de secundaria depende impedir que las voraces brujas causen un nuevo tipo de estrago en Salem antes del amanecer el día de Halloween.', trailer_url = 'https://www.youtube.com/watch?v=YQKkDuTVRbE' WHERE id_api = 'tt11909878';

UPDATE Contenido SET id_tmdb = 22947, descripcion = 'Ryan Bingham es un experto en despedir a gente, contratado de forma externa por otras empresas para reducir personal. Es un miembro mimado y de élite de todos los programas de fidelización de viajeros que existen. Sin embargo Ryan no tiene nada auténtico a lo que aferrarse. Cuando se siente atraído por una atractiva compañera de viaje, otra viajera frecuente, el jefe de Ryan, animado por una joven y advenediza experta en eficiencia, amenaza con atarle a un despacho. Enfrentado a la perspectiva, a la vez terrorífica de ser destinado a un puesto fijo, Ryan empieza a meditar sobre lo que puede llegar a significar el tener un hogar de verdad.', trailer_url = 'https://www.youtube.com/watch?v=yaDjjN1-sOA' WHERE id_api = 'tt1193138';

UPDATE Contenido SET id_tmdb = 76479, descripcion = 'La serie tiene lugar en un mundo en el que los superhéroes representan el lado oscuro de la celebridad y la fama. Un grupo de vigilantes que se hacen llamar "The Boys" decide hacer todo lo posible por frenar a los superhéroes que están perjudicando a la sociedad, independientemente de los riesgos que ello conlleva.', trailer_url = 'https://www.youtube.com/watch?v=AD0qUhZpbfc' WHERE id_api = 'tt1190634';

UPDATE Contenido SET id_tmdb = 34647, descripcion = 'Oscar y su hermana Linda viven desde hace poco en Tokyo. Él sobrevive traficando con drogas, ella trabaja como stripper en un club nocturno. Durante un forcejeo con la policía, Oscar cae herido tras un disparo. Aunque esté agonizando, su espíritu, fiel a la promesa de no abandonar a su hermana, rechaza abandonar el mundo de los vivos. Su espíritu vaga ahora por la ciudad y sus visiones son cada vez más caóticas. (FILMAFFINITY)', trailer_url = 'https://www.youtube.com/watch?v=HkPMjoUqYXU' WHERE id_api = 'tt1191111';

UPDATE Contenido SET id_tmdb = 44896, descripcion = 'El actor Rango es un solitario camaleón que vive en la inmensidad del desierto Mojave. Quiere ser un representante de la ley en un sediento pueblo llamado Dirt, pero enseguida se da cuenta de que hay una gran diferencia entre actuar y vivir la vida real, así que no tiene más remedio que enfrentarse a algunos aspectos de su identidad y aprender el significado y el valor de la amistad. Su misión consistirá en descubrir la conspiración que está detrás de la desaparición del agua en el pueblo. Film de animación del director de "Piratas del Caribe", con las voces originales de Johnny Depp (Rango), Abigail Breslin, Isla Fisher y Bill Nighy.', trailer_url = 'https://www.youtube.com/watch?v=wIKG4s_uSRg' WHERE id_api = 'tt1192628';

UPDATE Contenido SET id_tmdb = 41233, descripcion = 'El intenso baile callejero del metro de Nueva York cobra vida en 3D en la tercera entrega de la franquicia Step Up (2006), cuando la cruda y apasionada cultura se globaliza. Un cerrado grupo de bailarines callejeros, que incluye a Luke y a Natalie, se reúne con el novato Moose y juntos terminan enfrentados a los mejores bailarines de breakdance del mundo en una confrontación final que cambiará sus vidas para siempre.', trailer_url = 'https://www.youtube.com/watch?v=l6kL81VfMuE' WHERE id_api = 'tt1193631';

UPDATE Contenido SET id_tmdb = 49040, descripcion = 'El agente Aaron Cross es un producto del eficiente programa Outcome. Este programa diseña y entrena agentes cuya función consiste en actuar en solitario en misiones de alto riesgo. Sin embargo, en el momento en que la historia del agente Bourne está a punto de salir a la luz, los altos mandos de la agencia deciden tomar una solución drástica al respecto.', trailer_url = 'https://www.youtube.com/watch?v=CJKo5T098RU' WHERE id_api = 'tt1194173';

UPDATE Contenido SET id_tmdb = 72207, descripcion = 'Justo un año después de que el prometedor cocinero Tom Solomon conociese a Violet Barnes, la sorprende con un anillo de compromiso. Tom y Violet están destinados a vivir felices para siempre, pero una cadena de sucesos inesperados, trabajos y viajes sigue retrasando la fecha en la que deben ir juntos al altar para casarse.', trailer_url = 'https://www.youtube.com/watch?v=RZBPEsgCmqs' WHERE id_api = 'tt1195478';

UPDATE Contenido SET id_tmdb = 33217, descripcion = '¡El divertidísimo superventas cobra vida con esta comedia familiar de éxito! Greg Heffley hará grandes cosas, pero primero tendrá que sobrevivir a la experiencia más humillante y que más miedo da en la vida de un niño: ¡la secundaria! No será fácil considerando que está rodeado de idiotas peludos con pecas, abusones que tiran de los calzoncillos y una loncha de queso con piojos nucleares.', trailer_url = 'https://www.youtube.com/watch?v=w6P8O55fELE' WHERE id_api = 'tt1196141';

UPDATE Contenido SET id_tmdb = 100911, descripcion = 'Set in the backdrop of the mystical city of Varanasi, Asur follows Nikhil Nair, a forensic-expert-turned-teacher, who returns to his roots at the Central Bureau of Investigation, and along with his former mentor Dhananjay Rajpoot, finds himself caught in a cat-and-mouse game with a brutal serial killer. What follows is a blend of suspense, mythology and the murders of some people totally unrelated.', trailer_url = 'https://www.youtube.com/watch?v=0ZwyCRhhK60' WHERE id_api = 'tt11912196';

UPDATE Contenido SET id_tmdb = 22803, descripcion = 'Clyde Shelton es un ciudadano normal que lo ha perdido todo. Diez años antes su mujer y su hija fueron brutalmente asesinadas y los criminales nunca fueron condenados. El culpable es Nick Rice, el ambicioso ayudante del fiscal del distrito, porque hizo un pacto con el abogado de uno de ellos. Pero Clyde descubre ese acuerdo, y su deseo de venganza lo lleva a cometer una serie de asesinatos', trailer_url = 'https://www.youtube.com/watch?v=diBj-JyyWjE' WHERE id_api = 'tt1197624';

UPDATE Contenido SET id_tmdb = 1014214, descripcion = 'The cop universe expands with newer additions while the old ones return led by Bajirao Singham. Singham Again interweaves the mythological epic Ramayana''s good vs evil narrative when his wife Avni Kamath gets abducted by Danger Lanka setting Bajirao and his gang of Sangram Bhalerao and Veer Sooryavanshi along with Satya and Shakti Shetty on a mission to rescue her.', trailer_url = 'https://www.youtube.com/watch?v=DovbhJavvfU' WHERE id_api = 'tt11976134';

UPDATE Contenido SET id_tmdb = 16991, descripcion = 'En el centro comercial Forest Ridge, el jefe de seguridad Ronnie Barnhard (Seth Rogen) patrulla con puño de acero. Como dueño de su territorio, combate a los maleantes y en algunas ocasiones a los clientes rebeldes mientras sueña con cambiar su linterna por una una pistola. Cuando un exhibicionista comienza a atacar, Ronnie aprovecha la oportunidad para mostrar sus talentos y lograr un lugar en la academia de policía, y el corazón de la chica de sus sueños, Brandi (Anna Faris), la sexy vendedora de mostrador quien nunca le presta atención.', trailer_url = 'https://www.youtube.com/watch?v=O83-RR1UjWI' WHERE id_api = 'tt1197628';

UPDATE Contenido SET id_tmdb = 744653, descripcion = 'Un grupo de jubilados aficionados a resolver casos antiguos se enfrenta a un asesinato real cargado de misterio en esta comedia de humor negro basada en la novela homónima.', trailer_url = 'https://www.youtube.com/watch?v=50DYgzRBhFA' WHERE id_api = 'tt12001534';

UPDATE Contenido SET id_tmdb = 899112, descripcion = 'Cuando un equipo de mercenarios irrumpe en Nochebuena dentro de un complejo familiar adinerado y toma como rehenes a todos los que están dentro, no estaban preparados para un defensor sorpresa: Santa Claus (David Harbour) está en el edificio y a punto de demostrar por qué este Santa Claus, no es ningún santo.', trailer_url = 'https://www.youtube.com/watch?v=MUDqcnalsLg' WHERE id_api = 'tt12003946';

UPDATE Contenido SET id_tmdb = 807356, descripcion = 'Una joven se muda a un nuevo apartamento con su prometido y se ve atormentada por la sensación de ser acosada por un vigilante invisible en un edificio adyacente.', trailer_url = 'https://www.youtube.com/watch?v=8ZRMBLq81i8' WHERE id_api = 'tt12004038';

