UPDATE Contenido SET id_tmdb = 20829, descripcion = 'La historia ambientada en el mundo de los comediantes de standup (los monologuistas), y concretamente en George Simmons, un famoso cómico que descubre de repente que le queda poco tiempo de vida. George Simmons, que cree tenerlo todo, se da cuenta de lo que es estar cerca de la muerte, y a partir de ese momento pondrá todo su empeño en buscar aquello que realmente aporte significado a su vida.', trailer_url = 'https://www.youtube.com/watch?v=7ixy3fXB_Ak' WHERE id_api = 'tt1201167';

UPDATE Contenido SET id_tmdb = 687163, descripcion = 'El profesor de ciencias Ryland Grace se despierta en una nave espacial a años luz de casa sin recordar quién es ni cómo ha llegado hasta allí. A medida que recupera la memoria, empieza a descubrir su misión: resolver el enigma de la misteriosa sustancia que provoca la extinción del sol. Deberá recurrir a sus conocimientos científicos y a sus ideas poco ortodoxas para salvar todo lo que hay en la Tierra de la extinción... pero una amistad inesperada significa que quizá no tenga que hacerlo solo.', trailer_url = 'https://www.youtube.com/watch?v=in-lUuKi0eE' WHERE id_api = 'tt12042730';

UPDATE Contenido SET id_tmdb = 786892, descripcion = 'En un mundo postapocalíptico donde todo ha perdido su valor, los pocos supervivientes se guían por la ley del más fuerte. Sin aprecio por la vida, lo único que despierta un brutal interés es la gasolina, sinónimo de poder y objetivo de bandas armadas hasta los dientes y sin escrúpulos. En este contexto conoceremos la  historia de la arrebatadoramente despiadada, salvaje y joven Furiosa, quien cae en manos de una horda de motoristas y debe sobrevivir a muchas pruebas mientras reúne los medios para encontrar el camino de vuelta a casa. Precuela de ''Mad Max: Furia en la carretera'' (2015).', trailer_url = 'https://www.youtube.com/watch?v=52dKmsFt6Ek' WHERE id_api = 'tt12037194';

UPDATE Contenido SET id_tmdb = 12445, descripcion = 'La segunda parte de la batalla final entre las fuerzas del bien y el mal. El juego nunca ha sido tan peligroso y nadie está a salvo. Se acerca el momento de la confrontación final entre Harry Potter y Lord Voldemort. Todo termina aquí…', trailer_url = 'https://www.youtube.com/watch?v=M1me0fEgYxY' WHERE id_api = 'tt1201607';

UPDATE Contenido SET id_tmdb = 64328, descripcion = 'Durante sus vacaciones en Los Ángeles, Walter, el fan número uno de los Teleñecos, y sus amigos Gary (Jason Segel) y Mary (Amy Adams) descubren que el petrolero Tex Richman (Chris Cooper) planea demoler el Teatro de los Teleñecos para perforar el solar y extraer el petróleo que se halla debajo. Para montar el Show más espectacular de los Teleñecos y recaudar los 10 millones de dólares necesarios para salvar el teatro, Walter, Mary y Gary buscan a la Rana Gustavo y a los Teleñecos: Fozzie trabaja en un casino de Reno con la banda de los Moopets, Peggy trabaja para Vogue como una diseñadora de tallas grandes, Animal ha ingresado en una clínica de Santa Bárbara para aprender a controlar su ira, y Gonzo es un magnate de la industria de la fontanería.', trailer_url = 'https://www.youtube.com/watch?v=dqp9bWEq8OQ' WHERE id_api = 'tt1204342';

UPDATE Contenido SET id_tmdb = 137093, descripcion = 'Con el paso del tiempo, cuatro hombres que fueron amigos en los años cincuenta siguieron caminos muy distintos. Cuando el único que quedaba soltero decide casarse (Douglas), se reúnen todos en Las Vegas para celebrarlo.', trailer_url = 'https://www.youtube.com/watch?v=TvK3m0wJutI' WHERE id_api = 'tt1204975';

UPDATE Contenido SET id_tmdb = 242512, descripcion = 'Después de que uno de sus amigos sea brutalmente asesinado por un malvado ente oscuro, un grupo de amigos juega a la ouija para intentar hablar con él desde el más allá. Sin embargo, lo que consiguen es despertar a un antiguo espíritu y a los demonios más salvajes. Los chicos tendrán que hacer frente a sus miedos más profundos e intentar acabar con ellos. Han descubierto que la ouija no es un juego de niños, es algo mucho más real.', trailer_url = 'https://www.youtube.com/watch?v=PcX-nom2UCM' WHERE id_api = 'tt1204977';

UPDATE Contenido SET id_tmdb = 13223, descripcion = 'Walt Kowalski, un veterano de la guerra de Corea, es un obrero jubilado del sector del automóvil. Su máxima pasión es cuidar de su más preciado tesoro: un coche Gran Torino de 1972. Es un hombre inflexible y con una voluntad de hierro, al que le cuesta trabajo asimilar los cambios que se producen a su alrededor. Sin embargo, las circustancias harán que se vea obligado a replantearse sus ideas.', trailer_url = 'https://www.youtube.com/watch?v=U_bZWFLTp-c' WHERE id_api = 'tt1205489';

UPDATE Contenido SET id_tmdb = 24122, descripcion = 'Cuando Sandy (Catherine Zeta-Jones), una sexy madre de 40 años, descubre que su marido la engaña, su mundo aparentemente perfecto se viene abajo. Sin pensárselo dos veces, se traslada a Nueva York con sus dos hijos con ánimo de rehacer su vida. Allí, conoce a Aram (Justin Bartha), un encantador licenciado universitario de 25 años que trabaja en la cafetería bajo el apartamento que alquila Sandy. Cuando Sandy encuentra trabajo, le pide a Aram que haga de canguro de sus hijos. La carrera de Sandy empieza a despegar y Aram se va convirtiendo en una parte cada vez más importante de su vida. Es divertido y sus hijos lo adoran. Muy pronto, esta improvisada familia va tomando forma y, aunque hay una larga lista de razones por las que no deberían estar juntos, se enamoran. Sandy y Aram se topan con la resistencia de familiares y amigos a su nueva relación y ambos tendrán que decidir si lo que tienen es algo simplemente divertido y temporal o puede tratarse de algo realmente duradero...', trailer_url = 'https://www.youtube.com/watch?v=xAstZiV1hIQ' WHERE id_api = 'tt1205535';

UPDATE Contenido SET id_tmdb = 101352, descripcion = 'Panchayat is a comedy-drama, which captures the journey of an engineering graduate Abhishek, who for lack of a better job option joins as secretary of a panchayat office in a remote village of Uttar Pradesh. Stuck between crazy villagers and a difficult village lifestyle Abhishek starts his job with the sole motivation of getting out of there as soon as possible, for which he even prepares for CAT.', trailer_url = 'https://www.youtube.com/watch?v=AHMEtNAZTP4' WHERE id_api = 'tt12004706';

UPDATE Contenido SET id_tmdb = 137094, descripcion = 'Jack Ryan (Chris Pine) es un veterano de guerra que lleva una doble vida: es un ejecutivo de Wall Street y además trabaja de forma encubierta como analista de la CIA. Cuando descubre un complot meticulosamente planeado para hundir la economía norteamericana y sembrar el caos en todo el mundo, deciden que él es el hombre más adecuado para impedirlo debido a su habilidad para interpretar datos globales. Jack tendrá que viajar a Moscú para intentar descubrir toda la verdad, porque de ello depende la vida de millones personas, pero eso implica moverse en un mundo en el que no puede fiarse de nadie.', trailer_url = 'https://www.youtube.com/watch?v=khtmgdS5Jz0' WHERE id_api = 'tt1205537';

UPDATE Contenido SET id_tmdb = 164457, descripcion = 'Russell Baze (Christian Bale) y su hermano menor Rodney (Casey Affleck) viven en el Rust Belt, una zona de los Estados Unidos con el índice de paro más alto del país debido a la desindustrialización. Russell trabaja en una acería a punto de cerrar, mientras que Rodney acaba de regresar de Iraq donde sirvió en el ejército. Ambos sueñan con marcharse para encontrar una vida mejor. Sin embargo, un cruel giro del destino hace que Russell ingrese en prisión y que su hermano se una a una violenta banda criminal.', trailer_url = 'https://www.youtube.com/watch?v=U4tX3519bJ0' WHERE id_api = 'tt1206543';

UPDATE Contenido SET id_tmdb = 522938, descripcion = 'Después de luchar contra sus demonios durante décadas, John Rambo vive ahora en paz en su rancho familiar en Arizona, pero su descanso se ve interrumpido cuando Gabriela, la nieta de su ama de llaves María, desaparece después de cruzar la frontera con México con el propósito de conocer a su padre biológico. Rambo, que con los años se ha convertido para Gabriela en una verdadera figura paterna, emprende un desesperado y peligroso viaje para encontrarla.', trailer_url = 'https://www.youtube.com/watch?v=3WcrgWJXCHg' WHERE id_api = 'tt1206885';

UPDATE Contenido SET id_tmdb = 107846, descripcion = 'Cuando un experto en seguridad se encuentra encarcelado en la prisión más secreta y segura del mundo, tiene que utilizar sus habilidades para escapar con ayuda desde el interior.', trailer_url = 'https://www.youtube.com/watch?v=HZ2NNH--TXs' WHERE id_api = 'tt1211956';

UPDATE Contenido SET id_tmdb = 26390, descripcion = 'Un veterano policía llamado Eddie Dugan se encuentra en la última etapa de su carrera, muy quemado por los años de servicio y a una semana vista de comenzar su jubilación y retirarse a pescar a una cabaña en Connecticut. Por otro lado, el oficial de estupefacientes Sal Procida tiene claro que no hay ninguna línea que no cruzara para proporcionar a su mujer y sus siete hijos una vida estable y en paz. La tercera parte en discordia es Clarence "Tango" Butler, un policía que siempre se ha rodeado de hombres leales y que tiene una “relación especial” con Caz, uno de los narcotraficantes más infames de Brooklyn que en esos momentos se encuentra en prisión.', trailer_url = 'https://www.youtube.com/watch?v=tAs4HGsQKVM' WHERE id_api = 'tt1210042';

UPDATE Contenido SET id_tmdb = 57201, descripcion = 'Estamos ante una prometedora producción repleta de aventuras, no exentas de humor, en la que el popular cowboy enmascarado, que nació como un relato radiofónico, tomará un rostro y una apariencia renovada por completo. Tonto, es un nativo americano, curtido en mil batallas, que narra los increíbles relatos que convirtieron a John Reid, en el brazo ejecutor de la ley, toda una leyenda de los Estados Unidos. Esta insólita pareja se verá obligada a trabajar unida y a luchar contra la codicia y el crimen en una época en la que todavía prima la ley del más fuerte.', trailer_url = 'https://www.youtube.com/watch?v=T0qlJ17IdwY' WHERE id_api = 'tt1210819';

UPDATE Contenido SET id_tmdb = 60308, descripcion = 'Billy Beane (Brad Pitt) es el gerente general del equipo de béisbol Atléticos de Oakland, que acaba de perder otra temporada más. Decidido a relanzar el equipo, y con la ayuda del joven economista Peter Brand (Jonah Hill), utilizará las estadísticas de éste para fichar a los jugadores que cree más oportunos. Un método que no es compartido por sus compañeros, ni por el entrenador del equipo Art Howe (Philip Seymour Hoffman).', trailer_url = 'https://www.youtube.com/watch?v=RAG74hfW4pM' WHERE id_api = 'tt1210166';

UPDATE Contenido SET id_tmdb = 284052, descripcion = 'La vida del famoso neurocirujano Stephen Strange cambia radicalmente cuando un accidente le impide el uso de sus manos y se ve forzado a buscar una cura en un misterioso enclave. Inmediatamente aprende que no solo es un sanatorio... es también el frente de batalla contra oscuras fuerzas, y debe elegir entre volver a su antigua vida o defender al mundo como el más poderoso hechicero del momento. Algunas secuencias o formas con luces parpadeantes pueden afectar a los espectadores fotosensibles.', trailer_url = 'https://www.youtube.com/watch?v=PqTILYUNU3s' WHERE id_api = 'tt1211837';

UPDATE Contenido SET id_tmdb = 44603, descripcion = 'Narra paralelamente la historia de tres personajes que han tenido algún tipo de contacto con la muerte: una periodista francesa, que estuvo a punto de morir durante el tsunami que asoló el Sudeste asiático en las Navidades de 2004; un niño inglés que pierde a su hermano gemelo en un terrible accidente y que busca respuestas, y un norteamericano que tiene el don de comunicarse con los muertos.', trailer_url = 'https://www.youtube.com/watch?v=wrmY77ENiEQ' WHERE id_api = 'tt1212419';

UPDATE Contenido SET id_tmdb = 314095, descripcion = 'En 1925 el explorador británico Percy Fawcett se aventuró en el Amazonas en busca de una antigua civilización, cuya existencia los europeos llevaban siglos intentando demostrar. La ciudad perdida se conocía como ciudad ''Z'', y en su búsqueda habían fallecido cientos de personas.  Sin embargo, la expedición desapareció en la selva, y nunca más se volvió a saber nada de ellos. Ninguna de las expediciones que han seguido los pasos de Fawcett ha conseguido hallar la ciudad ''Z''.', trailer_url = 'https://www.youtube.com/watch?v=vhWfzG6ddT8' WHERE id_api = 'tt1212428';

UPDATE Contenido SET id_tmdb = 34806, descripcion = 'Comedia romántica que narra la historia de una mujer que, cansada de no encontrar al hombre de sus sueños, decide tener un niño acudiendo a una clínica de inseminación artificial... para conocer al hombre de sus sueños justo el mismo día. Tras salir con varios hombres sin que el amor se consolidara, Zoe (Jennifer Lopez) ha decidido que no está dispuesta a seguir esperando a que aparezca su pareja perfecta. Empeñada en convertirse en madre, trama un plan y pide una cita médica, decidiendo hacerlo en solitario. Ese mismo día, Zoe se encuentra con Stan (Alex O''Loughlin), un candidato con muchas posibilidades. Zoe protege la incipiente relación escondiendo los primeros signos de su embarazo, dando lugar a situaciones que Stan no sabe cómo interpretar. Cuando Zoe, nerviosa, revela la razón de su extraño comportamiento, Stan reflexiona sobre su inusual futuro, decidiendo que desea formar parte de él...', trailer_url = 'https://www.youtube.com/watch?v=4VD3rBA6gjo' WHERE id_api = 'tt1212436';

UPDATE Contenido SET id_tmdb = 82633, descripcion = 'Adaptación de una novela de Matt Bondurant que se inspiró en hechos reales protagonizados por su propia familia. Narra las peripecias de una banda que traficaba con whisky casero cuando aún estaba vigente en Estados Unidos la Ley Seca (1920 a 1933).', trailer_url = 'https://www.youtube.com/watch?v=dMZQXJsRVx8' WHERE id_api = 'tt1212450';

UPDATE Contenido SET id_tmdb = 49013, descripcion = 'Rayo McQueen y su amigo, la grúa Mate, viajan al extranjero para participar en el primer Campeonato Mundial en el que se decidirá cuál es el coche más rápido del planeta. La primera etapa es Tokio (Japón), donde Mate tendrá que convertirse en un espía secreto al verse envuelto inesperadamente en un caso de espionaje internacional, que lo llevará a París y a Londres. También vivirán una aventura de proporciones épicas al viajar a Porto Corsa (Italia), para disputar el Campeonato. Sin embargo, los dos tendrán que renunciar a los placeres de la Riviera italiana -yates, playas y pasta al pesto- ya que Mate está muy ocupado con su labor de espía, mientras que McQueen compite contra los mejores coches del mundo.', trailer_url = 'https://www.youtube.com/watch?v=oGpIMRq1O3k' WHERE id_api = 'tt1216475';

UPDATE Contenido SET id_tmdb = 369972, descripcion = 'Cuenta la historia de la misión de la NASA que llevó al primer hombre a la luna, centrada en Neil Armstrong y el periodo comprendido entre los años 1961 y 1969. Un relato en primera persona, basado en la novela de James R. Hansen, que explora el sacrificio y el precio que representó, tanto para Armstrong como para Estados Unidos, una de las misiones más peligrosas de la historia.', trailer_url = 'https://www.youtube.com/watch?v=JnISFkVs4Q0' WHERE id_api = 'tt1213641';

UPDATE Contenido SET id_tmdb = 13805, descripcion = 'Película de los creadores de Casi 300 y Scary Movie, que en esta ocasión parodia películas de catástrofes, como "El día del mañana", así como otras películas de actualidad como "Hancock", "High School Musical", "Juno", "10.000", "Ironman", etc.', trailer_url = 'https://www.youtube.com/watch?v=tihG_2BSUqg' WHERE id_api = 'tt1213644';

UPDATE Contenido SET id_tmdb = 107985, descripcion = 'Cinco amigos de la infancia se reúnen después de 20 años porque uno de ellos está empeñado en volver a probar suerte en un maratón alcohólico que nunca pudieron llegar a completar. Gary King, un cuarentón que todavía no ha conseguido superar la adolescencia, convence a sus cuatro reacios amigos y los arrastra a su pueblo natal en un desesperado intento por llegar al famoso pub “The World’s End”. Pero mientras intentan reconciliar el presente con el pasado, empiezan a darse cuenta de que la auténtica lucha debe librarse por el futuro, y no solo el suyo, sino el de toda la humanidad. Llegar al pub “The World’s End” es ahora el último de sus problemas.', trailer_url = 'https://www.youtube.com/watch?v=nhCmDbJAPDg' WHERE id_api = 'tt1213663';

UPDATE Contenido SET id_tmdb = 62177, descripcion = 'Mérida, la indómita hija del Rey Fergus y de la Reina Elinor, es una hábil arquera que decide romper con una antigua costumbre, que es sagrada para los señores de la tierra: el gigantesco Lord MacGuffin, el malhumorado Lord Macintosh y el cascarrabias Lord Dingwall. Las acciones de Merida desencadenan el caos y la furia en el reino. Además, pide ayuda a una sabia anciana que le concede un deseo muy desafortunado. La muchacha tendrá que afrontar grandes peligros antes de aprender qué es la auténtica valentía.', trailer_url = 'https://www.youtube.com/watch?v=0gc36idTb3c' WHERE id_api = 'tt1217209';

UPDATE Contenido SET id_tmdb = 48838, descripcion = 'Tras salir de la cárcel, un criminal del sur de Londres intenta olvidar su pasado y cambiar de vida; se convierte entonces en el protector de una joven actriz que tiene ciertos problemas. Debut en la dirección de William Monahan, guionista de Infiltrados (Martin Scorsese, 2006) y ganador del Oscar por ese mismo trabajo.', trailer_url = 'https://www.youtube.com/watch?v=Hsm9jQcq0Ms' WHERE id_api = 'tt1213648';

UPDATE Contenido SET id_tmdb = 74998, descripcion = 'El profesor Will Gerard (Nicolas Cage) y su mujer Laura (January Jones) llevan una vida tranquila, pero una noche Laura es víctima de una brutal agresión sexual. En el hospital, un misterioso tipo llamado Simon (Guy Pearce) se dirige a Will y se ofrece para hacer justicia y ahorrarles el suplicio de tener que pasar por un proceso judicial. Will está tan alterado que de manera irreflexiva acepta la propuesta. a partir de ese momento se verá metido en una organización justiciera clandestina.', trailer_url = 'https://www.youtube.com/watch?v=bTAVMVJTrv0' WHERE id_api = 'tt1214962';

UPDATE Contenido SET id_tmdb = 24253, descripcion = 'Lisbeth Salander es buscada por la policía, tras verse envuelta en el asesinato de dos colaboradores de Millennium, a punto de sacar a la luz un escándalo sobre el comercio sexual en Suecia. Sin embargo, Lisbeth es más un ángel vengador que una víctima indefensa, y arremete con justa ira sobre los que la han herido... Segunda parte de la trilogía Millennium, adaptaciones de las exitosas novelas de Stieg Larsson.', trailer_url = 'https://www.youtube.com/watch?v=XeWyJuT-t0w' WHERE id_api = 'tt1216487';

UPDATE Contenido SET id_tmdb = 245916, descripcion = 'Basada en la historia real del periodista estadounidense Gary Webb, que evidenció conexiones de la CIA con el mundo de la droga, revelando al mundo cómo los barrios negros del país fueron inundados de crack en medio de un narcotráfico destinado a abastecer de dinero y armas a la CIA.', trailer_url = 'https://www.youtube.com/watch?v=kqS1pUC0X6c' WHERE id_api = 'tt1216491';

UPDATE Contenido SET id_tmdb = 30018, descripcion = 'Hye-ia es una madre soltera. Do-Joon, su hijo de 27 años, es tan ingenuo e inmaduro que sigue dependiendo de ella. Su conducta es estúpida o simplemente peligrosa. Es una constante fuente de preocupación para todos. Un día, aparece una joven muerta en un edificio abandonado y Do-joon es acusado de su muerte. Seleccionada por Corea del Sur como candidada al Oscar 2010 en la categoría de película de habla no inglesa.', trailer_url = 'https://www.youtube.com/watch?v=vTF5yCh9qXc' WHERE id_api = 'tt1216496';

UPDATE Contenido SET id_tmdb = 25195, descripcion = 'Una joven enamorada va a Dublín para pedirle a su novio que se case con ella. Lo hará siguiendo una tradición irlandesa, según la cual solo un día cada cuatro años -el 29 de febrero- una mujer puede proponer matrimonio a su novio con la certeza de que no será rechazada. Sin embargo, durante el viaje, una circunstancia imprevista la obligará a pedir ayuda a un rudo mesonero irlandés con el que tendrá que caminar campo a través si quiere llegar a tiempo para hacer su propuesta de matrimonio.', trailer_url = 'https://www.youtube.com/watch?v=wUwju8fo9tQ' WHERE id_api = 'tt1216492';

UPDATE Contenido SET id_tmdb = 44943, descripcion = 'Durante años ha habido casos documentados de avistamientos de OVNIS en todo el mundo. Pero en 2011, lo que hasta ese momento eran simples avistamientos resulta una terrible realidad cuando la Tierra es atacada por fuerzas desconocidas. Mientras todos son testigos de cómo caen las grandes ciudades del mundo, Los Ángeles se convierte en el último bastión de la humanidad en una batalla que nadie esperaba. Un sargento de la Marina (Aaron Eckhart) y su división son los que tendrán que definir los límites frente a un enemigo como jamás se habían encontrado.', trailer_url = 'https://www.youtube.com/watch?v=Yt7ofokzn04' WHERE id_api = 'tt1217613';

UPDATE Contenido SET id_tmdb = 41216, descripcion = 'Soren es un joven búho que tendrá que luchar heroicamente para salvar a su pueblo de las fuerzas del Mal. Vive en el bosque Tyto, donde siempre ha reinado la paz entre las lechuzas. En su lucha contra el Mal, emprende un largo y angustioso viaje para buscar el Gran Árbol Ga''Hoole. Cuando lo encuentra, él y sus amigos tendrán que someterse a pruebas y afrontar desafíos inimaginables. Si son capaces de aprender de sus jefes y unos de otros, pronto se convertirán en verdaderas lechuzas de Ga''Hoole: honradas y valientes, sabias y sinceras.', trailer_url = 'https://www.youtube.com/watch?v=20lcY7I-CBc' WHERE id_api = 'tt1219342';

UPDATE Contenido SET id_tmdb = 51876, descripcion = 'Un escritor (Bradley Cooper), que sufre una crisis de creatividad, prueba un día una nueva droga que lo pone en condiciones de usar al máximo todas sus facultades mentales; es una especie de píldora inteligente gracias a la cual consigue triunfar en Nueva York. Un poderoso financiero de Wall Street (De Niro) siente una extraordinaria curiosidad por averiguar qué se esconde detrás de tanto éxito...', trailer_url = 'https://www.youtube.com/watch?v=4TLppsfzQH8' WHERE id_api = 'tt1219289';

UPDATE Contenido SET id_tmdb = 315837, descripcion = 'Tras esquivar la muerte, Major Kusanagi resucita como cíborg y encabeza un equipo de caza de ciberterroristas. Pero un pirata informático se reserva otros planes.', trailer_url = 'https://www.youtube.com/watch?v=8nfFMf6Hg9A' WHERE id_api = 'tt1219827';

UPDATE Contenido SET id_tmdb = 22824, descripcion = 'Thriller sobrenatural ambientado en Alaska en el que una mujer investiga una serie de misteriosas desapariciones ocurridas en el lugar durante los últimos 40 años. A finales del año 2000, los pacientes de la terapeuta Abbey Tyler, bajo hipnosis, reflejaron comportamientos que sugerían encuentros con seres no humanos. Antes de dormir, todos ellos aseguraban haber visto un búho que les observaba desde fuera de la ventana. Y despertaban completamente paralizados, escuchando ruidos terroríficos que provenían de fuera de la habitación. Los recuerdos posteriores se sumían en la oscuridad. La doctora prosiguió con sus investigaciones, descubriendo que la desaparición de personas y sucesos extraños en la región se remontaba a los años 60.', trailer_url = 'https://www.youtube.com/watch?v=VX3ms4i3By4' WHERE id_api = 'tt1220198';

UPDATE Contenido SET id_tmdb = 35791, descripcion = 'En un mundo asolado por un virus infeccioso que convierte a sus víctimas en muertos vivientes, Alice continúa buscando supervivientes para ponerlos a salvo. Su batalla a muerte con la Corporación Umbrella llega a alturas insospechadas, pero Alice, inesperadamente, recibe ayuda de una vieja amiga. Nuevas pistas, con la promesa de un paraíso a salvo de muertos vivientes, los conduce hasta Los Ángeles, pero cuando llegan, la ciudad está infectada con miles de muertos vivientes. Alice y sus compañeros están a punto de caer en una trampa mortal.', trailer_url = 'https://www.youtube.com/watch?v=SRRN6MvCdeg' WHERE id_api = 'tt1220634';

UPDATE Contenido SET id_tmdb = 14756, descripcion = 'Foshan, años treinta. Ip Man, respetado maestro de Wing Chun, combina el estudio de las artes marciales con los combates ocasionales a los que se ve forzado por parte de sus admiradores. Son tiempos de prosperidad a los que la guerra con Japón amenaza con poner fin. Con la ocupación estallará la tragedia e Ip Man se verá obligado a defender el honor de su pueblo. Ip Man (o también conocido como Yip Man), fue maestro y mentor de Bruce Lee.', trailer_url = 'https://www.youtube.com/watch?v=3IUR6P5VwGo' WHERE id_api = 'tt1220719';

UPDATE Contenido SET id_tmdb = 38317, descripcion = 'El bondadoso Griffin Keyes es uno de los cuidadores más queridos del Zoológico Franklin Park, pero se siente más cómodo con los animales que con las hembras de su especie, como lo demuestra su fallida propuesta de matrimonio a la egocéntrica Stephanie hace varios años. Los animales han escuchado a Griffin añorarla durante años y, tras su reaparición en su vida, deciden ayudarlo a reavivar la relación y convertirse en el macho alfa que ella desea que sea. Sin darse cuenta, revelan su capacidad secreta para hablar y, tras el impacto inicial de Griffin, le enseñan las reglas del cortejo, al estilo animal. Sorprendentemente, el consejo de los animales funciona de verdad y Griffin está a punto de conseguir todo lo que siempre ha soñado... ¿o no?', trailer_url = 'https://www.youtube.com/watch?v=pNJxxRi7AeE' WHERE id_api = 'tt1222817';

UPDATE Contenido SET id_tmdb = 7317, descripcion = 'Relata las aventuras (más bien desventuras) de Will y sus tres nuevos amigos. La historia comienza con la llegada al instituto de Will, que ha sido trasladado de otra escuela. En un intento de integrarse y conocer gente "guay" acaba uniéndose a Simon, Jay y Neil, que no son precisamente los más populares del instituto pero que tampoco son unos nerds antisociales. El ansia por perder la virginidad, el permiso de conducir que querías conseguir para ligar, mas para luego descubrir que tu padre te ha regalado un coche cutre; un corazón roto por el primer amor, o simplemente esas salidas entre amigos que suelen acabar en nada pero que no dejan de ser divertidas, son parte del día a día de estos cuatro amigos.', trailer_url = 'https://www.youtube.com/watch?v=T1Wwtj-YF7w' WHERE id_api = 'tt1220617';

UPDATE Contenido SET id_tmdb = 1419, descripcion = 'Un escritor de novelas se une a una detective de Nueva York para resolver un caso de un asesino que emula a otro de la misma calaña, lamentablemente la relación entre ambos no es de lo mejor.', trailer_url = 'https://www.youtube.com/watch?v=xjrObBtzGYg' WHERE id_api = 'tt1219024';

UPDATE Contenido SET id_tmdb = 700391, descripcion = 'Después de un catastrófico accidente en un planeta desconocido, el piloto Mills descubre rápidamente que realmente está varado en la Tierra… hace 65 millones de años. Ahora, con solo una oportunidad de rescate, Mills y la otra única superviviente, Koa, deberán abrirse camino a través del desconocido territorio plagado con peligrosas criaturas prehistóricas en una épica lucha por sobrevivir.', trailer_url = 'https://www.youtube.com/watch?v=YeKgkbYSUhA' WHERE id_api = 'tt12261776';

