UPDATE Contenido SET id_tmdb = 698948, descripcion = 'Basada en la historia real, "Trece vidas" es el relato del rescate de un equipo de fútbol de la cueva de Tham Luang, en Tailandia, tras quedar atrapado por las lluvias torrenciales y peligrosas inundaciones.', trailer_url = 'https://www.youtube.com/watch?v=czLULPI8LKA' WHERE id_api = 'tt12262116';

UPDATE Contenido SET id_tmdb = 114479, descripcion = '"Star Wars: The Acolyte" es una serie ambientada en los últimos días de la era de la Alta República, cien años antes de "La amenaza fantasma". La trama sigue a una respetada Maestra Jedi que se enfrenta a una serie de crímenes y a una peligrosa guerrera de su pasado. A medida que se investigan los crímenes, se revela un camino oscuro donde fuerzas siniestras están en juego y nada es lo que parece.', trailer_url = 'https://www.youtube.com/watch?v=H1F4PIHwB0I' WHERE id_api = 'tt12262202';

El dúo se va enfrentando a peligros físicos y emocionales, entre los que se incluyen batallas con brujas de la Fuerza, viejos Jedi caídos, entre otros enemigos. Todo el viaje y toda la investigación culmina con un enfrentamiento que cambiará el destino de los dos protagonistas.');

UPDATE Contenido SET id_tmdb = 32823, descripcion = 'Aaron Greenberg es un empleado de una compañía discográfica que dispone de dos días para arrastrar a la estrella del rock Aldous Snow, empeñada en no cooperar, para dar un concierto en Hollywood. Aldous es un músico brillante y un adicto al sexo. Harto del dinero y de que nadie le lleve la contraria, busca el significado de la vida. Cuando se entera de que su gran amor está en California, decide hacerlo todo para recuperarlo. El concierto se acerca y el representante de la discográfica se ve obligado a recorrer un campo de minas, poblado por camellos londinenses, barriobajeros neoyorquinos y bailarinas de Las Vegas, antes de entregar al cantante sano y salvo. Puede que tenga que rogar, convencer, mentir e irse de juerga con Aldous, pero si de Aaron depende, llegará al “Greek Theatre” pase lo que pase.', trailer_url = 'https://www.youtube.com/watch?v=SsstDm-MZxw' WHERE id_api = 'tt1226229';

UPDATE Contenido SET id_tmdb = 5917, descripcion = 'Harry Mills llega a Beverly Hills junto a su mujer y sus hijos para ocupar el puesto de nuevo director del instituto y cuidar de su madre. Allí se encontrará con sus viejos compañeros, así que los hijos de estos, sus nuevos alumnos y alumnas. Entre los más populares se encuentran Naomi Clark, la hija de Tracy, y su novio Ethan Ward, que acabará convirtiéndose en el rival del hijo adoptivo de Harry, Dixon. Sin embargo, esta no es la única situación comprometida a la que se enfrentará Harry, ya que de pronto aparece un joven que insiste en que es hijo suyo y de Tracy. Por otro lado está la mejor amiga de Naomi, Adrianna, que caerá en el mundo de las drogas cuando estas son filtradas en el instituto. Harry deberá afrontar la situación para evitar que el consumo de drogas se generalice, y conseguir que el orden, la disciplina y el bienestar regrese a los pasillos del West Beverly Hills.', trailer_url = 'https://www.youtube.com/watch?v=C3jnnWNHMbY' WHERE id_api = 'tt1225901';

UPDATE Contenido SET id_tmdb = 21641, descripcion = 'El Leeds United vive la época de más éxitos de su historia, aunque con un juego algo sucio. El entrenador Brian Clough acepta el reto de entrenar al equipo, e intentará cambiar el estilo de juego que le imprimió el anterior entrenador: Don Revie.', trailer_url = 'https://www.youtube.com/watch?v=RVnHpLho18c' WHERE id_api = 'tt1226271';

UPDATE Contenido SET id_tmdb = 12201, descripcion = 'Thomas Craven es un veterano detective de homicidios del departamento de policía de Boston y padre viudo. Cuando su única hija, Emma de 24 años, es asesinada en las escaleras de su casa, todo el mundo supone que él era el objetivo. Pero pronto sospecha lo contrario y se embarca en la misión de averiguar la vida secreta de su hija y el por qué de su asesinato. Su investigación le lleva a un peligroso mundo de encubrimientos corporativos, lleno de engaños, connivencia gubernamental y crímenes. Ahí conocerá a un misterioso agente del gobierno, Darius Jedburgh, que ha sido enviado para eliminar las pruebas del asesinato. La solitaria búsqueda de Craven de respuestas sobre la muerte de su hija se convierte en una odisea de descubrimiento emocional y redención.', trailer_url = 'https://www.youtube.com/watch?v=BCPMW6S7t6w' WHERE id_api = 'tt1226273';

