UPDATE Contenido SET id_tmdb = 48289, descripcion = 'En 1965, durante una misión secreta en Berlín oriental, tres jóvenes agentes del Mossad (servicio de inteligencia israelí) capturan a un importante criminal de guerra nazi, antiguo médico conocido por sus sádicos experimentos durante la II Guerra Mundial en el campo de Birkenau. La misión no salió como estaba planeada, pero ellos se convirtieron en héroes. Sin embargo, treinta años después, en 1997, algo sucede que cambia de nuevo la versión de aquella misión.', trailer_url = 'https://www.youtube.com/watch?v=pAXtJebf8Dc' WHERE id_api = 'tt1226753';

