UPDATE Contenido SET id_tmdb = 19833, descripcion = 'Todo empieza cuando el presidente de los Estados Unidos y el primer ministro británico deciden iniciar una guerra. No todo el mundo cree que sea una buena idea. Pero cuando Simon Foster, el secretario de Estado británico, respalda accidentalmente la guerra en horario de máxima audiencia en la televisión, se gana sin quererlo muchos amigos en Washington DC.', trailer_url = 'https://www.youtube.com/watch?v=NSTdPxndUzE' WHERE id_api = 'tt1226774';

