UPDATE Contenido SET id_tmdb = 5739, descripcion = 'Dr. Horrible''s Sing-Along Blog es un cortometraje musical de tragicomedia estrenado en 2008 y producido exclusivamente para su distribución por Internet. Cuenta la historia del Dr. Horrible, un aspirante a supervillano; el Capitán Hammer, su némesis; y Penny, el amor de ambos.', trailer_url = 'https://www.youtube.com/watch?v=mXI3obHfwgU' WHERE id_api = 'tt1227926';

UPDATE Contenido SET id_tmdb = 696506, descripcion = 'Mickey 17, un miembro de la tripulación ''expendable'' (prescindible) enviado a un planeta helado para colonizarlo, se niega a dejar que su clon de reemplazo, Mickey 18, tome su lugar... Adaptación del libro original de Edward Ashton.', trailer_url = 'https://www.youtube.com/watch?v=vzvAieKSWqA' WHERE id_api = 'tt12299608';

UPDATE Contenido SET id_tmdb = 56292, descripcion = 'El agente Ethan Hunt, acusado de un atentado terrorista con bombas contra el Kremlin, es desautorizado junto con toda la organización, al poner en marcha el presidente el llamado ''Protocolo fantasma''. Abandonado a su suerte y sin recursos, el objetivo de Ethan es rehabilitar el buen nombre de su agencia e impedir un nuevo ataque. Pero emprende esta misión con un equipo formado por fugitivos, cuyos motivos personales no conoce bien.', trailer_url = 'https://www.youtube.com/watch?v=9MMPQ88NDWY' WHERE id_api = 'tt1229238';

UPDATE Contenido SET id_tmdb = 41402, descripcion = '"Let Me In" se centra en un niño triste llamado Owen, maltratado por sus compañeros de clase y abandonado por sus padres divorciados; sin embargo, algo cambiará en la solitaria vida de Owen cuando conozca a una nueva y misteriosa vecina llamada Abby, que vive con su silencioso padre, y con quien entablará una particular amistad.', trailer_url = 'https://www.youtube.com/watch?v=x32TCsuIpfE' WHERE id_api = 'tt1228987';

