UPDATE Contenido SET id_tmdb = 38684, descripcion = 'Jane Eyre, una muchacha educada en un orfanato y de difícil infancia, es contratada por Edward Rochester para trabajar como institutriz de una niña en Thornfield House. La aislada y sombría mansión, así como la inicial frialdad del dueño de la casa ponen a prueba la fortaleza de la joven. Sin embargo, poco a poco empieza a enamorarse de él.', trailer_url = 'https://www.youtube.com/watch?v=kaVFI5aRSjw' WHERE id_api = 'tt1229822';

UPDATE Contenido SET id_tmdb = 22897, descripcion = 'Jane, madre de tres hijos ya adultos, es la propietaria de un restaurante-pastelería de Santa Barbara. A pesar de estar divorciada desde hace años, mantiene una amistosa relación con su ex-marido Jake. Sin embargo, cuando tienen que viajar juntos para asistir a la graduación de su hijo, su relación se estropea. Al casarse Jake con una mujer más joven, Jane se convierte de pronto en "la otra". Y de este embrollo no podrá librarse ni siquiera Adam, un arquitecto contratado para renovar la cocina de Jane.', trailer_url = 'https://www.youtube.com/watch?v=mavEOkgaBl4' WHERE id_api = 'tt1230414';

UPDATE Contenido SET id_tmdb = 23398, descripcion = 'Las ardillas más famosas y divertidas del cine regresan a la gran pantalla para protagonizar una nueva aventura. En ella, Alvin y sus compañeros deben enfrentarse a la presión de la escuela, a los problemas de la celebridad y a un grupo de chicas ardilla que les está haciendo la competencia', trailer_url = 'https://www.youtube.com/watch?v=5UpIz48hZmA' WHERE id_api = 'tt1231580';

UPDATE Contenido SET id_tmdb = 23048, descripcion = 'Tres amigos del instituto que llevan tiempo sin verse deciden pasar un fin de semana en un hotel de montaña en el que estuvieron 20 años antes y del que guardan un recuerdo inolvidable. Cuando llegan al lugar se dan cuenta de que nada es como recordaban, pero todo cambia cuando deciden probar el jacuzzi y descubren que es una máquina del tiempo, que los transporta hasta los años 80, concretamente a 1986. Inicialmente creerán que deben hacer exactamente lo mismo que hicieron anteriormente, pero luego se darán cuenta de que están ante una oportunidad única de cambiar sus vidas. Sólo hay un pequeño problema: el futuro no es tan sencillo de modificar como piensan...', trailer_url = 'https://www.youtube.com/watch?v=Qkgz_lgXPPI' WHERE id_api = 'tt1231587';

