UPDATE Contenido SET id_tmdb = 87428, descripcion = 'Un padre que pretende controlar la inminente boda de su hijo se muda a vivir con él y su novia.', trailer_url = 'https://www.youtube.com/watch?v=4P6GpzCoUSU' WHERE id_api = 'tt1232200';

UPDATE Contenido SET id_tmdb = 103540, descripcion = 'Percy Jackson emprende una peligrosa misión. Dejando atrás a los monstruos y burlando a los dioses, recorrerá Estados Unidos para devolver el Rayo Maestro de Zeus y evitar la guerra. Con ayuda de sus compañeros de misión, Annabeth y Grover, el viaje de Percy lo acercará más a las respuestas que busca: cómo encajar en un mundo que le es ajeno y si logrará entender su destino.', trailer_url = 'https://www.youtube.com/watch?v=-TvOvGMPnco' WHERE id_api = 'tt12324366';

UPDATE Contenido SET id_tmdb = 64688, descripcion = 'Dos jóvenes agentes de la ley se hacen pasar por alumnos de instituto para desarticular una red de narcotráfico. Schmidt y Jenko fueron enemigos en el colegio pero, cuando años más tarde se reencuentran en la academia de policía, terminan haciéndose amigos. Puede que no sean los mejores agentes, pero les llega su gran oportunidad de demostrar lo que valen cuando se unen a la unidad de la policía secreta Jump Street, comandada por el capitán Dickson. Entonces cambian sus armas e insignias por las mochilas y utilizan su apariencia juvenil para infiltrarse en un instituto. El problema es que los jóvenes de hoy no se parecen en nada a los de años atrás, y Schmidt y Jenko descubren que todo lo que creían saber sobre la adolescencia, el sexo, las drogas y el rock and roll era completamente erróneo.', trailer_url = 'https://www.youtube.com/watch?v=RK2MwSMjjFw' WHERE id_api = 'tt1232829';

UPDATE Contenido SET id_tmdb = 22804, descripcion = 'El Agente Especial Strahm está muerto, y el Detective Hoffman es el sucesor de Jigsaw y su juego macabro. Sin embargo, cuando la Brigada de Investigación Criminal comienza a estrechar el cerco a Hoffman, lo forzarán a poner en marcha el juego complejo de Jigsaw, y por fin a entenderlo por completo... Sexta entrega de la sangrienta saga Saw.En octubre de 2009 la distribuidora decidió cancelar su estreno en España a causa de la controvertida clasificación X que recibió del Ministerio de Cultura. Finalmente, la película llega a las salas españolas en octubre de 2010, con un montaje específico de los productores, que han eliminado 3 minutos de metraje, suprimiendo las escenas más violentas de la cinta.', trailer_url = 'https://www.youtube.com/watch?v=-zFvxEAdakE' WHERE id_api = 'tt1233227';

UPDATE Contenido SET id_tmdb = 24469, descripcion = 'Mia es una adolescente de quince años de edad que sufre un verdadero colapso cuando se entera de que su madre está saliendo con un chico. Lo peor es que la madre insiste en traerle a casa, lo cual ya es demasiado para Mia, que está viviendo una juventud desencantada.', trailer_url = 'https://www.youtube.com/watch?v=xf5VOvB5MHA' WHERE id_api = 'tt1232776';

UPDATE Contenido SET id_tmdb = 103516, descripcion = 'El capitán Pike, el oficial científico Spock y Number One exploran nuevos mundos alrededor de la galaxia a bordo de la USS Enterprise.', trailer_url = 'https://www.youtube.com/watch?v=2KJz0JRcNE8' WHERE id_api = 'tt12327578';

UPDATE Contenido SET id_tmdb = 38543, descripcion = 'Inglaterra, principios del siglo XIII. El 15 de junio de 1215 y, tras una dura negociación, el Rey Juan de Inglaterra, se ve obligado a firmar ciertas peticiones de los señores feudales que pretenden poner límites al uso despótico del poder por parte del Rey. El documento resultante es la Carta Magna. Un hecho insólito para un rey medieval, que veía cómo aquellos a quienes gobernaba y que debían serle fieles, le arrancaban sus prerrogativas reales. Sin embargoi, cuando hubo reunido un fuerte ejército, el rey Juan se negó a cumplir el acuerdo y se dispuso a eliminar a todos los que habían firmado la Carta Magna, poniendo a Inglaterra al borde de una guerra civil: la Primera Guerra de los Barones (1215-1217). Juan quiso castigar a aquellos que lo humillaron, entre ellos un grupo de caballeros templarios atrincherados en el castillo de Rochester, que lucharán para resistir el asedio de las tropas del rey Juan.', trailer_url = 'https://www.youtube.com/watch?v=UkK1H4uHXqA' WHERE id_api = 'tt1233301';

UPDATE Contenido SET id_tmdb = 60747, descripcion = 'Remake de la película de 1984 de John Milius que narraba cómo ocho adolescentes huían a las montañas cuando su ciudad es invadida por un grupo de nacionalistas extranjeros. Bajo el nombre del equipo de fútbol del instituto, los Wolverines, estos adolescentes libran una incesante batalla con el fin de defender a sus padres, amigos y a su propio país.', trailer_url = 'https://www.youtube.com/watch?v=lXVQ8rWo8wc' WHERE id_api = 'tt1234719';

UPDATE Contenido SET id_tmdb = 95479, descripcion = 'La vida de Itadori cambia para siempre cuando, para salvar a un compañero de clase, se come el dedo de Ryomen Sukuna y absorbe una poderosa maldición.', trailer_url = 'https://www.youtube.com/watch?v=aPBUUJbrAWo' WHERE id_api = 'tt12343534';

Guiado por los hechiceros, Yuji Itadori se une a la Escuela Técnica de Hechicería de Tokio, una organización que se enfrenta a las maldiciones. Con la ayuda de su profesor, Satoru Gojo, Itadori hace amistad con Megumi Fushiguro y Nobara Kurosaki, ambos estudiantes de primer año como él.');

UPDATE Contenido SET id_tmdb = 10313, descripcion = 'El periodista Bob Wilton (Ewan McGregor) está detrás de su próxima gran historia, cuando se cruza con Lyn Cassady (George Clooney), un personaje misterioso que proclama ser parte de una unidad experimental secreta del Ejército de los Estados Unidos. Según Cassady, este Ejército de la Nueva Tierra está cambiando las tácticas de combate. Se trata de una legión de ‘Guerreros Monje’ que posee una serie de poderes sin parangón, tales como leer la mente del enemigo, atravesar paredes o incluso matar una cabra con tan sólo mirarla fijamente.', trailer_url = 'https://www.youtube.com/watch?v=2qmdTQxvSHg' WHERE id_api = 'tt1234548';

UPDATE Contenido SET id_tmdb = 97020, descripcion = 'La película comienza con la trágica muerte del agente Murphy, que es asesinado por unos brutales criminales haciéndole saltar por los aires. Un equipo de científicos y doctores reconstruirán sus restos y lo convertirán en un organismo cibernético imparable, programado para combatir el crimen sin descanso. De esta forma crearán a Robocop. Pero lo que nadie se imagina es que bajo su nueva carcasa cibernética, Robocop vive atormentado por los recuerdos de su vida anterior acompañados de pesadillas de su muerte a manos de los despiadados asesinos.', trailer_url = 'https://www.youtube.com/watch?v=8KpSKzT-Fh0' WHERE id_api = 'tt1234721';

UPDATE Contenido SET id_tmdb = 23488, descripcion = 'Dorian Gray (Ben Barnes) es un joven aristócrata muy atractivo que, después de haber pasado una solitaria adolescencia en el campo, regresa a Londres, donde ha heredado una mansión. Atraído por la vida nocturna, se sumerge en ella de la mano de Lord Henry Wottom (Colin Firth), que lo conduce a los antros más recónditos y sórdidos de la ciudad. Al joven le fascina el estilo de vida decadente y amoral de Wotton. Por otra parte, su obsesión por alcanzar la eterna juventud lo impulsa a hacer un pacto diabólico: él se mantendrá siempre joven, pero las huellas del paso del tiempo y de sus terribles delitos, es decir, su degradación física y moral se reflejarán en un retrato que le ha hecho su amigo el pintor Basil Hallward (Ben Chaplin).', trailer_url = 'https://www.youtube.com/watch?v=DuqFwyI5kwY' WHERE id_api = 'tt1235124';

UPDATE Contenido SET id_tmdb = 21575, descripcion = 'Condenado a seis años de prisión, Malik El Djebena no sabe leer ni escribir. Cuando llega a la cárcel completamente solo, parece más joven y frágil que los demás presos. Tiene 19 años. Arrinconado por el cabecilla de la banda de corsos que domina la prisión, le encomiendan una serie de “misiones” que debe cumplir para hacerse más fuerte y ganarse la confianza del líder. Pero Malik es valiente y aprende rápido, e incluso se atreve a hacer sus propios planes.', trailer_url = 'https://www.youtube.com/watch?v=l69ARbQt-Ko' WHERE id_api = 'tt1235166';

UPDATE Contenido SET id_tmdb = 98357, descripcion = 'Siete años después de haberse visto obligado a dejar su puesto en la policía de Nueva York por un escándalo producido por un desafortunado tiroteo, el detective privado Billy Taggart (Mark Wahlberg) es contratado por el alcalde de la ciudad, Nicholas Hostetler (Russell Crowe), para que investigue la presunta infidelidad de su mujer (Catherine Zeta-Jones). Pero cuando el supuesto amante de ésta aparece muerto, las cosas se complican mucho más de lo que Taggart podría haber previsto. El detective, que no tarda en descubrir que no era más que un peón en una partida mayor, se adentra en la zona gris que une los mundos del crimen, la política y los negocios.', trailer_url = 'https://www.youtube.com/watch?v=oJWfM40Sklc' WHERE id_api = 'tt1235522';

UPDATE Contenido SET id_tmdb = 8358, descripcion = 'Paul Ekman, un psicólogo capaz de detectar si la gente miente o dice la verdad analizando la expresión de su cara, sus gestos y su voz, usa ese don para resolver casos criminales. Considerado por la revista ''Time'' una de las 100 personas más influyentes del mundo, sus experiencias y sus libros le serán muy útiles al ex policía y doctor Cal Lightman, un experto en el engaño que colabora con la policía y otras agencias de seguridad para resolver enrevesados casos criminales. Este "detector de mentiras humano" cuenta con la ayuda de una psicóloga clínica, la doctora Gillian Foster, que aporta a la investigación sus conocimientos académicos. El trabajo de Lightman se hace imprescindible para todos los cuerpos policiales y agencias gubernamentales.', trailer_url = 'https://www.youtube.com/watch?v=qahEZM_Fd6Y' WHERE id_api = 'tt1235099';

