UPDATE Contenido SET id_tmdb = 791373, descripcion = 'Con la determinación de asegurar que el sacrificio definitivo de Superman no fue en vano, Bruce Wayne une fuerzas con Diana Prince para reclutar a un equipo de metahumanos que protejan el mundo de una amenaza inminente de proporciones catastróficas. La tarea es más difícil de lo que Bruce imaginaba, ya que cada uno de los reclutas deberá enfrentarse a sus propios demonios para trascender aquello que los detenía, para unirse y formar de manera definitiva una liga de héroes sin precedentes. Ahora unidos, Batman, Wonder Woman, Aquaman, Cyborg y Flash deberán salvar al planeta de la amenaza de Steppenwolf, DeSaad y Darkseid, antes de que sea demasiado tarde.', trailer_url = 'https://www.youtube.com/watch?v=ui37YKQ9AC4' WHERE id_api = 'tt12361974';

UPDATE Contenido SET id_tmdb = 38319, descripcion = 'Thadeous se ha pasado la vida viendo cómo Fabious, su perfecto hermano mayor, se ha embarcado en tremendas confrontaciones y se ha hecho con el corazón de su pueblo. Cansado de que la aventura, la admiración y el trono no llamen a su puerta, se ha resignado a una vida dedicada a fumar hierba de brujo, beber buen alcohol y seducir a doncellas desvergonzadas. Pero cuando Belladona, la prometida de Fabious, es secuestrada por el malvado brujo Leezar, el rey da un ultimátum a su hijo menor: si no mueve el trasero y la rescata, se acabaron los fondos. Nada convencido de su misión, Thadeous se une a Fabious en un peligroso viaje para liberar a la princesa. Les acompaña Isabel, una misteriosa guerrera con un peligroso objetivo. Los hermanos se enfrentarán a terribles criaturas y a caballeros carentes de honor antes de llegar a Belladona.', trailer_url = 'https://www.youtube.com/watch?v=Z7-XsfytPRU' WHERE id_api = 'tt1240982';

