UPDATE Contenido SET id_tmdb = 96462, descripcion = 'Una historia sobre un empleado de una sala psiquiátrica y una mujer, con un trastorno de personalidad antisocial, que es una escritora popular de libros infantiles. Un hombre que niega el amor y una mujer que no conoce el amor desafían el destino y se enamoran, encontrando sus almas e identidades en el proceso.', trailer_url = 'https://www.youtube.com/watch?v=89i-Fn2CqQg' WHERE id_api = 'tt12451520';

UPDATE Contenido SET id_tmdb = 705996, descripcion = 'Hae-Joon, un veterano detective, investiga la sospechosa muerte de un hombre en la cima de una montaña. Pronto, comenzará a sospechar de Sore, la mujer del difunto, mientras la atracción que siente por ella le desestabilizará.', trailer_url = 'https://www.youtube.com/watch?v=c43Rus2Pnnc' WHERE id_api = 'tt12477480';

UPDATE Contenido SET id_tmdb = 23483, descripcion = 'Dave Lizewski es un estudiante de instituto que pasa desapercibido por todos, aficionado a los cómics, de donde saca un día la idea de convertirse en un superhéroe, aunque no tenga superpoderes, no haya seguido un duro entrenamiento y ni siquiera tenga una razón significativa para ello. Pero la vida de Dave cambiará para siempre cuando se encuentre con un par de locos vigilantes -la terremoto de 11 años Hit Girl y su padre, Big Daddy- y forje amistad con otro joven luchador contra el crimen, Red Mist. Y cuando todos se tengan que enfrentar al jefe de la mafia local, Frank D''Amico, sus alianzas y sus verdaderas habilidades serán puestas a prueba.', trailer_url = 'https://www.youtube.com/watch?v=hLFcik85gMY' WHERE id_api = 'tt1250777';

UPDATE Contenido SET id_tmdb = 716612, descripcion = 'Biopic de Lady Di que cuenta la historia de un fin de semana crucial a principios de los años 90, cuando la princesa Diana decidió que su matrimonio con el príncipe Carlos no estaba funcionando, y que necesitaba desviarse de un camino que la había puesto en primera fila para algún día ser reina. El drama tiene lugar durante tres días, en una de sus últimas vacaciones de Navidad en la Casa de Windsor en su finca de Sandringham en Norfolk, Inglaterra.', trailer_url = 'https://www.youtube.com/watch?v=INL2NhrM1GY' WHERE id_api = 'tt12536294';

UPDATE Contenido SET id_tmdb = 53182, descripcion = 'La historia se ambienta en el año 490 a.C., unos diez años antes de la batalla de las Termópilas. El general griego Temistocles intenta unir las polis griegas para combatir a los persas invasores. Él dirigirá las tropas griegas que se enfrentarán con los persas en la decisiva batalla de Maratón. La derrota persa impedirá la invasión del país.', trailer_url = 'https://www.youtube.com/watch?v=i14coKhHnl0' WHERE id_api = 'tt1253863';

UPDATE Contenido SET id_tmdb = 29917, descripcion = 'Cinta de tensión psicológica que nos sitúa en un escenario opresivo donde un grupo de candidatos competirán por hacerse con un jugoso puesto de trabajo. Las reglas son simples: nada de preguntas, nada de salir de la habitación y, por último, nada de estropear el folio del examen (un folio que, por otra parte, está en blanco). Tienen 80 minutos...', trailer_url = 'https://www.youtube.com/watch?v=a-KGruTCg0I' WHERE id_api = 'tt1258197';

UPDATE Contenido SET id_tmdb = 37958, descripcion = 'Enloquecido por el poder, el brutal rey Hiperión ha declarado la guerra a los hombres. Después de reunir a un ejército sediento de sangre formado por soldados que él mismo mandó desfigurar, Hiperión quema Grecia mientras busca un arma de poder inconcebible: el legendario arco Epiro, hecho por Ares en el Olimpo. El hombre que posea ese arco podrá liberar a los Titanes, que están encerrados en el monte Tártaro desde el principio de los tiempos, y claman venganza. Sin embargo, en manos de Hiperión, el arco significaría la destrucción de la raza humana y la aniquilación de los dioses. La ley prohíbe que los dioses se entrometan en los conflictos humanos, y nada pueden hacer para detener al rey. Pero la esperanza renace cuando Zeus encomienda al campesino Teseo la misión de acabar con Hiperión.', trailer_url = 'https://www.youtube.com/watch?v=pE3yR8bZ1pY' WHERE id_api = 'tt1253864';

UPDATE Contenido SET id_tmdb = 46738, descripcion = 'Jeanne y Simon Marwan son dos mellizos cuya madre, que lleva mucho tiempo sin hablar, está a punto de morir. Pero, antes del fatal desenlace, les da dos cartas que deben ser entregadas a un padre al que creían muerto y a un hermano cuya existencia desconocían. Ambos emprenderán un viaje al Líbano para localizarlos y encontrar respuestas a su existencia. Basada en una obra de teatro de Wajdi Mouawad.', trailer_url = 'https://www.youtube.com/watch?v=XJ69WnwvZhE' WHERE id_api = 'tt1255953';

UPDATE Contenido SET id_tmdb = 97430, descripcion = 'Intensa película de acción inspirada en los clásicos de artes marciales y kung-fu de la cultura oriental. El film está dirigido por uno de los más antiguos colaboradores del productor, el músico RZA, quien también escribe el guion junto a otro veterano cómplice de Tarantino, el artista estadounidense Eli Roth.  RZA debuta como director en la gran pantalla con este largometraje, que narra una legendaria historia sobre un héroe forastero y solitario en la China del siglo XIX. Los protagonistas de la historia tendrán que luchar contra un desalmado clan que intentará destruir su comunidad.  El extranjero herrero de la ciudad, dedicado a la creación de armas desde su llegada, invocará una extraordinaria energía mística con el objetivo de convertirse en una potente arma humana. Deberá aprovechar su poder para frenar las actuaciones de la organización enemiga y proteger a los habitantes de su entorno.', trailer_url = 'https://www.youtube.com/watch?v=u7Y9WBKtd90' WHERE id_api = 'tt1258972';

UPDATE Contenido SET id_tmdb = 718821, descripcion = 'Kate Carter, una ex cazadora de tormentas perseguida por un devastador encuentro con un tornado, es llamada por su amigo Javi de regreso a las llanuras para probar un nuevo e innovador sistema de seguimiento. Allí, se cruza con el encantador e imprudente ídolo de las redes sociales Tyler Owens y su estridente equipo. A medida que la temporada de tormentas se intensifica, se desatan fenómenos terroríficos nunca vistos, y Kate, Tyler y sus equipos competidores se encuentran directamente en el camino de múltiples sistemas de tormentas que convergen sobre Oklahoma en lo que será una lucha por sobrevivir.', trailer_url = 'https://www.youtube.com/watch?v=AuadPzIv-Yo' WHERE id_api = 'tt12584954';

UPDATE Contenido SET id_tmdb = 18239, descripcion = 'Edward Cullen decide abandonar a Bella Swan para mantenerla alejada de los peligros del mundo vampírico. Con la ayuda de Jacob Black, su amigo de la infancia y miembro de la misteriosa tribu quileute, Bella intentará superar el abandono de Edward, que la ha dejado sumida en el mayor de los desconsuelos. Pero los peligros siguen acechando a la joven; nuevas y asombrosas criaturas sobrenaturales se cruzarán en su camino, y Bella sólo contará con el apoyo del cada vez más cercano e irresistible Jacob. Repentinamente, Bella se encuentra inmersa en el mundo de los hombres lobo, ancestrales enemigos de los vampiros, y su lealtad es puesta a prueba...', trailer_url = 'https://www.youtube.com/watch?v=oDu2ifwrQNA' WHERE id_api = 'tt1259571';

UPDATE Contenido SET id_tmdb = 718930, descripcion = 'Cinco asesinos a sueldo se encuentran a bordo de un tren bala que viaja de Tokio a Morioka con unas pocas paradas intermedias. Descubren que sus misiones no son ajenas entre sí. La pregunta es quién saldrá vivo del tren y qué les espera en la estación final.', trailer_url = 'https://www.youtube.com/watch?v=C1rWd1iQfd0' WHERE id_api = 'tt12593682';

UPDATE Contenido SET id_tmdb = 22970, descripcion = 'Cinco jóvenes se preparan para pasar el fin de semana en una aislada cabaña en el bosque, sin ningún tipo de comunicación con el exterior. En el sótano encuentran una extraña colección de reliquias y entre ellas, un diario que habla de la antigua familia que ocupó la casa. Lo que no sospechan es que están siendo observados y que sus acciones marcarán el destino de algo mucho más grande que ellos.', trailer_url = 'https://www.youtube.com/watch?v=wZjung6T2Ps' WHERE id_api = 'tt1259521';

UPDATE Contenido SET id_tmdb = 449443, descripcion = 'Todos los días, el banco de la Reserva Federal de Los Ángeles saca de la circulación 120 millones de dólares en efectivo. Un grupo de experimentados ladrones planea su gran atraco final: robar esos 120 millones, pero el departamento del Sheriff de Los Ángeles, la brigada más temida de la ciudad liderada por ''El gran Nick'', no está dispuesto a ponérselo fácil.', trailer_url = 'https://www.youtube.com/watch?v=bEJfSCOTZiY' WHERE id_api = 'tt1259528';

UPDATE Contenido SET id_tmdb = 105248, descripcion = 'En una distopía plagada de corrupción e implantes cibernéticos, un chico prodigioso pero temerario trata de convertirse en un mercenario proscrito: un ‘edgerunner’.', trailer_url = 'https://www.youtube.com/watch?v=W6NhKRY_qmE' WHERE id_api = 'tt12590266';

UPDATE Contenido SET id_tmdb = 704239, descripcion = 'Un obrero de Nueva Jersey pasa de ser un tío normal a un aspirante a espía cuando su novia del instituto, desaparecida desde hace tiempo, lo recluta para una misión de espionaje.', trailer_url = 'https://www.youtube.com/watch?v=q1stQKQry9o' WHERE id_api = 'tt12610390';

UPDATE Contenido SET id_tmdb = 37786, descripcion = '¿Qué pasa después de dar el “Sí, quiero”? Han pasado dos años desde que Carrie Bradshaw y Big dieron el paso. Actualmente, a mitad de camino entre la pasión salvaje y la idea del bebé, se sienten muy casados.', trailer_url = 'https://www.youtube.com/watch?v=jF1iUxBYrSI' WHERE id_api = 'tt1261945';

UPDATE Contenido SET id_tmdb = 41446, descripcion = 'Sidney Prescott ha logrado olvidar los asesinatos cometidos en Woodsboro. Diez años después, convertida en una escritora de éxito, vuelve a su pueblo natal con motivo de la gira de promoción de su nuevo libro. Pero su regreso irá acompañado de una nueva ola de crímenes perpetrados por un viejo conocido: Ghostface.', trailer_url = 'https://www.youtube.com/watch?v=4kbeiU_T18Q' WHERE id_api = 'tt1262416';

UPDATE Contenido SET id_tmdb = 106379, descripcion = 'Basado en una de las sagas de videojuegos más importantes de todos los tiempos, Fallout es la historia de los que tienen y de los que no tienen en un mundo en el que prácticamente no queda nada para tener. 200 años después del apocalipsis, los apacibles habitantes de los refugios de lujo se ven obligados a regresar al infierno irradiado que dejaron sus antepasados - y se sorprenden al descubrir que les espera un universo increíblemente complejo, alegremente extraño y muy violento. De los productores ejecutivos Jonathan Nolan y Lisa Joy, los creadores de Westworld, protagonizada por Ella Purnell, Aaron Moten, Walton Goggins y más.', trailer_url = 'https://www.youtube.com/watch?v=SErNZJumbak' WHERE id_api = 'tt12637874';

UPDATE Contenido SET id_tmdb = 25196, descripcion = 'Bad Blake es un cantante de música country destrozado y con una dura vida, que ha pasado por demasiados matrimonios, demasiados años en la carretera y, en demasiadas ocasiones, demasiada bebida. Y, sin embargo, Bad no puede evitar buscar la salvación con la ayuda de Jean, una periodista que descubre al verdadero hombre detrás del músico.', trailer_url = 'https://www.youtube.com/watch?v=Y0349E7kFEM' WHERE id_api = 'tt1263670';

UPDATE Contenido SET id_tmdb = 402431, descripcion = 'Ambientada en la Tierra de Oz, mucho antes de la llegada de Dorothy Gale desde Kansas. Elphaba es una joven incomprendida por su inusual color verde que aún no ha descubierto su verdadero poder. Glinda es una popular joven marcada por sus privilegios y su ambición que aún no ha descubierto su verdadera pasión. Las dos se conocen como estudiantes de la Universidad Shiz, en la fantástica Tierra de Oz, y forjan una insólita pero profunda amistad. La trama abarca los acontecimientos del primer acto del musical de Broadway.', trailer_url = 'https://www.youtube.com/watch?v=UNHQgy3jawI' WHERE id_api = 'tt1262426';

UPDATE Contenido SET id_tmdb = 184315, descripcion = 'Hércules, como todos los héroes griegos, es un semidios. Tras realizar los terribles doce trabajos que le fueron impuestos y tras perder a su familia, decide darle la espalda a los dioses y encontrar consuelo en la búsqueda de aventuras. Gracias a sus andanzas, ha encontrado hombres afines que se han unido a él, pues comparten su amor por el combate y no temen la presencia constante de la muerte en sus vidas. El rey de Tracia pretende que estos hombres formen un ejército invencible. Adaptación de la novela gráfica de 2008 "Hercules: The Thracian War".', trailer_url = 'https://www.youtube.com/watch?v=M0w2jr3ftHU' WHERE id_api = 'tt1267297';

UPDATE Contenido SET id_tmdb = 84469, descripcion = 'Siempre con estilo, los cazarrecompensas Spike, Jet y Faye recorren el sistema solar en busca de trabajos. ¿Pero podrán escapar del pasado de Spike?', trailer_url = 'https://www.youtube.com/watch?v=dh5YtCp8n5w' WHERE id_api = 'tt1267295';

UPDATE Contenido SET id_tmdb = 722778, descripcion = 'La historia semiautobiográfica de la mayoría de edad de Fabietto Schisa, un niño del Nápoles de la década de 1980 cuyos años de adolescencia están marcados por alegrías inesperadas como la llegada de la leyenda del fútbol Diego Maradona, y una tragedia igualmente inesperada. El destino juega su papel, la alegría y la tragedia se entrelazan, y el futuro de Fabietto se pone en marcha en una historia de familia, deportes y cine, amor y pérdida.', trailer_url = 'https://www.youtube.com/watch?v=i_1VW_0i6vo' WHERE id_api = 'tt12680684';

UPDATE Contenido SET id_tmdb = 55465, descripcion = 'Seis años después de su aventura en la Bahía Guantánamo, Harold Lee y Kumar Patel causan una crisis navideña cuando sin querer incendian el árbol de Navidad del padre de Maria, la esposa de Harold. A partir de ese momento su navidad solo se centra en encontrar un árbol idéntico al que Kumar incendió, pero llegar a el será mucho más difícil de lo que ellos creían.', trailer_url = 'https://www.youtube.com/watch?v=rILHv9oFq38' WHERE id_api = 'tt1268799';

UPDATE Contenido SET id_tmdb = 46261, descripcion = 'Basada en un telefilm de la ABC del año 1973, la película “No tengas miedo a la oscuridad” nos cuenta la historia de una niña (Bailee Madison) que se muda con su padre (Guy Pearce) y la novia (Katie Holmes) de éste a una casa en la que habitan unas criaturas demoníacas. Cuando la pequeña las descubre, primero sentirá cierta fascinación por ellas, pero luego comprobará lo peligrosas que son.', trailer_url = 'https://www.youtube.com/watch?v=DcpRcEVryVk' WHERE id_api = 'tt1270761';

UPDATE Contenido SET id_tmdb = 335983, descripcion = 'Eddie Brock es un consolidado periodista y astuto reportero que está investigando una empresa llamada Fundación Vida. Esta fundación, dirigida por el eminente científico Carlton Drake, está ejecutando secretamente experimentos ilegales en seres humanos y realizando pruebas que involucran formas de vida extraterrestres y amorfas conocidas como simbiontes. Durante una visita furtiva a la central, el periodista quedará infectado por un simbionte. Comenzará entonces a experimentar cambios en su cuerpo que no entiende, y escuchará una voz interior, la del simbionte Venom, que le dirá lo que tiene que hacer. Cuando Brock adquiera los poderes del simbionte que le usa como huésped, Venom tomará posesión de su cuerpo, convirtiéndole en un despiadado y peligroso súpervillano.', trailer_url = 'https://www.youtube.com/watch?v=mYTmQWZkw10' WHERE id_api = 'tt1270797';

UPDATE Contenido SET id_tmdb = 62630, descripcion = 'Bagdad, 1987. El país está a punto de explotar, de vivir una revolución tras los abusos de poder y la corrupción política en la que se encuentra. Sin embargo, el príncipe Noir Oudaï Hussein, el hijo mayor y heredero del dictador Sadam Hussein, vive ajeno a todo, en su reino de perversión y despotismo. Pero tras los acontecimientos que están sucediendo, su padre tiene miedo de que los ciudadanos se tomen la justicia por su mano y asesinen a su hijo. Por eso obligará a uno de sus guardias, Latif Yahia, a que se haga pasar por él. Si no cumple esta orden, hará ejecutar a toda su familia. Latif no tendrá ninguna otra elección y empezará una nueva vida desempeñando el papel de Oudaï Hussein, el hombre más poderoso, odiado y temido del país. Comenzará a imitar primero sus movimientos físicos, pero después terminará adoptando su mismo modo de vida, suplantándolo de manera total, incluso en los actos más despreciables. ¿Será capaz de salir de ese infierno que le están obligando a vivir?', trailer_url = 'https://www.youtube.com/watch?v=saku9jyTWzc' WHERE id_api = 'tt1270262';

UPDATE Contenido SET id_tmdb = 49538, descripcion = 'Comienzo de la saga de los X-Men, esta es una historia secreta que alude a conocidos acontecimientos mundiales. Antes de que los mutantes se mostraran al mundo, y antes de que cambiaran sus nombres por los de Profesor X y Magneto, Charles Xavier (James McAvoy) y Erik Lehnsherr (Michael Fassbender) eran dos jóvenes que descubrían sus poderes. No había animadversión alguna entre ellos, sino que les unía una sincera amistad y la decisión de trabajar juntos y entrenar a un grupo de jóvenes mutantes para evitar el Armagedón nuclear. Su enemigo común: el malvado Sebastian Shaw (Kevin Bacon), un humano con poderes con el que Erik tiene una cuenta pendiente.', trailer_url = 'https://www.youtube.com/watch?v=BjSzQFRF-jw' WHERE id_api = 'tt1270798';

UPDATE Contenido SET id_tmdb = 136400, descripcion = 'Un agente de la DEA, Bobby Trench, y un oficial de la Inteligencia Naval, Michael Stigman, consiguen robarle 43 millones de dólares a la mafia. El problema consiste en que en realidad ese dinero no era de la organización criminal, sino de la CIA. Adaptación al cine de una novela gráfica de Steven Grant.', trailer_url = 'https://www.youtube.com/watch?v=aoQoH3-z1Ks' WHERE id_api = 'tt1272878';

UPDATE Contenido SET id_tmdb = 801688, descripcion = 'La historia se desarrolla en un futuro lejano, en el año 2898 AD. El mundo está en caos y decadencia, y una sociedad llamada ''The Complex'', formada por la élite y los ricos, tiene acceso a todos los recursos restantes del planeta. Aquellos que no pudieron comprar su entrada en el complejo viven en extensos barrios marginales, donde la comida y el agua son muy escasas.  En este mundo, llega un rayo de esperanza, donde la gente cree que Dios vendrá a rescatarlos en forma de un avatar. Ashwathama, un guerrero inmortal de la era del Mahabharata, busca redención protegiendo al niño que reside en el vientre de Sumathi.  Al mismo tiempo, The Complex intenta capturar a Sumathi, colocando una recompensa por su cabeza. Aquí es donde entra Bhairava, un cazarrecompensas. Él intenta luchar contra Ashwathama y reclamar la recompensa para sí mismo.', trailer_url = 'https://www.youtube.com/watch?v=rn7tdg6cpW4' WHERE id_api = 'tt12735488';

UPDATE Contenido SET id_tmdb = 73861, descripcion = 'Milo, una estrella del porno ya retirada que vive con su mujer y su hijo, está pasando por apuros económicos. Una cita con una antigua compañera de rodaje, la pornostar Layla, le presenta la oportunidad de trabajar con un tipo llamado Vukmir en su nueva película de porno experimental. Milos acaba aceptando sin saber exactamente lo que va a rodar y acaba sumergido en una tormenta de depravación violencia, snuff, pedofilia, y drogas que lo dejan en un abismo de locura.', trailer_url = 'https://www.youtube.com/watch?v=RcHq2W1dXRU' WHERE id_api = 'tt1273235';

UPDATE Contenido SET id_tmdb = 8592, descripcion = 'La serie sigue las andanzas en formato de documental, de Leslie Knope, que trabaja en el departamento de parques y tiempo libre en Pawnee, Indiana. Knope se une a una enfermera llamada Ann para lograr convertir en un parque lo que es un trozo de tierra abandonado, tratando de navegar hasta lograrlo por las mil trabas de la administración municipal y varios colectivos.', trailer_url = 'https://www.youtube.com/watch?v=5IZWeAwdJ-s' WHERE id_api = 'tt1266020';

UPDATE Contenido SET id_tmdb = 23172, descripcion = 'Bob Ho (Jackie Chan) es un superespía secreto de la CIA que decide abandonar su carrera en el mundo del espionaje para sentar la cabeza con su vecina y novia, la bella Gillian (Amber Valletta). Pero Bob tiene una última misión que cumplir antes de que Gillian acepte casarse con él: ganarse a sus tres testarudos hijos. Cuando Gillian se ve obligada de repente a salir de la ciudad, Bob se ofrece voluntario para cuidar de los niños, con intención de ganarse la aprobación de los mismos. Los problemas comienzan cuando uno de los pequeños se descarga por error una fórmula de alto secreto en su ordenador. Entonces todos se verán amenazados por un terrorista ruso, archienemigo de Bob, lo que fuerza a éste a compaginar los papeles de espía y futuro padrastro en el mayor desafío que se ha visto obligado a afrontar en su carrera.', trailer_url = 'https://www.youtube.com/watch?v=fa2RZf0m39g' WHERE id_api = 'tt1273678';

UPDATE Contenido SET id_tmdb = 723072, descripcion = 'Seis amigos realizan una sesión espiritista por Zoom durante la cuarentena, lo que les lleva a vivir una serie de aterradoras experiencias. Cuando un espíritu maligno invade sus casas, comienzan a preguntarse qué es lo que pueden hacer para sobrevivir a la noche.', trailer_url = 'https://www.youtube.com/watch?v=nA5CZGiPSoo' WHERE id_api = 'tt12749596';

UPDATE Contenido SET id_tmdb = 726759, descripcion = 'Basada en la historia real del comercial de videojuegos estadounidense Henk Rogers y su descubrimiento del Tetris en 1988. Cuando se dispone a hacer que el juego sea disponible en el mundo, se mete en una peligrosa red de mentiras y corrupción que hay detrás de la Cortina de Hierro.', trailer_url = 'https://www.youtube.com/watch?v=P3XojOorLOo' WHERE id_api = 'tt12758060';

UPDATE Contenido SET id_tmdb = 59967, descripcion = 'Como en 2072 los asesinatos están terminantemente prohibidos, las víctimas son enviadas a través de una máquina del tiempo al pasado (2042), donde los Loopers, un grupo de asesinos a sueldo, se encargan de eliminarlas y deshacerse rápidamente de sus cuerpos. El problema surge cuando Joe (Gordon-Levitt), uno de los Loopers, recibe desde el futuro un encargo muy especial: eliminarse a sí mismo (Bruce Willis).', trailer_url = 'https://www.youtube.com/watch?v=3tRLll52SeM' WHERE id_api = 'tt1276104';

UPDATE Contenido SET id_tmdb = 88273, descripcion = 'Para la joven Carolina Matilde (Alicia Vikander), casada siendo una adolescente con el rey de Dinamarca Christian VII, es un horror vivir con un marido ciclotímico y estrafalario que propone medidas como nombrar a su perro miembro honorario del Consejo de Estado, o que circulen en Copenhague por la noche carruajes vacíos para recoger a los borrachos. Así las cosas, Carolina se rinde a los encantos del médico personal del rey, un intelectual progresista (Mads Mikkelsen) que se verá dividido entre su lealtad al rey, su amor a la reina y su oportunidad de convertir una Dinamarca aún medieval en un país ilustrado.', trailer_url = 'https://www.youtube.com/watch?v=A8HTV3suZnw' WHERE id_api = 'tt1276419';

UPDATE Contenido SET id_tmdb = 777270, descripcion = 'La película, un drama de madurez ambientado en los tumultos de la Irlanda del Norte de finales de los años 60, sigue al joven Buddy mientras navega por un paisaje de lucha obrera, cambios culturales radicales y violencia sectaria. Buddy sueña con un futuro glamuroso que lo aleje de los problemas, pero, mientras tanto, encuentra consuelo en su carismático padre y su madre, y en sus alegres abuelos.', trailer_url = 'https://www.youtube.com/watch?v=T-9FUND1K60' WHERE id_api = 'tt12789558';

UPDATE Contenido SET id_tmdb = 14451, descripcion = 'Un grupo de amigos tenía todo lo necesario para pasar unas vacaciones geniales en la montaña: cabaña, esquíes, motos de nieve, trineos, grandes cantidades de cerveza y mucha hormona desatada. ¡Seguro que ninguno de ellos había previsto no volver a casa con vida! Sin embargo, el batallón de nazis zombis que habitan las montañas que rodean el lugar con el apropiado nombre de Öksfjord (Fiordo del Hacha) tenía otros planes', trailer_url = 'https://www.youtube.com/watch?v=2qUo2tS6t7U' WHERE id_api = 'tt1278340';

UPDATE Contenido SET id_tmdb = 508943, descripcion = 'Ambientada en un precioso pueblo costero de la Riviera italiana, narra la historia sobre el paso a la edad adulta de un chico que vive un verano inolvidable lleno de helados, pasta e infinitos paseos en scooter. Luca comparte estas aventuras con su nuevo mejor amigo, pero toda la diversión se ve amenazada por un secreto muy profundo: él es un monstruo marino de un mundo que yace bajo la superficie del agua.', trailer_url = 'https://www.youtube.com/watch?v=kw50vQA1S-o' WHERE id_api = 'tt12801262';

