UPDATE Contenido SET id_tmdb = 37799, descripcion = 'Mark Zuckerberg, alumno de Harvard y genio de la programación, se sienta a su ordenador y con empeño y entusiasmo comienza a desarrollar una nueva idea. En un furor de blogging y programación, lo que comenzó en la habitación de su colegio mayor pronto se convirtió en una red social global y una revolución en la comunicación. Seis años y 500 millones de amigos después, Mark Zuckerberg es el billonario más joven de la historia. Pero para este emprendedor, el éxito ha supuesto complicaciones personales y legales...', trailer_url = 'https://www.youtube.com/watch?v=K1JWiaIY-Xg' WHERE id_api = 'tt1285016';

