UPDATE Contenido SET id_tmdb = 52449, descripcion = 'Elizabeth es una profesora mal hablada, despiadada e inapropiada. Además bebe, se coloca y en lo único que piensa en es casarse con un buen partido que la mantenga y le permita dejar de trabajar. Cuando su prometido la deja, pone en marcha un plan para sustituirle por un rico y guapo profesor. Para ello tendrá que competir con Amy, otra profesora, hiperactiva y llena de energía. Cuando al mismo tiempo un sarcástico e irreverente profesor de gimnasia no para de tirarle los tejos a Elizabeth, las consecuencias de su salvajes y escandalosas confabulaciones aportarán a sus estudiantes, colegas e incluso a ella misma, una educación sin igual.', trailer_url = 'https://www.youtube.com/watch?v=ZGwp0xls1nc' WHERE id_api = 'tt1284575';

UPDATE Contenido SET id_tmdb = 5148, descripcion = 'Tras descubrirse el misterio del noveno chevron, un grupo de militares, civiles y científicos que habitaban la base secreta Ícaro se ven forzados a cruzar prematuramente el Stargate cuando la base es atacada. Como resultado, viajaron al interior de la nave Destiny (Destino), lanzada por Los Antiguos en la época dorada de su civilización como un experimento puesto en marcha pero nunca finalizado.

Lo que comienza como un accidente, termina siendo una misión sin fin cuando la improvisada expedición se percata de que la nave no puede regresar a la Tierra y ahora tienen que sobrevivir a bordo.', trailer_url = 'https://www.youtube.com/watch?v=9NbBcLf1-jA' WHERE id_api = 'tt1286039';

