UPDATE Contenido SET id_tmdb = 339527, descripcion = 'Joe Merriweather es un veterano detective del FBI al que le llega un horrible caso: varias personas han sido asesinadas de una manera espantosa y hay pocas pistas que revelen quién puede haber sido el asesino. Para intentar resolverlo trabaja junto a su ambiciosa compañera, la agente Katherine Cowles.  Pero, incapaces de avanzar en su búsqueda, ambos acabarán recurriendo al doctor Clancy, un solitario médico especialista ya retirado que se alejó del mundo tras la muerte de su hija. Además Clancy posee un don extraordinario, pues tiene visiones que podrían ser clave para dar con el rastro del criminal. Sin embargo, pronto descubrirá que no es el único con poderes y que tendrá que lidiar con los que tiene el escurridizo asesino.', trailer_url = 'https://www.youtube.com/watch?v=YWon8LoXqY0' WHERE id_api = 'tt1291570';

