UPDATE Contenido SET id_tmdb = 119675, descripcion = 'Antes de Elvis, Elton John y Madonna, existió Liberace: pianista virtuoso, artista exuberante, habituado a la escena y los plató de televisión. Liberace apreciaba la desmesura y cultivaba el exceso, dentro y fuera del escenario. Un día de verano de 1977, el joven y hermoso Scott Thorson entra en su camerino y a pesar de la diferencia de edad y del medio social, los dos hombres empiezan una relación secreta que duraría cinco años.', trailer_url = 'https://www.youtube.com/watch?v=IeqViWgc7QE' WHERE id_api = 'tt1291580';

