UPDATE Contenido SET id_tmdb = 37181, descripcion = 'Ahmad, un iraní que vive en Alemania desde hace años, regresa de vacaciones a su país natal. Sus amigos de la Universidad celebran su llegada con una excursión de tres días en el mar Caspio. Su amiga Sepideh, que sabe que acaba de divorciarse de una alemana, invita a Elly, la maestra de su hija. Al día siguiente, Elly desaparece sin dejar rastro, y todos culpan a Sepideh por haberla invitado. Poco a poco, la verdad sobre Elly acaba por salir a la luz. Seleccionada por Irán como candidata al Oscar 2010 en la categoría de película de habla no inglesa.', trailer_url = 'https://www.youtube.com/watch?v=atb0JaAN_90' WHERE id_api = 'tt1360860';

UPDATE Contenido SET id_tmdb = 114410, descripcion = 'Denji es un adolescente que vive con un demonio motosierra llamado Pochita. Para pagar la deuda que le dejó su padre tras su muerte, ha tenido que ganarse el pan como puede matando demonios y vendiendo sus cadáverse a la mafia, aunque su vida siempre ha sido miserable.

Cuando una traición provoca la muerte de Denji, Pochita hace un contrato con él y Denji revive como "Chainsaw Man", un ser humano con el corazón de un demonio.', trailer_url = 'https://www.youtube.com/watch?v=K9Gnl0VeIVI' WHERE id_api = 'tt13616990';

UPDATE Contenido SET id_tmdb = 114461, descripcion = 'Ambientada después de la caída del Imperio, la serie sigue al antiguo caballero Jedi mientras investiga una amenaza que se cierne sobre la galaxia.', trailer_url = 'https://www.youtube.com/watch?v=nh5hRXwMXrA' WHERE id_api = 'tt13622776';

UPDATE Contenido SET id_tmdb = 114471, descripcion = 'La brillante inventora Riri Williams vuelve a Chicago, donde conoce a Parker Robins, el Encapuchado.', trailer_url = 'https://www.youtube.com/watch?v=eqynxg3Uo_Q' WHERE id_api = 'tt13623126';

UPDATE Contenido SET id_tmdb = 157239, descripcion = 'Cuando una misteriosa nave se estrella contra la Tierra, una joven y un variopinto grupo de soldados tácticos hacen un fatídico hallazgo que los pone cara a cara con la mayor amenaza del planeta. El equipo de rescate busca supervivientes entre los restos de la colisión y se topa con una forma de vida depredadora que levanta más misterios y miedos de los que cabría imaginarse. Debido a esta nueva amenaza, el equipo deberá luchar por sobrevivir. Lo que decidan hacer con este descubrimiento podría cambiar el planeta Tierra tal y como lo conocen.', trailer_url = 'https://www.youtube.com/watch?v=nGV-HN8mc_k' WHERE id_api = 'tt13623632';

UPDATE Contenido SET id_tmdb = 232125, descripcion = 'Una serie de cortometrajes con Groot junto a varios personajes inusuales. Es infantil y molesta a todos los que le rodean: el árbol parlante Groot. Groot es tan tonto y poco razonable que tiene que abandonar la nave espacial del equipo de héroes y acaba aterrizando en un planeta extraño. Allí se encuentra con todo tipo de criaturas: Alienígenas y robots.', trailer_url = 'https://www.youtube.com/watch?v=Eaj4-ZrF3YQ' WHERE id_api = 'tt13623148';

UPDATE Contenido SET id_tmdb = 283587, descripcion = 'Drama basado en las experiencias de Agu, un niño soldado de un país africano que, tras cerrar la escuela y ser sacado de su aldea y golpeado casi hasta la muerte, se vio obligado a participar en una guerra civil empuñando un arma y combatiendo a sus compatriotas.', trailer_url = 'https://www.youtube.com/watch?v=2xb9Ty-1frw' WHERE id_api = 'tt1365050';

UPDATE Contenido SET id_tmdb = 839369, descripcion = 'Veinte años después de que el mediático romance entre Gracie Atherton-Yu (Julianne Moore) y su joven marido Joe escandalizara al país, con sus hijos a punto de graduarse en el instituto, se va a rodar una película sobre su historia. La actriz Elizabeth Berry (Natalie Portman) pasará un tiempo con la familia para intentar entender mejor a Gracie, a la que va a interpretar en la película, provocando que la dinámica familiar se deshaga bajo la presión de la mirada exterior.', trailer_url = 'https://www.youtube.com/watch?v=qPehIc6J3ZQ' WHERE id_api = 'tt13651794';

UPDATE Contenido SET id_tmdb = 21510, descripcion = 'Neil Caffrey es un ladrón de guante blanco, que se escapa de una cárcel de máxima seguridad para ir en busca de su novia que le ha abandonado para siempre. Para cazar a Caffrey, el FBI llama a Peter Burke, el agente que le ha perseguido durante años y que fue el único que consiguió encerrarlo. El agente encontrará a Caffrey que le ofrece un buen trato, usará su experiencia criminal para ayudarle a atrapar a los ladrones más escurridizos del mundo a cambio de la libertad. Una relación muy especial que también compartirán Elisabeth, la mujer de Burke y Mozzie, el mejor amigo de este ladrón que ahora trabaja para los buenos.', trailer_url = 'https://www.youtube.com/watch?v=xn71SKHlt_k' WHERE id_api = 'tt1358522';

