UPDATE Contenido SET id_tmdb = 950396, descripcion = 'Mandan a dos operativos de élite a vigilar lados opuestos de un misterioso abismo y allí intiman desde la distancia, pero deberán aunar fuerzas para sobrevivir al mal que esconde el abismo.', trailer_url = 'https://www.youtube.com/watch?v=VuzKAeHGuMI' WHERE id_api = 'tt13654226';

UPDATE Contenido SET id_tmdb = 338970, descripcion = 'Tras la desaparición de su padre, Lara vive una vida imprudente y despreocupada. Cuando la policía la arresta después de provocar un accidente de tráfico,  Ana Miller, la socia de negocios de su progenitor, deposita su fianza y le advierte que si no reclama la herencia de éste,  se liquidarán todos sus bienes.', trailer_url = 'https://www.youtube.com/watch?v=1fM_WoZmVFE' WHERE id_api = 'tt1365519';

UPDATE Contenido SET id_tmdb = 777245, descripcion = 'Un grupo de mujeres en una colonia religiosa aislada lucha por reconciliar su fe con una serie de agresiones sexuales cometidas por los hombres de la colonia.', trailer_url = 'https://www.youtube.com/watch?v=yfDAcKguj3Q' WHERE id_api = 'tt13669038';

UPDATE Contenido SET id_tmdb = 115036, descripcion = 'El legendario cazarrecompensas Boba Fett y la mercenaria Fennec Shand deben navegar por el inframundo de la galaxia cuando regresen a las arenas de Tatooine para reclamar el territorio que una vez gobernó Jabba el Hutt y su sindicato del crimen.', trailer_url = 'https://www.youtube.com/watch?v=CDMo4xDbzjo' WHERE id_api = 'tt13668894';

UPDATE Contenido SET id_tmdb = 894762, descripcion = 'Before the Kalyug begins, Lord Krishna hands over an anklet that holds the answer to all of world’s miseries. Years later a doctor finds himself in the thick of things when the pursuit for the anklet carries on. A doctor with a curious mind, Karthikeya, aka Karthik, believes in pursuing the truth. The quest leads Karthik to discover the power of the ancient Indian belief system and the essence of Krishna.', trailer_url = 'https://www.youtube.com/watch?v=UIYS4iyeXj4' WHERE id_api = 'tt13664684';

UPDATE Contenido SET id_tmdb = 83542, descripcion = 'El atlas de las nubes es una novela que da la vuelta al mundo y recorre desde el siglo XIX hasta un futuro apocalíptico, a través de seis historias entrelazadas. El relato se abre en 1850 con el regreso del notario estadounidense Adam Ewing desde las islas Chatham a su California natal. Durante el viaje, Ewing traba amistad con un médico, el doctor Goose, que comienza a tratarle de una extraña enfermedad causada por un parásito cerebral... Repentinamente, la acción se traslada a 1931 en Bélgica, donde Robert Frobisher, un compositor bisexual que ha sido desheredado, se introduce en el hogar de un artista enfermizo, su seductora esposa y su núbil hija... De ahí saltamos a la Costa Oeste en la década de los setenta, cuando Luisa Rey destapa una red de avaricia y crimen que pone en peligro su vida... Y, del mismo modo, con idéntica maestría, viajamos a la ignominiosa Inglaterra de nuestros días.', trailer_url = 'https://www.youtube.com/watch?v=MVg4fHWwsVs' WHERE id_api = 'tt1371111';

UPDATE Contenido SET id_tmdb = 239678, descripcion = 'La muerte del patriarca de la familia congrega por primera vez en años al clan de los Foxman. Judd, está de luto doble, no sólo ha muerto su padre, tambien lo ha hecho su matrimonio. Jen, su mujer, tiene un romance con su jefe que está en boca de todos.', trailer_url = 'https://www.youtube.com/watch?v=fH0cEP0mvlU' WHERE id_api = 'tt1371150';

UPDATE Contenido SET id_tmdb = 27205, descripcion = 'Dom Cobb es un ladrón hábil, el mejor de todos, especializado en el peligroso arte de extracción: el robo de secretos valiosos desde las profundidades del subconsciente durante el estado de sueño cuando la mente está más vulnerable. Esta habilidad excepcional de Cobb le ha hecho un jugador codiciado en el traicionero nuevo mundo de espionaje corporativo, pero al mismo tiempo, le ha convertido en un fugitivo internacional y ha tenido que sacrificar todo que le importaba. Ahora a Cobb se le ofrece una oportunidad para redimirse. Con un último trabajo podría recuperar su vida anterior, pero solamente si logra lo imposible.', trailer_url = 'https://www.youtube.com/watch?v=RV9L7ui9Cn8' WHERE id_api = 'tt1375666';

UPDATE Contenido SET id_tmdb = 58431, descripcion = 'Adaptación cinematográfica de la novela gráfica homónima de Seth Grahame-Smith, basada en el clásico literario de Jane Austen, que se desarrolla en un universo alternativo a la Regencia Británica de 1819, donde una plaga de zombies invaden la apacible población inglesa de Meryton.', trailer_url = 'https://www.youtube.com/watch?v=y5N7OyoTCXg' WHERE id_api = 'tt1374989';

UPDATE Contenido SET id_tmdb = 120089, descripcion = 'El espía "Twilight" recibe la misión de infiltrarse en la familia de un líder político. Para ello, crea una falsa familia con una hija que lee mentes y una esposa asesina, mientras ocultan sus secretos y viven juntos en una aventura peligrosa para mantener la paz mundial.', trailer_url = 'https://www.youtube.com/watch?v=44qfOGvEWAU' WHERE id_api = 'tt13706018';

UPDATE Contenido SET id_tmdb = 38365, descripcion = 'Después de muchos años, su antiguo entrenador de basquet muere y cincos amigos deciden pasar un fin de semanas -ahora con sus respectivas familias- en la casa donde celebraron, antaño, el campeonato.', trailer_url = 'https://www.youtube.com/watch?v=fhOA5vsop4M' WHERE id_api = 'tt1375670';

UPDATE Contenido SET id_tmdb = 785084, descripcion = 'Un solitario profesor de inglés con obesidad severa intenta reconectar con su hija adolescente en una última oportunidad de redención.', trailer_url = 'https://www.youtube.com/watch?v=Rhd5EyZ-rEs' WHERE id_api = 'tt13833688';

UPDATE Contenido SET id_tmdb = 38810, descripcion = 'Un matrimonio con tres hijos vive en una mansión en las afueras de una ciudad. Los chicos, que nunca han salido de casa, son educados según los métodos que sus padres juzgan más apropiados y sin recibir ninguna influencia del exterior. Creen que los aviones son juguetes o que el mar es un tipo de silla forrada de cuero. La única persona que puede entrar en la casa es Christine, guardia de seguridad en la fábrica del padre.', trailer_url = 'https://www.youtube.com/watch?v=YJe4eZ9l5KY' WHERE id_api = 'tt1379182';

UPDATE Contenido SET id_tmdb = 780609, descripcion = 'Tras sufrir una tragedia personal, Harper se retira sola a la hermosa campiña inglesa con la esperanza de encontrar un lugar para cerrar sus heridas. Pero alguien o algo de os bosques que la rodean parece estar acechándola. Lo que comienza como un temor latente se convierte en una auténtica pesadilla, habitada por sus recuerdos y miedos más oscuros.', trailer_url = 'https://www.youtube.com/watch?v=atTZSAz5KMI' WHERE id_api = 'tt13841850';

UPDATE Contenido SET id_tmdb = 38050, descripcion = 'El carismático político David Norris está a punto de ser elegido senador cuando conoce a la preciosa bailarina Elise Sellas, de la que se enamora. Pronto descubre que hay unas extrañas personas que tratan de impedir su relación.', trailer_url = 'https://www.youtube.com/watch?v=KTcFXViHzPY' WHERE id_api = 'tt1385826';

UPDATE Contenido SET id_tmdb = 116450, descripcion = 'Esta nueva entrega de "Sexo en Nueva York" sigue a Carrie, Miranda y Charlotte en su viaje desde la complicada realidad de la vida y la amistad a los 30 años, hasta la aún más complicada realidad de la vida y la amistad a los 50 años.', trailer_url = 'https://www.youtube.com/watch?v=4cIJBe17L4k' WHERE id_api = 'tt13819960';

UPDATE Contenido SET id_tmdb = 116799, descripcion = 'Mickey Haller, el famoso abogado de Los Ángeles, hace lo que sea necesario para ganar sus casos mientras lidia con el sistema de justicia penal desde su emblemático Lincoln.', trailer_url = 'https://www.youtube.com/watch?v=u-sLh8-ohzc' WHERE id_api = 'tt13833978';

UPDATE Contenido SET id_tmdb = 23742, descripcion = 'Bruce Willis y Tracy Morgan dan vida a dos policías que arman un escándalo buscando un carísimo cromo de béisbol de 1952. En el camino, deberán rescatar a una supermodelo mexicana y acabar con una organización de narcotraficantes.', trailer_url = 'https://www.youtube.com/watch?v=NAH8qgVY9jE' WHERE id_api = 'tt1385867';

UPDATE Contenido SET id_tmdb = 27581, descripcion = 'Allen Gamble y Terry Hoitz son un par de policías de Nueva York que viven a la sombra de los héroes del cuerpo, los superagentes Christopher Danson y P.K. Highsmith. Pero cuando las cosas se tuerzan en la gran manzana, esta peculiar pareja tendrá que levantar sus traseros del despacho de la comisaría y entrar en acción.', trailer_url = 'https://www.youtube.com/watch?v=D6WOoUG1eNo' WHERE id_api = 'tt1386588';

UPDATE Contenido SET id_tmdb = 37472, descripcion = 'En esta secuela, Ip Man (Donnie Yen), llega a Hong-Kong y abre una escuela de Wing Chun, pero pronto entrará en conflicto con un maestro local de Hung Fist llamado Hung Jan-nam, quien es interpretado por Sammo Hung. Aunque, Ip Man, últimamente ha sido desafiado por los ingleses que gobiernan el territorio, las tensiones entre los dos maestros de Kung fu sigue incrementando, y eso hace que ellos se vean forzados a batirse a duelo.', trailer_url = 'https://www.youtube.com/watch?v=4ynwOQX1A7k' WHERE id_api = 'tt1386932';

UPDATE Contenido SET id_tmdb = 301337, descripcion = 'Paul es un hombre que se da cuenta de que tendría una vida mucho mejor si encogiese, pues todo lo que necesita en la vida lo tendría igualmente pero en abundancia. Así que decide reducir enormemente su tamaño, ahora que la tecnología lo permite.', trailer_url = 'https://www.youtube.com/watch?v=3yXWdcjvE-s' WHERE id_api = 'tt1389072';

UPDATE Contenido SET id_tmdb = 121824, descripcion = 'Val sale de la cárcel tras cumplir 28 años de condena. Doc, su mejor amigo, le espera a la salida para ir a ver a Hirsch, otro viejo colega. A pesar de la edad, los tres gángsteres deciden reanudar esa misma noche su vida de crímenes, drogas y sexo. Sin embargo, Doc tiene que hacer antes un trabajo urgente que le ha encargado el jefe de la banda: debe matar a Val para saldar una cuenta pendiente. El dilema es peliagudo, y dispone de poco tiempo para resolverlo.', trailer_url = 'https://www.youtube.com/watch?v=dxlaRKbZYTc' WHERE id_api = 'tt1389096';

UPDATE Contenido SET id_tmdb = 74465, descripcion = 'En “Un lugar para soñar” conocemos a Benjamin Mee, un columnista de prensa y escritor de artículos de aventuras que, como padre viudo, se enfrenta al desafío de criar a sus dos hijos pequeños. Con la esperanza de que partir de cero y llevar una nueva vida restablecerá el espíritu familiar, Mee deja su empleo y compra una vieja casa rural situada en un terreno de unas ocho hectáreas fuera de la ciudad que incluye una irrepetible particularidad añadida: un zoológico denominado el Parque de Animales Rosemoor, residencia de docenas de animales encomendados al cuidado de la jefa de guardas Kelly Foster y su entusiasta equipo. Sin experiencia, con poco tiempo y reducidísimo presupuesto, Mee se propone, con el apoyo de su familia y de la gente de la localidad, reabrir el zoo. Ahora, Benjamin ya no cuenta una historia de aventuras, sino que vive la suya propia.', trailer_url = 'https://www.youtube.com/watch?v=Fopeq7wx4sw' WHERE id_api = 'tt1389137';

UPDATE Contenido SET id_tmdb = 76341, descripcion = 'Perseguido por su turbulento pasado, Mad Max cree que la mejor forma de sobrevivir es ir solo por el mundo. Sin embargo, se ve arrastrado a formar parte de un grupo que huye a través del desierto en un War Rig conducido por una Emperatriz de élite: Furiosa. Escapan de una Ciudadela tiranizada por Immortan Joe, a quien han arrebatado algo irreemplazable. Enfurecido, el Señor de la Guerra moviliza a todas sus bandas y persigue implacablemente a los rebeldes en una ''guerra de la carretera'' de altas revoluciones.', trailer_url = 'https://www.youtube.com/watch?v=UyqFAle_4aE' WHERE id_api = 'tt1392190';

UPDATE Contenido SET id_tmdb = 117303, descripcion = 'En los años 50, el sueño de Elizabeth Zott de ser científica se ve en peligro porque la sociedad dicta que las mujeres solo pertenecen al ámbito doméstico. Acepta un trabajo en un programa de cocina de televisión y se propone enseñar a las amas de casa olvidadas del país algo más que recetas.', trailer_url = 'https://www.youtube.com/watch?v=6jeSdjAT9IM' WHERE id_api = 'tt13911628';

UPDATE Contenido SET id_tmdb = 70160, descripcion = 'Lo que en el pasado fueron los Estados Unidos, ahora es una nación llamada Panem; un imponente Capitolio ejerce un control riguroso sobre los 12 distritos que lo rodean y que están aislados entre sí. Cada distrito se ve obligado a enviar anualmente un chico y una chica entre los doce y los dieciocho años para que participen en los Hunger Games, unos juegos que son transmitidos en directo por la televisión. Se trata de una lucha a muerte, en la que sólo puede haber un superviviente. Katniss Everdeen, una joven de dieciséis años, decide sustituir a su hermana en los juegos; pero para ella, que ya ha visto la muerte de cerca, la lucha por la supervivencia es su segunda naturaleza.', trailer_url = 'https://www.youtube.com/watch?v=y0hE3fDJCFA' WHERE id_api = 'tt1392170';

UPDATE Contenido SET id_tmdb = 146233, descripcion = 'Keller Dover se enfrenta a la peor de las pesadillas: Anna, su hija de seis años, ha desaparecido con su amiga Joy y, a medida que pasa el tiempo, el pánico lo va dominando. Desesperado, decide ocuparse personalmente del asunto. Pero, ¿hasta dónde está dispuesto a llegar para averiguar el paradero de su hija?', trailer_url = 'https://www.youtube.com/watch?v=AiN1ahjVb3Y' WHERE id_api = 'tt1392214';

UPDATE Contenido SET id_tmdb = 17610, descripcion = 'La ficción relata la extraordinaria labor que lleva a cabo el Servicio de Investigación Criminal Naval (NCIS), que investiga y combate las actividades de asociaciones criminales, grupos terroristas y a las agencias de inteligencia extranjeras que constituyen una grave amenaza para la Marina norteamericana. Dentro de este servicio se enmarca la Oficina de Proyectos Especiales, una división especializada en la captura y localización de los criminales más peligrosos que ponen en jaque la seguridad nacional. La utilización de identidades falsas y de la más avanzada tecnología permite a este grupo de agentes encubiertos cumplir los objetivos asignados. Desplegados en distintos puntos del mundo cuando la ocasión lo requiere a través de los portaviones o de las fuerzas anfibias de la Marina, los agentes del NCIS están entrenados para identificar y frenar los peligros externos mientras trabajan en estrecha colaboración con las fuerzas de seguridad estatales, federales o locales.

Un camaleónico agente capaz de infiltrase en cualquier organización criminal y un experto en sistemas de vigilancia que combatió en Afganistán son los principales protagonistas de ''NCIS: Los Ángeles''.', trailer_url = 'https://www.youtube.com/watch?v=Or5YChRcVAM' WHERE id_api = 'tt1378167';

