UPDATE Contenido SET id_tmdb = 58224, descripcion = 'Mr. Popper vive en una tranquila y pequeña ciudad americana llamada Stillwater. Allí nunca pasa nada. Quizá por eso se ha convertido en un soñador y en un especialista en temas del Ártico y de la Antártida, incluso podría decir el nombre de todos sus exploradores y qué fueron a hacer a los polos. Un día conversa, gracias a un programa de radio, con el almirante Drake sobre su expedición a la Antártida, y éste le dice que pronto recibirá una sorpresa… Lo que nadie podía suponer es que el almirante iba a enviar una caja con ¡un pingüino de la mismísima Antártida! La vida de nuestro protagonista cambiará radicalmente, y la aburrida vida en Stillwater se transformará en una fantástica y permanente aventura llena de pingüinos', trailer_url = 'https://www.youtube.com/watch?v=D1a9ykw0azY' WHERE id_api = 'tt1396218';

