UPDATE Contenido SET id_tmdb = 810693, descripcion = 'Yuta Okkotsu es un nervioso estudiante de instituto que sufre un grave problema: su amiga de la infancia Rika se ha convertido en una maldición y no le deja en paz. Como Rika no es una maldición cualquiera, su situación es percibida por Satoru Gojo, un profesor del instituto Jujutsu, una escuela donde los exorcistas noveles aprenden a combatir las maldiciones. Gojo convence a Yuta para que se matricule, pero ¿podrá aprender lo suficiente a tiempo para enfrentarse a la Maldición que le persigue?', trailer_url = 'https://www.youtube.com/watch?v=80TsKHyg0CE' WHERE id_api = 'tt14331144';

UPDATE Contenido SET id_tmdb = 812583, descripcion = 'El detective Benoit Blanc se une a un joven y honesto sacerdote para investigar un crimen totalmente imposible en la iglesia de un pequeño pueblo con una oscura historia.', trailer_url = 'https://www.youtube.com/watch?v=ek_1vaeoimg' WHERE id_api = 'tt14364480';

UPDATE Contenido SET id_tmdb = 58857, descripcion = 'El ascenso al poder del joven y sanguinario Lord Naritsugu supone una seria amenaza para la paz en el Japón feudal. Simplemente por ser el hermano del shogun, Lord Naritsugu está por encima de la ley, y asesina y viola a su antojo. Afligido por la masacre perpetrada por el sádico Naritsugu, el oficial Sir Doi contacta secretamente con el samurái Shinzaemon Shimada para acabar con Naritsugu. El noble samurái, indignado por la crueldad de Naritsugu, acepta de buen grado la peligrosa misión. Para ello, reúne a un selecto grupo de samuráis, entre los que se encuentra su sobrino Shinrokuro y el devoto aprendiz Hirayama. Juntos, traman una emboscada para atrapar a Lord Naritsugu. Shinzaemon es consciente del peligro que conlleva. Naritsugu va escoltado por una comitiva encabezada por el letal e implacable Hanbei, uno de sus antiguos rivales. Los “13 asesinos” de Takashi Miike es un remake del film homónimo dirigido por Eichi Kudo en 1963.', trailer_url = 'https://www.youtube.com/watch?v=Xpm007vne54' WHERE id_api = 'tt1436045';

UPDATE Contenido SET id_tmdb = 955916, descripcion = 'Un ladrón y su banda se preparan para dar un golpe de altura: robar 500 millones de dólares en oro de una caja fuerte... ¡a bordo de un avión a 9000 m de altitud!', trailer_url = 'https://www.youtube.com/watch?v=4tY7OLHevPw' WHERE id_api = 'tt14371878';

UPDATE Contenido SET id_tmdb = 58151, descripcion = 'Durante su último año en el instituto, Charlie Brewster (Anton Yelchin) parece que por fin ha alcanzado todos sus objetivos: es uno de los estudiantes más valorados y sale con la chica más deseada del centro. Su popularidad es tal que ha comenzado a dejar de lado a su mejor amigo. Sin embargo, cuando Jerry (Colin Farrell) se convierte en su vecino, aunque, al principio, le parece un tipo genial, con el paso del tiempo empieza a percibir en él algo extraño. Desgraciadamente nadie, ni siquiera la madre de Charlie (Toni Collette), se da cuenta de nada. Después de observar que en la casa de Jerry pasan cosas extrañas, Charlie llega a la conclusión de que su vecino es un vampiro que se sirve del vecindario para cazar a sus presas. Ante la incredulidad de los demás, el protagonista deberá ingeniárselas para deshacerse del monstruo por sí solo en esta moderna versión del clásico de la comedia y el terror dirigida por Craig Gillespie.', trailer_url = 'https://www.youtube.com/watch?v=UfDC2X4fZr4' WHERE id_api = 'tt1438176';

UPDATE Contenido SET id_tmdb = 77495, descripcion = 'César es el portero de un edificio de apartamentos y no cambiaría este trabajo por ningún otro, ya que le permite conocer a fondo los movimientos, los hábitos más íntimos, los puntos débiles y los secretos de todos los inquilinos. Si quisiera podría incluso controlar sus vidas, influir en ellas como si fuera Dios, abrir sus heridas y hurgar en ellas. Y todo sin levantar ninguna sospecha. Porque César guarda un secreto muy peculiar: le gusta hacer daño, mover las piezas necesarias para producir dolor a su alrededor. Y la nueva vecina del 5ºB no deja de sonreír. Entra y sale cada día radiante y feliz, llena de luz. Así que pronto se convertirá en el nuevo objetivo del juego de César. Se trata de un reto personal, de una obsesión.', trailer_url = 'https://www.youtube.com/watch?v=1sMBbvc2o_M' WHERE id_api = 'tt1437358';

UPDATE Contenido SET id_tmdb = 37950, descripcion = 'Charlie St. Cloud es un joven tan afectado por la muerte de su hermano menor, Sam, que acepta un trabajo como cuidador en el cementerio en el que el pequeño está enterrado. Charlie tiene un vínculo especial con su hermano, pues le puede ver, y cada noche se encuentra con él para hablar y jugar juntos. Pero sucede que un día una chica entra en la vida de Charlie, y este tendrá que elegir entre mantener una promesa que hizo a Sam o ir con la joven que ama.', trailer_url = 'https://www.youtube.com/watch?v=v4gdRlZwqHE' WHERE id_api = 'tt1438254';

UPDATE Contenido SET id_tmdb = 44833, descripcion = '“Battleship” es la libre adaptación al cine del popular juego de mesa de Hasbro conocido como “Hundir la flota” o ”Batalla naval”. La curiosa variante que plantea esta versión es que la batalla será entre la U.S. Navy y… ¡una flota alienígena! La historia nos propone una épica aventura de acción que transcurre en el mar, el cielo y la tierra, y en la que nuestro planeta lucha por sobrevivir contra una fuerza muy superior. La película está protagonizada por Taylor Kitsch en el papel del teniente Hopper, un oficial de la Marina destinado al John Paul Jones; Brooklyn Decker es Sam Shane, una fisioterapeuta de la Marina y novia de Hopper; Alexander Skarsgård es Stone, el hermano mayor de Hopper y comandante del Samson; Rihanna es la suboficial Raikes, especialista en armas del John Paul Jones; y Liam Neeson es el almirante Shane, el oficial superior de Hopper y Stone (y padre de Sam).', trailer_url = 'https://www.youtube.com/watch?v=m4S2cc1OKKI' WHERE id_api = 'tt1440129';

UPDATE Contenido SET id_tmdb = 49020, descripcion = 'Oliver Tate (Craig Roberts) es un peculiar joven de 15 años que tiene dos objetivos: impedir que su madre deje a su padre y encontrarse a sí mismo aunque sea a través de una chica, Jordana.', trailer_url = 'https://www.youtube.com/watch?v=B9yLagpZjCg' WHERE id_api = 'tt1440292';

UPDATE Contenido SET id_tmdb = 50837, descripcion = 'Atormentada por dolorosos recuerdos y dominada por una creciente ansiedad, Martha abandona una secta y se va a vivir con su hermana Lucy y con Ted, el marido de ésta. Intenta adaptarse al estilo de vida de la clase media-alta, pero acosada por constantes pesadillas, no le resulta nada fácil. Mientras asume su soledad, la paranoia resquebraja su existencia. Finalmente, desciende a un vestiginoso estado de pánico cuando comienza a sospechar que alguien sigue todos sus movimientos.', trailer_url = 'https://www.youtube.com/watch?v=8BitRyldbsk' WHERE id_api = 'tt1441326';

UPDATE Contenido SET id_tmdb = 154385, descripcion = 'Un incidente de tráfico entre dos desconocidos (un contratista fracasado y una empresaria descontenta) desata un conflicto que saca a relucir su lado más oscuro.', trailer_url = 'https://www.youtube.com/watch?v=SIH61jYsKf4' WHERE id_api = 'tt14403178';

UPDATE Contenido SET id_tmdb = 19092, descripcion = 'Basada en una novela del escritor Robert J. Sawyer, cuenta la historia de lo que ocurre después de que, el 6 de octubre de 2009, los 7.000 millones de personas que habitan la Tierra se desmayan a la vez y tienen una visión sobre lo que -parece ser- les ocurrirá a cada uno de ellos en el futuro, en concreto el 29 de abril de 2010. Cuando se despiertan, todos comienzan a preguntarse si lo que han visto les ocurrirá realmente.', trailer_url = 'https://www.youtube.com/watch?v=YVbtHAZsSYs' WHERE id_api = 'tt1441135';

UPDATE Contenido SET id_tmdb = 97370, descripcion = 'Un alien asume la forma de una atractiva mujer y deambula por las calles de Escocia, llevando a hombres solitarios y confiados a su destino fatal en la adaptación surrealista de la novela homónima de Michel Faber.', trailer_url = 'https://www.youtube.com/watch?v=J7bAZCOk0Sc' WHERE id_api = 'tt1441395';

