UPDATE Contenido SET id_tmdb = 18202, descripcion = 'El estreno de la primera temporada muestra a Jules mientras examina su cuerpo desnudo en un espejo, en busca de signos de envejecimiento. Jules, ahora divorciada de su esposo Bobby, trata de volver a entrar al mundo de las citas y su amiga Laurie la ayuda. La mejor amiga de Jules y su vecina, Ellie, trata de prevenirla de que salga mientras su hijo es constantemente avergonzado por ambos de sus padres. Jules comienza a salir con Josh (Nick Zano). La relación con Josh termina cuando él le dice que la ama y Jules no siente lo mismo. Luego, Jules comienza una relación con Jeff (Scott Foley) un cliente quién enfuerece a Jules con su indecisión. Su relación con Jeff termina cuando la relación se convierte más serie para Jules quién no está buscando nada serie tan pronto después de su divorcio, mientras que Jeff está listo para establecerse ya que ha estado "jugando en el campo de juego" por mucho tiempo. Después de que su relación con Jeff termina, Jules se acuesta con su ex-esposo, Bobby (Brian Van Holt). Esto causa que los sentimientos de Bobby hacia Jules se agranden y él le dice a ella que quiere que vuelvan. Jules, sin embargo, le dice que ella lo ama pero no ''de la misma forma'' y que están felices siendo amigos, criando a su hijo, Travis (Dan Byrd) juntos. Hacia el final de la temporada, los sentimientos latentes entre Jules y su vecino Grayson (Josh Hopkins) salen a la superficie, y los dos comienzan una relación. (wiki)', trailer_url = 'https://www.youtube.com/watch?v=1QYrcixZJ4o' WHERE id_api = 'tt1441109';

UPDATE Contenido SET id_tmdb = 46296, descripcion = 'Traicionado por su país. Convertido en esclavo. Renacido como guerrero. Spartacus protagoniza la historia más gráfica y visceral del gladiador más famoso de Roma. Con un reparto estelar, asistimos a una mezcla única de acción, efectos gráficos y brutales batallas. Separado del amor de su vida, Spartacus tendrá que luchar por su supervivencia, participando en un espectáculo, donde el principal entretenimiento es la muerte. En un mundo de corrupción, violencia, sexo y fama acabará interviniendo en política y vivirá atormentado por el deseo de venganza.', trailer_url = 'https://www.youtube.com/watch?v=yHxn8mTpAJU' WHERE id_api = 'tt1442449';

UPDATE Contenido SET id_tmdb = 81188, descripcion = 'Una aventura épica y mágica que cuenta la historia de Santa Claus, el Conejo de Pascua, el Hada de los Dientes y Jack Escarcha; personajes legendarios con desconocidas habilidades extraordinarias. Cuando un espíritu maligno, conocido como Sombra, decide inundar de miedo los corazones de los niños, los Guardianes inmortales unen sus fuerzas para proteger los deseos, las creencias y la imaginación de los niños.', trailer_url = 'https://www.youtube.com/watch?v=e4bdD8owgDU' WHERE id_api = 'tt1446192';

UPDATE Contenido SET id_tmdb = 70981, descripcion = 'Un grupo de científicos y exploradores emprende un viaje espacial a un remoto planeta, en el que sus límites físicos y mentales serán puestos a prueba. El motivo de la misión es que los humanos creen que allá podrán encontrar las respuestas a las preguntas más profundas y al mayor de los misterios: el origen de la vida en la Tierra.', trailer_url = 'https://www.youtube.com/watch?v=MldbTQFVE6c' WHERE id_api = 'tt1446714';

UPDATE Contenido SET id_tmdb = 1071215, descripcion = 'Tras un Black Friday en el que se producen disturbios que acaban en tragedia, un misterioso asesino inspirado en la festividad de Acción de Gracias aterroriza Plymouth, en Massachusetts – lugar de origen de la tristemente célebre festividad. Versión en largometraje del celebrado falso tráiler de Eli Roth para «Grindhouse».', trailer_url = 'https://www.youtube.com/watch?v=mQxbZubEv3A' WHERE id_api = 'tt1448754';

