UPDATE Contenido SET id_tmdb = 85889, descripcion = 'El detective Bruce Robertson (James McAvoy) es el detective de policía más maleducado, pervertido, misántropo y adicto a las drogas y al sexo de Edimburgo. A pesar de ello, Robertson quiere un ascenso. Claramente es la persona adecuada para el trabajo; el resto de sus colegas son idiotas. Desafortunadamente, ha habido un asesinato y el jefe de Bruce quiere resultados. No hay problema. Él está al mando y cuando resuelva el caso y consiga el ascenso su mujer volverá con él.', trailer_url = 'https://www.youtube.com/watch?v=tymWDB7gtK4' WHERE id_api = 'tt1450321';

UPDATE Contenido SET id_tmdb = 62211, descripcion = 'Desde que era pequeño, Mike Wazowski ha soñado con ser asustador y sabe que los mejores asustadores estudian en Monstruos University (MU). Pero durante su primer semestre en MU, los planes de Mike se desmoronan cuando se cruza con el listillo de James P. Sullivan, un asustador nato. El descontrolado espíritu competitivo de la pareja hace que los dos sean expulsados del programa de asustadores de la Universidad. Entonces se dan cuenta de que si quieren cumplir sus sueños, tienen que trabajar en equipo junto con un grupo de monstruos marginados.', trailer_url = 'https://www.youtube.com/watch?v=WzgYlDL0KJU' WHERE id_api = 'tt1453405';

