UPDATE Contenido SET id_tmdb = 37169, descripcion = 'Dos chicas norteamericanas que viajan a través de Europa tienen una avería en el coche en mitad de un bosque, en Alemania. Buscando ayuda llegan a una casa aislada y, al día siguiente, despiertan atrapadas en un tétrico sótano junto a un hombre japonés. Poco después descubren que están en manos de un siniestro médico alemán que anteriormente era un cirujano especializado en separar a gemelos siameses. Sin embargo, para ellos tiene otro escatológico plan, en los límites de lo imaginable...', trailer_url = 'https://www.youtube.com/watch?v=glfBurdSUS8' WHERE id_api = 'tt1467304';

