UPDATE Contenido SET id_tmdb = 41439, descripcion = 'Mientras una mortal batalla explota sobre el brutal legado de Jigsaw, un grupo de supervivientes busca el apoyo del gurú de la autoayuda Bobby Dagen, un hombre que con sus oscuros secretos provocará una nueva ola de terror.', trailer_url = 'https://www.youtube.com/watch?v=wemGRv2mWH4' WHERE id_api = 'tt1477076';

UPDATE Contenido SET id_tmdb = 522924, descripcion = 'El argumento está basado en la novela publicada por Garth Stein, la cual responde al mismo nombre que el filme. La historia combina diferentes sentimientos y situaciones comprometidas para la sociedad como son el dolor, la liberación, el cariño o el riesgo. Enzo, un perro que ha experimentado muchas aventuras interesantes a lo largo de su vida, es el personaje que pone voz a la película. Pese a no ser una persona de carne y hueso, este entrañable animal será capaz de dar diferentes lecciones a los seres humanos sobre cuál tendría que ser la manera adecuada de actuar sea cual sea la situación en la que se encuentren.', trailer_url = 'https://www.youtube.com/watch?v=Y5ISn-TZdFo' WHERE id_api = 'tt1478839';

UPDATE Contenido SET id_tmdb = 59678, descripcion = 'Divertida y aterradora película de aventuras que enfrenta a una banda de adolescentes contra una invasión de salvajes alienígenas, convirtiendo una zona marginal de Londres en una zona de peligrosos juegos de ciencia ficción. De la noche a la mañana, un bloque de pisos se convierte en una fortaleza sitiada y un grupo de adolescentes de la calle en héroes. El enfrentamiento entre el ghetto y el espacio exterior está servido.', trailer_url = 'https://www.youtube.com/watch?v=A4mf86YPqjM' WHERE id_api = 'tt1478964';

