UPDATE Contenido SET id_tmdb = 210232, descripcion = 'Se suponía que era la casa de sus sueños, pero pronto se convierte en un infierno para la familia Brannock. Las siniestras cartas que reciben de alguien que se hace llamar «el Vigilante» son solo el principio. Enseguida empiezan a salir a la luz los siniestros secretos del vecindario. Inspirada en la historia real de la tristemente célebre casa de Nueva Jersey.', trailer_url = 'https://www.youtube.com/watch?v=UFJvNxfsntA' WHERE id_api = 'tt14852808';

UPDATE Contenido SET id_tmdb = 70436, descripcion = 'Trata de los últimos días de la vida de Edgar Allan Poe. El escritor colabora en la búsqueda de un asesino cuyos crímenes se inspiran en sus obras. La muerte de Poe siempre ha estado envuelta en el misterio: fue encontrado en las calles de Baltimore, en un estado deplorable, vistiendo la ropa de otra persona, y repetía el nombre de Reynols, un explorador polar protagonista de sus novelas. Poco después, murió en el hospital sin llegar a explicar lo que le había sucedido. Sus últimas palabras fueron, ¡Que Dios ayude a mi pobre alma!', trailer_url = 'https://www.youtube.com/watch?v=OrzAQ_RetHg' WHERE id_api = 'tt1486192';

UPDATE Contenido SET id_tmdb = 840705, descripcion = 'Cuando el magnate de la tecnología Slater King (Channing Tatum) conoce a la camarera Frida (Naomi Ackie) en su gala de recaudación de fondos, saltan chispas. Él la invita a acompañarle a él y a sus amigos a unas vacaciones de ensueño en su isla privada. Un auténtico paraíso. Las noches salvajes se mezclan con mañanas bañadas por el sol y todo el mundo se lo pasa en grande. Nadie quiere que el viaje termine, pero cuando empiezan a suceder cosas extrañas, Frida intuye que algo anda mal en ese lugar. Tendrá que descubrir la verdad si quiere salir viva de la fiesta.', trailer_url = 'https://www.youtube.com/watch?v=5yZOzi5h54U' WHERE id_api = 'tt14858658';

