UPDATE Contenido SET id_tmdb = 399361, descripcion = 'Cinco amigos, todos ex veteranos militares y antiguos operativos de las Fuerzas Especiales, se reúnen para planificar un asalto a una zona fronteriza poco habitada en Sudamérica. El objetivo: robar a un poderoso narcotraficante. Por primera vez en sus prestigiosas carreras, estos héroes anónimos asumen una peligrosa misión en su propio beneficio y no en el de su país. Pero cuando la situación sufre un giro inesperado y amenaza con salirse de control, desencadenará una serie de consecuencias imprevistas.', trailer_url = 'https://www.youtube.com/watch?v=E3u-wS6l_NU' WHERE id_api = 'tt1488606';

UPDATE Contenido SET id_tmdb = 505600, descripcion = 'Dos excelentes estudiantes y grandes amigas, en la víspera de su graduación de su instituto, de repente se dan cuenta de que podrían haberse esforzado algo menos en clase y haberse divertido más. Así que deciden hacer algo al respecto para compensar tanto estudio y tan poca diversión: recuperar los años perdidos en una noche loca.', trailer_url = 'https://www.youtube.com/watch?v=PuErOBBz838' WHERE id_api = 'tt1489887';

UPDATE Contenido SET id_tmdb = 49520, descripcion = 'Durante la infancia y la adolescencia, Mitch (Ryan Reynolds) y Dave (Jason Bateman) fueron amigos inseparables, pero con el paso de los años se han ido distanciando. Dave es un abogado enganchado al trabajo, se ha casado y tiene tres hijos. Mitch sigue soltero, es bastante inmaduro, trabaja a veces y vive sin ataduras de ningún tipo. Mitch cree que Dave lo tiene todo: una preciosa esposa (Leslie Mann), unos niños que lo adoran y un buen trabajo en un prestigioso bufete. Dave, por su parte, envidia a Mitch porque vive sin estrés ni presión ni obligaciones. Un día, después de compartir una gran borrachera, los mundos de Mitch y Dave se vuelven del revés: cuando se despiertan cada uno ocupa el cuerpo del otro, de modo que no tendrán más remedio que intercambiar sus papeles.', trailer_url = 'https://www.youtube.com/watch?v=p3W7SIrMMaQ' WHERE id_api = 'tt1488555';

UPDATE Contenido SET id_tmdb = 858024, descripcion = 'Descubre la poderosa historia de amor que inspiró la creación de Hamlet, la intemporal obra maestra de Shakespeare.  La historia de Agnes, la esposa de William Shakespeare, en su lucha por superar la tragedia familiar que irrumpe en su vida. Una historia con el telón de fondo de la creación de una de las más conocidas e importantes obras de Shakespeare, ''Hamlet''.', trailer_url = 'https://www.youtube.com/watch?v=Ith7z6FzLe0' WHERE id_api = 'tt14905854';

