UPDATE Contenido SET id_tmdb = 72710, descripcion = 'En esta historia la Tierra ha sido invadida, pero la raza humana no se ha extinguido por completo, ya que los invasores se han apoderado de las mentes terrestres y han salvado sus cuerpos, que utilizan para transportarse. Esto hace que algunos de estos contenedores físicos, como el de Melanie Stryder (Saoirse Ronan, ''Hanna''), opongan resistencia a la invasión de su mente.  Melanie no se hace a la idea de perder el control de sí misma y envía a su alma invasora, Wanderer (la misma actriz), constantes reminiscencias de su pasado que contienen recuerdos del hombre al que amaba, Jared (Max Irons, ''El retrato de Dorian Gray'').  Debido a las sensaciones tan fuertes que recibe, Wanderer no puede hacerse con el control total de Melanie y empieza a desarrollar sentimientos hacia el hombre que aparece en su mente y que no conoce. Ambas fuerzas, la de Melanie y Wanderer, se aunarán para conseguir al mismo amante.', trailer_url = 'https://www.youtube.com/watch?v=Gu4kGA7b4ZY' WHERE id_api = 'tt1517260';

