UPDATE Contenido SET id_tmdb = 77866, descripcion = 'Hace tiempo que Chris Farraday (Mark Wahlberg) dejó el mundo de la delincuencia, pero cuando su cuñado Andy (Caleb Landry Jones) mete la pata en un asunto de drogas encargado por su implacable jefe Tim Briggs (Giovanni Ribisi), Chris se ve obligado a volver a hacer lo que mejor se le da, pasar contrabando, para pagar la deuda de Andy. Chris es un legendario contrabandista y no tarda en reunir a un equipo de primera con la ayuda de su mejor amigo, Sebastian (Ben Foster), y realizar un último viaje a Panamá para traer millones de dólares en billetes falsos.  Pero las cosas no salen como estaba previsto y con solo unas horas para hacerse con el dinero, Chris deberá hacer uso de sus oxidadas habilidades y superar una traicionera red criminal con brutales narcos, polis y sicarios, antes de que su esposa Kate (Kate Beckinsale) y sus hijos se conviertan en objetivos.', trailer_url = 'https://www.youtube.com/watch?v=QL598xrteO4' WHERE id_api = 'tt1524137';

