UPDATE Contenido SET id_tmdb = 49526, descripcion = '“Sin frenos” nos relatará la historia Wilee (Joseph Gordon-Levitt), un mensajero de Nueva York. Esquivar coches a toda velocidad, taxistas enloquecidos y ocho millones de peatones malhumorados forma parte de su día a día, pero él es el mejor entre los ágiles y agresivos mensajeros en bicicleta de Nueva York. Hay que ser de una raza especial, con una mezcla a partes iguales de pericia y chifladura, para conducir una fixie –bicicleta superligera, sin cambios ni frenos— arriesgándose a convertirse en una mancha más sobre el pavimento cada vez que se mueve entre el tráfico de la ciudad. Pero un tipo que está acostumbrado a arriesgar su vida continuamente, está a punto de enfrentarse a peligros aún mayores cuando su última entrega del día —lo que en principio parecía un servicio premium rutinario— acaba convirtiéndose en una persecución a vida o muerte a través de las calles de Manhattan.', trailer_url = 'https://www.youtube.com/watch?v=zhUqykv4f_I' WHERE id_api = 'tt1547234';

