UPDATE Contenido SET id_tmdb = 109491, descripcion = 'El hastío domina la vida de Ethan Wate, un chico que vive en un pueblo perdido del sur de los Estados Unidos. Pero, un día conoce a Lena Duchannes, que es exactamente la chica de sus sueños.. y de sus pesadillas. Cuento de amores contrariados que esconde un oscuro y peligroso secreto. Adaptación de una de las novelas tituladas "Sixteen Moons" (Dieciséis lunas).', trailer_url = 'https://www.youtube.com/watch?v=XpbswZaTHfI' WHERE id_api = 'tt1559547';

UPDATE Contenido SET id_tmdb = 338967, descripcion = 'En esta secuela y empleando el característico sentido del humor del que hizo gala "Zombieland", el grupo de protagonistas tendrá que viajar desde la Casa Blanca hasta el corazón de los Estados Unidos, sobreviviendo a nuevas clases de muertos vivientes que han evolucionado desde lo sucedido hace algunos años, así como a algunos supervivientes humanos rezagados. Pero, por encima de todo, tendrán que tratar de soportar los inconvenientes de convivir entre ellos.', trailer_url = 'https://www.youtube.com/watch?v=xJhsJql7x6s' WHERE id_api = 'tt1560220';

UPDATE Contenido SET id_tmdb = 51828, descripcion = 'Emma y Dexter se conocen el día de su graduación universitaria, el 15 de julio de 1988. Ella es una chica de clase trabajadora que sueña con hacer del mundo un lugar mejor. Él es un joven rico con ganas de comerse el mundo. Durante los siguientes veinte años, las vidas de ambos se cruzan y separan, su amistad se debilita o se refuerza y comparten la risa y el romance, el dolor y la alegría. Pero por fin, un día, ambos se dan cuenta de que lo que habían estado buscando durante tanto tiempo estaba delante de ellos.', trailer_url = 'https://www.youtube.com/watch?v=HPHlo41yeY0' WHERE id_api = 'tt1563738';

UPDATE Contenido SET id_tmdb = 61202, descripcion = 'Kabir Dhiman, perteneciente a una familia acaudalada de constructores de Bombay, se propone a su novia de siempre, Natasha, ante el deleite de sus respectivas familias. Como despedida de soltería quiere irse de viaje con sus amigos Imran Habib y Arjun en cumplimiento de un pacto de sus años de adolescencia. El viaje será a España. El trío comenzará su viaje no plenamente consciente que Arjun aún no ha perdonado a Imran por su ruptura con Sunani. Durante el viaje les ocurrirá infinidad de historias.', trailer_url = 'https://www.youtube.com/watch?v=FJrpcDgC3zU' WHERE id_api = 'tt1562872';

UPDATE Contenido SET id_tmdb = 41517, descripcion = 'Siguiendo la sugerencia de su hijo, un diseñador de videojuegos crea un juego de acción y aventura donde el villano tiene inteligencia artificial y es más fuerte que el protagonista. Los problemas comienzan cuando el hijo del creador se ve obligado a abandonar el juego en el medio, para decepción del villano que cambia de forma del juego y que luego cobra vida utilizando una tecnología recién inventada. El jugador ahora debe escapar de él o de lo contrario podría ser asesinado, algo que solo el protagonista menos poderoso del juego puede evitar que suceda.', trailer_url = 'https://www.youtube.com/watch?v=d9PlHc_qVKw' WHERE id_api = 'tt1562871';

UPDATE Contenido SET id_tmdb = 42684, descripcion = 'Se suponía que el viaje de Jarrod y Elaine al sur de California iba a ser una simple escapada de fin de semana para ir a ver al mejor amigo de Jarrod, Terry, y a su novia, Candice, por el cumpleaños de éste. Pero, cuando el amanecer parece llegar dos horas antes, provocado por una intensa e inquietante luz procedente de una fuente desconocida, su vida tal y como la conocen ha llegado a su fin. Desde las ventanas del ático de Terry, observan aterrados mientras por toda la ciudad la gente se ve atraída al exterior y desaparecen en inmensas naves alienígenas que cubren el cielo de Los Ángeles. Ahora, tendrán que hacer acopio de todo su instinto de supervivencia para evitar ser capturados por las miles de monstruosas criaturas que recorren la ciudad en busca de cualquier humano que haya logrado escapar de su asalto inicial. Desde tanques a zánganos o extraterrestres parecidos a hidras.', trailer_url = 'https://www.youtube.com/watch?v=cjPNaArFpQc' WHERE id_api = 'tt1564585';

UPDATE Contenido SET id_tmdb = 884605, descripcion = 'A punto de perder el hogar de su infancia, Maddie descubre una oferta de trabajo intrigante: padres adinerados que buscan a alguien con quien "salir" con su introvertido hijo de 19 años, Percy, antes de que se vaya a la universidad. Para su sorpresa, Maddie pronto descubre que el incómodo Percy no es algo seguro.', trailer_url = 'https://www.youtube.com/watch?v=WzR55awCD2c' WHERE id_api = 'tt15671028';

UPDATE Contenido SET id_tmdb = 80389, descripcion = 'En “Vacaciones en el infierno” conoceremos a Driver (Mel Gibson), un tipo que ha tenido un mal día. Y la cosa no mejora para él: se ha hecho con un botín de millones de dólares que le habría proporcionado unas vacaciones de verano memorables, pero esta idea se vino literalmente abajo. Durante una persecución automovilística a toda velocidad con la policía de la frontera y un cuerpo sangrando en el asiento trasero, Driver vuelca el coche y lo estampa contra el muro fronterizo para terminar cabeza abajo en México. Capturado por las autoridades mexicanas, le envían a una cárcel de mala muerte, donde se adentrará en el peligroso mundo de El Pueblito. No lo tendrá fácil para sobrevivir un forastero como él, a menos que sea con la ayuda de alguien que sepa de qué cabo tirar en cada momento: un niño de 10 años.', trailer_url = 'https://www.youtube.com/watch?v=TtU4LclCW7M' WHERE id_api = 'tt1567609';

