UPDATE Contenido SET id_tmdb = 137893, descripcion = 'Esta serie de ficción basada en hechos reales narra la trayectoria de Griselda Blanco desde Medellín hasta que se erigió en «la Madrina» del emporio de la droga de Miami.', trailer_url = 'https://www.youtube.com/watch?v=wcF0A-Gy-Ng' WHERE id_api = 'tt15837600';

