UPDATE Contenido SET id_tmdb = 82532, descripcion = 'Es la historia de dos hermanos, uno de ellos (Helms) está inmerso en una semi-crisis, y piensa que su mujer (Greer) tiene una aventura. El otro es un adorable perdedor (Segel) que todavía vive en casa de su madre (Sarandon). Un día, los hermanos salen a espiar a la mujer, con todo tipo de consecuencias imprevistas.', trailer_url = 'https://www.youtube.com/watch?v=jPB-VLLDruw' WHERE id_api = 'tt1588334';

UPDATE Contenido SET id_tmdb = 54186, descripcion = 'En el último día de clase de un instituto, una profesora se despide de los alumnos con el anuncio de que deja la escuela, pero añadiendo una confesión: su hija de cuatro años, fallecida recientemente al ahogarse en la piscina de la escuela, fue en realidad asesinada por dos de los estudiantes de esa misma clase.Y, añade, ya ha puesto en marcha su venganza contra ellos.', trailer_url = 'https://www.youtube.com/watch?v=dD1N5x1VGHY' WHERE id_api = 'tt1590089';

UPDATE Contenido SET id_tmdb = 399035, descripcion = 'Durante su trayecto habitual de vuelta a casa en tren, un hombre de negocios felizmente casado comienza a hablar con una misteriosa pasajera. Pronto el hombre se verá envuelto en una conspiración criminal que amenaza con poner en peligro tanto su vida como la de sus seres más cercanos.', trailer_url = 'https://www.youtube.com/watch?v=GxHM7YhIt_k' WHERE id_api = 'tt1590193';

UPDATE Contenido SET id_tmdb = 81796, descripcion = 'La MS1 es una prisión experimental en el espacio, que orbita a 50 millas de la Tierra, donde los 500 criminales más peligrosos del planeta se encuentran retenidos en un estado de “letargo” inducido. A la cabeza de una misión humanitaria, la hija del presidente de los Estados Unidos, Emilie Warnock (Maggie Grace) llega a bordo de la prisión justo antes del estallido de un motín. Emilie y los trabajadores de la MS1 son tomados como rehenes por los violentos internos. El presidente Warnock decide enviar al agente Snow (Guy Pierce) a la MS1 con la única misión de salvar a Emilie a toda costa. Snow es un convicto encerrado por conspiración y espionaje contra los Estados Unidos.', trailer_url = 'https://www.youtube.com/watch?v=1Z0NlcfxIa8' WHERE id_api = 'tt1592525';

UPDATE Contenido SET id_tmdb = 75674, descripcion = '''Acto de valor'' nos introduce en el día a día de la Armada de los Estados Unidos (a los que se denomina como Navy SEALs). En ella seguiremos los entrenamientos y las maniobras de un grupo de aguerridos soldados que se preparan día a día para poder emprender las tareas físicas y también las estrategias militares más insospechadas.  La mayor parte de las acciones que se emprenden en la película tienen una base de autenticidad. Cuando se desarrollan las tácticas militares, es como si estuviéramos presenciándolas de primera mano, casi como si se tratara de un documental. Los miembros de la brigada tendrán que hacer frente en esta ocasión a una conspiración internacional relacionada con el terrorismo y se embarcarán en una misión de alto secreto para mantener estable la paz mundial.', trailer_url = 'https://www.youtube.com/watch?v=35b_UqGYZgw' WHERE id_api = 'tt1591479';

UPDATE Contenido SET id_tmdb = 1265609, descripcion = 'En una última misión agotadora durante el entrenamiento para ser ranger, un ingeniero de combate debe liderar a su unidad contra una gigantesca máquina asesina de otro mundo.', trailer_url = 'https://www.youtube.com/watch?v=3o0qf9I3rY8' WHERE id_api = 'tt15940132';

UPDATE Contenido SET id_tmdb = 43959, descripcion = 'Basada en un hecho real, cuenta la historia de la surfista Bethany Hamilton quién tras perder un brazo tras el ataque de un tiburón gracias a su coraje no sólo volvió a competir, sino que además se volvió a proclamar campeona.', trailer_url = 'https://www.youtube.com/watch?v=MWeOjBCi3c4' WHERE id_api = 'tt1596346';

UPDATE Contenido SET id_tmdb = 51497, descripcion = 'Desde que Brian O''Conner y Mia Toretto sacaron a Dom Toretto de la cárcel, se han visto obligados a huir y cruzar muchas fronteras para evitar a la policía. Atrapados en Río de Janeiro, una vez más tienen que darse a la fuga si quieren conservar la libertad. Pero los tres saben muy bien que la única posibilidad que tienen de poner fin a esta situación es enfrentarse de una vez por todas al empresario corrupto que quiere verlos muertos. Pero éste no es el único que les sigue la pista.', trailer_url = 'https://www.youtube.com/watch?v=wvlF7e6377I' WHERE id_api = 'tt1596343';

UPDATE Contenido SET id_tmdb = 34307, descripcion = 'En la peculiar familia Gallagher, Frank, un padre soltero y alcohólico, intenta educar a sus seis inteligentes, salvajes e independientes hijos.

Es un remake estadounidense de la serie británica del mismo nombre.', trailer_url = 'https://www.youtube.com/watch?v=9tvkYS5cA58' WHERE id_api = 'tt1586680';

