UPDATE Contenido SET id_tmdb = 32868, descripcion = 'Readaptación de la película original de Luc Besson. A diferencia de los proyectos anteriores, esta versión, creada por Craig Silverstein, presentará a una nueva Nikita siendo entrenada para reemplazar a la original luego de que decide alejarse de la agencia.', trailer_url = 'https://www.youtube.com/watch?v=ySr1u6jguHQ' WHERE id_api = 'tt1592154';

