UPDATE Contenido SET id_tmdb = 318846, descripcion = 'Cuando cuatro tipos fuera del sistema descubren que los grandes bancos, los medios de comunicación y el gobierno se niegan a reconocer el colapso de la economía, tienen una idea: ''La Gran Apuesta''…  pero sus inversiones de riesgo les conducen al lado oscuro de la banca moderna, donde deben poner en duda todo y a todos...', trailer_url = 'https://www.youtube.com/watch?v=gjF_W4UxqRA' WHERE id_api = 'tt1596363';

UPDATE Contenido SET id_tmdb = 65086, descripcion = 'Arthur Kipps es un joven abogado cuya empresa lo envía a un lugar remoto para vender la casa de un cliente que acaba de fallecer. La gestión, aparentemente rutinaria, tropieza con ciertas dificultades: los vecinos se muestran reacios a hablar sobre la casa o a acercarse a ella; además, nadie está dispuesto a admitir la existencia de una mujer de negro que él está seguro de haber visto', trailer_url = 'https://www.youtube.com/watch?v=9M9by8N3Yrw' WHERE id_api = 'tt1596365';

UPDATE Contenido SET id_tmdb = 975533, descripcion = 'Ambientado en la década de 1960 en la India, en el pueblo de montaña ficticio de Riverdale, Los Archies es un musical sobre hacerse adulto protagonizado por los adolescentes más populares del pueblo, Archie, Betty, Veronica, Jughead, Reggie, Ethel y Dilton.', trailer_url = 'https://www.youtube.com/watch?v=07zwmOypaV8' WHERE id_api = 'tt15979666';

UPDATE Contenido SET id_tmdb = 59961, descripcion = 'Matt Weston lleva un año en Ciudad del Cabo trabajando como “guardián” de un piso franco. Aspira a convertirse en un agente respetado en la CIA, y se siente frustrado al no haber sido destinado a un puesto con más acción. Pero cuando el primer huésped del piso resulta ser el peligroso Tobin Frost, Weston se prepara para lo peor. Frost, antaño uno de los mejores agentes encubiertos que tuvo la CIA, ha conseguido escapar de sus perseguidores durante casi una década, tiempo que ha dedicado a vender secretos militares al mejor postor. Tan pronto como Frost llega para ser interrogado, aparecen unos mercenarios que arrasan el piso franco de Weston. Los dos consiguen escapar por los pelos, y ahora tendrán que descubrir si sus atacantes fueron enviados por terroristas o por alguien de dentro dispuesto a matar a cualquiera que se interponga en su camino.', trailer_url = 'https://www.youtube.com/watch?v=d7zBeMjK_0g' WHERE id_api = 'tt1599348';

UPDATE Contenido SET id_tmdb = 54054, descripcion = 'Stephanie Plum no está precisamente en racha. A sus 30 años acaba de salir de un divorcio, la han despedido y vive con su hámster en Trenton (Nueva Jersey). Sin blanca y desesperada, empieza a trabajar para un rastrero primo suyo, que es agente de fianzas. La urgente necesidad de conseguir dinero la lleva a encargarse de un caso muy difícil: la búsqueda de un policía local acusado de asesinato, que resulta ser el chico del que se enamoró en el instituto. La investigación acaba arrastrándola al mundo del crimen.', trailer_url = 'https://www.youtube.com/watch?v=8IGnFELC9vU' WHERE id_api = 'tt1598828';

UPDATE Contenido SET id_tmdb = 62838, descripcion = 'Film que comprende varias historias que tienen lugar entre Nochevieja y Año Nuevo: la de un hombre hospitalizado que vive sus últimos días, la de un hombre que odia las fiestas navideñas, la de una mujer de negocios que trata de alcanzar sus propósitos antes de que acabe el año, y la de una mujer que produce un espectáculo en el Time Square de Manhattan.', trailer_url = 'https://www.youtube.com/watch?v=pnDzKi5j_9Q' WHERE id_api = 'tt1598822';

UPDATE Contenido SET id_tmdb = 86837, descripcion = 'Crudo retrato de la vejez y de la muerte. Jean-Louis Trintignant y Emmanuelle Riva forman una pareja ya octogenaria, músicos retirados, que viven en París. Isabelle Huppert interpreta a la hija de ambos. El amor de la pareja será puesto a prueba en el momento en que ella sufre una grave parálisis.', trailer_url = 'https://www.youtube.com/watch?v=I3JYvawTuFA' WHERE id_api = 'tt1602620';

UPDATE Contenido SET id_tmdb = 154400, descripcion = 'En Brooklyn, un solitario camarero rescata a un cachorro de un cubo de basura. Sus problemas empiezan cuando aparece el dueño del animal, un hombre con problemas mentales que, además, está involucrado en una conspiración criminal que se planea en el bar en el que trabaja el camarero.', trailer_url = 'https://www.youtube.com/watch?v=RJZtoAKDf_8' WHERE id_api = 'tt1600196';

UPDATE Contenido SET id_tmdb = 77987, descripcion = 'En Bangkok, Julian, un fugitivo de la justicia estadounidense, dirige un club de boxeo tailandés que actúa como tapadera para su tráfico de estupefacientes. Su madre, jefe de una amplia organización criminal, desembarca procedente de Estados Unidos para repatriar el cuerpo de su hijo favorito, Billy: el hermano de Julian ha sido asesinado tras haber masacrado salvajemente a una joven prostituta. Llena de odio y venganza, exige a Julian la cabeza de los asesinos. Julian deberán entonces enfrentarse a Chang, un extraño policía jubilado, adulado por los demás policías.', trailer_url = 'https://www.youtube.com/watch?v=XiSq-7QQDQg' WHERE id_api = 'tt1602613';

UPDATE Contenido SET id_tmdb = 32692, descripcion = 'Frank Reagan es el jefe del Departamento de Policía de Nueva York. El duro oficial dirige el cuerpo tan diplomáticamente como a su familia, una saga de policías marcada por la trágica pérdida del hijo mayor.', trailer_url = 'https://www.youtube.com/watch?v=mi6USkjUWv4' WHERE id_api = 'tt1595859';

