UPDATE Contenido SET id_tmdb = 138502, descripcion = 'X-Men ''97 vuelve a la icónica época de los años 90, donde los X-Men, un grupo de mutantes que utilizan sus asombrosos poderes para proteger a un mundo que los odia y los teme, se enfrentarán a su mayor desafío y a un nuevo, insospechado y peligroso futuro.', trailer_url = 'https://www.youtube.com/watch?v=O8Gt7T6VgCw' WHERE id_api = 'tt16026746';

UPDATE Contenido SET id_tmdb = 171372, descripcion = 'Trata sobre un joven aspirante a músico, Jon, quien descubre que ha mordido más de lo que puede masticar cuando se une a un grupo de excéntricos músicos pop liderado por el misterioso y enigmático Frank y su complicada compañera Clara.', trailer_url = 'https://www.youtube.com/watch?v=Wptv2iDdTZM' WHERE id_api = 'tt1605717';

UPDATE Contenido SET id_tmdb = 210916, descripcion = 'Un joven y temerario abogado es reclutado por la CIA al salir de la facultad de Derecho y se adentra sin preparación en el peligroso mundo del espionaje internacional.', trailer_url = NULL WHERE id_api = 'tt16030542';

UPDATE Contenido SET id_tmdb = 71552, descripcion = 'Un grupo de viejos amigos vuelven a reunirse. Jim y Michelle siguen felizmente casados, aunque hay una vecina que se ha enamorado de él. Además, la cinta sexual con Nadia se ha convertido en uno de los videos más vistos de Youtube. Por su parte, Oz vive en una mansión de Malibú, pero su novia parece sólo interesada por su dinero. Mientras tanto, la vida de Stifler sigue siendo un desastre. Heather sale con un cirujano que intenta parecer más joven, y Finch, que ha viajado por el mundo, intenta ligar con Trish, una camarera amiga de Michelle.', trailer_url = 'https://www.youtube.com/watch?v=1PmZl3E9y9o' WHERE id_api = 'tt1605630';

UPDATE Contenido SET id_tmdb = 72570, descripcion = 'Un accidente de coche deja a Paige en coma. Cuando se despierta ha perdido la memoria, y ni siquiera reconoce a su marido Leo, con el que llevaba poco tiempo casada. Leo tendrá entonces que trabajar para ganarse de nuevo el corazón de su amada esposa.', trailer_url = 'https://www.youtube.com/watch?v=rc70kHj1wn0' WHERE id_api = 'tt1606389';

UPDATE Contenido SET id_tmdb = 32798, descripcion = 'Hawái 5.0 es una versión moderna de la recordada serie de los años sesenta sobre una división especial de la policía encargada de terminar con el crimen en Hawaii. En esta nueva versión seguimos al detective Steve McGarrett (Alex O’Loughlin), un ex-oficial de la marina convertido en policía, que llega a Oahu para investigar el asesinato de su padre y es convencido a quedarse en Hawaii al liderar su propio equipo especial. Junto a McGarrett encontramos al detective Danny “Danno” Williams (Scott Caan), un ex-policía de New Jersey que prefiere la ciudad pero esta decidido a mantener la seguridad en la isla por su pequeña hija; y a Chin Ho Kelly (Daniel Dae Kim), un ex-detective de Honolulu acusado erróneamente de corrupción. El ultimo miembro del equipo es la prima de Chin, Kono (Grace Park), una bella local, recién salida de la academia y deseosa de establecerse en el equipo de elite.', trailer_url = 'https://www.youtube.com/watch?v=xy30TGdaEAE' WHERE id_api = 'tt1600194';

