UPDATE Contenido SET id_tmdb = 329833, descripcion = 'Diez años después de conocerse entre pasarelas y sesiones de fotos, Derek y Hansel han caído en el olvido. Deciden entonces emprender una nueva aventura en busca de la fama y el éxito que perdieron. Para ello, viajan a Europa para enfrentarse a las nuevas celebridades. Secuela de "Zoolander" (2001).', trailer_url = 'https://www.youtube.com/watch?v=4CL4LNWHegk' WHERE id_api = 'tt1608290';

UPDATE Contenido SET id_tmdb = 55725, descripcion = 'Mike Flaherty (Giamatti), un abogado sin demasiada suerte en su trabajo, dedica su tiempo libre a entrenar a los muchachos de una escuela de lucha libre. En un momento dado, Mike asume la defensa de un viejo cliente con la esperanza de mantenerse a flote y sacar de apuros a su familia. Sin embargo, cuando el nieto adolescente de su cliente, toda una promesa deportiva, escapa de casa y y se va con su abuelo, la vida de Mike dará un giro completo.', trailer_url = 'https://www.youtube.com/watch?v=_TfeGeg6Erg' WHERE id_api = 'tt1606392';

UPDATE Contenido SET id_tmdb = 72331, descripcion = 'Indiana, 1818. La luz de la luna cae a través de los densos bosques que rodean una cabaña, donde un niño de nueve años llamado Abraham Lincoln se arrodilla junto a la cama de su madre que sufre. Ella ha sido atacada por algo que los lugareños llaman "Enfermedad de la Leche". Mi niño... susurra antes de morir. Más tarde, el niño se da cuenta de que la enfermedad mortal de su madre era en realidad obra de un vampiro. A partir de ese momento, el niño comienza un diario, y se propone ser un maestro de la mente y el cuerpo, con un sólo objetivo: Emprender un camino de venganza que le llevará a la Casa Blanca.', trailer_url = 'https://www.youtube.com/watch?v=QRiHF-u0kQE' WHERE id_api = 'tt1611224';

UPDATE Contenido SET id_tmdb = 70670, descripcion = 'Roger es un reputado cazatalentos noruego que vive en una maravillosa casa de campo con su esposa Diana, la bella propietaria de una galería de arte. En realidad, está viviendo muy por encima de sus posibilidades; si puede mantener ese ritmo de vida es gracias a que se dedica a robar obras de arte. En la inauguración de una galería, su esposa le presenta a Clas Greve, que, además de ser el candidato perfecto para el cargo de director general de la compañía de Roger, es propietario de una pintura muy valiosa. Roger ve que le ha llegado la oportunidad de alcanzar definitivamente la independencia económica y empieza a planear el robo del cuadro.', trailer_url = 'https://www.youtube.com/watch?v=hh4dxEX6GMs' WHERE id_api = 'tt1614989';

UPDATE Contenido SET id_tmdb = 70667, descripcion = 'El explorador noruego Thor Heyerdahl cruzó el Pacífico en una balsa de madera en 1947, para demostrar que los sudamericanos de antes de Colón podían haber cruzado el mar para instalarse en la Polinesia. Thor, junto a cinco hombres, partió en una travesía épica de 101 días a través de 8.000 kilómetros llenos de tormetas, tiburones y hambre, mientras el resto del mundo aguardaba el resultado del viaje.', trailer_url = 'https://www.youtube.com/watch?v=cL_cTT6uZ8s' WHERE id_api = 'tt1613750';

UPDATE Contenido SET id_tmdb = 82525, descripcion = 'Dos jóvenes emprendedores de Laguna Beach, Ben (Aaron Johnson), un budista pacífico y caritativo, y su mejor amigo Chon (Taylor Kitsch), ex miembro de las fuerzas especiales de la Marina estadounidense y ex mercenario, han montado un lucrativo negocio casero: cultivar y vender una de las mejores marías que jamás se ha obtenido. También comparten un amor único con la extraordinaria y bella O. (Blake Lively). Ambos llevan una vida idílica en este pueblecito del sur de California… hasta que se instala un cártel mexicano de Baja California y exige que el trío se asocie con ellos. Pero la despiadada jefa del cártel (Salma Hayek) y su brutal matón Lado (Benicio Del Toro) no toman en cuenta la fuerza del vínculo que une a los tres amigos. Ben y Chon, con la ayuda que les proporciona a regañadientes un corrupto y escurridizo agente de la DEA (John Travolta), deciden librar una guerra imposible contra el cártel.', trailer_url = 'https://www.youtube.com/watch?v=fhRlaeV4LDE' WHERE id_api = 'tt1615065';

UPDATE Contenido SET id_tmdb = 33907, descripcion = 'Serie británica que se desarrolla en el año 1912, durante el reinado de Jorge V, y que retrata a la sociedad aristocrática de aquella época y sus litigios para ganar o mantener sus títulos nobiliarios.', trailer_url = 'https://www.youtube.com/watch?v=EOM3y4P8TEM' WHERE id_api = 'tt1606375';

UPDATE Contenido SET id_tmdb = 379149, descripcion = 'Quan es un humilde empresario londinense cuyo pasado, largamente sepultado, estalla en una venganza feroz cuando la única persona que le queda en la vida, su hija adolescente, muere en un atentado terrorista del IRA. Su implacable búsqueda de los terroristas le lleva a un juego del gato y el ratón con un funcionario del gobierno británico, en cuyo pasado puede estar la pista de las identidades de los escurridizos asesinos.', trailer_url = 'https://www.youtube.com/watch?v=m1JJ5NJZkUA' WHERE id_api = 'tt1615160';

UPDATE Contenido SET id_tmdb = 88794, descripcion = 'En 1924, con sólo 29 años, Edgar Hoover fue nombrado director general del FBI para que reorganizara la institución. Ocupó el cargo hasta su muerte en 1972, sobreviviendo a siete presidentes, alguno de los cuales intentó inútilmente destituirlo. Los archivos que Hoover guardaba celosamente, llenos de secretos inconfesables de importantes personalidades, lo convirtieron en uno de los hombres más poderosos y temidos de la historia de los Estados Unidos.', trailer_url = 'https://www.youtube.com/watch?v=PLXKGFsdqnE' WHERE id_api = 'tt1616195';

UPDATE Contenido SET id_tmdb = 76757, descripcion = 'La película se centra en formas superiores de vida que nos vigilan desde otros mundos. Júpiter Jones, una inmigrante rusa que se dedica a fregar retretes para ganarse la vida, posee la misma composición genética que la Reina del Universo, por lo que será considerada como una amenaza para estos seres inmortales, que enviarán a un cazador exmilitar, Caine, para dar con ella.', trailer_url = 'https://www.youtube.com/watch?v=z_9WN9lgjow' WHERE id_api = 'tt1617661';

