UPDATE Contenido SET id_tmdb = 481084, descripcion = 'Los integrantes de la espeluznante familia Addams preparan una fiesta a la que asistirán sus terroríficos familiares, pero una amenaza se cierne sobre todos ellos: una estrella de la televisión se ha dado cuenta de que la lúgubre mansión de la familia le impide vender todas las casas del vecindario y hará lo que sea necesario para deshacerse de ellos.', trailer_url = 'https://www.youtube.com/watch?v=pDgn0IrXOVk' WHERE id_api = 'tt1620981';

UPDATE Contenido SET id_tmdb = 62206, descripcion = 'Nick (Jesse Eisenberg), un repartidor de pizzas, colisiona con los grandes planes de dos aspirantes a delincuentes (Danny McBride y Nick Swardson). Esta pareja de perdedores secuestra a Nick y le ata una bomba de relojería al cuerpo, amenazando con hacerla explosionar si él se niega a atracar un banco. Con tan solo un par de horas para hacer lo imposible, Nick pide ayuda a su amigo de toda la vida, Chet (Aziz Ansari). Según pasan los segundos, Nick y Chet tendrán que lidiar con policías, asesinos a sueldo, lanzallamas, y su propio pasado.', trailer_url = 'https://www.youtube.com/watch?v=yipV06G5TNI' WHERE id_api = 'tt1622547';

UPDATE Contenido SET id_tmdb = 67660, descripcion = '“Think Like a Man” se centra en la historia de amor que mantienen un soñador con talentos culinarios y una prestigiosa ejecutiva dedicada al mundo de la publicidad. Por su parte, Kevin Hart se pone en la piel de un experto a la hora de ayudar a las parejas en sus relaciones (lo curioso del caso es que el hombre está a punto de divorciarse).', trailer_url = 'https://www.youtube.com/watch?v=vxTN4eX4Vss' WHERE id_api = 'tt1621045';

UPDATE Contenido SET id_tmdb = 68728, descripcion = 'Recrea los orígenes del Mago de Oz. Oscar Diggs (James Franco), un mago de circo de poca monta y de dudosa reputación, tiene que abandonar la polvorienta Kansas y trasladarse al brillante País de Oz. Está convencido de que a partir de ahora la fama y la fortuna le sonreirán. Pero, cuando las brujas Theodora (Mila Kunis), Evanora (Rachel Weisz) y Glinda (Michelle Williams) empiezan a dudar de su categoria como mago, entonces todo serán problemas para él. Si quiere triunfar, tendrá que averiguar cuanto antes quiénes son buenos y quiénes son malos.', trailer_url = 'https://www.youtube.com/watch?v=KrQLcxR8o8U' WHERE id_api = 'tt1623205';

UPDATE Contenido SET id_tmdb = 77174, descripcion = 'Los aterrorizados habitantes de un pueblo asediado por zombis solo pueden pedir ayuda al incomprendido Norman, un joven que sabe hablar con los muertos. Además de plantar cara a los muertos vivientes, tendrá que enfrentarse a fantasmas, brujas y, lo que es peor, a adultos de lo más atontados para salvar a su pueblo de una maldición milenaria.', trailer_url = 'https://www.youtube.com/watch?v=5ivARRy6CiY' WHERE id_api = 'tt1623288';

UPDATE Contenido SET id_tmdb = 55779, descripcion = 'Sam Lawton tiene una premonición sobre la destrucción de un puente colgante que causaría su muerte y la de otras personas. La visión se hace realidad, pero Sam se las arregla para salvarse a sí mismo y a algunos otros de la catastrófica tragedia. Sin embargo, Sam y su novia Molly descubren que no están realmente a salvo: la muerte los persigue a ellos y a los que sobrevivieron al horrible accidente... Quinta entrega de la popular serie de terror "Destino final".', trailer_url = 'https://www.youtube.com/watch?v=24abND3yDq0' WHERE id_api = 'tt1622979';

