UPDATE Contenido SET id_tmdb = 47933, descripcion = 'Utilizando la tecnología que los extraterrestres tenían 20 años antes, las naciones de la Tierra, que temen el regreso de los invasores, han colaborado en la elaboración de un gigantesco programa de defensa para proteger el planeta. Pero no es seguro que ese programa sirva para hacer frente a los avanzados e inauditos recursos de los atacantes. Quizá sólo la inventiva de unos pocos valientes pueda evitar la destrucción del mundo, que se encuentra de nuevo al borde de la extinción. Secuela del gran éxito de 1996 "Independence Day".', trailer_url = 'https://www.youtube.com/watch?v=Qryj2jkG3RI' WHERE id_api = 'tt1628841';

