UPDATE Contenido SET id_tmdb = 338762, descripcion = 'Ray Garrison, también conocido como Bloodshot, es resucitado por la compañía Rising Spirit Technologies a través del uso de nanotecnología. Mientras lucha por recuperar la memoria, Ray trata de volver a ser el que era antes de sufrir el accidente que le dejaría amnésico.', trailer_url = 'https://www.youtube.com/watch?v=5nOea-_3iKI' WHERE id_api = 'tt1634106';

