UPDATE Contenido SET id_tmdb = 58233, descripcion = 'Johnny English, el mejor espía del MI7 (Rowan Atkinson) parece haber desaparecido de la faz de la Tierra pero, en realidad, ha estado perfeccionado sus extraordinarias habilidades en una lejana región de Oriente. Cuando sus jefes se enteran de que alguien planea un atentado contra el primer ministro chino, no les queda más remedio que localizar al poco ortodoxo agente, que ahora tendrá la posibilidad de redimirse y utilizar lo último en tecnología punta para desenredar una complicada conspiración que implica al KGB, a la CIA e incluso al MI7. Faltan pocos días para que se celebre una conferencia estatal y él deberá usar todos sus trucos para proteger a todos los participantes. En la mente de Johnny English el desastre puede ser una opción, pero el fracaso, jamás.', trailer_url = 'https://www.youtube.com/watch?v=wCsSzZU-sQ4' WHERE id_api = 'tt1634122';

UPDATE Contenido SET id_tmdb = 49530, descripcion = 'Ambientada en una sociedad futura. El hallazgo de una fórmula contra el envejecimiento trae consigo no solo superpoblación, sino también la transformación del tiempo en moneda de cambio, que permite sufragar tanto lujos como necesidades. Los ricos pueden vivir para siempre, pero los demás tendrán que negociar cada minuto de vida, y los pobres mueren jóvenes. Después de conseguir, por casualidad, una inmensa cantidad de tiempo, Will Salas, un joven obrero, será perseguido por unos policías corruptos conocidos como "los guardianes del tiempo". En su huida, Will tomará como rehén a una joven de familia adinerada.', trailer_url = 'https://www.youtube.com/watch?v=s9wiOtYFZwk' WHERE id_api = 'tt1637688';

