UPDATE Contenido SET id_tmdb = 72105, descripcion = 'La historia se centra en las aventuras de un hombre que ve cómo su osito de peluche de la infancia adquiere vida debido a un deseo que formuló cuando era pequeño, convirtiéndose el peluche en un gandul deslenguado que alterará por completo su vida y pondrá en peligro su relación amorosa con su pareja, debido a su comportamiento totalmente salvaje y su conducta fuera de toda norma social.', trailer_url = 'https://www.youtube.com/watch?v=tvaTGUOVtsE' WHERE id_api = 'tt1637725';

UPDATE Contenido SET id_tmdb = 200727, descripcion = 'Rosie y Alex son los mejores amigos del mundo y viven en Dublín. Desde su infancia, habían confiado el uno en el otro y se habían contado sus secretos y confidencias. En su época del instituto, los dos hicieron planes para ir juntos a la universidad, pero Rosie, en una noche de pasión junto a uno de los chicos más populares del instituto, se queda embarazada. Y justo cuando se lo va a contar a Alex, éste le dice que le han admitido en Harvard en la facultad de medicina.', trailer_url = 'https://www.youtube.com/watch?v=jposnP4GKyk' WHERE id_api = 'tt1638002';

UPDATE Contenido SET id_tmdb = 37680, descripcion = 'Michael Ross se gana la vida sobre la delgada línea de la legalidad. Es un joven con una inteligencia abrumadora, pero las malas compañías con las que se junta en la universidad le hicieron salirse y buscar una opción más vistosa a corto plazo, mejorar su economía.

Entre sus triquiñuelas destaca el número de veces que se presenta en nombre de otros a los exámenes de acceso a la facultad de derecho.

El azar le acabará situando en el despacho de uno de los abogados más jóvenes y brillantes de Manhattan, Harvey Specter.

La inteligencia y dotes de Michael le asombrarán tanto que le tomará como su pupilo, a pesar de que no tenga la licenciatura. Juntos trabajarán mano a mano, ocultándole al resto del mundo la verdad: que juntos sólo suman un único título universitario.', trailer_url = 'https://www.youtube.com/watch?v=cUnkjEIW2-o' WHERE id_api = 'tt1632701';

