UPDATE Contenido SET id_tmdb = 916224, descripcion = 'Suzume, una joven chica de diecisiete años que vive en un pueblo tranquilo en la región de Kyushu, en el suroeste de Japón. La historia comienza cuando Suzume conoce a un misterioso joven que busca una ''puerta''. Los dos viajan juntos y encuentran una puerta vieja en una casa abandonada en las montañas. Como si algo tirara de ella, Suzume extiende su mano hacia la puerta, lo que comienza una serie de eventos desafortunados en todo Japón.', trailer_url = 'https://www.youtube.com/watch?v=8OEn2k4YCHM' WHERE id_api = 'tt16428256';

