UPDATE Contenido SET id_tmdb = 76493, descripcion = 'El Almirante Haffaz Aladeen (Baron Cohen) es un dictador antioccidental, capaz de arriesgar su vida con tal de evitar el establecimiento de la democracia en Wadiya, un país norteafricano con recursos petrolíferos. Su más fiel consejero es su tío Tamir (Ben Kingsley), Jefe de la Policía Secreta, Jefe de Seguridad y Proveedor de Mujeres. Por desgracia para Aladeen y sus consejeros, Occidente ha empezado a inmiscuirse en los asuntos de Wadiya y las Naciones Unidas han sancionado repetidas veces al país en la última década. Sin embargo, tras sufrir un atentado que le cuesta la vida a uno de sus consejeros, Tamir convence a Aladeen para que vaya a Nueva York a solucionar la cuestión de las Naciones Unidas.', trailer_url = 'https://www.youtube.com/watch?v=cYplvwBvGA4' WHERE id_api = 'tt1645170';

UPDATE Contenido SET id_tmdb = 82702, descripcion = 'Han pasado cinco años desde que Hipo empezó a entrenar a su dragón, rompiendo la tradición vikinga de cazarlos. Astrid y el resto de la pandilla han conseguido difundir en la isla un nuevo deporte: las carreras de dragones. Mientras realizan una carrera, atraviesan los cielos llegando a territorios inhóspitos, donde nadie antes ha estado. Durante un viaje descubren una cueva cubierta de hielo que resulta ser el refugio de cientos de dragones salvajes, a los que cuida un misterioso guardián. Hipo y los suyos se unen al guardián para proteger a los dragones de las fuerzas malignas que quieren acabar con ellos.', trailer_url = 'https://www.youtube.com/watch?v=Ag_fkJsqlNY' WHERE id_api = 'tt1646971';

