UPDATE Contenido SET id_tmdb = 301502, descripcion = 'Reinvención de la historia personal de la sex symbol más famosa del mundo, Marilyn Monroe, en un retrato ficticio de la modelo, actriz y cantante durante los años cincuenta y sesenta, contado a través de la mirada moderna de la cultura de las celebridades.', trailer_url = 'https://www.youtube.com/watch?v=6mgek159VZs' WHERE id_api = 'tt1655389';

UPDATE Contenido SET id_tmdb = 857598, descripcion = 'As his smuggling empire grows, a brazen Pushpa longs for power and respect on his vengeful journey, while facing old rivals and new.', trailer_url = NULL WHERE id_api = 'tt16539454';

UPDATE Contenido SET id_tmdb = 50647, descripcion = 'George (Paul Rudd) y Linda (Jennifer Aniston) son la típica pareja aquejada de estrés que vive en Manhattan. Cuando la empresa de George reduce la plantilla y lo echa a la calle, deciden irse a Atlanta a vivir con el insoportable hermano de George. Durante el viaje, George y Linda descubren Elysium, una idílica comunidad rural, cuyos habitantes tienen una espiritual visión del mundo: desprecian el dinero y todos los bienes materiales. El dilema está servido.', trailer_url = 'https://www.youtube.com/watch?v=SK0pI5w52NI' WHERE id_api = 'tt1655460';

UPDATE Contenido SET id_tmdb = 127493, descripcion = 'Will Montgomery (Nicolas Cage) ha terminado en la cárcel después de haber consagrado su vida al robo de sucursales bancarias. Después de cumplir la sentencia, desilusionado con las perspectivas que le esperan, lo único que quiere es alejarse de ese tipo de vida y empezar desde cero. Una de las primeras cosas que quiere recuperar es el amor y la confianza de Allison, su hija (Sami Gayle), a la que nunca ha tenido el suficiente tiempo para dedicarle. Pero las cosas no serán exactamente como él espera: un amigo colega de trapicheos, Vincent (Josh Lucas), secuestrará a su hija para vengarse de él y de paso conseguir una buena tajada: 10 millones de dólares por el rescate. Will solo dispondrá de 24 horas para reunir esta cantidad y solo tendrá una persona en la que confiar, Riley (Malin Akerman), que le ayudará en esta carrera contrarreloj por recuperar con vida a Allison.', trailer_url = 'https://www.youtube.com/watch?v=ikhHu6XGy_g' WHERE id_api = 'tt1656186';

UPDATE Contenido SET id_tmdb = 62835, descripcion = 'Colombia, 1992. Cataleya, una niña de nueve años, tras presenciar el asesinato de sus padres, se entrena para convertirse en una asesina profesional. Después de escapar a duras penas de la masacre, se refugia en los Estados Unidos con Emilio, un tío suyo mafioso. Quince años después, ya trabaja para él como asesina a sueldo. Su tarjeta de visita -una orquídea dibujada en el pecho de sus víctimas- es un mensaje para los asesinos de sus padres, pues Cataleya está resuelta a vengarlos cueste lo que cueste, aunque para ello tenga que sacrificar todo lo que ama.', trailer_url = 'https://www.youtube.com/watch?v=myO2vmvggas' WHERE id_api = 'tt1657507';

UPDATE Contenido SET id_tmdb = 150689, descripcion = 'Cuenta las andanzas de Ella, una joven cuyo padre, un comerciante, vuelve a casarse tras enviudar. Para agradar a su padre, acoge con cariño a su madrastra y a sus hijas en la casa familiar. Pero, cuando su padre muere inesperadamente, la joven queda a merced de unas mujeres celosas y malvadas que la convierten en sirvienta y la relegan a la cocina. Pero, a pesar de la crueldad con la que la tratan, está dispuesta a cumplir las últimas palabras de su madre que le dijo que debía "ser valiente y amable".', trailer_url = 'https://www.youtube.com/watch?v=WRr5DRAEOXQ' WHERE id_api = 'tt1661199';

UPDATE Contenido SET id_tmdb = 72387, descripcion = 'Mei, una niña china que vive en los bajos fondos de Nueva York, tiene una mente prodigiosa para las matemáticas. Las triadas chinas, la mafia rusa e incluso la policía de NY la persiguen porque en su memoria guarda un código secreto de alta importancia para todos ellos. El destino hace que se cruce con Luke, un exagente de élite que ha tocado fondo y se ha convertido en un fracasado. Juntos trazarán un plan para librarse de los perseguidores de la niña.', trailer_url = 'https://www.youtube.com/watch?v=s3kTkk4k_5Q' WHERE id_api = 'tt1656190';

UPDATE Contenido SET id_tmdb = 45, descripcion = 'Top Gear. Programa de automóviles. Toda clase de pruebas con coches y resto de vehículos, incluyendo viajes a través de desiertos, caminos tortuosos. Experimentos con motores, lanzamientos por encima de caravanas....', trailer_url = 'https://www.youtube.com/watch?v=YdCFIC6D_kk' WHERE id_api = 'tt1628033';

Su viaje comienza en la increíble pista de pruebas de Nardò, una instalación tan enorme que es visible desde el espacio, antes de dirigirse al norte para una tensa conducción por el centro de Roma. El recorrido concluye en el legendario circuito de Imola, una pista lo suficientemente desafiante como para haber avergonzado a muchos pilotos de Fórmula 1, con un desafío cronometrado contra las habilidades increíbles del Stig.

De regreso al estudio, los presentadores analizan algunos de los mejores momentos automovilísticos del 2012 y otro invitado estrella se pone al volante del “Coche de Precio Razonable”.', 60, '2012-01-29');

UPDATE Contenido SET id_tmdb = 64807, descripcion = 'Billy ''El niño'' McDonnen y Henry ''Navaja'' Sharp son dos boxeadores rivales que serán persuadidos para dejar su jubilación y volver al ring en un combate final 30 años después de su última pelea.', trailer_url = 'https://www.youtube.com/watch?v=2_4lm3tZifc' WHERE id_api = 'tt1661382';

UPDATE Contenido SET id_tmdb = 281957, descripcion = 'Durante una expedición en las tierras salvajes americanas, el legendario explorador Hugh Glass es brutalmente atacado por un oso y dado por muerto por los miembros de su propia partida de caza. En su cruzada por sobrevivir, Glass supera inimaginables tribulaciones, además de la traición de su confidente John Fitzgerald. Guiado por la pura determinación y el amor de su familia, Glass deberá superar un duro invierno mientras busca sin descanso un motivo para seguir adelante y encontrar la redención.', trailer_url = 'https://www.youtube.com/watch?v=a8HRA49kaok' WHERE id_api = 'tt1663202';

UPDATE Contenido SET id_tmdb = 68726, descripcion = 'Cuando legiones de monstruosas criaturas, denominadas Kaiju, comienzan a salir del mar, se inicia una guerra que acabará con millones de vidas y que consumirá los recursos de la humanidad durante interminables años. Para combatir a los Kaiju gigantes diseñan un tipo especial de arma: enormes robots, llamados Jaegers, que son controlados simultáneamente por dos pilotos cuyas mentes están bloqueadas en un puente neural. Pero incluso los Jaegers proporcionan poca defensa ante los incansables Kaiju. A punto de la derrota, las fuerzas que defienden a la humanidad no tienen otra elección que recurrir a dos insólitos héroes: un ex piloto acabado (Charlie Hunnam) y un aprendiz que todavía no se ha puesto a prueba (Rinko Kikuchi). Ambos se unen para traer a un legendario pero al parecer obsoleto Jaeger del pasado. Juntos, son la última esperanza de la humanidad frente al Apocalipsis que se avecina.', trailer_url = 'https://www.youtube.com/watch?v=SiQBCqSxYIU' WHERE id_api = 'tt1663662';

UPDATE Contenido SET id_tmdb = 40264, descripcion = '''Vampires Suck'' es una comedia sobre la ansiedad adolescente. Becca es una adolescente no vampiro que se debate entre dos chicos. Antes de que pueda elegir, Becca debe sortear a su padre, quien avergüenza a su hija por tratarla como si fuera una niña. Mientras tanto, los amigos de Becca deberán lidiar con sus propios problemas amorosos, chocando todos ellos en el baile de graduación. Parodia de la creciente moda de las películas vampíricas, tomando "Crepúsculo" como eje.', trailer_url = 'https://www.youtube.com/watch?v=Gw1oGbdXzoU' WHERE id_api = 'tt1666186';

UPDATE Contenido SET id_tmdb = 62764, descripcion = 'Nueva versión en clave de comedia del cuento de Blancanieves narrado desde el punto de vista de la malvada madastra. Siete valerosos y rebeldes enanitos ayudarán a Blancanieves a reclamar sus derechos al trono, que le pertenece por nacimiento, y a conquistar al Príncipe con el que pretende casarse la temible Reina.', trailer_url = 'https://www.youtube.com/watch?v=s3wLa6sFlIA' WHERE id_api = 'tt1667353';

UPDATE Contenido SET id_tmdb = 75656, descripcion = 'Un equipo del FBI debe enfrentarse a una banda de criminales expertos en magia. Ellos son ''los cuatro jinetes'', un grupo formado por los mejores ilusionistas del mundo, dedicado a realizar grandes robos contra hombres de negocios corruptos. Su gran golpe es pasar desapercibidos para hacer llover el dinero robado a su público. En un mundo de magia y espectáculo, nada es lo que parece.', trailer_url = 'https://www.youtube.com/watch?v=K1lguoJMFBI' WHERE id_api = 'tt1670345';

UPDATE Contenido SET id_tmdb = 272693, descripcion = 'Bianca es una alumna de instituto de último curso a quien se le viene el mundo encima al enterarse de que sus compañeros se refieren a ella como la MAF (La amiga maja y fea) de sus amigas más guapas y más populares. Con su universo patas arriba, ignora los consejos de su profesor favorito y ficha a Wesley, un deportista pillo pero encantador, para que la ayude a separarse del grupo y borrar esa etiqueta para siempre. En el proceso, espera ligarse a su amor platónico, Toby, y encontrar la confianza para tumbar a la cruel etiquetadora del instituto, Madison, recordándole que, al margen del aspecto o la conducta de la gente, todos somos el MAF de alguien… y que no pasa absolutamente nada.', trailer_url = 'https://www.youtube.com/watch?v=YGBNMNaJ6M4' WHERE id_api = 'tt1666801';

UPDATE Contenido SET id_tmdb = 50620, descripcion = 'Bella concluye su transformación en vampiro y ahora debe familiarizarse con su nueva condición. Con el nacimiento de Renesmee, la familia Cullen deberá protegerse ante la amenaza de los Volturi ya que existe una ley para los vampiros que prohíbe a todos los clanes convertir a niños, pues son difíciles de controlar y pueden generar auténticas masacres que pongan en peligro la secreta existencia de los vampiros... Segunda parte de la adaptación de "Amanecer" que supone la quinta entrega de la franquicia cinematográfica Crepúsculo, basada en las novelas de Stephenie Meyer.', trailer_url = 'https://www.youtube.com/watch?v=_7KWijbclec' WHERE id_api = 'tt1673434';

UPDATE Contenido SET id_tmdb = 64720, descripcion = 'Curtis LaForche vive en un pequeño pueblo de Ohio con su mujer, Samantha, y su hija Ana, una niña sorda de seis años. Curtis empieza a sufrir fuertes alucinaciones apocalípticas. Unas alucinaciones que no sabe si son consecuencia de una enfermedad mental o se trata de premoniciones reales...', trailer_url = 'https://www.youtube.com/watch?v=Puyf88oLLgg' WHERE id_api = 'tt1675192';

UPDATE Contenido SET id_tmdb = 77338, descripcion = 'Un hombre tetraplégico y millonario contrata como cuidador a domicilio a Driss, un inmigrante de un barrio marginal recién salido de la cárcel. Aunque no parece la persona más indicada, congenian hasta forjar una amistad tan sólida como inesperada.', trailer_url = 'https://www.youtube.com/watch?v=Mg2JD7HQr8g' WHERE id_api = 'tt1675434';

UPDATE Contenido SET id_tmdb = 188222, descripcion = 'La estrella del mundo del espectáculo Vince Chase (Adrian Grenier), para mantener los pies en el suelo con el éxito que tiene, decide llevarse a sus amigos de toda la vida a que le acompañen en su vida en Hollywood. Eric (Kevin Connolly), Drama (Kevin Dillon) y Turtle (Jerry Ferrara) acompañan a Vince en su carrera, guiada por el agente Ari Gold (Jeremy Piven), mientras ven la exagerada, excéntrica y despiadada vida de la meca del cine.', trailer_url = 'https://www.youtube.com/watch?v=SGSE_XPF4_g' WHERE id_api = 'tt1674771';

UPDATE Contenido SET id_tmdb = 333339, descripcion = 'Cuando el creador de una realidad virtual llamada OASIS muere, lanza un reto póstumo a todos sus usuarios para que busquen un huevo de pascua, que dará al que lo encuentre su fortuna y el control de su mundo.', trailer_url = 'https://www.youtube.com/watch?v=J0ZKannF6l4' WHERE id_api = 'tt1677720';

UPDATE Contenido SET id_tmdb = 136799, descripcion = 'Conocidos por sus pelos de colores, locos y mágicos, los Trolls son las criaturas más felices y alegres que irrumpen en el mundo de la canción. Pero su mundo de arco iris y cupcakes cambiará para siempre cuando su líder Poppy debe embarcarse en una misión de rescate que la llevará muy lejos del único mundo que siempre ha conocido.', trailer_url = 'https://www.youtube.com/watch?v=yGXDktdsjBA' WHERE id_api = 'tt1679335';

UPDATE Contenido SET id_tmdb = 746036, descripcion = 'Es un doble de acción, y al igual que todos en la comunidad de especialistas, sale volando, le disparan, se estrella, se tira desde ventanas y cae desde las alturas más extremas, todo para nuestro entretenimiento. Y ahora, tras un accidente que casi acaba con su carrera, este héroe de clase trabajadora debe seguir la pista de una estrella de cine desaparecida, resolver una conspiración y tratar de recuperar el amor de su vida mientras sigue haciendo su trabajo. ¿Qué podría salir bien?', trailer_url = 'https://www.youtube.com/watch?v=9slZAY2fyaM' WHERE id_api = 'tt1684562';

UPDATE Contenido SET id_tmdb = 203739, descripcion = 'Como a la mayoría de las adolescentes, a Rose y a Lissa les gustan los chicos, van de compras al centro comercial y se sienten incomprendidas. Pero entre ellas y las demás hay una gran diferencia: son vampiresas. Lissa es una princesa que desciende de la dinastía Moroi, y Rose es la guardiana encargada de protegerla. Tras escapar de la Academia St. Vladimir, son obligadas a volver, y Rose queda bajo el estricto control de su estoico mentor, Dmitri, pero pronto se dará cuenta de que se siente atraída por él. Mientras tanto, Lissa se ve obligada a afrontar terribles peligros.', trailer_url = 'https://www.youtube.com/watch?v=fwf5ITyni9U' WHERE id_api = 'tt1686821';

UPDATE Contenido SET id_tmdb = 93456, descripcion = 'La película de animación de los estudios Universal, giraba en torno a una apacible y colorida población en la que vivía el malvado Gru. Ayudado por su batallón de Minions, unos pequeños seres de color amarillo, intentaron robar la Luna, aunque no todo acabó como esperaban. Tres niñas curiosas y algo traviesas se cruzaron en su camino, entorpeciéndole todos sus planes y conviertiendo su objetivo en una alocada hazaña interestelar.  Ahora, ''Gru, mi villano favorito 2'', narra una nueva aventura en la que Gru volverá a estar acompañado de simpáticos humanoides.', trailer_url = 'https://www.youtube.com/watch?v=4CB8CQ2FoJw' WHERE id_api = 'tt1690953';

UPDATE Contenido SET id_tmdb = 151960, descripcion = 'Película derivada de la exitosa de Disney/Pixar dirigida por John Lasseter, Cars. En esta ocasión no son coches sino aviones, los que van a sumergirse en una divertida historia de acción y aventuras.  El protagonista, un avión llamado Dusty Crophopper, tiene verdadero terror a las alturas. Pero desafiará sus miedos para poder cumplir uno de sus grandes deseos: poder correr en la carrera más grandiosa que exiten en todo el mundo. Dusty sabe que este será el mayor reto de su vida, pero también será la experiencia más apasionante y sobrecogedora que va a vivir jamás.', trailer_url = 'https://www.youtube.com/watch?v=BsV--WuDJGg' WHERE id_api = 'tt1691917';

UPDATE Contenido SET id_tmdb = 77949, descripcion = 'En 1921, después de la Primera Guerra Mundial (1914-1918), una escéptica mujer viaja hasta un internado para investigar una aparente posesión. Justo cuando cree que ha desacreditado la teoría del espíritu maligno, tendrá un espectral encuentro que desafiará todas sus creencias racionales.', trailer_url = 'https://www.youtube.com/watch?v=3yneMKpmA8w' WHERE id_api = 'tt1687901';

UPDATE Contenido SET id_tmdb = 72113, descripcion = 'Adaptación de la obra teatral homónima de la autora francesa Yasmina Reza. Ha sido rodada en Europa, pero la historia se desarrolla en Nueva York. En la obra original, los protagonistas son dos matrimonios que se reúnen, en principio de manera civilizada, para hablar de la reciente pelea que han tenido sus hijos en un parque. Pero el encuentro se complicará hasta límites insospechados.', trailer_url = 'https://www.youtube.com/watch?v=343N7mg_hh8' WHERE id_api = 'tt1692486';

UPDATE Contenido SET id_tmdb = 218778, descripcion = 'Un día, Alexander, un niño de once años, se despierta con un chicle pegado al pelo. A partir de ese momento todo irá de mal en peor. Aunque el chico le cuenta sus desgracias a su optimista familia, esta no le hace demasiado caso.', trailer_url = 'https://www.youtube.com/watch?v=bQ4C-RoKDQg' WHERE id_api = 'tt1698641';

UPDATE Contenido SET id_tmdb = 223702, descripcion = 'La trama sigue el drama de una salchicha y sus amigos, otros productos de supermercado, cuando descubren que serán brutalmente asesinados al llegar a casa de sus compradores. Es entonces que necesitan encontrar una manera de regresar al supermercado y avisar a sus amigos de lo que realmente sucede con la comida.', trailer_url = 'https://www.youtube.com/watch?v=DH1gUabvxZA' WHERE id_api = 'tt1700841';

UPDATE Contenido SET id_tmdb = 54518, descripcion = 'Las posibilidades de Justin Bieber eran una entre un millón, hasta que millones de fans le descubrieron en la red. Ahora su mundo te pertenece con Never Say Never, la “fascinante e inspiradora” historia del viaje de un adolescente normal y corriente que se ha convertido en el artista más joven que ha logrado abarrotar el escenario más famoso de Nueva York.', trailer_url = 'https://www.youtube.com/watch?v=dwHvLr5M4ks' WHERE id_api = 'tt1702443';

UPDATE Contenido SET id_tmdb = 926393, descripcion = 'Desde que renunció a su vida como asesino del gobierno, Robert McCall (Denzel Washington) ha luchado para reconciliarse con las cosas horribles que ha hecho en el pasado y encuentra un extraño consuelo en hacer justicia en nombre de los oprimidos. Mientras se encuentra en su casa en el sur de Italia, descubre que sus nuevos amigos están bajo el control de los jefes del crimen local. A medida que los acontecimientos comienzan a complicarse, McCall entiende lo que tiene que hacer: convertirse en el protector de sus amigos enfrentándose a la temida mafia.', trailer_url = 'https://www.youtube.com/watch?v=aHX8awq8vNA' WHERE id_api = 'tt17024450';

UPDATE Contenido SET id_tmdb = 33880, descripcion = 'Korra es una maestra agua nativa de la Tribu Agua del Sur, según sigue el ciclo del Avatar. Korra ya tiene control sobre el agua control, la tierra control y el fuego control, pero todavía no controla el aire control. Ella aprenderá aire control de un maestro aire, Tenzin, el hijo de Aang y Katara. Como no sucedía en la anterior serie, Avatar: La leyenda de Korra será ambientada en dos únicos lugares, la Ciudad República, una ciudad donde las personas de todas las naciones, maestros y no maestros, viven juntos y por primera vez el Imperio de la Magia, donde habitan maestros y no maestros del poder de la magia, ellos intentarán dominar Ciudad República y las otras 4 naciones. Ciudad República está rodeada del crimen y una revolución de anti-maestros.', trailer_url = 'https://www.youtube.com/watch?v=E7pZvihpgyA' WHERE id_api = 'tt1695360';

También se halla la inesperada aparición de una secta secreta : "El loto rojo" , el antagonista del "loto Blanco" , y en consecuencia el enemigo número uno del Avatar , en este caso el Avatar Korra , inicialmente sus planes son un poco confusos pero son revelados primeramente en el capítulo 9 y posteriormente en el trágico capítulo 12, donde se descubre que Bolin posee lava-control.');

UPDATE Contenido SET id_tmdb = 50698, descripcion = 'Nos muestra un equipo de cazadores de fantasmas en un show televisivo que ruedan un episodio dentro del abandonado hospital psiquiátrico Collingwood, donde durante años se han informado de fenómenos inexplicables. Cualquier cosa en nombre de la televisión vale, así que se encierran durante una noche dentro del lugar. Pero no tardarán en darse cuenta de que el edificio está más que maldito, está vivo, y no tiene la menor intención de dejarles salir de allí con vida. Se encuentran sumidos en un laberinto de pasillos interminables y aterrorizados por los fantasmas de antiguos pacientes. No tardarán en cuestionarse su propia cordura, descubriendo la verdad que esconde el oscuro hospital y grabando lo que será su último episodio.', trailer_url = 'https://www.youtube.com/watch?v=Qn3fDvUXFps' WHERE id_api = 'tt1703199';

UPDATE Contenido SET id_tmdb = 1401, descripcion = 'La Guerra Civil es parte del pasado, pero el ex soldado confederado Cullen Bahannon no puede dejarla atrás. Las memorias horrorosas del asesinato de su esposa a manos de soldados de la Unión siguen frescas en su mente, acto que lleva a Bohannon a vengarse. Este programa del Oeste contemporáneo cuenta la historia del recorrido de este hombre, la historia se embarca en la construcción del primer ferrocarril intercontinental del "Union Pacific". El viaje en dirección oeste de Bohannon lo lleva a un lugar sin ley en una ciudad llamada "Infierno Sobre Ruedas", cuya población ayuda a la construcción del ferrocarril y se muda con esta.', trailer_url = 'https://www.youtube.com/watch?v=Nkvf9NW4-cQ' WHERE id_api = 'tt1699748';

