UPDATE Contenido SET id_tmdb = 76726, descripcion = 'Chronicle cuenta la historia de tres adolescentes normales y corrientes que de pronto desarrollan superpoderes que les permiten hacer cosas que nunca creyeron posibles. Mientras intentan aprender a controlar sus habilidades para usarlas en su beneficio, sus vidas se adentran en una espiral fuera de control, y se muestra el lado oscuro de sus recién descubiertos poderes con consecuencias inesperadas.', trailer_url = 'https://www.youtube.com/watch?v=UxrVoxjtvtY' WHERE id_api = 'tt1706593';

UPDATE Contenido SET id_tmdb = 110415, descripcion = 'Un experimento para solucionar el calentamiento global acabó con la mayoría de vida existente en el planeta. El último tren llamado Snowpiercer (Rompenieves) se mueve en círculos por el mundo, a través de un desierto de hielo y nieve. Los últimos supervivientes de la Tierra se amontonan en sus vagones. El joven Curtis (Chris Evans) iniciará una revolución desde los vagones de cola.', trailer_url = 'https://www.youtube.com/watch?v=6C827NwDMro' WHERE id_api = 'tt1706620';

