UPDATE Contenido SET id_tmdb = 96724, descripcion = 'Adaptación de la famosa novela del ruso León Tolstoi, "Ana Karenina", en esta ocasión protagonizada por Keira Knightley, que encarna a Anna Karenina; Jude Law, que interpreta a Alexei Karenin; y Aaron Johnson, como el joven conde Vronsky. El director Joe Wright, experto en adaptaciones literarias tras el éxito de ''Orgullo y prejuicio'' y ''Expiación'', aborda esta cinta pasional y de adulterio en la que nuestra heroína, Anna, una refinada dama de la alta sociedad rusa de finales del siglo XIX que, a pesar de estar casada, se enamora de un joven por el que perderá la cabeza y la llevará a dejarse en evidencia dentro del puritano orden social de la época. Una historia de tumultuoso deseo que, además de ser considerada en su momento como una crítica despiadada a la aristocracia rusa, se convirtió también en todo un símbolo de los derechos de libertad de la mujer para elegir su destino en un momento en el que se encontraba a merced de los designios del hombre que fuera su esposo.', trailer_url = 'https://www.youtube.com/watch?v=zP936Bpieto' WHERE id_api = 'tt1781769';

