UPDATE Contenido SET id_tmdb = 89584, descripcion = 'En 1453, Constantinopla, la capital del Imperio Bizantino, es rodeada por los turcos otomanos. La ciudad no es más que una sombra de su antigua gloria. El Imperio Otomano ha ido creciendo y ahora, el ambicioso sultán Mehmet II lanza su campaña para acabar con el último vestigio del Imperio romano de Oriente y tomar Constantinopla.', trailer_url = 'https://www.youtube.com/watch?v=nSmEMqC6kUs' WHERE id_api = 'tt1783232';

UPDATE Contenido SET id_tmdb = 198663, descripcion = 'Thomas abre los ojos y se da cuenta que está en un ascensor. Lo extraño es que no recuerda nada, ni dónde está, ni quién es. Lo único que aún permanece intacto en su memoria es su nombre, y ya es mucho. Antes de que le dé tiempo a cuestionarse algo sobre sí mismo las puertas se abrirán y aparecerá ante él un extraño mundo. Todo lo que ve son chicos de su edad que tienen su mismo estado de amnesia. Una aventura fantástica que pronto destapará la dura realidad bajo ese velo de incertidumbre: todos ellos están atrapados en un laberinto. Si quieren tener alguna posibilidad de salir de allí y recuperar su antigua vida y aquello que no son capaces de recordar deberán unir fuerzas para escapar. Un mundo post-apocalíptico que les acorralará e irá un paso por delante será el desafío que tengan que pasar estos jóvenes por la libertad.', trailer_url = 'https://www.youtube.com/watch?v=RxNV8uAacjU' WHERE id_api = 'tt1790864';

UPDATE Contenido SET id_tmdb = 74725, descripcion = 'Tras un accidentado trabajo en Kiev que le dejó violentas secuelas psicológicas, Jay, un soldado reconvertido en asesino a sueldo, lleva ocho meses sin trabajar. Su mujer y su hijo deben sufrir su crispación, hasta que Gal, un amigo, le propone un encarguito. La lista de objetivos no es muy extensa, pero el trabajo terminará por arrastrar a Jay hacia el corazón de las tinieblas.', trailer_url = 'https://www.youtube.com/watch?v=aqkqF--v1tg' WHERE id_api = 'tt1788391';

UPDATE Contenido SET id_tmdb = 97630, descripcion = 'Tras varios años de investigación de la CIA, que incluyó torturas a prisioneros en Afganistán, y gracias sobre todo a la perserverancia y decisión de la agente especial Maya (Jessica Chastain), por fin el presidente Obama dio el visto bueno a la operación militar que acabó con la vida de Osama Bin Laden, líder de Al-Qaeda. El título, "Zero Dark Thirty", se refiere a la hora: las 00:30 de la madrugada del 2 de mayo de 2011, momento en que el comando SEAL de los marines penetró en la residencia de Bin Laden en Abbottabad, en Pakistán, para dar caza al hombre más buscado de la historia.', trailer_url = 'https://www.youtube.com/watch?v=tdARGxNiv3M' WHERE id_api = 'tt1790885';

UPDATE Contenido SET id_tmdb = 77953, descripcion = '''En campaña todo vale'', dirigida por Jay Roach (la saga ''Austin Powers'' y ''Los padres de ella''), sigue la competición entre dos políticos de un pequeño distrito de Carolina del Norte por el mismo asiento en el congreso. Los dos oponentes, sumergidos en la batalla electoral, elaborarán sus propias campañas para alcanzar el mismo objetivo: involucrarse y crecer en sus deseos políticos y en el ambiente gubernamental.  Una comedia ambientada en el mundo político y electoral estadounidense que sorprenderá al espectador con su original sátira.', trailer_url = 'https://www.youtube.com/watch?v=RH6T11HpncE' WHERE id_api = 'tt1790886';

UPDATE Contenido SET id_tmdb = 86004, descripcion = 'A cop, investigating the mysterious death of a filmstar, meets a sex-worker, while he faces some personal problems psychologically. The mystery connects these people in a way, that ultimately changes their lives.', trailer_url = 'https://www.youtube.com/watch?v=M97P3zoUIos' WHERE id_api = 'tt1787988';

UPDATE Contenido SET id_tmdb = 171274, descripcion = 'La historia está ambientada a finales de los años sesenta en Los Ángeles. Doc Sportello es un detective privado que hace mucho tiempo que no ve a su ex novia Shasta, hasta que un día ésta contrata sus servicios para resolver la desaparición de su nuevo amante. Sportello se verá entonces enredado en una serie de situaciones donde dejará atrás los escrúpulos y donde la resolución del misterio no será finalmente el objetivo principal.', trailer_url = 'https://www.youtube.com/watch?v=GMQe1mFaO88' WHERE id_api = 'tt1791528';

UPDATE Contenido SET id_tmdb = 252512, descripcion = 'Jamie (Adam Driver) y Darby (Amanda Seyfried) forman una joven pareja de espíritu libre que ayudará a un serio documentalista, Josh (Ben Stiller), y a su mujer Cornelia Srebnick (Naomi Watts) a liberarse de sus prejuicios.', trailer_url = 'https://www.youtube.com/watch?v=LfFGwbr0AKI' WHERE id_api = 'tt1791682';

UPDATE Contenido SET id_tmdb = 307081, descripcion = 'Pese a haber gozado de gloria y de premios en su pasado, un luchador (Jake Gyllenhaal) ha caído en desgracia. Sin embargo, no se ha rendido y ha tomado la decisión de mejorar su imagen por el bien de su mujer y su hija.', trailer_url = 'https://www.youtube.com/watch?v=q0Uye0omgrs' WHERE id_api = 'tt1798684';

UPDATE Contenido SET id_tmdb = 83389, descripcion = 'Umi Matsuzaki es una chica de instituto que cuida a sus dos hermanos y, en ausencia de su madre, administra un albergue de estilo occidental, el Coquelicot Manor, cercano al mar. La chica compagina tranquilamente sus responsabilidades con su vida escolar junto a Shun Kazama, miembro del club de periodismo, y Shiro Mizunuma, presidente del consejo de estudiantes.', trailer_url = 'https://www.youtube.com/watch?v=a0DIxdy8CZA' WHERE id_api = 'tt1798188';

UPDATE Contenido SET id_tmdb = 168672, descripcion = 'La película cuenta la historia de Irving Rosenfeld, un hombre muy inteligente que, junto con su atractiva compañera Sydney Prosser se ve obligado por un agente del FBI a trabajar en un complicado y peligroso caso. El agente les empuja a un mundo lleno de mafiosos situado en Nueva Jersey donde deben cumplir una misión.', trailer_url = 'https://www.youtube.com/watch?v=fEmwviKvA84' WHERE id_api = 'tt1800241';

UPDATE Contenido SET id_tmdb = 152601, descripcion = 'En un futuro cercano, Theodore, un hombre solitario a punto de divorciarse que trabaja en una empresa como escritor de cartas para terceras personas, compra un día un nuevo sistema operativo basado en el modelo de Inteligencia Artificial, diseñado para satisfacer todas las necesidades del usuario. Para su sorpresa, se crea una relación romántica entre él y Samantha, la voz femenina de ese sistema operativo.', trailer_url = 'https://www.youtube.com/watch?v=ne6p6MfLBxc' WHERE id_api = 'tt1798709';

UPDATE Contenido SET id_tmdb = 334524, descripcion = 'Kenny Wells es un fracasado hombre de negocios reconvertido en un moderno explorador, desesperado por tener un golpe de suerte. En un último esfuerzo, Wells se asocia con un geólogo, con la misma poca fortuna, para ejecutar un plan tan descabellado como grandioso: encontrar oro en las profundidades de la inexplorada jungla de Indonesia.', trailer_url = 'https://www.youtube.com/watch?v=GJKlnPep6g8' WHERE id_api = 'tt1800302';

UPDATE Contenido SET id_tmdb = 85446, descripcion = 'La historia se centra en una joven "niña de papá", que se enamora del líder de un grupo de baile que organiza flashmobs por amor al arte. Cuando el padre de ésta quiere demoler el barrio donde viven los bailarines, la chica insta sus compañeros de baile a que utilicen los flashmobs para reivindicar. Nueva entrega de la saga Step Up.', trailer_url = 'https://www.youtube.com/watch?v=Y94Kt5vPuus' WHERE id_api = 'tt1800741';

UPDATE Contenido SET id_tmdb = 97367, descripcion = 'Un artista circense, rebelde, misterioso y mujeriego, Luke (Ryan Gosling), se entera que ha sido padre con su antigua amante, Romina, (Eva Mendes). De inmediato, decide cambiar de vida y aceptar la responsabilidad de la paternidad. El problema es que educar un niño, requiere de los ingresos económicos de los que no dispone en ese momento, por lo que decide junto con otro individuo empezar a asaltar bancos para ganar algo de dinero de manera fácil y rápida, utilizando su capacidad de motociclista para lograrlo. Su carrera delictiva se ve estorbada por un policía que empieza a seguir su huella, Avery Cross, (Bradley Cooper), un joven, novato y ambicioso, el cual trabaja en un departamento dirigido por un detective corrupto', trailer_url = 'https://www.youtube.com/watch?v=KepnbJT5nBw' WHERE id_api = 'tt1817273';

UPDATE Contenido SET id_tmdb = 129670, descripcion = 'Narra el viaje de realizan un padre alcohólico y su distante hijo desde Montana a Nebraska para recoger lo que cree que es un premio de un millón de dólares.', trailer_url = 'https://www.youtube.com/watch?v=YvW_DmfKfSk' WHERE id_api = 'tt1821549';

UPDATE Contenido SET id_tmdb = 146216, descripcion = 'El agente retirado de operaciones encubiertas la CIA, Frank Moses (Bruce Willis), vuelve a reunir a su peculiar equipo de élite para emprender la búsqueda a nivel global de un dispositivo nuclear portátil desaparecido. Por el camino tendrán que enfrentarse a un ejército de implacables asesinos, despiadados terroristas y oficiales del Gobierno enloquecidos por el poder; todos ansiosos por hacerse con un arma devastadora… y todos muy poco conscientes de lo que puede suponer enfrentarse al equipo de Retirados Extremadamente Peligrosos y sus tácticas de la vieja escuela.', trailer_url = 'https://www.youtube.com/watch?v=ORvnTGEz9fI' WHERE id_api = 'tt1821694';

UPDATE Contenido SET id_tmdb = 82825, descripcion = 'La búsqueda de una mujer embarazada de su marido desaparecido la lleva de Londres a Calcuta, pero todas las personas a las que pregunta niegan haberlo conocido.', trailer_url = 'https://www.youtube.com/watch?v=CUj73MLqZoQ' WHERE id_api = 'tt1821480';

UPDATE Contenido SET id_tmdb = 198184, descripcion = 'En un futuro cercano, la policía mecanizada controla el crimen. Cuando un droide de la policía, Chappie, es robado y se le da una nueva programación, se convierte en el primer robot con la capacidad de pensar y sentir por sí mismo.', trailer_url = 'https://www.youtube.com/watch?v=q7_qn9KgFJE' WHERE id_api = 'tt1823672';

UPDATE Contenido SET id_tmdb = 284054, descripcion = 'Después de los acontecimientos de "Capitán América: Civil War", T''Challa vuelve a casa, la nación aislada y muy avanzada tecnológicamente de Wakanda, para ser proclamado Rey. Pero la reaparición de un viejo enemigo pone a prueba el temple de T''Challa como Rey y Black Panther ya que se ve arrastrado a un conflicto que pone en peligro todo el destino de Wakanda y del mundo.', trailer_url = 'https://www.youtube.com/watch?v=JK-wAfAvJ0g' WHERE id_api = 'tt1825683';

UPDATE Contenido SET id_tmdb = 146015, descripcion = 'Adaptación contemporánea de la novela de Dostoievski sobre un burócrata que empieza a perder la cabeza cuando un doble exacto a él aparece trabajando en su misma oficina y parece tener intenciones de suplantarle.', trailer_url = 'https://www.youtube.com/watch?v=mzw0wEcsfxE' WHERE id_api = 'tt1825157';

UPDATE Contenido SET id_tmdb = 74879, descripcion = 'La vida en una pequeña ciudad se asemeja a un viaje en medio de las estepas: la impresión de que algo "nuevo y diferente" va a surgir de cada colina, aunque las carreteras resulten siempre monótonas, interminables e inevitablemente iguales.', trailer_url = 'https://www.youtube.com/watch?v=oMxDtfN2U_0' WHERE id_api = 'tt1827487';

UPDATE Contenido SET id_tmdb = 466081, descripcion = 'En Nueva York, el exconvicto Pete Koslow, relacionado con la mafia polaca, debe lidiar tanto con Klimek el General, su despiadado jefe, como con las retorcidas ambiciones de dos agentes federales, mientras intenta sobrevivir y proteger las vidas de sus seres queridos.', trailer_url = 'https://www.youtube.com/watch?v=RSmuxxE2l18' WHERE id_api = 'tt1833116';

UPDATE Contenido SET id_tmdb = 41889, descripcion = 'Dushane y Sully son dos jóvenes traficantes de droga de Londres, de ascendencia jamaicana, que aspirando a crecer en el negocio de los narcos se alían con el poderoso Bobby Raikes. En su barrio también está Ra''Nell, un chico de 13 años cuya madre es ingresada en un hospital psiquiátrico, y que ayudará a una vecina con su plantación de marihuana casera.', trailer_url = 'https://www.youtube.com/watch?v=qIkEmW1PkYE' WHERE id_api = 'tt1830379';

