UPDATE Contenido SET id_tmdb = 40417, descripcion = 'Leyla ile Mecnun is a Turkish television comedy series. The show is set in Istanbul, Turkey and premiered in 2011 on TRT. The series is a surreal and absurd comedy that revolves around the fictional love story between Leyla and Mecnun.', trailer_url = NULL WHERE id_api = 'tt1831164';

UPDATE Contenido SET id_tmdb = 44977, descripcion = 'Para vengar la muerte de su padre, un artista de circo entrenado en la magia y acrobacia se convierte en ladrón para acabar con un banco corrupto en Chicago. Dos policías de Mumbai son asignados al caso para atrapar al artista, sin embargo pronto se darán cuenta que las cosas no son lo que parecen.', trailer_url = 'https://www.youtube.com/watch?v=qBf-oHyJWgA' WHERE id_api = 'tt1833673';

UPDATE Contenido SET id_tmdb = 37664, descripcion = 'La serie se enfoca en Cassie, una adolescente que, después de morir su madre, se muda con su abuela al misterioso pueblo de Chance Harbor, Washington. En este lugar, Cassie descubrirá que su nuevo grupo de amigos saben mucho más sobre ella que ella misma. Son, en realidad, una comunidad secreta de brujos y que desean que se les una. La joven no creerá que es una bruja también hasta que le enseñen cómo utilizar sus poderes. Sin embargo, Cassie descubrirá gracias a una carta de su madre escondida en un libro de hechizos llamado "Libro de Sombras" (Las seis familias del círculo tienen uno) que su destino es altamente peligroso, ya que ella es la clave de la batalla entre las fuerzas del bien y las del mal. En el transcurso de la serie descubrirá que su poder está más allá de lo imaginado, debido que desciende de brujos muy poderosos.', trailer_url = 'https://www.youtube.com/watch?v=f5dUzNSVK_c' WHERE id_api = 'tt1837654';

UPDATE Contenido SET id_tmdb = 79548, descripcion = 'Jill Parrish llega un día a su casa después de trabajar un turno de noche y descubre que su hermana, Molly, ha sido secuestrada. Jill, que ya tiene experiencia en esa materia, tras haber logrado escapar de las garras de un asesino en serie que la secuestró un año antes, está convencida de que se trata del mismo individuo. La policía cree que Jill está loca, por lo que no se muestran muy dispuestos a malgastar sus recursos para ayudarla. Al temerse que Molly pueda estar muerta para la puesta de sol, Jill decide emprender por su cuenta una persecución para encontrar al asesino, sacar a la luz sus secretos y salvar a su hermana.', trailer_url = 'https://www.youtube.com/watch?v=tPmg2B-ovsA' WHERE id_api = 'tt1838544';

UPDATE Contenido SET id_tmdb = 103332, descripcion = 'Los directores de "Little Miss Sunshine" relatan la historia de un escritor que se enamora de uno de sus personajes femeninos. Calvin Weir-Fields (Paul Dano) había sido un niño-prodigio, cuya primera novela había tenido un gran éxito. Pero, desde entonces, sufre un sistemático bloqueo creativo agravado por su deprimente vida amorosa. Finalmente, consigue crear un personaje femenino, Ruby Sparks (Zoe Kazan), que acaba materializándose y compartiendo la vida con él.', trailer_url = 'https://www.youtube.com/watch?v=6cQODwif8VY' WHERE id_api = 'tt1839492';

UPDATE Contenido SET id_tmdb = 66788, descripcion = 'A pesar del desconcierto que supone volver a oír la voz de Hannah, Clay descubrirá que son trece las razones por las cuales ha decidido quitarse la vida, trece caras de cassete y que, por ello, son trece las personas que deben escucharlas. Él es una de ellas.', trailer_url = 'https://www.youtube.com/watch?v=QkT-HIMSrRk' WHERE id_api = 'tt1837492';

UPDATE Contenido SET id_tmdb = 987917, descripcion = 'Tres amigos del alma que han sido padres un poco tarde deben vérselas con directores de guardería, CEOs millennials, y cualquier cosa creada después de 1987.', trailer_url = 'https://www.youtube.com/watch?v=mU01e6KjM2s' WHERE id_api = 'tt18394190';

UPDATE Contenido SET id_tmdb = 39358, descripcion = 'Emily Thorne, cuyo verdadero nombre es Amanda Clarke, regresa a Los Hamptons para vengarse de las personas que causaron la muerte de su padre, David Clarke, y que destruyeron su familia. Cuando Amanda era una niña, su padre fue arrestado por cargos inventados de terrorismo, fue juzgado injustamente y condenado por traición a la patria. Él murió en la cárcel. La misma gente que destruyó a su padre se aseguró de que Amanda terminara en un centro de detención juvenil. A sus 18 años es puesta en libertad, tras salir del correccional se entera de que es heredera de parte de una sociedad en la que su padre invirtió que vale una fortuna. Tras cambiar su nombre por el de Emily Thorne, decide vengarse de los responsables de la caída de su padre.', trailer_url = 'https://www.youtube.com/watch?v=R1C8ygebkng' WHERE id_api = 'tt1837642';

