UPDATE Contenido SET id_tmdb = 83686, descripcion = 'Un escritor de éxito lee su nueva novela ante una multitud de entregados admiradores. En ella se narra la historia de un escritor fracasado que tiene la fortuna de encontrar un manuscrito. Lo publica como suyo y obtiene un éxito espectacular que lo convierte en uno de los mejores escritores de su tiempo. El autor del manuscrito resulta ser un anciano que lo escribió durante su juventud, cuando estuvo destinado en París tras la Segunda Guerra Mundial (1939-1945), época en la que encontró al amor de su vida.', trailer_url = 'https://www.youtube.com/watch?v=G3CH1SURy1E' WHERE id_api = 'tt1840417';

