UPDATE Contenido SET id_tmdb = 720557, descripcion = 'Los espías Tiger (Salman Khan) y Zoya (Katrina Kaif) vuelven para salvar al país y a su familia. Esto sí, esta vez es personal. El objetivo es buscar venganza. Deberán hacer frente a las circunstancias de la única forma que saben. Cuando les pongan entre la espada y la pared idearán un plan para escapar del peligro por salvar la vida y limpiar su reputación.', trailer_url = 'https://www.youtube.com/watch?v=9Xmfb5hmlfI' WHERE id_api = 'tt18411490';

