UPDATE Contenido SET id_tmdb = 399402, descripcion = 'El capitán Joe Glass, un hombre firme pero justo y con un código moral muy exigente, se va a encargar de liderar una importante misión. Junto con un grupo de Navy Seals, y desde un submarino de los Estados Unidos, deberá rescatar al presidente de Rusia que ha sido hecho prisionero tras un golpe militar. Glass y su equipo deberán evitar a toda costa que la situación desemboque en una Tercera Guerra Mundial.', trailer_url = 'https://www.youtube.com/watch?v=kqxsE6gZhtg' WHERE id_api = 'tt1846589';

UPDATE Contenido SET id_tmdb = 68718, descripcion = 'Dos años antes de estallar la Guerra Civil (1861-1865), Schultz, un cazarrecompensas alemán que le sigue la pista a unos asesinos, le promete al esclavo Django dejarlo en libertad si le ayuda a atraparlos. Terminado con éxito el trabajo, Django prefiere seguir al lado del alemán y ayudarle a capturar a los delincuentes más buscados del Sur. Se convierte así en un experto cazador de recompensas, pero su único objetivo es rescatar a su esposa Broomhilda, a la que perdió por culpa del tráfico de esclavos. La búsqueda llevará a Django y a Schultz hasta Calvin Candie, el malvado propietario de la plantación "Candyland". La presencia de ambos en los alrededores de la propiedad, despierta las sospechas de Stephen, el esclavo de confianza de Candie.', trailer_url = 'https://www.youtube.com/watch?v=CLofzNkIqAc' WHERE id_api = 'tt1853728';

UPDATE Contenido SET id_tmdb = 83899, descripcion = 'La familia Davison es atacada por un grupo de asesinos sádicos durante una escapada familiar. Atrincherados en la casa de vacaciones, hacen frente a los asaltantes. Los asesinos enmascarados no contaban con la presencia de Erin, la novia del hijo mayor de los Davison, cuyo misterioso pasado la ha hecho fuerte y muy difícil de matar.', trailer_url = 'https://www.youtube.com/watch?v=eZ7ztxb2rOA' WHERE id_api = 'tt1853739';

UPDATE Contenido SET id_tmdb = 77016, descripcion = 'Los agentes Taylor y Zavala son dos policías de Los Angeles que patrullan las calles y que tendrán que superar su mayor reto cuando se convierten en el objetivo de una peligrosa banda de narcotraficantes que han puesto precio a su cabeza.', trailer_url = 'https://www.youtube.com/watch?v=TYGXe5ggBx0' WHERE id_api = 'tt1855199';

UPDATE Contenido SET id_tmdb = 71679, descripcion = 'El virus de la corporación Umbrella sigue haciendo estragos en La Tierra convirtiendo a la población en legiones de muertos sedientos de sangre. La última esperanza de la humanidad, Alice, despierta en el centro de operaciones de la compañía donde comienza a conocer más detalles de su pasado. Alice seguirá persiguiendo a los responsables del virus llevándola por Tokio, Nueva York, Washington y Moscú donde le será revelado algo que la hará plantearse todo lo que la ha sucedido hasta ahora. Con la ayuda de sus nuevos aliados, Alice deberá sobrevivir el tiempo suficiente para escapar de un mundo hostil... La cuenta atrás ha comenzado.', trailer_url = 'https://www.youtube.com/watch?v=hoyMT-7wEqs' WHERE id_api = 'tt1855325';

UPDATE Contenido SET id_tmdb = 947891, descripcion = 'Elliott Labrant, a quien su futuro yo le ha aconsejado que no se enamore, está segura de que puede hacerlo después de recibir el consejo. Hasta que conoce al chico del que le advirtió su yo mayor.', trailer_url = 'https://www.youtube.com/watch?v=hL1EO3-sSH4' WHERE id_api = 'tt18559464';

UPDATE Contenido SET id_tmdb = 39340, descripcion = 'Ambientada en el barrio de Williamsbourg, del distrito de Brooklyn, en Nueva York, la serie relata la vida de dos camareras veinteañeras que trabajan juntas en un restaurante, para lograr cumplir su sueño de abrir un negocio de cupcakes. Max Black (Kat Dennings), proveniente de una familia pobre de la clase trabajadora, que además tiene un trabajo adicional como niñera para una mimada y detestable socialité de Manhattan; y Caroline Channing (Beth Behrs), quien nació rica pero que ahora es pobre, debido a que su padre fue atrapado operando en una enorme estafa. Las dos se convierten en amigas y construyen un sueño juntas, el de abrir una tienda de magdalenas (para eso necesitan alcanzar 250.000 dólares), aunque casi no pueden costear nada con el pago que reciben en su trabajo. Junto con ellas trabajan también en el restaurante su jefe, Han Lee (Matthew Moy); Oleg (Jonathan Kite), un alegre cocinero ucraniano; y Earl (Garrett Morris), el cajero. Al comienzo de cada episodio, se muestra a Max sirviendo una mesa, y al final de cada episodio, un registro muestra lo que llevan para alcanzar los 250.000 dólares.', trailer_url = 'https://www.youtube.com/watch?v=aUkwxpMVW9M' WHERE id_api = 'tt1845307';

