UPDATE Contenido SET id_tmdb = 335984, descripcion = 'Han pasado 30 años desde los acontecimientos ocurridos en Blade Runner (1982). El oficial K, un blade runner caza-replicantes del Departamento de Policía de Los Ángeles, descubre un secreto que ha estado enterrado durante mucho tiempo y que tiene el potencial de llevar a la sociedad al caos. Su investigación le conducirá a la búsqueda del legendario Rick Deckard, un antiguo blade runner en paradero desconocido, que lleva desaparecido 30 años.', trailer_url = 'https://www.youtube.com/watch?v=zRy9zzc1FLo' WHERE id_api = 'tt1856101';

UPDATE Contenido SET id_tmdb = 81836, descripcion = 'Cuatro historias independientes con un escenario común: la ciudad de Roma. En la primera, un matrimonio americano (Woody Allen y Judy Davis) viaja a italia para conocer a la familia del prometido de su hija. En la segunda, un italiano (Roberto Benigni) es confundido con una estrella de cine. En la tercera, un arquitecto californiano (Alec Baldwin) visita Roma con sus amigos, y en la cuarta, unos reción casados (Alessandro Tiberi y Alessandra Mastronardi) se pierden en la capital italiana, a la que han ido a visitar a unos familiares.', trailer_url = 'https://www.youtube.com/watch?v=Zyx5y1InqDc' WHERE id_api = 'tt1859650';

UPDATE Contenido SET id_tmdb = 291870, descripcion = 'Un hombre, recientemente viudo y con muchas ganas de vivir, convence a su nieto para realizar un viaje por carretera a Florida. El nieto que, según su abuelo está a punto de casarse con la chica equivocada, descubrirá para su asombro, que el anciano está más loco de lo que pensaba y que a diferencia de él, no tiene ningún reparo a la hora de ligar con las chicas.', trailer_url = 'https://www.youtube.com/watch?v=skl7gYRZHwE' WHERE id_api = 'tt1860213';

UPDATE Contenido SET id_tmdb = 84332, descripcion = 'Un trío de empleados de una revista de investigación descubre un anuncio clasificado donde se busca un socio para viajar en el tiempo. Uno de los empleados desarrolla sentimientos por el paranoico pero atractivo solitario y trata de descubrir lo que realmente está haciendo.', trailer_url = 'https://www.youtube.com/watch?v=47wFru7nlk0' WHERE id_api = 'tt1862079';

UPDATE Contenido SET id_tmdb = 500682, descripcion = 'El legendario legislador Frank Hamer y Manny Gault, dos ex Rangers en el momento en que Bonnie & Clyde comenzó su reinado de robo, son comisionados como investigadores especiales, convencidos por un consorcio de bancos para armar un grupo y terminar con el robo del conocido dúo mató a 13 policías y otros.', trailer_url = 'https://www.youtube.com/watch?v=aH6vC-BBKOc' WHERE id_api = 'tt1860242';

UPDATE Contenido SET id_tmdb = 110416, descripcion = 'Ben y Saoirse son dos hermanos que viven en un faro de una isla junto a su padre que, para protegerlos de los peligros del mar, los envía con su abuela a la ciudad. Allí Ben descubre que su hermana pequeña es una Selkie, un hada del mar, una niña-foca que cantando puede liberar a los Seres Mágicos del sortilegio que les hizo la Bruja de los Búhos. Juntos emprenderán un viaje fantástico.', trailer_url = 'https://www.youtube.com/watch?v=2nq-n0qcDdI' WHERE id_api = 'tt1865505';

