UPDATE Contenido SET id_tmdb = 113947, descripcion = 'Mark O''Brien, poeta y periodista que vive con un pulmón artificial, a sus 36 años decide perder la virginidad. Con la ayuda de su terapeuta y la orientación de un sacerdote, se pone en contacto con una profesional que intentará que alcance la edad adulta.', trailer_url = 'https://www.youtube.com/watch?v=Eyf2N38uvfo' WHERE id_api = 'tt1866249';

UPDATE Contenido SET id_tmdb = 102382, descripcion = 'Peter Parker lleva una vida muy ocupada, compaginando su tiempo entre su papel como Spider-Man, acabando con los malos, y en el instituto con la persona a la que quiere, Gwen. Peter no ve el momento de graduarse. No ha olvidado la promesa que le hizo al padre de Gwen de protegerla, manteniéndose lejos de ella, pero es una promesa que simplemente no puede cumplir. Las cosas cambiarán para Peter cuando aparece un nuevo villano, Electro, y un viejo amigo, Harry Osborn, regresa, al tiempo que descubre nuevas pistas sobre su pasado.', trailer_url = 'https://www.youtube.com/watch?v=oMpJJ6GMj68' WHERE id_api = 'tt1872181';

UPDATE Contenido SET id_tmdb = 40075, descripcion = 'Narra las aventuras de los mellizos de 12 años Dipper y Mabel Pines, que ven cómo se desvanecen sus planes para el verano cuando sus padres deciden mandarlos con su tío-abuelo Grunkle Stan, que vive en el corazón de Gravity Falls. Pronto, Dipper y Mabel descubren que en Gravity Falls no todo es lo que parece y confían el uno en el otro y en sus nuevos amigos para descubrir lo que REALMENTE está sucediendo en este extraño lugar...', trailer_url = 'https://www.youtube.com/watch?v=bdoDOvQHOWk' WHERE id_api = 'tt1865718';

