UPDATE Contenido SET id_tmdb = 87499, descripcion = 'Sarah Moss es una trabajadora brillante que recibe una misión de una poderosa corporación: infiltrarse en un grupo anarquista de ecologistas radicales que está empezando a poner nerviosas a algunas empresas con sus ataques. Los problemas comienzan cuando Sarah intima demasiado con el líder de la banda que se enamora de ella, y que previamente había mantenido un romance con una joven del grupo.', trailer_url = 'https://www.youtube.com/watch?v=MRX7w75wIFk' WHERE id_api = 'tt1869716';

UPDATE Contenido SET id_tmdb = 205587, descripcion = 'Hank Palmer, un importante abogado, regresa a su hogar tras la muerte de su madre. Se entera entonces de que su padre, que es el juez del pueblo y de quien está distanciado, es sospechoso de haber cometido un crimen. Su decisión de investigar el caso lo lleva poco a poco a restablecer con los suyos una relación que estaba rota.', trailer_url = 'https://www.youtube.com/watch?v=nxIKHBxQJ6w' WHERE id_api = 'tt1872194';

UPDATE Contenido SET id_tmdb = 414906, descripcion = 'Cuando un asesino se dirige a la élite de Gotham con una serie de maquinaciones sádicas, un rastro de pistas crípticas envía Batman a una investigación en los bajos fondos. A medida que las pruebas comienzan a acercarse a su casa y se hace evidente la magnitud de los planes del autor, Batman debe forjar nuevas relaciones, desenmascarar al culpable y hacer justicia al abuso de poder y la corrupción que durante mucho tiempo han asolado Gotham City.', trailer_url = 'https://www.youtube.com/watch?v=L6DEcPaNdLs' WHERE id_api = 'tt1877830';

UPDATE Contenido SET id_tmdb = 376660, descripcion = 'Dos estudiantes de instituto que son las mejores amigas ven cómo su amistad se tambalea cuando una comienza a salir con el hermano mayor de la otra.', trailer_url = 'https://www.youtube.com/watch?v=Lza1bXCNQak' WHERE id_api = 'tt1878870';

UPDATE Contenido SET id_tmdb = 287424, descripcion = 'Un peligroso virus se está extendiendo por todas partes infectando a los habitantes de todo el mundo. Maggie es una joven adolescente de 16 años que vive junto a su familia en una pequeña granja de los EEUU. El virus avanza y Maggie termina infectada. Wade, el padre de la niña, no está dispuesto a renunciar a su pequeña y dejar que la aparten y aíslen en su agonizante y peligrosa transformación en un muerto viviente.', trailer_url = 'https://www.youtube.com/watch?v=g0KS6RyvthQ' WHERE id_api = 'tt1881002';

UPDATE Contenido SET id_tmdb = 136418, descripcion = 'Joey Jones (Jason Statham) es un ex soldado de las Fuerzas Especiales, vagabundo y atormentado por un trágico pasado. Harto de las injusticias que ve constantemente a su alrededor, los acontecimientos le llevan a convertirle en un “ángel vengador”. Pronto verá como su pasado se mezcla con su turbio presente y cómo sus intentos de forjar una nueva vida comienzan a desmontarse.', trailer_url = 'https://www.youtube.com/watch?v=Md-roGdI_Gs' WHERE id_api = 'tt1893256';

UPDATE Contenido SET id_tmdb = 314365, descripcion = 'Cuando el tenaz equipo de reporteros de la sección "Spotlight" ahonda en los alegatos de abuso dentro de la Iglesia Católica, descubren en su investigación el encubrimiento llevado a cabo durante décadas por parte de las altas esferas de organizaciones religiosas, legales y gubernamentales de Boston, desatando una ola de revelaciones alrededor del mundo.', trailer_url = 'https://www.youtube.com/watch?v=vwae8QE21UY' WHERE id_api = 'tt1895587';

UPDATE Contenido SET id_tmdb = 202555, descripcion = 'Matt Murdock, un abogado ciego con habilidades super desarrolladas lucha por la justicia desde su ajetreado bufete mientras el antiguo jefe mafioso Wilson Fisk emprende una carrera política en Nueva York. Cuando sus identidades pasadas empiezan a salir a la luz, ambos se ven abocados a un enfrentamiento inevitable.', trailer_url = 'https://www.youtube.com/watch?v=lav-qr0K1r8' WHERE id_api = 'tt18923754';

UPDATE Contenido SET id_tmdb = 956842, descripcion = 'Ambientada en el histórico alunizaje del Apolo 11, en 1969. Llamados para mejorar la imagen pública de la NASA, las chispas vuelan en todas las direcciones cuando la prodigio del marketing Kelly Jones causa estragos en la ya difícil tarea del director de lanzamiento Cole Davis. Cuando la Casa Blanca considera que la misión es demasiado importante para fracasar, Jones recibe la orden de simular un alunizaje falso como respaldo y comienza la verdadera cuenta atrás.', trailer_url = 'https://www.youtube.com/watch?v=IBVdzSoS1ik' WHERE id_api = 'tt1896747';

UPDATE Contenido SET id_tmdb = 82992, descripcion = 'Desde que Dom y Brian destruyeron el imperio de un mafioso y se hicieron con cien millones de dólares, se encuentran en paradero desconocido; no pueden regresar a casa porque la ley los persigue. Entretanto, Hobbs ha seguido la pista por una docena de países a una banda de letales conductores mercenarios, cuyo cerebro cuenta con la inestimable ayuda de la sexy Letty, un viejo amor de Dom que éste daba por muerta. La única forma de detenerlos es enfrentarse a ellos en las calles, así que Hobbs le pide a Dom que reúna a su equipo en Londres.', trailer_url = 'https://www.youtube.com/watch?v=kiSEFwqh2Qk' WHERE id_api = 'tt1905041';

UPDATE Contenido SET id_tmdb = 87502, descripcion = 'Tras un aterrizaje de emergencia en medio del campo gracias al cual salvan la vida un centenar de pasajeros, el comandante Whip Whitaker (Denzel Washington), que pilotaba el avión, es considerado un héroe nacional. Sin embargo, cuando se pone en marcha la investigación para determinar las causas de la avería, se averigua que el capitán tenía exceso de alcohol en la sangre.', trailer_url = 'https://www.youtube.com/watch?v=r-96m8c_o-E' WHERE id_api = 'tt1907668';

UPDATE Contenido SET id_tmdb = 74306, descripcion = 'Sin amor, sin trabajo y quizá con una enfermedad terminal, Frank ya no cree en el sueño americano. Sin nada que perder, coge su pistola decidido a terminar con lo peor de la sociedad. Cuenta para ello con un cómplice inusual: una chica de 16 años que comparte su rabia e insatisfacción. Hilarante ataque a todo lo que es sagrado en los Estados Unidos de América.', trailer_url = 'https://www.youtube.com/watch?v=2QWrVnfu6uA' WHERE id_api = 'tt1912398';

