UPDATE Contenido SET id_tmdb = 119283, descripcion = 'Parker es un ladrón con un código ético muy particular: solo roba a los ricos. Tras una operación, es traicionado por su equipo y dado por muerto. Entonces decide adoptar una nueva identidad; lo que se propone, con la ayuda de una hermosa mujer, es apoderarse del botín y que sus antiguos socios lamenten haberse cruzado en su camino.', trailer_url = 'https://www.youtube.com/watch?v=2rIlk-Jk3lw' WHERE id_api = 'tt1904996';

