UPDATE Contenido SET id_tmdb = 969492, descripcion = 'Kinney, un controlador de apoyo aéreo con poca experiencia, se incorpora a un equipo Delta Force en una misión en Filipinas. Cuando el equipo queda atrapado sin armas, las oportunidades de sobrevivir dependen de la habilidad de Reaper, un piloto de drones de las Fuerzas Aéreas.', trailer_url = 'https://www.youtube.com/watch?v=7vHG3DqEo7Y' WHERE id_api = 'tt19864802';

UPDATE Contenido SET id_tmdb = 440472, descripcion = 'Remake norteamericano del gran éxito del cine francés "Intocable" (2011), que aborda la relación que se desarrolla entre un parapléjico y un desempleado con antecedentes criminales que es contratado como asistente personal para ayudarle en el día a día.', trailer_url = 'https://www.youtube.com/watch?v=EWw7rCHcduQ' WHERE id_api = 'tt1987680';

UPDATE Contenido SET id_tmdb = 84329, descripcion = 'En un futuro no muy lejano, la integración de presencias robóticas entre los humanos hará posible que surjan, por ejemplo, androides programados para cuidar personas mayores. Esa es justamente la solución que encuentran Hunter y Madison para su anciano padre Frank, cuyas pérdidas de memoria son cada vez más frecuentes. Venciendo su aversión inicial por la tecnología, este encontrará en el robot a un amigo cuidadoso y preocupado por su bienestar. Pero, paralelo a su mejoría, también surgirá en Frank el deseo por volver a ejercer su antigua “profesión” de ladrón de joyas. Luminosa y tierna, Robot and Frank integra elementos de ciencia-ficción en una historia profundamente humanista.', trailer_url = 'https://www.youtube.com/watch?v=U_RU-wIPNc0' WHERE id_api = 'tt1990314';

UPDATE Contenido SET id_tmdb = 93856, descripcion = 'Un grupo de amigos que están pasando las vacaciones en Europa van a a parar a Prypiat, una ciudad abandonada, donde se refugiaron después del accidente los trabajadores de la central nuclear de Chernobil; pero pronto se darán cuenta de que no están solos.', trailer_url = 'https://www.youtube.com/watch?v=6zdPYuiiZY0' WHERE id_api = 'tt1991245';

UPDATE Contenido SET id_tmdb = 97051, descripcion = 'A raíz de la muerte de su padre, Iris  se esfuerza por ganarse la vida mientras cuida a su hermano pequeño, un enfermo terminal. Shepard Lambrick un aristócrata aparentemente filantrópico, expresa su interés en ayudarles. Cuando Lambrick la invita a una exclusiva cena en su casa, ella acepta, pero a esa cena también asisten otros siete individuos tan desesperados como ella. Pronto se encontrarán atrapados en la mansión de Lambrick y serán obligados a un juego sádico llamado "Would You Rather".', trailer_url = 'https://www.youtube.com/watch?v=zG2z4ng2ghU' WHERE id_api = 'tt1999995';

UPDATE Contenido SET id_tmdb = 106747, descripcion = 'Tras ser contratado por el presidente de Estados Unidos (Charlie Sheen), Machete (Dany Trejo) se embarca en una peligrosa misión: acabar con el líder de un cartel y un traficante de armas multimillonario y excéntrico llamado Luther Voz (Mel Gibson), quien ha ideado un plan para llevar el caos y la destrucción a todo el planeta con una potente arma espacial.', trailer_url = 'https://www.youtube.com/watch?v=aoiTEZWF-HQ' WHERE id_api = 'tt2002718';

UPDATE Contenido SET id_tmdb = 199373, descripcion = 'Basada en una historia real sucedida en Alaska. Robert Hansen (John Cusack) era un padre de familia que se dedicaba a contratar prostitutas en Anchorage a las que luego secuestraba, torturaba y violaba; después las llevaba a una remota cabaña en su avioneta. Una vez allí, las liberaba para darles caza como si fueran animales. El agente de la policía Jack Halcombe (Nicolas Cage) está decidido a atraparle. Para ello cuenta con la única testigo que ha conseguido escapar, la joven prostituta Cindy Paulson (Vanessa Hudgens).', trailer_url = 'https://www.youtube.com/watch?v=OfEcrF1PpP0' WHERE id_api = 'tt2005374';

UPDATE Contenido SET id_tmdb = 118340, descripcion = 'El temerario aventurero Peter Quill es objeto de un implacable cazarrecompensas después de robar una misteriosa esfera codiciada por Ronan, un poderoso villano cuya ambición amenaza todo el universo. Para poder escapar del incansable Ronan, Quill se ve obligado a pactar una complicada tregua con un cuarteto de disparatados inadaptados: Rocket, un mapache armado con un rifle, Groot, un humanoide con forma de árbol, la letal y enigmática Gamora y el vengativo Drax the Destroyer. Pero cuando Quill descubre el verdadero poder de la esfera, deberá hacer todo lo posible para derrotar a sus extravagantes rivales en un intento desesperado de salvar el destino de la galaxia.', trailer_url = 'https://www.youtube.com/watch?v=F60FZKt_36s' WHERE id_api = 'tt2015381';

UPDATE Contenido SET id_tmdb = 149870, descripcion = 'Jiro sueña con volar y diseñar hermosos aviones, inspirados por el famoso diseñador aeronáutico italiano Caproni. Corto de vista desde niño y por ello incapaz de volar, Jiro se une a la división aeronáutica de una compañía de ingeniería en 1927. Su genio pronto es reconocido y se convierte en uno de los más prestigiosos diseñadores aeronáuticos. La película relata su biografía y recrea sucesos históricos que marcaron su vida, como el terremoto de Kanto de 1923, la Gran Depresión, la epidemia de tuberculosis y la entrada de Japón en la guerra.', trailer_url = 'https://www.youtube.com/watch?v=q3kdZpeVbLM' WHERE id_api = 'tt2013293';

UPDATE Contenido SET id_tmdb = 77931, descripcion = 'Secuela de "Los pitufos", adaptación del cómic homónimo realizada en 2011 por Raja Gosnell. En esta secuela, el cruel y malvado Gargamel regresa con más fuerza que nunca para poder robar a los Pitufos la más pura esencia de su magia y para ello, fabrica dos pequeños Pitufos falsos llamados Naughties. Pero Gargamel, no tardará en darse cuenta de que no servirá de nada porque la magia que él anhela, sólo se la puede proporcionar un Pitufo verdadero, por eso decide secuestrar a la Pitufina y trasladarla a París, donde se ha ganado la admiración de miles de personas como el mejor mago del mundo. Ahora todo queda en manos de Papa pitufo y sus camaradas, quienes tendrán que volver al mundo de los humanos para salvar a la Pitufina.', trailer_url = 'https://www.youtube.com/watch?v=Rn66I93fKEY' WHERE id_api = 'tt2017020';

UPDATE Contenido SET id_tmdb = 974576, descripcion = 'Tras la inesperada muerte del sumo pontífice, el cardenal Lawrence es designado como responsable para liderar uno de los rituales más secretos y antiguos del mundo: la elección de un nuevo papa. Cuando los líderes más poderosos de la Iglesia Católica se reúnen en los salones del Vaticano, Lawrence se ve atrapado dentro de una compleja conspiración a la vez que descubre un secreto que podría sacudir los cimientos de la Iglesia.', trailer_url = 'https://www.youtube.com/watch?v=J0E78tL6CxY' WHERE id_api = 'tt20215234';

UPDATE Contenido SET id_tmdb = 974635, descripcion = 'Gary Johnson es el asesino profesional más buscado de Nueva Orleans. Para sus clientes, es el sicario ideal. Pero si le pagas para que elimine a un cónyuge infiel o a un jefe maltratador, será mejor que tengas cuidado: trabaja para la policía. Cuando rompe el protocolo para ayudar a una mujer desesperada que intenta huir de un marido maltratador, se convierte en uno de sus falsos personajes, se enamora de la mujer y coquetea con convertirse él mismo en un criminal.', trailer_url = 'https://www.youtube.com/watch?v=6dE7Xg-ypiY' WHERE id_api = 'tt20215968';

UPDATE Contenido SET id_tmdb = 974950, descripcion = 'Rita, una infravalorada abogada que trabaja para un gran bufete más interesado en librar a los criminales de la cárcel que en llevarlos ante la justicia, es contratada por el líder de una organización criminal.', trailer_url = 'https://www.youtube.com/watch?v=JyZnrpeMF1s' WHERE id_api = 'tt20221436';

UPDATE Contenido SET id_tmdb = 109431, descripcion = 'Un hombre verá cómo su identidad es robada por una mujer que aparece en su vida. ¿Qué pretende con ello? ¿Cómo es posible que una mujer de esas características quiera hacerse pasar por un señor?', trailer_url = 'https://www.youtube.com/watch?v=uoQERcYkJ7U' WHERE id_api = 'tt2024432';

UPDATE Contenido SET id_tmdb = 76203, descripcion = 'Basada en un hecho real ocurrido en 1850, narra la historia de Solomon Northup, un culto músico negro -y hombre libre- que vivía con su familia en Nueva York. Tras compartir una copa con dos desconocidos, Solomon descubre que ha sido drogado y secuestrado para ser vendido como esclavo en el Sur en una plantación de Louisiana. Renunciando a abandonar la esperanza, Solomon contempla cómo todos a su alrededor sucumben a la violencia, al abuso emocional y a la desesperanza. Entonces decide correr riesgos increíbles y confiar en la gente menos aparente para intentar recuperar su libertad y reunirse con su familia.', trailer_url = 'https://www.youtube.com/watch?v=8MsETvQYFZ8' WHERE id_api = 'tt2024544';

UPDATE Contenido SET id_tmdb = 137182, descripcion = 'Impactante historia de amor entre Elise y Didier. Ella se dedica a hacer tatuajes en su tienda y el toca el bajo en una banda a nivel regional.  Recuerdan su amor a primera vista, su pasión, cómo la música bluegrass les acercó, el embarazo inesperado y la alegría de tener a la preciosa Maybelle. Un círculo completo de felicidad para una pareja muy poco convencional. Pero a los 6 años de edad la enfermedad de la niña ocasionará una gran brecha en la pareja. El estrés y la tristeza causados por la enfermedad de Maybelle empiezan a pasarles factura y Didier y Elise reaccionan de modos completamente diferentes.', trailer_url = 'https://www.youtube.com/watch?v=dlAe82a7TAA' WHERE id_api = 'tt2024519';

UPDATE Contenido SET id_tmdb = 41727, descripcion = 'Este western contemporáneo nos sumerge en la América profunda siguiendo la odisea de Lucas Hood, un ex convicto dispuesto a cualquier cosa para resolver los asuntos de su turbio pasado. La oscura vida de Lucas Hood se complica aún más cuando, tras salir de prisión, decide tomar la identidad del nuevo sheriff de Banshee, un pequeño pueblo situado en Pennsylvania que oculta más de lo que parece. Allí espera encontrarse con su antigua colega y amante Ana, al tiempo que huye de quienes lo persiguen desde hace años y lidia a su manera con las acciones del siniestro cacique del pueblo.', trailer_url = 'https://www.youtube.com/watch?v=VI7haj7HTCA' WHERE id_api = 'tt2017109';

