UPDATE Contenido SET id_tmdb = 300673, descripcion = 'En febrero de 1952, una de las peores tormentas que jamás haya sufrido la costa este de Nueva Inglaterra daña a un petrolero frente a la costa de Cabo Cod. En un pequeño bote salvavidas, enfrentándose al temporal y las gélidas temperaturas, cuatro miembros de la Guardia Costera se disponen a rescatar a los 30 marineros atrapados a bordo del buque que se está hundiendo.', trailer_url = 'https://www.youtube.com/watch?v=7XC3b0OEfgg' WHERE id_api = 'tt2025690';

UPDATE Contenido SET id_tmdb = 244264, descripcion = 'La veinteañera Megan (Keira Knightley), de mentalidad todavía adolescente y asustada ante la proposición de matrimonio de su novio, busca un retiro temporal mientras huye durante una semana con Annika (Chloë Grace Moretz), una joven de 16 años que resulta ser su nueva mejor amiga.', trailer_url = 'https://www.youtube.com/watch?v=4o8peGbqxeI' WHERE id_api = 'tt2034031';

UPDATE Contenido SET id_tmdb = 311324, descripcion = 'Siglo XV, China. Dos mercenarios, uno inglés y otro español llegan a China buscando el secreto de la pólvora. Por el camino tienen un encuentro con una criatura espantosa; cuando lleguen se darán cuenta de que la Gran Muralla no se ha construído para defenderse de los mongoles, sino de algo mucho más peligroso y siniestro: la criatura que les atacó no está sola.', trailer_url = 'https://www.youtube.com/watch?v=8e_QwA0fWqs' WHERE id_api = 'tt2034800';

UPDATE Contenido SET id_tmdb = 284536, descripcion = 'Un profesor de inglés adicto al juego le debe a la mafia 40.000 dólares. Para ayudarle a salir a flote, su madre decide darle algún dinero que él trata de multiplicar rápidamente en Las Vegas, pero la suerte no le acompaña, por lo que su futuro estará en manos de la mafia.', trailer_url = 'https://www.youtube.com/watch?v=EtCkxWIXDQU' WHERE id_api = 'tt2039393';

UPDATE Contenido SET id_tmdb = 174772, descripcion = 'Una expedición al espacio compuesta por un equipo internacional de seis astronautas es enviada a una misión privada en la cuarta luna de Júpiter, Europa. Su objetivo principal era buscar vida extraterrestre. Pero se perdió la comunicación con ellos durante el transcurso del viaje.', trailer_url = 'https://www.youtube.com/watch?v=i2CqlWI1TLg' WHERE id_api = 'tt2051879';

UPDATE Contenido SET id_tmdb = 917496, descripcion = 'Tras una inesperada tragedia familiar, tres generaciones de la familia Deetz regresan a Winter River. La vida de Lydia, todavía atormentada por Bitelchús, da un vuelco cuando su rebelde hija adolescente, Astrid, descubre la misteriosa maqueta de la ciudad en el desván y el portal al Más Allá se abre accidentalmente. Con los problemas que se avecinan en ambos reinos, es sólo cuestión de tiempo que alguien diga el nombre de Bitelchús tres veces y el travieso demonio regrese para desatar su propio caos.', trailer_url = 'https://www.youtube.com/watch?v=9SzBZZhN0fQ' WHERE id_api = 'tt2049403';

UPDATE Contenido SET id_tmdb = 97365, descripcion = 'De repente, Alí tiene que hacerse cargo de su hijo Sam, un niño de cinco años al que apenas conoce. Como no tiene casa, ni dinero, ni amigos, se refugia en Antibes, en casa de su hermana, que los acoge cariñosamente. Tras una pelea en una discoteca, conoce a Stéphanie, una domadora de orcas en Marineland.', trailer_url = 'https://www.youtube.com/watch?v=6T8OK60XYIM' WHERE id_api = 'tt2053425';

UPDATE Contenido SET id_tmdb = 333352, descripcion = 'La coronel Katherine Powell, una oficial de la inteligencia militar británica, lidera una operación secreta para capturar a un grupo de terroristas en Nairobi, Kenia. Cuando se da cuenta que los terroristas están en una misión suicida, ella debe cambiar sus planes de ''capturar'' por ''matar''. El piloto estadounidense de drones Steve Watts recibe la orden de destruir el refugio donde se hallan los terroristas, pero una niña de nueve años ingresa en la zona donde podría ser herida.', trailer_url = 'https://www.youtube.com/watch?v=HQI2dXJ8zGk' WHERE id_api = 'tt2057392';

UPDATE Contenido SET id_tmdb = 257088, descripcion = 'Thriller de acción cargado de altas dosis de adrenalina y un ritmo trepidante en el que un joven agente del FBI , Johnny Utah, se infiltra en un equipo de atletas de élite a la búsqueda de emociones, liderado por el carismático Bodhi. Los atletas son sospechosos de llevar a cabo una serie de crímenes de forma extremadamente inusual.  Infiltrado en el grupo de forma encubierta y arriesgando su vida a cada instante, Utah se esfuerza por demostrar que son los artífices de una cadena de crímenes inconcebibles.', trailer_url = 'https://www.youtube.com/watch?v=ncvFAm4kYCo' WHERE id_api = 'tt2058673';

UPDATE Contenido SET id_tmdb = 504608, descripcion = '''Rocketman'' es la historia de Elton John, desde sus años como niño prodigio del piano en la Royal Academy of Music hasta llegar a ser una superestrella de fama mundial gracias a su influyente y duradera asociación con su colaborador y letrista Bernie Taupin.', trailer_url = 'https://www.youtube.com/watch?v=_AGX5wYKwfw' WHERE id_api = 'tt2066051';

UPDATE Contenido SET id_tmdb = 103328, descripcion = '"Holy Motors" narra 24 horas en la vida de un ser con múltiples caras: asesino, mendigo, ejecutivo, monstruo, padre de familia... El protagonista tiene una identidad completamente distinta en cada una de estas vidas. Encarna personajes como si se tratase de una película dentro de una película. ¿Pero dónde están las cámaras, el equipo de cine, el escenógrafo? ¿Y dónde está su casa, su refugio?', trailer_url = 'https://www.youtube.com/watch?v=kVF624osq2E' WHERE id_api = 'tt2076220';

UPDATE Contenido SET id_tmdb = 61068, descripcion = 'La mafia mata. Asesina, despedaza, quema, derrite en ácido y demás amabilidades. No hay espacio para el glamur del cine, al menos en la realidad italiana. No hay mafiosos de honor y líderes de atractivo irresistible sino capos sin piedad ni, a veces, alfabetización.', trailer_url = 'https://www.youtube.com/watch?v=5wahRkb8Ofk' WHERE id_api = 'tt2049116';

UPDATE Contenido SET id_tmdb = 412656, descripcion = 'Todd Hewitt es el último chico de Prentisstown, una pequeña comunidad cuya peculiaridad (aparte del hecho de que no hay mujeres) es que todos escuchan los pensamientos ajenos, lo que es definido como Ruido, un ruido que nunca cesa. Todd está contento porque sólo falta un mes para que sea su decimotercer cumpleaños y por fin, se convierta en hombre. Pero entonces, en uno de sus paseos por el bosque con su fiel perro, encuentra algo inesperado que cambiará su mundo para siempre: el silencio. O como lo define Todd: un agujero en el ruido.', trailer_url = 'https://www.youtube.com/watch?v=aJne8g5XkJs' WHERE id_api = 'tt2076822';

UPDATE Contenido SET id_tmdb = 1410, descripcion = 'En un mundo donde todas las fuentes de energía han desaparecido misteriosamente, un grupo de personas lucha por sobrevivir y reunirse con sus seres queridos. Los gobiernos han caído y el Ejército se ha hecho con el poder. La vida de la joven Charlie Matheson cambia radicalmente cuando los militares matan a su padre y secuestran a su hermano pequeño, Danny. Charlie emprende entonces un duro viaje en busca de su tío Miles, un antiguo marine que vive recluido tras el apagón. Lo que Charlie ignora es que su familia sabe la verdad sobre la desaparición de la electricidad y que ella puede ser una pieza clave para recuperarla.', trailer_url = 'https://www.youtube.com/watch?v=c3cMGHC-4ZY' WHERE id_api = 'tt2070791';

