UPDATE Contenido SET id_tmdb = 87825, descripcion = 'Gus es un veterano ojeador de béisbol que está perdiendo la vista poco a poco debido a su avanzada edad. Por ello decide viajar con su hija Mickey hasta Atlanta para observar a un joven talento. Pero las relaciones entre padre e hija han sido últimamente bastante conflictivas…', trailer_url = 'https://www.youtube.com/watch?v=V-wEMBaq2rw' WHERE id_api = 'tt2083383';

UPDATE Contenido SET id_tmdb = 127501, descripcion = 'Ambientada en la década de 1970 en un bonito rincón de la India, es la historia de tres jóvenes que se enteran que el amor no se puede definir ni contener por las normas de la sociedad.. Barfi es un chico con problemas de audición y del habla que se enamora de Shruti. A pesar de su profundo afecto por Barfi, Shruti cede a la presión social y a la de los padres para casarse con un hombre "normal".', trailer_url = NULL WHERE id_api = 'tt2082197';

UPDATE Contenido SET id_tmdb = 45094, descripcion = 'El asesino en serie Joe Carroll (James Purefoy) es un psicópata extremadamente peligroso capaz de conseguir generar un culto enfermizo en torno a su persona. Ahora ha conseguido escapar de prisión con la determinación de terminar su "obra". El antiguo agente del FBI Ryan Hardy (Kevin Bacon), que encarceló a Carroll hace 9 años, parece ser la persona idónea para poder volver a atraparlo, ya que le conoce mejor que a nadie. Él y su nuevo equipo emprenden la búsqueda y captura de Carroll, pero no saben que su objetivo está comunicándose con otros asesinos en serie para generar una telaraña de asesinatos y asesinos en serie que será muy difícil de desentrañar, incluso para Hardy.', trailer_url = 'https://www.youtube.com/watch?v=HbLGESANMWE' WHERE id_api = 'tt2071645';

