UPDATE Contenido SET id_tmdb = 894803, descripcion = 'Afreen, a rebellious Pakistani student sets ablaze the car of an Indian in London. Angered Afreen returns to Pakistan to ask for money from her grandfather that she has to pay in a month''s time as damages. However, she gets to know that he is no more and the only thing he has left for her is a letter-delivering task, written by Ram to Sita. As Afreen sets out to find Ram, there begins her journey of discovering the secret behind the 20-year-old letter.', trailer_url = 'https://www.youtube.com/watch?v=ZYl42EYOCNg' WHERE id_api = 'tt20850406';

UPDATE Contenido SET id_tmdb = 333385, descripcion = 'Una mujer se enamora de un hombre aparentemente perfecto... pero resulta ser un asesino profesional, algo que le planteará no pocas dudas éticas y morales.', trailer_url = 'https://www.youtube.com/watch?v=5dSDOlC-MoM' WHERE id_api = 'tt2091935';

UPDATE Contenido SET id_tmdb = 150540, descripcion = 'Riley es una chica que disfruta o padece toda clase de sentimientos. Aunque su vida ha estado marcada por la Alegría, también se ve afectada por otro tipo de emociones. Lo que Riley no entiende muy bien es por qué motivo tiene que existir la Tristeza en su vida. Una serie de acontecimientos hacen que Alegría y Tristeza se mezclen en una peligrosa aventura que dará un vuelco al mundo de Riley.', trailer_url = 'https://www.youtube.com/watch?v=x-xlkjPwaOY' WHERE id_api = 'tt2096673';

UPDATE Contenido SET id_tmdb = 986056, descripcion = 'Un grupo de supervillanos poco convencional es reclutado para hacer misiones para el gobierno: Yelena Belova, Bucky Barnes, Red Guardian, Ghost, Taskmaster y John Walker. Después de verse atrapados en una trampa mortal urdida por Valentina Allegra de Fontaine, estos marginados deben embarcarse en una peligrosa misión que les obligará a enfrentarse a los recovecos más oscuros de su pasado.', trailer_url = 'https://www.youtube.com/watch?v=QCbzHZ1Q2lw' WHERE id_api = 'tt20969586';

UPDATE Contenido SET id_tmdb = 40293, descripcion = 'Cuenta la desconocida historia de la juventud de Leonardo Da Vinci, uno de los mayores genios no sólo del Renacimiento, sino de toda la historia de la humanidad. Muestra las vivencias de este desenvuelto y brillante artista, inventor, espadachín, amante, soñador e idealista, que a los 25 años explora su intelecto y su talento mientras afronta el hecho de vivir en los confines de la realidad y del tiempo.', trailer_url = 'https://www.youtube.com/watch?v=vgg9nnALFGA' WHERE id_api = 'tt2094262';

Durante su búsqueda de financiación para poder desarrollar sus alocados proyectos, Leonardo termina realizando la colombina para el Carnaval de Cuaresma, lo cual le da la oportunidad de mostrarle a Lorenzo de Medici sus proyectos de ingeniería militar, una acción que llama la atención de la familia Medici y de la familia rival los Pazzi.

Mientras tanto Leonardo se topa con Saslan Al Rahim, miembro de una secta antigua que pone en duda la forma con la que los poderes mantienen al pueblo apartado del conocimiento y los beneficios que éste puede aportar a la mayoría que no ha sido bendecida ni por su posición ni por dinero.');

