UPDATE Contenido SET id_tmdb = 228203, descripcion = '''McFarland'' cuenta la historia de un entrenador de atletismo (interpretado por Kevin Costner, ''The Guardian'' y ''El último voto'') que hace lo posible por intentar reconstruir un equipo perteneciente al instituto de educación secundaria de una pequeña ciudad de California. A través de una enérgica motivación, el instructor consigue estimular la habilidad, la competitividad y el desarrollo de los alumnos que componen el equipo. El grupo de jóvenes deportistas, de la mano de este destacado entrenador, tendrá que hacer frente a numerosos obstáculos de carácter físico y social a lo largo de su recorrido y evolución. La capacidad de superación del preparador de la cuadrilla servirá de inspiración a todos los miembros del equipo, que tras un duro recorrido verán recompensado su esfuerzo y dedicación.', trailer_url = 'https://www.youtube.com/watch?v=74eJaVQFybI' WHERE id_api = 'tt2097298';

UPDATE Contenido SET id_tmdb = 102362, descripcion = 'Victor es la mano derecha de Alphonse, un mafioso neoyorquino que vive bajo la amenaza de un asesino que está matando a todos los miembros de su banda. Victor conoce a Beatrice, una mujer misteriosa que vive enfrente de su edificio y por la que empieza a sentirse atraído. Pronto descubre que la mujer ha sido víctima de un crimen y busca venganza. Pero ella también descubre que Víctor pretende vengar la muerte de su mujer y de su hija. Estos dos seres heridos y obsesionados llevarán a cabo juntos un oscuro y violento plan de venganza.', trailer_url = 'https://www.youtube.com/watch?v=88NfB6wKWis' WHERE id_api = 'tt2101341';

UPDATE Contenido SET id_tmdb = 42009, descripcion = 'Las historias más retorcidas pueblan esta alucinante serie antológica que muestra los peores rasgos de la humanidad, sus mayores innovaciones y mucho más.', trailer_url = 'https://www.youtube.com/watch?v=1iqra1ojEvM' WHERE id_api = 'tt2085059';

UPDATE Contenido SET id_tmdb = 122081, descripcion = 'Cuatro jóvenes estudiantes con ganas de mucha juerga acaban en la cárcel, tras ser sorprendidas en una casa llena de drogas durante sus locas vacaciones escolares de primavera. Pronto salen bajo fianza gracias a un joven traficante de armas y de drogas (James Franco), que ve en las chicas a unas potenciales delincuentes que podrían serle útiles.', trailer_url = 'https://www.youtube.com/watch?v=mI-1jgRnPWg' WHERE id_api = 'tt2101441';

UPDATE Contenido SET id_tmdb = 46298, descripcion = 'Gon Frecks, un niño de 12 años, vive con su tía Mito y su abuela en Isla Ballena, huérfano de madre y según su tía también de padre. Un día Gon es atacado por un oso del bosque, pero es salvado por un cazador quien le explica que está en busca de su maestro para así convertirse en un cazador, él es quien le dice que su padre Gin está vivo. Enterado de esto Gon decide convertirse en cazador para poder encontrar a su padre.', trailer_url = 'https://www.youtube.com/watch?v=F_YR1T_MdCI' WHERE id_api = 'tt2098220';

UPDATE Contenido SET id_tmdb = 169881, descripcion = 'Ambientada en el siglo XI en Inglaterra, narra la historia de Rob Cole, un joven que se queda huérfano, tras morir su madre por una extraña enfermedad. Decidido a convertirse en médico por la tragedia sufrida, el joven decide ir a Persia a estudiar medicina a las órdenes del sabio doctor Ibn Sina.', trailer_url = 'https://www.youtube.com/watch?v=Rv7sCnW1jIA' WHERE id_api = 'tt2101473';

UPDATE Contenido SET id_tmdb = 84348, descripcion = 'Un grupo de matones son contratados por un misterioso sujeto para que vayan a una casa abandonada y encuentren allí un VHS con imágenes horribles. Las instrucciones decían que el video sería de fácil reconocimiento, pero cuando llegan a la casa encuentran una enorme biblioteca llena de VHS. Su tarea será entonces descubrir cuál es la cinta maldita.', trailer_url = 'https://www.youtube.com/watch?v=8O8EmrbN1Ys' WHERE id_api = 'tt2105044';

UPDATE Contenido SET id_tmdb = 119450, descripcion = 'Un grupo de simios con grandes cualidades para la supervivencia toma las calles, liderado por César, un simio dotado de una inteligencia y unos instintos superiores para cualquier primate. Ante la necesidad de libertad, esta raza animal decide no doblegarse ante los humanos. Tendrá que luchar contra un grupo de humanos que han sobrevivido a una fuerte epidemia, desatada en la década anterior. Ambas partes han establecido una tregua, pero se verá interrumpida.', trailer_url = 'https://www.youtube.com/watch?v=DpSaTrW4leg' WHERE id_api = 'tt2103281';

UPDATE Contenido SET id_tmdb = 216282, descripcion = 'En el transcurso de un solo día, la ciudad de Silverton es azotada por una serie de tornados sin precedentes. Toda la ciudad está a merced de ciclones erráticos y mortales, mientras que los cazadores de tormentas predicen que lo peor está aún por llegar. La mayoría de las personas buscan refugio, mientras que otras corren hacia el vórtice, poniendo a prueba hasta dónde está dispuesto a llegar un cazador de tormentas para conseguir esa foto única que sólo se hace una vez en la vida. Contada a través de los ojos y de los objetivos fotográficos de cazadores profesionales de tormentas, aficionados en busca de emociones y valientes vecinos de la ciudad, “En el ojo de la tormenta” te lleva directamente al ojo de la tormenta para experimentar lo que ofrece la Madre Naturaleza en sus momentos más extremos.', trailer_url = 'https://www.youtube.com/watch?v=iJJJUEy5Vsg' WHERE id_api = 'tt2106361';

UPDATE Contenido SET id_tmdb = 850165, descripcion = 'Basada en la vida de los inseparables hermanos Von Erich, que hicieron historia en el competitivo mundo de la lucha libre profesional a principios de la década de los 80. A través de la tragedia y el triunfo, bajo la sombra de su dominante padre y entrenador, los hermanos buscan la inmortalidad en el escenario más importante del deporte.', trailer_url = 'https://www.youtube.com/watch?v=nUBJYKIQyxw' WHERE id_api = 'tt21064584';

UPDATE Contenido SET id_tmdb = 103663, descripcion = 'Tras un divorcio difícil, Lucas, de cuarenta años, ha encontrado una nueva novia, un nuevo trabajo y se dispone a reconstruir su relación con Marcus, su hijo adolescente. Pero algo va mal. Un detalle. Un comentario inocente. Una mentira fortuita. Y mientras la nieve comienza a caer y las luces de Navidad se iluminan, la mentira se extiende como un virus invisible. El estupor y la desconfianza se propagan y la pequeña comunidad se sumerge en la histeria colectiva, obligando a Lucas a luchar por salvar su vida y su dignidad.', trailer_url = 'https://www.youtube.com/watch?v=BSVDnUgJVYY' WHERE id_api = 'tt2106476';

UPDATE Contenido SET id_tmdb = 82990, descripcion = 'Todo transcurre cinco años después de los sucesos de "Paranormal Activity 2", que terminó con el secuestro de Hunter por parte de Katie. En la actualidad, Katie y Hunter, que ahora se hace llamar Robbie, se han trasladado a un nuevo barrio y sus vecinos, Alex y su familia, comienzan a experimentar sucesos paranormales que ocurren en su casa.', trailer_url = 'https://www.youtube.com/watch?v=o3unEjrJvBc' WHERE id_api = 'tt2109184';

UPDATE Contenido SET id_tmdb = 1236470, descripcion = 'En uno de los incendios forestales más mortíferos de la historia de Estados Unidos que amenaza la ciudad de Paradise, Kevin McKay, un conductor de autobús escolar, y Mary Ludwig, una maestra infantil, luchan para salvar a 22 niños del aterrador infierno.', trailer_url = 'https://www.youtube.com/watch?v=D3RJhf865SQ' WHERE id_api = 'tt21103218';

UPDATE Contenido SET id_tmdb = 91314, descripcion = 'Han pasado 4 años desde la tragedia de Chicago y la humanidad sigue reparando los destrozos, pero tanto los Autobots como los Decepticons han desaparecido de la faz de la Tierra. Ahora el Gobierno de los Estados Unidos está utilizando la tecnología rescatada en el asedio de Chicago para desarrollar sus propios Transformers. Al frente del proyecto está Joshua Joyce, un arrogante diseñador que piensa que los Autobots son "basura tecnológica" y se cree capaz de fabricar unos robots infinitamente más avanzados. Mientras tanto, Cade Yeager, un mécánico inventor, encuentra un Marmon semi-trailer. Al intentar repararlo, descubre que el camión no solo era un Transformer, sino también el mismísimo Optimus Prime, líder de los Autobots. Lo que Cade ignora son las consecuencias que pueden derivarse de este hallazgo.', trailer_url = 'https://www.youtube.com/watch?v=S30VkLn5a2o' WHERE id_api = 'tt2109248';

