UPDATE Contenido SET id_tmdb = 994108, descripcion = 'Adam es un guionista que, tras un encuentro casual con su misterioso vecino, regresa a la casa de su infancia donde descubre que sus padres, fallecidos hace mucho tiempo, están vivos y tienen la misma edad que el día de su muerte.', trailer_url = 'https://www.youtube.com/watch?v=D6D2_Ys2Q3o' WHERE id_api = 'tt21192142';

UPDATE Contenido SET id_tmdb = 324786, descripcion = 'La historia de Desmond T. Doss, quien, debido a que se lo prohibía su fe, combatió en la Segunda Guerra Mundial sin portar un arma. No disparó ni una bala, pero salvó a 75 personas de la muerte en la batalla de la isla de Okinawa.', trailer_url = 'https://www.youtube.com/watch?v=bSpqX6x97N0' WHERE id_api = 'tt2119532';

UPDATE Contenido SET id_tmdb = 993710, descripcion = 'Emily y Matt renunciaron hace años a ser espías de la CIA para formar una familia. Pero, cuando se descubre su tapadera, se ven arrastrados de nuevo al mundo del espionaje.', trailer_url = 'https://www.youtube.com/watch?v=MV2nYw6gL_w' WHERE id_api = 'tt21191806';

UPDATE Contenido SET id_tmdb = 257344, descripcion = 'Pixels cuenta como unos extraterrestres malinterpretan las imágenes de las máquinas recreativas como una declaración de guerra y deciden atacar la tierra, empleando dichos juegos como modelos para el asalto. El presidente de EEUU, Will Cooper (Kevin James), recurre entonces a su gran amigo de la infancia y campeón de las maquinitas de los años 80, Sam Brenner (Adam Sandler), quien actualmente trabaja como instalador de sistemas de home cinema, para encabezar un equipo de expertos jugadores de su época (Dinklage y Gad) cuya misión será derrotar a los extraterrestres y salvar al planeta. Monaghan interpreta al experto en armas del equipo.', trailer_url = 'https://www.youtube.com/watch?v=Lo9IWjUnMeo' WHERE id_api = 'tt2120120';

UPDATE Contenido SET id_tmdb = 265189, descripcion = 'Una familia pasa las vacaciones de invierno en los Alpes. El sol brilla y las pistas están magníficas, pero cuando almuerzan en un restaurante, se produce una avalancha. Los clientes del restaurante se asustan, Ebba, la madre, llama a su esposo Tomas para que le ayude e intenta salvar a sus hijos, pero Tomas ha huido para salvar su vida… La avalancha se detiene delante del restaurante, sin ocasionar daños, y sin embargo, el universo familiar se ha resquebrajado. Persiste una duda sobre el padre, y Tomas busca desesperadamente recuperar su lugar de patriarca de la familia.', trailer_url = 'https://www.youtube.com/watch?v=4aeC5DU-Oas' WHERE id_api = 'tt2121382';

UPDATE Contenido SET id_tmdb = 127532, descripcion = 'Lo que no te mata te hace más fuerte, pero en el caso de Sung Jinwoo, lo que lo mató lo hizo más fuerte. Después de ser brutalmente asesinado por monstruos en una mazmorra de alto rango, Jinwoo regresó con el Sistema, un programa que solo él puede ver y que eleva su nivel en todos los sentidos. Ahora, está decidido a descubrir los secretos detrás de sus poderes y la mazmorra que los engendró.', trailer_url = 'https://www.youtube.com/watch?v=TceDFwPXCuI' WHERE id_api = 'tt21209876';

UPDATE Contenido SET id_tmdb = 84175, descripcion = 'Hushpuppy, una intrépida niña de seis años, vive con su padre, Wink, en "la bañera", una comunidad del sur del Delta en el borde del mundo. El amor duro de Wink la prepara para el desmoronamiento del universo, para un momento en el que él ya no estará allí para protegerla. Cuando Wink contrae una misteriosa enfermedad, la naturaleza se descontrola: las temperaturas suben y los casquetes polares se derriten, desatando un ejército de criaturas prehistóricas llamadas uros. Con el aumento de las aguas, la llegada de los uros y la salud de Wink decayendo, Hushpuppy va en busca de su madre perdida.', trailer_url = 'https://www.youtube.com/watch?v=PrEswgnMXjI' WHERE id_api = 'tt2125435';

UPDATE Contenido SET id_tmdb = 84334, descripcion = 'Sixto Rodríguez fue un cantante de folk de Detroit que tuvo una carrera discográfica de corta duración, teniendo dos álbumes reconocidos, pero que no salieron a la venta, a principios de 1970.  Rodríguez continuó su carrera musical en el sur de África, convirtiéndose en un icono de la música pop, siendo un referente y sirviendo de inspiración a las futuras generaciones.  El largo rumor de que estaba muerto por suicidio, hizo que algunos fans de la década de los 90 buscaran la verdad del destino de su héroe.', trailer_url = 'https://www.youtube.com/watch?v=0fFQZK08oTI' WHERE id_api = 'tt2125608';

UPDATE Contenido SET id_tmdb = 254128, descripcion = 'La falla de San Andrés acaba cediendo ante las temibles fuerzas telúricas y desencadena un terremoto de magnitud 9 en California. Ante tal catástrofe, el piloto de helicóptero de búsqueda y rescate Ray y su ex esposa Emma viajan juntos desde Los Ángeles hasta San Francisco para salvar a su única hija, Blake. Pero su tortuoso viaje hacia el norte solamente es el comienzo del desomoronamiento de todo lo que creían firme en su vida.', trailer_url = 'https://www.youtube.com/watch?v=NZNHs7gyANA' WHERE id_api = 'tt2126355';

