UPDATE Contenido SET id_tmdb = 227159, descripcion = 'Secuela de "Cómo acabar con tu jefe"  En esta ocasión, Nick, Dalee y Kurt han formado su propia empresa y como consecuencia de ello, ¡no tienen jefe! Pero el trío protagonista tendrá que volver a idear un plan maestro parecido al de la anterior película. Esta vez, el objetivo es un inversor que les ha fastidiado sus planes de negocio. Así que deciden secuestrar a su hijo para poder pedirle un rescate al inversor y así recuperar las riendas de su empresa.', trailer_url = 'https://www.youtube.com/watch?v=utriEZFno0E' WHERE id_api = 'tt2170439';

UPDATE Contenido SET id_tmdb = 239563, descripcion = 'La película cuenta la historia de un chico cuyos padres se acaban de divorciar. La situación no es sencilla para él, le cuesta aceptar la nueva realidad y lo está pasando mal. Sin embargo, las cosas cambian cuando conoce al vecino que vive al lado de él. El hombre es un veterano de guerra misántropo y hedonista, y aparentemente no tienen nada en común. No obstante, entre ambos se establece una extraña relación de amistad y el hombre se convierte en el mentor del chico.', trailer_url = 'https://www.youtube.com/watch?v=y4rVNVE9ieE' WHERE id_api = 'tt2170593';

