UPDATE Contenido SET id_tmdb = 132316, descripcion = 'Un joven músico indio se enamora sin remedio de una chica extranjera que reside en su país, pero ella rechaza casarse con el típico indio de tez morena. Por eso la historia de amor que surge entre ambos acaba con una ruptura. Para olvidarse de su propia depresión, el músico decide alistarse en el ejército y flirtear con la muerte día tras día. Allí conocerá a una periodista del Discovery Channel que se sentirá muy atraída por su historia.', trailer_url = NULL WHERE id_api = 'tt2176013';

UPDATE Contenido SET id_tmdb = 152760, descripcion = 'A finales de la II Guerra Mundial (1939-1945), a un selecto grupo de historiadores, directores de museos y expertos en arte, tanto británicos como norteamericanos, se les encomienda la importante y peligrosa misión de recuperar las obras de arte robadas por los nazis durante la guerra para devolvérselas a sus legítimos propietarios. Era una misión imposible: las obras estaban muy bien custodiadas y el ejército alemán tenía orden de destruirlas en cuanto el Reich cayera. Pero aquellos hombres, en una carrera contrarreloj, arriesgaron sus vidas para evitar la destrucción de miles de años de cultura de la humanidad.', trailer_url = 'https://www.youtube.com/watch?v=Ez8kvzWxQHQ' WHERE id_api = 'tt2177771';

UPDATE Contenido SET id_tmdb = 156700, descripcion = 'Tres jóvenes adolescentes: Joe (Nick Robinson), Patrick (Gabriel Basso) y el excéntrico Biaggio (Moises Arias). Una cabaña perdida en el bosque. La libertad. The Kings of Summer nos adentra en la fantasiosa historia de estos tres jóvenes infelices que hartos de la sobreprotección de sus padres deciden independizarse y empezar una vida salvaje sin adultos y al margen de la sociedad, según sus normas, según sus principios.', trailer_url = 'https://www.youtube.com/watch?v=A6hZrvPfP9M' WHERE id_api = 'tt2179116';

UPDATE Contenido SET id_tmdb = 190859, descripcion = 'El marine del grupo de operaciones especiales de la Marina de Estados Unidos Chris Kyle es enviado a Irak con una sola misión: proteger a sus compañeros de ejército. Su precisión milimétrica salva incontables vidas en el campo de batalla y, a medida que se extienden sus valientes hazañas, se gana el apodo de ''Leyenda''. Sin embargo, su reputación también crece detrás de las líneas enemigas, de manera que ponen precio a su cabeza y se convierte en objetivo prioritario de los insurgentes. Al mismo tiempo también se está enfrentando a otra batalla en casa: ser un buen marido y padre desde el otro lado del mundo.', trailer_url = 'https://www.youtube.com/watch?v=iq7smHSQPho' WHERE id_api = 'tt2179136';

UPDATE Contenido SET id_tmdb = 619979, descripcion = 'Un marido adinerado, que permite que su esposa tenga relaciones extramatrimoniales para evitar el divorcio, se convierte en el principal sospechoso de la desaparición de los amantes de ella... Adaptación de la novela de Patricia Highsmith.', trailer_url = 'https://www.youtube.com/watch?v=yERv9roVKn0' WHERE id_api = 'tt2180339';

UPDATE Contenido SET id_tmdb = 951491, descripcion = 'Entre los acontecimientos de "Saw" y "Saw II", un enfermo y desesperado John Kramer viaja a México para someterse a un tratamiento médico arriesgado y experimental con la esperanza de encontrar una cura para su cáncer, pero descubre que todo forma parte de una operación con el fin de estafar a  los más desesperados.', trailer_url = 'https://www.youtube.com/watch?v=w0Aq7IoHxmo' WHERE id_api = 'tt21807222';

UPDATE Contenido SET id_tmdb = 158015, descripcion = 'Año 2022. En una futura sociedad distópica, el régimen político, llamado Nueva Fundación de los padres de América, ha implantado una medida catárquica ante la violencia campante y las cárceles saturadas: la "purga anual", según la cual una noche al año se puede cometer cualquier clase de crimen, incluso el asesinato, sin tener que responder ante la justicia. La violencia se desata durante esas 12 horas, y los individuos se desfogan, imperando la calma el resto del año. Horas antes de que comience la purga anual, el vendedor de sistemas de seguridad James Sandin regresa a su casa en un lujoso suburbio de Los Angeles junto a su esposa María y sus dos hijos, Zoey y Charlie. Lo que no contaba esa famillia es que poco tiempo después de comenzar la noche un extraño llame a la puerta.', trailer_url = 'https://www.youtube.com/watch?v=0gsWs5v5OvQ' WHERE id_api = 'tt2184339';

UPDATE Contenido SET id_tmdb = 1016084, descripcion = 'Dos emprendedores dispares, el innovador Mike Lazaridis y el despiadado empresario Jim Balsillie, unieron sus fuerzas en un proyecto que se convertiría en un éxito mundial en poco más de una década. El dispositivo que uno de ellos inventó y el otro vendió fue BlackBerry, un adictivo teléfono móvil que cambió la forma en que el mundo trabajaba, jugaba y se comunicaba. Pero justo cuando BlackBerry alcanzaba nuevas cimas, también empezó a perderse entre la niebla de las guerras de smartphones, la indecisión de los directivos y las distracciones externas.', trailer_url = 'https://www.youtube.com/watch?v=WKylzpr0Jbg' WHERE id_api = 'tt21867434';

UPDATE Contenido SET id_tmdb = 109418, descripcion = 'Lenny se ha trasladado con su familia a la pequeña ciudad donde tanto él como sus amigos se criaron. En esta ocasión, los adultos serán quienes reciban toda una lección de sus propios hijos.', trailer_url = 'https://www.youtube.com/watch?v=0c_zXgsy3QQ' WHERE id_api = 'tt2191701';

UPDATE Contenido SET id_tmdb = 109091, descripcion = 'Un respetado abogado (Michael Fassbender) del sudoeste de Estados Unidos decide participar por primera vez en una operación de tráfico de drogas en la frontera mexico-norteamericana. Su principal motivo es el de obtener dinero rápido y poder casarse con su querida novia, la dulce Laura (Penélope Cruz). Su conexión con los cárteles son Reiner (Javier Bardem), un ostentoso capo de la droga irremediablemente enamorado de su chica, la sexy y ambiciosa Malkina (Cameron Diaz), y Westray (Brad Pitt), un intermediario amigo suyo.', trailer_url = 'https://www.youtube.com/watch?v=sitiAk4WLQ8' WHERE id_api = 'tt2193215';

