UPDATE Contenido SET id_tmdb = 122906, descripcion = 'La trama de la película gira en torno a un joven llamado Tim Lake. El protagonista y su familia tienen el curioso don de poder viajar a través del tiempo. Al descubrir esta cualidad, Tim empieza a beneficiarse de ello para cambiar diferentes aspectos de su vida. Se enamora de una chica, Mary, a la que conoce tras transladarse a vivir a Londres por motivos de trabajo. Su historia de amor se verá beneficiada gracias al don de Tim, sin embargo, el protagonista no tardará en darse cuenta de que su habilidad no es capaz de ampararle en algunos problemas y cuestiones familiares.', trailer_url = 'https://www.youtube.com/watch?v=UBzabfE3Ysw' WHERE id_api = 'tt2194499';

UPDATE Contenido SET id_tmdb = 241554, descripcion = 'Al veterano mercenario Jimmy Conlon, conocido como El Cavatumbas, lo persiguen los crímenes del pasado, pero tambien el policía que le ha seguido la pista durante 30 años. Cuando se entera de que su hijo Mike corre peligro, Jimmy tiene que elegir entre el clan criminal al que ha pertenecido siempre y su familia, a la que había abandonado hace mucho tiempo. Sólo dispone de una noche para averiguar a quién debe su lealtad.', trailer_url = 'https://www.youtube.com/watch?v=dUCZD9NUVpY' WHERE id_api = 'tt2199571';

UPDATE Contenido SET id_tmdb = 1020006, descripcion = 'Cuando la adolescente Priscilla Beaulieu conoce a Elvis Presley en una fiesta, él ya es una meteórica superestrella del rock and roll pero se convierte en alguien totalmente inesperado en momentos privados: un apasionante flechazo, un aliado en la soledad, un vulnerable mejor amigo. Película basada en las memorias ''Elvis and Me'', escritas por Priscilla Beaulieu Presley, publicadas en 1985 y que relatan el largo noviazgo y turbulento matrimonio de Elvis y Priscilla, desde una base militar alemana hasta su finca de ensueño en Graceland.', trailer_url = 'https://www.youtube.com/watch?v=mIHaluJ1yjo' WHERE id_api = 'tt22041854';

