UPDATE Contenido SET id_tmdb = 157353, descripcion = 'El Dr. Will Caster (Johnny Depp), prestigioso investigador en el campo de la Inteligencia Artificial, trabaja en la creación de una máquina sensitiva que combine la inteligencia colectiva con las emociones humanas. Sus controvertidos experimentos le han hecho famoso, pero también lo han convertido en el principal objetivo de extremistas anti-tecnológicos. Su mujer Evelyn (Rebecca Hall) y Max, su mejor amigo (Paul Bettany) son sus colaboradores, pero ellos se plantean la cuestión moral de si deben fabricar esa máquina. Cuando Will sufre un atentado, Evelyn y él deciden tomar una decisión radical de imprevisibles consecuencias.', trailer_url = 'https://www.youtube.com/watch?v=MfMz2363exg' WHERE id_api = 'tt2209764';

UPDATE Contenido SET id_tmdb = 132344, descripcion = 'Han pasado dos décadas desde que se encontraron por primera vez en un tren en Vienna (''Antes del amanecer'' (1995)), y más tarde en París (''Antes del atardecer'' (2004)). Ahora es el turno de Grecia, páis en el que Celine y Jesse se encuentran de visita. La tercera entrega de la trilogía, retomando las vidas de los protagonistas, nueve años después de su segundo encuentro romántico y el misterio sobre cómo concluyó.', trailer_url = 'https://www.youtube.com/watch?v=NRVLVPWzeek' WHERE id_api = 'tt2209418';

