UPDATE Contenido SET id_tmdb = 138697, descripcion = 'Jon Martello (Joseph Gordon-Levitt), un joven adicto al sexo en general y al porno en particular, intenta ejercer algún tipo de control sobre sí mismo. Jon tiende a deshumanizarlo todo: su apartamento, su coche, su familia, su iglesia y las mujeres. Sin embargo, hasta los ligues más sofisticados no pueden compararse con el placer que obtiene viendo pornografía en su ordenador. Insatisfecho con su vida, decide cambiar. Gracias a la relación con dos mujeres muy distintas, Barbara (Scarlett Johansson) y Esther (Julianne Moore), aprenderá grandes lecciones sobre la vida y el amor.', trailer_url = 'https://www.youtube.com/watch?v=ttSNSsH44uY' WHERE id_api = 'tt2229499';

