UPDATE Contenido SET id_tmdb = 120467, descripcion = 'El Sr. Gustave H., un legendario conserje de un famoso hotel europeo de entreguerras, entabla amistad con Zero Moustafa, un joven empleado al que convierte en su protegido. La historia trata sobre el robo y la recuperación de una pintura renacentista de valor incalculable y sobre la batalla que enfrenta a los miembros de una familia por una inmensa fortuna. Como telón de fondo, los levantamientos que transformaron Europa durante la primera mitad del siglo XX.', trailer_url = 'https://www.youtube.com/watch?v=b7Dg35LBGBc' WHERE id_api = 'tt2278388';

UPDATE Contenido SET id_tmdb = 228165, descripcion = 'Segunda película sobre el personaje marino más querido por niños y adultos, Bob Esponja. El argumento gira en torno a Bob Esponja y sus inseparables amigos del mar, como son Patricio y la ardilla Arenita, y otros personajes de la serie en la que se basa, como Calamardo y Don Cangrejo. En esta ocasión Bob Esponja y cía se embarcan en una aventura en la que deberán encontrar una receta robada, lo que llevará a los personajes de Fondo Bikini hasta nuestra dimensión. Por lo que la película mezcla animación y escenas de acción real. Las escenas de animación están hechas tanto con CGI (imagen generada por ordenador) como en dibujo a mano. En la dimensión real se tendrán que enfrentar al pirata Alameda Jack, al que da vida Antonio Banderas.', trailer_url = 'https://www.youtube.com/watch?v=Whvm9CGDp2U' WHERE id_api = 'tt2279373';

