UPDATE Contenido SET id_tmdb = 1041613, descripcion = 'Cecilia (Sydney Sweeney), recién llegada de Estados Unidos, ingresa como novicia en un convento de la remota campiña italiana. Allí es recibida por el Padre Tedeschi (Álvaro Morte), quien la introduce en las rutinas religiosas. Un día descubre que está embarazada y lo que parecía un milagro, por conservar aún su virginidad, resulta ocultar un siniestro secreto que hará que busque salir de aquel lugar desesperadamente.', trailer_url = 'https://www.youtube.com/watch?v=lywekKHvLjo' WHERE id_api = 'tt23137390';

