UPDATE Contenido SET id_tmdb = 44217, descripcion = 'Sigue las aventuras de Ragnar Lothbrok, el héroe más grande de su época. La serie narra las sagas de la banda de hermanos vikingos de Ragnar y su familia, cuando él se levanta para convertirse en el rey de las tribus vikingas. Además de ser un guerrero valiente, Ragnar encarna las tradiciones nórdicas de la devoción a los dioses, la leyenda dice que él era un descendiente directo de Odín, el dios de la guerra y los guerreros.', trailer_url = 'https://www.youtube.com/watch?v=7rcozIVtujw' WHERE id_api = 'tt2306299';

Aunque sin duda, el gran fichaje de esta nueva etapa es el de Jonathan Rhys Meyers ("Match Point"), quien interpretará de manera regular al obispo Heahmund. Este personaje es un fanático religioso que se mueve entre el pecado y la penitencia, fue obispo de Wessex y supondrá un duro rival para Ivar sin huesos. Es además una figura precursora de los guerreros templarios.');

UPDATE Contenido SET id_tmdb = 181886, descripcion = 'Adam es un afable profesor de historia que lleva una vida bastante monótona. Un día, viendo una película, descubre a un actor que es idéntico a él. Obsesionado con la idea de tener un doble, la búsqueda de ese hombre tendrá para él consecuencias inesperadas...', trailer_url = 'https://www.youtube.com/watch?v=YlHXu2Nn_7E' WHERE id_api = 'tt2316411';

UPDATE Contenido SET id_tmdb = 216015, descripcion = 'Cuando la estudiante de Literatura Anastasia Steele recibe el encargo de entrevistar al exitoso y joven empresario Christian Grey, queda impresionada al encontrarse ante un hombre atractivo, seductor y también muy intimidante. La inexperta e inocente Ana intenta olvidarle, pero pronto comprende cuánto le desea. Cuando la pareja por fin inicia una apasionada relación, Ana se sorprende por las peculiares prácticas eróticas de Grey, al tiempo que descubre los límites de sus propios y más oscuros deseos.', trailer_url = 'https://www.youtube.com/watch?v=37azbhKZ0D4' WHERE id_api = 'tt2322441';

UPDATE Contenido SET id_tmdb = 226857, descripcion = 'Jade, una tímida joven de familia privilegiada, y David, un chico carismático y divertido, se enamoran perdidamente durante un verano. Cuando el padre de ella intenta separarlos, su pasión los llevará a arrostrar situaciones temerarias. Remake de ''Amor sin fin'' (1981).', trailer_url = 'https://www.youtube.com/watch?v=b-I3Aidc4Bg' WHERE id_api = 'tt2318092';

UPDATE Contenido SET id_tmdb = 242224, descripcion = 'Seis años después de la violenta muerte de su marido, Amelia continúa perdida intentando educar a Samuel, su hijo de seis años, que vive aterrorizado por un monstruo que se le aparece en sueños y amenaza con matarlos. Cuando un inquietante libro de cuentos llamado “The Babadook” aparece en su casa, Samuel se muestra convencido de que el Babadook es la criatura sobre la que ha estado soñando. Cuando sus alucinaciones entran en una espiral fuera de control, se vuelve impredecible y violento. Amelia, muy asustada por el comportamiento de su hijo, se ve forzada a medicarle. Pero cuando comienza a vislumbrar una presencia siniestra a su alrededor, Amelia poco a poco se da cuenta de que aquello sobre lo que Samuel la ha estado advirtiendo puede ser real.', trailer_url = 'https://www.youtube.com/watch?v=88DDAyYkvis' WHERE id_api = 'tt2321549';

