UPDATE Contenido SET id_tmdb = 191714, descripcion = 'En Mumbai, cada día, miles de amas de casa envían la comida a sus maridos a su lugar de trabajo a través de un eficiente y específico sistema de transporte. Un error en una de estas entregas pone en contacto a una joven con un hombre anodino. Juntos van construyendo un mundo de fantasía a través de notas que acompañan a la comida, lo que supone una amenaza para la vida real de cada uno. Esta película habla de la diferencia entre la vida que soñamos y la que vivimos, y del coraje que hace falta para convertir en realidad nuestras fantasías.', trailer_url = 'https://www.youtube.com/watch?v=PJGUU4w9FhI' WHERE id_api = 'tt2350496';

