UPDATE Contenido SET id_tmdb = 205220, descripcion = 'Philomena es la verdadera historia de la búsqueda de una madre por su hijo perdido. Quedando embarazada cuando era un adolescente en Irlanda en 1952, Philomena Lee fue enviada al convento de Roscrea para ser atendidas como una "mujer en desgracia". Cuando su hijo era sólo un bebé, las monjas se lo llevaron para darlo en adopción en Estados Unidos. Philomena pasó los próximos cincuenta años buscándolo en vano. Entonces conoció a Martin Sixsmith, un periodista cansado del mundo, tan cínico que Philomena confiaba en él. Juntos partieron hacia América en un viaje que no sólo revelaría la extraordinaria historia del hijo de Philomena, sino que también crearía un vínculo muy cercano e inesperado entre Philomena y Martin.', trailer_url = 'https://www.youtube.com/watch?v=a8WyFLsdtNw' WHERE id_api = 'tt2431286';

