UPDATE Contenido SET id_tmdb = 209274, descripcion = 'Años 60, Polonia. Una joven ilusionada con la búsqueda de la fé y la religión, esta a punto de tomar sus votos y convertirse en monja, aquello que siempre ha deseado. Se ha preparado duramente durante largos años y convertida en una novicia modelo decide entregarse totalmente a su religión.  Todo cambia en el momento en el que se entera de un secreto que atormentaba a toda su familia. Sus antepasados se vieron envueltos durante la ocupación nazi con terribles consecuencias, ante tales acontecimientos decide emprender una larga lucha para conocer la verdad.', trailer_url = 'https://www.youtube.com/watch?v=6C99zDU4Xp8' WHERE id_api = 'tt2718492';

