UPDATE Contenido SET id_tmdb = 331781, descripcion = 'Documental sobre la famosa cantante británica Amy Winehouse, que cuenta con imágenes inéditas de archivo y entrevistas con la malograda estrella, que murió en julio del 2011 a los veintisiete años de edad por parada cardíaca a consecuencia de sus excesos con las drogas y el alcohol, adicciones agravadas por su bulimia. Amy Winehouse, ganadora de seis Premios Grammy, se vio desde muy joven afectada por el divorcio de sus padres. Tenía un talento natural para el jazz y el soul y una voz prodigiosa que pronto la convirtió en una estrella mundial a pesar de lanzar sólo dos discos; pero la fama, la prensa sensacionalista, los intereses de la industria -y de su entorno- y su turbulento amor con el que fue su marido, Blake Fielder-Civil, la condujeron finalmente a su trágico destino en su piso de Camden, Londres.', trailer_url = 'https://www.youtube.com/watch?v=fq4oqmUs92U' WHERE id_api = 'tt2870648';

UPDATE Contenido SET id_tmdb = 263109, descripcion = 'Cuando Shaun decide tomarse el día libre y divertirse un poco, se encuentra con que va a tener más acción de lo que esperaba. Las trastadas de Shaun acaban por lograr que se lleven al Granjero, así que Shaun y el rebaño han de viajar a la Gran Ciudad y rescatarle. ¿Encontrará Shaun al Granjero en ese mundo extraño y desconocido de la Ciudad antes de que se pierda para siempre?', trailer_url = 'https://www.youtube.com/watch?v=LyXjbMRbza8' WHERE id_api = 'tt2872750';

UPDATE Contenido SET id_tmdb = 401981, descripcion = 'Dominika Egorova (Jennifer Lawrence) es reclutada contra su voluntad para ser un “gorrión”, una seductora adiestrada del servicio de seguridad ruso. Dominika aprende a utilizar su cuerpo como arma, pero lucha por conservar su sentido de la identidad durante el deshumanizador proceso de entrenamiento. Hallando su fuerza en un sistema injusto, se revela como uno de los activos más sólidos del programa. Su primer objetivo es Nate Nash (Joel Edgerton), un funcionario de la CIA que dirige la infiltración más confidencial de la agencia en la inteligencia rusa. Los dos jóvenes agentes caen en una espiral de atracción y engaño que amenaza sus carreras, sus lealtades y la seguridad de sus respectivos países.', trailer_url = 'https://www.youtube.com/watch?v=DuEPq0wxVME' WHERE id_api = 'tt2873282';

