UPDATE Contenido SET id_tmdb = 242095, descripcion = 'Tres estudiantes desaparecen sin dejar rastro cuando estaban investigando la pista de un hacker de ordenadores. Todo empieza cuando Nic, su novia Haley y su mejor amigo Jonah, que viajan por carretera a través del Suroeste, dan un rodeo para localizar a un genio informático que ya ha conseguido colarse en los sistemas del MIT y sacar a la luz fallos de seguridad. Los jóvenes han despertado la curiosidad del misterioso hacker y viceversa. Al ponerse en contacto, de repente, todo se oscurece. Cuando Nic recobra el conocimiento, tiene la impresión de estar viviendo una pesadilla: sus amigos no aparecen y a él lo está interrogando el Dr. Wallace Damon. Mientras se libra una batalla de ingenios entre ambos, Nic busca un modo de liberarse.', trailer_url = 'https://www.youtube.com/watch?v=1cLNkFZdku4' WHERE id_api = 'tt2910814';

