UPDATE Contenido SET id_tmdb = 243940, descripcion = 'Un equipo de estudiantes de investigación está mapeando el cerebro humano cuando accidentalmente matan a uno de ellos. El resto, al intentar reanimar a su colega, desatarán una fuerza letal. Luchando por sus vidas, el equipo deberá contener al recién vuelto a la vida en el laboratorio antes de que se entere en el mundo entero.', trailer_url = 'https://www.youtube.com/watch?v=WHfsR30wxuM' WHERE id_api = 'tt2918436';

