UPDATE Contenido SET id_tmdb = 250734, descripcion = 'Se trata de un retrato de una heroína victoriana que sabe lo dificil que es para una mujer definir sus sentimientos en un lenguaje creado principalmente por el hombre para expresar los suyos. De carácter fuerte e independiente, esta heroína, joven propietaria de la mayor granja de su localidad, está en situación de elegir entre los tres pretendientes que la rondan. Dichos pretendientes son Gabriel Oak, criador de ovejas; Frank Troy, un apuesto y temerario sargento; y William Boldwood, un maduro y próspero soltero. Al elegir descubrirá en poco tiempo que ha renunciado a la sencillez de la vida de soltera para convertirse en la humilde mitad de un indiferente todo matrimonial.', trailer_url = 'https://www.youtube.com/watch?v=KaJGTIG1ca0' WHERE id_api = 'tt2935476';

