UPDATE Contenido SET id_tmdb = 269149, descripcion = 'La moderna metrópoli mamífera de Zootrópolis es una ciudad absolutamente única. Está compuesta de barrios con diferentes hábitats como la lujosa Plaza Sahara, el Distrito Selva Tropical y el gélido Distrito Tundra. Es un crisol donde los animales de cada entorno conviven, un lugar donde no importa lo que seas. De hecho puedes ser cualquier cosa, desde un elefante enorme hasta la musaraña más diminuta. Pero cuando llega la optimista agente Judy Hopps, descubre que ser la primera conejita de un cuerpo policial compuesto de animales duros y enormes no es nada fácil. Pero está decidida a demostrar su valía y se mete de cabeza en un caso, a pesar de que eso significa trabajar con Nick Wilde, un zorro parlanchín y estafador, para resolver el misterio.', trailer_url = 'https://www.youtube.com/watch?v=rWq7HL67CsY' WHERE id_api = 'tt2948356';

UPDATE Contenido SET id_tmdb = 295699, descripcion = 'Jake llega a la Universidad de Texas en su deportivo, con las ventanillas bajadas y la música a todo volumen. Quedan sólo unos días para que arranque el curso, pero piensa aprovecharlos conociendo chicas, yendo a fiestas y haciendo amigos. Secuela espiritual de Dazed and Confused, ambientada en los años 80. Los protagonistas, un grupo de jugadores de béisbol a punto de ingresar en la Universidad, son conscientes de que las obligaciones de la edad adulta son ya ineludibles.', trailer_url = 'https://www.youtube.com/watch?v=8WAulKwKHbY' WHERE id_api = 'tt2937696';

UPDATE Contenido SET id_tmdb = 287948, descripcion = 'En los bajos fondos de Francia, Frank Martin (Ed Skrein) es conocido como «Transporter», el mejor conductor y mercenario que se puede comprar con dinero. Frank se rige por tres simples reglas: sin nombres, sin preguntas y sin renegociaciones, y transporta cualquier cosa por el precio adecuado. Hasta que conoce a la misteriosa mujer fatal llamada Anna (Loan Chabanol), que lidera un grupo de mortíferos asaltantes y que no se detendrá ante nada con tal de acabar con una despiadada banda rusa de traficantes humanos. Anna sabe que Frank es el mejor en su trabajo y, para asegurarse su colaboración, mantiene rehén a su padre (Ray Stevenson). Ahora, padre e hijo se verán obligados a trabajar con Anna para llevar a esta peligrosa banda ante la justicia.', trailer_url = 'https://www.youtube.com/watch?v=DPJGqXBqFzw' WHERE id_api = 'tt2938956';

