UPDATE Contenido SET id_tmdb = 568124, descripcion = 'Los Madrigal son una familia extraordinaria que vive en una casa mágica de un pueblo vibrante en las montañas de Colombia, escondidas en un ''Encanto''. La magia ha bendecido a cada niño de la familia con un don único, desde la superfuerza hasta el poder de sanar. A todos, excepto Mirabel, quien desea ser tan especial como el resto de su familia.  Pero cuando la magia que rodea al Encanto está en peligro, Mirabel decide que ella, la única Madrigal sin ningún tipo de don único, puede ser la única esperanza de su excepcional familia.', trailer_url = 'https://www.youtube.com/watch?v=SAH_W9q_brE' WHERE id_api = 'tt2953050';

