UPDATE Contenido SET id_tmdb = 208134, descripcion = 'Historia sobre un malhumorado anciano de 86 años, Irving Zisman (Johnny Knoxville), al que inesperadamente le encasquetan a su nieto de 8 años Billy (Jackson Nicoll). Las dos generaciones de folloneros pronto se sienten muy unidos al comenzar un increíble viaje por el corazón de Norteamérica, haciendo un montón de jugarretas y gamberradas a gente desprevenida de la vida real, que no tenían ni la más remota idea de que estaban interviniendo en una comedia de cámara oculta "verdaderamente escandalosa". Spin off de ''Jackass''.', trailer_url = 'https://www.youtube.com/watch?v=_MSrAwfagG4' WHERE id_api = 'tt3063516';

