UPDATE Contenido SET id_tmdb = 312221, descripcion = 'Adonis Johnson no llego a conocer a su padre, el campeón del mundo de los pesos pesados Apollo Creed, que falleció antes de que él naciera. Sin embargo, nadie puede negar que lleva el boxeo en la sangre, por lo que pone rumbo a Filadelfia, el lugar en el que se celebró el legendario combate entre su padre y Rocky Balboa. Una vez allí, Adonis busca a Rocky y le pide que sea su entrenador. A pesar de que este insiste en que ya ha dejado ese mundo para siempre, Rocky ve en Adonis la fuerza y determinación que tenía su enconado rival, y que terminó por convertirse en su mejor amigo. Finalmente, acepta entrenarle a pesar de estar librando su propio combate contra un rival más letal que cualquiera a los que se enfrentó en el cuadrilátero.', trailer_url = 'https://www.youtube.com/watch?v=8pPXp7pRKbQ' WHERE id_api = 'tt3076658';

UPDATE Contenido SET id_tmdb = 245168, descripcion = 'Cuenta la historia de las sufragistas inglesas en los albores de la Primera Guerra Mundial. La mayoría de estas mujeres no venían de clases altas, sino que eran mujeres trabajadoras que veían cómo sus protestas pacíficas no servían para nada. Radicalizadas y volviendo su lucha cada vez más violenta, estaban dispuestas a perderlo todo en su búsqueda incansable de la igualdad: sus trabajos, sus casas, sus hijos y sus vidas. Esta es la historia de Maud (Carey Mulligan), una de estas mujeres, y de su lucha por la dignidad y la de sus compañeras.', trailer_url = 'https://www.youtube.com/watch?v=XVw1MUzjthI' WHERE id_api = 'tt3077214';

