UPDATE Contenido SET id_tmdb = 288036, descripcion = 'Desde que en la época universitaria tuvieron un encuentro fortuito en el que ambos perdieron la virginidad, Jake y Lainey se han convertido en unos infieles compulsivos que han destruido sus relaciones de pareja una detrás de otra. Tras cortar con su último novio a causa de sus infidelidades, Lainey acepta ir a terapia y asiste a una reunión de adictos al sexo en Nueva York. Allí se reencuentra con Jake, y ambos descubren que tienen el mismo problema con sus relaciones desde que se acostaran 12 años atrás. Con la firme intención de apoyarse mutuamente para cambiar sus malos hábitos, emprenden una amistad platónica que les ayuda a construir nuevas y duraderas relaciones de pareja. El problema surgirá cuando empiecen a sentirse atraídos el uno por el otro.', trailer_url = 'https://www.youtube.com/watch?v=mbkUYoLiMto' WHERE id_api = 'tt3165612';

