UPDATE Contenido SET id_tmdb = 1249213, descripcion = 'Violet, una joven madre viuda que lleva años sin salir con nadie, al llegar al restaurante de lujo donde ha quedado con Henry, se siente aliviada al descubrir que este es mucho más encantador y apuesto de lo que esperaba. Pero la química se resquebraja cuando Violet empieza a mostrarse irritable al recibir una serie de mensajes anónimos en su móvil que acaban por aterrorizarla.', trailer_url = 'https://www.youtube.com/watch?v=FfzX2FtPI6w' WHERE id_api = 'tt32149847';

UPDATE Contenido SET id_tmdb = 1151031, descripcion = 'Un hermano y su hermana descubren un aterrador ritual en la apartada casa de su nueva madre adoptiva. Lo que parece un hogar seguro pronto se convierte en una pesadilla, donde figuras siniestras, extrañas imágenes en vídeo y sucesos paranormales los rodean.', trailer_url = 'https://www.youtube.com/watch?v=wLMRLWSsfhw' WHERE id_api = 'tt32246771';

UPDATE Contenido SET id_tmdb = 337404, descripcion = 'Ambientada en el Londres de los años 70, en plena revolución del punk rock, muestra a una joven estafadora llamada Estella, una chica inteligente y creativa, decidida a convertirse en una exitosa diseñadora de moda, que se asocia con un par de ladrones para sobrevivir en las calles de la capital británica. Pero cuando su talento para la moda llama la atención de la legendaria diseñadora, la Baronesa von Hellman, Estella cambia el rumbo de su vida hasta que una serie de acontecimientos y revelaciones que harán que Estella asuma su lado malvado y se convierta en la estridente, moderna y vengativa Cruella de Vil.', trailer_url = 'https://www.youtube.com/watch?v=1DMmsFz6hj8' WHERE id_api = 'tt3228774';

UPDATE Contenido SET id_tmdb = 219937, descripcion = 'En 1991, en Miami, Dexter Morgan pasa de ser estudiante a ser un asesino en serie vengador. Cuando sus impulsos sanguinarios ya no pueden ignorarse, Dexter debe aprender a canalizar su oscuridad interior. Con la guía de su padre, Harry, adopta un código diseñado para ayudarlo a encontrar y matar a personas que merecen ser eliminadas de la sociedad sin llamar la atención de las fuerzas del orden. Este es un desafío particular para el joven Dexter, ya que comienza una pasantía forense en el Departamento de Policía Metropolitana de Miami.', trailer_url = 'https://www.youtube.com/watch?v=Bw8ZdQpVtdU' WHERE id_api = 'tt32252772';

