UPDATE Contenido SET id_tmdb = 363676, descripcion = 'Chesley ''Sully'' Sullenberger es un piloto comercial que en 2009 se convirtió en un héroe cuando, al poco de despegar, su avión se averió y el comandante logró realizar un aterrizaje forzoso del aparato en pleno río Hudson, en Nueva York, con 155 pasajeros a bordo.', trailer_url = 'https://www.youtube.com/watch?v=w9bSO1hPq7w' WHERE id_api = 'tt3263904';

UPDATE Contenido SET id_tmdb = 579047, descripcion = 'Nick Bannister, un investigador privado que se interna en el oscuro y seductor mundo del pasado, ayuda a sus clientes a recuperar recuerdos perdidos. Vive a orillas de la costa de Miami que se encuentra sumergida en gran parte bajo el mar. Un día, su vida cambia cuando aparece Mae, una nueva clienta. Aunque Mae solo acude a su consulta para encontrar un objeto perdido, se convertirá en una peligrosa obsesión. Mientras Bannister intenta encontrar el motivo de la desaparición de Mae, descubre una violenta conspiración y, al final, deberá responder a la gran pregunta: ¿Hasta dónde llegarías para aferrarte a tus seres queridos?', trailer_url = 'https://www.youtube.com/watch?v=Nohj00cD_-U' WHERE id_api = 'tt3272066';

