UPDATE Contenido SET id_tmdb = 267860, descripcion = 'En un mundo gobernado por la injusticia y el caos, aparece la figura del presidente de los Estados Unidos que junto a su portavoz Trumbull, liderarán una lucha interna por las libertades de todos los americanos.  Sin embargo, se producirá un intento de derrocamiento por parte de fuerzas espías para acabar con el primer ministro inglés. Esto podría significar un intento de eliminar la paz mundial a toda costa. Para ello el presidente contará con la inestimable ayuda de su guardaespaldas. Mike Benning agente secreto del MI6 liderará una contención para intentar acabar con esta revolución. Benning no estará sólo ya que volverá a encontrar apoyo de Trumbull, especializado en técnicas paramilitares.', trailer_url = 'https://www.youtube.com/watch?v=Ja9XxdMAEk4' WHERE id_api = 'tt3300542';

