UPDATE Contenido SET id_tmdb = 262504, descripcion = 'Tras las revelaciones trascendentales de ''Insurgente'', Tris debe escapar con Cuatro e ir más allá del muro que rodea Chicago. Por primera vez dejarán la única ciudad y familia que conocen. Una vez fuera, todo aquello que presuponían como cierto, pierde cualquier sentido tras la revelación de nuevas verdades. Tris y Cuatro deben decidir rápidamente en quién confiar mientras se inicia una guerra despiadada que amenaza a toda la humanidad. Para sobrevivir, Tris se verá forzada a tomar decisiones imposibles sobre el coraje, la lealtad, el sacrificio y el amor. Secuela de "Insurgente" (2015) y punto final a la saga iniciada por "Divergente" (2014). Dividida en dos partes, una estrenada en 2016 y otra en 2017.', trailer_url = 'https://www.youtube.com/watch?v=ESJBomF-9Y8' WHERE id_api = 'tt3410834';

UPDATE Contenido SET id_tmdb = 364689, descripcion = 'Ferdinand es un novillo muy tranquilo que prefiere sentarse bajo un árbol a oler las flores que saltar, resoplar y embestirse con otros toros. A medida que va creciendo y haciéndose fuerte, su temperamento no cambia y sigue siendo un toro manso. Un día, unos hombres vienen buscando al toro más grande, rápido y bravo... y Ferdinand es elegido equivocadamente para las corridas de toros de Madrid.', trailer_url = 'https://www.youtube.com/watch?v=KRTT0wIxqoA' WHERE id_api = 'tt3411444';

UPDATE Contenido SET id_tmdb = 60863, descripcion = 'Un hecho fortuito desencadena el amor de Shouyou Hinata por el voleibol. Su club no tenía ningún miembro, pero de algún modo perseveró y finalmente realizó su primer y último partido regular de la escuela secundaria, donde fue aniquilado por Tobio Kageyama, un jugador superestrella conocido como "Rey de la Corte." ¡Jurando venganza, Hinata ingresa en el club de voleibol Karasuno, de secundaria alta, solo para volver a encontrarse cara a cara con su odiado rival, Kageyama!', trailer_url = 'https://www.youtube.com/watch?v=KhZG9Uw7PxM' WHERE id_api = 'tt3398540';

UPDATE Contenido SET id_tmdb = 258230, descripcion = 'Connor es un joven de 12 años que, tras la separación de sus padres, se convierte en el hombre de la casa y el encargado de llevar las riendas del hogar. Con su joven madre enferma de cáncer, el pequeño intentará superar todos sus miedos y fobias con la ayuda de un monstruo. Fantasía, cuentos de hadas e historias imaginarias del pequeño se verán las caras no sólo con la realidad, sino con su fría y calculadora abuela... Con este nuevo trabajo J.A. Bayona cerrará una trilogía sobre las relaciones madre-hijo, que inició con "El orfanato" y continuó con "Lo imposible".', trailer_url = 'https://www.youtube.com/watch?v=1-fubC9JN50' WHERE id_api = 'tt3416532';

UPDATE Contenido SET id_tmdb = 278154, descripcion = 'En la nueva historia veremos a Scrat y su mítica bellota en el espacio, donde accidentalmente desencadenará una serie de acontecimientos que amenazarán la Edad de Hielo. Para salvarse, Sid, Manny, Diego y el resto de la manada deberán salir de su hogar y embarcarse en una aventura llena de comedia y aventuras, viajando por tierras exóticas donde se encontrarán con nuevos y peculiares personajes.', trailer_url = 'https://www.youtube.com/watch?v=Ohq6NmKMja8' WHERE id_api = 'tt3416828';

