UPDATE Contenido SET id_tmdb = 281338, descripcion = 'César y sus monos son forzados a encarar un conflicto mortal contra un ejército de humanos liderado por un brutal coronel. Después de sufrir pérdidas enormes, César lucha con sus instintos más oscuros en una búsqueda por vengar a su especie. Cuando finalmente se encuentren, Cesar y el Coronel protagonizarán una batalla que pondrá en juego el futuro de ambas especies y el del mismo planeta. Tercera película de la nueva saga de El Planeta de los Simios.', trailer_url = 'https://www.youtube.com/watch?v=3d3rAJ8R0Fg' WHERE id_api = 'tt3450958';

