UPDATE Contenido SET id_tmdb = 271110, descripcion = 'Continúa la historia de “Avengers: Age of Ultron”, con Steve Rogers liderando un nuevo equipo de Vengadores en su esfuerzo por proteger a la humanidad. Tras otro incidente internacional relacionado con los Vengadores que ocasiona daños colaterales, la presión política fuerza a crear un sistema de registro y un cuerpo gubernamental para determinar cuándo se requiere los servicios del equipo. El nuevo status quo divide a los Vengadores mientras intentan salvar al mundo de un nuevo y perverso villano.', trailer_url = 'https://www.youtube.com/watch?v=6aWYmFCRsEI' WHERE id_api = 'tt3498820';

UPDATE Contenido SET id_tmdb = 284053, descripcion = 'Thor está preso al otro lado del universo sin su poderoso martillo y se enfrenta a una carrera contra el tiempo. Su objetivo es volver a Asgard y parar el Ragnarok porque significaría la destrucción de su planeta natal y el fin de la civilización Asgardiana a manos de una todopoderosa y nueva amenaza, la implacable Hela. Pero, primero deberá sobrevivir a una competición letal de gladiadores que lo enfrentará a su aliado y compañero en los Vengadores, ¡el Increíble Hulk!', trailer_url = 'https://www.youtube.com/watch?v=Cdp7Xo0x0Uw' WHERE id_api = 'tt3501632';

UPDATE Contenido SET id_tmdb = 420821, descripcion = 'Treinta años después, las estrellas de las series de animación de Disney de los años 1990, Chip y Chop, viven en Los Ángeles entre dibujos animados y humanos. Chip lleva una vida rutinaria y hogareña como vendedor de seguros, mientras que Chop se ha hecho la cirugía 3D y se dedica a explotar la nostalgia de convención en convención, desesperado por revivir sus días de gloria. Cuando un antiguo compañero de reparto desaparece misteriosamente, Chip y Chop se ven obligados a recuperar la amistad perdida y a hacer de detectives una vez más como Guardianes Rescatadores para salvar a su amigo.', trailer_url = 'https://www.youtube.com/watch?v=W9QY3lKw2p4' WHERE id_api = 'tt3513500';

UPDATE Contenido SET id_tmdb = 292011, descripcion = 'Richard Jewell era un guardia de seguridad en los Juegos Olímpicos de Atlanta 1996, el cual descubrió una mochila con explosivos en su interior y evitó un número mayor de víctimas al ayudar a evacuar el área poco antes de que se produjera el estallido. En un principio se le presentó como un héroe cuya intervención salvó vidas, pero posteriormente Jewell pasó a ser considerado el sospechoso número uno y fue investigado como presunto culpable.', trailer_url = 'https://www.youtube.com/watch?v=GZSrgY7r5Sc' WHERE id_api = 'tt3513548';

UPDATE Contenido SET id_tmdb = 277834, descripcion = 'Una gran aventura acerca de una enérgica adolescente que se embarca en una misión audaz para salvar a su pueblo de una antigua y misteriosa amenaza, en un viaje de autodescubrimiento. La acompañará el arrogante semidiós Maui, quien la guiará en su travesía por el océano en un viaje lleno de acción, plagado de temibles criaturas e imposibles desafíos para restaurar el orden perdido.', trailer_url = 'https://www.youtube.com/watch?v=tmpTGztGJ8E' WHERE id_api = 'tt3521164';

UPDATE Contenido SET id_tmdb = 60866, descripcion = 'Gira en torno a una estudiante de medicina que se convierte en zombi y coge un trabajo de médico forense para tener acceso a los cerebros que debe comer para mantener su humanidad. Pero con cada cerebro que consume, hereda recuerdos del cadáver. De ahí que, con la ayuda de su jefe médico forense y un detective de policía, empiece a resolver casos de homicidio con el fin de callar las voces inquietantes de su cabeza.', trailer_url = 'https://www.youtube.com/watch?v=UQhzQDW4L84' WHERE id_api = 'tt3501584';

