UPDATE Contenido SET id_tmdb = 61986, descripcion = 'La familia Rayburn es un pilar de su comunidad en los Cayos de la Florida. Pero cuando el hijo mayor, la oveja negra, vuelve a casa para celebrar el 45º aniversario del hotel de sus padres, amenaza con descubrir los secretos de los Rayburn y su vergonzoso pasado, llevando a los hermanos al límite de la lealtad familiar.', trailer_url = 'https://www.youtube.com/watch?v=7f-FpB_GoGE' WHERE id_api = 'tt3520702';

UPDATE Contenido SET id_tmdb = 60585, descripcion = 'Bosch Es una  serie de televisión americana de género policiaco producida por Amazon y protagoniza Titus Welliver, como el detective de Policía de Los Angeles, Harry Bosch. La serie fue desarrollada para Amazon por Eric Overmyer y se está inspirada por tres de las novelas de Michael Connelly: Ciudad de Huesos, Echo Park y La rubia de hormigón.', trailer_url = 'https://www.youtube.com/watch?v=vuVAP_4TQEY' WHERE id_api = 'tt3502248';

UPDATE Contenido SET id_tmdb = 278924, descripcion = 'Cuando Arthur Bishop (Jason Statham) creía que ya había dejado atrás su pasado criminal, se encuentra de nuevo con él al ser secuestrada la mujer de su vida por uno de sus mayores enemigos. Se ve así obligado a viajar por el mundo para ejecutar tres asesinatos imposibles que deben parecer accidentes.', trailer_url = 'https://www.youtube.com/watch?v=H-UAuf1ik-o' WHERE id_api = 'tt3522806';

UPDATE Contenido SET id_tmdb = 328387, descripcion = 'Vee Delmonico (Emma Roberts) es una joven y tímida estudiante de secundaria que decide apuntarse a Nerve, un provocativo juego online de ''verdad o acción'' en el que la audiencia observa todo, vota y además comenta. Al principio logra mucho éxito y disfruta la situación, sobre todo gracias a los premios que ofrece el juego. Así, empieza a competir junto a un misterioso extraño (Dave Franco), que será su compañero de equipo. Pero, a medida que sube niveles, Nerve evoluciona y Vee se verá envuelta en un juego cada vez mas peligroso...', trailer_url = 'https://www.youtube.com/watch?v=z6khd6myjT0' WHERE id_api = 'tt3531824';

UPDATE Contenido SET id_tmdb = 337170, descripcion = 'Basada en la vida real de Barry Seal, un expiloto que se convirtió en un importante narcotraficante en el cartel de Medellín y que acabó siendo reclutado por la CIA y el departamento de inteligencia de la DEA.', trailer_url = 'https://www.youtube.com/watch?v=q7XZk91GpuE' WHERE id_api = 'tt3532216';

UPDATE Contenido SET id_tmdb = 301507, descripcion = 'Dos de las mayores estrellas de la Major League Hockey están unidas por la ambición, la rivalidad y una atracción magnética que ninguna de las dos comprende del todo. Lo que comienza como una aventura secreta entre dos novatos se convierte en un viaje de años de amor, negación y autodescubrimiento. Durante los siguientes ocho años, mientras buscan la gloria sobre el hielo, luchan por comprender sus sentimientos mutuos. Divididos entre el deporte que les apasiona y el amor que no pueden ignorar, deben decidir si hay espacio en su mundo ferozmente competitivo para algo tan frágil —y poderoso— como el amor verdadero.', trailer_url = 'https://www.youtube.com/watch?v=ADi1iextoUM' WHERE id_api = 'tt35495073';

UPDATE Contenido SET id_tmdb = 279641, descripcion = 'Adaptación de las memorias de Kim Barker, ''The Taliban Shuffle'', que básicamente cuenta sus primeros años como periodista en Afganistán y Pakistán tras su llegada en 2002, sus experiencias y el desafío enorme que supone ser mujer en tiempos de guerra en esas zonas.', trailer_url = 'https://www.youtube.com/watch?v=dxAcIWDi8ps' WHERE id_api = 'tt3553442';

UPDATE Contenido SET id_tmdb = 334533, descripcion = 'Ben es un padre que ha pasado diez años viviendo en los remotos bosques situados al noroeste del Pacífico criando a sus seis hijos. Sin embargo un día la familia debe abandonar su modo de vida en la naturaleza y volver a la civilización. Asimilar su nueva situación y adaptarse de nuevo a la sociedad moderna no les va a resultar nada sencillo.', trailer_url = 'https://www.youtube.com/watch?v=w5jeBvjcJe4' WHERE id_api = 'tt3553976';

UPDATE Contenido SET id_tmdb = 61662, descripcion = 'Schitt''s Creek es una comedia creada por el actor y comico Eugene Levy (American Pie Doce fuera de casa) que sigue los avatares de los Rose Una familia de ricos que pierde todo su dinero después de que su gerente de negocios sea condenado por fraude y ellos despojados de sus posesiones para pagar las deudas Lo único que les ha dejado el gobierno es una localidad llamada Schitt''s Creek que el padre de familia Johnny Rose compro como una broma para su hijo No les queda otra que alojarse alli para empezar de cero rodeados de lo que consideran gente maleducada grosera y analfabeta presionados por un alcalde de lo mas extravagante Mientras intentan adaptarse a un entorno hostil y desconocido pronto se dan cuenta de que los verdaderos bichos raros del pueblo podrían ser ellos.', trailer_url = 'https://www.youtube.com/watch?v=W0uWS6CnC2o' WHERE id_api = 'tt3526078';

UPDATE Contenido SET id_tmdb = 379686, descripcion = 'Secuela de la cinta original de 1996, Space Jam, protagonizada por Michael Jordan. En esta segunda parte, la super estrella de la NBA es LeBron James, quien queda atrapado junto a su hijo Dom en un extraño lugar, un espacio digital de una fuerza todopoderosa y malvada conocida como A.I. Para volver a casa y poner a salvo a su hijo, el jugador de baloncesto deberá unir fuerzas con Bugs Bunny, Lola Bunny y el resto de personajes de los Looney Tunes para enfrentarse en un partido de baloncesto a los campeones digitalizados por inteligencia artificial.', trailer_url = 'https://www.youtube.com/watch?v=z2RHxm2CbGs' WHERE id_api = 'tt3554046';

UPDATE Contenido SET id_tmdb = 298312, descripcion = 'Una madre decide atender a las peticiones de sus dos hijos y los lleva a la remota granja de sus abuelos, en Pensilvania. Los niños, entusiasmados, empezarán a realizar una búsqueda intensiva por la casa. Sus abuelos, que en principio, parecen adorables, les establecen ciertas reglas que no pueden romper. Los niños, ingenuos, piensan que no pasará nada si se las saltan, hasta que descubran que la pareja está inmersa en algo realmente espeluznante y que en ocasiones, a veces es mejor no saber la verdad.', trailer_url = 'https://www.youtube.com/watch?v=2A5Dp4r1PuU' WHERE id_api = 'tt3567288';

