UPDATE Contenido SET id_tmdb = 260514, descripcion = 'Sorprendido por una nueva generación de corredores ultrarrápidos, el legendario Rayo McQueen queda relegado repentinamente del deporte que tanto ama. Para retomar su carrera, va a necesitar la ayuda de una joven mecánica de carreras, Cruz Ramírez, que tiene su propio plan para ganar, además de la inspiración del fallecido Fabuloso Hudson Hornet y un par de giros inesperados. ¡Y para probar que el nº95 no está ni mucho menos acabado, el campeón tendrá que poner a prueba su valía en el gran circuito de la Copa Piston!', trailer_url = 'https://www.youtube.com/watch?v=MKeUsy-d3_k' WHERE id_api = 'tt3606752';

UPDATE Contenido SET id_tmdb = 260513, descripcion = 'Helen tiene que liderar una campaña para que los superhéroes regresen, mientras Bob vive su vida ''normal'' con Violet, Dash y el bebé Jack-Jack —cuyos superpoderes descubriremos—. Su misión se va a pique cuando aparece un nuevo villano con un brillante plan que lo amenaza todo. Pero los Parr no se amedrentarán y menos teniendo a Frozone de su parte.', trailer_url = 'https://www.youtube.com/watch?v=92iqVqYGpxo' WHERE id_api = 'tt3606756';

UPDATE Contenido SET id_tmdb = 100088, descripcion = 'Año 2023, veinte años después del comienzo de una plaga mundial que infectó a población con un hongo mutado transformando a las personas en unas criaturas caníbales, el contrabandista Joel tiene la misión de escoltar a la adolescente Ellie por un mundo postapocalíptico en el nada va a ser fácil para los viajeros.  Joel todavía vive atormentado por el recuerdo de su única hija. Ellie es portadora de algo que podría cambiar el destino de la humanidad ¿Conseguirán sobrevivir los dos?', trailer_url = 'https://www.youtube.com/watch?v=jKDWKl7iTUY' WHERE id_api = 'tt3581920';

UPDATE Contenido SET id_tmdb = 61418, descripcion = 'Una joven devota descubre que ha sido inseminada artificialmente por error. Cuando Jane Villanueva era niña, su abuela le dejó claras dos cosas: las telenovelas son la mejor forma de entretenimiento y perder la virginidad es lo peor que le puede pasar a una mujer. A sus 23 años y en el corazón de Miami, Jane es una chica responsable y piadosa, ilusionada por labrarse un futuro con un novio perfecto con el que, por supuesto, no tiene relación. Pero todos sus planes se van al traste cuando es inseminada accidentalmente por error de un ginecólogo que atraviesa una mala racha. Paradojas del destino, Rafael, antiguo enamorado de Jane, ahora casado con una mujer retorcida y dueña del hotel donde ella trabaja. Jane se ve entonces obligada a cambiar radicalmente de perspectiva: ahora su vida es la mejor telenovela y ella es la protagonista.', trailer_url = 'https://www.youtube.com/watch?v=3JPNVHRNCrY' WHERE id_api = 'tt3566726';

