UPDATE Contenido SET id_tmdb = 286565, descripcion = 'Quentin Jacobsen ha pasado toda su vida amando en secreto a la aventurera Margo Roth Spiegelman. Así que cuando ella rompe una ventana y entra en su vida disfrazada de ninja y reclutándole para una misión de venganza, él le sigue sin dudar. Después de que la noche que han pasado juntos termine y el día comience, Q llega al colegio para descubrir que Margo, que siempre ha sido un enigma, ahora es un completo misterio. Pero Q descubre que hay pistas y que son para él. Andando por un camino sin conexión, cuanto más cerca está, menos ve de la chica que él creía que conocía.', trailer_url = 'https://www.youtube.com/watch?v=F1dDr4b36Mo' WHERE id_api = 'tt3622592';

