UPDATE Contenido SET id_tmdb = 282984, descripcion = 'Abe Lucas, un profesor de filosofía en plena crisis existencial, le encuentra de nuevo sentido a la vida al enamorarse de una de sus alumnas. Al poco de llegar a la universidad de una pequeña ciudad, se relaciona con dos mujeres: Rita Richards, una solitaria profesora que busca que la rescate de su infeliz matrimonio; y Jill Pollard, su mejor estudiante y muy pronto su amiga más cercana. Jill está enamorada de su novio, pero encuentra tan irresistible la personalidad atormentada de Abe que, incluso cuando el profesor muestra claros síntomas de desequilibrio mental, su fascinación por él no hace más que crecer.', trailer_url = 'https://www.youtube.com/watch?v=5Wf-ouBdYY8' WHERE id_api = 'tt3715320';

