UPDATE Contenido SET id_tmdb = 308531, descripcion = 'Michelangelo, Donatello, Leonardo y Raphael regresan junto con April O’Neil, Vern Fenwick y un nuevo vigilante enmascarado, Casey Jones, para combatir a unos villanos aún más malignos y poderosos. El súper villano Shredder escapa de prisión y une sus fuerzas con el científico loco Baxter Stockman y sus dos secuaces, Bebob y Rocksteady, para llevar a cabo un diabólico plan para conquistar el mundo. Mientras las Tortugas se preparan para enfrentarse a Shredder y su banda, tendrán que luchar también con un nuevo enemigo, incluso más poderoso, y también con intenciones malignas: El General Krang.', trailer_url = 'https://www.youtube.com/watch?v=6KW3njArGv4' WHERE id_api = 'tt3949660';

