UPDATE Contenido SET id_tmdb = 63174, descripcion = 'La serie se centrará en Lucifer (Tom Ellis) quien, aburrido e infeliz como el Señor del Infierno, dimite de su trono y abandona su reino para trasladarse a la ciudad de Los Angeles y abrir un lujoso piano-bar llamado Lux. Una vez allí ayudará a la policía a castigar a los más peligrosos criminales de la ciudad.', trailer_url = 'https://www.youtube.com/watch?v=X4bF_quwNtw' WHERE id_api = 'tt4052886';

UPDATE Contenido SET id_tmdb = 537915, descripcion = 'La joven Tessa Young cursa su primer año en la universidad. Acostumbrada a una vida estable y ordenada, su mundo cambia cuando conoce a Hardin Scott, un misterioso joven de oscuro pasado. Desde el primer momento se odian, porque pertenecen a dos mundos distintos y son completamente opuestos. Sin embargo, estos dos polos opuestos pronto se unirán y nada volverá a ser igual. Tessa y Hardin deberán enfrentarse a difíciles pruebas para estar juntos. La inocencia, el despertar a la vida, el descubrimiento sexual y las huellas de un amor tan poderoso como la fuerza del destino.', trailer_url = 'https://www.youtube.com/watch?v=wh6x78lbE2k' WHERE id_api = 'tt4126476';

UPDATE Contenido SET id_tmdb = 342521, descripcion = 'Key & Peele, el popular dúo cómico, interpretan a Clarence y Rell, dos primos que viven en la ciudad y que están muy lejos de ser unos rufianes. Cuando el querido gato de Rell, Keanu, es raptado, no tendrán más remedio que hacerse pasar por unos despiadados asesinos, con el objetivo de infiltrarse en una banda callejera y recuperar a su felino. Pero el increíblemente adorable gatito se vuelve tan codiciado que tendrán que luchar por su custodia, creando una guerra de pandillas, obligando a nuestros dos héroes a tomarse la justicia por su mano.', trailer_url = 'https://www.youtube.com/watch?v=K9zy27apgI8' WHERE id_api = 'tt4139124';

