UPDATE Contenido SET id_tmdb = 62715, descripcion = 'Tras derrotar a Majin Buu, Goku y sus amigos tienen una vida de lo más pacífica: Goku ahora se dedica a la agricultura, aunque siempre encuentra un rato para seguir entrenando; Mister Satán se ha hecho famoso como gran salvador de la Humanidad; Trunks y Goten hacen cosas de niños; Gohan y Videl se han casado; y Vegeta pasa unas vacaciones en familia. Pero algo que cambiará su destino está a punto de ocurrir. Mientras se reúnen para celebrar el cumpleaños de Bulma, el dios de la Destrucción ha despertado y se está dedicando a lo que mejor se le da: aniquilar planetas… y acaba de descubrir la Tierra. Una vez más, Goku necesitará la ayuda de sus amigos para convertirse en el legendario Super Saiyan y poder así derrotar al Dios de la Destrucción.', trailer_url = 'https://www.youtube.com/watch?v=pyaojNIYgcg' WHERE id_api = 'tt4644488';

