UPDATE Contenido SET id_tmdb = 480414, descripcion = 'La Llorona es una aparición tenebrosa, atrapada entre el Cielo y el Infierno, con un destino terrible sellado por su propia mano. La mera mención de su nombre ha causado terror en todo el mundo durante generaciones. En vida, ahogó a sus hijos en una rabia de celos, arrojándose en el río tras ver como mató a sus hijos violentamente. Ahora sus lágrimas son eternas, letales, y aquellos que escuchan su llamada de muerte en la noche están condenados. Se arrastra en las sombras y ataca a los niños, desesperada por reemplazar a los suyos. A medida que los siglos han pasado, su deseo se ha vuelto más voraz y sus métodos más terroríficos.', trailer_url = 'https://www.youtube.com/watch?v=JoTbiH3Wppo' WHERE id_api = 'tt4913966';

UPDATE Contenido SET id_tmdb = 522212, descripcion = 'Cuenta la historia real del joven abogado Bryan Stevenson y de su histórica batalla por la justicia. Después de licenciarse en Harvard, Bryan recibe ofertas de trabajo muy lucrativas. Pero él prefiere poner rumbo a Alabama para defender a personas que han sido condenadas erróneamente o que carecían de recursos para tener una representación legal adecuada, y lo hace con el apoyo de la activista local Eva Ansley. Uno de sus primeros y más turbulentos casos es el de Walter McMillian, que en 1987 fue sentenciado a la pena muerte por el asesinato de una chica de 18 años, a pesar de que las pruebas demostraban ostensiblemente su inocencia. En los años posteriores, Bryan se ve envuelto en un laberinto de maniobras legales y políticas y de un racismo abierto y descarado mientras lucha por Walter y otros como él, a pesar de tenerlo todo en su contra, incluido el sistema legal.', trailer_url = 'https://www.youtube.com/watch?v=epmO-wYI2bY' WHERE id_api = 'tt4916630';

UPDATE Contenido SET id_tmdb = 573435, descripcion = 'Los policías más famosos del mundo regresan con su icónica mezcla de acción al límite y comedia escandalosa, pero esta vez con un giro inesperado: ¡Los mejores de Miami se dan a la fuga! Cuarta entrega de la saga ''Dos policías rebeldes''.', trailer_url = 'https://www.youtube.com/watch?v=ULlFzofpV6w' WHERE id_api = 'tt4919268';

UPDATE Contenido SET id_tmdb = 393519, descripcion = 'Justine, una joven de 16 años, vive en una familia donde todos son veterinarios y vegetarianos. Es una estudiante brillante y prometedora, pero al ingresar en la facultad de veterinaria descubre un mundo decadente, despiadado y peligrosamente seductor. Durante la primera semana, obsesionada por encajar con sus compañeros de clase, se aleja de los principios que le han inculcado su familia, y come carne cruda por primera vez. Las consecuencias no tardan en llegar, y la joven empezará a desvelar su verdadera naturaleza.', trailer_url = 'https://www.youtube.com/watch?v=iidmSP1GOlc' WHERE id_api = 'tt4954522';

UPDATE Contenido SET id_tmdb = 381288, descripcion = 'A pesar de que Kevin le ha demostrado a su psiquiatra de confianza, la Dra. Fletcher, que posee 23 personalidades diferentes, aún queda una por emerger, decidida a dominar a todas las demás. Obligado a raptar a tres chicas adolescentes encabezadas por la decidida y observadora Casey, Kevin lucha por sobrevivir contra todas sus personalidades y la gente que le rodea, a medida que las paredes de sus compartimentos mentales se derrumban.', trailer_url = 'https://www.youtube.com/watch?v=GTnNVq99qdE' WHERE id_api = 'tt4972582';

