UPDATE Contenido SET id_tmdb = 66573, descripcion = 'Eleanor (Kristen Bell) es una mujer de Phoenix que, tras ser atropellada por un camión que transportaba productos para la disfunción eréctil, despierta para descubrir que ha llegado al más allá. Su mentor, Michael (Ted Danson), le informa de que ahora se encuentra en El Lugar Bueno, “The Good Place”, por su comportamiento adecuado en su vida anterior. Pero... la han confundido con otra persona: ella era puro egoísmo en vida. Eleanor se plantea decir la verdad, hasta que descubre lo que le depara El Lugar Malo, el sitio a donde debería haber ido en realidad, así que decide ganarse un puesto en El Lugar Bueno tratando de aprender a ser buena persona, cosa muy complicada siendo como es.', trailer_url = 'https://www.youtube.com/watch?v=9QxRbzFk3zk' WHERE id_api = 'tt4955642';

