UPDATE Contenido SET id_tmdb = 629176, descripcion = 'Sam Cleary (Javon "Wanna" Walton), un joven de 13 años, sospecha que su misterioso y solitario vecino, el Sr. Smith (Sylvester Stallone), es en realidad un personaje legendario que se esconde a plena vista. Hace 20 años, el vigilante superpoderoso de Granite City, Samaritan, fue declarado muerto tras una batalla en un almacén con su rival, Némesis. La gente cree que Samaritan falleció en el incendio, pero algunos ciudadanos como Sam tienen la esperanza de que siga vivo. Con la delincuencia en aumento y la ciudad al borde del caos, Sam se propone sacar a su vecino de su escondite para salvar la ciudad de la ruina.', trailer_url = 'https://www.youtube.com/watch?v=36X35b2LEu0' WHERE id_api = 'tt5500218';

UPDATE Contenido SET id_tmdb = 68595, descripcion = 'La segunda parte del mítico documental "Planeta Tierra", nos sumerge en increíbles paisajes y nos permite experimentar el mundo a través de la perspectiva de los animales. Viajando a través de junglas, desiertos, montañas, islas, dehesas y ciudades, esta serie documental explora las características de los habitantes más icónicos de la tierra y sus extraordinarios modos de supervivencia. La nueva tecnología nos acerca a detalles sin precedentes en la vida de los animales.

Hace una década, "Planeta Tierra" redefinió la forma de hacer documentales de naturaleza, regalándonos el retrato más completo de la vida en la tierra. En esta ocasión, los revolucionarios equipos y profesionales de BBC Earth han tratado de hacernos experimentar el mundo desde el punto de vista de los propios animales. A través de junglas, desiertos, montañas, islas, llanuras y ciudades, "Planet Eath II" explora de una manera única los hábitats naturales más icónicos del mundo.', trailer_url = 'https://www.youtube.com/watch?v=kAphgHhlteM' WHERE id_api = 'tt5491994';

