UPDATE Contenido SET id_tmdb = 67070, descripcion = 'La protagonista, Fleabag, es una mujer de clase media que tiene una  situación familiar complicada y un trabajo con el que no puede mantener  su estilo de vida. Ella es propietaria de un café con el que apenas gana  dinero y su novio es un hombre que llena su vacío existencial con  encuentros sexuales sin sentido con todo tipo de mujeres, cada cual peor  de la anterior. Y eso es solo una pequeña parte de su vida y  situaciones cotidianas con las que Fleabag debe lidiar.  Fleabag  es un ejemplo de una vida que ha ido mal y debe adaptarse a nuevas  situaciones, cosa que consigue hacer gracias a su personalidad.', trailer_url = 'https://www.youtube.com/watch?v=L3iqdpYoZNU' WHERE id_api = 'tt5687612';

UPDATE Contenido SET id_tmdb = 536869, descripcion = 'Durante una sola noche al año, una tribu de gatos llamada Jellicles se reúne en el basurero para conocer ''la elección de Jellicle'': cuál de ellos ascenderá a la capa Heaviside y volverá a una nueva vida. Allí conoceremos a la gata blanca Victoria y a Old Deuteronomy, quien decide qué felino será el elegido. También al misterioso Mr. Mistoffelees, al rockero Rum Tum Tugger o al refinado Bustopher Jones, junto a Grizabella, Macavity, Jennyanydots, Gus y Bombalurina. Adaptación a la gran pantalla del musical de Andrew Lloyd Weber basado, a su vez, en la recopilación de poemas titulada ''Old Possum''s Book of Practical Cats (El libro de los gatos habilidosos del viejo Possum)'', de T.S. Eliot.', trailer_url = 'https://www.youtube.com/watch?v=rWJKFt21xnQ' WHERE id_api = 'tt5697572';

