UPDATE Contenido SET id_tmdb = 738652, descripcion = 'Huyendo de un asesino letal, un astuto estafador inventa un plan para esconderse dentro de una comisaría de policía de un pequeño pueblo. Sin embargo, cuando el asesino a sueldo aparece en la comisaría, un policía novato desprevenido se encuentra atrapada en la mira.', trailer_url = 'https://www.youtube.com/watch?v=P2x0Yvw09v4' WHERE id_api = 'tt5748448';

UPDATE Contenido SET id_tmdb = 398181, descripcion = 'Joe, ex marine y antiguo veterano de guerra, es un tipo solitario que dedica su tiempo a intentar salvar a mujeres que son explotadas sexualmente. No se permite ni amigos ni amantes y se gana la vida rescatando jóvenes de las garras de los tratantes de blancas. Un día recibe la llamada de un político porque su hija ha sido secuestrada.', trailer_url = 'https://www.youtube.com/watch?v=fQyDaGWQ43w' WHERE id_api = 'tt5742374';

UPDATE Contenido SET id_tmdb = 717930, descripcion = 'Tras sabotear un reactor nuclear iraní, el agente de la CIA Tom Harris (Gerard Butler) descubre que su identidad ha sido revelada a los medios después de que un informante expusiera la implicación de la CIA en la destrucción del reactor. Harris dispone de sólo 30 horas para llegar al aeropuerto de Kandahar (Afganistán) y evitar su muerte y captura. Para conseguirlo, necesitará la ayuda de un traductor afgano llamado Mo (Navid Negahban) que desprecia la violencia y el derramamiento de sangre causado por el conflicto bélico. Perseguidos por peligrosas amenazas, entre las que se encuentra el despiadado asesino Kahil (Ali Fazal), Tom y Mo se verán obligados a unir fuerzas para llegar, de una pieza, a Kandahar.', trailer_url = 'https://www.youtube.com/watch?v=W57zTuI6Wwo' WHERE id_api = 'tt5761544';

