UPDATE Contenido SET id_tmdb = 439079, descripcion = 'Cuando una joven monja se suicida en una abadía de clausura en Rumanía, un sacerdote experto en posesiones demoniacas y una novicia a punto de tomar sus votos, son enviados por el Vaticano para investigar. Juntos descubren el profano secreto de la orden. Arriesgando no solo sus propias vidas sino su fe y hasta sus almas, se enfrentan a una fuerza maléfica en forma de monja demoníaca, en una abadía que se convierte en un campo de batalla de horror entre los vivos y los condenados....', trailer_url = 'https://www.youtube.com/watch?v=UZ_7__0rBAU' WHERE id_api = 'tt5814060';

