UPDATE Contenido SET id_tmdb = 399366, descripcion = 'En 1969, los cuatro hermanos Jack, Billy, Jane y Sam llegan a Marrowbone junto a su madre después de haber escapado de Inglaterra. En la nueva casa intentan empezar una nueva vida lejos de su padre, un hombre violento y con un pasado criminal. Poco después de su llegada, su madre fallece repentinamente y los chicos deciden esconder el asunto para que no los separen. Se esconderán en su granja, donde serán acechados por una siniestra presencia.', trailer_url = 'https://www.youtube.com/watch?v=U12evZapMWQ' WHERE id_api = 'tt5886440';

