UPDATE Contenido SET id_tmdb = 39852, descripcion = 'Una madre, víctima de un inexplicable ataque de rabia, comete un sorprendente acto de violencia y horror en el que, para mayor desconcierto, no tiene ni idea de por qué. El investigador se encuentra obsesionado con descubrir el motivo oculta de la mujer. Juntos viajarán por un viaje desgarrador hacia las profundidades de su psique y los violentos secretos escondidos en su pasado.', trailer_url = NULL WHERE id_api = 'tt6048596';

UPDATE Contenido SET id_tmdb = 442249, descripcion = 'Para mantener durante el resto del año la tasa de criminalidad por debajo del 1%, los Nuevos Padres Fundadores de América ponen a prueba una teoría sociológica que da rienda suelta a todo tipo de agresiones durante una noche en una comunidad aislada. Pero cuando la violencia de los opresores se encuentra con la ira de los marginados, el vandalismo explota más allá de esas fronteras “experimentales” para extenderse por todo el país. Detrás de cada tradición hay una revolución. Descubre cómo toda una nación entera abrazó una brutal celebración anual: 12 horas de impunidad criminal. Bienvenidos a un movimiento que comenzó como un simple experimento.', trailer_url = 'https://www.youtube.com/watch?v=hxksq2veLas' WHERE id_api = 'tt6133466';

