UPDATE Contenido SET id_tmdb = 476299, descripcion = 'a nueva película de Pascal Laugier (“Martyrs”), uno de los directores de cine de terror contemporáneo más aclamados de su generación. Un film escalofriante, con un universo propio que recuerda al Rob Zombie más inspirado. Pauline y sus dos hijas adolescentes, Beth y Vera, heredan una casa. La primera noche en su nuevo hogar sufren el ataque salvaje de un grupo de intrusos. Pauline y las chicas deberán luchar para salvar sus vidas. 16 años después, Beth es una novelista de éxito, mientras que su hermana Vera, víctima de desequilibrios mentales, vive todavía en aquella casa con su madre. Cuando las tres vuelven a reunirse allí, una ola de acontecimientos terroríficos se desata.', trailer_url = 'https://www.youtube.com/watch?v=ni_DF8waeDE' WHERE id_api = 'tt6195094';

