UPDATE Contenido SET id_tmdb = 446354, descripcion = 'En junio de 1971, los principales periódicos de EE.UU., entre los que se encontraban ''The New York Times'' y ''The Washington Post'', tomaron una valiente posición en favor de la libertad de expresión, informando sobre los documentos del Pentágono y el encubrimiento masivo de secretos por parte del gobierno, que había durado cuatro décadas y cuatro presidencias estadounidenses. En ese momento, Katherine Graham, primera mujer editora del Post, y el director Ben Bradlee intentaban relanzar un periódico en decadencia. Juntos decidieron tomar la audaz decisión de apoyar al ''The New York Times'' y luchar contra el intento de la Administración Nixon de restringir la primera enmienda. Historia basada en los documentos del Post que recogían información clasificada sobre la Guerra de Vietnam.', trailer_url = 'https://www.youtube.com/watch?v=CQEG_MVeg_Y' WHERE id_api = 'tt6294822';

