UPDATE Contenido SET id_tmdb = 496328, descripcion = 'Pocas vidas en nuestros tiempos son tan dramáticas y enigmáticas como la saga de Sanjay Dutt. Procedente de una familia de leyendas del cine, él mismo se convirtió en una estrella de cine, y luego vio alturas vertiginosas y profundidades más oscuras: adulación de fanáticos acérrimos, batallas interminables con diversas adicciones, roces con el inframundo, penas de prisión, pérdida de seres queridos, y inquietante especulación de que podría o no ser un terrorista. Sanju es a su vez una exploración hilarante y desgarradora de la batalla de un hombre contra su propio ser salvaje y las formidables fuerzas externas que intentan aplastarlo. Representa el viaje de un hombre a través de todo lo que la vida puede arrojar sobre él. Algunas historias verdaderas te dejan pensando "¿esto realmente sucedió?" Esta es una historia increíble que sucede que es verdad.', trailer_url = 'https://www.youtube.com/watch?v=1J76wN0TPI4' WHERE id_api = 'tt6452574';

