UPDATE Contenido SET id_tmdb = 581032, descripcion = 'Cinco años después del fin de la Guerra Civil estadounidense, el capitán Jefferson Kyle Kidd, veterano no de una, sino de tres guerras, va de ciudad en ciudad narrando noticias, hablando de presidentes y reinas, de luchas gloriosas, devastadoras catástrofes y apasionantes aventuras que tienen lugar en cualquier rincón del mundo. Un día, en las llanuras de Texas, el capitán conoce a Johanna, una niña de diez años que fue secuestrada seis años atrás por la tribu Kiowa, y que durante este tiempo fue educada como uno de ellos. Johanna, en contra de su voluntad, debe irse a vivir a casa de sus tíos, un lugar hostil y desconocido para ella. El capitán Kidd acepta entregar a la niña a sus tutores legales. En el viaje, ambos recorrerán cientos de kilómetros a través de una inhóspita naturaleza, y deberán enfrentarse a enormes dificultades, humanas y naturales, en búsqueda de un lugar al que puedan llamar “hogar”.', trailer_url = 'https://www.youtube.com/watch?v=zTZDb_iKooI' WHERE id_api = 'tt6878306';

