UPDATE Contenido SET id_tmdb = 79744, descripcion = 'Comenzar de nuevo no es fácil, especialmente para el chico de una ciudad pequeña John Nolan que, después de un incidente que cambia su vida, está persiguiendo su sueño de ser un oficial de policía de Los Ángeles. Como el novato más viejo de la fuerza, se ha encontrado con el escepticismo de algunos de los superiores que lo ven como una crisis ambulante.', trailer_url = 'https://www.youtube.com/watch?v=ZGI0VwJrphs' WHERE id_api = 'tt7587890';

