UPDATE Contenido SET id_tmdb = 519010, descripcion = 'Salvador Mallo, un director de cine en su ocaso, vive varios reencuentros. Algunos de ellos físicos, otros recordados: su infancia en los años 60; el primer deseo, su primer amor adulto ya en el Madrid de los 80; la escritura como única terapia para olvidar lo inolvidable; el temprano descubrimiento del cine y el inconmensurable vacío ante la imposibilidad de seguir rodando; la creación, la dificultad de separarla de la propia vida, las pasiones que le dan sentido y esperanza. En la recuperación de su pasado, Salvador encuentra la necesidad urgente de narrarlo, y en esa necesidad encuentra también su salvación.', trailer_url = 'https://www.youtube.com/watch?v=uJu7FAIdeyQ' WHERE id_api = 'tt8291806';

