UPDATE Contenido SET id_tmdb = 1580, descripcion = 'A casa de dos estudiantes van llegando los invitados a una especie de fiesta de fin de curso. El invitado que más temen es su tutor y profesor, un astuto criminólogo que sostiene que el crimen perfecto no existe, aunque ellos se han propuesto demostrar lo contrario. En efecto, con su llegada crece cada vez más la tensión y el nerviosismo de los jóvenes. Y no es para menos, porque tienen un cadáver encerrado en el arcón que sirve de mesa para la cena. Cuando, al final de la fiesta, profesor y alumnos se quedan solos, los errores y contradicciones en que éstos incurren son tales que el profesor empieza a comprender que han asesinado al joven invitado que han estado esperando en vano toda la noche.', trailer_url = 'https://www.youtube.com/watch?v=mTmEraaEY20' WHERE id_api = 'tt0040746';

