UPDATE Contenido SET id_tmdb = 1678, descripcion = 'Las misteriosas destrucciones de barcos en el Pacífico provocan el pánico. Los nativos de una isla afirman que el culpable es una criatura legendaria, Godzilla, un lagarto mutante convertido en un gigantesco monstruo a causa de unas radiaciones atómicas. Godzilla se dispone a atacar las principales ciudades del Japón.', trailer_url = 'https://www.youtube.com/watch?v=IVONRrcn9TI' WHERE id_api = 'tt0047034';

UPDATE Contenido SET id_tmdb = 405, descripcion = 'Cuando Zampanó, un artista ambulante, enviuda, compra a Gelsomina, la hermana de su mujer, sin que la madre de la chica oponga la menor resistencia. Pese al carácter violento y agresivo de Zampanó, la muchacha se siente atraída por el estilo de vida nómada, siempre en la calle (la strada en italiano), sobre todo cuando su dueño la incluye en el espectáculo. Aunque varios de los pintorescos personajes que va conociendo en su deambular le proponen que se una a ellos, Gelsomina se mantendrá fiel a Zampanó hasta las últimas consecuencias.', trailer_url = 'https://www.youtube.com/watch?v=GrE7syApSkA' WHERE id_api = 'tt0047528';

UPDATE Contenido SET id_tmdb = 3112, descripcion = 'Tras realizar un atraco en el que han muerto dos personas, Ben Harper regresa a su casa y esconde el botín confiando el secreto a sus hijos. En la cárcel, antes de ser ejecutado, comparte celda con Harry Powell y en sueños habla del dinero. Tras ser puesto en libertad, Powell, obsesionado por apoderarse del botín, va al pueblo de Harper, enamora a su viuda y se casa con ella.', trailer_url = 'https://www.youtube.com/watch?v=GAxs6tChiKo' WHERE id_api = 'tt0048424';

UPDATE Contenido SET id_tmdb = 826, descripcion = 'Durante la Segunda Guerra Mundial (1939-1945), un grupo de prisioneros británicos son obligados por los japoneses a construir un puente. Los oficiales, capitaneados por su flemático coronel, se opondrán a toda orden que viole la Convención de Ginebra sobre los derechos y las condiciones de vida de los prisioneros de guerra.', trailer_url = 'https://www.youtube.com/watch?v=k17_5rt8dIQ' WHERE id_api = 'tt0050212';

UPDATE Contenido SET id_tmdb = 389, descripcion = 'Tras escuchar todos los testimonios y valorar las pruebas presentadas, un jurado popular compuesto por doce hombres tiene que decidir, por unanimidad, si absuelve o condena a muerte a un joven acusado de haber matado a su padre. Al principio, once están completamente convencidos de su culpabilidad y se inclinan por la condena, pero el que discrepa empieza a plantear dudas razonables que, poco a poco, van resquebrajando la inicial seguridad de los demás.', trailer_url = 'https://www.youtube.com/watch?v=TEN-2uTi2c0' WHERE id_api = 'tt0050083';

UPDATE Contenido SET id_tmdb = 426, descripcion = 'Scottie Fergusson es un detective de la policía de San Francisco que padece de vértigo. Cuando un compañero cae al vacío desde una cornisa mientras persiguen a un delincuente, Scottie decide retirarse. Gavin Elster, un viejo amigo del colegio, lo contrata para que vigile a su esposa Madeleine, una bella mujer que está obsesionada con su pasado.', trailer_url = 'https://www.youtube.com/watch?v=UHhsEYDg8GI' WHERE id_api = 'tt0052357';

UPDATE Contenido SET id_tmdb = 490, descripcion = 'Suecia, mediados del siglo XIV. La Peste Negra asola Europa. Tras diez años de inútiles combates en las Cruzadas, el caballero sueco Antonius Blovk y su leal escudero regresan de Tierra Santa. Blovk es un hombre atormentado y lleno de dudas. En el camino se encuentra con la Muerte que lo reclama. Entonces él le propone jugar una partida de ajedrez, con la esperanza de obtener de Ella respuestas a las grandes cuestiones de la vida: la muerte y la existencia de Dios.', trailer_url = 'https://www.youtube.com/watch?v=vZucwtdSvJ8' WHERE id_api = 'tt0050976';

UPDATE Contenido SET id_tmdb = 147, descripcion = 'A sus doce años, Antoine Doinel se ve obligado no sólo a convivir con los problemas conyugales que sus padres no se atreven a afrontar, sino también a soportar las exigencias de un severo profesor. Un día, asustado porque no ha cumplido un castigo que el maestro le ha impuesto, decide hacer novillos con su amigo René. Inesperadamente, ve a su madre en compañía de otro hombre; la culpa y el miedo lo arrastran a una serie de mentiras y riñas que poco a poco van calando en su ánimo. Deseando dejar atrás todos sus problemas, sueña con conocer el mar y traza con René un plan para escaparse.', trailer_url = 'https://www.youtube.com/watch?v=1L0smVZDBUg' WHERE id_api = 'tt0053198';

UPDATE Contenido SET id_tmdb = 439, descripcion = 'Marcello Rubini es un desencantado periodista romano, en busca de celebridades, que se mueve con insatisfacción por las fiestas nocturnas que celebra la burguesía de la época. Merodea por distintos lugares de Roma, siempre rodeado de todo tipo de personajes, especialmente de la élite de la sociedad italiana. En una de sus salidas se entera de que Sylvia, una célebre diva del mundo del cine, llega a Roma, cree que ésta es una gran oportunidad para conseguir una gran noticia, y, en consecuencia, la perseguirá por las noches por diferentes lugares de la ciudad.', trailer_url = 'https://www.youtube.com/watch?v=YJV6g9bz6tI' WHERE id_api = 'tt0053779';

UPDATE Contenido SET id_tmdb = 301, descripcion = 'El sheriff Chance encarcela por asesinato al hermano de un poderoso terrateniente cuyos hombres intentarán liberarlo. Para impedirlo, Chance cuenta con la colaboración de dos ayudantes: un alcohólico y un viejo tullido, a los que se une un joven y hábil pistolero llamado Colorado. Todos quedarán encerrados en la cárcel de la oficina del sheriff, roedados, incrementándose la tensión en el pueblo a la espera de que llegue la autoridad estatal para llevarse al detenido.', trailer_url = 'https://www.youtube.com/watch?v=VD55fwjvJlw' WHERE id_api = 'tt0053221';

UPDATE Contenido SET id_tmdb = 12230, descripcion = 'Pongo y Perdita, los dalmatas protagonistas, son una feliz pareja canina que vive rodeada de sus cachorros junto a sus amos, Roger y Anita. Pero la felicidad no es eterna y hay una malvada mujer, que vive en una gran mansion, que es la mayor enemiga del perro.Cuando se entera de que los protagonistas tienen nada menos que quince cachorros dalmatas, su sueño de obtener un exclusivo abrigo de piel de los pequeños perros, se convierte en una obsesion. Para conseguirlo contrata a dos ladrones y pone en marcha un malvado plan con el unico fin de secuestrar a los dalmatas.', trailer_url = 'https://www.youtube.com/watch?v=gXgnT50Cr-c' WHERE id_api = 'tt0055254';

UPDATE Contenido SET id_tmdb = 1628, descripcion = 'Desde que se conocieron en 1912, Jules (Oskar Werner) y Jim (Henri Serre) se convirtieron en dos inseparables amigos que un día se enamoran de la misma mujer, Catherine (Jeanne Moreau). Uno de ellos finalmente se casa con ella. Obra capital del cine francés de los sesenta, un hermoso canto al amor y la pasión.', trailer_url = 'https://www.youtube.com/watch?v=X9OzdWczCfQ' WHERE id_api = 'tt0055032';

UPDATE Contenido SET id_tmdb = 947, descripcion = 'Biografía de T.E. Lawrence. El Cairo, 1917. Un conflictivo y enigmático oficial británico es enviado al desierto árabe durante la Gran Guerra en la campaña de ayuda a Arabia contra Turquía. En el desierto, se hace amigo de Sherif Ali Ben El Kharish y pone todo su empeño en la ayuda a los árabes. Éstos creen que Lawrence es otro amante del desierto que ayuda porque cree que Arabia es débil, mientras que sus superiores británicos creen que se ha vuelto loco. Cuando los planes de Lawrence consiguen llevarse a cabo con éxito, comienza a ganarse enemigos.', trailer_url = 'https://www.youtube.com/watch?v=KR1yTI8zFJk' WHERE id_api = 'tt0056172';

