UPDATE Contenido SET id_tmdb = 660, descripcion = 'La organización secreta Spectra se propone infiltrar en la base inglesa de la OTAN a un impostor llamado Angelo, y así lograr apoderarse de un bombardero Vulcan Vindicator equipado con dos bombas nucleares. Cuando logra su propósito, la organización amenaza con destruir una ciudad de EE.UU. o Inglaterra si no le dan 100 millones de libras esterlinas. El agente 007 es el encargado de seguir el caso, y en las Islas Bahamas conoce a Dominó, atractiva amante del misterioso Emilio Largo, que aparenta ser un ocioso millonario pero que en realidad es el número dos de Spectra. Mientras intenta localizar el avión secuestrado, James Bond debe enfrentarse con la cabecilla de los asesinos, Fiona Volpe, y con los secuaces de Emilio Largo.', trailer_url = 'https://www.youtube.com/watch?v=Ha94ny648TQ' WHERE id_api = 'tt0059800';

