UPDATE Contenido SET id_tmdb = 891, descripcion = 'En 1972, dos jóvenes periodistas del diario The Washington Post, Bob Woodward y Carl Bernstein, comienzan a investigar el allanamiento del cuartel general del Partido Demócrata en Washington. Sus descubrimientos desencadenan el llamado ''caso Watergate'', que provocó la dimisión del presidente Richard Nixon.', trailer_url = 'https://www.youtube.com/watch?v=k5y8SW2KyTY' WHERE id_api = 'tt0074119';

UPDATE Contenido SET id_tmdb = 794, descripcion = 'Cuando Kathy Thorn da a luz a un bebé muerto, su esposo Robert le oculta la verdad y sustituye a su hijo por un niño huérfano, ignorando su origen satánico. El horror empieza cuando, en el quinto cumpleaños de Damien, inesperadamente, su niñera se suicida. Un sacerdote que trata de advertir a Robert del peligro que corre, muere en un inesperado accidente. El creciente número de muertes hace que Robert, por fin, se dé cuenta de que el niño que han adoptado es el Anticristo, y que hay que matarlo para impedir que se cumpla una terrible profecía.', trailer_url = 'https://www.youtube.com/watch?v=mgjVPPVtnII' WHERE id_api = 'tt0075005';

UPDATE Contenido SET id_tmdb = 5902, descripcion = 'En septiembre de 1944, alentados por el éxito de la invasión de Normandía, los aliados emprendieron con determinación la operación "Market Garden", un arriesgado plan para poner fin lo antes posible a la guerra, invadiendo Alemania y destruyendo la industria bélica de Hitler. La clave era conquistar varios puentes por los que pasarían las tropas. No obstante, las estrategias en el campo de batalla, combinadas con los errores del servicio de información, la mala suerte y un clima, si cabe, peor, condujeron la operación a un desenlace inesperado.', trailer_url = 'https://www.youtube.com/watch?v=DKDPX8PEiVk' WHERE id_api = 'tt0075784';

UPDATE Contenido SET id_tmdb = 703, descripcion = 'Alvy Singer, un tipo algo neurótico, trabaja como humorista en clubs nocturnos. A sus 40 años, tras romper con Annie, su última novia, reflexiona sobre su vida, rememorando sus amores, sus matrimonios, pero muy en especial su relación con Annie, a la que conoció en una cancha de tenis. Al final, llega a la conclusión de que son sus manías y obsesiones las que siempre acaban arruinando su relación con las mujeres.', trailer_url = 'https://www.youtube.com/watch?v=5SzZ4GWfCJg' WHERE id_api = 'tt0075686';

UPDATE Contenido SET id_tmdb = 923, descripcion = 'La epidemia que hace resucitar a los muertos convertidos en seres ávidos de carne humana se ha extendido, llegando al punto en el que varias ciudades han quedado prácticamente desiertas. Los supervivientes deben refugiarse en zonas militares ya que los zombies no dudan en acabar con sus propios familiares…', trailer_url = 'https://www.youtube.com/watch?v=Y_EviQj5tvA' WHERE id_api = 'tt0077402';

UPDATE Contenido SET id_tmdb = 11778, descripcion = 'Unos amigos de un pequeño pueblo industrial acuden a la llamada del ejército para combatir en la guerra del Vietnam. Michael Cimino divide el film en dos partes: en la primera nos hace partícipes de la humilde vida de los personajes, de sus sueños, juergas y esperanzas; en la segunda nos muestra con dureza los efectos de la guerra y sus penosas consecuencias.', trailer_url = 'https://www.youtube.com/watch?v=g7q1SjVdsNk' WHERE id_api = 'tt0077416';

UPDATE Contenido SET id_tmdb = 11327, descripcion = 'Billy Hayes, un joven estadounidense, es detenido en el aeropuerto de Estambul cuando se dispone a subir a un avión con varios paquetes de hachís. Acusado de uno de los delitos más graves en Turquía, Billy es condenado a cuatro años de cárcel, donde sufrirá terribles penalidades en un sistema penal brutal e inhumano.', trailer_url = 'https://www.youtube.com/watch?v=lhuutAnXBzQ' WHERE id_api = 'tt0077928';

UPDATE Contenido SET id_tmdb = 348, descripcion = 'De regreso a la Tierra, la nave de carga Nostromo interrumpe su viaje y despierta a sus siete tripulantes. El ordenador central, MADRE, ha detectado la misteriosa transmisión de una forma de vida desconocida, procedente de un planeta cercano aparentemente deshabitado. La nave se dirige entonces al extraño planeta para investigar el origen de la comunicación.', trailer_url = 'https://www.youtube.com/watch?v=D3oC17nILkw' WHERE id_api = 'tt0078748';

UPDATE Contenido SET id_tmdb = 11449, descripcion = 'Una familia americana se instala en una mansión sin saber que allí, unos años antes, tuvo lugar una sangrienta tragedia. Sin embargo, pronto detectan la presencia de unos seres maléficos. Horrorizados e impotentes ante tal situación, acaban buscando la ayuda de un peculiar exorcista.', trailer_url = 'https://www.youtube.com/watch?v=f1NHTILX0QE' WHERE id_api = 'tt0078767';

UPDATE Contenido SET id_tmdb = 1398, descripcion = 'En un lugar de Rusia llamado "La Zona", hace algunos años se estrelló un meteorito. A pesar de que el acceso a este lugar está prohibido, los "stalkers" se dedican a guiar a quienes se atreven a aventurarse en este inquietante paraje.', trailer_url = 'https://www.youtube.com/watch?v=JCuwthnCRpg' WHERE id_api = 'tt0079944';

UPDATE Contenido SET id_tmdb = 11474, descripcion = 'Una batalla de proporciones gigantescas va a tener lugar en los bajos fondos de la ciudad de Nueva York. Los ejércitos de la noche, con más de 100.000 integrantes, quintuplican los efectivos de la policía. Se enfrentan a los Warriors, una banda callejera a la que acusan injustamente del asesinato del líder de un grupo rival. Es la historia de un mundo insólito de subculturas, de guerrillas entre bandas nocturnas, desde Coney Island a Manhattan, pasando por el Bronx. Los miembros de los Warriors luchan por sus vidas, intentan sobrevivir en la jungla urbana y aprenden el significado de la lealtad.', trailer_url = 'https://www.youtube.com/watch?v=IAn_PrquNIY' WHERE id_api = 'tt0080120';

UPDATE Contenido SET id_tmdb = 11033, descripcion = 'Kate Miller es una atractiva mujer, insatisfecha sexualmente, a quien asesinan en un ascensor tras salir de su primera sesión con el psiquiatra Robert Elliott. Liz Blake, una joven prostituta, es testigo del crimen y decide intentar detener al culpable con la ayuda de Peter, el hijo de la víctima.', trailer_url = 'https://www.youtube.com/watch?v=aR8tpdj5WL8' WHERE id_api = 'tt0080661';

UPDATE Contenido SET id_tmdb = 525, descripcion = 'Tras pasar años en la cárcel por robo a mano armada, Jake Blues es puesto en libertad por buen comportamiento. Sale de prisión vestido de la misma forma en la que entró: traje y sombrero negro y gafas oscuras. En la puerta le espera su hermano Elwood vestido de idéntica manera. Ahora, el único hogar que conocieron está en peligro. El orfelinato de Santa Elena necesita una gran cantidad de dinero. Los hermanos se ponen manos a la obra.', trailer_url = 'https://www.youtube.com/watch?v=zaCGMiFRJEA' WHERE id_api = 'tt0080455';

UPDATE Contenido SET id_tmdb = 9538, descripcion = '237 personas en todo el mundo son "scanners", personas con unos increíbles poderes mentales. Darryl Revok es el más poderoso de los integrantes del grupo clandestino que ellos constituyen. Es el líder. Todos ellos poseen enormes poderes físicos con los que son capaces de controlar las mentes de los demás. Pueden provocar enormes dosis de dolor y sufrimiento en sus víctimas. El Doctor Paul Ruth descubre un scanner con más poderes que Revok y decidirá utilizarlo para acabar con el grupo.', trailer_url = 'https://www.youtube.com/watch?v=UveLSA7Hoj8' WHERE id_api = 'tt0081455';

UPDATE Contenido SET id_tmdb = 694, descripcion = 'Jack Torrance se traslada, junto a su mujer y a su hijo, al impresionante hotel Overlook, en Colorado, para encargarse del mantenimiento del mismo durante la temporada invernal, en la que permanece cerrado y aislado por la nieve. Su idea es escribir su novela al tiempo que cuida de las instalaciones durante esos largos y solitarios meses de invierno, pero desde su llegada al hotel, Jack comienza a padecer inquietantes transtornos de personalidad, al mismo tiempo que en el lugar comienzan a suceder diversos fenómenos paranormales.', trailer_url = 'https://www.youtube.com/watch?v=A3q03BBwMp4' WHERE id_api = 'tt0081505';

UPDATE Contenido SET id_tmdb = 814, descripcion = 'Dos mochileros norteamericanos, David Kessler y Jack están de viaje por Europa. Caminando por una zona rural de Inglaterra, la población local los mira mal cuando entran en un bar. Al salir, reciben todo tipo de extrañas advertencias: ''Manténganse en la carretera y aléjense de los pantanos'' y ''Cuidado con la luna''. Aun así, los jóvenes se adentran en la oscuridad y no se dan cuenta que están siendo seguidos por una terrible criatura.', trailer_url = 'https://www.youtube.com/watch?v=EM9quAtFUH4' WHERE id_api = 'tt0082010';

UPDATE Contenido SET id_tmdb = 10323, descripcion = 'Cuando el rey de Argos decide sacrificar a su hija y a su nieto Perseo, Zeus decide salvarlos y arrasar la ciudad. Perseo crece feliz hasta que la diosa Thetis, para vengarse de Zeus, que ha castigado a su hijo Calibos con una horrible deformidad, lo secuestra y lo abandona a su suerte. Al conocer la noticia, Zeus ordena a los demás dioses que ofrezcan a su hijo regalos que le permitan defenderse. Así es como una mañana el héroe encuentra una espada capaz de cortar la piedra, un casco que lo vuelve invisible y un escudo que lo hace invulnerable. Con estas armas se dirige a la ciudad de Joppa, cuya princesa es víctima de una maldición.', trailer_url = 'https://www.youtube.com/watch?v=IopYAEDa6uU' WHERE id_api = 'tt0082186';

UPDATE Contenido SET id_tmdb = 85, descripcion = 'Año 1936, Indiana Jones es un profesor de arqueología, dispuesto a correr peligrosas aventuras con tal de conseguir valiosas reliquias históricas. Después de una infructuosa misión en Sudamérica, el gobierno estadounidense le encarga la búsqueda del Arca de la Alianza, donde se conservan las Tablas de la Ley que Dios entregó a Moisés. Según la leyenda, quien las posea tendrá un poder absoluto, razón por la cual también la buscan los nazis.', trailer_url = 'https://www.youtube.com/watch?v=ep1d88NWhVY' WHERE id_api = 'tt0082971';

UPDATE Contenido SET id_tmdb = 9725, descripcion = 'Alice, superviviente de la tragedia del campamento de Crystal Lake, muere asesinada en su apartamento. Cinco años más tarde, un grupo de jóvenes aparece en el escenario de las macabras muertes, que aparentemente ha recuperado la normalidad, para realizar un curso de entrenamiento. Cuando el grupo se separa empieza de nuevo el implacable ritual sangriento. Paul, el líder del grupo, y su novia Ginny vuelven al campo para descubrir la masacre y también al autor de los crímenes, un Jason milagrosamente vivo pero terriblemente deformado y sediento de venganza.', trailer_url = 'https://www.youtube.com/watch?v=3mNnJuOoI80' WHERE id_api = 'tt0082418';

UPDATE Contenido SET id_tmdb = 21484, descripcion = 'Berlín, antes de la caída del muro. Cuando Marc regresa de un viaje encuentra a su esposa Anna cambiada, muy nerviosa y perturbada. Por fin, le confiesa que tiene una aventura y lo abandona. Marc cae en una terrible depresión que lo lleva casi al borde de la locura. Unas semanas después, el detective privado que ha contratado para que siga a su mujer es salvajemente asesinado. La verdad sobre la aventura secreta de Anna se revelará monstruosa.', trailer_url = 'https://www.youtube.com/watch?v=CTB15PPtMyA' WHERE id_api = 'tt0082933';

UPDATE Contenido SET id_tmdb = 5961, descripcion = 'Fanny y Alexander son dos hermanos que pertenecen a la pintoresca familia Ekdahl, a principios de siglo XX. Sus padres, Oscar y Emilie, son el director y la actriz principal de la compañía local de teatro, respectivamente. Tras la repentina muerte de Oscar, Emilie se vuelve a casar con un predicador autoritario que les obliga a mantener una vida ascética. "Fanny y Alexander" fue mimada por la crítica y consiguió cuatro Oscars en la edición de 1984: dirección artística, fotografía, vestuario y película de habla no inglesa.', trailer_url = 'https://www.youtube.com/watch?v=UCXoXFdNa1o' WHERE id_api = 'tt0083922';

UPDATE Contenido SET id_tmdb = 97, descripcion = 'La primera película de aventuras dentro del inexplorado mundo tridimensional del inimaginado dominio de la informática. Tron deslumbra con los revolucionarios efectos visuales y las secuencias de acción. Flynn, un ordenador que inventa vídeojuegos, se encuentra a merced de la malvada fuerza humana que contesta al panel de control principal -la presencia de un poderoso corrupto ordenador que ha radiado Flynn dentro de su juego mortal. Allí, ladrones electrónicos y la imparable carrera «Cycle Lights». Con la ayuda de sus amigos, Alan y Lora, la esperanza de Flynn es activar a Tron, el valiente y fiable programa, en una heroica batalla por salvar a la humanidad!', trailer_url = 'https://www.youtube.com/watch?v=3efV2wqEjEY' WHERE id_api = 'tt0084827';

UPDATE Contenido SET id_tmdb = 9728, descripcion = 'Un idílico verano va a convertirse en la peor de las pesadillas para otro grupo de despreocupados jóvenes de vacaciones. Ignorando el legado de sangre del campamento de Crystal Lake, uno por uno van siendo víctimas del maníaco Jason, que los acecha en cada momento.', trailer_url = 'https://www.youtube.com/watch?v=SDdBhDJ7wdA' WHERE id_api = 'tt0083972';

UPDATE Contenido SET id_tmdb = 11704, descripcion = 'Ante la amenza de que el hogar de una familia de ratones de campo sea destruido, la madre, la señora Brisby, pide ayuda... Dibujos animados para los más pequeños de la casa, con una de las partituras más geniales del compositor de bandas sonoras Jerry Goldsmith.', trailer_url = 'https://www.youtube.com/watch?v=q8skJYBxvNk' WHERE id_api = 'tt0084649';

UPDATE Contenido SET id_tmdb = 8769, descripcion = 'Nació en Detroit en una línea de montaje de automóviles, pero no es un coche cualquiera. En el fondo de su chasis se aloja el mismísimo diablo. Es Christine un Plymouth Fury de 1958, rojo y blanco, cuyo único equipo "normalizado" comprende un deseo de venganza insaciable, que hiela la sangre a cualquiera y destruye todo aquello que encuentra en su camino.', trailer_url = 'https://www.youtube.com/watch?v=wMoHFqV3aX8' WHERE id_api = 'tt0085333';

UPDATE Contenido SET id_tmdb = 36670, descripcion = 'La temible organización criminal Spectra ha ideado un ingenioso plan que le permite conseguir dos proyectiles nucleares, los cuales harán estallar si el gobierno no cede a su chantaje. El agente 007 se encargará del caso.', trailer_url = 'https://www.youtube.com/watch?v=Ha94ny648TQ' WHERE id_api = 'tt0086006';

UPDATE Contenido SET id_tmdb = 850, descripcion = 'En los años cuarenta, un niño quiere como regalo de navidad un rifle de aire comprimido. Claro está, los padres piensan que no es una buena idea. Comedia familiar extraordinariamente popular en Estados Unidos que se basa en las historias del humorista Jean Shepherd. Calificada como divertida y conmovedora a partes iguales, una tierna historia con mensaje que encandila tanto a los adultos como a los más jóvenes.', trailer_url = 'https://www.youtube.com/watch?v=ptbPSR9pAB8' WHERE id_api = 'tt0085334';

