UPDATE Contenido SET id_tmdb = 1621, descripcion = 'Dos hombres de negocios sostienen distintas tesis sobre las condiciones de la naturaleza humana. Para uno es cuestión de genética, para el otro es cuestión de educación. Para corroborar sus teorías hacen una apuesta para lo cual cambian los destinos de dos personas socialmente antagónicas.', trailer_url = 'https://www.youtube.com/watch?v=rxz036jbrmI' WHERE id_api = 'tt0086465';

UPDATE Contenido SET id_tmdb = 9346, descripcion = 'Joel Goodsen es un joven de 17 años, universitario y responsable. Un chico en el que cualquiera puede confiar. Pero ha sido bueno durante demasiado tiempo. Ahora los padres de Joel se encuentran de viaje, y él está solo a cargo de la casa. Sus padres, confían en él. Aunque quizá no deberían...', trailer_url = 'https://www.youtube.com/watch?v=zPZafey1fyk' WHERE id_api = 'tt0086200';

UPDATE Contenido SET id_tmdb = 837, descripcion = 'Max Renn, un aburrido operador de televisión por cable, un día descubre una televisión "real" llamada Videodrome. Una palpitante pesadilla de ciencia-ficción que nos muestra un mundo en el que el vídeo puede controlar y alterar la vida humana. Considerada por Andy Warhol la "Naranja mecánica" de los 80.', trailer_url = 'https://www.youtube.com/watch?v=v8BUXKcp8zE' WHERE id_api = 'tt0086541';

UPDATE Contenido SET id_tmdb = 10823, descripcion = 'Una joven pareja que viaja por el medio oeste estadounidense se pierde y llega a una pequeña ciudad en la que todos los adultos han sido asesinados por los niños del lugar, a su vez poseídos por una malévola fuerza surgida de los campos de maíz que alcanzan hasta donde llega la vista.', trailer_url = 'https://www.youtube.com/watch?v=wHf4pnj2hg4' WHERE id_api = 'tt0087050';

UPDATE Contenido SET id_tmdb = 1788, descripcion = 'Cuenta la historia de un chico que llega a un pueblo en el que el fundamentalista Shaw Moore ha prohibido el baile. El joven, que además de rebelde es un entusiasta de la música, intentará por todos los medios acabar con esa prohibición, mientras se enamora de la hija de Moore.', trailer_url = 'https://www.youtube.com/watch?v=xxOuSqokKok' WHERE id_api = 'tt0087277';

UPDATE Contenido SET id_tmdb = 1885, descripcion = 'Daniel Larusso llega a Los Angeles procedente de la costa Este de Estados Unidos dispuesto a hacer nuevos amigos. Sin embargo, se convierte en el blanco de los ataques de los Cobras, un hostil grupo de estudiantes de kárate, cuando comienza a salir con Ali, la antigua novia del cabecilla del grupo. En tal situación, no tiene más remedio que pedirle ayuda a Miyagi, un maestro de artes marciales, para que le enseñe kárate. Bajo la tutela de Miyagi, Daniel desarrolla no sólo sus aptitudes físicas, sino también la seguridad en sí mismo que necesita para superar todos los obstáculos.', trailer_url = 'https://www.youtube.com/watch?v=r_8Rw16uscg' WHERE id_api = 'tt0087538';

UPDATE Contenido SET id_tmdb = 625, descripcion = 'Sydney es un periodista del "The New York Times" enviado a Camboya en 1972 como corresponsal de guerra. Una vez allí, conoce a Dith Pran, un nativo que le sirve de guía e intérprete durante la guerra. En 1975, al caer el gobierno camboyano, los EE.UU. se retiran del país, y toda la familia de Pran emigra a Norteamérica excepto él, que decide quedarse con el periodista para seguir ayudándole. Ambos viven refugiados en la embajada francesa, pero cuando deciden abandonar Camboya, el ejército revolucionario prohíbe salir del país a Pran, que es recluido en un campo de concentración.', trailer_url = 'https://www.youtube.com/watch?v=mTfqXmVVjPU' WHERE id_api = 'tt0087553';

UPDATE Contenido SET id_tmdb = 14052, descripcion = 'En  el Adams College, las reglas y la bromas, las ponen los deportistas de la fraternidad Alpha Beta. Por eso, cuando un grupo de inadaptados socialmente les desafia, inmediatamente son rechazados por todas las casas en el campus. Entonces toman la decisión de iniciar su propia fraternidad para proteger a sus hermanos marginados, los novatos del campus pronto se encuentran en una batalla real, cuando los Alpha Beta tratan de aplastar a sus nuevos rivales.', trailer_url = 'https://www.youtube.com/watch?v=kIZH5TKnEeg' WHERE id_api = 'tt0088000';

UPDATE Contenido SET id_tmdb = 218, descripcion = 'Un cyborg ha sido enviado desde el futuro en una misión mortal: eliminar a Sarah Connor, una joven cuya vida tendrá una gran importancia en los próximos años. Sarah tiene sólo un protector —Kyle Reese— también enviado desde el futuro. El Terminator utiliza su inteligencia excepcional y fuerza para encontrar a Sarah, pero ¿hay alguna forma de detener al cyborg aparentemente indestructible?', trailer_url = 'https://www.youtube.com/watch?v=alLxdt9PLMc' WHERE id_api = 'tt0088247';

UPDATE Contenido SET id_tmdb = 9663, descripcion = 'Jeff Bridges da vida a un extraterrestre de un lejano planeta que aprende lo que significa estar enamorado. Cuando su nave es abatida en Wisconsin, Starman llega al recóndito refugio de una joven y desconsolada viuda, Jenny Hayden, y adopta la forma de su marido fallecido. El extraterrestre convence a Jenny para que le lleve hasta Arizona, diciéndole que si no es rescatado por la nave nodriza en el plazo de tres días, él morirá.', trailer_url = 'https://www.youtube.com/watch?v=m9GbkmUG0PM' WHERE id_api = 'tt0088172';

UPDATE Contenido SET id_tmdb = 2108, descripcion = 'Cinco estudiantes de distinta educación, formación y gustos son castigados a pasar un sábado en el instituto en el que estudian. Pronto las desavenencias entre ellos aparecen, especialmente cuando el director que les vigila se ausenta del aula... Comedia juvenil de culto de los años ochenta.', trailer_url = 'https://www.youtube.com/watch?v=8_7UkjKja7w' WHERE id_api = 'tt0088847';

UPDATE Contenido SET id_tmdb = 10957, descripcion = 'Tarón es un valeroso joven que debe impedir que el malvado Rey Horned se apodere del Caldero Mágico, cuya fuerza misteriosa es capaz de crear un auténtico ejército de invencibles guerreros sobrenaturales. En su lucha contra el mal, Tarón cuenta con la ayuda de su maestro, Dallben, la princesa Eilonwy, un animal con aspecto de osito de peluche llamada Gurgi, un juglar que se hace llamar Fflewddur Fflam, un cerdito con dotes de clarividente y un trío de brujas excéntricas.', trailer_url = 'https://www.youtube.com/watch?v=WvWVQBdYE40' WHERE id_api = 'tt0088814';

UPDATE Contenido SET id_tmdb = 8408, descripcion = 'Los zombies se han apoderado del planeta, y el número de humanos se reduce a uno por cada 400.000 muertos vivientes. Un pequeño grupo de personas, formado por científicos y militares, se refugian en una antigua instalación subterránea del gobierno. Allí intentan contactar sin éxito con otros grupos supervivientes. Mientras, los doctores investigan el origen del fenómeno, y de su posible cura; a la vez que intentan domesticar a un muerto viviente al que mantienen encadenado. A medida que pasa el tiempo, las tensiones entre los científicos y los soldados irán creciendo dentro del grupo.', trailer_url = 'https://www.youtube.com/watch?v=G8gMvjmGv4k' WHERE id_api = 'tt0088993';

UPDATE Contenido SET id_tmdb = 10303, descripcion = 'Secuela de ''Tras el corazón verde''. Cuando Jack y Joan regresan de su romántico crucero alrededor del mundo y ya comienzan a tener una vida aburrida, Joan acepta una invitación para ir a un país de Oriente Próximo como invitada de un jeque, pero la secuestran y se ve atrapada junto a la ''joya''. Jack decide rescatarla con la ayuda de su nuevo amigo Ralph.', trailer_url = 'https://www.youtube.com/watch?v=K8ZvVDiYc88' WHERE id_api = 'tt0089370';

UPDATE Contenido SET id_tmdb = 9626, descripcion = 'La malvada reina Gedren arrasa la aldea de Hablac, llevándose con ella un talismán que le ofrece gran poder. Sonja es la hermana de la guardiana del talismán, asesinada durante el asalto. En busca de venganza, inicia un viaje para recuperar el talismán y asesinar a Gedren. Kalidor la sigue para cuidar de ella, pese a que ello entraña un gran riesgo, debido a la atracción que existe entre ambos, y a que los poderes de Sonja tienen una debilidad: desaparecerán si pierde su virginidad.', trailer_url = 'https://www.youtube.com/watch?v=MOBiGxkoazQ' WHERE id_api = 'tt0089893';

UPDATE Contenido SET id_tmdb = 11418, descripcion = 'Clark tiene la idea de volver a pasar unas vacaciones con su familia. Para ello ha trabajado duro y ha conseguido un viaje a Europa. Gran Bretaña, Alemania, Francia e Italia serán las damnificadas.', trailer_url = 'https://www.youtube.com/watch?v=vbF_7TiG5bg' WHERE id_api = 'tt0089670';

UPDATE Contenido SET id_tmdb = 10157, descripcion = 'Mahoney y sus amigos se han graduado ya en la academia de policía y se les asigna su primera misión. ¿Estarán preparados para enfrentarse a una peligrosa banda callejera de gamberros?', trailer_url = 'https://www.youtube.com/watch?v=K_pccyu6ipY' WHERE id_api = 'tt0089822';

UPDATE Contenido SET id_tmdb = 9281, descripcion = 'En su primer viaje a Philadelphia, Samuel Lap, un niño de una comunidad "amish", presencia por casualidad el brutal asesinato de un hombre. John Book (Harrison Ford) será el policía encargado de protegerles, a él y a su madre, de quienes quieren eliminar al niño sea como sea. Cuando Book se entera de que el asesinato está relacionado con una trama de corrupción en el seno de la policía, decide refugiarse en el poblado amish.', trailer_url = 'https://www.youtube.com/watch?v=Spwdv0OkNRc' WHERE id_api = 'tt0090329';

UPDATE Contenido SET id_tmdb = 793, descripcion = 'Una mañana, Jeffrey Beaumont, después de visitar a su padre en el hospital, encuentra entre unos arbustos una oreja humana. La guarda en una bolsa de papel y la lleva a la comisaría de policía, donde le atiende el detective Williams, que es vecino suyo. Comienza así una misteriosa intriga que desvelará extraños sucesos acontecidos en una pequeña localidad de Carolina del Norte.', trailer_url = 'https://www.youtube.com/watch?v=SECSDOK58Vc' WHERE id_api = 'tt0090756';

UPDATE Contenido SET id_tmdb = 1694, descripcion = 'Herbert West estudia en Europa métodos regenerativos junto a un conocido científico, que muere en extrañas circunstancias. Herbert viaja a EEUU, donde se matricula en la Miskatonic University. Allí continúa con sus experimentos, que tienen la intención de alcanzar la fórmula que permita reanimar los muertos. Su compañero de piso Dan y la novia de éste, Megan, se verán envueltos en el macabro proyecto.', trailer_url = 'https://www.youtube.com/watch?v=LhI9HLYyBgQ' WHERE id_api = 'tt0089885';

UPDATE Contenido SET id_tmdb = 11814, descripcion = 'Gary y Wyatt son dos adolescentes que no gozan de lo que se dice demasiada popularidad entre las chicas. Un día, aprovechando que los padres no están en casa, deciden crear por ordenador una mujer espectacular que les obedezca en todo, para poder presumir delante de sus amigos y no requerir la atención del resto de las chicas.', trailer_url = 'https://www.youtube.com/watch?v=hnLH2f7ZTm0' WHERE id_api = 'tt0090305';

UPDATE Contenido SET id_tmdb = 726209, descripcion = 'Las vacaciones de una familia en una casa de lujo dan un giro inquietante cuando un ciberataque anula sus dispositivos... y dos desconocidos llaman a la puerta.', trailer_url = 'https://www.youtube.com/watch?v=lEldhe2Zt0c' WHERE id_api = 'tt12747748';

UPDATE Contenido SET id_tmdb = 47971, descripcion = 'La película gira en torno al regreso de Xander Cage, a quien todos creían muerto. Cage, alias xXx (Triple X), es un rebelde amante de los deportes extremos que adora romper las leyes y que por ello acaba siendo atrapado por las autoridades de EE.UU. Entonces se ve obligado a colaborar como agente encubierto participando en numerosos episodios de riesgo. Tras un fatídico incidente, Xander es dado por muerto. Pero ahora, vuelve a la acción de incógnita acompañado de su agente instructor Augustus Gibbons.', trailer_url = 'https://www.youtube.com/watch?v=0j2Sm_XHha0' WHERE id_api = 'tt1293847';

UPDATE Contenido SET id_tmdb = 49444, descripcion = 'Po está ahora viviendo su sueño como el Guerrero del Dragón, protegiendo el Valle de la Paz junto a sus amigos y sus compañeros maestros del kung fu. Los Cinco Furiosos. Pero su nueva e impresionante vida se encuentra amenazada por la aparición de un villano formidable, que planea usar un arma secreta imparable para conquistar China y destruir el kung fu. Po debe volver la vista a su pasado para descubrir los secretos de su misterioso origen; solo entonces podrá adquirir la fuerza que necesita para vencer.', trailer_url = 'https://www.youtube.com/watch?v=kJVdvDhhWrg' WHERE id_api = 'tt1302011';

UPDATE Contenido SET id_tmdb = 35056, descripcion = 'Phil (Steve Carell) y Claire Foster (Tina Fey) son un matrimonio aparentemente feliz que ve como sus mejores amigos se separan después de una vida muy similar a la suya. En un intento por escapar de su anodina y rutinaria vida, Phil lleva a cenar a Claire a un caro restaurante de Manhattan, en el que, sin embargo, no ha hecho reserva. Cuando los Tripplehorn son llamados a ocupar su mesa y no aparecen, Phil y Claire se hacen pasar por el matrimonio ausente, comenzando así una noche de infortunios como consecuencia de haber adoptado una falsa identidad.', trailer_url = 'https://www.youtube.com/watch?v=aspBKFz2dBI' WHERE id_api = 'tt1279935';

UPDATE Contenido SET id_tmdb = 1865, descripcion = 'Cuando Jack Sparrow vuelve a encontrarse con una mujer a la que había conocido años atrás, no está seguro de si se trata de amor o si ella es una estafadora sin escrúpulos que lo está utilizando para encontrar la legendaria Fuente de la Juventud. A todo esto, Jack es capturado por el Venganza de la Reina Ana, el barco del temible pirata Barbanegra, que lo obliga a unirse a su tripulación, lo que le hará vivir una inesperada aventura en la que no sabe quién le inspira más miedo si Barbanegra o esa mujer que regresa del pasado.', trailer_url = 'https://www.youtube.com/watch?v=Ax6md6HoZ2o' WHERE id_api = 'tt1298650';

UPDATE Contenido SET id_tmdb = 41109, descripcion = 'Having conquered the Asian underworld, crime boss Don sets in motion a plan that will give him dominion over Europe.', trailer_url = 'https://www.youtube.com/watch?v=_X5w-6PqoZ0' WHERE id_api = 'tt1285241';

UPDATE Contenido SET id_tmdb = 740985, descripcion = 'Borat, el exuberante, ingenuo y atrasado periodista kazajo fanático de los Estados Unidos, se propone realizar un documental sobre ese país. Borat se pone en marcha en busca de figuras políticas estadounidenses para elaborar con ellas una evaluación de la presidencia de Trump y su gestión de la crisis del coronavirus en el país.', trailer_url = 'https://www.youtube.com/watch?v=QOJSxLyJ9t4' WHERE id_api = 'tt13143964';

UPDATE Contenido SET id_tmdb = 34653, descripcion = 'Los Ángeles, 1962, crisis de los misiles cubanos. George Falconer (Colin Firth) es un profesor universitario británico y homosexual de 52 años que lucha por encontrarle sentido a su vida tras la muerte de su compañero sentimental, Jim (Matthew Goode). George recibe consuelo de su amiga más íntima, Charley (Julianne Moore), una belleza de 48 años que también lucha con sus propias dudas acerca del futuro. Un joven estudiante, Kenny (Nicholas Hoult), que está intentando aceptar su auténtica naturaleza, acecha a George porque ve en él a un espíritu afín.', trailer_url = 'https://www.youtube.com/watch?v=0Eoe58Vd8R0' WHERE id_api = 'tt1315981';

UPDATE Contenido SET id_tmdb = 44629, descripcion = 'Tras la muerte de su madre, Joshua “J” Cody, tiene que trasladarse a casa de su abuela Janine, que vive en Melbourne con sus tres hijos, Andrew, Darren y Craig, todos implicados en negocios ilegales. Inevitablemente, el chico se verá envuelto en los turbios asuntos de sus tíos, sobre todo cuando se produzca un enfrentamiento entre sus familiares y las autoridades locales, situación que provocará una serie de asesinatos a sangre fría. El sargento Leckie intentará salvar a Joshua y, además, conseguir su colaboración para detener a la banda', trailer_url = 'https://www.youtube.com/watch?v=YNszOl14AWg' WHERE id_api = 'tt1313092';

UPDATE Contenido SET id_tmdb = 762509, descripcion = 'Rafiki debe transmitir la leyenda de Mufasa a la joven cachorro de león Kiara, hija de Simba y Nala, y con Timón y Pumba prestando su estilo característico. Mufasa, un cachorro huérfano, perdido y solo, conoce a un simpático león llamado Taka, heredero de un linaje real. Este encuentro casual pone en marcha un viaje de un extraordinario grupo de inadaptados que buscan su destino.', trailer_url = 'https://www.youtube.com/watch?v=HZIlPA4HiYQ' WHERE id_api = 'tt13186482';

UPDATE Contenido SET id_tmdb = 82682, descripcion = 'Los Angeles, 1949. Mickey Cohen, originario de Brooklyn, se ha convertido en el gran jefe de la mafia que dirige la ciudad. Todos parece pasar por sus manos: drogas, armas, prostitutas, y cualquier material robado. Se encuentra absolutamente protegido por los miembros de su clan, que lo veneran como a su líder indiscutible, pero no solo eso, pues sus tentáculos van más allá de los bajos fondos: parte del cuerpo de policía y algunos miembros del sector político se encuentran bajo su influjo.  Sin embargo, todavía hay hombres dentro de la brigada policial que no se dejan amedrentar por la corrupción. Es el caso de los sargentos John O''Mara y Jerry Wooters, que contra todo y contra todos, intentarán destruir el imperio del todopoderoso Cohen.', trailer_url = 'https://www.youtube.com/watch?v=nmIMSrggVOA' WHERE id_api = 'tt1321870';

UPDATE Contenido SET id_tmdb = 44363, descripcion = 'Tres locos por el snowboard van en el telesilla de una estación de esquí ambicionando la última bajada por la ladera antes de marchar a casa. De pronto, el telesilla se detiene por completo. Ni un alma alrededor. Todo empeora cuando las luces de la estación se apagan para no encenderse de nuevo hasta el próximo fin de semana. Entonces tendrán que hacer cosas impensables para poder sobrevivir a una muerte segura por congelación. Pero además, pronto se darán cuenta de que el frío no es su peor enemigo.', trailer_url = 'https://www.youtube.com/watch?v=tebjF7YuBpk' WHERE id_api = 'tt1323045';

UPDATE Contenido SET id_tmdb = 77877, descripcion = 'Un soldado americano destinado en Irak encuentra la fotografía de una mujer de la que queda prendado. Considera que el hallazgo es una prueba irrefutable de su buena suerte, así que, cuando regresa a su país, busca a la chica y la encuentra: se trata de una madre divorciada. Adaptación de una novela de Nicholas Sparks (El diario de Noa).', trailer_url = 'https://www.youtube.com/watch?v=iXfVxcwELH8' WHERE id_api = 'tt1327194';

UPDATE Contenido SET id_tmdb = 749170, descripcion = 'El primer ministro del Reino Unido y el presidente de EE. UU. tienen una rivalidad pública que pone en riesgo la alianza entre sus países. Pero cuando se convierten en el blanco de un poderoso enemigo, se ven obligados a confiar el uno en el otro. Aliados con Noel, una agente del MI6, intenta frustrar una conspiración que amenaza al mundo libre.', trailer_url = 'https://www.youtube.com/watch?v=Gs7JVZC28Qw' WHERE id_api = 'tt13357520';

UPDATE Contenido SET id_tmdb = 225180, descripcion = 'La convirtieron en una paria en el Japón del periodo Edo. Ahora, una joven espadachina sedienta de venganza recorre un camino sangriento hacia su destino.', trailer_url = 'https://www.youtube.com/watch?v=eOJ5J-hV7_Y' WHERE id_api = 'tt13309742';

UPDATE Contenido SET id_tmdb = 787752, descripcion = 'Thriller sobre los horrores de las citas modernas vistos a través de la desafiante batalla de una joven para sobrevivir a los inusuales apetitos de su nuevo novio.', trailer_url = 'https://www.youtube.com/watch?v=wKk5VAK1GZQ' WHERE id_api = 'tt13403046';

UPDATE Contenido SET id_tmdb = 112314, descripcion = 'Mientras restaura unas cintas de vídeo dañadas, un archivista se ve envuelto en una misteriosa trama relacionada con la directora desaparecida y una secta demoniaca.', trailer_url = 'https://www.youtube.com/watch?v=ibxKEqxARkE' WHERE id_api = 'tt13365348';

UPDATE Contenido SET id_tmdb = 42888, descripcion = 'Lisa Jorgenson es una joven atleta de 31 años que está convencida de que su vida sentimental es un fracaso. Pero, inesperadamente, se verá envuelta en un divertido triángulo amoroso con George, un ejecutivo en plena crisis, y Matty, un jugador de béisbol profesional. ¿Por cuál de los dos se decidirá? ¿Cómo saber qué es el amor verdadero?', trailer_url = 'https://www.youtube.com/watch?v=QK6abmq1bWc' WHERE id_api = 'tt1341188';

UPDATE Contenido SET id_tmdb = 15260, descripcion = 'Un niño de 12 años y su mejor amigo, un sabio perro de 28 años con poderes mágicos, se embarcan en una serie de aventuras surrealistas.', trailer_url = 'https://www.youtube.com/watch?v=cWfAN_TwW0E' WHERE id_api = 'tt1305826';

