UPDATE Contenido SET id_tmdb = 798286, descripcion = 'Beau (Phoenix) es un hombre que tendrá que enfrentarse a sus miedos y paranoias al aventurarse en una épica odisea para llegar a casa de su controladora madre.', trailer_url = 'https://www.youtube.com/watch?v=9xJEwiM9t_4' WHERE id_api = 'tt13521006';

UPDATE Contenido SET id_tmdb = 249164, descripcion = 'Mia es una joven de 17 años que parece tenerlo todo en la vida: una famila adorable, un novio que la quiere, una amiga incondicional y una prometedora carrera musical, debido a su talento natural para tocar el chelo. Sin embargo, todo eso cambia en una fracción de segundo, cuando ella y su familia sufren un terrible accidente de coche.', trailer_url = 'https://www.youtube.com/watch?v=B0chmofGqpk' WHERE id_api = 'tt1355630';

UPDATE Contenido SET id_tmdb = 1241982, descripcion = 'Tras recibir una inesperada llamada de sus antepasados, Vaiana debe viajar a los lejanos mares de Oceanía y adentrarse en peligrosas aguas perdidas para vivir una aventura sin precedentes.', trailer_url = 'https://www.youtube.com/watch?v=5REqdy3W3N4' WHERE id_api = 'tt13622970';

UPDATE Contenido SET id_tmdb = 119051, descripcion = 'Miércoles Addams, lista, sarcástica y un poco muerta por dentro, investiga misterios retorcidos mientras hace amigos —y enemigos— en la Academia Nunca Más.', trailer_url = 'https://www.youtube.com/watch?v=YJEjvt4FrPY' WHERE id_api = 'tt13443470';

UPDATE Contenido SET id_tmdb = 261023, descripcion = 'En el sur de Boston, en la década de 1970, el agente del FBI John Connolly (Joel Edgerton) convence al mafioso irlandés James “Whitey” Bulger (Johnny Depp), un delincuente recién salido de la cárcel, para que colabore con el FBI y elimine a un enemigo común: la mafia italiana. El drama cuenta la historia de esa nefasta alianza que provocó una espiral fuera de control, permitiendo a Whitey escapar del ámbito de la ley, consolidar su poder y convertirse en uno de los más implacables y poderosos gángsteres de la historia de Boston.', trailer_url = 'https://www.youtube.com/watch?v=R_F-lVhSfx8' WHERE id_api = 'tt1355683';

UPDATE Contenido SET id_tmdb = 766475, descripcion = 'Un desesperado productor de cine de Hollywood se propone convertir en película una popular obra de teatro. Cuando miembros de la producción son asesinados, el cansado inspector Stoppard y la agente novata Stalker se encontrarán en medio de una intrigante novela policíaca.', trailer_url = 'https://www.youtube.com/watch?v=jwsvofmgIug' WHERE id_api = 'tt13640696';

UPDATE Contenido SET id_tmdb = 241259, descripcion = 'Cuando un cómico en apuros tiene un gesto amable con una mujer vulnerable, desencadena una obsesión enfermiza que amenaza con destrozar la vida de ambos.', trailer_url = 'https://www.youtube.com/watch?v=zwWVSrLK10c' WHERE id_api = 'tt13649112';

UPDATE Contenido SET id_tmdb = 57431, descripcion = 'Todo comienza con un simple favor que con el tiempo se transforma en algo terrible. Cuando el peor canguro del mundo (Jonah Hill) embarca a los tres peores niños del mundo en una inolvidable aventura nocturna por las calles de la ciudad de Nueva York, con transporte de drogas y strippers incluidas, nadie puede predecir quién va a volver a su casa de una pieza...', trailer_url = 'https://www.youtube.com/watch?v=vpPOcKmCb6E' WHERE id_api = 'tt1366344';

UPDATE Contenido SET id_tmdb = 58244, descripcion = 'Adam es aparentemente un tipo corriente dentro de un universo extraordinario. Vive humildemente de lo que gana, pero su espíritu romántico conserva en la memoria el recuerdo del amor imposible por una chica que conoció en un mundo distinto, en un lugar que se halla fuera de su alcance. Sin embargo, cuando vuelve a verla en la televisión, no habrá nada en el mundo que le impida encontrar el camino que lo lleve hasta ella.', trailer_url = 'https://www.youtube.com/watch?v=J9LQNmaisv0' WHERE id_api = 'tt1374992';

UPDATE Contenido SET id_tmdb = 297761, descripcion = 'Mientras el gobierno de EE.UU no tiene claro cómo responder a una visita alienígena a la Tierra con intenciones malignas, Amanda ''El Muro'' Waller, la líder de la agencia secreta A.R.G.U.S., ofrece una curiosa solución: reclutar a los villanos más crueles, con habilidades letales e incluso mágicas, para que trabajen para ellos. Sin demasiadas opciones a dar una negativa, los ocho supervillanos más peligrosos del mundo acceden a colaborar con el Ejecutivo en peligrosas misiones secretas, casi suicidas, para así lograr limpiar su expediente.', trailer_url = 'https://www.youtube.com/watch?v=TwaBdZT0vfk' WHERE id_api = 'tt1386697';

UPDATE Contenido SET id_tmdb = 64635, descripcion = 'Rekall es una empresa que puede convertir los sueños en recuerdos reales, haciendo que la frontera entre realidad y memoria se difumine. Para Douglas Quaid la idea de hacer un viaje mental que le proporcione recuerdos de una vida como superespía puede ser la solución perfecta para contrarrestar su frustrante vida. Lo malo es que el proceso sale mal, y Quaid se convierte en un hombre perseguido por los agentes de un estado totalitario. En su huida, se asocia con una combatiente rebelde con el fin de encontrar al cabecilla de la resistencia clandestina. Mientras el destino del mundo pende de un hilo, Quaid descubre su verdadera identidad y su verdadero destino. Se inspira en el cuento "Podemos recordar por usted al por mayor" de Philip K. Dick.', trailer_url = 'https://www.youtube.com/watch?v=lzsLoPLpUWY' WHERE id_api = 'tt1386703';

UPDATE Contenido SET id_tmdb = 781732, descripcion = 'The hardened son of a powerful industrialist returns home after years abroad and vows to take bloody revenge on those threatening his father''s life.', trailer_url = 'https://www.youtube.com/watch?v=psnYuD4M6zY' WHERE id_api = 'tt13751694';

UPDATE Contenido SET id_tmdb = 205775, descripcion = 'En el invierno de 1820, el ballenero de Nueva Inglaterra Essex fue agredido por algo a lo que nadie podía dar crédito: una ballena de tamaño y voluntad descomunal, con un sentido de la venganza casi humano. Este hecho real que supuso un desastre marítimo fue la inspiración para Moby-Dick de Melville. Pero la novela solo contó la mitad de la historia. “En el corazón del mar” revela las horribles consecuencias del encuentro, cuando los supervivientes de la tripulación fueron forzados hasta el límite y se vieron obligados a hacer lo impensable para mantenerse vivos. Enfrentándose a las tormentas, el hambre, el pánico, y la desesperación, los hombres llegan a dudar hasta de sus creencias más profundas, desde el valor de sus vidas a la moralidad de su oficio, mientras el capitán intenta orientarse en el mar abierto y su primer oficial sigue empeñado en conquistar a la gran ballena.', trailer_url = 'https://www.youtube.com/watch?v=Wz5TPtX_wFM' WHERE id_api = 'tt1390411';

UPDATE Contenido SET id_tmdb = 784651, descripcion = 'Los mejores aviadores de la IAF se unen ante un peligro inminente para formar Air Dragons. El luchador despliega su camaradería, hermandad y batallas, internas y externas.', trailer_url = 'https://www.youtube.com/watch?v=lAVYll_wBeY' WHERE id_api = 'tt13818368';

UPDATE Contenido SET id_tmdb = 39013, descripcion = 'Ree Dolly (Jennifer Lawrence) es una joven de 17 años que tiene que hacerse cargo de su familia en una situación de extrema precariedad económica. Pero lo peor es que su padre, tras salir de la cárcel en libertad condicional, desaparece misteriosamente, lo que agrava todavía más los problemas de la familia. Encontrarlo se convierte para Ree Dolly en una cuestión vital.', trailer_url = 'https://www.youtube.com/watch?v=XfG2GLvjaU0' WHERE id_api = 'tt1399683';

UPDATE Contenido SET id_tmdb = 758866, descripcion = 'Pese a no ser capaz de recuperarse de un drama personal, Yusuke Kafuku, actor y director de teatro, acepta montar la obra ''Tío Vania'' en un festival de Hiroshima. Allí, conoce a Misaki, una joven reservada que le han asignado como chófer. A medida que pasan los trayectos, la sinceridad creciente de sus conversaciones les obliga a enfrentarse a su pasado.', trailer_url = 'https://www.youtube.com/watch?v=oQ6bRIe0dMo' WHERE id_api = 'tt14039582';

UPDATE Contenido SET id_tmdb = 54138, descripcion = 'Cuando a la tripulación de la nave Enterprise le ordenan que regrese a casa, en la Tierra se enfrentan a una terrorífica fuerza que, aparentemente desde dentro, ha perpetrado un ataque a la cúpula de la Federación y todo lo que ésta representa, sumiendo a la flota en una profunda crisis. Para intentar solucionar el problema, y con un asunto personal que resolver, el capitán Kirk encabeza una incursión a un planeta en guerra, para capturar a un hombre que es un arma de destrucción masiva. A medida que nuestros héroes se van sumergiendo en una épica partida de ajedrez a vida o muerte, la lealtad se verá puesta a prueba, las amistades se romperán, y habrá que hacer ciertos sacrificios por la única familia que le queda a Kirk: su tripulación.', trailer_url = 'https://www.youtube.com/watch?v=FFAiOtL_rNo' WHERE id_api = 'tt1408101';

