UPDATE Contenido SET id_tmdb = 27579, descripcion = 'Jack es un mercenario solitario, un auténtico maestro entre asesinos. Pero, cuando un trabajo en Suecia no acaba tan bien como estaba previsto para este estadounidense en el extranjero, Jack le deja claro a su contacto que su próxima misión será la última. Se traslada entonces a Italia, donde se refugia en un pueblecito y empieza a disfrutar lejos de la muerte. Una mujer belga, Mathilde, le comunica que su próxima misión tiene que ver con la fabricación de un arma. Jack se sorprende a sí mismo trabando amistad con el párroco del pueblo y teniendo un romance. Pero al salir de las sombras, puede que Jack esté tentando al destino.', trailer_url = 'https://www.youtube.com/watch?v=03wpTvy-vkI' WHERE id_api = 'tt1440728';

