UPDATE Contenido SET id_tmdb = 81025, descripcion = 'El doctor Alfred Jones (Ewan McGregor), miembro del Centro Nacional para el Fomento de la Piscicultura, debe su reputación a un trabajo pionero sobre la reproducción de los moluscos. Cuando su jefe le pide que estudie la posibilidad de introducir el salmón en Yemen, rechaza la propuesta rotundamente. Lo que ignora es que detrás del proyecto está un acaudalado jeque árabe (Amr Waked), empeñado en exportar el arte de la pesca con mosca al norte de Yemen. Sin embargo, el disparatado proyecto capta la atención de un ambicioso asesor del primer ministro, que ve en él una excelente oportunidad para mejorar el prestigio del Reino Unido en Oriente Medio y, de paso, consolidar su futuro político. Cuando el proyecto se pone en marcha, el doctor Jones se ve obligado a reconsiderar su dictamen inicial y a colaborar con la joven y atractiva representante del jeque (Emily Blunt).', trailer_url = 'https://www.youtube.com/watch?v=LqzwMX3ftLI' WHERE id_api = 'tt1441952';

