UPDATE Contenido SET id_tmdb = 68722, descripcion = 'Drama sobre la Iglesia de la Cienciología. Lancaster Dodd (Philip Seymour Hoffman), un intelectual brillante y de fuertes convicciones, crea una organización religiosa que empieza a hacerse popular en Estados Unidos hacia 1952. Freddie Quell (Joaquin Phoenix), un joven vagabundo, se convierte en su mano derecha. Sin embargo, cuando la secta triunfa y consigue atraer a numerosos y fervientes seguidores, a Freddie le surgirán dudas.', trailer_url = 'https://www.youtube.com/watch?v=f-ZTXw_em0Q' WHERE id_api = 'tt1560747';

UPDATE Contenido SET id_tmdb = 1029827, descripcion = '7 años después de que se cerrara el caso relacionado con Vijay Salgaonkar y su familia, una serie de acontecimientos inesperados sacan a la luz una verdad que amenaza con cambiarlo todo para los Salgaonkar. ¿Podrá Vijay salvar a su familia esta vez?', trailer_url = 'https://www.youtube.com/watch?v=cxA2y9Tgl7o' WHERE id_api = 'tt15501640';

UPDATE Contenido SET id_tmdb = 50546, descripcion = 'Danny Maccabee es un cirujano plástico que siempre finge estar casado para así no comprometerse con ninguna mujer. Pero un día conoce a la despampanante Palmer, una joven con la que quiere algo más serio. El problema es que cuando Palmer descubre su anillo de casado, piensa que lo está, así que Danny decide contratar a su ayudante Katherine, una madre soltera con hijos, para que finjan ser su familia. Su intención es demostrarle a Palmer que su amor por ella es tan grande que está a punto de divorciarse de su mujer.', trailer_url = 'https://www.youtube.com/watch?v=fpj7i2CPt8M' WHERE id_api = 'tt1564367';

UPDATE Contenido SET id_tmdb = 132117, descripcion = 'Sunny, un brillante artista de poca monta, se ve catapultado al arriesgado mundo de la falsificación cuando crea el billete falso perfecto, mientras Michael, un feroz y poco ortodoxo oficial del las fuerzas especiales, quiere librar al país de la amenaza de la falsificación. En esta emocionante carrera del gato y el ratón, ¡perder no es una opción!', trailer_url = 'https://www.youtube.com/watch?v=KQdgKpNYho8' WHERE id_api = 'tt15477488';

UPDATE Contenido SET id_tmdb = 244458, descripcion = 'Jerry vive en un piso con la única compañía de su perro Bosco y de su gato Mr. Whiskers. Hasta aquí todo parece normal, pero cuando conoce a la bella Fiona, nuestro protagonista llega a su casa y no duda en contarle a sus animales de compañía sobre el encuentro. Evidentemente, ellos contestan.', trailer_url = 'https://www.youtube.com/watch?v=aKp-lDM5fus' WHERE id_api = 'tt1567437';

UPDATE Contenido SET id_tmdb = 44564, descripcion = 'Ronny (Vince Vaughn), un soltero empedernido, y Nick (Kevin James), un hombre felizmente casado, son amigos incondicionales desde los tiempos de la Universidad. Además son socios de una empresa de diseño de automóviles y luchan por conseguir un importante proyecto que contribuiría a ponerla en marcha. Ronny pasa el tiempo con su novia Beth (Jennifer Connelly) y Nick, con su esposa Geneva (Winona Ryder). Un día Ronny ve a Geneva con otro hombre y comienza a investigar por su cuenta para saber quién es y por qué Geneva está traicionando a Nick. Pero este descubrimiento lo pone ante un peliagudo dilema: ¿debe o no debe decirle a su amigo lo que sabe?', trailer_url = 'https://www.youtube.com/watch?v=kvzwYzIBgzo' WHERE id_api = 'tt1578275';

UPDATE Contenido SET id_tmdb = 76617, descripcion = 'Secuela directa del film de Tobe Hooper (1974). Hace 20 años, el pueblo de Newt (Texas) se vengó de la familia Sawyer por su papel ayudando y ocultando los asesinados cometidos por Jeb Sawyer, el maniaco de la motosierra, también conocido como “Cara de cuero”. Se presumió que toda la famila estaba muerta cuando Burt Hartman lideró a la gente del pueblo para quemar su granja, pero el bebé de los Sawyer sobrevivió y Gavin y Arlene, dos de los vigilantes pueblerinos, se le llevaron en secreto y la criaron como hija propia con el nombre de Heather. Hasta llegar a la veintena ella no descubre que es adoptada. Un abogado de su abuela la localiza para hacerle saber de una herencia.', trailer_url = 'https://www.youtube.com/watch?v=Z0xYPG-gX0U' WHERE id_api = 'tt1572315';

UPDATE Contenido SET id_tmdb = 136311, descripcion = 'Jimmy trata de asimilar la muerte de su esposa mientras ejerce de padre, amigo y terapeuta. Decide cambiar su forma de ser con la gente y volverse una persona completamente honesta, sin ningún tipo de filtro. ¿Conseguirá que las cosas mejoren o desatará el caos?', trailer_url = 'https://www.youtube.com/watch?v=YjHfjQDWl1A' WHERE id_api = 'tt15677150';

UPDATE Contenido SET id_tmdb = 76494, descripcion = 'Adaptación del libro más popular sobre el embarazo. Cuatro parejas están a punto de conocer las emociones, los temores y los quebraderos de cabeza que supone el ser padres.', trailer_url = 'https://www.youtube.com/watch?v=3Ef0GCdpnN4' WHERE id_api = 'tt1586265';

UPDATE Contenido SET id_tmdb = 245698, descripcion = 'En 1972, en plena Guerra Fría, el campeonato mundial de ajedrez cobró proporciones mediáticas y tintes políticos sin precedentes. El enfrentamiento en Reikjavik entre el mítico jugador norteamericano Bobby Fischer y el campeón soviético Boris Spassky fue más allá de la pura competición, calificándose como la "Partida del Siglo". El enfrentamiento entre ambos convierte el tablero de ajedrez en tablero geopolítico.', trailer_url = 'https://www.youtube.com/watch?v=bLaDMh5OQLo' WHERE id_api = 'tt1596345';

UPDATE Contenido SET id_tmdb = 33025, descripcion = 'La serie narra principalmente la historia de la familia Borgia, familia noble, con origen en el pueblo aragonés de Borja y establecida en Játiva, reino de Valencia, y posteriormente en Gandía, muy influyente durante el Renacimiento.', trailer_url = 'https://www.youtube.com/watch?v=ItLou92CsEM' WHERE id_api = 'tt1582457';

UPDATE Contenido SET id_tmdb = 49018, descripcion = 'Una familia descubre que espíritus oscuros han invadido su hogar después de que su hijo inexplicablemente cae en un sueño interminable. Cuando piden ayuda a un profesional, descubren que las cosas son mucho más personales de lo que pensaban.', trailer_url = 'https://www.youtube.com/watch?v=M-irQA7NIrk' WHERE id_api = 'tt1591095';

UPDATE Contenido SET id_tmdb = 80271, descripcion = 'Tras ser abandonada por su novio, Lola (Miley Cyrus), una chica 16 años, busca el apoyo de su mejor amigo. Al mismo tiempo, su madre, una divorciada de 40 años, se esfuerza por salir adelante. Al mismo tiempo, en un mundo cada vez más conectado por YouTube, iTunes, Twitter y Facebook, Lola y sus amigos se enfrentan a las presiones de la amistad y los romances de instituto mientras lidian con sus padres, muchas veces sobreprotectores y tecnológicamente desorientados... Remake americano de la película francesa del mismo nombre.', trailer_url = 'https://www.youtube.com/watch?v=4P6mXZzY9nc' WHERE id_api = 'tt1592873';

UPDATE Contenido SET id_tmdb = 59962, descripcion = 'Dos agentes de la CIA, grandes amigos desde la infancia, se enamoran de la misma mujer. Su amistad desaparece y se enzarzan en una batalla de proporciones épicas que pondrá en jaque a la ciudad de Nueva York.', trailer_url = 'https://www.youtube.com/watch?v=oleuD8479uM' WHERE id_api = 'tt1596350';

UPDATE Contenido SET id_tmdb = 59436, descripcion = 'Un escritor norteamericano algo bohemio llega con su prometida Inez y los padres de ésta a París. Mientras vaga por las calles soñando con los felices años 20, cae bajo una especie de hechizo que hace que, a medianoche, en algún lugar del barrio Latino, se vea transportado a otro universo donde va a conocer a personajes que jamás imaginaría iba a conocer...', trailer_url = 'https://www.youtube.com/watch?v=j7pOVg0q5-E' WHERE id_api = 'tt1605783';

UPDATE Contenido SET id_tmdb = 75174, descripcion = 'En “Infierno blanco”, el personaje interpretado por Liam Neeson es el líder de un indisciplinado grupo de trabajadores de una refinería cuyo avión se estrella en las remotas montañas de Alaska. Los supervivientes, expuestos a heridas mortales y un tiempo inclemente, disponen de pocos días para escapar de los gélidos elementos. Y por si el terrible frío fuera poco enemigo, una manada de lobos salvajes, amenazantes y sanguinarios, persiguen incansablemente a sus presas humanas. A medida que las indefensas víctimas caen una a una, las posibilidades de supervivencia del último de estos hombres son cada vez más remotas.', trailer_url = 'https://www.youtube.com/watch?v=ztUGS_DOvQ0' WHERE id_api = 'tt1601913';

UPDATE Contenido SET id_tmdb = 59965, descripcion = 'Un día, Nathan Harper ve su foto en una página de personas desaparecidas. Sospechando que sus padres pudieron secuestrarlo siendo un bebé, empieza a investigar y descubre que sus padres no son quienes dicen ser. Pero lo peor es que, de repente, sin saber cómo ni por qué, empieza a ser perseguido por la policía, por agentes del gobierno e incluso por asesinos a sueldo, convirtiéndose en la víctima de una misteriosa conspiración. A partir de ese momento el objetivo de su vida será averiguar su verdadera identidad.', trailer_url = 'https://www.youtube.com/watch?v=CEVkp5Je7m0' WHERE id_api = 'tt1600195';

UPDATE Contenido SET id_tmdb = 50839, descripcion = 'Ambientada en el arriesgado mundo de las altas finanzas, es un thriller dramático que compromete a las figuras clave de un banco de inversión durante las turbulentas 24 horas previas al inicio de la crisis financiera de 2008. Cuando Peter Sullivan, un analista junior, revela información que podría probar la caída de la empresa, origina una toma de decisiones en cadena tanto morales como financieras que producen un terremoto en las vidas de los implicados en el inminente desastre.', trailer_url = 'https://www.youtube.com/watch?v=L1dMqRfrhCY' WHERE id_api = 'tt1615147';

UPDATE Contenido SET id_tmdb = 407451, descripcion = 'Tras la desaparición de su padre, un científico, tres seres peculiares envían a la joven Meg, a su hermano Charles y a su amigo Calvin al espacio, para intentar encontrarlo. Adaptación de la novela de Madeleine L''Engle.', trailer_url = 'https://www.youtube.com/watch?v=xhUKE2oTYL0' WHERE id_api = 'tt1620680';

UPDATE Contenido SET id_tmdb = 57157, descripcion = 'Tras su divorcio, la escritora Mavis Gary atraviesa una crisis existencial que intenta superar volviendo a su pueblo natal. Su situación empeora cuando intenta volver con su novio del instituto, que ya está casado y es padre de un niño. Pero Mavis encuentra un inesperado aliado en otro compañero del instituto.', trailer_url = 'https://www.youtube.com/watch?v=LuLAZpcHfxE' WHERE id_api = 'tt1625346';

UPDATE Contenido SET id_tmdb = 76600, descripcion = 'Más de una década después de los acontecimientos de ''Avatar'', los Na''vi Jake Sully, Neytiri y sus hijos viven en paz en los bosques de Pandora hasta que regresan los hombres del cielo. Entonces comienzan los problemas que persiguen sin descanso a la familia Sully, que decide hacer un gran sacrificio para mantener a su pueblo a salvo y seguir ellos con vida.', trailer_url = 'https://www.youtube.com/watch?v=inT3MvpxRqE' WHERE id_api = 'tt1630029';

UPDATE Contenido SET id_tmdb = 240667, descripcion = 'Emma y Dexter pasan juntos la noche de graduación y toman caminos distintos al día siguiente... pero sus vidas seguirán entrelazadas.', trailer_url = 'https://www.youtube.com/watch?v=X8vGnkXd9rA' WHERE id_api = 'tt16283804';

UPDATE Contenido SET id_tmdb = 137113, descripcion = 'En un futuro no muy lejano, invade la Tierra una raza de extraterrestres invencibles. Al comandante William Cage, un oficial que nunca ha entrado en combate, le encargan una misión casi suicida y resulta muerto. Entra entonces en un bucle temporal, en el que se ve obligado a luchar y morir una y otra vez. Pero las múltiples batallas que libra lo hacen cada vez más hábil y eficaz en su lucha contra los alienígenas. Su compañera de combate es Rita Vrataski, una guerrera de las Fuerzas Especiales. Adaptación del manga de Hiroshi Sakurazaka.', trailer_url = 'https://www.youtube.com/watch?v=EoEeZHPf5NE' WHERE id_api = 'tt1631867';

UPDATE Contenido SET id_tmdb = 64678, descripcion = 'George, un adolescente inteligente pero solitario y escéptico, cambia de actitud cuando entabla amistad con la bella Sally, una joven de su clase que le gusta desde hacía tiempo y que oculta su melancolía protegiéndose detrás de su máscara de "la chica más popular del instituto".', trailer_url = 'https://www.youtube.com/watch?v=N9tMK4FoXJs' WHERE id_api = 'tt1645080';

UPDATE Contenido SET id_tmdb = 32754, descripcion = 'En el año 2149, un momento en que toda la vida en el planeta Tierra está en peligro de extinción debido a la superpoblación y la disminución de la calidad del aire en todo el mundo. En Hope Plaza, una estructura en forma de anillo gigante en Chicago, los científicos descubren una grieta en el espacio de tiempo que permite a las personas viajar a finales del período Cretácico (85 millones de años atrás) en la Tierra prehistórica de una realidad alternativa , que ofrece una oportunidad de salvar la humanidad. La familia Shannon se une a la décima peregrinación para pobladores de Terra Nova, la primera colonia de humanos del otro lado del portal. Jim entra furtivamente a la expedición ya que estaba en prisión, pero se adapta muy bien y le ofrece un puesto de policía (era su trabajo antes de la prisión en 2149).', trailer_url = NULL WHERE id_api = 'tt1641349';

UPDATE Contenido SET id_tmdb = 198185, descripcion = 'J.B. Bernstein es un agente deportivo estadounidense cuya carrera no está pasando por su mejor momento. A Bernstein se le ocurre la idea de realizar un reality en India, cuya finalidad es la de encontrar futuros jugadores de cricket. Finalmente, los ganadores del concurso son Rinku Singh y Dinesh Patel a los que lleva a Estados Unidos para ser entrenados por Tom House, con la intención de que acaben siendo contratados por un equipo de la Liga Profesional de Béisbol.', trailer_url = 'https://www.youtube.com/watch?v=q0vAFPHAHDw' WHERE id_api = 'tt1647668';

UPDATE Contenido SET id_tmdb = 37686, descripcion = 'Año 1979, en un pequeño pueblo de Ohio. Joe Lamb (Joel Courtney) es un muchacho que ha perdido a su madre en un accidente y que vive con su padre policía (Kyle Chandler). Comenzado el verano, y mientras rueda una película de zombis en Super 8 con sus amigos -y sobre todo con la bella Alice Dainard (Elle Fanning)-, Joe observa cómo una camioneta se estrella contra un tren de mercancías, provocando su descarrilamiento y un terrible accidente. A partir de ese momento cosas extrañas e inexplicables comienzan a suceder en el pueblo.', trailer_url = 'https://www.youtube.com/watch?v=89u6eSBSZmw' WHERE id_api = 'tt1650062';

UPDATE Contenido SET id_tmdb = 34415, descripcion = 'Del escritor y productor ejecutivo Veena Sud (Caso Abierto), The Killing se basa en la exitosa serie de televisión danesa Forbrydelsen y cuenta la historia del asesinato de una joven de Seattle y la investigación policial posterior. The Killing une tres historias distintas en torno a un solo asesinato: la de los detectives asignados al caso, la de la afligida familia de la víctima, y la de los sospechosos. Ubicada en Seattle, la historia también explora la política local, ya que sigue los políticos relacionados con el caso. A medida que la serie avanza, se hace evidente que no hay casualidades, todo el mundo tiene un secreto, y mientras que los personajes piensan que han cambiado, su pasado no lo hace con ellos.', trailer_url = 'https://www.youtube.com/watch?v=OkbfvPeH3G0' WHERE id_api = 'tt1637727';

