UPDATE Contenido SET id_tmdb = 74643, descripcion = 'Hollywood 1927. George Valentin es una gran estrella del cine mudo a quien la vida sonríe. Pero la llegada del cine sonoro le conducirá al olvido. Por su parte Peppy Miller, una joven actriz, verá impulsada su carrera a lo más alto, al firmamento de las estrellas.', trailer_url = 'https://www.youtube.com/watch?v=qjCQmpNkBI4' WHERE id_api = 'tt1655442';

UPDATE Contenido SET id_tmdb = 1022690, descripcion = 'Tres amigos de la infancia se inventan a un amigo imaginario para salirse con la suya siempre que lo necesiten. Cuando ya son adultos y la mentira de su amigo imaginario se ve comprometida, el trio es forzado a contratar a un actor para convencer a sus esposas de que Ricky Stanicky es una persona real.', trailer_url = 'https://www.youtube.com/watch?v=0BdORnFDCQQ' WHERE id_api = 'tt1660648';

UPDATE Contenido SET id_tmdb = 293863, descripcion = 'Adaline Bowman (Blake Lively), nacida a comienzos del siglo XX, adquiere a los 29 años la eterna juventud tras un accidente. Tras años de vida solitaria y permanecer con la misma edad durante 8 décadas, conoce a Ellis Jones (Michiel Huisman), un hombre por el que podría merecer la pena perder la inmortalidad.', trailer_url = 'https://www.youtube.com/watch?v=7UzSekc0LoQ' WHERE id_api = 'tt1655441';

UPDATE Contenido SET id_tmdb = 33217, descripcion = 'Re-imaginación de la franquicia Teen Titans, presentando superhéroes en su etapa como adolescentes lidiando además de con supervillanos, con problemas típicos de su edad.', trailer_url = NULL WHERE id_api = 'tt1641384';

UPDATE Contenido SET id_tmdb = 57800, descripcion = 'La loca persecución de Scrat por su escurridiza bellota desde el principio de los tiempos, tiene consecuencias que cambiarán el mundo: un cataclismo continental que desencadenará la mayor de las aventuras para Manny, Diego y Sid. En medio de estas agitaciones, Sid se reencuentra con su Abuelita Gruñona y la manada tropieza con una extraña cuadrilla de piratas de altamar decididos a impedirles su regreso a casa.', trailer_url = 'https://www.youtube.com/watch?v=NV3vLRyw8eQ' WHERE id_api = 'tt1667889';

UPDATE Contenido SET id_tmdb = 1011477, descripcion = 'Tras una tragedia familiar, el prodigio del kung fu Li Fong se ve obligado a abandonar su hogar en Pekín y trasladarse a Nueva York con su madre. Li lucha por dejar atrás su pasado mientras intenta encajar con sus nuevos compañeros de clase y, aunque no quiere pelear, los problemas parecen encontrarle en todas partes. Cuando un nuevo amigo necesita su ayuda, Li se presenta a una competición de kárate, pero sus habilidades no son suficientes. El profesor de kung fu de Li, el Sr. Han, pide ayuda al Karate Kid original, Daniel LaRusso, y Li aprende una nueva forma de luchar, fusionando sus dos estilos en uno solo para el enfrentamiento definitivo de artes marciales. Nueva película de la saga "Karate Kid", conectada al universo de "Cobra Kai".', trailer_url = 'https://www.youtube.com/watch?v=rL0Ec_v4zVw' WHERE id_api = 'tt1674782';

UPDATE Contenido SET id_tmdb = 86825, descripcion = 'Cuando India Stoker (Mia Wasikowska), una adolescente algo excéntrica, pierde a su querido padre (Dermot Mulroney) en un trágico accidente de coche en el día de su 18 cumpleaños, su tranquila existencia en la apartada mansión familiar se hace añicos de golpe. Con una sensibilidad exquisita, India muestra un comportamiento impasible que enmascara los profundos sentimientos y los agudísimos sentidos que sólo su padre comprendía. India se ve arrastrada hacia el hermano perdido de su padre, Charlie (Matthew Goode), que aparece por sorpresa en el funeral y decide quedarse con ella y su inestable madre, Evie (Nicole Kidman). Aunque India al principio desconfía de su encantador y misterioso tío, pronto descubre que le fascina y se da cuenta de cuánto tienen en común... Debut en EEUU del director coreano Park Chan-wook (Old Boy).', trailer_url = 'https://www.youtube.com/watch?v=KlHA2qmtAaE' WHERE id_api = 'tt1682180';

UPDATE Contenido SET id_tmdb = 616747, descripcion = 'Una mujer y su hijo reclutan a un variopinto grupo de expertos espirituales para que les ayuden a liberar su hogar de unos ocupantes sobrenaturales.', trailer_url = 'https://www.youtube.com/watch?v=EMTG2dn0yhs' WHERE id_api = 'tt1695843';

UPDATE Contenido SET id_tmdb = 112949, descripcion = 'Katie (Julianne Hough) es una bella joven con un oscuro pasado que llega a la pequeña localidad costera de Southport, Carolina del Norte. Allí conocerá al apuesto Alex (Josh Duhamel), un joven viudo de buen corazón, y a una viuda que la enseñará a enfrentarse a las pesadillas secretas que la acechan... Adaptación de una nueva novela de Nicholas Sparks.', trailer_url = 'https://www.youtube.com/watch?v=Lg3oOLEjkAA' WHERE id_api = 'tt1702439';

UPDATE Contenido SET id_tmdb = 915935, descripcion = 'Sandra, una escritora alemana, vive con su marido Samuel y su hijo ciego, Daniel, en un chalé en medio de los Alpes franceses. Cuando Samuel fallece en misteriosas circunstancias, la investigación no puede determinar si se trata de un suicidio o de un homicidio. Sandra es arrestada y juzgada por asesinato, y el proceso pone su tumultuosa relación y su ambigua personalidad en el punto de mira.', trailer_url = 'https://www.youtube.com/watch?v=ZxxtuWFftMg' WHERE id_api = 'tt17009710';

UPDATE Contenido SET id_tmdb = 926676, descripcion = 'El director Daniel Roher explora la vida y el trabajo del líder de la oposición rusa Alexei Navalny, quien, tras años de campaña contra la corrupción, se ha granjeado poderosos enemigos, incluido el presidente Vladimir Putin.', trailer_url = 'https://www.youtube.com/watch?v=cPRuvKqZty0' WHERE id_api = 'tt17041964';

UPDATE Contenido SET id_tmdb = 157386, descripcion = 'Basada en una novela de Tim Tharp, cuenta la historia de Sutter Keely, un estudiante juerguista que un día conoce a Aimee Finicky, una tímida e inadaptada adolescente. Sutter se propone entonces realizar un experimento social con el fin de comprobar si es capaz de influir en la vida de las personas, y la cobaya será Aimee.', trailer_url = 'https://www.youtube.com/watch?v=rukPkkSRpvA' WHERE id_api = 'tt1714206';

