UPDATE Contenido SET id_tmdb = 147773, descripcion = 'Duncan (Liam James) es un adolescente de 14 años que, en el transcurso de un verano, tratará de encontrar la fuerza que precisa para poder encontrarse a sí mismo, y de paso, enfrentarse a su padrastro (Steve Carell), que bebe, consume drogas y se va de juerga con otras mujeres, y para volver a relacionarse con su madre (Toni Collette).', trailer_url = 'https://www.youtube.com/watch?v=6IUjRMVVstw' WHERE id_api = 'tt1727388';

UPDATE Contenido SET id_tmdb = 929590, descripcion = 'En un futuro cercano, donde América está sumida en una cruenta guerra civil, un equipo de periodistas y fotógrafos de guerra emprenderá un viaje por carretera en dirección a Washington DC. Su misión: llegar antes de que las fuerzas rebeldes asalten la Casa Blanca y arrebaten el control al presidente de Estados Unidos.', trailer_url = 'https://www.youtube.com/watch?v=1qE7rk5kP30' WHERE id_api = 'tt17279496';

UPDATE Contenido SET id_tmdb = 58595, descripcion = 'Versión oscura del cuento de los hermanos Grimm. Sólo una mujer (Kristen Stewart) supera en belleza a una reina tan malvada (Theron) que está dispuesta a acabar con ella. Pero la pérfida soberana ignora que el cazador (Chris Hemsworth) que debía haberla matado, no sólo le ha salvado la vida, sino que le ha enseñado a defenderse. Poco después, aparecerá en escena el Príncipe Azul (Sam Clafin) que queda hechizado por la belleza y el poder de Blancanieves.', trailer_url = 'https://www.youtube.com/watch?v=n0veSWlz0Ko' WHERE id_api = 'tt1735898';

UPDATE Contenido SET id_tmdb = 83666, descripcion = 'Años 60. La huida de dos jóvenes amantes de su pueblo natal lleva a sus familiares y amigos a salir en su búsqueda. Así, quedarán de manifiesto viejos rencores y ocultas relaciones románticas entre algunos de los personajes que participan en la búsqueda.', trailer_url = 'https://www.youtube.com/watch?v=6UqHU2uXXkk' WHERE id_api = 'tt1748122';

UPDATE Contenido SET id_tmdb = 202411, descripcion = 'Tras sobrevivir al ataque de Godzilla en San Francisco, un espeluznante secreto vuelve a sobrecoger a Cate. En medio de amenazas monstruosas, se embarca en una aventura por todo el mundo para descubrir la verdad sobre su familia y la misteriosa organización conocida como Monarca.', trailer_url = 'https://www.youtube.com/watch?v=1AzNxObJTGs' WHERE id_api = 'tt17220216';

UPDATE Contenido SET id_tmdb = 309809, descripcion = 'Para que todo salga bien en la prestigiosa Academia Werth, la pequeña y su madre se mudan a una casa nueva. La pequeña es muy seria y madura para su edad y planea estudiar durante las vacaciones siguiendo un estricto programa organizado por su madre; pero sus planes son perturbados por un vecino excéntrico y generoso. Él le enseña un mundo extraordinario en donde todo es posible. Un mundo en el que el Aviador se topó alguna vez con el misterioso Principito. Entonces comienza la aventura de la pequeña en el universo del Principito. Y así descubre nuevamente su infancia y comprenderá que sólo se ve bien con el corazón. Lo esencial es invisible a los ojos. Adaptación de la novela homónima de Antoine de Saint-Exupery.', trailer_url = 'https://www.youtube.com/watch?v=J6VRwAdhWIQ' WHERE id_api = 'tt1754656';

UPDATE Contenido SET id_tmdb = 60599, descripcion = 'El magnate Robert Miller, retrato perfecto del éxito tanto profesional como familiar, aparece siempre acompañado por su fiel esposa y por su hija y heredera. Pero, en realidad, Miller está con el agua al cuello: necesita urgentemente vender todo su imperio a un gran banco antes de que se descubra que ha cometido un fraude. Además, a espaldas de su mujer y de su hija, tiene un romance con una marchante de arte francesa. Cuando está a punto de deshacerse de su problemático imperio, un inesperado error lo obliga a enfrentarse con su pasado y con su doble moral.', trailer_url = 'https://www.youtube.com/watch?v=p67IYbLxeMc' WHERE id_api = 'tt1764183';

