UPDATE Contenido SET id_tmdb = 89492, descripcion = 'El director y productor Judd Apatow (''Virgen a los 40''), regresa a su particular universo tragicómico derivado de la crisis de la mediana edad partiendo esta vez de dos personajes conocidos: Debbie (Leslie Mann) y Pete (Paul Rudd), el matrimonio que ya aparecía en su exitosa ''Lío embarazoso'' y que ahora adquiere el máximo protagonismo en este spin-off titulado ''This Is 40''. A partir de ellos, el director profundizará en los conflictos derivados del matrimonio y la familia a partir de sus altibajos, sus incovenientes y sus problemas, así como en las cuestiones derivadas en torno a la paternidad. Si en ''Lío embarazoso'' descubríamos que esta pareja no era todo lo equilibrada y madura que podría parecernos en un principio, ahora descubriremos por qué, nos introduciremos en sus excentricidades y en la forma en la que afrontan las responsabilidades.', trailer_url = 'https://www.youtube.com/watch?v=2NvTjCELbrk' WHERE id_api = 'tt1758830';

UPDATE Contenido SET id_tmdb = 166426, descripcion = 'El capitán Jack Sparrow se enfrentará a un grupo de piratas-fantasma comandados por una de sus viejas némesis, el terrorífico capitán Salazar, recién escapado del Triángulo de las Bermudas. La única posibilidad de Sparrow para salir con vida es encontrar el legendario Tridente de Poseidón, un poderoso artefacto que le da a su poseedor el control de los mares.', trailer_url = 'https://www.youtube.com/watch?v=azjsS0wxTA8' WHERE id_api = 'tt1790809';

UPDATE Contenido SET id_tmdb = 62017, descripcion = 'Adaptación de la novela homónima de Philip K. Dick "El hombre en el castillo". Las fuerzas del Eje (Alemania y Japón) ganaron la II Guerra Mundial y ahora Estados Unidos está dividida en tres partes. Joe Blake, un luchador de la resistencia, parte de la Nueva York alemana con un misterioso cargamento hacia la zona neutral de Colorado. Por su parte, en la San Francisco japonesa, Juliana Crane recibe de manos de su hermana unas filmaciones que muestran una realidad alternativa en la que los aliados ganan la guerra.', trailer_url = 'https://www.youtube.com/watch?v=hzz_6dmv03I' WHERE id_api = 'tt1740299';

UPDATE Contenido SET id_tmdb = 80184, descripcion = 'La cara oculta explora los límites del amor, los celos y la traición. Adrián (Quim Gutiérrez) el atractivo director de la Orquesta Filarmónica de Bogotá, y su novia Belén (Clara Lago) parecen estar muy enamorados, pero cuando Belén empieza a dudar de su fidelidad, desaparece sin dejar rastro.  Afligido, Adrián encuentra consuelo tanto en su música como en los brazos de una hermosa camarera, Fabiana (Martina García), y a medida que la pasión entre ellos crece, las preguntas sobre la misteriosa desaparición de Belén comienzan a aflorar y el pasado de Adrián estará más presente de lo que nunca pudieron imaginar.', trailer_url = 'https://www.youtube.com/watch?v=hWq_1Pj0QDM' WHERE id_api = 'tt1772250';

UPDATE Contenido SET id_tmdb = 192141, descripcion = 'En su casa en un país del sudeste asiático, una familia estadounidense se encuentra atrapada en medio de un violento golpe de Estado. Desesperadamente intentarán escapar de un ambiente en el que los extranjeros, como ellos, son inmediatamente ejecutados.', trailer_url = 'https://www.youtube.com/watch?v=DOjj07EuO50' WHERE id_api = 'tt1781922';

UPDATE Contenido SET id_tmdb = 225565, descripcion = 'Tres amigos están en ese momento vital en el que no saben qué hacer con su vida sentimental. Jason y Daniel viven yendo de relación en relación con chicas con las que no quieren comprometerse, mientras que Mickey está casado y tiene problemas con su mujer. Todo cambiará para ellos una noche en que deciden salir de fiesta para animar a su amigo y Jason cae perdidamente enamorado de una chica a la que acaba de conocer.', trailer_url = 'https://www.youtube.com/watch?v=Mvr-NQrqF6I' WHERE id_api = 'tt1800246';

UPDATE Contenido SET id_tmdb = 60243, descripcion = 'Nader (Peyman Moaadi) y Simin (Leila Hatami) son un matrimonio iraní con una hija. Simin quiere abandonar Irán en busca de una vida mejor, pero Nader, que desea quedarse para cuidar a su padre, que tiene Alzheimer, le pide el divorcio. Como no lo consigue, se muda a vivir con sus padres y contrata a una mujer para que le ayude a cuidar a su padre. Un día, al llegar a casa, encuentra al anciano atado a la cama; a partir de ese momento, su vida dará un vuelco.', trailer_url = 'https://www.youtube.com/watch?v=wnSPZq3_8jQ' WHERE id_api = 'tt1832382';

UPDATE Contenido SET id_tmdb = 939243, descripcion = 'Sonic, Knuckles y Tails se reúnen para enfrentarse a un nuevo y poderoso adversario, Shadow, un misterioso villano cuyos poderes no se parecen a nada de lo que nuestros héroes han conocido hasta ahora. Con sus facultades superadas en todos los sentidos, el Equipo Sonic tendrá que establecer una insólita alianza con la esperanza de detener a Shadow y proteger el planeta.', trailer_url = 'https://www.youtube.com/watch?v=2YJXP8CKrNE' WHERE id_api = 'tt18259086';

UPDATE Contenido SET id_tmdb = 82700, descripcion = 'Tras una serie de cataclismos que forzaron a la humanidad a abandonar la Tierra, Nova Prime se convirtió en su nuevo hogar. Tras una larga misión fuera de ese planeta, el legendario general Cypher Raige regresa en compañía de su hijo Kitai. En medio de una tormenta de asteroides, la nave se avería y se estrella contra la Tierra, lugar desconocido y peligroso en el que todos los seres vivos no tienen más objetivo que eliminar a los hombres. Como Cypher ha resultado herido, Kitai debe recorrer ese mundo hostil en busca de la baliza de rescate. Siempre ha querido ser un soldado como su padre, y ahora se le presenta la oportunidad de cumplir su deseo.', trailer_url = 'https://www.youtube.com/watch?v=_iuS_ZDCdUU' WHERE id_api = 'tt1815862';

UPDATE Contenido SET id_tmdb = 137321, descripcion = 'A finales del siglo XIX, en Nueva York, Peter Lake, un ladrón irlandés, conoce a Beverly Penn, la joven heredera de la casa que pretende robar. Se trata de una historia de fantasía sobre un ladrón, una chica moribunda y un caballo blanco volador. Está ambientada en el siglo XIX y en la actualidad.', trailer_url = 'https://www.youtube.com/watch?v=NWVOuZ1lRqg' WHERE id_api = 'tt1837709';

