UPDATE Contenido SET id_tmdb = 72784, descripcion = 'Cinco hombres comparten en secreto un apartamento donde poder escaparse con sus amantes, donde relajarse o simplemente evadirse de la rutina. Hasta que un día aparece el cuerpo de una mujer asesinada en el apartamento y empieza un juego de sospechas entre ellos para intentar descubrir quién es el culpable y ver cómo se las arreglan para que todo el asunto no salga a la luz... Remake de la propia película de Erik Van Looy realizada en 2008.', trailer_url = 'https://www.youtube.com/watch?v=THY7kzl3xQ8' WHERE id_api = 'tt1850397';

