UPDATE Contenido SET id_tmdb = 324560, descripcion = 'Liz lleva una vida tranquila, pero cuando escuche el primer sermón del nuevo reverendo, la joven madre comprenderá que su paz ha terminado y que su pasado la ha alcanzado de nuevo. Comienza así un peregrinaje épico, lleno de sangre y sufrimiento. Dakota Fanning, Guy Pearce y Kit Harington (aka Jon Snow) protagonizan este American Gothic, en cuatro actos y con el mal pisando los talones.', trailer_url = 'https://www.youtube.com/watch?v=w4YZWBsuZzI' WHERE id_api = 'tt1895315';

