UPDATE Contenido SET id_tmdb = 103731, descripcion = 'En una isla del Mississippi, dos chicos descubren a un fugitivo llamado Mud. Ha matado a un hombre para proteger al amor de su vida, Juniper, y ahora se oculta de los cazadores de recompensas. Los chicos acceden a ayudarle a reunirse con Juniper y preparar su huida juntos, sin saber que la aparición de Mud significará el fin de sus infancias.', trailer_url = 'https://www.youtube.com/watch?v=DTEDfEhKwLo' WHERE id_api = 'tt1935179';

UPDATE Contenido SET id_tmdb = 225886, descripcion = 'Cuando Jay (Jason Segel) y Annie (Cameron Diaz) entablaron relación, la atracción entre ambos era muy intensa. Diez años y dos hijos después, se dan cuenta de que hay que reavivar la llama de la pasión. Deciden entonces grabarse en vídeo mientras mantienen una maratoniana sesión sexual de tres horas. El problema surge cuando descubren que el vídeo ha sido enviado por error a sus amigos y familiares.', trailer_url = 'https://www.youtube.com/watch?v=sxl4aOyHSwo' WHERE id_api = 'tt1956620';

UPDATE Contenido SET id_tmdb = 948549, descripcion = 'Jackie está decidida a triunfar como culturista y se dirige a Las Vegas para participar en una competición. En su camino, pasa por un pequeño pueblo de Nuevo México donde conoce a Lou, la solitaria gerente del gimnasio local. El padre de Lou es traficante de armas y lleva las riendas de un sindicato del crimen. Jackie y Lou se enamoran. Pero su relación provoca violencia y ambas se ven inmersas en las maquinaciones de la familia de Lou.', trailer_url = 'https://www.youtube.com/watch?v=-NIPUbemHOM' WHERE id_api = 'tt19637052';

UPDATE Contenido SET id_tmdb = 274857, descripcion = 'Arturo es un joven intrépido que dirige a su pandilla por los callejones de Londonium. Tras sacar la espada de Excalibur, se verá obligado a tomar algunas duras decisiones. Junto a una misteriosa mujer llamada Guinevere, deberá aprender a manejar la espada, vencer a sus demonios y unir al pueblo para derrotar al tirano Vortigern, quien robó su corona y asesinó a sus padres antes de convertirse en rey.', trailer_url = 'https://www.youtube.com/watch?v=8md0ReKuSiw' WHERE id_api = 'tt1972591';

UPDATE Contenido SET id_tmdb = 76338, descripcion = 'Thor lucha por restablecer el orden en el cosmos, pero una antigua raza liderada por el vengativo Malekith regresa con el propósito de volver a sumir el universo en la oscuridad. Se trata de un villano con el que ni siquiera Odín y Asgard se atreven a enfrentarse; por esa razón, Thor tendrá que emprender un viaje muy peligroso, durante el cual se reunirá con Jane Foster y la obligará a sacrificarlo todo para salvar el mundo.', trailer_url = 'https://www.youtube.com/watch?v=Dos2w0C3LP0' WHERE id_api = 'tt1981115';

UPDATE Contenido SET id_tmdb = 130150, descripcion = 'Ambientada en los años ochenta, la película cuenta la historia de Henry Wheeler, un chico de 13 años que vive en New Hampshire con su madre Adele. Ella está divorciada, hecho que le ha provocado una profunda depresión además de agorofobia, por lo que casi siempre está recluida en casa. Henry, además de estar pasando el complicado trance de la adolescencia, tiene que cuidar de su madre.  Es jueves, y ese mismo fin de semana se celebra el Día del Trabajo, aunque para Henry no tiene nada de especial. Piensa que va a ser un fin de semana más del verano cuya única distracción será quedarse en casa junto a su madre. Pero algo diferente está por llegar.', trailer_url = 'https://www.youtube.com/watch?v=eDAm-qRpkHI' WHERE id_api = 'tt1967545';

UPDATE Contenido SET id_tmdb = 967941, descripcion = 'Mientras la multitud alza su clamor contra la Bruja Malvada, Glinda y Elphaba deberán unirse una vez más. Con su singular amistad convertida en el punto de inflexión de su futuro, tendrán que mirarse a los ojos con honestidad y compasión para afrontar su transformación personal y cambiar el destino de todo Oz.', trailer_url = 'https://www.youtube.com/watch?v=wweDnEbMvtY' WHERE id_api = 'tt19847976';

UPDATE Contenido SET id_tmdb = 195589, descripcion = 'Aparentemente, Mac Radner y su esposa Kelly han hecho realidad el sueño americano: acaban de tener una niña adorable y se han comprado una preciosa casa en las afueras. La pareja de treintañeros está convencida de que ha adquirido el aplomo necesario para la vida de adultos, pero estos exjuerguistas van a enfrentarse a un reto inesperado. Cuando Mac y Kelly descubren que sus nuevos vecinos son los miembros de la fraternidad Delta Psi Beta, con el carismático presidente Teddy Sanders a la cabeza, intentan estar a la altura de la situación y parecer más colegas que adultos. Pero las juergas de los chicos adquieren proporciones épicas y a la pareja no le queda más remedio que poner un poco de orden. La guerra entre vecinos escala a la velocidad del rayo a medida que el matrimonio se las ingenia para que expulsen a los universitarios, y estos últimos, para hacer perder la poca cordura que les queda a los nuevos padres.', trailer_url = 'https://www.youtube.com/watch?v=baw3wUiU6Bk' WHERE id_api = 'tt2004420';

UPDATE Contenido SET id_tmdb = 132232, descripcion = 'El día que su padre mató a su madre, las hermanas Victoria y Lilly desaparecieron en el bosque cercano a la urbanización donde vivían. Su tío Lucas y su novia Annabel las han buscado sin cesar durante cinco años. Cuando ocurre lo imposible y las niñas aparecen en una cabaña medio derruida, la pareja empieza a preguntarse si no ha llegado alguien más a su casa acompañando a las niñas. Annabel intenta ofrecer una vida normal a las niñas, pero acaba convencida de que hay una presencia malévola en la casa. ¿Sufren las hermanas de estrés traumático o viene un fantasma a visitarlas? Mientras intenta contestar a estas inquietantes preguntas, la nueva madre acabará descubriendo que los susurros que se oyen a la hora de dormir proceden de los labios de una presencia letal.', trailer_url = 'https://www.youtube.com/watch?v=iBAn6uAGrHE' WHERE id_api = 'tt2023587';

UPDATE Contenido SET id_tmdb = 152747, descripcion = 'En el transcurso de un viaje en solitario a través del Océano Índico, un hombre descubre al despertar que el casco de su velero de 12 metros se ha agrietado tras una colisión con un contenedor que flotaba a la deriva. A pesar de las reparaciones, su intuición de marinero y una fuerza física que desafía su edad, a duras penas logra sobrevivir a la tormenta. Pero el sol implacable, la amenaza de los tiburones y el agotamiento de sus escasas reservas obligan a este marinero sin rumbo a mirar a la muerte a los ojos.', trailer_url = 'https://www.youtube.com/watch?v=dPv7kzQs59A' WHERE id_api = 'tt2017038';

