UPDATE Contenido SET id_tmdb = 225574, descripcion = 'Bill Marks, un veterano agente del servicio aéreo de los Air Marshalls, pasa por una mala etapa: tiene problemas con la bebida, y últimamente se toma su trabajo como una rutinaria tarea de vigilante a bordo de un avión. Sin embargo, en un viaje de Nueva York a Londres recibe una serie de misteriosos mensajes de texto, en los que se le pide que inste al gobierno a hacer una transferencia de 150 millones de dólares a una cuenta secreta. En caso contrario, un pasajero morirá cada 20 minutos. Comienza así un juego del gato y el ratón a 40.000 pies de altura y con la vida de 200 pasajeros pendiente de un hilo.', trailer_url = 'https://www.youtube.com/watch?v=XSF6GPNXr9Y' WHERE id_api = 'tt2024469';

