UPDATE Contenido SET id_tmdb = 67683, descripcion = 'Cientos de años en el futuro, los últimos supervivientes humanos sobre la Tierra descubren los medios para enviar su consciencia a través del tiempo al pasado, directamente a la gente del siglo XXI. Los viajeros asumen rápidamente las vidas de gente aparentemente elegida al azar mientras empiezan a trabajar de forma secreta en equipos para realizar misiones que salven la humanidad de un terrible futuro. Estos viajeros son: El agente especial del FBI Grant MacLaren (Eric McCormack), líder del equipo; Marcy (Mackenzie Porter), una mujer joven con discapacidad intelectual bajo el cuidado de su asistente social, David (Patrick Gilmore); Trevor (Jared Paul Abrahamson), mariscal de campo (quarterback) en el equipo de fútbol americano de su instituto; Carly (Nesta Marlee Cooper), madre soltera que se encuentra en una relación abusiva; y Philip (Reilly Dolman), un estudiante universitario adicto a la heroína. Armados solamente con su conocimiento sobre la historia y un archivo de perfiles de redes sociales, los viajeros descubren que las vidas y relaciones en el siglo XXI son un desafío tan grande como sus misiones de alto riesgo.', trailer_url = 'https://www.youtube.com/watch?v=99LZwZmSoNo' WHERE id_api = 'tt5651844';

