UPDATE Contenido SET id_tmdb = 581734, descripcion = 'En tiempos de la Gran Recesión, Fern, una mujer del poblado de Empire (Nevada, Estados Unidos), pierde su empleo en el 2011 tras el cierre de la fábrica de materiales de construcción donde trabajó junto con su esposo, quien recientemente falleció. Con sesenta años y sin otra alternativa, decide vender la mayoría de sus pertenencias y comprar una furgoneta para vivir y viajar por el país en busca de trabajo, como nómada de hoy en día.', trailer_url = 'https://www.youtube.com/watch?v=f_kPuDuj8mY' WHERE id_api = 'tt9770150';

UPDATE Contenido SET id_tmdb = 1712, descripcion = 'Jordan "Bick" Benedict, un joven terrateniente, llega a su inmenso rancho de Texas con su flamante esposa Leslie Benedict, una rica y bella muchacha del Este. No tardan mucho en descubrir que pertenecen a mundos radicalmente opuestos y que los separa un abismo. Jett Rink es un arrogante y joven empleado de los Benedict que tiene la suerte de encontrar petróleo en unas tierras que le ha dejado en su testamento Luz, la hermana de Jordan; pero, a pesar de su inmensa fortuna, no consigue lo que realmente le importa: Leslie.', trailer_url = 'https://www.youtube.com/watch?v=SZZTWO4_wto' WHERE id_api = 'tt0049261';

UPDATE Contenido SET id_tmdb = 103051, descripcion = 'A down and out cop lands the case of a lifetime when four suspects are nabbed in the assassination attempt of a prime time journalist. The case turns out to be a devious maze where nothing is what it looks like. The pursuit of it leads him to the dark netherworld - the ''Paatal Lok'', and to shocking discoveries in the past of the four suspects.', trailer_url = NULL WHERE id_api = 'tt9680440';

UPDATE Contenido SET id_tmdb = 37257, descripcion = 'Leonard Vole, un hombre joven y atractivo, es acusado del asesinato de la señora French, una rica anciana con quien mantenía una relacion de carácter amistoso. El presunto móvil del crimen era la posibilidad de heredar los bienes de la difunta. A pesar de que las pruebas en su contra son demoledoras, Sir Wilfrid Roberts, un prestigioso abogado criminalista londinense, se hace cargo de su defensa.', trailer_url = 'https://www.youtube.com/watch?v=CgjVcXRDU0I' WHERE id_api = 'tt0051201';

UPDATE Contenido SET id_tmdb = 221, descripcion = 'Tres jóvenes, Jim Stark, Judy y Platón, coinciden en una comisaría. Cada uno está allí por un motivo distinto: Jim está borracho, Judy se ha escapado de su casa y Platón acababa de matar a tiros a unos cachorros. El inspector Ray descubre que los tres mantienen una relación conflictiva con sus familias. A Jim y a Judy los van a recoger sus padres, pero Platón, hijo de una pareja divorciada, tiene que conformarse con la visita de la criada negra que vive con él.', trailer_url = 'https://www.youtube.com/watch?v=HWHH5TwEwtI' WHERE id_api = 'tt0048545';

UPDATE Contenido SET id_tmdb = 124364, descripcion = 'Desvela el misterio de un pueblo de pesadilla en el centro de Norteamérica que atrapa a todos los que entran. Mientras los residentes involuntarios luchan por mantener una sensación de normalidad y buscan una salida, también deben sobrevivir a las amenazas del bosque circundante, incluidas las aterradoras criaturas que salen cuando se pone el sol.', trailer_url = 'https://www.youtube.com/watch?v=pDHqAj4eJcM' WHERE id_api = 'tt9813792';

UPDATE Contenido SET id_tmdb = 935, descripcion = 'Convencido de que los comunistas están contaminando los Estados Unidos, un general ordena, en un acceso de locura, un ataque aéreo nuclear sorpresa contra la Unión Soviética. Su ayudante, el capitán Mandrake, trata de encontrar la fórmula para impedir el bombardeo. Por su parte, el presidente de los EE.UU. se pone en contacto con Moscú para convencer al gobierno soviético de que el ataque no es más que un estúpido error. Mientras tanto, el asesor estadounidense, un antiguo científico nazi, el doctor Strangelove, confirma la existencia de la «Máquina del Juicio Final», un dispositivo de represalia soviético capaz de acabar con la humanidad para siempre.', trailer_url = 'https://www.youtube.com/watch?v=IE9CmX15PYA' WHERE id_api = 'tt0057012';

UPDATE Contenido SET id_tmdb = 2134, descripcion = 'El tiempo en sus manos cuenta como en 1899 un científico finaliza la construcción de un vehículo que le permite viajar a través del tiempo.Poco después, inicia un alucinante viaje a través de los siglos, y es testigo entre otros acontecimientos, de la Segunda Guerra Mundial y de un holocausto atómico en 1966, del que sale ileso.Su último destino es un paradisiaco lugar, localizado en una era muy posterior a la nuestra, concretamente en el año el año 802701, donde vivirá una increíble aventura.', trailer_url = 'https://www.youtube.com/watch?v=2GZnAbgGFxg' WHERE id_api = 'tt0054387';

UPDATE Contenido SET id_tmdb = 11576, descripcion = 'Un grupo de automovilistas viaja por un agreste paisaje del sur de California. De pronto, un coche les adelanta a gran velocidad pero, al tomar una curva, se precipita por un barranco. Los automovilistas se detienen e intentan ayudar a los ocupantes del vehículo siniestrado, pero llegan tarde, y el conductor moribundo confiesa que tiene escondido un botín de trescientos mil dólares en el parque de Santa Rosita.', trailer_url = 'https://www.youtube.com/watch?v=Oly0EY47Ht4' WHERE id_api = 'tt0057193';

UPDATE Contenido SET id_tmdb = 17529, descripcion = 'Un viejo agente del Gobierno, alcohólico y tuerto (John Wayne), es contratado por Mattie Ross (Kim Darby), una valerosa y obstinada joven, que se propone capturar al asesino de su padre. Contarán además con la colaboración de La Boeuf (Campbell), un ránger de Tejas.', trailer_url = 'https://www.youtube.com/watch?v=ruTdCaAWTNA' WHERE id_api = 'tt0065126';

UPDATE Contenido SET id_tmdb = 62, descripcion = 'Mientras investigan la aparición de misteriosos monolitos en el universo, dos astronautas luchan contra la inteligencia artificial de su nave.', trailer_url = 'https://www.youtube.com/watch?v=Z2UWOeBcsJI' WHERE id_api = 'tt0062622';

UPDATE Contenido SET id_tmdb = 4929, descripcion = 'Oklahoma, 1889. Unos hombres acusan injustamente a Jed Cooper (Clint Eastwood) de haber robado ganado y no dudan en ahorcarlo. En el último instante, lo salva un comisario que trabaja a las órdenes del juez Fentom. Aclarados los hechos y demostrada su inocencia, el juez aconseja a Cooper que olvide lo ocurrido y le ofrece un puesto como comisario. Su misión será capturar vivos a los que intentaron lincharlo para que sean juzgados por el juez.', trailer_url = 'https://www.youtube.com/watch?v=FtxTu-NTebg' WHERE id_api = 'tt0061747';

UPDATE Contenido SET id_tmdb = 838, descripcion = 'Es la última noche del verano de 1962, y los jóvenes de Modesto, California, quieren divertirse antes de que lleguen sus resonsabilidades como adultos. Así, todos los adolescentes del pueblo salen esa noche para beber, ligar, pasearse con el coche, ir a la bolera o bailar un rato...', trailer_url = 'https://www.youtube.com/watch?v=hH0FXaU3e-A' WHERE id_api = 'tt0069704';

UPDATE Contenido SET id_tmdb = 11072, descripcion = 'El avaricioso gobernador Lepetomane y su malvado ayudante Hedley Lamarr quieren que los habitantes de Rock Ridge abandonen la ciudad, para vender los terrenos a una compañía de ferrocarril. Para facilitar sus maquiavélicos planes, nombran sheriff a Bart, un negro condenado a la horca, para que fomente el desorden y la anarquía en la ciudad.', trailer_url = 'https://www.youtube.com/watch?v=tb2fYUKJdN8' WHERE id_api = 'tt0071230';

UPDATE Contenido SET id_tmdb = 3175, descripcion = 'Siglo XVIII. El joven Redmond Barry, huérfano de padre, se ha enamorado de su prima, a la que también pretende el Capitán John Quin. El asunto se resuelve por medio de un duelo, del que Redmond resulta vencedor. A continuación se va a Dublín y decide alistarse en el ejército inglés, donde empieza a desarrollar sus extraordinarias habilidades para sobrevivir. Estando en Alemania, se le presenta la posibilidad de desertar, pero es capturado por el Capitán Potzdorf, un oficial prusiano que le ofrece la posibilidad de unirse a sus tropas o ser colgado por desertor. Una vez en el ejército prusiano, tiene la fortuna de salvarle la vida a Potzdorf, lo que le abre las puertas del servicio secreto prusiano.', trailer_url = 'https://www.youtube.com/watch?v=JH8j_1dUlUU' WHERE id_api = 'tt0072684';

UPDATE Contenido SET id_tmdb = 9552, descripcion = 'Regan es una niña de doce años víctima de fenómenos paranormales como la levitación o la manifestación de una fuerza sobrehumana. Su madre, aterrorizada, tras someter a su hija a múltiples análisis médicos que no ofrecen ningún resultado, acude a un sacerdote con estudios de psiquiatría. Éste está convencido de que el mal no es físico sino espiritual, es decir, que la niña es víctima de una posesión diabólica. Por eso, con la ayuda de otro sacerdote decide practicar un exorcismo.', trailer_url = 'https://www.youtube.com/watch?v=BU2eYAO31Cc' WHERE id_api = 'tt0070047';

UPDATE Contenido SET id_tmdb = 11963, descripcion = 'Robert Redford es un oscuro funcionario de la CIA, cuyo trabajo consiste en leer libros con el fin de detectar mensajes cifrados que permitan descubrir operaciones secretas susceptibles de perturbar la estabilidad del país. Un día, cuando vuelve al trabajo después de comer, encuentra a todos sus compañeros muertos. Consciente de que sólo el azar lo ha salvado de una muerte segura, huye tratando de salvarse, pero también para encontrar una explicación a lo sucedido. En su fuga se verá impelido a secuestrar a una bella mujer (Faye Dunaway) con la que, además de compartir sus peripecias, vive una intensa historia de amor.', trailer_url = 'https://www.youtube.com/watch?v=mU8tQTNlPAM' WHERE id_api = 'tt0073802';

UPDATE Contenido SET id_tmdb = 691, descripcion = 'La misteriosa desaparición de dos submarinos nucleares hace que colaboren los mejores operativos de los servicios secretos británico y soviético: James Bond y la mayor Amasova. Detrás de todo se encuentra el magnate Stromberg, cuya finalidad es la destrucción de la "corrupta" humanidad para fundar una civilización pura bajo el mar.', trailer_url = 'https://www.youtube.com/watch?v=Ha94ny648TQ' WHERE id_api = 'tt0076752';

UPDATE Contenido SET id_tmdb = 10803, descripcion = 'La vida transcurre plácidamente en una megalópolis del siglo XXIII. Sus habitantes dedican la mayor parte del tiempo a gozar de los placeres de la vida y frecuentan tiendas en las que pueden cambiar de personalidad y de aspecto físico, gracias a la cirugía plástica instantánea. Sin embargo, al cumplir los 30 años, deben morir. Logan, un policía encargado de cazar a los que huyen de la muerte, decide también rebelarse y huir hacia el desierto que rodea la ciudad.', trailer_url = 'https://www.youtube.com/watch?v=JPauhZFMXo8' WHERE id_api = 'tt0074812';

UPDATE Contenido SET id_tmdb = 10734, descripcion = 'Bahía de San Francisco, 18 de enero de 1960. Frank Lee Morris es trasladado a Alcatraz, una prisión de máxima seguridad situada en una isla rocosa. A pesar de que nadie ha conseguido nunca evadirse de allí, Frank y otros reclusos empiezan a preparar minuciosamente un plan de fuga.', trailer_url = 'https://www.youtube.com/watch?v=5bLmGl_USn8' WHERE id_api = 'tt0079116';

UPDATE Contenido SET id_tmdb = 790, descripcion = 'En la costa de California se alza el pintoresco centro turístico de Antonio Bay. Mientras sus residentes se preparan para las celebraciones del centenario de la ciudad, la tripulación de un viejo barco aparece brutalmente asesinada. Al mismo tiempo, en el mar, una misteriosa niebla que oculta un mortífero secreto comienza a desplazarse inexorablemente cada noche hacia la costa. Según una leyenda local, estos extraños sucesos están aparentemente relacionados con un terrible acontecimiento sucedido hace cien años. A medida que se aproxima el día del centenario el horror se acerca a su clímax.', trailer_url = 'https://www.youtube.com/watch?v=XU-47N87G9M' WHERE id_api = 'tt0080749';

UPDATE Contenido SET id_tmdb = 9387, descripcion = 'En la historia de la humanidad, los tiempos más recordados son aquellos de las grandes hazañas y fantásticas aventuras. Esa es la época de Conan el Bárbaro. Conan es capturado cuando tan sólo era un niño después que sus padres fueran asesinados por el malvado Thulsa Doom, el cabecilla de una secta de adoradores a la Serpiente. Quince años de agonía forjarón a Conan como un guerrero insuperable. Liberado por su dueño, Conan, en compañía de sus amigos Subotai, Mongol y Valeria, Reina de los Ladrones, emprenden un viaje en busca de venganza y sabiduría.', trailer_url = 'https://www.youtube.com/watch?v=nJCfTIzWLjs' WHERE id_api = 'tt0082198';

UPDATE Contenido SET id_tmdb = 2665, descripcion = 'Años después de que salvara heroicamente las vidas de los pasajeros de un avión Jumbo, cuya tripulación cayó intoxicada, Ted Striker trabaja como piloto de pruebas de la nueva Lanzadera lunar. Sin embargo será enviado a una institución mental tras estrellar su nave de pruebas, a pesar de no tener la culpa. Cuando se entere de que el mismo tipo de nave se utilizará para realizar el primer vuelo lunar comercial, escapará e intentará evitarlo por todos los medios.', trailer_url = 'https://www.youtube.com/watch?v=_rg5cGIQjHc' WHERE id_api = 'tt0083530';

UPDATE Contenido SET id_tmdb = 601, descripcion = 'Un pequeño ser de otro planeta se queda abandonado en la Tierra cuando su nave se marcha olvidándose de él. Tiene miedo. Está completamente solo, pero se hará amigo de un niño, que lo esconde en su casa. El niño y sus hermanos intentarán encontrar la forma de que el pequeño extraterrestre regrese a su planeta antes de que los científicos y la policía lo encuentren.', trailer_url = 'https://www.youtube.com/watch?v=jzC0c-GWeDQ' WHERE id_api = 'tt0083866';

UPDATE Contenido SET id_tmdb = 700, descripcion = 'El agente 009, compañero de James Bond, es asesinado en Berlín Oriental, aunque consigue llegar a la residencia del embajador británico antes de morir, llevando consigo una valiosísima pieza de orfebrería: un huevo de Pascua, creado por Fabergé. En Londres, especialistas del Servicio Secreto constatan que se trata de una falsificación de la joya original, que será subastada en breve. El hecho de que en un corto período de tiempo se hayan vendido piezas parecidas despierta las sospechas de los responsables de Inteligencia, que temen una maniobra rusa que estaría encaminada a recaudar fondos que irían destinados a oscuras operaciones. Tras la pista de Kamal Khan, turbio traficante de objetos de arte, James Bond llega a la India, lugar en el que descubrirá la relación entre el sospechoso, una misteriosa mujer conocida como Octopussy y el General Orlov, implicados todos ellos en una conspiración que pretende desatar un conflicto nuclear.', trailer_url = 'https://www.youtube.com/watch?v=Ha94ny648TQ' WHERE id_api = 'tt0086034';

UPDATE Contenido SET id_tmdb = 90, descripcion = 'Axel Foley es un impetuoso e inteligente detective de Detroit que sigue la pista del asesino de un amigo suyo hasta los barrios más elegantes de Beverly Hills. Pero antes de que Axel logre su objetivo, va a verse involucrado en una red internacional de contrabandistas y traficantes de droga.', trailer_url = 'https://www.youtube.com/watch?v=nfUPsOKywO8' WHERE id_api = 'tt0086960';

UPDATE Contenido SET id_tmdb = 377, descripcion = 'Varios jóvenes de una pequeña localidad tienen habitualmente pesadillas en las que son perseguidos por un hombre deformado por el fuego y que usa un guante terminado en afiladas cuchillas. Algunos de ellos comienzan a ser asesinados mientras duermen por este ser, que resulta ser un asesino al que los padres de estos jóvenes quemaron vivo hace varios años tras descubrir que había asesinado a varios niños.', trailer_url = 'https://www.youtube.com/watch?v=X2qRCfXzc7g' WHERE id_api = 'tt0087800';

UPDATE Contenido SET id_tmdb = 655, descripcion = 'Un hombre aparece andando en el desierto de Texas sin recordar quién es. Su hermano va en su busca, intentando que recuerde su vida cuatro años atrás, cuando abandonó a su mujer y a su hijo. Mientras la memoria va volviendo a él y recupera el contacto con personas de su pasado, descubre la oportunidad de rehacer su vida.', trailer_url = 'https://www.youtube.com/watch?v=Nmvte2r7Z8c' WHERE id_api = 'tt0087884';

UPDATE Contenido SET id_tmdb = 105, descripcion = 'El adolescente Marty McFly es amigo de Doc, un científico al que todos toman por loco. Cuando Doc crea una máquina para viajar en el tiempo, un error fortuito hace que Marty llegue a 1955, año en el que sus futuros padres aún no se habían conocido. Después de impedir su primer encuentro, deberá conseguir que se conozcan y se casen; de lo contrario, su existencia no sería posible.', trailer_url = 'https://www.youtube.com/watch?v=xxSo8ZEvzE8' WHERE id_api = 'tt0088763';

UPDATE Contenido SET id_tmdb = 9355, descripcion = 'Tras la catástrofe nuclear, Mad Max cruza un desierto donde pierde su caravana de camellos. Llega a una ciudad donde le proponen cambiárselos a cambio de que ataque al tirano de la ciudad subterránea, un enano que fabrica gas metano con excrementos de cerdo.', trailer_url = 'https://www.youtube.com/watch?v=vynTmqiizog' WHERE id_api = 'tt0089530';

UPDATE Contenido SET id_tmdb = 80035, descripcion = 'Evan, Bob, Franklin y Jamarcus, viven por separado existencias monótonas lastradas por las presiones cotidianas. Todos son vecinos de un barrio residencial muy tranquilo, pero sin embargo, un día un hombre será encontrado muerto en extrañas circunstancias en el perímetro de la urbanización. Será entonces cuando los cuatro se prestarán voluntarios para realizar labores de vigilancia. Así, encontrarán la excusa perfecta para poder escapar de sus obligaciones diarias, de sus esposas, de sus hijos... y poder establecer una camaradería masculina entre ellos. Lo que no se esperaban es que esta misión en la que se han embarcado les iba a conducir a la peligrosa tesitura de tener que enfrentarse nada más y nada menos que a unos alienígenas dispuestos a conquistar el mundo...  Al frente de la dirección de esta comedia con toques de fantasía, encontramos a Akiva Schaffer (''Flipado sobre ruedas'', Saturday Night Live'').', trailer_url = 'https://www.youtube.com/watch?v=MVtk505z0_o' WHERE id_api = 'tt1298649';

UPDATE Contenido SET id_tmdb = 11557, descripcion = 'Tras acabar sus estudios, un grupo de íntimos amigos deben enfrentarse a los problemas y desafíos que plantea la vida. Por mucho que sus aspiraciones y sus nuevas relaciones sociales y laborales pongan a prueba su amistad, ellos se aferran siempre al cariño, a la estabilidad y a la seguridad que les da el grupo.', trailer_url = 'https://www.youtube.com/watch?v=dsPFF5xBeMk' WHERE id_api = 'tt0090060';

UPDATE Contenido SET id_tmdb = 24150, descripcion = 'Tras sobrevivir a los sangrientos crímenes de la noche de Halloween, Laurie Strode (Scout Taylor-Compton) trata de rehacer su vida junto al sheriff Brackett (Brad Dourif) y su amiga Annie (Danielle Harris). Pero dos años después de los asesinatos de Michael Myers el pasado vuelve y la joven Strode tendrá que enfrentarse nuevamente al psicópata en una noche regada de horror y sangre.', trailer_url = 'https://www.youtube.com/watch?v=66Xrr9KRSE0' WHERE id_api = 'tt1311067';

UPDATE Contenido SET id_tmdb = 50780, descripcion = 'Walter Black lo tiene todo, una mujer maravillosa y dos hijos fantásticos. Pero, desde hace unos meses, ha perdido la ilusión por vivir, además de toda esperanza por encontrar algo que valga la pena. Sumido en una gran depresión toma la decisión de abandonar su hogar durante algún tiempo. Pasado éste, regresa y lo hace de mejor humor, el secreto de este radical cambio es una marioneta con forma de castor que encontró en un contenedor de basura. Aunque a priori parezca una tontería, este castor permite que Walter se comunique más estrechamente con los demás, le facilita expresar sus sentimientos y liberar así su corazón. Pero esta terapia que en principio parece positiva, no lo será tanto cuando se vuelva en su contra, al descubrir que depende completamente del muñeco y que no puede hacer nada sin su ayuda. De este modo, su esposa e hijos tratarán de hacer todo lo que esté en sus manos por recuperar a su marido.', trailer_url = 'https://www.youtube.com/watch?v=Pm3yP0cgo34' WHERE id_api = 'tt1321860';

UPDATE Contenido SET id_tmdb = 87818, descripcion = 'Serie de sketches cómicos que cuentan 14 disparatadas historias, dirigidas entre otros por los Hermanos Farrelly y con un reparto coral espectacular, todas conectadas entre sí y cada cual más hilarante que la anterior. Desde cómo fracasa una cita de dos jóvenes cuando la chica se convierte en “mujer” hasta la cita rápida de un superhéroe.', trailer_url = 'https://www.youtube.com/watch?v=OS3Hdf20z5Q' WHERE id_api = 'tt1333125';

