UPDATE Contenido SET id_tmdb = 724209, descripcion = 'Rachel Stone es una agente de inteligencia, la única mujer que se interpone entre su poderosa organización mundial de mantenimiento de la paz y la pérdida de su activo más valioso y peligroso.', trailer_url = 'https://www.youtube.com/watch?v=LOHrNvFH3F8' WHERE id_api = 'tt13603966';

UPDATE Contenido SET id_tmdb = 45657, descripcion = 'Kristen, una joven con problemas, es capturada por la policía tras incendiar una granja y encerrada en el Hospital Psiquiátrico de North Bend. Pronto, empieza a sospechar que el lugar esconde un oscuro secreto y está decidida a descubrirlo.', trailer_url = 'https://www.youtube.com/watch?v=kD8WvNEcZGw' WHERE id_api = 'tt1369706';

UPDATE Contenido SET id_tmdb = 277216, descripcion = 'A mediados de los 80, el barrio californiano de Compton era uno de los lugares más peligrosos de Estados Unidos. Cuando un grupo de jóvenes convirtieron sus experiencias vitales en una música brutalmente sincera que se rebelaba contra la autoridad, le dieron voz a una generación silenciada. Siguiendo la meteórica trayectoria de N.W.A. (formado por Arabian Prince, DJ Yella, Dr. Dre, Eazy-E, Ice Cube y MC Ren), la película narra la historia de cómo estos chicos revolucionaron para siempre la música y la cultura popular al contar al mundo cómo era realmente la vida en el ghetto.', trailer_url = 'https://www.youtube.com/watch?v=VYFPpmDzShY' WHERE id_api = 'tt1398426';

UPDATE Contenido SET id_tmdb = 168530, descripcion = 'Ben trabaja como vigilante de una escuela de secundaria. Solo tiene un propósito: casarse con Ángela. Sus planes se ven truncados cuando se da cuenta de que antes debe conseguir la aprobación de James, el sobreprotector hermano de Ángela, un agente condecorado del departamento de policía de Atlanta. Para demostrar su valentía, Ben decide unirse al departamento de su cuñado y, aunque consigue superar las pruebas, tendrá que pasar la prueba más dura: acompañar a James en una patrulla de 24 horas por los suburbios de la ciudad.', trailer_url = 'https://www.youtube.com/watch?v=SD4cQwr7n5Y' WHERE id_api = 'tt1408253';

UPDATE Contenido SET id_tmdb = 46195, descripcion = 'Blu es un guacamayo que ha crecido en un pequeño pueblo de Minnesota en EEUU, un buen día se entera que es el último espécimen macho de su especie. Es entonces cuando Blu y su dueña, compañera y protectora Linda, deciden tomar rumbo a Rio de Janeiro para conocer a Tulio, un excéntrico experto en pájaros, y a Perla, quien es la última hembra de su especie. Juntos se embarcan en una serie de aventuras para sobrevivir junto a otros amigos que conocen a medida que se desarrolla la historia', trailer_url = 'https://www.youtube.com/watch?v=3-fuxjHVrIY' WHERE id_api = 'tt1436562';

UPDATE Contenido SET id_tmdb = 38303, descripcion = 'Una joven se entera que su hermano se va a casar con la misma chica que convirtió su vida en un infierno años atrás, cuando ambas estudiaban en la escuela de secundaria. Por si no fuera poco, su madre se sorprenderá aún más cuando se de cuenta de que la pomposa tía de la novia es también su enemiga del colegio. Así, madre e hija deciden que ha llegado el momento de planear su venganza...', trailer_url = 'https://www.youtube.com/watch?v=cD-qihNzHuk' WHERE id_api = 'tt1414382';

