UPDATE Contenido SET id_tmdb = 58496, descripcion = 'Documental que recorre la vida del legendario piloto Ayrton Senna desde la temporada de su debut en 1984 hasta su prematura muerte una década después en el circuito de Imola. Cuenta una historia excepcional, dejando las técnicas habituales del documental para adoptar una visión más cinematográfica y basándose en material sorprendente e inédito extraído en gran parte de los archivos de la Fórmula 1.', trailer_url = 'https://www.youtube.com/watch?v=sfosF-ZAbR4' WHERE id_api = 'tt1424432';

UPDATE Contenido SET id_tmdb = 49730, descripcion = 'Nueva versión de ”Caperucita Roja”. Durante décadas, los habitantes de Daggerhorn mantienen un complejo pacto con el hombre-lobo: para saciar su apetito, le sacrifican mensualmente un animal. Pero la bestia, incumple el pacto, devorando a un ser humano. La víctima es la hermana mayor de Valerie, una hermosa joven que acaba de saber que sus padres van a casarla con Henry, el heredero de la familia más rica del pueblo. Ella está enamorada de Peter, un humilde leñador, con el que decide fugarse, pero el lobo trastoca sus planes. Para acabar con la bestia de una vez por todas, el pueblo recurre al padre Solomon, un cazador de hombres-lobo, pero éste atemoriza aún más a los vecinos cuando les advierte que el lobo, durante el día, adquiere forma humana, de modo que podría ser cualquiera de ellos.', trailer_url = 'https://www.youtube.com/watch?v=qRDxfrLI-h0' WHERE id_api = 'tt1486185';

