UPDATE Contenido SET id_tmdb = 693134, descripcion = 'Sigue el viaje mítico de Paul Atreides mientras se une a Chani y los Fremen en una guerra de venganza contra los conspiradores que destruyeron a su familia. Al enfrentarse a una elección entre el amor de su vida y el destino del universo conocido, Paul se esfuerza por evitar un futuro terrible que solo él puede prever.', trailer_url = 'https://www.youtube.com/watch?v=nWzes49-2DA' WHERE id_api = 'tt15239678';

UPDATE Contenido SET id_tmdb = 840430, descripcion = 'A nadie le gusta el profesor Paul Hunham (Giamatti), ni a sus alumnos, ni a sus compañeros, ni al director de la escuela secundaria donde trabaja, a todos les resulta exasperante su pomposidad y rigidez. Sin familia y sin ningún lugar a donde ir durante las vacaciones de Navidad de 1970, Paul se queda en la escuela para supervisar a los estudiantes que no han podido viajar a casa. Después de unos días, solo queda allí un estudiante: un problemático chico de 15 años llamado Angus, un buen estudiante cuyo mal comportamiento siempre amenaza con expulsarlo. Junto a Paul y Angus está la cocinera Mary (Randolph), una mujer afroamericana que atiende a hijos privilegiados y cuyo propio hijo perdió la vida recientemente en Vietnam. Estos tres náufragos tan diferentes formarán una improbable familia durante dos semanas muy nevadas en Nueva Inglaterra.', trailer_url = 'https://www.youtube.com/watch?v=zIy3ixhneCU' WHERE id_api = 'tt14849194';

UPDATE Contenido SET id_tmdb = 58574, descripcion = 'Sherlock Holmes siempre ha sido el tipo más listo de la habitación… hasta ahora. El Profesor Moriarty, un genio del crimen, hace acto de aparición, y no sólo es el símil intelectual de Holmes, pero su capacidad para el mal, junto con una falta total de conciencia, en realidad puede darle una ventaja sobre el reconocido detective. Cuando encuentran muerto al príncipe heredero de Austria, la evidencia, según lo interpretado por el Inspector Lestrade, apunta al suicidio. Pero Sherlock Holmes deduce que el príncipe ha sido víctima de un asesinato, un crimen que sólo es una pieza de un rompecabezas mucho más grande y portentoso diseñado por Moriarty. Mezclando los negocios con el placer, las pistas conducen a Holmes a un club de caballeros donde él y su hermano, Mycroft Holmes brindan por la despedida de soltero del Dr. Watson.', trailer_url = 'https://www.youtube.com/watch?v=6t7qm0ycQNk' WHERE id_api = 'tt1515091';

