UPDATE Contenido SET id_tmdb = 39452, descripcion = 'Thierry Guetta es un un francés que vive en Los Ángeles y cuya única obsesión es grabarlo todo con su cámara de vídeo. Poco a poco se va introduciendo en el mundo del arte urbano y llega a conocer a Banksy, el artista urbano más famoso de la historia. En los títulos de crédito oficiales no aparece ningún director o guionista, tan sólo "Un film de Banksy".', trailer_url = 'https://www.youtube.com/watch?v=oHJBdDSTbLw' WHERE id_api = 'tt1587707';

UPDATE Contenido SET id_tmdb = 1422, descripcion = 'La de Frankie Heck es una familia de libro: tiene un hijo adolescente que se pasa el día en su cuarto y cuando se pasea lo hace sin camiseta ni pantalones; una hija que es un desastre en casi todo lo que intenta; y otro chico, el pequeño, que repite las últimas palabras en susurros porque le hace sentir bien. Además, intenta vender coches cuando su marido no se olvida de ir a recoger a los chicos al colegio.', trailer_url = 'https://www.youtube.com/watch?v=77d1smyqkYA' WHERE id_api = 'tt1442464';

