UPDATE Contenido SET id_tmdb = 57165, descripcion = 'Diez años después de los sucesos de “Furia de titanes”, Perseo (Sam Worthington) está decidido a llevar una vida tranquila con su hijo Helio. Sin embargo, los dioses, debilitados por la falta de fe de la humanidad, pierden el control sobre los Titanes, cuyo líder no es otro que Kronos, el padre de Zeus (Liam Neeson), Hades (Ralph Fiennes) y Poseidón (Danny Huston). Cuando Hades y Ares (Edgar Ramírez) llegan a un acuerdo con Kronos para capturar a Zeus, entonces Perseo tendrá que abandonar su apacible vida para rescatarlo, misión en la que cuenta con la ayuda de Andrómeda (Rosamund Pike), Agénor (Toby Kebbell) y Hefesto (Bill Nighy).', trailer_url = 'https://www.youtube.com/watch?v=vZWv38yn4ws' WHERE id_api = 'tt1646987';

UPDATE Contenido SET id_tmdb = 70578, descripcion = 'En “Bajo amenaza”, el feliz matrimonio formado por Sarah (Nicole Kidman) y Kyle Miller (Nicolas Cage) parece tenerlo todo: un elegante y apartado hogar con todas las comodidades imaginables, y una adorable aunque rebelde hija adolescente, Avery.  Kyle es un tratante de diamantes de gran éxito y Sarah es arquitecta. Ella misma ha diseñado su extenso y moderno hogar de cristal, piedra y acero, rodeado de densa vegetación. Pero sus tranquilas vidas se verán amenazadas cuando una banda de intrusos irrumpe violentamente en la casa. A partir de ese momento, Kyle se verá obligado a hacer uso de toda su pericia en un intento por salvar las vidas y los sueños de su familia.', trailer_url = 'https://www.youtube.com/watch?v=zP8I0WLRd8s' WHERE id_api = 'tt1674784';

UPDATE Contenido SET id_tmdb = 36994, descripcion = 'Workaholics gira entorno a las vidas de Blake, Adam y Anders, tres amigos de la universidad que se licencian y se adentran, por primera vez, en el esfera laboral, con todo lo que ello conlleva. O puede que no.', trailer_url = NULL WHERE id_api = 'tt1610527';

UPDATE Contenido SET id_tmdb = 74308, descripcion = 'A un instituto lleno de alumnos problemáticos y con unos resultados académicos muy bajos, llega Henry Bathes, un profesor sustituto que posee un auténtico don para conectar con los alumnos. Pero Henry prefiere ignorar su talento. Al trabajar sólo sustituciones, nunca permanece bastante tiempo en un instituto como para mantener una relación afectiva con sus alumnos o sus compañeros. Cuando llega a este instituto donde una frustrada administración ha conseguido volver totalmente apáticos a los alumnos, Henry no tarda en convertirse en un ejemplo a seguir para los adolescentes. Logra una conexión emocional con los alumnos, con los otros profesores y con una adolescente prostituta a la que recoge en la calle. Puede que gracias a ellos se dé cuenta de que no está solo en su desesperada búsqueda de la belleza en un mundo aparentemente falto de amor y lleno de maldad.', trailer_url = 'https://www.youtube.com/watch?v=tm36HwFKplc' WHERE id_api = 'tt1683526';

