UPDATE Contenido SET id_tmdb = 84174, descripcion = 'La noche antes de la boda de una vieja amiga, tres damas de honor buscan un poco de diversión, pero encontrarán mucho más de lo que buscaban. Con la encantadora Becky a punto de casarse con su apuesto novio Dale, el resto de miembros de la pandilla del instituto se reúnen para una última fiesta de solteras en la Gran Manzana. Pero cuando Becky insiste en que la fiesta de despedida de soltera sea light, las chicas se montan su propia fiesta. Las cosas se ponen salvajes muy rápido, con el trío recorriendo Manhattan con un vestido de novia roto, volando hacia una tintorería y buscando un sastre, además de destrozar la despedida de soltero del novio. ¿Conseguirán las chicas superar la noche con vida? ¿Podrán arreglar el vestido, estar junto a Becky y llegar a la ceremonia a tiempo? El tiempo corre, pero las solteras solo están empezando lo que será un fin de semana inolvidable que cambiará sus vidas.', trailer_url = 'https://www.youtube.com/watch?v=aBrONPfJ2iQ' WHERE id_api = 'tt1920849';

