UPDATE Contenido SET id_tmdb = 86829, descripcion = 'La vida de un joven cantante de folk en el universo de Greenwich Village en 1961. Llewyn Davis está en una encrucijada. Con su guitarra a cuestas acurrucado contra el frio de un invierno implacable en Nueva York, el joven lucha por ganarse la vida como músico y hace frente a obstáculos que parecen insuperables – comenzando por aquellos creados por él mismo. Sobrevive gracias a la ayuda de sus amigos o de desconocidos a cambio de pequeños trabajos. De los cafés del Village a un club desierto de Chicago, sus desventuras lo llevan a una audición para el gigante de la música Bud Grossman – antes de volver al lugar de donde viene...', trailer_url = 'https://www.youtube.com/watch?v=RwfpdIp-eZw' WHERE id_api = 'tt2042568';

