UPDATE Contenido SET id_tmdb = 522162, descripcion = '1942, Segunda Guerra Mundial. Después del devastador ataque sorpresa que destruyó Pearl Harbor, la Armada Imperial Japonesa se prepara para un nuevo ataque. Pero el Almirante Nimitz  y Dick Best, el mejor piloto de la armada estadounidense, preparan un contraataque al imponente ejército japonés. Dick encabezará un ataque masivo que hará que Japón se dé cuenta de su error. Una decisión que cambió el curso de la historia para siempre. Mientras estos dos titánicos enemigos emprenden una letal batalla para cambiar el rumbo de la guerra, todas las miradas se vuelcan hacia la remota isla de Midway, donde una serie de impactantes ataques aéreos y marítimos pondrán a prueba la potencia y la fortaleza de ambas naciones.', trailer_url = 'https://www.youtube.com/watch?v=sJrtMy_PmYI' WHERE id_api = 'tt6924650';

UPDATE Contenido SET id_tmdb = 82816, descripcion = 'Lovecraft Country cuenta la historia de Atticus Black, un chico de 25 años que al enterarse que su padre ha desaparecido inicia un búsqueda junto a su tío George y su amiga Letitia por Estado Unidos durante los años 50. En este recorrido los tres se enfrentarán al racismo de la América blanca y los espíritus malignos.', trailer_url = 'https://www.youtube.com/watch?v=eEvK1Zwi9XY' WHERE id_api = 'tt6905686';

UPDATE Contenido SET id_tmdb = 70796, descripcion = 'Manhattan, año 1958. Miriam Midge Maisel (Rachel Brosnahan) es una mujer cuya vida como esposa y madre da un giro inesperado cuando descubre un talento desconocido para la comedia. Midge cambiará entonces su cómoda existencia en el Upper West Side para hacer monólogos. Una serie de la creador de "Las chicas Gilmore".', trailer_url = 'https://www.youtube.com/watch?v=fOmwkTrW4OQ' WHERE id_api = 'tt5788792';

UPDATE Contenido SET id_tmdb = 658412, descripcion = 'Ludo trata sobre el efecto mariposa y cómo, a pesar de todo el caos y la multitud del mundo, todas nuestras vidas están inextricablemente conectadas. Desde un video sexual resurgido hasta una maleta llena de dinero, cuatro historias tremendamente diferentes se superponen a los caprichos del destino, el azar y un criminal excéntrico.', trailer_url = 'https://www.youtube.com/watch?v=RBk31vhORnc' WHERE id_api = 'tt7212754';

UPDATE Contenido SET id_tmdb = 79788, descripcion = 'Watchmen es una extensión de la historia original gráfica creada por Alan Moore y Dave Gibbons. La trama se sitúa en un universo alternativo donde los superhéroes son tratados como proscritos. Sin embargo, un grupo de superhéroes apodados como Watchmen, están en medio de una investigación centrada en el asesinato de un integrante de su equipo, topándose con una conspiración que pondrá en peligro sus vidas y las de los demás.', trailer_url = 'https://www.youtube.com/watch?v=7RhBjI9dPe4' WHERE id_api = 'tt7049682';

UPDATE Contenido SET id_tmdb = 512196, descripcion = 'Los peligros no han desaparecido para Tree Gelbman. Esta joven heroína se va a dar cuenta de que morir (y revivir) continuamente no ha sido el mayor de sus problemas. Los acontecimientos que se avecinan prometen poner a Tree en más peligros que nunca cuando vuelve a entrar en el bucle temporal para descubrir el motivo por el cual accedió a él en primer lugar. Secuela de la película de terror "Feliz día de tu muerte" (2017).', trailer_url = 'https://www.youtube.com/watch?v=6OTjK6ykLPA' WHERE id_api = 'tt8155288';

