UPDATE Contenido SET id_tmdb = 521029, descripcion = 'Annabelle Vuelve a Casa es la tercera entrega de la saga "Annabelle" de New Line Cinema, protagonizada por la infame y siniestra muñeca del universo "Expediente Warren".  Los demonólogos Ed y Lorraine Warren están decididos a evitar que Annabelle cause más estragos, así que llevan a la muñeca poseída a la sala de objetos bajo llave que tienen en su casa. La colocan "a salvo" en una vitrina sagrada bendecida por un sacerdote. Pero una terrorífica noche nada santa, Annabelle despierta a los espíritus malignos de la habitación que se fijan un nuevo objetivo: la hija de diez años de los Warren, Judy, y sus amigas.', trailer_url = 'https://www.youtube.com/watch?v=1VTnFrWGD-w' WHERE id_api = 'tt8350360';

