UPDATE Contenido SET id_tmdb = 11864, descripcion = 'Enemigos por instinto, amigos por necesidad, un humano y un alienígena con aspecto de reptil libran en un planeta hostil una dura batalla, parte de la salvaje guerra que enfrenta a la tierra con el planeta Dracon, habitado por seres monstruosos. Esta guerra alcanza una dimensión que puede poner en peligro la supervivencia de ambos planetas y puede conducir al exterminio total, pero sólo forzados a confiar el uno en el otro conseguirán sobrevivir.', trailer_url = 'https://www.youtube.com/watch?v=J8wLPApYGOw' WHERE id_api = 'tt0089092';

