UPDATE Contenido SET id_tmdb = 696, descripcion = 'Podría decirse que Isaac Davis, un neoyorquino de mediana edad, lo tiene todo, si por todo entendemos un trabajo que odia, una novia de 17 años a la que no ama y una ex-esposa lesbiana a la que desearía estrangular, porque está escribiendo un libro en el que cuenta las intimidades de su matrimonio. Pero su vida cambia cuando conoce a Mary, la sexy e inteligente amante de su mejor amigo, y se enamora perdidamente de ella. Dejar a su novia, acostarse con Mary y abandonar su trabajo no es más que el comienzo de la búsqueda de sí mismo.', trailer_url = 'https://www.youtube.com/watch?v=J5c93q3gU3w' WHERE id_api = 'tt0079522';

