UPDATE Contenido SET id_tmdb = 10246, descripcion = 'En Florida, durante la década de los cincuenta, un grupo de pícaros adolescentes que van juntos a la escuela descubren el sexo y el amor. Para dar rienda suelta a sus necesidades intentan entrar en Porky''s, un local de alterne, pero, al negarles la entrada el dueño del establecimiento, conciben todo tipo de gamberradas contra él. A partir de entonces le harán la vida imposible con tal de lograr tener acceso a las chicas.', trailer_url = 'https://www.youtube.com/watch?v=KpzxvPigAr8' WHERE id_api = 'tt0084522';

