UPDATE Contenido SET id_tmdb = 39538, descripcion = 'De repente, sin saber cuál es su origen, aunque todo hace sospechar que comienza con el viaje de una norteamericana a un casino de Hong Kong, un virus mortal comienza a propagarse por todo el mundo. En pocos días, la enfermedad empieza a diezmar a la población. El contagio se produce por mero contacto entre los seres humanos. Un thriller realista y sin efectos especiales sobre los efectos de una epidemia.', trailer_url = 'https://www.youtube.com/watch?v=vRa_XGr8NWU' WHERE id_api = 'tt1598778';

