UPDATE Contenido SET id_tmdb = 328111, descripcion = 'Comedia acerca de la vida que llevan nuestras mascotas cuando cerramos la puerta detrás de nosotros camino del trabajo o del colegio.', trailer_url = 'https://www.youtube.com/watch?v=lcrroI4bBf8' WHERE id_api = 'tt2709768';

UPDATE Contenido SET id_tmdb = 278927, descripcion = 'Después de ser abandonado en la selva, una familia de lobos cría al pequeño cachorro humano Mowgli. Gracias a la manada de lobos, sale adelante hasta ser capaz de enfrentarse por sí mismo a los peligros de la selva. Pero con la llegada del peligroso Shere Khan, Mowgli deja de ser bien recibido. Este temible tigre, resentido por las heridas que le ha ocasionado el hombre, ha prometido eliminar toda amenaza humana en la selva. Así que a Mowgli no le queda más remedio que abandonar el único hogar que ha conocido en toda su vida.  El pequeño niño humano emprenderá entonces un arriesgado y fascinante viaje de autodescubrimiento, para regresar junto a su especie, acompañado de la siempre fiel Bagheera, la pantera mentora del niño, y el despreocupado y divertido oso Baloo.  Esta nueva adaptación de El Libro de la selva de Rudyard Kipling, que combina acción real con escenarios fotorrealistas y animales generados por ordenador, corre a cargo de Disney.', trailer_url = 'https://www.youtube.com/watch?v=fCGgfrRApCs' WHERE id_api = 'tt3040964';

UPDATE Contenido SET id_tmdb = 321741, descripcion = 'El Dr. Bennet Omalu (Will Smith) es un neuropatólogo forense que descubrió el síndrome postconmoción cerebral, que tanto daño causó a muchos jugadores de fútbol americano y que provocó el suicidio de muchas estrellas de la liga NFL afectadas por el síndrome, como Dave Duerson y Junior Seau.', trailer_url = 'https://www.youtube.com/watch?v=0hBPjRu-6Ec' WHERE id_api = 'tt3322364';

UPDATE Contenido SET id_tmdb = 950387, descripcion = 'Cuatro inadaptados se encuentran luchando con problemas ordinarios cuando de repente se ven arrastrados a través de un misterioso portal al Mundo Exterior: un extraño país de las maravillas cúbico que se nutre de la imaginación. Para volver a casa, tendrán que dominar este mundo mientras se embarcan en una búsqueda mágica con un inesperado experto artesano, Steve.', trailer_url = 'https://www.youtube.com/watch?v=NOAmJa-dhCA' WHERE id_api = 'tt3566834';

UPDATE Contenido SET id_tmdb = 332210, descripcion = 'En Montaña Cigüeña, viven las cigüeñas que hace tiempo enviaban bebés a los padres de todo el mundo. Ahora distribuyen los paquetes de una compañía mundial de Internet. Junior, la mejor cigüeña repartidora de la compañía, está a punto de conseguir un ascenso, pero accidentalemete activa la Máquina de Producción de Bebés y el resultado es una adorable niña ilegal. Para evitar que su jefe se entere, Junior y su amiga Tulip, el único ser humano de Montaña Cigüeña, se apresuran a entregar el bebé en un viaje salvaje que podría afectar a la integridad de más de una familia y restablecer la verdadera misión de las cigüeñas en el mundo. Debut en el largometraje de Doug Sweetland, responsable del corto de Pixar "Presto" (2008).', trailer_url = 'https://www.youtube.com/watch?v=_2DO65R2Kds' WHERE id_api = 'tt4624424';

UPDATE Contenido SET id_tmdb = 292431, descripcion = 'Un 1 de enero por la mañana, el teléfono suena. Murphy se despierta junto a su esposa y su hijo de dos años. Escucha el mensaje, la madre de Electra, muy inquieta, le pregunta si tiene noticias de su hija que está desaparecida. Teme que le haya sucedido algo grave. A lo largo de un día lluvioso, Murphy se encuentra solo en casa, recordando su historia de amor más grande; dos años con Electra. Una pasión llena de promesas, juegos, excesos, errores...', trailer_url = 'https://www.youtube.com/watch?v=mR4JLD84RBo' WHERE id_api = 'tt3774694';

UPDATE Contenido SET id_tmdb = 371645, descripcion = 'Ricky es un rebelde chico de ciudad de doce años al que no encuentran hogar de acogida para él, salvo una granja en medio de la nada con una pareja; ella encantadora, él, arisco y solitario. Cuando comienza a sentirse a gusto, un problema imprevisto dará pie a una caza humana por el campo neozelandés.', trailer_url = 'https://www.youtube.com/watch?v=tICv8QH3oM0' WHERE id_api = 'tt4698684';

