UPDATE Contenido SET id_tmdb = 474764, descripcion = 'Grace y Richard acaban de comenzar su relación. Esto supone un pequeño inconveniente para los hijos de este, que no terminan de aceptar a la nueva pareja de su padre. Para su desgracia, estos tienen que pasar las Navidades con Wendy en una cabaña solitaria, alejada de la ciudad. Sin embargo, el trío comienza a conectar aunque resulta ser en el peor momento posibe. Unas fuerzas sobrenaturales comienzan a ser las protagonistas de unos extraños eventos en la cabaña, unos eventos que amenazan con despertar el tortuoso pasado de Grace.', trailer_url = 'https://www.youtube.com/watch?v=ohLHereEOM8' WHERE id_api = 'tt7347846';

