UPDATE Contenido SET id_tmdb = 535581, descripcion = 'En la pacífica localidad de Centerville pasa algo raro. Los animales se empiezan a comportar de forma extraña, las horas de luz solar cambian de forma impredecible y la luna vigila permanentemente desde el horizonte. Los científicos están preocupados y los informativos dan noticias desconcertantes. Y es que, una extraña invasión está a punto de suceder en la que los muertos ya no está muertos y se levantarán de sus tumbas. Los habitantes de Centerville, liderados por Ronald Peterson y Cliff Robertson, deberán detener esta amenaza y luchar para sobrevivir.', trailer_url = 'https://www.youtube.com/watch?v=teOGqx26lBA' WHERE id_api = 'tt8695030';

UPDATE Contenido SET id_tmdb = 411728, descripcion = 'A mediados del siglo XIX, el profesor James Murray comienza a compilar palabras para la primera edición del Oxford English Dictionary, un diccionario que tiene la ambiciosa tarea de recopilar todas las palabras de la lengua inglesa. Para sorpresa de Murray, un doctor de un asilo psiquiátrico será una de sus mayores ayudas.', trailer_url = 'https://www.youtube.com/watch?v=3IrAly1lcB8' WHERE id_api = 'tt5932728';

